INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (365, '강남제비스코, 지난해 영업익 83억…전년비 59.6% ↓', '[헤럴드경제=증권부] 강남제비스코는 지난해 연결기준 영업이익이 82억9475만원으로 전년대비 59.6% 감소했다고 12일 공시했다.같은 기간 매출액은 5985억5286만원으로 6.9% 줄어든 것으로 나타났다.당기순이익은 9억2601만원으로 94.9% 감소한 것으로 집계됐다.', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002600278', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2026-02-12 14:01:17', 0, true, '2026-03-09 05:36:23.110709') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (366, '올해 주가 리노공업 58%, 강남제비스코 45% 껑충', '부산 ‘반도체·조선 기자재’ 호황…BNK 28%·화승코퍼레이션 25%리노공업(코스닥)과 강남제비스코(코스피)의 주가가 부산지역 상장기업 가운데 최근 가장 크게 뛰어오른 것으로 나타났다.11일 한국거래소에 따르면 이날 리노공업은 전장보다 1.66% 내린 9만5000원으로 거래를 마쳤다. 지난해 12월 30일 종가(6만300원)와 비교하면 두 달여 동안 57.55% 올랐다.이는 부산지역 86개 상장기업 가운데 가장 높은 주가 상승률로, 반도체 슈퍼사이클의 열기가 반도체 소부장 기업인 리노공업으로 확산한 영향이다. 증권업계 보고서를 종합하면 향후 주가가 13만 원까지 오를 것으로 내다본다.이처럼 반도체와 조선·해운 등 호황기를 맞은 산업에서 기자재 기업의 주가 상승세가 가팔랐다. 부산 강서구에 있는 조선기자재 업체인 태광(코스닥)과 성광벤드(코스닥)의 주가가 같은 기간 각각 36.64%, 27.96% 올랐다. 또 석유화학·조선·2차전지 기자재 기업인 한선엔지니어링(코스닥) 주가도 19.67% 상승했다.그 외 BNK금융지주(27.60%·코스피)와 화승코퍼레이션(25.17%·코스피) 등의 상승세가 두드러졌다.상승률만 놓고 보면 강남제비스코가 리노공업 다음으로 2위를 차지했다. 강남제비스코는 같은 기간 1만2850원에서 1만8600원으로 44.75% 올랐다. 부산진구에 본사를 둔 강남제비스코는 ‘제비표 페인트’로 친숙한 국내 도료(페인트) 대표 회사다.증권가에서 강남제비스코는 저평가 자산주로 꼽힌다. 이날 기준 주가순자산비율(PBR)은 0.39배 수준이다.버핏연구소 독립리서치에 따르면 강남제비스코가 보유한 부동산 가치는 4000억 원 대로 시가총액(2418억 원)의 약 1.65배에 달한다. 또 경기 안양공장 부지 매각 잔금인 1800억 원이 올해 들어올 예정이다.버핏연구소 이승윤 연구원은 “본업인 도료 사업 외 이차전지 소재, 복합성형재료 등 신사업을 추진하고 계열사에 조선업 기자재가 있다”며 “대형 반도체주의 쏠림 현상이 줄어들 때 강남제비스코가 여기에 부합하는 조건을 갖췄다”고 밝혔다.', NULL, '국제신문', 'https://n.news.naver.com/mnews/article/658/0000135165', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2026-02-11 19:35:11', 0, true, '2026-03-09 05:36:23.110709') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (543, '''1500원 쇼크'' 겪은 환율, 당분간 살얼음판…"트럼프 출구전략 관건"', '장중 1500원 돌파 후 1470원대 숨 고르기…당분간 널뛰기 장세전문가 "사태 장기화 땐 1525원 상단…트럼프 ''조기 출구''가 분수령"6일 서울 중구 하나은행 딜링룸 전광판에 코스피 등 시황이 표시되고 있다. 2026.3.6 ⓒ 뉴스1 김진환 기자(세종=뉴스1) 전민 심서현 기자 = 달러·원 환율이 장중 1500원을 일시적으로 돌파하는 쇼크를 겪은 외환시장이 당분간 살얼음판 장세를 이어갈 전망이다. 중동의 지정학적 긴장으로 인한 극심한 변동성이 다소 숨을 고르고 있으나, 사태가 장기화할 경우 언제든 1500원을 재위협할 수 있다는 불안감은 여전히 남아있다.전문가들은 단기 급등이 얇은 거래량 속에서 과도하게 반영된 측면이 있다면서도, 향후 1500원 재돌파 여부 등 환율의 핵심 향방은 도널드 트럼프 미국 대통령의 조기 출구 전략에 달려있다고 입을 모았다.8일 서울외환시장에 따르면 미국과 이란의 대치 국면이 지속되면서 달러·원 환율은 다시 1470원대에 진입했다. 지난 6일 주간장에서 달러·원 환율은 전 거래일 대비 8.3원 오른 1476.4원으로 마감했다.환율은 전날(7일) 1470원 밑으로 떨어졌으나, 이란의 공세가 시작되고 전쟁이 주변국으로 확대될 수 있다는 우려가 고조되면서 야간장에서 한때 1480원을 다시 돌파하기도 했다.유가 상승·강달러 이중고…장기화 땐 1500원 훌쩍 넘어지난달 말 1420원대에서 하향 안정세를 보이던 환율은 이란의 호르무즈 해협 봉쇄 위협 등으로 단숨에 1460원에서 1480원대로 급등하며 불안한 흐름을 이어가고 있다. 핵심 에너지를 전량 수입하는 한국 경제의 구조적 특성상 국제유가 상승에 원화가 다른 주요국 통화보다 민감하게 반응하기 때문이다.외환시장 전문가들은 전면전이라는 최악의 시나리오가 아니더라도 중동발 불확실성 지속으로 인해 당분간 1400원대 중후반의 높은 환율 레벨이 유지될 것으로 내다봤다. 강달러를 부추기는 안전자산 선호 심리와 원화 가치를 끌어내리는 유가 상승이라는 이중고가 원화 약세 압력을 가중시키고 있다는 평가다.전규연 하나증권 연구원은 "미국과 이스라엘의 이란 공습 이후 호르무즈 해협을 봉쇄하면서 원유 공급 차질이 불가피해져 기존 전망보다 유가 레벨이 높아질 것"이라며 "유가 상승은 원화의 평가절하 압력을 높이는 요인"이라고 분석했다.오재명 KB증권 연구원은 "사태가 한 달 이상 장기화될 시에는 달러가 강세로 전환될 것"이라며 "국제유가가 80달러에서 100달러대 진입을 시도할 것으로 예상되며, 이 경우 외환시장 변동성도 추가로 확대될 가능성에 무게를 둔다"고 설명했다.이에 따라 사태 장기화 시나리오를 경계하며 시장 상황을 예의주시해야 한다는 지적이 제기된다. 사태가 단기에 진정 국면으로 접어들 경우 환율 상승폭이 제한되겠지만, 호르무즈 해협 수급 차질이 장기화할 경우 언제든 1500원 선을 재위협할 수 있는 극심한 변동성이 이어질 것이라는 예측이다.최예찬 상상인증권 연구원은 "역사적으로 중동 무력 이슈 발생 후 달러·원 환율은 90일 전후까지 쉽게 레벨을 낮추지 못하는 경향을 보여왔다"면서 "이번 분쟁의 장기화 가능성까지 감안하면 한동안 환율은 높은 지정학적 리스크 프리미엄을 반영할 것"이라며 전쟁 격화 시 환율 상단을 1525원으로 제시했다.이란 이슬람혁명수비대(IRGC)의 호르무즈 해협 군사훈련. 2026.02.16 ⓒ AFP=뉴스1"얇은 시장에 충격 과도하게 반영…네고 물량이 상단 방어"다만 최근의 환율 급등세가 얇은 거래량 속에서 단기적인 충격이 과도하게 반영된 측면이 있다는 진단도 나온다.사태 장기화 여부가 최대 관건이지만, 현재 수준에서는 수출업체들의 달러 매도 물량이 환율 상단을 방어할 것이라는 분석이다.이영화 부산은행 이코노미스트는 "극단적인 상황을 제외한 베이스 시나리오 하에서의 환율 상승분은 지난주 2~3일 동안 1500원을 일시적으로 넘고, 1400원대 후반까지 오르며 이미 시장에 많이 반영된 것으로 보인다"며 "거래량이 많지 않은 얇은 시장 환경 탓에 야간장 등에서 환율 변동 폭이 과도하게 나타나는 측면이 있다"고 진단했다.이어 이 이코노미스트는 "야간장에 환율이 무섭게 오르더라도 주간장에서는 우리나라의 무역 흑자 기조 속에 달러를 쥐고 있는 수출업체들의 네고(달러 매도) 물량이 나오면서 하락 방어하는 양상이 반복되고 있다"며 "오히려 수출 업체들이 좋은 조건으로 환헤지를 할 수 있는 찬스로 작용해 매도 물량이 나오고 있어, 완전한 호르무즈 봉쇄 장기화로 유가가 90달러 이상 급등하지 않는 한 현재 수준의 충격에 그칠 것"이라고 덧붙였다.전쟁 양상이 장기화하지 않고 조기에 마무리될 것이라는 전망도 나온다. 박상현 iM증권 연구원은 "트럼프 대통령이 전쟁을 오래 끌 수 있는 상황이 아니기 때문에 이번 주 정도가 이번 사태의 고비가 될 것"이라며 "미국이 조기에 출구 전략을 펼 가능성이 있다"고 내다봤다.환율 흐름에 대해서도 박 연구원은 "사태 당일에는 얇은 시장 탓에 다소 민감하게 반응했지만 이후로는 관망세가 유지되고 있다"며 "달러가 강세이긴 하나 우려할 정도의 초강세는 아니며 원화가 급격히 허물어지는 움직임도 뚜렷하지 않다"고 분석했다.아울러 이들은 미국 연방준비제도(Fed·연준)의 금리 인하 경로 역시 중동 사태 장기화 여부에 달렸다고 평가했다.박 연구원은 "사태가 어느 정도 마무리된다고 하면 미국이 전 세계 에너지를 통제하는 상황이 돼 유가가 오히려 더 큰 폭으로 내릴 수 있다"며 "전쟁 전 배럴당 50달러대 중후반이었던 유가가 초중반까지 떨어진다면 물가 안정에 기여해 연준의 금리 인하 가능성이 다시 탄력을 받을 수도 있다"고 전망했다.이 이코노미스트 역시 "물가에 대한 경계감이 일부 반영되기는 했지만 연준이 고용에 더 중점을 둬 금리를 인하하겠다는 기조"라며 "사태가 테일리스크(발생 확률은 낮지만 한번 발생하면 큰 충격을 주는 위험)로 번지며 장기화되지 않는다면 인플레이션 우려가 현재보다 크게 증폭될 가능성은 낮다"고 부연했다.', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008812361', 'https://imgnews.pstatic.net/image/421/2026/03/08/0008812361_001_20260308080012972.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-08 08:00:00', 0, true, '2026-03-09 05:43:22.327051') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (544, '"공포에 산 개미 환호" 이틀 연속 쭉쭉..."변동장 ''이 업종'' 주목"', '[내일의 전략]6일 서울 중구 하나은행 본점 딜링룸 전광판에 종가가 표시되고 있다. 이날 코스피 지수는 전일대비 0.97p(0.02%) 오른 5584.87에 코스닥은 전일 대비 38.26p(3.43%) 오른 1154.67에 장을 마감했다. /사진=뉴스1장초반 하락 출발한 후 하루종일 혼조세를 보이며 맥을 못추던 코스피가 상승으로 마감했다. 증권가에서는 중동전쟁의 영향을 받은 지정학적 리스크를 소화했고 펀더멘털과 실적을 살펴 비중을 확대하는 전략을 제안했다.6일 한국거래소에 따르면 코스피 지수는 전일 대비 0.97포인트(0.02%) 오른 5584.87로 장 마감했다. 코스피는 ''검은 화요일''로 불리며 급락장을 펼친 지난 4일 이후 2거래일 연속 상승했다. 이날 개인은 코스피 주식을 2조9495억원어치 나홀로 순매수했다.코스닥은 장초반 지수가 급등하면서 매수 방향 사이드카가 발동했다. 매수 사이드카는 전일에 이어 이틀째 울렸다. 사이드카 발동시점의 프로그램 순매도 거래규모는 322억원을 기록했다.시장은 당분간 중동 사태의 영향을 받을 것으로 증권가는 내다보고 있다. 호르무즈 해협의 폐쇄가 장기화할 경우 유가와 천연가스 가격 등이 올라 악영향을 미칠 수 있다. 협상을 통해 현지 긴장이 완화할 경우에는 반대 장세가 연출될 가능성도 있다.증권가에선 국내 증시에 영향을 미칠 수 있는 미국의 주요 지수에 주목하고 있다. 현지시간으로 6일에는 미국의 2월 고용보고서(실업률 포함), 11일에는 미국 소비자물가지수(CPI), 13일에는 미국 근원 개인소비지출(PCE) 수치가 공개된다.이날 대신증권은 중장기적 관점에서 실적 추세와 펀더멘털은 견고하다는 입장을 밝혔다. 이경민 대신증권 FICC(채권·외환·원자재) 부장은 "중장기적 관점에서 실적 가시성 또는 성장성이 높은 반도체, 방산·조선, 기계·원전, IT하드웨어, 자동차 업종을 비롯해 업황 개선이 가시화되는 화학, IT가전, 철강, 2차전지 등은 변동성을 매수 기회로 활용해야한다"며 "에너지, 철강, 2차전지, 소재, 화장품, 호텔·레저, 소매·유통 등은 차익실현 매물이 출회할 경우 물가지표 발표 결과를 확인하면서 적정 가격에서 전략적으로 대응해야 할 것"이라고 말했다.상상인증권 리서치센터는 이날 보고서를 통해 "이란에 대한 변수가 자산시장의 향방을 좌우할 것으로 보이는 가운데, 미국 CPI와 오라클 실적 발표가 각각 물가와 AI 소프트웨어에 대한 우려를 해소시킬지를 지켜봐야한다"며 "유가를 비롯한 에너지 가격의 불안정성은 시장 참가자의 투심 위축과 투자의 시계열을 단축시킬 수 있어 변동성 확대 요인으로 작용할 수 있다"고 했다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005326508', 'https://imgnews.pstatic.net/image/008/2026/03/06/0005326508_001_20260306184815099.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-06 17:20:17', 0, true, '2026-03-09 05:43:22.327051') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (367, '지난해 영풍 등 상장법인 25개사 주식 액면변경', '2025년 한 해 동안 상장법인 25개사가 주식 액면변경을 실시했다고 한국예탁결제원이 오늘(28일) 밝혔습니다.액면분할을 실시한 곳은 13개사, 액면병합을 진행한 곳은 12개사로 나타났습니다. 이는 전년 대비 감소한 수치입니다. 유가증권시장에서는 전년 대비 2개사 감소한 5개사가, 코스닥시장에서는 10개사 감소한 20개사가 액면변경을 실시했습니다.액면분할은 주식의 액면가를 일정 비율로 나누어 주식 수를 증가시키는 방식입니다. 이는 주식거래의 유통성을 제고하기 위해 실시됩니다. 액면병합은 액면가가 낮은 주식을 합쳐 액면가를 높이는 방식으로, 기업 이미지 제고 등을 목적으로 합니다.상법상 액면주식 1주의 금액은 100원 이상이거나 무액면주식입니다. 상장법인의 경우 1주의 금액이 100원, 200원, 500원, 1000원, 2500원, 5000원의 6종류나 무액면주식이 있습니다. 2025년 12월 말 기준, 증권시장에서는 이러한 6종류 액면주식과 무액면주식이 유통되고 있습니다.지난해 유가증권시장에서는 500원에서 100원으로 액면분할을 실시한 유형이 다수를 차지했습니다. 코스닥시장에서는 100원에서 500원으로 액면병합을 실시한 회사가 다수를 차지했습니다.액면금액 분포는 유가증권시장에서 500원이 50.2%, 코스닥시장에서는 75%를 차지하며 가장 많았습니다. 투자자는 시장에 다양한 액면금액의 주식이 유통돼 주가의 단순비교가 어려워 세심한 주의가 필요합니다.액면변경을 실시한 상장법인의 구체적인 사례로는 ㈜영풍, 일정실업(주), 강남제비스코(주), ㈜성안머티리얼스 등이 있습니다. 이들 기업은 각각 5000원에서 500원, 5000원에서 1000원, 1000원에서 500원, 500원에서 100원으로 액면분할을 실시했습니다. 액면병합을 실시한 기업으로는 케이비아이동양철관(주) 등이 있으며, 이 경우 500원에서 1000원으로 액면병합을 진행했습니다.당신의 제보가 뉴스로 만들어집니다.SBS Biz는 여러분의 제보를 기다리고 있습니다.홈페이지 = https://url.kr/9pghjn', NULL, 'SBS Biz', 'https://n.news.naver.com/mnews/article/374/0000489210', 'https://imgnews.pstatic.net/image/374/2026/01/28/0000489210_001_20260128143709604.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-28 14:37:09', 0, true, '2026-03-09 05:36:23.110709') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (368, '[지배구조 톺아보기] 강남제비스코 장남 사임, 모친은 최대주주로…차남 사망 후 막 내린 ‘母子 경영’', '차남 사망 따른 지분 상속…임예정 회장 최대주주 등극장남 황익준 대표는 사임, 계열사 이사 유지강남제비스코, 실적 부진 속 경영 체제 재정비국내 페인트 제조 상장사 강남제비스코의 지배구조가 오너 일가의 지분 상속을 계기로 재편됐다.임예정(73) 회장이 지난달 말 강남제비스코 최대주주로 올라선 이후, 임 회장의 장남인 황익준(47) 대표이사가 사임하며 대표 교체와 최대주주 변경이 동시에 이뤄졌다. 회사는 기존 황익준·김재현 각자대표 체제에서 전문경영인인 김재현 대표 단독 체제로 전환했다.그래픽=정서희황 전 대표는 고(故) 황학구 강남제비스코 창업주의 손자로, 오너 3세 경영인이다. 그는 미국 로체스터 공과대학을 졸업한 뒤 2011년 부친인 황성호 회장이 별세하면서 강남제비스코에 입사했다. 이후 해외사업실장, 경영기획실장 등을 거쳐 2016년 대표에 올랐고, 약 10년간 회사를 이끌어왔다.임 회장 역시 2011년 회장직에 오르며 회사 경영을 총괄해 왔다. 이에 따라 강남제비스코는 지난 10여 년간 임 회장과 황 전 대표를 축으로 한 ‘모자(母子) 경영’ 체제를 유지해 왔지만, 이번 인사를 계기로 해당 체제는 막을 내리게 됐다.지배구조 변화의 직접적인 계기는 임 회장의 차남인 황익수씨의 사망이다. 황씨가 보유하던 지분 18.87%는 지난달 29일 모친인 임 회장에게 상속됐다. 이로써 임 회장의 지분은 23.95%로 늘었고, 최대주주도 황익준 전 대표(19.24%)에서 임 회장으로 변경됐다.지분 승계 이틀 뒤인 지난달 31일에는 황 전 대표가 일신상의 사유를 들어 대표이사와 사내이사직에서 모두 사임했다. 이로써 황 전 대표는 경영과 이사회에서 완전히 물러났으며, 이는 단순한 보직 조정이 아닌 ‘경영 일선 퇴진’으로 해석된다.업계에서는 장남인 황 전 대표가 19.24%의 지분을 보유한 상태에서도 대표이사직을 내려놓은 점을 주목하고 있다. 이를 두고 모친인 임 회장을 정점으로 한 지배구조를 명확히 하기 위한 정비 과정이라는 분석이 나온다.임 회장의 차남 황익수씨는 2011년 황 전 대표와 함께 입사해 경영에 참여했지만, 2010년대 말 학업을 이유로 회사를 떠났다. 임 회장의 막내딸인 황수진씨는 강남제비스코 지분 4.44%를 보유하고 있지만, 회사 경영에 참여하지 않고 있다.황 전 대표의 사임 배경에는 실적 부진도 영향을 미친 것으로 풀이된다. 강남제비스코는 2024년 매출 6431억원, 영업이익 205억원을 기록했다. 매출은 전년 대비 증가했지만, 영업이익은 231억원에서 11% 감소했다. 특히 회사 전체 매출의 약 57%를 차지하는 도료 사업에서 적자가 이어지고 있다. 도료 사업 영업손실은 2022년 175억원, 2023년 55억원, 2024년 74억원이었다.황 전 대표는 강남제비스코 경영에서는 물러났지만, 강남화성(접착제·합성수지 제조사), 강남건영(건설사) 등 계열사 이사로 재직하며 일부 계열사 경영에는 관여하고 있는 것으로 알려졌다.재계 관계자는 “이번 인사는 상속을 계기로 지배구조를 정비하고 전문경영인 체제로 전환하려는 결정으로 해석된다”며 “도료 사업을 비롯한 핵심 사업의 수익성 개선 여부가 향후 황 전 대표의 역할을 가르는 변수가 될 것”이라고 말했다.', NULL, '조선비즈', 'https://n.news.naver.com/mnews/article/366/0001138270', 'https://imgnews.pstatic.net/image/366/2026/01/26/0001138270_001_20260126090718740.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-26 06:01:20', 0, true, '2026-03-09 05:36:23.110709') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (369, '"한번 지으면 재건축 어렵다던데"…건설사 해법은?', '장수명주택 기술 개발 ''총력''방수 페인트로 철근 부식 예방배관 모듈화…수리 간편해져건설사들이 기존 주택의 수명을 늘리고 유지·보수 효율성을 높이는 이른바 ‘장수명 주택 기술’을 잇달아 내놓고 있다. 노후 단지를 재건축할 때 용적률을 높게 적용하면 이후 다시 짓기 힘들기 때문이다.23일 업계에 따르면 포스코이앤씨는 최근 철근 부식을 예방할 수 있는 콘크리트 배합 기술을 개발한 데 이어 인증을 추진하고 있다. 철근콘크리트의 내구 수명을 연장하기 위한 기술이다. 철은 공기 중 이산화탄소와 반응하며 녹슨다. 콘크리트의 알칼리성을 강화해 이산화탄소와 먼저 반응(탄산화)하게 만드는 원리다.철근콘크리트에 보호막을 덧대는 방법도 있다. DL이앤씨는 강남제비스코와 공동 개발한 ‘내구성 향상 페인트’로 국토교통부 건설신기술 인증을 받았다. 회사 측은 “탄성 및 방수성을 높여 이산화탄소 침투를 방해하는 방식이어서 탄산화 속도를 5분의 1로 늦출 수 있다”고 설명했다. GS건설과 포스코이앤씨도 비슷한 원리의 도막재(방수층 형성 자재) 기술을 보유하고 있다. 효성중공업은 콘크리트 강화와 페인트 보강을 동시에 적용하는 ‘이중복합기술’을 내놨다.유지·관리를 쉽게 하는 기술도 속속 등장하고 있다. 삼성물산이 선보인 ‘넥스트 플로어’는 입주자가 원하는 곳에 물을 사용하는 ‘수공간’을 배치할 수 있도록 바닥 하부 공간에 배관을 설치하는 기술이다. 모듈 형태로 제작돼 해체와 이동, 재설치가 쉽다. 건물 전체에 적용하면 노후 배관을 쉽게 교체할 수 있다. 전재열 단국대 건축공학과 교수는 “건물을 오래 쓰지 못하는 주된 원인은 콘크리트보다 수명이 짧은 배관에 있다”며 “동절기 추위로 설비를 외부에 설치하기 어려운 만큼 쉽게 교체할 수 있는 시스템을 구축해야 한다”고 말했다.업계가 장수명 주택 건설에 나서는 것은 용적률이 높은 재건축·재개발 사업이 늘어 30년 이후 추가적인 도시정비사업이 쉽지 않을 가능성이 높아서다. 서울 송파구 ‘잠실르엘’(미성·크로바 재건축), 경기 광명 ‘광명자이더샵포레나’(광명1R 재개발) 등은 제3종 일반주거지역의 최고 용적률로 정비계획을 확정하고 공사를 시작했다. 수도권 1기 신도시 재정비 단지도 용적률을 법적 최고 한도의 1.5배까지 늘리는 방안이 추진되고 있다. 이지현 주택산업연구원 도시정비실장은 “강북 노후 주택 재개발과 중층 아파트 재건축은 기존 가구 수가 많은 데다 사업성이 상대적으로 낮다”며 “미래에 용적률 체계를 개편하지 않는 이상 건축물 수명을 늘리는 방법을 고민할 수밖에 없다”고 말했다.', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005241393', 'https://imgnews.pstatic.net/image/015/2026/01/23/0005241393_001_20260123234815980.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-23 16:45:13', 0, true, '2026-03-09 05:36:23.110709') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (370, '아파트 외벽 내구성 높이는 페인트 나와', '강남제비스코 신기술 인증''제비표 페인트''로 알려진 강남제비스코가 DL이앤씨와 공동 개발한 ''푸른솔 듀라쉴드 프라이머''를 적용한 공동주택 내구성 향상 페인트 기술이 국토교통부의 건설신기술(NeT) 인증을 획득했다고 밝혔다.이번 인증은 국내 건설 분야에 적용되는 페인트 제품이 국토부 건설신기술 인증을 받은 최초 사례로, 국내 건설용 페인트의 기술적 완성도와 현장 적용성이 공식적으로 인정받았다는 평가가 나온다.건설신기술 인증은 국내 최초 개발 기술 또는 기존 기술을 개선해 신규성·진보성·현장 적용성이 입증된 기술에 부여되는 제도다.''푸른솔 듀라쉴드 프라이머''(사진)는 탄성·내수성이 우수한 아크릴 에멀전계 고기능성 외벽 프라이머로, 도막의 탄성이 뛰어나 콘크리트 외벽에 발생하는 미세 균열에 유연하게 대응할 수 있고, 효과적인 방수막을 형성한다. 또 외부 수분 침투를 차단하는 동시에 탄산화 저감 성능을 확보해 콘크리트의 구조적 성능 저하를 사전에 방지한다.[이유진 기자]', NULL, '매일경제', 'https://n.news.naver.com/mnews/article/009/0005624042', 'https://imgnews.pstatic.net/image/009/2026/01/19/0005624042_001_20260119173417426.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-19 17:34:17', 0, true, '2026-03-09 05:36:23.110709') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (371, '강남제비스코, 국토부 건설신기술 인증 획득', 'DL이앤씨와 ‘푸른솔 듀라쉴드 프라이머’ 공동개발국내 건설용 페인트로 국토부 인증 최초탄성과 내수성 우수…외벽 노후화 지연공동주택 내구성 향상 기술로건설시장 새 기준 제시 -국토교통부로부터 건설신기술 인증을 받은 강남제비스코의 ‘푸른솔 듀라쉴드 프라이머’.강남제비스코 제공강남제비스코는 ‘푸른솔 듀라쉴드 프라이머’를 적용한 ‘공동주택 내구성 향상 페인트 기술’이 국토교통부의 ‘건설신기술(NeT)’ 인증을 획득했다고 12일 밝혔다.이번 인증은 국내에서 건설 분야에 적용되는 페인트 제품 가운데 국토교통부 건설신기술 인증을 받은 최초 사례로, 국내 건설용 페인트 기술의 기술적 완성도와 현장 적용성이 공식적으로 인정받았다는 점에서 의미가 크다.건설신기술 인증은 국내 최초 개발 기술 또는 기존 기술을 개선해 신규성·진보성·현장 적용성이 입증된 기술에 부여되는 제도로, 이번 기술은 공동주택 외벽 내구성 향상 분야에서 기술 혁신성을 인정받았다.DL이앤씨와 공동 개발한 푸른솔 듀라쉴드 프라이머는 탄성과 내수성이 우수한 아크릴 에멀젼계 고기능성 외벽 프라이머로 도막의 탄성이 뛰어나 콘크리트 외벽에 발생하는 미세 균열에 유연하게 대응하여 효과적인 방수막을 형성한다. 또한 외부 수분 침투를 차단함과 동시에 탄산화 저감 성능을 동시에 확보해 콘크리트의 구조적 성능 저하를 사전에 방지한다.이 제품은 자외선과 강우 등 외부 환경 변화에도 탁월한 내구성을 유지해 시간이 경과해도 안정적인 도막 성능을 발휘하는 것이 특징이다. 이를 통해 공동주택 외벽의 노후화를 지연시키며 장기적인 내구성 확보가 가능하여 재도장 기간 단축 등 유지관리 비용 절감에 기여할 수 있을 것으로 기대된다.푸른솔 듀라쉴드는 2021년 특허 등록을 시작으로 2022년 한국콘크리트학회 인증을 획득했으며, 이후 도료 설계 고도화와 현장 적용, 기술 검증, 장기 모니터링까지 DL이앤씨와 약 4년에 걸친 협업을 통해 기술 완성도를 지속적으로 높여왔다. 그 결과 지난해 12월 공동주택 내구성 향상 페인트 기술로 건설신기술 인증을 획득했으며, 최대 16년간 기술 보호와 함께 공공 건축현장 등 관급 공동주택 시장에 공급이 가능해졌다.강남제비스코 관계자는 “국내 건설용 페인트 분야에서 독보적으로 건설신기술 인증을 획득함으로써 제비스코의 차별화된 도료 기술 경쟁력을 공식적으로 입증받았다”며 “침체된 국내 건설시장에 새로운 기술 혁신을 제시하고, 공동주택의 장기 내구성과 품질 향상에 끊임없이 기여해 나가겠다”고 말했다.', NULL, '부산일보', 'https://n.news.naver.com/mnews/article/082/0001362281', 'https://imgnews.pstatic.net/image/082/2026/01/12/0001362281_001_20260112163114922.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-12 16:31:14', 0, true, '2026-03-09 05:36:23.110709') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (372, '유가 100달러 돌파 산업계 ‘초비상’ 내연기관 줄인다 “1분 1초가 비상”[종합]', '국제 유가가 배럴당 100달러 선을 돌파하며 산업계에 ‘초고유가’ 경보가 발령됐다.중동 정세 불안이 장기화 조짐을 보이자 삼성, SK, 현대차, LG 등 주요 대기업들은 긴급회의를 소집하고 공급망 다변화와 비용 절감을 골자로 한 비상 대응 체계에 돌입했다.정유·에너지업계·전자·자동차“1분 1초가 비상”유가 변동에 가장 직접적인 영향을 받는 정유 및 석유화학 업계는 그룹 수뇌부가 직접 진두지휘에 나섰다.기아 셀토스.허태수 GS그룹 회장을 필두로 고위 임원진이 사태 추이를 예의주시하고 있다. 특히 GS칼텍스는 호르무즈 해협 봉쇄 가능성에 대비해 비축유 활용 및 원유 수송 우회 경로 확보 등 시나리오별 대책을 마련 중이다.한화그룹에선 한화토탈에너지스와 한화솔루션 등 석유화학 계열사를 중심으로 원료 수급 현황과 공장 가동 상황을 실시간으로 점검하고 있다.HD현대는 중동 사태 이후 지속적인 긴급회의를 통해 정부의 에너지 수급 안정 정책에 발맞춘 대응 방안을 검토하고 있다.유류비 비중이 높은 운송 업계는 수익성 악화를 막기 위해 안간힘을 쓰고 있다.대한항공은 연간 예상 유류 소모량의 최대 50%에 대해 ‘유가 헤지(Risk Hedge)’를 시행하며 탄력적으로 대응하고 있으며, 국내 최대 해운사인 HMM은 유류할증료 부과와 경제속도 운항을 통한 비용 절감을 추진 중이다.하지만 해운업계 관계자는 “화물마다 유류할증료가 부과됨에 따라 결국 소비자 부담이 커지는 결과로 이어질 것”이라며 우려를 표했다.‘고유가·고환율’ 이중고…환율 1494원까지 치솟아제조업 전반에서는 유가 상승이 원자재 가격 상승과 강달러 현상을 동시에 부추기는 상황을 경계하고 있다. 통상 환율 상승은 수출 기업에 유리하지만, 지금처럼 원자재 가격이 동반 급등할 경우 수입 원가 부담이 수출 이익을 상쇄하기 때문이다.전자업계는 유가 상승이 모든 원자재 가격에 전이될 것으로 보고 비용 통제 방안을 검토 중이다.연초 인공지능으로 주목 받아온 현대차그룹 등은 유가 상승에 따른 ‘내연기관차 수요 감소’ 가능성을 주시하고 있다.이에 따라 하이브리드 및 전기차 비중을 높이는 ‘제품 믹스’ 조정 카드를 만지작거리고 있다.전문가들은 이번 상황이 단기적 비용 상승을 넘어 글로벌 경기 둔화와 고물가가 동반되는 스태그플레이션으로 이어질 가능성을 경고한다.현대경제연구원에 따르면 연평균 유가가 100달러 수준을 유지할 경우, 국내 국내총생산(GDP) 성장률은 0.3%포인트 하락하고 소비자물가는 1.1%포인트 상승할 것으로 분석됐다. 경상수지 역시 260억 달러 가량 감소할 전망이다. 화폐가치가 그 만큼 줄어들기 때문이다. 이처럼 경영 불확실성이 극에 달하면서, 일부 기업들 사이에서는 연초에 세웠던 대규모 투자 계획을 전면 재검토하고 있다.손재철 기자 son@kyunghyang.com', NULL, '스포츠경향', 'https://n.news.naver.com/mnews/article/144/0001102147', 'https://imgnews.pstatic.net/image/144/2026/03/09/0001102147_001_20260309111215912.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-03-09 11:11:12', 0, true, '2026-03-09 05:36:46.292222') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (373, '[유가 100달러] 기업들 비상체계 가동…비용방어·공급선 다변화', '모니터링 강화·긴급회의…투자계획·집행 시기도 다시 들여다봐[그래픽] 국제유가 추이(서울=연합뉴스) 원형민 기자 = 미국, 이스라엘과 이란 간 전쟁 여파로 걸프 지역 원유 공급망이 크게 흔들리면서 9일 국제유가가 배럴당 100달러를 넘어섰다. circlemin@yna.co.kr(서울=연합뉴스) 조성흠 김보경 홍규빈 한지은 윤민혁 기자 = 미국·이스라엘과 이란 간 전쟁 여파로 국제 유가가 배럴당 100달러선을 돌파하자 국내 대기업들은 긴급회의를 여는 등 비상 체계에 돌입했다.이란 사태 장기화로 ''초고유가'' 시대가 도래할 가능성이 커짐에 따라 대기업들은 비용 방어에 더해 공급선 다변화, 생산전략 조정 등 다양한 대책을 검토하는 모습이다.정유공장[연합뉴스 자료사진]긴급회의·모니터링 등 대책 마련 ''분주''…경영난 가중 전망9일 재계에 따르면 삼성·SK·현대차·LG·한화·HD현대·GS 등 주요 대기업들은 주말부터 긴급회의를 소집하고 관련 부서를 중심으로 시시각각 변하는 상황에 촉각을 곤두세우고 있다.특히 유가 상승에 가장 직접적인 영향을 받는 정유 및 석유화학 계열사를 둔 대기업 그룹은 회장을 필두로 임원진들이 직접 사태를 모니터링하며 대책을 모색 중이다.한화토탈에너지스, 한화솔루션 등 석유화학 계열사를 둔 한화그룹은 그룹 차원에서 원료 수급, 공장별 가동 상황 등을 실시간으로 모니터링하고 있다.HD현대는 중동 사태 이후 지속해 긴급회의를 열어 정부의 에너지 수급 안정 정책에 협조할 방안을 검토하고 있다.GS그룹은 허태수 회장을 중심으로 고위급 임원진이 사태의 추이와 영향을 챙기고 있다. 그룹의 정유 계열사인 GS칼텍스는 호르무즈 해협 봉쇄 등 중동 사태 장기화에 대비해 비축유 활용, 원유 수송 우회경로 확보 등 대책을 마련 중이다.유류비 비중이 높은 항공·해운업계도 유가 헤지(위험회피) 확대를 포함한 대응 방안을 다각도로 들여다보고 있다.대한항공은 연간 예상 유류 소모량의 최대 50%에 대해 유가 헤지를 실행 중인 가운데 국제 유가 추이를 모니터링하며 탄력적으로 대응한다는 계획이다.국내 최대 해운사 HMM은 곧 유류할증료를 부과할 계획이다.HMM 관계자는 "최소한의 비용 절감 차원에서 경제속도로 운항하는 것 외엔 할 수 있는 게 많지 않다"면서 "화물마다 유류할증료가 부과돼 소비자 부담이 커지게 될 것"이라고 말했다HMM[연합뉴스 자료사진]다른 업종도 유가 급등에 대비해 원자재 수입 및 완제품 수출의 대체 운송 경로를 확보하고 비용 통제 방안을 검토 중이다.한 전자업체 관계자는 "유가가 오르면 모든 원자재 가격이 동반 상승할 수밖에 없다"며 "유가가 너무 올라서 모든 산업에 부담이 커질 것으로 보인다"고 말했다.고유가에 따른 강달러로 환율까지 급등한 데 따른 영향도 집중 점검 중이다.통상적으로 환율이 오르면 수출 기업의 가격 경쟁력이 높아질 수 있지만, 지금처럼 원자재 가격과 환율이 동시에 오르는 상황에서는 수입 원가 부담이 수출 이익을 상쇄하는 역효과가 더 클 수 있다.기업들이 환율 변동 위험 회피를 위해 통화 스와프, 옵션 등 파생상품으로 환 헤지를 시행 중이지만, 환율 급변에 따른 변동성은 기업 전략 수립을 어렵게 하고 있다.다른 대기업 관계자도 "환율 수준보다 변동성이 너무 큰 것이 문제"라며 "기존의 헤지 전략을 넘어서는 리스크에 대해선 사업 계획 수정도 필요할 것"이라고 말했다.현대차그룹 등 자동차 업계는 유가 변화에 따른 내연기관차 등 수요 변화를 우려하고 있다.고유가 기조가 지속될 경우 내연기관차 대신 하이브리드 및 전기차 비중을 늘리는 등 제품 믹스를 조정하는 방안도 검토할 것으로 예상된다.기름값 상승[연합뉴스 자료사진]유가상승이 경기침체 가속할수도…연초 투자계획 재검토 움직임국내 대기업들은 이번 상황이 단기적 비용 상승과 물류 차질에 그치지 않고 글로벌 경기 둔화와 고물가를 동반한 스태그플레이션으로 이어질 가능성까지 염두에 두고 있다.국제금융센터는 최근 보고서에서 블룸버그 이코노믹스와 씨티 전망을 인용해 에너지 시설 타격, 호르무즈 해협 봉쇄 및 위협 등으로 원유 생산과 운송이 어려워질 경우 국제 유가는 오는 4분기까지 배럴당 100달러 이상으로 유지될 가능성이 크고 120달러까지도 상승 가능하다고 전망했다.현대경제연구원도 올해 연평균 유가가 배럴당 100달러 수준을 유지할 경우 우리나라 국내총생산(GDP) 성장률이 0.3%포인트 하락할 수 있다고 분석했다.또 소비자물가상승률은 1.1%포인트 커지고, 경상수지는 260억달러 감소할 것으로 전망했다.이에 따라 일부 기업은 연초 세운 투자계획을 재검토하거나 집행 시기를 미루는 방안도 들여다보는 것으로 알려졌다.vivid@yna.co.kr', NULL, '연합뉴스', 'https://n.news.naver.com/mnews/article/001/0015946487', 'https://imgnews.pstatic.net/image/001/2026/03/09/GYH2026030900040004402_P2_20260309110017548.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-03-09 10:59:33', 0, true, '2026-03-09 05:36:46.292222') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (374, '이재현·서경배도 제쳤다…유통업계 새 주식왕은 ''38세 창업자''', '김병훈 에이피알 대표, 1년 새 자산 346% 급증정유경 신세계 회장 지분가치 증가…남매 순위 역전오뚜기·동서 등 전통 식품기업 자산은 정체국내 유통·소비재 업계 주식 부자 지형이 바뀌고 있다. 그동안 전통 재벌 총수들이 지켜온 상위권에 30대 창업자가 올라섰다. 에이피알(APR) 창업자인 김병훈 대표(38)가 이재현 CJ그룹 회장(66)과 서경배 아모레퍼시픽그룹 회장(63)을 제치고 유통업계 주식 자산 1위에 올랐다.9일 금융정보업체 에프앤가이드와 유통업계에 따르면 김 대표는 에이피알 지분 31.94%를 보유한 최대 주주다. 지난 5일 종가 기준 지분 가치는 약 3조3828억원으로 집계됐다. 1년 전 7578억원에서 약 2조6250억원 늘어난 규모다. 증가율은 346%에 달한다. 전체 주식 부자 순위에서도 김 대표는 전년보다 19계단 오른 16위를 기록했다. 유통·소비재 업계 오너 가운데 가장 높은 순위다.김병훈 에이피알 대표(왼쪽부터), 이재현 CJ그룹 회장, 서경배 아모레퍼시픽그룹 회장.김 대표는 뷰티 브랜드 기업인 에이피알을 창업한 30대 기업인이다. 디지털 마케팅과 온라인 직판(Direct to Consumer·D2C) 전략을 앞세워 글로벌 시장에서 빠르게 성장했다. 특히 뷰티 브랜드 ''메디큐브'' 등이 해외 시장에서 인기를 끌며 실적과 기업가치가 동시에 상승했다는 평가가 나온다. 에이피알 주가 상승이 김 대표 개인 자산 급증으로 이어진 셈이다.그동안 유통·소비재 업계 주식 자산 상위권은 전통 대기업 총수들이 차지해 왔다. 이 회장은 CJ(42.07%), CJ제일제당(0.43%), CJ프레시웨이(0.59%), CJ ENM(1.82%) 등의 지분을 보유하고 있다. 이들 지분 가치는 약 2조3072억원으로 업계 2위를 기록했다. CJ 주가 상승 영향으로 1년 새 자산이 약 1조원 늘었고 증가율은 77%에 달했다.유통업계 주식 부자 1위를 유지해온 서 회장은 올해 3위로 밀려났다. 서 회장은 아모레퍼시픽홀딩스(54.97%)와 아모레퍼시픽(10.65%) 지분을 보유하고 있다. 지분 가치는 약 1조9901억원으로 집계됐다. 화장품 업황 회복 기대감 속에 주가가 상승했지만 증가율은 20% 수준에 그쳤다. 전체 주식 부자 순위는 전년보다 9계단 하락했다.패션 기업 F&F 창업자인 김창수 회장(65)은 F&F홀딩스(62.84%)와 F&F(23%) 지분 가치가 약 1조231억원으로 4위에 올랐다. 이어 신세계(29.16%)와 신세계인터내셔날(15.29%) 지분을 보유한 정유경 신세계 회장(54)이 약 1조163억원으로 5위를 기록했다. 신세계 주가가 1년 사이 249% 상승하면서 정유경 회장의 지분 가치도 약 6773억원 늘어 증가율이 210%에 달했다. 지분 가치 기준으로는 오빠인 정용진 신세계그룹 회장(58)을 앞서며 남매간 자산 순위도 역전됐다. 정용진 회장은 이마트 주가가 13.8% 오르며 지분 가치가 7275억원을 기록해 9위에 올랐지만, 전체 주식 부자 순위에서는 전년보다 30계단 하락했다.정지선 현대백화점그룹 회장(54)은 약 9432억원으로 6위에 올랐다. 현대지에프홀딩스 주가 상승 영향으로 1년 전보다 자산이 155% 증가했다. 김남정 동원그룹 회장(53)은 약 9253억원으로 7위를 기록했다. 신동빈 롯데그룹 회장(71)은 약 7339억원으로 8위 자리에 이름을 올렸다. 이어 이화경 오리온그룹 부회장(70)이 약 6693억원으로 10위를 기록했다.유통업계 자산 순위에서 나타난 가장 큰 변화는 세대와 사업 모델이다. 과거에는 식품·백화점 중심의 전통 유통 기업 총수들이 상위권을 차지했다. 최근에는 뷰티 브랜드와 패션, 플랫폼 기반 소비재 기업 창업자들이 빠르게 부상하고 있다. 에이피알을 창업한 김 대표는 올해 38세다. 주요 유통 대기업 총수들보다 20~30세 이상 젊다. 디지털 기반기업이 전통 유통 기업을 넘어서는 흐름을 보여준 사례라는 평가가 나온다.주식 자산 증가율을 보면 이런 변화는 더욱 뚜렷하다. 김동선 한화그룹 부사장(37)은 한화와 한화갤러리아 지분 가치 상승 영향으로 자산이 1년 새 442% 증가했다. 정유경 회장 역시 210% 늘어 상위권 인물 가운데 가장 큰 상승 폭을 보였다.반면 일부 전통 식품기업 총수들의 자산은 상대적으로 정체된 모습이다. 함영준 오뚜기 회장(67)의 지분 가치는 약 3808억원으로 1년 전보다 5% 감소했다. 불닭볶음면 수출 호조로 실적이 증가한 삼양식품의 김정수 부회장(62)도 지분 가치가 약 3005억원으로 1년 전보다 3% 증가하는 데 그쳤다. 김석수 동서식품 전 회장(72)의 지분 가치는 약 4336억원으로 거의 변동이 없었다.', NULL, '아시아경제', 'https://n.news.naver.com/mnews/article/277/0005731260', 'https://imgnews.pstatic.net/image/277/2026/03/09/0005731260_001_20260309141910113.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-03-09 10:08:57', 0, true, '2026-03-09 05:36:46.292222') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (545, 'GM철수 악몽 딛고 12조 유치…군산이 꿈틀댄다', '■활기 되찾은 새만금산단 가보니최근 3년간 55개 기업 투자협약지역 새 일자리 1만개 창출 기대현대차, AI·로봇 10조 투입 예정새만금 국가산업단지. /사진제공=전라북도최근 찾은 전북 군산 새만금산업단지 5공구. LS L&F 배터리솔루션과 PKC(전 백광산업)의 공장 건설 현장이 쉴 틈 없이 돌아갔다. 대로변에는 건설 근로자들의 차량이 길게 늘어섰고 점심 시간이 다가오자 인근 식당에서 음식을 준비해 공사장 한쪽에 ‘함바집’을 마련했다. 현장은 근로자들 100여 명이 계속 드나들어 분주했다.2018년 한국GM이 철수하면서 몰락하다시피한 군산 경제가 기업들의 투자 확대로 다시 살아나고 있다. 24일 군산시에 따르면 최근 3년(2023~2025년) 동안 LG화학·HD건설기계·DS단석·세아제강 등 55개 기업이 총 12조 362억 원을 군산에 투자하기로 했다.시는 이 같은 투자로 신규 일자리가 1만 개 가까이 창출될 것으로 집계했다. 기업 투자가 급증하면서 새만금산업단지 분양률은 97%에 달해 새만금개발청은 올 하반기 4공구, 7~9공구 분양도 개시한다.한국GM에 1년 앞서 불황으로 조선소 문을 닫았던HD현대중공업(329180)역시 최근 블록 생산 등이 늘면서 직원과 협력 업체에 1000만 원 넘는 성과급을 지급해 군산 경제에 다시 활력을 불어넣고 있다. 조선소와 한국GM 군산 공장이 폐쇄된 후 근로자 1만 8000명이 일자리를 잃고 인근 도시로 뿔뿔이 흩어진 8년 전과 비교하면 격세지감이 뚜렷하다.정부와 지방자치단체가 새만금산단 일대 기업들에 안정적 전력 공급을 위해 2030년까지 10GW 규모의 재생에너지 공급 체계를 갖추기로 한 것도 향후 군산 경제 활성화에 한몫할 것으로 전망된다.새만금산단은 현재 0.3GW 규모의 육상태양광과 OCI그룹의 열병합발전소가 전력 공급을 담당하고 있는데 수상태양광 등으로 전력설비를 확충해 RE100(재생에너지 100% 사용) 산단으로 거듭난다.여기에 현대차그룹이 조만간 미래 성장 동력인 인공지능(AI)과 수소·로보틱스 사업 육성을 위해 새만금에 5년간 10조 원 규모 투자 계획도 발표할 것으로 알려져 군산 경제는 고공행진을 지속할 것으로 보인다. 새만금은 여의도의 140배에 이르는 부지에 일조량도 풍부해 AI 데이터센터 구축에 알맞은 여건을 갖추고 있다.', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004593001', 'https://imgnews.pstatic.net/image/011/2026/02/24/0004593001_001_20260224233202083.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-24 17:58:12', 0, true, '2026-03-09 05:43:44.364749') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (546, '로봇·신소재·바이오·AIDC까지…미래산업 불빛 다시 밝힌 새만금', '<기업 투자 날개 단 군산 경제>LS·포스코, 새만금에 공장 건설현지 건설사 일감 주고 인력 채용질좋은 일자리 등 산업생태계 구축GM·HD현대重 폐쇄 후 인구감소제한적인 인력풀에 채용도 쉽잖아전기료 감면·정주여건 확보 절실50개가 넘는 기업들이 12조 원 이상의 투자를 개시하고 현대차그룹이 수소와 로봇 등에 10조원의 투자를 계획하면서 8년 전 한국GM 철수로 붕괴됐던 군산 경제가 다시 비상하고 있다. 중국과 가격 경쟁력 등에 정부 지원이 절실한 배터리 소재를 중심으로 바이오연료와 인공지능(AI) 데이터센터까지 조(兆) 단위 대형 투자도 봇물을 이뤄 군산은 한국GM이 철수하기 전보다 한층 강력한 산업 생태계를 구축하고 있다.24일 군산시와 기업들에 따르면 LSL&F배터리솔루션이 최근 군산에서 연산 2만 톤의 전구체 생산 라인 시험 가동에 들어갔다. 현재 직원은 65명으로 본사에서 파견 온 15명을 제외한 50명은 모두 군산과 인근 전주·익산 등에서 채용했다고 한다. 회사는 2만 톤의 전구체 설비를 추가로 건설하고 있는데 완공 시 190명까지 인력을 늘릴 계획이다.포스코퓨처엠의 구형흑연 전문 자회사인 퓨처그라프는 내년 하반기 준공을 목표로 공장 건설이 한창이다. 현재 직원은 15명이지만 생산 라인을 가동하기 시작하면 100여 명을 더 뽑을 예정이다. 여기에PKC(001340)(전 백광산업), 두산퓨얼셀, 에코앤드림, 성일하이텍 등이 신소재 공장 건설에 박차를 가하고 있다.새만금 산업단지 곳곳에서 공장 건설이 진행 중인 데다 기업들이 군산 건설 업체들에 일감을 주면서 지역경제는 한층 활성화하는 분위기다. 군산시는 기업들과 투자협약(MOU)을 맺을 때 지역 기업들에 공사 물량을 우선 발주해 달라는 항목을 넣은 것이 도움이 된다는 후문이다.군산은 지역을 대표하던 한국GM과HD현대중공업(329180)사업장이 2018년 모두 문을 닫아 크게 흔들렸다. 연간 27만 대의 차를 생산하며 1만 2000명의 직원을 고용한 한국GM 공장과 6000명의 직원을 보유했던 HD현대중공업 조선소가 가동을 멈췄기 때문이다.2016년 27만 7551명이던 군산 인구는 10년이 지난 올해 25만 6127명으로 2만 명 넘게 감소했다. 특히 젊은 인구가 일자리를 찾아 군산을 빠져나가면서 30대 이하 인구 비중이 2018년 44%에서 크게 감소했다.군산시는 지역경제를 되살리기 위해 절박하게 기업 유치에 나섰다. 군산시는 1000억 원 이상을 투자하는 기업(한도 100억 원), 공장 전부 혹은 일부 이전 기업(한도 50억 원) 등에 10개 항목의 지원금을 주고 있다. 전북특별자치도가 주는 인센티브와 합치면 새만금 산단 신규 입주 기업은 최소 수십억 원에서 많게는 수백억 원을 지원받을 수 있다.군산시는 제일 먼저 HD현대중공업의 문을 두드렸다. 군산시 등 지자체가 블록을 울산까지 운송하는 비용을 지원하는 조건 아래 군산조선소는 2022년 10월 조업 중단 5년 만에 재가동을 시작했다. 지난해 말 기준 1200명의 직원이 매년 9만 4000톤의 선박 블록을 제작하고 있다.정부의 지원이 필요한 2차전지 기업들도 새만금 산단에 들어왔다. LSL&F배터리솔루션은 길 건너편 PKC로부터 전구체 원료인 가성소다를 공급받는 밸류체인을 구축했다. LS 계열사인 LS MnM도 전구체 원료인 황산니켈을 인근에서 공급하기 위해 1조 1600억 원의 투자를 결정했다. LG화학은 1조 2000억 원을 들여 전구체 공장을 조성하기로 했고 DS단석은 1조 900억 원을 투자해 바이오 연료 생산 시설을 짓기로 했다.새만금 산단에서 사업을 이어오던 상용차 업체들도 부활의 기지개를 펴며 지역에 활력을 불어넣고 있다. KG모빌리티커머셜은 지난해 매출 1077억 원, 영업이익 2억 5000만 원을 기록하며 2023년 KG그룹 편입 후 처음 흑자를 기록했다. 군산이 본사인 타타대우모빌리티 역시 준중형 전기트럭 ‘기쎈’을 출시하며 힘을 내고 있다. 굴삭기와 휠로더를 생산해오던 HD건설기계는 1168억 원을 투자해 방산용 엔진을 군산 공장에서 생산하는 증설 투자를 진행 중이다.현대차그룹이 밝힌 10조 원 규모의 투자까지 가세할 경우 군산 경제 부활은 한층 가팔라질 것으로 전망된다. AI 데이터센터뿐 아니라 수소와 로봇 관련 공장 등이 입주하기 시작하면 전력 등 인프라 구축을 통한 부가가치 창출이 더해지기 때문이다.투자가 늘면서 기업들이 인력 채용에 어려움을 겪고 있는 것은 해결해야할 과제다. 군산의 한 기업 관계자는 “현지에서 인력을 채용하려고 해도 인력풀이 제한적이라 채용에 어려움이 있다” 면서 “일자리 창출 효과가 큰 전통 제조업까지 유치하려면 전력 요금 감면, 정주 여건 확보 등이 꼭 해결돼야 한다”고 말했다.', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004592980', 'https://imgnews.pstatic.net/image/011/2026/02/24/0004592980_001_20260224233638246.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-24 17:47:12', 0, true, '2026-03-09 05:43:44.364749') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (715, '유가 급등에 중소형 정유·에너지주 ''들썩''…상승률 상위권 포진', '중동 사태 후 주가 상승률 상위 5권 내 3개가 정유·에너지 관련석유화학주는 하위권에 ''나란히''…"가격 외 복합적인 시각 필요"호르무즈 해협 통과하는 유조선[로이터=연합뉴스 자료사진. 재판매 및 DB 금지](서울=연합뉴스) 고은지 기자 = 중동지역 정세 불안으로 국제유가가 급등하면서 국내 중소형 정유·에너지 관련 종목이 들썩였다.반면 석유화학 업종은 원가 부담으로 인해 이번 사태에 더 민감하게 반응하며 하락률 상위종목에 줄줄이 포함됐다.8일 한국거래소에 따르면 미국과 이란 간 전쟁이 발발한 이후인 지난 3∼6일 유가증권시장에서 반사 수혜가 예상되는 정유주와 대체재로서 부상한 에너지 관련 종목이 크게 올랐다.특히 주가가 높지 않은 중소형 종목이 나란히 최상위권에 이름을 올렸다.한국ANKOR유전은 3일 215원에서 6일 490원으로 127.91% 급등하며 코스피 상장종목 중 상승률 1위를 차지했다.LIG넥스원(63.85%), 대성에너지(47.64%), 한국석유(42.64%), 흥아해운(41.98%) 등이 그 뒤를 이었다.상승률 상위 5개 종목 중 3개가 정유 및 에너지 관련 종목이었다.한국ANKOR유전은 미국과 이란 간 전쟁이 발발하면서 국제유가가 급등하자 일종의 ''테마주''로 관심을 받으며 매수세가 집중됐다.주가가 1천원 미만의 ''동전주''라는 점도 단기간 상승세를 크게 키운 요인으로 작용했다.한국ANKOR유전 주가는 지난 3일 29.77%, 4일 29.75%, 5일 29.83% 등 사흘 내리 상한가를 기록했다. 6일에는 4.26% 상승 마감했다.한국석유 역시 3일 29.75%, 4일 29.79% 급등했다. 단, 5일에는 2.55% 오르면서 상승세가 둔화했고 6일에는 17.41% 하락하는 등 큰 변동성을 보였다.도시가스 제조·공급기업인 대성에너지는 중동 전쟁으로 인해 국제유가와 함께 천연가스 등 에너지 가격이 상승할 것이라는 전망에 투자자들의 주목을 받았다.이외에도 극동유화(10위·20.70%), S-OIL(11위·17.91%), SH에너지화학(17위·12.90%) 등 정유·에너지 관련 기업의 주가가 높은 상승률을 나타냈다.신재생에너지 기업인 HD현대에너지솔루션은 12.60%(18위) 상승했다.코스피 상승 (CG)[연합뉴스TV 제공]반면에 LG화학, 롯데케미칼, 금호석유화학 등 석유화학 관련주는 원유 가격 급등에 따른 원가 상승 부담에 맥을 못 췄다.3∼6일 LG화학은 21.80% 떨어지며 하락률 7위에 올랐다.LG화학은 미·이란 전쟁 발발 전인 지난달 27일 41만7천500원에서 연이틀 급락하며 4일 종가 기준 30만7천원으로 이틀 만에 10만원 넘게 밀렸다. 다만, 5일부터 소폭 반등해 6일에는 32만6천500원에 거래를 마감했다.같은 기간 롯데케미칼은 21.08%(8위), 금호석유화학은 20.14%(12위) 하락했다.증권가에서는 당분간 유가 불안정성에 따른 변동성 확대가 불가피하다고 왔다.하지만 단순히 유가 움직임뿐만 아니라 다각도의 분석을 통해 매수 여부를 신중히 결정할 필요가 있다고 조언했다.신영증권 이상연 연구원은 "만일 유가 상승이 1∼2주를 넘어서 장기화할 경우에는 본격적으로 인플레이션에 대한 우려가 부각될 수 있다"면서 "중장기 시계열에서 고유가에 대한 대비가 필요하다"고 분석했다.NH투자증권 최영광 연구원은 "제품 가격에만 주목하기보다는 제품별 수급 상황, 원가 상승분 전가 가능성, 향후 유가 하락 시 수익성 방어 여지 등 복합적인 시각이 필요하다"고 말했다.eun@yna.co.kr', NULL, '연합뉴스', 'https://n.news.naver.com/mnews/article/001/0015944389', 'https://imgnews.pstatic.net/image/001/2026/03/08/PCM20260306000065990_P4_20260308070410266.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-08 07:03:01', 0, true, '2026-03-09 05:50:35.733881') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (375, '이란 사태에 방산주 급등⋯한화, 시총 4위 올라', '한화에어로스페이스·한화시스템 등 방산주 급등한화그룹 12개 상장사의 시가총액 합산액 180조한화그룹이 시가총액 기준으로 LG그룹을 제치고 사상 첫 4위에 올랐다. 미국과 이스라엘의 이란 공습으로 한화에어로스페이스 등 방산 계열사의 관련주가 급등한 여파다.서울 장교동 한화빌딩 [사진=한화]9일 한국거래소에 따르면 지난 6일 종가 기준 한화그룹 12개 상장사의 시가총액 합산액은 180조6741억원으로 집계됐다.이는 삼성그룹(1433조2720억원)과 SK그룹(826조5930억원), 현대자동차그룹(300조6250억원)에 이어 4위다. 기존 4위였던 LG그룹((175조290억원)은 한 계단 내려온 5위를 기록했다.한화에어로스페이스는 지난 3일부터 4거래일 동안 주가가 119만5000원에서 148만1000원으로 28만6000원(23.93%) 올라 시가총액이 14조7471억원 증가했다. 지난 6일 기준 시가총액은 76조3654억원이다.한화시스템도 같은 기간 주가가 11만 3600원에서 15만 8900원으로 4만5300원(39.88%) 오르며 시가총액이 8조5580억원 증가한 30조193억원으로 집계됐다.지난 2024년 말 한화그룹 시총 순위는 8위 수준이었으나 지난해 방산업과 조선업 호황으로 한화에어로스페이스·한화오션·한화시스템 등 주가가 오르며 포스코그룹과 셀트리온그룹을 제치고 6위로 상승했다.이어 올해 미국과 이스라엘의 이란 공습으로 한화에어로스페이스, 한화시스템 등 한화그룹 방산 계열사 주가가 급등했다.', NULL, '아이뉴스24', 'https://n.news.naver.com/mnews/article/031/0001011365', 'https://imgnews.pstatic.net/image/031/2026/03/09/0001011365_001_20260309092216733.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-03-09 09:22:16', 0, true, '2026-03-09 05:36:46.292222') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (376, '[기업이슈] 에스팀, 코스닥 상장 첫날 공모가 대비 4배 ''따따블''', '■ 머니쇼 ''기업이슈'' - 도지은어제장에서 이슈가 있었던 업종 살펴보는 기업이슈 시간입니다.◇ 에스팀, 코스닥 입성 첫날 ''따따블'' 달성장윤주·한혜진 소속사로 유명한 에스팀이, 코스닥 상장 첫날, 공모가 대비 4배 주가가 올랐습니다.에스팀은 국내 최초 모델 전문 매니지먼트사로, 장윤주, 한혜진, 이현이 등 유명 모델들을 보유하고 있는 것으로도 유명한데요.2023년 자체 IP 콘텐츠 ''캣워크페스타''를 처음 기획해 진행하는 등 성과를 바탕으로, 매출액이 2021년 254억 원에서 2024년에는 356억 원으로 성장했습니다.앞서 진행된 일반 청약에서 1960.87대1의 경쟁률을 기록하며 흥행을 예고한 바 있습니다.◇ 중동 전쟁에 방산주 들썩…한화그룹, 시총 4위 등극중동 사태가 격화되는 가운데, 아랍에미리트가 국산 요격미사일 체계인 ''천궁-Ⅱ'' 조기 공급을 요청했다는 소식이 전해지면서, 국내 방산주가 급등했습니다.증권가에서는 이번 강세가 단순 단기 반등을 넘어, 방산 업종 재평가 흐름으로 이어질 것이라는 긍정적 전망을 내놓고 있는데요.참고로 LIG넥스원은 천궁-Ⅱ의 제작을 맡고 있고, RFHIC는 LIG넥스원을 통해 레이더용 전력 증폭기를 공급하고 있습니다.◇ 코스피·코스닥 급등 속…2차전지주 일제히 랠리지난주 금요일 국내 증시에서 2차전지 관련 기업들이 다시 투자자들의 관심을 받으며 상승세 보였습니다.전기차 시장의 중장기 성장 전망과 함께, 에너지저장장치(ESS) 수요 확대 기대가 부각되면서 배터리 산업 전반에 대한 투자 심리가 개선되고 있다는 분석이 나왔습니다.특히 글로벌 배터리 공급망 확대 움직임이 투자 심리를 자극하는 요소로 언급됐는데요.미국과 유럽을 중심으로 배터리 생산 기지와 소재 공급망 구축이 진행되고 있고, 이러한 흐름 속에서 배터리 소재와 장비 기업들의 역할이 더욱 중요해지고 있다는 분석입니다.◇ “구글 앱 수수료 내린다”…넷마블, 최대 수혜 기대넷마블이 구글 플레이스토어 앱 수수료 인하 기대감에 주가가 강세 보였습니다.앞서 구글은 지난 4일, 안드로이드 앱 내의 결제 수수료를 30%에서 최소 15%까지 인하하고 구독 서비스에 대한 수수료는 10%로 낮춘다고 밝혔습니다.구글의 결제 시스템을 이용하면 여기에 추가 수수료 5%가 붙지만, 앱 개발자가 자체 결제 시스템을 쓰거나 외부 사이트로 이동해 결제하도록 하는 경우에는 부과되지 않습니다.전문가들은 "앱 수수료 인하가 현실화하면서, 공헌이익률 증대에 따른 게임사들의 수익성 개선이 본격화할 전망"이라고 분석했습니다.당신의 제보가 뉴스로 만들어집니다.SBS Biz는 여러분의 제보를 기다리고 있습니다.홈페이지 = https://url.kr/9pghjn', NULL, 'SBS Biz', 'https://n.news.naver.com/mnews/article/374/0000496547', 'https://imgnews.pstatic.net/image/374/2026/03/09/0000496547_001_20260309082109333.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-03-09 08:21:09', 0, true, '2026-03-09 05:36:46.292222') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (377, '[굿모닝경제] 원유 ETF 급등 / 한화 시총 4위 / 군 대출 444억', '중동 정세 불안으로 국제유가가 급등하면서 국내 원유 ETF 가격이 4년 만에 최고 수준으로 치솟았습니다.한국거래소에 따르면 6일 주요 원유 ETF들이 전 거래일 대비 3~4% 올라 2022년 7월 이후 최고치를 기록했습니다.다만 유가 변동성이 높아지면서 단기 조정 가능성도 있는데다 ETF는 구조상 수익률 괴리가 발생할 수 있어 투자자들의 주의가 필요하다는 지적도 나옵니다.---중동 사태 이후 방산주가 급등하면서 방산기업을 다수 보유한 한화그룹의 시가총액 순위가 바뀌었습니다.한국거래소에 따르면 6일 기준 한화그룹 12개 상장사의 시가총액 합산액은 180조 6740억 원으로 집계돼 삼성그룹과 SK그룹, 현대자동차그룹에 이어 4위로 올라섰습니다.중동 사태로 방산주가 대표적인 수혜 종목으로 꼽히면서 온라인 커뮤니티에선 김승연 한화그룹 회장이 등장하는 밈이 확산되기도 했습니다.---군 장병이 대부업체에서 빌린 대출이 444억 원에 달하는 것으로 나타났습니다.현역병이 242억 원으로 절반이 넘었는데 대부분 20%대의 최고 수준 이자를 부담하는데다 ''충성론'', ''병장론''과 같은 자극적인 인터넷 광고를 보고 유입된 것으로 파악됐습니다.군 장병들이 무리하게 빚을 내 투자 등에 쓰면서 부작용이 커지자 금감원은 대부업체에 무리한 영업 자제를 지도하는 한편 군 장병 금융교육을 강화하기로 했습니다.', NULL, 'MBN', 'https://n.news.naver.com/mnews/article/057/0001938836', 'https://imgnews.pstatic.net/image/057/2026/03/09/20260309080847_20_605_1413352_1080_7_20260309081407881.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-03-09 08:14:07', 0, true, '2026-03-09 05:36:46.292222') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (378, '‘재계 서열’ 지각 대변동…3년만에 무슨 일이?', '한화그룹 계열사들의 주가가 오르자 온라인에 확산한 김승연 한화그룹 회장 밈. [온라인 커뮤니티 갈무리][헤럴드경제=김성훈 기자] 반도체 호황과 글로벌 긴장 고조로 한국의 재계 순위가 급속히 바뀌고 있다.8일 한국거래소에 따르면, 6일 기준 재계 주요 그룹 시가총액 합산액은 삼성그룹이 1433조2720억으로 1위를 차지했고, SK그룹(826조5930억원), 현대자동차그룹(300조6250억원), 한화그룹(180조6740억원)이 2~4위를 차지했다. 그간 4위를 지켰던 LG그룹(175조290억원)은 5위로 내려앉았다.LG그룹은 2022~2023년 시가총액이 2위였다. 2022년 LG에너지솔루션의 상장으로 기존 2위였던 SK그룹을 제친 것. 2023년 1월 초 LG그룹 시총은 203조원이었지만, SK그룹은 그 60% 수준인 124조원에 그쳤다.그러나 3년이 지난 현재 상황은 180도 달라졌다. LG그룹에서 가장 시가총액이 큰 LG에너지솔루션(8일 기준 88조 원)은 전기차 수요 성장세 둔화로 50만원 안팎에 거래되던 주가가 40만원을 밑돌고 있다. 두번째로 큰 LG화학(시가총액 24조 원)도 LG에너지솔루션을 떼어내 중복상장 논란을 일으킨 뒤 주가가 계속 추락해 60만원대에서 30만원대로 주가가 반토막난 상태다.반대로 SK그룹은 SK하이닉스가 AI 생태계 구축의 핵심 역할을 하면서 3년 새 주가가 13배나 급등했다. SK하이닉스의 시총만으로도 658조 원으로 LG그룹 전체의 4배에 달할 정도가 됐다.현대차그룹 역시 피지컬 AI 아틀라스를 공개하며 미래 사업 청사진을 제시한 이후 주가가 큰 폭으로 뛰었다. 3년 전에 비하면 3배가 넘는 54만3000원이다.한화그룹도 2022년 러시아·우크라이나 전쟁 발발 이후 글로벌 군사 긴장이 높아지며 방산 관련 계열사의 주가 급등으로 시가총액이 크게 늘었다. 한화에어로스페이스는 2023년 1월 7만원 안팎이던 주가가 8일 기준 145만9000원으로 20배 가까이 뛰었다. 시가총액은 76조3653억원. 한화시스템도 3년 전 1만원이던 주가가 8일 15만5500원으로 15배 뛰었다. 시가총액은 30조192억원이다.', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002610160', 'https://imgnews.pstatic.net/image/016/2026/03/08/0002610160_001_20260308201609381.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-03-08 19:57:11', 0, true, '2026-03-09 05:36:46.292222') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (379, '이란 전쟁으로 방산주 급등하자…한화, ''시총 4위''로 올라서', '한화그룹, 삼성·SK·현대차 이어 ''재계 4위'' 우뚝중동 사태에 한화에어로·한화시스템 주가 급등[서울=뉴시스] 한화그룹 본사 사옥 전경.(사진제공=한화그룹). 2025.9.18. photo@newsis.com *재판매 및 DB 금지[서울=뉴시스]이지민 기자 = 한화그룹 시가총액이 LG그룹을 제치고 재계 4위에 올라섰다. 중동 사태로 방산 업종 투자 매력이 부각되면서, 한화에어로스페이스·한화시스템 등 주가가 급등한 영향이다.8일 한국거래소에 따르면 지난 6일 기준 한화그룹 12개 상장사의 시총 합산액은 180조6740억원으로 집계됐다. 삼성그룹(1433조2720억원)과 SK그룹(826조5930억원), 현대자동차그룹(300조6250억원)에 이어 4위다. LG그룹(175조290억원) 시총 순위는 5위로 내려앉았다.지난 2024년 말까지만 해도 한화그룹 시총 순위는 8위 수준이었다. 그러나 지난해 방산과 조선업 호황으로 그룹 내 화에어로스페이스·한화오션·한화엔진·한화시스템 등 주가가 일제히 오르며, 포스코그룹과 셀트리온그룹을 제치고 6위로 상승했다.이에 더해 올해 미국과 이스라엘의 이란 공습으로 방산 업종 투자 매력이 재부각되며 시총 순위를 4위까지 끌어올렸다.한화에어로스페이스 주가는 지난달 말 119만5000원에서 지난 6일 148만1000원으로 23.93% 올랐다. 6일 기준 시총은 76조3654억원에 달했다. 한화시스템 주가도 같은 기간 39.88% 급등했다.증권가에서는 방산주 강세가 당분간 이어질 것으로 전망하고 있다. 이란 전쟁이 끝나도 수주 모멘텀은 계속될 것이란 분석이다.장남현 한국투자증권 연구원은 "이란 전쟁 과정에서 방공 미사일의 중요성이 부각됐다"며 "방산은 이번 사태와 무관하게 올해 수출 모멘텀도 강한 업종"이라고 말했다.이한결 키움증권 연구원은 "전쟁 종결 이후 미군이 철수하면 중동 국가들의 방위 수요가 늘어나 방위력 개선 사업이 탄력을 받을 것"이라며 "중동에 수출된 한국산 방공 체계 천궁Ⅱ 성능이 검증돼 향후 장거리 지대공 유도무기체계인 L-SAM 도입에 대한 기대감이 늘어날 것"이라고 예상했다．', NULL, '뉴시스', 'https://n.news.naver.com/mnews/article/003/0013808679', 'https://imgnews.pstatic.net/image/003/2026/03/08/NISI20250918_0001946905_web_20250918111009_20260308230414739.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-03-08 19:43:23', 0, true, '2026-03-09 05:36:46.292222') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (381, '보해양조 막걸리 ''순희'' 전면 리뉴얼…"전통·현대적 가치 강조"', '나비·백호 담은 ''수호신'' 라벨 도입…아스파탐 제거·도수 6→5도보해양조가 리뉴얼한 막걸리 ''순희''(보해양조 제공, 재판매 및 DB금지)/뉴스1(장성=뉴스1) 조영석 기자 = 보해양조가 막걸리 브랜드 ''순희''를 15년 만에 전면 리뉴얼해 선보인다고 4일 밝혔다.보해양조에 따르면 이번 리뉴얼의 핵심은 막걸리의 정체성을 현대적 감각으로 재해석한 ''조선 RTD(Ready To Drink)''다. RTD란 별도 조제 없이 바로 마실 수 있는 주류를 뜻한다. 발효 과정을 거친 술을 사발에 ''막 걸러'' 마시던 조상들의 막걸리 음용 방식이 현대 RTD의 본질인 간편함 및 즉각성과 맞닿아 있다는 게 회사 측 설명이다.보해양조는 이를 ''조선 RTD''로 재정의해 "막걸리의 전통성과 현대적 가치를 동시에 강조했다"고 밝혔다.이번에 전면 리뉴얼해 선보이는 ''순희''는 건강 중시 트렌드에 맞춰 감미료인 아스파탐을 제거하고 알코올 도수를 기존 6도에서 5도로 낮춰 목 넘김은 더 가볍게 했다. 또 "100% 국내산 쌀 사용 원칙을 고수해 밀 함유 제품 특유의 텁텁함이 없으며 깔끔한 뒷맛을 유지한다"고 보해양조가 전했다.이 제품 품질의 뼈대인 파스퇴르 공법도 유지된다. 보해양조는 "발효가 절정에 달한 순간을 포착해 저온살균함으로써 시간이 지나도 신선하고 부드러운 맛을 유지하며, 실온 보관도 가능해 언제 어디서든 편리하게 즐길 수 있다"고 부연했다.브랜드 서사와 디자인엔 변화를 줬다. ''순희''라는 한국인에게 친숙한 이름에 현대인의 일상을 지키는 ''수호신''이라는 의미를 새롭게 불어넣었다는 게 회사 측 설명이다.보해양조는 "전통 고사(告祀) 문화에서 막걸리가 액운을 막는 매개였다는 점에 착안해 순희를 스트레스와 불안을 달래주는 존재로 재탄생시켰다"며 "새 라벨에는 수호신 순희와 함께 나비, 꽃, 백호를 감각적으로 시각화해 현대적인 미감을 더했다"고 소개했다.최현준 보해양조 홍보이사는 "순희는 가장 한국적인 방식으로 현대인에게 위로와 정서를 건네는 수호신 같은 브랜드"라며 "리뉴얼된 순희를 통해 막걸리의 본질적 가치를 새롭게 알리고 현대적인 주류 트렌드를 선도해 나갈 것"이라고 말했다.', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008805221', 'https://imgnews.pstatic.net/image/421/2026/03/04/0008805221_001_20260304105832814.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-04 10:58:00', 0, true, '2026-03-09 05:37:05.829974') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (382, '주류업계 유일 두자릿수 자사주 ''국순당의 고심''', '롯데칠성 ''소각''·무학 ''맞교환''…국순당 11.86% 규제 대상 분류오너 지분 41%·자사주 12%…소액주주 환원보다 지배력 유지 지적자사주 취득 후 소각을 의무화하는 상법 개정안이 국회를 통과하면서 주류업계에서 유일하게 두자릿수 자사주를 보유한 국순당의 고심이 깊어질 전망이다. 지난해 기준 롯데칠성음료, 보해양조, 한울앤제주 등이 1% 미만의 자사주를 보유한 데 반해 국순당의 자사주 비율은 11.86%다. 사진은 국순당 스테디셀러 백세주. /사진=국순당자사주 취득 후 소각을 의무화하는 상법 개정안이 국회를 통과하면서 주류업계에서 자사주 비율이 가장 높은 국순당에 이목이 쏠린다. 경쟁사들이 소각이나 맞교환 방식으로 자사주를 처분한 것과 달리 국순당은 유일하게 자사주 비율 두자릿수를 유지하고 있다.26일 금융감독원 전자공시시스템에 따르면 국순당의 자사주 보유율은 11.86%로 확인된다. 이는 주류 상장사 중 가장 높은 수치다.경쟁사들은 자사주를 정리했다. 롯데칠성음료는 보유 자사주를 전량 소각(0%)했고 보해양조(0.82%)와 한울앤제주(구 제주맥주·0.1%) 자사주 비율은 1% 미만이다. 하이트진로도 2.1% 정도다. 2025년 초까지 자사주 비율 7.1%였던 무학은 지난해 하반기부터 자사주를 조금씩 처분, 지난달 14일 계열사 금비와 1.6% 규모의 자사주를 맞교환해 마지막 보유량을 털어냈다.통상 자본시장에서는 자사주 비중 20% 이상을 고위험군으로, 10% 이상을 정부 규제의 잠재적 영향권으로 분류한다. 주요 주류 기업 중 국순당만 자사주 관련 규제 대상이다.국순당의 지분 구조는 배중호 회장(36.59%)과 배상민 대표(4.88%) 등 오너 일가 및 특수관계인 지분율이 41.47%, 기타 소액주주가 46.67%다. 시장에서는 소액주주 환원보다 자사주를 통한 지배력 유지에 무게를 둔다는 지적이 제기된다.국순당은 지난해 11월 공시를 통해 "현재 보유 중인 자기주식에 대한 처분이나 소각 계획은 없다"고 밝혔다. 개정안이 시행되면 취득한 자사주를 일정 기간 내 의무적으로 소각해야 하는 만큼 국순당의 고심이 깊어질 것으로 보인다.올해 자사주 소각 및 처분 계획과 관련해 국순당 관계자는 "별도로 밝힐 입장이 없다"며 말을 아꼈다.', NULL, '동행미디어 시대', 'https://n.news.naver.com/mnews/article/417/0001131714', 'https://imgnews.pstatic.net/image/417/2026/02/26/0001131714_001_20260226163606461.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-26 16:35:05', 0, true, '2026-03-09 05:37:05.829974') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (383, '[서울데이터랩]오리엔트바이오 29.83% 폭등 금일 증시 상승률 1위로 마감', '12일 오후 15시 35분 오리엔트바이오(002630)가 등락률 +29.83%로 상승률 1위로 마감했다. 오리엔트바이오는 장 중 16,016,210주가 거래되었으며 주가는 전 거래일 대비 162원 오른 705원에 마감했다.한편 오리엔트바이오의 PER은 -11.19로 주가 대비 기업의 수익성이 부정적일 가능성을 시사하며, ROE는 -16.82%로 수익성이 매우 낮은 수준이다.이어 상승률 2위 태광산업(003240)은 주가가 25.21% 폭등하며 종가 1,187,000원에 상승 마감했다. 상승률 3위 씨케이솔루션(480370)의 주가는 11,880원으로 24.92% 폭등하며 강세를 보였다. 상승률 4위 HDC현대EP(089470)는 18.40% 상승하며 6,500원에 마감했다. 상승률 5위 보해양조(000890)는 17.43%의 급등세를 타고 종가 485원에 마감했다.6위 파미셀(005690)은 종가 16,990원으로 16.13% 급등 마감했다. 7위 현대비앤지스틸(004560)은 종가 18,350원으로 15.12% 급등 마감했다. 8위 현대지에프홀딩스(005440)는 종가 13,930원으로 15.12% 급등 마감했다. 9위 SGC에너지(005090)는 종가 34,950원으로 12.74% 급등 마감했다. 10위 화신(010690)은 종가 11,420원으로 12.51% 급등 마감했다.이밖에도 팜스코(036580) ▲12.40%, 아이티센씨티에스(031820) ▲12.12%, 삼영무역(002810) ▲11.95%, DN오토모티브(007340) ▲11.69%, 경동나비엔(009450) ▲10.93%, 한국금융지주우(071055) ▲10.38%, 한미반도체(042700) ▲9.97%, 에코프로머티(450080) ▲9.91%, OCI(456040) ▲9.75%, 대한유화(006650) ▲9.56% 등을 기록하며 금일 증시를 상승으로 마감했다.전문가는 “오리엔트바이오의 경우, 생명과학 관련 신기술 개발 및 연구에 대한 기대감이 주가에 긍정적인 영향을 미쳤을 가능성이 있다”고 분석했다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003617624', 'https://imgnews.pstatic.net/image/081/2026/02/12/0003617624_001_20260212162108137.png?type=w800', 'NEWS_ETC', NULL, '2026-02-12 16:20:07', 0, true, '2026-03-09 05:37:05.829974') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (384, '[서울데이터랩]2월 12일 코스피 주요 종목 마감시황', '2월 12일 한국거래소에 따르면, 오리엔트바이오(002630)는 전 거래일 대비 29.83% 상승한 705원에 거래를 마감하며 금일 코스피 상승률 1위를 차지했다. 태광산업(003240)은 25.21% 상승한 1,187,000원에 거래를 마치며 뒤를 이었다. 씨케이솔루션(480370)은 24.92% 상승한 11,880원에, HDC현대EP(089470)는 18.40% 상승한 6,500원에, 보해양조(000890)는 17.43% 상승한 485원에 각각 거래를 마감했다.코스피 하락률 상위 종목으로는 다스코가 전 거래일 대비 16.20% 하락한 3,880원에 거래를 마감하며 1위를 기록했다. 에이프로젠은 9.17% 하락한 515원에, 이마트는 7.84% 하락한 117,600원에 거래를 마쳤다. TKG휴켐스와 제이알글로벌리츠는 각각 7.49%와 6.52% 하락한 19,520원과 2,150원에 거래를 마감했다.시가총액 상위 종목 중에서는 상승한 종목이 없었다. 하락 종목으로는 삼성전자가 591만 주가 거래되며 0.19%의 하락세를 기록했다. SK하이닉스는 177만 주의 거래량을 기록하며 0.05% 하락했다. LG에너지솔루션은 거래량 23만 주로, 2.43% 하락 마감했다. 삼성바이오로직스는 6만 주가 거래되며 1.39%의 하락세를 보였다.금일 코스피 주요 종목들은 전반적으로 혼조세를 보이며, 상승 종목과 하락 종목이 혼재되어 있다. 투자자들은 개별 종목의 특성과 시장의 추세를 면밀히 분석하여 신중한 투자 전략을 세우는 것이 중요하다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003617628', 'https://imgnews.pstatic.net/image/081/2026/02/12/0003617628_001_20260212162020126.png?type=w800', 'NEWS_ETC', NULL, '2026-02-12 16:20:20', 0, true, '2026-03-09 05:37:05.829974') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (716, '본업보다 부업? ‘투자 귀재’ 넷마블·SKT', '‘지분 투자’의 마법기업 성과를 읽는 기준이 달라지고 있다. 본업만으로 기업가치를 높이기 어려운 환경이 되면서 ‘본업 밖의 성과’를 찾는 기업이 늘었다. 변화의 중심에는 지분 투자가 있다. 일부 기업에선 지분 투자로 발생한 차익 덕분에 본업 부진을 상쇄하고 신사업까지 벌인다. 또 매각 대금을 현금 대신 지분으로 확보하는 사례도 생겼다. 과거엔 부수적인 선택지로 평가받던 지분 투자가 이제는 기업 밸류에이션의 핵심 요소로 올라선 것이다.넷마블은 최근 하이브 일부 지분 매각 공시를 했다. 총 규모는 3207억원이다. 앞서 넷마블은 두 차례 매각을 통해 각각 5235억원, 2200억원을 확보했다. 잔여 지분 가치도 1조원 이상으로 예상된다. (넷마블 제공)본업 흔들려도…버티는 넷마블지분 투자가 만든 ‘시간’과 ‘빅딜’지분 투자로 재미를 본 대표 사례는 넷마블이다. 넷마블의 최근 실적을 별도 재무제표 기준으로 보면, ‘본업 실적’은 그리 좋은 편은 아니다. 지난해 3분기 누적 매출은 9744억원, 영업이익은 353억원이다. 영업이익률은 3.6% 수준이다. 게임 업계의 평균 이익률을 고려하면 상당히 낮은 편이다. 같은 기간 경쟁사인 크래프톤과 네오위즈의 영업이익률은 각각 45.9%, 23.2%에 달한다. 부진했다 평가받는 카카오게임즈도 4.1%다.그나마 현재 실적은 나아진 편이다. 최근까지도 본업은 적자에 허덕였다. 게임 시장 경쟁이 치열해지며 이렇다 할 신작 흥행을 이뤄내지 못한 결과다. 넷마블 연간 영업이익(별도 기준)은 2021년 453억원이었지만, 2022년과 2023년엔 각각 132억원, 417억원 영업손실을 냈다.그런데도 넷마블의 재무 불안은 크게 부각되지 않는다. 한국기업평가도 지난해 12월 넷마블의 신용등급 전망을 ‘A+, 부정적’에서 ‘A+, 안정적’으로 상향했다. 이유는 단순하다. 앞서 지분 투자한 건들의 회수를 통한 유동성 확보가 가능해서다. 지분 투자 덕분에 본업 부진을 견딜 ‘시간’을 번 꼴이다.넷마블은 최근 하이브 지분 매각 공시를 했다. 내용을 살펴보면, 보유 지분 88만주를 주당 36만4500원에 매각하는 형태다. 총 규모는 3207억원이다. 이번이 세 번째 지분 매각이다. 도기욱 넷마블 최고재무책임자(CFO)는 4분기 실적 발표 콘퍼런스콜에서 “하이브 주식 매각을 통한 유동성 확보는 재무 구조를 개선하기 위한 결정”이라고 설명했다.넷마블은 2018년(최초 투자)과 2021년(주주배정 유상증자) 하이브에 지분 투자했다. 매입 주식 수는 753만주, 투자 규모는 약 2900억원이다. 이후 2023년부터 회수를 시작한 상태다. 2023년 250만주(주당 20만9400원)를 매각해 약 5235억원을 확보했고, 2024년 약 2200억원(110만주×19만9900원), 이번에 3207억원을 회수했다. 매각을 통해 확보한 금액은 1조600억원에 달한다. 아직 남은 주식 수도 상당하다. 잔여 지분은 약 305만주다. 2월 9일 기준 하이브 주가(36만6500원)을 고려하면 단순 계산으로도 1조1170억원에 달한다. 조 단위 차익의 투자를 이뤄낸 꼴이다.지분 투자의 역할은 여기서 끝나지 않는다. 새 먹거리를 확보하기 위한 대형 인수합병(M&A)으로도 이어졌다. 대표 사례가 2021년 소셜 카지노 게임 업체 스핀엑스 인수다. 인수 금액은 약 2조5000억원에 달했다. 당시 별도 기준 영업이익이 450억원 수준이었다는 점을 고려하면 본업 현금흐름만으로는 감당하기 어려운 빅딜이었다. 이때 활용한 게 지분 투자 회수다. 당시 넷마블은 하이브뿐 아니라 카카오뱅크와 카카오게임즈 등 과거 지분 투자를 단계적으로 유동화하며 인수 자금을 마련했다.카카오는 다음(AXZ) 매각 대금을 현금 대신 업스테이지 지분으로 받았다. 업스테이지 IPO 이후 중장기 차익 실현 가능성이 제기된다. (카카오 제공)韓은 좁다…지분 투자도 글로벌로‘미래 옵션’ 쌓는 SKT·NXC지분 투자의 대상은 국내를 넘어 글로벌로 확장하고 있다. 목적도 분명하다. 본업 성장 한계를 보완하고, 미래 기업가치를 확보하기 위해서다.통신 산업은 대표적으로 성장 한계가 분명한 산업이다. 내수 시장을 겨냥해 경쟁사와 파이를 나눠먹기 때문이다. SK텔레콤도 마찬가지였다. 본업 성장성은 제한적이었고, 가입자 증가와 무선 가입자 등 본업 지표만으로는 주가 재평가를 설명하기 어려운 구조였다. 이 흐름을 바꾼 게 글로벌 생성형 AI 기업 앤트로픽 지분 투자다. SK텔레콤은 지난 2023년 8월 챗GPT의 강력한 대항마로 꼽히던 앤트로픽에 1억달러(한화 약 1300억원)를 투자했다. 해당 지분 가치는 현재 약 2조~3조원 수준으로 추정된다. 최근 앤트로픽이 투자를 유치하며 인정받은 몸값이 3500억달러(약 510조원)여서다.지분 가치가 부각되며 SK텔레콤 주가는 오름세다. 올해 초 5만3300원이던 주가는 2월 11일 기준 7만5400원까지 올랐다. 40%가 넘는 상승폭이다. 증권가도 기업가치 평가에서 앤트로픽 지분 가치를 별도로 반영해 목표주가를 상향 조정했다.정원석 신영증권 애널리스트는 “앤트로픽이 AI 시장에서의 점유율을 높이고, 수익성을 개선하고 있다는 점을 감안하면 기업공개(IPO) 때까지 기업가치 상승 가능성이 높다”며 “SK텔레콤이 보유한 지분 가치에 대한 시장 관심도 지속될 수 있다고 판단한다”고 말했다. 정 애널리스트는 SK텔레콤 목표주가를 5만7000원에서 9만6000원으로 68% 높였다.넥슨 지주사 엔엑스씨(NXC)도 비슷한 맥락에서 주목받는다. NXC는 지난 2020년 스페이스X 주식을 담은 펀드에 1600만달러를 투자했다. 스페이스X는 일론 머스크가 ‘화성 이주’라는 꿈을 내걸고 설립한 민간 우주 개발 기업이다. 올 하반기 약 1조5000억달러(약 2200조원)의 기업가치로 IPO를 추진 중이다.NXC가 투자했을 당시 기업가치(460억달러)와 환차익을 고려하면, NXC의 스페이스X 투자 수익률은 20배를 웃돌 것으로 추정된다.해외 지분 투자는 아니지만, 카카오 역시 미래 옵션을 위한 지분을 확보했다. 카카오는 다음 운영사 AXZ를 업스테이지에 매각하면서 현금 대신 업스테이지 지분을 확보했다.정확한 지분 수치는 공개되지 않았지만, 증권가에선 10%대 중후반 정도로 보고 있다. 업스테이지는 KB증권과 미래에셋증권을 주관사로 선정하고 올 하반기를 목표로 IPO 절차를 밟고 있다. 업스테이지는 IPO를 통해 최소 2조원의 몸값을 목표로 할 전망이다. 프리 IPO에서는 1조3000억원 몸값을 인정받았다.[최창원 기자 choi.changwon@mk.co.kr][본 기사는 매경이코노미 제2349호(2026.03.04~03.10일자) 기사입니다][Copyright (c) 매경AX. All rights reserved. 무단 전재, 재배포 및 AI학습 이용 금지]', NULL, '매경이코노미', 'https://n.news.naver.com/mnews/article/024/0000103928', 'https://imgnews.pstatic.net/image/024/2026/03/07/0000103928_001_20260307201106999.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-07 20:11:06', 0, true, '2026-03-09 05:50:35.733881') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (717, '한 번도 경험 못한 ‘트리플 쇼크’ 경고음…물가·금리가 나침반', '━미국·이란 전쟁 쇼크, 한국경제 진단“심장이 약한 자는 버틸 수 없다.” 짐 비앙코 비앙코리서치 대표는 4일(현지시간) 엑스(X)에 “개인투자자 쏠림이 심한 한국 증시 구조 탓에 오를 때는 두 배로 뛰지만, 하락 국면에선 단순 조정을 넘어 걷잡을 수 없는 급락으로 이어진다”며 경고했다. 중동 사태 후 하루 변동 폭이 10%를 넘나드는 한국 증시의 ‘롤러코스터 장세’에 글로벌 투자자들도 놀라움을 감추지 못하고 있다. 급락 뒤 극적인 ‘V자 반등’이 나타났지만, 공포는 아직 걷히지 않았다. 반등 속에서도 언제든 다시 흔들릴 수 있다는 긴장감이 이어지며, 투자자는 여전히 일촉즉발의 시장을 마주하고 있다.6일 코스피는 5584.87에 거래를 마쳤다. [뉴시스]인공지능(AI) 투자 열풍 속에 단숨에 6000선을 돌파했던 코스피가 중동 전쟁이라는 돌발 변수 앞에서 급격히 흔들렸다. 전쟁 발발 직후 시장은 말 그대로 쑥대밭이 됐다. 코스피는 1월 27일 5000선을 돌파한 뒤 한 달 만인 2월 25일 6000선을 넘어섰지만, 전쟁 충격 속에 3일과 4일 단 이틀 사이 지수는 18% 넘게 급락하며 그동안 쌓아 올린 상승분을 순식간에 반납했다. 달러당 원화값도 장중 1500원 선까지 밀리며 글로벌 금융위기 이후 17년 만의 ‘환율 쇼크’가 덮쳤다.그래픽=남미가 기자글로벌 사모신용 시장서도 불안 신호 감지그러나 시장은 곧바로 반격에 나섰다. 이틀 동안 951조원이 증발했던 코스피·코스닥 시가총액은 5일 하루에만 412조원이 회복됐다. 6일에도 소폭 상승 마감했다. 코스피는 이날 전 거래일 대비 0.97포인트 오른 5584.87에 장을 마쳤다. 극단적인 폭락 뒤 급반등이 이어지며 한국 증시는 ‘롤러코스터 장세’를 연출하고 있다.과거 지정학적 충격 속에서도 코스피의 하락은 대부분 단기에 그쳤다. 2001년 9·11 테러 당시 코스피 하락률은 약 12%에 달했지만 약 20일 만에 안정을 되찾았다. 같은 해 아프가니스탄 침공이나 2003년 이라크 전쟁 때도 충격은 제한적이었다. 아프가니스탄 침공 당시에는 첫날 하락 폭이 1% 미만에 그쳤고, 시장은 며칠 만에 충격을 흡수했다.그래픽=남미가 기자그러나 이번 상황은 예단하기 이르다. 시장에서는 이번 폭락이 단순한 외부 충격을 넘어 유가·환율·증시가 동시에 흔들리는 ‘트리플 쇼크’로 번질 가능성을 경고하고 있다.가장 먼저 던져야 할 질문은 “왜 유독 한국인가”다. 이란 사태 이후 한국 증시의 낙폭은 주요 국가와 비교해도 두드러진다. 전쟁 발발 이후 지난 3일부터 5일까지 사흘 동안 코스피는 10.57% 급락했다. 같은 위기를 겪은 일본(-6.07%), 대만(-4.92%)보다 낙폭이 훨씬 컸다.더 아이러니한 장면도 나타났다. 전쟁 당사국인 이스라엘 증시(TA-35)는 같은 기간 5.4% 상승하며 사상 최고치를 경신했다. 미국 증시 역시 하루 평균 변동 폭이 1%에도 미치지 않았다. 환율 시장에서도 대비는 뚜렷했다. 달러 대비 원화 가치는 2% 하락한 반면, 이스라엘 셰켈화는 오히려 1.57% 상승했다. 전쟁은 중동에서 났는데, 피는 한국 증시가 흘린 셈이다.그래픽=남미가 기자전문가는 한국 증시의 구조적 취약성을 지목한다. 글로벌 경제 불안이 발생할 때 가장 먼저 흔들리는 ‘탄광 속 카나리아’라는 평가다. 모닝스타의 로레인 탄 아시아 주식 리서치 총괄은 “코스피 하락은 특정 종목 쏠림에서 비롯된 구조적 문제”라고 지적했다. 삼성전자와 SK하이닉스 두 종목이 시가총액의 약 40%를 차지할 만큼 집중도가 높다. AI 거품 논란이 불거지면 대형주 차익 실현이 쏟아지고, 전쟁이 터지면 유가 충격에 취약한 한국 시장 전체가 기계적으로 매도되는 구조라는 분석이다.반도체 업황 기대가 다소 식은 점도 부담이다. 서상영 미래에셋증권 연구원은 “엔비디아 등이 내년 수요까지 대응할 재고를 확보했다고 언급하면서 반도체 수급 공포가 완화됐고, 단기 투자 심리도 냉각됐다”고 말했다. 여기에 단기간 급등에 따른 피로감까지 겹쳤다. 김영익 한양대 겸임교수는 “코스피는 통화량과 수출 대비 과대평가 구간에 들어섰다”며 “지표상 적정 지수는 5000선 아래일 가능성도 있다”고 말했다.문제는 금융시장을 넘어 실물경제다. ‘S의 공포’, 즉 경기 둔화 속 물가 상승을 뜻하는 스태그플레이션 우려가 고개를 들고 있다. 한국은 경제협력개발기구(OECD) 회원국 가운데 국내총생산(GDP) 1만 달러당 원유 소비량이 5.63배럴로 압도적 1위다. 에너지 가격 충격에 그만큼 취약한 구조다. 씨티그룹은 브렌트유가 배럴당 82달러 이상에서 장기간 유지될 경우 한국 경제성장률이 0.45%포인트 하락할 수 있다고 전망했다.환율 역시 위태롭다. 석병훈 이화여대 경제학과 교수는 “이란 전쟁이 없었더라도 대미투자특별법이 확정될 경우 미국과 한국의 기초체력이 더 벌어져 환율이 1500원을 위협할 가능성이 있었다”며 “중동 사태마저 장기화하면 원화 약세는 1500원대 중반까지 확대되며 금리 인하 기대를 꺾을 수 있다”고 말했다.일각 “급락장, 장기 투자자에 기회” 시각도시장이 가장 두려워하는 극단적 시나리오는 전 세계 원유 물동량의 약 20%가 지나가는 호르무즈 해협의 봉쇄 장기화다. 다만 현재 시장은 이 가능성에 큰 무게를 두지 않고 있다. 영국 옥스퍼드이코노믹스는 해협이 심각하게 교란될 가능성을 약 5% 수준의 ‘꼬리 위험(tail risk)’으로 평가했다. 다만 이 시나리오가 현실화할 경우 브렌트유 가격은 배럴당 130~140달러까지 치솟을 수 있다고 전망했다. 현재 국제유가는 브렌트유 80달러대 중반, 두바이유 90달러 안팎에서 움직이고 있다.글로벌 금융시장에서도 불안 신호가 감지된다. 최근 영국 모기지 업체 MFS의 법정관리 신청을 계기로 블루아울, KKR, 아레스 등 대형 운용사가 참여한 펀드들마저 대출 부실과 환매 요구에 시달리며 글로벌 사모신용 시장의 균열이 수면 위로 드러나고 있다. 제이미 다이먼 JP모건 최고경영자(CEO)는 “2008년 금융위기 이전과 비슷한 징후가 보인다”고 경고했다. 박상현 iM증권 연구원은 “이란발 지정학 리스크가 장기화해 고유가가 고착될 경우, 풍부한 유동성 속에 가려져 있던 신용 위험이 빠르게 증폭될 수 있다”고 말했다.다만 전문가는 공포보다 거시 지표를 보라고 조언한다. 김학균 신영증권 리서치센터장은 “전쟁 당사국이 아닌 국가에서는 결국 인플레이션과 장기 금리가 핵심 변수”라며 “전쟁 공포보다 물가와 금리 흐름이 시장 방향을 좌우할 것”이라고 말했다. 실제로 미 국채 시장에서는 이례적인 흐름이 나타나고 있다. 통상 전쟁이 발발하면 안전자산 선호로 국채 금리가 하락하지만, 이번에는 인플레이션 우려가 더 크게 작용하며 미 10년물 국채 금리가 4.1%를 넘어섰다. 시장이 전쟁 자체보다 금리 인하 기대가 꺾일 가능성을 더 두려워하고 있다는 신호다.시장에선 5000선을 주목한다. 지난 4일 장중 기록한 코스피 5059포인트는 주가수익비율(PER) 약 8배 수준으로, 금융위기를 제외하면 역사적으로 강한 지지선으로 작용했던 구간이다. 정해창 대신증권 연구원은 “이란 전쟁이 경기침체나 시스템 리스크로 퍼지지 않는다면 PER 8배 이하 구간은 낙폭 과대 영역으로 볼 수 있다”고 말했다.일각에서는 이번 변동성을 역발상 투자 기회로 보는 시각도 있다. 김용구 유안타증권 연구원은 “증시가 W자 반등 흐름을 보이는 상황에서는 투매 대응보다 보유 전략, 관망보다 매수 전략이 유효하다”고 말했다. 김민국 VIP투자자문 대표는 “급락장에서는 고평가와 저평가 종목이 함께 떨어지기 때문에 장기 투자자에게 기회가 될 수 있다”며 “주주환원이 높은 지주사와 저평가 우량주를 눈여겨볼 필요가 있다”고 말했다.', NULL, '중앙SUNDAY', 'https://n.news.naver.com/mnews/article/353/0000054781', 'https://imgnews.pstatic.net/image/353/2026/03/07/0000054781_001_20260307014211568.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-07 01:10:18', 0, true, '2026-03-09 05:50:35.733881') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (385, '[특징주] “동전주 상장폐지”에 요동치는 주가…상한가 vs 급락', '금융 당국이 주가가 1000원 미만인 이른바 ‘동전주’에 대한 상장폐지 요건을 새롭게 신설하면서 12일 오후 관련 기업의 주가가 요동치고 있다. 일부 기업은 상한가로 직행했고, 일부는 급락하고 있다.이날 금융위원회와 한국거래소는 ‘부실 기업 신속·엄정 퇴출을 위한 상장폐지 개혁 방안’을 발표하고 7월 1일부터 ‘동전주’를 상장폐지 대상으로 한다고 밝혔다. 동전주의 경우 높은 주가 변동성 및 낮은 시가총액 등의 특성이 있고, 주가 조작의 대상으로 악용되기 쉽다고 판단했기 때문이다.권대영 금융위원회 부위원장이 12일 서울 종로구 정부서울청사에서 부실기업의 신속·엄정 퇴출을 위한 상장폐지 개혁방안 관련 브리핑을 하고 있다. /뉴스1이날 오후 2시 18분 기준 코스닥 시장에서 소프트센은 전 거래일 대비 75원(29.64%) 오른 328원에 거래되고 있다. 이날 252원으로 출발한 주가는 금융 당국의 동전주 상장폐지 요건이 발표된 이후 상승 폭을 키우며 상한가를 기록했다.보해양조, 엔투텍, 엑시온그룹, 형지I&C, 큐캐피탈 등도 급등 중이다.반면 하락 흐름을 보이고 있는 기업들도 있다. 에이프로젠은 같은 시각 전 거래일 대비 51원(8.99%) 내린 516원에 거래되고 있다. 웰킵스하이텍, 윈팩, 다이나믹디자인, 유디엠텍, 씨유메디칼 등은 하락 중이다.', NULL, '조선비즈', 'https://n.news.naver.com/mnews/article/366/0001142353', 'https://imgnews.pstatic.net/image/366/2026/02/12/0001142353_001_20260212143109720.JPG?type=w800', 'NEWS_ETC', NULL, '2026-02-12 14:29:13', 0, true, '2026-03-09 05:37:05.829974') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (386, '[서울데이터랩]금일 코스피 거래량 1위 한화생명 거래대금 1525억 돌파', '코스피 거래량 상위 종목들이 전반적으로 엇갈린 흐름을 보인다.12일 한국거래소에 따르면, 한화생명(088350)이 33,202,566주의 거래량을 기록하며 코스피 종목 중 실시간 거래량 1위를 차지한다. 현재 주가는 4,435원으로, 시가총액 대비 0.4%에 해당하는 152,589백만원의 거래대금을 보이고 있다. PER은 4.96, ROE는 6.98로, 투자 매력이 비교적 높게 평가된다. 한편, 한온시스템(018880)는 26,547,791주의 거래량과 119,084백만원의 거래대금을 기록하며 거래량 2위에 오른다. 현재 주가는 4,382원이며 시가총액 대비 거래대금은 0.27% 수준이다. PER이 -10.69, ROE가 -13.90으로, 재무 상태 개선이 시급해 보인다.삼성전자(005930)는 26,324,625주의 거래량과 4조 6,123억원의 거래대금을 기록하며 거래량 3위를 차지하고 있다. 현재가는 178,000원으로, 등락률은 +6.08%를 보인다. 이어서 오리엔트바이오(002630)는 15,886,728주의 거래량과 +29.83%의 등락률을, 보해양조(000890)는 15,626,276주의 거래량과 +16.95%의 상승률을 기록 중이다. 그 외에도 대우건설(047040) +0.27%, 대호에이엘(069460) +3.18%, SK증권(001510) +1.99%, SG세계물산(004060) -5.14%, 한화갤러리아(452260) +0.91% 등의 흐름을 보이고 있다.한편, 거래량 상위 20위권 종목들은 파미셀(005690) ▲16.95%, 카카오(035720) ▲0.85%, 다스코(058730) ▼6.48%, 에이프로젠(007460) ▼3.70%, 현대지에프홀딩스(005440) ▲15.95%, SH에너지화학(002360) ▲11.36%, 한미반도체(042700) ▲10.76%, 한화솔루션(009830) ▼2.19%, 화신(010690) ▲13.40%, 대한해운(005880) ▲4.25% 등의 성적을 기록했다.특히, 급등세를 보인 종목으로는 오리엔트바이오와 보해양조가 있다. 오리엔트바이오는 거래량 15,886,728주와 거래대금 10,865백만원을 기록하며 시가총액의 1.3%에 해당하는 자금 유입을 보였다. 보해양조는 거래량 15,626,276주, 거래대금 7,330백만원으로 시가총액의 1.1%를 차지한다. 하락세를 보인 종목으로는 한온시스템과 SG세계물산이 눈에 띈다. 한온시스템은 거래량 26,547,791주와 거래대금 119,084백만원을 기록하며 시가총액의 0.27% 수준의 자금 이동을 보였고, SG세계물산은 거래량 10,619,258주와 거래대금 4,782백만원으로 시가총액의 0.53%를 차지한다.전체적인 시장 흐름은 거래량과 거래대금이 높은 종목들이 다양한 등락률을 보이며 혼조세를 나타내고 있다. 특히, 급등 종목과 하락 종목 간의 차별화된 흐름이 두드러지는 상황이다. 투자자들은 이러한 변동성 속에서 신중한 투자 판단이 요구된다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003617514', 'https://imgnews.pstatic.net/image/081/2026/02/12/0003617514_001_20260212135216288.png?type=w800', 'NEWS_ETC', NULL, '2026-02-12 13:52:16', 0, true, '2026-03-09 05:37:05.829974') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (387, '"술 없이 차트 못 봐"…불장에 ''나홀로 신저가'' 개미 ''눈물'' [종목+]', '주류주 전날 줄줄이 신저가올 들어 코스피 27% 오를 동안주류주 주가는 대부분 ''마이너스''/사진=게티이미지뱅크"술 없이는 하이트진로 차트 못 보겠네요."(포털사이트 ''하이트진로'' 종목토론방에 개인투자자가 올린 글)코스피지수가 하루가 멀다 하고 치솟는 것과 달리 주류주(株)들은 부진을 면치 못하고 있다. 내수 주류 시장 위축이 길어지고 있어서다.4일 한국거래소에 따르면 하이트진로 주가는 전날 대비 320원(1.84%) 오른 1만7740원에 장을 끝냈다.이날은 상승했지만 주가는 올해 들어 계속 부진한 흐름이다. 앞서 전날(3일)에는 장중 1만7300원까지 밀려 52주 신저가를 쓰기도 했다. 우선주인 하이트진로2우B도 신저가를 갈아치웠다.하이트진로뿐 아니다. 전날 대다수 주류주가 신저가를 찍었다. 유가증권시장에선 보해양조와 삼화왕관이, 코스닥시장에서는 국순당과 한울앤제주, MH에탄올 등이 줄줄이 최근 1년 중 가장 낮은 주가를 기록했다.연초 이후로 시야를 넓히면 부진 흐름은 더 뚜렷하다. 코스피지수와 코스닥지수가 올 들어 이날까지 각각 27.45%, 24.2% 수직 상승한 반면, 주류주들의 주가는 고꾸라진 것으로 나타났다.한울앤제주(-13.61%)와 MH에탄올(-11.5%), 무학(-4.13%), 국순당(-3.99%), 하이트진로(-3.8%), 삼화왕관(-3.58%), 보해양조(-3.52%) 등이 하락했다. 시장 움직임을 한참 못 따라가는 현상이 이어지고 있는 것이다.주류주의 하락세는 팍팍해진 지갑 사정과 무관치 않다. 내수 경기 침체, 고물가가 이어지는 가운데 소비심리가 위축되면서 술을 사 마시는 이들도 줄어든 것이다. 식당이나 편의점 등 주요 판매 채널들이 줄면서 주류 판매량이 위축된 영향도 있다.전 세계적으로 ''음주 문화''가 확연히 바뀐 점도 주목된다. 코로나19 이후 회식 등 단체 모임이 줄어든 데다, 젊은 층 사이에서 건강을 중시하는 분위기가 번지면서 ''술 덜(안) 마시는 문화''가 자리 잡고 있다.질병관리청의 ''국민건강통계''에 따르면 우리나라 20대 음주율(최근 1년 사이 월 1회 이상 술을 마신 사람의 비율)은 2020년 64.4%에서 2024년 63%로 하락했다. 이 기간 30대의 음주율은 69.2%에서 65.3%로 감소했다.내수 주류시장 위축, 음주 문화 변화 등 복합적 배경 속에서 "답답할 때 술 생각이 나니, 경기가 움츠러들수록 주류주는 오른다"던 말도 옛말이 된 셈이다.증권가도 회의론을 내놓고 있다. 이경신 iM증권 연구원은 "대외경기 악화에 따른 주류시장 침체가 주류주들의 외형 성장을 가로막고 있다"며 "국내 유흥 중심 시장이 계속 작아지고 있고 주류 음용방식과 문화도 바뀌어서 업체로선 부담"이라고 짚었다.신흥시장 공략 등이 대안으로 꼽힌다. 박상준 키움증권 연구원은 "주류 회사들은 글로벌 매출 비중을 확대해야 하는 상황"이라며 "현실적으로 주류 업계가 올해도 매출 부진을 피하기 어려울 것인 만큼 향후 어떤 글로벌 전략을 내놓을지가 변수가 될 것"이라고 말했다.', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005246979', 'https://imgnews.pstatic.net/image/015/2026/02/04/0005246979_001_20260204220110273.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-04 22:01:10', 0, true, '2026-03-09 05:37:05.829974') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (388, '보해양조, 3억원 규모 자기주식 취득 완료', '보해양조가 주가 안정 및 주주가치 제고를 위해 진행한 자기주식 취득을 마무리했다고 29일 공시했다.보해양조는 지난해 12월 29일부터 올해 1월 28일까지 NH투자증권을 통해 보통주 72만1774주를 장내 매수했다. 총 취득 금액은 약 3억원으로, 주당 평균 취득가액은 416원이다. 이번 매입으로 보해양조가 보유한 보통주 자기주식은 기존 대비 늘어난 총 103만8687주가 됐으며, 전체 발행주식 대비 보유 비율은 0.75%로 집계됐다.회사 측은 취득 기간 내 주가 변동에 따라 실제 취득 주식 수가 예정치(71만4285주)보다 약 7000여 주 늘었으나 당초 계획한 취득 예정 금액 내에서 집행을 완료했다고 밝혔다. 이번 자기주식 취득 과정에서 최대주주인 창해에탄올의 보유 주식 수 변동은 없다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000078606', 'https://imgnews.pstatic.net/image/293/2026/01/29/0000078606_001_20260129153507563.png?type=w800', 'NEWS_ETC', NULL, '2026-01-29 15:35:07', 0, true, '2026-03-09 05:37:05.829974') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (389, '"회식? 전 운동 갈게요" 달라진 2030...김빠진 소맥문화에 주류주 ''휘청''', '하이트진로 주가 1년 사이 5%  하락글로벌 헬시플레저 트렌드 확산에…주류 소비 침체하이트진로·롯데칠성 등 해외시장·무알코올 시장 적극 공략지난해 연말 대비 주가 등락률/그래픽=윤선정국내 주류주가 휘청인다. 코로나 팬데믹 이후 20·30세대를 중심으로 헬시플레저(즐겁게 건강을 관리하는 문화) 트렌드가 확산하면서 주류 매출이 급감한 탓이다.30일 한국거래소에 따르면, 하이트진로는 지난해 연말(12월 30일 종가)부터 전날까지 주가가 5.28% 하락했다. 이 기간 코스피지수가 70% 상승한 것을 감안하면 부진이 깊다. 같은 기간 한울앤제주는 2860원에서 1340원으로 반토막 났다. 코스피 상장사 보해양조는 423원에 장을 마감하며 동전주 신세를 면치 못하고 있다. 이 기간 유일하게 롯데칠성은 주가가 11만4900원에서 13만원대로 올랐지만, 주류 외 다른 사업 부문으로 부진을 상쇄한 덕택이다.해외 주류주의 고전은 더욱 두드러진다. 조니워커, 스미노프 등을 보유한 영국 디아지오는 지난해 연말(12월 29일 종가 기준)부터 지난 24일까지 주가가 35.08% 하락했다. 같은 기간 프랑스 페르노리카(-30.49%), 미국 컨스텔레이션브랜드(-37.18%)도 비슷한 흐름을 보였다.지난 10월31일 블룸버그 통신은 전 세계 주요 50개 주류업체 시가총액이 최근 4년 동안 8300억 달러(우리돈 약 1190조 원) 감소했다고 보도했다.이처럼 국내외 주류주가 휘청이는 건 코로나 팬데믹을 기점으로 전 세계적으로 주류 소비 문화가 감소한 영향이다.국내에서는 지난해 비상계엄 여파까지 겹치면서 회식 문화가 줄어든 점도 주류 시장 침체를 가속화했다. 서울시가 운영하는 서울시상권분석서비스에 따르면 2023년 3분기부터 2025년 3분기까지 외식업체 3650곳이 줄어들었는데, 이 중 2218곳(60.8%)이 호프·간이주점인 것으로 집계됐다.하이트진로는 지난 3분기 연결기준 매출 6695억원, 영업이익 544억원으로 전년 동기 대비 각각 2.4%, 22.5% 감소했다. 같은 기간 롯데칠성음료 주류 부문 매출은 1933억 원으로 전년 동기 대비 5.3% 줄었다. 전체 매출 중 주류 비중은 19.7%를 기록하며 13년 만에 20%선 아래로 내려갔다.이에 롯데칠성음료는 지난달 창사 75년 만에 처음으로 주류 부문 희망퇴직을 시행했다. 근속 10년 이상, 1980년 이전 출생자가 대상이다. 실적 부진에 따른 비용 절감과 인력 구조 효율화의 일환이다.국내 주류업계는 돌파구로 내수 중심의 사업을 재편하고 신흥국 중심으로 해외 시장을 적극 공략하고 있다. 대표적으로 하이트진로는 베트남에 해외 첫 공장을 착공했다. 오비맥주는 지난해 제주도 지역 소주 기업 제주소주를 인수하며 해외 수출용 소주 브랜드를 새롭게 런칭했다.장지혜 DS투자증권 연구원은 "하이트진로는 내년 말 완공 예정인 베트남 공장을 통해 해외 매출이 본격적으로 개선되며, 내수 부진을 상쇄할 것으로 기대한다"고 말했다.하이트진로 관계자는 "국내 주류 시장은 갈수록 인구가 줄어들고 헬시플레저 문화가 확산하면서 폭발적인 성장이 어려울 것으로 판단한다"며 "현재 해외 시장을 공략 중이다"라고 말했다.국내 시장에서는 무알코올, 저도주 알코올 사업에 주력하고 있다.오비맥주 관계자는 "아직 매출의 대부분이 내수 시장에서 나오고 있는 만큼, 그동안 건강 문제로 주류 소비를 하지 않던 소비자와 주류 소비를 줄이려는 소비자를 위해 카스제로 등 새로운 맥주 카테고리를 신설했다"고 말했다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005298085', 'https://imgnews.pstatic.net/image/008/2025/12/30/0005298085_001_20251230060115710.jpg?type=w800', 'NEWS_ETC', NULL, '2025-12-30 06:00:00', 0, true, '2026-03-09 05:37:05.829974') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (390, '[광주소식] 보해양조, 지역 인재 40명에 장학금 전달', '보해장학회 장학금 전달식[보해양조 제공. 재판매 및 DB 금지](광주=연합뉴스) 주류 전문기업 보해양조와 재단법인 보해장학회는 지역 청소년 40명에게 장학금 4천200만원을 전달했다고 23일 밝혔다.장학생들은 전남도교육청, 전남도장애인체육회 등 7개 기관의 추천을 받아 선발됐다박철수 보해장학회 이사장은 "설립자 고(故) 임광행 회장이 강조했던 인재 육성의 뜻이 44년째 이어지고 있다"며 "고물가와 취업난 속에서도 학생들이 용기를 잃지 않고 지역사회의 빛나는 리더로 성장해주길 바란다"고 말했다.', NULL, '연합뉴스', 'https://n.news.naver.com/mnews/article/001/0015811438', 'https://imgnews.pstatic.net/image/001/2025/12/23/AKR20251223127200054_01_i_P4_20251223161231343.jpg?type=w800', 'NEWS_ETC', NULL, '2025-12-23 16:11:44', 0, true, '2026-03-09 05:37:05.829974') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (579, '로봇으로 좀 질주하나 싶더니…코스피 급락에 자동차주 후진', '[특징주]머니투데이 특징주 그래픽 이미지코스피가 급락으로 출발한 가운데 최근 주가가 상승세를 보였던 자동차 관련주가 일제히 낙폭을 키운다.4일 오전 9시10분 현재 거래소에서 현대차우는 전 거래일 대비 2만8000원(9.93%) 하락한 25만4000원에 거래 중이다. 기아와 현대차가 8%대 약세를 보이고 KG모빌리티와 KG에코솔루션, KG케미칼 등은 6%대 하락 중이다.지난해 관세 여파로 주가가 부진했던 자동차주는 올해 피지컬AI(인공지능) 모멘텀으로 주가가 가파른 상승세를 보였다. 이란 사태가 터지며 국내 증시 전반에서 투매가 나타나고 있는 가운데 자동차주 역시 매도세가 강하게 나타나고 있다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005324944', 'https://imgnews.pstatic.net/image/008/2026/03/04/0005324944_001_20260304092511618.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-03-04 09:17:53', 0, true, '2026-03-09 05:44:54.377094') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (391, '희토류 관련株, 중국의 대일 희토류 수출허가 심사 강화에 동반 강세[특징주]', '[이데일리 신하연 기자] 중국이 일본 희토류 수출 허가 심사를 강화하면서 국내 희토류 관련주들이 강세를 보이고 있다.19일 엠피닥터에 따르면 이날 오전 9시21분 현재 노바텍(285490)은 전거래일 대비 20.13% 오른 2만7150원에 거래 중이다.같은 시각 유니온(000910)머터리얼(4.87%), LS에코에너지(229640)(3.75%), 유니온(000910)(3.60%), 그린리소스(402490)(3.58%), 티플랙스(081150)(2.36%) 등 희토류 관련주로 묶이는 종목들이 반사 수혜 기대감으로 동반 강세를 보이고 있다.중국이 일본 희토류 수출 허가 심사를 강화하면서 최종 사용자 등에 대한 정보를 담은 추가 서류를 요구하고 있다는 보도가 나오면서 투자심리에 영향을 미친 것으로 풀이된다.지난 17일 일본 교도통신은 무역업계 소식통을 인용해 중국 당국이 일본에 희토류를 수출하는 업체에 구매 기업, 제조하는 최종 제품, 운송 경로, 제품의 미국 등 제3국 수출 여부 등을 포함해 정확한 정보 제출을 요구하고 있다고 전했다. 중국은 희토류 등 전략 광물 수출에 대해 허가제를 운용 중이다.이 조처로 전기차와 반도체 등 첨단 제품에 사용되는 희토류 등 핵심 광물의 선적이 지연될 수 있다는 우려가 나오는 상황이다.앞서 지난해 11월 초 다카이치 사나에 총리의 ‘대만 유사시 자위권 행사 가능’ 발언 뒤 경제적 압박을 가하던 중국은 이달 들어 일본에 대한 희토류 수출 통제를 강화하고 있다. 중국 상무부는 지난 6일 군사용으로 사용하거나 사용할 가능성이 있는 이중용도(민간·군사 양용) 물자의 일본 수출을 금지했다. 희토류와 희토류 영구자석 등은 중국이 정한 이중용도 물자 목록에 포함되어 있다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006202892', 'https://imgnews.pstatic.net/image/018/2026/01/19/0006202892_001_20260119092907388.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-19 09:29:07', 0, true, '2026-03-09 05:37:29.500005') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (392, '[서울데이터랩]금일 코스피 거래량 1위 삼성전자 거래대금 무려 3조 6,284억원 돌파', '코스피 거래량 상위 종목들이 전반적으로 엇갈린 흐름을 보인다.8일 한국거래소에 따르면, 삼성전자(005930)가 25,659,313주의 거래량을 기록하며 코스피 종목 중 실시간 거래량 1위를 차지했다. 현재 주가는 140,900원이며, 거래대금은 3조 6,284억원에 달한다. 이는 시가총액 8조 3,407억원의 약 43.5%에 해당하는 금액으로, 거래대금이 대규모로 유입된 상황이다. PER은 29.26, ROE는 9.03으로 안정적인 재무 상태를 유지하고 있다. 이어 유니온머티리얼(047400)은 18,295,928주의 거래량과 35,320백만원의 거래대금을 기록하며 거래량 2위에 올랐다. 현재가는 1,834원으로, 시가총액 대비 거래대금 비율은 4.59%로 집중적인 매수세가 이어지고 있다. PER은 -1.92, ROE는 -117.43으로 재무 상태는 불안정한 편이다.형지엘리트(093240)는 14,581,167주의 거래량과 26,642백만원의 거래대금을 기록하며 3위에 올랐다. 현재가는 1,787원이며, 등락률은 +2.06%로 상승세를 보이고 있다. 한온시스템(018880)은 11,865,223주가 거래되며 -1.55%의 하락세를 기록하고 있다. 계양전기(012200)는 8,700,279주의 거래량과 82,269백만원의 거래대금을 기록하며 +14.79%의 급등세를 보이고 있다. 삼성중공업(010140)은 6,354,787주가 거래되며 +3.94%의 상승세를 기록하고 있다. 한화오션(042660)은 4,373,386주가 거래되며 +6.60%로 상승하고 있으며, 한미반도체(042700)는 4,118,319주가 거래되며 +0.64%의 소폭 상승을 기록하고 있다. 인스코비(006490)는 3,995,500주가 거래되며 +4.67%의 상승세를 보이고 있고, SK하이닉스(000660)는 3,924,855주가 거래되며 +3.91%로 강세를 보이고 있다.한편 거래량 상위 20위권 종목들은 아남전자(008700) ▲2.79%, 삼성전자우(005935) ▼0.48%, 금호전기(001210) ▼5.56%, 두산에너빌리티(034020) 보합, 한화갤러리아(452260) ▼2.19%, 디아이(003160) ▲8.87%, 대창(012800) ▼5.21%, 미래에셋증권(006800) ▼1.07%, 유니온(000910) ▼10.06%, 남선알미늄(008350) ▼2.76% 등의 성적을 기록했다.계양전기는 +14.79%의 급등세를 보이며 주목받고 있다. 거래대금은 82,269백만원으로 시가총액 대비 31.14%에 이르며, 이는 시장에서 큰 관심을 받고 있음을 의미한다. 반면, 유니온은 -10.06%의 하락률을 기록하며 주가가 크게 떨어졌다. 거래대금은 10,983백만원으로, 시가총액 대비 15.58%로 매도세가 강하게 작용하고 있다.전체적으로 시장은 특정 종목들에 대한 집중적인 매수·매도세가 관찰된다. 특히 거래량 상위 종목들은 대체로 상승세를 유지하고 있으며, 일부 종목에서는 급등 및 급락이 동시에 나타나는 등 변동성이 크다. 투자자들은 이러한 시장 흐름에 주목하며 신중한 투자 전략을 고민해야 할 것으로 보인다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003607256', 'https://imgnews.pstatic.net/image/081/2026/01/08/0003607256_001_20260108140915229.png?type=w800', 'NEWS_ETC', NULL, '2026-01-08 14:09:15', 0, true, '2026-03-09 05:37:29.500005') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (393, '[특징주 & 리포트] ''유니온머티 上…희토류株 급등'' 등', '● 유니온머티 上…희토류株 급등국내 희토류 관련주가 7일 급등했다. 중국 정부가 일본을 겨냥해 희토류 수출 통제 조치에 나서면서다. 희토류 관련 테마주로 분류되는 유니온머티리얼은 29.99% 오른 1747원에 마감했다. 이 회사는 희토류 대체 소재로 알려진 ‘페라이트 마그넷’ 등을 생산한다. 모회사인 유니온(19.95%)과 EG(10.75%), 삼화전자(9.36%), 대원화성(5.72%), 쎄노텍(5.90%), 동국알앤에스(4.24%) 등 다른 희토류 테마주도 상승했다.● ‘불닭’ 삼양식품, 8% 넘게 하락‘불닭’ 브랜드로 유명한 삼양식품이 크게 떨어졌다. 전날 대비 8.24% 밀린 115만8000원에 거래를 마쳤다. 외국계 증권사 창구에서 매물이 쏟아졌다. 박성호 LS증권 연구원은 “작년 4분기 매출과 영업이익이 각각 6405억원, 1364억원으로 전년 동기 대비 33.8%와 21.3% 증가하겠지만 영업이익 컨센서스(증권가 추정치 평균)는 8% 이상 밑돌 것”이라고 예상했다. 다만 목표주가 175만원은 유지했다.● 대신證, 크래프톤 목표가 낮춰대신증권은 크래프톤의 목표주가를 기존 41만원에서 37만원으로 낮췄다. 작년 4분기 실적이 기대를 밑돌았을 것으로 봤다. 이지은 연구원은 “PC 매출이 직전 분기 대비 67%, 모바일 매출이 22% 각각 감소했을 것”으로 추정했다. 다만 올해 1분기는 전통 성수기이기 때문에 실적이 개선될 것으로 예상했다. 주가는 6.45% 밀린 23만2000원에 마감했다.', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005234140', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2026-01-07 17:25:12', 0, true, '2026-03-09 05:37:29.500005') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (394, '[서울데이터랩]‘계양전기우’ 30.00% 상한가…금일 증시 상승률 1위로 마감', '7일 오후 3시 35분 계양전기우(012205)가 등락률 +30.00%로 상승률 1위로 마감했다. 계양전기우는 장 중 394,133주가 거래되었으며 주가는 공모가 대비 3,000원 오른 13,000원에 마감했다.계양전기우의 PER은 -6.27로, 이는 주가가 내재가치보다 높게 평가됐을 가능성을 시사한다.이어 상승률 2위 유니온머티리얼(047400)은 주가가 29.99% 폭등하며 종가 1,747원에 마감했다. 상승률 3위 현대오토에버(307950)의 주가는 394,500원으로 26.44% 폭등하며 강세를 보였다. 상승률 4위 유니온(000910)은 19.95% 급등하며 5,020원에 마감했다. 상승률 5위 현대글로비스(086280)는 16.78%의 급등세를 기록하며 218,500원에 마감했다.6위 현대차(005380)는 350,500원으로 13.80% 급등 마감했다. 7위 일동제약(249420)은 종가 43,500원으로 10.83% 상승 마감했다. 8위 HJ중공업(097230)은 종가 24,300원으로 10.20% 상승 마감했다. 9위 신세계(004170)는 262,000원으로 9.62% 상승 마감했다. 10위 한올바이오파마(009420)는 50,700원으로 9.39% 상승 마감했다.이밖에도 삼화전자(011230) ▲9.36%, 태영건설우(009415) ▲9.32%, 한국화장품(123690) ▲8.35%, 일동홀딩스(000230) ▲8.13% 등을 기록하며 금일 증시를 상승으로 마감했다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003607018', 'https://imgnews.pstatic.net/image/081/2026/01/07/0003607018_001_20260107170422970.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-07 17:04:22', 0, true, '2026-03-09 05:37:29.500005') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (395, '[서울데이터랩]1월 7일 코스피 주요 종목 마감시황', '1월 7일 한국거래소에 따르면, 계양전기우(012205)는 전 거래일 대비 30.00% 상승한 13,000원에 거래를 마감하며 금일 코스피 상승률 1위를 차지했다. 유니온머티리얼(047400)은 29.99% 상승한 1,747원에 거래를 마치며 뒤를 이었다. 현대오토에버(307950)는 26.44% 상승한 394,500원에 장을 마감했다. 유니온(000910)은 19.95% 상승한 5,020원을 기록했으며, 현대글로비스(086280)는 16.78% 상승한 218,500원에 거래를 종료했다.IHQ는 전 거래일 대비 36.06% 하락한 422원에 거래를 마치며 코스피 하락률 1위를 기록했다. KH 필룩스는 16.19% 하락한 321원을 기록했다. 엠앤씨솔루션은 11.53% 하락한 148,900원에 장을 마감했으며, 형지엘리트는 9.60% 하락한 1,751원, NHN은 8.48% 하락한 31,850원을 기록했다.시가총액 상위 종목 중 삼성전자는 44,861,495주의 거래량을 바탕으로 1.51% 상승했다. SK하이닉스는 5,673,014주의 거래량을 기록하며 2.20% 상승했다. 삼성바이오로직스는 61,546주의 거래량을 바탕으로 2.67% 상승했다. 현대차는 7,764,177주의 거래량을 기록하며 13.80% 상승했다. HD현대중공업은 261,596주가 거래되며 1.27% 상승했다. 삼성전자우는 6,029,786주의 거래량과 함께 0.78% 상승했다.금일 코스피 주요 종목들은 상승세와 하락세가 혼재된 모습을 보였다. 특히 시가총액 상위 종목들 중에서는 상승세를 보인 종목들이 다수였다. 투자자들은 이러한 시장의 변동성을 주의 깊게 살펴보고, 장기적인 투자 계획을 세우는 것이 필요하다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003607017', 'https://imgnews.pstatic.net/image/081/2026/01/07/0003607017_001_20260107170420449.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-07 17:04:20', 0, true, '2026-03-09 05:37:29.500005') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (580, 'KG에코솔루션, 바이오선박유 앞세워 2030년 매출 7000억 목표', '발전용에서 선박용으로…사업 축 전환 가속울산 신공장 가동 임박, 고부가 연료 시장 정조준퍼스트 무버 전략으로 수익성·해외 매출 동시 확대올해 매출 목표 1800억…항공유 시장까지 공략KG에코솔루션이 바이오 연료 사업 확대를 발판으로 친환경 에너지 기업으로의 도약을 선언했다.발전용 바이오중유 중심의 내수 사업 구조에서 벗어나 고부가가치 ''바이오 선박유''를 앞세워 수익성과 해외 매출을 동시에 키우고, 오는 2030년 매출 7000억원 규모로 성장하겠다는 중장기 목표를 제시했다.박생근 KG에코솔루션 대표가 지난 25일 서울 중구 세종문화회관에서 개최된 신년 기자간담회에서 인사말을 하고 있다. [사진=이한얼 기자]박생근 KG에코솔루션 대표는 지난 25일 서울 중구 세종문화회관에서 개최된 신년 기자간담회에서 "울산 신공장 가동을 기점으로 선박용 연료 시장을 선점해 올해를 도약의 원년으로 만들겠다"며 "글로벌 환경 규제 강화 흐름 속에서 바이오 연료 수요는 구조적으로 확대될 것"이라고 밝혔다.회사는 1999년 설립, 2013년 상장했으며 모회사인 KG케미칼을 중심으로 한 계열 체제 아래 안정적인 지배구조를 갖췄다. 연간 기준으로는 약 1000억원 수준의 매출을 기록 중이고 영업이익률은 약 10%를 유지하고 있다.주력 제품인 바이오중유는 기존 벙커C유를 바이오 원료로 대체한 연료다. 황산화물은 사실상 전량 저감이 가능하고 온실가스와 질소산화물, 미세먼지도 크게 줄일 수 있다. 기존 발전 설비와 호환돼 추가 설비 투자 없이 사용할 수 있다는 점이 강점이다. KG에코솔루션은 현재 발전소 연료 시장에서 점유율 약 20%로 업계 선두권을 차지하고 있다.성장의 핵심 축은 다음 달 가동 예정인 울산 공장이다. 고온 공정을 적용해 불순물을 최소화한 바이오 선박유를 생산하는 전용 설비로, 품질 기준이 높은 선박 연료 시장을 겨냥했다. 박 대표는 "아직 경쟁 제품이 많지 않은 초기 시장인 만큼 퍼스트 무버로서 가격 협상력을 확보할 수 있다"고 기대했다.판매 확대를 위해 국내외 메이저 정유사 등과 품질 테스트 및 사전 마케팅을 진행하고 있으며 상반기 내 실질적인 거래가 성사될 가능성도 언급됐다.박 대표는 올해 매출 목표를 1875억원으로 제시했다. 기존 발전용 연료 중심 구조에서 벗어나 선박유 매출이 본격 반영되면 수익성이 크게 개선될 것으로 보고 있다. 발전소 입찰 방식으로 단가가 제한됐던 기존 사업과 달리, 선박유는 고객과 직접 가격을 협상하는 구조라 마진 확보가 수월하다는 설명이다.중장기적으로는 오는 2028년 매출 3000억원, 2030년 7000억원 달성을 목표로 제시했다. 이 과정에서 수출 비중이 빠르게 늘어 내년 또는 내후년에는 해외 매출이 국내를 넘어설 것으로 전망했다.박 대표는 "조직 개편과 연구개발 강화를 통해 제품 포트폴리오를 다변화하고, 향후에는 재생 항공유 원료 시장까지 진출해 글로벌 친환경 연료 기업으로 자리매김하겠다"고 말했다.', NULL, '아이뉴스24', 'https://n.news.naver.com/mnews/article/031/0001008540', 'https://imgnews.pstatic.net/image/031/2026/02/26/0001008540_001_20260226100109367.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-02-26 10:01:09', 0, true, '2026-03-09 05:44:54.377094') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (889, '또 터진 제약사 리베이트…혁신형 제약기업에 ''악재'' 될까', '의약품 처방을 늘리기 위해 병·의원에 현금·상품권 등 부당 이익을 제공한 제약사들이 공정거래위원회에 적발됐다. 보건복지부가 제네릭(복제약) 가격 인하를 골자로 한 약가제도 개선방안(약가 개편안)을 추진하는 가운데 ''우대 조건''인 혁신형 제약기업 인증기준에 어떤 파장을 미칠지 관심이 집중된다.━또 다시 터진 ''제약사 리베이트''━공정위는 19일 의료기관을 대상으로 불법 리베이트를 제공한 혐의로 동성제약에 시정명령(향후금지명령)을, 국제약품은 시정명령과 과징금 300만원을 부과했다고 전날 밝혔다. 동성제약은 현재 회생절차가 진행 중인 점을 감안해 과징금은 면제하고 시정명령만 부과했다공정위에 따르면 동성제약은 자사 의약품을 처방하는 대가로 2010~2019년 수도권 4개 병·의원에 현금 등 2억5000만원 상당의 리베이트를 제공한 것으로 드러났다. 초기에는 계열사인 동성바이오팜을 통해 리베이트를 제공했다가, 책임 위험을 회피하기 위해 2014년부터는 영업대행업체(CSO)에게 전문의약품 영업을 전면 위탁하며 불법 리베이트를 자행한 것으로 확인됐다.국제약품의 경우 2015~2019년 광주시 소재 병원에 송년회 경품으로 상품권과 가전제품을 지원하는 등 7차례에 걸쳐 1300만원의 리베이트를 제공한 혐의를 받는다. 리베이트에 필요한 자금은 영업사원에게 처방 실적에 따른 활동비를 지급하거나, 법인카드를 이용해 허위 결제한 후 현금을 돌려받는 속칭 ''법인카드 깡''으로 조성한 것으로 확인됐다.━업계, 혁신형 제약기업 ''인증 기준'' 촉각━업계는 잊을만하면 터지는 불법 리베이트 소식에 씁쓸해하면서도, 복지부가 추진 중인 혁신형 제약기업의 기준 수립에 미칠 영향을 예의주시하는 분위기다. 제약사로서는 약가 개편안 시행 결정에 따라 혁신형 제약기업 포함 여부가 이전보다 훨씬 중요해졌는데, 인증 시 리베이트 처분 수위가 큰 영향을 미치기 때문이다. 일각에서는 "10년도 더 지난 리베이트가 적발된 것은 이유가 있다"는 이야기가 들린다.약가 개편안은 올 하반기부터 2012년 일괄 약가 인하 이후 지금까지 가격 조정이 없었던 복제약 가격을 현행 오리지널 약(원조약) 대비 53.55%에서 40%대로 낮추는 게 핵심이다. 여유 재원은 연구개발(R&D)에 투자하는 혁신형 제약기업에 돌려 신약 개발을 촉진한다는 게 정부 구상인데, 구체적으로 혁신형 제약기업에는 최소 3년간 R&D 비중에 따라 60%(하위 70%), 68%(상위 30%)의 가산율을 책정해 안정적인 수익을 보장할 방침이다.관건은 혁신형 제약기업의 인증 기준, 특히 리베이트 처분 수위다. 현재는 △2회 이상 리베이트 등으로 행정처분을 받거나 △리베이트 총액이 500만원 이상이면 제약산업육성·지원위원회를 열어 인증을 취소할 수 있다. 실제 이렇게 취소된 대형 제약사도 존재한다. 다만, 제약업계는 "리베이트가 잘못한 건 맞지만 오래 전 발생한 일이 최근 행정처분 됐다고 ''원 스트라이크 아웃''으로 처벌하는 것은 지나치다"고 주장해왔다. 5년 이내 리베이트가 적발됐거나, 개인 일탈이 아닌 제약사가 조직적으로 가담한 경우만 인증 취소를 하는 것이 합리적이란 것이다.복지부는 지난해 제도 개선에 착수한 후 1년 가까이 장고를 이어가고 있지만 아직도 결론을 내리지 못한 상태다. 그러는 사이 최근 약가 개편안과 맞물려 혁신형 제약기업의 새로운 인증 기준은 제약업계는 물론 이들에게 고용된 노동계에서도 주목받는 사안으로 부상했다.업계 한 관계자는 "약가 개편안보다 혁신형 제약기업 인증기준이 먼저 나와야 제약사는 불확실성을 해소하는 동시에 3년 이상의 장기 계획을 수립하는 등 대처할 수가 있다"며 빠른 의사 결정을 주문했다. 또 다른 업계 관계자는 "혁신형 제약기업 요건이 강화될수록 건강보험 투입 재정이 줄어들고 반대로 완화되면 우대 기업이 늘어나 재정 축소 효과가 낮아진다"며 "인증기준이 완화·강화되는지가 ''혁신 추진''과 ''재정 안정화'' 사이에서 정부 정책 방향을 알려줄 가늠자가 될 것"이라 분석했다.혁신형 제약기업 목록/그래픽=김지영', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005319659', 'https://imgnews.pstatic.net/image/008/2026/02/19/0005319659_001_20260220042017545.jpg?type=w800', 'NEWS_CHEM', NULL, '2026-02-19 16:05:48', 0, true, '2026-03-09 06:11:39.620947') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (396, '[특징주] 중국, 희토류 일본 수출 통제 가능성에 관련주 ''불기둥''(종합)', '[연합뉴스TV 제공](서울=연합뉴스) 이민영 기자 = 중국 정부가 일본을 겨냥한 희토류 수출 통제 조치를 검토 중인 것으로 알려지면서 7일 국내 희토류 관련주가 일제히 급등했다.이날 희토류 관련 테마주로 분류되는 유니온머티리얼은 전장 대비 29.99% 올라 상한가인 1천747원에 거래를 마쳤다.유니온도 19.95% 급등했으며 EG(10.75%), 동국알앤에스(4.24%), 성안머티리얼스(2.29%) 등 다른 희토류 테마주도 줄줄이 올랐다.중국 정부가 다카이치 사나에 일본 총리의 ''대만 유사시 개입'' 시사 발언을 문제 삼아 일본에 군사 목적의 이중용도 물자(민간용으로도 군용으로도 활용 가능한 물자) 수출을 금지하는 보복 조치를 단행한 점이 매수세를 자극한 것으로 보인다.중국 상무부는 전날 "일본 군사 사용자와 군사 용도 및 일본 군사력 제고에 도움이 되는 기타 최종 사용자 용도의 모든 이중용도 물자 수출을 금지한다"고 발표했다.이날에는 중국 정부가 일본을 상대로 일부 희토류 관련 품목의 수출 허가 심사를 강화하는 방안을 검토하고 있다는 소식이 전해졌다.중일 갈등이 격화하는 가운데 국내 기업이 반사 이익을 얻을 수 있을 것이라는 기대감이 번지면서 주가를 밀어올린 모습이다.mylux@yna.co.kr', NULL, '연합뉴스', 'https://n.news.naver.com/mnews/article/001/0015834960', 'https://imgnews.pstatic.net/image/001/2026/01/07/PCM20230406000036990_P4_20260107162418296.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-07 16:23:34', 0, true, '2026-03-09 05:37:29.500005') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (397, '[서울데이터랩]금일 코스피 거래량 1위 금호전기 거래대금 255억 돌파', '코스피 거래량 상위 종목들이 전반적으로 엇갈린 흐름을 보인다.7일 한국거래소에 따르면, 금호전기(001210)가 3,088만9,289주 거래되며 코스피 종목 중 실시간 거래량 1위를 차지한다. 현재 주가는 746원이며, 거래대금은 25,501백만원으로 시가총액 대비 5,556%에 달한다. 등락률은 4.78% 상승하며, 강력한 매수세가 이어지고 있다. PER -4.44, ROE -56.56으로, 재무 지표는 부진한 모습을 보이나, 투기적 매수세가 주요 원인으로 보인다. 남선알미늄(008350)은 2,590만8,584주 거래되며 거래량 2위를 기록하고, 현재 주가는 1,267원으로 1.77% 상승한다. 거래대금은 34,472백만원으로 시가총액 대비 2,108%에 이르며, PER -5.15, ROE -8.90으로 실적 개선이 필요한 상황이다.삼성전자(005930)는 2,546만6,965주 거래되며 거래량 3위를 기록하고 있다. 현재 주가는 142,500원으로 2.59% 상승 중이다. 대창(012800)은 현재가 1,424원으로 2.86% 하락하며, 1,680만8,858주 거래되고 있다. 성안머티리얼스(011300)는 1.43% 상승해 355원에 거래 중이며, 거래량은 1,546만4,287주이다. 유니온(000910)은 4,820원으로 15.17% 급등하며 1,249만9,176주가 거래되고 있다. 유니온머티리얼(047400)스는 28.50% 폭등하여 1,727원에 거래 중이며, 거래량은 891만4,912주이다. 인스코비(006490)는 7.35% 상승해 745원에 거래되며, 802만0,753주가 거래되고 있다. 형지엘리트(093240)는 1,749원으로 9.71% 하락 중이며, 거래량은 717만0,344주이다. 경인양행(012610)은 6.77% 상승하여 4,970원에 거래되며, 703만7,530주가 거래되고 있다.한편 거래량 상위 20위권 종목들은 삼성중공업(010140) ▲2.62%, 미래에셋증권(006800) ▼2.26%, 현대차(005380) ▲16.56%, 아남전자(008700) ▲2.21%, 두산에너빌리티(034020) ▼0.35%, 카카오(035720) ▼6.90%, 디아이씨(092200) ▲6.40%, 삼화전자(011230) ▲6.54%, 삼성전자우(005935) ▲1.17%, SK하이닉스(000660) ▲4.61% 등의 성적을 기록했다.주목할 만한 종목으로는 유니온머티리얼스와 현대차가 있다. 유니온머티리얼스는 거래대금이 시가총액의 2,113%에 달하며 28.50%의 폭등세를 보이고 있다. 현대차는 시가총액 대비 231%의 거래대금을 기록하며 16.56% 상승해 주목받고 있다. 반면, 형지엘리트와 카카오는 각각 9.71%, 6.90% 하락하며 부진한 모습을 보이고 있다. 전체적으로 시장은 상승세와 하락세가 혼재하는 가운데, 투자자들의 신중한 판단이 요구된다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003606914', 'https://imgnews.pstatic.net/image/081/2026/01/07/0003606914_001_20260107133415120.png?type=w800', 'NEWS_ETC', NULL, '2026-01-07 13:34:15', 0, true, '2026-03-09 05:37:29.500005') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (398, '[서울데이터랩]유니온 29.99% 상한가…실시간 상승률 1위', '7일 오전 9시 10분 유니온(000910)(003840)이 등락률 +29.99%로 상한가를 기록하며 상승률 1위를 차지했다. 유니온은 개장 직후 5분간 165만 2528주가 거래되었으며 주가는 공모가 대비 1255원 오른 5440원이다.한편 유니온의 PER은 -6.04로 나타나며 이는 시장에서의 평가가 부정적일 수 있음을 암시하고, ROE는 -39.45%로 수익성이 낮음을 보여준다.이어 상승률 2위 유니온머티리얼(047400)은 현재가 1747원으로 주가가 29.99% 상승하고 있다. 상승률 3위 경인양행(012610)은 현재 5650원으로 21.37% 폭등 중이다. 상승률 4위 성안머티리얼스(011300)는 15.43% 급등하며 404원에 거래되고 있다. 상승률 5위 금호전기(001210)는 15.03%의 상승세를 타고 819원에 거래되고 있다.6위 삼화전자(011230)는 현재가 3230원으로 14.13% 상승 중이다. 7위 삼화전기(009470)는 현재가 3만 4550원으로 10.56% 상승 중이다. 8위 인스코비(006490)는 현재가 760원으로 9.51% 상승 중이다. 9위 신세계(004170)는 현재가 25만 7500원으로 7.74% 상승 중이다. 10위 KCTC(009070)는 현재가 6510원으로 6.20% 상승 중이다.이밖에도 한미반도체(042700) ▲6.04%, 씨아이테크(004920) ▲5.94%, 현대오토에버(307950) ▲5.61%, 인바이오젠(101140) ▲5.22%, 현대차(005380) ▲5.19%, LG디스플레이(034220) ▲5.04%, SK하이닉스(000660) ▲4.55%, 유화증권우(003465) ▲4.45%, 삼성물산(028260) ▲4.42%, 코리아써키트(007810) ▲4.12% 등을 기록하며 시장에서 활발히 거래되고 있다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003606890', 'https://imgnews.pstatic.net/image/081/2026/01/07/0003606890_001_20260107112220143.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-07 11:22:20', 0, true, '2026-03-09 05:37:29.500005') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (399, '[이 시각 시황] 中, 對일본 ''희토류 보복 카드'' 꺼내 들어', '■ 머니쇼 ''이 시각 시황'' - 장연재이 시각 시황입니다.오늘(7일)도 반도체가 지수 주도하는 장세가 펼치고 있습니다.반도체 투톱이 강세를 보이면서 코스피 상승하지만 코스닥은 약합니다.코스피가 1.5% 상승하면서 현재 4,591포인트 기록하고 있습니다.코스닥은 0.15% 약세로 954포인트에서 움직임 전개됩니다.수급상황 보시죠.유가증권 시장 매매 동향입니다.외국인 5,213억 원 순매수 기록 중입니다.기관은 855억 원, 개인이 4,246억 원 팔아 냅니다.코스닥 시장입니다.외국인 1,217억 원, 기관이 174억 원 매도 우위 기록 중입니다.개인이 1,400억 원 가까운 사자 포지션 취하고 있습니다.등락률 상하위 업종입니다.오늘은 반도체와 반도체 장비, 비철금속, 디스플레이패널 업종이 상승률 상위권에 위치해 있습니다.반면, 카드, 손해보험, 은행 업종이 하락폭이 큰 것으로 집계됩니다.시장을 주도하는 테마, 종목별 시세 체크하시죠.중일 갈등 반사이익을 볼 수 있는 테마들이 어제(6일) 시간 외 거래에 이어서 주목받고 있습니다.중국은 일본에 대한 ‘희토류’ 수출금지 카드를 꺼내 들었습니다.중국 상무부는 희토류 수출을 금지한다고 발표하면서, 다카이치 사나에 일본 총리를 겨냥했는데요.관련주 내에서는 유니온머티리얼이 상한가로 1,747원입니다.유니온이 21.6% 시세 분출하면서 5,090원에 거래되고 있습니다.성안머티리얼스가 8% 강세, 동국알앤에스가 10.7% 오르면서 거래가 2,480원 기록합니다.EG가 12.4% 오름세로 현재 5,960원에 거래가 집계됩니다.희토류 관련주가 상승합니다.중국이 희토류 수출을 금지하면서 일본은 반도체 포토레지스트 무기를 꺼내들 수 있다는 분석이 나옵니다.이에 일본 기업을 대체할 수 있는 국내 소부장 기업들이 부각되고 있습니다.관련주 내에서는 경인양행이 13.8% 오름세로 5,300원입니다.동진쎄미켐이 3.3% 상승하면서 42,450원에 거래됩니다.켄트로스가 2% 오름세입니다.솔브레인이 5% 상승하면서 거래가 293,500원입니다.삼양엔씨켐이 3% 가까이 상승하면서 26,250원에 거래됩니다.한편 간밤 뉴욕증시에서 반도체 섹터가 강했던 흐름을 이어받으며 오늘도 반도체 섹터가 지수 상승을 주도하고 있습니다.컴퓨트익스프레스링크, CXL 관련주 상승 합니다.네오셈 2.7% 강세로 거래가 12,490원입니다.SK하이닉스가 2.6% 강세로 현재 거래가 745,000원입니다.오킨스전자가 하락 전한된 상태입니다.코리아써키트가 0.65% 오름세로 46,400원입니다.삼성전자가 2.2% 오르면서 142,000원에 거래됩니다.반도체 소부장 쪽도 일제히 상승하고 있습니다.한양디지텍이 12.8% 오르면서 26,300원입니다.하나머티리얼즈가 6.1% 강세로 거래가 52,100원입니다.티씨케이가 3% 넘게 올라가면서 166,700원입니다.에스에이엠티가 2.3%, 동진쎄미켐이 3.5% 강세 보여주고 있습니다.코스피 또 한 번 사상 최고치입니다.반도체가 또 한 번 시장을 끌어올리고 있는데, 장중에 4600선 유지할 수 있을지 지켜보시죠.지금까지 시장 상황 전해드렸습니다.당신의 제보가 뉴스로 만들어집니다.SBS Biz는 여러분의 제보를 기다리고 있습니다.홈페이지 = https://url.kr/9pghjn', NULL, 'SBS Biz', 'https://n.news.naver.com/mnews/article/374/0000484772', 'https://imgnews.pstatic.net/image/374/2026/01/07/0000484772_001_20260107095217512.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-07 09:52:17', 0, true, '2026-03-09 05:37:29.500005') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (400, '[특징주]''中 대일 수출 금지''에 韓 희토류 관련주 급등', '유니온머티리얼 ''上'' 직행희토류 관련주가 7일 장 초반 동반 강세를 보인다. 유니온머티리얼은 개장과 동시에 상한가로 직행했다.이날 오전 9시 31분 기준 유가증권시장에서 유니온머티리얼 주식은 전 거래일 대비 29.99% 오른 1747원에 거래되고 있다. 유니온머티리얼은 희토류 대체 소재로 알려진 ''페라이트 마그넷'' 등을 생산한다.유니온머티리얼의 모회사 유니온도 전 거래일보다 21.39% 뛴 5080원에 거래되고 있다. 이 밖에 삼화전자(14.49%) 성안머티리얼스(8.00%) 등도 오른다.같은 시각 코스닥 시장에서도 EG(15.28%) 동국알앤에스(9.82%) 쎄노텍(5.54%) 티플랙스(4.90%) 등이 급등하고 있다.중국이 일본에 희토류 통제 카드를 꺼내 들면서 국내 희토류 관련 기업들에 대한 반사이익 기대감이 커진 영향으로 보인다. 중국 상무부는 지난 6일 "일본 군사 사용자와 군사 용도 및 일본 군사력 제고에 도움이 되는 기타 최종 사용자 용도의 모든 이중용도 물자 수출을 금지한다"고 발표했다.', NULL, '아시아경제', 'https://n.news.naver.com/mnews/article/277/0005703213', 'https://imgnews.pstatic.net/image/277/2026/01/07/0005703213_001_20260107094125718.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-07 09:39:54', 0, true, '2026-03-09 05:37:29.500005') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (401, '건설경기 악화 장기화…광주 주택 재개발 ''답보''', '신가 재개발조합장 해임·시공사 협상으로 분양시점 연내→내년 전망광천조합-현대건설 공사비 협상 막바지·누문구역 철거율 10%대광주 신가동 재개발 사업지 내 신가도서관[연합뉴스 자료사진](광주=연합뉴스) 장아름 김혜인 기자 = 지방 건설경기 악화가 장기화하면서 광주의 주요 재개발·재건축 사업이 답보 상태를 보이고 있다.앞서 민간공원 특례사업으로 공급이 집중돼 미분양 물량이 적지 않은 데다가 공사비 상승으로 시공사와의 협상에 난항을 겪는 곳도 있는 것으로 나타났다.1일 광주시와 5개 자치구에 따르면 현재 광주에서 진행 중인 재개발 사업지는 17곳, 재건축 사업지는 4곳이다.이 중 신가동·광천동·운암주공 3단지·누문동 구역이 3천세대 이상 대규모 재개발로 꼽히는데 운암주공 3단지를 제외하고는 착공 및 분양 계획이 미정인 상황이다.4천700여가구가 들어설 신가동 재개발 사업은 애초 올해 분양을 목표로 했으나 조합장 해임과 새 집행부 구성, 시공사와 협상 재개 등이 맞물려 분양 시기가 내년 이후로 미뤄질 전망이다.조합원들은 지난 6일 임시총회를 통해 조합장을 해임하고 비상대책위원회 체제를 가동 중이나 기존 조합장이 해임이 부당하다며 법적대응을 예고해 조합 안정화에 시일이 걸릴 것으로 보인다.조합은 그동안 DL이앤씨 등 5곳이 참여한 시공사와 공사비·분양가·하이엔드 브랜드 사용 등을 두고 입장차를 보였으며 조합 정상화 후 재협상을 할 예정이다.광주 광천동 일대 전경[연합뉴스 자료사진]5천가구 규모의 광천동 재개발 사업도 시공사인 현대건설의 공사비 인상 요구로 수개월째 협상을 진행 중이다.현재 주민 이주까지 완료됐고 공사비 협상도 막바지 단계에 도달했지만, 협상 지연으로 애초 지난해 11월 시작하려던 철거공사 착수가 3월 이후로 밀렸다.분양 시점도 내년 말 또는 2028년 초가 될 것으로 예상된다.3천가구가 넘는 누문 재개발도 장기간 이주와 분담금 등을 두고 갈등이 장기화했으나 최근 98% 이주가 완료되는 등 속도를 내고 있다.현재는 안전상의 문제로 블록별로 해체를 진행 중이며 10∼12% 철거율을 보인다.이들 재개발 사업은 옛 전방·일신방직(전일방) 부지 개발과 함께 광주의 부동산 시장을 이끌 매머드급 사업으로 주목받았으나, 각 사업이 속도를 내지 못하고 지방 분양시장 저조세가 겹치고 있다.2023∼2025년 신규 입주가 2만가구에 달했고, 올해(첨단3지구. 인접 장성 제외 1만1천490가구)와 내년(8천427가구)에도 약 2만가구 입주가 예고돼 물량 해소가 쉽지 않으리라는 것이다.부동산 업계 관계자는 "미분양 아파트가 지난해 말 기준 1천400호로 적지 않지만 이들 재개발 지역은 입지와 규모 면에서 경쟁력이 있어 분양가·브랜드 등에 따라 수요가 달라질 것"이라며 "2028년부터는 신축 공급 감소가 전망돼 분양 시기가 늦어진 점도 악재로 볼 수는 없다"고 밝혔다.areum@yna.co.krin@yna.co.kr', NULL, '연합뉴스', 'https://n.news.naver.com/mnews/article/001/0015930831', 'https://imgnews.pstatic.net/image/001/2026/03/01/PYH2025031601820005400_P4_20260301090125401.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-01 09:00:08', 0, true, '2026-03-09 05:37:53.356331') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (402, '더현대 광주, 2029년 완공 예정…당초 계획보다 1년 지연', '시공사 선정·착공 일정 지연에 완공시점 조정1.2조 투자에서 1.5조로 공사비 확대 전망[이데일리 김지우 기자] 초대형 복합쇼핑몰인 더현대 광주의 완공이 당초 계획보다 1년 이상 늦춰질 전망이다.광주 북구 임동 복합쇼핑몰 ''더현대 광주'' 부지. (사진=뉴스1)24일 광주시와 광주 북구에 따르면 더현대 광주 사업 시행자는 지난달 22일 북구로부터 착공 신고 필증을 교부받고 기초 공정을 시작했다. 지난해 11월 착공식 후 2개월 뒤에 공사에 들어갔다. 착공계에 적시한 목표 준공 일자는 오는 2029년 5월이다.앞서 광주시와 현대백화점은 로드맵 발표 당시 지난해 10월 착공, 2027년 말 준공, 2028년 상반기 복합쇼핑몰 오픈 계획을 밝혔다. 하지만 시공사 선정과 착공 일정이 지연되면서 완공 목표 시점도 연기됐다.공사 기간이 늘어나면서 예상 총공사비 역시 상승할 전망이다. 현대백화점은 기존에 더현대 광주에 1조 2000억원을 투자기로 했었지만, 현재 1조 5000억원 안팎 수준으로 늘어날 것으로 관측되고 있다.더현대 광주는 광주 북구 임동 옛 전방·일신방직(전일방) 부지에 연면적 27만 2955㎡, 영업 면적 10만890㎡(지하 6층∼지상 8층) 규모의 복합문화공간으로 조성될 예정이다. 이는 더현대 서울보다 약 1.4배 큰 규모다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006223829', 'https://imgnews.pstatic.net/image/018/2026/02/24/0006223829_001_20260224172213289.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-24 17:22:13', 0, true, '2026-03-09 05:37:53.356331') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (403, '더현대 vs 신세계 vs 스타필드…광주서 펼쳐지는 ''복합쇼핑몰 전쟁''', '현대백화점, ''더현대 광주'' 2029년 상반기 완공 목표신세계, 백화점 리뉴얼 넘어 ''복합 단지'' 구축 예고지난 2024년 5월 광주 서구 광주시청 비즈니스룸에서 전방·일신방직터에 조성되는 ''더현대광주'' 건축 디자인이 공개되고 있다. ''더현대광주''는 건축계의 노벨상 격인 프리츠커상을 수상한 건축가 헤르조그&드 뫼롱이 설계한다. /뉴시스[더팩트ㅣ문화영 기자] 광주광역시가 유통 대기업들의 새로운 전장으로 떠올랐다. 현대백화점이 초대형 복합쇼핑몰 ''더현대 광주''로 포문을 열었으며 신세계와 신세계프라퍼티도 대규모 개발에 나섰다. 그동안 광역시 가운데 유일하게 대형 복합쇼핑몰이 없던 광주가 ''3파전'' 구도로 재편되는 모양새다.◆ 광주 첫 대규모 복합쇼핑몰…''더현대 광주'' 먼저 삽 떴다현대백화점은 지난해 11월 광주 북구 임동 옛 전방·일신방직 부지에 ''더현대 광주'' 착공식을 열었다. ''더현대 광주''는 광주에 처음 들어서는 초대형 복합쇼핑몰로 연면적 27만2955㎡, 지상 6층~지상 8층 규모다. 이는 서울 여의도 ''더현대 서울''보다 약 1.4배 크다.총 사업비는 약 1조2000억원으로 완공 후 연간 3000만명 방문, 약 7조원 규모의 경제적 파급 효과를 기대하고 있다. 건물설계에는 세계적인 듀오 건축가 헤르조그 앤 드 뫼롱이 참여하며 현대백화점은 전통과 현대를 접목한 문화복합공간을 구상 중이다.다만 일정은 한차례 조정됐다. 당초 2028년 개점을 목표로 했지만 경기 침체와 시공 변수 등으로 2029년 상반기로 늦춰졌다.신세계는 광천터미널 부지에 터미널 빌딩과 백화점 신관을 만든다. /광주신세계◆ ''도심 재편'' 카드 꺼낸 신세계현대가 신규 랜드마크를 짓는다면 신세계는 기존 중심 상권을 키우는 전략이다. 신세계는 지난 5일 광주시와 광천터미널 복합화 사업 투자 양해각서(MOU)를 체결하며 ''더 그레이트 광주'' 구상을 공식화했다.서구 광천동 광천터미널 부지에 35층 규모 터미널 빌딩과 42~44층 복합시설 4개 동을 짓는다. 총 사업비는 3조원에 달하며 기존 백화점 리뉴얼을 넘어 대규모 복합단지로 확장하는 것이 골자다.전체 사업기간은 2033년까지이며 2028년까지 백화점 신관을 신축하는 1단계를 마친 뒤, 2033년까지 터미널·호텔·공연장·업무시설이 들어서는 터미널빌딩과 주거·의료·양료·교육시설이 들어서는 복합시설을 순차적으로 조성한다.백화점은 기존 영업 면적 대비 3배 늘어나고 터미널빌딩은 1.6배 확대돼 시민 편의 시설이 한층 강화될 전망이다. 특히 해당 건물들은 천연기념물 제465호로 지정된 지질 유산인 무등산 주상절리 등 광주의 지형적 특징을 모티브로 해 지역 상징성도 강화한다.지난 1995년 현지법인으로 설립된 광주신세계는 30년 동안 광주 지역 유통의 상징으로 자리해왔다. 지난해 매출은 약 5279억원으로 전국 백화점 중 15위권 안팎이다. 앞서 박주형 신세계 대표이사는 해당 사업과 관련해 "다른 도시에 비해 낡은 백화점을 광주의 랜드마크로 탈바꿈시키겠다"라는 의지를 내비친 바 있다.신세계프라퍼티는 ''그랜드 스타필드 광주''를 오는 2033년까지 완공한다고 밝혔다. /광주시◆ 체류형 승부수…스타필드는 ''관광''에 방점세 번째 주자는 스타필드다. 신세계프라퍼티는 어등산 관광단지에 ''그랜드 스타필드 광주''를 조성할 계획이다. 지난 2023년 광주도시공사와 개발 협약을 체결했으며 올해 상반기 세부 설계를 마무리한 뒤 하반기 기반 시설 공사에 착수할 예정이다.1조3403억원을 투입해 14만7000㎡ 부지를 3단계로 개발한다. 1단계에는 복합쇼핑몰과 워터파크, 2단계에는 호텔·콘도 등 숙박시설이 들어선다. 3단게에서는 골프장 등 레저시설을 더한다. 최종 완공 목표는 2033년이다.스타필드는 단순히 쇼핑 중심이 아닌 쇼핑과 숙박을 결합한 ''체류형 복합단지''를 내세운다. 이는 외지 관광 수요를 끌어들이겠다는 전략으로 풀이된다. 다만 도심과 떨어진 입지가 부담 요인으로 꼽힌다.◆ "세 곳 다 살아남을까"…관건은 ''수요''관건은 소비력이다. 광주는 인구 증가 폭이 크지 않고 소비 규모 역시 수도권 대비 제한적이라는 평가를 받는다. 세 프로젝트가 모두 완공될 경우 공급 과잉 가능성도 배제할 수 없다.기존 상무지구, 충장로와 금남로 등 상권에 미칠 영향도 변수다. 대형몰이 지역 상권을 잠식할지, 외부 방문객을 끌어들여 소비 파이를 키울지 역시 미지수다.세 곳은 모두 입지와 개발 방식이 다르지만 대형 쇼핑몰, 관광 인프라 확충이라는 공통점을 갖고 있다. 업계 관계자는 "''쇼핑 불모지''로 불리던 광주가 단기간에 유통 격전지가 됐다"며 "진짜 승부는 착공 여부가 아니라 오픈 한 이후이며 성공 여부는 규모가 아닌 광주 시민들과 관광객들에게 얼마나 더 차별화된 경험을 제공하는지에 달렸다"고 말했다.발로 뛰는 더팩트는 24시간 여러분의 제보를 기다립니다.▶카카오톡: ''더팩트제보'' 검색▶이메일: jebo@tf.co.kr▶뉴스 홈페이지: http://talk.tf.co.kr/bbs/report/write', NULL, '더팩트', 'https://n.news.naver.com/mnews/article/629/0000473305', 'https://imgnews.pstatic.net/image/629/2026/02/17/202623521770967362_20260217000140449.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-17 00:01:40', 0, true, '2026-03-09 05:37:53.356331') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (404, '올해 광주 아파트 분양 1만세대 또 풀린다…엇갈린 시장 전망', '미분양 증가 속 신가·방직공장 재개발 등 분양 예고"수급 불균형 커질 것", "2028년 공급 감소 예상돼 하방 지지할 수도"광주 아파트단지 전경 [촬영 정회성](※ 아래 기사와 무관한 자료사진입니다.)(광주=연합뉴스) 장아름 기자 = 올해 광주에 아파트 1만1천가구 신규 분양이 예고돼 미분양 우려가 커지고 있다.첨단 3지구와 인접한 전남 장성까지 합치면 1만4천600가구의 입주 물량이 연내에 쏟아지는 가운데 대형 분양도 잇따르는 상황에서 시장 전망은 다소 엇갈린다.15일 부동산 플랫폼 직방에 따르면 올해 분양 예정인 광주 아파트는 16개 단지 1만1천129가구(임대 제외)로 조사됐다.우선 옛 전방·일신방직(전일방) 부지에 추진되는 주상복합아파트인 챔피언스시티 2단지(3천216가구)가 오는 5월 1차 분양을 계획하고 있다.7월에는 민간공원 특례사업지 중 하나인 운암동 힐스테이트 중외공원 1단지(총 994가구)의 748가구 분양이 시작된다.11월에는 양동3구역 재개발 사업지인 더샵루미트리에(총 1천212가구) 781가구를 분양할 예정이다.정확한 분양 시기는 나오지 않았지만 월출동 첨단 A7(총 356가구), 신가동 주택재개발 정비 사업지에 들어설 아크로트라몬트 4개 단지(총 4천718가구)도 연내 분양을 계획하고 있다.2023∼2025년 신규 입주 2만가구 등과 맞물려 미분양 물량이 해소되지 않은 상황에서 단기적 수급 불균형이 커질 수 있다는 전망이 나온다.아파트 건설 (PG)[장현경 제작] 사진합성·일러스트국토교통부 통계에서 광주의 미분양 아파트는 지난해 12월 말 기준 1천404호로, 지난해 1월 말(1천234호)보다 다소 늘었다.12월 말 기준 준공 후 미분양은 781호로 연초보다 훨씬 늘어났다.준공 후 미분양이 아닐 경우 공개 의무가 없어서 준공 전 미분양은 실제 훨씬 더 많을 것으로 추정된다.2월 중 광주 아파트 분양 전망지수는 전국 특광역시 중 최저치를 기록했다.주택산업연구원이 주택사업자를 대상으로 설문 조사한 결과 광주 아파트 분양 전망지수는 95.0이었다.전월(71.4) 대비 23.6포인트 올랐으나 서울(111.9), 세종(121.4), 울산(105.9), 대전(105.6), 인천·부산·대구(100.0) 등 특광역시 중 유일하게 기준치를 밑돌았다.일각에서는 2028년께 입주와 공급이 대폭 감소하고 고분양가가 당분간 이어질 것으로 예상돼 신축 아파트 선점 수요가 나타날 수 있다는 전망도 나온다.김은선 직방 빅데이터실 랩장은 "광주의 올해 분양 물량이 단기적으로 시장에 부담 요인이 될 수 있지만, 계획 수치여서 실제 실적으로 얼마나 이어질지는 지켜봐야 한다"고 말했다.그는 "2027∼2028년 공급 감소가 예상돼 하방을 일정 부분 제한할 수도 있다"며 "최근 서울과 수도권에서 공급 감소 기대가 가격 불안 요인으로 작용했던 사례를 보면, 광주 역시 단기 수치보다는 향후 공급 흐름 추세를 함께 봐야 한다"고 덧붙였다.areum@yna.co.kr', NULL, '연합뉴스', 'https://n.news.naver.com/mnews/article/001/0015907475', 'https://imgnews.pstatic.net/image/001/2026/02/15/C0A8CA3D00000159EFB3BC070002A45E_P4_20260215070125051.jpeg?type=w800', 'NEWS_ETC', NULL, '2026-02-15 07:00:08', 0, true, '2026-03-09 05:37:53.356331') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (405, '손경식 경총 회장 만장일치 재추대…5연임 확정', '24일 이사회·총회서 최종 의결“노란봉투법 대응 등 구심점 필요”손경식 한국경영자총협회 회장이 5일 서울 웨스틴조선호텔에서 열린 한국최고경영자포럼에서 개회사하고 있다. 연합뉴스손경식 한국경영자총협회 회장의 다섯 번째 연임이 사실상 확정됐다.13일 경영계에 따르면 경총 회장단은 이달 11일 회장단 회의를 열고 이달 임기가 만료되는 손 회장을 만장일치로 재추대하기로 뜻을 모았다. 경총은 이달 24일 정기 이사회와 총회를 차례로 열어 손 회장의 연임 안건을 상정·의결할 예정이다. 별다른 변수가 없는 한 연임이 확정된다.손 회장은 2018년 3월 경총 회장에 취임한 후 네 차례 연임에 성공하며 조직을 이끌어왔다. 이번에 5연임이 확정되면 임기가 2년 더 연장돼 10년간 경총 수장을 맡게 된다. 경총 정관에는 회장 연임 제한 규정이 없다. 초대 회장인 고(故) 김용주 전남방직 회장이 12년, 2대 회장인 고 이동찬 코오롱그룹 선대 회장이 15년간 재임한 전례도 있다.손 회장은 당초 연임 고사의 뜻을 내비친 것으로 알려졌다. 그러나 최근 노사 환경을 둘러싼 불확실성이 커지면서 경영계의 요청이 이어졌다는 후문이다. 재계 관계자는 “손 회장이 ‘노란봉투법’으로 불리는 개정 노동조합법 시행을 앞두고 산업 현장의 혼란을 최소화할 구심점이 필요하다는 판단에서 연임을 받아들였다”고 말했다.손 회장은 이달 5일 열린 ‘제4회 한국최고경영자포럼’에서도 개정 노동조합법 시행에 대한 우려를 공개적으로 언급했다. 그는 “많은 기업이 법 시행 이후의 파장에 대해 우려하고 있다”며 “정부와 국회가 산업 현장의 혼란을 최소화할 수 있도록 실효성 있는 보완 대책을 조속히 마련해달라”고 촉구했다.', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004590249', 'https://imgnews.pstatic.net/image/011/2026/02/13/0004590249_001_20260213233322613.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-13 14:24:19', 0, true, '2026-03-09 05:37:53.356331') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (406, '[컨콜]에코프로, 인도네시아 투자 성과로 연간 흑자 전환…영업익 2332억원(종합)', '인도네시아 제련소 투자 결실메탈 트레이딩 호조에 수익성 회복유럽 전기차 판매 회복 영향에코프로가 인도네시아 제련소 투자 성과와 메탈 가격 상승에 힘입어 지난해 연간 흑자 전환에 성공했다. 전기차 수요 둔화에도 불구하고 사업 포트폴리오 다각화와 강도 높은 경영 효율화, 공정 혁신이 실적 개선으로 이어졌다는 평가다.에코프로CI에코프로는 5일 지난해 연결 기준 매출 3조4315억원, 영업이익 2332억원을 기록했다고 밝혔다. 매출은 전년 대비 10% 증가했고, 영업이익은 흑자로 돌아섰다. 에코프로머티리얼즈는 지난해 4분기 분기 기준 흑자 전환에 성공했으며, 에코프로이노베이션 등 주요 계열사 역시 리튬 가격 반등에 따라 경영 실적이 점진적으로 개선되고 있다.이번 실적 개선의 주요 배경으로는 인도네시아 제련소 투자 성과와 메탈 트레이딩 호조가 꼽힌다. 에코프로는 2022년부터 약 7000억원을 투입해 인도네시아 모로왈리 산업단지(IMIP) 내 제련소 4곳에 투자를 진행해 왔다. 이들 제련소 투자로 지난해 약 2500억원 규모의 투자 차익을 거뒀으며, 제련소에서 확보한 니켈 중간재(MHP) 판매 역시 실적 개선에 기여했다.메탈 가격 상승과 환율 등 대외 환경 개선도 매출과 이익 성장을 뒷받침했다. 지난해 하반기 이후 유럽 전기차 판매가 회복세를 보이면서 에코프로 그룹 주요 계열사의 양극재, 전구체, 리튬 판매 실적도 개선 흐름을 나타냈다.계열사별로 보면 전구체를 생산하는 에코프로머티리얼즈는 2025년 별도 기준 매출 3925억원, 영업손실 654억원을 기록했다. 전구체와 메탈 판매 증가로 매출은 전년 대비 31% 늘었으나 연간 기준으로는 적자를 냈다. 다만 지난해 4분기에는 가동률 상승과 메탈 가격 상승에 따른 재고평가충당금 환입 효과로 분기 기준 영업 흑자를 기록하며 수익성 회복 기대를 키웠다.친환경 소재 사업을 영위하는 에코프로에이치엔은 2025년 연결 기준 매출 1411억원, 영업이익 117억원을 기록했다. 전방 반도체 고객사의 투자 조정과 가동률 변동으로 실적이 다소 부진했으나, 4분기부터 업황이 개선되며 회복 조짐을 보이고 있다.에코프로는 올해 경영 환경을 비교적 긍정적으로 전망하고 있다. 회사는 메탈 시세 상승을 반영해 인도네시아 IMIP 제련소 투자 및 트레이딩 이익 규모를 연평균 1800억원에서 약 2200억원 수준으로 상향 추산했다. 제련소 투자를 통해 원가 경쟁력을 확보하면서 제품 판매 가격 상승에 따른 이익률 개선도 기대하고 있다. 메탈 가격 상승 흐름이 이어지면서 지난해에 이어 올해도 연간 흑자 기조를 유지할 수 있을 것으로 보고 있다.시장에 따르면 올해 1월 말 기준 니켈 가격은 지난해 3분기 말 대비 16% 상승했으며, 리튬과 코발트 가격도 같은 기간 각각 98%, 62% 올랐다. 에코프로는 AI 데이터센터 확장에 따른 에너지저장장치(ESS) 시장 성장과 로봇 배터리 등 신규 애플리케이션 수요에도 적극 대응할 방침이다.아울러 전기차 판매 부진에 대응해 각 사업장별 손익 관리 강화를 추진하고, 품질·물류 등 계열사 간 시너지를 높이기 위한 조직 개편을 단행했다. 제조 R&D를 포함한 전 부문에 AI 도입을 추진하는 등 원가 절감과 본업 경쟁력 강화에도 속도를 내고 있다.송호준 에코프로 대표는 "경영 위기를 돌파하기 위해 강도 높은 경영 효율화와 함께 인도네시아 제련 사업 등 미래 성장 동력 확보에 집중해 왔다"며 "올해는 전 사업장에 AI를 도입하고 로봇 등 신규 애플리케이션 대응력을 강화해 흑자 기조를 안정적으로 정착시켜 나갈 계획"이라고 말했다.', NULL, '아시아경제', 'https://n.news.naver.com/mnews/article/277/0005717686', 'https://imgnews.pstatic.net/image/277/2026/02/05/0005717686_001_20260205163216485.png?type=w800', 'NEWS_ETC', NULL, '2026-02-05 16:31:26', 0, true, '2026-03-09 05:37:53.356331') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (407, '롯데정밀화학, 지난해 영업익 744억…전년比 47.6%↑', '매출은 4.9% 증가한 1조7527억[이데일리 김성진 기자] 롯데정밀화학은 지난해 매출액 1조7527억원, 영업이익 744억원의 실적을 기록했다고 4일 밝혔다. 전년 대비 매출액은 4.9% 늘었으며 영업이익은 47.6% 증가했다.이번 실적 개선 배경으로는 염소계열 제품의 국제가 상승과 반도체 현상액 원료 TMAC의 전방 수요 확대에 따른 판매량 확대가 꼽힌다. 주당 현금배당은 1500원으로 결정됐다. 이는 배당성향 36.6% 수준으로 최근 3년간 30% 이상 수준을 유지하고 있다.롯데정밀화학은 지난해 페인트 첨가제 헤셀로스 3공장 인수와 식의약용 셀룰로스 증설 공장 투자 등 총 2636억원의 투자를 집행했다. 특히 식의약용 셀룰로스 증설 공장은 4분기 기계적 준공을 마쳤고 올해 중 상업가동을 시작할 예정이다. 이를 통한 고부가 스페셜티 포트폴리오 강화가 기대된다.또한, 현재 아시아 1위 암모니아 유통 인프라를 바탕으로 청정 암모니아 벙커링(선박연료) 사업 진출 등 아시아 청정 암모니아 허브 도약을 위한 기반을 마련할 계획이다. 정승원 롯데정밀화학 대표는 “2025년에는 주요 제품 시황 호전으로 실적이 개선되었고 고부가 스페셜티 제품에 대한 투자를 강화했다”며 “올해도 식의약용 셀룰로스 증설 공장 상업가동 등 고부가 스페셜티 포트폴리오 강화와 청정 암모니아 사업 기반을 마련해 나갈 것”이라고 말했다.롯데정밀화학 울산 사업장.(사진=롯데정밀화학.)', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006213151', 'https://imgnews.pstatic.net/image/018/2026/02/04/0006213151_001_20260204144311443.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-04 14:43:11', 0, true, '2026-03-09 05:37:53.356331') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (431, '韓금융기관 해외투자 2025년 5000억弗 넘어 역대 최대', '전년보다 872억弗 늘어 5078억弗주식 660억弗·채권 189억弗 증가한국 주요 금융기관의 해외 투자액이 지난해 5000억달러를 넘어서며 역대 최대 규모를 기록했다. 미국 증시에 투자하는 규모가 커진 영향이다.한국은행이 4일 발표한 ‘지난해 주요 기관투자가의 외화증권투자 동향’에 따르면 외화증권투자 잔액(시가 기준)은 5078억3000만달러다.사진=뉴스1직전 연도와 비교했을 때 872억4000만달러(20.7%) 증가한 것으로, 증가폭도 사상 최대다.한은은 “미국 경제의 성장세와 인공지능(AI) 산업 발전 기대감 등으로 주요국 주가가 상승한 가운데 미국 연방준비제도(Fed·연준)의 금리 인하로 미국 국채 금리가 하락하며 외국 주식과 채권 모두 평가이익이 발생했고, 순투자가 증가한 결과”라고 설명했다.기관별 자산운용사의 외화 투자 잔액은 직전 연도 대비 681억달러 늘어난 3582억4000만달러로 역대 최대치를 갈아치웠다.외화 투자 잔액에서 보험사는 94억3000만달러, 외국환은행은 59억1000만달러, 증권사는 38억달러가 각각 늘었다.상품별로는 외국주식이 660억4000만달러 증가한 2925억3000만달러로 최고 기록을 경신했다. 주요국 주가 상승에 자산운용사를 중심으로 한 순투자가 더해지며 증가했다. 미국 국채 금리가 하락하며 보험사를 중심으로 순투자가 확대된 외국채권은 189억8000만달러 늘어난 1828억9000만달러가 됐다.거주자가 외국에서 발행하는 외화 표시 증권인 코리아페이퍼는 외국환은행을 중심으로 증가해 22억2000만달러 늘어난 324억1000만달러로 파악됐다.', NULL, '세계일보', 'https://n.news.naver.com/mnews/article/022/0004110280', 'https://imgnews.pstatic.net/image/022/2026/03/05/20260204516232_20260305060228132.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-05 06:02:28', 0, true, '2026-03-09 05:38:58.463614') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (408, '광천터미널 개발 협상 타결…공공기여·주거시설 모두 증가', '[KBS 광주] [앵커]광주시와 광주신세계 측의 이견으로 진통을 겪어 온 광주 광천터미널 복합 개발  사업 협상이 마침내 타결됐습니다.쟁점이던 공공 기여금과 주거 면적 모두  늘어났는데요.복합 개발 사업이 속도를 낼 것으로 보입니다.박지성 기자의 보도입니다.[리포트]광주시와 광주신세계의 협상이 길어지면서 철거를 먼저 진행중인 광주 광천터미널.공공성과 사업성을 놓고 1년 6개월 동안 이어진 줄다리기가 끝났습니다.핵심인 공공 기여금 규모는 총 1,497억 원.현금 천368억 원에 교통 대책인 무진대로와 터미널을 잇는 양방향 2차로 지하도로 설치비 일부가 현물 공공기여로 포함됩니다.당초 신세계가 제안한 828억 원보다 1.8배 늘어난 규모입니다.다만 토지가치 상승분 대비 공공 기여율은 45.34%에 그쳐 공공시설 수준을 조금 웃돌았습니다.인근 개발 지역인 전일방 부지의 공공 기여율은 54.45%입니다.광주시는 터미널 시설이라는 특수성이 반영된 결과라고 설명했습니다.[김준영/광주시 시민안전실장 : "전일방(전방·일신방직) 같은 경우는 일단 주거 부분이 차지하는 비중이 약 56% 정도를 차지합니다. 여기는 주거 부분이 21% 그 차이가 있기 때문에..."]또 다른 쟁점이었던 주거 면적은 기존안에서 10% 정도 늘리기로 했습니다.세대수로 환산하면 516세대에서 567세대로 계단식 아파트 1동 정도를 더 짓게 된 셈입니다.광주시는 사실상 주거시설이 아니냐는 논란이 있었던 통합 노인 복지시설은 취사와 용도 변경을 못 하도록 제도적으로 막겠다고 밝혔습니다.또 현재 버스정류장 부지에는 650석 규모의 공연장과 5성급 호텔, 180m 전망대, 국제회의시설 등을 조성하는 복합 단지가 만들어집니다.세부 내용을 따져봐야 하지만 큰 틀에서는 터미널 개발의 공공성과 사업성의 균형을 이뤘다는 평가가 나옵니다.광주시와 신세계는 내일 공식 협약식을 통해 터미널 복합 개발의 구체적인 방향과 디자인을 공개할 계획입니다.KBS 뉴스 박지성입니다.촬영기자:조민웅·이승준', NULL, 'KBS', 'https://n.news.naver.com/mnews/article/056/0012118508', 'https://imgnews.pstatic.net/image/056/2026/02/04/0012118508_001_20260204103816382.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-04 09:54:25', 0, true, '2026-03-09 05:37:53.356331') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (409, '광천터미널 개발 협상 타결…공공기여·주거시설 모두 증가', '[KBS 광주] [앵커]광주시와 광주신세계 측의 이견으로 진통을 겪어 온 광주 광천터미널 복합 개발  사업 협상이 마침내 타결됐습니다.쟁점이던 공공 기여금과 주거 면적 모두  늘어났는데요.복합 개발 사업이 속도를 낼 것으로 보입니다.박지성 기자의 보도입니다.[리포트]광주시와 광주신세계의 협상이 길어지면서 철거를 먼저 진행중인 광주 광천터미널.공공성과 사업성을 놓고 1년 6개월 동안 이어진 줄다리기가 끝났습니다.핵심인 공공 기여금 규모는 총 1,497억 원.현금 천368억 원에 교통 대책인 무진대로와 터미널을 잇는 양방향 2차로 지하도로 설치비 일부가 현물 공공기여로 포함됩니다.당초 신세계가 제안한 828억 원보다 1.8배 늘어난 규모입니다.다만 토지가치 상승분 대비 공공 기여율은 45.34%에 그쳐 공공시설 수준을 조금 웃돌았습니다.인근 개발 지역인 전일방 부지의 공공 기여율은 54.45%입니다.광주시는 터미널 시설이라는 특수성이 반영된 결과라고 설명했습니다.[김준영/광주시 시민안전실장 : "전일방(전방·일신방직) 같은 경우는 일단 주거 부분이 차지하는 비중이 약 56% 정도를 차지합니다. 여기는 주거 부분이 21% 그 차이가 있기 때문에..."]또 다른 쟁점이었던 주거 면적은 기존안에서 10% 정도 늘리기로 했습니다.세대수로 환산하면 516세대에서 567세대로 계단식 아파트 1동 정도를 더 짓게 된 셈입니다.광주시는 사실상 주거시설이 아니냐는 논란이 있었던 통합 노인 복지시설은 취사와 용도 변경을 못 하도록 제도적으로 막겠다고 밝혔습니다.또 현재 버스정류장 부지에는 650석 규모의 공연장과 5성급 호텔, 180m 전망대, 국제회의시설 등을 조성하는 복합 단지가 만들어집니다.세부 내용을 따져봐야 하지만 큰 틀에서는 터미널 개발의 공공성과 사업성의 균형을 이뤘다는 평가가 나옵니다.광주시와 신세계는 오는 5일 공식 협약식을 통해 터미널 복합 개발의 구체적인 방향과 디자인을 공개할 계획입니다.KBS 뉴스 박지성입니다.촬영기자:조민웅·이승준', NULL, 'KBS', 'https://n.news.naver.com/mnews/article/056/0012118129', 'https://imgnews.pstatic.net/image/056/2026/02/03/0012118129_001_20260203214121079.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-03 21:34:54', 0, true, '2026-03-09 05:37:53.356331') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (410, '광주, 침체 속 광산·동구 회복…챔스시티 분양 ''변곡점''', '지방 부동산 시장 점검(3) 작년 광주 집값 1.96%↓작년 1.7만건 손바뀜…거래 반등작년 11월 이후 동구 0.28% 상승''학군지'' 광산·남구도 오름세챔피언스시티 상반기 분양 예정더현대·호텔 조성…주변 단지 기대지난 23일 찾은 프로야구 KIA 타이거즈 홈구장인 광주광역시 북구 임동 광주기아챔피언스필드 인근에 약 2㎞ 길이의 펜스가 세워져 있다. 그 너머로 야구장 9개가 들어가고도 남을 크기의 ‘빈 땅’(옛 전방·일신방직 부지)이 눈에 들어왔다. 이곳에 복합쇼핑몰과 4315가구의 주상복합이 들어설 예정이다. 상반기 분양 예정인 챔피언스시티가 올해 광주 지역 부동산 시장의 향방을 좌우할 것으로 보여 관심을 끈다.광주는 공급 과잉과 공사비 상승 등으로 부동산 시장에 찬바람이 불고 있다. 2020년 이후 준공한 대단지를 중심으로 거래량이 증가하는 등 일부 지역에서 회복세를 보이며 장기 침체의 끝이 보인다는 기대도 나온다.◇집값 4년째 하락…미분양도 여전26일 한국부동산원에 따르면 광주의 주간 아파트 매매가격은 작년(2024년 12월 30일~2025년 12월 29일) 한 해 동안 1.96% 하락했다. 2021년 9% 넘게 급등한 뒤 4년 동안 내림세가 이어지고 있다.주요 단지의 몸값이 전고점을 밑도는 등 매매 시장이 회복하지 못하고 있다. ‘광주의 대치동’이라고 불리는 남구 봉선동의 ‘봉선3차 한국아델리움’ 전용면적 84㎡는 작년 11월 9억원(8층)에 새 주인을 찾았다. 2021년 11월 최고가(12억3000만원, 7층)와 비교해 3억원가량 낮은 가격이다.미분양 아파트도 여전하다. 국토교통부에 따르면 지난해 11월 말 기준 미분양 주택은 총 1403가구다. 이 중 ‘악성 재고’로 분류되는 준공 후 미분양은 474가구다. 업계에서는 실제 미분양 물량이 더 많을 것으로 보고 있다. 최근 3년간 민간공원 특례사업과 재건축·재개발 사업 등 43개 단지, 3만246가구가 공급된 여파다.대규모 개발 사업도 답보 상태다. 2023년 4월 철거를 마친 광산구 ‘신가동 주택재개발 정비사업’(4718가구)은 조합과 시공사 간 분양가·분담금 갈등으로 3년 가까이 멈춰 있다. 공사를 맡은 빛고을사업단(대표사 DL이앤씨)은 분양 리스크를 고려해 조합원 분담금을 높여 일반 분양가를 낮출 것을 요구하고 있다.챔피언스시티는 시행사인 신영그룹이 시공사를 정하고 상반기 분양에 나설 계획이다. 인근 A공인 관계자는 “더현대광주와 호텔, 공원 등이 조성된다는 소식에 주변 단지 기대가 크다”며 “전용 84㎡ 기준 9억원가량으로 예상되는 분양가가 관건”이라고 말했다.◇작년 손바뀜 1만7000여 건부동산 플랫폼 아실에 따르면 광주에서 지난해 1만7270건이 손바뀜해 거래량이 3년째 증가세다. 호황기였던 2020년(3만5205건)과 비교해 절반가량 회복한 셈이다. 2020년 이후 준공해 ‘염·계·무·제’로 불리는 더샵염주센트럴파크, 계림아이파크SK뷰, 무등산자이&어울림, 에스클래스더제니스가 거래량 증가의 일등 공신으로 꼽힌다.동구 집값 회복세도 눈여겨볼 만하다. 지난해 11월 첫째주 상승 전환(-0.02%→0.04%) 후 누적으로 0.28% 올랐다. 도시철도 2호선 1단계 공사 구간의 상부 도로가 개방되는 등 개통 일정이 가시화된 영향으로 분석된다. 광산구와 남구는 최근 12주 동안 각각 0.25%, 0.16% 상승했다. 학군지(봉선동, 수완지구)에 속해 학부모 선호도가 높은 지역이다.일각에서는 시장 회복을 위해 인센티브가 필요하다는 주장이 나왔다. 최은선 한국공인중개사협회 광주시회장은 “미분양 주택 매입 때 취득·양도세를 감면해 준다면 악성 재고 해소에 도움이 될 것”이라며 “인공지능(AI), 미래차 등 광주 전략산업과 연계해 청년과 전문인력이 정착할 수 있는 정책을 마련해야 한다”고 말했다.광주=손주형 기자 handbro@hankyung.com', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005242245', 'https://imgnews.pstatic.net/image/015/2026/01/26/0005242245_001_20260127001912856.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-26 16:49:15', 0, true, '2026-03-09 05:37:53.356331') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (411, '[유가증권시장 공시] SK바이오팜 / 파미셀 / 디앤디플랫폼리츠 등', '◇SK바이오팜=자회사 SK라이프사이언스에 483억원 규모 의약품 공급 계약.◇파미셀=1주당 50원 현금 배당 결정.◇디앤디플랫폼리츠=전자단기사채 상환 위해 780억원 규모 자금 차입.◇한국주철관공업=1주당 400원 현금 배당.', NULL, '매일경제', 'https://n.news.naver.com/mnews/article/009/0005641392', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2026-02-24 17:56:20', 0, true, '2026-03-09 05:38:15.594652') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (412, '한국주철관공업, 주당 400원 현금 배당', '한국주철관공업은 보통주 1주당 400원의 현금 배당을 결정했다고 24일 공시했다.시가배당률은 6%다. 배당금 총액은 86억455만2000원이다. 배당 기준일은 지난해 12월31일이다.', NULL, '아시아경제', 'https://n.news.naver.com/mnews/article/277/0005725117', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2026-02-24 13:49:38', 0, true, '2026-03-09 05:38:15.594652') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (413, '알래스카 LNG 기대에 강관주 ''들썩''…넥스틸 25%↑', '[워싱턴=AP/뉴시스]도널드 트럼프 미국 대통령이 취임 1년을 맞은 20일(현지 시간) 백악관 기자회견에서 발언하고 있다. 2026.01.21.[서울=뉴시스] 박주연 기자 = 강관 관련주들이 21일 장 초반 일제히 급등세다.도널드 트럼프 미국 대통령의 알래스카 액화천연가스(LNG) 관련 발언으로 가스관·강관 수요 확대 기대감이 커진 영향이다.21일 한국거래소에 따르면 이날 오전 9시 33분 현재 넥스틸은 전 거래일에 비해 22.12% 상승한 12만700원에 거래되고 있다.하이스틸(19.03%), 이렘(9.95%), 유에스티(9.63%), KBI동양철관(8.07%), 휴스틸(5.11%), 한국주철관(1.35%) 등도 상승세다.트럼프 대통령은 지난 20일(현지시간) 2기 행정부 출범 1주년 기자회견에서 "아시아로 천연가스를 수출하기 위한 대대적인 알래스카 파이프라인 프로젝트를 시작했다"며 "한국, 일본과 유례 없는 수준의 자금을 우리에게 주는 협상을 체결했다"고 언급했다.', NULL, '뉴시스', 'https://n.news.naver.com/mnews/article/003/0013721793', 'https://imgnews.pstatic.net/image/003/2026/01/21/NISI20260121_0000938773_web_20260121055632_20260121094123138.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-21 09:40:33', 0, true, '2026-03-09 05:38:15.594652') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (414, '마천캐스트, 한국주철관 지분 15.22%로 확대…4만5000주 장내 매수', '한국주철관공업의 주요 주주인 마천캐스트가 최근 장내 매수를 통해 보유 지분을 늘렸다. 이로써 최대주주 등 특수관계인 전체 지분율은 50.31%에서 50.50%으로 상승하며 과반 지위를 재확인했다.26일 금융감독원 전자공시시스템에 따르면 마천캐스트는 같은 날 보통주 4만5000주를 장내에서 매수했다. 이번 매수로 마천캐스트의 보유 주식은 기존 342만5880주에서 347만0880주로 증가했다. 지분율은 15.04% 수준에서 15.22%로 상승했다.발행주식총수 2280만500주 기준 한국주철관 전체 최대주주 그룹의 지분은 직전 1147만304주(50.31%)에서 1151만5304주(50.50%)로 0.20p 확대됐다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000075544', 'https://imgnews.pstatic.net/image/293/2025/11/26/0000075544_001_20251126102212240.png?type=w800', 'NEWS_ETC', NULL, '2025-11-26 10:22:12', 0, true, '2026-03-09 05:38:15.594652') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (453, '제약사들 "본업만으론 못버틴다"…투자자문·태양광까지 ''영역 확장''', '정관 변경 등으로 사업 다각화JW중외제약, 컨설팅업 추가 추진대웅제약, 태양광 발전업 진출''제약'' 뗀 보령은 우주까지 발 넓혀국내 제약사들이 최근 잇따라 정관을 손보고, 때로는 사명에서 ''제약''이라는 명칭까지 덜어내며 사업의 외연을 넓히고 있다. 본업인 의약품 중심 성장만으로는 변동성이 커진 시장을 버티기 어렵다는 판단 아래 신사업 영역을 선제적으로 열어두고 투자·협업 기회를 넓히려는 ''사업다각화'' 전략을 펼치는 모습이다.26일 업계에 따르면 JW중외제약은 다음달 26일 정기주주총회에서 사업 다각화를 이유로 사업목적에 ''투자, 경영자문 및 컨설팅업''을 추가하는 정관 변경안을 의결할 예정이다. JW중외제약 관계자는 "내부 조직을 개편하면서 계열사간 제공하는 서비스들이 생겼는데, 그에 따른 일종의 컨설팅 수수료를 받게 되면서 사업목적을 추가하게 된 것"이라며 "외부 대상으로 사업을 새롭게 추진하려는 것은 아니다"라고 설명했다. JW생명과학 역시 투자, 경영 자문 및 컨설팅에 더해 열병합발전, 자가발전 및 에너지(전기, 열)의 자가소비, 판매 및 공급업을 사업목적에 추가할 예정이다. 이에 제약사가 단순히 제품을 파는 회사에서 벗어나, 투자·자문을 통해 기술과 파트너를 발굴하고 포트폴리오를 확장할 수 있는 길을 열어두겠다는 해석이 나온다.대웅제약도 다음달 26일 주총에서 사업목적을 손질한다. 기존 ''식품의 제조 및 판매업''을 ''식품 및 건강기능식품의 제조 및 판매업''으로 보다 명확히 하고, 여기에 ''태양광 발전업''까지 추가하도록 정관을 변경하는 안이 상정됐다. 원가절감형(자가발전)부터 신재생에너지 사업 옵션 확보까지 다양한 시나리오를 열어둔 행보로 해석된다.그간 제약업계는 그동안 치열해지는 경쟁구도 속에서 매출을 확보하기 위해 사업 영역을 꾸준히 확대해왔다. 과거에는 건강기능식품, 의료기기, 반려동물 사업 등 기존 의약품 사업과 밀접한 영역으로 확장을 선호해왔다. 하지만 이 같은 영역에서도 경쟁이 치열해지면서 각 기업들의 사업 영역 확장은 더욱 광범위해지는 양상이다.가장 상징적인 사례로는 보령(옛 보령제약)이 거론된다. 보령은 지난 2022년 1월 사명을 ''보령제약''에서 ''보령''으로 바꾸며 우주 헬스케어 사업 진출을 선언했고, 이후 미국 상업용 우주정거장 기업 Axiom Space와의 협력 흐름 속에서 국내 합작법인 ''브랙스스페이스(BRAX Space)'' 출범을 공식화했다. 보령은 저궤도(LEO) 연구·실험 플랫폼 서비스, 한국인 유인 우주 프로젝트 추진, 우주정거장 모듈 공동개발 등까지 사업 청사진으로 제시하고 있다.업계 관계자는 "최근들어 제약사들이 신규 추가하는 사업들은 과거에 비해 그 영역이 점차 광범위해지는 추세"라면서 "다만 정관 변경이나 사명 변경은 가능성의 문을 여는 초기 단계인 만큼, 실제 투자 집행·자회사 설립·매출화로 이어지기까진 어려울 수 있다"고 말했다.', NULL, '파이낸셜뉴스', 'https://n.news.naver.com/mnews/article/014/0005483598', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_BIO', NULL, '2026-02-26 18:20:15', 0, true, '2026-03-09 05:39:43.216553') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (415, '손놓은 금융위...''L&F·한국주철관'' 9개월째 자사주 공시 안해', 'L&F·한국주철관공업, 자사주 보유현황 등 공시 전무선도전기는 자사주보고서만 첨부금융당국이 1년만에 자기주식 공시 의무 대상을 확대하고 공시 주기를 늘리기로 했지만, 다수 상장회사는 자사주 공시 의무를 외면하고 있다. 자사주 공시 의무 제도를 도입하면서 감독 강화 계획을 밝혔지만 사실상 손을 놓고 있었던 것이다.25일 금융감독원 전자공시시스템에 따르면 유가증권시장 상장법인인 L&F는 지난 3월 2024 사업연도 사업보고서에서 자사주 보유 현황과 보유 목적, 처리 계획 등을 담은 자사주 현황을 공시하지 않았다. 이사회에 자사주 보유 현황과 처리 계획을 보고하는 자사주 보고서도 사업보고서에 담지 않았다. L&F는 지난 8월 공시한 2025 사업연도 반기보고서에도 자사주 공시 의무를 이행하지 않았다.L&F 외에 코스피 상장사인 한국주철관공업 역시 자사주 공시와 자사주 보고서를 9개월 넘게 이행하지 않고 있다. 코스피 상장사인 선도전기는 2024 사업연도 사업보고서에 자사주 보고서만 첨부하고 자사주 현황에 대한 공시는 여전히 이행하지 않고 있다. 국보디자인은 자사주 공시만 하고 자사주 보고서는 사업보고서에 첨부하지 않았다.L&F, 한국주철관공업, 선도전기 CI지난해 6월 자본시장법 시행령 개정안 입법예고 후 12월말에 시행된 자사주 공시 의무는 자사주를 5% 이상 보유한 상장법인에 대해 자사주 보유현황과 보유목적, 향후 추가취득이나 소각 등 처리계획 등에 관한 ‘자사주 보고서’를 작성해 이사회에서 승인받도록 했다. 증권의 발행 및 공시 등에 관한 규정 개정안은 5% 이상 자사주에 대해 처리계획을 담은 보고서를 사업보고서 첨부서류로 제출하고, 해당 내용을 사업보고서에 기재하도록 했다. 자사주 제도가 주주가치 제고라는 취지대로 운용될 수 있도록 하기 위한 노력이었다.올해 초 자사주 공시 제도 시행 직후 35개사가 자사주 보고서를 제출하지 않았다. 이후 케이엘넷, 한컴위드, 희림, NHN벅스, 솔본, CNT85, PN풍년, 케이씨피드, 딜리, 동일기연 등이 7~8월께에야 자진정정에 나섰다. 그렇지만 L&F, 선도전기, 한국주철관공업은 모르쇠로 일관하고 있다.L&F는 자사주 비중이 발행주식총수의 7.54%(2024년 12월말 기준)이고, 선도전기와 한국주철관공업의 자사주 비중도 각각 5.73%, 5.66%로 5%를 넘고 있다.자본시장법은 금융위원회에 자사주 공시 의무 상장법인에 대해 발행주식 일평균거래대금의 10% 이내에서 공시위반 과징금을 부과하도록 하고 있지만, 공시 의무 위반에 대해 조사해 과징금을 부과한 사례는 아직 없다. 금융위원회가 제도 시행 1년도 지나지 않은 시점에 ''자본시장조사업무 규정'' 개정을 통해 자사주 공시 위반에 대한 가중처벌을 추진하는 배경이다. 그럼에도 공시 의무만으로 자사주를 대주주의 지배력 강화에 활용하는 것을 막기에는 역부족이라는 지적이다.', NULL, '아이뉴스24', 'https://n.news.naver.com/mnews/article/031/0000968303', 'https://imgnews.pstatic.net/image/031/2025/09/25/0000968303_001_20250925142909943.jpg?type=w800', 'NEWS_ETC', NULL, '2025-09-25 14:29:09', 0, true, '2026-03-09 05:38:15.594652') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (416, '"실무 논의 없다" 선 그어도…''알래스카'' 나오자 강관주 줄줄이 올랐다', '26일 철강·강관 관련주 상승률./그래픽=윤선정 디자인 기자한미 정상회담에서 알래스카 액화천연가스(LNG) 개발 협력이 언급되면서 강관주가 일제히 상승 마감했다. 한국 정부는 알래스카 LNG 사업 참여 여부에 신중을 기하고 있지만 LNG 밸류체인에 대한 기대감은 단기적으로 주목받을 전망이다.26일 한국거래소(KRX) 코스피 시장에서 하이스틸은 전일 대비 395원(8.62%) 오른 4975원에 마감했다. 개장 직후에는 전일 대비 740원(16.16%) 오른 5320원을 나타냈다. 개장 직후에는 23%대 상승한 5650원까지 올랐다.이날 넥스틸(+2.69%), 이렘(+1.39%), 한국주철관(+0.44%), 율촌(+0.31%), 세아제강(+0.22%) 등 철강·강관 관련주가 동반 상승 마감했다.국내 철강·강관주는 알래스카 LNG(액화천연가스) 개발 수혜주로 분류돼왔다. LNG 프로젝트가 진행되면 다양한 종류의 강관 수요가 발생할 수 있다는 기대에서다.지난 25일(현지 시각) 미국 워싱턴DC 백악관에서 열린 한미 정상회담에서 트럼프 대통령은 알래스카 LNG 개발 프로젝트에 대한 한국의 참여를 재차 요구했다. 트럼프 대통령은 "알래스카 가스전과 관련해 한국과 합작회사(JV)를 추진하려고 한다"며 "일본과 한국이 함께할 것"이라고 말했다.그러면서 "(한미는) 서로 필요한 관계라고 생각한다. 양국의 제품을 서로가 좋아한다"며 "한국은 에너지가 필요한데, (미국은) 알래스카에 풍부한 자원을 갖고 있다. 한국과 같이 협업하고 싶다"고 강조했다.트럼프 행정부는 출범 초기부터 한국, 일본, 대만 등에 알래스카 LNG 사업 참여를 독려해왔다. 다만 한국 정부는 미국의 계속되는 투자 압박에도 신중한 입장을 유지하고 있다. 김용범 대통령실 정책실장은 한미 정상회담 이후 열린 브리핑에서 "알래스카 합작투자는 트럼프 대통령이 한미 협력 분야 중 에너지를 얘기하며 언급한 것"이라며 "실무적 논의는 아직 없다"고 설명했다.이번 정상회담에서 LNG 사업이 다시 한번 언급된 만큼 LNG 밸류체인은 단기적으로 주목될 전망이다. 증권가에서는 한미 정상회담을 계기로 에너지(LNG)를 포함해 조선, 원자력, 항공, 핵심 광물 등 산업 분야에서 대규모 협력 MOU가 체결될 가능성이 높다고 보고 있다.조연주 NH투자증권 연구원은 "에너지 분야에서는 한국가스공사가 미국산 LNG 장기 도입을 계약했다며 추후 양국간 산업 협력은 더욱 확대될 전망"이라고 했다.한국가스공사는 이날 미국 워싱턴DC에서 글로벌 에너지 기업인 트라피구라와 쉐니에르 등 주요 공급업체들과 향후 10년 동안 미국산 LNG를 연간 330만톤씩 추가로 도입하는 계약을 체결했다고 밝혔다. 지난달 한미 관세협상에서 합의된 1000억달러 규모의 미국산 에너지 구매 계획 일환으로 이뤄졌다.김대준 한국투자증권 연구원은 "트럼프 대통령과의 회담에서 산업 협력이 시사된 조선, 에너지 등이 다시 관심 대상이 될 것"이라고 했다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005241264', 'https://imgnews.pstatic.net/image/008/2025/08/26/0005241264_001_20250826161313641.jpg?type=w800', 'NEWS_ETC', NULL, '2025-08-26 16:13:07', 0, true, '2026-03-09 05:38:15.594652') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (417, '부산 올해의 향토기업 21곳 확정', '은산해운항공 등 신규 5곳 포함- 자금·홍보·무역사절단 등 혜택은산해운항공 효성전기 삼영엠티 등 5개 기업이 지역 산업을 이끌고 기반을 다진 부산 향토기업에 새로 선정됐다.부산시는 지역 기업 21개 사를 ‘2025년 부산시 향토기업’으로 뽑았다고 29일 밝혔다. 올해 새로 뽑힌 기업은 ▷물류기업 은산해운항공 ▷자동차 관련 기계장비 제조 기업 나라오토시스템 ▷자동차 부품 전문 생산업체 삼영엠티 ▷선박 부품 전문 제조 업체 한라아이엠에스 ▷전력기기 생산 기업 효성전기 5개 사다. 이밖에 ▷하이록코리아 ▷한국주철관공업 ▷조광페인트 ▷동화엔텍 ▷에스앤더블류 ▷삼원에프에이 ▷엠에스(MS)가스 ▷한탑 ▷대창솔루션 ▷부산은행 ▷SNT모티브 ▷세정 ▷파크랜드 ▷성우하이텍 ▷한국쉘석유 ▷태광 등 16개 사가 재인증을 받았다.시는 지난 4월 공모 접수한 기업을 대상으로 서류평가를 진행했으며, ‘기업애로해소대책위원회’ 심의를 거쳐 향토기업을 확정했다. 이들 기업은 ‘부산광역시 향토기업 육성 및 지원 조례’에 따라 ▷중소기업 이차보전 등 자금한도 상향 ▷시 해외시장개척단(무역사절단 해외전시회 참가 등) 선정 우대 ▷기업 홍보 지원 등의 혜택을 받는다.시는 2006년부터 매년 ▷부산에 본사를 두고 ▷업력 30년 이상 ▷상시 종업원 수 100명 이상 ▷최근 3년간 평균 매출액 200억 원 이상인 기업 중 지역경제 활성화에 이바지한 기업을 향토기업으로 선정했다. 박형준 부산시장은 “향토기업은 오랜 기간 시민과 함께 호흡하며 성장해 온 소중한 자산이다. 시는 앞으로도 다양한 정책적 지원을 통해 지역의 향토기업이 더 높이 도약할 수 있도록 돕겠다”고 말했다.', NULL, '국제신문', 'https://n.news.naver.com/mnews/article/658/0000115203', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2025-07-29 19:54:15', 0, true, '2026-03-09 05:38:15.594652') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (418, '솔본·한컴위드·KL넷, 자사주보고서 늑장 공시…자사주 제도개편 맹탕', '시행 후 7개월째 늑장공시·미이행에도 속수무책태광산업, 자사주 보고서·공시 강화 무력화 무대응자기주식 보유 사실 공시 의무를 위반했던 솔본과 한컴위드, 케이엘넷 등이 뒤늦게 자사주 보고서 등 자사주 보유 사실을 공시했다. 자사주의 보유와 처분 등의 공시를 대폭 강화한다고 했던 금융당국의 자사주 제도 개편이 맹탕이라는 지적이다.7일 금융감독원에 따르면 솔본은 지난 2일 자기주식 보고서를 첨부한 사업보고서를 정정 공시했다. 지난해 12월31일부터 시행한 ''상장법인 자기주식 제도개선''에 따른 자사주 보고서를 뒤늦게 제출한 것이다.금융위원회는 지난해 12월 자본시장법 시행령을 개정해 자사주를 5% 이상 보유한 상장법인에 대해 △자사주 보유 현황 △보유 목적 △취득·소각·처분 계획 △기타 자사주 관련 사항을 이사회에서 승인한 자사주 보고서를 사업보고서에 첨부하도록 했다. 자사주 처분 시에는 처분 상대방, 가격 산정 근거, 예상 주식가치 희석효과 등도 구체적으로 공개하도록 했다.금융위원회는 2024년 1월 상장법인 자사주 제도개선 간담회를 비롯해 1년 간의 공론화 과정을 거쳐 지난해 12월 상장법인의 자사주 보고서 공시와 자사주 공시 상대방 명시 공시 강화 등을 담은 자사주 제도 개선 방안을 의결했다.그렇지만 올해 3월말 제출한 사업보고서에서 솔본을 비롯해 딜리, 케이씨피드, 케이엘넷, 한컴위드, PN풍년 등은 자사주 보고서를 제출하지 않았다. 솔본과 딜리는 사업보고서 제출 시한이 3개월 이상 지난 7월2일 정정 공시를 했고, 케이엘넷과 한컴위드 등은 지난 3일에서야 자사주 보고서를 추가한 사업보고서를 뒤늦게 공시했다. PN풍년은 지난 4일 사업보고서를 정정해 제출했다.솔본과 한컴위드, 케이엘넷 등이 공시 시한이 한참 지난 이후에 자사주 보고서 공시를 이행했으나, CNT85를 비롯해 동일기연·L&F·선도전기·한국주철관공업·국보디자인·희림·NHN벅스 등은 여전히 자사주 보고서 공시 의무를 이행하지 않고 있다. 최근 자사주 처분과 자사주를 교환대상으로 한 태광산업의 자사주 처분 공시는 자사주 처분 상대방을 정하지 않은 채 자사주 처분을 공시했다.금융위가 지난해 1월 ''상장법인 자사주 제도 개선 간담회''를 연 것을 시작으로 1년 간 진행한 자사주 제도 개편안이 제대로 시행되지 않고 있는 것이다.자사주 보고서 공시 기업들의 이사회 승인 내용도 천편일률적이라서 제도 개편의 의의는 물론이고 제도 개선의 의미가 벌써부터 퇴색되고 있다. 자사주 보유 목적은 ''주가 안정 및 주주가치 제고''으로 동일하고, 자사주 처분이나 소각 게획은 ''없음''이라는 답변이 대부분이다. 롯데지주는 자사주 처분 상대방을 지배주주 등으로 공시했다가 계열회사로 변경했고, 태광산업은 자사주 처분계획이 없다고 했다가 갑작스럽게 자사주 전량을 처분하는 등 제도 개편의 실효성조차 의심된다.금융투자업계 관계자는 "자사주 제도 개편을 위해 수 많은 공론화 과정을 거쳤음에도 시행 이후 제대로 된 감독 기능을 찾기 어렵다"면서 "자사주 보고서 공시 변경이나 공시 강화를 무력화하는 시도에 대해 아무런 대응이 없다는 점에서 제도 개편의 취지가 무색하다"고 지적했다.', NULL, '아이뉴스24', 'https://n.news.naver.com/mnews/article/031/0000946613', 'https://imgnews.pstatic.net/image/031/2025/07/07/0000946613_001_20250707170409006.jpg?type=w800', 'NEWS_ETC', NULL, '2025-07-07 17:04:09', 0, true, '2026-03-09 05:38:15.594652') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (419, '한국주철관공업, 김길춘 회장 가족 증여…지분율 ''12.71→9.64%''', '김길춘 한국주철관공업 회장이 자신이 보유한 회사 주식 70만주를 증여했다. 김 회장의 장남인 김태형 대표는 장내매수를 통해 지분율을 끌어올리며 지배력 강화에 나섰다.2일 한국주철관공업은 최대주주 등 소유주식변동 신고서를 통해 증여사실을 공시했다. 김 회장은 70만주를 장남 김태현 대표를 비롯해 김유현, 김유준, 김해윤, 김해민, 김해준, 김서현, 김서진 씨 등에게 증여했다.김 대표를 제외한 나머지 수증자들은 증여 지분 일부를 매각해 현금을 확보했다. 세금 납부를 위해 장내매도에 나선 것으로 보인다. 반대로 김 대표는 사비를 들여 한국주철관공업 지분을 매수해 지분율을 끌어올렸다.김 대표 지분율은 3월 7.4%에서 8.29%로 증가했다. 김 회장의 지분율은 같은 기간 12.71%에서 9.64%로 감소했다. 김 회장이 자신이 보유한 주식 일부를 증여했으나 여전히 최대주주 지위를 지키고 있다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000069356', 'https://imgnews.pstatic.net/image/293/2025/07/02/0000069356_001_20250702171809470.png?type=w800', 'NEWS_ETC', NULL, '2025-07-02 17:18:09', 0, true, '2026-03-09 05:38:15.594652') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (420, 'L&F·NHN벅스·한컴위드 등 자사주 공시 위반 여전...손놓은 금융당국', '5% 이상 자사주 보고서 시행 6개월, 14개 상장사 공시위반 지속5% 이상 자기주식 보유 사실 공시 의무 시행에도 다수의 상장법인이 6개월 넘게 공시 의무를 위반하고 있다. 금융감독당국의 방치 속에 자사주 보유 현황과 처분 계획 등이 드러나지 않고 있는 것이다.1일 금융감독원에 따르면 유가증권시장 상장법인인 L&F는 지난 3월11일 제출한 2024사업연도 사업보고서에서 자사주 7.54% 보유 사실을 밝혔으나, 자사주 보유 현황과 처분 계획 등을 이사회에서 논의한 자사주 보고서 등을 공시하지 않았다.코스피 상장법인인 선도전기와 한국주철관공업도 각각 자사주 5.73%, 5.66%를 보유하고 있지만, 자사주 보고서를 공시하지 않았다.케이엘넷, 국보디자인, 희림, 솔본 등 14개 상장법인이 자본시장법 시행령 상의 자기주식 보고서 공시 의무를 지키지 않고 있다.코스닥시장 상장법인 중에서는 솔본, 국보디자인, NHN벅스, 케이엘넷, 한컴위드, 희림, CNT85, 케이씨피드, 딜리, 동일기연 등이 모두 상장법인의 자사주 공시 의무를 지키지 않았다.지난 3월말 사업보고서 제출 마감 시한에는 일성IS(옛 일성신약) 등 35개 상장법인이 자사주 보고서 공시 의무를 지키지 않았으나, 이후 정정 공시를 통해 공시 의무 위반을 해소했다. 진양제약은 지난 20일에서야 자사주 보고서를 추가했다.사업보고서 제출 마감 이후 3개월이 지났음에도 L&F 등 14개 상장법인은 여전히 자사주 공시 의무를 지키지 않고 있다.금융위원회는 2024년 자본시장법 시행령 개정을 통해 자사주 5% 이상 보유 상장법인에 대해 ‘자사주 보고서’ 작성과 함께 이사회 승인, 사업보고서 첨부 공시를 의무화했다. 보고서에는 △자사주 보유 현황 △보유 목적 △취득·소각·처분 계획 △기타 자사주 관련 사항이 반드시 포함돼야 한다. 자사주 처분 시에는 처분 상대방, 가격 산정 근거, 예상 주식가치 희석효과 등도 구체적으로 공개해야 한다.금융감독원이 2024년말 자사주 보유 비중이 발행주식총수의 15% 이상인 주권 상장법인 111개사를 대상으로 자사주 보고서와 자사주 보유현황을 조사한 결과에서도 자사주 보고서 첨부를 누락하거나, 자사주 보유 현황을 누락한 곳이 다수 발견됐다.자본시장법에 따르면 금융위원회는 사업보고서 상의 자사주 보고서 공시 의무 등 주요 사항 공시 의무를 위반한 상장법인에 대해 발행주식 일평균거래대금의 10% 이내에서 공시위반 과징금을 부과할 수 있다. 다만 아직까지 자사주 보고서 공시 의무 위반에 대해 조사해 과징금을 부과한 사례는 없다.', NULL, '아이뉴스24', 'https://n.news.naver.com/mnews/article/031/0000944813', 'https://imgnews.pstatic.net/image/031/2025/07/01/0000944813_001_20250701112612476.jpg?type=w800', 'NEWS_ETC', NULL, '2025-07-01 11:26:12', 0, true, '2026-03-09 05:38:15.594652') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (421, '반도체 투자 쏠림이 ‘롤러코스피’ 불렀다', '반도체주, 코스피·코스닥 시총 36%삼전·하닉 급락에 지수도 ‘널뛰기’美·日 대비 과도한 변동성 한계 지적증권가 “반도체주 저점 매수기회로”중동발(發) 지정학적 리스크로 국내 증시가 크게 요동치는 가운데, 반도체 종목에만 의존하는 코스피의 구조적 취약성이 충격을 키우고 있다. 국내 지수에서 반도체 관련 35개 종목이 차지하는 비중은 36%에 이른다. 특히 그 중에서 삼성전자와 SK하이닉스의 비중도 절대적이다.지나치게 반도체 종목에 편중돼 있다보니 해당 업종의 등락에 전체 지수가 크게 요동치는 구조다. 중동 사태에서 미국, 일본 등 주요국보다 국내 증시의 변동성이 더 극심한 것도 이 같은 구조적 한계 때문이란 지적이다.9일에도 국내 증시는 어김없이 크게 출렁였다. 코스피는 개장에서부터 5.72%나 급락한 5265.37로 출발했다. 삼성전자와 SK하이닉스도 개장부터 각각 7%대 급락했다.6일 기준 한국거래소(KRX) 반도체 지수의 시가총액 규모는 1887조4430억원으로, 코스피·코스닥 시총(5240조7250억원)의 36.01%에 달하는 규모다. KRX 반도체 지수는 삼성전자, SK하이닉스 외 한미반도체, 원익IPS, DB하이텍, 주성엔지니어링, RFHIC 등 35개 종목으로 구성돼 있다.증권가에서는 이번 중동 사태가 실제 경제에 미치는 영향보다 코스피가 과도하게 반응했고, 그 배경에는 편중된 반도체 쏠림 구조가 있다고 분석했다. 다른 나라의 주가 지수도 이란 사태로 변동성을 보였지만, 우리나라처럼 하루 10% 전후로 움직이는 상황은 이례적이라는 분석이다.특히 전쟁 당사국인 미국의 주가가 일평균 1% 내외의 변동을 보인 것과 비교하면 우리의 주가 변동은 더욱 두드러진다.정용택 IBK투자증권 연구원은 “소수 종목에 의한 과도한 집중으로 중동사태가 경제에 미치는 영향보다 과도하게 주가지수가 반응하고 있다”며 “우리나라는 두 반도체 종목(삼성전자·SK하이닉스)이 전체 시장의 40% 가까이 차지하는 반면, 미국 스탠더드앤드푸어스(S&P)500에서 가장 큰 두 종목의 비중은 10%대 초반”이라고 지적했다.문제는 당장 이를 대체할 대안이 쉽지 않다는 데에 있다. 중동발 지정학적 리스크가 커지고 있는 상황에서도 반도체 수출은 가파르게 증가하는 등 사실상 우리 경제를 떠받치고 있다.2월 한국 수출 증가율은 설 연휴로 조업일수가 감소했음에도 전년 동월 대비 29% 증가했다. 특히 반도체 수출은 전년 동월 대비 160.8% 증가하며, 월 기준 역대 최대치를 기록했고, 3개월 연속 200억달러를 상회하는 흐름을 이어가고 있다.증권가에서는 양사의 최근 주가 하락을 매수 기회로 보고 있다. 김영건 미래에셋증권 연구원은 삼성전자와 SK하이닉스의 목표주가로 앞서 제시한 27만5000원, 154만원을 유지했다.김 연구원은 “주가 하락이 무색하게도 메모리 가격은 매우 안정적”이라며 “공급망의 불확실성은 오히려 메모리 안전 재고 확충 기조를 강화할 수 있고, 동시에 공급자로 하여금 설비 투자에 대한 경계심을 확대할 만한 요인”이라고 말했다. 김지윤 기자', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002610517', 'https://imgnews.pstatic.net/image/016/2026/03/09/0002610517_001_20260309111919373.jpg?type=w800', 'NEWS_SEMI', NULL, '2026-03-09 11:19:19', 0, true, '2026-03-09 05:38:37.163613') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (424, '아스타, 반도체 분석장비 양산성능평가 인증', '‘가스분석기(GM-TOF)’로 반도체산업협회서회사 “반도체 기업에 공급물량 확대 가능해져”질량분석장비 기업 아스타(대표 조응준)가 반도체 공정용 가스 검사장치로 ‘양산성능평가 인증’을 받았다.이 회사는 최근 한국반도체산업협회로부터 이 인증을 받았으며, 대상은 국내 최초로 개발한 실시간 ‘가스분석기(GM-TOF)’다. 이는 세계 최대 메모리 반도체 기업 중의 하나인 S사 생산라인에서 10개월 가량 테스트를 거친 제품이다.반도체산업협회는 국내 반도체 3사(삼성전자, 하이닉스, 동부하이텍) 주도의 ‘반도체 장비·재료 성능평가 팹’을 구축해 운영 중이다. 중소 반도체장비, 재료업체의 경쟁력 제고와 대-중소기업 간 상생협력 차원이다.이를 통해 장비·재료 검사라인의 성능 검증·평가 및 인증으로 핵심부품의 국산화를 유도한다. 교차 인증된 품목의 경우 기업간 교차구매를 실시해 관련 산업을 활성화하게 된다.지금까지 국내 재료·장비 업체들은 제품을 개발하고도 시장에서 성능을 인정받는데 어려움을 겪었다. 성능평가 팹 운용을 위해 필요한 양산라인 설치에 수 조원의 비용이 들기 때문.아스타는 5일 “이번 반도체 양산성능평가 인증으로 국내 뿐 아니라 일본, 대만 등 해외 매출도 탄력을 받을 것으로 기대된다. 향후 더욱 적극적인 영업을 전개할 수 있을 것”이라고 밝혔다.국내 반도체 제조사들은 반도체 공정 중 발생하는 기체를 포집해 가스를 분석하는데 외국산 분석기를 쓰고 있다. 상대적으로 고가이며 고장 및 수리에 2~3주가 소요돼 국산화 필요성이 제기돼왔다.회사 관계자는 “산업용 분석기기를 국내 대기업에 매년 공급하면서 기술력을 쌓아왔다. 이번 반도체 양산 성능인증으로 공급물량을 크게 늘리는 분기점이 될 것으로 시장에서는 평가하고 있다”고 했다.', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002609053', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_SEMI', NULL, '2026-03-05 15:56:15', 0, true, '2026-03-09 05:38:37.163613') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (425, '[서울데이터랩]한화시스템 30.00% 상한가…금일 증시 상승률 1위로 마감', '5일 오후 15시 35분 한화시스템(272210)(150800)이 등락률 +30.00%로 상승률 1위로 마감했다. 한화시스템은 장 중 8,178,289주가 거래되었으며 주가는 공모가 대비 34,800원 오른 150,800원에 마감했다.한편 한화시스템의 PER은 47.86으로 평가되며, ROE는 19.63%로 수익성이 비교적 양호한 수준을 보여주었다.이어 상승률 2위 한화갤러리아우(45226K)는 주가가 +30.00% 상한가를 기록하며 종가 7,670원에 상승 마감했다. 상승률 3위 미래에셋생명(085620)의 주가는 13,570원으로 +29.98% 폭등하며 강세를 보였다. 상승률 4위 한국ANKOR유전(152550)은 +29.83% 상승하며 470원에 마감했다. 상승률 5위 에이엔피(015260)는 +29.79%의 상승세로 종가 562원에 마감했다.6위 디아이(003160)는 종가 33,800원으로 +24.72% 상승 마감했다. 7위 KEC(092220)는 종가 1,424원으로 +23.83% 상승 마감했다. 8위 LIG넥스원(079550)은 종가 763,000원으로 +23.26% 상승 마감했다. 9위 DB하이텍(000990)은 종가 95,000원으로 +22.90% 상승 마감했다. 10위 삼아알미늄(006110)은 종가 30,350원으로 +22.87% 상승 마감했다.이밖에도 한미반도체(042700) ▲21.62%, 일정실업(008500) ▲20.81%, 자화전자(033240) ▲19.68%, 대덕전자(353200) ▲18.84%, 한화비전(489790) ▲18.64%, 키움증권(039490) ▲18.39%, 한화투자증권(003530) ▲17.81%, 케이씨텍(281820) ▲17.62%, SK증권(001510) ▲17.37%, 태경케미컬(006890) ▲17.14% 등을 기록하며 금일 증시를 상승으로 마감했다.전문가는 “한화시스템의 급등은 방산 및 첨단 기술 부문에서의 성장 잠재력과 관련된 기대감이 반영된 것으로 보인다”며 “시장 참여자들이 장기적인 성장 가능성을 긍정적으로 평가하여 주가에 긍정적인 영향을 미쳤다”고 설명했다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003623251', 'https://imgnews.pstatic.net/image/081/2026/03/05/0003623251_001_20260305155217848.png?type=w800', 'NEWS_SEMI', NULL, '2026-03-05 15:52:17', 0, true, '2026-03-09 05:38:37.163613') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (426, '[김지영의 생존투자] 국경 넘은 ‘K-반도체’ 사랑…해외 ETF 시장서 韓존재감↑', '제미나이가 그린 일러스트.반도체 업황 개선 기대를 등에 업고 코스피가 강세를 이어가자 해외 상장 한국 관련 상장지수펀드(ETF)로 글로벌 자금이 대거 유입되고 있다. 미국과 중국 증시에 상장된 한국 반도체·지수 추종 ETF에 자금이 집중되는 한편, 국내 투자자들까지 레버리지 상품을 활용하기 위해 해외 시장을 통한 우회 투자에 나서고 있다.2일 코스콤 ETF체크에 따르면 최근 일주일 동안 ‘디렉시온 데일리 MSCI 사우스코리아 불 3X 셰어즈(KORU)’ ETF에는 최근 일주일 동안 약 2억6030만달러의 자금이 유입됐다. 해당 ETF는 모건스탠리캐피털인터내셔널(MSCI)이 산출하는 MSCI 코리아 25/50 지수를 정방향으로 3배 추종하는 상품이다. 코스피 시장 주요 대형주와 중형주의 일일 수익률을 3배로 추종하도록 설계됐다.뉴욕 증시에 상장된 ‘아이셰어즈 MSCI 사우스코리아(EWY)’에도 최근 일주일 동안 18억달러가 순유입됐다. 이 ETF는 한국의 시가총액 상위 종목에 투자하는 상품으로 삼성전자(28.72%), SK하이닉스(19.73%), 현대차(2.82%) 등을 담고 있다.지난해부터 강세를 이어오고 있는 국내 증시가 연초 이후에도 오름세를 지속하자 외국인 투자자들도 코스피에 자금을 공격적으로 실어 나르는 모습이다. 특히 뉴욕 증시에 상장된 한국 관련 ETF로 대규모 자금이 유입되면서 해외 자금을 통한 우회 투자 수요가 빠르게 확대되고 있다는 분석이 나온다.미국 뿐만 아니라 중국 투자자들의 관심도 집중되고 있다. 중국 증시에 상장된 ‘중한반도체(中韓半導體)’ ETF는 지난달 27일 4.25위안에 거래를 마쳤다. 장중 4.65위안까지 치솟으며 최고가를 경신했다. 올해 수익률은 59.77%에 달한다.해당 ETF는 한국거래소와 상하이증권거래소가 공동 개발한 ‘KRX CSI 한중반도체지수’를 기초지수로 삼아 삼성전자와 SK하이닉스, 리노공업, DB하이텍 등 한국 반도체 기업을 포함한다. 중국 증시 특성상 해외 주식 직접 투자가 쉽지 않아 공모 ETF로 자금이 집중되고 있는 것이다.시장에서는 반도체 업황 개선 기대와 인공지능(AI) 관련 투자 확대, 원·달러 환율 안정 등이 복합적으로 작용한 결과로 보고 있다. 삼성전자와 SK하이닉스를 중심으로 한 대형 반도체주의 실적 개선 기대가 높아지면서 MSCI 코리아 지수 편입 종목 전반에 대한 투자 매력이 부각되고 있다는 평가다.반도체를 중심으로 증시 강세가 집중되면서 레버리지를 활용하기 위해 해외 증시를 우회적으로 이용하는 서학개미의 자금도 집중되고 있는 것으로 나타났다.이날 예탁결제원에 따르면 2월 넷째주(23~27일) 해외주식 순매수 상위 종목 가운데 ‘KORU’가 8392만달러 순유입을 기록하며 1위에 올랐다. 앞서 2월 셋째주(16~20일)부터 자금 유입이 본격화되며 순매수 6위를 기록한 데 이어, 한 주 만에 순매수 1위로 뛰어오른 것이다.국내 투자자들이 우회 투자를 선택한 배경에는 레버리지 활용이 자리한다. 국내에는 코스피 지수를 3배로 추종하는 ETF가 없지만 미국 시장에는 KORU처럼 3배 레버리지 상품이 상장돼 있어 단기 상승장에 보다 공격적으로 대응할 수 있다.여기에 달러 자산 형태로 한국 증시에 투자할 수 있다는 점도 영향을 미친 것으로 보인다. 원화 주식 직접 매수와 달리 해외 상장 ETF는 달러로 거래되는 만큼, 환율 변동에 대한 전략적 대응이 가능하다는 판단이 깔려 있다는 분석이다.금융투자업계에선 실적 개선과 유동성 확대가 동시에 진행되면서 밸류에이션 재평가 기대가 커지고 있다는 분석이 나온다.이재만 하나증권 연구원은 “반도체 업종을 중심으로 2026~2027년 코스피 상장사의 이익 추정치가 잇따라 상향 조정되고 있다”며 “고객예탁금이 사상 최고치를 경신하는 등 대기성 자금도 빠르게 불어나고 있다”고 말했다.이 연구원은 “MSCI가 산출하는 MSCI 코리아 지수를 추종하는 ETF로의 자금 유입이 꾸준히 이어지고, 액티브 ETF 시장 확대 가능성까지 거론되면서 수급 여건은 우호적으로 전개되는 모습”이라고 분석했다.', NULL, '디지털타임스', 'https://n.news.naver.com/mnews/article/029/0003013336', 'https://imgnews.pstatic.net/image/029/2026/03/02/0003013336_001_20260302193608344.png?type=w800', 'NEWS_SEMI', NULL, '2026-03-02 18:29:51', 0, true, '2026-03-09 05:38:37.163613') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (427, '신임 팹리스협회장 "엔비디아·퀄컴 같은 ''앵커기업'' 만들어낼 것"', '김경호 신임 회장, 취임 기자간담회서 발언"삼성, LG 등 세트 업체와 긴밀한 관계 중요""팹리스 대표 기업 중심의 생태계 구축해야""타깃 명확한 팹리스 전문 인력 육성 필요"[이데일리 박원주 기자] “전체 반도체 시장에서 시스템반도체가 차지하는 비중은 70%이지만, 이 중 우리 기업들의 비중은 1~2% 수준입니다.”김경호 신임 한국팹리스산업협회장이 지난 27일 경기 판교에 위치한 협회 세미나실에서 진행된 취임 기자간담회에서 발언하고 있다.(사진=박원주 기자)김경호 신임 한국팹리스산업협회장은 지난 27일 경기 판교에 위치한 협회 세미나실에서 진행한 기자간담회에서 “메모리반도체는 삼성전자와 SK하이닉스가 확고하게 1위와 2위를 다투고 있지만 시스템반도체는 한국 기업들의 존재감이 불행하게도 없다”며 이렇게 말했다.김 회장은 카이스트 전기·전자공학 박사 출신으로 시스템반도체 분야에서 40년 이상 경력을 쌓았다. 삼성전자 임원으로 재직하며 DMB와 LTE 등 시스템온칩(SoC) 설계 분야의 주요 프로젝트를 총괄했다. 이후 연세대 교수로 재직했다. 또 코아시아세미와 어보브반도체의 대표이사를 역임했다.김 회장은 “(연간 매출을 기준으로) 국내 시스템반도체 분야에서 삼성 시스템LSI와 LX세미콘을 제외하면 3000억원 아래 기업이 다수 포진하고 있다”고 했다. 그러면서 “시스템반도체 사업의 성공 요인은 세트(완성품) 업체의 수요에 맞춰 개발하고, 수요 업체들은 (반도체의) 초기 테스트를 진행하는 것”이라며 “지금까지는 그 관계가 약했던 게 (성장 제약의) 가장 큰 요인이었다”고 진단했다.김 회장은 팹리스 분야 ‘앵커기업’의 중요성을 강조했다. 팹리스 대표 업체를 중심으로 파운드리(반도체 위탁 생산)와 OSAT(반도체 후공정), 수요 기업을 포괄하는 반도체 생태계를 구축해야 한다는 의미다. 그는 “미국 엔비디아와 퀄컴, 대만 미디어텍 등 각 나라마다 팹리스 업계의 대표 기업이 있다”며 “우리는 AI 반도체에서 자산 가치 3조원 단위로 평가 받는 기업들이 상용화 트랙으로 나가고 상장하는 식으로 대표 기업이 될 가능성이 있다”고 했다. 실제 국내 기업들 중 퓨리오사, 리벨리온 등은 AI 반도체 기술력을 인정 받고 있다.김 회장은 임기 동안 △전자설계자동화(EDA)와 지적재산권(IP) 비용에 대한 세제 지원 확대와 세액공제 현금 확대 등 ‘팹리스 맞춤형 정책’ △국내 파운드리 생산량의 일정 비율을 한국 팹리스에 우선 배정하는 ‘상생 쿼터제’ △판교 중심의 실전형 반도체 인재 육성 등 5대 과제를 추진할 예정이다.그는 아울러 국내 팹리스 업체들이 국내 파운드리를 충분히 활용할 수 있는 방안을 논의 중임을 밝혔다. 그는 “국내 시제품 제작을 위한 공공 트랙 구축 필요성도 제기돼 왔다”며 “40~130, 180나노 공정 구간에 대해 공공 팹에서 시제품을 제작하고, 이후 양산은 삼성전자, DB하이텍 등 민간 파운드리가 진행하는 모델을 논의 단계에 있다”고 설명했다.김 회장은 “팹리스 기업들이 국내에 충분하지 않은 40~90나노 공정을 해외에서 이용해 멀티 프로젝트 웨이퍼(MPW)를 진행할 경우 비용 부담이 커지고, 아울러 해외 MPW 제작 비용은 연구개발(R&D) 비용으로 인정받기 어려워 세액공제 적용에 제약이 있다”며 “협회는 공정 부족에 따른 세제상 불이익이 발생하지 않도록 국세청과 협의하고 있다”고 덧붙였다.김 회장은 팹리스 특화 인재 육성의 필요성도 강조했다. 그는 “전국에 반도체 특성화 학과가 30개 이상 운영되고 있지만, 저희 회원사로 있는 중소기업 팹리스 관점에서 ‘리텐션’(인력 유지)이 굉장히 어려운 게 현실”이라며 “마이크로컨트롤러(MCU) 등 팹리스 분야별로 세분화한 계약학과에서 특화된 교육하면서 타깃을 명확히 한 인력 수급을 하는 게 중요하다”고 했다.그는 또 “대기업에서 정년에 가까워진이 전문가들을 협회 차원에서 채용해 중소·중견기업이 필요로 하는 분야에 도움을 주는 것을 생각하고 있다”고 설명했다.아울러 보상제도의 방향성에 대해서도 언급했다. 그는 “대기업의 연봉과 복지를 중소기업이 따라갈 수 없다”며 “그럼에도 이에 경쟁할 수 있는 건 스톡옵션(주식매수선택권)”이라고 했다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006226873', 'https://imgnews.pstatic.net/image/018/2026/03/02/0006226873_001_20260302191307067.jpg?type=w800', 'NEWS_SEMI', NULL, '2026-03-02 12:02:10', 0, true, '2026-03-09 05:38:37.163613') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (428, '국민성장펀드 자금 무산 위기에…DB하이텍 소액주주 직접 등판', 'DB하이텍 공장 증설을 위해 대규모 정부 지원금이 필요한 가운데 최근 지배구조 리스크로 해당 지원금을 받기 어려워지자 소액주주연대가 직접 이사회에 진입하겠다고 나서 주목된다.25일 DB하이텍 소액주주연대는 다음달 24일 예정된 DB하이텍 정기주주총회를 앞두고 회사 경영진의 지배구조 리스크로 위기에 처한 1조5000억원 규모 정부 지원금을 살리기 위해 직접 이사회에 진입한다고 밝혔다.DB하이텍 소액주주연대 관계자는 "현재 DB하이텍은 충청북도 음성 공장 증설을 위해 국민성장펀드 유치가 절실한 시점"이라며 "최근 공정거래위원회가 총수 일가 지배력 유지와 사익 편취를 위해 은폐해 온 위장계열사를 적발해 검찰에 고발하며 자금 지원이 원점에서 재검토될 위기에 처했다"고 지적했다.이어 "정부 방침이 오너 리스크가 있는 회사에 정책자금을 지원하는 것이 적합한지 검토할 것이라고 한만큼 DB하이텍의 현재 거버넌스가 우려된다"며 "이번 주주총회에서 경영진을 견제하고 투명성을 확보하기 위해 이상목 액트 대표를 사외이사 후보로 추대했다"고 말했다.DB하이텍 소액주주연대가 제안한 공정거래 특별 조사 신설의 건, 내부거래위원회 신설의 건, 위장계열사 부당 거래 진상 규명을 위한 법원검사인 선임 신청 권고의 건은 모두 주주총회 정식 안건으로 확정됐다.이 관계자는 "DB하이텍 반도체 사업 역량은 국가 경쟁력 차원에서 반드시 키워야 할 핵심 자산"이라며 "주주들이 직접 철저한 감시자가 돼 투명한 환경을 만들어내면 정부도 안심하고 1조5000억원 규모 국민성장펀드를 집행할 수 있을 것"이라고 했다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005323978', 'https://imgnews.pstatic.net/image/008/2026/03/02/0005323978_001_20260302100118409.jpg?type=w800', 'NEWS_SEMI', NULL, '2026-03-02 10:00:28', 0, true, '2026-03-09 05:38:37.163613') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (429, '“우리도 韓주식 사게해줘” 中부자들 바이코리아 열풍', '온라인 커뮤니티삼성전자와 SK하이닉스를 중심으로 한 한국 반도체주가 강세를 보이면서 중국 증시에 상장된 한국 반도체 ETF(상장지수펀드)가 인기다. 특히 중국에 상장된 ‘중한 반도체 ETF’에 자금이 폭발적으로 몰렸다. 해당 상품은 중국 본토 투자자가 위안화로 한국 반도체 대형주에 접근할 수 있는 사실상 유일한 공모 ETF다.28일 금융투자업계에 따르면 중국 상하이 증권거래소에 상장된 ‘중한반도체’ ETF는 지난 26일 9.64% 오른 4.321위안에 거래를 마쳤다. 장 중 한 때 4.33위안까지 오르며 상한가인 4.335위안에 근접했다. 이날 거래대금만 86억9900만 위안(약 2조 원)이었다.특히 1년 전인 지난해 2월27일 중한반도체 종가는 1.636위안이었다. 1년 사이 가격이 164% 넘게 오른 것이다. 지난해 12월30일(2.577위안)보다도 65.4% 높은 수치다.2022년 11월 신규 상장된 중한반도체 ETF는 중국 본토 증시 상장된 유일한 한국 관련 투자 상품이다. 중국 자산운용사 화타이바이루이가 운용하며, 한국과 중국의 대표 반도체 기업에 투자하는 상품이다.포트폴리오에는 삼성전자(16.31%)와 SK하이닉스(15.45%)를 비롯해 리노공업, DB하이텍 등 한국 반도체 기업과 SMIC, 캄브리콘 등 중국 반도체 기업이 함께 담겨 있다. 삼성전자와 SK하이닉스 비중만 30%를 웃돈다.금융투자업계 관계자는 “중국은 자본 유출 관리를 엄격히 하고 있어 개인이 해외에서 계좌를 개설하지 않는 이상 해외 주식 직접 투자가 쉽지 않다”면서 “이 때문에 한국 반도체 투자 수요가 해당 ETF로 집중되는 구조”라고 설명했다.다만 한국 증시 열풍이 중국에만 국한되는 것은 아니다. 미국 증시에 상장된 대표적인 한국 투자 상품인 ‘아이셰어즈 MSCI 한국 ETF(EWY)’에도 최근 한 달간 수십억 달러의 자금이 순유입된 것으로 전해졌다.', NULL, '문화일보', 'https://n.news.naver.com/mnews/article/021/0002773953', 'https://imgnews.pstatic.net/image/021/2026/02/28/0002773953_001_20260228181109687.jpg?type=w800', 'NEWS_SEMI', NULL, '2026-02-28 18:11:09', 0, true, '2026-03-09 05:38:37.163613') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (430, 'DB그룹, 오너리스크 재점화…공정위, 김준기 창업회장 검찰 고발', 'DB그룹이 오너리스크에 휩싸였다. 공정거래위원회가 김준기 창업회장을 검찰에 고발했다. 총수 일가의 지배력 유지를 위해 위장 계열사를 운영했다는 혐의에서다. 오너리스크가 재점화된 셈이다. 김 창업회장은 불미스러운 일로 회장직에서 물러났다. 이후 김남호 명예회장이 DB그룹을 이끌었고, 지난해에는 전문경영인 체제로 전환한 바 있다. 전문인경영체제에도 오너일가의 문제는 그룹 운영에 있어 부정적 영향을 줄 수 있는 요소다. 지배구조 문제로 인한 좋지않은 ESG평가는 투자 유치 차질 등으로 이어질 수 있다는 지적이다.24일 재계와 DB그룹 등에 따르면 김 창업회장은 공정위에 공시대상기업집단 등 지정을 위한 자료(지정자료)를 허위로 제출한 혐의로 검찰 수사를 받을 전망이다. 공정위는 지난 8일 김 창업회장이 동곡사회복지재단 및 그 산하회사 총 15개(재단회사)사 등을 소속 현황에서 누락한 행위를 적발, 검찰에 고발키로했다. 15개사는 삼동흥산, 빌텍, 뉴런엔지니어링, 탑서브, 코메랜드(구 삼동랜드), 상록철강, 평창시티버스, 강원흥업, 강원일보, 강원여객자동차, 동구농원, 양양시티버스, 대지영농, 동철포장, 구미자원 등(현재 기준 폐업한 회사도 포함)이다. 해당 계열사들은 1999년 11월부터 DB그룹의 계열사에서 제제외됐다.공정위는 DB그룹이 최소 2010년부터 총수 일가의 지배력 유지 및 사익을 위해 재단회사들을 활용했고, 2016년 이들 회사를 관리하는 직위까지 설치해 본격적으로 지배력을 행사했다고 봤다. DB아이엔씨와 DB하이텍을 김 창업회장의 지배력을 유지하기 위한 핵심 계열사로 삼았고, DB아이엔씨를 통해 제조서비스 계열사를 장악했다는 게 공정위의 설명이다.DB그룹의 지배구조상 김 창업회장의 지배력 유지 핵심계열사는 DB아이엔씨와 DB하이텍이다. 오너일가가 지분 43.7%를 소유하고 있고, 김 창업회장은 두 회사를 통해 제조서비스 계열사를 지배하고 있다. DB하이텍의 경우 DB그룹 소속 비금융계열사 중 재무규모가 가장 크지만 김 창업회장 측 지분율이 23.9%(자사주 제외) 정도로 낮았다. 이런 상황에서 총수의 지배력을 유지하기 위해 재단회사들이 무리하게 동원됐다고 공정위는 전했다. 재단회사들은 2010년에 DB하이텍의 재무 개선을 위해 DB캐피탈로부터 거액의 대출을 받아 불필요한 부동산을 DB하이텍으로부터 매수했다는 것이다. 김 창업회장은 2021년 개인적으로 돈이 필요해지자 재단회사 중 하나인 빌텍으로부터 220억원을 대여받기도 했다. 김 창업회장은 대여받은 돈을 중도 상환했다가 취소했지만, 중도 상환 수수료를 내지 않았다.공정위는 DB그룹의 관심사항이 ''총수일가의 지배력 유지·확대와 사익 추구였고, 재단회사들은 도구에 지나지 않았다는 것이 적나라하게 드러나는 사례도 적발했다. 외견상 계열사가 아닌 재단회사에게 위험부담을 지게 하고 이익은 총수일가가 얻게 하며 DB 지배구조를 강화하는 형태를 보였다는 설명이다. 공정위는 DB그룹이 위법 행위를 은폐하기 위한 방침도 운영했다고 봤다. DB그룹이 재단회사를 동원하는 거래를 기획할 때마다 위장계열사 리스크를 분석하고, 그룹 조직도에 재단이 포함된 내용을 관계사에 배포할 경우 재단 내용을 삭제하라고 명시했다는 게 공정위의 설명이다.공정위는 "이번 사안은 동일인 측의 지배적인 영향력 행사, 즉 지배력 요건을 여러 증거와 거래 관계, 구체적인 정황 등을 종합적으로 고려하여 계열 관계를 밝혀낸 최초의 사례"라고 강조했다.김 창업회장의 검찰 고발에 따라 DB그룹 주요 계열사의 경영차질은 불가피 할 전망이다. 공교룝게도 국세청은 DB그룹의 핵심계열사인 DB하이텍을 상대로 비정기(특별) 세무조사를 진행하고 있다. 단순 회계 문제가 아닌 그룹 차원의 부당 거래에 초점을 맞추고 있을 가능성이 크다. 뿐만아니라 차세대 반도체 공정을 건설을 위해 추진중인 동부하이텍의 정책자금 확보도 순탄치 않을 것이란 관측이 나온다. 오너리스크가 있는 회사에 정부의 정책자금 지원에 대한 문제가 제기될 수 있다는 것이다.DB그룹은 공정위의 결정에 대해 별다른 언급은 하지 않고 있다. DB그룹 관계자는 "검찰 조사 과정에서 최대한 회사의 입장을 소명하겠다"고 말했다.', NULL, '스포츠조선', 'https://n.news.naver.com/mnews/article/076/0004378347', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_SEMI', NULL, '2026-02-25 11:33:14', 0, true, '2026-03-09 05:38:37.163613') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (454, 'JW중외제약 헴리브라, ‘피 멎는 약’이 아니다…출혈 자체를 없앤 치료 혁명', '이 기사는 2026년02월19일 08시20분에팜이데일리 프리미엄 콘텐츠로 선공개 되었습니다.[이데일리 김지완 기자] “주사 맞는 아이의 울음이 사라졌다. 피가 멎는 수준이 아니라, 출혈 자체가 사라졌다.”광고 문구가 아니다. 국제 저명 학술지에 게재된 JW중외제약(001060)의 A형 혈우병 치료제 헴리브라(성분명 에미시주맙)에 대한 연구진의 평가다.국제 학술지 ''헤모필리아''(Haemophilia)는 지난해 12월 10일 ''에미시주맙 치료를 받은 A형 혈우병 소아 환자의 치료 결과: 체계적 문헌고찰 및 메타분석''(Outcomes of Emicizumab Treatment for Haemophilia A Paediatric Patients: A Systematic Review With Meta-Analysis) 제목으로 논문을 발간했다.이 논문엔 ''콘스탄티나 볼루''(Konstantina Bolou) 그리스 아테네 국립 카포디스트리아 대학교 보건과학부 의과대학 교수, 조지 트리안타필루(George Triantafyllou) 아테네 국립 카포디스트리아 대학교 의과대학 해부학교실 교수를 비롯해 그리스 ‘아기아 소피아’ 어린이병원 혈우병센터·지혈 및 혈전증 진료부 교수들과 아테네 국립 카포디스트리아 대학교 의과대학 부속 아티콘 대학병원 영상의학과 교수 등 총 7명이 저자로 참여했다.헤모필리아는 혈우병을 비롯한 출혈성 질환과 지혈·혈전증 분야를 전문적으로 다루는 글로벌 권위 저널로, 최신 치료 전략과 임상 연구 성과를 집중 조명한다. 특히, 희귀 혈액질환 분야에서 가장 영향력 있는 학술지 중 하나로 평가받으며, 신약 임상 결과와 치료 가이드라인 논문이 꾸준히 게재되고 있다.헴리브라는 혈우병 환자의 몸속에 부족한 혈액응고 제8인자를 모방하는 혁신 신약으로 A형 혈우병 치료제 중 유일하게 기존 치료제(제8인자 제제)에 대한 내성을 가진 항체 환자와 비항체 환자 모두 사용할 수 있다.“1년에 출혈 0.5회”… 사실상 출혈이 멈췄다헴리브라는 기존 혈액응고인자(FVIII)를 정맥주사로 반복 투여하던 방식에서 벗어나, 피하주사만으로 출혈을 거의 차단하는 예방 치료가 현실이 됐다. 헴리브라는 최대 4주 1회 피하주사로 예방 효과가 지속된다.최근 발표된 대규모 메타분석 연구는 에미시주맙이 소아 혈우병 환자에게 단순한 ‘편의성 개선 치료제’가 아니라, 출혈과 생명 위협을 사실상 제거하는 질병 경과 전환 치료제임을 과학적으로 입증했다.연구진은 전 세계 18개 임상 및 실제 진료 데이터를 통합 분석해 총 720명의 소아 혈우병 A형 환자를 평가했다.분석 결과, 헴리브라 투약받은 아이들의 연간 출혈 빈도는 중앙값 0.50회로 떨어졌다. 이는 1년에 한 번 출혈이 생길까 말까 한 수준이다. 기존 혈액응고인자 치료 시대에는 매년 수십 회의 출혈이 흔했다는 점을 감안하면 사실상 질병이 완벽하게 ‘통제’된 것과 다름없다.가장 치명적인 뇌출혈은 단 한 건도 없었다.분석에 포함된 720명 전원에서 단 한 건의 뇌출혈도 발생하지 않았다. 혈우병 소아에서 뇌출혈은 사망과 영구 장애 주요 원인이다. 과거 연구들에선 영아기 뇌출혈 발생률이 일반 아이들보다 수십 배 높았다. 하지만 헴리브라 도입 이후 이 같은 공포에서 벗어날 수 있게 됐다.관절 파괴도 획기적으로 줄였다. 혈우병 환자의 삶의 질을 무너뜨리는 것은 반복적인 관절 출혈이다. 어린 시절부터 출혈이 누적되면 성인이 되기 전 이미 걷기 힘든 관절 장애가 발생한다. 이번 분석에서 관절 출혈 발생률은 5.4% 수준으로 극히 낮았다.연구진은 “헴리브라는 아이들의 관절 구조를 장기적으로 보호할 수 있는 최초의 예방 전략”이라고 평가했다.에미시주맙 예방요법을 받은 소아 A형 혈우병 환자에서 ''두개내 출혈''(ICH)이 단 한 건도 없었다. (제공=헤모필리아)면역 부작용 거의 ‘제로’… 기존 치료의 최대 약점 해결기존 혈액응고인자 치료의 가장 큰 문제는 20~30% 환자에서 항체가 생긴다는 점이었다. 항체가 생기면 치료 자체가 무력화된다. 하지만 헴리브라에서는 억제항체 발생률이 0.01% 미만, 항약물항체 역시 극소수에 불과했다연구진은 "헴리브라는 면역계가 공격할 표적 구조 자체가 없다"면서 "근본적으로 안전성이 높다"고 강조했다.임상 수치 이상의 변화도 확인됐다.부모들은 반복적인 정맥주사 공포에서 벗어났고, 아이들은 운동·학교생활·사회활동을 정상적으로 할 수 있게 됐다.연구진은 "에미시주맙은 단순히 출혈을 막는 약이 아니라, 아이들의 정상적인 성장과 삶을 회복시키는 치료"라고 높은 평가를 내렸다.대부분의 연구에서 헴리브라 예방요법을 받은 소아 A형 혈우병 환자에서 ‘FVIII 억제항체’가 새로 발생한 비율이 ''0''건이다. (제공=헤모필리아)매출 수직 상승헴리브라는 지난 2023년 5월에는 건강보험 급여 대상이 만 1세 이상의 비항체 중증 A형 혈우병 환자로 확대되면서 매출이 급성장하고 있다.헴리브라 매출액은 2023년 236억원, 2024년 489억원 지난해 726억원 순으로 급증했다. 지난해 분기별로 살펴봐도 1분기 145억원, 2분기 153억원, 3분기 200억원, 4분기 229억원 순으로 매분기 처방액이 확대되는 추세다.이 같은 헴리브라의 국내 매출 증가는 세계적인 추세와 궤를 같이 한다.헴리브라는 2018년 출시 첫해 연매출 약 2억2400만달러에 머물렀지만, 2021년에는 27억~28억달러 규모로 급성장하며 혈우병 예방 치료의 핵심 처방 약물로 자리 잡았다. 이어 2022년 매출은 41억~42억달러로 뛰며 전년 대비 수십 퍼센트 성장률을 기록했다.이어 2023년에는 로슈 기준 약 41억4700만 스위스프랑(47억달러)으로 다시 한 번 최고치를 경신했다. 헴리브라 매출은 지난 2024년 51억달러, 지난해 56억달러 순으로 증가해 세계에서 가장 많이 처방되는 이중특이항체 치료제가 됐디.헴리브라는 지난해 9월에는 세계보건기구(WHO)의 필수의약품목록(EML)과 소아용 필수의약품목록(EMLc)에 등재됐다.업계 관계자는 "헴리브라가 높은 효능에도 불구 부작용 위험을 극단적으로 낮추면서, 혈우병 A형 소아 환자 치료 패러다임이 근본적으로 바뀌고 있다"며 "기존 혈액응고인자를 정맥주사로 반복 투여하던 방식에서 벗어나, 피하주사만으로 출혈을 거의 차단하는 예방 치료가 현실이 됐다"고 말했다.연구진은 논문 말미에 "헴리브라는 소아 혈우병 치료 패러다임을 ‘출혈 감소’ 수준에서 ‘거의 완전한 출혈 예방’ 단계로 끌어올릴 수 있는 혁신 치료제"라며 "현재까지의 결과만으로도 헴리브라는 영유아 및 소아 A형 혈우병 환자에서 1차 예방 치료의 최우선 선택지"라고 목소리를 높였다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006224881', 'https://imgnews.pstatic.net/image/018/2026/02/26/0006224881_001_20260226082616163.jpg?type=w800', 'NEWS_BIO', NULL, '2026-02-26 08:22:14', 0, true, '2026-03-09 05:39:43.216553') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (432, '''美경제 성장세''에 기관 해외투자 잔액 5000억달러 첫 돌파', '2025년중 주요 기관투자가의 외화증권투자 동향2024년 말 4205.8억달러→지난해 말 5078.3억달러주요국 주가 상승·美연준 금리 인하·순투자 증가지난해 말 우리나라 주요 기관투자가의 외화증권투자 잔액이 사상 처음으로 5000억달러를 돌파했다.4일 한국은행이 발표한 ''2025년 중 주요 기관투자가의 외화증권투자 동향''에 따르면 우리나라 자산운용사·외국환은행·보험사·증권사 등 주요 기관투자가의 외화증권투자 잔액(시가 기준)은 5078억3000만달러로 전년 말 대비 872억4000만달러(20.7%) 증가했다.외화증권투자 잔액은 글로벌 주가 상승으로 순투자가 확대되며 지난해 1분기(4306억7000만달러), 2분기 4654억1000만달러, 3분기 4901억달러로 확대됐다.기관투자가별 외화증권 투자 잔액도 모두 늘었다. 자산운용사와 외국환은행의 외화증권투자 잔액은 지난해 3분기 대비 각각 152억8000만달러, 40억8000만달러 증가했고, 보험사와 증권사는 각각 8억5000만달러, 7억9000만달러 감소했다.다만 연간 단위로 살펴보면 모든 기관투자가가 외화증권 투자 잔액을 늘렸다. 자산운용사의 외화증권 투자 잔액은 2024년 말 2901억4000만달러에서 지난해 말 3582억4000만달러로 681억달러(23.5%) 증가했다.보험사는 같은 기간 94억3000만달러(14.4%) 늘어난 750억달러, 외국환은행은 59억1000만달러(12.8%) 증가한 520억2000만달러, 증권사는 38억달러(20.3%) 늘어난 225억7000만달러의 외화증권투자 잔액을 기록했다.상품별로는 외국주식이 전년 대비 660억4000만달러 증가한 2925억3000만달러를 기록했다. 외국주식은 주요국 주가 상승에 따른 평가이익에 자산운용사를 중심으로 순투자가 더해지면서 증가했다.채권도 같은 기간 189억8000만달러 증가한 1828억9000만달러, 국내기업이 해외에서 발행하는 외화표시 증권인 코리아 페이퍼가 22억2000만달러 늘어난 324억1000만달러를 기록했다. 외국채권은 미국 연방준비제도(연준·Fed)의 금리 인하 등에 따른 미 국채금리 하락으로 평가이익이 발생하고, 보험사를 중심으로 순투자가 확대되면서 증가했다. 코리아 페이퍼는 외국환은행을 중심으로 증가했다.', NULL, '아시아경제', 'https://n.news.naver.com/mnews/article/277/0005729148', 'https://imgnews.pstatic.net/image/277/2026/03/04/0005729148_001_20260304120321713.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-04 12:01:00', 0, true, '2026-03-09 05:38:58.463614') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (433, '''올빼미 공시'' 또다시 기승…감자·횡령·자본잠식 등 줄이어', '[서울=뉴시스] 최진석 기자 = 코스피가 전 거래일(6244.13)보다 78.98포인트(1.26%) 하락한 6165.15에 개장한 3일 서울 중구 하나은행 딜링룸에 코스피 시세가 보이고 있다. 코스닥 지수는 전 거래일(1192.78)보다 22.96포인트(1.92%) 내린 1169.82에 거래를 시작했다. 서울 외환시장에서 원·달러 환율은 전 거래일 주간거래 종가(1439.7원)보다 22.6원 오른 1462.3원에 출발했다. 2026.03.03. myjs@newsis.com[서울=뉴시스] 김경택 기자 = 국내 증시가 3·1절 연휴로 하루 쉬어간 가운데 지난주 휴장을 앞두고 사람들의 관심이 적은 시기에 투자자에 불리한 정보를 정보를 공개하는 이른바 ''올빼미 공시''가 기승을 부린 것으로 나타났다.3일 금융감독원 전자공시 시스템에 따르면 지난달 27일 오후 6시 이후 코스피·코스닥 통틀어 84건의 공시가 게재됐다. 이 가운데 악재성 공시가 상당수였디.실제 코스피 상장사 한컴라이프케어는 거래처와의 거래 중단 사실을 공시했다. 국가, 지자체 및 공공기관을 상대로 한 입찰 참가 자격이 3개월 제한된다는 내용으로 중단 규모는 약 852억원이다. 이는 2024년 매출액 대비 81.28%에 해당하는 규모다.엑시큐어하이트론 역시 자본잠식률이 50%를 초과했다는 내용을 공시했다. 엑시큐어하이트론의 지난해 자본금은 382억원으로 집계된 반면 자본총계는 157억원에 불과했다. 자본잠식률은 58.91%다.무상감자 및 횡령 공시도 이뤄졌다. 코스닥 상장사 형지I&C는 재무구조 개선을 위해 10대 1 무상병합 방식의 감자를 결정했다고 공시했다. 이에 따라 1주 당 액면금액 500원의 보통주 10주가 동일한 액면금액 보통주 1주로 무상병합될 예정이다.또 푸른저축은행은 100억원 규모의 전직 임원에 대한 횡령 혐의가 발생했다고 공시했다. 이에 한국거래소 코스닥시장본부는 푸른저축은행의 매매거래를 정지시켰다.실적 부진 공시도 대거 집중됐다. 페이퍼코리아, 특수건설, 톱텍, 스맥, 우듬지팜 등이 전년 대비 영업이익 적자 전환 소식을 전했고 싸이버원은 영업이익이 97.1% 감소했다는 내용의 잠정 실적을 발표하기도 했다. 아미코젠도 지난해 영업손실이 169억원을 기록해 2024년(71억원) 대비 적자폭이 크게 확대됐다고 전했다.한편, 투자자 주목도가 낮아지는 시점에 악재를 발표하는 ''올빼미 공시''는 매번 연휴 때면 등장하는 우리 증시의 고질병으로 꼽힌다.앞서 지난 설 연휴에도 계약해지, 실적 부진, 파생상품 평가손실 등 회사에 불리한 내용을 담은 공시가 연휴 직전 장 마감 후 다수 이어진 바 있다. 이에 한국거래소는 연휴 직전 장 마감 이후 공시된 내용을 연휴가 끝난 뒤 홈페이지 배너 등을 통해 다시 안내하고 있다.', NULL, '뉴시스', 'https://n.news.naver.com/mnews/article/003/0013797300', 'https://imgnews.pstatic.net/image/003/2026/03/03/NISI20260303_0021192915_web_20260303093311_20260303095715537.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-03 09:56:11', 0, true, '2026-03-09 05:38:58.463614') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (434, '최현수 제지연합회장 “AI와 데이터 활용해 경쟁력 향상시킬 것”', '안전 경영 문화 정착도 강조최현수 한국제지연합회 회장이 올해 제지업계 주요 과제로 ‘인공지능(AI) 전환’과 ‘사업장 안전관리’를 강조했다.8일 한국제지연합회는 지난 7일 서울 서초구 소재 더 리버사이드 호텔에서 ‘2026 제지·펄프업계 신년인사회’를 개최했다고 밝혔다. 정연수 아진P&P 부회장, 권택환 신대양제지 부회장, 이도균 무림그룹 사장, 한경록 한솔제지 사장, 이동열 깨끗한나라 사장, 심철식 전주페이퍼 사장, 유승환 아세아제지 사장, 문성운 페이퍼코리아 사장, 정동하 태림페이퍼 대표 등 국내 주요 제지회사 대표와 유관 단체 및 학계 관계자 100여 명이 참석했다.최현수 회장은 올해 최우선 과제로 ‘지속 가능한 성장 기반 마련’을 꼽으며 △AI와 데이터를 활용한 전 공정의 효율 극대화 △친환경 신소재 개발을 통한 종이 가치 확장 △순환경제 핵심 인프라로의 도약 △안전 경영 최우선 문화 정착을 4대 핵심 과제로 제시했다.최 회장은 “AI와 데이터를 활용해 산업 전반의 경쟁력을 끌어올리는 것이 글로벌 시장에서 살아남는 가장 확실한 해법”이라며 “원료확보부터 제조, 유통, 폐기물 재활용에 이르는 ‘전 공정의 효율을 극대화해야 한다”고 했다. 또 지난해 제지업계에서 안전사고가 발생한 것과 관련해 사업장 안전관리의 중요성도 강조했다. 최 회장은 “안전은 결코 타협할 수 없는 경영의 최우선 가치이고, ‘안전’이 회사의 경쟁력이 되는 시대가 됐다”며 “올해는 안전 보건 체계를 원점에서 재점검하고, 사업장의 문화를 정착시키는 데 만전을 기해 주시길 당부드린다”고 했다.‘2026 제지·펄프업계 신년인사회’가 지난 7일 서울 서초구 더 리버사이드 호텔에서 열렸다.  사진은 왼쪽부터 한경록 한솔제지 사장, 이도균 무림그룹 사장, 이동열 깨끗한나라 사장, 유승환 아세아제지 사장, 문성운 페이퍼코리아 사장, 심철식 전주페이퍼 사장, 최현수 제지연합회 회장, 정연수 아진P&P 부회장, 조한제 대한제지 부사장, 이경선 고려제지 부사장, 정동하 태림페이퍼 대표, 권택환 신대양제지 부회장. 한국제지연합회', NULL, '매일경제', 'https://n.news.naver.com/mnews/article/009/0005618549', 'https://imgnews.pstatic.net/image/009/2026/01/08/0005618549_001_20260108144812348.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-08 14:48:12', 0, true, '2026-03-09 05:38:58.463614') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (435, '브랜드리팩터링 "유암코 동성제약 인수 추진에 ‘단기 엑시트’ 우려"', '[이데일리 박정수 기자] 동성제약(002210)의 최대주주인 브랜드리팩터링은 9일 기업회생 절차를 밟고 있는 동성제약의 예비 인수자로 나선 연합자산관리(유암코)에 대해 단기 엑시트(투자금 회수) 가능성을 둘러싼 우려가 제기되고 있다고 지적했다.브랜드리팩터링 측은 “유암코는 부실자산 정리와 재무구조 개선을 주요 전략으로 하는 기관”이라며 “과거 STX엔진, 페이퍼코리아 등에서 재무개선 후 재매각 방식이 반복된 바 있다. 시장에서는 동성제약에 대해서도 동일한 구조가 적용될 가능성을 주목하고 있다”고 전했다.이어 “제약업계는 신약 개발, 임상, 인허가 등 중장기 연구개발(R&D) 투자가 필수적인 산업 특성을 근거로, 단기 재무개선 중심의 운영이 파이프라인 축소나 비용 감축으로 이어질 수 있다는 점을 우려하고 있다”고 강조했다.또 “동성제약은 현재 자산초과 상태이며, DIP 파이낸싱·유상증자 등으로 자력 정상화가 가능하다는 평가도 존재한다”며 “이 때문에 인가전 M&A를 통해 유암코가 인수하는 방식의 적정성에 대한 의문도 제기되고 있다”고 짚었다.아울러 “PEF 성격 기관이 단기 구조조정 중심 전략을 적용할 경우 제약사 R&D 구조와 맞지 않을 수 있다”며 “동성제약이 제2의 페이퍼코리아가 되지 않으려면 산업적 관점에서 회사를 장기적으로 성장시킬 주체가 필요하다”고 말했다.한편 유암코의 참여로 동성제약의 회생 구조는 변곡점을 맞은 상황으로, 시장은 단기 엑시트 전략이 재현될지, 혹은 중장기 정상화가 추진될지를 지켜보고 있다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006180330', 'https://imgnews.pstatic.net/image/018/2025/12/09/0006180330_001_20251209144510441.jpg?type=w800', 'NEWS_ETC', NULL, '2025-12-09 14:45:10', 0, true, '2026-03-09 05:38:58.463614') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (436, '美증시 호조 지속에 기관 해외투자 역대 최대…증가세는 ‘주춤’', '3분기 기관 외화증권투자 잔액 4902억달러올해 3분기 연속 잔액 기준 역대 최대 경신분기 증가폭 200억달러대…직전분기 증가폭比 ↓[이데일리 유준하 기자] 3분기 우리나라 주요 기관투자자의 외화증권투자가 247억달러 증가하며 잔액 기준 3분기 연속 최대치 경신을 이어갔다. 증가폭은 전분기 347억달러 대비 줄었지만, 미국 증시가 호조를 이어가면서 투자 증가세를 이어간 것으로 풀이된다.사진=로이터한국은행이 1일 발표한 ‘3분기중 주요 기관투자가의 외화증권투자 동향’에 따르면 지난 9월말 기준 주요 기관투자가의 외화증권투자 잔액은 시가 기준 4902억 1000만달러(약 719조 2361억원)를 기록하며 역대 최대치를 기록했다. 2분기 대비 246억 7000만달러 늘어나면서 전분기(347억 4000만달러) 대비 증가폭은 줄었다.외화증권투자 잔액은 글로벌 주가 상승으로 올해 1분기부터 증가세를 이어가며 역대 최대 기조를 이어가고 있다. 3분기 기관의 해외투자 증가액이 역대 최대를 기록한 배경에는 역시 미국 증시 호조 영향이다. 3분기 미국 스탠더드앤푸어스(S&P)500 지수는 8.1% 상승한 바 있다.한은은 “주요국 주가 상승과 미국 연방준비제도(Fed·연준)의 금리 인하 등의 영향으로 외국 주식과 채권에 대한 순투자가 지속됐다”면서 “평가이익 역시 늘어나면서 투자 잔액이 늘었다”고 짚었다.투자 주체별로는 자산운용사(178억 5000만달러), 보험사(33억 6000만달러), 외국환은행(14억 6000만달러), 증권사(20억 1000만달러) 등 모든 주체에서 투자잔액이 증가했다.상품별로 보면 외국주식은 191억 3000만달러 늘었다. 미국 증시 호조 등 주요국 주가 상승으로 평가이익이 발생하고, 자산운용사를 중심으로 순투자가 확대된 영향이다.한편 외국채권은 미국 연준의 금리 인하에 따른 미국채 금리 하락으로 보험사, 증권사 등의 순투자가 확대되면서 46억 6000만달러 증가했다. 거주자가 외국에서 발행하는 외화표시 증권인 코리아페이퍼는 외국환은행과 증권사를 중심으로 8억 8000만달러 늘었다.자료=한국은행', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006175153', 'https://imgnews.pstatic.net/image/018/2025/12/01/0006175153_001_20251201120114580.jpg?type=w800', 'NEWS_ETC', NULL, '2025-12-01 12:01:14', 0, true, '2026-03-09 05:38:58.463614') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (455, '전주시, 광역도시 인프라 조성 총력…''7대 역점사업'' 제시', '''MICE 복합단지 조성'' 등김칠현 전주시 광역도시기반조성 국장이 26일 신년브리핑을 통해 올해 역점 추진 정책에 대해 설명하고 있다./뉴스1(전주=뉴스1) 임충식 기자 = 전북 전주시가 올해 마이스(MICE) 복합단지 조성 등 장기 현안 사업 추진에 행정력을 집중하기로 했다. 또 인프라 확충과 주거환경 개선 등을 통해 도시경쟁력 제고에도 적극 나선다는 방침이다.김칠현 시 광역도시기반조성국장은 26일 신년 브리핑에서 이 같은 내용을 포함한 광역도시·도시개발 분야 7대 역점 시책을 소개했다.시가 역점을 둘 7대 분야는 △MICE 복합단지 조성 △민자유치와 개발 지원을 통한 상생발전 견인 △효율적 재개발 및 정주 환경 개선 △도시기능 고도화 및 핵심 개발사업 가속화 △공영개발 및 공공주택 조성 △주민복지 중심의 전주형 도시 정비 추진 △취약 주거지 개선 및 생활환경 개선이다.시는 MICE 복합단지 조성사업에 만전을 기하고, 공공기여 시설 설치를 위한 실시설계와 건설사업관리 용역을 병행하는 등 옛 대한방직 부지개발 사업도 차질 없이 준비할 계획이라고 설명했다.이와 함께 시는 지역 여건에 맞는 도시·주거 정비 기반을 마련하고, 조례 개정 등 제도 정비에도 나설 방침이다. 신속한 인허가 지원을 통한 재개발·재건축 사업에도 속도를 내기로 했다.시는 ''전주대대'' 이전 사업도 속도감 있게 추진할 계획이다. 시는 상반기 중 실시설계 검토와 보상 절차를 마무리하고, 오는 2029년 준공을 목표로 하반기엔 공사에 착수할 예정이라고 설명했다. 천마지구 도시개발사업도 실시설계 및 각종 영향평가를 추진한다는 계획이다.오는 2030년 준공을 목표로 한 전주교도소 이전·신축 사업의 경우 총사업비 조정을 위한 적정성 재검토와 실시설계 등 절차를 거쳐 오는 2027년 착공할 예정이다. 이를 위해 시는 작지마을 이주단지 조성을 연내 마무리하기로 했다.시는 공공주택 조성에도 힘을 쏟을 예정이다. 전주역세권 복합 개발사업은 현재 지구계획신청이 진행 중이다. 시는 연말까지 관련 행정절차를 마무리한 후 2027년부터 토지 보상 등 사업에 착수할 계획이다.이와 함께 시는 청년 창업인과 중기 근로자들 주거 안정을 위해 하반기에 팔복동 ''일자리 연계형 지원 주택'' 공사에 착수할 예정이라고 전했다. 이를 통해 2028년부터는 임대주택 70호를 공급한다는 계획이다.시는 또 △전주역세권 △덕진권역 △금암고 일원 △인후반촌 △팔복동 빈집 밀집 구역 등 주요 도시재생사업을 추진하고, 새뜰마을 조성 사업과 낙수정마을·견훤왕궁지구 사업 등 취약지역 주거환경 개선에도 힘쓸 예정이라고 설명했다.김 국장은 "올해를 100만 미래 광역도시 기반을 완성하는 원년으로 삼겠다"며 "대규모 도시개발과 체계적 도시 정비를 통해 100만 광역도시 실현 기반을 공고히 하고, 시민이 체감하는 성과 창출을 위해 미래지향적 도시 인프라 구축에 행정 역량을 집중하겠다"고 말했다.', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008795230', 'https://imgnews.pstatic.net/image/421/2026/02/26/0008795230_001_20260226115116123.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-26 11:50:41', 0, true, '2026-03-09 05:40:04.547682') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (952, '''닭고기 담합'' 논란…하림, 1천억원 과징금 소송 결과 주목', '공정위 "하림, 닭고기 가격 인위적 인상…소비자 폐해 상당"주주들 "김홍국 회장, 회사 과징금 손해 배상하라" 소송하림, 과징금 불복해 공정위 상대로 소송 2건"과징금 상향하거나 담합 적발 확률 높여야"[연합뉴스 자료사진](서울=연합뉴스) 김윤구 한주홍 기자 = 설탕, 밀가루에서 전분당까지 먹거리를 둘러싼 가격 담합 논란이 끊이지 않고 있다. 이재명 대통령이 담합으로 인한 식료품 물가 상승을 엄단하라고 지시하자 검찰이 수사에 나섰으며 공정거래위원회는 20년 만에 담합 업체에 ''가격 재결정 명령''을 내리는 방안까지 검토하고 있다.이런 가운데 닭고기 담합으로 공정위에서 1천억원 넘는 과징금을 부과받은 재계 30위 하림그룹이 이에 불복해 낸 2건의 소송이 주목받고 있다.공정위 "하림과 계열사 올품 등 닭고기 담합"…불복 소송중하림과 올품 등의 계열사는 지난 2022년 치킨, 닭도리탕 등에 사용하는 육계 신선육 담합 혐의로 공정위로부터 942억원의 과징금을 부과받고 이를 취소해달라며 소송을 제기했다.하림과 울품은 삼계탕용 닭고기 담합 혐의로도 지난 2021년 과징금 130억원을 부과받고 소송을 냈다.두 건 모두 서울고등법원에서 재판이 진행 중이다. 공정거래법 위반 처분에 불복하는 소송은 3심제의 예외로, 서울고법에서 시작해 대법원으로 올라간다.공정위의 육계 신선육 담합 조사 결과 하림과 올품을 비롯해 마니커 등은 지난 2005년부터 2017년까지 12년간 45차례에 걸쳐 가격 인상, 출고량 조절, 생산량 감축 등의 광범위한 담합 수단을 동원했다.공정위는 하림 등이 위법 행위로 국민 대다수가 이용하는 닭고기 가격을 인위적으로 상승시켜 소비자에 미친 폐해가 상당하다고 판단했다.하림지주 익산 본사 신사옥[하림지주 제공]도축·운반비 인상, 생산량 줄여…하림 "정부 수급조절"하림 등은 짬짜미로 도축 비용과 운반비를 인상하거나 할인 기준과 폭을 담합했다. 또 육계 신선육을 냉동 비축하는 방식으로 신선육 출고량을 줄였다.특히 닭고기 판매가격이 하락하지 않도록 생산량을 줄이기 위해 9차례에 걸쳐 3천만 마리의 병아리를 살처분하는 데도 합의했다.하림 측은 8일 닭고기 담합과 관련해 "정부의 수급 조절 정책에 따른 것"이라면서 "법원에 계류 중인 사안이라 상세하게 말할 수 없다"는 입장을 밝혔다.국내 닭고기 신선육 시장의 규모는 지난 2017년 기준 3조3천억원 수준이었다. 담합에 가담한 업체들의 시장 점유율은 77%를 웃돈다.이 가운데 1위 하림과 계열사인 올품, 한강식품을 합한 점유율은 30%에 육박했다.이들 3개 업체와 하림지주가 육계 담합으로 부과받은 과징금(942억원)은 당시 전체 16개 사업자에 대한 과징금 1천758억원의 절반을 훌쩍 넘는다.주주들 "김홍국 회장, 담합책임…손해배상 소송"하림은 닭고기 담합과 관련한 과징금 행정소송을 제기했지만, 주주들은 김홍국 하림그룹 회장을 상대로 담합 책임을 묻는 소송에 나섰다.경제개혁연대는 지난해 8월 김홍국 하림그룹 회장이 담합에 책임이 있다면서 김 회장을 상대로 회사의 과징금 손해를 배상하라는 소송을 냈다. 이 소송은 전주지법 군산지원에서 변론기일이 잡히지 않은 상태다.형사 재판도 진행 중이다.검찰은 지난 2022년 6월 하림과 울품 등 6개 회사를 공정거래법 위반 혐의로 재판에 넘겼다. 다만 피고인 측이 전문가 의견을 제출하겠다며 연기를 요청해 재판은 2024년 4월 이후 열리지 않았다."닭고기 등 제재 수준 높지 않아 담합해 이윤 올려"하림 등은 지난 2006년에도 육계 신선육 가격·출고량 담합으로 과징금을 부과받았다.제분·제당 업체들이 20년 만에 또다시 담합으로 도마 위에 오른 것과 비슷하다.이름을 밝히지 않은 한 대형로펌의 공정거래 전문 변호사는 연합뉴스와의 통화에서 "설탕과 밀가루, 닭고기는 회사 간 품질 차이가 크지 않으니 제재 수준이 높지 않다고 판단하면 담합해서 편안하게 이윤을 올리려고 하는 것"이라고 말했다.이황 고려대학교 법학전문대학원 교수는 "과징금 수준을 높여 담합의 경제적 인센티브를 제거하거나 공정위 조사 권한을 강화해 담합 적발 확률을 높이는 방법이 있을 것"이라고 제안했다.공정위는 담합을 근절하기 위해 과징금 기준을 관련 매출액의 20%에서 30%로 상향하는 방안을 추진하고 있다.ykim@yna.co.kr, juhong@yna.co.kr', NULL, '연합뉴스', 'https://n.news.naver.com/mnews/article/001/0015944334', 'https://imgnews.pstatic.net/image/001/2026/03/08/PYH2025071712090001300_P4_20260308060111083.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-08 06:01:00', 0, true, '2026-03-09 06:14:52.405129') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (953, '하림, 사외이사 ''계열사 갈아타기''…이사회 독립성 논란', '전북 익산 하림지주 사옥 /사진=하림지주하림이 오는 26일 정기주주총회에서 최대주주 하림지주의 100% 자회사인 엔에스쇼핑의 사외이사를 맡았던 인물을 새 사외이사로 선임한다. 계열사 사외이사가 임기를 마치는 시점에 또 다른 계열사의 사외이사·감사위원으로 자리를 옮기는 구조다. 그룹 안에서 사외이사직을 순환하는 모양새로 독립성 논란이 불가피할 전망이다.하림은 이번 주총 안건으로 임채언 남양공원묘원 총괄이사를 사외이사 및 감사위원으로 신규 선임하는 건을 올렸다. 임 후보자는 현재 하림지주의 100% 자회사인 엔에스쇼핑의 사외이사로 재직 중이다. 하림지주의 완전 자회사에서 사외이사 임기를 마무리하면서 같은 그룹 산하인 하림의 사외이사·감사위원으로 이동하는 것으로 풀이된다.계열사 ''돌려막기'' 논란, 법적 하자 없지만하림은 법적 문제가 없다는 입장이다. 계열사 사외이사는 상법상 ''상무에 종사하지 않는 비상무 임원''에 해당해 사외이사 결격 사유를 규정한 상법 적용 대상이 아니라는 것이다. 감사위원의 회계·재무 전문가 요건에 대해서도 "나머지 사외이사 2인이 각각 회계 및 재무 전문가에 해당하기 때문에 임 후보는 이 요건에서 자유롭다"고 덧붙였다.상법은 사외이사가 최대주주의 영향권에서 벗어나도록 여러 장치를 마련해 두고 있다. 계열사 상무 임직원 출신은 사외이사직에서 배제하고 한 회사에서 6년 이상 재임하지 못하도록 하면서 계열사 재임 기간까지 합산해 9년을 넘지 못하도록 했다. 특히 9년 합산 규정은 계열사를 옮겨 다니는 방식으로 사실상 장기 재임하는 경우를 차단하기 위한 취지다.하림 사례는 비상무 사외이사라는 이유로 결격 조항의 적용을 피했지만 계열사에서 다른 계열사로 자리를 옮기는 구조가 이런 입법 취지와 충돌하지 않느냐는 지적은 피하기 어렵다.독립성 의문은 경력에서도 나온다. 임 후보자의 이력은 함소아제약 비서실장(2020~2022년)과 남양공원묘원 총괄이사(2022년~현재)가 전부다. 하림의 핵심 사업인 식품·축산과 직접적인 연관성이 없다. 하림이 추천 사유로 "회계 및 사업 관리 분야의 심도 있는 실무 경험"을 내세웠지만 묘원 총괄이사 경력을 식품 대기업 감사위원직의 근거로 삼기엔 무리가 있다는 지적이 나온다.''지배구조 개선'' 명분 뒤에 오너 권한 강화하림은 이사의 책임 감경 조항을 새로 넣었다. 이사가 회사에 손해를 끼쳐도 최근 1년 보수의 6배(독립이사는 3배)를 초과하는 부분에 대해서는 책임을 면제한다는 내용이다. 임원 특별공로금의 지급 결정권도 이사회에서 대표이사로 넘겼다. 김 회장이 임원의 공로금을 직접 결정할 수 있는 구조가 된다.하림은 이번 정관 변경을 두고 ''지배구조 투명성 제고''를 이유로 들었다. 독립이사 비율 강화, 감사위원 분리선출 인원 확대(1명→2명) 등 외형상 개선 조치를 담은 것은 사실이다.한 지배구조 전문가는 "이사 충실의무 대상이 주주로 확대되는 만큼 이사의 책임을 완화하는 차원에서 일부 상장사들이 이사의 방어권을 강화하기 위한 정관 개정에 나서고 있다"며 "경영활동의 자율성을 보장한다는 측면이 있지만 충실의무 위반에 대해서도 책임이 제한될 여지가 있어 논란의 가능성이 존재한다"고 말했다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000080298', 'https://imgnews.pstatic.net/image/293/2026/03/04/0000080298_001_20260304174015143.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-04 17:40:15', 0, true, '2026-03-09 06:14:52.405129') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (437, '[서울데이터랩]‘페이퍼코리아’ 22.59% 폭등…실시간 상승률 1위', '12일 오전 9시 10분 페이퍼코리아(001020)가 등락률 +22.59%로 상승률 1위를 차지했다. 페이퍼코리아는 개장 직후 5분간 2,519,395주가 거래되었으며 주가는 공모가 대비 157원 오른 852원이다. 한편 페이퍼코리아의 PER은 -7.96으로 상대적으로 저평가를 받고 있을 가능성을 시사하며, ROE는 -3.35%로 수익성이 낮다고 평가된다.이어 상승률 2위 KIWOOM 미국성장기업30액티브(459790)는 현재가 20,630원으로 주가가 9.97% 상승하고 있다. 상승률 3위 솔루스첨단소재(336370)는 현재 10,040원으로 9.73% 상승하며 활발한 거래를 보이고 있다. 상승률 4위 롯데에너지머티리얼즈(020150)는 8.11% 상승하며 38,000원에 거래되고 있다. 상승률 5위 한미약품(128940)은 6.61%의 상승세를 타고 484,000원에 거래되고 있다.6위 일동제약(249420)은 현재가 28,000원으로 6.46% 상승 중이다. 7위 진원생명과학(011000)은 현재가 2,250원으로 6.13% 상승 중이다. 8위 갤럭시아에스엠(011420)은 현재가 2,085원으로 5.62% 상승 중이다. 9위 코오롱모빌리티그룹(450140)은 현재가 12,960원으로 5.62% 상승 중이다. 10위 SUN&L(002820)은 현재가 2,590원으로 5.50% 상승 중이다.이밖에도 OCI홀딩스(010060) ▲5.06%, 일동홀딩스(000230) ▲4.96%, 삼성증권(016360) ▲4.59%, HL홀딩스(060980) ▲4.52%, 솔루스첨단소재1우(33637K) ▲4.51%, 엔씨소프트(036570) ▲4.36%, 한국금융지주우(071055) ▲4.20%, KIWOOM 미국블록버스터바이오테크의약품+(483030) ▲4.15%, GS(078930) ▲4.05%, 부광약품(003000) ▲3.87% 등을 기록하며 시장에서 활발히 거래되고 있다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003590695', 'https://imgnews.pstatic.net/image/081/2025/11/12/0003590695_001_20251112091813679.png?type=w800', 'NEWS_ETC', NULL, '2025-11-12 09:18:13', 0, true, '2026-03-09 05:38:58.463614') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (438, '기업공시 [9월 30일]', '[서울경제]<코스피 공시>▲한미약품(128940)=당뇨 치료제 개발을 위한 식약처 제3상 임상시험 계획 승인 신청 ▲삼성증권(016360)=지속가능경영보고서 제출 ▲대한조선(439260)=오세아니아 지역 선주로부터 1223억 원 규모 원유운반선 1척 수주 ▲동부건설(005960)=한국토지주택공사로부터 1543억 원 규모 평택고덕 공공주택건설사업 수주 ▲KCC(002380)=교환사채(EB) 발행 등 자기주식 활용계획 철회 ▲페이퍼코리아(001020)=문성운 대표이사 신규 선임<코스닥 공시>▲오픈엣지테크놀로지(394280)=해외 기업으로부터 20억 원 규모 반도체 설계자산(IP) 라이선스 계약 체결 ▲위드텍(348350)=삼성전자로부터 124억 원 규모 산업배출가스측정 유지보수업무 위탁계약 체결 ▲유니테크노(241690)=기업가치 제고 계획 공개 ▲티앤엘(340570)=10월 15일 주주총회 소집공고 ▲엑셀세라퓨틱스(373110)=유상증자 1차 발행가액 1880원', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004539436', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2025-09-30 15:14:14', 0, true, '2026-03-09 05:38:58.463614') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (439, '페이퍼코리아, 문성운 신임 대표이사 선임…"부동산개발 마무리 최선"', '문성운 페이퍼코리아 대표이사.(페이퍼코리아 제공. 재판매 및 DB금지)(군산=뉴스1) 김재수 기자 = 문성운 페이퍼코리아 구매물류본부장(58)이 30일 페이퍼코리아 대표이사로 선임됐다.페이퍼코리아는 이날 임시주주총회를 열고 문성운 구매물류본부장을 대표이사로 선임했다고 밝혔다.문 신임 대표이사는 군산제일고와 전북대 무역학과를 졸업했으며, 1993년 페이퍼코리아에 입사해 구매팀장을 거쳐 구매물류본부장까지 역임했다.문 대표는 "과거의 방식에 머무르지 않고 새로운 아이디어와 시도를 통해 다른 결과를 만들어 낼 수 있도록 하겠다"며 "창사 이래 지난 80년이 넘는 세월 동안 수많은 어려움을 극복해 왔듯이 본업인 제지업은 물론, 공장 이전으로 진행 중인 부동산개발사업이 잘 마무리될 수 있도록 임직원들과 역량을 모아 나가겠다"고 포부를 밝혔다.', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008518090', 'https://imgnews.pstatic.net/image/421/2025/09/30/0008518090_001_20250930125510119.jpg?type=w800', 'NEWS_ETC', NULL, '2025-09-30 12:54:46', 0, true, '2026-03-09 05:38:58.463614') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (440, '미국 증시 호조에…기관 해외증권 투자 348억달러↑', '[연합뉴스 제공]올해 2분기 자산운용사, 증권사 등 국내 민간 기관투자자들의 해외 증권 투자 잔액이 3개월 만에 350억달러 가까이 상승했습니다.오늘(29일) 한국은행 발표에 따르면 자산운용사·보험사·증권사 등 국내 기관투자자의 외화증권 투자 잔액은 6월 말 기준 4,655억3천만달러로 집계됐습니다.2분기 증가 규모는 348억달러로 분기 기준 사상 최대치를 나타냈습니다.미국 증시 호조와 금리 인하 기대 속에 주식·채권 순투자가 늘고 평가이익도 확대된 영향입니다.상품별로는 외국주식이 242억9천만달러 늘며 2,571억6천만달러를 기록했습니다.외국채권도 91억9천만달러 증가했고, 코리아페이퍼는 12억8천만달러 늘었습니다.기관별로는 자산운용사가 274억1천만달러 늘어난 3,251억1천만달러를 기록해 잔액과 증가 폭 모두 최대치를 보였습니다.보험사(+43억5천만달러)와 증권사(+20억9천만달러), 외국환은행(+9억2천만달러)도 모두 증가했습니다.한은 관계자는 “미국 증시 호조에 외화증권 잔액과 자산운용사, 외국주식에서 모두 역대 최대치를 기록했다”며 “거래 요인보다는 평가이익 같은 비거래 요인의 영향이 더 컸다”고 설명했습니다.#한국은행 #자산운용사 #증권사 #기관투자자 #외국주식연합뉴스TV 기사문의 및 제보 : 카톡/라인 jebo23', NULL, '연합뉴스TV', 'https://n.news.naver.com/mnews/article/422/0000775765', 'https://imgnews.pstatic.net/image/422/2025/08/29/AKR20250829142635628_01_i_20250829142711440.jpg?type=w800', 'NEWS_ETC', NULL, '2025-08-29 14:27:11', 0, true, '2026-03-09 05:38:58.463614') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (441, '[비즈톡톡] 팔아버린 ‘이노엔’은 1조 클럽, 품에 안은 ‘천랩’은 10년 적자… CJ의 엇갈린 희비', 'CJ그룹이 매각한 HK이노엔은 매출 1조 클럽 가입3년 뒤 인수한 CJ바이오사이언스는 만년 적자재무 관리하는 경영리더 사내이사로 선임하고 성장 도모마이크로바이옴 치료제 기술 이전하며 수익성 개선해야그래픽=정서희CJ그룹의 손길을 거친 두 회사의 성적표가 극명하게 엇갈리고 있습니다. CJ가 매각한 HK이노엔(당시 CJ헬스케어)은 매출 ‘1조 클럽’에 진입했습니다. 이후 인수한 CJ바이오사이언스(천랩)는 적자를 벗어나지 못하고 있는데요. 두 회사는 어디서부터 희비가 엇갈리게 됐을까요.CJ제일제당은 1984년 유풍제약을 인수하며 제약 사업에 뛰어들었고 2006년 한일약품을 인수하며 전문 의약품을 강화했습니다. CJ제일제당은 연구개발 역량을 강화하기 위해 2014년 제약 사업을 분사, CJ헬스케어를 출범시켰습니다. CJ헬스케어는 2018년 한국콜마에 1조3100억원에 매각했는데요.이후 CJ제일제당은 2021년 마이크로바이옴을 연구하는 천랩을 983억원에 인수하며 바이오 사업에 대한 의지를 다시 한번 다졌습니다. 이후 천랩과 CJ제일제당의 레드 바이오(의료·제약) 사업 부문을 합쳐 CJ바이오사이언스를 출범시켰는데요.CJ바이오사이언스는 마이크로바이옴으로 항암제 등을 개발하고 있습니다. 마이크로바이옴은 미생물을 의미하는 마이크로브(microbe)와 생태계(biome)를 뜻하는 바이옴의 합성어입니다. 우리 몸에 사는 미생물을 기반으로 각종 치료제를 개발하는 게 목표인데요.공교롭게도 두 회사의 실적은 엇갈리고 있습니다. CJ바이오사이언스는 CJ제일제당이 인수한 뒤 아직 뚜렷한 성과를 내진 못하고 있습니다. CJ바이오사이언스는 지난 2014년부터 지난해까지 영업이익을 낸 적이 없는데요. 지난해 3분기 연결 기준 누적 매출은 24억원으로 전년 동기 대비 4% 줄었고 영업손실은 196억원을 기록했습니다. 연구개발비 138억원을 투입하며 적자가 났다고 합니다.회사의 가장 시급한 과제는 수익성 개선입니다. 현재 대표적인 파이프라인(신약 후보군)은 비소세포폐암, 두경부암 등을 치료하는 항암제 후보 물질 CJRB-101, 염증성 장 질환 치료제 후보 물질 CJRB-201 등이 있습니다. 항암제 후보 물질은 임상 중이고 염증성 장 질환 치료제 후보 물질은 비임상 단계인데요.CJ바이오사이언스 관계자는 “신약 개발 과정에서 연구개발비가 투입됐다”면서 “치료제 후보 물질 기술 이전을 검토하고 있다”고 했습니다. 그러면서 “고기능성 프로바이오틱스 사업으로 포트폴리오를 확대하고 헬스·웰니스 기업으로 도약하는 것을 목표로 하고 있다”고 하는데요.CJ바이오사이언스는 오는 26일 주주총회를 거쳐 이사회를 재편하고 수익성 강화를 도모한다는 계획입니다. 현재 CJ바이오사이언스 사내이사는 윤상배 대표, 최임재 경영리더 2명이 있는데요. 최 리더가 주주총회 이후 사임하게 되며 사내이사 자리를 오귀흥 경영리더로 채울 예정입니다.오 리더는 1999년 12월 CJ제일제당에 입사해 2020년 바이오 사업 관리 담당 상무에 올랐는데요. 화이트 바이오(바이오 소재) 재무 전략(Corporate Finance) 경영 리더를 거쳐 지난해 7월 CJ바이오사이언스에 합류했습니다. 현재 회사에서 재무 등 사업 관리를 담당하고 있는데요. 이사회에 진입한 뒤 수익성 강화에 주력할 것이라는 전망이 나옵니다. 회사 측은 “성장을 이끌 적임자로 판단했다”고 하는데요.반면 CJ그룹을 떠난 HK이노엔은 매출이 고공행진하고 있습니다. HK이노엔의 지난해 연결 매출은 1조632억원으로 전년 대비 19% 증가했습니다. 영업이익은 1109억원으로 26% 늘었는데요. HK이노엔은 매각 이듬해인 2019년 3세대 위장약 ‘케이캡’을 선보이며 시장 지배력을 빠르게 확대했습니다. 케이캡은 빠른 약효와 야간 속 쓰림 개선 효과가 특징인데요. 최근에는 미국 식품의약국(FDA)에 케이캡 품목 허가를 신청하며 해외 무대 확장을 꾀하고 있습니다.업계 관계자는 “CJ그룹이 매각한 회사는 실적이 좋아진 반면 인수한 회사는 부진한 분위기”라면서 “두 회사가 극과 극으로 갈렸다”고 하는데요. 두 회사의 미래가 어떻게 될지 제약·바이오 업계가 주목하고 있습니다.', NULL, '조선비즈', 'https://n.news.naver.com/mnews/article/366/0001146767', 'https://imgnews.pstatic.net/image/366/2026/03/09/0001146767_001_20260309060229167.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 06:02:29', 0, true, '2026-03-09 05:39:23.109066') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (456, '"자광, ''옛 대한방직 부지 개발'' 실행력 부족…전주시, 승인 취소해야"', '민노총·전주시민회·정의당·진보당, 주택사업계획 취소 촉구민주노총 전북본부와 전주시민회 등은 25일 전주시청에서 기자회견을 갖고 자광의 옛 대한방직 부지개발사업에 대한 사업계획 승인 취소를 촉구했다./뉴스1(전주=뉴스1) 임충식 기자 = 전북 전주지역 시민 노동단체가 현재 ''자광''이 추진 중인 옛 대한방직 부지개발 사업에 대한 사업계획 승인 취소를 촉구하고 나섰다.민주노총 전북본부와 전주시민회 등은 25일 전주시청에서 회견을 열아 "''자광''이 옛 대한방직 부지 개발사업을 실행하기에는 역량이 부족한 기업이라는 사실을 드러나고 있다"면서 "시는 주택건설 사업계획 승인을 취소해야 한다"고 밝혔다.이날 회견에는 진보당과 정의당 시 지역위원회 관계자들도 참석했다.이들은 "자광은 지난해 9월 주택건설 사업계획 승인을 받았음에도 지금까지 사업을 맡을 시공사를 구하지 못하고 있다"면서 "게다가 최근 재산세와 공유재산 임대료, 변상금도 체불하고 있는 사실도 드러났다"고 지적했다.이들은 "재산세와 임대료 변상금 등 11억 원을 체납한 자광이 6조 4000억 원대에 이르는 부지개발 사업을 실행하기 어렵다는 것은 삼척동자도 알 수 있다"면서 "시는 당장 자광의 주택건설 사업계획을 취소하고 시민을 우롱한 행위에 대해 사죄해야 한다. 해당 토지 공매를 통해 세금과 임대료 변상금을 징수해야 한다"고 촉구했다.자광은 옛 대한방직 부지(23만 565㎡)에 대한 개발사업(전주 관광 타워복합개발 사업)을 추진 중이다. 주요 개발 계획은 △관광 전망 타워 건설(470m) △200실 규모 호텔(8층) △복합쇼핑물 △고품격 주상복합아파트 3536세대 △문화공원 및 공개공지 조성(8만㎡) △지하차도 조성 △교량 확장 및 신설 △주변 도로 확충 △녹지조성 등이다.이에 따른 총사업비는 6조 원이며, 완공 목표 시점은 2030년이다. 자광이 전주시와 협약을 통해 정한 공공기여량(계획 이득 환수) 규모는 3855억 원이다.', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008792664', 'https://imgnews.pstatic.net/image/421/2026/02/25/0008792664_001_20260225135414256.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-25 13:53:48', 0, true, '2026-03-09 05:40:04.547682') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (442, '봄동이 동이 날 지경…제철 채소 열풍에 봄·봄·봄 바람', '봄동·미나리 등 제철 식재료 유행지난 4일 서울의 한 시장에서 봄동을 고르는 시민. 연합뉴스특정 계절에만 맛볼 수 있는 먹거리를 찾는 소비 흐름이 최근 들어 더욱 뚜렷해지면서 식품업계의 상품 기획에도 영향을 주고 있다. 특히 봄동에 대한 소비자의 관심이 높아지면서 이를 활용한 업계의 홍보활동도 활발해지는 분위기다.대상의 김치 브랜드인 종가가 지난 1월7일 계절 한정으로 출시한 ‘봄동 겉절이’는 2월28일까지 약 두 달간 누적 판매량 2만개를 돌파했다. 중량으로 환산하면 약 22톤 규모다. 한국방송(KBS) 예능 프로그램 ‘1박2일’에서 과거 출연자가 봄동 겉절이에 밥과 달걀프라이, 참기름을 비벼 먹는 장면이 최근 소셜미디어에서 다시 화제가 되면서 관련 수요가 늘어난 것으로 풀이된다.회사 관계자는 “젊은 층을 중심으로 겉절이 등 별미 김치 수요가 늘면서 지난해 여름 ‘오이나박물김치’를, 이번 겨울엔 ‘봄동겉절이’를 기획했는데 이번 제품은 이전보다 훨씬 빠른 속도로 판매량이 늘고 있다”고 말했다. 샘표 역시 봄동비빔밤이 화제가 되자 지난 2일까지 ‘새미네 부엌 김치양념 1+1’ 기획전을 진행하기도 했다.외식업계도 제철 음식 수요를 공략하고 있다. 본아이에프의 도시락 브랜드 본도시락은 냉이를 활용해 ‘봄 냉이 무침’이 포함된 봄철 메뉴 4종을 지난 4일 출시했다. 씨제이(CJ)제일제당 역시 미나리와 바지락을 활용한 봄 계절 메뉴 2종을 5일 선보였다.대형마트와 이커머스 기업 등 유통업계도 제철 식재료 수요를 겨냥한 행사 중이다. 컬리는 오는 9일까지 두릅·달래·냉이·돌나물 등 제철 나물과 봄나물 비빔밥 등 밀키트를 선보인다. 업계는 제철 코어 흐름이 지속할 것으로 전망하면서, 계절 식재료를 활용한 상품 출시와 할인 행사도 계속될 것으로 보고 있다.', NULL, '한겨레', 'https://n.news.naver.com/mnews/article/028/0002794834', 'https://imgnews.pstatic.net/image/028/2026/03/08/0002794834_001_20260308165411034.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-08 15:06:07', 0, true, '2026-03-09 05:39:23.109066') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (443, 'CJ·상미당 ''백기''…농심·롯데는 버티기?', '[앵커]이재명 대통령이 물가 관리에 고삐를 죄면서 설탕과 밀가루 업계에 이어 제빵업계도 백기를 들었죠.하지만 정부는 부족하다는듯 업계를 돌아가면서 만나는 등 압박을 이어가고 있습니다.이에 과자와 라면 등의 업계는 노심초사하면서도 가격 인하에 있어선 아직까지 신중한 입장입니다.정대한 기자와 나와 있습니다.우선 제빵업계가 백기를 들었죠?[기자]네 상미당홀딩스, 구 SPC그룹이 운영하는 파리바게뜨와 CJ푸드빌이 운영하는 뚜레쥬르가 다음 달부터 빵과 케이크 등 주요 제품을 인하하기로 결정했습니다.두 업체는 구체적으로 다음 달 13일부터 단팥빵 등 빵류 가격을 최대 1천100원, 케이크는 최대 1만 원 낮출 계획인데요.베이커리 업계 1위와 2위가 함께 가격을 내리면서 다른 기업들로도 가격 인하 움직임이 확산될 것이라는 전망이 나옵니다.특히, 이재명 대통령이 직접 비싼 빵값을 지적한 이후로 이 같은 인하 결정이 나오면서 정부의 물가 안정 기조가 먹혀들었다는 평가가 나옵니다.[이재명 / 대통령(지난달 5일) : 실제 조사를 해보니까 우리나라 빵값이 다른 나라에 비해서 엄청 비싸다고 하는데 그게 밀가루·설탕값 때문이 아니냐 전부는 아니겠지만 일부 그런 요소도 있는 것 같습니다.][앵커]실제로 빵값 인하에는 밀가루와 설탕값 인하가 꽤 역할을 했죠?[기자]두 업체가 가격 인하에 나서게 된 건 주재료로 사용하고 있는 설탕과 밀가루 가격이 떨어진 영향이 큰데요.구체적으로 삼양사와 사조동아원은 제품 가격을 각각 평균 최대 6%가량 인하했고, 대한제분도 일부 밀가루 가격을 5% 가까이 낮췄습니다.특히, CJ제일제당은 지난 1월 밀가루 가격을 평균 최대 5.5% 내린 데 이어 지난달 26일에는 소비자용 밀가루 가격을 5% 추가로 인하했습니다.공정위에 따르면 정부의 물가 대응 이후 설탕은 16% 넘게, 밀가루는 8%가량 인하됐고, 전분당은 16.7% 수준의 가격 인하가 이뤄졌습니다.[앵커]그러면 밀가루와 설탕값이 내려가는 데까지는 어떤 일들이 있었습니까?[기자]공정위가 담합 의혹 조사에 착수한 게 결정적이었습니다.공정위는 CJ제일제당과 대한제분 등 7개 제분사가 지난 2019년부터 작년까지 밀가루 판매가 등을 밀약한 혐의를 조만간 전원회의에서 심의할 예정입니다.앞서 공정위는 지난달 12일 CJ제일제당 등 3개 제당사가 설탕 가격을 담합한 행위에 대해 총 4천83억 원의 과징금을 부과한 바 있는데요.밀가루도 담합했다는 판단이 나오면 업체들은 최대 1조 1천600억 원 규모의 과징금을 부과받을 수 있습니다.공정위는 각 제분사가 자발적으로 가격을 다시 정하도록 하는 가격 재결정 명령을 내려달라는 의견도 냈습니다.[앵커]공정위 뿐 아니라 식품 물가 관리 주무부처도 분주하던데, 이쪽 움직임은 어떻습니까?[기자]농림축산식품부는 주요 식품업계와 만나 회의를 열고 물가 안정 기조에 동참할 것을 당부했습니다.4일엔 CJ제일제당과 대상 등 식용유 업체들이 참석했고, 5일엔 농심 등 라면 업체들이 참여했는데요.지난달 제분·제당 업계의 가격 인하 이후 가공식품 물가를 관리하는 농식품부가 업계와 관련 회의를 여는 것은 이번이 처음입니다.지난주에는 공정위도 주병기 위원장 주재로 교촌, 롯데GRS 등 7개 외식기업과 회의를 열고 외식 가격 인하를 독려하는 등 정부가 업계 전반에 물가 안정을 촉구하는 상황입니다.[앵커]가공식품의 주재료인 밀가루와 설탕 가격이 떨어졌고 그래서 빵값은 내렸는데, 다른 식품들은 어떻습니까?[기자]라면과 과자 등의 업체들도 가격 인하를 고심하고는 있지만, 상당수는 아직 신중한 입장을 보이고 있는데요.업계 추정치에 따르면 라면 원가 비중은 밀가루가 20% 수준이고, 팜유가 20%, 포장재가 20~25%, 물류비 등 기타 비용으로 이뤄져 있습니다.밀가루 가격은 인하됐더라도 팜유 등 다른 재료 가격이나 환율 등 다른 비용이 상승한 만큼 당장 가격을 내리기엔 난처하다는 겁니다.그나마 라면업계 중 오뚜기는 아직 확정은 아니지만, 가격 인하를 검토하고 있다고 밝힌 가운데, 팔도 측은 소비자 부담을 완화하기 위해 다양한 방안을 고민하고 있다고 밝혔고요.업계 1위인 농심은 원자재 품목별 가격 변동과 국제 유가, 환율 등 고려해야 할 변수가 많다는 입장입니다.과자업계 중 롯데웰푸드나 오리온 등 제과 기업들은 아직 관련 입장을 내놓지 않았는데요.다만，가격 인하를 고려 중인 오뚜기의 경우엔 작년 영업이익이 18.9% 하락할 것으로 전망되지만, 가격 인하에 신중한 모습을 보이고 있는 농심과 삼양식품 등의 경우엔 지난해 영업이익이 두 자릿수 성장한 것으로 예측되고 있어 인하 여력이 충분하다는 지적도 나옵니다.[이은희 / 인하대 소비자학과 교수 : 식품회사 같은 경우에는 영업이익이 해마다 우상향으로 증가하는 통계치를 내놓고 있어요. 물가 때문에 고생하는 국민들을 생각해서 물가를 내릴 수 있는 방안을 다각도로 좀 고민해 주시는 것이 필요하다…][앵커]실제로 식품업계가 설명하는 것처럼 비용 부담이 큰 상황인가요?[기자]우선 매출 중 얼마나 제조원가로 투입되는지를 나타내는 매출원가율을 보면요.지난해 3분기 기준으로 롯데웰푸드가 전년 동기 대비 2.5% 포인트(p) 오르면서 약 72%를 기록했고, 오리온도 2.2% 포인트 상승한 63.4%, 오뚜기도 84% 가까이 올랐습니다.최근 고환율과 원재료 가격 상승에 따라 원가 부담이 높아진 것으로 해석할 수 있는데요.영업이익률도 보면 롯데웰푸드는 지난해 2.6%, 오뚜기는 4.8%로 한자릿수에 그치고 있습니다.여기에 최근 미국과 이란의 군사 충돌에 따른 고환율과 유가상승이 추가로 물류비 부담을 늘릴 것으로 전망되고 있는데요.이에 식품업계들이 실제로 가격을 인하할 여력이 제한적이라는 지적도 나옵니다.[정연승 / 단국대 경영학부 교수] 원재료 이외에도 다른 원재료들이 있고 또 물류비라든지 중동발 (리스크 등) 여러 가지 영향들이 있기 때문에 가격 인하는 점진적으로, 그리고 아주 제한적으로 서서히 진행될 수밖에 없다…][앵커]내수가 주춤한 데다 정부 압박도 거세지다 보니 식품업계가 국내 대신 해외로 눈을 돌리고 있죠?[기자]식품업계는 국내 시장이 소비 심리 위축에다가 정부의 물가 안정 기조로 가격 인상 여력도 제한적인 만큼 최근 해외시장 확대에 사활을 걸고 있는데요.전체 매출의 약 80%가 해외에서 발생하고 있는 삼양식품은 지난해 영업이익이 전년 대비 50% 넘게 급증했고, 매출은 사상 처음으로 2조 원을 넘어섰습니다.해외매출 비중을 40% 수준으로 끌어올린 농심도 지난해 영업이익이 약 16% 증가할 것으로 전망되고 있는 가운데, 오는 2030년까지 해외 매출 비중을 61%까지 끌어올리겠다는 목표를 세웠습니다.당신의 제보가 뉴스로 만들어집니다.SBS Biz는 여러분의 제보를 기다리고 있습니다.홈페이지 = https://url.kr/9pghjn', NULL, 'SBS Biz', 'https://n.news.naver.com/mnews/article/374/0000496409', 'https://imgnews.pstatic.net/image/374/2026/03/07/0000496409_001_20260307163711100.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-07 08:01:11', 0, true, '2026-03-09 05:39:23.109066') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (444, '이미경 CJ그룹 부회장, ''세계 영화계에 영감 준 리더''로 지목', '아카데미영화박물관장, 이 부회장 리더십 극찬이미경 CJ그룹 부회장이 글로벌 영화계에 영감을 준 리더로 지목됐다.CJ ENM은 에이미 홈마 아카데미영화박물관 관장이 최근 인터뷰에서 이 부회장을 직접 언급하며 리더십을 높이 평가했다고 6일 밝혔다.홈마 관장은 "이 부회장은 사람과 사람을 연결해 공동체를 만들어내는 탁월한 역량을 지니고 있다"며 "글로벌 비전과 한국 영화에 대한 아낌없는 지원으로 엔터테인먼트 산업의 지형을 넓혀가고 있다"고 밝혔다.이미경 CJ그룹 부회장이 부회장은 아시아 우수 창작자들이 할리우드에서 꿈을 펼칠 수 있도록 가교 역할을 해왔다. 2019년 아카데미영화박물관 이사진으로 선임된 이후 할리우드 핵심 문화기관 내에서 주도적인 역할을 수행했다. 최근엔 글로벌 레이블 ''퍼스트 라이트 스토리하우스''를 출범해 아시아계 창작자와 아시아 스토리 기반 콘텐츠를 지원하고 있다.지난해엔 아카데미영화박물관과 CJ ENM 간 3개년 공식 파트너십을 체결해 첫 협력 프로젝트로 봉준호 감독 특별전 ''Director''s Inspiration: Bong Joon Ho''를 진행중이다.CJ ENM은 "이 부회장의 행보는 단순한 기업 후원을 넘어 아시아 창작자들이 글로벌 영화 생태계의 주류로 진입할 수 있는 길을 마련했다"며 "(홈마 관장의 언급으로) 한국을 넘어 미국 문화 엔터테인먼트 커뮤니티에서도 존경받는 이 부회장의 리더로서의 위상이 뚜렷하게 드러났다"고 밝혔다.', NULL, '지디넷코리아', 'https://n.news.naver.com/mnews/article/092/0002413275', 'https://imgnews.pstatic.net/image/092/2026/03/06/0002413275_001_20260306172213165.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-06 17:22:13', 0, true, '2026-03-09 05:39:23.109066') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (445, '공정위, 7년간 6.2조 ‘전분당 담합’ 심의 착수…“가격 재결정 명령·고발”', '게티이미지뱅크공정거래위원회가 6조2천억원대의 전분당 담합 의혹과 관련해 가격 재결정 명령 등의 제재를 내릴지 심의에 착수했다.공정위 사무처는 4개 전분당 제조·판매 사업자들의 담합 의혹에 대해 제재 의견을 담은 심사보고서(검찰의 공소장에 해당)를 해당 업체들에 보내고 위원회에 제출해 심의 절차가 개시됐다고 5일 밝혔다. 4개 업체는 씨제이(CJ)제일제당, 대상, 사조씨피케이(CPK), 삼양사다.공정위 심사관은 이들 업체가 2018년 5월부터 2025년 10월까지 7년6개월에 걸쳐 반복적·조직적으로 전분당 판매가격을 담합했다고 판단했다. 담합행위에 영향을 받은 관련 매출액은 6조2천억원에 이르는 것으로 산정했다.전분당의 주원료는 옥수수 전분으로 물엿, 포도당, 액상과당 등이 전분당에 해당한다. 용도에 따라 면류, 제과 등 식품의 원료로 쓰이거나 제지·철강 등 산업에서 접착·코팅 용도로 사용된다.심사관은 이런 행위가 공정거래법(가격 담합 금지)에 어긋난다며 시정명령과 과징금을 부과하고, 관련 임직원을 고발해야 한다는 의견을 제시했다. 과징금은 관련 매출액의 최대 20%까지 부과할 수 있다. 공정위는 앞서 지난달 검찰이 같은 혐의로 고발을 요청한 4개 법인에 대해서는 이미 고발했다고 밝혔다.특히 시정명령에는 이재명 대통령이 최근 필요성을 언급한 가격 재결정 명령이 포함됐다. 가격 재결정 명령은 담합으로 형성된 가격을 각 기업이 적정한 수준으로 다시 정하도록 하는 조처다. 유성욱 공정위 조사관리관은 “(전분당 업체들이) 심의일 이전에 가격을 3~5% 인하했다는 보도가 있기는 했지만, 이것이 적정한 가격 인하 폭인지 등도 고려해 결정할 것”이라고 말했다.앞서 공정위는 2006년 밀가루 담합에 대해 가격 재결정 명령을 내린 바 있다. 이후 공정위는 한동안 가격 재결정 명령을 꺼내 들지 않다가, 최근 연이어 심사보고서에 가격 재결정 명령을 담았다. 한솔제지와 무림페이퍼 등 6개 제지업체의 인쇄용지 담합, 씨제이(CJ)제일제당과 대한제분 등 7개 제분업체의 밀가루 담합에 이어 이번 전분당 담합까지 세 건이다. 이 같은 심사관 의견이 최종 확정될 경우 20년 만에 다시 가격 재결정 명령이 내려지게 된다.아울러 공정위는 전분당 업체들의 전분당 가격 담합행위 외에 일부 실수요처에 대한 입찰 담합행위와 전분당 부산물 가격 담합행위에 대해서도 조사 중이라고 밝혔다. 전분당 부산물은 옥수수 분쇄 과정에서 발생하는 글루텐피, 배아, 섬유질 등으로 대부분 사료용으로 쓰인다.최종 제재 여부와 수준은 업체들의 의견서를 받은 뒤 전원회의를 열어 결정하게 된다. 업체들은 심사보고서 수령일로부터 8주 내 의견을 제출해야 한다. 공정위는 “전분당 담합 사건이 민생물가와 직결된 중대 사안인 만큼, 방어권 보장 절차가 종료되는 대로 최대한 신속하게 위원회를 개최해 최종 판단을 내릴 계획”이라고 밝혔다.', NULL, '한겨레', 'https://n.news.naver.com/mnews/article/028/0002794663', 'https://imgnews.pstatic.net/image/028/2026/03/06/0002794663_001_20260306141611045.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-06 14:06:13', 0, true, '2026-03-09 05:39:23.109066') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (446, 'CJ제일제당, 대표 직속 ''미래혁신사무국'' 신설', 'CJ제일제당이 대표이사 직속 혁신 조직을 신설하며 전사적 체질 개선에 나섰다.5일 업계에 따르면 CJ제일제당은 최근 대표이사 직속 ''미래혁신사무국''을 신설했다. 조직은 최고재무책임자(CFO)와 식품·바이오 사업 관리, 재무, 인사 등 임원급 13명으로 구성된 것으로 알려졌다. 회사 전략과 자원 배분을 전면 재검토하는 컨트롤타워 역할을 맡는다.기사의 이해를 돕기 위한 생성형AI 이미지업계는 이번 조직 신설에 대해 최근 이어진 성장 정체와 각종 대외 변수에 대응하기 위한 조치로 보고 있다. CJ제일제당은 지난해 2007년 CJ주식회사에서 제조 사업 부문이 인적 분할된 이후 처음으로 순손실을 기록했다. 최근 설탕 담합과 관련해 공정거래위원회로부터 1506억원 과징금을 부과받으며 경영상 부담도 커졌다.미래혁신사무국은 전 사업 부문의 효율성을 점검하고 비핵심 자산 유동화, 신사업 개편, 조직 문화 혁신 등을 포함해 회사 전반을 들여다볼 것으로 알려졌다.윤희석 기자 pioneer@etnews.com', NULL, '전자신문', 'https://n.news.naver.com/mnews/article/030/0003404831', 'https://imgnews.pstatic.net/image/030/2026/03/05/0003404831_001_20260305191615546.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-05 19:16:15', 0, true, '2026-03-09 05:39:23.109066') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (447, 'JW중외제약 ''제이클'' 심포지엄, 대장정결제 임상 데이터 공유', '대한위대장내시경학회 춘계학술대회서 임상 3상 결과 발표JW중외제약은 지난 8일 서울 소공동 소재 롯데호텔서울에서 열린 대한위대장내시경학회 제47회 춘계학술대회에서 대장정결제 ‘제이클’ 심포지엄 행사 모습. JW중외제약 제공[파이낸셜뉴스] JW중외제약은 지난 8일 서울 소공동 롯데호텔서울에서 열린 대한위대장내시경학회 제47회 춘계학술대회에서 대장정결제 ‘제이클’ 관련 심포지엄을 개최했다고 9일 밝혔다.이번 심포지엄에서는 양산부산대학교병원 소화기내과 박수범 교수가 연자로 참여해 제이클의 임상 3상 연구 결과와 대장내시경 검사 전처치 과정에서의 임상적 활용 방안 등을 발표했다.제이클은 대장내시경이나 X선 촬영 등 검사 전 장을 세척하기 위해 복용하는 전문의약품이다. 총 복용량이 20정으로 상대적으로 적고 필름코팅 정제 형태로 제작돼 삼킴이 용이한 점이 특징이다.기존 대장정결제는 산제 또는 액상 제형이 주로 사용되며 복용 과정에서 구역이나 두통 등 이상반응이 발생해 환자 부담이 크다는 지적이 있었다. 이러한 불편함은 검사 전 처치 과정의 순응도를 낮추고 결과적으로 검사 정확도에 영향을 줄 수 있다는 평가도 있다.제이클은 이러한 한계를 개선하기 위해 정제형 제형을 적용해 복용 편의성을 높였다. 주요 성분은 삼투성 하제로 작용하는 마그네슘설페이트, 포타슘설페이트, 소듐설페이트와 장내 거품을 제거하는 시메티콘, 장 연동운동을 촉진하는 소듐피코설페이트 등으로 구성됐다.박 교수는 강연에서 임상 3상 연구 결과를 바탕으로 제이클의 장 정결 효과와 안전성, 복약 순응도 측면의 특징을 설명했다.임상 결과에 따르면 장 정결 효과는 헤어필드(Harefield) 정결도 척도(HCS) 기준에서 대조군 대비 통계적으로 유의미한 차이를 보이지 않아 동등한 수준을 확인했다. 또한 대장내시경 검사에서의 용종 및 선종 발견율 역시 대조군과 유사한 결과를 나타냈다.안전성 측면에서는 일부 이상반응 발생률이 낮게 나타났다. 임상 3상 연구에서 구역 발생률은 대조군 21.7%에 비해 제이클 정은 7.62%로 낮았고, 두통 발생률 역시 대조군 8.49% 대비 제이클 정은 0.95%로 나타났다.박 교수는 “제이클은 시메티콘 성분이 포함돼 있어 장내 거품이 거의 없어 검사 과정에서 시야 확보에 도움이 된다”며 “필름코팅 정제 형태로 복용 부담이 상대적으로 낮아 환자 선호도가 높을 것으로 보인다”고 말했다.이번 연구 결과는 최근 SCI(Science Citation Index)급 국제 학술지인 ‘World Journal of Gastroenterology’에 게재됐다.JW중외제약은 향후 임상 데이터를 기반으로 의료진 대상 학술 활동을 확대해 제이클의 임상적 활용 경험을 넓혀 나간다는 계획이다.JW중외제약 관계자는 “이번 심포지엄을 통해 제이클의 임상 3상 결과와 실제 검사 환경에서의 활용 포인트를 의료진과 공유했다”며 “환자 편의성과 검사 효율성을 동시에 고려한 대장정결제 옵션으로서 제품 인지도를 높여 나가겠다”고 말했다.', NULL, '파이낸셜뉴스', 'https://n.news.naver.com/mnews/article/014/0005488333', 'https://imgnews.pstatic.net/image/014/2026/03/09/0005488333_001_20260309142413212.jpg?type=w800', 'NEWS_BIO', NULL, '2026-03-09 14:24:13', 0, true, '2026-03-09 05:39:43.216553') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (448, '[제약바이오] JW중외제약, 대장정결제 ‘제이클’ 유효성 확인 外', '▷JW중외, 8일 대한위대장내시경학회서 제이클 심포지엄 개최=제이클정은 내시경·X선 촬영 등 각종 검사 전 대장 세척을 위해 복용하는 전문의약품이다. 주요 성분은 삼투성 하제로 작용하는 마그네슘설페이트·포타슘설페이트·소듐설페이트와 대장 내 거품을 제거하는 시메티콘, 대장 연동운동을 촉진하는 소듐피코설페이트 등이다.해당 의약품은 임상 3상에서 구역은 대조군 21.7%, 제이클 정 7.62%로 나타났으며 두통은 대조군이 8.49%를 기록했지만 제이클 정은 0.95%로 더 낮았다. 박수범 양산부산대병원 소화기내과 교수는 “임상 3상 결과 장 정결 효과는 헤어필드(Harefield) 정결도 척도(HCS) 기준 대조군과 통계적으로 유의미한 차이를 보이지 않았으며 용종, 선종 발견율도 유사한 수준을 보였다”라며 “이상 반응의 경우 구역과 두통 비율 역시 대조군 대비 낮게 나타났다”라고 밝혔다. 이 결과는 국제 학술지 ‘World Journal of Gastroenterology’에 게재됐다.사진=픽사베이▷롯데바이오로직스, 美 디켓위크 2026 참가=행사는 오는 23일~26일 뉴욕에서 열린다. 롯데바이오로직스는 미팅룸을 운영하며, 미국 뉴욕 시러큐스 바이오 캠퍼스와 8월 준공 예정인 앞둔 인천 송도 바이오 캠퍼스 제1공장의 생산 역량을 바탕으로 수주에 나설 예정이다.관련해 회사는 작년 3월 아시모브와 업무협약을 체결했다. 세포주 개발부터 원료의약품 생산까지 약 8.5개월 내에 수행이 가능하다. 단일클론항체, 이중특이항체 등에 대한 개발 및 제조 지원은 물론 임상부터 GMP 생산까지 아우르는 단계별 제조 옵션을 제공 중이다. 회사 관계자는 “이번 참가를 통해 잠재 고객사와의 협력 기회를 적극 모색해 세계 시장에서의 경쟁력을 확대하겠다”라고 말했다.▷동아제약, ‘조르단 어린이 칫솔’ 국내 판매 5년 연속 1위=닐슨코리아에 따르면, 2020년~2025년 온오프라인 판매처를 대상으로 한 어린이 칫솔 카테고리에서 ‘조르단 스텝 시리즈’ 칫솔이 가장 높은 점유율을 기록했다. 조르단은 1837년 노르웨이 오슬로에서 시작된 구강용품 브랜드다. 조르단은 어린이 잇몸과 치아 구조를 고려해 다양한 소재와 경도를 적용한 브러쉬를 설계했다.어린이 대상 제품인 ‘스텝 시리즈’는 아이들의 연령별 구강 발달 단계를 고려해 설계됐다. 회사 관계자는 “조르단의 5년 연속 1위는 단순한 판매 실적이 아니라 수많은 부모님들의 신뢰와 아이들의 미소가 쌓인 결과”라고 강조했다.▷일동제약, ‘아로나민 골드’ 모델 새 광고 선봬=광고는 약국에서 출발한 ‘아로나민 골드’가 피로가 있는 곳으로 직접 찾아간다는 콘셉트다. 제품은 활성형 비타민 B군, 비타민 C‧E 등이 포함됐다. 육체 피로, 체력 저하, 신경통, 근육통, 관절통, 눈 피로 등에 효과가 있다.회사 관계자는 “아로나민의 메시지를 더 직관적이고 재미있게 전달했다”라며 “판매 1위 일반의약품 비타민, 브랜드 파워 1위 종합영양제 등으로 브랜드 신뢰도를 더했다”라고 전했다.▷HK이노엔, 티로그 스파클링 레몬라임 아이스티 세븐일레븐서 출시=제로 칼로리인 해당 제품은 홍차에 레몬과 라임의 맛을 더했다. 기존 제품은 캔 형태지만, 신제품은 500ml 용량의 페트병(PET) 음료로 출시돼 음용 편의성을 높였다. 가격은 2500원.회사 음료마케팅팀 티로그 담당자는 “신제품은 레몬 라임의 상큼함과 청량감으로 소비자들에게 즐거움을 선사할 것”이라고 덧붙였다.', NULL, '지디넷코리아', 'https://n.news.naver.com/mnews/article/092/0002413453', 'https://imgnews.pstatic.net/image/092/2026/03/09/0002413453_001_20260309141212895.png?type=w800', 'NEWS_BIO', NULL, '2026-03-09 14:12:12', 0, true, '2026-03-09 05:39:43.216553') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (449, '‘다크 팩토리’ 이어 ‘다크 실험실’ AI·로봇이 신약 연구 효율 5배 높였다', 'AI 상용화 선도하는 中 선전시 르포AI가 설계한 화학 연구, 로봇이 수행세계 20대 제약사 중 17곳과 협업산업용 로봇 사면 비용 50% 지원지난달 11일 방문한 중국 선전시의 AI 기반 신약 개발 업체 ‘엑스탈파이’ 본사에 스스로 화학 분자 실험을 수행하는 ‘자동화 로봇 워크스테이션’이 100여 대 설치돼 있다. 엑스탈파이 제공“이 연구실 안에는 인공지능(AI)과 로봇 말고는 아무도 없습니다.”지난달 11일 중국 광둥성 선전시의 AI 기반 신약 개발 업체 ‘엑스탈파이(XTalPI)’ 본사. 보안구역 내 독립된 공간에는 면적 2.5㎡의 자동화 로봇 워크스테이션 100대가 줄지어 설치돼 있었다. 그 안에서는 쉴 새 없이 움직이는 로봇 팔이 AI가 설계한 공식에 따라 각종 화학 실험을 이어갔다. 워크스테이션 사이로 자율주행로봇(AGV)이 지나다니며 실험이 끝난 샘플을 옮겨 담았다. 사람 없이 AI가 공장을 운영하는 ‘다크 팩토리’처럼 AI가 실험을 설계하고, 로봇이 실행하는 ‘다크 실험실’의 모습이 국내 언론에 처음으로 공개된 것이다.홍콩과 마주하고 있는 중국 남부의 선전시는 대표적인 첨단 제조의 중심지다. 텐센트, 화웨이, 비야디(BYD) 등 글로벌 기업들의 본사가 즐비하다. 최근에는 산업 현장과 일상생활 전반에 AI를 접목시키는 ‘AI 상용화’에 가장 앞선 도시로 탈바꿈하고 있다. 화학연구 분야의 엑스탈파이를 비롯해 대표적인 휴머노이드 로봇 기업 유비테크, 자율주행을 선도하는 로보센스도 선전에 본사를 두고 있다. 5일 리창(李强) 국무원 총리가 전국인민대표회의 업무보고에서 중점 산업에서 AI를 통한 상용화와 규모화를 강조하면서 선전시와 이곳의 기업들은 더욱 큰 주목을 받고 있다.로봇 팔은 24시간 동안 한 치의 오차 없이 재료를 섞고, 걸러내며 실험을 한다. 엑스탈파이 제공●AI·로봇 투입하니 신약 개발 효율 5배 높아져“다들 처음에는 바이오나 제약회사라고 생각해요. 저희는 AI와 로봇으로 화학 연구를 하는 기술 플랫폼 기업입니다.”엑스탈파이의 허메이 박사는 회사를 이렇게 소개했다. 이 회사는 미국 매사추세츠공대(MIT) 박사 출신 3명이 2014년 공동으로 창업했다. 이들의 전공은 각각 양자 물리, 양자 화학, 수학, 물리학 등이다.엑스탈파이가 신약 개발 회사로 잘 알려진 건 글로벌 제약회사인 화이자와의 인연 때문이다. 사업 초기 화이자가 개최한 화학 분자 구조 예측 대회에서 우승을 했고, 엑스탈파이의 실력을 인정한 화이자가 이들의 첫 번째 고객이 된 것. 지금은 세계 20대 제약사 중 17곳이 엑스탈파이와 협업 중이다. 화이자는 신종 코로나바이러스 감염증(코로나19) 치료제인 ‘팍스로비드’를 만들 당시 엑스탈파이와의 협업을 통해 AI 기술을 실험에 대거 적용했다. 그 결과 수개월 걸리는 연구를 6주 만에 끝냈다. 한국 회사 가운데 대웅제약, JW중외제약 등이 프로젝트를 진행하고 있다.초기 신약 개발 단계가 어려운 건 특정 질병을 일으키는 몸속의 표적을 찾았다 하더라도 그 표적에 잘 들어맞을 ‘분자 물질’을 찾아내야 하기 때문. 기존에는 연구원들이 수백 개의 가설을 세우고, 수천 번의 실험을 통해 적합한 물질을 찾아야 했다. 엑스탈파이는 이 과정에 AI를 도입해 실험해야 할 경우의 수를 크게 줄였다. 실험 이후 결과 데이터가 나오면 다시 AI 알고리즘에 반영하는 과정을 거치며 완성도를 더 높였다.엑스탈파이는 2019년부터 로봇을 통한 실험 자동화를 추진했다. 로봇은 카메라와 센서로 워크스테이션 내 상황을 확인하고 시험관에 재료를 넣고, 섞고, 걸러내는 등의 복잡한 작업을 인간의 개입 없이 수행한다. AI가 제시해 준 실험 설계도에 따라 한 치의 오차 없이 실험을 진행할 수 있으니 결과 데이터의 양과 신뢰도가 높아졌다. AI가 단순히 스마트폰이나 PC 속에 머무르는 게 아니라 실제 연구와 산업 현장의 생산력을 업그레이드한 것이다.“신약을 만드는 화학 실험의 80% 이상을 로봇이 해내고 있어요. 24시간씩 주 7일을 일하며 실수도 없죠. 실험 효율은 5배 이상 빨라졌고, 데이터는 40배 더 많이 확보할 수 있습니다. 최근에는 태양광 전지, 배터리 전해질, 슈퍼 농작물을 만드는 기업들과도 함께 연구를 진행하고 있습니다.”●선전, 피지컬AI 앞장서는 기업 즐비선전시 바오안구에서 국도 107호선을 따라 약 10km 구간은 ‘로봇 밸리’로 불린다. 유비테크와 두봇 등 중국 본토와 홍콩 증시에 상장된 업체를 비롯해 200여 로봇 제조사가 밀집해 있다. 감속기, 모터, 컨트롤러 같은 로봇의 핵심 부품을 만드는 회사까지 포함하면 800여 개에 달한다. 남방과학기술대학, 칭화대 선전국제대학원 등 대학과 연구기관까지 들어서 중국 로봇 공급망의 핵심 중 하나로 자리 잡았다.유비테크는 중국 휴머노이드 로봇 업체 중 상용화에 가장 앞선 것으로 평가받는다. S2 유비테크의 최신형 로봇 ‘워커 S2’는 출시 단계부터 산업용 휴머노이드 로봇을 표방했다. 세계 최초로 개발된 스스로 배터리를 교체할 수 있는 기술이 적용됐다. 사람이 주기적으로 배터리를 교체하거나 충전시켜 주지 않아도 24시간 내내 멈추지 않고 공장에서 작업할 수 있는 것이다. 지난해 4월 중국 자동차업체 지커의 저장성 지역 공장에서 진행한 실전 테스트를 시작으로 니오, 둥펑 등 다른 자동차 회사들의 공장에도 투입되고 있다.선전시에 본사를 둔 라이다(LIDAR) 센서 기업인 로보센스 역시 피지컬AI에서 빼놓을 수 없는 회사다. 라이다 센서는 주변에 레이저를 쏘아서 사물과의 거리를 측정하는 기술이다. AI가 로봇의 두뇌에 해당한다면, 라이다는 눈 역할을 하는 셈이다. 자율주행차는 물론 공장 자동화 시스템, 로봇 등에 필수적 요소가 됐다.●휴머노이드 로봇 도입 기업에 비용 50% 지원선전시는 베이징, 상하이, 항저우 등과 함께 AI, 로봇 산업의 중심지로 꼽힌다. 베이징은 칭화대를 중심으로 한 뛰어난 인재와 연구 역량을 바탕으로 AI 원천 기술 개발에 강점이 있다. 상하이는 반도체 등 제조 시설과 금융 인프라가 갖춰진 생산의 거점이다. 반면 선전은 AI 기술 개발을 넘어 실제 산업과 서비스에 적용하는 상용화에 초점을 맞췄다.1월 리창(李强) 중국 국무원 총리는 올해 첫 지방 일정으로 선전시를 찾았다. 리 총리는 엑스탈파이 본사를 둘러본 뒤 유비테크, 로보센스 등 중국 대표 로봇 기업 관계자들과 간담회를 가졌다. 이 자리에서 리 총리는 “로봇과 드론 등 신기술 제품들을 광범위하게 보급해야 한다”면서 “제품의 성능 향상에 속도를 내려면 실제 적용 분야를 확대하고 육성하는 것이 중요하다”고 강조했다.선전시도 적극적인 지원책을 펴고 있다. 지난해와 올해 초 발표한 인공지능 선도 관련 계획에 따르면 AI를 활용한 PC, 스마트폰, 웨어러블 기기, 로봇 등을 출시하면 최대 300만 위안(약 6억4000만 원)을 지원한다. AI 모델을 훈련하는 데 드는 비용은 최대 1000만 위안(약 21억2000만 원)까지 시에서 보조해 준다.제품 공급자뿐 아니라 수요자에 대한 지원도 있다. 기업이 자신들의 업무에 활용하기 위해 AI 모델을 구입하거나 AI에이전트 시스템을 구축할 경우 최대 200만 위안(약 4억2000만 원)까지 보조금을 준다. 또 중소기업이 산업용 로봇이나 휴머노이드 로봇을 구매할 경우 비용의 50%(연간 최대 100만 위안)를 지원한다.', NULL, '동아일보', 'https://n.news.naver.com/mnews/article/020/0003701862', 'https://imgnews.pstatic.net/image/020/2026/03/06/0003701862_001_20260306043515681.jpg?type=w800', 'NEWS_BIO', NULL, '2026-03-06 04:35:15', 0, true, '2026-03-09 05:39:43.216553') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (450, '‘다크 팩토리’ 이어 ‘다크 실험실’ AI·로봇이 신약 연구 효율 5배 높였다', '지난달 11일 방문한 중국 선전시의 AI 기반 신약 개발 업체 ‘엑스탈파이’ 본사에 스스로 화학 분자 실험을 수행하는 ‘자동화 로봇 워크스테이션’이 100여대 설치돼 있다. 엑스탈파이 제공“이 연구실 안에는 인공지능(AI)과 로봇 말고는 아무도 없습니다.”지난달 11일 중국 광둥성 선전시의 AI 기반 신약 개발 업체 ‘엑스탈파이(XTalPI)’ 본사. 보안구역 내 독립된 공간에는 면적 2.5㎡의 자동화 로봇 워크스테이션 100대가 줄지어 설치돼 있었다. 그 안에서는 쉴 새 없이 움직이는 로봇 팔이 AI가 설계한 공식에 따라 각종 화학 실험을 이어갔다. 워크스테이션 사이로 자율주행로봇(AGV)이 지나다니며 실험이 끝난 샘플을 옮겨 담았다. 사람 없이 AI가 공장을 운영하는 ‘다크 팩토리’처럼 AI가 실험을 설계하고, 로봇이 실행하는 ‘다크 실험실’의 모습이 국내 언론에 처음으로 공개된 것이다.홍콩과 마주하고 있는 중국 남부의 선전시는 대표적인 첨단 제조의 중심지다. 텐센트, 화웨이, 비야디(BYD) 등 글로벌 기업들의 본사가 즐비하다. 최근에는 산업 현장과 일상생활 전반에 AI를 접목시키는 ‘AI 상용화’에 가장 앞선 도시로 탈바꿈하고 있다. 화학연구 분야의 엑스탈파이를 비롯해 대표적인 휴머노이드 로봇 기업 유비테크, 자율주행을 선도하는 로보센스도 선전에 본사를 두고 있다. 5일 리창(李强) 국무원 총리가 전국인민대표회의 업무보고에서 중점 산업에서 AI를 통한 상용화와 규모화를 강조하면서 선전시와 이곳의 기업들은 더욱 큰 주목을 받고 있다.지난달 11일 중국 선전시의 엑스탈파이 본사. 보안 구역 안에  있는 ‘자동화 로봇 워크스테이션’의 모습이 국내 언론에 처음 공개됐다. 선전=김철중 특파원 tnf@donga.com● AI·로봇 투입하니 신약 개발 효율 5배 높아져“다들 처음에는 바이오나 제약회사라고 생각해요. 저희는 AI와 로봇으로 화학 연구를 하는 기술 플랫폼 기업입니다.”엑스탈파이의 허메이 박사는 회사를 이렇게 소개했다. 이 회사는 미국 매사추세츠공대(MIT) 박사 출신 3명이 2014년 공동으로 창업했다. 이들의 전공은 각각 양자 물리, 양자 화학, 수학, 물리학 등이다.엑스탈파이가 신약 개발 회사로 잘 알려진 건 글로벌 제약회사인 화이자와의 인연 때문이다. 사업 초기 화이자가 개최한 화학 분자 구조 예측 대회에서 우승을 했고, 엑스탈파이의 실력을 인정한 화이자가 이들의 첫 번째 고객이 된 것. 지금은 세계 20대 제약사 중 17곳이 엑스탈파이와 협업 중이다. 화이자는 신종 코로나바이러스 감염증(코로나19) 치료제인 ‘팍스로비드’를 만들 당시 엑스탈파이와의 협업을 통해 AI 기술을 실험에 대거 적용했다. 그 결과 수개월 걸리는 연구를 6주 만에 끝냈다. 한국 회사 가운데 대웅제약, JW중외제약 등이 프로젝트를 진행하고 있다.초기 신약 개발 단계가 어려운 건 특정 질병을 일으키는 몸속의 표적을 찾았다 하더라도 그 표적에 잘 들어맞을 ‘분자 물질’을 찾아내야 하기 때문. 기존에는 연구원들이 수백 개의 가설을 세우고, 수천 번의 실험을 통해 적합한 물질을 찾아야 했다. 엑스탈파이는 이 과정에 AI를 도입해 실험해야 할 경우의 수를 크게 줄였다. 실험 이후 결과 데이터가 나오면 다시 AI 알고리즘에 반영하는 과정을 거치며 완성도를 더 높였다.자동화 로봇 워크스테이션 안에 있는 로봇팔은 24시간 동안 한 치의 오차 없이 재료를 섞고, 걸러내며 실험을 진행한다. 엑스탈파이 제공엑스탈파이는 2019년부터 로봇을 통한 실험 자동화를 추진했다. 로봇은 카메라와 센서로 워크스테이션 내 상황을 확인하고 시험관에 재료를 넣고, 섞고, 걸러내는 등의 복잡한 작업을 인간의 개입 없이 수행한다. AI가 제시해 준 실험 설계도에 따라 한 치의 오차 없이 실험을 진행할 수 있으니 결과 데이터의 양과 신뢰도가 높아졌다. AI가 단순히 스마트폰이나 PC 속에 머무르는 게 아니라 실제 연구와 산업 현장의 생산력을 업그레이드한 것이다.“신약을 만드는 화학 실험의 80% 이상을 로봇이 해내고 있어요. 24시간씩 주 7일을 일하며 실수도 없죠. 실험 효율은 5배 이상 빨라졌고, 데이터는 40배 더 많이 확보할 수 있습니다. 최근에는 태양광 전지, 배터리 전해질, 슈퍼 농작물을 만드는 기업들과도 함께 연구를 진행하고 있습니다.”●선전, 피지컬AI 앞장서는 기업 즐비선전시 바오안구에서 국도 107호선을 따라 약 10km 구간은 ‘로봇 밸리’로 불린다. 유비테크와 두봇 등 중국 본토와 홍콩 증시에 상장된 업체를 비롯해 200여 로봇 제조사가 밀집해 있다. 감속기, 모터, 컨트롤러 같은 로봇의 핵심 부품을 만드는 회사까지 포함하면 800여 개에 달한다. 남방과학기술대학, 칭화대 선전국제대학원 등 대학과 연구기관까지 들어서 중국 로봇 공급망의 핵심 중 하나로 자리 잡았다.선전의 휴머노이드로봇 제조업체인 유비테크의 산업용 로봇‘워커 S2’는 이미 중국의 자동차 업체 지커와 BYD 등의 공장에 투입됐다. 유비테크 제공유비테크는 중국 휴머노이드 로봇 업체 중 상용화에 가장 앞선 것으로 평가받는다. S2 유비테크의 최신형 로봇 ‘워커 S2’는 출시 단계부터 산업용 휴머노이드 로봇을 표방했다. 세계 최초로 개발된 스스로 배터리를 교체할 수 있는 기술이 적용됐다. 사람이 주기적으로 배터리를 교체하거나 충전시켜 주지 않아도 24시간 내내 멈추지 않고 공장에서 작업할 수 있는 것이다. 지난해 4월 중국 자동차업체 지커의 저장성 지역 공장에서 진행한 실전 테스트를 시작으로 니오, 둥펑 등 다른 자동차 회사들의 공장에도 투입되고 있다.선전시에 본사를 둔 라이다(LIDAR) 센서 기업인 로보센스 역시 피지컬AI에서 빼놓을 수 없는 회사다. 라이다 센서는 주변에 레이저를 쏘아서 사물과의 거리를 측정하는 기술이다. AI가 로봇의 두뇌에 해당한다면, 라이다는 눈 역할을 하는 셈이다. 자율주행차는 물론 공장 자동화 시스템, 로봇 등에 필수적 요소가 됐다.●휴머노이드 로봇 도입 기업에 비용 50% 지원선전시는 베이징, 상하이, 항저우 등과 함께 AI, 로봇 산업의 중심지로 꼽힌다. 베이징은 칭화대를 중심으로 한 뛰어난 인재와 연구 역량을 바탕으로 AI 원천 기술 개발에 강점이 있다. 상하이는 반도체 등 제조 시설과 금융 인프라가 갖춰진 생산의 거점이다. 반면 선전은 AI 기술 개발을 넘어 실제 산업과 서비스에 적용하는 상용화에 초점을 맞췄다.1월 리창(李强) 중국 국무원 총리는 올해 첫 지방 일정으로 선전시를 찾았다. 리 총리는 엑스탈파이 본사를 둘러본 뒤 유비테크, 로보센스 등 중국 대표 로봇 기업 관계자들과 간담회를 가졌다. 이 자리에서 리 총리는 “로봇과 드론 등 신기술 제품들을 광범위하게 보급해야 한다”면서 “제품의 성능 향상에 속도를 내려면 실제 적용 분야를 확대하고 육성하는 것이 중요하다”고 강조했다.선전시도 적극적인 지원책을 펴고 있다. 지난해와 올해 초 발표한 인공지능 선도 관련 계획에 따르면 AI를 활용한 PC, 스마트폰, 웨어러블 기기, 로봇 등을 출시하면 최대 300만 위안(약 6억4000만 원)을 지원한다. AI 모델을 훈련하는 데 드는 비용은 최대 1000만 위안(약 21억2000만 원)까지 시에서 보조해 준다.제품 공급자뿐 아니라 수요자에 대한 지원도 있다. 기업이 자신들의 업무에 활용하기 위해 AI 모델을 구입하거나 AI에이전트 시스템을 구축할 경우 최대 200만 위안(약 4억2000만 원)까지 보조금을 준다. 또 중소기업이 산업용 로봇이나 휴머노이드 로봇을 구매할 경우 비용의 50%(연간 최대 100만 위안)를 지원한다.', NULL, '동아일보', 'https://n.news.naver.com/mnews/article/020/0003701738', 'https://imgnews.pstatic.net/image/020/2026/03/05/0003701738_001_20260305202015243.jpg?type=w800', 'NEWS_BIO', NULL, '2026-03-05 20:20:15', 0, true, '2026-03-09 05:39:43.216553') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (451, '정기주총 앞둔 제약바이오 기업들…전문경영인 연임? 교체? 촉각', '삼성바이오로직스·셀트리온 등 실적 이끈 전문경영인 연임 무게약가 인하·수익성 둔화 변수 속 성과·R&D 경쟁력이 관건3월 정기주주총회 시즌을 앞두고 제약바이오 업계 전문경영인 재선임 여부에 이목이 쏠린다. 특히 2020년 취임 이후 대형 수주를 잇달아 따낸 존림(사진) 삼성바이오로직스 대표는 사실상 연임이 확정됐다는 평가다. /삼성바이오로직스[더팩트ㅣ조성은 기자] 3월 정기주주총회 시즌을 앞두고 제약바이오 업계 전문경영인(CEO) 재선임 여부에 이목이 쏠리고 있다. 약가 인하와 수익성 둔화 우려 속에서 ''안정''과 ''성과''에 방점이 찍히면서, 장수 CEO와 실적 개선을 이끈 경영진의 연임 가능성에 무게가 실린다.3일 금융감독원 전자공시시스템에 따르면 매출 상위 상장 제약바이오기업 72곳 가운데 32개 기업에서 대표이사 36명이 올해 임기 만료를 앞두고 있다. 이 중 상당수가 전문경영인으로, 이달 주총에서 재신임 여부가 결정된다. 업계에선 "약가 인하와 비용 통제 압박이 커진 상황에서 급격한 리더십 교체보다는 연속성 유지가 우선될 것"이라는 관측이 나온다.삼성바이오로직스는 오는 20일 주총에서 존림 대표의 사내이사 재선임 안건을 다룬다. 지난해 11월 임직원 개인정보 유출 사태와 그로 인한 노사갈등이 남아있지만 연임에는 무리가 없다는 게 지배적인 평가다. 이미 그룹 정기 인사를 통해 연임이 사실상 확정된 만큼, 주총에서 세 번째 임기가 공식화될 전망이다.존림 대표는 2020년 취임 이후 대형 수주를 잇달아 따내며 매년 최대 실적을 경신해왔다. 지난해 삼성바이오로직스는 연간 수주금액 6조원을 넘어서며 바이오업계 최초로 연간 영업이익 2조원을 돌파했다. 특히 인적분할을 통해 위탁개발생산(CDMO) 체제로 전환하고 미국 메릴랜드주 록빌 바이오의약품 생산시설 인수를 결정하는 등 글로벌 수주 불확실성을 줄이는 데 공을 들였다. 회사는 글로벌 빅파마 중심으로 고객 포트폴리오를 확대하고 대규모 수주와 생산능력 증설을 병행해 가시적인 성과를 냈다는 점을 재선임 사유로 설명했다.기우성·김형기 셀트리온 대표의 연임 가능성도 높다. 2015년 전무경영인 체제 전환 이후 두 대표는 각자대표 체제를 안정화했다는 평가를 받는다. 기우성·김형기 셀트리온 대표. /셀트리온셀트리온도 오는 24일 열리는 주총에서 기우성·김형기 각자대표의 재선임 안건이 상정된다. 기 대표는 5연임, 김 대표는 4연임에 도전한다. 두 대표는 셀트리온의 창업 공신으로 서정진 회장과 오랜 기간 손발을 맞춰왔다. 2015년 전문경영인 체제 전환 이후 회사를 이끌어온 두 대표는 통합 작업을 마무리하며 3인 각자대표 체제를 안정화했다는 평가를 받는다.셀트리온은 공동대표 체제 하에서 제품의 글로벌 점유율 확대와 신규 포트폴리오 확대 등 성장을 거듭했다. 셀트리온은 지난해 매출 4조원, 영업이익 1조원 시대를 열었다. 올해 매출 목표는 5조3000억원으로, 이번 재선임으로 리더십의 연속성을 이어가며 글로벌 시장에서의 바이오시밀러 점유율 확장에 주력할 것으로 전망된다.장수 CEO의 연임 도전도 이어진다. 가장 주목받는 인물은 제일약품의 성석제 대표다. 2005년 첫 선임 이후 7연임에 성공한 장수 CEO로, 올해 8연임에 도전한다. 지난해 오너 3세 한상철 사장과 공동대표 체제로 전환한 가운데, 전문경영인-오너 투톱 체제가 유지될지 관심이 쏠린다. 유제만 신풍제약 대표는 5연임, 신영섭 JW중외제약 대표는 4연임에 도전한다. 백진기 한독 대표 역시 3연임이 유력하다. 실적 방어와 연구개발(R&D) 성과가 재신임의 핵심 잣대로 꼽힌다.재선임에 첫 도전하는 전문경영인도 적지 않다. 박성수 대웅제약 대표는 글로벌 사업과 R&D를 총괄하며 보툴리눔 톡신 ''나보타''의 해외 확장을 이끈 인물로, 회사의 대표이사 6년 임기 관행에 비춰 재선임 가능성이 거론된다. 박재현 한미약품 대표 역시 재선임 대상이다. 경영권 분쟁이라는 변수를 겪었지만, 국산 비만치료제 등 신약 파이프라인 성과를 이유로 ''안정적 연속성''에 무게가 실린다는 관측이 나온다.변수는 실적과 지배구조다. 일부 기업은 오너 2·3세와 공동대표 체제를 구축하며 세대교체를 병행하고 있고, 약가 인하 등 정책 환경 변화도 부담 요인으로 작용한다. 지난해에는 임기를 남기고 물러난 사례도 적지 않았던 만큼, 올해 역시 주총 이후 2차 인사 변동이 이어질 가능성도 배제할 수 없다.업계 관계자는 "R&D 성과와 글로벌 경쟁력, 비용 통제 역량이 재신임의 핵심 기준이 될 것"이라며 "대외 불확실성이 큰 만큼 전문경영인의 책임경영과 이사회 견제 기능이 동시에 시험대에 오를 것"이라고 말했다.발로 뛰는 더팩트는 24시간 여러분의 제보를 기다립니다.▶카카오톡: ''더팩트제보'' 검색▶이메일: jebo@tf.co.kr▶뉴스 홈페이지: http://talk.tf.co.kr/bbs/report/write', NULL, '더팩트', 'https://n.news.naver.com/mnews/article/629/0000477309', 'https://imgnews.pstatic.net/image/629/2026/03/03/202684961772507488_20260303124308337.jpg?type=w800', 'NEWS_BIO', NULL, '2026-03-03 12:43:08', 0, true, '2026-03-09 05:39:43.216553') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (452, '신약조합, 오픈이노베이션‧전주기 지원 인프라 구축키로', '한국신약개발연구조합, 제40차 정기총회 성료한국신약개발연구조합이 27일 서울 삼정호텔에서 제40차 정기총회를 개최했다.신약조합은 정관 변경, 2025년도 사업실적 보고 및 2026년도 사업계획, 2025년도 결산 및 2026년도 예산, 임원 선임 등을 의결했다.신약조합은 ▲오픈이노베이션 지원 환경 조성 ▲바이오헬스 신약 R&D 전주기 플랫폼 구축 및 운영 ▲국가 R&D지원 정책 기획 및 연계사업 인큐베이션 ▲분야별 바이오헬스 전문인력 양성 등을 역점 사업으로 추진할 예정이다.김정진 한국신약개발연구조합 이사장이날 제27회 대한민국신약개발상 시상식을 비롯해 바이오헬스산업 분야 유공자 과학기술정보통신부장관표창식, 2026년도 제약산업 혁신성과 실용화연계 우수전문가 한국보건산업진흥원장 표창식, 제약산업기술거래센터 26차년도 출범식, 유망기술 사업화 설명회, KDRA 바이오헬스 플랫폼 지원사업 설명회, 2026 KDRA 신년교례회 등도 함께 진행됐다.특히 15대 이사장을 역임한 홍성한 비씨월드제약 회장에 대한 명예이사장 위촉식 및 감사패 전달식도 진행됐다.올해 선정된 바이오헬스산업 분야 유공자들은 ▲진주남 보령 글로벌 RA그룹 그룹장 ▲정미현 씨티엑스 전무 ▲최유화 지씨씨엘 본부장 ▲이혜리 카이특허법인 파트너 변리사 ▲김진선 한림제약 연구소장 ▲손미원 엠테라파마 대표 ▲이태규 스케일업파트너스  대표 ▲유현숙 퍼슨 부사장 ▲이우영 신신제약 연구위원 ▲박형서 유투엑스랩 센터장 ▲김미영 제일약품 센터장 ▲이호찬 유한양행 이사 ▲장영표 경희대약대 교수 ▲권학철 한국과학기술연구원 책임연구원 ▲진세호 제이더블유중외제약 CMC연구센터장 ▲김용전 과학기술사업화진흥원 책임연구원 ▲윤수정 한국발명진흥회 책임전문위원 ▲오두병 한국생명공학연구원 노화연구소장 ▲김봉석 보령 실장 ▲송현의 이화여대 기술사업화센터장 ▲김도원 아주대 파트장 ▲이혜윤 경연전람 차장 등 22명이다.김정진 이사장은 “조합 설립 40주년을 맞아 글로벌 제약·바이오 환경을 도약의 기회로 삼아 오픈이노베이션 강화, 신약개발 전주기 지원 인프라 구축, 합리적인 정책·지원 환경 조성, 미래 전문인력 양성 등 4대 중점 과제를 중심으로 조합의 역할을 강화하겠다”라며 “조합원사가글로벌 경쟁력을 갖춘 신약개발 생태계를 조성하겠다”라고 밝혔다.', NULL, '지디넷코리아', 'https://n.news.naver.com/mnews/article/092/0002412232', 'https://imgnews.pstatic.net/image/092/2026/02/27/0002412232_001_20260227140511908.jpg?type=w800', 'NEWS_BIO', NULL, '2026-02-27 14:05:11', 0, true, '2026-03-09 05:39:43.216553') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (457, '"전주시, 체납 상태 업체에 옛 대한방직 부지 개발 인허가"', '시민단체, 권익위에 신고전북 전주 신시가지에 위치한 옛 대한방직 부지./뉴스1 DB(전주=뉴스1) 강교현 기자 = 전북 전주지역 시민단체가 옛 대한방직 부지 개발사업과 관련해 "체납 상태 민간업체에 인허가가 이뤄졌다"며 전주시를 국민권익위원회에 신고했다.전주시민회는 최근 전주시를 고발하는 신고서를 권익위에 제출했다고 24일 밝혔다.전주시민회에 따르면 시가 옛 대한방직 부지 소유 업체 ''자광''과 맺은 공유재산(토지) 임대 계약이 작년 6월 만료됐다. 그러나 이후에도 자광의 시 소유 토지 점유가 계속됐고, 이에 시는 임대료와 무단 점유에 따른 변상금 약 3억 원을 부과했다. 그러나 이 또한 현재까지 체납 상태다.이 단체는 "시는 최소한 지방세와 체납 임대료 변상금 등을 징수한 뒤 사업 계획을 승인하거나 거부해야 했다"며 "그러나 시는 아무 조처를 하지 않고 사업계획을 승인해 줬다"고 지적했다.단체는 "자광은 현재도 재산세와 공유재산 임대료, 공유재산 무단 점유에 따른 변상금 등을 체납하는 상황"이라며 "권익위는 사업계획 승인 과정에서 시가 지방세와 임대료 변상금 해소 없이 조건부 사업 계획을 승인한 경위를 조사해야 한다"고 주문했다.자광은 옛 대한방직 부지(23만 565㎡)에 관광 전망 타워(470m), 200실 규모 호텔, 복합쇼핑몰, 주상복합아파트 3536세대 등을 조성하는 복합 개발사업을 추진 중이다.', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008790149', 'https://imgnews.pstatic.net/image/421/2026/02/24/0008790149_001_20260224142911732.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-24 14:28:23', 0, true, '2026-03-09 05:40:04.547682') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (458, '자사주 소각 ''의무화'' 시대 온다...지난해 소각 규모 증자 3.6조 초과', '3차 상법 개정 통과 임박 ''자사주 디플레이션'' 뚜렷소각 규모 증자보다 많아…2년 연속 증시 공급액 마이너스올 두달새 연간 21% 달성, 금융·지주사 ''대기 수요'' 주목금융·증권주 중심 자사주 소각 활발해 질 듯[이데일리 김경은 기자] 자기주식(자사주) 소각 의무화를 골자로 한 3차 상법 개정안이 국회 통과를 목전에 두면서 국내 증시의 수급 구조가 근본적으로 달라질 것이란 전망이 힘을 얻고 있다. 소각이 매입을 압도하는 ‘자사주 디플레이션’ 현상이 뚜렷해지는 가운데, 자사주 비중이 높은 금융주와 지주사를 중심으로 주주환원 기대감도 커지고 있다.[이데일리 김일환 기자]자사주 소각 2배 ↑...약 두달만에 작년 21% 도달23일 정치권과 금융투자업계에 따르면 3차 상법 개정안은 이날 국회 법제사법위원회 전체회의를 통과한 데 이어, 24일 본회의 의결이 유력하다.핵심 내용은 기업이 신규로 취득하는 자사주를 취득일로부터 1년 이내에 의무 소각하도록 한 것이다. 다만 보유 중이라면 기한이 6개월 더 늘어나고 외국인 지분제한이 걸린 기업은 최대 3년까지 소각을 미룰 수 있다.법개정을 앞두고 상장사들의 자발적 자사주 소각 공시는 잇따르고 있다. 대신증권에 따르면 2025년 한 해 동안 소각된 자기주식은 4억1500만주로, 1년 전 1억9700만주 대비 110.66% 급증했다.그 결과 지난해 유상증자와 전환사채(CB) 발행 등 증시 공급 금액을 자사주 소각 금액이 3조5600억원 초과하며, 2024년(1조5300억원)에 이어 2년 연속 순공급 마이너스를 기록했다. 이는 앞서 6년 연속 누적 62조원 규모로 증시 공급액이 증가한 것과 대비된다.자사주 매입 금액이 2024년 18조8000억원에서 2025년 20조1000억원으로 소폭 늘어나고, 소각 금액은 같은 기간 13조9000억원에서 21조4000억원으로 54% 넘게 뛰면서다.이 같은 흐름은 올해 들어 더욱 가팔라지고 있다. 이달 20일 기준 올해에만 82건(1억1900만주)의 자사주 소각 공시가 접수됐는데, 이는 2025년 연간 소각 주식건수(378건, 5억6100만주)의 약 21%에 달하는 수치다. 2월이 아직 채 끝나지 않은 시점임을 감안하면 소각 속도가 눈에 띄게 빨라진 셈이다.이 같은 소각 확대 기조는 상장사 전체 자기주식 수의 실물 감소로도 확인된다. 한국거래소에 따르면 전 종목 자기주식 수는 2024년 초 27억3797만주에서 2025년 초 28억6692만주로 4.71% 증가했으나, 2026년 초 28억4928만주로 -0.62% 감소했다. 이에 따라 2026년 들어 상장사 총 발행주식수 대비 자사주 비중도 전년 2.56%에서 2.53%로 0.03%포인트 감소 전환했다.자사주 10% 넘는 곳들 보니...지주ㆍ금융사ㆍ전통제조업 ‘쏠림’3차 상법 개정안이 통과되면 이 같은 흐름은 더욱 가속화될 전망이다. 특히 자사주 비중이 높은 금융주와 지주사들이 소각 확대의 주요 주체로 부상할 것으로 증권가에서는 보고 있다.이날 현재 자사주 비중이 10%를 넘는 상장사를 분석한 결과(자사주 보유 기준은 지난해 3분기말), 지주회사와 금융사, 전통 제조업 기반 기업에 집중되는 경향이 뚜렷하다. 가장 높은 수준을 보이는 기업은 인포바인(115310)(54.2%)으로, 발행주식의 절반 이상을 자사주로 보유하고 있다. 이어 신영증권(001720)(51.2%), 일성아이에스(003120)(48.8%), 조광피혁(004700)(46.6%), 텔코웨어(078000)(44.1%), 부국증권(001270)(42.7%) 등이 40~50%대에 분포한다.지주사 그룹에서도 자사주 비중이 높게 나타난다. 롯데지주(004990)(27.5%), SK(034730)(24.8%), 하림지주(003380)(13.2%), LS(006260)(12.5%) 등이 대표적이다. 지주사의 경우 자사주는 의결권이 없지만, 소각·교환·합병 등 다양한 전략적 선택지를 제공해왔다. 3차 개정안은 이러한 활용 방식을 사실상 봉쇄하는 만큼, 기존 보유 자사주를 어떻게 처리할지가 향후 지배구조 개편의 핵심 변수로 작용할 전망이다.증권·보험업에서도 높은 자사주 비중이 확인된다. 미래에셋생명(085620)(26.3%), 미래에셋증권(006800)(23.3%), DB손해보험(005830)(15.5%), 한화생명(088350)(13.5%), 삼성화재(000810)(13.4%), 삼성생명(032830)(10.2%) 등이 포함된다. 금융사의 자사주 매입은 주당순이익(EPS) 개선, 주주환원 강화, 주가 안정 등 복합적 목적이 작용하는 경우가 많다.전통 제조업 기반 기업에서도 자사주 비중이 높다. 제일연마(001560)(32.2%), 대한방직(001070)(31.8%), 대웅(003090)(29.7%), 한샘(009240)(29.5%), SNT다이내믹스(003570)(28.9%) 등이 대표적이다. 이들 기업은 오너 중심 지배구조를 유지하는 경우가 많아, 자사주 보유가 경영권 안정 장치로 기능해왔다는 점에서 법 개정 이후 행방에 시장의 관심이 쏠린다.이경민 대신증권 연구원은 “3차 상법 개정안 통과는 시장 기대심리의 정점 통과 시점이 될 수 있다”면서도 “정책 기대가 현실화되는 과정에서 금융주를 중심으로 자사주 소각 공시가 잇따를 것”이라고 진단했다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006222946', 'https://imgnews.pstatic.net/image/018/2026/02/23/0006222946_001_20260223195310248.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-23 16:56:14', 0, true, '2026-03-09 05:40:04.547682') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (459, '[서울데이터랩]대원전선우 30.00% 상한가…금일 증시 상승률 1위로 마감', '23일 오후 3시 35분 대원전선우(006345)가 등락률 +30.00%로 상승률 1위로 마감했다. 대원전선우는 장 중 2,198,764주가 거래되었으며 주가는 전 거래일 대비 1,095원 오른 4,745원에 마감했다.한편 대원전선우의 PER은 33.42로 평가되었다.이어 상승률 2위 미래에셋생명(085620)은 주가가 +30.00% 폭등하며 종가 16,120원에 상승 마감했다. 상승률 3위 삼화콘덴서(001820)의 주가는 57,000원으로 +29.99% 폭등하며 강세를 보였다. 상승률 4위 대원전선(006340)은 +29.99% 폭등하며 5,440원에 마감했다. 상승률 5위 SG세계물산(004060)은 +29.95%의 상승세를 타고 768원에 마감했다.6위 에이엔피(015260)는 612원으로 +29.94% 상승 마감했다. 7위 서울식품(004410)은 종가 223원으로 +29.65% 상승 마감했다. 8위 더존비즈온(012510)은 종가 118,600원으로 +23.54% 상승 마감했다. 9위 텔코웨어(078000)는 20,050원으로 +23.46% 상승 마감했다. 10위 대한방직(001070)은 8,800원으로 +23.25% 상승 마감했다.이밖에도 성안머티리얼스(011300) ▲21.79%, 태양금속(004100) ▲17.88%, 영흥(012160) ▲16.56%, 부국증권(001270) ▲16.46%, 한국ANKOR유전(152550) ▲16.46%, 티와이홀딩스(363280) ▲16.42%, 삼성전기우(009155) ▲15.46%, 흥국화재(000540) ▲14.41%, 일진전기(103590) ▲14.15%, DB(012030) ▲13.40% 등을 기록하며 금일 증시를 상승으로 마감했다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003619992', 'https://imgnews.pstatic.net/image/081/2026/02/23/0003619992_001_20260223154711808.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-23 15:47:11', 0, true, '2026-03-09 05:40:04.547682') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (460, '''공급 절벽'' 전주…지방서 이례적 집값 강세', '지방 부동산 시장 점검(6) 새 아파트 부족한 전주작년 전주 아파트값 5.5% 뛰어지방 시·군 가운데 2번째로 높아입주·분양 적어 수급 불균형''포레나에코시티'' 7.8억 신고가익산·군산은 32주째 집값 하락“올해도 아파트 입주 물량이 크게 부족할 것으로 보입니다. 덕진구 에코시티 일대는 전용면적 84㎡ 호가가 8억원대로 치솟았습니다.”(전북 전주 덕진구 송천동 A공인 대표)전주 아파트값이 지방 도시 중 이례적으로 오름세를 이어가고 있다. 지난해 아파트값 상승률은 5.5%로 지방 시·군 가운데 경북 문경(6.9%)에 이어 두 번째로 높았다. 작년 전북 상승률이 지방 8개 도 가운데 가장 높은 1.69%를 기록한 것도 전주 아파트값이 강세를 보인 영향이다. 입주 물량 감소 등 공급 부족 우려로 수요자들은 새 아파트 분양에 관심이 커지고 있다.◇전주 분양단지 완판 행렬13일 한국부동산원에 따르면 전주 아파트값은 지난해 5월 이후 9개월 연속 상승세를 이어가고 있다. 이번주(지난 9일 기준)에도 주간 상승률 0.24%를 기록했다. 주거 환경이 좋은 것으로 평가받는 덕진구 에코시티 일대 아파트 가치가 치솟고 있다.신고가 거래도 속속 나온다. 송천동 포레나전주에코시티 전용 84㎡는 지난해 11월 7억8000만원에 손바뀜해 최고가를 기록했다. 같은 면적의 최근 호가는 8억원대 초반까지 올랐다.전주 집값이 상승 곡선을 그리는 원인으로는 공급 부족이 꼽힌다. 부동산 플랫폼 아실에 따르면 2020년 5848가구에 달한 아파트 입주 물량은 2024년 245가구, 지난해 277가구로 급감했다. 전주 인구가 63만 명에 달한다는 점을 고려하면 연간 적정 공급 수요(인구의 0.5% 수준)는 3150가구 정도다. 박합수 건국대 부동산대학원 겸임교수는 “전주는 2024년부터 공급 부족 이슈가 있었던 지역”이라며 “수급 불균형 문제가 나타나고 있는 것”이라고 설명했다.새 아파트 부족에 분양 단지는 속속 ‘완판’(완전 판매) 행진을 이어가고 있다. 송천동에서 지난해 11월 분양한 송천아르티엠더숲은 1순위 청약에서 평균 21.2 대 1, 최고 39.4 대 1의 경쟁률을 기록했다. 작년 1월 공급한 완산구 중노송동 더샵라비온드는 1순위 청약에서 평균 경쟁률 26.1 대 1로 마감했다.개발 호재도 이어지고 있다. 전주의 ‘마지막 노른자위 땅’으로 꼽히는 완산구 효자동 옛 대한방직 부지(23만㎡) 개발사업이 올해 본격화할 전망이다. 인근에 전북도청과 전북경찰청 등 행정기관이 많고, 신도심이 형성돼 있어 관심이 높다. 전주시는 지난해 9월 사업계획을 승인했다. 시행사 자광은 높이 470m 관광 전망 타워, 200실 규모 호텔, 쇼핑몰과 영화관을 갖춘 복합쇼핑몰, 49층 규모 주상복합아파트 10개 동(3536가구) 등을 2030년까지 지을 계획이다.◇익산과 군산은 공급 과잉 우려익산과 군산은 공급 과잉 우려가 커지고 있다. 물량을 받아줄 수요도 충분치 않아 집값이 하락하는 추세다. 익산과 군산의 주간 아파트 매매지수는 작년 7월 첫째 주 이후 32주째 내림세를 이어가고 있다.업계에 따르면 올해 전북 입주 물량 가운데 80%가량이 두 도시에 몰려 있어 당분간 집값 하락세가 계속될 것이란 전망이 나온다. 익산지역 분양 관계자는 “입주 시기가 다가와도 잔금을 치르지 못하는 계약자가 적지 않다”며 “기존 집이 팔려야 새 아파트에 들어갈 수 있는데 매매가 쉽지 않고, 전세로 내놔도 수요자가 거의 없다”고 했다.전주=안정락 기자 jran@hankyung.com', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005251278', 'https://imgnews.pstatic.net/image/015/2026/02/13/0005251278_001_20260214002513934.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-13 15:10:17', 0, true, '2026-03-09 05:40:04.547682') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (461, '강성희 "대한방직 개발사업 시행사 자광, 자금력 입증해야"', '전주시에 "이행 능력 검증" 요구강성희 전 국회의원이 10일 전주시청에서 기자회견을 갖고 대한방직 부지개발사업 시행사인 (주)자광의 재무능력에 대한 전주시의 철저한 점검을 촉구했다./뉴스1(전주=뉴스1) 임충식 기자 = 6·3지방선거 전북 전주시장 출마를 선언한 강성희 전 진보당 국회의원이 옛 대한방직 부지개발 사업 시행사 ''자광''에 재무 상황 공개를 촉구하고 나섰다. 그는 이에 대한 전주시의 철저한 점검도 요구했다.강 전 의원은 10일 전주시청에서 회견을 열어 "전주시는 금융당국의 프로젝트 파이낸싱(PF) 규제 강화 기조에 따라 자본 잠식 상태인 자광의 재무적 이행 능력을 점검해야 한다"고 말했다.그는 "현재 자광은 시공사 계약조차 맺지 않은 상태에서 화려한 축제를 계획하고 있다"며 "하지만 그 화려한 불꽃놀이 뒤에는 완전 자본잠식이라는 참담한 재무제표와 대주단으로부터 기한이익상실 통보를 받았던 실체가 숨겨져 있다"고 지적했다.그는 "자광은 PF 자금조달 확약서와 시공사 책임 준공 확약서를 시민 앞에 공개하라"면서 "만약 자광이 못한다면 전주시가 나서야 한다. 시는 자광의 재무적 이행 능력을 점검해야 한다"고 주문했다.강 전 의원은 "자광이 실질적인 자금력을 증명하지 못한다면 시장 당선 즉시 용도 환원 절차에 착수하고, 전주시가 주도하는 공영 관리형 민관합동 개발로 전환할 것"이라며 "대한방직 부지를 전주 경제의 새로운 심장이자 시민 모두의 자부심이 되는 공공의 자산으로 만들겠다"고 말했다.자광은 현재 옛 대한방직 부지(23만 565㎡)에 대한 개발사업을 추진 중이다. 주요 개발 계획은 △관광 전망 타워 △200실 규의 호텔 △백화점과 쇼핑몰 등의 상업시설 △고품격 주상복합아파트 3536세대 건설과 △문화공원·공개공지 및 △지하차도 조성 △교량 확장 및 신설 △주변 도로 확충 △녹지조성 등이다.', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008764933', 'https://imgnews.pstatic.net/image/421/2026/02/10/0008764933_001_20260210111832886.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-10 11:17:28', 0, true, '2026-03-09 05:40:04.547682') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (462, '대한방직 터 관광타워 복합개발 착공 지연', '[KBS 전주]전주 옛 대한방직 터 개발 사업 시행사인 주식회사 자광이 지난해 말 첫 삽을 뜰 거라고 밝혔지만, 시공사가 나타나지 않으면서 당초보다 착공이 늦어지고 있습니다.또 철거 작업을 맡은 업체가 지난해 11월, 9명의 사상자를 낸 울산화력발전소 사고와 연관돼 건물 철거에도 변수가 생긴 것으로 알려졌습니다.이런 가운데, 자광은 오는 11일 옛 대한방직 터에서 ''관광타워 복합개발사업 비전 페스타''를 열어 사업 추진 현황 등을 공유하고 불꽃놀이와 축하 공연을 펼칠 예정입니다.', NULL, 'KBS', 'https://n.news.naver.com/mnews/article/056/0012120766', 'https://imgnews.pstatic.net/image/056/2026/02/06/0012120766_001_20260206220854468.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-06 21:53:28', 0, true, '2026-03-09 05:40:04.547682') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (463, '전주 옛 대한방직 터 개발사업, 올해 상반기 본격화', '전주 옛 대한방직 터[전주시 제공. 재판매 및 DB 금지](전주=연합뉴스) 김동철 기자 = 전북 전주시의 ''마지막 노른자위 땅''으로 꼽히는 옛 대한방직 부지(23만㎡) 개발사업이 올해부터 본격화한다.전주시는 시공자 선정과 감리자 지정, 안전관리계획 승인 등의 절차를 거쳐 올 상반기에 옛 대한방직 부지 개발사업이 본격 추진될 예정이라고 6일 밝혔다.부지 내 무상 귀속 시설과 공공기여 시설 설치를 위한 실시설계, 건설사업관리 용역도 추진된다.민간 개발사인 자광은 6조원가량을 들여 옛 대한방직 부지에 470m 높이의 관광전망타워, 200실 규모의 호텔, 주상복합아파트 10개동(3천536세대), 복합쇼핑몰 등을 2030년까지 건립할 예정이다.자광은 용도지역 변경에 따른 토지가치분에 대해 공공기여로 2천528억원을 납부하기로 했다.김칠현 시 광역도시기반조성국장은 "개발사업이 계획대로 추진돼 지역경제 활성화와 관광산업 발전에 기여하고 공공기여 사업도 차질 없이 추진되도록 노력하겠다"고 말했다.sollenso@yna.co.kr', NULL, '연합뉴스', 'https://n.news.naver.com/mnews/article/001/0015831367', 'https://imgnews.pstatic.net/image/001/2026/01/06/AKR20260106085500055_01_i_P4_20260106105120570.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-06 10:51:00', 0, true, '2026-03-09 05:40:04.547682') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (464, '"공사장 가림막 대부분 불량·비규격"…붕괴사고 유발·보행자 안전 위협', '"안전인증 대상 제외…불량 무허 제품이 시장 잠식"KS규격·인증 자재 사용해 품질관리체계 구축해야"중고 가설울타리(가림막)을 사용해 무너진 모습 (사진=독자제공) /뉴스1(양주=뉴스1) 이상휼 기자 = 공사장 주변 보행자의 안전을 확보하는 ''가설울타리''가 비규격, 중고자재 사용, 무허가 업체의 불량제품이 유통되는 등 ''붕괴·전도 사고를 유발한다''는 지적이 나오고 있다.경기 양주시의회 김현수 의원은 ''가설울타리(가설가림막) 안전관리 및 품질기준 점검강화 촉구 건의안''을 대표발의했다고 19일 밝혔다.가설울타리란 공사장 주변의 보행자·차량 안전을 확보하고, 소음·분진 확산을 차단하는 핵심 임시시설물이다.수도권의 도심지 해체공사 및 고층 건축공사가 증가함에 따라 가설울타리는 단순 구획 경계시설이 아니라 공공안전과 도시환경을 지키는 1차 방호선의 역할을 수행하고 있다.하지만 현장의 법적 기준 미비, 관리·감독 부족으로 인해 가설울타리 붕괴 사고가 잇따르고 있다.건의안에 따르면 현행 건설기술진흥법 제62조는 발주자와 시공자에게 건설공사 전반의 안전관리 의무를 부과하고, 가설구조물 설치 시 기술사에 의한 구조안전성 확인을 반드시 거치도록 규정하고 있다.국토교통부 건설기준(KCS 21 10 00, 21 20 05)은 가설공사의 구조적 안전기준과 더불어 KS규격 또는 동등 이상의 재료 사용 기준까지 명확히 제시하고 있다.그럼에도 불구하고 가설울타리는 ''산업안전보건법'' 등 관련 법령에서 비계·동바리·안전난간과 달리 안전인증 및 구조검토 적용 대상에서 제외돼 있다. 이로 인해 품질 미달 자재 사용이 제도적으로 통제되지 못하고, 안전관리의 공백이 고착화되고 있다는 지적이 나온다.규제 부재 속에서 다수의 건설현장에서는 비용 절감과 낙찰 경쟁을 이유로 ''비규격'' 또는 ''중고 가설자재''가 반복 사용되고 있다. 그 결과 구조적 취약성과 사고 위험이 상시적으로 존재하는 실정이다.이로 인한 사고 사례로 △2021년 9월 서울 강남구 청담동 어린이보호구역 가림막 전도 △2022년 3월 인천 신축공사장 방음벽 붕괴 △2022년 12월 전주 대한방직 터 외국인 노동자 추락사 △2023~2025년 서울·대구·광주 등지에서 발생한 가설가림막 전도 및 붕괴사고 등이 발생했다.관련 업계에서는 "중고 자재 사용, 무허가 업체의 규격 미달 제품 공급, 감리·감독의 소극적 관리가 복합적으로 작용한 결과"라고 사고 유형을 분석했다.시장 일각에서는 생산자책임재활용제도(EPR) 적용을 회피하는 사례로, 폐PVC(폴리염화비닐), 플라스틱 재가공 과정에서 적법한 절차를 거치지 않은 제품의 유통을 원인으로 꼽았다.이들 제품은 정식 안전검사나 품질확인을 거치지 않아 내풍압성능, 인장강도, 방염성 등 최소 안전기준조차 충족하지 못하는 경우가 많아 시민의 생명과 재산을 직접적으로 위협한다는 것이다.반면 인증기준에 따라 생산·회수·재활용을 성실히 이행하는 업체들은 저가 불량제품의 대량 유통으로 인한 단가경쟁과 원료 확보 비용 증가로 경영 압박을 겪고 있다.결국 제도권 내 성실 업체가 손해를 보고, 무허가·비인증 업체가 시장을 잠식하는 구조적 불공정이 심화된다는 지적이다.현행 제도에는 가설울타리의 구체적 안전기준과 현장점검 체계가 미흡한 실정이다. 일부 감리·감독 단계에서는 서류 확인에만 의존한 형식적 점검이 이뤄지고 있다.업계 관계자는 "가설울타리는 단순한 임시시설이 아닌 ''국민 안전시설''로 인식해야 한다"며 "국토교통부는 건설기준(KDS·KCS)에 가설울타리의 구조안전성, 재료기준, 품질검증 절차를 명문화해야 하며, 고용노동부는 안전인증대상기계 적용 범위를 확대하여 비하중형 임시시설물도 인증 검토 대상에 포함시켜야 한다"고 제시했다.그러면서 "환경부는 생산자책임재활용(EPR) 제도의 사각지대를 해소해 건설용 PVC 기자재의 불법 재가공·유통 차단을 위한 회수·재활용 관리체계를 마련해야 한다"고 요청했다.이와 함께 지자체와 공공기관은 ''지방계약법 시행령''에 따라 계약특수조건으로 △안전인증·KS규격품 사용 △납품 전 자재검증 절차를 명문화해 발주 단계부터 품질관리가 이뤄지도록 해야 개선될 것이라고 내다봤다.시의회는 "정부는 가설울타리를 건설기술진흥법상 가설구조물 안전관리 대상에 포함시키고, 구조검토 및 품질검증 절차를 예외 없이 의무화할 것, 건설용 PVC 기자재의 회수·재활용 관리기준을 강화하고, 불법 재가공 자재의 재유통을 차단할 강력한 방지 장치를 마련할 것, 공공기관 및 지방자치단체는 지방계약법 시행령에 따라 계약특수조건으로 KS규격·인증 자재 사용 및 납품현장 검수 절차를 의무화해 공공부문이 선도하는 품질관리체계를 조속히 구축할 것" 등을 골자로 한 건의안을 발표했다.이 건의안을 대통령비서실, 국회의장, 국토교통부장관, 환경부장관, 고용노동부장관, 경기도의회, 경기도, 양주시에 발송했다고 밝혔다.', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008669419', 'https://imgnews.pstatic.net/image/421/2025/12/19/0008669419_001_20251219082720260.jpg?type=w800', 'NEWS_ETC', NULL, '2025-12-19 08:27:04', 0, true, '2026-03-09 05:40:04.547682') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (465, '코스피 급락에도 종합상사株 강세…포스코인터내셔널 8%↑', '에너지 노출 기업으로 매수세 이동[서울=뉴시스] 포스코인터내셔널 송도 사옥. (사진=포스코인터내셔널) 2025.10.29 photo@newsis.com *재판매 및 DB 금지  *재판매 및 DB 금지[서울=뉴시스]송혜리 기자 = 국제유가 급등 여파로 코스피가 9일 8% 넘게 급락하며 시장 전반이 흔들리고 있지만 종합상사 관련 종목은 오히려 강세를 보이고 있다.한국거래소에 따르면 이날 오전 10시48분 현재 포스코인터내셔널은 전 거래일보다 8.87% 오른 7만9800원에 거래되고 있다.같은 시각 LX인터내셔널은 6.46%오른 4만2050원, GS글로벌은 2.19% 오른 2570원에 거래되고 있다.최용현 KB증권 연구원은 "현재 시장 환경은 포스코인터내셔널에 우호적"이라며 "미국 에너지 노출도가 높은 일본 종합상사들도 같은 맥락에서 수혜가 예상되며 주가가 상승하고 있다"고 설명했다.이어 "포스코인터내셔널은 LNG와 팜 등 업스트림 사업을 영위하고 있어 원자재 가격이 오를 경우 판매단가 인상 효과를 기대할 수 있다"고 분석했다. 특히 "미국산 LNG 오프테이크 계약을 확보하고 있어 비교적 저렴한 가격에 물량을 도입할 수 있다는 점도 강점"이라고 덧붙였다．', NULL, '뉴시스', 'https://n.news.naver.com/mnews/article/003/0013809554', 'https://imgnews.pstatic.net/image/003/2026/03/09/NISI20251029_0001977967_web_20251029090244_20260309120516098.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 10:57:32', 0, true, '2026-03-09 05:40:27.476623') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (466, '이란 사태에 코스피 하락…포스코인터 ‘나홀로’ 8%대 급등 이유는? [종목Pick]', '증권가 ‘인플레이션 방어주’로 평가LNG 등 원자재 판매가격 상승 호재포스코인터내셔널 회사 전경. [포스코인터내셔널 제공][헤럴드경제=김지윤 기자] 코스피 지수가 장 초반 7%대 하락하는 가운데, 포스코인터내셔널의 주가가 8% 넘게 급등하고 있다.중동 전쟁으로 원자재 가격이 오르면서 액화천연가스(LNG) 판매가격이 오를 것이란 전망이 나오면서다. 포스코인터내셔널은 LNG트레이딩 사업을 영위하고 있다.9일 오전 10시11분 기준 포스코인터내셔널 주가는 전장 대비 8.05% 뛴 7만7900에 거래 중이다. 장중 8만5900원까지 오르기도 했다.증권가에서 포스코인터내셔널을 ‘인플레이션 방어주’로 평가하면서 기대감이 집중됐다.최용현 KB증권 연구원은 “현재 시장 환경이 포스코인터내셔널에 우호적”이라며 “LNG, 팜 등 업스트림을 영위하고 있어 원자재 가격이 상승하면 판매가 인상 효과를 본다”고 했다.이어 “미국 LNG 장기구매(오프테이크) 계약을 확보해 저렴하게 수입할 수 있다”고 덧붙였다.포스코인터내셔널과 함께 무역회사 및 판매업체 업종으로 묶이는 LX인터내셔널과 GS글로벌도 각각 4.81%, 1.79% 상승하고 있다.', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002610419', 'https://imgnews.pstatic.net/image/016/2026/03/09/0002610419_001_20260309102909540.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 10:29:09', 0, true, '2026-03-09 05:40:27.476623') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (467, '[특징주] 폭락장에서도 종합상사 관련 종목 강세…"반사수혜 예상"', '포스코인터내셔널 본사[포스코인터내셔널 제공](서울=연합뉴스) 고은지 기자 = 국제유가 급등에 코스피가 7%가 넘는 급락세를 나타내고 있지만, 종합상사 관련 종목은 강세를 보이는 중이다.이날 오전 10시 9분 현재 포스코인터내셔널은 전장보다 8.32% 오른 7만9천400원에 거래되고 있다.같은 시각 LX인터내셔널은 5.32% 뛴 4만1천600원, GS글로벌은 1.79% 상승한 2천560원이다.증권가에서는 종합상사 관련주를 중동 전쟁에서 상대적으로 수혜를 볼 수 있는 종목으로 평가했다.KB증권 최용현 연구원은 "중동 전쟁으로 원자재 가격 상승하면서 인플레이션 우려가 커지고 있으나 미국 에너지 가격은 상대적으로 안정세를 보이면서 미국 에너지 수출에 대한 기대감이 있다"며 "미국 에너지 노출도가 높은 일본 상사도 마찬가지로 수혜가 예상되면서 (포스코인터내셔널 등) 주가가 상승 중"이라고 분석했다.현대차증권 조창민 연구원은 "주주환원 및 지정학적 리스크 관련 모멘텀(동력) 측면에서 상사·자본재 업종을 이달 최선호 업종으로 추가 제시한다"고 말했다.eun@yna.co.kr', NULL, '연합뉴스', 'https://n.news.naver.com/mnews/article/001/0015946318', 'https://imgnews.pstatic.net/image/001/2026/03/09/PCM20240205000051003_P4_20260309102324373.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 10:22:35', 0, true, '2026-03-09 05:40:27.476623') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (479, '제분사 대표 전원 협회 이사직 사임…"담합 사죄"', '한국제분협회가 국내 제분업계의 밀가루 가격 담합과 관련해 "국민에게 큰 실망과 심려를 끼쳐 깊이 사과한다"고 밝혔습니다.제분협회는 어제(5일) 오전 정기총회를 열어 가격 담합에 대한 책임을 지고 제분회사 대표 전원이 협회 이사회에서 물러나 자숙의 시간을 갖기로 했습니다.제분협회 회원사는 대한제분, 사조동아원, 대선제분, 삼양사, CJ제일제당, 삼화제분, 한탑 등 7곳입니다.앞서 제분 7개사는 밀가루를 6년간 담합해 판 혐의로 20년 만에 다시 공정거래위원회의 심판을 받게 됐습니다.연합뉴스TV 기사문의 및 제보 : 카톡/라인 jebo23', NULL, '연합뉴스TV', 'https://n.news.naver.com/mnews/article/422/0000840967', 'https://imgnews.pstatic.net/image/422/2026/03/06/969675_1772745827_20260306063113101.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-06 06:31:13', 0, true, '2026-03-09 05:40:51.149416') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (468, '[서울데이터랩]‘조비’ 29.95% 상한가…실시간 상승률 1위', '9일 오전 9시 30분 조비(001550)가 등락률 29.95%로 상한가를 기록하며 상승률 1위를 차지했다. 조비는 개장 직후 5분 동안 60만 3112주가 거래됐으며 주가는 전 거래일 대비 4370원 오른 1만 8960원이다.한편 조비의 PER은 89.01로 고평가됐을 가능성을 시사하며, ROE는 1.2%로 수익성이 낮다고 평가할 수 있다.이어 상승률 2위 남해화학(025860)은 현재가 9860원으로 주가가 29.9% 상한가를 기록하고 있다. 상승률 3위 KG케미칼(001390)은 현재 5900원으로 19.8% 급등하며 강세를 보인다. 상승률 4위 한국ANKOR유전(152550)은 18.2% 급등하며 579원에 거래되고 있다. 상승률 5위 롯데정밀화학(004000)은 15.5%의 상승세를 타고 5만 2500원에 거래되고 있다.6위 대성에너지(117580)는 현재가 1만 3670원으로 15.2% 상승 중이다. 7위 고려산업(002140)은 현재가 3130원으로 14.0% 상승 중이다. 8위 극동유화(014530)는 현재가 4870원으로 13.7% 상승 중이다. 9위 SH에너지화학(002360)은 현재가 475원으로 13.1% 상승 중이다. 10위 한국석유(004090)는 현재가 2만 6100원으로 12.3% 상승 중이다.이 밖에도 포스코인터내셔널(047050) 11.9%, DS단석(017860) 11.8%, 경농(002100) 10.7%, 서울가스(017390) 9.9%, 대성산업(128820) 9.5%, LX인터내셔널(001120) 9.4%, 유니드(014830) 9.0%, 퍼스텍(010820) 9.0%, STX엔진(077970) 8.8%, 흥아해운(003280) 8.2% 등을 기록하며 시장에서 활발히 거래되고 있다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003624038', 'https://imgnews.pstatic.net/image/081/2026/03/09/0003624038_001_20260309100818622.png?type=w800', 'NEWS_ETC', NULL, '2026-03-09 10:08:18', 0, true, '2026-03-09 05:40:27.476623') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (469, '''나홀로 7% 뛰었다''…코스피 폭락 와중에 급등한 ''이 종목'' [종목+]', '사진=게티이미지뱅크코스피 지수가 장 초반 큰 폭으로 하락하고 있는 가운데 포스코인터내셔널은 급등하고 있다. 중동 전쟁으로 원자재 가격이 오르자 판매가 인상 효과를 볼 것이라는 분석이 나와서다.9일 오전 10시 기준 포스코인터내셔널 주가는 전장 대비 7.64% 뛴 7만8900원에 거래 중이다. 장중 8만5900원까지 올랐다.포스코인터내셔널증권가에서는 포스코인터내셔널을 ''인플레이션 방어주''로 평가했다. 최용현 KB증권 연구원은 "현재 시장 환경이 포스코인터내셔널에 우호적"이라며 "LNG, 팜 등 업스트림을 영위하고 있어 원자재 가격이 상승하면 판매가 인상 효과를 본다"고 했다. 이어 "미국 LNG 장기구매(오프테이크) 계약을 확보해 저렴하게 수입할 수 있다"고 덧붙였다.포스코인터내셔널과 함께 무역회사 및 판매업체 업종으로 묶이는 LX 인터내셔널과 GS글로벌도 각각 5.44%, 3.18% 상승률을 기록 중이다.', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005259724', 'https://imgnews.pstatic.net/image/015/2026/03/09/0005259724_001_20260309101112090.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 10:03:11', 0, true, '2026-03-09 05:40:27.476623') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (470, '2월 완성차 판매 일제히 후진…설 연휴 여파', '[워치인더픽]2월 완성차 판매 60만2689대…조업일수 감소 영향LX인터, 필리핀 구리 광산 환경 복원 공로 표창조업일수 감소에 완성차 2월 내수 판매 감소지난 2월 설 연휴로 인해 영업일수가 감소하자 국내 완성차업체의 판매량이 일제히 감소한 것으로 집계. 지난 2월 현대자동차, 기아, 한국GM, KG모빌리티, 르노코리아 등 국내 완성차 5개사의 글로벌 판매대수는 60만2689대로 지난해 2월과 비교해 4.4% 감소.해외 판매는 52만7051대로 1.8% 증가했지만 내수 판매는 9만5638대로 14.8% 줄어든 것으로 조사. 이는 올해 설날 연휴가 2월에 배치되면서 조업일수가 줄어들었기 때문으로 분석.업체별로는 현대자동차는 30만6528만대를 판매. 이는 지난해 2월과 비교해 5.1% 감소한 수준. 기아의 경우 24만7401대를 판매하며 전년 2월 대비 2.8% 줄어.중견 3사는 KG모빌리티가 전년 동월과 견줘 2.6% 줄어든 8237대를 판매. 르노는 36.2%감소한 3893대, 한국GM은 7.6%감소한 3만6000대를 판매.솔루엠, EV 충전 인프라 위해 펌프킨과 맞손솔루엠이 국내 전기 상용차 충전 기업 펌프킨과 EV충전 인프라 기술 자립 등을 위해 맞손.양사는 전기차 충전 인프라 사업 협력을 위한 양해각서를 체결. 펌프킨은 충전기 전체에 100% 국산 기술 적용을 목표로 해왔고 파워모듈 국산화가 주요 과제였는데 솔루엠과 시너지를 낼 수 있을 것으로 판단.이번 협약에 따라 양사는 △솔루엠 자체 개발 파워모듈 펌프킨 충전기 탑재 및 공동 개발 △충전기·EV차량·통합관제 포함 해외 상용차 EV 충전 토탈솔루션 협력  △신재생에너지 기반 EV 충전스테이션 사업 협력 △차세대 충전기 신규 모델 기획 및 기술 협력 등에 나서기로.솔루엠 ANP 사업부 유동균 부사장은 "상용차 충전 분야의 강자인 펌프킨과의 협력은 솔루엠의 전력전자 기술력을 현장에서 입증할 수 있는 최고의 기회"라며 "핵심 부품 기술 자립을 넘어 글로벌 시장이 인정하는 EV 충전 솔루션 기업으로 도약하겠다"고 전해.LX인터, 광산 환경 공로로 필리핀 정부 표창LX인터내셔널이 필리핀 라푸라푸 구리 광산 환경 복구 완료 공로를 인정 받아 필리핀 정부로부터 공식 표창.필리핀 정부는 라푸라푸 구리 광산 개발에서 복구까지 이어지는 자원개발 전 과정을 일관되게 책임지고 마무리 한 점을 높게 평가.LX인터내셔널은 2008년 라푸라푸 광산을 인수한 이후 △개발 △생산 △폐광 △환경복구까지 자원개발의 모든 단계를 체계적으로 수행.특히 2018년부터 본격적인 환경복구 작업에 착수해 토양 안정화, 생태 복원, 수질 관리 등 전문적이고 지속적인 복구 프로그램을 전개. 지난해 8월 필리핀 정부로부터 최종 광산 복구 및 폐광 계획 이행 완료에 대한 공식 승인을 획득. 이는 필리핀 광업 역사상 첫 환경복구 승인 사례.LX인터내셔널 관계자는 "이번 필리핀 정부의 표창은 향후 글로벌 핵심광물 확보를 추진하는 데 확고한 신뢰 기반이 될 것"이라며 "핵심광물 확보와 책임경영이 선순환하는 지속가능한 자원개발 모델을 더욱 발전시켜 나가겠다"고 전해.4일 필리핀 마닐라 콘래드 호텔에서 열린 ''한-필리핀 비즈니스 포럼''에서 LX인터내셔널의 필리핀 라푸라푸 구리 광산 환공복구 공로 표창 이후 구혁서 LX인터내셔널 대표, 미겔 쿠나 필리핀 환경자원부 장관, 이준택 LX인터내셔널 마닐라지사장이 기념사진을 촬영하고 있다. /사진=LX인터내셔널 제공현대자동차, 2027 아이오닉9 출시현대자동차가 대형 SUV 아이오닉 9의 연식 변경 모델 ''2027 아이오닉 9''을 출시. 2027 아이오닉 9은 트림별로 고객 선호도가 높은 편의 사양을 기본화해 전반적인 상품 경쟁력을 한층 강화한 것이 특징.현대차는 기본 트림인 익스클루시브에 △2열 통풍시트 △2열 스위블링 시트, 주력 트림인 프레스티지에는 △발수 적용 1열 유리, 최상위 트림인 캘리그래피에는 △3열 열선시트를 기본 적용. 기존 최상위 트림에만 적용되던 메탈 페달, 메탈 도어 스커프 등을 프레스티지 트림까지 확대.현대차 관계자는 "2027 아이오닉 9은 고객 선호 사양을 확대 적용해 상품성을 더욱 강화한 모델"이라며 "입증된 안전성과 함께 전동화 대형 SUV만의 차별화된 가치를 고객들에게 제공할 것"이라고 전함.아이오닉9. /사진=현대자동차 제공LG이노텍, 올해도 협력사 지원LG이노텍이 2026 ''동반성장 상생데이''를 개최. 이 행사는 LG이노텍이 협력사와 동반성장을 위해 상호 간의 협력을 다지는 행사로 2010년부터 매년 진행. 이번 ''동반성장 상생데이''에는 100여개 협력사가 참석. LG이노텍은 이들과 2026 공정거래 및 동반성장협약을 체결.협약에 따라 LG이노텍은 동반성장펀드, 스마트공장 구축 지원 등 금융 지원 프로그램을 시행할 예정. 협력사의 ESG 역량 강화를 위한 지원 프로그램도 지속 운영. LG이노텍은 협력사가 글로벌 ESG 경영 요구에 효과적으로 대응할 수 있도록 ESG 컨설팅을 제공.협력사 경쟁력 강화를 위한 교육 프로그램도 마련. LG이노텍은 올해 ''협력사 역량강화 훈련센터''의 프로그램에 협력사의 AI 대응 역량 강화를 위한 교육 과정을 새롭게 추가.문혁수 LG이노텍 사장은 "협력사 덕분에 LG이노텍이 탁월한 고객가치를 제공하는 신뢰받는 기술 파트너로 자리매김하고 있다"면서 "협력사와의 적극적인 상생 협력을 기반으로, 부품 기업을 넘어 최적의 솔루션을 제공하는 솔루션 기업으로 거듭날 것"이라고 말해.5일 LG이노텍이 협력사 대표를 초청한 동반성장 상생데이 행사를 개최했다. /사진=LG이노텍 제공두산에너빌, 미국서 대규모 가스터빈  수주두산에너빌리티가 미국 기업에 380MW급 가스터빈 7기 공급계약 체결. 두산에너빌은 기업이 건설하는 데이터센터에 가스터빈과 발전기를 2029년 5월부터 매달 1기씩 순차 공급할 계획.이에 두산에너빌리티는 미국에 총 12기의 가스터빈을 공급. 두산에너빌리티 측은 미국 가스터빈 수주 확대 배경으로 검증된 성능, 빠른 납기, 미국 현지 자회사의 서비스 지원을 꼽아.손승우 두산에너빌리티 파워서비스BG장은 "이번 계약 포함 총 12기 가스터빈을 미국에 공급하게 되어 글로벌 플레이어로서의 입지를 견고히 할 수 있게 됐다"며 "두산은 앞으로도 경쟁력 있는 가스터빈을 제공하며 국내외 수요 증가에 적극 대응해 나가겠다"고 말해.두산에너빌리티 가스 터빈. /사진=두산에너빌리티 제공[워치인더픽]은 매주 토요일, 한 주간 기업들의 소식을 한눈에 돌아보는 비즈워치 산업부의 뉴스 코너입니다.', NULL, '비즈워치', 'https://n.news.naver.com/mnews/article/648/0000045040', 'https://imgnews.pstatic.net/image/648/2026/03/07/0000045040_001_20260307150014131.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-07 15:00:14', 0, true, '2026-03-09 05:40:27.476623') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (471, '정기선, 필리핀 경제사절단 참여…"HD현대, 한·필 핵심 가교 역할"', 'HD현대 정기선 회장이 3월4일 필리핀 국립 영웅묘지에 위치한 한국전 참전 기념비를 찾아 헌화하고 있다. [사진=HD현대][디지털데일리 최민지기자] 정기선 HD현대 회장이 한·필리핀 경제 협력 확대와 우호 증진을 위한 가교 역할에 나섰다.HD현대는 정기선 회장이 정부 경제사절단 일원으로 필리핀을 방문해 한국전 참전 기념비 참배와 한·필리핀 비즈니스 포럼 참석, HD현대필리핀조선 점검 등을 실시했다고 5일 밝혔다.정 회장은 지난 4일 필리핀 마닐라 국립 영웅묘지에 있는 한국전 참전 기념비를 찾아 헌화했다. 필리핀은 한국전쟁 당시 아시아 국가 중 가장 먼저 전투부대를 편성해 가장 많은 7420명 병력을 파병했다.같은 날 오전에는 한국경제인협회와 필리핀상공회의소가 공동 개최한 ''한·필리핀 비즈니스 포럼''에 참석해 양국 경제 협력 확대를 위한 세부 방안을 모색했다.정 회장은 5일 필리핀 수빅만에 위치한 HD현대필리핀을 방문해 직원 기숙사 신축 현장과 야드를 둘러보며 현지 근무 직원들을 격려했다. 이날 정 회장은 직원들과 점심을 함께하며 "임직원들 불편이 없도록 주거와 의료·치안 등 분야를 더욱 각별히 챙기겠다"며 "무엇보다 안전을 최우선으로 맡은 바 일에 최선을 다해주기를 바란다"고 말했다.HD현대 조선 부문 중간지주사인 HD한국조선해양은 2024년 5월 미국 서버러스 캐피탈과 필리핀 조선소 일부 부지에 대한 임차 계약을 체결해 HD현대필리핀을 출범했다.2025년 9월에는 HD현대필리핀이 건조하는 첫 선박인 11만5000톤급 석유화학제품운반선 건조를 위한 강재 절단식을 열었다. HD현대중공업은 2016년 이후 필리핀에서 총 12척 함정을 수주해 필리핀 해군 현대화 사업에 참여하고 있다. 2022년에는 현지에 군수지원센터를 설립해 호위함·초계함 등 함정 MRO(유지·보수·정비) 사업을 진행 중이다.정기선 회장은 "HD현대는 필리핀과의 단순한 사업협력 관계를 넘어 대한민국과 필리핀 간 우호 증진을 위한 핵심적인 가교 역할을 수행해 오고 있다"며 "앞으로도 대한민국을 대표한다는 자부심으로 필리핀과 깊은 신뢰를 쌓아갈 것"이라고 강조했다.한편 이번 경제사절단은 류진 한경협 회장, 윤진식 무역협회 회장, 손경식 경총 회장, 김기문 중기중앙회 회장, 최진식 중견련 회장 등 경제단체장과 신동빈 롯데그룹 회장, 정기선 HD현대 회장, 이형희 SK 부회장, 김원경 삼성전자 사장, 성김 현대자동차 사장, 정대화 LG전자 사장, 류두형 한화 대표, 구혁서 LX인터내셔널 대표, 김정수 삼양식품 부회장, 차재병 한국항공우주산업(KAI) 대표 등으로 구성됐다.', NULL, '디지털데일리', 'https://n.news.naver.com/mnews/article/138/0002219617', 'https://imgnews.pstatic.net/image/138/2026/03/05/0002219617_001_20260305114215985.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-05 11:42:15', 0, true, '2026-03-09 05:40:27.476623') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (472, '한-필리핀 정상회담 계기…K-소비재 1600만 달러 수출계약', '‘한-필 비즈니스 포럼’ 개최…조선·원전·소비재 등 MOU 7건 성사한-필리핀 정상회담을 계기로 열린 ‘한-필 비즈니스 파트너십 행사’에서 식품·뷰티·헬스케어 등 K-소비재로 1640만 달러의 수출계약이 성사됐다.산업통상부와 KOTRA(대표 강경성)는 이재명 대통령의 필리핀 국빈방문 계기로 4일 필리핀 마닐라 SMX 컨벤션 센터에서 한-필 비즈니스 파트너십 행사를 개최했다. 이날 행사에는 식품·뷰티·헬스케어 등 소비재 기업 52개사와 필리핀 바이어 70개사가 참가해 총 11건, 1640만 달러 규모 계약을 체결했다.김정관 산업부 장관은 행사장 내 소비재·프랜차이즈 등 분야 국내 기업 전시관을 방문해 필리핀 내 K-라이프스타일 확대를 위한 방안을 논의하고, 필리핀 현지 대규모 유통망을 보유한 SM·Landers 등 현지 기업 부스를 방문해 필리핀 내 K-소비재의 인지도 제고와 판로 확대 방안을 모색했다.김정관 산업통상부 장관(앞줄 왼쪽)과 강경성 KOTRA 사장(앞줄 오른쪽)이 4일 필리핀 마닐라 SMX 컨벤션센터에서 열린 ''한-필리핀 비즈니스파트너십'' 행사에서 소비재, 프랜차이즈 등 분야 전시관 부스를 둘러보고 있다.김정관 장관은 “최근 K-뷰티·식품 등 한국 제품 인기가 빠르게 확산하고 있는 만큼 정부는 관계 부처·유관기관과 긴밀히 협력해 필리핀을 거점으로 동남아 시장에서 다양한 비즈니스 기회를 창출할 수 있도록 우리 기업의 시장 진출을 적극 지원할 것”이라고 밝혔다.산업부는 이날 행사에 앞서 한국경제인협회(회장 류진)와 함께 마닐라 호텔에서 한국과 필리핀 양국 대통령이 참석한 가운데 ‘한-필 비즈니스 포럼’을 개최했다. 양국 기업 간 협력과 교류의 장인 포럼에서는 김정관 산업부 장관과 크리스티나 A. 로케 필리핀 통상산업부 장관 임석하에 조선·원전·소비재 등 다양한 분야에서 총 7건의 MOU가 체결됐다.한국수력원자력과 한국수출입은행은 필리핀 전력기업 메랄코와 신규원전 건설사업 관련 사업·재무 모델을 공동 개발하고 인력을 양성하는 분야를 중심으로 협력하기로 합의했다. MOU를 계기로 앞으로 필리핀 신규원전 도입 시 국내 기업의 참여 기반이 강화될 것으로 예상된다.이재명 대통령의 필리핀 국빈방문을 계기로 4일 필리핀 마닐라 콘래드호텔에서 열린 ''한-필리핀 비즈니스 포럼''에서 김정관 산업통상부 장관(오른쪽 두 번째)과 크리스티나 A. 로케 필리핀 통상산업부 장관(왼쪽 두 번째)이 임석한 가운데 원전·조선·소비재 등 7건의 업무협약이 이뤄졌다.조선 분야에서는 HD현대중공업과 필리핀 기술교육개발청(TESDA)이 조선산업 기술 발전을 위한 MOU에 서명, 조선 인력양성과 기술협력이 확대될 것으로 기대된다. HD현대중공업은 필리핀 현지 생산거점인 수빅조선소에서 지난해 9월 필리핀 페르디난드 마르코스 주니어 대통령이 참석한 강재절단식을 계기로 필리핀 현지 생산에 속도를 내고 있다.식품 분야에서는 삼양식품과 필리핀 유통사 S&R 간 식품 수출 및 유통 협력을 위한 MOU를 체결, 필리핀 현지 대규모 유통망을 활용한 K-푸드의 시장 접근성이 한층 강화될 것으로 기대된다.포럼에서 진행된 발표 세션에서는 핵심광물·조선·소비재·인프라 등 분야에서 HD현대중공업·LX인터내셔널·롯데·한국수자원공사 등 국내 기업의 우수 활동 사례를 공유하고 양국 기업 간 실질적인 협력 방안을 논의했다.산업부는 이번 국빈방문 계기로 이뤄진 한-필 비즈니스 성과가 국내 기업이 체감할 수 있는 실질적 사업 기회로 연결될 수 있도록 한-필 경제협력위원회 개최 등을 통해 후속 논의를 지속하는 한편, 현지 인허가·유통 지원 등 기업 애로 해소를 위한 지원을 강화해 나갈 계획이다.', NULL, '지디넷코리아', 'https://n.news.naver.com/mnews/article/092/0002412903', 'https://imgnews.pstatic.net/image/092/2026/03/04/0002412903_001_20260305083510620.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-04 22:21:12', 0, true, '2026-03-09 05:40:27.476623') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (473, '[미리보는 이데일리 신문] 1500원대 환율, 12% 빠진 증시… 물가도 초비상', '[이데일리 유진희 기자] 다음은 5일 자 이데일리 신문 주요 기사다.△ 1면1500원대 환율, 12% 빠진 증시… 물가도 초비상‘제2 HBM’ 쇼캠2 삼성, 세계 첫 양산제2이라크전 악몽...세계경제 덮친 ‘S공포’[전문가 진단] 호르무즈 봉쇄...중동발 에너지 위기 대안은△ 종합 (2면)‘알짜’ 잠실점까지 문 닫는 홈플러스 “임금 반토막...두달 뒤도 암담합니다”전 세대 공감 부른 ‘이야기의 힘’ 파죽지세 ‘왕사남’, 1400만 보인다△ 종합 (3면)두 달간 오른 폭 이틀 만에 절반 반납: 증시 폭락으로 인해 34조 원 규모의 반대매매 공포 커졌다저항선 뚫은 환율… “강달러·고유가 지속 땐 큰 폭 오른다”러·우 전쟁 때도 물가 6.3% 급등… 중동발 인플레 비상△ 종합 (4면)美, 중동전 길어지면 ‘백전백패’...‘경제 충격·반미 확산’ 아프간戰 데자뷔중동 원유생산 이어 아시아 석유산업까지 강타하메네이 차남, 이란 새 지도자로갈라진 세계...이재명 정부 ‘실용외교’ 시험대△ 종합 (5면)최악 대비 에너지 수입처 다변화 서두르고… 기업들 물류 지원 필요호르무즈 통과 비중 54% 나프타 직격탄 해운업계, 운임 올라도 보험료 뛰어 불안△ MWC 2026 (6면)통신사 부스까지 점령한 로봇...직접 ‘福’글자 쓰고, 식당 예약도 척척GPU 효율 극대화… SKT·파네시아, 데이터센터 구조 혁신 ‘맞손’비번 입력창만 옆에서 안 보이게 ‘화면 보안’ 신기원△ 종합 (8면)전쟁 공포에 불붙은 금테크...편의성은 ‘금 ETF’, 장투엔 ‘골드바’5000피 넘자 주식 팔아 집 샀다...폭락장 앞둔 ‘신의 한수’원화 스테이블코인 담보 통안채·MMF 포함 검토삼성 ‘양산’으로 기선제압...마이크론 ‘최대용량’ 반격 채비△ 정치 (9면)李, 외교 성과 보따리 들고 왔지만… 중동 리스크·입법개혁 첩첩산중대미특위 재가동… 與野, 투자공사 설립·규모 놓고 이견“존재 자체가 위헌”… 대법원장 탄핵 몰아붙이는 與:정원오 퇴임, 윤희숙 출사표… 서울시장 레이스△ 경제 (10면)반도체 숨 고르기에 산업생산 1.3% 뚝...소비·투자는 ‘활짝’히트펌프 보급 확대 위해 144억 투입...업계 “효과 의문”“정부도 노란봉투법 대상”...시행 앞두고 총점검△ 금융 (12면)CEO 연임 특별결의 도입 ‘0’… 무안해진 금융당국금감원, 디지털자산 업계 내부통제 강화한다“저축은행 ‘상생·포용’ 물길 넓혀달라”신한금융, PF 정상화펀드로 공덕역 주상복합사업 되살렸다△ 산업 (13면)“사람처럼 움직이네”… 中 5대 로봇기업 ‘한자리’현대차·기아 ‘모베드’ 판매 본격화...로보틱스 협력 생태계 조성 나선다포스코인터, 불황에도 ‘최대 실적’...그룹 매출 절반 책임졌다삼성전자, 美 협력사 갑질 의혹 전면 부인△ ICT (14면)KT 현·차기 CEO 만나 갈등 봉합 “원만한 인수인계...경영 공백 해소”다음, 6년 만에 ‘실검’ 부활‘거래소 대주주 지분 20% 제한’ 강행하나...업계 반발NHN 사업 재편 두고 갈등...노조 “고용 보장 촉구”△ 성장기업 (16면)호르무즈 봉쇄에… 페인트·건자재 업계 비상엘리스그룹, 한·싱가포르 AI 셔틀 참여 李 대통령에 ‘이동형 데이터 센터’ 시연촬영, 판매, 배송...귀찮은 중고거래, 차란에 맡기세요엔씽, 수직 농장빌딩에 158억 규모 AI 농업 솔루션 공급△ 생활경제 (18면)코스맥스 업은 C뷰티… 신세계 시코르 뚫고 K뷰티 안방 공략빵 이어 라면값 내리나...정부, 주요 업체 소집 ‘시선 집중’“장보기는 SSG닷컴에서” 배송·품질·멤버십 강화K패션 골든타임인데...의료제조사 80% ‘5인 미만 영세업체’△ 제약·바이오 (19면)3.5조 환자 모니터링 시장 잡아라...앞서는 씨어스 VS 뒤쫓는 메쥬랩 링커, RNA 편집… 황금알 낳는 플랫폼 기술中 혈액암 신약 ‘엑스포비오’ 보령, 국내 판권·유통권 확보△ 증권 (20면)외국인, 두 달간 삼전닉스 33조 팔아치웠다반도체서 원전까지… 한투 ‘AI 풀밸류체인’ 투자 구축반등에 베팅한 개미...레버리지 ETF 3155억원 매수“액티브·해외 상장 양 날개...3년 내 ETF 100조 도전”‘1.8조 빅딜’ 성사한 아이엠바이오 “면역질환약 사노비와 경쟁 자신”△ 부동산 (21면)학군지 아파트 전세 씨 마르고 가격 뛰자… 맹모들 ‘빌라 매수’로광화문 ‘감사의 정원’ 공사 중지...국토부 vs 서울시 충돌LH, 올해 전세임대 3만 7580가구 공급△ 엔터테인먼트 (22면)CD 대신 MD 사는 시대블랙핑크·BTS, 앨범 참여진도 ‘월드 클래스’△ 피플 (24면)“AI 기술, 그 끝은 사람을 향해야” 구광모 인재철학 담은 대학원 출범“한·필리핀 협력 강화...공급망 핵심축 도약”한국IPTV방송협회장에 유용화 교수 내정“라푸라푸 구리 광산 환경 복구 성공” 필리핀 정부, LX인터내셔널에 표창△ 오피니언 (25면)이면근의 사람이야기 플랫폼 공룡 쿠팡 vs 국가의 책임생생확대경 끝나지 않은 콘텐츠 괴물의 위협e갤러리 권세진 ‘고요한 풍경·램프’△ 전국 (26면)경기북부 지자체 ‘세수 500억’ 경마장 쟁탈전수도권 7개 지자체, 경부선 지하화 촉구대전·충남 통합 사실상 무산...6·3 지방선거 판세 요동미지급 초과수당, 순직 소방관에도 지급한다△ 사회 (27면)실종·시설아동 정보·사진 유출보고도 반년간 쉬쉬...복지부 늑장 눈총단속 7분 만에 음주운전 적발… 새학기 등굣길 ‘위태위태’강북모텔 살인 피의자, 2년 전엔 절도 행각택배포장 기준 손질...자동화 포장 50cm→60cm로', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006228631', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2026-03-04 21:45:11', 0, true, '2026-03-09 05:40:27.476623') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (474, '구리광산 복구 LX인터내셔널, 필리핀 정부 표창', '구혁서 LX인터내셔널 대표(오른쪽)가 4일 마닐라 콘래드호텔에서 열린 ''한-필리핀 비즈니스 포럼''에서 후안 미겔 쿠나 필리핀 환경자원부 장관(가운데), 이준택 LX인터내셔널 마닐라지사장과 함께 기념촬영을 하고 있다. LX인터내셔널 제공LX인터내셔널이 필리핀 라푸라푸 구리 광산의 환경복구를 성공적으로 완료한 공로를 인정받아 필리핀 정부로부터 공식 표창을 받았다고 4일 밝혔다.시상식은 이날 마닐라 콘래드호텔에서 열린 ''한-필리핀 비즈니스포럼'' 현장에서 진행됐으며, 후안 미겔 쿠나 환경자원부(DENR) 장관이 구혁서 LX인터내셔널 대표에게 직접 표창을 수여했다. 구 대표는 필리핀 경제사절단 자격으로 이날 행사에 참석했다.LX인터내셔널 관계자는 "필리핀 정부가 자국 광업 역사상 최초로 환경복구 의무를 이행한 사례에 직접 시상을 했다는 점에서 의미가 있다"고 설명했다.시상식 이후에는 LX인터내셔널 마닐라지사장이 발표자로 나서 라푸라푸 광산 프로젝트를 양국 간 핵심광물 협력의 대표 사례로 소개했다.', NULL, '파이낸셜뉴스', 'https://n.news.naver.com/mnews/article/014/0005486302', 'https://imgnews.pstatic.net/image/014/2026/03/04/0005486302_001_20260304183627436.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-04 18:36:27', 0, true, '2026-03-09 05:40:27.476623') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (475, '“7년반 담합, 영향 매출액만 무려 6조원”…이 대통령 물가단속에 유통업계 ‘긴장’', '공정위 전분당·제분 담합 조사 속도교육부 학교 5700곳 교복비 조사도생리대 가격 인하·초저가 제품 등장“생활물가 언급 잇따르자 업계 긴장”이재명 대통령이 지난 6일 오전 청와대에서 열린 수석보좌관회의를 주재하는 모습. [김호영 기자]이재명 대통령이 생리대와 교복 가격 문제에 이어 제당·제분 업계의 담합 의혹까지 언급하며 생활물가 점검을 강화하고 있다. 국민 생활과 밀접한 품목을 중심으로 정부의 조사와 규제 가능성이 커지면서 유통·식품업계 전반에 긴장감이 확산하는 분위기다.8일 정치권과 유통업계에 따르면 이 대통령과 정부는 최근 생활물가 안정 필요성을 잇달아 강조하며 생필품과 식품 등 국민 체감도가 높은 품목의 가격 동향을 예의주시하고 있다. 특히 제당·제분·전분당 제조·판매사를 대상으로 한 담합 의혹 조사에도 속도를 내는 모습이다.공정거래위원회는 지난 5일 전분당 담합 사건에 관한 심사보고서를 대상, 사조CPK, 삼양사, CJ제일제당 등 4개 사에 발송하고 같은 날 전원회의에 제출해 심의 절차가 개시됐다고 6일 밝혔다.공정위에 따르면 이들 4개 사는 2018년 5월부터 지난해 10월까지 총 7년 6개월 동안 전분당 판매 가격을 반복적으로 담합한 혐의를 받는다.전분당은 옥수수를 분쇄해 만든 전분과 이를 분해해 생산한 당류(물엿·포도당·액상과당 등)를 말하며 주로 식품용과 산업용 원료로 쓰인다.이들 업체는 국내 전분당 기업간거래(B2B) 판매시장에서 약 90%의 점유율을 차지한다. 담합 행위로 영향을 받은 관련 품목 매출액은 총 6조2000여억원에 이르는 것으로 산정됐다.유성욱 공정거래위원회 조사관리관이 6일 세종시 정부세종청사에서 4개 전분당 제조판매 사업자의 부당 공동행위 건에 대한 심의 상정 내용을 발표하고 있다. [뉴스1]공정위 심사관은 지난해 10월부터 이달 초까지 142일간 조사 끝에 이를 공정거래법을 위반한 중대한 위법 행위로 판단했다. 심사 보고서에는 가격 재결정 명령을 포함한 시정 조치, 과징금 부과 및 관련자 고발 의견이 담겼다.제분업계 역시 담합 의혹과 관련해 고개를 숙였다. 한국제분협회는 정기총회에서 밀가루 가격 담합 논란과 관련, 논란에 대한 책임을 지고 제분회사 대표 전원이 협회 이사회에서 물러나 자숙의 시간을 갖기로 했다.제분협회 회원사는 대한제분, 사조동아원, 대선제분, 삼양사, CJ제일제당, 삼화제분, 한탑 등 7곳이다.공정거래위원회는 7개 제분사가 2019년 11월부터 작년 10월까지 B2B에서 밀가루 판매 가격과 물량 배분을 밀약한 혐의를 전원회의에서 심의하기로 했다고 지난달 20일 발표했다. 담합 판단이 나오면 공정위는 관련 매출액의 최대 20%까지 과징금을 부과할 수 있으며 규모는 최대 1조2000억원에 이를 수 있다는 분석도 나온다.지난달 26일 서울 송파구 나눔교복매장을 찾은 학부모가 교복을 고르고 있다. [연합뉴스]교복 가격도 정부 점검 대상에 올랐다.교육부는 지난달 26일 ‘민생물가 특별관리 관계장관 태스크포스(TF)’ 회의에서 교복 가격 개선 방안을 발표했다. 정장형 교복을 줄이고 생활복·체육복 중심으로 전환하는 한편 가격 구조 전반을 점검하겠다는 내용이다.교육부는 오는 16일까지 전국 중·고등학교 약 5700곳을 대상으로 교복비 전수조사를 진행해 가격 적정성을 분석할 방침이다.쿠팡의 PB 자회사 씨피엘비(CPLB)가 생리대를 최저 99원에 제공하기로 했다. 중대형 PB 생리대 판매가를 최대 29% 인하했다. [쿠팡 제공]생리대 가격 역시 이 대통령 발언 이후 생활 물가 이슈로 떠올랐다. 일부 유통업체와 제조사들은 저가 제품 출시와 할인 판매에 나서며 즉각적인 반응을 보였다.이 대통령의 지시에 가장 먼저 응답한 건 쿠팡이다. 쿠팡은 중형 생리대 가격을 개당 120~130원에서 99원으로, 대형 생리대는 140~150원대에서 105원으로 인하했다.아성다이소는 깨끗한나라와 손잡고 오는 5월 ‘10매 1000원’ 생리대 출시를 예고했다. 이는 기존 판매가 대비 최대 60% 낮은 수준이다.홈플러스 중형 기준 개당 99원인 초저가 생리대를 지난달 28일부터 판매하고 있다. 중형 14매가 1380원으로 개당 98.57원이다. 1인 5개까지 구매할 수 있다.업계 안팎에선 정부의 점검이 특정 품목을 넘어 유통·식품업계 전반으로 확대될 수 있다는 우려도 제기된다.업계 관계자는 “생활물가와 직결된 품목들이 잇달아 언급되면서 업계도 상황을 예의주시하고 있다”며 “가격 정책이나 마케팅 전략을 더욱 신중하게 검토하는 분위기”라고 말했다.', NULL, '매일경제', 'https://n.news.naver.com/mnews/article/009/0005646820', 'https://imgnews.pstatic.net/image/009/2026/03/08/0005646820_001_20260308162708529.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-08 16:27:08', 0, true, '2026-03-09 05:40:51.149416') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (476, '가공식품·돼지고기·계란·교복·주유소…''물가 감시망'' 넓히는 공정위', '밀가루·전분당 담합에 최대 1조대 과징금돼지고기·계란 가격 담합 제재 절차 착수교복·가공식품·에너지 등 광범위 조사 중"민생 밀접한 품목 점검…부당 이익 대응"[서울=뉴시스] 정병혁 기자 = 지난달 27일 서울 서초구 하나로마트 양재점에 밀가루가 진열돼 있는 모습. 2026.02.27. jhope@newsis.com **사진은 기사 내용과 직접 관련 없습니다**[세종=뉴시스]여동준 기자 = 공정거래위원회가 설탕에 이어 밀가루·전분당 등 식료품 담합에 대한 심의에 착수했다. 가공식품과 주유소까지 감시 범위를 넓히며 물가 관리에 나서고 있다.농축산물, 교복 시장 등에 대한 조사도 동시에 진행하면서 민생 물가와 직결된 분야 전반으로 조사망을 확대하는 모습이다.공정위가 담합 단속을 통해 가격 인상 요인을 차단하는 물가 감시자 역할을 강화하고 있다는 평가가 나온다.7일 정부 등에 따르면 공정위는 최근 밀가루·전분당 등 주요 식료품 시장에서 발생한 담합 사건에 대한 심의에 착수했다.이들 품목은 과자·빵·음료 등 가공식품의 핵심 원료이자 소비자 물가에 직접적인 영향을 미치는 품목이다.대표적인 사례가 설탕 담합 사건이다. 공정위는 지난달 CJ제일제당·삼양사·대한제당 등 3개 제당사가 약 4년 동안 가격을 담합한 사실을 적발하고 과징금 총 4083억원을 부과하고 시정명령을 내렸다.조사 결과 이들 업체는 원당 가격이 하락했음에도 이를 제품 가격에 즉시 반영하지 않고 인하 시점을 늦추는 방식으로 가격을 유지한 것으로 나타났다. 이 과정에서 발생한 관련 매출액은 약 3조2884억원 규모로 집계됐다.[서울=뉴시스] 고승민 기자 = 서울의 한 대형마트에 진열된 설탕 제품 모습. 2024.03.11. kkssmm99@newsis.com밀가루 시장에 대한 제재도 임박했다. 공정위는 대선제분·대한제분·CJ제일제당 등 7개 제분업체의 가격 담합 의혹에 대한 조사를 마치고 최근 심사보고서를 발송했다.해당 사건의 관련 매출액은 약 5조8000억원 규모로 추산된다. 공정거래법상 관련 매출액의 최대 20%까지 과징금을 부과할 수 있어 이론상 최대 1조1600억원대 과징금이 가능하다는 전망도 나온다.전분당 시장에서도 장기간 담합 정황이 포착됐다. 대상·사조CPK·삼양사·CJ제일제당 등 4개 업체가 약 7년 6개월 동안 가격을 공동으로 조정한 혐의다.전분당 사건의 경우 관련 매출액이 약 6조2000억원으로 산정돼, 최대 1조2400억원 수준의 과징금 부과 가능성이 점쳐진다.공정위는 밀가루·전분당 가격 담합에 대해 가격 재결정 명령을 함께 내리는 방안도 검토하고 있는 것으로 전해졌다.가격 재결정 명령은 기업이 담합으로 결정한 가격을 다시 정하도록 하는 제도로, 실제로 발동될 경우 약 20년 만의 사례가 된다.[서울=뉴시스] 최진석 기자 =  3일 서울 롯데마트 서울역점에서 고객이 돼지고기를 고르고 있다. 2026.03.03. myjs@newsis.com공정위의 감시망에는 돼지고기와 계란도 포함됐다.공정위는 지난해 10월 돼지고기 납품 가격과 생돈 구매 가격을 담합했다는 의혹을 받는 목우촌·도드람·대성실업·부경양돈농협·충남양돈농협·CJ피드앤케어 등 육가공 업체 6곳에 심사보고서를 발송했다.이들은 축산 농가에서 구입한 돼지고기를 가공한 뒤 대형마트나 대리점에 납품하는 과정에서 가공육 가격을 담합했다는 의혹을 받았다.지난달에는 계란값 상승을 주도한 의혹을 받는 산란계 협회에 대한 제재 절차에 착수했다.공정위는 산란계협회가 고시가격을 발표한 뒤 회원사가 이를 따르도록 강제해 가격 상승을 주도한 것으로 의심하고 있는 것으로 알려졌다.식료품뿐 아니라 민생에 직결되는 교복도 물가 관리 대상에 올랐다.공정위는 조만간 광주 지역 136개교 27개 업체의 입찰 담합 사건에 대한 심의를 진행할 예정이다.동시에 4개 교복 제조사 및 전국 40개 내외 대리점을 대상으로 조사를 진행 중이다.[서울=뉴시스] 추상철 기자 = 12일 오후 서울시내 한 대형마트에서 외국인 관광객이 라면을 고르고 있다. 농림축산식품부는 지난해 K-푸드 플러스(+) 수출액이 한류 콘텐츠의 글로벌 인기와 ''K-매운맛'' 열풍 확산으로 라면·소스·아이스크림 등 가공식품을 주도로 역대 최고인 136억 달러를 돌파했다고 밝혔다. 2026.01.12. scchoo@newsis.com공정위는 향후 조사 범위를 가공식품과 에너지 분야로 확대할 계획이다.우선 라면·과자·빵·아이스크림 등 가공식품 가격 동향을 살펴볼 예정이다. 원재료 가격 하락에도 부당한 방법으로 제품 가격이 내려가지 않는다면 체감 물가 하락으로 이어지지 않기 때문이다.공정위는 출고가·소비자가·단위가격 등을 집중 모니터링하고, 담합 등 불공정거래행위가 우려되는 경우 신속히 조사에 착수할 예정이다.중동 사태를 빌미로 에너지 가격의 변동성이 커진 가운데, 이를 빌미로 담합 등 부적절한 방법으로 가격을 인상하는 행태에 대한 점검도 진행한다.가격 담합이나 눈속임 판매 등 시장 질서를 교란하는 행위가 포착되면 곧바로 조사를 개시할 계획이다.장례식장 리베이트 관행에 대한 조사도 전국 단위로 진행되고 있다. 리베이트 비용이 이용자에게 전가되는 것으로 됐기 때문이다.이재명 대통령이 거듭 담합 등 부당한 방법으로 물가를 높이는 행위에 대한 엄벌을 주문하는 상황에서, 공정위의 물가당국으로서의 역할은 더욱 강화될 것으로 예상된다.주병기 공정위 위원장은 "국민 생활과 밀접한 주요 민생품목에 대한 점검을 강화할 예정"이라며 "원재료 가격 상승에 편승해 생필품 등 가격을 과도하게 인상하거나, 사재기 및 가격담합 등 불공정행위를 통해 부당한 이익을 편취하지 못하도록 강력히 대응하겠다"고 강조했다.[서울=뉴시스] 최동준 기자 = 주병기 공정거래위원장이 지난달 24일 청와대에서 열린 국무회의에서 발언하고 있다. 2026.02.24. photocdj@newsis.com', NULL, '뉴시스', 'https://n.news.naver.com/mnews/article/003/0013807362', 'https://imgnews.pstatic.net/image/003/2026/03/07/NISI20260227_0021189503_web_20260227105529_20260307160022836.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-07 16:00:00', 0, true, '2026-03-09 05:40:51.149416') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (477, '빵·아이스크림 가격 낮아질까···‘짬짜미’ 혐의 등 전분당 4사에 최대 1조원대 과징금 및 가격재결정명령 착수', '공정위 심사보고서전분당 제조 4개사, 7년 6개월간 담합 혐의밀가루 담합때도 제재에 들어간 ‘가격 재결정 명령’도 포함이르면 5월쯤 전원회의 거쳐 최종 결정지난달 6일 서울 시내 대형마트에 설탕, 밀가루 판매대 모습. 연합뉴스공정거래위원회가 빵·아이스크림 원재료인 전분당을 7년 넘게 담합해 판 혐의로 대상 등 4개사를 제재하는 절차를 시작했다. 심사보고서에는 이들이 담합으로 6조원대 매출액을 기록해 최대 1조2000억원대 과징금을 부과할 수 있다는 의견이 담겼다. 가격을 내리라는 가격재결정 명령도 포함됐다. 공정위는 향후 이의 신청 절차를 거쳐 이르면 5월쯤 전원회의에서 과징금 등 최종 제재수위를 확정한다.공정거래위원회는 6일 전분당 담합 사건에 대한 심사보고서를 전날 4개 전분당 제조 및 판매사업자들에게 송부했다고 밝혔다. 4개사는 대상·사조CPK·삼양·CJ제일제당 등이다. 최종 제재 수위는 공정위 전원회의를 거쳐 확정된다.전분당은 옥수수 가공물인 ‘전분유액’을 분해해 얻은 포도당·물엿·과당 등 당류를 말한다. 통상 청량음료나 케이크·빵·아이스크림 등 가공식품의 원재료로 사용된다.공정위 심사관 측은 4개사가 2018년 5월부터 지난해 10월까지 7년6개월에 걸쳐 전분당 판매가격 담합행위를 했다고 판단했다. 이들의 담합 관련 매출액은 6조2000억원에 이르는 것으로 추산됐다.공정위 심사관은 4개사의 담합이 ‘중대한 위법 행위’에 해당한다고 판단, 가격재결정 명령을 포함한 시정조치를 부과해달라는 의견을 냈다. 가격재결정 명령은 법 위반 업체들이 담합 제품의 적정 가격을 재산정해 공정위에 산정 근거 등을 보고하도록 하는 제도로, 사실상 제품 가격을 담합 이전 수준으로 낮추는 효과가 있다. 이는 지난달 밀가루 담합 제재 당시에 20년만에 등장한 제재 조치다.공정위 심사관은 관련 매출액의 최대 20%까지 과징금 부과가 가능하다고 설명했다. 관련 매출액을 대입해보면 4개사에 대한 과징금은 최대 1조2400억원 달한다. 심사보고서에는 과징금 및 담합 주도 임직원에 대한 고발 의견도 담겼다. 공정위는 지난달 검찰 요청에 따라 4개사 법인을 먼저 고발해둔 상태다.공정위는 설탕 담합 조사 과정에서 전분당 관련 합의 혐의를 포착해 지난해 10월부터 조사를 벌였다. 이후 140여일 만에 조사를 마무리하고 전원회의에 안건을 상정했다.이재명 대통령이 담합 근절을 여러 차례 강조하면서 공정위도 ‘속도전’에 들어간 모습이다. 공정위 심사관 측은 4개사의 가격 담합행위 외에도 입찰담합 행위와 전분당 부산물 가격 담합행위에 대해서도 조사를 진행 중이라고 밝혔다.공정위는 지난달 20일에도 CJ제일제당·대한제분 등 7개 제분업체가 2019년부터 약 6년간 밀가루 시장에서 담합을 벌인 행위에 대한 제재 절차에 착수했다.업계도 바짝 몸을 낮추고 있다. CJ제일제당·사조CPK는 올해 들어 B2B(기업간 거래) 전분당 가격을 3~5% 낮춘 바 있다. 제분업체들도 잇따라 가격 인하 방침을 밝혔다.유성욱 공정위 조사관리관은 “담합이 빵·아이스크림 가격 상승에도 간접적으로 영향을 미쳤을 것으로 보인다”면서 “최근 전분당 업체들이 일부 가격을 내리기는 했으나 그것이 적정가격 수준인지는 심의과정에서 더 살펴볼 문제”라고 말했다.', NULL, '경향신문', 'https://n.news.naver.com/mnews/article/032/0003431620', 'https://imgnews.pstatic.net/image/032/2026/03/06/0003431620_001_20260306140910027.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-06 12:00:01', 0, true, '2026-03-09 05:40:51.149416') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (478, '정부 칼 빼들자 ''설탕·밀가루'' 인하…가공식품 가격 상승 둔화 이어질듯', '지난달 가공식품 물가 오름세 주춤밀가루·설탕 상승폭 둔화 영향 미친듯정무 민생물가 관련 담합조사 영향제당·제분사 가격 인하 다음달 본격 반영 전망(서울=뉴스1) 최지환 기자 = 27일 서울의 한 대형마트에서 직원이 밀가루 제품을 정리하고 있다.  지난 26일 CJ제일제당은 밀가루 제품 가격을 평균 5% 추가 인하한다고 밝혔다. 이는 지난달 업소용, 이달 초 소비자용 밀가루 가격을 각각 평균 4%, 5.5% 내린 데 이은 후속 조치다. 2026.2.27/뉴스1  Copyright (C) 뉴스1. All rights reserved. 무단 전재 및 재배포,  AI학습 이용 금지. /사진=(서울=뉴스1) 최지환 기자지난달 가공식품 물가 상승폭이 둔화된 데는 정부의 민생물가 관련 담합 조사가 영향을 미친 것으로 풀이된다. 가공식품은 지난달 2.1% 상승해 전월(2.8%) 대비 오름폭이 둔화됐다. 2024년 12월(2.0%) 이후 14개월 만에 최저치다.6일 국가데이터처에 따르면 가공식품 물가는 지난해 4~9월까지 4%대 상승률(전년 동월 대비)을 지속하다 2%대로 상승폭을 축소했다. 재정경제부는 가공식품 물가가 설 명절 할인행사와 밀가루 가격 인하 등으로 지난달 2.1% 상승했다고 전했다. 이두원 데이터처 경제동향통계심의관은 "(공정거래위원회의 민생물가 관련 담합 조사가) 가공식품 상승폭이 둔화된 이유 중에 하나로 보인다"고 말했다.앞서 지난달 12일 공정위는 4년여에 걸쳐 설탕 판매가격을 담합한 CJ제일제당과 삼양사, 대한제당 등 제당 3사에 4000억대 과징금을 부과했다. 또 지난달 19일 CJ제일제당과 대한제분, 삼양사 등 7개 밀가루 제조 및 판매사업자들의 가격 담합 의혹에 대해 심사보고서(검찰 공소장 격)를 발송했다. 심사보고서에는 가격 재결정명령을 포함한 시정명령과 함께 과징금 부과가 필요하다는 내용이 담겼다.이에 CJ제일제당, 삼양사 등 국내 주요 제당·제분사는 공정위의 담합 조사 후 밀가루·설탕 가격을 4~6% 인하했다. 특히 CJ제일제당은 업소용(1월 초)·소비자용(2월 초) 밀가루 가격을 각각 평균 4%, 5.5% 내린 데 이어 밀가루 제품 가격도 평균 5% 추가 인하했다.실제로 설탕은 지난달 전년 동월 대비 0.4% 상승해 상승폭을 축소했고, 밀가루는 0.6% 하락했다. 밀가루는 지난 1월 상승률이 2.3%를 기록했으나 하락 전환한 것이다. 특히 밀가루 가격은 전월 대비 2.4% 감소했다.제빵업계로도 가격 인하 조치가 확산되는 중이다. SPC그룹의 파리바게트는 다음달 13일부터 빵 6종과 케이크 5종 가격을 내린다. CJ푸드빌이 운영하는 뚜레쥬르도 빵과 케이크 17종의 공급가를 평균 8.2% 내린다. 삼립도 가격 인하를 검토 중이다. 3월엔 가공식품 물가 상승폭이 더 줄어들 수 있다는 전망이 나오는 이유다.이 심의관은 "출고가를 인하한다고 해서 바로 매장에 반영되긴 힘들고 기존에 유통됐던 물량들이 소화되면서 순차적으로 반영되지 않을까 예상 중이다"며 "다음달 가공식품의 상승폭이 더 줄어들 것으로 예상하고 있다"고 말했다.추가적인 가격 인하 가능성도 나온다. 주병기 공정위 위원장이 인하를 압박하고 있어서다. 주 위원장은 지난달 23일 국회에서 "원자재 가격이 하락했기 때문에 어림짐작해도 10% 이상은 하락하는 게 맞는 것 같다"며 제분업계의 5% 가격 인하 조치가 필요하다는 취지의 답변을 했다. 특히 가격 하락을 지속적으로 모니터링하고 관련된 식품 가공업체의 추가 가격 인하도 필요하다고 했다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005326300', 'https://imgnews.pstatic.net/image/008/2026/03/06/0005326300_001_20260306105119319.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-06 10:50:47', 0, true, '2026-03-09 05:40:51.149416') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (480, '밀가루 가격 담합 공개 사과 제분협회 이사회 전원 사퇴', '국내 주요 제분업체 대표들이 밀가루 가격 담합 사건과 관련해 공개 사과하고 협회 이사직에서 물러나기로 했다.한국제분협회는 5일 정기총회를 열고 최근 제분업계 밀가루 가격 담합 논란에 대해 “국민께 큰 실망과 심려를 끼친 점을 깊이 사과한다”며 책임을 통감한다는 입장을 밝혔다. 협회는 담합 사태에 대한 책임을 지는 차원에서 제분회사 대표들로 구성된 협회 회장과 부회장, 이사 등 이사회 구성원 7명 전원이 이사직에서 물러나기로 했다고 설명했다.이번 사과는 공정거래위원회의 담합 조사와 제재 절차가 진행되는 가운데 나왔다. 공정위는 지난달 20일 대한제분, 사조동아원, 대선제분, 삼양사, CJ제일제당, 삼화제분, 한탑 등 7개 제분사가 2019년 11월부터 지난해 10월까지 기업 간 거래(B2B) 시장에서 밀가루 판매 가격과 물량을 사전에 조율한 혐의가 있다고 발표했다. 이들 업체는 납품 가격을 함께 올리고 수요처별 공급 물량을 나누는 방식으로 담합을 벌인 것으로 공정위는 보고 있다.공정위에 따르면 담합과 관련된 매출 규모는 약 5조 8000억 원에 달한다. 공정위는 가격 재결정 명령을 포함한 제재 방안을 담은 심사보고서를 해당 업체들에 전달했으며 전원회의 심의를 거쳐 제재 수위를 결정할 예정이다. 담합이 인정될 경우 관련 매출액의 최대 20%까지 과징금이 부과될 수 있어 제재 규모가 최대 1조 2000억 원에 이를 수 있다는 전망도 나온다.조사 이후 일부 업체들은 가격 조정에 나섰다. CJ제일제당 등 일부 제분사는 밀가루 제품 가격을 최대 6% 인하했다.', NULL, '부산일보', 'https://n.news.naver.com/mnews/article/082/0001369583', 'https://imgnews.pstatic.net/image/082/2026/03/05/0001369583_001_20260305182821466.JPG?type=w800', 'NEWS_ETC', NULL, '2026-03-05 18:28:21', 0, true, '2026-03-09 05:40:51.149416') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (481, '증권 전문가들 "유가 방향성이 시장 최대 변수"', '[9일 서울 중구 하나은행 본점 딜링룸에 코스피가 표시돼 있다. 이날 코스피는 하락 출발해 장 초반 5,200대까지 내려앉았다. (사진=연합뉴스)]증권 전문가들은 향후 국내 주식시장은 이란전쟁의 흐름과 유가의 방향성이 최대 변수로 작용할 것으로 전망했습니다.여기에 스태그플레이션(고물가 속 경기침체) 우려까지 대두되면서 증시에 드리워진 먹구름이 예상보다 오래갈 수 있다는 우려가 나왔습니다. 다만, 신재생에너지, 종합상사 등 일부 종목은 반사 수혜를 볼 수도 있다는 의견도 제기됐습니다.오늘(9일) 코스피는 고유가 충격에 전장보다 319.50포인트(5.72%) 급락한 5,265.37로 출발해 낙폭이 커지며 5,100선까지 밀린 상황입니다.미국, 이스라엘과 이란 간 전쟁 여파로 걸프 지역 원유 공급망이 크게 흔들리면서 국제유가가 심리적 저항선인 배럴당 100달러를 넘어선 데 따른 것입니다.미국 뉴욕상품거래소에서 4월 인도분 서부텍사스산원유(WTI) 선물 가격은 한국시간으로 이날 오전 7시 26분 기준 전장 대비 14.85% 오른 배럴당 107.54달러를 기록했습니다. WTI는 한때 111.24달러까지 올랐습니다.WTI 가격이 배럴당 100달러를 넘어선 것은 2022년 7월 이후 처음입니다.국제 유가 기준인 브렌트유는 같은 시각 영국 런던 ICE 선물거래소에서 14.85% 오른 배럴당 107.54달러에 거래됐습니다.브렌트유 가격 역시 한때 배럴당 111.04달러까지 고점을 높였습니다.유가 급등에 원/달러 환율은 1,500원을 목전에 두고 있습니다.유진투자증권 허재환 연구원은 "호르무즈 해협은 사실상 봉쇄됐고, 중동 지역 유류 창고 여력은 상당 부분 소진됐을 것으로 점쳐진다"고 분석했습니다.증권가는 유가의 방향성에 촉각을 곤두세우고 있습니다.키움증권 한지영 연구원은 "한국 증시는 미국과 이란 간 전쟁 흐름, 국제유가 방향성, 미국 물가·경기 지표 등 굵직한 이벤트를 소화하는 과정에서 변동성 장세가 지속될 것"이라고 전망했습니다. 이번 주 코스피 예상 범위는 5,150∼5,800으로 제시했습니다.전문가들은 유가 급등이 스태그플레이션으로 이어질 수 있다는 점에도 유의해야 한다고 입을 모았습니다.신영증권 박소영 연구원은 "미국 증시는 유가 급등과 미국 고용지표 둔화로 스태그플레이션 우려가 대두되면서 임의소비재·소재·정보기술(IT) 중심의 약세가 나타났다"고 전했습니다.허 연구원은 "과거 유가가 두 배 오르면 전 세계 경제가 스태그플레이션 압력 이후 침체에 빠졌던 경험이 있다"면서 "이란 전쟁이 확전 조짐을 보이는 만큼 위험에 대비할 필요가 있다"고 말했습니다.나아가 전쟁이 확전될 기미도 보이면서 당분간 유가가 진정되긴 어려울 것으로 예상되지만, ''패닉 셀링''(공황 매도)에 나서는 것은 바람직하지 않다고 전문가들은 조언했습니다.대신증권 이경민 연구원은 "현재 코스피는 경기 악화, 실적 악화를 선반영한 수준까지 내려왔다고 본다"면서 "만에 하나 경기와 실적이 꺾일 수 있더라도 그전까지 최소한 반등이 가능하다고 본다"고 말했습니다.이번 사태로 인해 반사 수혜가 기대되는 종목도 나오고 있습니다.허 연구원은 "유가 100달러는 부담스럽다"면서도 "그러나 방산, 정유와 함께 도널드 트럼프 미국 대통령 정책의 피해 산업들, 예컨대 신재생에너지 등은 새로운 국면을 맞을 수 있다"고 말했습니다.KB증권 최용현 연구원은 "전쟁으로 원자재 가격 상승하면서 인플레이션 우려가 커지고 있으나 미국 에너지 가격은 상대적으로 안정세를 보이면서 미국 에너지 수출에 대한 기대감이 있다"며 "미국 에너지 익스포저(위험노출)가 높은 일본 상사와 마찬가지로 국내 상사도 수혜가 예상되면서 주가가 상승 중"이라고 짚었습니다.당신의 제보가 뉴스로 만들어집니다.SBS Biz는 여러분의 제보를 기다리고 있습니다.홈페이지 = https://url.kr/9pghjn', NULL, 'SBS Biz', 'https://n.news.naver.com/mnews/article/374/0000496632', 'https://imgnews.pstatic.net/image/374/2026/03/09/0000496632_001_20260309142710624.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 12:09:09', 0, true, '2026-03-09 05:41:07.754843') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (482, '유가 급등에 한국 증시 패닉…매도 사이드카 발동', '▲ 9일 서울 중구 하나은행 본점 딜링룸 현황판에 두바이유 선물 가격, 코스피가 표시돼 있다이란 사태가 장기화할 조짐을 보이면서 국제유가가 배럴당 100달러 선을 돌파하자 코스피가 오늘(9일) 장 초반 7% 넘게 급락하는 등 국내 증시에 충격이 미치고 있습니다.오늘 한국거래소에 따르면 오늘 오전 9시 58분 현재 코스피는 전장보다 404.90포인트(7.25%) 내린 5,179.97을 나타내고 있습니다.5.72% 내린 5,265.37로 출발한 지수는 오전 9시 28분쯤에는 5,171.53까지 밀리기도 했습니다.개장 직후부터 과도한 급락세가 나타나면서 오전 9시 6분 2초쯤에는 프로그램 매도호가 일시효력정지(사이드카) 조처가 발동돼 5분간 프로그램 매도호가의 효력이 정지되기도 했습니다.유가증권시장에서는 현재 외국인과 기관이 각각 1조 2천159억 원과 8천723억 원을 순매도하며 지수를 끌어내리고 있습니다.반면 개인은 2조 326억 원을 순매수하며 저가 매수에 나서는 모양새입니다.같은 시각 코스닥은 67.15포인트(5.82%) 내린 1,087.52를 보입니다.지난주 코스피가 10.6% 급락하는 동안 코스닥 낙폭이 3.2%에 그치는 등 중동발 불확실성에 상대적으로 견조한 모습을 보였던 것과 달리 오늘은 충격의 강도가 크게 차이 나지 않는 모습입니다.증권가에선 정부의 코스닥 활성화 정책에 대한 기대감이 살아있다는 점을 들어 이번 주 코스피에서 코스닥으로의 ''머니무브''가 지속될 가능성에 무게를 둬 왔지만, 유가급등에 따른 충격이 시장 전반에 영향을 미치면서 당장은 차별성이 크게 나타나지 못한 것으로 보입니다.국제유가가 심리적 저항선인 배럴당 100달러를 넘어선 것이 증시 급락의 주된 배경이 됐습니다.지난주 마지막 거래일인 6일 뉴욕증시 3대 지수는 국제유가 급등과 고용 지표 충격에 일제히 하락했는데, 그 이후에도 국제유가가 꾸준히 치솟다가 100달러 선 위로 치솟자 투자심리가 크게 위축된 것으로 풀이됩니다.한국시간 오늘 오전 9시 30분 현재 미국 뉴욕상품거래소에서 4월 인도분 서부텍사스산원유(WTI) 선물 가격은 전장 대비 18.29% 오른 배럴당 107.53달러에 거래되고 있으며, 장중 최고치는 111.24달러입니다.이란이 세계 에너지 수송의 관문인 호르무즈 해협을 차단하자, 수출길이 막힌 쿠웨이트가 감산을 선언하는 등 걸프 산유국들이 차례로 에너지 관련 시설 가동을 중단한 데 따른 것입니다.중동산 원유 의존도가 높은 아시아 여타 주요국 증시도 상당한 충격을 받을 것으로 보입니다.실제, 금융정보서비스업체 연합인포맥스에 따르면 일본 닛케이255 지수는 현재 6.58% 급락한 51,963.04를 나타내고 있으며, 조만간 개장할 대만 가권과 중국 상해종합지수 등도 하락 출발이 점쳐지는 상황입니다.이번 사태가 단기간에 마무리되지 못해 유가 고공행진이 지속될 경우 미국을 비롯한 주요국 금융시장의 연쇄적 버블 붕괴로 이어지며 주식시장이 추세 하락으로 전환할 것이란 일각의 우려도 일부 영향을 미쳤을 수 있습니다.허재환 유진투자증권 연구원은 "지난 한 주 동안 천연가스 가격은 60%, 국제유가는 30% 넘게 올랐다"면서 "과거 유가가 두배로 오르면, 전 세계 경제가 스태그플레이션(고물가속 경기침체) 압력 이후 침체에 빠졌던 경험들이 있다"고 짚었습니다.미국과 이스라엘이 개전 초 이란 최고지도자인 아야톨라 알리 하메네이를 제거하긴 했으나 베네수엘라 등 사례와는 달리 ''순교 서사''가 형성될 수 있다는 측면도 전쟁 장기화를 우려하게 하는 배경입니다.김성환 신한투자증권 연구원은 "최고지고자의 제거는 전쟁을 끝내는 요소가 아니라 시아파의 순교 서사 완성으로, 보복하지 않을 수 없는 종교적 의무를 발생시킨다"고 말했습니다.아울러 지상군을 투입하지 않고 전략적 목표 달성이 가능한지, 도널드 트럼프 대통령이 ''무조건 항복''을 요구하고 있지만 이란 측이 이를 받아들일 가능성이 희박해 보인다는 점 등도 우려되는 지점입니다.다만, 미국 11월 중간선거를 앞둔 상황에서 무작정 전쟁을 끌고 가기 힘든 상황 등을 고려하면 이란 차기 지도자와 극적 협상이 이뤄질 가능성도 배제하기 힘듭니다.허 연구원은 "이란 전쟁이 확전 조짐을 보인다. 위험에 대비할 필요가 있다. 비(非)미국 지역과 전통 경기민감주들의 강세 추세에 제동이 걸렸다"면서도 "좋은 점도 있다. 국내 증시 과속 부담은 완화되고 있고, 미국 소프트웨어주들의 급락과 빅테크들의 부진도 진정되고 있다"고 말했습니다.허 연구원은 "더 확실한 것은 무리하게 전쟁에 나선 도널드 트럼프 대통령의 레임덕이 빨리 도래할 가능성이 크다는 사실"이라면서 "유가 100달러는 부담스럽다. 그러나 방산, 정유와 함께 신재생에너지 등 트럼프 정책 피해 산업들은 새로운 국면을 맞을 수 있다"고 조언했습니다.DS투자증권은 미국과 이스라엘의 공격을 받은 이란의 보복 능력이 구조적으로 훼손된 상태라면서 이번 사태로 촉발된 국제유가의 불확실성 프리미엄이 단기간에 그칠 것이라고 내다봤습니다.(사진=연합뉴스)', NULL, 'SBS', 'https://n.news.naver.com/mnews/article/055/0001338720', 'https://imgnews.pstatic.net/image/055/2026/03/09/0001338720_001_20260309124250876.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 10:48:26', 0, true, '2026-03-09 05:41:07.754843') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (483, '[ET특징주]한화시스템, 중동 긴장감에 상승세', '한화시스템이 중동 긴장감에 상승세다.한화시스템(272210)은 3월 9일 오전 10시 35분 기준 전 거래일보다 3.02% 상승한 163,700원에 거래되고 있다.이는 미국과 이스라엘의 이란 공습의 영향으로 보인다.한화시스템은 이번 이란 전쟁에서 실전 배치돼 주목받은 천궁-Ⅱ의 다기능 레이더(MFR)를 제조한다.양승윤 유진투자증권 연구원은 “이란이 주변 걸프국을 대상으로 미사일과 드론 공격을 감행 중인데, 방공 자산이 빠르게 소모되며 한국의 천궁 체계에 이목이 집중되고 있다”며 “향후 천궁 추가 수출 가능성 및 L-SAM 수출 가능성 확대, 조기 인도를 통한 매출 인식 증가, 긴급 소요 속 공급 업체의 가격 협상력 상승 등 기대 요인 다수”라고 말했다.이원지 기자 news21g@etnews.com', NULL, '전자신문', 'https://n.news.naver.com/mnews/article/030/0003405492', 'https://imgnews.pstatic.net/image/030/2026/03/09/0003405492_001_20260309104621776.gif?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 10:46:21', 0, true, '2026-03-09 05:41:07.754843') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (484, '‘중동발 암초’ 불확실성 시대의 투자 전략은 [美·이란 전쟁, 시험대 선 韓 경제] ⑤', '1년7개월 만 서킷브레이커 발동 개미들 패닉금리·환율·공포지수 고려한 전략 재조정코스피 지수가 10% 이상 급락한 4일 하나은행 중구 딜링룸의 모습. [사진 연합뉴스][이코노미스트 김두용 기자] k2young@edaily.co.kr이란과 미국의 충돌 이후 중동 분쟁의 장기화 조짐으로 국내외 증시가 크게 휘청이고 있다. 대외적인 환경에 따른 불확실성 확대로 투자 전략을 재조정해야 하는 시점이다. 국내 유가증권시장에 대한 긍정과 부정론이 공존하는 가운데 유가와 금리, ‘공포지수’ 등 지수 가늠자들을 최대한 활용하는 전략이 요구되고 있다.극심한 변동성 장에 개미들 ‘오락가락’올해 들어 국내 증시를 받치는 축으로 성장한 개인 투자자(개미)는 순매수 행진을 이어가고 있다. ‘이란 사태’에도 개인의 매수세는 지속되고 있는 형국이다.중동에서 군사적 충돌이 계속되면서 국내 증시는 냉탕과 온탕을 오가는 등 변동성이 극심한 상황이다. 세계 증시를 통틀어 가장 가파른 상승세를 보였던 코스피의 상승장이 큰 ‘암초’를 만난 격이다.이란 사태 이후 개장한 코스피는 지난 3일과 4일 역대급 폭락을 보였다. 그러다 5일에는 10% 가까이 급등하는 변동성을 나타냈다.개인 투자자들은 코스피 5000, 6000 시대 개막에 주도적인 역할을 해왔다. 예전에는 외국인과 기관이 지수를 이끌었다면 최근에는 개미들이 지수를 지탱하는 축이 되고 있다.한국거래소에 따르면 지난 2월 개인 투자자는 유가증권시장에서 하루 8191억원을 순매수했다. 이는 1월(7001억원) 대비 1000억원 이상 증가한 수치다.올해 들어 개미들의 매수 우위 현상은 뚜렷하다. 지난 2월 27일 개인 투자자들은 외국인 투자자가 역대급으로 던진 7조원을 그대로 순매수하며 코스피 지수의 낙폭을 축소하는 데 앞장섰다. 전날인 26일에도 개미들은 5조원 이상 순매수했다.3월 3일에도 개미들은 ‘중동 사태’ 충격파와 관련해 지수 방어에 나섰다. 개인 투자자들은 5조8000억원 이상을 쏟아부으며 코스피 상승에 계속 베팅하는 흐름을 보였다. 개미들은 코스피가 반등한 5일 다시 1조8000억원의 순매수 행진을 이어갔다.변동성이 극심한 ''현기증 장세''에서 삼성전자와 SK하이닉스의 매도 시점 여부를 고민하는 투자자들이 수두룩했다. 40대의 회사원이라는 A씨는 주식 커뮤니티에 “지금 당장 매도해야 하는 ‘어깨선’이냐”고 물어보기도 했다.개인의 투자심리가 위축됐지만 대응은 극명히 갈리고 있다. 올해 상승장으로 준수한 수익률을 올린 반도체 주주들의 경우 분쟁 장기화를 고려한 손절을 고심하는 모습이다.반면 ‘20만 전자’와 ‘100만 닉스’에 들어간 투자자들은 울며 겨자 먹기 심정으로 물타기를 하거나 관망하겠다는 자세를 취하고 있다. 30대 직장인 B씨는 “아직까지 코스피 상승장에 대한 믿음이 사라지지 않았다. 이란 사태가 진정되면 다시 오를 것 같아서 저점 매수를 조금씩 하고 있다”고 털어놓았다.김석환 미래에셋증권 연구원은 “직전 고점 회복을 얼마나 빨리하느냐가 투자심리 회복에 중요한 잣대가 될 것으로 보인다. 대외 불확실성의 여진이 지속되고 있다는 점과 최근 월가에서 ‘시스템 리스크’로 부상 중인 사모신용 부실화는 지속해서 점검할 필요가 있다”고 조언했다.코스피 지수가 10% 이상 급락한 4일 하나은행 중구 딜링룸의 모습. [사진 연합뉴스]다양한 ‘공포지수’ 따른 전략 조정전문가들은 ▲금리 ▲환율 ▲공포지수 등을 고려한 신중한 베팅을 조언하고 있다. 보통 증시는 유가와 금리 등락 여부에 따라 후미적 영향을 받는 특징을 보이기 때문이다.이란이 글로벌 에너지 시장의 ‘동맥’인 호르무즈 해협 봉쇄하면서 국제 유가와 환율 등이 요동치고 있다. 분쟁 장기화로 브렌트유 가격이 배럴당 100달러까지 돌파할 것이라는 전망이 나오고 있다. 원·달러 환율은 한때 1500원까지 치솟았다.여기에 국내외 ‘공포지수’도 주목해야 한다. 한국거래소 정보 데이터시스템의 ‘코스피200 변동성지수’(VKOSPI)는 한국형 공포지수로 불린다. 코스피200 옵션 가격을 바탕으로 향후 30일간 시장 변동성에 대한 기대치를 수치화한 지수다.보통 10~40포인트 사이에서 움직이는데 4일 VKOSPI 지수는 80.29까지 치솟았다. 그러다 5일에는 70.75포인트로 하락했다. 지난 2월 27일 50포인트대였던 지수가 급등하면서 그야말로 공포장이 되고 있다. 일반 시장에서의 경우 40포인트 이상이 ‘과도한 공포’로 해석된다. 이는 반등 신호로 여겨지기도 한다.월가의 ‘공포지수’는 시카고옵션거래소(CBOE) 변동성지수(VIX)로 꼽힌다. VIX도 30일간의 변동성을 나타내는 지수다. 이란 사태 발발 이후 VIX는 지난해 11월 이후 최고치를 보이고 있다. 3월 3일 뉴욕 증시도 장중 한때 28포인트를 돌파하기도 했다. 4일에는 21포인트 수준을 보였다.시장이 불안해질수록 VIX가 상승하는 경향을 나타낸다. 보통 20~30포인트는 경계심이 커지는 구간이다. 30포인트 이상 커졌을 때는 불확실성이 매우 높고 공포심이 커진 상태로 해석된다. VIX는 상승장에서는 완만하게 하락하고, 하락장에서 커지는 양상을 보인다.중동 사태는 향후 국내 증시의 분수령이 될 가능성이 크다. 이런 가운데 전문가들의 의견은 ‘투자 기회’ vs ‘신중론’으로 갈리고 있다.먼저 허재환 유진투자증권 연구원은 “이란의 막판 저항이 생각보다 길어질 수 있다. ‘에너지 쇼크’라는 근본적인 위험은 해소되지 않았다. 그렇지만 과거 지정학적 위험은 지나고 나면 늘 기회였다”며 “VIX 30~40포인트 대에서 주가 바닥의 확률이 꽤 높다. 기회가 아주 멀리 있지 않는 것 같다”고 분석했다.정해창 대신증권 연구원도 “코스피는 1월 24%, 2월 19.5%의 급등세를 이어오면서 단기과열 해소가 필요한 상황이었다. 현재는 전망보다는 대응이 유효한 시점으로 보인다”고 말했다.반면 노동길 신한투자증권 연구원은 “단기적으로 가격결정력은 (바닥 수준인) 주가수익비율(PER)보다 환율·외국인·변동성에 더 크게 좌우된다”며 “환율 고착과 선물매도 재확대가 동반되고, 에너지 가격이 고공행진을 이어간다면 밸류에이션이 하단 구간에 접근해도 하방 테스트가 한 번 더 열릴 수 있다”고 경고했다.', NULL, '이코노미스트', 'https://n.news.naver.com/mnews/article/243/0000094145', 'https://imgnews.pstatic.net/image/243/2026/03/09/0000094145_001_20260309100109899.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 10:01:09', 0, true, '2026-03-09 05:41:07.754843') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (485, '중동 전쟁인데 유가는 폭락? "공포가 곧 매수 기회"', '◆…미국과 이스라엘의 대이란 군사 충돌이 이어지는 가운데 사우디아라비아 수도 리야드 상공에 연기가 피어오르고 있다. 사진=로이터통신미국과 이스라엘의 이란 공격으로 지정학적 긴장이 고조됐지만 증권가는 국제유가 불확실성 프리미엄이 단기에 그칠 가능성에 무게를 두고 있다. 반도체 이익 상향 사이클은 유효하며 에너지 자립 필요성이 부각되며 재생에너지 관련주도 주목받는 모습이다.9일 DS투자증권 양형모 연구원은 "과거 오일쇼크를 유발했던 전쟁과 현재는 구조적으로 다르다"고 밝혔다. 그는 "과거에는 이란이나 이라크가 산발적 공격을 지속할 물리적 역량을 유지했지만 현재는 이란 최고지도자 제거 시점부터 중앙 지휘 체계가 붕괴했다"고 지적했다.이어 "조직적 반격 능력이 무력화된 상태에서 불확실성 프리미엄이 장기간 유지될 근거는 없다"며 "글로벌 원유 시장은 하루 200만배럴 공급 과잉 상태이고 사우디도 여유 생산 능력을 보유하고 있다"고 강조했다. 그는 1991년 걸프전 당시 유가가 33% 폭락했던 사례를 들며 "군사적 결과가 확실해지면 시장은 프리미엄을 즉각 제거한다"고 말했다.양 연구원은 변동성 지수(VIX)에 대해 "현재 VIX 26.0은 초기 단계로 30이 고점일 확률은 70.6%"라고 분석했다. 코스피에 대해서는 "5059 레벨은 1차 매수 구간, 4816 도달 시 2차 적극적 비중 확대 구간"이라며 "공포는 매수 기회"라고 강조했다.DS투자증권 김현지 연구원도 "반도체와 조선 등 고부가가치 산업 성장이 상용임금 증대로 이어질 것"이라며 "약 25조원 추가 유동성이 확보되어 있어 유동성 랠리가 지속될 것"이라고 전망했다.iM증권 김준영 연구원은 "반도체 이익 상향 사이클은 끝나지 않았고 유가 상승 영향도 적게 받는다"며 "밸류에이션이 저렴해 고점을 지났다고 판단하기는 이르다"고 진단했다.한편, 유진투자증권 한병화 연구원은 재생에너지 강세 배경을 에너지 자립에서 찾았다. 그는 "전쟁이 종료돼도 데탕트 시절로 돌아가기는 어렵다"며 "연료 없는 전력원 확보가 핵심"이라고 설명했다. 이어 "최근 3년간 에너지 수입액이 연평균 1400억달러를 웃돌고 있다"며 "재생에너지 연간 설치량을 현재 3GW에서 10GW 이상으로 확대해야 한다"고 덧붙였다.', NULL, '조세일보', 'https://n.news.naver.com/mnews/article/123/0002379052', 'https://imgnews.pstatic.net/image/123/2026/03/09/0002379052_001_20260309095813997.png?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 09:58:13', 0, true, '2026-03-09 05:41:07.754843') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (486, '‘이란 쇼크’ 번진 국내 증시…지정학 리스크 장기화 시험대', '[美·이란 전쟁, 시험대 선 韓 경제] ④매도 사이드카 발동 하루 만에 매수 사이드카 발동…주식시장 변동성 커져“장기화 여부가 핵심”…유가·환율·미국 증시가 결국 변수코스피가 하루 만에 급등하며 5700선을 기록한 3월 5일 오전 서울 중구 하나은행 본점 딜링룸에서 딜러가 업무를 보고 있다. [사진 연합뉴스][이코노미스트 송현주 기자] 한국의 주식시장이 출렁이고 있다. 지난 3월 4일 국내 증시는 급락과 급반등을 반복하며 코스피와 코스닥 시장에서 매수 사이드카(프로그램 매수호가 일시효력정지)가 발동했다. 앞서 매도 사이드카와 서킷브레이커까지 잇따라 작동하면서 시장 변동성이 크게 확대된 상태다. 미국과 이스라엘의 이란 공습으로 촉발된 중동 긴장이 글로벌 금융시장 전반으로 확산되면서 국내 증시도 큰 변동성을 겪고 있는 것이다. 전쟁이라는 변수는 단기간에 투자심리를 위축시키며 위험자산 회피 흐름을 자극했고, 그 여파는 코스피와 코스닥을 가리지 않고 국내 증시 전반으로 빠르게 번졌다.특히 한국처럼 원유 수입 의존도가 높은 경제 구조에서는 중동 리스크가 단순한 이벤트성 충격에 그치지 않기에 시장의 경계감이 커졌다. 국제유가와 환율, 글로벌 자금 흐름까지 동시에 흔들 수 있는 변수라는 점에서 투자자들의 불안 심리가 확대됐다. 여기에 최근 증시 상승에 따른 고점 부담과 수출 중심의 산업 구조까지 겹치며 국내 증시는 다른 아시아 시장보다 더 민감하게 반응했다는 분석이 나온다. 실제 시장 충격은 단순한 지수 하락을 넘어 투자 심리 전반에 영향을 미쳤다. 투자자들은 단기 흐름에 민감하게 반응하며 위험자산 비중을 줄였고, 그 과정에서 대형주와 경기민감 업종을 중심으로 매도 압력이 확대됐다. 삼성전자와 SK하이닉스를 비롯한 반도체·자동차·2차전지 등 국내 증시를 이끄는 핵심 업종들이 동시에 약세를 보이면서 시장 전반의 투자심리가 빠르게 위축되는 모습이 나타났다.다만 이후 시장은 일정 부분 안정을 찾는 모습도 보이고 있다. 단기 충격으로 급락했던 지수가 반등 흐름을 보이면서 투자자들의 관망 심리도 점차 완화되는 분위기다. 증권가에서는 이번 급락을 지정학 리스크에 따른 단기 충격으로 보는 시각과 함께 글로벌 금융시장 흐름에 따라 변동성이 당분간 이어질 가능성도 제기하고 있다. 업종별 흐름에서도 전쟁 리스크가 시장 전반에 어떤 영향을 미치는지 그대로 드러났다. 방산·해운·정유 등 이른바 ‘전쟁 수혜주’로 꼽히는 업종에 투자자들의 관심이 집중됐지만 실제 주가 흐름은 기대만큼 단순하지 않았다. 지정학적 이벤트 장세에서는 특정 업종에 단기 자금이 빠르게 몰렸다가 차익 실현 매물이 동시에 쏟아지는 경우가 많아 상승과 하락이 반복되는 높은 변동성이 나타나는 것이 일반적이다.대표적인 사례가 방산주다. 중동 지역 긴장이 고조되면서 글로벌 방위산업 수요 확대 기대가 부각됐지만 주가 흐름은 일방적인 상승세로 이어지지 않았다. 한화에어로스페이스·현대로템·한화시스템·한국항공우주 등 주요 방산 종목들은 장중 등락을 반복하며 변동성이 확대된 모습이다. 한화시스템은 3월 3일 14만6700원에 장을 마감했지만, 하루 만에 11만6000원으로 하락했다. 하지만 지난 3월 5일 오전 10시 30분에는 14만1300원을 기록해 등락을 반복하는 모습을 보여줬다.국산 방공 무기 ‘천궁-Ⅱ’ 관련 이슈로 주목을 받은 LIG넥스원 역시 단기 급등 이후 차익 실현 매물이 나오며 높은 변동성을 보였다. 해운주 역시 비슷한 흐름을 나타냈다. 이란 군부가 호르무즈 해협 봉쇄 가능성을 언급하면서 해상 운임 상승 기대가 부각됐지만 시장 전반의 위험 회피 심리가 강화되면서 상승 흐름이 이어지지 않았다. HMM과 팬오션 등 주요 해운 종목들은 투자자들의 단기 매매가 집중되며 변동성이 확대되는 모습을 보였다. 국제유가 상승 기대감 속에 주목받았던 정유주 역시 방향성이 뚜렷하지 않았다. SK이노베이션과 S-Oil 등 주요 종목들은 유가 상승 기대와 글로벌 경기 둔화 우려가 엇갈리며 장중 등락을 반복하는 흐름을 보였다.미국과 이란의 전쟁으로 지정학적 불안감이 지속되고 있는 3월 3일 서울 중구 하나은행 딜링룸 현황판에 삼성전자와 하이닉스의 주가가 표시되고 있다. [사진 하나은행]“지정학 리스크 장세”…단기 테마 매매에 변동성 확대이처럼 지정학 리스크 장세에서는 특정 업종이 단기적으로 시장의 관심을 받더라도 지속적인 상승 추세로 이어지기보다 테마성 매매가 반복되며 높은 변동성을 보이는 경우가 많다는 분석이 나온다. 전쟁이나 군사 충돌과 같은 지정학적 사건은 기업 실적이나 경기 지표와 달리 향후 전개를 예측하기 어렵다는 점에서 시장 변동성을 크게 키우는 요인으로 꼽힌다. 특히 중동과 같은 에너지 공급 핵심 지역에서 긴장이 고조될 경우 국제유가와 환율, 글로벌 자금 흐름이 동시에 흔들리면서 금융시장에 불확실성이 빠르게 확대되는 특징이 있다.이 때문에 투자자들은 장기적인 펀더멘털보다 단기 흐름에 민감하게 반응하는 경향을 보인다. 전쟁 관련 소식이 전해질 때마다 위험자산 비중을 줄이거나 단기 테마주로 자금이 이동하면서 시장 전체의 변동성이 확대되는 모습이 나타난다. 방산이나 해운, 에너지 업종 등 특정 테마로 자금이 빠르게 쏠렸다가 차익 실현 매물이 동시에 나오며 급격한 등락이 반복되는 것도 이러한 장세의 특징이다. 다만 전문가들 사이에서는 향후 시장 대응 전략을 두고 의견이 엇갈리고 있다. 반도체 수요가 여전히 견고한 만큼 현재의 낙폭을 저가 매수 기회로 활용해야 한다는 의견과 외국인 자금 유출이 이어지는 상황에서 바닥을 확인한 후 대응해야 한다는 신중론이 맞서고 있다.그러면서도 전문가들은 공통적으로 미국 증시 흐름을 중요한 변수로 꼽고 있다. 고태봉 IM증권 리서치본부장은 “장기화 여부가 핵심이다. 이번 사태가 길어지면 반도체주를 더 싸게 살 수 있는 타이밍이 분명 다시 올 것”이라며 “지난 2일(현지시간) 미국 증시는 견조한 흐름을 보였는데 전쟁이 장기화될 경우 어떻게 될지는 아직 알 수 없다”고 말했다. 이어 “미국 시장이 잘 버텨준다면 국내 증시도 반등할 수 있기 때문에 미국 증시 데이터가 무엇보다 중요하다”고 설명했다.이재원 신한투자증권 연구원은 “방산과 해운 등 반사 수혜 기대 업종도 상승분을 반납하는 흐름을 보이고 있다”며 “국내 증시는 단기 급등 부담과 차익 실현 심리가 겹치며 여타 아시아 증시 대비 하락 폭이 크게 나타났다”고 말했다. 시장에서는 이번 사태가 단기 충격에 그칠지, 국제유가와 글로벌 자금 흐름을 흔드는 구조적 변수로 확대될지에 따라 향후 국내 증시의 방향성이 갈릴 것이라는 전망이 나온다.허재환 유진투자증권 연구원은 “국내 증시가 올해 다른 지역보다 유독 많이 오르기는 했지만 코스피 급락에 대한 타격감은 상당하다”면서 “주가가 많이 올랐던 업종부터 우선 매도하는 무차별한 하락세가 나타나고 있다”고 분석했다.', NULL, '이코노미스트', 'https://n.news.naver.com/mnews/article/243/0000094141', 'https://imgnews.pstatic.net/image/243/2026/03/09/0000094141_001_20260309091609560.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 09:10:16', 0, true, '2026-03-09 05:41:07.754843') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (487, '액스비스 코스닥 상장⋯코스모로보틱스·리센스메디컬 수요예측', '아이엠바이오로직스, 11~12일 일반청약이번 주(9~13일) 기업공개(IPO) 시장에서는 액스비스가 신규 상장한다. 코스모로보틱스와 리센스메디컬은 기관 투자자 대상 수요예측, 아이엠바이오로직스는 일반 청약에 나선다.9일 금융투자업계에 따르면 고출력 레이저 솔루션 기업 액스비스는 이날 코스닥 시장에 신규 상장한다. 확정 공모가는 1만1500원이다. 공모 금액은 265억원, 상장 후 예상 시가총액은 1073억원 수준이다.IPO [사진=챗GPT ]앞서 진행된 수요예측에선 총 2411곳의 국내외 기관 투자가가 참여, 경쟁률 1124.21을 기록했다. 당시 액스비스는 작년 7월 의무보유 확약 우선 배정제 도입 이후 가장 높은 의무보유 확약률인 75.7%(신청수량 기준)를 기록한 바 있다.수요예측을 진행하는 기업도 다수다. 웨어러블 로봇 전문기업인 코스모로보틱스는 이날부터 13일까지 수요예측에 나선다. 총 417만주를 공모한다. 공모가 희망밴드는 5300~6000원, 공모 예정금액은 약 221억~250억원 수준이다. 유진투자증권과 NH투자증권이 상장을 주관한다.같은 기간 정밀 냉각기술 의료기기 업체 리센스메디컬도 수요예측을 실시한다. 총 공모 주식수는 140만주다. 희망 공모가는 9000~1만1000원이다. 상장 주관사는 KB증권과 한국투자증권이다.인벤테라는 오는 11일부터 17일까지 수요예측을 진행한다. 자기공명영상(MRI) 조영제 신약 개발 전문기업이다. 총 118만주를 공모하며, 공모가 밴드는 1만2100~1만6600원이다. NH투자증권과 유진투자증권이 상장 주관사다.외국인 대상 해외송금 플랫폼 한패스는 지난 6일부터 진행 중인 수요예측을 12일 마칠 예정이다. 이후 공모가를 확정한 뒤 16일부터 17일까지 양일간 일반청약을 진행한다. 총 170만주를 공모한다. 공모가 범위는 1만7000~1만9000원이다. 한국투자증권과 대신증권이 주관한다.아이엠바이오로직스는 오는 11~12일 일반 투자자 대상 공모 청약을 앞두고 있다. 아이엠바이오로직스는 자가면역질환 치료제를 주요 제품으로 보유한 바이오업체다. 공모가 희망 범위는 1만9000~2만6000원이다. 한국투자증권과 신한투자증권이 주관사를 맡았다.', NULL, '아이뉴스24', 'https://n.news.naver.com/mnews/article/031/0001011354', 'https://imgnews.pstatic.net/image/031/2026/03/09/0001011354_001_20260309085413204.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 08:54:13', 0, true, '2026-03-09 05:41:07.754843') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (488, '유진證 "전쟁 후 에너지자립 필요성 각인…태양광·풍력주 강세"', '유진투자증권[촬영 안 철 수] 2024.10.13(서울=연합뉴스) 고은지 기자 = 유진투자증권은 9일 "이란 전쟁 발발 후 태양광, 풍력 관련주들이 강세"라며 "단순히 유가 상승에 대한 반응이 아니라 에너지자립에 대한 필요성이 각인되기 시작했기 때문"이라고 분석했다.한병화 연구원은 이날 보고서에서 "전쟁이 종료된다고 해도 데탕트(긴장 완화) 시절로 돌아가는 것은 불가능해 보여 이와 같은 상황에서 한국에 가장 절실한 이슈는 에너지 자립"이라고 짚었다.이어 "과거에는 유정, 가스전 등의 확보가 자립과 등치 개념이었지만, 지금은 모든 에너지원이 전력화되고 있는 것을 고려하면 에너지자립은 연료 없는 전력원, 즉 재생에너지 확보로 직결된다"고 판단했다.한 연구원이 한국무역통계 정보포털(TRASS)을 분석한 바에 따르면 우리나라 에너지 수입액은 원유, 액화천연가스(LNG), 석탄 기준으로 지난 3년간 연평균 1천400억달러를 웃돈다. 코로나19로 에너지 가격이 약세를 보였던 2020년 수입액은 680억달러에 그쳤으나 러시아-우크라이나 전쟁의 여파로 큰 폭 상승했다.한 연구원은 "화석연료 기반의 우리나라 경제에 수입 에너지가 미치는 영향은 절대 금액을 넘어서 경제 부담의 변동성 확대까지 견뎌야 하는 상황이 됐다"고 진단했다.이어 "이란 전쟁 후 국내 태양광, 풍력 관련 종목의 주가가 강세를 나타내는 건 투자자들이 에너지 자립에 대한 필요성을 인식했기 때문"이라며 "이재명 정부의 재생에너지 중심 전환 정책이 이를 가속하는 역할을 할 것"이라고 내다봤다.주목해볼 만한 종목으로는 SK이터닉스, 대명에너지, 금양그린파워 등 국내 민간 재생에너지 개발 업체를 꼽았다.한 연구원은 "국내 에너지자립을 위해서는 재생에너지 연간 설치량이 현재 3GW 수준에서 10GW 이상으로 확대돼야 하기 때문에 이들이 보유하고 있는 파이프라인이 2030년 내 대부분 완공될 전망"이라면서 "미래가치가 선반영되는 환경이 조성되고 있다"고 설명했다.아울러 "정부 정책이 국산 기자재를 육성하는 방향인 만큼 태양광, 풍력 기자재업체의 경우 국내 사업 비중이 큰 업체일수록 단기 주가에 강하게 반응할 수 있다"고 덧붙였다.eun@yna.co.kr', NULL, '연합뉴스', 'https://n.news.naver.com/mnews/article/001/0015945945', 'https://imgnews.pstatic.net/image/001/2026/03/09/PCM20241013000053990_P4_20260309082910993.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 08:28:52', 0, true, '2026-03-09 05:41:07.754843') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (509, '구자열 LS 이사회 의장, 한일경제협 16대 회장 선출', '구자열  신임 한일경제협회 회장/뉴스1 자료사진(서울=뉴스1) 최동현 기자 = 구자열 LS그룹 이사회 의장 한일경제협회 제16대 회장에 선출됐다.한일경제협회는 25일 서울 중구 롯데호텔에서 제45회 정기총회를 열고 구 회장을 신임 회장으로 선출했다고 밝혔다. 12년간 협회를 이끌어 온 김윤 회장은 명예회장으로 추대됐다.구 신임 회장은 "일본 측 파트너 기관과 마음을 합쳐 대일 경제협력 증진을 위해 애쓸 것"이라며 "창립 45년을 맞는 협회 발전을 위해 역량을 쏟겠다"고 포부를 밝혔다.회장단은 신동빈 롯데그룹 회장, 조원태 한진그룹 회장, 조현준 효성그룹 회장, 진옥동 신한금융그룹 회장, 이형희 SK 부회장, 박승희 삼성전자 사장, 서석숭 협회 상근부회장 등이 재선임됐다.협회 신임 부회장은 권대열 카카오 그룹ESG 담당, 김성원 GS글로벌 사장, 서형원 케이디마켓 회장이, 상임이사로는 김성용 동원F&B 사장이 신규 선임됐다.', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008793812', 'https://imgnews.pstatic.net/image/421/2026/02/25/0008793812_001_20260225212110002.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-25 21:20:34', 0, true, '2026-03-09 05:42:15.595041') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (489, '[서울데이터랩]에이엔피 29.90% 상한가…실시간 상승률 1위', '24일 오전 9시 10분 에이엔피(015260)가 등락률 +29.90%로 상한가를 기록하며 상승률 1위를 차지했다. 에이엔피는 개장 직후 5분간 266만 5430주가 거래되었으며 주가는 공모가 대비 183원 오른 795원이다.한편 에이엔피의 PER은 -3.43으로 상대적으로 저평가를 받고 있을 가능성을 시사하며, ROE는 -35.66%로 수익성이 낮다고 해석할 수 있다.이어 상승률 2위 미래에셋생명(085620)은 현재가 1만 9220원으로 주가가 19.23% 급등하고 있다. 상승률 3위 삼화콘덴서(001820)는 현재 6만 7800원으로 18.95% 급등하며 강세를 보이고 있다. 상승률 4위 애경산업(018250)은 16.77% 급등하며 1만 8660원에 거래되고 있다. 상승률 5위 KEC(092220)는 11.13%의 상승세를 타고 879원에 거래되고 있다.6위 한농화성(011500)은 현재가 2만 6150원으로 11.04% 상승 중이다. 7위 한미사이언스(008930)는 현재가 4만 6600원으로 9.01% 상승 중이다. 8위 금호전기(001210)는 현재가 1006원으로 7.48% 상승 중이다. 9위 SG세계물산(004060)은 현재가 811원으로 5.60% 상승 중이다. 10위 엘앤에프(066970)는 현재가 12만 100원으로 5.26% 상승 중이다.이밖에도 LS ELECTRIC(010120) ▲4.99%, 삼성SDI(006400) ▲4.98%, 한국ANKOR유전(152550) ▲4.71%, 제일연마(001560) ▲4.48% 등을 기록하며 시장에서 활발히 거래되고 있다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003620231', 'https://imgnews.pstatic.net/image/081/2026/02/24/0003620231_001_20260224092013550.png?type=w800', 'NEWS_ETC', NULL, '2026-02-24 09:20:13', 0, true, '2026-03-09 05:41:29.858380') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (490, '[더차트]"올 초에만 샀어도"...1억이 3억 됐다, 상승률 1위 ''이 종목''', '''코스피5000시대'', 2026년 상승률 상위 30개 종목. 거래정지종목 제외./그래픽=김지영이번주 코스피 지수가 사상 최초로 5000선을 돌파하며 한국 증시의 새 역사를 썼다. 코스피는 지난해에 이어 올해도 상승세다.24일 한국거래소에 따르면 코스피 지수는 지난 22일 장중 5019.54포인트를 기록해 사상 최고치를 갱신했다. 다음날인 23일에도 최고 5019.54포인트까지 상승했다. 코스피는 지난해 2400.87포인트로 시작해 4214.17포인트로 마감해 75% 가량 급등했고, 올해 초 18% 가량 상승하며 ''꿈의 지수''로 불렸던 5000포인트까지 달성했다.올해도 코스피의 상승세는 계속되고 있다.에프엔가이드에 따르면 올해 첫 거래일인 1월 2일부터 ''코스피5000 시대''를 연 22일까지 20일간의 주가 등락률을 분석한 결과 코스피 상장사 중 가장 높은 상승률을 기록한 종목은 금호전기다. 지난 2일 545원으로 출발한 주가는 22일 1113원까지 치솟으며 20일 만에 100% 넘는 수익률을 기록했다. 이어 이수스페셜티케미컬이 82% 급등하며 2위를 차지했고, 효성티앤씨가 81% 오르며 뒤를 이었다.대형주인 현대차는 이 기간 77% 급등하며 코스피 시가총액 3위로 올라섰다. 현대차의 이 같은 상승세는 기아(36%), 현대글로비스(44%), 현대모비스(22%) 등 그룹주 전반의 상승 탄력을 이끌었다.이 밖에도 방산·우주항공 분야 한화시스템(59%)과 원전 설비 관련주인 한전기술(52%), 현대건설(50%) 등이 50% 넘는 상승률을 보이며 시장을 주도했다. 이 밖에 상위 30위권 종목을 살펴보면 에스엘(47%), 한국무브넥스(45%) 등 자동차 부품주와 삼성SDI(46%), 롯데에너지머티리얼즈(41%) 등 2차전지 관련주가 포진했다.코스닥 시작도 코스피의 온기를 이어받아 상승세를 보였다. 코스닥 지수는 지난 23일 장중 최고 998.32포인트를 기록하며 1000포인트를 목전에 두고 있다.코스닥 상승률 1위는 자동차 부품업체인 모베이스전자다. 현대차 협력업체로 분류되는 모베이스전자는 연초 1420원이던 주가가 4345원까지 오르며 이달 2일부터 22일까지 205% 넘는 수익률을 기록했다. 이는 코스피 1위인 금호전기의 상승률을 2배가량 웃도는 수치다.이어 카메라 모듈 부품사인 해성옵틱스가 185%, 통신장비 기업 센서뷰가 184% 급등하며 뒤를 이었다. 로봇 테마주인 휴림로봇도 162% 상승하며 4위를 기록했다.코스닥 상위권 종목에는 주로 자동차 부품, IT 하드웨어, 로봇 등 전방 산업의 수혜가 예상되는 기술주들이 대거 포진돼 코스피 대형주의 ''낙수 효과''를 누린 것으로 분석된다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005308825', 'https://imgnews.pstatic.net/image/008/2026/01/24/0005308825_001_20260124115712919.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-24 06:01:00', 0, true, '2026-03-09 05:41:29.858380') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (491, '[서울데이터랩]금일 코스피 거래량 1위 한화갤러리아 거래대금 831억 돌파', '코스피 거래량 상위 종목들이 전반적으로 엇갈린 흐름을 보인다. 23일 한국거래소에 따르면, 한화갤러리아(452260)가 4천만주 이상 거래되며 코스피 종목 중 실시간 거래량 1위를 차지한다. 현재 주가는 2,075원이며, 시가총액은 4,023백만원으로, 거래대금은 시가총액의 약 20.68%에 달한다. PER은 -11.53, ROE는 -2.31로, 수급 측면에서는 큰 변동성을 보인다. 미래에셋증권(006800)은 3만5,200원으로 17.92% 급등하며, 거래량 1천5백만주 이상을 기록한다. 거래대금은 5,189억원으로, 시가총액 대비 2.6%의 비율을 보인다. PER 20.20, ROE 7.94로 재무 지표는 양호하다.대우건설(047040)은 5,160원으로 3.82% 상승하며, 거래량 1천4백만주 이상을 기록한다. 화천기계(010660)는 10.52% 상승하며, 거래량 1천2백만주 이상을 기록하고 있다. 삼성전자(005930)도 1.64% 상승하며 1천2백만주 이상 거래되고 있다. 웰바이오텍(010600)은 보합세를 보이며 1천만주 이상 거래되고, 보락(002760)은 6.10% 상승하며 1천만주 이상 거래된다. 한화투자증권(003530)은 12.02% 상승, SK증권(001510)은 6.11% 상승하며 각각 1천만주 가까이 거래되고 있다. 카카오페이(377300)는 23.95% 급등하며 8백만주 이상 거래되고 있다.한편 거래량 상위 20위권 종목들은 국보(001140) ▲70.97%, 형지엘리트(093240) ▼1.62%, 한온시스템(018880) ▲0.59%, 한화생명(088350) ▲9.05%, 한국전력(015760) ▼7.73%, 카카오(035720) ▲3.77%, LG씨엔에스(064400) ▲7.06%, 두산에너빌리티(034020) ▲2.89%, 금호전기(001210) ▼7.73%, 현대건설(000720) ▲4.33% 등의 성적을 기록한다.주목할 만한 종목으로는 급등한 카카오페이와 미래에셋증권이 있다. 카카오페이는 거래대금이 시가총액 87,439백만원의 약 59.88%에 달하며, 급등세를 보인다. 미래에셋증권은 시가총액 대비 거래대금 비율이 2.6%로, 활발한 매수세가 나타난다. 반면, 형지엘리트와 한국전력은 각각 ▼1.62%, ▼7.73%로 하락하며, 거래대금은 상대적으로 낮은 편이다.전체적으로 시장은 혼조세를 보이며, 일부 종목에서는 강한 매수세가 관찰된다. 특히 거래대금이 시가총액의 큰 비중을 차지하는 종목들은 투자자들의 큰 관심을 받고 있다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003611262', 'https://imgnews.pstatic.net/image/081/2026/01/23/0003611262_001_20260123144218693.png?type=w800', 'NEWS_ETC', NULL, '2026-01-23 14:42:18', 0, true, '2026-03-09 05:41:29.858380') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (492, '[서울데이터랩]금일 코스피 거래량 1위 한온시스템 거래대금 무려 879억 돌파', '코스피 거래량 상위 종목들이 전반적으로 엇갈린 흐름을 보인다.22일 한국거래소에 따르면, 한온시스템(018880)이 25,157,869주가 거래되며 코스피 종목 중 실시간 거래량 1위를 차지하고 있다. 현재 주가는 3,435원이며, 시가총액 35,252억원 대비 거래대금은 879억 5,800만원으로, 약 2.5%에 해당하는 거래대금이 이루어졌다. 이는 5.69%의 상승률을 보이며 활발한 매수세가 유입되었음을 시사한다. PER은 -8.38, ROE는 -13.90으로 재무 지표는 다소 부정적이다. 삼성전자(005930)는 18,215,595주가 거래되며 거래량 2위를 기록하고 있으며, 현재 주가는 155,600원으로 시가총액 9,210,957억원에 비해 거래대금이 2조 8,250억원에 달한다. 이는 시총의 약 0.31%에 해당하며, 4.08%의 상승세를 나타내고 있다. PER은 32.31, ROE는 9.03으로 안정적인 재무 상태를 보여준다.웰바이오텍(010600)은 현재 15,663,812주가 거래되며 거래량 3위를 기록 중이며, 주가는 15원으로 21.05%의 폭락세를 보이고 있다. KBI동양철관(008970)은 2,052원으로 8.92% 상승세를 보이며 11,259,026주의 거래량을 기록하고 있다. 형지엘리트(093240)는 1,532원으로 7.36% 상승하며 10,482,655주가 거래되었다. 화천기계(010660)는 5,450원으로 22.06% 상승하고, 10,043,649주의 거래량을 기록 중이다. 금호전기(001210)는 1,122원으로 5.85% 올랐으며, 거래량은 8,930,039주에 달한다. 한신기계(011700)는 4,495원으로 5.37% 하락하며 7,457,454주의 거래량을 보이고 있다. 대한전선(001440)은 28,950원으로 7.62% 상승하며 7,170,964주의 거래량을 기록 중이다. 한화갤러리아(452260)는 1,793원으로 2.55% 하락하며 6,687,488주가 거래되고 있다.한편 거래량 상위 20위권 종목들은 이수화학(005950) ▲13.45%, 두산에너빌리티(034020) ▲0.77%, 대우건설(047040) ▲2.94%, 현대차(005380) ▲0.36%, 삼성중공업(010140) ▼0.65%, 한국전력(015760) 보합, 삼성SDI(006400) ▲15.28%, 이수스페셜티케미컬(457190) ▲19.43%, 한국무브넥스(010100) ▼2.90%, 한농화성(011500) ▲29.83% 등의 성적을 기록하고 있다.주목할 만한 종목으로는 급등세를 보이는 화천기계와 ▲22.06% 상승한 한농화성이 있다. 화천기계는 거래대금이 시가총액의 4.5%에 달하며 투자자들의 주목을 끌고 있다. 반면 웰바이오텍과 ▼21.05% 하락한 한국무브넥스는 거래대금이 상대적으로 적어 하락세가 두드러진다.전체적으로 시장은 상위 종목들이 엇갈린 흐름을 보이는 가운데, 일부 종목에서는 강한 매수세가 포착되고 있다. PER과 ROE 지표를 통해 기업의 재무 상태를 확인할 필요가 있으며, 유입된 자금의 흐름과 관련한 투자자들의 움직임을 주의 깊게 살펴볼 필요가 있다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003610842', 'https://imgnews.pstatic.net/image/081/2026/01/22/0003610842_001_20260122130923970.png?type=w800', 'NEWS_ETC', NULL, '2026-01-22 13:09:23', 0, true, '2026-03-09 05:41:29.858380') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (493, '[서울데이터랩]금일 코스피 거래량 1위 한신기계 거래대금 1조 3,710억원 돌파', '코스피 거래량 상위 종목들이 전반적으로 엇갈린 흐름을 보인다.21일 한국거래소에 따르면, 한신기계(011700)가 2천6백만주 이상 거래되며 코스피 종목 중 실시간 거래량 1위를 차지하고 있다. 현재 주가는 5,250원으로, 거래대금은 1,371억여원을 기록하고 있으며, 폭등하는 모습을 보이고 있다. 시가총액 대비 거래대금 비율이 80.54%에 달해 투자자들의 높은 관심을 받고 있다. 웰바이오텍(010600)은 2천3백만주 거래되며 거래량 2위를 기록했다. 하지만 주가는 17원으로 전 거래일 대비 폭락하였으며, 거래대금은 597백만원에 불과하다. KBI동양철관(008970)은 거래량 2천3백만주로 3위를 기록하며, 현재 주가 1,910원과 거래대금 484억9천만원을 기록, 보합권에 머무르고 있다.삼성전자(005930)는 현재 148,600원으로 2.34% 상승하며, 거래량 2천2백만주를 기록하고 있다. 한화갤러리아(452260)는 1,867원으로 6.88% 하락, 거래량은 1천94만8천주로 집계된다. 한국전력(015760)은 68,000원에 3.98% 상승, 모나리자(012690)는 2,440원에 10.41% 상승을 기록 중이다. 하이스틸(071090)은 3,990원으로 14.16% 상승, 국보(001140)는 99원으로 59.68% 급등세를 보이고 있다. 휴스틸(005010)은 4,190원에 4.36% 상승 중이다.한편 거래량 상위 20위권 종목들은 포스코DX(022100) ▲2.52%, 두산에너빌리티(034020) ▼3.57%, 현대차(005380) ▲9.39%, 금호전기(001210) ▼6.49%, 대우건설(047040) ▼5.38%, 한온시스템(018880) ▼1.08%, SK증권(001510) ▼4.41%, 삼성중공업(010140) ▼1.46%, 넥스틸(092790) ▲15.10%, 대한전선(001440) ▼3.40% 등의 성적을 기록하고 있다.특히 국보는 거래량 756만주에 거래대금 704백만원을 기록하며 59.68%의 급등세를 보이고 있다. 넥스틸 역시 15.10%의 상승률과 함께 498만주가 거래되고 있다. 반면 웰바이오텍과 한화갤러리아는 각각 거래대금 대비 시가총액 비율이 미미하며, 큰 폭의 하락세를 보이고 있다.코스피 시장은 이러한 종목들의 활발한 거래와 등락을 보이며 변동성을 나타내고 있다. 투자자들의 매수 매도세가 치열하게 맞물리며, 단기적으로 변동성이 클 것으로 예상된다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003610467', 'https://imgnews.pstatic.net/image/081/2026/01/21/0003610467_001_20260121134514352.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-21 13:45:14', 0, true, '2026-03-09 05:41:29.858380') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (494, '[서울데이터랩]금일 코스피 거래량 1위 웰바이오텍 거래대금 921백만원 기록', '코스피 거래량 상위 종목들이 전반적으로 엇갈린 흐름을 보인다.20일 한국거래소에 따르면, 웰바이오텍(010600)이 33,232,772주의 거래량을 기록하며 코스피 종목 중 실시간 거래량 1위를 차지했다. 현재 주가는 34원이며, 시가총액의 2.97%에 해당하는 거래대금이 일어났다. PER 0.20, ROE -72.93으로, 재무적 지표는 다소 불안정한 모습을 보인다. 이러한 가운데 급격한 폭등세를 보이며 투자자들의 큰 관심을 받고 있다. 대우건설(047040)은 5,040원으로 11.75% 상승하며, 22,882,023주의 거래량을 기록하고 있다. 거래대금은 114,086백만원에 이르며, 시가총액의 5.45%를 차지한다. PER -75.22, ROE 5.62로, 건설 경기 회복에 대한 기대감이 반영되고 있다.삼성전자(005930)는 현재 147,100원으로 1.47% 하락하며, 16,228,879주의 거래량을 보이고 있다. 금호전기(001210)는 1,147원으로 7.50% 하락하며, 10,458,812주의 거래량을 기록하였다. KBI동양철관(008970)은 1,891원으로 8.00% 상승하며, 9,998,983주의 거래량이 집계되었다. 한화갤러리아(452260)는 2,075원으로 6.11% 하락하며, 거래량은 9,223,844주이다. 한온시스템(018880)은 3,205원으로 0.79% 상승하였고, 8,160,858주의 거래량을 기록 중이다. 한국전력(015760)은 62,000원으로 10.12% 상승하며, 7,117,885주의 거래량을 나타내고 있다. 한국무브넥스(010100)는 6,850원으로 1.18% 상승하며, 7,057,071주의 거래량을 보이고 있다. 아진전자부품(009320)은 1,190원으로 7.21% 상승하며, 6,938,803주의 거래량을 기록했다.한편 거래량 상위 20위권 종목들은 퍼스텍(010820) ▲9.58%, 한신기계(011700) ▲13.28%, 삼성중공업(010140) ▼2.83%, 대한해운(005880) ▲5.53%, 두산에너빌리티(034020) ▼0.63%, 팬오션(028670) ▲6.50%, SK증권(001510) ▲3.59%, 에쓰씨엔지니어링(023960) ▼8.64%, 포스코DX(022100) ▲0.48%, 현대차(005380) ▲0.10% 등의 성적을 기록했다.주목할 만한 종목으로는 웰바이오텍과 대우건설이 있다. 웰바이오텍은 폭등세로 기록적인 거래량을 보이며 시장의 주목을 받고 있으며, 대우건설은 상승세와 함께 시가총액 대비 높은 거래대금 비율을 보이고 있어 투자자들의 큰 관심을 모으고 있다. 반면, 금호전기와 에쓰씨엔지니어링은 하락세를 보이며 거래대금 비율도 낮아, 투자 심리의 위축을 반영하고 있다.전체적인 시장 흐름은 상승과 하락이 혼재된 가운데, 일부 종목들은 급격한 변동을 보이며 투자자들의 이목을 끌고 있다. 특히 웰바이오텍의 폭등이 시장 분위기를 주도하고 있으며, 다른 종목들 또한 다양한 이슈에 따라 차별화된 움직임을 보이고 있다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003610199', 'https://imgnews.pstatic.net/image/081/2026/01/20/0003610199_001_20260120152821884.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-20 15:28:21', 0, true, '2026-03-09 05:41:29.858380') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (495, '[서울데이터랩]1월 15일 코스피 주요 종목 마감시황', '1월 15일 한국거래소에 따르면, 한화갤러리아우(45226K)는 전 거래일 대비 30.00% 상승한 8060원에 거래를 마감하며 금일 코스피 상승률 1위를 차지했다. DYP(092780)는 29.98% 상승한 6070원에 거래를 마치며 뒤를 이었다. 포스코DX(022100)는 전 거래일 대비 29.92% 상승한 38650원에 종가를 기록했다. 현대약품(004310)은 29.89% 상승한 10560원에 거래를 종료했다. 메타랩스(090370)는 29.79% 상승한 2000원에 마감하며 상승률 상위권에 이름을 올렸다.웰바이오텍은 전 거래일 대비 95.60% 하락한 24원에 거래를 마감하며 금일 코스피 하락률 1위를 기록했다. 금호전기는 11.89% 하락한 1000원에 종가를 마쳤다. 대성산업은 전 거래일 대비 11.62% 하락한 6390원에 거래를 종료했다. 금호건설우는 10.77% 하락한 17060원에 마감했다. 동양고속은 10.40% 하락한 64600원에 거래를 마쳤다.시가총액 상위 종목 중 삼성전자가 2438만 주의 거래량을 바탕으로 2.57% 상승했다. SK하이닉스는 298만 주의 거래량을 기록하며 0.94% 상승했다. LG에너지솔루션은 거래량 28만 주로, 0.64% 상승 마감했다. 삼성바이오로직스는 7만 주가 거래되며 1.97%의 상승세를 보였다. 삼성전자우는 287만 주가 거래되며 2.79% 상승했다. 현대차는 282만 주의 거래량을 기록하며 2.55% 상승했다. 한화에어로스페이스는 21만 주가 거래되며 1.97% 상승했다. HD현대중공업은 25만 주가 거래되며 2.60% 상승했다. 기아는 337만 주가 거래되며 6.64%의 상승세를 보였다. 두산에너빌리티는 459만 주가 거래되며 0.11% 하락했다.금일 코스피 주요 종목들은 상승세를 보이며 전반적으로 긍정적인 움직임을 보였다. 투자자들은 이러한 시장의 변동성에 주의하며, 안정적인 포트폴리오 구성을 통해 시장 변화에 대응하는 전략이 필요하다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003609131', 'https://imgnews.pstatic.net/image/081/2026/01/15/0003609131_001_20260115163415725.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-15 16:34:15', 0, true, '2026-03-09 05:41:29.858380') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (496, '[서울데이터랩]금일 코스피 거래량 1위 한화갤러리아 거래대금 1,322억원 돌파', '코스피 거래량 상위 종목들이 전반적으로 엇갈린 흐름을 보인다. 15일 한국거래소에 따르면, 한화갤러리아(452260)가 6,422만주 이상 거래되며 코스피 종목 중 실시간 거래량 1위를 차지한다. 현재 주가는 2,105원으로, 시가총액의 32.4%에 해당하는 1,322억 6,500만원의 거래대금과 함께 29.78%의 폭등세를 보이고 있다. PER -11.69, ROE -2.31로, 재무 지표는 부진하지만, 투자자들의 매수세가 집중되고 있는 상황이다. 웰바이오텍(010600)은 2,670만주 이상 거래되며 두 번째로 높은 거래량을 기록했으나, 주가는 23원으로 95.78% 폭락했다. 시가총액 21억원에 비해 거래대금은 7억 800만원으로, PER 0.14, ROE -72.93으로 재무 상태가 좋지 않다.포스코DX(022100)는 현재가 36,850원으로 23.87% 폭등하며 거래량 1,392만주를 기록하고 있다. 삼성전자(005930)는 현재가 140,850원으로 거래량 1,109만주와 0.39%의 횡보세를 보인다. KBI동양철관(008970)은 3.01% 상승하며 1,037만주가 거래되었고, 삼성중공업(010140)은 5.11% 상승하며 1,020만주가 거래되고 있다. 현대약품(004310)은 26.69% 폭등하며 922만주가 거래되고 있다. 한화생명(088350)은 3.99% 하락하며 550만주가 거래되고 있으며, DYP(092780)는 29.98% 폭등하며 529만주가 거래 중이다.한편 거래량 상위 20위권 종목들은 미래에셋증권(006800) ▲3.05%, 계양전기(012200) ▼7.57%, 한온시스템(018880) ▲1.95%, 흥아해운(003280) ▲1.68%, 금호전기(001210) ▼13.66%, 대성산업(128820) ▼10.24%, 한화시스템(272210) ▲7.14%, 한화오션(042660) ▲4.58%, 한국ANKOR유전(152550) 보합, 두산에너빌리티(034020) ▼0.78% 등의 성적을 기록한다.주목할 만한 종목으로는 한화갤러리아와 포스코DX가 있다. 한화갤러리아는 거래대금이 시가총액의 2%를 훨씬 상회하며 폭등세를 보이고 있어 투자자들의 관심이 집중되고 있다. 포스코DX는 시가총액 대비 거래대금이 8.72%에 달하며 높은 상승세를 기록 중이다. 반면, 웰바이오텍과 금호전기는 각각 95.78%와 13.66%로 큰 하락세를 보이며, 시가총액 대비 거래대금의 비율이 낮아 투자자들의 주의가 필요하다.전체적으로 거래량 상위 종목들이 상승과 하락을 오가는 혼조세를 보이고 있으며, 특히 한화갤러리아와 포스코DX가 폭등세를 보이며 시장의 주목을 받고 있다. 반면, 웰바이오텍과 금호전기 등 일부 종목은 급락하며 변동성이 높은 시장 흐름을 나타내고 있다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003609062', 'https://imgnews.pstatic.net/image/081/2026/01/15/0003609062_001_20260115131109884.png?type=w800', 'NEWS_ETC', NULL, '2026-01-15 13:10:15', 0, true, '2026-03-09 05:41:29.858380') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (497, '한달간 코스피 거래량 상위 10개 중 6개 ''소형주''…"1월 효과"(종합)', '한화갤러리아·삼성전자·남선알미늄·형지엘리트·동양 등 順계양전기·금호전기 주가 급등…"1월엔 중소형주 프리미엄 발생"상장사 시가총액 (PG)[박은주 제작] 사진합성·일러스트(서울=연합뉴스) 고은지 기자 = 최근 한 달간 유가증권시장에서 거래량이 가장 많았던 10개 종목 중 6개가 소형주인 것으로 나타났다.14일 한국거래소에 따르면 지난달 12일부터 이날까지 거래량 1위는 한화갤러리아로, 이 기간 총 5억6천227만주가 거래됐다.이어 삼성전자(5억5천655만주), 남선알미늄(3억6천136만주), 형지엘리트(3억2천508만주), 동양(2억457만주)이 2∼5위를 차지했다.6∼10위는 금호전기(1억9천421만주), 계양전기(1억6천876만주), 미래에셋증권(1억4천839만주), 한온시스템(1억2천546만주), 두산에너빌리티(1억2천187만주)였다.삼성전자, 미래에셋증권, 한온시스템, 두산에너빌리티를 제외한 종목은 시가총액 301위 이하인 소형주다.코스피 상승 (CG)[연합뉴스TV 제공]또 한화 계열의 한화갤러리아와 유진그룹 계열의 동양을 뺀 소형주 종목의 시작일 기준가 대비 이날 종가 등락률을 보면 계양전기가 638.13% 폭등했고, 금호전기는 83.06%, 형지엘리트는 26.06% 뛰었다.계양전기는 현대차그룹 계열사와의 로봇 부품 공급 계약 이력이 부각되면서 주목받았다.현대차그룹이 지난 6∼9일(현지시간) 미국 라스베이거스에서 열린 세계 최대 가전·정보기술(IT) 전시회 ''CES 2026''에서 휴머노이드 로봇 ''아틀라스''를 공개한 이후 주가가 고공행진을 하는 상황에서 계양전기가 ''수혜주''로 부상하면서 동반 상승한 것으로 풀이된다.''번개표'' 전구로 잘 알려진 금호전기는 지난 12일과 13일 이틀 연속 상한가를 기록했고 이날도 장 초반 20%대 상승률을 나타내다가 점차 둔화해 4.61% 상승 마감했다.금호전기 주가 급등은 전력 설비 수요 증가에 따른 전력기기 업종의 호조세에 영향을 받은 것으로 여겨진다.학생복 브랜드인 형지엘리트는 웨어러블 로봇 개발 소식에 주가가 상승세를 탔다.앞서 형지엘리트는 ''형지로보틱스''(hyungjiROBOTICS) 상표권을 출원하며 차세대 사업으로 ''시니어 웨어러블 로봇'' 사업 진출 계획을 공식화한 바 있다.지난 6일에는 중국에서 열린 ''한중 비즈니스 포럼''의 사전 간담회를 통해 ''시니어 웨어러블 로봇'' 사업 계획을 발표했다.남선알미늄은 자동차 업종의 호조세와 정치 테마주 영향이 복합적으로 미치며 같은 기간 15.09% 올랐다.유안타증권 신현용 연구원은 "다른 달 대비 1월에는 중소형 프리미엄이 강하게 발생하는 ''1월 효과''가 나타난다"며 "전년도 4분기 실적 시즌을 통해 이익에 대한 민감도가 나타나면서 이익 트렌드(경향)가 견조한 낙폭 과대 종목이 재차 주목받을 수 있다"고 분석했다.eun@yna.co.kr', NULL, '연합뉴스', 'https://n.news.naver.com/mnews/article/001/0015847404', 'https://imgnews.pstatic.net/image/001/2026/01/14/PCM20210504000088990_P4_20260114162421890.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-14 16:23:56', 0, true, '2026-03-09 05:41:29.858380') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (498, '[서울데이터랩]금일 코스피 거래량 1위 한화갤러리아 거래대금 1,036억 돌파', '코스피 거래량 상위 종목들이 전반적으로 엇갈린 흐름을 보인다.14일 한국거래소에 따르면, 한화갤러리아(452260)가 68,686,064주의 거래량으로 코스피 종목 중 실시간 거래량 1위를 차지하고 있다. 현재 주가는 1,622원으로, 시가총액의 약 32.94%에 해당하는 거래대금이 발생하며 상한가인 29.97% 상승률을 기록 중이다. PER은 -9.01, ROE는 -2.31로, 재무 지표는 다소 부진한 상태다. 금호전기(001210)는 41,314,306주가 거래되며 19.63%의 급등세를 보이고 있으며, 거래대금은 53,854백만원에 달한다. 현재 주가는 1,298원으로, 시가총액 대비 거래대금 비율이 6.74%에 이르고 있다. 삼성전자(005930)는 11,370,290주의 거래량을 기록하며 1.56% 상승, 거래대금은 1,580,200백만원이다. 현재 주가는 139,750원이며, PER 29.02, ROE 9.03으로 안정적인 재무 상태를 유지하고 있다.대성산업(128820)은 7,830원으로 26.29% 급등하며 10,289,925주가 거래되고 있다. 두산에너빌리티(034020)는 89,300원으로 2.64% 상승했으며, 거래량은 9,399,902주다. 신성이엔지(011930)는 1,698원으로 7.67% 상승하며 7,354,517주가 거래 중이다. 한온시스템(018880)은 3,110원으로 3.67% 상승, 6,453,610주가 거래되고 있으며, 삼성중공업(010140)은 28,400원으로 1.90% 하락, 5,612,060주의 거래량을 기록하고 있다. 계양전기(012200)는 11,670원으로 6.19% 하락, 5,424,694주가 거래 중이며, 현대건설(000720)은 95,200원으로 3.48% 상승하며 5,140,996주의 거래량을 보이고 있다.한편 거래량 상위 20위권 종목들은 한화시스템(272210) ▲0.34%, 광명전기(017040) ▼3.54%, 형지엘리트(093240) ▼0.51%, 티에이치엔(019180) ▲8.88%, DYP(092780) ▲29.90%, 한국ANKOR유전(152550) ▲0.46%, 한화오션(042660) ▼4.87%, 동원금속(018500) ▲5.67%, 흥아해운(003280) ▼0.36%, 한국전력(015760) ▼3.77% 등의 성적을 기록했다.특히 DYP는 거래량 3,282,746주로 상한가인 29.90%의 상승률을 기록하고 있으며, 이에 따른 거래대금은 15,146백만원이다. 티에이치엔 또한 8.88% 상승률을 보이며 3,545,260주의 거래량을 기록했다. 반면, 계양전기는 6.19% 하락하며 5,424,694주의 거래량과 함께 거래대금 67,787백만원을 기록, 시장에서의 주목을 받고 있다. 한화오션도 4.87% 하락하며 3,239,614주가 거래되고 있으며, 거래대금은 465,290백만원이다.시장의 전체적인 흐름은 상승과 하락이 혼재된 모습을 보이고 있다. 한화갤러리아와 금호전기 같은 종목들은 급등세를 보이며 투자자들의 관심을 끌고 있는 반면, 삼성중공업과 계양전기 등 일부 종목들은 하락세를 보이고 있다. 이는 시장에서의 매수와 매도세가 각 종목별로 차별화된 움직임을 보이고 있음을 시사한다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003608755', 'https://imgnews.pstatic.net/image/081/2026/01/14/0003608755_001_20260114144111988.png?type=w800', 'NEWS_ETC', NULL, '2026-01-14 14:41:11', 0, true, '2026-03-09 05:41:29.858380') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (499, '이번엔 인프라 슈퍼사이클…K철강 ''고부가 제품'' 승부수', '한경Aicel 분석봉형강 올해 대미 수출 급증美 데이터센터 ''붐''…건설용 철강 수출 10배 급증2월 6700만弗…1년새 ''쑥''"봉형강 가격 경쟁력 뛰어나"철근과 H형강 등 건물 골조에 쓰이는 봉형강 수출이 올해 들어 빠르게 증가하고 있다. 미국 하이퍼스케일러(대규모 클라우드 인프라를 운영하는 빅테크)의 데이터센터 건설 붐이 국내 반도체뿐 아니라 철근 수요까지 끌어올린 영향이다.8일 한경에이셀(Aicel)에 따르면 지난달 봉형강 수출액은 2억894만달러(약 3090억원)로 1년 전보다 27.0% 증가했다. 미국 수출이 전체 실적 증가를 견인했다. 대미 봉형강 수출액은 6686만달러로 전년 동기 대비 927.8% 급증했다. 한 달 전인 1월 9270만달러로 594.4% 늘어난 데 이어 증가 속도가 더 빨라졌다.미국의 왕성한 수요 덕분에 내리막길을 걷던 한국산 봉형강 수출 실적은 작년 12월(21.5% 증가)부터 3개월 연속 두 자릿수 증가율을 이어갔다. 올해 1월에는 2억981만달러로 53.4% 늘어 2022년 8월 후 3년5개월 만의 최대를 기록했다.업계 전문가들은 인공지능(AI) 데이터센터 등 현지 건설 수요 증가가 침체에 빠진 국내 철근 시장에 활력을 불어넣었다고 분석했다. 아울러 글로벌 데이터센터 투자가 2030년까지 매년 10%대 성장을 이어가며 철근 등 건축자재 가격 상승을 뒷받침할 것으로 예상했다. 김현태 BNK투자증권 연구원은 “높은 운송 비용과 관세 부담에도 미국으로의 봉형강 수출이 증가하고 있다”며 “현지 데이터센터 건설 붐에 따른 수요 급증과 비정상적으로 낮은 수준까지 떨어진 국내 철근 가격이 맞물려 무거운 철근의 장거리 수송을 가능하게 했다”고 설명했다.건물 골조에 쓰이는 철근·H형강…美 가격 급등에 韓 가성비 부각"철강수요 백열 수준으로 뜨겁다"미국의 인공지능(AI) 데이터센터 건설 붐이 국내 철강업계에 뜻밖의 특수를 가져다주고 있다. 현지 철강 공급 부족에 직면한 건설업체들이 장거리 운송 비용을 감수하면서까지 한국산 철강 수입을 늘리고 있어서다. 고부가가치 맞춤형 제품을 개발·공급하기 위한 철강업체의 대응도 빨라지고 있다.한경DB◇대미 철근 수출 ‘깜짝’ 급증8일 대체 데이터 플랫폼 한경에이셀(Aicel)에 따르면 올해 들어 봉형강 수출이 이례적인 증가세를 보이고 있다.올해 1~2월 누적 수출금액은 4억1875만달러(약 6100억원)로 전년 동기(3억128만달러)보다 39.0% 증가했다. 전체 철강 제품 수출이 42억9448만달러로 2.9% 감소한 점을 감안하면 눈에 띄는 증가세다. 봉형강은 철근과 H형강 등 주로 건물 골조에 쓰이는 제품이다.봉형강과 달리 다른 철강 제품 수출은 이 기간 일제히 감소했다. 가장 큰 비중을 차지하는 판재류는 29억6254만달러로 5.8% 줄었다. 속이 빈 철강재인 강관 수출금액도 3억3951만달러로 13.3% 축소됐다. 형틀에 쇳물을 부어 만드는 주강, 내구성을 키운 단강 수출액은 합쳐서 1억4395만달러로 12.2% 감소했다.‘나홀로’ 수출 증가의 핵심 배경은 미국의 철근 수입 수요 급증이다. 대미 봉형강 수출금액은 1~2월 누적 1억6000만달러(약 2370억원)로 1년 전보다 703.7% 급증했다. 작년 4분기에 131.1% 증가해 눈길을 끈 데 이어 증가 속도가 더 가팔라졌다.데이터센터 건설 붐으로 미국이 한국산 철근 수입을 대폭 늘리고 있는 것으로 전문가들은 분석했다. 미국 하이퍼스케일러(대규모 클라우드 인프라를 운영하는 빅테크)는 천문학적인 자금을 투입한 건설 프로젝트를 동시다발로 추진 중이다. 미국 최대 전기로 철강사 뉴코어의 리언 토팰리언 최고경영자(CEO)는 지난해 10월 분기실적 발표 당시 “데이터센터의 철강 수요가 ‘백열(white hot)’ 수준으로 뜨겁다”고 표현하기도 했다.현지 철근 가격 상승세도 건설업자들이 상대적으로 저렴한 한국산에 눈을 돌리게 했다. 미국 노동통계국에 따르면 미국의 콘크리트 보강용 철근 생산자물가지수(PPI)는 올해 1월 330.6으로 작년 동월(276.3) 대비 19.7% 상승했다. 반대로 국내 철근 가격은 건설경기 침체로 수년간 하락세를 지속하고 있다. t당 가격은 작년 상반기 850달러로 2022년 상반기(1135달러)와 비교해 25.1% 하락했다. 장재혁 메리츠증권 연구원은 “알제리 등 기존 대미 철근 수출국 물량이 관세 등 여파로 감소하며 공급 공백이 생겼다”며 “미국 기업들이 이 공백을 가격 경쟁력을 갖춘 한국산으로 메우고 있다”고 분석했다.◇글로벌 DC 용량 14%씩 증가국내 철강업계는 고성장 인프라 수요를 흡수하기 위해 하이퍼스케일러와의 제휴와 데이터센터 맞춤형 제품 출시를 서두르고 있다.국내 최대 철근 생산업체인 현대제철은 글로벌 하이퍼스케일러인 아마존과 협력해 저탄소 강재를 데이터센터 프로젝트에 공급하는 방안을 추진 중이다. 데이터센터에 친환경 자재 사용을 의무화하는 규제 방향을 반영한 전략이다. 철근 생산능력 국내 2위 동국제강은 지난해 AI 데이터센터 맞춤형 특수 강재인 디-메가빔을 생산하기 시작했다. 일반 건물보다 훨씬 큰 하중을 견딜 수 있도록 강도를 대폭 높인 형강 제품이다.부동산 컨설팅업체 존스랑라살(JLL)은 글로벌 데이터센터 용량이 지난해 103GW에서 2030년 200GW로 연평균 14%씩 증가할 것으로 내다봤다. 올해 건설비용은 ㎿당 1130만달러로 전년 대비 6% 상승할 것으로 예상했다. 앤드루 뱃슨 JLL 데이터센터 리서치헤드는 “데이터센터 산업이 역사상 최대 인프라 투자 슈퍼사이클의 초기 단계에 들어섰다”며 “전력부터 부동산까지 다양한 산업을 동시에 재편하고 있다”고 말했다.', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005259526', 'https://imgnews.pstatic.net/image/015/2026/03/08/0005259526_001_20260309010112299.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-08 17:45:12', 0, true, '2026-03-09 05:41:53.570543') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (500, '벼랑 끝 철강업계, 야간 전기요금 부담까지…자구책 마련 속도', '현대제철 인천공장 전기로. 현대제철정부가 야간 전기요금을 인상하는 방향의 전기요금 체계 개편을 추진하면서 철강업계 우려가 커졌다. 중국산 저가 철강재가 확산하는 상황에 전기요금 부담까지 더해질 전망이어서 자구책 마련에 속도를 내고 있다.8일 업계에 따르면 철강업계는 최근 기후환경에너지부와 산업통상부에 전기요금 개편 관련 의견을 전달했다. 정부가 1분기 중 계절·시간대별 요금제(계시별 요금제) 개편을 추진하는 과정에서 산업 특성에 맞는 정교한 요금제 개편안을 마련해야 한다는 취지다.정부는 태양광 등 재생에너지 발전이 확대되면서 낮 시간대 전력 공급이 수요를 초과하는 현상이 나타나자 낮 시간대 요금은 낮추고 야간 요금을 인상하는 방향으로 개편을 검토한다.철강업계는 이 같은 요금제 개편이 산업 특성을 충분히 고려하지 못한 정책이라고 지적했다.철강사들은 산업용 전기요금 인상의 부담을 상쇄하기 위해 비교적 저렴한 야간 가동을 통해 수익성을 방어해 왔다. 낮 시간에는 설비 점검이나 공장 개·보수 작업이 이뤄지는 경우가 많다. 즉 야간 전기요금 인상은 원가 부담으로 이어질 수밖에 없다는 얘기다.업계는 중국산 저가 철강재 유입과 미국의 50% 관세 등 구조적 위기에 놓인 상황에서 전기요금 부담까지 커진다면 산업경쟁력이 더욱 악화될 수 있다고 우려했다.이 같은 정책이 철강산업의 ''그린 경쟁력'' 확보라는 정부의 목표에도 반한다는 지적도 나온다. 탄소중립 추진을 위해서는 전기로(전기가 발생하는 열로 금속을 녹여 정련하는 로)를 활용해야 하지만 새로운 정책 방향은 이 같은 흐름과 충돌할 수 있다는 것이다.업계 관계자는 “정부가 업계의 의견을 수렴하고 있지만 반영되지 않는 모습”이라며 “전기요금제가 개편된다면 철강산업 경쟁력의 위기는 더욱 커질 우려가 있다”라고 말했다.주요 철강사들은 전기요금 부담을 줄이기 위해 자구책 마련에 나서고 있다.현대제철의 경우 당진제철소에 액화천연가스(LNG) 발전소 건설을 추진 중이다. 중동의 지정학적 리스크로 LNG 가격 변동성이 커졌지만 전기요금 부담과 비교하면 안정적인 전력 확보 수단이라는 판단이다. 현대제철은 이달 열릴 정기 주주총회에서 사업목적에 천연가스 수출입업을 추가할 계획이다.포스코는 포항제철소에 기존 설비를 확대한 600㎿ LNG발전소 건설을 추진 중이다. 전력 공급을 늘려 수소환원제철 등에 필요한 전력을 공급할 방침이다.동국제강의 경우 전기로의 생산효율을 끌어올려 탄소 저감 효과를 내는 ''하이퍼 전기로'' 고도화에 집중하고 있다. 폐열 활용과 열 투입 방식, 원료 투입 등 기술적 완성도를 높여 하이퍼 전기로의 효율을 높인다는 전략이다.업계 관계자는 “그린 경쟁력 확보를 위해서는 막대한 전력이 필요하다”며 “안정적인 전력 공급과 요금 부담 완화를 위해 자체 발전 등 자구책을 마련하는 곳이 늘어날 것”이라고 전했다.조성우 기자 good_sw@etnews.com', NULL, '전자신문', 'https://n.news.naver.com/mnews/article/030/0003405296', 'https://imgnews.pstatic.net/image/030/2026/03/08/0003405296_001_20260308192407378.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-08 15:31:58', 0, true, '2026-03-09 05:41:53.570543') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (501, '한국철강협회, ''스틸-AI 안전환경협의체'' 개최', '한국철강협회는 인공지능(AI) 적용 사례를 공유하고 실행 중심 스마트 안전관리 체계 구축 방안을 논의하기 위해 ''2026년도 제1차 스틸(Steel)-AI 안전환경협의체''를 개최했다고 3월5일 밝혔다. [사진=한국철강협회][디지털데일리 최민지기자] 한국철강협회는 인공지능(AI) 적용 사례를 공유하고 실행 중심 스마트 안전관리 체계 구축 방안을 논의하기 위해 2026년도 ''제1차 스틸(Steel)-AI 안전환경협의체''를 개최했다고 5일 밝혔다.경주 교원드림센터에서 열린 이번 협의체에는 포스코, 현대제철, 동국제강, 세아창원특수강, KG스틸 등 주요 철강업체와 정보통신기술(ICT) 기업·연구기관 등 21개사 약 60명이 참여했다.이번 협의체에서는 정책 방향과 현장 적용 기술·정부 연구개발(R&D) 연계 방안 등을 논의했다.숭실대학교 이준원 교수는 최근 중대재해 발생 현황을 분석하고 정부 예방 중심 안전보건 정책 방향을 공유했다. AI 기반 스마트 안전기술을 활용한 휴먼에러 저감과 사고 예방 방안도 제시했다.포항산업과학연구원 유기성 그룹장은 현장 맞춤형 스마트 안전기술맵을 기반으로 사전 예지 중심 지능형 안전관리 패러다임 전환을 추진하고 있다고 설명했다. K-세이프티 플랫폼과 안전혁신센터 구축을 통해 계열사 전반에 안전 데이터 기반 통합 관리체계를 확산하고 있다.위드로봇 김도윤 대표는 와이어 기반 이동형 로봇 ''와이럴봇(WiralBot)''과 엣지 AI 기술을 소개했다. 현장에서 즉시 이상을 판단하는 ''카멜레온 보드''를 활용한 화재·설비 사고 대응 체계를 소개했다. 지능형 예지보전 기반 설비 이상 사전 예측 방안도 제시했다.인하대학교 이창선 교수는 제조 변수와 전조 데이터를 기반으로 사고 이전 단계에서 위험을 판단·대응하는 AI 안전 플랫폼을 발표했다. 고위험 제조 현장에서 사고 예방과 생산·안전 균형을 동시에 달성하는 방향도 공유했다.한국금속재료연구조합 김태윤 실장은 정부 R&D 전주기 프로세스와 AI 얼라이언스 운영 현황을 밝히며 2026~2027년 AI 관련 사업 주요 기획 방향을 소개했다.한국철강협회 강성욱 전무는 "이번 협의체는 AI 기술 공유를 넘어 철강 현장 중대재해 예방을 위한 실행 중심 대응 전략을 논의하는 자리"라며 "위험 인지 기술과 로봇 활용 등 구체적 방안을 통해 업종 차원 안전관리 체계를 고도화하겠다"고 말했다.', NULL, '디지털데일리', 'https://n.news.naver.com/mnews/article/138/0002219664', 'https://imgnews.pstatic.net/image/138/2026/03/05/0002219664_001_20260305154617038.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-05 15:46:17', 0, true, '2026-03-09 05:41:53.570543') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (502, '[기업이슈] AI데이터센터 붐에 강재 수요 확대 기대…철강주 강세', '■ 머니쇼 ''기업이슈'' - 도지은어제장에서 이슈가 있었던 업종 살펴보는 기업이슈 시간입니다.◇ UAE와 50조 규모 경제협력 소식에 방산주 상승한국과 아랍에미리트 정부가 350억 달러(우리 돈으로 약 50조 원) 규모의 ''방산 협력 프레임워크 양해각서''를 맺으면서 국내 방산주, 강세 보였습니다.전문가들은 "이번 MOU가 한국 방위 산업의 위상을 또다시 한 단계 끌어올리는 계기가 될 것"이라면서 "약 50조 원이라는 규모가 갖는 상징성뿐 아니라, 단순 판매를 넘어 개발에서 유지·보수에 이르는 전방위적 협력에 대한 합의를 통해 구조적이고 장기적인 성장 모델을 구축했기 때문"이라고 평가했습니다.◇ 현대차 "새만금을 ''AI-로봇-수소'' 도시로"현대차가 올해 전북 새만금 지역에 9조 원을 단계적으로 투자해 인공지능·로봇·에너지를 아우르는 혁신성장거점을 구축한다는 소식에 장중 급등세 보였습니다.이번 투자는 AI 데이터센터(5조 8천억 원), 로봇 제조·부품 클러스터(4천억 원), 수전해 플랜트(1조 원), 태양광 발전(1조 3천억 원) 등으로 구성됩니다.새만금 부지 약 34만 평를 활용하는 대규모 프로젝트인 이번 사업을 통해, 현대차그룹은 피지컬 AI와 탄소 중립 시대를 선도하는 ''미래기술 기업''으로 도약하겠다는 구상입니다.◇ AI 데이터센터 붐에 철강주↑…현대제철 등 강세인공지능 데이터센터 붐에 따라 맞춤형 강재 수요 확대 기대감에, 그간 침체됐던 철강 기업들의 주가가 강세 보였습니다.일례로, 앞서 현대제철은 탄소 배출량을 기존 대비 20% 절감한 저탄소 강판의 양산 체제를 갖췄다고 발표했습니다.동국제강도 AI 데이터센터 산업 진출을 선언하기도 했는데요.그간 국내 철강사들은 건설 경기 부진과 해외 기업의 저가 물량 공세, 산업용 전기요금 인상 및 미국의 관세 압박 등 복합적인 악재로 몸살을 앓아왔는데, 지난주 금요일 AI 확산에 발맞춘 철강 기업들의 공급 전략 발표에 투자 심리가 자극된 것으로 보입니다.◇ 남북경협주, 북·미 대화 재개 기대감에 강세미국이 북한과 전제 조건 없는 대화에 열린 입장을 유지 중이란 소식에 남북경협주 주가도 강세보였습니다.앞서 정부 북핵 수석대표인 정연두 외교부 외교전략정보본부장이 "미국이 북한과 전제 조건 없는 대화에 열린 입장에 변함이 없음을 확인했다"고 밝힌 것이 투자심리를 자극한 것으로 보입니다.다만, ''북한과의 조건 없는 대화에 열려 있다''는 미국 측 입장과 관련해, 정부 고위 당국자는 북미 간의 접촉이 진행 중인지에 대해 "(북미 간의) 실무접촉 같은 새로운 뉴스는 없다"고 밝혔습니다.당신의 제보가 뉴스로 만들어집니다.SBS Biz는 여러분의 제보를 기다리고 있습니다.홈페이지 = https://url.kr/9pghjn', NULL, 'SBS Biz', 'https://n.news.naver.com/mnews/article/374/0000495336', 'https://imgnews.pstatic.net/image/374/2026/03/03/0000495336_001_20260303082012263.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-03 08:20:12', 0, true, '2026-03-09 05:41:53.570543') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (503, '[애프터마켓 리뷰] AI 데이터센터 붐에 철강주↑…현대제철 등 강세', '■ 모닝벨 ''애프터마켓 리뷰'' - 도지은애프터마켓 정리해 드립니다.최근 AI 관련해 반도체나 전력 기기가 가장 주목받았는데, 잠잠하던 ''철강주'' 주가가 튀어 오르면서 눈길을 끌었습니다.지난주 금요일 애프터마켓에서도 현대제철, 동국제강 등 주요 철강주들 상승세 이어졌는데요.전통적인 굴뚝 산업으로 불리던 철강이 갑자기 AI 테마에 올라탄 이유는, 바로 AI 데이터센터의 ''뼈대'' 때문입니다.AI 서버는 일반 서버보다 훨씬 무겁고 전력 설비나 냉각 장치도 대규모로 들어가기 때문에, 건물이 버텨야 하는 하중이 엄청난데요.그래서 일반 빌딩보다 훨씬 많은 양의 철강이 투입될 뿐만 아니라, 열에 강하고 단단한 ''고부가가치 강재''가 필수적입니다.이미 미국과 일본의 대형 철강사들은 공장을 데이터센터 전용 라인으로 바꾸며 발 빠르게 움직이고 있는데, 이에 우리 기업들도 본격적인 수혜를 준비하고 있습니다.현대제철은 아마존웹서비스와 손잡고 데이터센터용 탄소 저감 철강재 공급을 추진 중이고요.동국제강은 데이터센터 전용 대형 형강을 선보이는 동시에, 그룹 자산을 활용한 데이터센터 투자까지 검토 중인 것으로 알려졌습니다.전문가들은 건설 경기 침체로 어려움을 겪던 철강사들에게 AI 인프라가 새로운 ''활로''이자 ''수익 모델''이 될 것으로 내다보고 있습니다.반도체에서 시작된 AI 특수가 철강이라는 기초 소재 산업까지 확산하고 있다는 점, 흐름을 읽으실 때 꼭 참고해 보시면 좋겠습니다.지난주 금요일에 국내증시 숨을 고르는 모습이었는데요.외국인이 하루 사이 역대 최대 규모, 7조 원을 투매하면서 코스피는 6200선으로 밀리면서 마감했습니다.앞서서 엔비디아 주가가 급락하면서 심리적 충격이 작용한 모습인데, 저녁에도 삼성전자 0.23% 하락, SK하이닉스는 3%대 하락하면서 장을 마쳤습니다.시총 상위 주 5위 안에서는 현대차만 홀로 빨간 불을 켰는데, 현대차는 전북 새만금 지역에 9조 원 규모의 대규모 투자를 단행한다는 소식을 전하면서 사상 최고가를 경신하기도 했습니다.반면 LG에너지솔루션은 0.12% 하락, SK스퀘어도 SK하이닉스와 함께 4.5%대 하락으로 마감했습니다.이 외에 한국과 아랍에미리트 정부가 방산 분야 사업에 대해 협력하기로 합의했다는 소식에, 국내 방산주들은 좋은 흐름 보였습니다.코스닥으로 넘어가 보시죠.이날 코스피보다 코스닥 지수 흐름이 더 좋았는데요.에코프로 0.81% 상승, 알테오젠도 1%대 올랐고, 그 전거래일에 상한가 찍었던 삼천당제약은, 금요일에도 7%대 급등세 보이면서 마감했습니다.마지막으로 레인보우로보틱스는 1.59% 하락했습니다.미국의 이란 공습 여파로 글로벌 증시 전반적으로 불확실성이 커진 가운데, 연휴를 마치고 개장하는 국내증시, 장초반 흐름이 어떨지 잠시 후 프리마켓 통해서 미리 살펴보시죠.애프터마켓 리뷰였습니다.당신의 제보가 뉴스로 만들어집니다.SBS Biz는 여러분의 제보를 기다리고 있습니다.홈페이지 = https://url.kr/9pghjn', NULL, 'SBS Biz', 'https://n.news.naver.com/mnews/article/374/0000495323', 'https://imgnews.pstatic.net/image/374/2026/03/03/0000495323_001_20260303075409467.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-03 07:54:09', 0, true, '2026-03-09 05:41:53.570543') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (504, '철강협회,‘친환경 금속소재산업 전문인력양성사업 성과교류회’통해 산학 네트워킹', '영남대 안효주 학생 사업 최우수 선정 영예[파이낸셜뉴스]26일 한국철강협회 주최로 포항 라한호텔에서 열린 친환경 금속소재산업 전문인력양성사업 총괄 성과교류회에서 참석자들이 기념촬영을 하고 있다. 한국철강협회제공한국철강협회(이하 협회)는 26일 포항 라한호텔에서 ‘친환경 금속소재산업 전문인력양성사업 총괄 성과교류회(이하 성과교류회)’를 개최했다고 27일 밝혔다.산업통상부가 지원하고 한국철강협회가 주관한 이번 행사는 철강·금속산업의 미래를 이끌어갈 저탄소 공정기술과 친환경 제품 개발 전문 인력들의 연구 성과를 공유하기 위해 마련됐다.이날 성과교류회에는 7개 사업 참여대학에서 우수 ‘산학협력 프로젝트 연구’수행자로 선정된 13명의 사업 참여 대학원생과 포스코, 현대제철, 동국제강, 세아제강, 고려제강 등 포항 소재 주요 철강기업 소속 전문가가 평가위원으로 참석했다.각 사업 참여대학을 대표하는 대학원생들은 수소환원제철, 친환경 신소재 개발, 공정 최적화 등 철강업계 핵심 이슈를 다룬 산학프로젝트 성과 발표를 진행했으며, 기업 평가위원들은 해당 산학프로젝트의 계획 적정성·운영과정·연구성과 및 파급력을 기준으로 심도 있는 평가 피드백을 제공했다.기업 평가위원들의 성과평가 결과, ‘폐플라스틱 기반 친환경 가탄재를 활용한 슬래그 포밍 특성 및 기공 분석’을 주제로 발표한 영남대학교 안효주 학생(석사과정)이 탁월한 성과를 인정받아 사업 최우수 참여 학생으로 선정돼 최우수상(한국철강협회장상)을 수상했다. 영남대 안효주 학생은 “이번 사업을 통해 단순한 이론 위주 학습을 넘어 실제 산업 현장에 적용할 수 있는 프로젝트를 수행할 수 있었다”면서, “특히 오늘 기업 현직자들께서 주신 피드백 덕분에 앞으로의 연구 방향성을 확립할 수 있었고, 연구자로 성장하는 데 큰 디딤돌이 됐다”고 소감을 밝혔다.성과평가 이후 진행된 전체 참석자 만찬 간담회에서는 앞선 순서에서 평가위원이었던 기업체 소속 전문가가 멘토가 되고, 참여 대학원생이 멘티가 되어 한 테이블에서 함께 식사를 하는 가운데 상호 연구 분야와 공통 관심사를 바탕으로 자연스레 현장 전문지식 공유와 진로 조언이 이뤄졌다.협회 관계자는“친환경 금속소재산업 전문인력양성사업은 우리 철강산업의 초격차 경쟁력을 이끌어갈 실무형 핵심 융합 인재를 육성해 업계에 안정적으로 공급하는 매우 중요한 의미를 가지는 기반 사업”이라며, “앞으로도 산학 교류의 장을 지속적으로 넓혀 우수한 예비 전문인재들이 철강 실무 현장에 원활하게 진출할 수 있도록 적극 지원하겠다”고 밝혔다', NULL, '파이낸셜뉴스', 'https://n.news.naver.com/mnews/article/014/0005484127', 'https://imgnews.pstatic.net/image/014/2026/02/27/0005484127_001_20260227172709455.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-27 17:27:09', 0, true, '2026-03-09 05:41:53.570543') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (505, '전기료 부담에 ‘직구’ 나선 기업들…“요금 구조 새판 짜야”', '[앵커]한때 미국은 한국의 값싼 전기요금이 사실상 정부 보조금이라고 주장했습니다.그만큼 저렴하고 안정적인 전력망, 우리 산업의 경쟁력으로 꼽혔는데, 저렴하다는 건 이제 옛말입니다.산업용 요금이 유독 가파르게 오르면서 급기야 전기 직구에 나서는 기업이 늘고 있습니다.이어서 송락규 기자입니다.[리포트]고압의 전기봉으로 고철을 녹여 쇳물을 만드는 전기로입니다.탄소 배출량이 기존 용광로의 4분의 1 수준.세계 각국의 탄소 규제에 대응하기 딱 좋습니다.문제는 전기요금입니다.철 생산원가 중 전기료는 10~15%를 차지하는데 5년 전부터 산업용 전기요금이 급등하면서  부담이 더 커졌습니다.[이재윤/산업연구원 산업탄소중립연구실장 : "철강 산업의 저탄소화의 수단으로 고로보다는 전기로 가동을 좀 더 높여야 하는 상황인데요. 최근에 급등한 전력 요금 인상으로 인해서 전기로 가동을 높이는 데 조금 제한이 있고…."]연간 전기요금만 수조 원.업황 악화까지 겹치며 결국 일부는 용광로를 껐습니다.24시간 공장을 돌려야 하는 석유화학과 반도체 산업도  어려움을 호소합니다.우리나라의 산업용 전기요금은 OECD 기준으로는 여전히 낮은 수준이지만, 미국이나 중국보다 더 비쌉니다.주택용 전기 요금을 동결에 가깝게 묶어두면서  산업용 전기 요금을 빠르게 인상하다 보니 가격 경쟁력을 잃었다는 평가가 나옵니다.실제로 주택용과 산업용 요금은 2023년 역전됐습니다.기업들은 전력 직구라는 우회로도 찾아 나섰습니다.한국전력을 거치지 않고 발전사업자에게서 전력을 직접 사면  전기 요금을 10% 아낄 수 있습니다.1년 새 27개 기업이 뛰어들었습니다.[정연제/서울과기대 에너지정책학 교수 : "산업용 전기 요금은 몇 년 동안 많이 올렸기 때문에 산업 경쟁력을 확보할 수 있는 방향으로 정부에서 지원 방안을 좀 마련해 주는 게 좋지 않을까… (주택용) 전기요금을 현실화 시켜서 어느 정도 가격 신호를 제공해 주는 것도 고민해 볼 때가 아닌가…."]정부는 산업용 전기요금 개편안을 다음 달 발표할 예정입니다.KBS 뉴스 송락규입니다.영상편집:한찬의/그래픽:박미주 김경진/영상 출처:현대제철·동국제강 공식 유튜브 채널■ 제보하기▷ 전화 : 02-781-1234, 4444▷ 이메일 : kbs1234@kbs.co.kr▷ 카카오톡 : ''KBS제보'' 검색, 채널 추가▷ 네이버, 유튜브에서 KBS뉴스를 구독해주세요!', NULL, 'KBS', 'https://n.news.naver.com/mnews/article/056/0012132233', 'https://imgnews.pstatic.net/image/056/2026/02/27/0012132233_001_20260227072633498.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-27 06:29:15', 0, true, '2026-03-09 05:41:53.570543') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (506, '철강도 AI 특수… 데이터센터 뼈대 만든다', '고부가가치 강재 수요 확대동국제강이 AI 데이터센터의 고강도·고하중 설비를 버틸 수 있도록 제작한 맞춤형 특수 강재 ''디-메가빔(D-Mega Beam)''. /동국제강미국 최대 전기로 철강사 뉴코어는 작년 하반기 기존 공장 2곳을 데이터센터 전용 강재 생산 시설로 전환했다. 일본제철도 US스틸 인수 이후 미국 노후 제철소를 개선해 2028년부터 데이터센터용 고급 강재를 양산하겠다며 수십억 달러 규모 추가 투자를 예고했다. AI 데이터센터 붐이 철강 업계의 생산 라인을 바꾸기 시작한 것이다.건설 경기 침체로 전통적인 수요처가 위축된 철강 업계에서 AI 데이터센터가 새 시장으로 주목받고 있다. 데이터센터는 일반 상업용 건물보다 철강 투입량이 구조적으로 많다. 서버와 네트워크 장비, 냉각 장비까지 겹겹이 쌓이는 다층 설계로 인해 건물 하중이 더 크기 때문이다.AI 데이터센터 붐이 먼저 일어난 미국에선 철강 기업들이 맞춤형 생산에 이미 돌입했고, 국내 철강사들도 고부가가치 강재 생산 등 사업 확대를 검토하고 있다.일반 빌딩보다 철강 수요 多AI 데이터센터는 고성능 GPU 서버, 전력 설비, 대형 냉각 장치가 다층으로 배치된다. 바닥 하중과 진동 기준이 훨씬 엄격하다. 주요 골조뿐 아니라 이중 바닥, 케이블 트레이, 냉각 설비 지지 구조까지 철강이 대거 투입된다. 특히 폭증하는 AI 수요 때문에 대규모 시설을 짧은 기간에 안정적으로 지어야 하는 특성상 설계·시공이 용이한 철골 구조가 선호된다.여기에다 전력 설비·에너지저장장치(ESS)·차폐 구조물에는 고강도·고내열 강재가 요구된다. 단순히 물량 수요만 많은 게 아니라 고부가가치 제품 비중이 높다는 의미다. 업계 관계자는 “AI 서버가 고성능이 될수록 전력·냉각 설비가 늘고 이를 지탱하는 구조·차폐 강재 수요도 함께 증가하는 구조”라고 설명했다.미국은 마이크로소프트·아마존·구글이 수십 GW(기가와트)급 설비 확장 계획을 밝히면서 관련 철강 수요도 빠르게 늘고 있다. 뉴코어는 데이터센터 구조용 강재에 맞춰 생산 설비를 조정했고, 일본제철은 미국 현지에서 고급 강재 양산 체제를 구축 중이다. AI 인프라 확충이 철강 설비 투자까지 자극하는 선순환 구조다.대형 서버 장비가 밀집한 SK의 AI 데이터센터 내부 모습. /SK텔레콤美 철강사, 데이터센터 맞춤 전환 속도국내에서도 SK그룹이 작년 8월 아마존웹서비스(AWS)와 함께 울산에 100MW(메가와트)급 AI 데이터센터 건설에 착공하고, 삼성이 오픈AI와 함께 포항에 AI 데이터센터 조성에 나서면서 데이터센터 수요에 대한 기대가 커지고 있다. 데이터센터를 추진하는 기업들이 데이터센터에도 저탄소 철강 사용을 검토하면서, 보다 수익성이 높은 고부가가치 철강 시장 확대를 기대하는 측면도 있다.동국제강은 특수 강재 생산뿐 아니라 직접 공장 부지와 전력 인프라 등 그룹 자산을 활용한 AI 데이터센터 투자까지 검토하고 있다. 우선 최대 폭 3m까지 맞춤 제작이 가능한 대형 형강을 선보이며 데이터센터, 플랜트 등 대형 인프라 시장을 겨냥하고 있다. 포스코도 정부의 AI 인프라 확충 계획에 따라 향후 시장성이 커질 것으로 전망하고, 전력용 강재 등 고부가가치 철강재 수요 확대를 기대하고 있다.현대제철은 지난해 AWS와 협약을 맺고, 아시아·태평양 지역 데이터센터에 탄소 저감 철강재를 공급하는 방안을 추진하고 있다. 현대차그룹과 함께 추진하는 미국 루이지애나주 제철소가 완공되면 현지 데이터센터 건설 수요에도 대응할 수 있을 전망이다. 전체 철강 수요에서 데이터센터 비중은 아직 크지 않지만 업계에서는 AI 확산과 함께 수요가 빠르게 늘어날 것으로 보고 있다.', NULL, '조선일보', 'https://n.news.naver.com/mnews/article/023/0003961383', 'https://imgnews.pstatic.net/image/023/2026/02/27/0003961383_001_20260227101308215.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-27 00:34:17', 0, true, '2026-03-09 05:41:53.570543') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (507, '전기료 부담에 ‘직구’ 나선 기업들…“요금 구조 새판 짜야”', '[앵커]한때 저렴하고 안정적인 전력망은 우리 산업의 경쟁력으로 꼽혔습니다.하지만 저렴하다는 건 이제 옛말이 됐는데요.산업용 전기 요금이 가파르게 오르면서 급기야 전기 직구에 나서는 기업이 늘고 있습니다.이어서 송락규 기자입니다.[리포트]고압의 전기봉으로 고철을 녹여 쇳물을 만드는 전기로입니다.탄소 배출량이 기존 용광로의 4분의 1 수준.세계 각국의 탄소 규제에 대응하기 딱 좋습니다.문제는 전기요금입니다.철 생산원가 중 전기료는 10~15%를 차지하는데 5년 전부터 산업용 전기요금이 급등하면서  부담이 더 커졌습니다.[이재윤/산업연구원 산업탄소중립연구실장 : "철강 산업의 저탄소화의 수단으로 고로보다는 전기로 가동을 좀 더 높여야 하는 상황인데요. 최근에 급등한 전력 요금 인상으로 인해서 전기로 가동을 높이는 데 조금 제한이 있고…."]연간 전기요금만 수조 원.업황 악화까지 겹치며 결국 일부는 용광로를 껐습니다.24시간 공장을 돌려야 하는 석유화학과 반도체 산업도  어려움을 호소합니다.우리나라의 산업용 전기요금은 OECD 기준으로는 여전히 낮은 수준이지만, 미국이나 중국보다 더 비쌉니다.주택용 전기 요금을 동결에 가깝게 묶어두면서  산업용 전기 요금을 빠르게 인상하다 보니 가격 경쟁력을 잃었다는 평가가 나옵니다.실제로 주택용과 산업용 요금은 2023년 역전됐습니다.기업들은 전력 직구라는 우회로도 찾아 나섰습니다.한국전력을 거치지 않고 발전사업자에게서 전력을 직접 사면  전기 요금을 10% 아낄 수 있습니다.1년 새 27개 기업이 뛰어들었습니다.[정연제/서울과기대 에너지정책학 교수 : "산업용 전기 요금은 몇 년 동안 많이 올렸기 때문에 산업 경쟁력을 확보할 수 있는 방향으로 정부에서 지원 방안을 좀 마련해 주는 게 좋지 않을까…, (주택용) 전기요금을 현실화 시켜서 어느 정도 가격 신호를 제공해 주는 것도 고민해 볼 때가 아닌가…."]정부는 산업용 전기요금 개편안을 다음 달 발표할 예정입니다.KBS 뉴스 송락규입니다.영상편집:한찬의/그래픽:박미주 김경진/영상 출처:현대제철·동국제강 공식 유튜브 채널■ 제보하기▷ 전화 : 02-781-1234, 4444▷ 이메일 : kbs1234@kbs.co.kr▷ 카카오톡 : ''KBS제보'' 검색, 채널 추가▷ 네이버, 유튜브에서 KBS뉴스를 구독해주세요!', NULL, 'KBS', 'https://n.news.naver.com/mnews/article/056/0012132046', 'https://imgnews.pstatic.net/image/056/2026/02/26/0012132046_001_20260226220638959.png?type=w800', 'NEWS_ETC', NULL, '2026-02-26 21:35:26', 0, true, '2026-03-09 05:41:53.570543') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (508, '스페셜티로 승부…K-철강, 방산·에너지 소재 공략', '신 방산 소재를 적용한 차세대 함정 가상 이미지. 포스코중국발 과잉 공급으로 위기에 빠진 철강업계가 고부가 스페셜티 제품으로 돌파구 찾기에 나섰다. 방산·조선·우주·에너지 등 산업용 소재 시장을 선점해 수익성을 회복하겠다는 구상이다.26일 관련 업계에 따르면 포스코, 현대제철, 세아그룹 등 주요 철강사들이 스페셜티 공급 및 판매 확대에 나서고 있다.중국발 과잉 공급으로 인해 저가 범용 제품이 밀려 들어오면서 국산 철강재는 가격 경쟁력을 상실했다. 이에 기술 경쟁력을 갖춘 고부가 스페셜티 제품 판매를 통해 수익성 확보에 나서고 있다. 특히 방산, 조선, 에너지, 자동차 등 전방산업 중심으로 제품 개발과 판매 확대에 주력하고 있다.포스코는 함정용 고연성강과 방탄강을 국내 최초로 개발해 한국선급(KR) 인증까지 획득했다. 고연성강은 기존 조선용 후판 강재 대비 연신율을 35% 이상 향상시킨 강재로, 충격 흡수율은 기존 제품 대비 50% 높다. 또 철에 망간을 다량 투입해 영하 196도에서도 깨지지 않는 소재인 고망간강도 자체 개발했다. 고망간강은 액화천연가스(LNG)·액화수소 운반선 탱크 및 육지 저장탱크 등에 활용된다.현대제철은 고성형성, 고강도 및 경량화 특성을 갖춘 3세대 자동차용 강판을 올해 1분기 양산할 계획이다. 고강도 극후물재 개발 및 인증을 완료하고 신안 우이 해상풍력 프로젝트에 초도 공급하는 등 해상풍력용 후판 수요에도 나설 계획이다.세아그룹은 올 하반기 본격 가동 예정인 북미 세아슈퍼알로이테크놀로지를 통해 항공·우주 소재 등 특수합금 상업 생산에 본격적으로 나설 예정이다. 세아창원특수강은 한화에어로스페이스에 900도급 초내열합금 시제품을 공급하는 등 초내열합금 제품 공급 확대에 박차를 가하고 있다.동국제강그룹은 동국씨엠의 세계 최초 태양광 전용 초고반사 솔라셀 컬러강판을 앞세워 신재생에너지 시장 진출을 노리고 있다. 또 동국제강의 디-메가빔 등을 통해 데이터센터 등 건설 자재 스페셜티 포트폴리오 구축에 박차를 가하고 있다.한 업계 관계자는 “범용 제품만으로는 더 이상 경쟁력을 갖추기 어렵다”라며 “고부가 스페셜티 제품으로 수익성을 확보해야 한다”고 밝혔다.조성우 기자 good_sw@etnews.com', NULL, '전자신문', 'https://n.news.naver.com/mnews/article/030/0003402602', 'https://imgnews.pstatic.net/image/030/2026/02/26/0003402602_001_20260226193541120.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-26 17:01:11', 0, true, '2026-03-09 05:41:53.570543') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (510, '‘4세 경영 돌입’ GS엔텍, 하반기 투자 유치 카드 ‘만지작’', '[본 기사는 02월 20일(15:26) 매일경제 자본시장 전문 유료매체인 ‘레이더M’에 보도 된 기사입니다]GS 오너가 4세 경영 체제로 돌입한 해상풍력 모노파일 제조 기업 GS엔텍이 이르면 올 하반기 신규 투자 유치를 검토하고 있다.성장 동력에 필요한 재원을 확보해 2028년 기업공개(IPO)를 준비하려는 움직임으로 분석된다.20일 투자은행(IB) 업계에 따르면 GS엔텍은 이르면 올 하반기 신규 투자 유치를 검토하고 있다. 늦어도 내년까지는 신규 투자금을 에퀴티(Equity)로 수혈하는것을 목표로 하고 있다.투자 유치 금액 등은 아직 정해지지 않았다. 다만 향후 이뤄질 카펙스(CAPEX) 투자 등을 고려했을 때 최소 1000억원 이상일 것으로 예상된다.[사진=GS엔텍]GS엔텍의 전신은 지난 1988년 설립됐던 대경OEKE다. 2005년 자금난으로 부도 처리된 이후 코스닥에서 퇴출됐다. 이후 2010년 GS글로벌에 인수되면서 GS 그룹에 편입됐다.설립 초기에는 정유·석유화학 플랜트용 화공기기를 전문으로 제작했다. 최근에는 해상풍력 모노파일 제조로 비즈니스 모델 전환을 추진하고 있는 중이다.최근 본격적인 오너 4세 경영이 시작된 이후 전반적인 재정비에 나서는 모습이다. 작년 11월 허철홍 GS글로벌 기획·신사업본부장(부사장)이 신임 대표이사로 선임됐다.허 대표는 허정수 GS네오텍 회장의 장남이자 허준구 GS건설 명예회장의 손자다. 허 명예회장은 GS 그룹 창업주인 고 허만정 명예회장의 셋째 아들로 허 대표는 GS 오너가 4세 경영인에 해당한다.허 대표는 지난 2009년 ㈜GS에 입사한 후 2018년 상무로 승진했다. ㈜GS 경영지원팀 부장, GS칼텍스 경영개선부문장, 경영혁신부문장 등을 거쳤으며 2023년에는 GS칼텍스 자회사인 GS엠비즈 대표로 선임되기도 했다.향후 IPO도 준비해야하는 만큼 신사업에서 성과를 내야 한다. GS엔텍은 지난 2023년 도미누스인베스트먼트, 시몬느자산운용 등으로부터 900억원을 투자받는 과정에서 2028년 IPO를 조건으로 내걸었다.지금 당장 IPO를 위한 움직임이 있는 것은 아니지만, 하반기 투자 유치를 통해 성장 동력을 위한 재원을 확보하려는 것으로 보인다.GS엔텍은 작년에도 에퀴티 투자 유치를 추진한바 있다. 당시 은행권 신디케이션 론 형태로 1500억원을 수혈했다.', NULL, '매일경제', 'https://n.news.naver.com/mnews/article/009/0005640164', 'https://imgnews.pstatic.net/image/009/2026/02/22/0005640164_001_20260222184109767.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-22 18:41:09', 0, true, '2026-03-09 05:42:15.595041') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (512, 'GS글로벌, 임직원 헌혈 캠페인…“헌혈하고 두쫀쿠도”', '‘생명을 나누는 헌혈 캠페인’ 열어GS글로벌 임직원이 11일 서울 역삼동 GS타워 본사에서 혈액 수급 안정화와 생명 나눔 문화 확산을 위해 ‘생명을 나누는 헌혈 캠페인’에 참여하는 모습. ﻿GS글로벌 제공GS글로벌은 서울 강남구 역삼동 GS타워 본사에서 혈액 수급 안정화와 생명 나눔 문화 확산을 위해 ‘생명을 나누는 헌혈 캠페인’을 개최했다고 11일 밝혔다.이번 행사는 겨울철 혈액 수급 부족으로 어려움을 겪고 있는 의료 현장을 지원하고 생명 나눔의 가치를 확산하기 위해 마련됐다.행사에는 김성원 GS글로벌 대표를 포함한 임직원이 자발적으로 참여했다. 대한적십자사가 서울 강남 GS타워 본사 앞에 마련한 헌혈 버스에서 진행됐다.헌혈은 수혈이 필요한 환자들에게 가장 직접적으로 도움이 되는 생명 나눔 활동으로 헌혈 1회는 성분 분리를 통해 최대 3명의 환자에게 도움을 줄 수 있다. 헌혈에 참여한 임직원에게는 헌혈증서와 함께 커피 쿠폰과 두쫀쿠 등 소정의 기념품도 제공됐다.GS글로벌 관계자는 “헌혈은 누구나 참여할 수 있는 가장 따뜻한 기부”라며 “이번 행사를 통해 지역사회에 생명 나눔 문화가 더욱 확산하기를 기대하고 진정성 있는 사회공헌 활동을 지속하겠다”고 말했다.GS글로벌은 헌혈 외에도 소외계층 지원, 고교 장학금 후원 등 다양한 사회공헌 프로그램을 통해 이웃사랑 실천에 적극적으로 나서고 있다.', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003617182', 'https://imgnews.pstatic.net/image/081/2026/02/11/0003617182_001_20260211180212988.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-11 18:02:12', 0, true, '2026-03-09 05:42:15.595041') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (513, '㈜GS, GS칼텍스 정제마진 개선에 숨통 ''고배당 기조'' 유지', '/사진 제공=GS㈜GS가 핵심 자회사인 GS칼텍스의 실적 반등에 힘입어 지난해 실적 방어에 성공했다. 올해 석유화학 및 발전 부문의 부진과 정유 마진의 변동성 등 불확실성이 남아있지만 ㈜GS는 개선된 이익을 바탕으로 고배당 기조를 유지하며 적극적인 주주 환원 의지를 보였다.㈜GS는 11일 2025년 연결기준 매출 25조1841억원, 영업이익 2조9271억원을 각각 기록했다고 밝혔다. 이는 전년 대비 각각 0.3%, 4.5% 감소한 수치다.㈜GS의 수익성을 견인한 주역은 단연 GS칼텍스다. GS칼텍스는 지난해 상반기까지 유가 하락으로 인해 부진한 실적을 냈다. 그러나 4분기 매출은 11조7538억원으로 전년 동기 대비 3% 증가했으며 영업이익은 137% 늘어난 6534억원을 기록했다. 특히 당기순이익은 전년 동기 대비 3116% 급증한 5210억원을 달성했다.국제유가는 지난해 4분기에도 석유수출기구(OPEC) 증산에 따른 공급 증가 우려로 하락세를 보였다. 그러나 글로벌 정제설비의 가동 차질과 계절적 수요 증가가 맞물려 정제마진이 가파르게 상승했다. 윤활유부문 또한 안정적인 마진을 유지하며 수익성 개선에 기여했다.주요 계열사들의 실적은 업황에 따라 희비가 엇갈렸다. 에너지 중간 지주사인 GS에너지는 GS칼텍스의 지분법 이익 개선에 힘입어 4분기 영업이익이 전년 대비 65% 증가한 7019억원을 기록했다.반면 민자 발전사인 GS EPS는 전력도매가격(SMP) 하락의 직격탄을 맞았다. 4분기 SMP 평균 가격이 kWh당 96원으로 전년 동기 대비 17% 하락하면서 GS EPS는 206억원의 영업손실을 내며 적자로 전환했다. GS글로벌 또한 제조부문 공장 전환(컨버전)에 따른 일시적 비용 반영 등으로 영업이익이 32% 감소했다.㈜GS는 GS칼텍스의 실적 회복을 바탕으로 주주환원정책을 강화했다. ㈜GS는 이날 이사회를 열고 2025년 결산배당으로 보통주 1주당 3000원을 지급하기로 결의했다. 이는 전년 2700원 대비 300원 인상된 금액이다.㈜GS는 최근 3개년 별도기준 당기순이익 평균의 40% 이상을 배당성향 목표로 하고 있다. ㈜GS는 2025년 별도기준 매출 3693억원, 영업이익 2816억원, 당기순이익 2499억원을 기록했다. GS에너지 등 자회사 배당금 수익 감소의 영향으로 전년 대비 각각 46%, 52%, 56% 줄어든 수치다. 순이익 감소에도 불구하고 3개년 평균 순이익 기준 배당성향은 50%를 기록했다.㈜GS가 별도 기준 순이익이 감소했음에도 고배당 기조를 유지한 것은 GS칼텍스의 업황 회복에 대한 자신감이 반영된 영향으로 풀이된다. 또한 ㈜GS는 GS에너지 배당을 제외하더라도 GS리테일, GS EPS 등으로부터 배당금이 유입되는 데다 GS강남타워 임대수익과 상표권 수익만으로도 연간 1600억원 안팎의 유동성이 확보되는 상황이다.GS 관계자는 "양호했던 정유부문과 달리 석유화학부문의 경우 공급 과잉 및 글로벌 수요 위축으로 제품 마진 약세가 지속되며 부진한 실적을 기록했고 SMP 하락에 따라 발전 자회사들의 수익성도 전반적으로 낮아졌다"며 "올해도 석유화학 및 발전 부문의 영업 환경이 어려울 것으로 예상되는 가운데, 정유부문이 이러한 부진을 얼마나 만회할 수 있을지가 실적의 관건이 될 것"이라고 전망했다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000079297', 'https://imgnews.pstatic.net/image/293/2026/02/11/0000079297_001_20260211130610203.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-11 11:06:09', 0, true, '2026-03-09 05:42:15.595041') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (514, '볼보·랜드로버 등 11개 차종 5만 5,178대 자발적 시정조치', '국토교통부가 볼보자동차코리아, GS글로벌 등에서 수입해 판매한 11개 차종 5만5천178대에서 제작결함이 발견돼 자발적 시정조치를 한다고 밝혔습니다.볼보 XC60 등 7개 차종 5만434대는 비상 자동 제동장치 센서의 문제로 의도치 않은 자동 긴급 제동이 발생할 가능성이 있어 지난 26일부터 시정조치를 진행하고 있습니다.GS글로벌이 수입한 BYD 1톤 전기트럭 T4K 1천692대는 차량 제어장치 소프트웨어 오류로 주차 단으로 변속 시 전자식 주차브레이크가 작동하지 않을 우려가 있어 오늘(29일)부터 시정조치를 진행합니다.랜드로버의 레인지로버 이보크 1천416대는 조수석 에어백 조립 불량으로 에어백이 펼쳐질 때 에어백이 손상돼 탑승자가 다칠 가능성이 있어 지난 23일부터 리콜이 진행 중입니다.포드 머스탱 1천489대는 차체 제어장치 수분 유입으로 차폭등, 후미등 및 번호등이 정상 작동되지 않는 안전기준 부적합으로, 익스페디션 147대는 후방 카메라가 내구성이 부족해 제대로 작동하지 않을 우려로 모두 지난 26일부터 시정조치를 진행하고 있습니다.차량의 리콜 대상 여부와 구체적인 결함 사항은 자동차리콜센터에서 차량번호 또는 차대번호를 입력하고 확인할 수 있습니다.※ ''당신의 제보가 뉴스가 됩니다''[카카오톡] YTN 검색해 채널 추가[전화] 02-398-8585[메일] social@ytn.co.kr', NULL, 'YTN', 'https://n.news.naver.com/mnews/article/052/0002307618', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2026-01-29 15:38:24', 0, true, '2026-03-09 05:42:15.595041') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (515, '서울 중림동 재개발 수주전 재점화… 포스코이앤씨 “2차 현장설명회 참여”', '서울역 통합개발 인접 핵심 입지…4월 24일 입찰 마감 앞두고 건설사 관심중림동 일대 재개발정비사업조합 전면서울 중구 중림동 일대 재개발 사업을 둘러싼 수주 경쟁이 다시 움직이고 있다. 건설경기 침체로 대형 건설사들이 정비사업 수주에 신중한 태도를 보이는 가운데, 포스코이앤씨가 1차에 이어 2차 현장설명회에도 참석하며 사업 참여 의지를 재확인했다.중림동 재개발 조합에 따르면 5일 오후 열린 2차 현장설명회에는 현대건설, 포스코이앤씨, 진흥기업, 남광토건, 극동건설 등 총 5개 건설사가 참석했다.포스코이앤씨는 지난해 12월 열린 1차 현장설명회에도 참석하며 사업 검토를 이어온 상태다.앞서 1차 현장설명회에는 포스코이앤씨를 비롯해 롯데건설, 대원건설, 한화건설, SK에코플랜트, GS건설, 남광토건, 대우건설 등 총 8개사가 참석했지만, 본입찰에서는 포스코이앤씨만 단독 응찰하면서 유찰된 바 있다.조합은 이후 입찰을 재공고하고 2차 절차를 진행하고 있으며, 이번 입찰 마감일은 오는 4월 24일이다.업계에서는 포스코이앤씨가 이 사업지를 단순한 재개발 수주를 넘어 전략적 거점 확보 차원에서 바라보고 있다는 분석이 나온다.중림동 일대는 국토교통부와 서울시가 공동 추진하는 서울역 통합개발 마스터플랜의 핵심 권역과 인접해 있다. 특히 서울역 서측 완충지대에 위치해 향후 철도 상부 공간 개발과 도심 재정비 사업이 본격화될 경우 상당한 시너지 효과가 기대되는 지역으로 평가된다.업계 관계자는 “단순한 주택사업 수주를 넘어 서울역 일대 개발 흐름의 교두보를 확보하려는 전략적 판단이 작용한 것으로 보인다”며 “향후 도심 랜드마크 조성 여부에 따라 브랜드 위상 강화에도 도움이 될 것”이라고 말했다.포스코이앤씨는 최근 정비사업 시장에서 무리한 확장보다 선별 수주 전략을 유지하면서도 사업성이 높은 핵심 입지에는 적극적으로 참여하는 기조를 이어가고 있다.포스코이앤씨 관계자는 “중림동 입지에 걸맞은 독보적인 랜드마크를 완성하겠다는 목표로 1차 입찰에 참여했다”며 “조합원들의 오랜 바람인 재개발 사업 성공을 위해 2차 입찰 준비에도 최선을 다할 것”이라고 밝혔다.한편 중림동 재개발 사업은 예정 공사비 약 3580억원 규모로, 3.3㎡당 공사비는 887만원 수준이다. 사업 계획에 따르면 지하 6층에서 지상 최고 25층 규모의 아파트 6개 동이 들어설 예정이며, 총 791가구가 공급된다. 이 가운데 191가구는 임대주택으로 계획돼 있다.', NULL, '조선비즈', 'https://n.news.naver.com/mnews/article/366/0001146149', 'https://imgnews.pstatic.net/image/366/2026/03/05/0001146149_001_20260305170911956.jpg?type=w800', 'NEWS_CONSTRUCT', NULL, '2026-03-05 17:09:11', 0, true, '2026-03-09 05:42:33.515078') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (516, '남광토건, 359억 광양 세풍일반산단 조성사업 수주 [공시pick]', '◆…조세일보 DB.남광토건이 359억원 규모 전라남도 광양시 광양읍 세풍리 일원에 들어서는 세풍일반산업단지 조성사업을 수주했다고 5일 공시했다.계약은 오는 2031년 2월 13일까지다.이번 계약금액은 전체 금액인 705억원의 남광토건 지분 51%를 반영한 금액이다.', NULL, '조세일보', 'https://n.news.naver.com/mnews/article/123/0002378891', 'https://imgnews.pstatic.net/image/123/2026/03/05/0002378891_001_20260305145111555.jpg?type=w800', 'NEWS_CONSTRUCT', NULL, '2026-03-05 14:51:11', 0, true, '2026-03-09 05:42:33.515078') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (517, '남광토건, 송파 가락7차 가로주택정비사업 수주', '남광토건이 서울 송파구 가락동 가락7차 현대아파트 가로주택정비사업 시공권을 확보하며 올해 정비사업 첫 수주를 올렸다.가락7차 사업은 기존 72가구를 113가구로 재건축하는 소규모 정비사업으로, 서울 지하철 5호선 개롱역 바로 앞 초역세권 입지가 강점이다. 조합은 남광토건을 우선협상대상자로 지정한 뒤 총회 의결을 거쳐 시공사로 최종 확정했다.남광토건은 창사 80주년을 앞두고 주택사업 강화에 나서고 있다. 극동건설과의 브랜드 통합·리뉴얼을 추진하며 서울·수도권 정비사업을 핵심 전략 시장으로 설정했다. 회사 측은 “서울 도심권 등 검증된 입지의 정비사업을 중심으로 추가 수주를 이어갈 계획”이라고 말했다.', NULL, '동아일보', 'https://n.news.naver.com/mnews/article/020/0003701408', 'https://imgnews.pstatic.net/image/020/2026/03/04/0003701408_001_20260304184815804.jpg?type=w800', 'NEWS_CONSTRUCT', NULL, '2026-03-04 18:48:15', 0, true, '2026-03-09 05:42:33.515078') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (518, '남광토건, 송파 ‘가락7차 현대아파트 가로주택사업’ 수주', '주택부문 강화 전략으로 서울 핵심지 시공권 확보에 박차가락7차 현대아파트 가로주택정비사업 조감도. 남광토건 제공주택부문 강화에 나선 남광토건이 서울 핵심 입지 내 정비사업 수주에 성공했다.남광토건은 2월 28일 열린 조합원 총회를 통해 서울 송파구 소재 가락7차 현대아파트 가로주택정비사업 시공사로 최종 선정됐다고 밝혔다.지난해부터 시공사 선정 절차에 돌입한 가락7차 현대아파트 가로주택정비사업은 1차, 2차 입찰을 거쳤다. 그 결과 남광토건이 단독으로 응찰해 남광토건을 우선협상대상자로 지정했고 이번에 총회 의결을 통해 최종 시공자로 선정했다.가락7차 가로주택정비사업은 기존 72세대 규모의 단지를 113세대 규모로 재건축하는 사업이다. 사업 규모는 작지만, 서울 지하철 5호선 개롱역 초역세권이라 입지 경쟁력이 높다. 또 송파구 내 학군·생활편의시설·의료·상업 인프라를 두루 누릴 수 있다.이 같은 소규모 핵심지 정비사업 수주는 향후 주택사업 강화 및 사업지 확대를 위한 교두보 역할을 할 것으로 기대된다.1947년 창립한 남광토건은 내년 창사 80주년을 앞두고 같은 해 창립한 극동건설과 브랜드 통합 및 리뉴얼을 준비하는 등 주택사업 부문을 강화하는 데 박차를 가하고 있다.남광토건은 마포로5구역 제2지구 재개발사업에도 참여하는 등 서울 도심권 내 입지가 좋은 사업지를 중심으로 수주 전략을 본격화하고 있다.남광토건 관계자는 “가락7차 수주는 올해 민간부문 마수걸이 수주로 창사 80주년을 맞아 새롭게 주택 분야를 강화하겠다는 회사의 의지를 담고 있다”며 “리뉴얼되는 ‘하우스토리’ 브랜드에 걸맞게 서울 도심권 등 검증된 입지의 정비사업에 적극 참여할 계획”이라고 밝혔다.', NULL, '한경비즈니스', 'https://n.news.naver.com/mnews/article/050/0000103076', 'https://imgnews.pstatic.net/image/050/2026/03/03/0000103076_001_20260303164410833.jpg?type=w800', 'NEWS_CONSTRUCT', NULL, '2026-03-03 16:44:10', 0, true, '2026-03-09 05:42:33.515078') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (519, '남광토건, 송파 가락 7차 현대아파트 가로주택정비 시공권 확보', '개롱역 인근 113가구 규모…올해 첫 정비사업 수주 성과가락 7차 현대아파트 가로주택정비사업 조감도 / 사진 = 남광토건남광토건이 지난달 28일 서울 송파구 가락동 소재 가락 7차 현대아파트 가로주택정비사업 시공사로 최종 확정됐습니다.가락 7차 가로주택정비사업 조합은 지난해부터 시공사 선정 절차를 진행해 왔는데, 1·2차 입찰 모두 남광토건이 단독 응찰했습니다.이에 조합은 남광토건을 우선협상대상자로 지정, 총회 의결을 거쳐 최종 시공사로 확정했습니다.가락 7차는 기존 72가구 규모의 단지를 113가구 규모로 재건축하는 가로주택정비사업입니다.서울 지하철 5호선 개롱역 바로 앞에 위치한 초역세권 단지라는 점과 송파구 내 학군·생활편의시설·의료·상업 인프라를 고루 누릴 수 있어 입지 경쟁력을 갖췄다는 평가를 받고 있습니다.남광토건 관계자는 "가락 7차 수주는 올해 민간부문 마수걸이 수주로 창사 80주년을 맞아 새롭게 주택 분야를 강화하겠다는 회사의 의지를 담고 있다"며 "리뉴얼되는 ''하우스토리'' 브랜드에 걸맞게 서울 도심권 등 검증된 입지의 정비사업에 적극 참여할 계획"이라고 밝혔습니다.', NULL, 'MBN', 'https://n.news.naver.com/mnews/article/057/0001937923', 'https://imgnews.pstatic.net/image/057/2026/03/03/0001937923_001_20260303154408327.jpg?type=w800', 'NEWS_CONSTRUCT', NULL, '2026-03-03 15:44:08', 0, true, '2026-03-09 05:42:33.515078') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (520, '남광토건, 송파 가락7차 가로주택정비 시공사 선정', '단독 응찰로 시공사 최종 확정서울 송파구 가락 7차 현대아파트 가로주택정비사업 조감도. 사진 제공=남광토건남광토건이 서울 송파구 가락동에 있는 가락 7차 현대아파트 가로주택정비사업의 시공사로 선정됐다고 3일 밝혔다.남광토건은 지난해 시공사 선정 절차가 시작된 뒤 1·2차 입찰 모두 단독으로 응찰했다. 조합은 남광토건을 우선협상대상자로 지정해 지난 달 28일 총회 의결을 거쳐 최종 시공사로 확정했다.가락 7차 현대아파트는 가로주택정비사업을 통해 기존 72세대 규모에서 113세대 규모 단지로 탈바꿈한다. 서울 지하철 5호선 개롱역이 가깝고 송파구 학군·의료·상업 인프라를 누릴 수 있어 실수요자들에게 인기를 끌 것으로 예상된다.건설 업계에서는 최근 대형 정비사업 위주 수주 경쟁이 심화하는 가운데 도심 내 중·소규모 정비사업을 통한 안정적 수주 전략이 다시 주목받고 있다. 특히 역세권 소형 정비사업은 사업 리스크를 상대적으로 낮추면서 브랜드 인지도를 확대할 수 있는 장점이 있다.남광토건은 내년 창사 80주년을 앞두고 마포로5구역 제2지구 재개발 사업에도 참여하는 등 서울 도심권 내 입지 경쟁력을 갖춘 사업지를 중심으로 추가 수주를 추진 중이다. 남광토건 관계자는 “가락 7차 현대아파트 가로주택정비사업 수주는 창사 80주년을 맞아 새롭게 주택 분야를 강화하겠다는 회사의 의지를 담고 있다”며 “리뉴얼되는 ‘하우스토리’ 브랜드에 걸맞게 서울 도심권 등 검증된 입지의 정비사업에 적극 참여할 계획”이라고 말했다.', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004595204', 'https://imgnews.pstatic.net/image/011/2026/03/03/0004595204_001_20260303233309728.png?type=w800', 'NEWS_CONSTRUCT', NULL, '2026-03-03 15:38:09', 0, true, '2026-03-09 05:42:33.515078') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (521, '남광토건, ‘가락7차 현대 가로주택정비사업’ 수주', '남광토건이 서울 송파구 가락동 가락7차 현대아파트 가로주택정비사업을 수주했다고 3일 밝혔다.남광토건은 지난달 28일 개최된 조합 총회에서 시공사로 확정됐다. 남광토건은 기존 72가구의 낡은 단지를 헐고 113가구로 다시 지을 예정이다. 서울 지하철 5호선 개롱역에 위치한 역세권 단지다.남광토건 관계자는 "가락7차 수주는 올해 민간부문 마수걸이 수주로 창사 80주년을 맞아 새롭게 주택 분야를 강화하겠다는 회사의 의지를 담고 있다"고 전했다.안다솜 기자 cotton@dt.co.kr가락7차 현대아파트 가로주택정비사업 조감도. [남광토건 제공]', NULL, '디지털타임스', 'https://n.news.naver.com/mnews/article/029/0003013477', 'https://imgnews.pstatic.net/image/029/2026/03/03/0003013477_001_20260303191015629.png?type=w800', 'NEWS_CONSTRUCT', NULL, '2026-03-03 14:00:02', 0, true, '2026-03-09 05:42:33.515078') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (522, '남광토건, 가락현대7차 가로주택 정비사업 시공권 확보', '가락현대7차 아파트 가로주택정비사업 조감도 /사진 제공=남광토건남광토건이 서울 송파구 가락현대7차 아파트의 가로주택정비사업 시공권을 확보했다.남광토건은 지난달 28일 개최된 가락현대7차 조합 총회에서 시공사로 선정됐다고 3일 밝혔다. 1·2차 입찰에 남광토건이 단독 응찰한 결과 조합은 남광토건을 우선협상대상자로 지정 후 총회를 거쳐 시공사로 확정했다.가락현대7차는 1991년 준공된 단지로 1개동 12층 전용면적 97.89㎡ 72가구로 구성됐다. 정비사업을 통해 2개동 최고 26층 113가구(분양 101가구, 임대 12가구)로 재건축한다.가락현대7차는 서울 지하철 5호선 개롱역이 도보 3분 거리에 있다.', NULL, '동행미디어 시대', 'https://n.news.naver.com/mnews/article/417/0001132229', 'https://imgnews.pstatic.net/image/417/2026/03/03/0001132229_001_20260303111015423.jpg?type=w800', 'NEWS_CONSTRUCT', NULL, '2026-03-03 11:09:26', 0, true, '2026-03-09 05:42:33.515078') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (523, '마포로5-2구역 재개발정비사업조합, 2월 25일 재공고… 남광토건·두산건설 재격돌', '1차 입찰 서류 미비로 유찰…  3월 6일 현장설명회, 4월 21일 입찰 마감조합 “관련 법령에 따라 투명·공정 절차로 정상 추진”서울 도심 알짜 정비사업지로 평가받는 마포로5구역 제2지구 도시정비형재개발사업이 시공사 선정 재공고를 내고 사업정상화에 속도를 내고 있다.지난 12일 시공사 선정 입찰에는 남광토건과 두산건설이 참여했으나 경쟁 요건을 충족하지 못하면서 무산된 바 있다. 이번 재공고가 사업 정상화의 분수령이 될 전망이다.정비업계에 따르면 마포로5-2구역 재개발정비사업 조합은 25일 시공자 선정을 위한 입찰 재공고를 공식 게재하고 관련 절차를 다시 개시했다. 앞서 진행된 1차 입찰에서는 남광토건과 두산건설이 참여했으나, 두산건설이 일부 입찰 서류를 제출하지 못해 무효 처리됐다. 이에 따라 남광토건 1개사 단독 입찰 구도로 정리됐고, 도시정비사업 시공사 선정 기준상 ‘2개사 이상 경쟁’ 요건을 충족하지 못해 최종 유찰이 확정됐다.조합은 유찰 직후 후속 절차에 착수했다. 2026년 2월 25일 자로 시공자 선정 재공고를 실시하고, 입찰 마감일은 2026년 4월 21일로 확정했다. 현장설명회는 3월 6일 개최될 예정이다. 조합 측은 “사업 지연을 최소화하고 공정한 경쟁을 통해 시공사를 선정하겠다는 원칙에 따라 절차를 다시 진행하게 됐다”는 입장이다.조합이 공고한 ‘시공자 선정 입찰공고’에 따르면, 이번 입찰은 「도시 및 주거환경정비법」과 국토교통부 고시 ‘정비사업 계약업무 처리기준’에 근거해 진행되며, 입찰보증금은 입찰금액의 40% 범위 내 400억원으로 명시됐다. 시공사 선정이 완료되면 대지면적 5,596.2㎡의 부지에 연면적 44,292.906㎡, 지하 6층~지상 28층 높이의 공동주택(192세대) 및 근린생활시설이 조성된다마포로5-2구역은 서울 서대문구 충정로 일대에 위치한 정비사업지로 교통 접근성과 생활 인프라 측면에서 안정적인 입지 여건을 갖췄다는 평가를 받는다. 인근 정비사업과 연계한 주거벨트 형성 가능성도 거론되며 중견 건설사 입장에서는 전략적 수주 대상으로 분류돼 왔다.서지영 기자', NULL, '일간스포츠', 'https://n.news.naver.com/mnews/article/241/0003496559', 'https://imgnews.pstatic.net/image/241/2026/02/27/0003496559_001_20260227095807226.png?type=w800', 'NEWS_CONSTRUCT', NULL, '2026-02-27 09:58:03', 0, true, '2026-03-09 05:42:33.515078') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (524, '마포로5-2구역 재개발 시공사 선정 재공고', '1차 입찰서류 미비로 유찰…4월 21일 입찰 마감마포로5구역 제2지구 재개발 조합은 지난 25일 시공자 선정을 위한 입찰 재공고 냈다. 사진은 마포로5구역 제2지구 위치도. /마포로5구역 제2지구 재개발 조합[더팩트｜황준익 기자] 서울 서대문구 마포로5구역 제2지구 도시정비형재개발사업이 시공사 선정 절차를 다시 밟는다.26일 정비업계에 따르면 마포로5구역 제2지구 재개발 조합은 지난 25일 시공자 선정을 위한 입찰 재공고를 냈다. 현장설명회는 다음달 6일 개최되며 입찰 마감일은 오는 4월 21일이다.앞서 진행된 1차 입찰에서는 남광토건과 두산건설이 참여했지만 두산건설이 일부 입찰서류를 제출하지 못해 무효 처리됐다. 남광토건 1개사 단독 입찰 구도로 정리됐고 경쟁 요건을 충족하지 못해 최종 유찰이 확정됐다.조합 측은 "사업 지연을 최소화하고 공정한 경쟁을 통해 시공사를 선정하겠다는 원칙에 따라 절차를 다시 진행하게 됐다"고 밝혔다.한편 마포로5구역 제2지구 재개발은 1937년 준공된 우리나라 최초의 아파트로 알려진 ''충정아파트''를 포함한 사업지다. 재개발을 통해 지하 6층~지상 28층 높이의 공동주택(192가구) 및 근린생활시설이 조성된다.발로 뛰는 더팩트는 24시간 여러분의 제보를 기다립니다.▶카카오톡: ''더팩트제보'' 검색▶이메일: jebo@tf.co.kr▶뉴스 홈페이지: http://talk.tf.co.kr/bbs/report/write', NULL, '더팩트', 'https://n.news.naver.com/mnews/article/629/0000475997', 'https://imgnews.pstatic.net/image/629/2026/02/26/202633381772071041_20260226110020134.png?type=w800', 'NEWS_CONSTRUCT', NULL, '2026-02-26 11:00:20', 0, true, '2026-03-09 05:42:33.515078') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (525, '에스엠씨지, 기관투자자 대상 안성 공장 탐방 진행', '(사진=에스엠씨지) *재판매 및 DB 금지[서울=뉴시스] 김경택 기자 = 화장품 유리용기 전문기업 에스엠씨지는 코스닥 상장 1주년을 맞아 지난 6일 부국증권 등 16개 기관투자자·애널리스트를 대상으로 안성 공장 탐방 및 기업설명회(IR)를 개최했다고 9일 밝혔다.회사 측에 따르면 기관투자자 일행은 최근 멀티 생산 가동에 들어간 라인을 직접 참관했다. 에스엠씨지는 지난해 말부터 기존 1개 라인에서 1개 제품만 생산하던 방식에서 2개 제품이 생산 가능하도록 설비투자를 진행해 최근 완료, 이달부터 1개 라인이 가동에 들어갔다. 다른 라인도 생산에 지장이 없도록 순차적으로 양산 시스템을 보강 구축해, 제품 교체에 따른 로스를 최소화한다는 계획이다.또 검수 공정의 육안 검사를 자동비전 검수시스템을 도입해 대체함으로써 검수 공정 인건비를 최대 60% 감축, 제품 품질 향상과 글로벌 경쟁력을 확보하고, 주요 고정비 항목인 전력비용도 FEMS(공장에너지관리시스템)를 상반기까지 도입해 에너지 비용을 5%까지 감축한다는 전략이다.최승호 에스엠씨지 대표는 기업설명회를 통해 "에스엠씨지는 잠정실적 공시 기준, 지난해 558억원의 매출액과 전년 대비 10.7% 증가한 49억원의 영업이익, 흑자전환한 7억원의 당기순이익을 달성했다"며 "올해에는 연내 신기술 양산·FEMS 구축으로 수익성을 극대화해 기업가치 제고에 최선의 노력을 경주할 것"이라고 말했다.', NULL, '뉴시스', 'https://n.news.naver.com/mnews/article/003/0013809198', 'https://imgnews.pstatic.net/image/003/2026/03/09/NISI20260309_0002078699_web_20260309093133_20260309093722576.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 09:36:39', 0, true, '2026-03-09 05:42:59.303121') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (526, '[마켓PRO] Today''s Pick : "''유가 100달러'' 소식에 이차전지주 오를 이유"', '사진=게티이미지뱅크※Today''s Pick은 매일 아침 여의도 애널리스트들이 발간한 종목분석 보고서 중 투자의견 및 목표주가가 변경된 종목을 위주로 한국경제 기자들이 핵심 내용을 간추려 전달합니다.주목할 만한 보고서에코프로비엠  -" 가정의 변화들이 나타나기 시작"목표주가: 20만원→27만원(상향)  / 현재주가 : 20만2500원투자의견 : 매수(유지) / 다올투자증권[체크 포인트]-원유 가격 상승, 유럽 정책 발표로 이차전지 업종 전반 반사수혜 기대.-최근의 유가 상승으로 전기차 시장 수요증가 가속화할 가능성.-지난주 EU 산업 가속화법 초안엔 배터리의 유럽내 생산 의무화도 포함.-완성차업체 입장에선 현지화된 양극재소재 수요 급증할 것.-에코프로비엠은 헝가리 생산 거점을 운영 중.-영업이익은 올 하반기부터 개선을 기대.오리온홀딩스-"검은 반도체를 손에 쥐다"목표주가 : 2만8000원→3만3000원(상향)   / 현재주가 :2만2850원투자의견 : 매수(유지) / IBK투자증권[체크 포인트]-앞서 수협과 총 600억원 출자해 JV 신설 합의.-수협의 마른김과 조미김 구매능력으로 효율적 구조.-오리온 해외판매망 활용해 유통망 확대도 수월할 전망.-김 수출 주요 지역은 미국, 중국, 러시아, 동남아 등.-오리온은 이들 지역에서 안정적 유통망 확보.-본격적 매출은 2027년부터 이뤄질 전망.-최근 주당배당금 1100원으로 공시. 주주환원책 확대 중.현대무벡스-" 불안한 정세에 딱 맞는 주식 "목표주가 : 미제시   / 현재주가 : 3만1800원투자의견 : 미제시 / 부국증권[체크 포인트]-작년 연간 실적 매출액 3939억원, 영업이익 182억원.-영업이익 전년동기 대비 25.9% 감소.-이익 감소는 중국고객사 기업회생 절차에 따라 대손충당금 선제 설정한 영향.-현재 유럽 탑티어 타이어 업체와 700억원 규모 막바지 비딩 조율 중.-안정적 캐시카우 역할하는 PSD 사업부 수주금액 확대 전망.-글로벌 자동화 투자 확대가 중장기 수주로 연결될 것.한국가스공사- "해외 자원개발 이익 증가는 긍정적"목표주가 : 5만원→ 5만원(유지)  / 현재주가 : 3만6900원투자의견 : 매수(유지) / NH투자증권[체크 포인트]-호르무즈 해협 봉쇄 장기화시 원유와 LNG 가격 상승.-해외 자원 개발 이익 증가에 긍정적.-모잠비크, 알래스카 등 주요 LNG 프로젝트 추가 투자 검토 중.-높은 수준의 미수금 회수 위해 도시가스 요금 인상 필요한 상황.롯데관광개발-"이제 본 게임 "목표주가: 3만원 (신규)   / 현재 주가 : 1만9090원투자의견 : 매수(신규) / 흥국증권[체크 포인트]-올해는 기존 VIP 중심 성장세에 탈일본 수요 동반 작용 전망.-중일 갈등으로 중국인 관광객 유입 확대되는 구간.-카지노 드롭 증가와 함께 부대매출 동반 개성 기대.-연내 리파이낸싱을 통한 순이익 추가 개선도 예상.-현재 객실 확대와 운영테이블 최적화로 모객과 체류 올리는 램프업 구간.', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005259667', 'https://imgnews.pstatic.net/image/015/2026/03/09/0005259667_001_20260309084815283.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 08:43:11', 0, true, '2026-03-09 05:42:59.303121') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (527, '우리투자증권, 133조원 투자자문·일임업 진출', '투자자문·투자일임업 등록 완료지난해 투자매매업 인가를 마친 우리투자증권이 133조원 규모의 투자자문업·투자일임업 시장에 진출한다.5일 금융당국에 따르면 우리투자증권은 지난 2월25일 투자자문업(5-1-1)과 투자일임업(6-1-1) 등록을 완료했다.우리투자증권 CI. [사진=우리투자증권]우리투자증권은 지난해까지 투자매매업과 투자중개업, 신탁업 인가만 취득한 상태였다. 투자중개업 인가 취득에도 불구하고 MTS 등 인프라 구축이 늦어지면서 실제 수탁수수료 수입은 지난해 8억2339억원에 그쳤다. 신탁보수도 전무했다. 수수료수익보다는 증권평가 및 처분이익이 578억원으로 수수료 수입이 미미한 상태다.이에 수익원 다양화 차원에서 증권회사의 고유 업무라고 할 수 있는 투자일임업에 진출한 것으로 평가된다. 2025년말 기준 국내 자문사·증권사·선물사의 투자일임 시장 규모는 약 116조원, 투자자문업 시장 규모는 17조원으로 투자자문업·일임업 전체 시장 규모는 133조원 규모다. 전체 투자자문업·투자일임업 규모는 807조원에 이르나, 대부분이 자산운용사의 투자일임 시장이다.국내 증권사 중에서 투자자문업과 투자일임업 등록이 없는 곳은 KR투자증권(투자일임 미등록), 넥스트증권, 부국증권, 유화증권(투자자문업 미등록), 카카오페이증권, 코리아에셋투자증권(투자일임업 미등록), 토스증권, 한국스탠다드차타드증권, 한양증권(투자자문업 미등록), 흥국증권 등에 불과하다.2024년 우리종합금융과 한국포스증권의 합병으로 출범한 우리투자증권은 작년 3월 투자매매업 인가를 받고 모바일트레이딩시스템(MTS) 출시 등 2분기부터 투자은행(IB)과 리테일 부문 영업을 개시했다.', NULL, '아이뉴스24', 'https://n.news.naver.com/mnews/article/031/0001010540', 'https://imgnews.pstatic.net/image/031/2026/03/05/0001010540_001_20260305110207464.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-05 11:02:07', 0, true, '2026-03-09 05:42:59.303121') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (528, '코스피 반등에 증권株 불기둥...두자릿수 상승 [이런국장 저런주식]', '전장 대비 SK증권 20.0%·미래에셋증권 19.82% ↑주요 증권주 일제히 올라...코스피·코스닥 반등 영향코스피가 장 초반 급등하며 5700선을 터치한 가운데 5일 서울 중구 하나은행 본점 딜링룸에서 딜러가 업무를 보고 있다. 연합뉴스이란 사태로 급락했던 증시가 반등하면서 5일 오전 국내 증시에서 SK증권을 비롯한 증권 관련주가 일제히 강세를 나타내고 있다.이날 오전 10시 25분 현재 SK증권의 주가는 전장 대비 20.0% 오른 주당 1782원에 거래되고 있다. 미래에셋증권과 상상인증권 역시 각각 19.82%, 17.40% 치솟았다. 한화투자증권(17.17%), 키움증권(17.05%), NH투자증권(13.19%), 부국증권(12.81%), 한양증권(12.77%)등 주요 증권주들도 오름세를 보이고 있다.이는 미국의 이란 공습 이후 이틀 연속 급락했던 증시가 이날 반등한 영향으로 풀이된다. 이날 코스피·코스닥 모두 장이 열리자 마자 매수 사이드카가 발동됐다. 삼성전자와 SK하이닉스를 비롯한 시가총액 상위 종목 대부분이 강세를 나타내고 있다.최근 증시 급락과 반등으로 인해 거래대금이 늘어난 것 역시 증권주 매수 배경이 됐다. 유가증권시장, 코스닥 시장, 코넥스 시장의 총 거래대금은 지난 3일 69조 6990억 원, 4일 79조 4720억 원으로 집계됐다. 이는 올해 일평균 거래대금(45조 3500억 원)을 훨씬 상회하는 수준이다.시장에서는 주가지수 급등락에 따른 매매 회전율 증가가 증권사 브로커리지(위탁매매) 수익 개선 기대를 자극한 것으로 보고 있다. 변동성 장세가 이어질 경우 단기적으로 거래 활성화에 따른 실적 모멘텀이 부각될 가능성도 제기된다.삼전 18만 갈 때 이건 160% 터졌다? 개미들만 몰랐던 ‘진짜’ 대장 증권주', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004595983', 'https://imgnews.pstatic.net/image/011/2026/03/05/0004595983_001_20260305132709672.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-05 10:36:13', 0, true, '2026-03-09 05:42:59.303121') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (529, '증시 급반등에 증권주 일제히 폭등…SK증권 25%↑[특징주]', '[이데일리 김윤정 기자] 증권주가 장 초반 두 자릿수 강세다. 개장 직후 코스피·코스닥 동시 매수 사이드카가 발동하는 등 이틀 연속 급락했던 증시가 반등하면서 동반 상승한 것으로 풀이된다.5일 엠피닥터에 따르면, 이날 오전 9시26분 기준 SK증권(001510)은 전 거래일 대비 380원(25.59%) 오른 1865원에 거래됐다.증권주 대부분이 두 자릿수 강세를 보이고 있다. 상상인증권(001290)은 전 거래일 대비 240원(23.60%) 오른 1257원에, 미래에셋증권(006800)은 전 거래일 대비 1만700원(20.71%) 오른 6만8300원을 기록했다.이 밖에도 한화투자증권(003530) (17.81%), 키움증권(039490) (15.30%), 부국증권(001270) (14.87%), 유진투자증권(001200) (13.73%), NH투자증권(005940) (13.72%), 신영증권(001720) (13.49%), 대신증권(003540) (12.76%), 현대차증권(001500) (12.55%), DB증권(016610) (11.50%) 등 강세다.삼성증권(016360) (11.48%), 유안타증권(003470) (11.19%), 교보증권(030610) (11.12%), 다올투자증권(030210) (7.80%), 유화증권(003460) (6.20%) 등도 상승했다.미국·이스라엘의 이란 공습에 최근 이틀 연속 급락했던 증시가 이날 반등하면서 증권주도 동반 강세를 보이는 것으로 풀이된다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006228836', 'https://imgnews.pstatic.net/image/018/2026/03/05/0006228836_001_20260305094614237.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-05 09:39:07', 0, true, '2026-03-09 05:42:59.303121') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (530, '급등락 오가는 증시에 매매량 급증…증권주 일제히 불기둥', '특징주머니투데이 특징주 그래픽 이미지5일 개장 직후 코스피·코스닥에서 동시에 매수 사이드카가 발동되면서 증권주가 큰 폭으로 상승하고 있다.이날 오전 9시10분 현재 코스피 시장에서 SK증권은 전 거래일 대비 325원(21.89%) 오른 1810원에 거래되고 있다.SK증권뿐만 아니라 대부분 증권주가 두 자릿수 강세다. 상상인증권(18.29%), 미래에셋증권(15.58%), 키움증권(15.17%), 한화투자증권(14.15%), 부국증권(13.84%), NH투자증권(12.15%), 한국금융지주(11.38%), 유진투자증권(11.20%), 대신증권(10.82%), 삼성증권(10.57%), 신영증권(10.55%), 현대차증권(10.02%), 교보증권(10.00%) 등이다.DB증권(9.84%), 케이프투자증권(9.13%), 유안타증권(8.54%), 한양증권(8.51%), LS증권(8.36%), 유화증권(6.20%) 등도 강세다.증권주 강세는 미국-이란 충돌로 이틀 연속 급락했던 증시가 이날 반등하면서 동반 강세를 보이는 것으로 풀이된다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005325576', 'https://imgnews.pstatic.net/image/008/2026/03/05/0005325576_001_20260305091613755.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-05 09:15:35', 0, true, '2026-03-09 05:42:59.303121') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (531, '''코스피 매도 사이드카''... 증권주 우수수 급락', '머니투데이 특징주 그래픽 이미지4일 개장 직후 코스피 매도 사이드카가 발동되는 등 증시가 연이틀 급락하고 있는 가운데 증권주들도 큰 폭으로 하락하고 있다.이날 오전 9시 8분 현재 증권주들은 일제히 급락세를 보이고 있다. 부국증권이 13.4% 하락하며 두자릿수 하락세를 보이고 있고 SK증권은 9.7% 떨어지고 있다. 대신증권, 신영증권, NH투자증권은 7%대 낙폭을 나타내고 있고 한국금융지주, 삼성증권도 각각 6.6%, 6.5% 하락 중이다. 미래에셋증권은 4.9% 떨어지고 있다.최근 코스피 랠리 속 급등했던 증권주들이 미국-이란 사태로 증시가 급락세를 보이면서 동반 약세를 보이는 것으로 보인다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005324941', 'https://imgnews.pstatic.net/image/008/2026/03/04/0005324941_001_20260304091414384.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-04 09:13:25', 0, true, '2026-03-09 05:42:59.303121') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (532, '''이란 사태'' 코스피 불장에 찬물...증권주도 와르르', '[특징주]국내 증권주가 3일 장 초반 약세다. 연휴간 발발한 중동사태 여파에 코스피가 하락 출발한 여파로 풀이된다.이날 오전 9시21분 한국거래소(KRX)에서 상상인증권은 전 거래일 대비 143원(9.53%) 내린 1357원, SK증권은 153원(7.20%) 내린 1972원에 거래됐다.보통주 기준으로 부국증권은 6000원(6.64%) 내린 8만4300원, 한화투자증권은 520원(6.24%) 내린 7820원에 거래 중이다.신영증권·현대차증권·코리아에셋투자증권은 5%대, 키움증권·유진투자증권·대신증권·한양증권·교보증권·DB증권·LS증권·한국금융지주·미래에셋증권은 4%대 낙폭을 보인다.다올투자증권·유안타증권·NH투자증권·삼성증권·유화증권은 3%대 약세다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005324305', 'https://imgnews.pstatic.net/image/008/2026/03/03/0005324305_001_20260303094912836.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-03 09:28:55', 0, true, '2026-03-09 05:42:59.303121') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (533, '수주본능 깨어난 현대무벡스, 실적 개선 가시화', 'AGV 등 물류 로봇 고도화 성과작년 3분기 기준 수주잔고 3632억피지컬 AI 등 첨단기술과 융합근로자 안전·생산성 제고 모색현대무벡스의 수주 본능이 깨어났다. 올해 AI(인공지능)·로봇 분야에서 성과가 유력시된다. 무인이송로봇(AGV), 갠트리로봇 등 자체 개발한 물류 로봇에 AI 솔루션을 접목해 현장 효율성을 개선했다. 현정은 현대그룹 회장이 그룹의 IT(정보기술) 서비스를 맡은 현대U&I와 현대무벡스를 합병한 것이 ''신의 한 수''가 됐다는 평가다.1일 업계에 따르면 현대무벡스의 총 수주잔고는 지난해 3·4분기 기준 3632억원이다. 2022년 1890억원 이후 2023년 3755억원, 2024년 3927억원을 기록하며 3000억원대 중후반 수준을 유지하고 있다.김성환 부국증권 연구원은 "최근 대부분의 수주가 AGV 중심으로 이뤄지고 있으며, AI가 적용된 피킹 로봇의 경우 평택 소재 국내 대기업 제조공장에 진입할 것으로 보인다"고 밝혔다.현대무벡스는 지난 2019년 청라 R&D센터를 구축해 단기간 내 AGV·AMR·갠트리로봇 등 수십 종의 물류 로봇 개발에 성공했다. 현대무벡스는 AS/RS(자동입출고시스템), 즉 선반-스태커크레인-이송-컨베이어-소터로 이어지는 자동창고 구축 사업을 주력으로 하고 있다. 중간 과정에서는 고객 요구에 따라 AGV/AMR(무인이송로봇)로 대체해 토털 엔지니어링(패키지) 방식으로 제공한다.''피지컬 AI'' 등 첨단 기술을 자동화 설비와 융합해 근로자의 안전과 생산성을 동시에 높이는 방안도 연구 중이다.최승환 신한투자증권 연구원은 "현대무벡스는 그동안 진출하지 않았던 클린룸 영역에 필요한 제품 개발이 거의 완료돼 국내 반도체 클러스터향 프로젝트 진출을 추진하고 있다"고 설명했다.''강점'' 타이어 포함 가전·뷰티 CDC까지…고객사 해외 확장 유력북미 시장은 전기차 캐즘(수요 정체) 속에서도 ESS(에너지저장장치)와 배터리 소재 부문 수요는 증가할 것이라는 전망이 나오고 있다. 현대무벡스가 강점을 가진 타이어 산업 역시 고인치·프리미엄 전략에 따라 올해 주요 기업들의 글로벌 생산기지 확장이 예상된다. 국내 타이어 3사뿐 아니라 해외 기업들도 국내외 생산 네트워크 재편을 서두르는 모양새다.지난해 연속 수주한 가전과 뷰티 산업의 CDC(중앙물류센터) 자동화 사업도 국내 고객사의 해외 확장 가능성이 높은 것으로 보인다.하나증권은 현대무벡스의 올해 매출을 5098억원, 영업이익을 425억원으로, 부국증권은 매출 4963억원, 영업이익 385억원으로 각각 전망했다. 올해부터 해외 수주를 중심으로 실적 개선세가 가시화될 것으로 내다봤다.업계 관계자는 "현대무벡스는 캡티브(계열사 간 거래) 물량 비중이 거의 없어 자생력이 상당히 강한 기업"이라며 "토털 엔지니어링의 강점을 청라 R&D센터의 개발 역량이 잘 뒷받침한다면 대표적인 글로벌 테크기업의 면모를 갖출 것"이라고 평가했다.', NULL, '파이낸셜뉴스', 'https://n.news.naver.com/mnews/article/014/0005484547', 'https://imgnews.pstatic.net/image/014/2026/03/01/0005484547_001_20260301185215625.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-01 18:28:16', 0, true, '2026-03-09 05:42:59.303121') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (534, '증권 거래대금 62조 시대...대형사만 웃었다', '[증권사 양극화]①증권업계 ‘빅5’ 작년에만 당기순이익 6.7조원중소형사는 지난해 4분기 순이익 감소 기록코스피 5000 돌파 영향에 올해도 순익 확대서울 여의도 증권가. [사진 연합뉴스][이코노미스트 이용우 기자] 코스피가 5000선을 돌파한 이후 국내 증시 거래대금이 급증하면서 증권업계 전반에 훈풍이 불고 있다. 하루 거래대금이 62조원을 웃도는 날이 이어지면서 브로커리지(위탁매매) 수익이 빠르게 늘어나고 있다. 다만 ‘거래대금 62조 시대’라는 외형적 호황의 과실은 대형 증권사에 집중되는 모습이다. 리테일 고객 기반과 시장 점유율에서 우위를 점한 대형사들은 사상 최대 실적을 기록하는 반면, 일부 중소형사는 호황의 온기를 체감하지 못하고 있다. 증시 호황이 ‘증권사 양극화’를 만들고 있다는 분석이다.‘빅5’ 순익 급증…10대 증권사 이익의 75% 흡수금융투자업계에 따르면 지난해 주요 10개 증권사의 연결 기준 당기순이익은 9조112억원으로 전년 대비 43.1% 증가해 역대 최대 수준을 기록했다. 하지만 이번 호실적은 한국투자·미래에셋·키움·NH투자·삼성증권 등 ‘빅5’의 수익 확대 영향이 컸다.한국투자증권은 업계 최초로 연간 순이익 2조원을 돌파하며 ‘2조 클럽’에 이름을 올렸다. 한국투자증권의 지난해 순이익은 전년 동기 대비 79.9% 증가한 2조135억원을 기록했다. 이어 미래에셋증권이 순이익 1조5936억원(전년 동기 대비 72.2% 증가)을 기록했고 ▲키움증권 1조1149억원(33.5%) ▲NH투자증권 1조315억원(50.2%) ▲삼성증권 1조84억원(12.2%) 순으로 순이익 규모가 컸다.미래에셋증권은 2021년 이후 4년 만에 순이익 1조원을 넘겼고, 키움·NH·삼성증권은 처음으로 ‘1조 클럽’을 달성했다. 이에 ‘빅5’ 증권사의 지난해 순이익은 총 6조7619억원으로 1년 전보다 51.4% 증가했다. 5대 증권사가 지난해 달성한 순이익은 사실상 10대 증권사 전체의 75%를 차지하며, 상위권 실적 쏠림 현상이 심화됐다. KB증권도 ‘1조 클럽’에 근접하고 있다. KB증권의 지난해 순이익은 15.1% 확대된 6739억원으로 연간 최대 실적을 기록했다.대형 증권사의 수익 확대는 지난해부터 나타난 증시 활황과 거래대금 증가 영향이 컸다. 코스피는 지난해 6월 20일 종가 기준 3021.84를 기록하며 3000선을 넘었고, 4개월 만인 10월 27일 4042.83으로 4000선을 뛰어넘었다. 지난 한 해 코스피 증가율은 75.6%로 주요 20개국(G20)과 경제협력개발기구(OECD) 회원국 가운데 1위를 기록했다. 이로 인해 대형 증권사들은 거래량 증가에 따른 브로커리지 수익 확대와 기업금융(IB)·자산관리(WM) 부문의 안정적 수익이 더해지며 역대 최대 실적을 낼 수 있었다.반면 중소형사의 상황은 다소 다른 것으로 나타났다. 지난해 연간 기준으로는 대체로 양호한 실적을 거뒀지만, 4분기만 놓고 보면 적자로 돌아선 곳이 적지 않았기 때문이다. 금융정보업체 에프앤가이드에 따르면 LS증권은 지난해 4분기 141억원의 당기순손실을 기록한 것으로 추정된다. BNK증권과 SK증권, 부국증권 역시 같은 기간 각각 62억원, 17억원, 11억원의 순손실을 낸 것으로 파악됐다. 4분기에 흑자를 낸 중소형 증권사들 역시 순이익이 전분기보다 절반가량 감소했다. 교보증권의 경우 지난해 3분기 308억원의 순이익을 기록했지만 4분기에는 173억원의 순이익을 내며 감소 폭이 큰 것으로 나타났다.한 중견 증권사 관계자는 “거래대금이 늘었어도 시장 점유율이 제한적인 탓에 중소형 증권사의 경우 브로커리지 수익 증가 효과가 크지 않다”며 “일부는 부동산 프로젝트파이낸싱(PF) 관련 충당금 부담과 평가손실을 4분기에 반영하며 실적이 크게 증가하지 못한 것”이라고 설명했다.시장 점유율 따라 브로커리지 수익 격차 확대증권업계의 양극화 현상은 올해 더 심화할 것으로 예상된다. 코스피 5000 돌파 이후 개인 투자자들의 매수세가 거세지며 거래 회전율도 높아지고 있는데, 리테일 고객 기반이 두텁고 모바일트레이딩시스템(MTS) 경쟁력이 높은 대형사들이 직접적인 수혜를 입는 구조이기 때문이다. 증권업계에 따르면 지난달 일평균 거래대금은 62조3000억원을 기록했다. 전월(33조원)보다 89.1% 증가했고, 전년 같은 달과 비교하면 339.1% 급등했다.증권사의 핵심 수익원은 투자자가 주식을 사고팔 때 발생하는 매매 수수료인 만큼, 연초 이후 외국인·기관·개인의 대규모 매매가 이어지며 증권사 수익이 크게 늘어날 것으로 예상된다. 다만 점유율 상위권 증권사들이 거래대금 증가 효과를 상당 부분 흡수할 것으로 보여 실적 개선 폭도 더 커질 전망이다.강승건 KB증권 연구원은 “거래대금 증가는 증권사의 이익과 자기자본이익률(ROE)에 지대한 영향을 준다”며 “개인 투자자 증가는 브로커리지 수수료뿐 아니라 신용공여 이자수익 확대와도 연계된다는 점에서 실질적인 효과는 더 크다”고 분석했다.강 연구원의 분석에 따르면 올해 일평균 거래대금이 45조6000억원을 기록할 경우, 증권사 점유율과 수수료율을 고려한 브로커리지 수수료 수익 증가 효과는 ▲미래에셋증권 4180억원 ▲NH투자증권 3909억원 ▲삼성증권 3773억원 ▲키움증권 3198억원 ▲한국금융지주 2637억원 순으로 예상된다.한 중소형 증권사 관계자는 “지금처럼 거래대금이 급증해도 점유율을 확보하지 못한 상황이라 곧바로 실적 개선으로 이어지기 어렵다”며 “앞으로는 일시적 격차가 아니라 구조적 양극화가 우려되는 상황”이라고 말했다.', NULL, '이코노미스트', 'https://n.news.naver.com/mnews/article/243/0000093755', 'https://imgnews.pstatic.net/image/243/2026/02/28/0000093755_001_20260228080111276.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-02-28 08:01:11', 0, true, '2026-03-09 05:42:59.303121') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (535, '10% 널뛰는 장세에 사상 최대 ‘빚투’… 대규모 반대매매 공포 확산', '7% 급락→ 12% 급락  →9% 급등→7% 급락증시 급락하면 반대매매(강제 청산) 가능성 증가미국과 이스라엘의 이란 침공 여파로 국내 증시 변동성이 극단적으로 커졌다. 하루 사이 지수가 10% 가까이 오르내리는 장세가 이어지는 가운데, 증권사에서 돈을 빌려 투자하는 이른바 ‘빚투’ 규모는 사상 최대치를 연일 경신하고 있다. 시장에서는 증시 급등락 국면에서 레버리지 투자 확대가 대규모 반대매매로 이어지며 국내 증시의 ‘뇌관’으로 작동할 수 있다는 우려가 나온다.일러스트=챗GPT 달리3이날 오전 2시 23분 기준 코스피 지수는 전 거래일 대비 393.78(7.05%) 내린 5192.41에 거래되고 있다. 오전 10시 31분쯤 8% 넘게 폭락하면서 매매를 20분간 멈추는 ‘서킷 브레이커’도 발동했다. 같은 시간 코스닥 지수도 5% 넘게 빠지며 1000선에서 거래되고 있다.중동발(發) 지정학적 리스크가 확대되면서 코스피 변동성은 극단적으로 커진 모습이다. 미국과 이스라엘의 이란 공격 이후 첫 거래일이었던 3일 코스피는 7% 하락했고, 다음 날인 4일에는 12% 폭락하며 역대 최대 하락률을 기록했다. 이어 5일에는 9% 넘게 반등했고 6일에는 보합권에서 마감했다. 이후 다시 장중 8% 급락이 나타나는 등 하루 사이 큰 폭의 등락이 반복되고 있다.이는 평상시 코스피 변동성과 비교하면 매우 이례적인 수준이다. 코스피의 지난해 평균 일간 등락률이 약 0.24% 수준이었던 점을 고려하면 최근의 두 자릿수 변동은 통상적인 변동폭 대비 크다.그래픽=손민균이처럼 시장 변동성이 확대되는 가운데 증권사에서 돈을 빌려 투자하는 신용거래 잔고가 급증하고 있다. 지난해 말부터 시작된 증시 급등의 수혜를 충분히 누리지 못했다고 판단한 투자자들이 ‘포모(FOMO·기회 상실의 공포)’ 심리에 따라 레버리지 투자를 확대하고 있다는 분석이다.금융투자협회에 따르면, 지난 5일 신용거래융자 규모는 33조6945억원으로 또다시 사상 최고치를 경신했다. 유가증권 22조8152억원, 코스닥 10조8792억원 수준이다. 이는 올해 1월 2일(27조4207억원) 대비 22.8%, 지난해 1월 2일(15조6823억원) 대비 115% 증가한 수치다.‘초단기 빚투’ 성격의 위탁매매 미수금도 증가 추세다. 위탁매매 미수금은 지난 5일 기준 2조4879억원으로 역대 최고치다. 위탁매매 미수금은 투자자가 결제일에 대금을 납부하는 조건으로 먼저 주식을 매수하는 거래다. 국내 주식 결제일이 매수 후 2거래일(T+2)이라는 점을 이용해 주가 상승을 예상하고 미수로 매수한 뒤 결제일 전에 매도해 차익을 실현하는 방식이다.문제는 증시 급등락 국면에서 이러한 레버리지 투자가 반대매매(강제 청산)로 이어질 수 있다는 점이다. 신용융자 거래의 경우 계좌 담보 비율이 140% 아래로 떨어지면 추가 증거금 납입을 요구받고, 이를 채우지 못하면 다음 거래일 장 시작과 동시에 보유 주식이 강제 매도된다. 위탁 매매 미수금 역시 결제일까지 대금을 납부하지 못하면 다음 날(T+3) 반대 매매 절차가 진행된다.전문가들은 급격하게 늘어난 ‘빚투’가 한국 증시의 뇌관으로 작동할 위험이 있다고 분석한다. 염동찬 한국투자증권 연구원은 “사상 최대 수준까지 상승한 신용 잔고는 시차를 두고 증시에 부담 요인으로 작용할 수 있다”고 설명했다. 또 반대 매매 물량이 쏟아질 경우 ‘반대 매매→지수 하락→추가 반대 매매’로 이어지는 악순환이 발생할 수 있다는 점도 부담이다.다만 시장 일각에서는 풍부한 대기 자금이 충격을 일부 흡수할 수 있다는 분석도 나온다. 개인 투자자의 투자 대기 자금인 투자자 예탁금 역시 빠르게 늘고 있기 때문이다. 금융투자협회에 따르면 지난 4일 투자자 예탁금은 130조원을 기록하며 역대 최고치를 경신했다.김현수 상상인증권 연구원은 “증시 레버리지 규모가 역대 최대 수준인 것은 사실”이라면서도 “예탁금 증가 속도가 더 빠른 만큼 신용이 시장 과열을 촉발하기보다는 상승 국면에서 변동성을 확대하는 보조적 역할에 그칠 가능성도 있다”고 분석했다.', NULL, '조선비즈', 'https://n.news.naver.com/mnews/article/366/0001146927', 'https://imgnews.pstatic.net/image/366/2026/03/09/0001146927_001_20260309142813443.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 14:28:13', 0, true, '2026-03-09 05:43:22.327051') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (536, '이란 확전에 오일쇼크 ''비상''…롤러코스터 탄 증시, 변동성 더 확대될까', 'WTI 90달러 돌파…주간 상승률 1983년 이후 최대시장 변동성 확대 우려…9일 코스피 7% 급락·사이드카 발동장기전 시 코스피 30% 이상 하락·유가 150달러 관측지수 5000대서 대기 자금 유입 기대감…분할 매수 대응 조언연합뉴스미국과 이란 간 전쟁이 지속되면서 글로벌 에너지 시장에 ''오일쇼크'' 공포가 확산하고 있다. 호르무즈 해협이 사실상 봉쇄되며 국제 유가가 배럴당 90달러를 돌파한 가운데 증시 변동성에 대한 우려가 커지고 있다. 증권가에선 전쟁 장기화 시 유가 150달러 돌파, 코스피 30% 급락 가능성까지 거론된다.9일 금융투자업계에 따르면 지난 6일(현지시각) 브렌트유 선물 가격은 배럴당 92.69달러에 거래를 마쳤고 서부텍사스산 원유(WTI) 선물(4월 인도분)도 배럴당 90.90달러에 마감했다. 브렌트유가 종가 기준 90달러를 넘어선 것은 2023년 9월 이후 처음이다.WTI 선물은 주간 36% 올라 배럴당 90.90달러에 마감했다. 이는 1983년 이후 가장 빠른 속도의 상승이다. 브렌트유 역시 주간 28% 올라 배럴당 92.69달러를 기록했다.유가 급등은 이란 전쟁 확대에 따른 원유 공급 차질 우려가 커져서다. 이란이 사실상 호르무즈 해협을 봉쇄하면서 페르시아만 지역의 원유 수출이 큰 영향을 받고 있다.월스트리트저널(WSJ)과 파이낸셜타임스(FT) 등에 따르면 쿠웨이트 국영 석유회사 KPC는 호르무즈 해협 통항 위협과 해상 운송 차질을 이유로 원유 생산과 정제 처리량을 줄이기로 하고 계약상 의무 이행을 유예할 수 있는 ''불가항력'' 조항을 발동했다. 쿠웨이트 감산 규모는 초기 하루 약 10만 배럴 수준에서 시작됐으며 상황에 따라 확대될 가능성이 있는 것으로 알려졌다.이라크는 이미 생산량을 절반 수준으로 줄였고 사우디아라비아와 아랍에미리트(UAE) 역시 저장 여력이 급감하고 있다. 이와 관련해 카타르 사드 알카비 에너지 장관은 "중동 전쟁이 계속되면 페르시아만 국가들이 며칠 안에 에너지 생산을 중단할 수도 있다"고 경고했다. 그는 이 상황을 가정해 유가가 배럴당 150달러까지 치솟을 수 있다고 밝혔다.호르무즈 해협을 통과하는 선박 운항은 사실상 멈췄다. 약 1000척의 선박이 걸프 해역과 인근 바다에 묶여 있으며 이들의 누적 가치가 약 250억달러에 달한 것으로 알려졌다.◆유가·환율 발목 잡힌 증시, 변동성 주의보…장기전 시 30% 폭락 전망도이란 사태로 국내 증시 변동성은 높아진 상황이다.개별 종목의 주가가 급변하면 2분간 단일가 매매로 전환하는 장치인 변동성완화장치(VI)는 지난 3~6일 유가증권시장에서만 3314번 발동했다. 하루 평균 828.5건의 VI가 발동된 셈인데 올해 1월과 2월 유가증권시장 VI 발동 횟수가 하루 평균 각각 134.3건과 183.4건이었던 점을 고려하면 급증세가 뚜렷하다.지난주 국내 증시에서는 VI와 함께 프로그램매수호가 일시효력정지(사이드카)와 서킷브레이커(주가 급등락시 20분간 주식 매매 중단)도 발동됐다. 코스피 매수 사이드카는 1회, 매도 사이드카는 2회 발동했고 코스닥에서는 매수와 매도 사이드카가 각각 2회와 1회 발동했다. 매도세가 급격하게 커진 지난 4일 두 시장에서 1단계 서킷브레이커가 1회 발동됐다.9일 한국거래소에 따르면 이날 오전 10시24분 현재 코스피는 전 거래일 대비 7.79%, 코스닥은 6.27% 급락 중이다. 이란 사태가 장기화할 조짐을 보인 충격으로 코스피 이날 장 초반 사이드카가 발동됐다.문제는 시장의 불확실성이 여전하다는 점이다. 미국과 이란의 갈등이 중동 지역으로 전반으로 확산하며 장기전으로 흐를 수 있다는 우려가 나온다. 골드만삭스는 분쟁이 장기화될 경우 국제 유가가 배럴당 100달러를 넘어설 가능성이 있다고 전망했다.우리나라는 원유 수입 의존도가 높아 국제유가 상승은 국내 증시를 위축시키는 주요 요인이다. 특히 수입 원유의 70% 이상을 중동에 의존해 타격이 불가피하다. 대신증권은 전쟁이 1년 이상 중장기로 접어들 경우 유가뿐 아니라 곡물 가격 상승 압력 확대로 코스피가 30% 이상 하락할 것이라고 전망했다.노동길 신한투자증권 연구원은 "국내 주식시장 변동성의 본질은 유가에서 출발한다"며 "유가 상승이 국제수지를 약화시켜 환율 약세를 유도하고 외국인 매도를 순환적으로 키우는 움직임"이라고 밝혔다.노 연구원은 "유가 변동성이 리스크 프리미엄을 자극해 성장주에 영향을 줄 수 있다"며 "변동성에 대한 대비가 필요하다"고 짚었다.특히 호르무즈 해협 봉쇄로 국제 유가가 치솟으면서 환율 약세를 유발해 외국인 매도를 키울 수 있다는 우려도 나온다.이달 들어 지난 6일까지 미국 달러화 대비 원화 환율 일일 변동폭은 평균 13.2원에 달했다. 과거 월별 일평균 변동폭과 비교하면 코로나19 공포가 극에 달했던 지난 2020년 3월의 13.8원 이후 가장 높다.최예찬 상상인증권 연구원은 "기본적으로 전쟁은 당사국들의 통화 가치를 절하시키는 요인이며 비당사국인 한국의 원화 역시 중동 무력 분쟁에 대체로 약세로 반응해왔다"며 "이번 분쟁은 호르무즈 해협 봉쇄 가능성이라는 변수가 추가된 만큼 분쟁 직전 수준 대비 유사한 폭의 환율 상승은 충분히 가능하다"고 분석했다.다만 증시 전문가들은 코스피가 ''5000포인트''에서 오래 머물 가능성은 제한적이라고 관측한다. 유가 상승이 지속될수록 미국 내 에너지 가격 상승에 따른 트럼프 미국 대통령의 정치적 부담감이 가중될 수밖에 없어서다.안현국 한화투자증권 연구원은 "코스피는 5000포인트 근방에서 대기 자금이 강하게 유입될 수 있다고 보고 분할 매수 대응이 유효하다"며 "반등 이후 반도체와 IT 소부장, 자동차, 코스닥 시총 상위주를 선호한다. 미국 IT 회복 이후 코스닥으로 자금 유입과 정책적 노력을 기대할 수 있다"고 조언했다.', NULL, '매일신문', 'https://n.news.naver.com/mnews/article/088/0001000043', 'https://imgnews.pstatic.net/image/088/2026/03/09/0001000043_001_20260309104513133.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 10:45:13', 0, true, '2026-03-09 05:43:22.327051') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (537, '코스피 빠지자 증권주 우르르…상상인증권 10% 하락', '[특징주]머니투데이 특징주 그래픽 이미지증권주들이 장 초반 동반 하락하고 있다. 코스피가 6% 이상 하락하며 5200대로 미끄러지자 투자심리가 악화된 것으로 보인다.9일 오전 9시4분 현재 다올투자증권은 전 거래일 대비 465원(10.16%) 내린 4110원에 거래되고 있다.상상인증권(-9.25%), 한국금융지주(-9.57%), 미래에셋증권(-8.2%), 교보증권(-7.38%), 한화투자증권(-8.16%), 키움증권(-8.04%), 신영증권(-7.99%), SK증권(-7.35%), NH투자증권(-7.45%) 등도 하락하고 있다.지난달 28일 미국과 이스라엘이 이란을 공습한 이후 국내 증시는 극심한 변동성을 보이고 있다. 이에 코스피는 6000대에서 5000대로 하락했고, 증권주도 동반 하락하고 있다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005327014', 'https://imgnews.pstatic.net/image/008/2026/03/09/0005327014_001_20260309091311770.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 09:12:27', 0, true, '2026-03-09 05:43:22.327051') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (538, '상상인證 "BGF리테일, 업황 개선에 가장 큰 수혜주…목표가 16만원 유지"', '[서울=뉴시스] BGF리테일 BI (사진=BGF리테일 제공) 2026.02.13. photo@newsis.com *재판매 및 DB 금지[서울=뉴시스] 김진아 기자 = 상상인증권은 9일 BGF리테일에 대해 기존점 성장률이 지난해 4분기 턴어라운드를 맞이하며 올해에도 업황 및 실적 개선 흐름이 유지될 것이라 분석하며 투자의견은 ''매수'', 목표주가는 16만원을 유지했다.김혜미 상상인증권 연구원은 "BGF리테일의 기존점 성장률이 지난 4분기부터 턴어라운드한 가운데, 올 1분기에도 호조세가 지속되고 있다"며 "1월과 2월 기존점 성장률이 각각 플러스 성장을 시현한 점은 고무적"이라고 분석했다.이어 "지난 1년여간 하위 사업자를 중심으로 점포 구조조정이 진행되는 동안, BGF리테일의 시장 점유율은 오히려 지속해서 확대됐다"며 "전방 업황이 회복될 때 1위 사업자로서 가장 큰 수혜를 누릴 수 있는 구조를 다져놓은 상황"이라고 짚었다.올해 실적 개선을 이끌 동력으로는 업계 전반의 구조조정 속 점유율이 확대되고 있다는 점과, 외국인 매출 성장, 비수도권 점포 매출 회복 등을 꼽았다.상상인증권에 따르면 작년 한 해 BGF리테일의 외국인 소비로 추정되는 해외 카드 매출은 전년 대비 44% 급증했는데, 이는 전체 매출 내 1.5% 비중에 불과하다.김 연구원은 "지난 4분기부터 중국인 단체 무비자 입국 허용 정책이 시행되는 등 국내에 외국인 관광객 유입이 활성화되고 있다"며 "일상체험 소비 채널 측면에서 외국인 관련 매출은 지속 고성장할 전망"이라고 내다봤다.이어 "현재 고환율과 글로벌 지정학적 불안으로 인해 국민들이 해외보다 국내 여행 소비를 늘릴 가능성이 높다"며 "코로나19 팬데믹 시기 동사의 비수도권 매출이 성장했던 경험을 반추하고, 현재 비수도권 점포 수가 51% 비중을 차지하는 점을 감안하면 충분한 업사이드 모멘텀이 될 것"이라고 전망했다.매력적인 밸류에이션과 주주환원율 제고 가능성 역시 투자 매력을 높이는 요소로 평가했다.김 연구원은 "현재 낮은 수준의 밸류에이션 레벨도 매력적"이라며 "올해 안정적인 실적 성장세와 더불어 부산 물류센터 투자가 종료되면 배당 확대 기대감도 점차 높아질 것"이라고 밝혔다.', NULL, '뉴시스', 'https://n.news.naver.com/mnews/article/003/0013808979', 'https://imgnews.pstatic.net/image/003/2026/03/09/NISI20260213_0002063639_web_20260213113355_20260309083718087.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 08:36:58', 0, true, '2026-03-09 05:43:22.327051') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (539, '[클릭 e종목]"대주전자재료, 실리콘 음극재 성장…목표주가↑"', '"현대차그룹 내 적용차종 확대"상상인증권은 9일 대주전자재료에 대해 투자의견 매수를 유지하고 목표주가를 15만원으로 상향조정한다고 밝혔다.유민기 상상인증권 연구원은 "실리콘 음극재의 파나소닉향 매출 반영본격화, 현대차그룹 내 적용차종 확대에 따른 효과를 기대한다"며 이같이 말했다. 이어 "전도성페이스트 또한 인공지능(AI) 서버향 MLCC 수요증가에 따라 성장세 지속할 것으로 전망한다"며 북미 민간우주항공사업자가 연중 발사예정인 3세대 인공위성에 대주전자재료의 페이스트를 적용한 태양전지가 탑재될 가능성이 높을 것으로 예상한다고 덧붙였다.유 연구원은 올해 매출액 3221억원, 영업이익 414억원으로 전망했다. 전도성페이스트 부문은 데이터센터향 MLCC 수용증가 영향으로 전년 대비 지난해 30% 성장했는데, 올해도 동일한 추세를 보일 것으로 예상했다. 실리콘 음극재 부문은 파나소닉과 테슬라향 물량의 온기 반영, 포르쉐 카이엔 신차 효과, 현대차그룹향 적용차종 확대로 연 39% 성장을 전망했다.페이스트와 관련해 초기물량은 시범적 규모이겠지만 HJT 전극형성에 필수적인 은, 은-구리 페이스트를 국내거점 양산이 가능해 이에 따른 수혜를 받을 것으로 기대한다고 말했다. 장기적으로 운용가능 위성대수 확대, 비중국 소재 밸류체인(가치사슬) 구축 의무화 기조 조건이 맞물리면 대주전자재료의 1차벤더 진입 가능성이 기대된다고도 했다.', NULL, '아시아경제', 'https://n.news.naver.com/mnews/article/277/0005731054', 'https://imgnews.pstatic.net/image/277/2026/03/09/0005731054_001_20260309080419033.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 08:02:46', 0, true, '2026-03-09 05:43:22.327051') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (540, '제이엘케이, 하반기 수출 진척 기대…주가 회복 가능성-상상인', '[이데일리 이혜라 기자] 상상인증권은 9일 제이엘케이(322510)에 대해 “매출 증가 속도는 다소 느리지만 하반기에 수출에서 진척이 기대된다”며 “국내외 매출 증가로 점진적인 주가 회복 가능성이 있다”고 밝혔다. 목표주가는 제시하지 않았다.(자료, 사진=JLK, 상상인증권)하태기 상상인증권 연구원은 이날 보고서에서 “하반기 주가 회복 가능성에 대해 긍정적인 시각으로 지켜볼 필요가 있다”고 말했다.제이엘케이는 인공지능을 활용해 뇌졸중 분야에서 CT 기반 6개 제품, MRI 기반 6개 제품 등 총 12개 뇌졸중 AI 솔루션(MEDIHUB STROKE)을 개발해 세계 최다 전주기 뇌졸중 AI솔루션을 상업화한 기업이다.하 연구원은 JLK가 지난해까지 100% 내수 매출 구조에서 하반기 중 시작되는 일본과 미국 수출로 변화하는 점을 주목했다.하 연구원은 “기술개발도 중요하지만 올해 JLK는 매출 발생과 규모가 더 중요하다”며 “전사 매출액 증가에는 수출이 중요한 변수”라고 했다.그는 “일본 유통 계약으로 일본 시장 매출이 우선적으로 기대된다”며 “미국 시장 수출은 2026년 4분기부터 시작해 매출 증가는 2027년에 예상된다.  미국 보험시장 등재 추진도 기대 요인”이라고 했다.하 연구원은 이어 “일본 수출이 의미 있게 발생하고, 미국에서 비보험수가 등재가 순조롭게 진행되며, 수출이 시작된다면 영업실적 증가에 기반한 주가 상승이 가능할 것”이라고 말했다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006230547', 'https://imgnews.pstatic.net/image/018/2026/03/09/0006230547_001_20260309074911017.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 07:49:11', 0, true, '2026-03-09 05:43:22.327051') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (541, '[이번주 증시 예보] 美 물가지표·오라클 실적발표 주목', '이란 전쟁 여파로 미국 서부텍사스산원유(WTI) 가격이 80달러까지 상승하며 작년 말 대비 약 40% 급등했다. 유가 급등에 따라 미국 국채 10년 금리도 전주 대비 20bp 이상 상승했다. 인플레이션에 대한 경계심이 높아진 상황에서 전 세계 증시는 다음주 발표되는 물가지수에 촉각을 곤두세우고 있다.11일(현지시간)에는 미국 2월 소비자물가지수(CPI) 발표, 13일에는 1월 개인소비지출(PCE) 발표가 예고돼 있다.1월 CPI는 전월 대비 0.2% 상승, 전년 대비 2.4% 상승을 기록했다. 에너지 가격이 1.5% 하락하며 상승폭을 제한했다. 이란 전쟁에 따른 원유 가격 급등은 2월 수치 자체에는 제한적으로 반영될 가능성이 높지만, 관세 효과는 이미 소매 가격에 전이되기 시작했다는 분석이다. 변동성이 큰 식품과 에너지를 제외한 근원 PCE는 18일 연방공개시장위원회(FOMC) 회의 전 블랙아웃 기간 진입 직전 마지막 핵심 인플레이션 지표로 꼽힌다. 1월 CPI에서 근원 지표가 2.0%까지 하락해 PCE에서도 유사한 둔화 추세가 확인되면 미국 연방준비제도(연준)의 ''임무 완수'' 내러티브에 뒷받침이 될 것이란 분석이다.상상인증권은 "이틀 간격으로 발표되는 두 인플레이션 지표가 엇갈리거나 모두 상승 반전할 경우 유가 충격이 아직 반영되지 않은 1월 데이터에서조차 인플레이션이 재가속되고 있다는 해석이 우세해지며 연준의 ''장기 동결'' 시나리오가 시장의 기본 전제로 재설정될 리스크가 있다"고 내다봤다.10일 오라클 실적 발표에도 관심이 쏠린다. 지난 분기 실적 발표 당시 오라클은 시장 기대에 못 미친 매출을 발표하면서 주가가 급락했다. 12일에는 또 다른 인공지능(AI) 소프트웨어주인 어도비가 실적을 발표한다. 최근 월가에서는 ''AI 부채 사이클의 건전성을 점검하려면 오라클을 보라''란 말이 나올 정도로 오라클은 AI 열풍의 풍향계로 여겨진다.[우수민 기자]', NULL, '매일경제', 'https://n.news.naver.com/mnews/article/009/0005646845', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_FINANCE', NULL, '2026-03-08 17:05:12', 0, true, '2026-03-09 05:43:22.327051') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (547, 'PKC, 반도체 고순도 소재 효과로 작년 영업이익 24.6%↑', 'PKC CI. PKC 제공[파이낸셜뉴스] PKC가 반도체 고순도 소재 매출 확대에 힘입어 지난해 실적 개선에 성공했다.PKC는 작년 연결 기준 매출액은 2721억 원으로 전년 대비 11.0% 증가했으며 영업이익은 122억 원으로 24.6% 늘어난 것으로 잠정 집계됐다고 6일 밝혔다. 당기순이익은 61억원으로 68.6% 급증했다.회사 측은 실적 개선 배경으로 클로르 알칼리(CA) 및 반도체 스페셜티 가스 소재 부문의 매출 성장을 꼽았다. PKC 관계자는 “반도체향 고순도 소재의 매출 비중이 확대되면서 원가 부담이 증가했음에도 수익성을 유지할 수 있었다”고 설명했다.출하량 증가에 따른 비용 부담도 확대됐다. 물류비는 전년 대비 7.1%, 전력비는 9.5% 증가했다. 다만 고수익 제품 중심의 제품 믹스 개선 효과가 원가 상승분을 상쇄하며 영업이익률 개선으로 이어졌다는 설명이다. 영업성과 개선과 함께 영업 외 수지도 호전되며 당기순이익 증가 폭도 확대됐다.PKC는 반도체·디스플레이·2차전지 등 고성장 산업을 중심으로 핵심 화학소재 국산화를 추진하고 있다. 이를 위해 새만금 1공장을 신축 중이며, 상반기 시운전과 품질 인증 시험을 거쳐 하반기부터 본격적인 매출 발생을 목표로 하고 있다.윤해구 PKC 대표이사는 “인건비 증가와 새만금 1공장 투자 등 선행 투자가 단기적으로는 비용과 재무 부담으로 작용하고 있다”면서도 “이는 향후 고부가가치 제품 공급 확대와 실적 성장을 견인할 핵심 기반이 될 것”이라고 말했다. 이어 “불확실한 대외 환경 속에서도 고부가 제품 판매 확대를 통해 수익성을 유지하며 견조한 성장을 이어가겠다”고 밝혔다.', NULL, '파이낸셜뉴스', 'https://n.news.naver.com/mnews/article/014/0005474415', 'https://imgnews.pstatic.net/image/014/2026/02/06/0005474415_001_20260206090711098.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-06 09:07:11', 0, true, '2026-03-09 05:43:44.364749') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (548, '''트래펑'' 팔던 PKC "첨단 소재사로 변신"', '기업 탐방100년 기업 꿈꾸는 윤해구 대표내달 새만금 1공장 완공 땐2차전지 핵심 원재료 국산화반도체 금속 재활용도 도전유가증권시장 상장사인 PKC는 1954년 백광약품으로 출발해 가성소다, 염소 등 다양한 기초화학 소재를 제조하는 기업이다. 변기나 배관을 뚫는 가정용 세정제 ‘트래펑’으로도 유명하다. 창립한 지 70년이 넘은 이 회사는 이제 전통 화학 소재 업체에서 벗어나 반도체·배터리 소재 회사로 변신하고 있다.윤해구 PKC 대표는 지난 16일 인터뷰에서 “반도체 경기가 확장 국면에 진입한 상황에서 다음달 새만금 1공장을 완공한다”며 “배터리·반도체 소재 사업을 키우고 글로벌 업체들의 핵심 파트너가 돼 100년 기업의 기틀을 마련하겠다”고 강조했다.PKC는 기존 거래 업체 물량을 늘리고 해외로 고객군을 확장하고 있다. 아산화질소와 고순도 염소, 고순도 염화수소 등으로 거래처를 다변화하는 중이다. 소기가스라고 불리는 아산화질소는 OLED(유기발광다이오드) 제조뿐 아니라 자동차 엔진 출력 강화제나 의료용 마취제로 쓰인다. 최근에 불순물이 없는 고순도 가스 활용도가 높아지면서 반도체 증착 공정의 필수재로 이용되고 있다.윤 대표는 “반도체의 집적도가 올라가는 게 반도체 소재 판도를 바꾸고 있다”고 설명했다. 예전에는 같은 면적의 땅(칩)에 1층짜리 단독 주택을 지었다면 이제는 100층, 200층짜리 마천루에 해당하는 고대역폭메모리(HBM)와 3D 낸드를 쌓아 올리는 시대가 돼 소재에도 변화가 필요하다는 얘기다. 건물이 높아질수록 더 정교하고 깊게 깎아내는 기술이 필요한데, 기존 범용 가스로는 이 미세 공정을 감당하기 힘들어졌다. 그래서 삼불화인 같은 차세대 특수가스로 반도체 회로를 아주 깊고 날카롭게 깎아내야 한다. 윤 대표는 “초미세·고집적 공정 변화에 맞춰 글로벌 장비사와 함께 차세대 가스와 증착 소재인 전구체 물질을 개발 중”이라며 “반도체 집적화가 고도화할수록 우리가 만드는 특수 소재 수요는 급증할 것”으로 전망했다.PKC는 반도체 금속 재활용 사업에도 진출했다. 윤 대표는 “반도체 원자층증착(ALD) 공정에서 원자력 발전의 핵심 소재인 하프늄이나 지르코늄 같은 특수 금속을 사용하는데, 공정 특성상 투입량의 90%가 그냥 폐기된다”고 했다. 최근 연이은 데이터센터 건설로 원전 수요가 급증함에 따라 이 금속들의 가격이 폭등하고 있다.반도체회사 입장에서 비싸게 산 원료를 버리는 건 큰 손해다. 게다가 RE100(재생에너지 100% 전환)이나 탄소 중립 같은 글로벌 환경 규제에 대응하기 위해서라도 자원 재활용이 중요해졌다. 이를 위해 PKC는 반도체업체들이 수거한 폐기물에서 희소 금속을 다시 추출해 고순도 원료로 재공급하는 사업에 나섰다. 고객사는 원재료 구매 비용을 낮추고 환경 인증까지 덤으로 받을 수 있다. PKC는 원재료 비용을 부담하지 않고 고수익을 낼 수 있다. 1차 시제품을 선보인 이 회사는 내년께 수익을 낼 것으로 전망하고 있다.윤 대표는 “다음달 준공하는 새만금 1공장에서 국내 최초로 배터리 전해액 핵심 원료인 삼염화인과 오염화인을 생산한다”며 “상반기에 시운전과 품질 인증 시험을 마치고 하반기부터 매출이 발생하면 실적이 더 좋아질 것”으로 내다봤다.', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005239154', 'https://imgnews.pstatic.net/image/015/2026/01/19/0005239154_001_20260120013821627.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-19 16:40:20', 0, true, '2026-03-09 05:43:44.364749') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (549, '[서울데이터랩]‘참엔지니어링’ 29.92% 상한가…실시간 상승률 1위', '19일 오전 9시 10분 참엔지니어링(009310)가 등락률 +29.92%로 상한가를 기록하며 상승률 1위를 차지했다. 참엔지니어링은 개장 직후 5분간 24만 8584주가 거래되었으며 주가는 공모가 대비 304원 오른 1320원이다.한편 참엔지니어링의 PER은 -1.07로 저평가되어 있을 가능성을 시사하며, ROE는 -36.15%로 수익성이 낮다고 볼 수 있다.이어 상승률 2위 서원(021050)은 현재가 1306원으로 주가가 17.76% 급등하고 있다. 상승률 3위 DYP(092780)는 현재 9080원으로 15.08% 급등하며 활발한 거래를 보이고 있다. 상승률 4위 두산로보틱스(454910)는 12.28% 상승하며 10만 1500원에 거래되고 있다. 상승률 5위 알루코(001780)는 9.52%의 상승세를 타고 2300원에 거래되고 있다.6위 에스엠벡셀(010580)은 현재가 2725원으로 9.00% 상승 중이다. 7위 PKC(001340)는 현재가 5700원으로 8.16% 상승 중이다. 8위 현대약품(004310)은 현재가 1만 4220원으로 7.81% 상승 중이다. 9위 HD현대건설기계(267270)는 현재가 12만 8900원으로 7.69% 상승 중이다. 10위 수산인더스트리(126720)는 현재가 2만 6250원으로 7.36% 상승 중이다.이밖에도 현대차(005380) ▲6.54%, 보락(002760) ▲6.08%, 이수스페셜티케미컬(457190) ▲5.98%, 포스코인터내셔널(047050) ▲5.76% 등을 기록하며 시장에서 활발히 거래되고 있다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003609748', 'https://imgnews.pstatic.net/image/081/2026/01/19/0003609748_001_20260119094214837.png?type=w800', 'NEWS_ETC', NULL, '2026-01-19 09:42:14', 0, true, '2026-03-09 05:43:44.364749') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (550, '''월급 35만원'' 이 악물고 버텼다…급기야 ''연봉 2억'' 찍은 비결 [윤현주의 主食이 주식]', '기초 소재 73년 한우물 PKC윤해구 대표, 취임 첫 인터뷰“2차전지 전해액 핵심 원재료 국산화반도체 메탈 리사이클링 사업 도전2030년 매출 1조원 달성할 것”대주주 과거 회사 돈 횡령은 오점아리스 “목표주가 9000원”백문불여일견(百聞不如一見). 백 번 듣는 것보다 한 번 보는 게 낫다는 말이다. 가짜뉴스 홍수 속 정보의 불균형을 조금이라도 해소하기 위해 주식 투자 경력 19년 5개월 차 ‘전투개미’가 직접 상장사를 찾아간다. 회사의 사업 현황을 살피고 경영진을 만나 투자자들의 궁금증을 해결한다. 전투개미는 평소 그가 ‘주식은 전쟁터’라는 사고에 입각해 매번 승리하기 위해 주식 투자에 임하는 상황을 빗대 사용하는 단어다. 그 누구보다 손실의 아픔이 크다는 걸 잘 알기에 오늘도 개인투자자 입장에서 기사를 쓴다. <편집자주>윤해구 PKC 대표가 사료 원재료 중 하나인 HCl-라이신 합성제품을 들고 군산 공장 위치를 가리키고 있다.“73년 무기화학의 저력을 발판으로 글로벌 첨단 소재 기업으로 도약하겠습니다. 오는 2월 새만금 1공장이 완공되면 2차전지·반도체 소재 사업 강화로 100년 기업의 기틀을 마련하겠습니다.”유가증권시장 상장사인 PKC의 윤해구 대표(1965년생)는 지난 16일 한국경제신문 인터뷰에서 첨단산업 핵심 파트너가 되겠단 의지를 밝혔다. 이 회사는 1954년 백광약품으로 출발해 가성소다(NaOH), 염소(Cl₂) 등 다양한 기초화학 소재를 제조 및 판매한다. 공장은 군산(1만8500평, 생산능력 연 1200억원), 여수(1만평, 생산능력 700억원), 음성(생산능력 161억원)에 있고 본사는 군산에 있다. 작년 3월 취임한 윤 대표의 언론 인터뷰는 이번이 처음이다. 서울특별시 구로구 안양천로539길 6에 있는 서울지점에서 이뤄졌다.유형근 대리가 반도체 납품 가스 밸브를 보여주고 있다. 윤현주 기자가성소다는 공업용 소금을 전기분해해 제조하며 순수한 화학명은 수산화나트륨이다. 가성소다 용액은 무색·무취이며 물보다 무거운 액체로 희석 시에는 다량의 희석열이 발생돼 특별한 안전 작업이 요구되는 소재다. 염소는 소금물이나 액체 소금을 전기 분해해 제조하며 독성이 강한 성질을 띄는 소재로 일상에서 세척과 소독 작업 때 주로 사용한다.남현우 상무가 신규 계약 관련 법률 검토 내용을 설명하고 있다. 윤현주 기자배관 세정제 트래펑으로 유명 … 첨단산업 핵심 소재 국산화 주역으로전통적인 화학 공장을 넘어 2차전지·반도체로 사업 영토 확장을 하기 위해 작년 3월 사명을 바꿨다. 새 엠블럼 중 P는 퍼스트 펭귄(First Penguin)을 상징한다. 남들이 위험하다고 주저할 때 생존을 위해 가장 먼저 차가운 바다로 돌진하는 펭귄처럼, 소재 국산화 이후 글로벌 시장을 선점하는 혁신의 아이콘이 되려 선택했다고 한다. 화학업체라 거리감이 있을 수 있지만 가정용 배관 세정제 트래펑(1989년 출시)으로 유명하다. 현재는 원료 공급만 하는데 예전엔 직접 생산 및 판매도 했다.사업 구조를 살펴보면 소금물(NaCl+H₂O)이라는 가장 기초적인 원료에서 출발해 첨단산업의 핵심 소재로 뻗어나가고 있다. 사업의 뿌리는 전기 분해 공정인데, 소금(NaCl)과 물(H₂O)을 전기 분해하면 세 개의 기초물질(가성소다, 염소, 수소)이 나온다. 가성소다는 전해 매출의 50% 이상을 차지하는데 전 산업에 쓰이며 최근 2차전지 양극재 제조와 폐배터리 재활용 공정 필수 소재로 수요가 늘고 있다고 한다. LS, 에코앤드림, 성일하이텍과 거래 중인 것으로 알려졌다.최우석 과장이 거버넌스 개선 관련 내용을 설명하고 있다. 윤현주 기자염소의 경우 2차전지 주원료가 되면서 전해 사업과 배터리 사업 시너지를 낼 것으로 보고 있다. 청정 에너지원인 수소는 다양한 합성(솔비톨 등 식품첨가제, 염산, 고순도 염화수소)에 쓰이는 기초원료다.전기 분해로 얻은 수소에 포도당을 합성해 만든 게 솔비톨이다. 합성 감미료와는 달리 자연계에 널리 존재하는 천연 과실 감미제와 같은 다양한 효과를 갖는 첨가물로 보습성이 우수하고 단백질 변성 방지, 비만 방지, 난충치성 효과로 인해 각종 식품 첨가제로 광범위하게 사용되고 있다. 현재 제로 슈거 열풍을 이끄는 감미료로 안정적인 수익을 창출한다. PKC는 국내 솔비톨 매출 1위로 작년 관련 매출 370억, 점유율 80%를 자랑한다. 솔비톨은 치약, 청량음료, 제약 제품 등에도 쓰인다.이수정 상무가 신사업 관련 내용을 설명하고 있다. 윤현주 기자염소와 수소를 합성하면 염화수소가 되는데, 이를 반도체 공정에 투입할 수 있는 수준인 고순도 염화수소를 생산하고 있다. 기존 염소를 정제해 고순도 염소를 생산할 수 있는 독보적인 기술을 확보했다고 한다. 반도체 및 디스플레이 고객사에게 공급되고 있다.가성소다 사업 부문 고객사는 SK하이닉스, 삼성디스플레이, LG디스플레이, 코오롱인더스트리 등이 있고 솔비톨 사업 부문 고객사는 아모레퍼시픽, LG생활건강, 롯데푸드 등이 있다. 신소재사업은 삼성전자, SK실트론 등이 고객으로 꼽힌다.윤중현 차장이 일자리 으뜸기업 상패 등을 자랑하고 있다. 윤현주 기자“반도체 소재 매출 대폭 증가 예상”…반도체 메탈 리사이클링 사업도윤 대표는 “올해 반도체 경기가 확장 사이클에 진입했다”며 “아산화질소(N₂O), 고순도 염소, 고순도 염화수소 등의 거래처 다변화 전략이 빛을 볼 것 같다”고 말했다. 기존 고객사 물량 확대와 더불어 해외 고객사 진입을 통해 반도체 소재 매출이 큰 폭으로 증가하는 걸 암시했다. 아산화질소는 소기가스라고도 불리는데 발화성이 없고 약간 달콤한 향이 있는 무색 가스이다. 디스플레이(OLED)에 대량으로 쓰인다.윤 대표는 “반도체 시장의 트렌드는 집적화다”고 말했다. 쉽게 말해 예전에는 1층짜리 단독 주택을 지었다면 이제는 한정된 땅(칩)에 100층, 200층짜리 마천루(HBM·3D 낸드)를 쌓아 올리는 시대가 된 것이다. 건물이 높아질수록 더 정교하고 깊게 깎아내는 기술이 필요한데, 기존 범용 가스로는 이 미세한 공정을 감당하기 힘들다. 그래서 삼불화인(PF3) 같은 차세대 특수가스가 필요한데, 이 가스는 반도체 회로를 아주 깊고 날카롭게 깎아내는 식각 공정에서 필수 역할을 한다. 그는 “초미세·고집적 공정 변화에 맞춰 글로벌 장비사 및 칩 메이커와 함께 차세대 가스와 증착 소재인 프리커서(전구체) 물질을 개발 중이다”며 “반도체 집적화가 늘수록 우리가 만드는 특수 소재 수요는 급증할 것이다”고 설명했다.조영훈 차장이 출자 보조금 관련 설명을 하고 있다. 윤현주 기자특히 반도체 메탈 리사이클링 사업도 진출했다. 윤 대표는 “반도체 원자층증착(ALD) 공정에서 하프늄(Hf)이나 지르코늄(Zr) 같은 특수 금속을 사용하는데, 공정 특성상 투입량의 90%가 그냥 버려진다”고 했다. 문제는 이 금속들이 원자력 발전의 핵심 소재로 쓰인다는 것이다. 최근 인공지능(AI) 데이터센터 가동을 위해 글로벌 원전 건설이 늘면서 이 금속들의 품귀 현상으로 가격이 폭등하는 현상이 발생하고 있다.칩 메이커 입장에서는 비싸게 산 원료를 버리는 것도 비용적으로 손해지만 RE100(재생에너지 100%)이나 탄소 중립 같은 글로벌 환경 규제에 대응하기 위해서라도 자원 재활용이 중요한 셈이다. 이를 위해 PKC가 칩 메이커가 수거해 온 폐기물에서 희소 금속을 다시 추출해 고순도 원료로 재공급하는 사업에 나섰다. 고객사는 원재료 구매 비용을 낮추고 환경 인증은 덤인 셈이다. PKC 입장에서는 원재료비 0원으로 고수익을 낼 수 있는 장점이 있다. 현재 1차 시제품이 나왔는데 내년 정도 수익화가 가능할 것으로 보인다.윤정호 부장(왼쪽)과 김주현 이사가 영업 실적 회의 중이다. 윤현주 기자또 “새만금 1공장이 내달 완공되면 이곳에서 국내 최초로 2차전지 전해액 핵심 원료인 PCl₃와 PCl₅의 양산이 시작된다”며 “상반기에 시운전과 퀄 테스트(품질 인증 시험)를 마치고 하반기부터 매출이 발생하면 외형 성장을 주도할 수 있다”고 했다. 이어 “최근 중국이 800개 이상의 광물·소재를 일본 대상으로 수출 통제에 나섰고 리튬 가격 반등으로 전해액 가격이 안정되면서 소재 시장의 전망도 좋아지고 있다”고 부연했다.내년부터 PCl₅ 양산을 시작으로 배터리 산업 공급망 안보를 담당한다는 계획이다. 2차전지 전해액 핵심 원재료 국산화가 미래 성장동력인 것이다. PCl₃는 삼염화인으로 PCl₅ 제조 원료이며 계면활성제, 살충제, 가소제 등으로 사용하고 전량 수입에 의존하고 있다. PCl₅는 오염화인으로 2차전지 전해액의 15%를 차지하는 리튬염 원료로 사용된다.배석전 상무가 새만금1공장 사업 내용을 알려주고 있다. 윤현주 기자윤 대표는 “반도체·2차전지 사업 강화로 올해 사상 최대 실적을 이루겠다”고 강조했다. 신사업 순항 땐 2030년 매출 1조원도 가능하다는 계산이다. 반도체, 2차전지, 자원 재활용 등에서 고부가 소재 개발로 첨단 산업 고객사가 확대됐을 경우다.4차 산업혁명 가속화에 따른 핵심 소재의 중요성은 계속 부각되고 있다. 민감한 첨단 산업 및 제품들의 안정성을 위한 고성능 핵심 소재가 필요하고, 무역 분쟁 등 대외 리스크 관리 및 첨단 산업 내 비용 절감을 위해 핵심 소재 국산화 필요성은 높아지고 있다. 환경을 생각하고 지속 가능한 삶을 위해 친환경 소재 수요도 늘고 있는 건 PKC에게 우호적이다. 70년 넘게 화학물 노하우가 있기에 고순도 소재 사업서 결실을 맺겠다는 것이다.윤 대표는 “대한민국 산업의 뿌리와 같은 기업으로 키우고 싶다”며 “2차전지·반도체 소재 공급으로 대한민국의 든든한 일꾼이 되겠다”고 덧붙였다. 2030년 연매출 1조원, 영업이익 1000억원 이상 꿈꾸고 있다.작년 3분기 누적 매출 2006억원, 영업이익 87억원으로 안정적인 실적을 자랑하고 있다. 가성소다와 염소 등을 생산하는 클로르 알칼리(CA)가 전체 매출의 70%를 담당한다. 새만금 공장 가동으로 올해 구조적인 변화를 기대한다.PKC 주가 주봉 그래프 캡처.그럼에도 주가는 내리막길이다. 18일 한국거래소에 따르면 주가는 5270원으로 1년 전(2025년 1월 10일 7730원)보다 31.82% 떨어졌다. 코스피지수가 같은 기간 92.42% 폭등할 때 주가 하락으로 주주들의 심리적 고통이 커진 셈이다.신기두 부장이 산업안전보건법 법령 요지 내용을 알려주고 있다. 윤현주 기자주가 부양책을 묻자 “미래 성장을 위한 설비투자와 연구개발(R&D)에 모든 역량을 쏟아붓고 있다”며 “신사업 성과가 가시화되고 현금 흐름이 안정화되면 배당 확대나 자사주 매입 등 주주환원책을 적극 검토하겠다”고 약속했다.총 주식 수는 4491만8407주로 김성훈 전 대표(지분 22.64%) 외 특수관계인 9인이 지분 42.82%를 보유한 최대주주다. 자사주 1.71%, 외국인 2.21%로 유통 물량은 사실상 55% 정도다. 개인주주는 약 2만명(2024년 12월 기준) 정도로 파악된다.박찬호 대리가 내부회계 자료를 검토 중이다. 윤현주 기자“서울 구로구 땅 가치 6000억”…시총은 2367억작년 3분기 기준 현금성 자산 406억원, 유형자산 4698억원 있다. 특히 서울 구로구에 있는 2만평 부지의 가치에 시장은 주목하고 있다. 과거 서울공장 자리인데 땅은 그대로 남아 스포츠센터(아이스링크, 골프장)로 운영되고 있다. 개발제한 구역이라 감정가가 2000억원 정도 하는데 주변 시세로 따지면 약 6000억원 가치라고 사측은 밝혔다. 현재 시가총액(2367억원)의 2배 이상이다.다만 김성훈 전 대표가 229억원 회사 돈 횡령으로 오점을 남겼다. 시장의 신뢰를 쌓기에 많은 시간이 필요할 수 있는 대목이다. 이를 지적하자 “오너 일가의 경영 개입은 일체 없고 전문경영인 체제로 회사를 더 건전하게 만들고 있다”고 답했다. 이어 “지배구조 위기가 회사를 더 투명하고 단단하게 만드는 예방주사가 되었다”고 덧붙였다.박정호 상무가 결산 자료를 검토하고 있다. 윤현주 기자윤 대표는 1989년 첫 회사로 PKC를 택했다. 당시 백광화학이었는데 월급이 35만원, 연봉은 420만원이었다고 한다. 보너스로 700%가 나오는 우량 회사였다고 한다. 37년간 근무한 지금 그의 월급은 2000만원, 연봉은 약 2억4000만원 정도라고 한다.37년 ‘화학 한 우물’인데 애로사항은 없었을까. 윤 대표는 “2010년 서울 마지막 화학 공장이 PKC 공장이었다”며 “이를 여수로 이전하는 작업을 8개월 안에 마쳐야 하는 게 가장 컸다”고 회상했다. 이어 “화학공장은 한순간의 실수로 큰 사고가 발생할 수 있는데 안전 수칙을 잘 지키고 직원들이 합심해 8개월 만에 여수 공장 이전을 잘 마쳐 제품도 완벽하게 납품할 수 있었다”고 웃으며 말했다. 다국적 기업이 좋은 조건으로 ‘여수 러브콜’을 했는데 납기를 제때 맞춘 것이다.사원으로 시작해 최고경영자(CEO)까지 오른 그에게 인생 조언을 부탁하자 ‘진인사대천명’을 말했다. 그는 “실패를 너무 두려워해 시작조차 주저하는 경우가 많은데, 본인이 할 수 있는 모든 노력을 쏟아부었다면 하늘이 반드시 보상해준다”며 “올바른 길이 맞다면 무조건 도전하길 추천한다”고 덧붙였다.황다희 사원이 트래펑 제품을 설명하고 있다. 윤현주 기자독립리서치를 운영하는 이재모 아리스 대표는 18일 기자와의 통화에서 “PKC는 현재 반도체·디스플레이·2차전지 소재 분야에 선제적 설비투자를 통해 신성장동력을 강화하고 있다”며 “2차전지 전해액 핵심소재인 육불화인산리튬(LiPF6) 원료( PCl₃· PCl₅) 생산을 위한 새만금 공장 가동 땐 중국 의존도가 높은 핵심 소재를 연간 2.9만t까지 자체 생산해 국산화 및 매출 증가에 기여할 전망이다”고 분석했다. 이어 “그럼에도 주가는 신사업의 가치가 전혀 반영되지 않은 바닥권에 있다”며 “수급 개선이 되면 9000원까지 오를 수 있다”고 주장했다. 현 주가 대비 70.78% 상승 여력이 있는 셈이다.''1500만 개미''와 함께 달리겠습니다. 여러분의 주식 계좌가 빨간불이 되는 그날까지 재미있는 종목 기사 많이 쓰겠습니다. 아래 기자 페이지에서 윤현주 기자 구독과 응원을 눌러 주시면 기사를 매번 빠르게 확인하실 수 있습니다.윤현주 기자 hyunju@hankyung.com', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005238522', 'https://imgnews.pstatic.net/image/015/2026/01/18/0005238522_001_20260118100511847.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-18 07:01:10', 0, true, '2026-03-09 05:43:44.364749') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (551, 'PKC, 총 181억원 규모 지방투자촉진보조금 지원 확정…새만금 공장 증설 투입', '[이데일리 박순엽 기자] 글로벌 종합 화학 신소재 개발·제조 전문기업 PKC(001340)는 군산시로부터 국비, 도비 지원을 포함 총 181억원 규모의 지방투자촉진보조금 지원을 확정받고, 전액을 새만금 공장 증설에 투입한다고 20일 밝혔다.PKC 군산공장 전경 (사진=PKC)해당 보조금은 ‘지방자치분권 및 지역균형발전에 관한 특별법’에 근거해, 수도권 기업의 지방 이전 또는 지방 내 신·증설 투자를 촉진하기 위해 지원되는 제도다.이번 보조금 확정은 새만금개발청과 전북특별자치도, 군산시 등 유관기관의 협력 아래 이뤄진 것이며, 이번 투자로 법인세와 소득세 전액 면제(3년) 및 50% 감면(추가 2년) 혜택도 함께 적용받게 됐다.PKC는 사업성, 투자 규모, 고용 창출 등 엄격한 심사 기준을 충족해 이번 지원 대상으로 최종 선정됐다.PKC는 새만금 산업단지 내 부지에 약 1200억원을 투자해 핵심 설비 증설을 추진하고 있으며, 신규 고용도 계획하고 있다.PKC는 2차전지 전해액의 핵심소재인 LiPF6 원료(PCl3, PCl5) 생산을 위한 새만금 공장을 올해 내 준공할 예정이며, 완공 후에는 중국 의존도가 높은 핵심 소재를 연간 2.9만 톤까지 자체 생산해 국산화와 매출 증가에 기여할 전망이다.윤해구 PKC 대표이사는 “이번 보조금 확보는 PKC의 안정적 성장을 뒷받침함과 동시에 지역 산업 생태계 활성화와 신규 투자 유치에도 긍정적인 파급효과를 가져올 것”이라며 “앞으로도 지역사회와의 상생을 통해 지속 가능한 산업 기반을 조성하고 새만금 경제의 도약을 이끌겠다”고 말했다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006142010', 'https://imgnews.pstatic.net/image/018/2025/10/20/0006142010_001_20251020092617946.jpg?type=w800', 'NEWS_ETC', NULL, '2025-10-20 08:54:10', 0, true, '2026-03-09 05:43:44.364749') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (552, '대상의 도약 이끈 임창욱… 두 딸 세령·상민 사실상 ‘3세 체제’[2025 재계 인맥 대탐구]', '4부 소비재 왕국의 신화 (3) 대상대상의 상징 임창욱 회장한양대·日와세다대 화학공학 전공연구파 부친과 달리 해외 사업 확장1990년대 초 아시아 신흥 시장 진출성과보다 직원과 조직의 화합 중시전문경영인 체제로 경영 분쟁 없어임세령, 브랜드 전략·마케팅 성과임상민, 글로벌·신사업 발굴 주도고 임대홍 대상그룹 창업주는 전북 정읍 출신이다. 임 창업주는 이리농림학교를 졸업한 뒤 고창군청 공무원으로 일했으나 해방 이후 공직을 떠나 피혁공장을 세웠다. 6·25 전쟁 직후 복구사업이 시작되면서 무역업에 뛰어들었고, 일본을 오가며 국내 식탁을 장악한 조미료 ‘아지노모토’를 보고 국산 조미료 개발을 결심했다.1955년 일본으로 건너가 MSG 제조 기술을 익힌 그는 이듬해 부산에 ‘동아화성공업’을 세웠다. 이때 국내 최초의 국산 조미료인 ‘미원’이 탄생했다. 순수 국내 자본과 기술로 생산된 미원은 1960~70년대 국내 시장의 절반 이상을 점유했고, 1967년 발효식품 최초로 KS인증을 받았다. 1970년 세계 식품 콘테스트에서 1위를 차지하며 해외 시장으로 뻗어 나갔다.임 창업주는 경영자보다 실험자로 불렸다. 직접 설비를 제작하고, 부족한 자재를 옹기와 돌로 대신했다. 공장 바닥에 염산이 새어 나오면 전국을 다니며 내구성이 강한 돌을 찾아내 석부(돌솥)를 만들기도 했다. 생활은 검소했다. 지방 출장 땐 1박에 5만원 이상 숙소를 피했고 전철을 애용했다. 평생 양복 세 벌과 구두 두 켤레 이상을 소유하지 않았다는 일화는 유명하다.임 창업주는 부인 고 박하경 여사와의 사이에서 2남 1녀를 뒀다. 장남 임창욱(76) 회장이 1987년부터 그룹을 맡았다. 한양대와 일본 와세다대에서 화학공학을 전공한 그는 40대에 회장직에 올라 그룹을 이끌었다.임 회장은 부친과 달리 대외 활동을 늘리고 진취성을 강조했다. 창업주가 연구와 실험에 몰두했다면 그는 해외 사업을 확장하고 기업의 현대화를 추진했다. 1990년대 초반 인도네시아·베트남·중국 등 아시아 신흥 시장에 진출했고, 가공식품·건강기능식품·외식사업 등으로 포트폴리오를 다변화했다. ‘청정원’ 브랜드 출범도 그의 재임기에 방향이 잡혔다. 다만 외부 홍보에는 소극적이었다.그의 경영 철학은 성과보다 직원과 조직의 화합을 중시한 것으로 전해진다. 1997년 퇴임 후 전문경영인 체제가 도입됐지만 현재도 그룹 내 상징적 인물로서 존재감을 유지하고 있다.임 회장은 금호그룹 창업주 고 박인천 회장의 셋째 딸 박현주(72) 대상홀딩스 부회장과 결혼했다. 박 부회장은 이화여대 영문학과를 졸업하고 미국에서 미술을 전공했다. 두 사람 사이에서 장녀 임세령(48) 부회장과 차녀 임상민(45) 부사장이 태어났다.임 회장의 남동생 임성욱(58) 세원그룹 회장은 한국산업은행 전 부총재보를 지낸 손필영씨의 딸 손성희(59)씨와 혼인했다. 두 사람은 일본 유학 시절 교회에서 만나 가정을 꾸렸다.임 창업주의 장녀 임경화(82)씨는 ‘트래펑’으로 알려진 김종의 백광산업 회장과 결혼했다.임 부회장은 연세대 경영학과에 재학 중이던 1998년 이재용(57) 삼성전자 회장과 결혼했다. 당시 결혼은 양가 어머니인 홍라희(80) 리움미술관 명예관장과 박 부회장이 주선한 것으로 알려졌다. 임 부회장은 결혼 직후 학교를 중퇴하고 이 회장의 미국 하버드대 유학길에 함께 올랐고, 이 시기 뉴욕대 심리학과를 졸업했다. 결혼 11년 만인 2009년 합의 이혼했다. 두 사람 사이에서 아들 지호(25)씨와 딸 원주(21)씨가 태어났다.이혼 후 임 부회장은 2012년 대상 식품BU 크리에이티브 디렉터로 합류해 경영 일선에 뛰어들었다. 브랜드 전략과 마케팅에서 성과를 냈다고 평가받는다. 2014년 청정원 브랜드 리뉴얼을 주도해 기존 전통 이미지를 현대적이고 세계적인 이미지로 바꿨다. 2016년에는 가정간편식(HMR) 브랜드 ‘안주야’를 출시해 시장을 선도했다. 국내 안주 HMR 시장이 성장하는 계기를 만들었다는 평가다.2021년 부회장으로 승진한 뒤 식품BU 마케팅을 총괄하고 있다. 내부에서는 글로벌 트렌드에 밝고, 소비자 친화적 감각을 갖춘 리더로 알려졌다. 임 부회장은 공식 석상 노출이 많지 않지만 사내에서는 직원들과 구내식당에서 함께 식사하거나 카페에서 자연스럽게 어울리는 등 ‘열린 경영자’의 모습을 보이고 있다. 배우 이정재씨와 10년째 열애 중이다.아들 지호씨는 해군 학사사관 후보생으로 입대하며 미국 시민권을 포기했다. 특권 대신 병역의무를 택한 사례로 주목받았다. 딸 원주씨는 미국 시카고대 데이터과학 전공 2학년으로 재학 중이다. 현지 NGO 시몬스센터에서 인턴으로 일하며 ‘매디슨 리’라는 이름으로 활동하고 있다.임 회장의 차녀 임 부사장은 이화여대 사학과, 미국 파슨스디자인스쿨, 런던비즈니스스쿨(MBA)을 거쳤다. 2009년 대상 PI(프로세스 이노베이션) 본부에 입사해 경영혁신 관련 업무를 맡았다. 2016년 전무로 승진한 뒤 그룹 내 합병과 사업구조 개편을 통해 경영 효율성을 높였다.2023년 부사장으로 승진하면서 글로벌 사업 확장과 신사업 발굴을 주도하고 있다. 대상 아메리카 법인에서 근무한 경험이 있어 해외 시장과 네트워크에 강점이 있다. 내부에서는 ‘경청형 리더’라는 평가가 나온다. 회의에서 실무자와 동등하게 의견을 나누지만 필요할 땐 날카로운 질문을 던져 직원들을 긴장하게 만든다는 후문이다.2015년 다섯 살 연하인 국유진(40) 블랙스톤 한국 프라이빗에퀴티(PE) 부문 대표와 결혼했다. 국 대표는 국균(73) 전 언스트앤영 한영회계법인 대표의 장남으로 미국 시카고대 경제학과와 하버드대 경영전문대학원(MBA)을 졸업했다.대상그룹의 지주사인 대상홀딩스 지분은 임 부사장 36.71%, 임 부회장 20.41%, 임 회장 4.09%, 박 부회장 3.87% 순으로, 지분 구조만 보면 이미 두 자매 중심의 3세 경영 체제가 확립됐다.임 부회장은 브랜드와 소비자 전략, 임 부사장은 경영 효율화와 글로벌 확장을 맡고 있어 상호보완적인 성향이라는 평가가 나온다. 자매간 우애가 좋고 대상그룹이 1997년부터 전문경영인 체제로 운영된 만큼 경영권 분쟁 없이 전문경영인 체제가 유지될 것으로 전망된다.', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003577057', 'https://imgnews.pstatic.net/image/081/2025/09/23/0003577057_001_20250923050400665.jpg?type=w800', 'NEWS_ETC', NULL, '2025-09-23 05:04:00', 0, true, '2026-03-09 05:43:44.364749') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (553, 'PKC, 2분기 영업이익 22억…전년比 77.9%↑', '[서울=뉴시스] 김경택 기자 = 종합 화학 신소재 개발·제조 전문기업 PKC는 2분기 연결 영업이익이 22억원을 기록해 전년 동기 대비 77.9% 증가했다고 18일 밝혔다.같은 기간 매출액은 662억원으로 12.0% 늘었고 순이익은 22억원으로 879.9% 늘었다. 별도 기준 매출액은 655억원으로 전년 동기 대비 13.7% 증가했고, 같은 기간 영업이익은 236.4% 증가한 21억원을 기록했으며 순이익은 흑자전환에 성공했다.회사 관계자는 "CA(클로르 알칼리) 및 고순도 제품군 판매 확대가 매출을 견인했고, 제품 포트폴리오 다각화를 통해 시장 내 경쟁력을 강화하며 전력비 상승에도 불구, 매출 성장을 지속했다"고 설명했다.PKC의 자기자본비율은 지난 6월 말 기준 42.3%, 현금성 자산은 337억원을 보유하고 있다. 이 같은 견고한 재무구조를 바탕으로 사업 안정성과 신뢰성을 확보하고, 장기 성장 전략을 안정적으로 추진할 수 있는 체력을 확보했다는 게 회사 측 설명이다.향후 PKC는 반도체·디스플레이·이차전지 소재 분야의 선제적 설비투자를 통해 신성장 동력을 강화할 계획이다. 현재 해당 사업의 생산역량 확보를 위해 새만금 1공장을 건설하고 있으며, 올해 연말 완공을 예상하고 있다. 이를 통해 ▲핵심 화학소재 국산화 ▲제품 포트폴리오 확대 ▲첨단 산업 시장 진출 비전을 실현할 방침이다.윤해구 PKC 대표이사는 "이번 실적은 PKC의 지속적인 기술 혁신과 제품 경쟁력 강화 노력의 결실"이라며 "기존 사업의 안정적 성장과 더불어 이차전지 소재 등 신성장 동력을 확보해 지속 가능한 성장을 추진하겠다"고 말했다.', NULL, '뉴시스', 'https://n.news.naver.com/mnews/article/003/0013426193', 'https://imgnews.pstatic.net/image/003/2025/08/18/NISI20250818_0001920022_web_20250818084059_20250818084822539.jpg?type=w800', 'NEWS_ETC', NULL, '2025-08-18 08:47:47', 0, true, '2026-03-09 05:43:44.364749') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (562, '삼성제약, ‘PSP 치료제 GV1001’ 조건부 허가 신청', '[사진제공 = 삼성제약]삼성제약은 식품의약품안전처(식약처)에 ‘진행성핵상마비(progressive supranuclear palsy, 이하 PSP) 치료제 GV1001’의 품목 조건부 허가를 신청했다고 20일 밝혔다.삼성제약에 따르면 이번 조건부 허가 신청은 진행성핵상마비 리처드슨 신드롬(PSP-RS) 유형을 적응증으로 하며, 조건부 승인을 받을 경우, 식약처 조건에 따른 임상시험을 시행해야 한다. 삼성제약은 지난해 12월 젬백스앤카엘과의 기술이전을 통해 한국을 포함한 아시아 주요 4개국에서 PSP 치료제 GV1001의 임상 개발 및 상업화 권리를 확보했다.조건부 허가는 생명을 위협하는 암 등 중증 질환이나 희귀질환 치료제에 대해 2상 임상시험 결과를 근거로 우선 시판을 허가하되, 출시 후 3상 임상시험 결과 제출을 조건으로 허가하는 제도이다.PSP 치료제 GV1001은 2024년 식약처로부터 개발단계 희귀의약품으로 지정받았다. 삼성제약은 조건부 허가 취득 시, 의료 현장에 약물이 신속히 공급될 수 있도록 한다는 계획이다.이상규 기자', NULL, '매일경제', 'https://n.news.naver.com/mnews/article/009/0005624825', 'https://imgnews.pstatic.net/image/009/2026/01/21/0005624825_001_20260121080008252.jpg?type=w800', 'NEWS_BIO', NULL, '2026-01-21 08:00:08', 0, true, '2026-03-09 05:44:08.420912') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (554, '[서울데이터랩]다이나믹디자인 17.04% 급등…실시간 상승률 1위', '21일 오전 9시 10분 다이나믹디자인(145210)가 등락률 +17.04%로 급등하며 상승률 1위를 차지했다. 다이나믹디자인은 개장 직후 5분간 2,350,345주가 거래되었으며 주가는 전 거래일 대비 160원 오른 1,099원이다.한편 다이나믹디자인의 PER은 -4.52로 다소 부정적인 수익성을 시사하며, ROE는 -12.87%로 수익성이 낮다고 평가된다.이어 상승률 2위 아이티센씨티에스(031820)는 현재가 757원으로 주가가 16.64% 급등하고 있다. 상승률 3위 한화솔루션(009830)은 현재 38,050원으로 7.79% 상승 중이다. 상승률 4위 씨에스윈드(112610)는 6.61% 상승하며 50,000원에 거래되고 있다. 상승률 5위 호텔신라우(008775)는 4.62%의 상승세를 타고 52,100원에 거래되고 있다.6위 한화솔루션우(009835)는 현재가 28,800원으로 4.54% 상승 중이다. 7위 OCI(456040)는 현재가 60,100원으로 4.52% 상승 중이다. 8위 삼아알미늄(006110)은 현재가 19,720원으로 4.50% 상승 중이다. 9위 한화엔진(082740)은 현재가 28,200원으로 4.44% 상승 중이다. 10위 롯데케미칼(011170)은 현재가 68,700원으로 4.09% 상승 중이다.이밖에도 한농화성(011500) ▲4.04%, 유화증권우(003465) ▲3.97%, 현대제철(004020) ▲3.88%, 국도화학(007690) ▲3.85%, LG화학(051910) ▲3.85%, PKC(001340) ▲3.81%, 대한유화(006650) ▲3.68%, SK이터닉스(475150) ▲3.55%, 조광페인트(004910) ▲3.45%, POSCO홀딩스(005490) ▲3.38% 등을 기록하며 시장에서 활발히 거래되고 있다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003559338', 'https://imgnews.pstatic.net/image/081/2025/07/21/0003559338_001_20250721093013283.jpg?type=w800', 'NEWS_ETC', NULL, '2025-07-21 09:30:13', 0, true, '2026-03-09 05:43:44.364749') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (555, '[서울데이터랩]금일 코스피 거래량 1위 신성이엔지 거래대금 1,141억 돌파', '코스피 거래량 상위 종목들이 전반적으로 상승세를 보이고 있다.9일 한국거래소에 따르면, 신성이엔지(011930)가 46,880,966주가 거래되며 코스피 종목 중 실시간 거래량 1위를 기록하고 있다. 현재 주가는 2,400원으로, 시가총액 4,940억원 대비 거래대금이 114,133백만원으로 2.31%를 차지하며 활발한 매수세가 이어지고 있다. PER은 -40.68, ROE는 -5.85로 나타나며 재무 지표는 다소 부진하지만, 긍정적인 투자 심리가 반영된 것으로 보인다. SK증권(001510)은 913원으로 6.53% 상승하며 거래량 35,949,657주를 기록하고 있다. 거래대금은 33,272백만원으로 시가총액 4,315억원 대비 0.77%를 차지하며, PER은 114.12, ROE는 -13.91로 나타나고 있다.한화솔루션(009830)은 48,550원으로 15.60% 급등하며 거래량 27,753,899주를 기록 중이다. SG세계물산(004060)은 460원으로 6.31% 하락하며 19,716,740주가 거래되고 있다. 삼성전자(005930)는 166,500원으로 4.98% 상승하며 17,624,161주가 거래되고 있다. 미래에셋증권(006800)은 54,500원으로 13.54% 상승하며 10,183,757주가 거래 중이다. 두산에너빌리티(034020)는 95,400원으로 7.19% 상승하며 7,762,584주가 거래되고 있다. 대우건설(047040)은 5,750원으로 4.17% 상승하며 7,354,807주가 거래되고 있다. 한화갤러리아(452260)는 2,090원으로 2.34% 하락하며 5,857,322주가 거래 중이다. 한온시스템(018880)은 3,845원으로 2.26% 상승하며 5,718,939주가 거래되고 있다.한편 거래량 상위 20위권 종목들은 대한해운(005880) ▲3.18%, 서울식품(004410) ▲1.37%, 금호타이어(073240) ▲11.06%, 조비(001550) ▲13.57%, 계양전기(012200) ▲4.83%, 에이프로젠(007460) ▼0.98%, 다이나믹디자인(145210) ▲10.53%, 한화투자증권(003530) ▲5.09%, SK하이닉스(000660) ▲4.95%, 삼성제약(001360) ▲6.00% 등의 성적을 기록하고 있다.주목할 만한 종목으로는 한화솔루션과 미래에셋증권이 있다. 한화솔루션은 15.60%의 급등과 함께 거래대금 1조 2,943억을 기록하며 시가총액의 15.50%를 차지하고 있다. 이는 투자자들의 대규모 매수세가 몰린 것으로 해석할 수 있다. 반대로, SG세계물산은 6.31% 하락과 함께 거래대금이 시가총액의 1.01%에 불과하여 상대적인 매도세가 관찰되고 있다.전체적으로 코스피 시장은 긍정적인 투자 심리가 반영된 모습이다. 특히, 급등한 종목들이 높은 거래대금을 동반하며 시장에서 주목받고 있다. 이에 따라 투자자들의 관심이 지속적으로 유지될 것으로 예상된다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003615994', 'https://imgnews.pstatic.net/image/081/2026/02/09/0003615994_001_20260209133316525.png?type=w800', 'NEWS_BIO', NULL, '2026-02-09 13:33:16', 0, true, '2026-03-09 05:44:08.420912') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (556, '김민석 총리 “희귀질환, 국가 정책 차원 대응”…관련 기업들 주목', '[이데일리 박정수 기자] 김민석 국무총리가 희귀질환 환자와 가족을 만나 희귀질환 치료에 대한 국가 정책 차원의 대응 필요성을 언급하면서, 희귀질환 치료제 개발 기업들에 대한 관심이 높아지고 있다.김 총리는 최근 희귀질환 환자 및 가족들과의 만남에서 신약 허가와 보험 급여 등 다양한 정책 수단을 통해 희귀질환 환자들이 보다 원활하게 치료를 받을 수 있도록 관계 부처와 논의하겠다는 입장을 밝혔다. 적시 치료가 중요한 희귀질환 특성상, 치료제 개발과 허가 과정 전반에 속도가 붙을 수 있을지 이목이 쏠린다.6일 식품의약품안전처의 의약품통합정보시스템 ‘의약품안전나라’에 따르면 현재 개발 단계의 희귀의약품으로 약 74개 품목이 지정돼 있다.질환별로 보면 젬백스(082270)는 진행성 핵상마비 치료제를, 메디포스트(078160)는 미숙아 기관지이형성증 치료제를 개발 중이다. 이엔셀(456070)은 듀센근디스트로피 치료제를, 녹십자(006280)는 산필리포증후군 A형 치료제를, 부광약품(003000)은 레보도파 유발 이상운동증 치료제 개발을 진행하고 있다.이 외에도 안트로젠(065660), 셀비온(308430), HLB생명과학(067630) 등 다수 기업들이 희귀의약품 치료제 연구개발을 이어가고 있다.여기에 삼성제약(001360)은 최근 희귀질환인 진행성 핵상마비 치료제 GV1001에 대해 조건부 허가를 식약처에 신청한 것으로 확인됐다. 조건부 허가는 생명을 위협하는 중증 질환이나 희귀질환 치료제에 대해 임상 2상 결과를 근거로 우선 시판을 허용하는 제도다.지난해 12월 젬백스로부터 GV1001에 대한 기술이전 계약을 체결하고, 한국을 포함한 아시아 주요 4개국에 대한 임상 개발 및 상업화 권리를 확보한 삼성제약은 허가 결과를 앞두고 있어 환자와 업계의 관심이 높아지고 있다.제약업계 관계자는 “지난해 12월 이재명 대통령이 희귀질환 환자들과 직접 면담한 데 이어, 올해 1월에는 희귀질환 치료 지원 대책이 발표됐다”며 “이번에는 총리까지 나서 정책적 관심을 언급한 만큼 제도 환경이 점진적으로 개선될 가능성이 있다”고 말했다.이어 “희귀질환 치료제 개발 기업들은 까다로운 임상 조건과 허가 지연 등으로 어려움을 겪어왔다”며 “정책과 제도 개선이 뒷받침된다면 치료제 개발 속도도 빨라질 수 있을 것”이라고 덧붙였다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006214643', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_BIO', NULL, '2026-02-06 11:33:10', 0, true, '2026-03-09 05:44:08.420912') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (557, '비엘팜텍 5연상…젬백스도 상승세 지속[바이오맥짚기]', '이 기사는 2026년01월29일 08시00분에팜이데일리 프리미엄 콘텐츠로 선공개 되었습니다.[이데일리 김진수 기자] 28일 국내 제약·바이오 업계에서는 비엘팜텍(065170)이 분자접착제(Molecular Glue) 플랫폼 기술에 대한 기술수출(기술이전, 라이선스-아웃) 기대감으로 5거래일 연속 상한가를 기록했다.젬백스(082270)는 계열사 삼성제약의 진행성 핵상마비(PSP) 치료제 후보물질의 식품의약품안전처 조건부 허가 신청 소식 이후 꾸준히 오름세를 보이고 있다. 한미약품(128940)은 개발 중인 비만 치료제 유통 계약을 체결하면서 본격적인 글로벌 무대 진출을 알렸고 이에 주가가 10% 가량 상승했다.비엘팜텍 주가 추이. (사진=KG제로인 엠피닥터)비엘팜텍, 5연상…분자접착제 주목KG제로인 엠피닥터(MP DORTOR·옛 마켓포인트)에 따르면 이날 비엘팜텍 주가는 장 초반부터 상한가로 직행했다. 비엘팜텍은 이날까지 상한가를 기록하면서 22일부터 5거래일 연속으로 상한가를 달성했다. 비엘팜텍 주가 상승세는 분자접착제 플랫폼의 기술수출 협상이 점차 구체화된 데 따른 것으로 분석된다.팜이데일리는 지난 15일 <''시총 6·11·26조 기업들과 동시 협상''… 비엘팜텍, 분자접착제로 조 단위 빅딜 정조준> 제목의 기사를 유료 회원에게 선공개했다. 이후 해당 기사는 22일 포털사이트에 무료로 풀리면서 투자자들의 관심이 집중된 것으로 보인다.기사에 따르면 비엘팜텍은 현재 국내 바이오 기업 3곳과 분자접착제 기술수출 협상을 진행하고 있다. 계약을 위해 논의 중인 상대들의 현재 시총은 각각 6조원, 11조원, 26조원으로 국내 투자자들에게는 익숙한 기업으로 전해진다.분자접착제는 단순 파이프라인이 아니라 기존 항체, 항체약물접합체(ADC), 표적치료제 등에 붙여서 약효를 증폭시키는 플랫폼 기술이다.비엘팜텍은 ‘비엘멜라니스’라는 자회사를 보유(지분 34.91%) 중인데, 비엘멜라니스의 분자접착제 기술은 지난해 11월 다국적 제약사 암젠(Amgen)이 주최하는 ‘2025 골든티켓’ 프로그램에서 최종 수상자로 이름을 올리면서 주목을 받았다.비엘팜텍은 분자접착제 플랫폼 기술 뿐 아니라 ML301, ML302 등의 파이프라인도 보유 중인데, 임상을 직접하는 것은 자금적으로 무리가 있는 만큼 조건이 맞는 파트너를 찾아 기술수출하는 것을 목표로 하고 있다.분자접착제 계열 기술에 대한 글로벌 제약사들의 관심은 거래 사례로도 확인된다. 지난해 유럽의 한 바이오 기업이 유사한 분자접착제 계열 기술을 베링거인겔하임에 수조원 규모로 거래한 바 있다. 이에 비엘팜텍은 기술수출 시 선급금만 최소 1000억원 이상 마일스톤 포함 총 계약 규모는 조 단위까지도 가능할 것으로 기대하고 있다.비엘팜텍 관계자는 “분자접착제 기술은 전 세계적으로 제대로 하는 곳이 몇 곳 없다”며 “보유한 플랫폼 기술은 암젠 내부 평가에서도 상당히 파워풀한 기술로 인정 받았다”고 말했다.젬벡스, GV1001 조건부 허가 기대 20% 이상 상승젬백스 주가는 전일 대비 21.82% 오른 4만1600원을 기록했다. 젬백스 주가는 최근 상승세를 보이고 있는데 지난 22일부터 약 78% 상승했다. 이는 최근 젬백스 관계사 삼성제약이 진행성핵상마비 치료제 후보물질을 식약처에 조건부 신청한 데 따른 것으로 분석된다.팜이데일리는 27일 <&ldquo;약 한번 맞아보고 죽고 싶다&rdquo;&hellip;젬백스, GV1001 조건부 허가 승부수> 기사를 통해 GV1001의 우수성과 시장성 등에 대해 분석했다.GV1001은 2024년 식약처로부터 개발단계 희귀의약품으로 지정받은 바 있다. 젬백스에 따르면 이번 조건부 허가 신청은 진행성핵상마비 리처드슨 신드롬(이하 PSP-RS) 유형을 적응증으로 한다. 조건부 허가는 생명을 위협하는 암 등 중증 질환이나 희귀질환 치료제에 대해 2상 임상시험 결과를 근거로 우선 시판을 허가하지만 출시 후 3상 임상시험 결과를 제출해야한다.삼성제약은 젬백스와 계약을 통해 한국을 포함한 아시아 주요 4개국에서 GV1001의 임상 개발 및 상업화 권리를 확보했다.GV1001은 국내 2상 임상 시험에서 우수한 내약성과 함께 질환 진행 속도를 늦추는 경향성을 보였다. 이어 이뤄진 12개월 연장 임상시험까지 합산한 72주 데이터 분석에서는 PSP-RS 유형 환자군을 대상으로 PSP 등급 척도(PSP-rating scale) 총점 변화량을 분석한 결과, 저용량(0.56㎎)군에서 외부 대조군 대비 통계적 유의성이 확인됐다.특히, GV1001은 미국 식품의약국(FDA)으로부터 패스트트랙 및 희귀의약품 지정을 받았으며 유럽의약품청(EMA)에서도 희귀의약품 지정을 받아 글로벌 임상시험 시 다양한 혜택 및 지원을 받을 수 있다.젬백스 관계자는 “글로벌 시장에서 신약이 상업화될 때까지 삼성제약과 긴밀히 협력해 나갈 것”이라고 밝혔다.한미약품, 국산 비만약 첫 글로벌 발판 마련한미약품 주가는 장 중 15.79% 오르며 55만원으로 52주 신고가를 기록했다. 그러나 이후 조금씩 주가가 빠지면서 최종적으로는 9.26% 오른 51만9000원으로 장을 마감했다. 이날 한미약품 주가 상승은 국산 비만 치료제 중 최초로 해외 무대 진출 발판을 마련한 데 따른 것으로 분석된다.이날 한미약품은 멕시코 제약사 산페르(Laboratorios Sanfer)와 GLP-1 비만 치료제 ‘에페글레나타이드’를 포함해 당뇨 치료 복합제인 ‘다파론 패밀리’ 등에 대한 독점 유통 계약을 체결했다고 밝혔다.계약에 따라 한미약품은 에페글레나타이드와 한미의 대표 당뇨 치료제 라인업인 다파론 패밀리(다파론정·다파론듀오서방정) 완제품을 공급하며 산페르는 멕시코 내 허가, 마케팅, 유통 및 판매를 담당한다.멕시코는 비만 유병률이 36.86%에 달하는 대표적인 고비만 국가다. 당뇨 유병률은 16.4%를 기록하고 있다. 체중 감량 및 이후 유지 요법 단계에서의 혈당 관리 수요 역시 높은 시장 특성을 지닌 만큼, 에페글레나타이드의 글로벌 확장성과 전략적 가치가 높다는 판단이 이번 계약에 반영됐다.계약 상대방인 산페르에 대한 기대감도 높다. 산페르는 멕시코 최대 민간 제약기업으로 중남미 전역에 걸친 견고한 영업·유통 네트워크와 자체 연구개발 역량을 바탕으로 업계를 선도하고 있다. 현재 멕시코를 포함한 중남미 20여 개국과 미국에서 사업을 전개하고 있으며, 최근 바이오의약품 기업 프로바이오메드(Probiomed) 인수를 통해 멕시코 최대 바이오의약품 기업으로 부상했다.한미약품 관계자는 “에페글레나타이드와 대사질환 치료제 전반에 대한 협력을 단계적으로 확대할 계획”이라며 “중장기적으로는 추가 제품 도입과 공동 마케팅 전략 등에 대해서도 논의해 나갈 것”이라고 말했다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006213524', 'https://imgnews.pstatic.net/image/018/2026/02/05/0006213524_001_20260205080211314.jpg?type=w800', 'NEWS_BIO', NULL, '2026-02-05 08:02:11', 0, true, '2026-03-09 05:44:08.420912') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (558, '“약 한번 맞아보고 죽고 싶다”…젬백스,  GV1001 조건부 허가 승부수', '이 기사는 2026년01월27일 08시20분에팜이데일리 프리미엄 콘텐츠로 선공개 되었습니다.[이데일리 김지완 기자] “환자들이 회사로 전화를 합니다. ‘약 한 번만 맞아보고 죽으면 안 되냐’고요. 어떤 분은 소동까지 일으켰습니다.”김상재 젬백스 고문(창업주)이 이데일리와 경기도 성남시 본사에서 인터뷰를 진행하고 있다. (사진=김지완 기자)김상재 젬백스 고문의 목소리는 차분했지만 그 안에는 절박함이 묻어 있었다. 젬백스(082270)의 계열사인 삼성제약(001360)이 최근 진행성핵상마비(PSP) 치료제 후보물질 GV1001에 대해 식품의약품안전처에 조건부 허가를 신청한 배경이다.PSP란 파킨슨병과 유사한 증상을 보이지만 진행 속도가 훨씬 빠르고 평균 생존 기간도 짧은 희귀 신경퇴행성 질환을 말한다. 현재까지 전 세계적으로 승인된 치료제가 단 하나도 없다. 진단을 받으면  병의 경과를 되돌릴 방법조차 없어 의료진조차 할 수 있는 일이 거의 없다. 사실상 ‘죽음을 기다리는 시간’만 남는 병이다.김 고문은 “환자 입장에서 1년 반 뒤에 약이 나온다는 말은 우리에게 ‘30년 뒤에 나온다’는 말과 다를 게 없다”며 “이미 병이 상당히 진행된 환자들에게 1년은 10년, 20년과 같은 시간”이라고 말했다.이데일리는 지난 21일 김상재 젬백스 고문(창업주) 단독 인터뷰를 통해 GV1001의 PSP 조건부 허가 신청 배경에 대해 자세히 물어봤다.“임상 끝까지 기다리면…그 사이 환자들은 다 떠난다”젬백스는 당초 임상 3상까지 완료한 뒤 정식 허가를 고려했다. 문제는 시간이었다.그는 “임상 3상까지 가면 최소 1년 반~2년이 걸린다. 그 사이에 환자들은 기다리지 못한다”며 “두 번 허가 자료 만드는 등 회사 입장에서도 업무가 훨씬 번거로운 걸 알면서도 조건부 허가를 택했다”고 설명했다.PSP는 증상 발병 후 생존기간을 통상 5~7년으로 본다. 하지만 대부분 진단까지 지연이 흔해 ''진단 후 생존''을 더 짧게 보이는 연구도 있다. 일부에선 PSP 진단 후 중앙생존이 약 1.8년으로 발표했다.젬백스는 과거 췌장암 치료제 개발 과정에서 조건부 허가 관련 절차를 경험했다. 젬백스는 이번 PSP 조건부 허가 신청을 위해 법률 검토는 물론 규제 당국 출신 자문 인력들과의 사전 검토를 거쳤다. 하지만 결정적 이유는 환자들의 절박한 요구였다.“보라매병원에서 임상에 참여했던 환자들이 ‘약을 더 맞게 해달라’고 합니다. 공급은 제한돼 있고, 회사로는 편지와 메일이 계속 옵니다. 읽다 보면 정말… 눈물 나는 사연이 많습니다.”2년 넘게 진행 멈춘 환자들…“이런 경우는 처음 봤다”GV1001의 임상 결과는 의료진들에게도 충격에 가까웠다.김 고문은 “현재 약을 맞고 있는 환자 중에는 2년이 넘도록 병의 진행이 멈춘 분들이 있다”며 “40점, 50점, 60점대 점수였던 환자들이 2년이 지나도 그대로거나 오히려 좋아지는 경우도 있다”고 말했다.PSP는 통상적으로 점수가 60점 수준에 도달하면 2년 내 사망으로 이어지는 경우가 대부분이다. 그런데 이 환자들은 그 시간의 시계가 멈춰버린 것이다.PSP는 증상이 복잡하고 진행 속도가 빠른 대표적인 신경퇴행성 희귀질환이다. 이 병의 중증도와 진행 상태를 객관적인 숫자로 평가하기 위해 국제적으로 가장 널리 쓰이는 지표가 바로 진행성핵상마비(PSP-RS, Progressive Supranuclear Palsy Rating Scale)다.PSP-RS는 총 28개 평가 항목으로 구성돼 있다. 0점(정상)에서 최대 100점(가장 중증)까지 점수가 올라간다. 점수가 높을수록 병이 더 많이 진행됐고 일상생활이 더 크게 제한돼 있다는 의미다.PSP-RS 환자군에서 PSP-RS 총점은 보통 연간 9~12점(평균 진행 속도는 연 11.3점) 정도 악화하는 것으로 자주 보고된다. PSP-RS 40~49점 구간의 3년 생존율이 41.9%인 반면 4년 생존율은 17.9%로 더 낮아진다. 또 다른 예후 연구에선  PSP-RS가 50점대인 환자에서 앞으로 최소 3년 더 생존할 확률을 약 26%로 계산했다.그는 “김종민 분당서울대병원 교수, 이지영 서울보라매병원 교수처럼 굉장히 보수적인 분들조차 (GV1001 투약 후) ‘(PSP 환자가) 이렇게 좋아지는 경우는 처음 본다’고 말할 정도”라며 “힘들게 걷던 분이 다시 또박또박 걸어 들어오고 말이 어눌하던 분이 또렷하게 말하는 걸 보고 의료진이 더 놀랐다”고 전했다.“치료제 부재…부작용 없고 대체약도 없다”시장 환경은 GV1001에 절대적으로 유리하다. 지구촌 어디에도 시판 중인 PSP 치료제는 없다. 경쟁 약물도 대체 치료 옵션도 없다. 게다가 GV1001은 지금까지 의미 있는 부작용 사례가 보고되지 않았다.김 고문은 “시장에 약이 없고 독성도 없고 효과까지 있다면 ‘물약이라도 팔린다’는 말이 나올 정도”라며 “미국과 유럽 쪽에서도 ‘이거 패스트트랙 아니냐’는 얘기가 나올 만큼 결과가 좋다”고 말했다.실제로 글로벌 데이터 기준으로 PSP 환자는 16개국 합산 약 37만명으로 추정된다. 이 중 1%만 시장에 진입해도 약 6억달러(8644억원) 규모가 된다. 현재 희귀 신경질환 치료제들의 연간 약가는 1인당 15만~20만달러(2억1610만~2억8814만원)수준으로 알려졌다. 바이오젠의 칼소디는 21만달러(3억원), 아밀릭스는 16만달러(2억3043만원) 선에 이른다.김 고문은 “GV1001이 3상에서 더 좋은 결과를 낸다면 더 높은 약가도 가능하다”고 내다봤다.“조건부 허가 후 환자 위한 길 찾겠다”문제는 높은 가격으로 인한 접근성이다. 조건부 허가를 받더라도 건강보험 급여 적용까지는 시간이 걸린다. 환자 입장에서는 연간 수억원에 달하는 비용이 부담이다.그는 “국내외 전역에서 연구자 임상, 추가 임상, 연구 프로그램을 최대한 활용해 환자들이 약을 맞을 수 있는 길을 최대한 열어보려 한다”며 “비싼 약가로 환자들이 전혀 접근 못 하면 그건 너무 잔인한 일”이라고 말했다.특히 GV1001을 맞고 2년 넘게 생존하며 병의 진행이 멈춘 환자들에 주목했다.김 고문은 “PSP는 점수가 곧 사망과 직결된다. 그 점수가 2년 넘게 멈춰 있다는 건, 이미 생존기간이 연장되고 있다는 뜻이다. 그 자체로 GV1001의 전체 생존기간(OS) 데이터”라고 표현했다.그는 “김종민 교수가 GV1001에 대해 ‘PSP를 10년을 늦추는 약’이라고 말한 것도 그냥 홍보용 멘트가 아니다"라며 "수십 년 환자를 본 사람이 그렇게 말할 정도면, 진짜 뭔가를 본 것”이라고 강조했다.김 고문은 인터뷰 내내 ‘시장’보다 ‘환자’를 먼저 이야기했다. 젬백스의 이번 조건부 허가 신청은 단순히 바이오 기업의 승부수가 아니다. 시간과 싸우는 환자들에게 건네는 마지막 치료 기회이기도 하다.“우리 전략이 중요한 게 아닙니다. 지금 (국내에) 살아 있는 2000명 모두 다 소중한 사람들입니다. ‘약 한번 맞아보고 죽고 싶다’는 말을 듣는데 회사가 가만히 있을 수 있겠습니까.”', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006211971', 'https://imgnews.pstatic.net/image/018/2026/02/03/0006211971_001_20260203082217438.jpg?type=w800', 'NEWS_BIO', NULL, '2026-02-03 08:22:17', 0, true, '2026-03-09 05:44:08.420912') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (559, '[서울데이터랩]금일 코스피 거래량 1위 SK증권 거래대금 354억 돌파', '코스피 거래량 상위 종목들이 전반적으로 엇갈린 흐름을 보인다.2일 한국거래소에 따르면, SK증권(001510)이 3,768만주 이상 거래되며 코스피 종목 중 실시간 거래량 1위를 차지하고 있다. 현재 주가는 881원이며, 시가총액 대비 거래대금 비율은 약 8.5%로 매우 높은 수준이다. 이는 매수와 매도세가 치열한 공방을 벌이고 있음을 시사한다. SK증권의 등락률은 -7.07%로 하락세를 보이고 있으며, PER 110.12, ROE -13.91로 다소 부진한 재무 지표를 나타내고 있다. 삼성전자(005930)는 20,532,511주의 거래량으로 뒤를 잇고 있으며, 현재 주가는 152,900원이다. 삼성전자의 거래대금은 시가총액의 약 3.55%를 차지하고 있으며, 등락률은 -4.74%로 하락하고 있다. PER 31.75, ROE 9.03으로 안정적인 재무 상태를 유지하고 있다.한화갤러리아(452260)는 1,914원으로 5.11% 상승하며 거래량 13,006,215주를 기록했다. 대성산업(128820)은 8,250원으로 12.24% 급등하며 11,532,364주가 거래되고 있다. 제주은행(006220)은 16,990원으로 19.90% 급등하며 9,930,048주의 거래량을 보인다. 퍼스텍(010820)은 4,670원으로 5.30% 상승, 진원생명과학(011000)은 2,030원으로 5.78% 상승했다. 삼성중공업(010140)은 27,700원으로 5.94% 하락하고 있으며, 세이브존I＆C(067830)는 3,060원으로 1.13% 하락하고 있다. 한화시스템(272210)은 95,100원으로 0.96% 상승 중이다.한편 거래량 상위 20위권 종목들은 한화투자증권(003530) ▼5.37%, 애경케미칼(161000) ▲7.05%, 대한해운(005880) ▲0.97%, 현대비앤지스틸(004560) ▲22.70%, 한온시스템(018880) ▼1.22%, SK하이닉스(000660) ▼6.71%, 미래에셋증권(006800) ▼5.96%, 두산에너빌리티(034020) ▼3.53%, 삼성제약(001360) ▲0.28%, 신성이엔지(011930) ▼1.69% 등의 성적을 기록했다.특히 주목할 만한 종목으로는 제주은행과 현대비앤지스틸이 있다. 제주은행은 19.90%의 급등세를 보이며, 거래대금이 시가총액의 25.37%에 달해 매수세가 강하게 유입되고 있다. 반면 SK증권은 거래대금이 시가총액 대비 8.5%에 달함에도 불구하고 7.07% 하락하는 모습을 보인다. 이는 투자자들 사이에서의 매도 압력이 크다는 것을 의미할 수 있다.전체적으로 시장은 엇갈린 흐름을 보이고 있다. 거래대금이 시가총액의 2%를 초과하는 종목이 다수 발견되며, 이는 투자자들의 매매가 활발하게 이루어지고 있음을 나타내고 있다. 특히 급등과 급락을 보이는 종목들이 주목받으며, 투자자들의 관심이 집중되고 있다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003613625', 'https://imgnews.pstatic.net/image/081/2026/02/02/0003613625_001_20260202131214944.png?type=w800', 'NEWS_BIO', NULL, '2026-02-02 13:12:14', 0, true, '2026-03-09 05:44:08.420912') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (560, '[서울데이터랩]금일 코스피 거래량 1위 SK증권 거래대금 2,346억 돌파', '코스피 거래량 상위 종목들이 전반적으로 엇갈린 흐름을 보인다.30일 한국거래소에 따르면, SK증권(001510)이 2억 3천만주 이상 거래되며 코스피 종목 중 실시간 거래량 1위를 차지하고 있다. 현재 주가는 1,015원이며, 시가총액 대비 거래대금 비율은 약 4,894%에 달하는 2,346억 8,700만원으로 매우 활발한 거래가 이루어지고 있다. 등락률은 13.53%로 급등하고 있으며, PER은 126.88, ROE는 -13.91로 재무 지표에서는 다소 불안정한 모습을 보인다. 이어 삼성전자(005930)는 거래량 2,309만 1,916주를 기록하며 2위를 차지하고 있으며, 현재 주가는 162,300원으로 시가총액 대비 거래대금 비율은 약 3.92%이다. 등락률은 1%로 횡보하고 있으며, PER 33.70, ROE 9.03으로 재무 안정성을 나타내고 있다.3위부터 10위까지의 종목들은 다음과 같다. 3위 미래에셋증권(006800)은 42,800원에 4.77% 상승하며 1,038만 6,251주가 거래되었다. 4위 상상인증권(001290)은 770원으로 1.28% 하락, 5위 삼성제약(001360)은 1,815원으로 4.43% 상승, 6위 남선알미늄(008350)은 1,257원으로 1.45% 상승, 7위 흥아해운(003280)은 1,729원으로 0.23% 하락, 8위 대한전선(001440)은 28,950원으로 2.30% 상승했다. 9위 한화투자증권(003530)은 6,480원으로 1.97% 하락, 10위 한국ANKOR유전(152550)은 216원으로 1.89% 상승하고 있다.한편 거래량 상위 20위권 종목들은 조일알미늄(018470) ▲1.15%, 대원전선(006340) ▼1.31%, 두산에너빌리티(034020) ▼3.24%, SK하이닉스(000660) ▲4.99%, 신성이엔지(011930) ▼0.83%, 대덕전자(353200) ▲22.67%, 한온시스템(018880) ▼1.50%, 다이나믹디자인(145210) ▼13.96%, KG모빌리티(003620) ▼0.77%, 한미반도체(042700) ▲4.42% 등의 성적을 기록했다.주목할 만한 종목으로는 대덕전자와 SK하이닉스가 있다. 대덕전자는 64,400원에 거래대금 300,479백만원을 기록하며 22.67%의 폭등세를 보인다. SK하이닉스는 904,000원에 거래대금 4,319,886백만원으로 4.99%의 상승률을 기록하고 있다. 반면, 다이나믹디자인은 419원에 거래대금 1,723백만원을 기록하며 13.96%의 급락세를 보이고, 한화투자증권은 6,480원에 거래대금 44,244백만원으로 1.97% 하락세를 보인다.전체적으로 코스피 시장은 종목별로 혼재된 흐름을 보이며 투자자들의 매수와 매도세가 맞물려 활발한 거래가 이어지고 있다. 일부 종목에서는 큰 폭의 가격 변동이 발생하고 있어 투자자들의 주의가 요구된다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003613101', 'https://imgnews.pstatic.net/image/081/2026/01/30/0003613101_001_20260130125018383.png?type=w800', 'NEWS_BIO', NULL, '2026-01-30 12:50:18', 0, true, '2026-03-09 05:44:08.420912') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (561, '복잡한 코딩 몰라도 … 말 한마디로 세련된 홈피 만들죠', '미국 AI 코딩기업 고투엑스이승주 창업자 인터뷰"무신사 같은 패션몰 만들어줘"자연어로 요구사항 입력하면10여분 만에 홈페이지가 뚝딱공연플랫폼부터 기업 ERP까지제작과 동시에 즉시 접속 가능''바이브 코딩'' 게임체인저 급부상2040년 478조원 폭발적 성장''무신사 같은 패션 쇼핑몰을 만들고 싶다. 웹사이트는 깔끔하고 세련된 톤으로. 카테고리별로 상품의 이미지, 가격 정보 담아주고. 결제 기능도 넣어줘.''기획서도, 디자인 시안도, 개발자도 없었다. 기자가 한 일은 바이브코딩 플랫폼 ''바이브엑스(Vibe X)'' 대화창에 간단한 프롬프트를 입력한 것이 전부였다. 10분쯤 지났을까. 화면에는 제법 그럴듯한 패션 커머스 사이트가 펼쳐졌다. 상품 페이지와 장바구니, 결제 기능까지. 무신사 쇼핑몰 페이지와 비교해도 손색이 없어 보였다. 대화창에 ''관리자 화면도 함께 만들어줘''라고 입력하자 상품과 콘텐츠를 운영할 수 있는 그룹웨어 성격의 백오피스(CMS·콘텐츠 관리 시스템)까지 곧바로 완성됐다. 이 모든 작업이 코딩 없이, 몇 줄의 문장으로, 10여 분 만에 이뤄졌다.지난 20일 서울 서초동 소재 TDI타워 스튜디오에서 인공지능(AI) 코딩 기업 ''고투엑스(GotoX)''의 시연회가 열렸다. 고투엑스가 개발한 엔드투엔드 바이브코딩(end-to-end Vibe Coding) 플랫폼 ''바이브엑스''가 한국에서 처음 공개된 자리였다. 웹이나 앱의 기획부터 디자인, 개발, 배포까지 전 과정을 하나의 대화 흐름으로 완성하는 방식은 행사장을 찾은 기업인과 투자자들의 시선을 단번에 사로잡았다. 고투엑스 창업자인 이승주 총괄 프로듀서(GP·사진)는 무대에 올라 "오늘은 프롬프트 하나로, 짧은 시간에 ''마법 같은 홈페이지''를 만드는 과정을 보여드리겠다"고 말했다. 그러면서 그는 "개발자들과 함께 작업할 때면 한 프로젝트에 3~4개월이 걸리기도 하는데, 오늘은 10~15분 안에 프로젝트의 상당 부분을 구현할 수 있다는 사실을 확인하실 수 있을 것"이라고 설명했다.현장에서 공개된 데모는 쇼핑몰에 그치지 않았다. 패션 커머스처럼 보이는 사이트를 만든 뒤 같은 방식으로 언론사 형태 뉴스 사이트, 기업 내부 관리용 시스템, 예약·주문 기능을 갖춘 여행 플랫폼까지 연속해서 생성하는 과정이 시연됐다. 사용자가 자연어로 요구 사항을 계속 던지면, 결과물은 요청대로 실시간 바뀌었고, 사이트 구성에 필요한 이미지와 기본 콘텐츠도 문맥에 맞춰 자동으로 채워졌다.특히 ''레퍼런스 기반 제작'' 장면이 눈길을 끌었다. 이 GP는 "말로 설명하기 어렵다면 원하는 사이트를 캡처해서 올린 뒤 ''이 이미지와 똑같이 만들어줘''라고 요청해도 된다"며 "이렇게 간단하고 누구나 손쉽게 할 수 있는 명령어 한 줄로 기사 작성·관리 같은 CMS까지 만들 수 있다"고 설명했다. 실제로 시연에서는 언론사 사이트 화면을 캡처해 업로드한 뒤 "캡처된 이미지와 같은 사이트를 만들어 달라"는 요청을 하자 CMS 구축이 단번에 이뤄졌다.''운영까지 포함한 완성''도 바이브엑스가 꼽는 장점이다. 쇼핑몰을 만들더라도 결국 운영이 문제인데 상품·콘텐츠·사용자 등을 관리하는 백오피스가 함께 붙어야 서비스가 제대로 굴러간다. 이 GP는 쇼핑몰 데모에서 "무신사 같은 의류 쇼핑몰을 만들어줘"라는 요청에 더해 "운영을 위한 ERP(전사 자원 관리) 성격 시스템도 함께 구성해달라"고 하자 오래지 않아 ERP 페이지가 생성됐다. 그는 "예전엔 급한 대로 저작권을 생각하지 않고 남의 이미지를 끼워 넣곤 했는데, 지금은 필요한 이미지를 AI가 즉시 생성해서 채우는 단계로 넘어가고 있다"고 말했다.웹페이지 완성 즉시 바로 사업에 이용할 수 있는 것도 강점이다. 이 GP는 첫 번째 데모 결과물이 생성되자 "우리는 별도의 게시(배포) 절차를 밟지 않고, 바로 웹으로 결과물이 공개된다"며 "임시 도메인이 자동으로 생성되기 때문에 도메인만 사면 바로 사업 운영에 들어갈 수 있다"고 설명했다. 실제 화면에서는 결과물이 생성되는 즉시 브라우저에서 접속 가능한 형태로 게시돼 제작과 배포가 하나의 흐름으로 붙는 장면이 연출됐다.이날 행사에는 비개발자 경영진이 직접 무대에 올라 바이브엑스를 시연하는 세션도 마련됐다. 정성택 삼성제약 대표는 시연 직후 "평생 제약 산업 현장에서 신약 개발과 경영에만 몰두해 코딩 자체는 늘 낯선 영역이었다"며 "뇌리에 있는 사업 구상을 말로 설명했을 뿐인데, 전문가가 만든 것 같은 웹사이트가 바로 구현되는 걸 보고 경영의 속도가 완전히 달라질 수 있겠다고 느꼈다"고 말했다. ''오페라의 유령'' ''알라딘'' 등 유명 공연 콘텐츠를 제작·유통하는 클립서비스(ClipService)의 안영복 부장은 "''뮤지컬 포털 사이트 만들어줘''라고 입력했을 뿐인데, 공연 일정과 예매 흐름, 커뮤니티 같은 요소까지 한 번에 만들어졌다"며 "보통 이 같은 수준의 사이트를 만들려면 최소 6개월에서 1년이 걸리는데, 시간을 획기적으로 줄일 수 있겠다는 생각이 들었다"고 평가했다.이 GP가 반복해서 강조한 점은 ''진입장벽의 변화''다. 그는 "그냥 생각나는 대로 짧게 명령어를 쓰기만 하면 된다"며 "중요한 대목은 ''무엇을 만들지''에 대한 의도를 던지는 것"이라고 말했다. 이날 시연은 여러 프로젝트를 동시에 생성해 돌린 뒤 생성이 끝난 결과물을 순차적으로 공개하는 방식으로 진행됐다. 단시간에 복수의 정교한 웹사이트와 운영 시스템을 함께 구현할 수 있는 가능성을 보여줬다는 점에서 참가자들의 높은 관심을 이끌어냈다.이 GP는 바이브코딩의 변화를 ''실행 방식의 재편''으로 정리했다. 그는 "몇 줄의 문장으로 쇼핑몰을 만들고, 같은 방식으로 언론사 사이트나 기업 운영 시스템까지 확장할 수 있게 되면 개발의 중심이 코드에서 사람의 ''의도''로 온전히 이동하게 될 것"이라며 "기업은 무엇을 만들 것인지 더 빠르게 검증하고 수정하게 되고, 그 과정이 의사결정 속도와 사업 실행 구조를 다시 짜게 될 것"이라고 말했다.또한 이날 행사에서는 바이브엑스의 한국 사업 대행을 맡은 ''레버리지히어로''의 김일신 대표도 무대에 올라 서비스를 소개하는 시간을 가졌다. 김 대표는 "한국 시장에서 바이브엑스의 보급과 운영은 레버리지히어로가 전담하게 될 것"이라며 국내 사업 계획을 밝혔다.바이브 코딩 시장 전망은 밝다. 소프트웨어 개발 시장의 패러다임이 ''코드 중심''에서 ''의도(Vibe) 중심''으로 완전히 넘어갈 것으로 예상되기 때문이다. 시장조사기관 루츠 애널리시스(Roots Analysis)에 따르면 글로벌 바이브 코딩 시장은 2025년 29억6000만달러(약 4조3560억원)에서 2040년 3250억달러(약 478조3350억원) 규모로 100배 이상 성장할 전망이다. 이 GP는 "''말해보면 만들어진다''는 서비스 철학처럼 직관적인 경험을 통해 사람의 일상 깊숙이 스며드는 글로벌 플랫폼으로 진화해 나갈 것"이라며 "바이브엑스를 글로벌 코딩 산업의 게임체인저로 지켜봐 달라"고 강조했다.바이브 코딩 (Vibe Coding)개발자가 복잡한 프로그래밍 언어의 문법(Syntax)을 직접 작성하는 대신 자연어 명령어를 통해 소프트웨어의 목적, 기능, 디자인적 ''느낌(Vibe)''을 전달하면 인공지능(AI)이 코드를 자동 생성하고 즉시 실행까지 이행하는 차세대 개발 방식.[김대기 기자 / 사진 한주형 기자 ]', NULL, '매일경제', 'https://n.news.naver.com/mnews/article/009/0005627430', 'https://imgnews.pstatic.net/image/009/2026/01/26/0005627430_001_20260126160725279.jpg?type=w800', 'NEWS_BIO', NULL, '2026-01-26 16:07:09', 0, true, '2026-03-09 05:44:08.420912') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (563, '삼성제약, 식약처에 PSP 치료제 ‘GV1001’ 조건부 허가 신청', '삼성제약(001360)은 식품의약품안전처(이하 식약처)에 진행성핵상마비(이하 PSP) 치료제 ‘GV1001’의 품목 조건부 허가를 신청했다고 20일 밝혔다.삼성제약에 따르면 이번 조건부 허가 신청은 진행성핵상마비 리처드슨 신드롬(이하 ‘PSP-RS’) 유형을 적응증으로 하며, 조건부 승인을 받을 경우 식약처 조건에 따른 임상시험을 시행해야 한다.조건부 허가는 생명을 위협하는 암 등 중증 질환이나 희귀질환 치료제에 대해 2상 임상시험 결과를 근거로 우선 시판을 허가하되, 출시 후 3상 임상시험 결과 제출을 조건으로 허가하는 제도이다.삼성제약 로고삼성제약은 2025년 12월 젬백스앤카엘과 기술이전을 통해 한국을 포함한 아시아 주요 4개국에서 PSP 치료제 GV1001의 임상 개발 및 상업화 권리를 확보했다.PSP 치료제 GV1001은 2024년 식약처로부터 개발단계 희귀의약품으로 지정받았다. 삼성제약은 조건부 허가 취득 시, 의료 현장에 약물이 신속히 공급될 수 있도록 한다는 계획이다.', NULL, '지디넷코리아', 'https://n.news.naver.com/mnews/article/092/0002406869', 'https://imgnews.pstatic.net/image/092/2026/01/20/0002406869_001_20260120172712056.jpg?type=w800', 'NEWS_BIO', NULL, '2026-01-20 17:27:12', 0, true, '2026-03-09 05:44:08.420912') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (564, '바이젠셀, 세포치료제 조건부 허가 가능성에  上...대화제약도 급등[바이오맥짚기]', '이 기사는 2025년12월09일 08시00분에팜이데일리 프리미엄 콘텐츠로 선공개 되었습니다.[이데일리 송영두 기자] 바이젠셀이 세포치료제 ‘VT-EBV-N’ 임상 2상에 성공한 여파로 주가 상승세가 지속되고 있다. 특히 8일에는 상한가까지 치솟았다. 내년 상반기 국내서 조건부 허가 가능성과 품목허가시 세계 최초 자연살상/티(NK/T) 세포치료제 상용화라는 타이틀로 시장 선점이 가능할 것으로 평가받으면서 투심도 움직이는 모양새다.젬백스앤카엘로부터 진행성핵상마비(PSP) 치료제 ‘GV1001’를 도입한 삼성제약도 주가가 상한가를 기록했다. 대화제약도 이날 중국 시장 진입 가속화 가능성이 제기되면서 상한가에 근접한 급등세를 나타냈다.바이젠셀 주가 추이.(자료=KG제로인 엠피닥터)바이젠셀, 1111 거래일 연속 주가 상승세8일 KG제로인 엠피닥터(MP DORTOR·옛 마켓포인트)에 따르면 바이젠셀(308080)은 이날 주가가 전일 대비 30%(3060원) 오른 1만3260원을 기록했다. 최근 바이젠셀은 11거래일 연속 주가 상승세를 나타냈다. 11월 24일 전일 대비 140원 오른 3270원을 기록한 후 이날까지 주가가 상승했는데, 신약 임상 2상 성공 소식 후 향후 모멘텀에 대한 기대 심리가 상한가까지 이끌었다는 분석이다.실제로 바이젠셀은 지난달 25일 NK/T 세포림프종 치료제로 개발 중인 ‘VT-EBN-N’ 임상 2상 톱라인 데이터를 발표했다. 투약 완료 후 2년간의 경과 관찰에 대한 수치가 핵심인데 임상적 유효성과 안전성을 입증했다.서울성모병원을 포함한 전국 13개 의료기관에서 환자 48명을 대상으로 무작위배정·이중맹검 방식으로 진행된 임상 2상에서 1차 유효성 평가 변수인 2년 무질병생존(DFS)에서 투여군은 95.0%, 대조군은 77.58%로 나타났다. 두 군 간 차이는 통계적으로 유의미(p=0.0347)한 것으로 분석됐다.투여군에서는 재발 또는 사망 등 이벤트 발생률이 4.76%(1명)에 불과했다. 대조군은 32%(8명)로 나타났다. 이번 결과는 VT-EBV-N이 NK/T세포 림프종 환자의 장기 질병 억제에 의미 있는 효과를 보여준 것으로 평가받는다.특히 바이젠셀은 임상 2상 성공으로 조건부 허가 절차를 밟을 것으로 전망된다. 이미 회사는 해당 치료제에 대해 식품의약품안전처로부터 2019년 희귀의약품 지정을 받았다. 희귀의약품 지정을 받으면 품목허가 심사에서 우선 심사를 받을 수 있어, 허가까지 기간을 단축할 수 있다.이와 함께 대체 치료제가 없거나 생명이 위중한 질환으로 인정받을 경우 조건부 허가 신청도 가능하다. 투심은 신속한 상업화와 이에 따른 실적 모멘텀에 주목하고 있다. 바이젠셀 측은 상용화 5년 내 1000억원대 이상의 매출을 기대하고 있다. 아울러 바이젠셀은 중국 기업과 기술이전 협상도 재개할 것으로 예상된다.바이젠셀 측은 내년 상반기 정도에 신속처리 지정을 신청하고 이후 조건부 허가 신청을 계획하고 있다. 바이젠셀 관계자는 “금일 상한가는 지난달 세포림프종 치료제 임상 2상 결과 발표가 영향을 준 것으로 보고 있다. 임상 2상 후 모멘텀에 대한 투심이 작용한 것으로 판단한다”며 “그동안 회사 주가가 저평가돼 있던 부분도 영향을 끼친 것으로 보고 있다”고 말했다.그러면서 “VT-EBV-N 임상 2상 최종 결과보고서(CSR)는 내년 초에 나올 예정으로 CSR을 수령 후 상반기에 식약처에 신속처리 지정 신청을 하고 하반기에 조건부 허가를 신청할 것”이라며 “조건부 허가를 획득하면 세계 최초 NK/T 세포치료제를 상용화하게 된다"고 말했다.이어 "2027년 상용화를 예상하고 상용화 5년 차인 2031년에는 1200억원대 매출을 기대하고 있다"며 "과거부터 진행하던 중국 기업과 기술이전 협의도 재개할 예정”이라고 설명했다.PSP 치료제 ‘GV1001’ 도입한 삼성제약, 적응증 확장 기대감최근 젬백스(082270)앤카엘은 삼성제약(001360)에 진행성 핵상마비(PSP) 치료제 ‘GV1001’을 기술이전 했다. 아시아 주요 4개국에 대한 임상 개발 및 상업화 권리를 선급금 115억원 포함 총 2200억원에 넘겼다.이번 계약으로 삼성제약은 기존 알츠하이머를 적응증으로 한 GV1001에 이어 PSP 치료제까지 확보했다. 특히 한국, 일본, 인도, 인도네시아에 대한 권리를 획득하면서 파이프라인 강화와 글로벌 진출 국가 수를 늘렸다는 평가다. 이날 삼성제약 주가도 껑충 뛰었다. 직전 거래일 1364원이던 주가는 8일 상한가인 29.99%(409원) 오른 1773원으로 장을 마감했다.젬백스에 따르면 PSP 치료제 GV1001은 국내 2상 임상시험에서 우수한 내약성과 함께 질환 진행 속도를 늦추는 경향성을 보여준 바 있다. 이어서 진행된 12개월 연장 임상시험까지 합산한 72주 데이터 분석에서는 진행성핵상마비 리처드슨 신드롬(PSP-RS) 유형 환자군을 대상으로 PSP 등급 척도(PSP-rating scale)의 총점 변화량을 분석한 결과, 저용량(0.56mg)군에서 외부 대조군 대비 통계적 유의성을 확인했다.삼성제약 관계자는 “젬백스로부터 PSP 치료제를 도입하면서 알츠하이머 치료제에 이어 적응증 확장을 했다는 의미가 있다”며 “파이프라인 확장에 대한 모멘텀과 상용화에 대한 기대감이 작용하면서 주가가 강세를 보인 것으로 보고 있다”고 말했다.제약업계에서는 현재 젬백스가 추진 중인 PSP 치료제 임상 3상이 본격화하고 삼성제약이 판권을 확보한 한국과 일본, 인도, 인도네시아가 글로벌 임상 3상 사이트에 포함된다면 임상 3상 개발에 중추적인 역할을 할 수 있을 것으로 보고 있다.대화제약, 마시는 항암제 中서 가격 경쟁력 확보대화제약(067080)은 이날 경구용(마시는) 파클리탁셀 항암제 ‘리포락셀’이 중국 국가의료보장국(NHSA)이 발표한 2025년 국가급여의약품목록(NRDL)에 신규 등재됐다고 발표했다. 발표 직후 주가가 급등해 직전 거래일 대비 21.02%(4030원) 오른 2만3200원을 기록했다.대화제약 관계자는 “리포락셀이 중국에서 국가급여의약품목록에 등재되면서 주가가 영향받은 것으로 보고 있다”고 말했다. 리포락셀은 정맥주사 제형의 항암제를 경구용으로 제형을 변경한 개량 신약으로 지난해 9월 중국 국가약품감독관리국으로부터 위암 적응증으로 품목허가를 획득했다.올해 1월부터 비급여 판매가 이뤄졌지만 이번 보험 등재로 가격 경쟁력을 확보했다. 보험 적용으로 리포락셀은 300mg 기준 1208위안(약 25만원)의 약가가 확정됐다. 가격 경쟁력을 확보한 만큼 중국 시장에서 시장점유율 확대에 속도가 붙을 것이란 평가가 제기된다.대화제약 관계자는 “리포락셀액의 NRDL 등재는 대화제약의 기술력과 치료 혁신성을 중국 의료 시장에서 공식적으로 인정받은 중요한 성과”라며 “파트너사와의 긴밀한 협력을 통해 현지 시장에서의 실행력을 강화하고 글로벌 항암제 시장에서 대화제약의 위상을 한 단계 더 높이겠다”고 말했다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006184094', 'https://imgnews.pstatic.net/image/018/2025/12/16/0006184094_001_20251216080214058.jpg?type=w800', 'NEWS_BIO', NULL, '2025-12-16 08:02:14', 0, true, '2026-03-09 05:44:08.420912') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (565, 'SG글로벌, 지난해 영업익 50억…전년비 19.3% ↓', '[헤럴드경제=증권부] SG글로벌은 지난해 연결기준 영업이익이 49억6413만원으로 전년대비 19.3% 감소했다고 29일 공시했다.같은 기간 매출액은 934억8124만원으로 6% 줄어든 것으로 나타났다.당기순이익은 28억671만원으로 55.6% 감소한 것으로 집계됐다.', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002592843', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_AUTO', NULL, '2026-01-29 10:22:10', 0, true, '2026-03-09 05:44:30.348128') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (566, '"AI 데이터센터에 거품…지금은 美 아닌 中 테크기업 더 담아야"', '한경 인터뷰''유럽 최대 자산운용사'' 아문디운용 뱅상 모르티에 CIO인공지능 관련 투자, 과열된 상황머스크 ''우주 데이터센터'' 실현 땐지금보다 운영비 10분의 1로 줄어건설중인 데이터센터 가치 떨어질것美 투자 비중은 3분의 1이 적당달러 약세 신호…아시아 투자 늘려야중국 상위기업株, 미국 대비 절반값양자컴·로보틱스 관련 업체에 주목유럽 최대 자산운용사 아문디자산운용의 뱅상 모르티에 최고투자책임자(CIO)는 “데이터센터 등 일부 인공지능(AI) 관련주에 거품이 낀 게 사실”이라며 “시야를 넓혀 투자 업종과 지역을 다변화해야 할 시점”이라고 강조했다. 모르티에 CIO가 최근 서울 여의도 NH아문디자산운용 본사에서 한국경제신문과 인터뷰하고 있다.  임형택 기자인공지능(AI)산업이 거품인지 아닌지는 최근 국내 투자자 사이에서 초미의 관심시다. 미국 증시에 돈을 넣는 서학개미가 매달 최고 기록을 경신하는 가운데 상당수가 엔비디아, 구글 등 AI 관련주에 묶여 있어서다. 최근 방한한 뱅상 모르티에 아문디자산운용 최고투자책임자(CIO)에게 글로벌 시장 진단 및 AI 투자 전략을 들어봤다. 프랑스 아문디운용은 총 2조3170억유로(약 3945조원)를 굴리는 유럽 최대 자산운용사다.▷‘AI 거품’ 논란이 최근 일었는데요.“AI 기술 자체는 거품이 아닙니다. 오히려 새로운 시장을 개척하도록 해주는 중요한 기술이죠. 다만 투자 관점에선 과열됐다고 볼 수 있습니다. AI산업 전체는 아니지만 일부엔 거품이 끼어 있다고 분명히 얘기할 수 있죠.”▷일부 거품으로 판단하는 근거는 무엇입니까.“기술 변화가 빠르기 때문입니다. 몇 년 후에는 지금보다 훨씬 적은 에너지로 운영되는 데이터센터가 등장할 겁니다. 일론 머스크 테슬라 최고경영자(CEO)가 언급한 ‘우주 데이터센터’처럼요. 우주에선 냉각 비용이 거의 들지 않고, 태양 에너지를 바로 사용할 수 있어 운영비가 현재 대비 10분의 1로 줄어듭니다. 세계 곳곳에서 건설 중인 데이터센터의 경제적 가치가 크게 떨어질 겁니다.”▷‘거품 산업’을 구체적으로 꼽자면 어떤 게 있나요.“데이터센터를 포함해 하이퍼스케일러로 불리는 미국 대형 기술 기업이 중심입니다. 미국·유럽에서는 데이터센터에 대규모로 투자하고 있는데, 상당한 투자금이 부채를 통해 조달되고 있죠. 회계상 5~7년에 걸쳐 상각되면서 비용으로 인식됩니다. 문제는 지금 짓고 있는 데이터센터들은 곧 ‘구식’이 될 위험이 있다는 겁니다. 자산 가치가 하락한 뒤에도 해당 기업이 과연 부채를 안정적으로 상환할 수 있을까요?”▷또 어디가 과열됐을까요.“챗GPT, 제미나이 같은 대규모언어모델(LLM) 서비스 시장 경쟁도 매우 치열합니다. 다양한 기업에서 비슷한 서비스를 잇달아 내놓고 있죠. 결국 LLM은 범용재(commodity)가 될 겁니다. 사람들은 이 서비스를 구독하는 데 많은 돈을 지불하려 들지 않을 겁니다.”▷AI 반도체는 어떻습니까.“지금까지 AI산업의 핵심 동력은 반도체였죠. 앞으로도 계속 중요하겠지만 이 분야 기술 역시 빠르게 변하고 있습니다. 오늘의 승자가 내일의 승자가 될 것이라고 보장할 수 없다는 의미입니다. 최근 구글이 메타에 자체 칩을 공급하기로 하면서 메타의 엔비디아 의존도가 낮아진 것은 중요한 변화라고 할 수 있죠. 내가 투자한 기업의 마진(이익률)과 점유율이 10년 후에도 그대로일 것이라고 가정하는 건 위험한 판단입니다.”▷아직 투자 기회가 남은 곳이 있을까요.“AI 데이터센터를 구축하는 데 필요한 인프라와 에너지를 공급하는 기업을 선호합니다. 데이터센터는 기본적으로 엄청난 양의 에너지를 사용하기 때문이죠. AI 시장의 후방산업인 전력망과 재생에너지 등이겠죠. AI를 활용해 효율성을 크게 높일 수 있는 기업에도 기회가 있습니다. 제약·은행 업종이 대표적입니다.”▷미국 증시의 가장 큰 문제는 무엇입니까.“시장이 소수 종목에 지나치게 쏠려 있습니다. S&P500 내 10개 정도에 개인과 헤지펀드 자금이 집중됐습니다. 심지어 2~3배짜리 상장지수펀드(ETF), 단일종목옵션, 마진거래 등 레버리지를 낀 투자도 상당합니다. 시장이 하락하기 시작하면 손실이 급격히 불어나는 ‘눈덩이(snowball) 효과’가 생길 수 있죠. 마진콜로 강제 청산이 발생하고, 이게 또 다른 하락을 불러오며 거품이 와르르 무너질 겁니다. 최근 급락한 비트코인처럼요.”▷어떻게 대비해야 하나요.“답은 분산투자입니다. S&P500, 나스닥100 등 대표 지수조차 소수 종목에 집중됐죠. 시가총액과 관계없이 모든 종목에 동일한 비중을 부여한 ‘S&P500 동일 가중지수’에 투자하는 걸 추천합니다. 더 넓은 시장에 분산투자할 수 있습니다.”▷지금은 미국 비중을 낮춰야 할까요.“미국 비중을 더 높여선 안 된다고 생각합니다. 포트폴리오 중 3분의 1에서 최대 절반이 적당합니다. 달러는 장기적으로 약세를 보일 가능성이 높습니다. 미국 주식이 올라도 달러가 약세면 성과가 낮아질 수 있지요. 미국 재정적자는 국내총생산(GDP) 대비 6~7%로 높은데, 향후 줄어들 가능성은 작습니다. 미국 중앙은행(Fed)의 신뢰도 역시 달러 가치에 영향을 미치는데, 이 신뢰가 흔들릴 위험이 있죠.”▷그럼 어느 나라에 투자해야 하나요.“아시아 투자를 늘려야 합니다. 최소 4분의 1에서 3분의 1을 할애하는 게 좋습니다. 중국, 인도, 한국, 일본 모두 각자의 투자 매력이 있죠. 유럽은 상대적으로 덜 흥미로운 시장이지만 저렴합니다. 가치주와 배당주를 중심으로 투자하는 걸 추천합니다.”▷아시아에서 가장 유망한 곳은 어디입니까.“중국 기술 기업을 주목하고 있습니다. LLM 시장에서 점유율을 늘려나가는 등 혁신을 주도하고 있죠. 그런데도 중국의 상위 기술 기업은 미국의 절반 가격입니다. 중국인이 올 들어 주식을 사기 시작하면서 증시에 대규모 자금이 유입되고 있는 점도 긍정적입니다. 최근에는 민간 기업이 시장 혁신을 주도하고 있습니다. 시장 친화적 구조로 전환하고 있다는 의미죠.”▷어떤 중국 기업을 골라야 합니까.“양자컴퓨팅, 반도체, 바이오테크, 로보틱스 관련 기업을 긍정적으로 보고 있습니다. 특히 동남아시아를 비롯해 아시아 전역으로 수출하는 기업이 좋습니다. 텐센트, 알리바바 같은 빅테크보다 상대적으로 덜 알려졌지만 혁신적 기술을 보유한 종목에 더 많은 기회가 있을 겁니다.”▷한국 투자자에게 어떤 조언을 해주고 싶으신가요.“시장 변동성은 더 커질 수 있습니다. 이럴 땐 기본 원칙에 충실해야 합니다. 위험자산 대신 채권 비중을 늘리는 게 대표적이죠. 한국 국채, 회사채 모두 좋습니다. 채권은 이자수익이 있고, 만기까지 보유하면 가격 변동을 걱정할 필요가 없습니다. 전체 포트폴리오의 5~10%를 금으로 채워 변동성을 완충하는 것도 방법이죠. 한국 투자자라면 달러 약세에 대비해 환헤지를 하는 게 좋습니다.”■뱅상 모르티에는…△프랑스 ESCP 유럽경영대학원 경영학석사(MBA)△1996년 프랑스 투자은행 소시에테제네랄(SG) 감사 부문△2012년 SG 글로벌뱅킹 및 투자자 솔루션 부문 최고재무책임자(CFO)△2022년 아문디자산운용 최고투자책임자(CIO)△2023년 아문디자산운용 부사장△아문디자산운용 경영위원회 위원', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005218506', 'https://imgnews.pstatic.net/image/015/2025/12/01/0005218506_001_20251202004910386.jpg?type=w800', 'NEWS_AUTO', NULL, '2025-12-01 17:41:21', 0, true, '2026-03-09 05:44:30.348128') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (567, '“내 주식만 안 오른다”… 코스피 불장에도 중소형株 투자자는 ‘한숨’', '최근 코스피 지수가 사상 최고 행진을 이어가고 있지만, 중소형주는 상대적으로 저조한 수익률을 내고 있어 투자자들의 한숨이 커지고 있다.일러스트=손민균12일 한국거래소에 따르면 코스피는 지난 10일 전 거래일보다 1.73% 오른 3610.60에 거래를 마감했다. 이는 지난해 말(2399.49) 대비 50.5% 상승한 수치다.상장 기업 규모별로 보면 시가총액 상위 1∼100위권의 대형주로 구성된 코스피 대형주 지수는 올해 들어 54.7% 상승해 코스피 수익률을 웃돌았다. 이 지수를 구성하는 100개 종목 중 지난해 말 대비 상승한 종목은 87개로 하락 종목(11개) 수의 8배에 달했다.대표적으로 대형 반도체주의 상승세가 두드러졌다. 삼성전자는 올해 들어 주가가 5만3200원에서 9만4400원으로 77% 올랐다. 같은 기간 SK하이닉스도 17만3900원에서 42만8000원으로 146% 급등했다.반면 코스피 시총 상위 101위∼300위 종목으로 구성된 중형주 지수는 올해 들어 32.8% 올랐다. 이는 코스피 수익률(50.5%)을 밑도는 수치다.중형주 지수를 구성하는 200개 종목 중 72%에 해당하는 144개 종목이 올랐으며, 25%에 해당하는 50개가 하락했다. 중형주 내 하락 종목 비율(25%)은 대형주 내 하락 종목 비율(11%)의 2배를 넘었다.특히 코스피 소형주 지수는 올해 들어 16.8% 오르는 데 그쳤다. 같은 기간 코스피 상승률(50.5%)을 밑돈 데 이어, 코스피 대형주(54.7%)와 중형주 상승률(32.8%) 대비로도 모두 부진했다.코스피 소형주 지수를 구성하는 541개 종목 중 33%에 해당하는 179개 종목이 지난해 말 대비 주가가 하락했다. 이는 코스피 대형주 내 하락 종목 비율(11%)의 3배에 달한다.특히 소형주 중 이스타코 주가는 지난해 말 1899원에서 이달 들어 633원으로 66.7% 하락했다. 이밖에 인스코비(-53.9%), 일성건설(-64.8%), SG글로벌(-50.6%) 등 주가가 올해 들어 반토막이 됐다.상황이 이렇다 보니 대형 반도체주가 랠리를 이어가고 있는 반면 중소형주를 보유한 투자자는 ‘불장’에도 울상을 짓고 있다. 특히 투자자 중 국민연금 등 기관이나 외국인은 대형주 위주로 투자하는 데 비해 중·소형주에 상대적으로 많이 투자하는 개인에게는 쉽지 않은 투자 환경이라는 분석이 나온다.', NULL, '조선비즈', 'https://n.news.naver.com/mnews/article/366/0001113639', 'https://imgnews.pstatic.net/image/366/2025/10/12/0001113639_001_20251012091307165.jpg?type=w800', 'NEWS_AUTO', NULL, '2025-10-12 09:13:07', 0, true, '2026-03-09 05:44:30.348128') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (568, '[어제장 오늘장] 코스피, 상반기에만 28% 올랐다…서머랠리 이어질까', '■ 머니쇼 ''어제장 오늘장'' - 장연재7월의 첫날입니다.코스피 어제(30일) 상승하며 올해 상반기를 화려하게 마무리 지었습니다.상반기에만 28% 올라 2000년 이후 세 번째로 높은 반기 성적을 거뒀습니다.이런 상승세가 7월, 서머랠리로 이어질지 주목됩니다.7월엔 트럼프발 관세에 2분기 실적까지 고려해야 할 변수가 한층 많아지겠는데요.어제장 복기하면서 서머랠리가 가능할지 오늘(1일) 장 투자포인트도 체크하시죠.코스피 0.5% 상승해 3071선이었습니다.코스닥은 약보합으로 마감했습니다.코스피 이틀 하락 후 매수세가 유입되며 반등했는데요.이로써 6월 한 달간 상승률은 13.86%에 달해 4년 7개월 만에 월간 기준 최대 상승률을 기록했습니다.어제는 개인 수급을 중심으로 시장이 지지됐습니다.다만 코스피에서 외국인 대규모 매도세가 이어지며 지수 상승이 제한됐습니다.외국인 6500억 원 가까이 팔아냈습니다.기관은 4700억 원에 달하는 매수 우위를 기록했는데 금융 투자가 대부분이었고요.개인 2000억 원 가까이 순매수하며 지수를 지탱했습니다.코스닥 시장에서는 외국인 170억 원 팔아냈고, 개인도 114억 원 순매도하며 어느 정도 관망심리를 보였고, 기관만 536억 원 순매수했습니다.시가총액 상위단 섹터별, 종목별로 엇갈리는 흐름이 나타났습니다.우선 SK하이닉스는 3% 가까이 상승했지만 삼성전자는 잠정실적 발표를 앞두고 다시 6만전자를 반납했습니다.장관 후보자 지명 소식에 두산에너빌리티가 반응하며 시총 5위로 점프했습니다.4% 가까이 상승했고, KB금융 상승.네이버는 나흘 만에 반등하며 시총 8위를 기록했습니다.반면 한화에어로스페이스는 5% 가까이 내렸습니다.코스닥 시총 상위단을 보면 헬스케어 섹터, 종목별로 엇갈렸고요.2차전지 대표주들은 상승 출발했지만, 힘이 빠지며 마감했습니다.환율은 떨어졌습니다.정규장 마감 시간 7원 40전 내린 1350원에 거래를 마쳤습니다.약달러가 계속되며 장중엔 1350원선도 밑돌기도 했습니다.이후 야간거래에서는 1350원 중반대에서 거래를 이어갔는데요.미국의 기준금리 인하 기대감에 따른 달러 약세에도 무역 협상 불확실성이 원화 강세를 제한한 것으로 분석됩니다.새벽 6시 기준 NDF에서 환율은 1354원 30전을 기록했습니다.오늘 외환시장 소폭 오르며 출발할 수 있겠습니다.7월의 첫 거래일 증권가에서 나온 섹터별 리포트 정리했습니다.우선 7월 2분기 실적 발표를 앞두고 대신증권은 자동차 부품주에서 봐야 할 종목들을 제시했습니다.이번 분기는 관세 영향으로 실적 눈높이가 전반적으로 하향세를 보일 것으로 내다봤는데요.그래서 관세 영향이 적고, 개별 모멘텀이 있거나 현금이 넉넉한 종목 중심으로 대응할 것을 추천했습니다.탑픽으로는 올해 2분기 영업이익이 컨센서스를 상회할 것으로 예상되는 SNT모티브와 현대오토에버, 그리고 낙폭 과대에 관세 이수를 공급망 변경으로 대응하며 부품 업종 내에서 상대적 우위가 부각될 HL 만도를 꼽았습니다.KB증권은 운송인프라 섹터 내에서 저가 매수, 공개매수, 염가매수 할 만한 3가지 종목을 제시했습니다.운송 업황 자체는 미국과 중국의 화물 수요가 줄어 전망이 좋지 않다고 진단했습니다.다만 대한항공의 경우, 환율 하락에 따른 수혜에 아시아나항공 통합 시 장기 성장 동력도 갖추고 있으며 지금 주가가 역사적 저점에 위치해 있다며 저가 매수를 권했습니다.그밖에 HMM은 KB증권이 HMM을 2만 5000원에 공개매수를 실시할 것이라고 가정하며 이를 목표 주가로 제시했고요.대한해운은 절대적으로 낮은 밸류에이션은 언제 주가가 급등해도 이상하지 않을 수준이라고 평가했습니다.자동차 부품과 운송 업종에 대한 보고서 내용, 투자하실 때 참고하시죠.오늘 일정입니다.우리나라 6월 수출입 동향이 발표되고요.오늘 밤에 나올 미국의 경제지표들 중요하겠습니다.한편 넥스트레이드 첫 정기 종목 변경이 이뤄집니다.LG씨앤에스, SAMG 엔터 등 105개 종목이 새로 편입되고, SG글로벌, 퀀타매트릭스 등 112개 종목은 제외됩니다.한편 어제 시간 외 거래에서는 바이오 쪽이 강했습니다.개별 이슈에 따라 움직임 보였는데요.에이비온이 전임상 단계의 신약후보물질로 최대 1조 8000억 원 규모의 기술수출에 성공했는데, 이번 기술 수출이 올해 법인세 비용 차감 전 계속사업 손실, 법차손 리스크 해소에 기여할 것으로 기대되자 에이비온, 케이피엠테크, 텔콘 RF제약까지 상승했습니다.브릿지바이오테라퓨틱스는 200억 원 규모 3자배정 유상증자로 인해 최대주주가 변경된다는 소식에 시간 외 거래에서 급등했습니다.참고하시죠.그럼 프리마켓 통해 한국거래소 개장 분위기 가늠해 보겠습니다.간밤 뉴욕증시 오는 8일까지인 상호관세 유예 만료 이전에 미국과 주요 교역국의 무역 협상이 진전을 보일 것이란 낙관론에 S&P500지수와 나스닥지수가 사상 최고치를 기록했죠.7월의 시작, 시장 어떤 방향성을 나타낼까요?3100선 재돌파를 시도하는 가운데 발목 잡고 있는 외국인 수급이 개선될지 지켜보시죠.지금까지 어제장 오늘장이었습니다.당신의 제보가 뉴스로 만들어집니다.SBS Biz는 여러분의 제보를 기다리고 있습니다.홈페이지 = https://url.kr/9pghjn', NULL, 'SBS Biz', 'https://n.news.naver.com/mnews/article/374/0000448939', 'https://imgnews.pstatic.net/image/374/2025/07/01/0000448939_001_20250701082910693.jpg?type=w800', 'NEWS_AUTO', NULL, '2025-07-01 08:29:10', 0, true, '2026-03-09 05:44:30.348128') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (569, '[애프터마켓 리뷰] NXT, 105종목 추가…LG CNS·GS피앤엘 등', '■ 모닝벨 ''애프터마켓 리뷰'' - 도지은애프터마켓 정리해드립니다.대체거래소가 올해 3분기 매매체결 대상으로 791개 종목을 선정했습니다.새로 편입되는 종목은 LG씨엔에스, 삼양홀딩스, 넥센타이어, 신세계인터내셔날 등 105개 종목이고, 편출되는 종목은 SG글로벌, LX하우시스 등 112개 종목입니다.전체 매매 체결 대상 종목은, 기존 798종목에서 791개 종목으로 총 7개 줄었습니다.대체거래소는 한국거래소에 상장된 주권 중 일부를 매매체결 대상으로 하고 있고, 이를 분기마다 선정·변경하는 것을 원칙으로 합니다.이번에 선정된 종목은 오는 7월 1일부터 최소한 오는 12월 말까지 대체거래소의 정규시장, 그러니까 프리, 메인, 애프터마켓에서 거래될 예정입니다.다만, 관리종목 지정 등으로 거래 제한 사유가 발생할 경우에는 매매체결 대상 종목에서 제외되는데요.지난 분기 선정돼 거래되고 있는 종목 중 일정 요건을 충족하지 못할 경우 다음 정기 변경 시기인 오는 9월 말에 매매체결 대상 종목에서 제외될 수 있습니다.새롭게 편입, 편출되는 종목에 대해서는 미리 체크하셔야겠고요.어제(25일) 애프터마켓은 메인마켓의 온기를 유지하는 모습이었습니다.전날 뉴욕증시에서 반도체주들이 일제히 급등한 영향 받았는데요.삼성전자 1.32% 올랐고, SK하이닉스는 정규장 보다 더 상승세 키우면서 28만 8500원에 장 마쳤습니다.대형 반도체뿐만 아니라 어제는 반도체 소부장 종목 주가도 함께 반등했다는 점 특징적이었습니다.반도체, 자동차 등 저평가, 낙폭 과대 업종으로 순환매 움직임이 감지됐습니다.참고로 6위의 현대차 5%대, 그리고 기아도 4%대 시원한 급등세 보였습니다.이 외에 삼성바이오로직스는 보합, NAVER는 3%대 하락했는데, 이처럼 최근 급등세가 지속됐던 원전이나 인터넷, 게임 업종에서는 차익실현 매물이 출회되는 흐름 포착이 됐고요.이밖에 실적 개선 기대감과 원전 확대 수혜 전망에 한국전력이 이틀째 두 자릿수 상승률 기록했고, DL이앤씨, 현대건설 등 건설주들 전반적으로 강세 보였습니다.코스닥으로 넘어가면 대체로 쉬어가는 가운데 알테오젠 0.26% 상승, 에코프로비엠도 강보합권에 마무리됐고, 반면 레인보우로보틱스가 6%대 떨어지면서 하락폭이 가장 깊었습니다.상승세 이어지지만 외국인은 반도체에, 개인은 원전과 방산 등에 투자를 하는 등 투자처가 갈리고 있는데요.과연 오늘(26일) 시장의 주역은 누구일지, 잠시 후 프리마켓에서 확인해 보시죠.지금까지 애프터마켓 리뷰였습니다.당신의 제보가 뉴스로 만들어집니다.SBS Biz는 여러분의 제보를 기다리고 있습니다.홈페이지 = https://url.kr/9pghjn', NULL, 'SBS Biz', 'https://n.news.naver.com/mnews/article/374/0000448049', 'https://imgnews.pstatic.net/image/374/2025/06/26/0000448049_001_20250626075111296.jpg?type=w800', 'NEWS_AUTO', NULL, '2025-06-26 07:51:11', 0, true, '2026-03-09 05:44:30.348128') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (570, 'LG 씨엔에스·SAMG엔터 출퇴근길 주식 거래 가능…NXT, 정기종목 변경', '2025년 3분기 넥스트레이드 매매체결대상 종목 변동 현황.[넥스트레이드]넥스트레이드(NXT)는 올해 3분기 매매체결 대상으로 791종목(코스피 380종목, 코스닥 411종목)을 선정했다고 25일 밝혔다.편입되는 종목은 LG 씨엔에스, SAMG엔터 등 105종목이며 편출되는 종목은 SG글로벌, 퀸타매트릭스 등 112종목이다. 이에 따라 전체 매매체결 대상 종목은 기존 798종목에서 791종목으로 7개 줄었다. 삼성전자, 알테오젠 등 686종목은 이전 분기에 이어 계속 매매체결 대상 종목에 포함됐다.넥스트레이드는 한국거래소(KRX)에 상장된 주권 중 일부를 매매체결 대상으로 하고 있으며 이를 분기마다 선정·변경하는 것을 원칙으로 하고 있다. 분기별로 선정된 종목은 해당 분기와 다음 분기 말일까지 매매체결 대상 종목에 포함된다.이에 이번에 선정된 종목은 오는 7월 1일부터 최소한 오는 12월 말까지 넥스트레이드의 정규시장(프리·메인·애프터마켓)에서 거래될 예정이다.다만 관리종목 지정 등으로 거래 제한 사유가 발생할 경우에는 매매체결 대상 종목에서 제외된다. 지난 분기 선정돼 거래되고 있는 종목 중 일정 요건을 충족하지 못할 경우 다음 정기 변경 시기인 오는 9월 말에 매매체결 대상 종목에서 제외될 수 있다. 김지영기자 jy1008@dt.co.kr', NULL, '디지털타임스', 'https://n.news.naver.com/mnews/article/029/0002963979', 'https://imgnews.pstatic.net/image/029/2025/06/25/0002963979_001_20250625194753967.jpg?type=w800', 'NEWS_AUTO', NULL, '2025-06-25 19:12:08', 0, true, '2026-03-09 05:44:30.348128') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (571, '[서울데이터랩]금일 코스피 거래량 1위 웅진 거래대금 389억 돌파', '코스피 거래량 상위 종목들이 전반적으로 엇갈린 흐름을 보이고 있다.한국거래소에 따르면, 웅진(016880)이 29,128,022주 이상의 거래량을 기록하며 코스피 종목 중 실시간 거래량 1위를 차지하고 있다. 현재 주가는 1,407원이며, 거래대금은 38,912백만원으로 시가총액의 3.46%에 해당하는 수준이다. 등락률은 +29.92%로 상한가를 기록하고 있다. PER은 37.03, ROE는 4.50으로, 수급과 재무 지표 모두에서 주목할 만한 상승세를 보이고 있다. 두 번째로 거래량이 많은 오리엔트바이오(002630)도 27,644,703주의 거래량을 나타내며 거래량 2위를 기록 중이다. 현재 주가는 1,586원으로, 거래대금은 43,104백만원으로 시가총액의 2.29%에 달하고 있다. 등락률은 +20.52%로 급등세를 보이고 있으며, PER은 99.12, ROE는 16.45이다.웅진씽크빅(095720)은 20,948,140주의 거래량을 기록하며 거래량 3위를 차지하고 있다. 현재 주가는 1,809원, 등락률은 +12.92%로 급등세를 보이고 있다. 그 뒤를 이어 형지엘리트(093240)는 12,356,100주의 거래량과 +18.99%의 상승률을 보이고 있으며, 동양철관(008970)은 7,591,413주의 거래량과 -4.62%의 하락세를 나타내고 있다. 애경케미칼(161000)은 6,457,037주의 거래량과 +5.88%의 상승률, LG헬로비전(037560)은 6,344,230주의 거래량과 +0.37%의 보합권 내 움직임을 보이고 있다. 태영건설(009410)은 6,053,346주의 거래량을 기록하며 -4.75%의 하락세를 보이고 있고, 동양(001520)은 5,679,980주의 거래량과 -6.76%의 하락세, 삼성전자(005930)는 5,604,385주의 거래량과 -0.36%의 보합권 내 움직임을 보이고 있다.한편 거래량 상위 20위권 종목들은 두산에너빌리티(034020) ▼-1.21%, 태양금속(004100) ▼-10.63%, 삼성중공업(010140) ▼-3.34%, 미래에셋증권(006800) ▲8.37%, 대한제당(001790) ▼-7.63%, 대영포장(014160) ▼-3.38%, SG글로벌(001380) ▲2.89%, 이스타코(015020) ▲16.53%, 한화오션(042660) ▼-1.78%, 남선알미늄(008350) ▲1.46% 등의 성적을 기록하고 있다.주목할 만한 종목으로는 상한가를 기록한 웅진과 급등세를 보이는 오리엔트바이오가 있다. 웅진은 시가총액 대비 거래대금 비율이 3.46%로 시장의 관심을 끌고 있으며, 오리엔트바이오 역시 시가총액 대비 거래대금 비율이 2.29%에 달하고 있다. 반면, 태양금속과 대한제당은 각각 -10.63%와 -7.63%의 하락률을 기록하며 하락세를 보이고 있다.전체 시장은 상승과 하락이 엇갈리며 혼조세를 보이고 있다. 일부 종목은 투자자들의 관심을 집중시키며 강세를, 다른 일부 종목은 약세를 보이고 있어 투자에 신중한 접근이 필요할 것으로 보인다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003537831', 'https://imgnews.pstatic.net/image/081/2025/04/30/0003537831_001_20250430131516232.jpg?type=w800', 'NEWS_AUTO', NULL, '2025-04-30 13:15:16', 0, true, '2026-03-09 05:44:30.348128') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (572, '[서울데이터랩]일정실업 29.97% 폭등…실시간 상승률 1위', '30일 오전 9시 10분 일정실업(008500) 일정실업이 등락률 +29.97%로 상승률 1위를 차지했다. 일정실업은 개장 직후 26,482주가 거래되었으며 주가는 전 거래일 대비 5,650원 오른 24,500원이다.한편 일정실업의 PER은 8.62로 상대적으로 저평가를 받고 있을 가능성을 시사하며, ROE는 74.89%로 매우 높은 수익성을 나타낸다.이어 상승률 2위 형지엘리트(093240)는 현재가 2,620원으로 주가가 25.96% 폭등하고 있다. 상승률 3위 금호건설우(002995)는 현재 17,900원으로 24.65% 폭등하며 강세를 보이고 있다. 상승률 4위 오리엔트바이오(002630)는 16.57% 급등하며 1,534원에 거래되고 있다. 상승률 5위 일성건설(013360)은 14.43%의 상승세를 타고 3,410원에 거래되고 있다.6위 이스타코(015020)는 현재가 1,490원으로 12.96% 급등 중이다. 7위 웅진(016880)은 현재가 1,195원으로 10.34% 상승 중이다. 8위 SG글로벌(001380)은 현재가 2,060원으로 10.10% 상승 중이다. 9위 애경케미칼(161000)은 현재가 10,890원으로 6.66% 상승 중이다. 10위 한미약품(128940)은 현재가 260,000원으로 5.26% 상승 중이다.이밖에도 코오롱모빌리티그룹우(45014K) ▲5.10%, 흥국화재우(000545) ▲4.84%, 그린케미칼(083420) ▲4.21%, 웅진씽크빅(095720) ▲4.06% 등을 기록하며 시장에서 활발히 거래되고 있다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003537743', 'https://imgnews.pstatic.net/image/081/2025/04/30/0003537743_001_20250430092113095.png?type=w800', 'NEWS_AUTO', NULL, '2025-04-30 09:21:13', 0, true, '2026-03-09 05:44:30.348128') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (573, '코스피, 트럼프의 자동차부품 관세 완화에...17p ''상승반전''', '코스피, 16.56포인트(0.65%) 상승 2565.42 마감코스닥, 7.05포인트(0.98%) 상승 726.46 마감◆…[사진=연합뉴스]미국과 중국의 관세협상이 지지부진하게 진행되고 있지만, 도널드 트럼프 미국대통령이 자동차부품 관세를 완화한다는 소식이 전해지면서, 29일 코스피는 16.56포인트(0.65%) 상승하며 2565.42로 마감했다. 전날의 보합세에서 상승반등했고, 한달 여만에 2560선도 회복했다.신한투자증권 강진혁 연구원은 "트럼프가 자동차 부품 관세를 소급해서 완화할 방침임을 밝힌 점은 상승 반전의 재료로 작용했다"면서, "단순히 자동차 산업에 국한된 이슈라기보다 내부 산업계·노동계의 의견이 받아들여지며 관세 이슈가 조정될 수 있음을 보여줬다"고 분석했다.전날 미국 주식 시장은 다우(+0.28%), S&P500(+0.06%), 나스닥(-0.10%), 필라델피아반도체(-0.38%) 등 미-중 협상 부진에 혼조세로 전환됐고, 29일 아시아 증시도 일본 니케이(+0.38%), 홍콩 항셍(+0.19%), 중국 상해(-0.05%), 베트남 호치민(-0.04%) 등 혼조양상을 보였다.이날 유가증권시장에서는 전날에 이어 외국인과 개인이 각각 2351억원, 1664억원 순매도를 이어갔지만, 기관이 이날도 3566억원 순매수하며 지수 상승을 견인했다.상승종목은 660종목, 하락은 238종목으로 전날의 하락세에서 상승세로 돌아섰고, 보합은 37종목이었다. 시가총액 상위 10위 종목도 상승 7종목 하락 2종목, 보합 1종목으로 특히, 자동차 종목이 오르며 상승세를 이끌었다.삼성전자가 보합으로 마감됐고, LG에너지솔루션(+1.16%), 삼성바이오로직스(+1.54%), 현대차(+2.01%), 삼성전자우(+0.54%), 셀트리온(+3.80%), 기아(+2.14%), HD현대중공업(+1.00%) 등 7종목이 상승 마감했다.반면, SK하이닉스(-1.30%), 한화에어로스페이스(+0.36%) 등 2종목은 하락 마감했다.코스닥도 개장 때의 상승세를 시간이 갈수록 확대해, 전날의 10포인트 급락세에서 7.05포인트(0.98%) 상승세로 돌아서며 726.46으로 마감했다.이날 외국인과 기관은 각각 1333억원, 403억원 순매수하며 지수를 끌어 올렸고, 개인은 1635억원 순매도했다.상승종목은 1056종목, 하락은 549종목으로 하루만에 상승세로 바뀌었고, 보합은 98종목이었다. 시가총액 상위 10위 종목도 상승 8종목, 하락 2종목으로 상승세가 압도했다.알테오젠(+1.68%), HLB(+1.08%), 레인보우로보틱스(+1.44%), 휴젤(+4.23%), 클래시스(+1.10%), 파마리서치(+3.72%), 펩트론(+0.23%), 리가켐바이오(+3.71%) 등 8종목이 상승 마감한 반면, 에코프로비엠(-2.01%)과 에코프로(-0.78%) 등 2종목은 하락 마감했다.한편, 대체거래소 넥스트레이드도 한국거래소(KRX)와 같이 상승전환했다.프리마켓은 기준가(전일 정규시장 종가)보다 0.26% 상승 출발했고, 메인마켓은 상승폭을 확대해 0.58% 상승 마감했다. 정규시장 마감후 거래가 이뤄지는 애프터마켓은 17시 20분 현재 이날 KRX 종가보다 0.06% 하락한 상태에서 거래되고 있다.이날 대체거래소에서 기준가보다 크게 오르고 있는 종목은 인벤티지랩(+25.63%), 티와이홀딩스(+18.14%), SG글로벌(+17.57%) 등이며, 하락폭이 큰 종목은 더블유씨피(-12.72%), 한화오션(-12.65%), 박셀바이오(-7.92%) 등이다.', NULL, '조세일보', 'https://n.news.naver.com/mnews/article/123/0002358102', 'https://imgnews.pstatic.net/image/123/2025/04/29/0002358102_001_20250429175817793.jpg?type=w800', 'NEWS_AUTO', NULL, '2025-04-29 17:58:17', 0, true, '2026-03-09 05:44:30.348128') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (574, '이재명株, 한동훈株, 김문수株… 대선 테마주 불장난과 불구경', '더스쿠프 커버스토리 視리즈정치 테마주 위험의 악순환 1편대선 앞두고 출렁이는 테마주우후죽순 생기는 정치인 테마주대선 주자부터 정책 관련주까지실적과 무관하게 움직이는 주가국내 증시 부진에도 급등세 기록# 시장의 변화에 가장 민감하게 반응하는 곳은 주식시장이다. 시장의 변화가 테마주를 만들고 이를 통해 수익을 올릴 수 있다는 기대감이 증시에 작용하기 때문이다. 대표적인 것이 정치 테마주다.# 6월 3일 치러질 21대 대통령선거를 앞두고 정치 테마주의 주가가 널을 뛰고 있다. 문제는 선거 때마다 기승을 부리는 정치 테마주를 막을 뾰족한 방법이 없다는 점이다. 국내 증시에 불고 있는 정치 테마주의 광풍을 지켜볼 수밖에 없는 이유다. 視리즈 정치 테마주 위험의 악순환 1편을 열어보자.21대 대통령선거를 앞두고 정치 테마주가 들썩이고 있다.[사진｜연합뉴스]최악의 ''블랙 먼데이(검은 월요일)''가 펼쳐졌다. 도널드 트럼프 미국 대통령의 상호관세 발표 소식을 접한 7일 국내 증시는 얼어붙었다. 이날 코스피지수는 전 거래일 대비 5.57% 폭락했고, 코스닥지수는 5.25% 하락했다.찬바람은 기업까지 얼렸다. 코스피·코스닥 시장에 상장한 2757개 종목 중 주가가 상승한 건 259개(9.4%)에 불과했다. 주가가 등락하지 않은 137개 종목을 제외하면 전체의 85.6%에 해당하는 2361개 종목의 주가가 하락했다.주목할 점은 이런 와중에도 상한가를 기록한 종목이 적지 않았단 점이다. 경남스틸, 꿈비, 에르코스, 상지건설, 태양금속 우선주, 평화홀딩스 등 17개 종목이었는데, 이중 13개 종목이 ''정치 테마주''였다.일례로, 한동훈 국민의힘 예비대선후보(전 대표·이하 대선후보)의 테마주로 불리는 태양금속 우선주와 태양금속의 주가는 7일 상한가를 기록했다. 홍준표 국민의힘 대선후보(전 대구시장) 테마주인 경남스틸·휴맥스홀딩스, 이재명 더불어민주당 대선후보(전 대표) 테마주 상지건설 등도 상한가를 기록했다.6월 3일 치러질 조기대선 기대감 때문인지 원티드랩, 꿈비, 윌비스, 아이비김영, 아이스크림에듀 등 저출생·일자리 테마주도 부진했던 시장과는 180도 다른 모습을 보였다.비단 7일만이 아니다. 그 이후에도 정치 테마주는 연일 출렁이고 있다. 10일 나경원 국민의힘 의원이 대선 출마를 선언할 것이란 소식에 오텍의 주가가 장중 26.21%까지 치솟았다. 오텍은 특수차량 제조업체로 2011년 서울시장 보궐선거에 출마한 나 의원이 "저상버스를 많이 도입해야 한다"고 밝힌 말 한마디에 테마주로 묶였다. 정치 테마주가 정치인의 14년 전 발언까지 소환한 셈이다.한덕수 대통령 권한대행 겸 국무총리 테마주도 급등과 급락을 거듭하고 있다. 한덕수 권한대행이 차기 대선 후보 적합도 조사에서 한동훈 후보(6.2%)를 제치고 3위(8.6%에 올랐다는 소식이 알려지면서다.그 결과, 관련주로 분류된 시공테크의 주가는 지난 14일 장중 27.38%까지 급등했고, 다음날인 15일엔 장중 -17.49%로 하락하는 롤러코스터 흐름을 보였다. 정치 테마주가 국내 증시의 불안 요소로 떠올랐다는 우려가 커지는 이유가 여기에 있다.[※참고: 한덕수 권한대행이 실제로 대선에 출마할지는 미지수다. 지난 16일 헌법재판소가 한덕수 권한대행의 이완규·함상훈 헌법재판관 후보자 지명 효력에 관한 가처분 신청을 전원 일치의견으로 인용하면서다. 헌법재판관 지명 후 정치권에서 떠오른 ''한덕수 차출론''이 동력을 상실한 게 아니냐는 평가를 받는 이유다.][일러스트｜게티이미지뱅크]■ 이재명 테마주 =그렇다면 국내 증시를 들썩이게 만드는 정치 테마주는 어떤 것들이 있을까. 가장 많은 테마주를 양산한 것은 ''어대명(어차피 대통령은 이재명)''이란 말이 회자될 만큼 유력한 차기 대통령 후보로 꼽히는 이재명 테마주다.이재명 테마주로 불리는 종목은 20개가 넘는다. 동신건설, 상지건설, 시공테크, 오리엔트정공, 오리엔트바이오, 에르코스, 코나아이, 크라우드윅스, 캠시스, CS, 프리엠스 등 관련 종목을 일일이 나열하기도 힘들 정도다.시장에선 이재명 테마주가 70개를 웃돈다는 우스갯소리도 나온다. 이재명 테마주가 갈수록 확산하고 있다는 건데, 그렇다고 특별한 호재나 관련성이 있는 건 아니다. 인맥으로 얽혀있는 것이 대부분이다.올해(1월 2일~4월 17일) 들어 주가가 812.72 %(4755원→4만3400원) 치솟은 상지건설은 사외이사가 이 후보의 캠프에 합류했다는 소식에 상승세를 타고 있다. 동신건설은 본사가 이 후보의 고향인 안동에 있다는 이유로 테마주에 이름을 올렸다. 오리엔트정공은 이 후보가 계열사인 오리엔트시계에서 근무했던 것이 부각하면서 올해에만 85.07 %(6630원→1만2270원)의 주가상승률을 기록했다.더불어민주당 대선 레이스에 뛰어든 김동연 대선후보(경기도지사)와 김경수 대선후보(전 경남도지사)의 테마주도 들썩이고 있다. 자동차 부품 제조업체 SG글로벌은 김동연 후보의 고향인 충청도에 본사를 두고 있다는 이유로 ''김동연 테마주''로 불린다.한국컴퓨터는 모회사 한국컴퓨터지주의 홍정환 대표가 김경수 후보와 서울대 동문이라는 게 알려지면서 테마주에 합류했다. 정치 테마주로 엮이는 게 얼마나 허술한 이유인지 여실히 보여주는 사례다.■ 한동훈 테마주 =이번엔 국민의힘 대선후보의 테마주를 좀 더 구체적으로 살펴보자. 먼저 한동훈 테마주다. 한동훈 테마주의 대장은 태양금속이다. 이 회사의 회장이 한동훈 후보와 같은 ''청주 한씨氏''란 소문에 테마주에 편입됐다.낯뜨거운 이유로 테마주가 됐지만 주가는 아랑곳하지 않았다. 윤석열 전 대통령의 파면으로 한 후보의 대선출마 가능성이 모락모락 피어오른 4일부터 태양금속의 주가는 가파른 상승세를 기록했다. 태양금속의 주가는 4일 28.27% 치솟은 데 이어 7일에도 상한가(29.88%)를 기록했다.그 이후에도 급등락을 거듭하고 있다. 지난 9~11일 리얼미터가 실시한 대선 적합도 조사에서 이재명 후보(48.8%)에 이어 2위에 이름을 올린 김문수 후보(10.9%)를 둘러싸고도 평화홀딩스, 평화산업을 필두로 대영포장, 세원물산, 옵티시트, 동일금속 등 10개가 넘는 테마주가 형성됐다.대부분 회사의 본사가 김문수 후보의 고향인 경북 영천시 소재기업이라는 점과 회사 임원이 경북고나 서울대 동문이라는 게 테마주로 엮인 이유였다. 안철수 후보의 테마주인 써니전자와 안랩의 주가도 4월 들어 롤러코스터를 타고 있다.정치 테마주는 6월 3일로 예정된 대선이 다가올수록 더욱 기승을 부릴 게 분명하다. 양당의 경선 과정을 거치면서 대선후보가 좁혀질수록 관련주에 베팅하는 투자자도 증가할 것이다.정치적 불확실성 속에서 널을 뛰는 정치 테마주를 이대로 모른척해도 괜찮은 걸까. 이 이야기는 視리즈 정치 테마주 위험의 악순환 2편에서 이어나가도록 하겠다.강서구 더스쿠프 기자ksg@thescoop.co.kr', NULL, '더스쿠프', 'https://n.news.naver.com/mnews/article/665/0000004861', 'https://imgnews.pstatic.net/image/665/2025/04/18/0000004861_001_20250418092412535.jpg?type=w800', 'NEWS_AUTO', NULL, '2025-04-18 09:24:12', 0, true, '2026-03-09 05:44:30.348128') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (575, 'KG에코솔루션, 울산에 바이오선박유 생산 설비 구축…"탄소중립 실천"', '곽재선 회장 "친환경 에너지 시대 의미 있는 첫걸음"KG에코솔루션은 지난 6일 울산 울주군 온산읍에서 연간 3만6000톤 바이오선박유 생산능력을 갖춘 신공장 준공식을 열었다. KG에코솔루션 울산 신공장 전경. /KG그룹[더팩트ㅣ최의종 기자] KG에코솔루션이 울산공장에 바이오선박유 생산 설비를 구축하며 수익성 강화에 박차를 가한다.KG에코솔루션은 지난 6일 울산 울주군 온산읍에서 연간 3만6000톤 바이오선박유 생산능력을 갖춘 신공장 준공식을 열었다고 9일 밝혔다. 행사에는 곽재선 회장과 박생근 KG에코솔루션 대표, 김재익 KG케미칼 대표 등 경영진 등 70여명이 참석했다.KG에코솔루션은 신공장 완공을 통해 글로벌 친환경 연료 시장에서 경쟁력 있는 생산 기반을 마련하게 됐다고 밝혔다. 울산공장 바이오선박유 생산시설은 지난해 9월 착공해 공사를 본격적으로 시작했다. 약 6개월간 공사와 시운전 과정을 거쳐 준공했다.KG에코솔루션은 고가 정제 원료를 혼합하는 기존 방식 대신 200℃ 이상 고온 탈산 공정을 통해 저가·고산가 미정제 원료를 직접 정제하는 ''업사이클링 생산 구조''를 확립했다고 강조했다. 원료 선택 폭을 넓히고 구조적인 마진을 확보해 수익성을 극대화할 계획이다.울산공장은 국내 주요 정유사와 수출 항만 인근에 있어 물류비 절감뿐 아니라 해외 주요 정유사와 글로벌 트레이더와의 수출 협의에도 유리한 입지를 점하고 있다는 것이 KG에코솔루션 설명이다.곽 회장은 "울산 바이오선박유 전용 공장 준공은 친환경 에너지 시대를 향한 KG에코솔루션 의미 있는 첫걸음"이라며 "앞으로도 지속 가능한 미래 에너지 산업의 거점으로서 탄소중립 실천과 대한민국 친환경 에너지 산업 발전에 중추적인 역할을 해나가겠다"고 밝혔다.발로 뛰는 더팩트는 24시간 여러분의 제보를 기다립니다.▶카카오톡: ''더팩트제보'' 검색▶이메일: jebo@tf.co.kr▶뉴스 홈페이지: http://talk.tf.co.kr/bbs/report/write', NULL, '더팩트', 'https://n.news.naver.com/mnews/article/629/0000479321', 'https://imgnews.pstatic.net/image/629/2026/03/09/202638651773031343_20260309134707045.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-03-09 13:47:07', 0, true, '2026-03-09 05:44:54.377094') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (576, '호르무즈 해협 봉쇄에 ''초비상''…이 와중에 상한가 친 종목 [종목+]', '호르무즈 봉쇄, 비료 교역도 막았다남해화학·조비 ''上''이란 호르무즈 해협 봉쇄 민간 선박 4척 피격/사진=AFP, 연합뉴스비료·사료 관련 종목들이 급등하고 있다. 질소비료의 원료인 요소가 천연가스 부산물이기에 중동에서 많이 생산되고 있어서다. 호르무즈 해협이 봉쇄된 데 따라 비료 원료의 교역도 막히면서 올해 농사를 망칠 우려가 커지고 있다.9일 오전 9시49분 현재 남해화학은 전일 대비 2270원(29.91%) 오른 9860원에, 조비는 4370원(29.95%) 상승한 1만8960원에 각각 거래되고 있다.남해화학은 국내 최대 비료생산업체이며, 조비는 친환경 맞춤 비료 기업이다.이외에도 농자재를 생산하는 KG케미칼(19.19%), 미래생명자원(24.4%), 농우바이오(5.53%) 등도 강세다.미국과 이란의 전쟁 때문이다. 전쟁으로 인해 호르무즈해협이 봉쇄되면서 비료 원료인 요소 교역도 막혔다. 요소는 천연가스를 생산하는 과정에서 나오는 수소로 만든다.사료 생산업체인 한일사료(29.68%), 고려산업(17.67%), 팜스토리(12.86%) 등도 급등 중이다. 농산물 가격이 치솟게 되면 이를 원료로 만드는 사료 가격도 상승할 수밖에 없다.', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005259721', 'https://imgnews.pstatic.net/image/015/2026/03/09/0005259721_001_20260309100619344.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-03-09 09:58:21', 0, true, '2026-03-09 05:44:54.377094') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (577, '[이 시각 시황] 국제유가 100달러 돌파…LPG 관련주 강세', '■ 머니쇼 ''이 시각 시황'' - 장연재이 시각 시황입니다.월요일부터 시장 대응하기 만만치 않습니다.양시장 모두 급락합니다.코스피 7.1% 떨어지면서 5,187선 가리키고 있습니다.코스닥 5.7% 가까이 빠지면서 1,089포인트 기록 하고 있습니다.수급상황 보시죠.유가증권 시장입니다.외국인 6,300억 원 가까이 팔아냅니다.기관도 4,698억 원 매도 우위 기록 중입니다.개인 홀로 1조 1342억 원 사자 포지션 취하고 있습니다.코스닥 시장입니다.외국인 215억 원, 기관도 419억 원 매수우위 기록 중입니다.개인 홀로 148억원 팔아냅니다.외국인은 팔자세로 전환된 상태입니다.등락률 상하위 업종입니다.오늘(9일) 상승하는 종목 많지않습니다.오늘은 우주항공과 국방, 가스유틸리티, 에너지 장비 및 서비스 업종이 상승률 상위권에 위치해 있습니다.반면, 자동차, 항공화물운송과물류, 건강관리업체 및 서비스 업종이 하락폭이 큰 것으로 집계됩니다.시장을 주도하는 테마, 종목별 시세 체크하시죠.미국과 이란간 충돌 옆로 국제유가가 배럴당 100달러를 넘어서자 LPG 관련주가 바로 반응합니다.관련주 내에서는 중앙에너비스가 18.5% 뛰면서 거래가 34,550원입니다.흥구석유가 19% 가까운 강세 기록 중으로 32,800원에 거래됩니다.극동유화가 16.1% 오름세로 거래가 4,975원입니다.대성산업이 7.1%, S-Oil이 1.1% 오름세로 현재 거래가 131,100원으로 집계됩니다.해운주도 강세입니다.미국, 이스라엘과 이란간 전쟁 여파로 호르무스 해협이 봉쇄됐고, 이에 운임 쇼크가 현실화된 영향입니다.LPG선 스팟 요금은 일주일 만에 약 6배 급등했고, 초대형원유운반선, VLCC 스팟 요금도 사상 최고치를 경신한 바 있습니다.이 영향으로 관련주 내에서는 흥아해운이 8.6% 강세로 거래가 2,770원입니다.STX그린로지스가 2% 강세로 7,320원입니다.대한해운이 0.7% 오름세로 2,290원입니다.HMM이 현재 1.1% 내림세로 돌아서면서 20,900원입니다.KSS해운이 2.8% 약세로 현재 거래가 10,320원으로 집계됩니다.이란 전쟁 확전 우려가 커지며 방산주 계속해서 주목받고 있습니다.디와이씨가 7.5% 강세입니다.한일단조가 17% 가까이 상승 하면서 현재 거래가 4,365원입니다.센서뷰도 14% 가까운 강세로 거래가 3,060원입니다.삼미금속 8.8% 오름세로 15,660원입니다.RF시스템즈도 현재 0.2% 가까운 오름세입니다.비료주도 상승합니다.전세계 비료 무역량의 3분의 1이 호르무즈 해협 막히자 봄 파종을 앞둔 농가의 비료 수급에 영향을 미칠 것이란 우려가 커지고 있기 때문입니다.남해화학이 상한가로 9,860원 기록했습니다.조비 역시 상한가 경신하면서 거래가 18,960원입니다.KG케미칼이 18.6% 급등 하면서 거래가 5,840원입니다.효성오앤비가 24% 급등세로 거래가 7,610원입니다.롯데정밀화학이 50,800원에 거래되고 있습니다.양 시장 또 한번 출렁이고 있는데 장중에 낙폭을 조금이라도 줄여낼 수 있을 지 전 거래일처럼 코스피 개인들이 시장을 말아올려줄 지 지켜보시죠.지금까지 시장 상황 전해드렸습니다.당신의 제보가 뉴스로 만들어집니다.SBS Biz는 여러분의 제보를 기다리고 있습니다.홈페이지 = https://url.kr/9pghjn', NULL, 'SBS Biz', 'https://n.news.naver.com/mnews/article/374/0000496562', 'https://imgnews.pstatic.net/image/374/2026/03/09/0000496562_001_20260309094414079.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-03-09 09:44:14', 0, true, '2026-03-09 05:44:54.377094') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (578, '농사철 다가오는데 전쟁에 교역로 1/3 막혔다…비료주 급등', '특징주머니투데이 특징주 그래픽 이미지미-이란 충돌 여파로 비료주가 급등하고 있다. 봄 파종 시기는 다가오는데 전 세계 비료 교역량의 3분의 1이 지나가는 호르무즈 해협이 사실상 막힌 영향이다.9일 오전 9시17분 현재 코스피 시장에서 조비는 전 거래일 대비 4370원(29.95%), 남해화학은 2270원(29.91%) 올라 상한가인 1만8960원과 9860원에 거래되고 있다. 조비는 친환경 맞춤 비료 기업이고 남해화학은 국내 최대 비료 생산업체 중 하나다.비료 테마주 9개 모두 강세다. 효성오앤비는 전 거래인 대비 1440원(23.38%) 오른 7600원, KG케미칼은 965원(19.59%) 오른 5890원, 롯데정밀화학은 5450원(11.99%) 오른 5만900원, 누보는 144원(11.38%) 오른 1409원, 농우바이오는 350원(4.40%) 오른 8310원, 체시스는 39원(3.96%) 오른 1025원, 태경비케이는 80원(1.80%) 오른 4515원이다.중동은 세계 최대 비료 교역로이자 비료 원료 생산국이기도 하다. 질소비료의 주 원료인 요소는 천연가스에서 나오는 수소로 만드는데, 카타르의 LNG(액화천연가스) 생산 시설이 이란의 드론 공격으로 가동 중단됐다. 이에 카타르 내 요소생산공장도 중단됐다. 카타르는 전 세계 요소 수출량의 11%를 차지하고 있다. 카타르가 LNG 생산을 중단하면서 인도와 파키스탄 등 요소 공장 가동에도 차질이 생겼다.전쟁으로 비료 생산과 수출에 차질이 생기면서 비료 가격이 오르고 있다. 북반구 농가가 봄 파종에 앞서 비료를 뿌리는 시기가 도래하면서 비룟값은 더욱 가파르게 치솟았다. 로이터통신 등 외신에 따르면 지난 5일 기준 미국 최대 비료 수입항인 뉴올리언스 기준 요소비료 가격은 전주 대비 32.4% 올랐다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005327032', 'https://imgnews.pstatic.net/image/008/2026/03/09/0005327032_001_20260309093010455.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-03-09 09:29:04', 0, true, '2026-03-09 05:44:54.377094') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (581, 'KG케미칼, 컴플라이언스 경영시스템 도입', '전사 리스크 진단·내부통제 강화 통해 국제표준 인증 확보이용기 한국준법진흥원장(왼쪽)과 김재익 KG케미칼 대표이사가  지난 23일 KG타워 하모니홀에서 기념 촬영을 하고 있다. ⓒKG케미칼[데일리안 = 정진주 기자] KG케미칼은 지난 23일 KG타워 하모니홀에서 윤리·준법경영 강화를 위해 컴플라이언스 경영시스템을 도입하고, 국제표준화기구(ISO)가 제정한 ▲준법경영시스템(ISO 37301)과 ▲부패방지경영시스템(ISO 37001) 인증 수여식을 진행했다고 24일 밝혔다.이번 인증 획득은 지난해 10월부터 약 4개월간 전사적인 리스크 진단과 내부통제 시스템 강화를 추진한 결과라고 회사 측은 설명했다. 컴플라이언스 경영시스템 도입을 위해 ▲준법경영 정책 수립 ▲리스크 식별 및 평가 ▲내부 규정 및 업무 프로세스 정비 ▲임직원 대상 컴플라이언스 교육 ▲내부 점검 및 개선 체계 구축 등을 단계적으로 추진해 왔다.김재익 KG케미칼 대표이사는 “이번 ISO 인증 획득은 단순한 제도 도입을 넘어, 전 임직원이 준법과 윤리를 핵심 가치로 인식하고 실천하는 경영문화 정착의 중요한 이정표”라며 “앞으로도 컴플라이언스 경영을 지속적으로 고도화해 투명한 지배구조를 바탕으로 고객과 이해관계자로부터 신뢰받는 기업으로 성장해 나가겠다”고 말했다.', NULL, '데일리안', 'https://n.news.naver.com/mnews/article/119/0003062525', 'https://imgnews.pstatic.net/image/119/2026/02/24/0003062525_001_20260224175014985.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-02-24 17:50:14', 0, true, '2026-03-09 05:44:54.377094') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (582, 'KG그룹 6개 가족사, ‘ISO 컴플라이언스·부패방지’ 인증 획득', '[이코노미스트 박세진 기자] KG그룹이 국제표준화기구(ISO)가 제정한 규범준수경영시스템(ISO 37301)과 부패방지경영시스템(ISO 37001) 인증을 동시에 획득했다.KG그룹은 한국준법진흥원으로부터 두 인증을 함께 받았다고 24일 밝혔다. 이번 인증은 그룹 차원의 내부통제 및 컴플라이언스 체계를 국제 기준에 맞춰 끌어올렸다는 의미가 있다.대상은 KG케미칼·KG에코솔루션·KG모빌리티·KG스틸·KG모빌리언스·KG이니시스 등 상장 가족사 6곳이다.KG그룹은 지난해 10월부터 약 4개월 동안 6개 주요 상장 가족사를 대상으로 전사적 리스크 이슈 풀을 구축했다. 이를 토대로 그룹의 비즈니스 방향성과 정합성을 갖춘 방식으로 리스크를 식별·검토하는 절차를 진행해 왔다.통합 인증을 계기로 KG그룹은 그룹 통합 컴플라이언스 경영 시스템을 도입하고 전사적 리스크 관리 체계를 한 단계 고도화했다. 거버넌스·리스크관리·컴플라이언스를 아우르는 GRC 운영 기반도 마련했다는 설명이다.아울러 기업 운영 전반에서 발생할 수 있는 위법·부패 관련 잠재 리스크를 사전에 식별하고 통제할 수 있는 시스템적 토대를 구축해 대외 신뢰도를 높이고, ESG 경영의 핵심 요소로 꼽히는 투명하고 윤리적인 지배구조 확립 기반을 갖췄다고 밝혔다.KG그룹 관계자는 “이번 ISO 통합 인증은 재무적 성장과 함께 비재무적 가치 창출 역량을 동시에 강화하는 계기”라며 “성숙한 리스크 관리 체계를 바탕으로 그룹의 지속 가능한 통합적 가치를 높여가겠다”고 말했다. 이어 “글로벌 스탠다드에 부합하는 투명한 지배구조를 통해 주주와 고객 등 이해관계자에게 신뢰받는 기업으로 자리매김하겠다”고 덧붙였다.법무법인 바른 관계자는 “기업전략연구소와 GRC TF 변호사 그룹이 KG그룹 6개 주요 가족사의 전사적 리스크 이슈 풀 구축을 지원했다”며 “그룹 전략과 정합성을 갖춘 리스크 식별·평가와 임원 교육 등을 통해 그룹 통합 차원의 실행력 있는 GRC 운영 기반 마련을 지원했다”고 밝혔다.한편 KG그룹 내 상장사 CEO들은 통합 인증의 실질 이행 의지를 대내외에 알리기 위해, 각 가족사 대표이사가 임직원 앞에서 ‘준법 서약서’에 직접 서명하는 서약식과 전 임직원이 참여하는 ‘준법경영 선포식’을 열었다.', NULL, '이코노미스트', 'https://n.news.naver.com/mnews/article/243/0000093539', 'https://imgnews.pstatic.net/image/243/2026/02/24/0000093539_001_20260224111614001.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-02-24 11:16:14', 0, true, '2026-03-09 05:44:54.377094') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (583, '성수동 ‘월리’ 흥행…태원물산 “제조 벗고 글로벌 IP 브랜드 전환”', '단순 하청, 제조 탈피글로벌 IP 결합 “고수익 브랜드 기업 전환”올해 매출 500억원 목표코스피 상장사 태원물산이 전통 제조업 중심의 사업구조에서 ‘글로벌 지식재산권(IP) 기반의 브랜드 전문 기업’으로 전환에 나선다. 서울 성수동에서 흥행 돌풍을 일으킨 ‘월리를 찾아라’ 전시를 신호탄으로 자체 브랜드 사업을 핵심 성장 동력으로 육성한다는 전략이다.태원물산이 서울 성수동에서 진행 중인 ‘월리를 찾아라’ 전시장. /태원물산 제공태원물산은 자동차 부품 제조, 식자재 유통 등 기존 사업의 저성장 기조를 타개하기 위해 직접 기획하고 소유권을 확보한 ‘자체 브랜드 사업’을 주요 사업으로 육성한다고 5일 밝혔다.태원물산 브랜드 전략의 핵심 무기는 세계적인 콘텐츠 기업들과의 파트너십이다. 태원물산은 최근 유니버설 스튜디오, 일본 IP 전문 기업 SMG홀딩스 등과 전략적 계약을 잇달아 성사시키며 IP 포트폴리오를 구축했다. 단순히 해외 캐릭터를 들여와 유통하는 데 그치지 않고, 회사가 직접 기획한 제품에 두터운 팬덤을 보유한 글로벌 캐릭터를 입히는 방식이다. 이를 통해 신규 브랜드의 약점인 ‘초기 인지도 부족’을 극복하고 마케팅 효율을 끌어올려, 국내외 시장에서 강력한 브랜드 파워를 형성하겠다는 전략이다.이 같은 전략은 이미 시장에서 좋은 반응을 얻고 있다. 서울 성수동에서 진행 중인 ‘월리를 찾아라(Where’s Wally?)’ 전시는 월 평균 약 2만 명의 관람객을 끌어모으며 흥행을 이어가고 있다. 이번 전시는 태원물산이 유니버설 스튜디오와 직접 라이선스 계약을 맺고 기획부터 운영까지 총괄한 프로젝트다. 회사는 단순 전시 대행을 넘어 글로벌 IP를 국내 트렌드에 맞게 재해석했다고 강조했다.태원물산은 전시 흥행 경험을 식음료(F&B)와 라이프스타일 전반으로 확장할 계획이다. 향후 해외 시장에도 직접 진출해 글로벌 브랜드로 자리매김하겠다는 구상이다. 사업 가속화를 위해 유망 기업 투자와 추가 전략적 파트너십 체결도 검토하고 있다.태원물산은 자체 브랜드 사업을 통해 수익 구조를 개선하고, 올해 매출 500억원 달성을 1차 목표로 내걸었다. 단순 제조 중심 기업에서 브랜드 소유 기업으로 전환해 기업가치를 재평가받겠다는 방침이다.태원물산 관계자는 “기존 제조 방식으로는 더 이상 생존과 성장을 담보할 수 없다는 절박함으로 수년간 IP 기반 신사업을 준비해 왔다”며 “검증된 글로벌 IP 활용과 독자적인 브랜드 기획력을 무기로, 저평가 된 기업가치를 끌어올리겠다”고 말했다.', NULL, '조선비즈', 'https://n.news.naver.com/mnews/article/366/0001145921', 'https://imgnews.pstatic.net/image/366/2026/03/05/0001145921_001_20260305070110730.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-05 07:01:10', 0, true, '2026-03-09 05:45:13.476395') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (584, '[서울데이터랩]이수화학 24.50% 폭등…실시간 상승률 1위', '23일 오전 9시 10분 이수화학(005950)가 등락률 +24.50%로 폭등하며 상승률 1위를 차지했다. 이수화학은 개장 직후 611,814주가 거래되었으며 주가는 전 거래일 대비 1,850원 오른 9,400원이다.한편 이수화학의 PER은 -3.46으로 상대적으로 저평가를 받고 있을 가능성을 시사하며, ROE는 -36.16%로 수익성이 낮다고 평가할 수 있다.이어 상승률 2위 에스엠벡셀(010580)은 현재가 3,350원으로 주가가 9.48% 상승하고 있다. 상승률 3위 광명전기(017040)는 현재 1,570원으로 7.83% 상승하고 있다. 상승률 4위 LS ELECTRIC(010120)은 7.51% 상승하며 343,500원에 거래되고 있다. 상승률 5위 SK케미칼우(28513K)는 6.42%의 상승세를 보이며 28,200원에 거래되고 있다.6위 유니온머티리얼(047400)은 현재가 1,864원으로 5.49% 상승 중이다. 7위 SK케미칼(285130)은 현재가 72,600원으로 5.37% 상승 중이다. 8위 명인제약(317450)은 현재가 95,600원으로 5.29% 상승 중이다. 9위 태원물산(001420)은 현재가 3,505원으로 4.94% 상승 중이다. 10위 윌비스(008600)는 현재가 344원으로 3.93% 상승 중이다.이밖에도 달바글로벌(483650) ▲3.85%, 현대로템(064350) ▲3.84%, 성문전자우(014915) ▲3.66%, SNT에너지(100840) ▲3.46%, 휴스틸(005010) ▲3.38%, 산일전기(062040) ▲3.15%, 농심(004370) ▲3.02%, 농심홀딩스(072710) ▲2.95%, KIWOOM 차이나A50커넥트MSCI(441330) ▲2.73%, 한국석유(004090) ▲2.61% 등을 기록하며 시장에서 활발히 거래되고 있다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003584581', 'https://imgnews.pstatic.net/image/081/2025/10/23/0003584581_001_20251023092217923.png?type=w800', 'NEWS_ETC', NULL, '2025-10-23 09:22:17', 0, true, '2026-03-09 05:45:13.476395') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (600, 'AI발 모멘텀 계속 가져간다…전기장비株 일제히 강제', '특징주머니투데이 특징주 그래픽 이미지지난 3, 4일 약 20% 떨어졌던 코스피가 급격히 회복되면서 기존 모멘텀을 받고 있던 전기장비주 주가도 일제히 반등하고 있다.5일 오전 9시 20분 현재 코스피 시장에서 대한전선은 전 거래일 대비 3900원(14.97%) 오른 2만9950원에, HD현대일렉트릭은 11만8000원(13.55%) 오른 98만9000원, 효성중공업은 30만2000원(13.15%) 오른 259만9000원, LS ELECTRIC은 8만2000원(13.10%) 오른 70만8000원에 거래되고 있다.같은 시각 코스닥에서는 서진시스템이 전 거래일 대비 7800원(20.86%) 오른 4만5200원, 비나텍이 1만9500원(18.54%) 오른 12만4700원, 보성파워텍이 1480원(17.94%) 오른 9730원, 서남이 480원(14.04%) 오른 3900원, 지투파워가 1200원(13.27%) 오른 1만240원 등을 나타낸다.전기장비주는 최근 AI(인공지능) 사용량 폭증에 따른 빅테크향 데이터센터발 수요, 북미 전력망 교체 등으로 실적이 급격히 올랐다. HD현대일렉트릭은 지난해 4분기 영업이익이 93.0% 오르기도 했다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005325592', 'https://imgnews.pstatic.net/image/008/2026/03/05/0005325592_001_20260305092811889.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-03-05 09:27:12', 0, true, '2026-03-09 05:45:47.270845') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (601, '‘발주 지연 폭탄’도 터지나…산업계, 중동 속앓이', '현대차 사우디 생산법인(HMMME) 공장 조감도. [사진 현대차]미국·이스라엘의 이란 공습과 이란의 강경 대응으로 중동 정세가 급격히 얼어붙으면서 국내 산업계에 긴장감이 고조되고 있다. 현지 인프라 발주 지연, 국제유가와 해상운임 급등, 공급망 차질 우려 등 악재가 동시다발적으로 번지는 양상이다.4일 재계에 따르면 중동 현지 프로젝트를 수행 중인 기업들은 발주처의 의사결정 지연 가능성을 예의주시하고 있다. 사태가 장기화할 경우 착공 일정이 늦어지거나 금융 조달 여건이 경색될 가능성을 배제하기 어렵다는 분위기다.중동 사업은 단순 제품 수출과 달리 대규모 인프라 프로젝트 비중이 높아 외부 변수에 취약한 구조다. 사우디아라비아의 ‘네옴시티’ 등 초대형 개발 사업이 진행 중인 가운데 긴장 국면이 이어질 경우 일부 사업의 진행 속도가 더뎌질 수 있다는 관측이 나온다.김주원 기자삼성은 중동에 건설·연구·영업 거점을 운영하고 있다. 사우디에서는 삼성물산이 건설 프로젝트에 참여하고 있고, 이스라엘에는 반도체 연구시설을 두고 있다. 현대차는 사우디 킹 살만 자동차 산업단지에 연산 5만 대 규모의 전기차·내연기관차 혼류 생산공장을 건설 중이다. 현지 생산거점을 축으로 중동 시장 공략을 강화하는 시점에 지정학 리스크가 변수로 부상했다.LG와 GS 역시 현지에서 판매·건설·부동산 사업을 병행하고 있어 신규 프로젝트 흐름에 촉각을 곤두세우고 있다. GS는 오만에만 8개 법인을 두고 플랜트·건설 사업을 수행 중이며, LG는 중동에서 판매법인과 일부 인프라 사업을 운영하고 있다.전력·기계 업계도 긴박하게 돌아가고 있다. 중동은 국내 전력기기 업체들의 최근 핵심 해외 시장으로 부상했다. 효성중공업·HD현대일렉트릭·LS일렉트릭 등은 사우디·UAE·쿠웨이트 등에서 송전망 확충과 발전 인프라 사업을 수행해왔다. 대한전선과 LS전선 역시 초고압 케이블과 해저 케이블을 공급하고 있다. 업계 관계자는 “초고압 변압기나 발전 설비는 발주부터 제작·해상 운송·현지 설치까지 수년이 걸리는 게 일반적”이라며 “발주처의 의사결정이 늦어지면 공정이 밀리면서 매출 인식 시점도 조정될 수 있다”고 말했다.유가·물류비 등 비용 부담 요인도 커지고 있다. 먼저 해상운임이 급등 조짐이다. 발틱해운거래소에 따르면 발틱원유유조선지수(BDTI)는 2일 중동~극동 노선 기준으로 42만3736달러를 기록했다. 한 달 전 12만8799달러와 견줘 세 배로 뛰었다. BDTI는 27만t 이상 초대형 유조선(VLCC)의 하루 용선료를 뜻한다. 용선료는 향후 실제 운임으로 이어지는 선행지표라는 점에서 원유 수입비용과 물류비 전반에 추가 부담이 가중될 가능성이 커졌다. 해운 업계는 유조선 운임 상승이 벌크선과 컨테이너선으로 확산될 경우 수출 기업의 물류비 부담이 더 커질 수 있다고 본다.가뜩이나 업황 부진을 겪고 있는 건설사들도 원가 상승 및 수익성 저하 리스크에 직면했다. 한국건설산업연구원에 따르면 유가가 60% 상승할 경우 건축물 생산비용은 1.5%, 토목시설 생산비용은 3% 증가한다. 한 대형 건설사 관계자는 “기존에도 원자잿값 상승 문제로 공사에 어려움이 컸는데, 전쟁이 겹치면서 공사 지연과 공사대금 미지급 등 문제가 더 커질 것으로 보인다”고 전했다.주원 현대경제연구원 본부장은 “중동 인프라 발주 지연은 건설·플랜트·전력기기 등 수주 산업 전반에 구조적 영향을 미칠 수 있다”며 “기업의 수익성 악화와 투자 위축, 현금흐름 경색이 복합적으로 나타날 가능성도 있다”고 우려했다.', NULL, '중앙일보', 'https://n.news.naver.com/mnews/article/025/0003506892', 'https://imgnews.pstatic.net/image/025/2026/03/05/0003506892_001_20260305054048564.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-03-05 00:02:01', 0, true, '2026-03-09 05:45:47.270845') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (585, '[서울데이터랩]한미글로벌 +7.82% 상승…실시간 상승률 1위', '6일 오전 9시 10분 한미글로벌(053690)이 등락률 +7.82%로 상승률 1위를 차지했다. 한미글로벌은 개장 직후 5분간 241,879주가 거래되었으며 주가는 전 거래일 대비 1,530원 오른 21,100원이다.한편 한미글로벌의 PER은 11.63으로 상대적으로 저평가를 받고 있을 가능성을 시사하며, ROE는 10.28%로 수익성이 양호한 수준이다.이어 상승률 2위 GS피앤엘(499790)은 현재가 43,200원으로 주가가 7.20% 상승하고 있다. 상승률 3위 대한조선(439260)은 현재 110,500원으로 6.45% 상승하며 좋은 흐름을 보이고 있다. 상승률 4위 퍼시스(016800)는 6.05% 상승하며 47,300원에 거래되고 있다. 상승률 5위 화인베스틸(133820)은 5.83%의 상승세를 타고 1,397원에 거래되고 있다.6위 우진(105840)은 현재가 11,390원으로 5.46% 상승 중이다. 7위 에이프로젠(007460)은 현재가 660원으로 4.60% 상승 중이다. 8위 율촌화학(008730)은 현재가 36,300원으로 4.01% 상승 중이다. 9위 SK아이이테크놀로지(361610)는 현재가 28,100원으로 3.88% 상승 중이다. 10위 한전기술(052690)은 현재가 93,500원으로 3.77% 상승 중이다.이밖에도 제이준코스메틱(025620) ▲3.70%, 코오롱모빌리티그룹(450140) ▲3.46%, 이수스페셜티케미컬(457190) ▲3.46%, 풀무원(017810) ▲3.33%, 삼성E&A(028050) ▲3.30%, 태원물산(001420) ▲3.13%, 팜스코(036580) ▲3.11%, 한국전력(015760) ▲3.00%, 카카오뱅크(323410) ▲2.94%, HDC(012630) ▲2.78% 등을 기록하며 시장에서 활발히 거래되고 있다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003563824', 'https://imgnews.pstatic.net/image/081/2025/08/06/0003563824_001_20250806092010561.png?type=w800', 'NEWS_ETC', NULL, '2025-08-06 09:20:10', 0, true, '2026-03-09 05:45:13.476395') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (586, '[서울데이터랩]대한조선 84.80% 급등…금일 증시 상승률 1위로 마감', '1일 오후 15시 35분 대한조선(439260)가 등락률 +84.80%로 상승률 1위로 마감했다. 대한조선은 장 중 14,528,507주가 거래되었으며 주가는 전 거래일 대비 42,400원 오른 92,400원에 마감했다.한편 대한조선의 PER은 7.42로 평가되었으며, ROE는 55.26%로 나타나 수익성이 높은 수준으로 평가받았다.이어 상승률 2위 풀무원(017810)은 주가가 18.91% 급등하며 종가 17,670원에 상승 마감했다. 상승률 3위 엔케이(085310)의 주가는 1,194원으로 12.22% 급등했다. 상승률 4위 온타이드(005320)는 8.70% 상승하며 587원에 마감했다. 상승률 5위 대양금속(009190)은 7.58%의 상승세를 타고 종가 1,618원에 마감했다.6위 한성기업(003680)은 종가 5,450원으로 6.45% 상승 마감했다. 7위 KR모터스(000040)는 종가 640원으로 4.58% 상승 마감했다. 8위 한화오션(042660)은 종가 117,400원으로 4.54% 상승 마감했다. 9위 STX엔진(077970)은 종가 24,650원으로 3.57% 상승 마감했다. 10위 인디에프(014990)는 종가 1,469원으로 2.58% 상승 마감했다.이밖에도 태원물산(001420) ▲2.18%, 흥국화재우(000545) ▲2.04%, 대림통상(006570) ▲1.97%, 화인베스틸(133820) ▲1.95%, 일신석재(007110) ▲1.73%, KIWOOM 미국달러선물레버리지(225800) ▲1.58%, 한화엔진(082740) ▲1.44%, 세진중공업(075580) ▲1.38%, JW중외제약2우B(001067) ▲1.11%, KIWOOM 미국달러SOFR금리액티브(합성)(460270) ▲1.08% 등을 기록하며 금일 증시를 상승으로 마감했다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003562830', 'https://imgnews.pstatic.net/image/081/2025/08/01/0003562830_001_20250801154820358.jpg?type=w800', 'NEWS_ETC', NULL, '2025-08-01 15:48:20', 0, true, '2026-03-09 05:45:13.476395') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (587, 'IPO 신호탄에 달아오른 우주株 랠리...밸류체인 주목, 자금 조달 리스크 주의', '스페이스X 광풍, 지금 올라타도 되나스페이스X의 미국 증시 상장 가능성이 높아지자 국내외 우주 테마주가 달아오르고 있다. 국내 투자자가 스페이스X 같은 미국 비상장 기업에 직접 투자하는 건 현실적으로 불가능하다. 미국 기업공개(IPO)는 한국처럼 개인이 일반 청약에 참여하는 구조가 아니기 때문이다.투자자들은 발 빠르게 ‘우회 경로’를 찾고 있다. 크게 보면 ▲ 스페이스X 지분을 보유한 상장사 ▲ 스페이스X 지분을 담은 해외 펀드·ETF ▲ 스페이스X와 거래하는 밸류체인(가치사슬) 공급망 기업으로 갈린다. 같은 ‘스페이스X’로 묶이지만 수익이 나는 구조는 셋이 완전히 다르다. 투자자들은 ‘무엇을, 어떻게’ 사는지부터 점검해야 한다는 것이 전문가들 한목소리다.스페이스X 우회 투자 어떻게‘지분·ETF·폐쇄형 펀드’ 주목첫 번째 방법은 ‘지분 보유 상장사’ 투자다. 국내 상장사 중에선 미래에셋증권이 대표적이다. 미래에셋증권은 스페이스X 외에도 스페이스X와 합병한 인공지능(AI) 기업 xAI 등에 총 4억달러(약 5800억원) 이상을 투자한 것으로 알려졌다. 아주IB투자도 스페이스X 지분을 보유 중인 것으로 전해진다.또 다른 방법은 해외 투자 상품이다. 미국 자산운용사 ER셰어스가 운용하는 ‘ER셰어스 프라이빗-퍼블릭 크로스오버(XOVR)’ ETF가 대표적이다. XOVR은 상장 기업과 비상장 기업을 동시에 편입하는 액티브형 상품이다. 개인이 투자하기 어려운 비상장 기업을 ETF를 통해 손쉽게 거래할 수 있도록 만든 것이 특징이다. 스페이스X 등 비상장 기업 주식을 보유한 특수목적회사(SPV) 지분을 취득하는 방식으로 포트폴리오를 구성한다.ER셰어스 홈페이지 내 XOVR ETF 구성 내역을 보면, ‘ER셰어스 프라이빗-퍼블릭 크로스오버(XOVR)’ ETF의 스페이스X 투자 비중은 21.4%에 달한다. 올해 초 10% 정도였는데 스페이스X의 IPO가 가시화한 뒤 비중이 높아졌다.펀드를 활용해 스페이스X 등 비상장 기업에 투자하는 길도 열려 있다. 미국 뉴욕 증시에 상장된 ‘데스티니 테크100(DXYZ)’은 폐쇄형 펀드 구조다. 포트폴리오에는 스페이스X를 비롯해 쉴드AI, 데이터브릭스, 오픈AI 등 성장성이 부각된 비상장 기업들이 다수 포함돼 있다. 다만 폐쇄형 펀드는 ETF와 달리 수시로 설정과 환매가 이뤄지지 않아 순자산가치(NAV)가 고정된다. 투자 수요가 몰리면 주가가 NAV보다 높게 평가될 수 있다. 이동헌 신한투자증권 애널리스트는 “DXYZ는 가격과 NAV 격차가 커 투자에 유의할 필요가 있다”고 들려줬다.우주 투자, 본게임은 ‘공급망’특수합금·센서 등 K기업 기회 있다증권 업계가 주목하는 투자법은 세 번째, 밸류체인 투자다. 우주 산업의 밸류체인은 발사체·위성·통신·방산·소재·지상장비로 넓게 퍼져 있다. 그런데 뉴스페이스 시대의 핵심은 발사 단가 하락이 물량(Q)을 키우고, 그 물량이 공급망 매출로 연결되는지다. 증권 업계는 스페이스X와 직접 연결된 국내 기업이 소수라는 점을 전제하면서도 특수합금, 방산 등 일부 기업은 스페이스X와 동반 성장이 가능한 구조를 갖췄다고 평가한다.소재·부품 분야에서는 스피어가 두각을 나타내는 중이다. 스피어는 스페이스X의 5대 핵심 공급 업체 중 하나다. 2035년까지 약 10억달러 규모의 특수합금 장기 공급 계약을 체결하며 안정적인 수주 기반을 확보했다. 발사체와 엔진에 필수적인 고내열·고강도 합금을 공급하는 구조다. 첨단 금속 소재 기업 에이치브이엠도 고순도 진공용해 기술을 앞세워 스페이스X의 랩터 엔진용 특수 금속을 납품하고 있다. 2025년 말부터 스페이스X향 물량이 빠르게 늘었고, 2026년 우주 산업 관련 매출 비중이 60%를 웃도는 것으로 전해진다.세아베스틸지주는 미국 텍사스에 항공우주·방산용 특수합금 공장을 건설 중이다. 자회사 세아창원특수강을 통해 스페이스X에 특수합금을 공급하는 방안도 추진하는 것으로 알려졌다. 롯데케미칼 역시 최근 고기능성 합성소재 일부를 스페이스X에 납품했다는 후문이다. 다만 공급 물량은 1t 미만 수준으로 크지 않다.광학·센서 분야에서는 파이버프로가 존재감을 키운다. 1997년 설립된 이 회사는 광 계측기기와 광섬유 관성센서, 분포형 온도센서 등을 생산해왔다. 최근 미국 방산·우주 시장에 고정밀 광섬유 관성센서를 공급, 점유율을 확대하고 있다. 스페이스X의 스타링크 서비스가 전 세계 어디서든 고속 인터넷 접속을 가능하게 하는 위성 인터넷 시스템을 구축하고 있다.스페이스X가 열어젖힌 저궤도 통신 시장이 커질수록 지상장비·단말기·데이터 처리 같은 연관 시장도 함께 성장할 가능성이 크다. 우주 데이터센터 구상이 현실화할 경우 전력과 열관리, 나아가 태양광 같은 인프라 테마가 다시 연결될 수 있다는 관측도 나온다.최도연 SK증권 리서치센터장은 “고객의 위성을 원하는 궤도에 안착시키는 발사 서비스, 저궤도 위성을 활용한 통신, 저궤도 위성 영상 분석 등 여러 분야에서 실질적인 수익을 창출할 수 있음이 증명되는 시기”라며 “뉴스페이스 시대에서는 우주 인프라를 활용해 부가가치를 창출하는 각종 서비스 경쟁이 치열해지고 관련 시장 성장세가 두드러질 것”이라고 진단했다.우주株 투자 유의할 점은자금 조달·정책 리스크 변수그렇다면 지금 우주 산업 관련주 투자에 나서도 괜찮을까. 전문가들은 현재 우주 투자 시장이 ‘과열’ 상태라고 평가한다. 주가 상승 속도가 기업 실적 대비 과도하다는 지적도 제기된다. 대표적으로 미래에셋증권의 예상 주가수익비율(PER)은 약 21배 수준으로, 최근 5년 평균 대비 3배가량 높은 상태다. KB증권은 스페이스X 투자 가치 상승이 실제 주주 수익으로 이어지기까지 불확실성이 존재한다고 봤다. 펀드 평가이익 상당 부분이 미실현 이익에 해당해 단기 실적에 직접 반영되기 어렵다는 이유다.과열 우려 속 우주 산업 성장에 관한 기대도 적잖다. 위성이 늘면 통신·관측·정찰 같은 서비스가 커지고, 다시 위성·지상장비·단말기 수요로 이어지는 선순환이 만들어지기 때문이다.정의훈 유진투자증권 애널리스트는 “밸류에이션만 놓고 보면 과열 구간이 맞지만, 구조적 성장 단계에서 성장률이 부각되는 시기라 변동성이 크게 나타난다”며 “현재는 위성 제조 영역이 성장하고 있고, 시간이 지날수록 서비스 시장과 지상장비 시장 성장으로 이어질 것”이라고 봤다.우주 산업 특유의 자금 조달 리스크도 변수다. 우주 산업은 연구개발(R&D)과 시험 발사 과정에서 현금 소진이 크고, 이 구간에서 유상증자나 전환사채 발행이 잦아질 수 있다. 기업 기술력과 함께 자금 조달(증자) 리스크를 검토해야 하는 이유다.해외 정책 변화도 주의 깊게 살펴야 한다.우주 산업은 국가 안보와 직결된 전략 산업이다. 미국 NASA나 국방부 등 핵심 기관의 예산 집행과 정책 방향에 따라 시장 판도가 단숨에 뒤바뀔 수 있다. 한유건 하나증권 애널리스트는 “우주 산업 투자자는 개별 기업 기술력뿐만 아니라, 주요국의 우주 정책 변화와 지정학적 변수를 지속해서 모니터링해야 한다”고 전했다.인터뷰 | 방효충 KAIST 항공우주공학과 교수(국가우주위원회 부위원장)상업 우주 法 제정, ‘韓 스페이스X’ 첫 단추글로벌 우주 산업이 커지며 스페이스X 상장 이슈가 글로벌 자본 시장을 달구고 있다. 한국 우주 산업도 이런 성장세에 올라탈 수 있을까. ‘한국형 스페이스X’는 현실 가능한 목표일까. 국가우주위원회 부위원장인 방효충 KAIST 항공우주공학과 교수에게 조언을 구했다.방효충 KAIST 항공우주공학과 교수Q. 스페이스X 상장은 국내외 우주 산업에 어떤 파장을 미칠까.A.일반 우주기업 상장과는 차원이 다르다. 스페이스X는 일론 머스크의 혁신적 경영 방식과 스타링크, 스타십 등 독보적 사업 모델을 보유했다. 단순한 기업 성장 이상의 의미를 가진다. 우주 산업 전반의 ‘빅 웨이브’로 볼 수 있다. 국내에서도 민간 중심의 우주 개발 움직임이 더욱 활발해질 가능성이 크다.Q. 글로벌 우주 산업 전망은 어떻게 보나.A.장기 전망은 밝다. 우주 산업 전체를 100으로 볼 때 발사체와 위성 제작은 약 15%에 불과하다. 나머지 85%는 영상, 통신, 데이터 등 서비스 영역이다. 위성 항법 시장은 발사체 시장의 10배 이상이다. 향후 우주 산업은 1조달러 이상으로 성장할 전망이다. 스타링크, 인공지능, 우주 데이터센터, 저궤도 통신, 6G 등은 모두 우주 기반 인프라가 필요하다. 다만 기술 실패와 규제 리스크는 여전하다.Q. 한국의 발사체 기술 수준과 상업 발사 역량은 어느 수준인가.A.발사체 사업은 늦게 출발했다. 중국과 일본보다 정확히 50년 뒤처졌다. 1970년 두 나라가 발사에 성공했고 우리는 2022년에서야 누리호를 발사했다. 격차는 분명 존재한다. 현재 상업 발사국들은 95~98%의 성공률을 보유한다. 우리는 아직 발사 횟수가 적다. 하지만 과거 자동차·반도체·조선 산업도 초기 경쟁력이 압도적이라 시작한 것은 아니었다. 인내와 축적이 필요하다. 누리호의 민간 기술 이전이 본격화되면 상업 발사 시점이 예상보다 빨라질 가능성도 있다.Q. ‘한국판 스페이스X’ 육성을 위한 전략은.A.스페이스X도 초기에 발사 3회 연속 실패를 겪었다. 이후 NASA 발주와 군 수요가 결합하면서 성장 기반을 확보했다. 정부 수요 창출과 정책적 지원이 필수적이라는 얘기다. 현재 우주 개발의 목표는 외교·안보에서 경제 중심으로 전환됐다. 우주를 하나의 산업 생태계로 봐야 한다. 정부와 기업이 함께 힘을 모아 전략을 수립해야 한다. 우주 데이터센터 같은 신시장에서 기회를 찾을 가능성도 높다.Q. 정부 차원의 역할도 필요할 텐데.A.상업 우주에 대한 기본 법제 정비가 필요하다. 미국은 1980년대부터 상업 우주 관련 법 체계를 갖췄지만 우리는 아직 미흡하다. 민간이 위성을 활용해 통신 서비스를 할 경우 각종 규제를 받는다. 이를 체계적으로 정비해야 한다. 특히 국방 분야 수요와의 연계가 중요하다. 미국도 군 수요를 통해 민간 기업이 자립 기반을 확보했다. 초기에 정부가 안정적 물량을 제공하면 기업이 차근차근 성장할 수 있다.[조동현 기자 cho.donghyun@mk.co.kr][본 기사는 매경이코노미 제2349호(2026.03.04~03.10일자) 기사입니다][Copyright (c) 매경AX. All rights reserved. 무단 전재, 재배포 및 AI학습 이용 금지]', NULL, '매경이코노미', 'https://n.news.naver.com/mnews/article/024/0000103936', 'https://imgnews.pstatic.net/image/024/2026/03/07/0000103936_001_20260307202307115.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-07 20:23:07', 0, true, '2026-03-09 05:45:23.676583') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (588, '[증시 인사이트] 美-이란 전쟁 장기화 우려…금융시장 긴장감 최고조', '■ 머니쇼+ ''증시 인사이트'' - 정의훈 유진투자증권 선임연구원, 이지은 이지스탁 대표어제(3일)에 이어 오늘(4일)도 우리 증시는 큰 폭으로 하락했습니다. 양 시장 통틀어 상승한 종목이 100개도 안 되는 ''검은 수요일''인데요. 우리 시장, 어떻게 바라봐야 할지 알아보겠습니다. 유진투자증권 정의훈 선임연구원, 이지스탁 이지은 대표 모셨습니다.Q. 오늘 우리 증시, 양 시장 모두 서킷 브레이커 발동으로 거래가 일시 중단되기도 했습니다. 중동 전쟁 영향이 상당히 큰 듯한데요. 오늘 우리 증시 어떻게 보셨습니까?- 코스피 장중 한때 12%대 하락…''01년 9월 이후 처음- 코스피·코스닥 큰 폭 하락…장중 서킷브레이커 발동- 코스피, 장중 한때 매도 사이드카 발동…"이틀 연속"- 코스피, 장중 큰 폭으로 급락하며 5500선도 내줘- BofA "가파르게 상승한 코스피, 더 큰 조정 우려"- "투매가 투매 불러"…반대매매 공포 현실화 우려- 달러·원, 오늘(4일) 새벽 외환시장서 1500원 넘기도- 미국- 이란 전쟁에 안전자산 달러화 쏠림 현상 가중- 금융당국, 어제(3일) 중동 사태 관련 긴급회의 개최- 금융당국 "필요시 100조+α 조치 시행할 계획"- 코스피, 한때 5200 하회…화요일 이어 검은 수요일- 美- 이란 전쟁 장기화 우려…금융시장 긴장감 최고조- 美, 이란 공격…지정학적 위기 고조·유가 급등세- 호르무즈 해협 봉쇄 현실화…국내 산업계도 비상- ''22년 러우 전쟁 발발 후 유럽 타격…''에너지 위기''- 중동 사태 장기화 시 국제유가 100달러 돌파 우려- 이란 혁명수비대 "호르무즈 통과 선박 공격할 것"- 이란 호르무즈 해협 봉쇄…에너지 공급 차질 우려- 트럼프 "필요시 미군이 호르무즈 해협서 유조선 호송"- 트럼프 "염두에 뒀던 이란 ''차기 지도자'' 후보들 사망"- 이란, 새 최고지도자로 하메네이 차남 선출 임박- 하메네이 차남 지도자 선출 시 美 공격 거세질까- 트럼프 "이란, 해군도 없고 공군도 무력화됐다"- 이란 "최첨단 무기 남았다…아직 손도 안 댄 상황"- 트럼프, 협조 거부 스페인에 "모든 무역 중단할 것"- NYT "이란, 대가 치르더라도 장기전 하려 들 것"- NYT "이란에게는 정권 생존이 현재 최우선 목표"- 이란 최고지도자 선출 기구 청사, 폭격에 붕괴- 청사 붕괴에 이란 후계자 발표 연기될 가능성도Q. 미국과 이란 간의 전쟁으로 인해 우리 증시, 시총 상위주부터 줄줄이 큰 폭의 하락을 보였습니다. 특히 어제 강세를 보였던 한화에어로스페이스, 한화시스템은 변동성이 상당했습니다. 방산주 중에서는 LIG넥스원만 살아남나 싶었는데 끝내 하락 전환하며 낙폭을 키웠어요?- 하나證 "중동정세 불안…방공체계 수요 확대 기대"- 하나證 "美 패트리어트 보완할 천궁- II 부상"- 유럽, 다연장로켓 수요↑…한화에어로 ''천무'' 주목- 美 공습에 이란은 미사일·드론 등으로 보복 공격- 중동 각국 방공망 보강 필요성 대두…K- 방산 주목Q. LIG넥스원만 오늘 장에서 살아남은 이유는 실전 투입된 천궁- II 때문이라고 하는데요. 이제 국내 방산기업들도 ''발사형 무기''에 본격적으로 집중하게 될 듯해요. 천궁- II는 미국 패트리어트 미사일의 보완재로도 부상했다고 하더라고요. 특히 한국항공우주 등 지상이 아닌 공중전이 가능한 기업들도 주목받더라고요. 이번 미국과 이란의 전쟁에서 드론도 무기로 사용됐다고 하던데, 국내 기업 중에서도 드론 및 발사체와 관련해 주목해 볼 기업도 있을까요?- LIG넥스원 천궁, 美 패트리어트 보완재로 부상- 천궁- II, UAE서 첫 실전 투입…요격률 90% 이상- LIG넥스원, UAE와 ''22년 천궁- II 공급 계약 체결- 천궁- II 포대, 발사대·레이더·교전통제소 등 구성- 천궁- II 유효사거리 약 20km…중거리·중고도 무기Q. 반도체 투톱을 비롯한 중소형주 모두가 주춤한 상황입니다. 삼성전자도 17만 원대로 내려앉았고 SK하이닉스도 90만 원 선을 밑도는데요. 모바일월드콩그레스, MWC에서 새로운 뭔가를 발표해도 중동 사태로 인한 타격이 크고 국내외 증권가의 낙관적 전망에도 조정이 깊은 듯해요?- 삼성, MWC 2026서 AI 네트워크 플랫폼 공개- 현지시간 2일 스페인에서 MWC 2026 개막- MWC 2026, 삼성전자·화웨이·샤오미 등 참가- MWC, 올해로 개최 20주년…주제는 ''IQ 시대''- 맥쿼리 "삼전·하닉 올해 합산 영업익 573조 원 전망"- 맥쿼리 "삼성전자 목표주가 34만 원으로 상향"- 맥쿼리 "SK하이닉스 목표주가 170만 원으로 상향"- 삼성, MWC 2026서 갤 S26 중심 전시부스 운영- 삼성, 갤럭시 생태계 전반 AI·네트워크 혁신 공개- 삼성 "2030년까지 AI- 휴머노이드 자율 공장 전환"- 삼성, 제조 혁신에 에이전틱 AI 적용 계획 밝혀- 삼성 "에이전틱 AI로 생산 과정 전반 지능화"- 증권가, 삼성전자·하이닉스 영업익 전망치 상향- 증권가 "HBM 등 AI 메모리 수요 기대감 커져"- AI 붐에 SK하이닉스 낸드플래시 매출 48%↑Q. 중동 사태에 가려지긴 했지만 현재 스페인에서 모바일월드콩그레스가 열리고 있습니다. AI 시대가 열리면서 광통신, 위성통신 등 통신 관련주들도 주목하게 되는데요. 지난해만 해도 국내에서 저궤도 위성통신에 대한 기대가 있었는데 요즘은 시들해진 느낌이기도 해요. 그래도 올해 스페이스X 상장도 있고, 우주 AI 데이터센터 기대감도 있으니 위성통신 관련주에 주목해도 될까요?- 스페이스X, 재무제표 정리…투자자에 신뢰 높여- xAI·X, 기존 175억 달러의 부채 전액 상환 결정- 스페이스X, 계열사 부채 리스크 완전 제거 나서- 블룸버그 "스페이스X, 이르면 이달 상장 서류 제출"- 스페이스X 상장 시 최대 1.8조 달러의 가치 기대- 에이치브이엠, 민간 우주 시대 최대 수혜주 부각- 에이치브이엠, 신형 발사체 상용화 직접 수혜 기대- 에이치브이엠, 우주항공용 핵심 소재 공급 늘 전망- 세아베스틸, 고부가가치 특수강 제조사로 주목- 스피어, 우주항공용 렌즈·광학 부품 생산에 주목- 스페이스X 로켓 발사↑…소모성 부품·소재 수요 확대- 스피어, 우주항공 특수합금 분야 글로벌 강자로- 올해 MWC 화두 ''지상 6G·위성 네트워크 결합''- 끊김 없는 통신 인프라 경쟁…스타링크 보유 美 선두- 화웨이 등 中 기업들 "위성보다 6G 통신에서 승부"- 유진證 "인텔리안테크, 스페이스X발 모멘텀 본격화"Q. 중동 사태로 인해 영향을 받은 섹터가 바로 정유주, LPG 관련주입니다. 트럼프 대통령이 호르무즈 해협 방어 의지를 보였지만 오늘 장에서도 대부분 오름세를 보였습니다. 상한가도 여럿 나왔잖아요?- 정부 "수급 우려…중동 외 대체 원유 확보 추진"- 정유주, 이란 사태 격화·유가 상승 영향에 급등- 원유 공급 차질 발생 시 정제마진 개선 기대감↑- 국내증시 급락세…방산·정유주도 상승 탄력 줄어- WTI 74달러 선…두바이유·브렌드유 80달러 선- 호르무즈 긴장 고조…호주·동남아 "석유 재고 충분"- 중동 사태, 장기전으로 번져…인플레이션 직격탄- 달러·원, 장중 한때 심리적 방어선 1500원 넘어- 정부 "석유·가스 비축 충분…단기 수급 문제없어"- 오늘 오전 9시 서울 휘발유 평균가격 1820.5원- 오늘 오전 9시 전국 휘발유 평균가격 1751.4원- 국제유가 급등·고환율에 주유소로 시민들 몰려- 주유 가격 급등에 흥구석유 등 유류도매주 화색- 국내증시 ''패닉 셀''…코스피 5000선 붕괴 위기도- iM證 "향후 1주일이 증시 급락의 분수령 될 것"Q. 오늘 양 시장에 서킷 브레이커가 발동되기도 했고, 일부 언론에서는 금융당국은 10조 원 규모의 증안펀드로 증시 하단 지지에 나서겠다는 구상도 밝혔다고 합니다. 하지만 외국인들의 코스피 순매도는 여전하고, 대형주들도 맥을 못 추는 상황인데요. 대응 전략 세우기도 쉽지 않아 졌어요. 대형주에 몰렸던 개인 투자자들 손해가 막심할 듯한데, 이틀 연속 큰 폭의 조정에도 레버리지 ETF에 베팅한 분들도 상당하다고 해요. 증권사들이 역대급 빚투에 신용거래도 속속 중단하고 있는데, 이 점도 시장에 영향을 줄 듯해요?- 금융당국 "증시 변동성 대응 위한 증안펀드 준비"- 금융당국 "증안펀드, 현재 10조 원 규모로 준비 중"- 우리 금융 "외환시장 변동성 주시…당국에 협조"- 한은 "달러 유동성 풍부…CDS 프리미엄 안정적"- 금감원 "시장 안정에 집중…24시간 비상대응체계"- 금감원 ''중도 비상대응 TF'' 구성…"감독역량 집중"- 국내증시 조정에도 개인들 ''레버리지 ETF''에 베팅- 일부 증권사 신용거래 중단…"역대급 빚투, 한도 소진"- 지난달 27일 신용거래융자잔고 32조 6689억 원- 한 달 만에 신용잔고 2조 원 증가…"빚투 역대 최대"Q. 현재 커버하고 계신 업종과 기업 대부분이 코스닥에 상장돼 있는데, 수급도 따라주지 않고 정부 지원책에도 부진은 이어지고 있습니다. 코스닥도 시총 상위 대형주에만 시선이 몰리는데요. 요즘 상황에서 위원님께서 보시기에 그래도 주목해 볼 만한, 모멘텀이 살아 있다고 볼 만한 업종이나 기업이 있다면요?- 중동 긴장 고조에…사우디 진출한 네카오 ''촉각''- 네이버, 중동 법인 재택근무로 전환·핫라인 가동- 삼성·현대차 등 중동 진출 기업 임직원 즉각 대피- 신흥 시장으로 떠오른 중동…국내 기업 다수 진출- 국내 기업 해외법인 140곳 중동에…삼성 28곳 최다(자세한 내용은 동영상을 시청하시기 바랍니다.)당신의 제보가 뉴스로 만들어집니다.SBS Biz는 여러분의 제보를 기다리고 있습니다.홈페이지 = https://url.kr/9pghjn', NULL, 'SBS Biz', 'https://n.news.naver.com/mnews/article/374/0000495778', 'https://imgnews.pstatic.net/image/374/2026/03/04/0000495778_001_20260304165210953.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-04 16:49:07', 0, true, '2026-03-09 05:45:23.676583') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (589, '철강업, 탄소비용 본격화… 일부 성장 모멘텀 주목[산업별 ESG 투자 리포트⑨]', '[한경ESG] 산업별 ESG 리포트 ⑨철강업배출권거래제(K-ETS) 제4차 계획기간(2026~ 2030년) 돌입으로 철강 업종의 무상 할당량이 전 주기에 비해 18.6%나 급감했다. 탄소배출권 구매 비용 부담과 유럽연합(EU)의 탄소국경조정제도(CBAM) 대응력이 철강 기업의 실질적인 밸류에이션을 결정짓는 핵심 변수로 부상하고 있다. 이에 따라 철강 산업은 수소 기반의 저탄소 플레이어로 진화해야 하는 필연적인 과제에 직면했다.K-ETS 4차 계획기간 돌입…유상할당 상향·CBAM 전면 시행기후에너지환경부는 ‘제4차 계획기간 국가 배출권 할당계획’을 수립하고 2026~2030년에 적용될 배출권 할당을 완료했다. 4차 계획기간의 배출허용 총량은 발전 부문 8억5000만 톤, 발전 외 부문 16억8000만 톤 등 약 25억4000만 톤 규모다. 이는 전기에 비해 5억 톤가량 감소한 수치다. 할당 구조는 무상 할당 21억 톤, 유상 할당 2억6000만 톤, 신증설 예비분 8900만 톤, 시장안정화예비분 8500만 톤으로 구성돼 있어 여전히 무상 할당 비중이 높지만 감축목표의 지속적인 상향은 구조적인 가격 상승 요인으로 작용할 전망이다. 다만 무상 할당 비율이 높은 3차 계획기간 탄소배출권인 KAU25는 이러한 가격 상승 영향에서 비교적 자유로운 편이다.4차에서는 탄소집약도와 무역집약도의 곱이 0.1 이상인 업종이 무상 할당 대상이 된다. 탄소집약도는 온실가스 배출량을 부가가치 생산액으로 나누어 계산하며 무역집약도는 해당 업종의 무역의존도를 나타낸다. 기존과 동일하게 수출 비중이 높은 산업은 무상 할당이 유지되는데, 철강과 비철금속, 석유화학, 시멘트, 정유, 반도체·디스플레이, 이차전지 등이 무상 할당 대상 업종이다.2025년 12월 17일 유럽연합(EU)은 기존 탄소국경조정제도(CBAM) 6대 규제 품목(시멘트·전력·비료·철강·알루미늄·수소) 외에 철강과 알루미늄을 사용한 최종재까지 적용을 확대하는 개정안을 발표했다. 주요 최종재로 △철강·알루미늄 비중이 높은 자동차 부품 △철강·알루미늄이 포함된 가구, 의료기기, 방열기 등 복합재가 해당된다. 이렇게 확대된 품목을 담은 개정안은 유럽의회 승인을 거쳐 2028년 1월부터 본격 시행된다.특히 올해 1월 1일부터 EU의 CBAM이 전면 시행됐다. 수입업자는 EU 탄소배출권(EU ETS)과 한국의 탄소배출권(KAU)의 가격 차이에 온실가스 배출량을 곱한 만큼 CBAM 인증서 비용을 부담하게 된다. 현재 무상 할당 비율이 높은 3차 계획기간의 KAU25 가격은 EU 가격을 따라가지 못해 수출 기업들의 인증서 비용 부담이 큰 상황이다.이에 정부는 산업통상부·기후에너지환경부·중소벤처기업부·관세청 등 범정부 실무회의를 통해 CBAM 대응 실무회의를 개최했다. 범정부 지원 계획으로 △탄소배출량 산정, 보고, 검증 역량 강화 △탄소배출량 감축 △기업 담당인력 역량 강화 방안을 발표했다. 관세청은 철강·알루미늄 최종재 포함 180개 품목의 ‘EU CBAM 규제품목 한-EU 품목번호 연계표’를 제작해 EU 품목분류 CN코드와 한국의 HSK코드를 1 대 1로 매칭함으로써 수출 기업의 예측 가능성을 높이고 있다.KODEX 철강 ETF, 4차 계획기간 무상할당 감소에도 성장 모멘텀↑배출권거래제 4차 계획기간 시행에 따른 배출권 무상 할당량 감소와 올해부터 본격화되는 EU 탄소 관세의 직격을 맞는 업종은 철강 산업이다. 철은 생산 1톤당 1.8톤의 이산화탄소(CO₂)가 배출되는 대표적인 탄소집약 제품으로 한국 전체 온실가스 배출량의 39%를 차지한다. 무상 배출이 허용되는 사전 할당량은 전기 대비 18.6% 감소하면서 한국철강협회는 2030년까지 업계가 총 5100만 톤의 배출권을 추가로 구매해야 할 것으로 전망한다.철강 업계는 이러한 탄소 관세 시대에 대응해 저탄소 체제로의 전환을 서두르고 있다. 대표적인 핵심 기술은 철광석의 산소 분리 과정에서 석탄 대신 수소를 사용하는 수소환원제철이다. 포스코는 2028년까지 포항제철소 내 30만 톤 규모 수소환원제철 설비 준공 및 검증으로 배출권거래제 4차 마지막 해인 2030년까지 기술 상용화를 완성하겠다는 계획이다.현재 국내 상장 철강 기업은 코스피 37개 기업(시가총액 44조 원), 코스닥 17개 기업(시가총액 1조7000억 원)에 달한다. 하지만 총 54개 상장기업 중 애널리스트 추정치가 존재하는 기업은 11개뿐이다. 커버리지가 많지 않고 유동성도 작다 보니 상장지수펀드(ETF) 거래 규모도 미미했다. 국내 ETF로 상장된 철강 ETF는 둘뿐으로 시가총액이 280억 원인 KODEX 철강 ETF가 시가총액 70억 원인 TIGER 200 철강 소재 ETF보다는 컸다.최근 한국 증시의 활황 속에도 철강 업종의 낮은 주가순자산비율(PBR)은 여전히 저평가 구간에 있어 밸류에이션 매력이 높다. 특히 오는 6월 예정된 스페이스엑스(SpaceX) 상장 기대감과 맞물려 우주항공용 특수합금 수요 확대 수혜주가 강세를 보이고 있는데 세아베스틸지주와 에이치브이엠이 대표적이다. 이 두 종목은 1년간 주가가 2~3배 급등하며 ETF 편입 종목 중 가장 강력한 주가 모멘텀을 기록하고 있다.특히 세아베스틸지주는 1년간 350%의 주가수익률을 기록했음에도 불구하고 12개월 선행 주가수익비율(PER) 29.4배, PBR 1.4배로 여전히 비싸지 않고 향후 안정적인 매출과 이익 성장이 전망된다. 최근 시가 총액 대비 금융투자 순매수 강도가 강한 기업은 세아베스틸지주, 에이치브이엠, 포스코엠텍 순으로 강하게 유입되며 시장의 기대감을 반영하고 있다.박우열 신한투자증권 수석연구원', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005257790', 'https://imgnews.pstatic.net/image/015/2026/03/04/0005257790_001_20260304072310543.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-04 07:23:10', 0, true, '2026-03-09 05:45:23.676583') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (590, '[증시 인사이트] 美-이란 전쟁 장기화 우려…금융시장 긴장감 최고조', '■ 머니쇼+ ''증시 인사이트'' - 김영환 NH투자증권수석연구원, 길건우 에프알자산관리 대표미국과 이란의 전쟁이 장기화될 우려가 생겨나며 우리 시장은 내림세를 보였습니다 특히 코스피는 장중 한때 매도 사이드카도 발동했죠? 달러원 환율도 크게 오르고, 외국인들의 매도세도 거세진 영향에 코스피는 6천 선도 내줬는데요. 변동성이 극대화된 상황 속 어떤 전략이 필요할지 알아보겠습니다. NH투자증권 김영환 수석연구원, 에프알자산관리 길건우 대표 모셨습니다.Q. 어제(2일) 하루 쉬었던 우리 증시, 쉬는 동안 여러 이슈들이 있었는데요. 오늘(3일) 개장부터 마감까지의 흐름, 어떻게 보셨습니까?- 국내증시 동반 하락…코스피, 6000선 내주며 후퇴- 장중 코스피 선물 5%대 급락…한때 매도 사이드카- 지난 주말 美·이스라엘, 이란 주요 거점 공습 시행- 美-이란 전쟁 장기화 우려…금융시장 긴장감 최고조- 증권가 "추세적 하락보다 단기적 숨 고르기 그칠 것"- 2월 반도체 수출 사상 최고…무역흑자 역대 최대- 2월 반도체 수출 251.6억달러…전년비 161%↑Q. 중동 사태 영향으로 오늘 우리 증시는 큰 폭의 조정을 받았습니다. 반도체 투톱을 비롯해 소부장주들도 쉬어가는 분위기였는데요. 올 법한 조정이 왔다고 봐야 하는 걸까요?- 美, 이란 공격…지정학적 위기 고조·유가 급등세- 호르무즈 해협 봉쇄 현실화…국내 산업계도 비상- ''22년 러우 전쟁 발발 후 유럽 타격…''에너지 위기''- 호르무즈 해협, 세계 석유 물동량의 30% 지나- 국내 도입 중동 원유 95% 이상 호르무즈 해협 통과- 일본·대만 등 아시아 전체가 중동에 에너지 의존- 중동 사태 장기화 시 국제유가 100달러 돌파 우려- 삼성·현대차 등 중동 진출 기업 임직원 즉각 대피- 신흥 시장으로 떠오른 중동…국내 기업 다수 진출Q. 사실 우리가 쉬는 동안 삼성전자가 2030년까지 AI와 휴머노이드 로봇을 도입해 자율형 공장으로 전환하겠다는 소식도 있었고, 그래서 오늘 레인보우로보틱스나 일부 로봇주들도 오름세를 보였잖아요?- 현지시간 2일 스페인에서 MWC 2026 개막- MWC 2026, 삼성전자·화웨이·샤오미 등 참가- MWC, 올해로 개최 20주년…주제는 ''IQ 시대''- 맥쿼리 "삼전·하닉 올해 합산 영업익 573조원 전망"- 맥쿼리 "삼성전자 목표주가 34만원으로 상향"- 맥쿼리 "SK하이닉스 목표주가 170만원으로 상향"- 키움證 "삼전·하닉 올해 합산 영업익 370조원 전망"- 삼성, MWC 2026서 갤S26 중심 전시부스 운영- 삼성, 갤럭시 생태계 전반 AI·네트워크 혁신 공개- 삼성 "2030년까지 AI-휴머노이드 자율 공장 전환"- 삼성, 제조 혁신에 에이전틱 AI 적용 계획 밝혀- 삼성 "에이전틱 AI로 생산 과정 전반 지능화"Q. 미국과 이란 간의 전쟁이 계속되며 오늘 우리 장에서는 방산주가 강세를 보였습니다. 지정학적 리스크가 불거져야 주가가 급등하는 업종인데, 수주 소식보다는 확실히 크게 작용한 듯해요?- 정부 "수급 우려…중동 외 대체 원유 확보 추진"- 정유주, 이란 사태 격화·유가 상승 영향에 급등- 이란 혁명수비대 "호르무즈 통과 선박 공격할 것"- 이란 호르무즈 해협 봉쇄…에너지 공급 차질 우려- 원유·석유제품·가스 등 단기 가격 급등세 보일 듯- 코스피, 한때 5900선 후퇴…외국인·기관 순매도↑- 신한證 "글로벌 원유·LNG 운송 차질 불가피"- 원유 공급 차질 발생 시 정제마진 개선 기대감↑- 가스를 석유로 대체하는 수요까지 발생할 가능성Q. 이란이 호르무즈 해협을 봉쇄하자 오늘 장에서 해운주들도 급등세를 보였습니다. 반면 하늘 길이 막히고 유가가 올라서 그런지 항공주는 하락세를 보였어요?- 이란의 호르무즈 해협 봉쇄에 해운주 급등세 보여- 해운주, 호르무즈 해협 봉쇄로 운임 상승 기대감- 유가 급등에 항공주↓…운임 상승 기대에 해운주↑- 항공주, 유가 급등 시 연료비 부담 늘며 ''부정적''- 브렌트유·WTI, 각각 전일 대비 6% 이상 급등- 해상 운임 증가 시 여러 산업에 부정적 영향 끼쳐- 국가 간 긴장 고조…운송업 중장기적 변동 유의必Q. 방산과 엮인 우주항공 관련주, 일부 스페이스X 관련주들도 오늘 장에서 흐름이 괜찮았습니다. 미국과 이란 간의 갈등이 심화되지만 스페이스X도 IPO 진행에는 차질이 없을 것이라 하고, 그와 엮인 국내 기업들도 오름세를 보이는 듯 해요?- CNBC "미국-이란 전쟁…K-방산 기업 주가 급등"- LIG넥스원, 장중 상한가 기록…방산주 일제히↑- 하나證 "중동정세 불안…방공체계 수요 확대 기대"- 하나證 "美 패트리어트 보완할 천궁-II 부상"- 한화에어로 52주 신고가…''천무'' 추가 수출 기대감- 한투證 "한화에어로, 중장기 수출 모멘텀 강화"- 유럽, 다연장로켓 수요↑…한화에어로 ''천무'' 주목- 美 공습에 이란은 미사일·드론으로 보복 공격- 중동 각국 방공망 보강 필요성 대두…K-방산 주목- 스페이스X, 재무제표 정리…투자자에 신뢰 높여- xAI·X, 기존 175억달러의 부채 전액 상환 결정- 스페이스X, 계열사 부채 리스크 완전 제거 나서- 韓-UAE, 방산 분야서 350억달러 규모 사업 협력- 韓-UAE, 방산 외 투자 협력 분야도 300억달러 사업- 韓-UAE, 방산 협력 프레임워크 양해각서 체결 완료- 韓-UAE, 방산 부문 전 주기에 걸친 협력 강화 합의- UAE, 통합 방공망 절실…"방공·공군·해군 전반 포괄"- UAE, 2022년 35억달러 규모 천궁II 도입하기도- UAE, 전투기 KF-21 성능개량 모델 개발 참여 희망- UAE 항공무기체계 대부분 노후화…대규모 교체 예정- UAE, 한화에어로 K9 자주포·다연장로켓 천무 주목- 현대로템 K2 전차, 사막 환경 운용 성능 강화 주목- 한화에어로, 지난해 UAE 방산기업과 공동개발 MOU- 방산업계, UAE와 ''방산 패키지 협력 방안'' 논의 중Q. 특히 오늘 장에서 스페이스X 관련주 중 에이치브이엠의 오름세가 굉장했습니다. 스피어나 세아베스틸지주도 좋았는데요. 스페이스X에 투자를 한 기업보다 부품이나 소재 관련주들 위주로 주목하는 게 나을까 싶기도 해요?- 블룸버그 "스페이스X, 이르면 이달 상장 서류 제출"- 스페이스X 상장 시 최대 1.8조달러의 가치 기대- 미래에셋그룹·스피어 등 스페이스X 관련주 주목- 에이치브이엠, 민간 우주 시대 최대 수혜주 부각- 미래에셋그룹, 스페이스X 간접 투자 이력 부각- 에이치브이엠, 신형 발사체 상용화 직접 수혜 기대- 에이치브이엠, 우주항공용 핵심 소재 공급 늘 전망- 세아베스틸, 고부가가치 특수강 제조사로 주목- 스피어, 우주항공용 렌즈·광학 부품 생산에 주목- 스페이스X 로켓 발사↑…소모성 부품·소재 수요 확대- 스피어, 우주항공 특수합금 분야 글로벌 강자로Q. 오늘 장에서 제약바이오주들의 흐름도 나쁘지 않았던 듯 합니다. 특히 지난해 역대급 실적을 기록한 기업들은 적극적인 배당에도 나서고 있다고 하죠. 특히 지정학적 리스크가 장기화가 우려되는 시기에는 피난처로 주목해도 될 듯 해요?- 제약·바이오 기업, 역대급 실적 바탕 적극적 배당- 알테오젠, 창사 이래 처음으로 현금 배당 결정- 알테오젠, 지난해 기술 수출로 사상 최대 실적- 셀트리온, 지난해 사상 최대 실적…역대급 현금 배당- 일동제약, 수익성 개선 성공…7년 만에 배당 재개- K-제약·바이오, 중동 시장 진출 추진에 제동 걸려- 중동 지역 불안 장기화 시 제약·바이오 타격 불가피- K-제약·바이오, 중동 불안에 파트너십 지연 우려- 사우디·UAE 진출 신약 기업들 "타격 모니터링 중"- K-제약·바이오, ''포스트 오일'' 대비 중동과 밀착- 중동서 군사적 충돌 발생…국내 기업 "예의주시"Q. 국내 제약바이오 기업들은 중동 사태로 원료의약품 수급에 차질이 생길 수 있다는 우려도 받습니다. 그래도 오늘 에임드바이오, 오스코텍이나 올릭스 같은 일부 바이오주들은 흐름이 괜찮았거든요?- 오스코텍, 지난해 매출 1000억원 육박 "흑자전환"- 오스코텍, 비소세포폐암 치료제 렉라자 원개발사- 오스코텍 "항내성 항암제 포함 혁신 신약개발 박차"- 올릭스, siRNA 기반 비만·MASH 치료제 주력- 올릭스, 기술이전·공동개발 협상력 형성 구간 진입- 에임드바이오, 임상경험 녹인 ''완성형 ADC''로 승부- 에임드바이오, 항체-약물접합체(ADC) 신약개발 주력- 에임드바이오, 자체 링커-페이로드 기술로 승부- 제약·바이오, 플랫폼 기술에 대한 중요성 부각(자세한 내용은 동영상을 시청하시기 바랍니다.)당신의 제보가 뉴스로 만들어집니다.SBS Biz는 여러분의 제보를 기다리고 있습니다.홈페이지 = https://url.kr/9pghjn', NULL, 'SBS Biz', 'https://n.news.naver.com/mnews/article/374/0000495512', 'https://imgnews.pstatic.net/image/374/2026/03/03/0000495512_001_20260303174911560.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-03 16:36:21', 0, true, '2026-03-09 05:45:23.676583') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (591, '고배당에 분리과세 혜택까지…3월은 ''벚꽃 배당''의 계절', 'Cover Story3월 배당 시즌 투자법코스피 상장사 배당기준일3월 134곳·4월 28곳 설정신세계·동국제강 등 24곳연간 배당성향 40% 넘어배당소득 분리과세 충족배당성향 지나치게 높거나짧은 기간에 주가 급락해배당수익률 뛴 종목 유의를배당기준일이 3월 이후인 이른바 ‘벚꽃 배당’ 종목에 관심이 쏠리고 있다. 올해 배당소득 분리과세 제도 도입, 기업 실적 개선으로 높은 배당과 안정적인 주가 흐름이 기대돼서다. 단순히 배당금 규모보다는 배당성향과 실적 지속 가능성을 함께 고려해 투자할 것을 전문가들은 추천했다.160여 개사 벚꽃 배당 ‘관심’2일 한국상장회사협의회에 따르면 코스피 상장사 가운데 2025회계연도 결산 배당기준일을 3월로 설정한 기업은 지난달 26일 기준 134곳(현금배당 기준, 상장폐지 기업 제외)에 달한다. 4월로 설정한 기업은 28곳으로 집계됐다. 과거 대부분 기업이 12월 말을 기준일로 설정하던 때와 비교해 배당주 투자 시계가 봄으로 이동한 것이다. 2023년 정부가 ‘선(先)배당 확정, 후(後)기준일 지정’이 가능하도록 제도를 손봐 배당액을 먼저 확인한 뒤 투자할 수 있게 됐다.3월 배당 일정을 잡은 대형주를 살펴보면 오는 7일에는 한미반도체가 기준일을 맞는다. 10일은 카카오의 배당기준일이다. 중순으로 넘어가면 미래에셋증권이 17일, 현대모비스가 20일을 배당기준일로 잡았다. 이어 25일에는 기아가, 27일에는 삼성화재 기준일이 돌아온다. LG화학, LG전자, 포스코퓨처엠, 현대글로비스는 월말인 31일을 기준일로 설정했다. LG화학과 미래에셋증권, 삼성화재는 우선주 거래가 가능하다는 점도 눈여겨볼 부분이다. 우선주는 보통주와 동일하거나 더 높은 배당을 받을 수 있는 상품이다. 그 대신 주주가 의결권을 가질 수 없어 통상 보통주 대비 낮은 가격에 거래된다.배당금을 받으려면 반드시 기준일 2거래일 전까지 주식을 사야 한다는 점도 유의해야 한다. 예를 들어 3월 31일이 기준일인 종목은 이달 27일까지 매수해야 배당 권리가 발생한다.분리과세 요건 충족 40여 곳올해부터 적용되는 배당소득 분리과세 제도는 고배당주 가격의 재평가를 촉진할 수 있는 변수다. 연간 배당성향이 40% 이상이거나, 배당성향이 25% 이상이면서 배당금을 전년보다 10% 이상 확대하는 요건을 충족하는 종목에 투자하면 14~30% 세율로 분리과세를 적용받을 수 있다. 종전에는 금융소득이 2000만원을 넘는 자산가는 배당액의 최대 45%를 세금으로 내야 했다. 고액 자산가의 세후 수익 확대 수단으로서 배당주 매력이 커진 셈이다.한국투자증권에 따르면 배당 기준일을 3월로 잡은 기업 가운데 분리과세 요건을 충족하는 종목은 40여 곳이다. 이 중 연간 배당성향이 40% 이상인 기업은 24곳이다. 배당성향은 기업이 한 해 동안 벌어들인 순이익 가운데 얼마를 배당금으로 지급했는지 보여주는 지표다. 예를 들어 순이익의 50%를 주주에게 배당했다면 배당성향은 50%다. 수치가 높을수록 이익을 주주에게 많이 환원한다는 의미다.배당성향 순으로 보면 신세계가 350.6%로 가장 높다. 이어 신세계인터내셔날(327.4%), 동국제강(240.8%), 스카이라이프(238.6%), 롯데쇼핑(219.3%), 두산테스나(194.3%)가 순이익을 뛰어넘는 배당금을 준다. 디엔에프(90.6%), SK네트웍스(97.4%), 에이블씨엔씨(80.7%), 롯데칠성(72.4%), 포스코퓨처엠(68.9%), LG(64.9%) 등도 순이익 대부분을 지급하기로 했다. 세아베스틸지주(62.4%), LG유플러스(53.7%), 포스코인터내셔널(51.4%), SK케미칼(50.1%) 등도 40% 이상 구간에 포함된다. 배당성향이 100%로 순이익보다 많은 배당금을 지급하는 기업은 내용을 잘 살펴봐야 한다는 게 전문가들의 조언이다. 과거에 쌓아둔 이익을 활용하거나 일시적 실적 감소 상황에서 기존 배당을 유지하는 사례가 흔한데 배당의 지속 가능성이 떨어질 수 있기 때문이다.또 하나 눈여겨봐야 할 지표는 배당수익률이다. 배당수익률은 현재 주가 대비 연간 배당금이 차지하는 비율로, 투자자가 주식을 보유했을 때 기대할 수 있는 연간 현금 수익의 수준을 보여준다. 예를 들어 주가가 1만원이고 연간 배당금이 500원이면 배당수익률은 5%다. 한국투자증권에 따르면 연간 기준 배당수익률이 가장 높은 종목은 레드캡투어였다. 스카이라이프, 광주신세계, HS애드가 각각 뒤를 이었다.배당락 주의보…권리일·주가 조정 체크높은 배당수익률은 주가 하락의 결과일 때도 있다. 매년 일정한 배당금을 지급하는데, 주가가 단기에 가파르게 하락하면 배당수익률이 오르는 효과를 내기 때문이다. 일시적인 변동성 확대가 아니라 기업 가치 훼손의 신호라면 투자에 유의해야 한다.‘배당락’을 이해하고 투자하는 것도 중요하다. 배당을 받으려면 배당기준일 2거래일 전까지 주식을 매수해야 하는데, 기준일 다음 거래일엔 배당받을 권리가 사라진다. 이런 이유로 배당락일에는 이론적으로 배당금만큼 하락하는 주가 조정이 발생한다. 예를 들어 주당 1000원을 배당하는 종목이라면 배당락일 시초가는 그만큼 낮게 형성될 수 있다. 배당금을 노리고 기준일 직전에 매수했다가 되파는 과정에서 배당락 때문에 손실을 보는 사례도 적지 않다. 배당금을 받기 위해 종목을 매수할 때는 배당락에 따른 가격 조정을 반드시 함께 고려하는 전략이 필요하다. 이상헌 iM증권 연구원은 “지난해 반도체와 조선, 증권 업종을 중심으로 실적이 크게 개선됐고, 증가한 이익이 배당 확대로 연결되는 흐름이 나타나고 있다”며 “자사주 비중이 높은 지주사, 금융지주, 보험·증권 업종은 배당 확대와 맞물려 주주환원 효과가 더 크게 생길 수 있는 만큼 관련 종목에 관심을 둬야 한다”고 말했다.', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005257076', 'https://imgnews.pstatic.net/image/015/2026/03/02/0005257076_001_20260303004920553.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-02 18:08:13', 0, true, '2026-03-09 05:45:23.676583') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (592, '''3년째 역성장'' K철강 … 고부가 특수강으로 위기 돌파', '우주·방산 차별화된 소재 공략포스코, 함정용 방탄강 첫 개발현대제철, 장갑차·전차서 두각세아그룹, 美에 특수합금 공장보잉과 알루미늄 합금 계약도범용재와 달리 기술 문턱 높고영업이익률도 좋아 ''마진 방패''국내 철강 업계가 우주·방산·원전 등 차별화된 고부가가치 특수강으로 활로를 모색하고 있다. 중국산 값싼 범용재(후판·철근 등)와 출혈경쟁을 벌이기보다는 진입 난도와 마진율이 높은 분야 제품으로 ''체질 전환''에 나선 모습이다.24일 철강 업계에 따르면 세아·포스코·현대제철 등 주요 철강사들이 우주·방산·원전 특수강을 앞세워 사업 포트폴리오를 빠르게 재편하고 있다.체질 개선의 선두에 선 곳은 기존 형강·강관이 주축인 세아그룹이다. 특수강 계열사 세아창원특수강은 지주사 세아베스틸지주와 함께 미국 텍사스주 템플시에 우주항공용 특수합금 공장 ''세아슈퍼알로이테크놀로지(SST)''를 짓고 있다.올해 하반기부터 상업생산을 시작해 현지 항공·방산 업체에 직접 공급할 계획이다. 스페이스X 등 우주항공 선도 기업과 관련한 수주도 기대된다.세아창원특수강은 항공기 엔진 내부에 들어가는 900도급 초내열합금 시제품을 지난해 한화에어로스페이스에 공급한 바 있다. 세아그룹 관계자는 "글로벌 특수합금 수요의 약 40%가 몰린 북미 현지 시장을 적극 공략할 계획"이라고 밝혔다. 이외에도 알루미늄 계열사 세아항공방산소재는 총탄·충격에 강하면서도 정밀 가공이 가능한 고강도 알루미늄을 항공기·전투기 등에 공급한다. 지난해 말 세계 최대 항공기 제조사 보잉과 알루미늄합금 장기 공급 계약(LTA)을 맺어 안정적 수요처를 확보했다.포스코도 함정용 고연성강·방탄강을 국내 최초로 개발해 군함용 특수강 시장의 문을 열었다. 방탄강은 기존 선박용 철판보다 두께는 30% 얇지만 동일한 방탄 성능을 갖췄다. 군함 상부 구조물에 적용해 방호력을 높이면서도 무게를 줄여 선박의 복원력까지 개선하는 게 핵심이다.극저온 환경에서 버티는 에너지용 강재로도 입지를 넓히고 있다. 독자 개발한 ''고망간강''은 철에 망간을 다량 넣어 영하 196도에서도 깨지지 않는 소재다. 액화천연가스(LNG)·액화수소 운반선 탱크와 육상 저장탱크에 들어가는 핵심 강재다.현대제철 역시 건설·자동차 수요 둔화에 맞서 방산용 특수강을 새 축으로 키우고 있다. 2024년부터 현대로템에 장갑차용 후판을 공급하기 시작했으며, 전차용 후판은 지난해 개발을 끝내고 올해부터 양산·공급에 나선다.국내 철강 업계가 우주·방산 등 고부가가치 소재로 눈을 돌린 것은 중국산 저가 범용재의 공습으로 인한 ''역성장 터널''을 벗어나기 위한 생존 전략으로 풀이된다.금융감독원 전자공시에 따르면 포스코·현대제철·동국제강·세아제강 등 국내 철강 빅4의 지난해 매출 합산치는 잠정 기준 70조9800억여 원으로 전년보다 약 3% 줄며 3년 연속 역성장을 기록했다.범용 후판·철근 영업이익률이 한 자릿수에 그치는 반면, 항공·방산용 특수강·특수합금은 두 자릿수를 웃도는 경우가 많아 침체기에도 ''마진 방패'' 역할을 한다는 평가다.실제로 세아항공방산소재는 고강도 알루미늄 수출에 힘입어 지난해 매출 1287억원, 영업이익 246억원, 영업이익률 19.1%로 창사 이래 최대 실적을 갈아치웠다. 포스코도 고부가가치강 비중 확대에 힘입어 지난해 매출 감소에도 영업이익이 20% 이상 증가하며 ''역성장 속 이익 방어''에 성공했다.철강 업계 관계자는 "범용재만으로는 중국·인도 등 후발주자와의 가격 경쟁에서 버티기 어렵다"며 "우주항공 소재, 군함용 방탄강처럼 기술 문턱이 높은 특수강이 K철강의 다음 10년을 가를 것"이라고 진단했다.[정지성 기자]', NULL, '매일경제', 'https://n.news.naver.com/mnews/article/009/0005641322', 'https://imgnews.pstatic.net/image/009/2026/02/24/0005641322_001_20260224172720589.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-24 17:27:20', 0, true, '2026-03-09 05:45:23.676583') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (593, '"차별화만이 살길"…스페셜티 속도 내는 K철강', '현대제철 3세대 자동차 강판 공급 속도…포스코 함정용 고연성강·방탄강 인증국내 철강 기업 스페셜티 전략/그래픽=최헌정국내 철강기업들의 고부가가치 소재 중심의 사업재편이 본격화하고 있다. 기술력을 기반으로 한 특수 소재 개발에 속도를 내며 차별화된 경쟁력 확보와 수요처 확대에 나선단 전략이다.23일 관련 업계에 따르면 현대제철은 3세대 자동차 강판 공급을 위한 막바지 작업을 진행 중이다. 올해 1분기 양산에 돌입할 예정이고, 현재 글로벌 주요 고객사들과 테스트를 이어가고 있다. 현대제철의 3세대 자동차 강판은 고성형성과 고강도, 경량화 특성을 동시에 구현한 제품으로 차세대 모빌리티 시장을 겨냥한 핵심 고부가 소재로 평가된다. 현대자동차·기아를 시작으로 해외 완성차업체로 공급망을 점차 확대할 계획이다. 올해 생산 목표는 550만톤이다.글로벌 전력 수요 증가로 원자력발전소 건설이 확대되며 관련 시장 선점에도 나서고 있다. 현대제철은 국내 철강사 최초로 미국기계기술자협회 원자력소재 공급사품질 시스템 인증(ASME QSC)을 취득했다. 고강도 극후물재(두께 100㎜ 이상 후판) 개발 및 인증을 완료했으며 신안 우이 해상풍력 프로젝트에 초도 공급할 예정이다.포스코는 최근 국내 철강사 최초로 함정용 고연성강과 방탄강에 대한 한국선급(KR) 인증을 완료했다. 고연성강은 기존 조선용 후판 대신 연신율을 35% 이상 높인 강재다. 방탄강은 기존 후판보다 두께를 30% 줄이면서도 방호 성능은 유지한 고부가가치 제품이다. KR인증이 군함 납품의 필수 요건인 만큼 국내 조선사들과 협력 기회를 확보할 수 있을 전망이다. 에너지용 후판, 신에너지 스테인리스(STS), 고망간강 등 그간 기술력을 쌓아온 에너지 부문 강재 경쟁력을 강화한다는 목표다.세아베스틸지주 자회사 세아항공방산소재는 항공·방산 소재 분야에서 보폭을 넓히고 있다. 항공기 제작사 보잉과 장기공급계약(LTA)을 체결하고, 올해부터 항공기 동체와 날개용 고강도 알루미늄 합금 소재를 공급 중이다. 국내 대표 방산 수출품인 K9 자주포와 K2 전차에 들어가는 포신은 국내에서 유일하게 전량 생산하고 있다.국내 철강업계가 미래 먹거리 발굴에 총력을 기울이는 배경에는 건설 경기 침체 등 전방 산업 부진이 자리하고 있다. 여기에 미국을 중심으로 한 관세 장벽 강화와 중국산 저가 제품의 공세까지 겹치며 불확실성이 이어지고 있다. 최근 도널드 트럼프 미국 대통령이 철강 관세를 인하할 수 있다는 현지 보도가 나오기도 했으나 미국 연방대법원이 트럼프 대통령의 상호관세 조치를 무효화하고, 이에 대해 트럼프 대통령이 맞대응에 나서면서 관세를 둘러싼 혼란이 다시 커지는 양상이다.결국 기업들이 스페셜티 중심의 전략으로 갈 수밖에 없다고 보는 이유다. 실제 지난해 현대제철, 포스코 등은 글로벌 통상 리스크 속에서도 고부가 제품 확대와 원가 절감 노력으로 전년 대비 영업이익을 끌어올렸다. 세아항공방산소재는 지난해 창사 이래 최대 실적을 달성했다. 정부도 철강 산업 고도화 정책을 발표하는 등 관련 지원에 나설 계획이다.업계 관계자는 "지난해부터 관세 불확실성이 지속되며 중점 수출 상품을 다시 살펴보는 등 고부가가치 제품 중심의 전략을 짜기 위한 노력을 지속해왔다"며 "기술력이 필요한 제품으로 포트폴리오를 재구성해 수익성을 방어할 것"이라고 했다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005321200', 'https://imgnews.pstatic.net/image/008/2026/02/24/0005321200_001_20260224061010877.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-24 06:10:00', 0, true, '2026-03-09 05:45:23.676583') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (594, '[비즈S+]방산·우주항공 겨냥한 철강업계, 특수강으로 불황 넘는다', '중국 저가 공세로 범용 가격 경쟁 한계… 고부가 방산·우주항공 소재 시장 잠재력 커국내 철강업계가 방산·우주항공 등 고부가가치 소재 시장으로 사업 영역을 넓히고 있다. 사진은 세아창원특수강 창원 공장의 모습. /사진=세아홀딩스국내 철강업계가 방산·우주항공 등 고부가가치 소재 시장으로 사업 포트폴리오를 확장하고 있다. 중국발 저가 공세로 범용 제품의 수익성이 악화하는 상황에서 기술 장벽이 높은 특수강을 돌파구로 삼겠다는 전략이다. 고부가 특수강은 초기 시장 선점 시 안정적인 수요를 확보할 수 있어 중장기 경쟁력 확보에도 도움이 될 것으로 기대된다.포스코는 최근 함정용 고연성강과 방탄강을 국내 최초로 개발하며 글로벌 함정 시장 공략에 나섰다. 포스코가 개발한 고연성강은 기존 조선용 후판 강재 대비 연신율(늘어나는 비율)이 35% 이상 높다. 함정 충돌 시뮬레이션 결과 충격 흡수율은 약 58% 향상된 것으로 나타났다.함께 개발된 방탄강은 기존 후판 대비 두께를 30% 줄여 함정 방호 성능과 기동성을 확보했다. 이를 통해 우리 해군의 차세대 함정 성능을 높이고 향후 미 해군 함정 유지·정비·보수(MRO)와 건조 사업 등에도 적용할 수 있을 것으로 기대된다.현대제철은 미래 모빌리티 시장의 핵심 소재를 공급한다. 올해 1분기부터 고성형·고강도 특성을 갖춘 ''3세대 자동차 강판''을 양산할 계획이다. 신안 우이 해상풍력 프로젝트에 고강도 극후물 후판을 초도 공급하고 원전용 강재 판매를 확대하는 등 에너지용 강재 시장 점유율도 높여가고 있다.세아베스틸지주는 국내 우주항공 소재 분야의 선두주자다. 자회사 세아항공방산소재는 세계 최대 항공기 제작사 보잉과 장기공급계약(LTA)을 체결, 올해부터 항공기 동체·날개용 고강도 알루미늄 합금 소재를 공급한다. 세아창원특수강은 미국 특수합금 생산법인 SST를 오는 하반기부터 가동해 현지 우주항공 시장 진출을 모색할 방침이다.지난해 고부가 제품 판매를 확대한 포스코와 현대제철은 영업이익이 증가한 반면 건설·강관 중심 사업 구조를 가진 동국제강과 세아제강은 영업이익이 감소했다. 사진은 포스코의 신 방산 소재를 적용한 차세대 함정 가상 이미지. /사진=포스코지난해 철강업계 실적은 원가 절감과 고부가 제품 판매 성과가 희비를 갈랐다. 고부가 제품 비중이 높은 포스코와 현대제철은 영업이익이 전년 대비 각각 20.8%, 37.4% 증가한 반면 건설·강관 중심 사업 구조를 가진 동국제강과 세아제강은 각각 42.1%, 75.6% 감소했다. 방산·우주항공용 특수합금 판매를 확대한 세아베스틸지주는 영업이익이 95.6% 급증하며 고부가 전략의 효과를 입증했다.미국·유럽 등 주요 수출국의 관세 장벽과 중국발 공급 과잉으로 범용 중심의 가격 경쟁은 한계에 다다랐다. 한국산업연구원(KIET)은 올해 철강 수출이 전년 대비 6.4% 감소할 것으로 내다봤다. 고부가 특수강 제품으로 사업 구조를 전환해 철강 산업의 질적 성장을 도모해야 한다는 목소리가 크다.특수강은 다품종소량생산 구조로 규모의 경제를 확보하기 쉽지 않지만 방산·우주항공 등 수요 산업이 성장하고 있어 진입장벽을 넘을 경우 초기 시장을 선점할 수 있다. 시장조사업체 글로벌리서치인사이트에 따르면 세계 특수강 시장 규모는 2033년 3162억달러(약 466조6500억원)에 달할 전망이다.철강업계 관계자는 "우주항공·방산 소재는 국가 안보와 직결되는 분야로 일반 특수강보다 훨씬 엄격한 기준이 적용돼 진입장벽이 높다"면서도 "동맹국이나 신뢰할 수 있는 국가의 기업으로부터 소재를 조달하려는 경향이 강해 한 번 공급망에 진입하면 수요가 점진적으로 확대될 가능성이 크다"고 말했다.', NULL, '동행미디어 시대', 'https://n.news.naver.com/mnews/article/417/0001130825', 'https://imgnews.pstatic.net/image/417/2026/02/23/0001130825_001_20260223060107150.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-23 06:00:00', 0, true, '2026-03-09 05:45:23.676583') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (631, '''르네상스 저주'' 푼 이지스, 국민연금의 보복?…센터필드서 ''팽'' 당할 위기', '이지스운용, 밸류업 성공하고도 퇴출 위기…"성과보수 아끼기 꼼수"신세계 반발 속 국민연금 ''침묵''…"스튜어드십 논란"서울 강남구 역삼동 센터필드(서울=뉴스1) 신건웅 기자 = 서울 강남 테헤란로의 한복판. 과거 10년 가까이 ''도심의 흉물''로 방치됐던 옛 르네상스 호텔 부지를 개발한 오피스 빌딩 ''센터필드''가 위치해 있다.아마존, 메타(페이스북), 크래프톤 등 글로벌 빅테크 기업이 입주해 있고, 최고급 호텔인 조선 팰리스까지 위치해 ''공실률 제로(0)''를 자랑한다. 3조 원대 ''트로피 에셋(Trophy Asset)''으로, 부동산 개발의 대표적인 성공사례중 하나다.그러나 아이러니하게도 이 개발을 주도한 운용사(GP)는 펀드 만기를 앞두고 ''토사구팽 위기''에 처했다는 평이 나온다. 투자자(LP)들이 성과 보상 대신 ''운용사 교체''와 ''자산 이관''을 요구하고 있기 때문이다.시장에서는 ''성과보수 삭감''과 국민연금이라는 ''보이지 않는 손''이 작동하고 있다고 보고 있다.''르네상스의 저주'' 푼 이지스의 밸류업…투자자는 "운용사 바꿔라?"센터필드 개발은 약 10년 전부터 시작됐다. 해당 부지는 2015년 삼부토건의 법정관리 이후 시장에 나왔지만, 복잡한 권리관계와 까다로운 인허가 문제로 인해 내로라하는 디벨로퍼들이 모두 손을 털고 나가는 상황이었다. 업계에서는 ''르네상스의 저주''라는 말이 돌 정도였다.꼬인 실타래를 푼 곳이 이지스자산운용이다. 2018년 과감하게 부지를 인수한 이지스는 난해한 개발 과정을 주도적으로 풀어냈고, 2021년 준공과 동시에 글로벌 우량 임차인을 대거 유치하며 강남권역(GBD) 최고 임대료를 달성했다.그런데 펀드 만기를 앞두고 이상기류가 감지됐다. 전략적 투자자(SI)인 신세계프라퍼티가 돌연 이지스자산운용의 매각 추진을 "독단적 결정"이라고 문제 삼으며, 매각 중단과 운용사 교체를 요구하고 나선 것이다.IB 업계 관계자는 "통상적으로 난이도 높은 개발 사업을 성공시킨 운용사에게는 높은 성과보수와 재계약 기회를 주는 것이 관례"라며 "압도적인 퍼포먼스를 보여준 GP를 상대로, SI가 전례 없는 강경 태도로 ''방을 빼라''고 요구하는 것은 자산의 가치 때문이 아니라 다른 ''셈법''이 숨어 있다는 방증"이라고 말했다.서울 역삼동 센터필드"성과보수 깎으려는 꼼수?"… ''스튜어드십''의 자기부정무리한 운용사 교체 추진에 대해 시장에서는 ''성과보수 삭감''을 노린 경제적 셈법으로 해석했다.통상적으로 자산을 제3자에게 매각하면 ''실제 매각가''를 기준으로 성과보수를 지급해야 한다. 센터필드처럼 가치가 급상승한 자산은 운용사에게 지급할 보수 규모도 커질 수밖에 없다.반면 운용사를 교체하거나 자산을 이관할 경우에는 통상 ''감정평가액''을 기준으로 정산하게 된다. 감정가는 실제 시장 거래가보다 보수적으로 책정되는 경우가 많다.LP 입장에서는 운용사를 내보내고 감정가로 정산하는 것이 막대한 성과보수를 아끼는 ''남는 장사''가 되는 셈이다.문제는 도덕성이다. 업계 관계자는 "만약 실제로 보수를 아끼기 위해 10년간 자산을 키운 운용사를 내친다면, 이는 명백한 시장기만이자 모럴 해저드"라고 지적했다.국민연금의 침묵과 동조…"만기 연장 불가, 매각 반대?"주요 LP인 국민연금의 입장은 주요 변수다. 현재 국민연금은 ''만기 연장 불가''와 ''매각 반대''라는 양립 불가능한 입장을 고수하고 있다. 사실상 자산을 고립무원 상태로 몰아넣는 셈이다.시장에서는 국민연금이 신세계를 앞세워 이지스를 압박하고, 그 과정에서 자연스럽게 운용사 교체 명분을 쌓으려는 것으로 보고 있다. 그 기저에는 지배구조 변경(힐하우스) 과정 등에서 쌓인 특정 실무 라인의 ''감정적 골''과, 성과보수 절감이라는 ''경제적 실리''가 복합적으로 작용하고 있다는 분석이다.이는 ESG와 공정 투자를 표방하는 국민연금의 스튜어드십 코드(수탁자 책임 원칙)에도 정면으로 위배된다. 정당한 성과에 대한 보상을 ''힘의 논리''로 박탈하는 것은 자본시장의 생태계를 파괴하는 행위이기 때문이다.서울 역삼동 센터필드  /뉴스1 ⓒ News1 박세연 기자9월 대출 만기 ''시한폭탄''..."고래 싸움에 자산 터진다"문제는 이러한 ''복합 갈등'' 속에 우량 자산이 볼모로 잡혔다는 점이다. 센터필드를 담보로 한 1조 2000억 원 규모의 대출 만기는 오는 9월로, 펀드 만기(10월)보다 한 달 앞서 도래한다.신세계를 앞세운 국민연금의 ''비토(Veto)''로 리파이낸싱과 매각이 모두 막힌 상황에서, 이대로 9월을 맞으면 대출 상환 실패로 인한 기한이익상실(EOD) 발생이 불가피하다.한 부동산 금융 전문가는 "겉으로는 신세계와 이지스의 싸움 같지만, 핵심은 결국 국민연금이 쥐고 있다"며 "공적 연기금이 수수료 몇 푼을 아끼거나 감정적 이유로 1등 자산을 부도 위기로 내모는 것은 국민에 대한 배임"이라고 꼬집었다.시장은 국민연금의 ''설명 책임''을 요구하고 있다. 국민연금이 나서서 입장을 명확히 밝혀야 한다는 주장이다.한 외국계 사모펀드 관계자는 "글로벌 시장에서는 정당한 성과 보상을 회피하기 위한 운용사 교체를 심각한 ''약탈적 행위''로 간주한다"며 "국민연금이 대외 신뢰도를 지키기 위해서라도 현재의 교착 상태를 풀 합리적인 가이드라인을 제시해야 한다"고 지적했다.', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008724048', 'https://imgnews.pstatic.net/image/421/2026/01/20/0008724048_001_20260120154122003.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-20 14:09:58', 0, true, '2026-03-09 05:46:51.819344') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (632, '[김남석의 개미생활] 코스피 종가 맞히기 이벤트서 꼴찌한 이유', '[미리캔버스 생성 이미지][글쓴이주] 주식시장 관련 소식이 매일 쏟아지지만 뉴스에서 ''개미''의 목소리를 찾기 쉽지 않습니다. 기사를 쓰는 기자도 개인 투자자고, 매일 손실과 이익 사이에서 울고 웃습니다. 일반 투자자보다 많은 현장을 가고 사람을 만나지만 미처 전하지 못했던 바를 철저하게 ''개인''의 시각으로 풀어보겠습니다.지난해 코스피가 75% 상승하며 전 세계 주요 지수 중 가장 높은 수익률을 기록하고 코스닥도 36% 이상 올랐지만 모든 투자자가 웃을 수는 없었다.코스피 상장사 948개 중 301개는 2024년 연초와 가격이 같거나 떨어졌다. 연간 낙폭이 가장 큰 엑시큐어하이트론의 수익률은 마이너스(-) 81.60%다. 코스피 상승률보다 더 큰 하락률을 기록했다.이스타코, 삼부토건, 오리엔트바이오, 코아스도 하락률이 60%를 넘었다. DI동일, 동성제약, 금양, TCC스틸, 금호전기, 시프트업, HLB글로벌 등 업종을 가리지 않고 떨어질 종목은 떨어졌다.코스닥 시장은 이보다 더 심하다. 원익홀딩스 주가가 2550원에서 48700원으로 1810% 오르고 씨어스테크놀로지, 로보티즈 등 수익률 1000%가 넘는 종목들이 있었던 반면 아이엠, 하이퍼코퍼레이션, 아이톡시, 파라택시스코리아, 더테크놀로지 등은 -80%씩 떨어졌다.코스닥에선 1722개 종목 중 768개 주가가 그대로거나 떨어졌다. 연간 주가가 하락한 종목들의 업종을 보면 특정 업종의 약세도 아니다. 장세가 아무리 좋아도 기업의 실적이 좋지 않거나 성장성이 보이지 않는 등 떨어질 기업의 주가는 하락한 셈이다.한국거래소에서 매년 출입기자를 대상으로 실시하는 ''연간 종가 맞히기'' 이벤트에서 기자는 꼴찌를 했다. 기자들 중 가장 낮은 지수를 써냈다고 한다.주식 투자를 오래 한 것은 아니지만, 직업 특성상 과거 주식시장에 있었던 일들을 찾아볼 수밖에 없다. 시장을 오래 겪었던 전문가들을 만나면서 우리나라 주식시장에 대한 신뢰도는 더 떨어졌다.지난해 코스피가 3000을 넘었을 때도, 4000을 넘었을 때도 계속 오를 것이란 기대보다는 언젠가의 급락이 더 우려됐다. 특히 지난해는 원화 약세와 주식 상승이 동시에 나타난 한 해다. 달러 약세에도 우리나라 통화에 대한 평가가 더 낮아지는데, 주식시장은 끝없이 상승세를 보이는 것이 비정상적으로 보일 정도였다.한 증권사 연구원이 보고서에 비슷한 고민을 털어놨다. 그는 "주가가 오를 때마다 ''이게 맞나''라는 생각에 긍정적인 뉴스가 나와도 그 이면의 리스크를 찾는 데 더 많은 시간을 썼다"고 적었다.건설업종 분석을 담당하는 이 연구원은 건설업에 쌓인 뿌리깊은 불신이 쉬이 주가의 변화를 인정할 수 없게 만들었다고 했다.''코스피 곱버스'' 상장지수펀드(ETF)가 지난해 개인 투자자 순매수 2위를 기록한 것을 보면, 이 같은 불신은 이미 시장에서도 나타나고 있다. 이미 많이 오른 지수가 조정을 받는 것은 그동안의 흐름을 보면 당연하지만 2조원이 넘는 개인의 돈이 들어온 것을 보면 조정의 폭이 예상보다 클 수도 있을 것 같다.결국 여전히 투자자들은 국장이 꾸준하게 우상향 할 것이란 믿음이 없는 셈이다. 지난해 개인 투자자가 가장 많이 산 ETF는 미국S&P500과 나스닥100이다. 최근 3년간을 생각해 보면 코스피보다 미국 증시가 더 높은 상승률을 기록했다. 그럼에도 여전히 투자자들은 미국 주식이 오를 것이라 보고 있다.정부는 내년 코스닥 시장을 활성화하겠다고 했다. 정책자금과 연기금을 통해 코스닥 시장에 돈을 불어넣을 수는 있다. 하지만 코스피 5000, 코스닥 1000이 단순히 선전을 위한 상징적인 수치가 돼서는 안된다.코스피가 5000에 도달하고 코스닥이 1000을 넘어선다고 해도 정책자금과 연기금이 빠져나간 뒤 다시 빠르게 내려온다면 오히려 시장의 신뢰도는 더 무너질 수 있다.연말 환율 종가를 낮추기 위해 시장이 개입해 1480원이 넘었던 환율이 1430원 아래로 내려갔지만, 종가 기준 시간이 지난 뒤 환율은 다시 1447원까지 올라왔다. 환율이든 지수든 순간의 수치보다는 시장의 신뢰를 얻는 것이 먼저일 수 있다.', NULL, '디지털타임스', 'https://n.news.naver.com/mnews/article/029/0003002532', 'https://imgnews.pstatic.net/image/029/2026/01/01/0003002532_001_20260101181015013.png?type=w800', 'NEWS_ETC', NULL, '2026-01-01 18:08:29', 0, true, '2026-03-09 05:46:51.819344') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (595, '"봄 바람 불면 배당주...배당주 투자 아직 안 늦어"', '코스피가 전 거래일(5677.25)보다 19.64포인트(0.35%) 상승한 5696.89에 개장한 20일 오전 서울 중구 하나은행 딜링룸 전광판에 지수가 표시되고 있다. 뉴시스 제공[파이낸셜뉴스] 최근 국내 증시에서 배당주가 강세를 보이지만, 증권가에선 "지금도 늦지 않았다"를 외친다. 현 시점에 매수해도 배당을 받을 수 있는 기업에 관심을 가져야 한다는 이야기다. 올해 2~3월에 배당기준일을 둔 배당소득 분리과세 대상 기업을 추천했다. 20일 증권업계에 따르면 염동찬 한국투자증권 연구원은 “인하 대상이 되는 배당소득은 2026년 발생한 배당부터 해당되는데 올해 2월과 3월에 배당 기준일이 있는 기업들은 지금 관심을 가져야 할 영역”이라고 밝혔다.올해부터 도입되는 배당소득 분리과세안에 따르면, 기업 주주는 배당소득세에 대해 종합소득세 합산 없이 낮은 세율(14~30%)로 분리과세를 적용받는다. 대상 기업은 배당성향이 40% 이상이거나 배당성향이 25% 이상이면서 전년 대비 현금배당이 10% 이상 증가한 기업이다.배당소득 분리과세는 올해 1월 1일 이후 배당 지급분부터 적용된다. 올해 2~3월 분리과세를 목표로 하는 자금이 증시에 유입될 것이라는 전망이다.염동찬 연구원은 “지금 매수해도 4분기 배당을 받을 수 있는 기업 중 배당소득세 인하 대상이 되는 기업에 대한 관심이 필요하다”며 “만약 1년 중 4분기 배당금 지급 비중이 높은 기업이라면 더욱 긍정적인 접근이 가능할 것”이라고 말했다.배당 기준일이 2월인 배당소득세 인하 대상 기업으로는 △KT △KB금융 △HD현대중공업 △하나금융지주 △HD현대일렉트릭 △POSCO홀딩스 △우리금융지주 △HD한국조선해양 △KT&G △HD현대 △카카오뱅크 △HD현대마린솔루션 △BNK금융지주 △GS △JB금융지주 △GS건설 △GS리테일 등이다.배당 기준일이 3월인 배당소득세 인하 기업은 △레드캡투어 △디어유 △풍산홀딩스 △세아베스틸지주 △SK가스 △GKL △포스코퓨처엠 △현대글로비스 △LG전자 △LG △포스코인터내셔널 △LIG넥스원 △아모레퍼시픽 △LS △LG유플러스 △신세계 △롯데쇼핑 △아모레퍼시픽홀딩스 △롯데칠성 △롯데웰푸드 △NHN △SK케미칼 △신세계인터내셔날 △동국제강 △롯데이노베이트 △광주신세계 △신세계I&C △스카이라이프 △디엔에프 △HS애드 △이마트 △SK네트웍스 △컴투스 △두산테스나 △현대그린푸드 등이다.', NULL, '파이낸셜뉴스', 'https://n.news.naver.com/mnews/article/014/0005480224', 'https://imgnews.pstatic.net/image/014/2026/02/20/0005480224_001_20260220104709420.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-20 10:47:09', 0, true, '2026-03-09 05:45:23.676583') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (596, '철강업계, 방산·항공·원전용 고부가 소재로 포트폴리오 다변화', '세아항공방산소재, 방산 등 특수소재로 지난해 역대 최대 실적포스코, 함정용 고연성강·방탄강 국내 최초 개발·선급 인증받아현대제철, 고성형성·고강도·경량화 3세대 강판 1분기 양산 계획"비중 확대 점진적으로 이뤄질 전망⋯수익성 위주 경영에 도움"포스코, 현대제철, 세아 등 국내 철강업계가 범용 제품 중심에서 벗어나 방산·항공 등 고부가가치 소재 시장으로 사업 포트폴리오를 재편하고 있다. 중국산 저가재 공급 과잉 등으로 수익성이 악화하자 특수 소재를 돌파구로 삼겠다는 전략이다.세아항공방산소재의 고강도 알루미늄 소재. [사진=세아항공방산소재]19일 업계에 따르면 포스코, 현대제철, 세아 등 철강사들이 고부가가치 제품 판매 확대 등으로 수익성 중심의 사업을 강화하고 있다.세아베스틸지주 자회사 세아항공방산소재는 실적으로 증명했다. 세아항공방산소재는 방산·항공 등의 시장에 고강도 알루미늄을 공급하며 지난해 매출 1287억원, 영업이익 246억원을 기록했다. 창사 이래 최대 실적이다.세아항공방산소재는 항공기 제작사 보잉과 장기공급계약(LTA)을 체결하고 올해부터 항공기 동체·날개용 고강도 알루미늄 합금 소재를 공급하고 있다.회사는 새롭게 재편되고 있는 항공·우주·방산 시장 공급망 내 특수금속 소재 주요 공급사로서의 입지 강화를 위해 국내 자회사(세아베스틸·세아창원특수강·세아항공방산소재)간 통합 포트폴리오 강화·선제적인 연구 개발(R&D) 투자를 통해 특수합금 소재 기술 고도화를 추진한다는 방침이다.또 올해 하반기 미국 특수합금 생산법인의 성공적인 상업 생산 안착을 위해 전사적 역량을 집중하고, 창녕 신공장 투자를 적기에 진행해 글로벌 신규 수요 창출과 새로운 성장동력을 확보한다는 계획이다.포스코는 함정용 고연성강과 방탄강을 국내 최초로 개발하고 지난달 한국선급(KR) 인증을 완료했다. KR인증은 군함 납품의 필수 요건인 동시에 해외 수출하는데 있어 중요한 트랙 레코드로 이를 바탕으로 해외 인증을 신속하게 받거나 별도 인증없이 그대로 해외 품질 규격에 통과될 수 있다.신 방산 소재를 적용한 차세대 함정 가상 이미지. [사진=포스코]고연성강은 기존 조선용 후판 대비 연신율을 35% 이상 높인 강재로, 함정 충돌 시뮬레이션에서 충격 흡수율이 약 58% 향상된 것으로 확인됐다.방탄강은 기존 후판보다 두께를 약 30% 줄이면서도 방호 성능을 유지해 함정 상부 구조 경량화와 복원력 개선 효과가 기대된다.두 소재 모두 기존 강재 대비 성능을 끌어올린 만큼 함정 경쟁력 향상은 물론 향후 수요 확대에 따른 적용 범위 확장도 기대된다는 게 회사 측 설명이다.현대제철은 고성형성·고강도·경량화 특성을 갖춘 3세대 강판을 올해 1분기에 양산할 계획이다. 또 해상풍력용 고강도 극후물재(두께 100㎜ 이상 후판) 개발·인증을 완료하고 신안 우이 해상풍력 프로젝트에 초도 공급할 예정이다.원자력 발전소 건설 확대가 전망됨에 따라 원전용 강재 판매도 확대한다. 현대제철은 국내 철강사 최초로 미국기계기술자협회(ASME)의 원자력 소재 공급사 품질인증(QSC)을 획득한 바 있어 이를 바탕으로 글로벌 수주 활동을 확대한다는 방침이다.업계 관계자는 "중국산 저가 수입재와 경쟁이 심화되는 상황에서 범용제품만으로는 수익성을 담보하기 어렵다"며 "고부가 소재 확대는 어려운 업황을 버텨내는 동시에 미래 경쟁력을 확보하기 위함"이라고 말했다.이재윤 산업연구원 실장은 "중국과 확실히 차이가 있는 제품도 있고, 기술력이 유사하더라도 고기능성 철강제품은 핵심소재인 만큼 신뢰성이 확보되어야 하기 때문에 중국산 보다는 국내 업체  제품을 선호하는 경향이 있다"고 말했다.이어 "현재 해당 시장은 유럽과 일본 등이 장악하고 있어, 국내 철강사들의 고부가 전략은 이들이 주도해온 시장에 진출하는 전략으로 볼 수 있다"며 "고부가 소재 분야의 수요 역시 제한적이라 비중 확대는 점진적으로 이뤄질 전망이지만 현재의 수익성 위주 경영에는 도움이 될 것으로 보인다"고 덧붙였다.', NULL, '아이뉴스24', 'https://n.news.naver.com/mnews/article/031/0001006728', 'https://imgnews.pstatic.net/image/031/2026/02/20/0001006728_001_20260220074012569.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-20 07:40:12', 0, true, '2026-03-09 05:45:23.676583') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (597, '수은, 대한전선 HVDC 해저케이블 공장에 4500억 지원…서해안 에너지고속도로 기반 구축', '수출금융 2000억·공급망안정화기금 2500억 결합한 ‘K-파이낸스 패키지’ 지원당진 해저케이블 2공장 건설…해상풍력·국가 전력망·AI 데이터센터 인프라 대응유턴기업 투자 지원 통해 전력망 공급망 강화·지역경제 활성화 기대한국수출입은행은 대한전선이 충남 당진에 건설 중인 ‘해저케이블 제2공장 신설 프로젝트’에 총 4500억원 규모의 금융을 지원할 예정이라고 9일 밝혔다. ⓒ한국수출입은행[데일리안 = 손지연 기자] 한국수출입은행이 서해안 에너지 고속도로 구축과 전력망 인프라 확충을 위해 대한전선의 해저케이블 생산시설 투자에 대규모 금융 지원에 나선다.수출입은행은 대한전선이 충남 당진에 건설 중인 ‘해저케이블 제2공장 신설 프로젝트’에 총 4500억원 규모의 금융을 지원할 예정이라고 9일 밝혔다.이번 지원은 수출금융 2000억원과 공급망안정화기금 2500억원을 결합한 ‘K-파이낸스 패키지’ 방식으로 이뤄진다.수은이 보유한 다양한 정책금융 수단을 묶어 국내 기업을 일괄 지원하는 구조다.대한전선 당진 2공장은 초고압직류송전(HVDC) 해저케이블을 생산하는 시설로, 대규모 해상풍력 단지 조성과 서해안 에너지 고속도로 구축, 국가 간 전력망 연계 등에 활용되는 핵심 인프라를 담당하게 된다.산업통상자원부는 2025년부터 해저케이블을 국가핵심자원으로 지정해 관리하고 있다.특히 HVDC 해저케이블은 장거리 전력 전송 효율이 높아 국가 핵심 전력망 구축에 활용될 뿐 아니라, 전력 수요가 급증하는 글로벌 인공지능(AI) 데이터센터 전력 인프라에도 필수적인 기반 시설로 평가된다.수은은 최근 도입한 ‘AX(AI 전환) 특별프로그램’을 통해 관련 산업 성장을 지원할 계획이다.아울러 이번 지원은 해외 대신 국내에 생산시설을 구축하는 ‘유턴기업’ 투자에 대한 금융지원 성격도 갖는다.이를 통해 전력망 인프라 공급망을 국내에 안정적으로 구축하고 대외 의존도를 낮추는 효과도 기대된다.수은 관계자는 “HVDC 해저케이블은 국가 전력망과 글로벌 AI 데이터센터 전력망 구축에 핵심적인 요소”라며 “이번 지원을 통해 우리 기업이 글로벌 시장에서 기술 주도권을 확보할 수 있도록 적극 뒷받침하겠다”고 말했다.이어 “핵심 기술을 보유한 기업의 국내 복귀를 지원해 지역경제를 활성화하고, 공급망안정화기금과의 시너지를 통해 우리 기업의 글로벌 산업 경쟁력 확보를 지속적으로 지원할 것”이라고 덧붙였다.', NULL, '데일리안', 'https://n.news.naver.com/mnews/article/119/0003066803', 'https://imgnews.pstatic.net/image/119/2026/03/09/0003066803_001_20260309123015332.jpeg?type=w800', 'NEWS_ENERGY', NULL, '2026-03-09 12:30:15', 0, true, '2026-03-09 05:45:47.270845') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (598, '포화 휩싸인 중동 지역에 불안 휩싸인 韓 전력업계', 'HD현대일렉트릭·효성重 등송전망·변전설비 수주 위축전쟁 장기화될라 노심초사미국·이스라엘과 이란 간 분쟁이 장기화할 조짐을 보이면서 중동을 주력 시장으로 노리고 있는 국내 전력 업계가 촉각을 곤두세우고 있다. 현지 발주 지연을 비롯해 공급망 차질 우려 같은 악재가 불거질 수 있기 때문이다.6일 업계에 따르면 효성중공업, HD현대일렉트릭, LS일렉트릭을 비롯한 국내 전력기기 업체들은 사우디아라비아와 아랍에미리트(UAE), 쿠웨이트를 필두로 한 중동 국가에서 송전망과 변전 설비 구축 사업을 진행하고 있다. 중동은 전력 수요 증가와 개발 확대로 송·변전 설비 투자가 이어지는 지역이다.기업별로 보면 HD현대일렉트릭의 중동 진출이 가장 활발하다. 중동 지역을 북미, 유럽 등과 함께 4대 핵심 수출 시장으로 설정하고 매출 비중을 꾸준히 늘리고 있다. 지난해 4조795억원 규모의 매출 가운데 북미 비중이 39.6%로 가장 많았고 중동은 20.9%로 2위로 집계됐다. HD현대일렉트릭 관계자는 "중동 지역의 지정학적 리스크가 발생한 지 얼마 안 돼 당장 실적에 미치는 영향은 제한적"이라면서도 "해상 운임에 문제가 발생해도 납품에 차질이 없도록 대체 경로를 파악하는 등 만전의 조치를 기하고 있다"고 설명했다.지난해 초고압 변압기를 포함한 중공업 부문에서 매출액 4조1483억원의 실적을 거둔 효성중공업도 중동 상황을 예의 주시하고 있다. 효성중공업은 전체 매출의 20% 안팎을 중동 지역에서 거두고 있다. LS일렉트릭은 전체 매출에서 중동 비중이 상대적으로 작지만 중동 법인을 핵심 거점으로 활용하고 있는 만큼 이번 사태를 자세히 모니터링하고 있다.전력기기 업체뿐만 아니라 전선 업계도 상황 관리에 나서고 있다. 대한전선, LS전선 등의 기업은 현재 중동 지역에서 초고압 케이블과 해저 케이블 사업을 진행하고 있다. 업계 관계자는 "중동 전력 인프라스트럭처 사업이 대부분 장기 프로젝트로 진행되는 만큼 단기적인 사업 차질 가능성은 제한적일 것"이라면서도 "당장은 중동 지역 주재 인력에 대해 재택근무로 전환하는 조치를 시행하는 등 임직원의 안전을 최우선으로 삼고 있다"고 밝혔다.[이진한 기자]', NULL, '매일경제', 'https://n.news.naver.com/mnews/article/009/0005646398', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ENERGY', NULL, '2026-03-06 17:40:06', 0, true, '2026-03-09 05:45:47.270845') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (599, '‘석화 한파에’…LG화학, 20년차 이상 희망퇴직 실시', '불황 장기화 속 인력 구조 효율화5일부터 내달 9일까지 신청 접수[이데일리 김성진 기자] LG화학이 근속 20년 이상 직원을 대상으로 희망퇴직을 실시한다. 석유화학 산업 불황이 장기화하는 데 따라 조직 효율성을 높이기 위한 조치로 해석된다.5일 업계에 따르면, LG화학은 이날부터 내달 9일까지 2006년 12월31일 이전 입사한 전 구성원을 대상으로 희망퇴직 신청을 받는다. 근속 연수가 약 20년 이상인 직원들이 주 대상이며, 희망퇴직 확정자를 대상으로는 전직 및 재취업 지원 교육 프로그램도 제공될 예정이다.LG화학 여수 NCC공장.(사진=LG화학.)이번 희망퇴직은 업황 불황 지속에 따른 대응으로 분석된다. 국내 석유화학 업계는 중국발(發) 과잉공급 여파로 최근 몇 년간 전례 없는 침체기를 보내고 있다. 정부는 이 같은 위기를 돌파하기 위해 지난해 말 석유화학 산업의 자율 구조조정에 나섰다.지난 25일 정부가 발표한 ‘석유화학산업 재도약 추진방향’에 따르면 롯데케미칼과 HD현대오일뱅크는 대산 사업장을 중심으로 신설 통합법인을 설립하기로 했다. 이를 통해 롯데케미칼은 연산 110만톤(t) 규모의 대산 나프타분해설비(NCC) 의 가동을 중단하고, HD현대케미칼은 85만t만 생산을 계속한다.동시에 고부가·친환경 전환을 위한 대형 연구개발(R&D) 사업도 추진한다. 석유화학산업의 구조개편 전환을 주도할 ‘화학산업 혁신 얼라이언스’를 중심으로 화학산업의 혁신을 이끈다는 계획이다. 삼성전자, LG에너지솔루션, 대한전선, HD현대중공업 등 각 분야 수요기업이 공유한 R&D 추진 전략에 발맞춰 화학기업들이 핵심 소재를 개발하는 식이다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006229261', 'https://imgnews.pstatic.net/image/018/2026/03/05/0006229261_001_20260305173423140.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-03-05 17:34:23', 0, true, '2026-03-09 05:45:47.270845') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (602, '''친환경·고부가'' 민관 뭉친 화학산업 혁신 첫발 뗐다', '''화학산업 혁신 얼라이언스'' 첫 총회수요기업 R&D 투자 방향 맞춰 프로젝트산업부 "고부가 전환 전폭 지원"지난달 25일 서울 서초구 코트라에서 열린 ''석유화학 사업재편승인기업 CEO 간담회'' 뒤 참석자들이 기념 촬영을 하고 있다. 왼쪽부터 조남수 HD현대케미칼 대표, 이영준 롯데케미칼 대표, 김정관 산업통상부 장관, 송명준 HD현대오일뱅크 대표. 뉴스1석유화학산업의 고부가·친환경 전환을 주도할 민관 협력체 ''화학산업 혁신 얼라이언스''가 본격적으로 가동된다.산업통상부는 4일 서울 중구 대한상공회의소에서 석유화학산업 생태계 전반의 중소·중견기업, 수요기업, 연구소 관계자 150여 명이 참석한 가운데 총회를 개최했다고 밝혔다. 혁신 얼라이언스는 구조 개편을 추진 중인 석유화학산업의 고부가 전환을 위한 ''K-화학 차세대 기술혁신 로드맵 2030''의 이행을 담당한다.총회에서는 석유화학산업 전주기와 수요산업을 연계한 연구·개발(R&D)을 기획하기 위해 △얼라이언스 운영계획 △대형 R&D 사업 추진 동향 △주요 수요기업의 R&D 투자 방향 등이 논의됐다. 삼성전자, LG에너지솔루션, 대한전선, HD현대중공업 등 수요기업들이 이날 공유한 R&D 추진 전략을 토대로 화학기업들은 원료·소재·응용 분야 플래그십 프로젝트를 기획한다. 이를 통해 소재·응용 분야 중소·중견기업의 기술력을 끌어올리는 게 목표다.정부는 민간의 노력이 결실을 맺을 수 있도록 로드맵 2030에 따라 고부가·친환경 전환을 위한 대형 R&D 사업을 준비 중이다. 송현주 산업부 산업공급망정책관은 "지난해 출범식이 화학산업 혁신의 목표를 선포하는 자리였다면, 오늘은 실행의 첫발을 떼는 자리"라며 "얼라이언스를 통해 기획된 플래그십 프로젝트가 우리 화학산업의 미래 성장 동력이 될 수 있도록 정책적 지원에 최선을 다하겠다"고 밝혔다.', NULL, '한국일보', 'https://n.news.naver.com/mnews/article/469/0000917568', 'https://imgnews.pstatic.net/image/469/2026/03/04/0000917568_001_20260305061319674.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-03-04 17:56:15', 0, true, '2026-03-09 05:45:47.270845') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (603, '“유가보다 더 큰 충격”…산업계, 중동 수주 지연 우려', '미국과 이스라엘의 이란 공습으로 중동 전역의 긴장감이 높아지는 가운데, 국내 산업계가 직면할 최대 변수는 ‘유가’보다 ‘현지 수주 지연’이라는 분석이 나온다. 중동 지역에 진출한 한국 대기업들의 해외법인이 140개에 달하는 만큼, 발주 차질이나 프로젝트 연기가 현실화할 경우 산업 전반으로 충격이 확산될 수 있다는 우려다.4일 한국CXO연구소에 따르면 공정거래위원회 지정 92개 대기업 집단 가운데 30개 그룹이 중동 10개국에 140개 해외법인을 운영 중이다. 전체 해외법인(6362개)의 2.2% 수준이지만, 에너지·플랜트·인프라 사업이 집중된 전략 지역이라는 점에서 체감 리스크는 적지 않다.김주원 기자국가별로는 아랍에미리트(UAE) 56개, 사우디아라비아 38개로 두 국가에만 전체의 67%가 집중돼 있다. 이어 오만 12개, 이집트 11개 순이다. 그룹별로는 삼성 28개, 현대차·LG·GS 각 14개다.문제는 중동 사업의 성격이다. 단순 판매법인보다 건설·플랜트·전력 인프라 등 대규모 프로젝트의 비중이 높다. 실제로 중동 진출 법인 가운데 건설업이 26개로 가장 많다. 사우디 ‘네옴시티’ 등 초대형 인프라 사업이 진행 중인데 지정학적 긴장 상황이 계속될 경우 발주 일정 조정이나 금융 조달 지연 가능성이 제기된다.삼성은 중동에 28개 법인을 두고 있다. 사우디에서는 삼성물산이 건설 프로젝트에 참여하고 있고, 이스라엘에는 반도체 연구 거점을 운영 중이다. UAE에는 전자제품 판매 법인이 다수 포진해 있다. 생산시설은 제한적이지만 프로젝트·연구·영업거점이 많아 지역 불안이 장기화할 경우 사업 속도 조절이 불가피할 수 있다.현대차그룹의 경우 현대차가 사우디 킹 살만 자동차 산업단지에 연산 5만대 규모의 전기차·내연기관차 혼류 생산 공장을 건설 중이다. 최근 2년 새 중동 법인이 6개 늘어 총 14개로 늘어났다. 현지 생산거점을 축으로 중동 시장 공략을 강화하는 시점에 지정학 리스크가 불거진 셈이다.현대차 사우디 생산법인(HMMME) 공장 조감도. 사진 현대차전력·기계 업계도 긴장하고 있다. 중동은 국내 전력기기 업체들의 최대 해외 시장 중 하나다. 효성중공업·HD현대일렉트릭·LS일렉트릭 등은 사우디·UAE·쿠웨이트 등에서 송전망 확충과 발전 인프라 사업을 잇따라 수주해왔다. 대한전선과 LS전선 역시 초고압 케이블과 해저케이블 공급을 통해 중동 프로젝트에 참여하고 있다.전력기기 업계 관계자는 “초고압 변압기나 발전 설비는 발주부터 제작·해상 운송·현지 설치까지 수년이 걸리는 장기 프로젝트가 일반적”이라며 “발주처의 의사결정이 늦어지면 공정이 밀리면서 매출 인식 시점도 함께 뒤로 이동할 수 있다”고 말했다.LG와 GS 역시 중동에서 판매·건설·부동산 사업을 병행하고 있어 신규 프로젝트 발주 흐름을 예의주시하고 있다. 특히 GS는 오만에만 8개 법인을 두고 플랜트·건설 사업을 수행 중이며, LG는 중동 지역에서 판매법인과 일부 인프라 사업을 운영하고 있다.현대경제연구원은 최근 보고서에서 중동 긴장이 장기화해 2026년 유가가 배럴당 100달러 수준으로 오를 경우 한국 경제 성장률이 0.3%포인트 하락할 수 있다고 전망했다. 주원 현대경제연구원 본부장은 “유가 상승은 비용 부담이라는 단기 충격이지만, 중동 인프라 발주 지연은 건설·플랜트·전력기기처럼 수주 산업 전반에 영향을 줄 수 있다”고 말했다.', NULL, '중앙일보', 'https://n.news.naver.com/mnews/article/025/0003506780', 'https://imgnews.pstatic.net/image/025/2026/03/04/0003506780_001_20260304155415621.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-03-04 15:53:13', 0, true, '2026-03-09 05:45:47.270845') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (604, '대한전선, 단순 전선 제조사 넘어 ‘에너지 인프라 강자’로[오늘 나온 보고서]', '초고압 부문 등 수익성 높은 사업부 비중 확국내 주식시장이 조정을 겪고 있는 가운데 유안타증권이 대한전선 목표주가를 기존 3만 3000원에서 3만 9000원으로 상향했다. 초고압, 해저 부문 매출 증가 등 수익성 높은 사업부의 비중이 확대되면서 이익 상승이 빠를 것이라는 분석이다.대한전선이 초고압과 해저 케이블을 중심으로 한 고부가가치 사업 구조로의 전환에 성공하며 역대급 실적 랠리를 이어가고 있다. 유안타증권은 4분기 어닝 서프라이즈를 기록한 이번 실적의 핵심은 단순한 외형 성장을 넘어선 ‘매출 믹스의 극적인 변화’에 있다. 수익성이 낮은 일반 산업전선 비중을 줄이는 대신, 전분기 대비 40% 이상 급증한 초고압·해저 부문이 전사 이익률을 한 단계 끌어올리며 질적 성장을 견인했다는 평가다.유안타증권은 이러한 변화가 일시적인 현상이 아니라, 대한전선의 체질이 완전히 바뀌었음을 의미한다고 분석했다. 현재 대한전선이 확보한 수주잔고는 3.7조 원으로 역대 최대 수준이다. 초고압 케이블 사업의 특성상 수주 이후 매출 인식까지 보통 2.5년에서 3년이 소요되는데, 이는 지금 확보한 일감이 2026년을 넘어 2027년 이후까지의 실적 하단을 탄탄하게 지지하는 구조적 성장기에 진입했음을 보여준다고 유안타증권은 분석했다.정부가 추진하는 ‘서해안 에너지 고속도로’는 호남권의 전력을 수도권으로 보내기 위한 대규모 프로젝트로, 전력 손실을 최소화하는 HVDC(고압직류송전) 기술이 필수적이라는 점도 긍정적인 요소로 작용할 것으로 봤다. 대한전선은 이미 HVDC 테스트센터를 통해 독보적인 실증·인증 체계를 구축해 두었으며, 이는 향후 국가 기간망 투자 사이클에서 수혜를 입을 수 있는 기술적 기반이 될 전망이다.북미 지역의 노후 전력망 교체 수요와 AI 데이터센터 확산에 따른 폭발적인 전력 수요 역시 대한전선에 기회가 되고 있다. 유안타증권은 최근 수주한 230kV급 리버사이드 프로젝트는 글로벌 시장 내 대한전선의 입지를 다시 한번 증명한 사례라고 분석했다.', NULL, '매일경제', 'https://n.news.naver.com/mnews/article/009/0005644813', 'https://imgnews.pstatic.net/image/009/2026/03/04/0005644813_001_20260304092408412.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-03-04 09:24:08', 0, true, '2026-03-09 05:45:47.270845') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (605, '"주재원 인접국 대피 완료, 출장 금지" 기업들 ''초비상''…피해 없어', '삼성·LG, 주재원 인접국 대피시키고 출장 금지…대체 물류 검토중동 공장 짓는 현대차 ''노심초사''…수주업체 "장기전 땐 사업 차질"미국과 이스라엘이 2일(현지시간) 이란의 수도 테헤란을 공격한 후 연기가 피어오르고 새들이 날아오르고 있다. 2026.3.2 ⓒ 로이터=뉴스1(서울=뉴스1) 최동현 신현우 김진희 기자 = 미국과 이스라엘의 이란 공습으로 중동 지역 긴장이 고조하면서 삼성전자와 LG전자 등 현지에서 사업을 벌이고 있는 국내 기업들도 일제히 ''비상체제''(컨틴전시플랜)를 가동하고 임직원 안전 확보에 만전을 기하고 있다."인접국 대피·출장 중단"…삼성·LG ''비상체제'' 가동3일 업계에 따르면 삼성전자는 이란과 이스라엘 브랜치(영업소)에 근무 중인 주재원과 가족들을 두바이·이집트·요르단 등 상대적으로 안전이 확보된 주변국으로 대피시켰다.아랍에미리트(UAE), 카타르, 이라크 영업소 근무 직원들은 재택근무로 전환했다. 사우디라아리비와 요르단 영업소는 정상 근무를 유지하되, 비상 연락망을 상시 유지하도록 했다.삼성전자는 중동 지역에 별도의 생산 시설을 두지 않고, 스마트폰, TV, 가전 등 소비자 제품 판매(영업소)를 중심으로 사업을 벌이고 있다.사우디 리야드 중동·북아프리카(SEMENA) 법인은 네옴시티에 참여 중이고, 이스라엘에선 반도체 연구소를 운영 중이다. 이란에는 생산 시설이나 영업소를 두지 않고 있다.삼성전자 측은 "정부와 소통하며 중동 지역 사업소 현황을 실시간으로 모니터링하고 있다"며 "중동 지역 출장도 비공식적으로 사실상 중단한 상황"이라고 전했다.LG전자는 지난주 이란에 파견했던 한국 직원 1명을 급거 귀국 조처하고 이스라엘 지점에 근무하는 한국인 직원 및 가족들은 인근 국가로 대피시켰다.또 LG전자 중동·아프리카 지역 대표 명의로 재택근무 전환을 공지하고, 당분간 중동 지역 출장도 금지하기로 했다.LG전자는 중동·아프리카 지역에 3개 생산법인(이집트·사우디·남아프리카)과 18개의 영업소(이스라엘·사우디·UAE·앙골라·요르단·알제리·이집트·남아프리카공화국·튀르키예·나이지리아·모로코)를 두고 있다.LG전자 측은 "이란과 이스라엘 외 중동 지역 법인들은 호르무즈 해협 봉쇄에 따른 물류 대체 경로를 검토하고, 거래선과 함께 수요 영향을 점검하고 있다"고 전했다.현대차는 지난 14일(현지시간) 사우디아라비아 킹 살만 자동차 산업단지에 위치한 현대차 사우디아라비아 생산법인 부지에서 공장 착공식을 개최했다고 15일 밝혔다. 사진은 현대차 사우디 생산법인(HMMME) 공장 조감도. (현대차 제공. 재판매 및 DB 금지) 2025.5.15 ⓒ 뉴스1중동 사업 차질 불가피…"장기전 땐 물류 차질"사우디 킹 살만에 중동 첫 생산 거점을 구축 중인 현대차그룹은 한국 주재원과 현지 직원의 안전을 모니터링하며 정상 근무 체제를 유지하고 있다.킹 살만 자동차 산업단지는 연간 5만 대 규모의 전기차와 내연기관차를 혼류 생산하는 대규모 플랜트다. 지난해 5월 착공해 내년 4분기 가동을 목표로 정했지만 ''이란 사태''로 때아닌 복병을 만났다.현대차 관계자는 "사우디 현지 공항은 폐쇄됐지만 현지 체류 인력은 모두 안전을 확보한 상태"라며 "사태를 주시하며 정상 근무를 하고 있다"고 전했다.사우디, UAE, 카타르, 쿠웨이트 등 중동 시장에서 방산·금융·기계 사업을 활발히 벌이고 있는 한화그룹도 비상이 걸렸다. 현재 중동 지역에 체류 중인 한화 임직원은 123명, 가족을 포함하면 172명에 달한다.한화그룹도 임직원 안전을 최우선으로 확보하라는 매뉴얼을 공지한 것으로 알려졌다. 회사 관계자는 "현재까지 귀국한 임직원은 없다"면서도 "현지에서 안전하게 대기하면서 상황을 지켜보고 있다"고 했다.중동 전력 인프라 사업에 참여 중인 전력기기 및 전선 업계도 상황은 비슷하다. 특히 초고압 변압기 등 해상운송 인도가 필요한 업종인 만큼, 분쟁 장기화에 대한 우려가 커지는 분위기다.효성중공업·HD현대일렉트릭·LS일렉트릭 3사는 모두 현지 인력을 재택근무로 전환하고 사태를 모니터링 중이다. 중동 사우디와 쿠웨이트에 생산법인(접속기·광케이블)을 둔 대한전선과, 이집트에 영업소를 둔 LS전선도 임직원 피해는 없는 것으로 파악됐다.업계 관계자는 "다행히 분쟁 지역과 거리가 있는 만큼 주재원과 현지 인력의 안전은 확보가 된 상황"이라면서도 "(이란 사태가) 장기화할 경우 해상운송에 차질을 빚거나 운임이 급증할 가능성이 있어 동향을 주시하고 있다"고 말했다.', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008803951', 'https://imgnews.pstatic.net/image/421/2026/03/03/0008803951_001_20260303173010843.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-03-03 17:29:28', 0, true, '2026-03-09 05:45:47.270845') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (606, '인력감축 대신 ''직원 빚 탕감''…매출 3조 ''부활 드라마'' 쓴 사모펀드', '[기업을 살린 사모펀드들]③적자의 늪에 빠진 대한전선 인수한 IMM PE회사 살리려던 직원들 빚부터 탕감본업 살리고 기업가치 제고 ''반전 드라마''이 기사는 2026년03월02일 18시44분에마켓인 프리미엄 콘텐츠로 선공개 되었습니다.국내 시장에서 사모펀드는 구조조정과 고용 불안의 상징으로 굳어지고 있습니다. 일부 부정적 사건이 잇따르며 시선이 차가워졌지만, 실제로는 기업을 살리고 키워낸 사례가 많습니다.이데일리는 사모펀드가 인력 감축 대신 성장에 투자하며 기업가치를 끌어올린 사례를 집중 조명했습니다. 사모펀드에 인수됐다는 이유로 우려와 오해를 받았으나, 체질개선에 성공한 기업 사례를 통해 사모펀드의 전문 경영인 영입과 글로벌 확장, 고용 확대가 어떻게 실적 개선과 성장으로 이어졌는지를 살펴봤습니다.이를 통해 투자 방식과 경영 전략이 기업의 성패를 좌우한다는 점을 짚으며, 사모펀드를 둘러싼 편견을 다시 생각해 볼 필요성을 짚어보고자 합니다. [편집자 주][이데일리 마켓in 지영의 김연지 기자] 쓰러져가는 회사를 살려보겠다고 지갑을 열었던 직원들이 빚쟁이가 됐다. 대한전선이 휘청이던 지난 2000년대, 직원들은 회사가 버티는 데 보탬이 되고자 유상증자에 참여해 우리사주를 샀다. 54년 연속 흑자를 내던 ''내 회사''를 지켜보려던 선택이었다. 그러나 회사는 2008년 글로벌 금융위기 충격을 버티지 못하고 더 기울었고, 직원들에게 남은 것은 인당 수천만 원의 우리사주 매입 대출금이었다. 회사를 지키려던 마음이, 족쇄로 전락한 것이다.채권단 관리 끝에 대한전선은 국내 사모펀드 IMM프라이빗에쿼티(IMM PE)에 팔렸다. 구조조정과 인력 감축, 자산 매각. 새 경영자인 사모펀드가 여러 선택지 중 어떤 경영 방식을 고를지 불안감이 높을 수밖에 없던 상황이었다. 그런데 대한전선을 사들인 사모펀드는 의외의 이야기를 꺼냈다. 대한전선 경영진 및 직원들과 마주한 첫 타운홀 미팅, IMM PE는 ''빚 탕감''을 선언했다."대한전선 직원들의 우리사주 대출금 약 45억 원을 회사가 대신 상환하겠습니다"첫 인상부터 회사에 신선한 충격을 안긴 이 사모펀드는, 경영 기간 내내 대한전선에 ''반전 드라마''를 써내려갔다. IMM PE의 경영 하에 대한전선은 채권단 자율협약 기업이라는 꼬리표를 떼고 글로벌 수주를 기반으로 성장 궤도에 복귀했고, 이후 중장기 성장을 뒷받침할 수 있는 호반그룹으로 재매각된 무렵에는 15년 만에 매출 3조원을 회복했다.적자의 늪에 빠진 대한전선…문어발 확장과 금융위기의 후폭풍대한전선은 1941년 설립된 국내 최초 전선 회사로, 오랜 기간 국내 기간산업을 떠받친 기업이었다. 54년 연속 흑자를 내며 건실한 기업으로 불렸다. 그러나 대한전선의 창업주인 설경동 회장이 별세한 2000년대 중반 이후 경영이 흔들리기 시작했다. 무주리조트와 남부터미널, 해외 부동산 등 본업과 거리가 있는 투자들이 누적되면서 재무구조가 흔들렸고, 2008년 글로벌 금융위기는 그 취약한 구조를 정면으로 때렸다. 결국 대한전선은 2012년 채권단 자율협약에 들어갔다. 주요 채권자를 중심으로 관리단이 파견되고, 임시 체제 하에 소극적인 경영이 이어졌다.M&A 시장에 나온 대한전선을 지켜보던 IMM PE 눈에는 회사의 ‘수술이 필요한 부위’가 비교적 또렷하게 보였다. 회사를 무너뜨린 것은 본업과 거리가 먼 투자와 그로 인해 누적된 재무 부담, 그리고 체계적이지 못한 경영 구조였다. IMM PE는 경영만 제대로 하면 살릴 수 있는 회사라고 판단했다.IMM PE는 기존 주주 지분을 사들이는 방식 대신, 유상증자를 통해 회사에 직접 자금을 투입하겠다고 제안했다. 회사에 당장 현금이 유입되는 방식으로 사들여 재무 구조를 먼저 바로잡기 위해서였다. 지난 2015년 9월, IMM PE는 약 3000억원 규모의 유상증자를 단행하며 대한전선 지분 70.1%를 확보, 대주주로 올라섰다.회생의 첫 단추, 구조조정 대신 ''사람 투자''대한전선에 입성한 IMM PE는 회생의 첫 순서로 ''사람 투자'' 부터 시작했다. 인수 직후 회사가 어려울 때 직원들이 떠안게 된 약 45억원의 우리사주 대출금을 회사가 부담해 정리한 것 역시 투자의 일환이었다. 회사를 지탱해온 사람을 살려놔야 경영전략이 통하고, 성과가 자연스럽게 뒤따를 것이라는 판단이었다.[그래픽=이데일리 김일환 기자]경영진 구성도 인력감축과 전면 교체보다 재편에 방점을 찍었다. 대주주가 바뀌면 통상 최고경영자부터 교체하지만, IMM PE는 당시 영업을 이끌던 내부 인사를 직접 면담한 뒤 대표이사직을 유지했다. 회사를 가장 잘 아는 사람은 남기고, 재무·관리·우발채무 정리 등 구조를 바꾸는 역할 교체에 집중했다. 이를 위해 인수 직후 IMM PE의 딜팀이 현장에 상주하며 임직원 면담을 반복했다. 누가 앞으로 회사를 함께 이끌 수 있는지를 가려내는 데 방점을 둔 ''100일간의 플랜''이었다.보상과 평가의 기준도 다시 세웠다. 스톡옵션과 성과급 제도를 도입해 해외 수주와 수익성 개선 같은 결과에 보상이 직결되도록 했다. 구조조정이라는 칼을 꺼내들지 않아도, 보상과 평가 기준이 합리적으로 바뀌자 조직은 빠르게 재정비되기 시작했다.‘재무 쥐어짜기’ 대신 ‘경영 재설계’…사모펀드 만난 대한전선의 5년 반IMM PE가 대한전선에 들어와 가장 먼저 수술대에 올린 것은 불필요하게 비대한 사업 구조였다. 우수한 기술력을 갖고 있었지만, 각종 우발채무와 비핵심 자산이 얽힌 구조에서는 성장 전략을 제대로 펴기 어려웠다. 대한전선이 가진 우발채무의 상당 부분은 본업과 무관한 사업에 얽혀있었다. 리조트와 부동산, 터미널 개발 등에서 발생한 지급보증과 소송, 출자법인들과 관련된 책임들이 회사 전체를 옭아매고 있던 상황이었다.IMM PE는 남부터미널과 무주리조트, 해외 부동산 자산을 매각하고, 36개에 달하던 출자법인을 절반 수준으로 줄였다. 자산 매각 과정에서 보증과 잠재 부실까지 함께 걷어냈다. 불확실성을 제거해야 영업이 움직이고, 영업이 움직여야 성장이 가능하다는 판단이었다.사업 전략도 본업에 충실한 방향으로 틀었다. 저수익 제품을 줄이고, 초고압·고압(EHV/HV) 케이블과 해저 케이블처럼 기술 장벽이 높은, 투자할 수록 회사의 경쟁력을 키울 수 있는 영역에 집중했다. 고부가가치 영역을 키우자 미국과 유럽, 오세아니아, 아시아, 중동 등 주요 글로벌 시장에서 대형 수주 요청이 쏟아지기 시작했다.다음으로 손을 댄 곳은 브로커 의존도가 높은 해외 수주 구조였다. 중간 딜러를 거치는 구조 속에 수수료 부담이 높았고, 저가 수주 문제가 심각했다. IMM PE는 이런 구조가 수익성을 갉아먹는다고 보고 해외 지사를 통한 직접 영업을 강화하는 방향으로 전략을 틀었다. 발주처와 직접 거래하는 체계가 자리 잡으면서, 환율과 원자재 가격 변동을 감안한 원가 구조를 수주 단계에서부터 관리할 수 있게 됐고 저가 수주 비중도 자연스럽게 줄었다. 글로벌 수주에 다른 외화 자산 관리에서도, 환율과 원자재 가격 변동을 운에 맡기지 않도록 헤지 원칙을 세웠다. 환변동에 따른 투기적 성과를 기대하기보다, 제조업답게 이익을 고정해두는 방식이었다.경영 방식을 차츰 개선한 결과, 대한전선은 지난 2020년 흑자 전환에 성공했다. 인수 당시 4500억원대에 달하던 우발채무는 1000억원대로 줄었고, 순차입금 비율도 250%에서 100% 수준으로 감소했다. 총차입금 역시 2014년 1조1373억원에서 2020년 5863억원으로 절반 가까이 감소했다.IMM PE는 약 5년 반에 걸쳐 대한전선을 정상화 시키고, 키운 뒤 전략적 투자자(SI)인 호반그룹에 재매각했다. 통상 짧게는 3년, 길게는 5~6년을 투자한 뒤 회수하는 사모펀드의 특성상 자연스러운 수순이었지만, 대한전선이 한 단계 더 도약하기 위해서는 장기적인 설비 투자와 자본 투입이 가능한 주인이 필요해서였다. IMM PE가 경영 기간에 다져둔 재무건전성과 체력은, 대한전선이 호반그룹에 재매각된 이후에도 이어졌다. 대한전선은 호반 편입 이후에도 추가 유상증자와 차입 구조 개선을 통해 재무 부담을 낮췄고, 2024년에는 매출 3조원을 넘어섰다.우리가 모르는, 사모펀드의 다른 얼굴대한전선을 재도약시킨 IMM PE 사례는 ''사모펀드의 경영''에 대한 편견을 다시 보게 만든다. 사모펀드는 흔히 구조조정과 비용 절감의 이미지로 기억되지만, 기업 경영의 실제 현장에서는 그보다 훨씬 다양한 역할을 한다. 위기에 빠진 기업의 망가진 재무를 손질하고, 사업의 중심 전략을 다시 짜고, 무너져가는 조직을 다시 세울 수 있는 여건을 다진다. ''잘 사고, 잘 팔아서, 잘 번다''는 사모펀드의 성패는 결국 인수하고, 투자한 기업의 성공과도 맞닿아 있다.사모펀드는 영원한 주인은 아니다. 대신 병든 기업을 긴급하게 수술하고, 다시 일어설 수 있는 상태로 회복되는 과정을 책임지는 자본일 수 있다. 대한전선에서 IMM PE가 보여준 경영은, 위기의 순간 ''응급실 의사''에 가까웠다. 사모펀드를 보는 시야는 더 넓어질 필요가 있다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006227118', 'https://imgnews.pstatic.net/image/018/2026/03/03/0006227118_001_20260303180010472.png?type=w800', 'NEWS_ENERGY', NULL, '2026-03-03 06:46:15', 0, true, '2026-03-09 05:45:47.270845') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (607, '현대차·삼성화재, 광주 자율주행 실증 ''원팀''…사고당 100억 보험', '[일문일답] 현대차, 레벨4 무인주행 차량·플랫폼 공급삼성화재, 연 300억 보상 전용보험 설계8일(현지시간) 미국 네바다주 라스베이거스 모셔널테크니컬센터에 현대차 그룹과 모셔널이 함께 개발한 아이오닉 5 기반 ''로보택시''가 주차돼 있다. 2026.1.12 ⓒ 뉴스1 황기선 기자(세종=뉴스1) 조용훈 기자 = 국토교통부는 9일 자율주행 실증도시 사업을 지원하기 위해 자동차 제작사·보험사·운송플랫폼사가 함께 참여하는 ''K-자율주행 협력모델'' 참여 기업을 선정했다고 밝혔다. 현대자동차는 실증용 자율주행 차량과 운영 플랫폼을 제공하고, 삼성화재는 사고당 100억 원 규모의 전용 보험을 맡아 실증 과정의 리스크를 담당한다.이번 공모에는 자동차 분야 1개사, 보험 분야 5개사(삼성화재·현대해상·한화·KB·DB손해보험), 운송플랫폼 분야 5개사(현대자동차·카카오모빌리티·쏘카·스튜디오갈릴레이·코나투스)가 참여했다. 이 가운데 자동차 제작사와 운송플랫폼사는 현대자동차(005380), 보험사는 삼성화재(000810)가 최종 협력사로 선정됐다.현대자동차는 자율주행 전용차(SDV)를 공급하고 표준화된 차량 제어 인터페이스(API)와 고속 통신망을 제공해 자율주행 기업의 기술 개발과 데이터 수집을 지원한다. 동시에 차량 관제·배차·운행 데이터 분석 등 운송플랫폼 운영체계도 구축한다.삼성화재는 사고당 100억 원, 연간 300억 원 보상 한도의 전용 보험을 제공한다. 전담 콜센터 운영과 함께 사고기록장치(EDR) 분석, 사고 예방, IT 보안 컨설팅 등 특화 서비스도 맡아 실증 과정에서 발생할 수 있는 리스크를 흡수하는 역할을 담당한다.국토부는 4월 말까지 자율주행 기업 공모를 마무리한 뒤 선정 기업을 협력모델에 참여시켜 광주 자율주행 실증도시를 중심으로 자율주행 AI 기술과 서비스의 국제 경쟁력을 높인다는 계획이다.다음은 임월시 자율주행정책과장, 임채현 사무관과의 일문일답.8일(현지시간) 미국 네바다주 라스베이거스 모셔널테크니컬센터에 현대차 그룹과 모셔널이 함께 개발한 아이오닉 5 기반 ''로보택시''가 주차돼 있다. 2026.1.12 ⓒ 뉴스1 황기선 기자- 현대차가 제공하는 실증 차량의 종류와 성격은.▶ (임월시) 기본 플랫폼은 아이오닉 5를 기반으로 하지만 레벨4 무인 주행이 가능하도록 조향·제어·센서 등 핵심 장치를 이중화한 개발용 전용 차량을 공급한다. 기존에는 시판 차량을 역설계해 개조하는 방식이었지만, 이번에는 실증용 스펙을 국토부가 사전에 제시했고 현대차가 이에 맞춘 소프트웨어 중심 차량(SDV)을 제공하는 구조다.이 차량에는 자율주행 시스템 탑재를 위한 표준화된 차량 제어 인터페이스와 고속 통신 네트워크가 포함된다. 차량에서 발생하는 데이터의 실시간 수집과 상태 모니터링, 데이터 파이프라인 구축도 함께 이뤄질 예정이다.- 사고당 100억·연 300억 보상 한도는 어떻게 산정됐는지.▶ (임월시) 국토부는 공모 단계에서 자율주행 전용 보험 설계와 일정 수준 이상의 보상 한도를 지원 조건으로 제시했고, 그 범위 안에서 보험사들이 자율적으로 한도를 제안했다. 그 과정에서 삼성화재가 고난이도 자율주행 실증에 맞춘 비교적 높은 보상 한도를 제시해 차별화됐다.자율주행 실증 과정에서 발생할 수 있는 다양한 사고에 대비해 사고당 100억 원, 연간 300억 원 수준의 보장 구조를 제시한 것으로 볼 수 있다. 기존 자동차 보험이 법정 책임보험과 종합보험을 조합해 보상 한도가 단계적으로 올라가는 구조라면, 이번 상품은 실증 리스크를 고려해 보험사가 자체적으로 높은 상한을 설정한 실증 특화 상품에 가깝다.- 실제 사고 발생 시 책임 주체와 분담 구조는 어떻게 되나.▶ (임월시) 자율주행차 전용 보험 상품이 아직 본격적으로 도입되지 않았기 때문에 구체적인 책임 분담 규칙은 확정되지 않았다. 지금까지는 일반 자동차 보험에 자율주행 특약을 추가하는 수준으로, 레벨3 정도를 가정한 구조였다.이번 사업은 레벨4를 목표로 하는 만큼 상반기 중 삼성화재가 자율주행 보험 초안(draft)을 마련하고, 하반기에는 실증 과정에서 축적되는 사고·운행 데이터를 바탕으로 가중치, 리스크 헤지, 책임 분담 비율 등을 단계적으로 조정할 계획이다.원칙적으로는 자율주행 기술 기업이 차량을 가져와 개조하고 소프트웨어를 탑재해 운행하는 구조이기 때문에 1차 책임 주체로 본다. 다만 사고조사위원회 분석 결과 차체 결함 등 제조사 책임이 인정될 경우 제작사까지 책임 범위가 확대될 수 있다. 플랫폼사·지자체 등의 역할과 책임 분담 문제도 보험 설계 과정에서 함께 논의될 예정이다.- 그동안 자율주행 실증 과정에서 사고는 어느 정도 발생했는지.▶ (임월시) 국토부는 ''자율주행차 사고 조사위원회''를 통해 자율주행차 사고를 100% 신고받아 관리하고 있으며 유·무선 신고 체계를 운영하고 있다. 축적된 사고 데이터를 보면 대부분 차량 간 경미한 접촉이나 안전관리자의 조작 오류 등 비교적 작은 사고가 대부분이었다.지금까지 인명 피해가 발생한 중대 사고 사례는 보고되지 않았다. 이러한 리스크를 고려해 각 실증 사업도 난이도가 낮은 구간과 시간대 중심으로 비교적 보수적으로 운행해 왔다. 이번에 전용 보험과 협력모델이 구축되면 다양한 도로와 시간대로 실증 범위를 확대할 기반이 마련될 것으로 보고 있다.- 100억 보상 한도의 수준은 일반 자동차 보험과 비교해 어느 정도인가.▶ (임월시) 일반 자동차 보험은 자동차손해배상보장법상 법정 책임보험 한도가 있고 여기에 종합보험을 추가해 배상 한도를 높이는 구조다.반면 자율주행 실증도시 사업은 국비 예산으로 실증을 지원하는 만큼 정부 예산과 별도로 보험사가 산정한 보상 한도가 설정된다. 삼성화재는 자율주행 실증의 고위험성을 고려해 사고당 100억 원, 연간 300억 원 한도를 제시했다. 이는 실증 과정에서 발생할 수 있는 복합 사고나 대규모 피해 가능성까지 고려한 수준으로 해석된다.​- 4월 말 자율주행 기업 공모 이후 세부 일정은 어떻게 진행되나.▶ (임월시) 이번에 선정된 K-자율주행 협력모델은 자율주행 기술 기업을 지원하는 ''베이스 라인'' 역할을 한다. 차량·플랫폼·보험 인프라가 기반을 제공하고, 그 위에서 자율주행 기술 기업이 실증에 집중하는 구조다.과거에는 스타트업이 차량 구매와 개조, 운행, 보험까지 모두 부담해야 했지만 이번에는 역할을 분업화·특화했다. 각 분야의 기업이 기반을 제공하고 자율주행 기업은 기술 실증에 집중하도록 설계했다.4월 말 자율주행 기술 기업 공모가 끝나면 5월 중 3개 안팎의 기술 기업을 선정해 현대차·삼성화재·운송플랫폼과 하나의 패키지 팀으로 묶는다. 이를 광주 실증도시 사업의 핵심 운영 주체로 삼을 계획이다.- 실제 자율주행 차량 운행은 언제부터 시작되나.▶ (임월시) 차량 제작사로 현대차가 선정된 만큼 국토부가 요청하면 현대차가 우선 소량의 시제품 차량을 제공한다. 이후 5월 선정된 자율주행 기술 기업들이 이 차량을 기반으로 자체 시스템을 탑재하는 테스트를 진행한다.각 기업이 기존에 사용해 온 차량과 플랫폼이 다른 만큼 새로운 SDV에 맞춘 적응과 보정 기간이 필요하다. 개조 작업에는 약 두세 달이 걸릴 것으로 보고 있다.이후 화성 K-City에서 반복적인 시험 주행을 통해 자율주행 성능을 검증한다. 안전성이 충분히 확보됐다고 판단되면 광주 도심 실증에 투입한다. 하반기에는 광주 전역을 대상으로 월별로 실증 차량을 순차 투입해 규모를 확대할 계획이다.- 정부 지원 실증 과정에서 수집되는 데이터는 어떻게 활용·공유되나.▶ (임월시) 이번 실증 사업은 국비 예산이 투입되는 만큼 참여 자율주행 기술 기업은 수집한 데이터를 국토부와 전담기관에 의무적으로 제출해야 한다.데이터는 원칙적으로 ''공유를 기본''으로 하되 개인정보와 영상 정보 보호 문제를 고려해 방식에 차이를 둔다. 자율차법 개정으로 개별 기업이 자신의 자율차를 통해 수집한 원본 영상 정보는 실증에 활용할 수 있지만 제3자가 활용할 경우 개인정보 비식별화나 영상 블러 처리 등 일정한 제한이 따른다.정부는 참여 기업 간에는 일정 수준의 데이터 표준화를 통해 상호 공유를 의무화하고, 제3자 공개는 개인정보 보호 조치 수준에 따라 단계적으로 범위를 확대하는 방향을 검토하고 있다.- 광주 시민들의 인지와 지역 사회 수용성은 어떻게 높일 계획인지.▶ (임월시) 광주가 자율주행 실증도시로 지정된 사실은 연초에 발표됐지만 아직 시민들에게 널리 알려질 시간은 충분하지 않았다. 무엇보다 실증 성공을 위해서는 시민들의 지지와 이해가 중요하다. "우리 동네에서는 안 된다"는 인식이 확산되면 사업이 위축될 수 있기 때문이다.자율주행차로 인한 교통 정체나 출퇴근 불편에 대한 우려도 있는 만큼 광주시와 국토부가 시민 대상 홍보와 설명, 민원 대응 체계를 강화해야 한다.▶ (임채현 사무관) 이와 별도로 광주시 주도로 ''지역 상생 협의체''를 발족해 시민사회와 소통 창구를 마련할 계획이다. 협의체에는 지역 시민단체뿐 아니라 기존 운수업계 종사자도 참여시켜 자율주행 서비스 도입에 따른 이해관계와 우려를 사전에 조율할 예정이다. 이를 통해 지역 주민의 기술 체감도와 수용성을 높이고 자율주행 서비스가 지역 경제와 교통 체계와 상생하는 방향으로 자리 잡도록 유도할 계획이다.', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008814597', 'https://imgnews.pstatic.net/image/421/2026/03/09/0008814597_001_20260309140420000.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 13:00:00', 0, true, '2026-03-09 05:46:11.674488') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (608, '금융당국, 과잉영업 "콕 찝었는데"…KB손해보험, 보험모집 민원 ''경고등''', '보유계약 10만건당 모집 민원 1.05건…주요 손보사 ''최상위''구본욱 대표 취임 이후 모집 민원 증가세…지난해 733건 집계구본욱 KB손해보험 사장(왼쪽)이 지난달 금융감독원이 주최한 보험회사 최고경영인(CEO) 간담회에 참석해 유인물을 살피고 있다. /김정산 기자[더팩트ㅣ김정산 기자] 이찬진 금융감독원장이 보험사의 과잉영업 행태에 주의를 당부한 가운데 지난해 주요 손해보험사 중 KB손해보험이 보험모집 부문 민원 비율이 가장 높은 것으로 나타났다. 구본욱 KB손해보험 사장이 취임 당시 강조했던 ''고객 최우선'' 기조와 대비되는 행보다.5일 금융권에 따르면 최근 이찬진 금융감독원장은 보험회사 최고경영인(CEO)들과 간담회를 진행했다. 보험관련 민원이 전 금융권에서 접수되는 소비자 민원 중 40%를 차지하고 있음을 직접 언급한 만큼 보험업권을 향해 꾸준히 강조했던 소비자 보호를 당부하기 위한 것으로 풀이된다. 이 원장은 "일부 상품에서 과도한 모집수수료 경쟁과 불합리한 상품 구조 등으로 소비자 신뢰가 저하되고 있다"고 직접 꼬집었다.이 원장은 향후 보험산업의 발전 방향으로 △소비자 보호 중심 경영 △건전한 영업 관행 정착 △사회적 책임 확대 등을 제시했다. 특히 CEO가 소비자 보호를 핵심 경영원칙으로 삼고 내부통제와 위험관리 체계를 강화해야 한다고 강조했다. 아울러 판매수수료 제도 개편 과정에서 시장 혼탁 행위를 엄정히 관리하겠다는 방침이다.실제로 보험업계에서는 올 상반기 영업 경쟁이 과열될 수 있다는 목소리가 적지 않았다. 오는 7월부터 ''1200%룰''과 보험수수료 7년 분납 등이 적용되는 만큼 제도 시행 전 수익 확보를 위한 영업 경쟁이 나타날 수 있다는 관측이 나오면서다. 이에 금융당국 또한 업계가 우려한 단기적인 부작용 가능성을 사전에 차단하려는 의도도 담긴 것으로 해석된다.금융당국이 보험업계의 과도한 수수료 경쟁 등 영업관행을 경계하고 있으나 지난해 4분기 말 기준 KB손해보험의 보유계약 10만건당 발생한 보험 모집 관련 민원은 1.05건으로 집계됐다. 주요 손해보험사 5곳(메리츠화재·삼성화재·현대해상·KB손해보험·DB손해보험) 중 가장 높은 수치다.절대적인 민원 건수 역시 상위권에 속한다. 같은 기간 KB손해보험의 보험 모집 관련 민원 건수는 733건으로 △메리츠화재(382건) △삼성화재(450건) △현대해상(433건)보다 많은 수치다. 전체 민원 규모에서는 DB손해보험이 856건으로 가장 많았지만, 보유계약 10만건당 발생한 민원 건수는 0.82건으로 1건에도 미치지 않는 수준이다.KB손해보험의 보험 모집 관련 민원 건수는 구본욱 사장 취임 첫해 이후 본격적으로 상승 궤도에 올랐다. KB손해보험의 보험 모집 관련 민원 건수는 지난 2022년 466건에서 다음 해인 2023년 505건으로 8.4% 늘어나는 데 그쳤지만, 구 사장 취임 첫해인 2024년에는 605건으로 연간 19.8% 증가했다. 특히 연임의 분수령으로 볼 수 있는 지난해에는 733건까지 확대되며 전년 대비 21.2% 상승했다.보험 모집 관련 민원이란 보험 상품을 판매·권유하는 과정에서 발생하는 소비자 불만을 의미한다. 보장 내용이나 위험 요소를 충분히 설명하지 않거나 수익률 등을 과장해 안내하는 경우가 대표적이다. 기존 보험을 해지하고 새 상품 가입을 유도하는 ''부당승환''도 주요 유형 중 하나로 손꼽힌다.KB손해보험의 영업 관련 지표는 녹록지 않은 흐름을 보이고 있다. 금감원에 따르면 KB손해보험의 25회차 계약 유지율은 지난 2023년 75%에서 다음 해 70%로 하락한 뒤 지난 2025년 상반기까지 70% 수준에 머물렀다. 같은 기간 경쟁사인 DB손해보험과 현대해상은 각각 74%, 73% 수준을 유지했고 삼성화재는 69% 수준에 머물렀지만 꾸준히 회복 흐름을 보이고 있다.업계에서는 25회차 유지율이 낮을 경우 보험료 부담이나 상품 경쟁력, 모집 단계에서의 불완전판매 가능성 등이 영향을 미쳤을 수 있다고 본다. 구 사장 취임 이후 25회차 계약 유지율이 낮아진 만큼 영업 과정 전반에 대한 점검이 필요하다는 지적도 나온다.보험설계사 정착률도 주요 손해보험사 중 하위권이다. 지난 2024년 말 기준 KB손해보험의 설계사 등록 정착률은 54.66%로 △DB손해보험(64.61%) △삼성화재(58.25%) △현대해상(55.61%) 등 주요 손보사 대비 낮은 수준을 보였다. 설계사 정착률이 낮다는 것은 모집 과정에서 불완전판매나 민원이 발생할 가능성이 높다는 것으로도 해석된다. 내부 관리 체계 강화와 인센티브 구조 개선 등이 요구되는 대목이다.이에 대해 KB손해보험은 민원 통계가 실제 소비자 불만 규모를 그대로 반영한 것은 아닐 수 있다는 입장이다. 대외민원 뿐 아니라 민원을 사전에 관리하기 위해 내부적으로 접수하는 ''대내 민원''이 존재하는데, 이 과정에서 예상되는 민원 사안을 미리 등록하는 경우도 있어 집계 수치가 늘어날 수 있다는 설명이다.또 보험사별로 민원을 분류하고 협회에 제출하는 과정에서 집계 방식이 동일하지 않다는 점도 영향을 미쳤을 가능성이 있다는 설명이다. 각 사별로 민원을 분류하는 기준이 달라 단순 수치 비교는 어렵다는 것이다.KB손해보험 관계자는 "사소한 불편이나 단순 질의도 대외 민원으로 확대되기 전 대내 민원으로 선제 등록해 관리하고 있다"며 "보험사별 민원 분류 기준 차이로 수치가 높아 보일 수 있지만 선제적인 민원 관리로 서비스 품질 개선에 힘쓰겠다"고 말했다.발로 뛰는 더팩트는 24시간 여러분의 제보를 기다립니다.▶카카오톡: ''더팩트제보'' 검색▶이메일: jebo@tf.co.kr▶뉴스 홈페이지: http://talk.tf.co.kr/bbs/report/write', NULL, '더팩트', 'https://n.news.naver.com/mnews/article/629/0000478646', 'https://imgnews.pstatic.net/image/629/2026/03/06/202612991772757760_20260306112709000.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-06 11:08:10', 0, true, '2026-03-09 05:46:11.674488') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (609, '"GA 관리 못하면 건전성 타격"…보험사 ''제3자 리스크'' 관리 고삐', '위탁GA 관리 평가해 킥스 연동 규제 신설보험사들, GA 협업해 선제적 대응 움직임[서울=뉴시스][서울=뉴시스]권안나 기자 = 금융당국이 법인보험대리점(GA) 관리 실태를 등급화해 원수보험사에 책임을 묻는 제도 도입을 추진하면서 보험업계의 긴장감이 높아지고 있다. 판매 채널에서 발생하는 불완전판매나 내부통제 미흡 문제가 보험사 건전성 평가에까지 영향을 줄 수 있기 때문이다.6일 금융권에 따르면 금융당국은 보험사의 위탁GA 관리 실태를 평가해 등급을 매기는 ''운영위험 평가제도'' 신설을 위해 업권의 의견을 수렴하고 있다.금융당국은 보험사가 GA에 대한 리스크 이상징후에도 적절한 통제활동을 수행하지 않은 것으로 판단하고, 관리 강도를 점층적으로 높여가고 있다.지난해 4월 설계사 위촉업무 기준을 배포하고, 연말에는 보험사들에 제3자 리스크관리 가이드라인을 배포해 내부통제 체계 정비를 주문했다.대형 보험사들도 대응에 나서고 있다. 일부 보험사는 주요 GA와 업무협약(MOU)을 체결하거나 공동 교육·점검 체계를 마련하는 등 내부통제 협력 방안을 확대하고 있다.한화생명은 한화생명금융서비스·한화라이프랩·피플라이프·IFC그룹 등 자회사형 GA 조직 역량을 기반으로 이미 이사회 산하에 위험관리 관련 협의회를 구성하고 위탁 위험 평가에 대한 기준을 수립했다. GA를 대상으로 우선적으로 첫 평가를 실시할 예정이며, 하반기에는 다른 위탁사 대상으로도 평가를 실시한다.삼성생명은 지난해부터 글로벌금융, 지에이코리아, 인카금융, 토스인슈어런스 등 10개의 대형 GA들과 연이은 업무협약을 체결하고, 판매 과정에서 발생할 수 있는 리스크를 사전에 관리하기 위한 협업에 나섰다.현대해상도 대형 GA 23개사를 대상으로 ''소비자보호 세미나''를 열고  영업관련 주요 민원 정보 및 사례 소개와 금융소비자보호 내부통제 주요 정보 등을 공유하는 자리를 가졌다. KB손보는 최근 지에이코리아와 내부통제와 개인정보보호 관리 체계 고도화 등을 추진하기 위한 업무협약을 맺었다.다만 업계에서는 현실적인 한계도 적지 않다는 지적이 나온다. GA가 보험사 입장에서는 핵심 판매 채널로 나날이 그 비중이 확대되고 있기 때문이다. 여러 보험사의 상품을 동시에 취급하는 GA 특성상 특정 보험사가 일방적인 통제 강도를 높이기 쉽지 않은 상황이다.이 같은 여건 속에서 금융당국이 GA 관리 실태를 보험사의 지급여력비율(K-ICS·킥스) 등 건전성 지표와 연계하는 방안까지 검토하면서 업계의 우려는 더 커지고 있다.금융당국은 GA에서 다수의 소비자피해나 금융질서문란을 초래한 중대한 불법·불건전 영업행위 또는 금융사고가 발생한 경우, 관리책임을 소홀히 한 보험사를 연계 검사해 엄정 대응한다는 방침도 발표했다.업계에서는 이 같은 제3자 리스크 관리 체계의 실효성을 높이기 위해서는 GA 관리 책임의 범위와 방식이 구체화돼야 한다는 목소리가 나온다.보험업계 한 관계자는 "보험사가 GA에 내부통제 기준을 요구하더라도 GA가 이미 보험시장의 핵심 채널로 자리 잡은 구조상 강제력을 행사하기 어려운 것이 현실"이라며 "명확한 법적 근거가 마련되지 않고 책임만 강화될 경우 현장에서 부담이 커질 수 있다"고 말했다.금융당국은 상반기 중 운영위험 평가제도 등급 산정 기준을 마련하고, 연내 시범사업을 실시하는 것을 목표로 제도 설계를 진행하고 있다.위탁GA의 민원발생률, 계약유지율, 불완전판매비율 등 판매품질과 수수료 정책 등을 고려해 회사별 운영위험을 1~5등급으로 평가하고, 평가 결과가 저조한 보험사에는 킥스비율의 패널티를 부과한다는 방침도 세웠다.금감원 관계자는 "평가 기준이 한번 만들어지면 업계에 미치는 영향이 크다보니 실무 차원에서 의견 수렴을 하면서 지표를 명확하게 만드는 데 집중하고 있다"며 "소비자 보호에 목적을 두고 있는 만큼, 연내 시범 운영을 하면서 제도를 개선해나갈 것"이라고 말했다．', NULL, '뉴시스', 'https://n.news.naver.com/mnews/article/003/0013804953', 'https://imgnews.pstatic.net/image/003/2026/03/06/NISI20250217_0001772025_web_20250217163208_20260306072919007.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-06 07:00:00', 0, true, '2026-03-09 05:46:11.674488') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (610, '롯데손보, 경영개선요구 격상… 소송 취하·이사회 정비 ''매각 속도전''', '롯데손보, 적기시정조치 이행 기간에도 ''정상 영업''경영정상화 나선 롯데손보…행정소송 취소, 사외이사 교체 등 자세 낮춰롯데손해보험 사옥(서울=뉴스1) 박재찬 보험전문기자 = 금융위원회가 롯데손해보험에 대해 경영개선권고보다 한 단계 높은 경영개선요구 조치를 내렸다. 이에 따라 롯데손보는 2개월 내 자본적정성을 높이기 위한 경영개선계획을 금융감독원에 제출해야 한다.적기시정조치 이행 기간에도 롯데손보는 정상 영업을 한다. 하지만 롯데손보의 적기시정조치 격상에 이미 ''MG손보 사태''를 겪은 소비자들의 불안감은 커지고 있다.금융권에서는 ''MG손보 사태''가 마무리되지 않은 만큼 당국이 롯데손보에 대해 추가로 적기시정조치 수위를 높이기는 쉽지 않을 것이라는 관측이 나온다. 또 롯데손보와 대주주인 JKL파트너스도 금융위를 상대로 제기했던 행정소송을 취소하고, 사내이사를 교체하는 등 경영 정상화를 위해 적극적으로 나서고 있다.6일 금융권에 따르면 금융위원회는 지난 4일 정례회의에서 롯데손해보험에 대해 경영개선요구 조치를 의결했다.이번 금융위의 경영개선요구는 지난해 11월 5일 경영개선권고 조치를 받은 롯데손보가 제출한 경영개선계획이 불승인됨에 따른 조치다. 금융위는 롯데손보가 제출한 경영개선계획의 구체성, 실현 가능성, 근거 등이 부족하다고 판단해 이를 불승인했다.이번 조치에 따라 롯데손보는 향후 2개월 내 자산 처분, 비용 감축, 조직 운영 개선, 자본금 증액, 매각 계획 수립 등 자본적정성(계량·비계량 항목 종합)을 높이기 위한 경영개선계획을 마련해 금융감독원에 제출해야 한다. 또 금융위가 해당 계획을 승인할 경우 롯데손보는 향후 1년 6개월간 개선 작업을 이행하게 된다.적기시정조치는 금융당국이 부실 금융회사에 재무 건전성 개선을 요구하는 제도다. △경영개선권고 △경영개선요구 △경영개선명령 등 단계로 구분된다.이번에 롯데손보에 부과된 경영개선요구 단계에서는 주주배당 제한 또는 금지, 점포 폐쇄·통합 또는 신설 제한, 임원 교체 요구, 일부 보험종목 영업 제한, 조직 축소 등의 조치가 내려질 수 있다.이후 경영개선명령 단계로 격상되면 주식 일부 소각 및 병합, 임원 직무집행 정지 및 보험관리인 선임, 보험사업 전부 또는 일부 정지, 계약 이전, 합병 등의 조치가 가능하다.''MG손보 사태''는 아직도 진행중…금융위도 롯데손보 추가 조치는 ''부담''금융권에서는 당국도 롯데손보에 대한 추가적인 적기시정조치 상향은 부담스러울 것이라는 관측이 나온다. 지난 2018년 적기시정조치를 받은 MG손해보험(현 예별손해보험)도 아직 정리되지 않고 있기 때문이다.MG손보는 적기시정조치를 받은 이후 부실금융기관으로 지정됐다. 이후 예금보험공사 주도로 여러 차례 매각을 시도했지만 결국 실패했다. 현재 MG손보는 파산해 가교보험사인 예별손해보험 체제로 운영되고 있다.하지만 ''MG손보 사태''는 여전히 진행 중이다. 현재 예별손보는 삼성화재, DB손해보험, 메리츠화재, 현대해상, KB손해보험 등 대형 손해보험사로의 계약 이전을 추진하는 한편 매각 절차도 진행 중이다. 하나금융지주, 한국투자금융지주, JC플라워 등이 인수 검토를 위한 실사를 진행하고 있으며 오는 30일 본입찰이 예정돼 있다.금융당국의 적기시정조치부터 예별손보 체제까지 이어진 ''MG손보 사태''로 보험소비자들의 불안감은 계속 이어지고 있다. 실제 일부 소비자들은 "롯데손보도 MG손보처럼 되는 것 아니냐"는 반응까지 나오고 있다.다만, 롯데손보의 현재 경영 상황은 당시 MG손보와 차이가 크다. 지난해 말 기준 롯데손보의 순이익은 513억 원으로 전년 동기 대비 111.9% 증가했고, 재무건전성 지표인 지급여력비율(K-ICS)은 159.3%로 당국 권고치를 크게 웃돌았다.금융위는 "롯데손보에 대한 경영개선요구는 자본건전성 관리 강화를 유도하기 위한 사전 예방적 성격의 조치"라며 "경영개선계획을 충실히 수립하고 이행해 적기시정조치 사유를 해소하면 경영개선요구 조치도 종료된다"고 밝혔다. 이어 "조치 이행기간 중 롯데손보는 정상 영업을 하며 보험금 지급과 퇴직연금 운영 등 보험서비스는 차질 없이 제공되므로 계약자는 안심하고 서비스를 이용할 수 있다"고 덧붙였다.롯데손보, 소송 취소·이사 교체 등 경영 정상화에 적극 나서롯데손보도 경영 정상화 작업에 속도를 내고 있다. 우선 롯데손보는 금융위를 상대로 제기했던 행정소송을 취소했다. 지난해 롯데손보는 금융위의 경영개선권고 의결에 대해 효력정지 가처분 신청과 본안 소송을 제기한 바 있다.또 기획재정부 출신의 최원진 JKL파트너스 부대표가 최근 롯데손보 사내이사직에서 물러났다. 최 부대표는 JKL파트너스의 롯데손보 인수를 이끈 인물이다. 특히 지난해부터 이어지고 있는 금융당국과 롯데손보 사이의 마찰에 최 부대표의 의중이 크게 작용했던 것으로 알려졌다.이에 시장에서는 최 부대표의 퇴사로 금융당국과 롯데손보의 갈등이 해소 국면에 접어들 것이라는 관측도 나온다. 롯데손보는 다음 달 주주총회를 열고 JKL파트너스 창업자인 강민균 대표를 기타비상무이사로 선임할 예정이다. 금융당국이 지적한 비계량 평가 문제도 1분기 내 해소한다는 계획이다.JKL파트너스는 롯데손보 매각 작업에도 속도를 낼 계획이다. JKL파트너스는 그동안 유지했던 "일정 가격 이하면 매각하지 않겠다"는 기조를 버리고 매각가 가이드라인도 없애기로 결정했다. 이에 따라 시장에서는 롯데손보 매각가가 1조 원 안팎까지 낮아질 것이라는 관측도 나오고 있다. JKL파트너스는 지난 2024년부터 JP모건을 주관사로 선정해 롯데손보 매각을 추진해 왔지만 2조 원 수준의 높은 매각가가 걸림돌로 작용해 왔다.업계 관계자는 "롯데손보가 경영 정상화와 적기시정조치 해소에 적극적으로 나서고 있다"며 "금융당국 입장에서도 MG손보 사태가 수습되지 않은 상태에서 롯데손보까지 적기시정조치를 상향하는 것은 부담스러울 수밖에 없다"고 말했다.', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008809758', 'https://imgnews.pstatic.net/image/421/2026/03/06/0008809758_001_20260306114815169.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-06 06:53:31', 0, true, '2026-03-09 05:46:11.674488') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (611, '[Why&Next]보험사 채권 전략 변화…초장기물 약화 속 장기채 매수 지속', '30년물 금리 상승…초장기물-장기물 간 금리 역전 폭 축소시장 환경 변화에 보험사 매수 여력 약화듀레이션 규제 영향…"장기채 중심 투자 이어질 것"최근 국고채 30년물 금리가 상승하는 등 채권시장 수급에 변화가 나타나고 있다. 그동안 초장기채의 핵심 매수 주체였던 보험업계의 매수 강도가 예전보다 약해졌다는 평가가 나오면서 보험사들의 채권 투자 전략에 변화가 감지되는 모습이다. 다만 자산과 부채의 만기 구조를 맞추기 위한 듀레이션 관리 필요성이 지속되는 만큼 보험사들의 장기채 중심 투자 기조는 당분간 이어질 것이라는 전망이 나온다. 금융당국이 자산부채관리(ALM) 강화를 추진하고 있는 점이 이러한 흐름에 힘을 싣는 요인으로 지목된다.6일 금융권에 따르면 지난 3일 국고채 30년물 금리는 전 거래일 대비 15bp(1bp=0.01%포인트) 급등한 3.57%에 장을 마감했다. 같은 날 3.59%를 기록한 10년물보다 2bp 낮은 수준이다. 연초 17bp 이상 벌어졌던 초장기물과 장기물 간 금리 역전 폭이 줄며 장기 금리가 단기 금리에 근접하는 흐름을 보이고 있다.시장에서는 이 같은 초장기 금리 상승 흐름의 배경으로 보험업계의 채권 수요 변화가 영향을 미쳤다는 분석이 나온다. 그간 국고채 30년물의 핵심 매수 주체였던 보험사들의 매수 여력이 예전보다 약해졌다는 것이다. 최근 보험사들은 국채 발행 당국과의 협의 자리에서 초장기물 매수 규모를 크게 늘리기 어렵다는 의견을 전달한 것으로 알려졌다.이와 관련해 증시 호조에 따른 ''머니무브'' 현상이 초장기물 수요 감소 요인 중 하나로 꼽힌다. 지난해부터 이어진 주식시장 강세에 따른 자금 이동이 보험사 장기자금 유입에도 일부 영향을 미쳤을 가능성이 제기된다. 실제로 지난해 11월 말 기준 생명보험사의 전체 보유 계약 규모는 약 2311조원을 기록하며 전년(2339조원) 대비 1.2% 감소했다.증시로의 자금 이동 현상만으로 초장기물 수요가 줄어든 것을 설명하기 어렵다는 지적도 나온다. 김재우 삼성증권 리서치센터 팀장은 "보험사의 초장기채 매수 감소는 증시 강세에 따른 영향도 일부 있지만 보다 근본적으로는 전반적인 시장 금리 상승에 따른 자본 여력 개선이 영향을 미친 것으로 보인다"고 했다. 이는 금리 상승 시 보험사의 부채 현재가치가 감소해 지급여력비율(K-ICS) 등 건전성 지표가 개선되는 구조와 관련된다. 자본 여력이 커지면 자산과 부채의 만기를 맞추기 위해 초장기채를 적극적으로 매입해야 할 필요성이 과거보다 줄어들 수 있다는 설명이다.김 팀장은 "그동안 보험사들이 초장기채를 지속적으로 매입하면서 장기 국채 금리가 단기채보다 낮은 금리 역전 현상이 이어졌는데, 이는 보험사 운용자산 수익률을 떨어뜨리는 요인으로 작용하기도 했다"며 "현재 보험사의 자산운용 환경은 대체로 과거보다 우호적으로 변한 상황"이라고 말했다.보험사, ALM 관리 강화해야…"장기채 매수 계속"초장기 국채 수요는 다소 약화했지만 장기채 전반에 대한 보험사의 투자 수요는 이어지고 있다. 금융투자협회에 따르면 연초 이후 지난달 말까지 보험사들의 채권 순매수 규모는 약 7조9000억원을 기록하며 전년 동기 대비 70% 넘게 증가했다. 주로 국채와 특수채, 은행채 등 안정적인 중장기 채권 위주로 투자하는 모습이다.전문가들은 자산과 부채의 만기를 맞추기 위한 듀레이션 관리 필요성에 따라 보험사들의 장기채 투자 기조가 당분간 이어질 것으로 보고 있다. 지난해 금융당국이 듀레이션 관련 규제를 올해부터 도입할 계획을 밝힘에 따라, 보험사들은 ALM을 한층 강화해야 하는 상황이다. 듀레이션은 금리 변동 시 자산과 부채 가치가 얼마나 변하는지를 나타내는 민감도 지표다. 자산 듀레이션과 부채 듀레이션의 차이인 듀레이션 갭이 0에 가까울수록 자산과 부채의 만기 구조가 잘 맞춰졌다는 것을 의미한다. 반대로 차이가 클수록 금리 변화에 따른 순자산 변동성이 커진다.금융위원회는 보험사의 금리 리스크 관리 강화를 위해 경영실태평가 항목에 듀레이션 갭 지표를 새로 반영하고 갭이 일정 범위 이상인 경우 하위 평가 등급이 되도록 설정하는 등 강화된 기준을 적용할 계획이다. 아울러 경영공시 항목에 듀레이션과 듀레이션 갭을 추가해 시장규율 및 감시체계가 작동할 수 있도록 유도한다는 방침이다. 금융위는 "보험산업의 ALM 관리와 자산운용 수익률을 제고하기 위한 출발점"이라며 "건전성에 기반한 신뢰 금융과 생산적 금융 간 선순환 구조 마련에 기여할 것"이라고 강조했다.보험사들은 금융당국의 기조에 발맞춰 듀레이션 관리 강화를 위해 장기채 중심의 자산운용 전략을 이어가는 모습이다. 지난해 1분기 마이너스(-) 3년 이상까지 벌어졌던 듀레이션 갭을 연말에 -0.7년까지 좁히는 데 성공한 현대해상은 최근 콘퍼런스콜에서 "이 같은 자본비율 개선세는 시장금리 상승 영향에 더해 자산 측면에서 장기채 투자 비중을 확대한 노력이 반영된 것"이라며 "올해도 ALM 개선을 위해 장기채 투자 비중을 늘려 자산의 금리 민감도를 높일 계획"이라고 했다.업계 관계자는 "새 국제회계기준(IFRS17) 도입 이후 보험 부채가 시가 기준으로 평가되면서 보험사들이 국내 장기채와 더불어 해외 장기채까지 매입해 자산 듀레이션을 점진적으로 늘리는 전략을 이어가는 추세"라며 "단기적으로 금리 변동성에 따라 운용 방식에 일부 조정은 있을 수 있지만 듀레이션 규제 도입과 기본자본 K-ICS 비율 관리 등을 고려하면 장기채 중심의 ALM 관리 기조는 유지될 가능성이 높다"고 말했다.', NULL, '아시아경제', 'https://n.news.naver.com/mnews/article/277/0005730123', 'https://imgnews.pstatic.net/image/277/2026/03/06/0005730123_001_20260306113016167.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-06 06:10:00', 0, true, '2026-03-09 05:46:11.674488') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (612, '현대해상, 못 준 성과급 주식으로…주가가 ''변수'' [기업 백브리핑]', '2006년 이후 처음으로 성과급을 주지 못해 ''회사가 이렇게 어렵나'' 하는 불안을 키웠던 현대해상이 뒤늦게 격려금을 지급하기로 했습니다.보유한 자사주의 약 8%(지분율 1%)를 뚝 떼서 지급한다는 계획입니다.주가가 요동치고 있어 정확한 산정은 어렵습니다만 한 달 월급에 준하는 수준이 지급되는 것으로 전해졌습니다.3차 상법 개정안이 통과되면서 자사주 소각 압박이 커진 상태인데 이를 직원들에게 주면서 명분도 실속도 챙기겠다는 선택을 한 것으로 보이는데요.이에 더해 나머지 자사주 약 1000만 주 중 830만 주를 2년간 순차 소각하는 방안도 실행할 계획입니다.다만 문제는 역시 주가죠.최근 상법 개정 수혜로 주가가 급등했다가 이란 사태 이후 그 상승분을 대부분 되돌려놓은 상태인데요.기업 주가의 핵심은 역시 실적입니다.직원 보상과 주주가치 제고 등 어떤 목적이든 자사주의 활용이 의미가 있으려면 실적의 유의미한 개선이 필요하다는 지적입니다.당신의 제보가 뉴스로 만들어집니다.SBS Biz는 여러분의 제보를 기다리고 있습니다.홈페이지 = https://url.kr/9pghjn', NULL, 'SBS Biz', 'https://n.news.naver.com/mnews/article/374/0000496098', 'https://imgnews.pstatic.net/image/374/2026/03/05/0000496098_001_20260305173307726.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-05 17:03:12', 0, true, '2026-03-09 05:46:11.674488') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (613, '2년 연속 배당 못한 현대해상, ‘비과세 감액배당’ 추진', '685억원 이익잉여금으로 전입최근 2년 연속 배당을 못한 현대해상이 배당소득세를 납부하지 않아도 되는 ‘비과세 감액배당’을 추진한다.5일 보험업계에 따르면, 현대해상은 20일 주주총회를 열고 작년 말 기준 자본준비금 1132억원 중 685억원을 이익잉여금으로 전입하는 안건을 상정해 의결할 예정이다. 상법상 회사가 적립한 자본준비금·이익준비금 총액이 자본금의 1.5배를 초과하면 초과 금액을 감액할 수 있다. 이익잉여금으로 전입된 685억원은 향후 법인세법상 비과세 배당 재원으로 활용할 수 있다.현대해상 사옥. /현대해상 제공일반 주주가 비과세 배당을 받으면 원천징수(세율 15.4%) 없이 배당금 전액을 수령하게 된다. 이자소득·배당소득 등 금융소득이 2000만원을 초과할 때 적용되는 금융소득 종합과세 산정에서도 제외된다. 반면 정몽윤 현대해상 회장 등 대주주는 올해 개정된 세법 시행령이 시행되면서 배당소득세를 내야 한다.현대해상처럼 자본준비금이 감액되면 배당 가능 이익이 늘어나는 효과도 있다. 배당가능 이익은 순자산에서 자본금과 법정준비금(자본준비금·이익준비금 합계), 미실현 이익 등을 뺀 것으로 계산된다. 다만 내년부터 배당을 재개할지는 미지수다. 배당가능 이익이 마이너스가 되면 이익잉여금으로 전입한 685억원을 별도 배당 재원으로 사용하지 못하고 이익잉여금으로 남겨놔야 한다.보험업계에서는 순이익이 늘어도 배당가능 이익이 줄어드는 원인으로 해약환급금준비금 제도를 꼽는다. 해약환급금준비금은 보험 계약 해지 시 고객에게 지급할 환급금에 대비해 미리 쌓아두는 금액으로, 배당가능 이익을 줄이는 법정준비금 중 하나다. 신계약이 늘어날수록 적립해야 할 금액도 늘어난다. 작년 말 기준 현대해상 배당가능 이익은 마이너스 1조원으로 추정된다.', NULL, '조선비즈', 'https://n.news.naver.com/mnews/article/366/0001146051', 'https://imgnews.pstatic.net/image/366/2026/03/05/0001146051_001_20260305133810973.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-05 13:38:10', 0, true, '2026-03-09 05:46:11.674488') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (614, '보험사 CEO “보험사기 설계사 퇴출해야”…당국에 입법 지원 요청[사기공화국의 민낯]', '국회 내 보험사기 법안 처리 전무 상태사기 설계사 퇴출, 명단 공개 법안 멈춰2024년 1조원대 적발…역대 최대 규모과잉청구·보험사기로 보험사 실적 악화보험사 최고경영자(CEO)들이 보험사기를 억제할 수 있는 법적·제도적 장치 마련을 강조하고 나섰다. 사진은 지난달 26일 서울 광화문 생명보험교육문화센터에서 열린 ‘금융감독원장-보험회사 최고경영자(CEO) 간담회’ 모습.  박성준 기자보험사 최고경영자(CEO)들이 보험사기를 억제할 수 있는 법적·제도적 장치 마련을 강조하고 나섰다. 보험사기 적발 규모는 2024년 1조원을 넘어서며 역대 최대 규모를 기록했다. 그럼에도 보험사기 가담 설계사 퇴출, 사기범 명단 공개 등의 법안이 발의됐지만, 22대 국회 출범 이후 통과된 건은 아직 한 건도 없다. 지난해 보험사 실적 악화까지 겹치면서, 보험업계가 입법 지원을 직접 요청하고 나선 것이다.5일 보험업계에 따르면 지난달 26일 이찬진 금융감독원장과 주요 보험사 CEO들이 만난 간담회 자리에서 보험업계는 보험사기 근절을 위한 적극적인 지원을 요청했다. 현재 금감원·경찰이 운영 중인 실손의료보험 보험사기 집중신고기간의 연장과 보험사기 근절 관련 법 개정 추진 사항에 관한 관심을 촉구했다. 범죄 이력 모집종사자 퇴출과 재진입 차단, 사기범 명단 공개 시행 등 업계 공통 요구사항과 관련해 금융당국이 관심을 가져달라는 취지다. 이와 함께 실손보험 청구 전산화 참여 의무화, 미참여 의료기관 제재, 블랙컨슈머 방지를 위한 금융소비자보호법(금소법) 개정 검토 등 법적·제도적 장치 마련 요구도 나왔다.이처럼 보험사기 관련 업계 요구가 확대된 데에는 보험사기 규모가 갈수록 커지는데도 법과 제도적 개선이 빠르게 이뤄지지 않고 있기 때문이다. 국회 의안정보시스템에 따르면 22대 국회 출범 이후 발의된 보험 관련 법안 19건 중 입법 문턱을 넘은 건은 한 건도 없다. 보험사기와 직접 관련된 법안만 해도 보험업법·보험사기방지특별법·자동차관리법에 걸쳐 다수가 계류 중이다.현행법상 보험사기 설계사 제재는 재판(최소 3년)과 청문(2년) 등 최종 확정까지 5년 이상 소요된다. 그사이 해당 설계사는 다른 보험사로 이직해 영업을 이어갈 수 있고, 사기 수법이 전파되는 경로가 된다.이를 해결하기 위해 법원 판결로 범죄사실이 확인된 설계사의 청문 절차를 생략하고 즉시 등록을 취소하는 보험업법 개정안이 유영하 의원(2024년 8월)에 의해 처음 발의됐고, 같은 취지의 법안이 잇따라 발의됐다. 법인보험대리점(GA)에 대한 제재를 강화하는 법안도 김상훈 의원을 중심으로 발의됐다. 하지만 법안들 모두 현재 국회 내 표류 중이다.편취액이 1억원 이상, 조직 보험사기를 실행한 자의 명단을 공개하는 보험사기방지특별법 개정안(강준현 의원 대표발의)도 소위 회부 후 논의가 진전되지 않고 있다. 사기범 명단공개는 이전 국회에서 정무위원회를 통과했으나, 기본권 침해 우려 등을 이유로 삭제된 바 있다.지난해부터 양형 기준이 개정돼 의료인·설계사 등 전문직 종사자의 보험사기 가담이 특별 가중요소로 반영됐지만, 행정적으로 가담자를 시장에서 신속히 퇴출하는 장치는 여전히 빈약하다는 것이 업계의 지적이다. 보험업계 관계자는 “형사처벌까지 가야 계도가 통하는데, 지금은 솜방망이 수준이다 보니 일반 소비자들도 보험사기가 범죄 인식 자체가 낮다”고 말했다.그러는 새 보험사기는 2024년 기준 적발 규모 1조1502억원, 인원 10만9000명으로 역대 최고치를 기록했다. 실제 보험사기 규모는 연간 약 8조원, 국민 한 사람이 지는 사회적 부담은 16만원에 육박하는 것으로 추정된다. 개인 중심의 생계형 사기에서 병원·브로커·설계사가 역할을 분담하는 조직형 사기로 빠르게 변모하는 추세다.이런 변화는 보험사 실적에도 적지 않은 영향을 미쳤을 것으로 보인다. 지난해 국내 5대(삼성화재·DB손해보험·현대해상·KB손해보험·메리츠화재) 손해보험사의 합산 당기순이익은 전년 대비 약 11.5% 감소했다. 자동차보험과 함께 장기보험의 실적 악화가 보험사 경영에 하방 압력으로 작용 중인데, 장기보험 예실차 손실 확대 배경에도 과잉청구와 보험사기가 자리 잡고 있다는 게 업계 시각이다.해외는 법적·행정적 대응 체계를 정비해 보험사기 예방에 나서고 있다. 독일은 형법에 보험사기죄를 별도 죄목으로 명시해 일반 사기와 구별되는 엄격한 구성요건과 형량 체계를 갖추고 있다. 일본은 대형 GA에 대한 감독을 강화하고, 금융청이 업무개선명령·면허취소 등 강력한 행정처분을 신속하게 내릴 수 있도록 보험업법을 개정했다. 영국은 업계 공동 비영리기구인 보험사기조사국(IFB)을 통해 사기 데이터를 실시간 공유하고, 수사기관과 상시 공조 체계를 운용한다.국내 보험업계도 멈춰 선 입법의 조속한 추진, 정부합동 대응체계 구축과 공·민영보험 간 정보교류의 실질화 등을 공통 과제로 제시한다. 보험업계 관계자는 “정부의 합동 대응과 함께 법·제도적 미비점을 하나씩 보완해 나가야 한다”며 “보험사기가 반드시 적발된다는 인식이 퍼져야 시도 자체가 줄어들 것”이라고 말했다. 박성준 기자', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002608866', 'https://imgnews.pstatic.net/image/016/2026/03/05/0002608866_001_20260305113211342.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-05 11:32:11', 0, true, '2026-03-09 05:46:11.674488') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (615, '일교차 큰 ''간절기'', 봄버 재킷부터 기능성 이너까지', '[패션&뷰티] 29CM 봄버 재킷 거래액 526%↑키즈 아우터·기능성 이너웨어 수요도 확대왼쪽은 튜드먼트 워시드 봄버 레더 재킷, 오른쪽은 반로에 더블 스냅 버튼 페이크 레더 재킷.(29cm 제공)(서울=뉴스1) 최소망 기자 = 이번 주말 낮 기온은 20도 안팎까지 오르며 포근하지만 아침저녁으로는 쌀쌀할 것으로 예상돼 ''간절기 패션''에 대한 고민도 깊어지고 있다. 두꺼운 겨울 외투를 벗어야 할 시점이지만, 얇은 차림만으로는 일교차를 버티기 어렵다.패션업계는 이 같은 계절적 특성에 맞춰 ''가볍지만 실용적인'' 아이템을 잇달아 선보이고 있다.거래액 6배 뛴 봄버 재킷…트렌드와 실용성 동시 부상21일 업계에 따르면 올봄 간절기 아우터로 ''봄버 재킷''이 뚜렷한 성장세를 보이고 있다.무신사(458860)가 전개하는 29CM는 1월 26일~2월 8일(최근 2주간) 거래액 데이터를 분석한 결과, 봄버 재킷 관련 상품 거래액은 전년 동기 대비 526% 이상 증가했다. 같은 기간 29CM 앱 내 ''봄버 재킷'' 검색량도 전월 대비 2배 이상 늘었다.봄버 재킷은 제1차 세계대전 당시 미 공군 조종사들의 체온 유지를 위해 제작된 허리길이의 항공 점퍼에서 유래한 아이템이다. 활동성과 보온성을 동시에 고려한 구조가 특징으로, 기능성 아우터에서 출발해 현재는 대표적인 간절기 패션 아이템으로 자리 잡았다.최근 사회관계망서비스(SNS)를 중심으로 ''2026년은 새로운 2016년''(2026 is new 2016) 트렌드가 확산되며 2016년 감성을 재해석한 스타일이 주목받고 있다. 과거 나일론 소재 중심이었다면, 올해는 가죽과 스웨이드 등 고급 소재를 적용한 제품이 부상했다. 실제로 최근 2주간 ''가죽 재킷''과 ''스웨이드’ 카테고리 거래액은 전년 동기 대비 각각 30%, 77% 이상 증가했다.29CM는 2월 19일부터 28일까지 ''29 스프링 시그널'' 기획전을 열고 26SS 봄 신상품을 선보인다. 최대 3만 5000원 할인과 4만 원 할인 쿠폰을 동시에 제공한다.29CM 관계자는 "10년 전 패션업계를 휩쓸었던 봄버 재킷이 재조명되며 다양한 소재와 디테일을 적용한 신제품이 출시되고 있다"며 "강추위가 지나고 가벼운 아우터를 찾는 시기에 보온성과 스타일을 동시에 만족시키는 선택지가 될 것"이라고 말했다.활동성 강화한 키즈 아우터…실용성 강조하며 다채로운 컬러간절기 실용성을 강조하는 흐름은 키즈 라인에서도 나타난다. F&F(383220)가 전개하는 ''디스커버리'' 키즈는 26SS 시즌을 맞아 다채로운 컬러와 기능성을 강조한 봄 화보를 공개했다.대표 아이템인 ''하이넥 우븐 자켓''은 은은한 광택 소재에 루즈한 오버핏을 적용했으며, 등판 벤틸레이션 디테일을 더해 통기성을 강화했다. 소매와 밑단에는 밴드와 벨크로 디테일을 적용해 사이즈 조절과 활동성을 높였다.여아용 하이넥 우븐 자켓은 밑단 스트링을 통해 실루엣 조절이 가능하며, 우븐 스커트와 셋업으로 연출할 수 있다. ''키즈 레이어드 긴팔 티셔츠''는 면·폴리 혼방 소재를 사용해 땀을 빠르게 흡수·건조시키는 기능을 갖췄고, ''키즈 카라 맨투맨''은 세미 오버핏오버핏 실루엣과 볼륨 자수 그래픽을 적용했다.디스커버리 키즈가 최근다채로운 컬러 구성에 기능성까지 갖춘 26SS 시즌 봄 화보 공개했다.(디스커버리 제공)얇고 따뜻한 기능성 이너웨어 제안도…안정적인 체온 유지아우터 선택만큼 중요한 것은 체온을 안정적으로 유지해 줄 이너웨어다. BYC(001460)는 환절기를 겨냥한 기능성 웨어 ''보디히트기모긴팔티''를 선보였다.보디히트기모긴팔티는 얇은 기능성 소재로 제작해 보온성과 활동성을 동시에 갖췄다. 소프트한 기모 소재를 적용해 보온 효과를 높였고, 신축성이 뛰어난 원사를 사용해 편안한 착용감을 제공한다.라운드넥의 베이직한 디자인으로 단독 착용은 물론, 봄버 재킷이나 경량 자켓 안에 레이어드하기에도 부담이 적다. 블랙, 그레이, 와인 등 3가지 컬러로 구성됐으며 BYC 온오프라인 판매처에서 구매 가능하다.봄버 재킷처럼 기능성에서 출발해 패션 아이템으로 자리 잡은 아우터부터, 통기성과 활동성을 강화한 키즈 자켓, 체온 유지를 돕는 얇은 이너웨어까지. 올봄 간절기 스타일링의 키워드는 ''레이어드''와 ''실용성''이다. 일교차가 큰 계절일수록 겉과 속을 전략적으로 갖추는 선택이 필요하다.BYC가 보디히트 기모긴팔티를 선보였다(BYC 제공)', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008784371', 'https://imgnews.pstatic.net/image/421/2026/02/21/0008784371_001_20260221075023330.jpg?type=w800', 'NEWS_CONSUMER', NULL, '2026-02-21 07:50:00', 0, true, '2026-03-09 05:46:31.220530') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (616, '[서울데이터랩]삼화페인트 30.00% 상한가 금일 증시 상승률 1위로 마감', '10일 오후 15시 35분 삼화페인트(000390)가 등락률 +30.00%로 상승률 1위로 마감했다. 삼화페인트는 장 중 8,503,597주가 거래되었으며 주가는 공모가 대비 12,350원에 마감했다.한편 삼화페인트의 PER은 41.3으로 다소 높은 평가를 받고 있으며, ROE는 4.87%로 수익성 면에서는 다소 아쉬운 수준에 머물렀다.이어 상승률 2위 신대양제지(016590)는 주가가 26.98% 폭등하며 종가 16,000원에 상승 마감했다. 상승률 3위 대우건설(047040)의 주가는 7,060원으로 22.36% 폭등하며 주목받았다. 상승률 4위 한온시스템(018880)은 17.94% 급등하며 4,570원에 마감했다. 상승률 5위 CJ대한통운(000120)은 16.74%의 상승세를 보이며 종가 136,700원에 마감했다.6위 한섬(020000)은 종가 21,200원으로 16.16% 상승 마감했다. 7위 롯데쇼핑(023530)은 종가 113,500원으로 14.88% 상승 마감했다. 8위 현대홈쇼핑(057050)은 종가 67,000원으로 14.73% 상승 마감했다. 9위 한화손해보험(000370)은 종가 7,290원으로 14.26% 상승 마감했다. 10위 BYC(001460)는 종가 54,100원으로 13.66% 상승 마감했다.이밖에도 대신증권(003540) ▲13.42%, 아세아제지(002310) ▲12.64%, 한화생명(088350) ▲11.97%, 한국앤컴퍼니(000240) ▲11.63%, 세원정공(021820) ▲11.63%, 이마트(139480) ▲9.50%, 금호건설(002990) ▲9.33%, 한진(002320) ▲9.27%, 계양전기(012200) ▲9.24%, 우진플라임(049800) ▲9.20% 등을 기록하며 금일 증시를 상승으로 마감했다.전문가는 “삼화페인트의 이번 상한가 기록은 시장의 긍정적인 반응을 반영한 결과로 보인다. 높은 거래량과 함께 주가가 급등한 것은 투자자들의 관심이 집중되었음을 의미한다”고 평가했다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003616594', 'https://imgnews.pstatic.net/image/081/2026/02/10/0003616594_001_20260210154712621.png?type=w800', 'NEWS_CONSUMER', NULL, '2026-02-10 15:47:12', 0, true, '2026-03-09 05:46:31.220530') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (617, 'BYC, 유아복 ''코코모메'' 설 선물용 제품 출시', '가볍고 편안한 착용감 강조byc의 코코모메.(서울=뉴스1) 최소망 기자 = BYC(001460)의 키즈 패션 브랜드 코코모메가 설 명절을 맞아 ''코코모메 패딩점퍼''와 ''코코모메 뽀글이 카라집업''을 선보인다고 10일 밝혔다.신제품은 아이들이 좋아하는 일러스트를 적용해 가볍고 편안한 착용감을 강조했다.''코코모메 패딩점퍼''는 루즈핏 디자인으로 두꺼운 이너와 함께 착용하기 좋고, 보온성을 높인 넥 디자인과 지퍼 여밈, 포켓 디테일을 더했다. ''코코모메 뽀글이 카라집업''은 오버핏 실루엣과 뽀글이 소재를 적용해 겨울철 다양한 코디가 가능하며 조거팬츠와 세트 연출도 가능하다.제품은 BYC 직영점과 온라인몰 등 온·오프라인 판매처에서 구매할 수 있다.한편 코코모메는 ''아이''를 뜻하는 ''coco''와 ''시간, 순간''을 의미하는 ''moment''의 합성어로, 아이의 성장 순간을 함께하는 BYC의 키즈 패션 브랜드다.', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008764442', 'https://imgnews.pstatic.net/image/421/2026/02/10/0008764442_001_20260210092023352.jpg?type=w800', 'NEWS_CONSUMER', NULL, '2026-02-10 09:20:08', 0, true, '2026-03-09 05:46:31.220530') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (618, '[애프터마켓 브리핑] 한화솔루션, 실적 턴어라운드 기대감으로 급등', '■ 머니쇼+ ''애프터마켓 브리핑'' - 김유민애프터마켓 브리핑입니다.오늘(6일) 우리 시장은 어제에 이어 오늘까지 지수가 밀리면서 불안감이 퍼졌습니다.오늘 코스피는 1.44% 내린 5,089포인트로 마감했고, 코스닥은 2.49% 하락하며 1,080선에 거래 마쳤습니다.그래도 우리 시장 매도 사이드카 발동됐음에도 빠르게 회복세 보였는데, 애프터마켓 흐름은 어떤지 시세부터 체크해 보겠습니다.시가총액 1위에서 5위 종목들부터 보겠습니다.미국 빅테크 케펙스 쇼크로 반도체 투톱 모두 정규장에서부터 약세를 보이고 있습니다.삼성전자는 정규장에서 158,600원에 마쳤는데, 현재가는 158,100원입니다.SK하이닉스는 장중 한때 80만 원 아래까지 내려갔는데 장 후반에 낙폭을 줄였습니다.정규장 0.36% 하락률로 마감했는데, 현재가 836,000원에 거래되고 있습니다.이어서 현대차, 외국인의 매도 공세와 미국 관세 리스크로 내림세입니다.현재가는 468,000원입니다.LG에너지솔루션은 장 마감 후 캐나다 스텔란티스 JV 지분을 인수했다는 소식 나왔죠.현재 385,500원에 거래되고 있습니다.다음으로 상승률 1위에서 5위 종목들 보겠습니다.하락장에서도 크게 오르고 있는 스피어는 현재 상승률 1위로, 현재가 37,350원입니다.오늘도 스페이스X 관련주 강세인 가운데, 스피어가 가장 탄력적이었죠.그리고 한화솔루션, 지난 4분기 실적은 부진했지만 태양광 사업이 가시화되면서 오름세입니다.유진증권은 5만 원의 목표가 제시했습니다.현재 한화솔루션은 상승률 2위로 42,200원에 거래되고 있습니다.그리고 아난티, 애프터마켓에서도 상승률 큽니다.미국이 대북 인도적 지원을 재개한다는 기대감에 관련주들 함께 올라갑니다.현재 상승률 5위로 9,020원에 거래되고 있습니다.그리고 카카오페이, 현재 순위권에는 없지만, 카카오페이 장 마감 직후 실적을 발표했습니다.처음으로 연간 영업이익 흑자를 기록하며, 애프터마켓에서만 4% 넘는 상승 탄력을 키웠습니다.이어서 하락률 1~5위 종목들 보겠습니다.어제(5일) 급등세 보였던 BYC와 일신방직, 오늘은 빠지는 움직임입니다.현재 BYC는 48,900원, 일신방직은 14,210원에 거래되고 있습니다.SK텔레콤도 어제 실적 발표했는데, 오늘도 하락세입니다.또 현재 하락률 순위권에는 안 보이는데요.HD현대일렉트릭, 장 마감 직전에 실적을 발표했죠.변압기 호황으로 사상 최대 4분기 실적을 내놓으면서 낙폭 줄였습니다.다음으로 거래량 1~5위 종목들 살펴보겠습니다.한화솔루션, 상승률에 이어 거래량도 좋습니다.현재 거래량 1위로, 42,200원에 거래되고 있습니다.정규장에서 15.38% 오르며 마쳤는데, 현재 15.93% 상승률 보이며 상승 탄력 키워갑니다.그리고 미래에셋벤처투자, 스페이스X 섹터 관련주들 전반적으로 강했는데 스피어와 함께 올라갑니다.이렇게 애프터마켓 흐름부터 특징주까지 살펴봤는데요.오늘 밤 열리는 뉴욕증시는 안자은 캐스터와 함께 대비해 보시죠.지금까지 애프터마켓 브리핑이었습니다.당신의 제보가 뉴스로 만들어집니다.SBS Biz는 여러분의 제보를 기다리고 있습니다.홈페이지 = https://url.kr/9pghjn', NULL, 'SBS Biz', 'https://n.news.naver.com/mnews/article/374/0000491293', 'https://imgnews.pstatic.net/image/374/2026/02/06/0000491293_001_20260206164108957.jpg?type=w800', 'NEWS_CONSUMER', NULL, '2026-02-06 16:41:08', 0, true, '2026-03-09 05:46:31.220530') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (619, '[서울데이터랩]2월 5일 코스피 주요 종목 마감시황', '2월 5일 한국거래소에 따르면, HD현대에너지솔루션(322000)은 전 거래일 대비 16.17% 상승한 81,900원에 거래를 마감하며 금일 코스피 상승률 1위를 차지했다. 일신방직(003200)은 16.11% 상승한 16,000원에 거래를 마치며 뒤를 이었다. BYC(001460)는 13.99% 상승한 55,800원, 현대약품(004310)은 11.69% 상승한 13,090원, GS피앤엘(499790)은 10.14% 상승한 60,800원에 각각 거래를 종료했다.이수스페셜티케미컬은 전 거래일 대비 13.58% 하락한 105,600원에 거래를 마감하며 금일 코스피 하락률 1위를 기록했다. 동양고속은 13.02% 하락한 60,800원에 거래를 마쳤다. 대성산업은 12.81% 하락한 9,800원, 롯데케미칼은 11.48% 하락한 75,600원, 세아베스틸지주는 11.07% 하락한 80,300원에 각각 거래를 종료했다.시가총액 상위 종목 중 상승하거나 보합세를 기록한 종목은 없었다. 삼성전자는 38,290,228주가 거래되며 5.80%의 하락세를 기록했다. SK하이닉스는 5,446,432주의 거래량을 기록하며 6.44% 하락했다. 현대차는 1,653,286주가 거래되며 3.08% 하락했다. 삼성전자우는 4,237,458주가 거래되며 5.81% 하락했다. LG에너지솔루션은 거래량 338,536주로, 1.86% 하락 마감했다. 삼성바이오로직스는 59,550주가 거래되며 3.35%의 하락세를 보였다. SK스퀘어는 1,076,988주가 거래되며 6.15% 하락 마감했다. 한화에어로스페이스는 333,625주가 거래되며 7.33% 하락했다. 기아는 1,586,898주가 거래되어 0.38% 하락했다. 두산에너빌리티는 7,586,811주가 거래되며 6.11% 하락했다.금일 코스피 주요 종목들은 전반적으로 하락세를 보였다. 이러한 시장 상황에서는 투자자들이 시장의 불확실성을 주의 깊게 살펴보며, 리스크 관리에 유의할 필요가 있다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003614954', 'https://imgnews.pstatic.net/image/081/2026/02/05/0003614954_001_20260205162116725.png?type=w800', 'NEWS_CONSUMER', NULL, '2026-02-05 16:21:16', 0, true, '2026-03-09 05:46:31.220530') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (767, '[특징주]‘MLCC 가격 인상 기대’ 삼화콘덴서 17%대↑', '삼화콘덴서가 적층세라믹커패시터(MLCC) 가격 인상 기대에 상승세를 보이고 있다.24일 오전 9시20분 삼화콘덴서는 전 거래일보다 17.02%(9700원) 오른 6만6700원에 거래되고 있다.iM증권은 전날 보고서에서 삼화콘덴서의 목표주가를 기존 3만4500원에서 5만1000원으로 상향했다. 투자의견은 매수를 유지했다.이상헌 iM증권 연구원은 "올해 삼화콘덴서의 예상 연결 매출은 3230억원, 영업이익은 203억원으로 예상되면서 실적 개선이 가시화될 전망"이라며 "MLCC 가격 인상 기대와 함께 전력 변환용 커패시터(DCLC) 매출 성장으로 수익성이 회복될 것으로 예상되기 때문"이라고 말했다.', NULL, '아시아경제', 'https://n.news.naver.com/mnews/article/277/0005724892', 'https://imgnews.pstatic.net/image/277/2026/02/24/0005724892_001_20260224092224173.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-02-24 09:21:33', 0, true, '2026-03-09 05:52:50.425799') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (620, '[서울데이터랩]HD현대에너지솔루션 16.17% 급등 금일 증시 상승률 1위로 마감', '5일 오후 15시 35분 HD현대에너지솔루션(322000)이 등락률 +16.17%로 상승률 1위로 마감했다. HD현대에너지솔루션은 장 중 5,291,061주가 거래되었으며 주가는 전 거래일 대비 11,400원 오른 81,900원에 마감했다.한편 HD현대에너지솔루션의 PER은 29.86으로 기업의 수익성 대비 현재 주가가 상대적으로 높다고 평가될 수 있으며, ROE는 0.03%로 나타나 주주 자본의 수익성이 낮은 수준임을 보여준다.이어 상승률 2위 일신방직(003200)은 주가가 16.11% 급등하며 종가 16,000원에 상승 마감했다. 상승률 3위 BYC(001460)의 주가는 55,800원으로 13.99% 급등하며 양호한 모습을 보였다. 상승률 4위 현대약품(004310)은 11.69% 상승하며 13,090원에 마감했다. 상승률 5위 GS피앤엘(499790)은 10.14%의 상승세를 타고 종가 60,800원에 마감했다.6위 대한제강(084010)은 종가 12,450원으로 10.08% 상승 마감했다. 7위 넥센타이어(002350)는 종가 8,820원으로 9.70% 상승 마감했다. 8위 까뮤이앤씨(013700)는 종가 1,470원으로 9.54% 상승 마감했다. 9위 이마트(139480)는 종가 103,600원으로 9.51% 상승 마감했다. 10위 아이에스동서(010780)는 종가 27,100원으로 9.49% 상승 마감했다.이밖에도 SGC에너지(005090) ▲9.04%, 휴비스(079980) ▲8.86%, 대동(000490) ▲8.85%, 한전산업(130660) ▲8.82%, 한온시스템(018880) ▲8.19%, 자이에스앤디(317400) ▲7.68%, 신성이엔지(011930) ▲7.45%, 카카오뱅크(323410) ▲7.40%, 우진플라임(049800) ▲7.07%, SG세계물산(004060) ▲6.97% 등을 기록하며 금일 증시를 상승으로 마감했다.전문가는 “HD현대에너지솔루션은 에너지 솔루션 분야에서의 지속적인 기술 개발과 시장 확장으로 투자자들의 기대감을 높이고 있다”며 “최근의 상승세는 기업의 성장 가능성을 반영한 것으로 보인다”고 전했다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003614952', 'https://imgnews.pstatic.net/image/081/2026/02/05/0003614952_001_20260205162109951.png?type=w800', 'NEWS_CONSUMER', NULL, '2026-02-05 16:21:09', 0, true, '2026-03-09 05:46:31.220530') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (621, '리복, 2026 트렌드 ‘컬러 블로킹’ 반영한 간절기 아우터 공개 外 [유통소식]', 'LF가 전개하는 글로벌 스포츠 브랜드 리복은 2026년 봄여름(SS26) 시즌을 맞아 올해의 패션 트렌드로 떠오른 ‘컬러 블로킹(Color Blocking)’을 반영한 간절기 아우터 신제품을 공개했다. 신성통상의 패션·라이프스타일 플랫폼 굿웨어몰이 16일부터 20일까지 5일간 새해맞이 프로모션 ‘해피굿이어 팸데이’를 진행한다. BYC가 추운 겨울에도 편안하게 착용할 수 있는 실용적인 패션 아이템 ‘보디히트 올데이기모후드’를 선보인다.◆ 리복, 2026 트렌드 ‘컬러 블로킹’ 반영한 간절기 아우터 공개LF가 전개하는 글로벌 스포츠 브랜드 리복은 2026년 봄여름(SS26) 시즌을 맞아 올해의 패션 트렌드로 떠오른 ‘컬러 블로킹(Color Blocking)’을 반영한 간절기 아우터 신제품을 공개했다.2026년 봄여름 시즌은 색의 표현이 한층 자유롭고 대담해지며, 컬러 자체가 개성을 드러내는 핵심 요소로 작용하며 단일 원색부터 과감한 블로킹까지 ‘색을 즐기는’ 흐름이 글로벌 패션 브랜드의 런웨이 전반에서 나타났다. 이러한 트렌드는 스포츠웨어와 애슬레저, 라이프스타일 패션 전반으로도 확산되고 있다.리복은 이러한 컬러 트렌드를 반영해 기존 아이코닉 아이템에 새로운 시선과 감각을 더했다는 의미를 담은 2026 봄여름 시즌 ''LEGEND RE:IMAGINED'' 캠페인 화보를 공개했다.이번 시즌에는 리복의 베스트 셀러 바람막이 ''레전드 윈드 브레이커''를 디자인 업그레이드해 선보이고 간절기용 ''레전드 트랙 패딩 재킷''과 스포티한 컬러 블록 트렌드를 반영한 ''컬러 블록 패딩 재킷''을 새롭게 출시했다.리복은 활동성과 스타일을 동시에 만족시키는 간절기 아우터 라인업을 강화했다.레전드 윈드브레이커는 2024년 2월 첫 출시 후 무신사를 비롯한 주요 온오프라인 채널에서 연이어 완판을 기록하며 리복을 대표하는 바람막이 아이템으로 자리매김한 베스트셀러다. 2025년 1월 재출시 이후 무신사 내 연간 판매량이 전년 대비 140% 증가하며 전 채널 완판에 힘입어 2차 리오더까지 진행됐다.인기의 핵심 요인은 강렬한 컬러 배색이다. 리복의 브랜드 아이덴티티를 상징하는 레드와 블루 컬러 포인트, 아카이브에서 영감을 받은 시그니처 배색 디테일이 특징이다.이번 시즌에는 스포티한 컬러 블록과 파이핑 디테일을 통해 레트로 무드를 현대적으로 재해석했다. 넥 라인부터 자연스럽게 이어지는 다이내믹한 절개 라인을 더해 한층 세련된 실루엣으로 업그레이드했다. 전체 메쉬 안감을적용해 스포츠 활동 시 쾌적한 착용감을 제공하며 일상적인 데일리 룩으로도 활용도를 높였다.길어진 겨울과 큰 일교차를 반영해 윈드브레이커 디자인에 가벼운 패딩 충전재를 적용한 ''레전드 트랙 패딩 재킷''과 스포티한 컬러 블록 트렌드를 반영한 ''컬러 블록 패딩 재킷''을 처음으로 선보인다.리복 관계자는 "2026년 봄여름 시즌을 관통하는 컬러 블로킹 트렌드는 강렬한 색 조합을 통해 개성과 에너지를 드러내는 흐름으로 스포츠와 애슬레저 패션 전반으로 확산되고 있다"며 "리복은 브랜드 헤리티지를 기반으로 한 스포티한 컬러 감각을 현대적으로 재해석해 활동성과 스타일 모두를 만족시키는 라인업을 탄탄히 구축해 갈 것"이라고 말했다.◆ 신성통상 굿웨어몰, 새해맞이 ‘해피굿이어 팸데이’ 개최신성통상의 패션·라이프스타일 플랫폼 굿웨어몰이 16일부터 20일까지 5일간 새해맞이 프로모션 ‘해피굿이어 팸데이’를 진행한다.매일 다른 브랜드 특가와 전 상품 할인 쿠폰을 동시에 이용할 수 있으며, 고객이 선택한 베스트 아이템 큐레이션과 새해 쇼핑 가이드도 함께 제공한다.굿웨어몰은 행사 시작과 동시에 사용 가능한 팸데이 전용 장바구니 쿠폰 3종을 제공해, 첫 쇼핑부터 실질적인 혜택을 받을 수 있도록 했다. 구체적으로 5만 원 이상 구매 시 5000원, 7만 원 이상 구매 시 9000원, 10만 원 이상 구매 시 1만5000원이 각각 할인된다. 여기에 16일과 20일 오전 8~9시에는 6만 원 이상 구매 시 1만5000원이 할인되는 타임 쿠폰을 추가 제공한다.일자별 브랜드 프로모션은 캐주얼데이, 맨즈데이, 탑텐데이, 셀렉션데이로 나뉘어 순차 진행되며, 마지막 날인 20일에는 전 브랜드 통합 프로모션이 열린다. 전 브랜드를 대상으로 한 ''오늘의 특가'' 상품도 매일 선보인다.고객 구매 데이터를 기반으로 선정한 베스트 아이템 큐레이션도 제공한다. MD 추천 상품을 중심으로 방한 아이템, 아우터, 상·하의, 세트 상품부터 키즈·스포츠·잡화·라이프 카테고리까지 포함해 새해 쇼핑 가이드 역할을 한다.고객 참여형 혜택도 제공한다. 행사 기간 중 1회 사용 가능한 쇼핑 지원금으로 굿포인트 800포인트가 지급되며, 출석 이벤트 참여 시 하루 200포인트, 5일 전체 출석 시 추가 200포인트를 받아 최대 1,200포인트 적립이 가능하다. 지급된 포인트는 행사 종료 시 소멸된다.굿웨어몰 관계자는 "매일 입는 옷을 가장 중요하게 생각하는 고객들을 위해, 당장 필요한 옷부터 오래 입을 수 있는 옷까지 좋은 혜택으로 부담 없이 선택할 수 있도록 준비했다"며 "일자별로 전환되는 브랜드 특가와 시작과 동시에 사용 가능한 쿠폰으로 새해 첫 쇼핑에 실질적인 도움을 드리고자 한다"고 말했다.◆ 코스맥스바이오, 9시간 지속성 제형 ''타임핏 비타'' 개발코스맥스바이오는 지속성 비타민C 제형인 ''타임핏 비타(TimeFit-vita™)를 개발했다고 16일 밝혔다.지속성 제형은 식품의약품안전처 신규 고시 제형으로 일반 제형 대비 천천히 녹아 오랜시간 기능성분을 방출하는 특징이 있다. 기존에는 서방정 형태로 의약품에만 적용할 수 있었지만 2024년부터 건기식에도 적용할 수 있게 됐다.타임핏 비타는 코스맥스바이오가 독자 개발한 지속성 제형이다. 셀룰로오스 유래 친수성 고분자 망상구조를 활용한 서방형 정제 기술을 적용했다. 정제가 위액과 만나면 부드럽게 팽창하면서 보호 겔 구조를 형성해 비타민C가 일정 속도로 용출되도록 설계됐다.타임핏 비타는 기본적으로 9시간동안 비타민C 600㎎을 방출할 수 있도록 설계했다. 비타민C는 혈중 일정 농도를 유지할 때 가장 효과적이지만 체내 저장이 어렵다. 특히 고용량 섭취 시 흡수율이 급격히 떨어지며, 흡수되지 못한 나머지는 몸 밖으로 배출되는 특성을 갖고 있다.코스맥스바이오는 이러한 특성을 고려해 비타민C 600㎎을 9시간 동안 분산 방출하는 구조로 최적 설계를 구현했다. 이는 기존에 권장되던 ‘분할 섭취’ 개념을 제형 기술로 구현한 것으로, 1회 섭취만으로도 장시간 혈중 농도를 유지하도록 도와준다. 아울러 고함량 비타민C 섭취 시 발생할 수 있는 속쓰림 등 위장관 부담을 최소화했으며, 공복 섭취 시에도 부담을 줄일 수 있도록 설계됐다.특히 타임핏 비타 기술은 자체 제형 설계를 기반으로 용출 시간과 용출률을 정밀하게 제어할 수 있어 기술 확장성이 높다.코스맥스바이오는 지속성 비타민C 기술을 시작으로, 향후 다양한 수용성 비타민에 지속 방출 제형 기술을 확대 적용할 계획이다.코스맥스바이오 관계자는 "이번 기술은 소비자 섭취 패턴과 영양 흡수 효율을 동시에 고려한 결과물"이라며 "앞으로도 제형 기술 혁신을 통해 건강기능식품의 새로운 기준을 제시해 나갈 것"이라고 말했다.◆ BYC, 보온성과 실용성 갖춘 ‘보디히트 올데이기모후드’ 선봬BYC가 추운 겨울에도 편안하게 착용할 수 있는 실용적인 패션 아이템 ‘보디히트 올데이기모후드’를 선보인다.‘보디히트 올데이기모후드’는 양면 피치 가공을 적용해 부드러운 촉감과 내구성을 강화했고, 가볍고 포근한 착용감을 제공한다. 중량 대비 부피감을 높여 가볍지만 보온성이 뛰어난 것이 특징이다.또한 클래식한 칼리지 프린트를 활용한 아트워크로 포인트를 더했고, 끈 조절이 가능한 후디 디자인을 적용해 찬바람을 효과적으로 차단한다. 양손 포켓 스타일로 실용성도 강화했다.BYC ‘보디히트 올데이기모후드’는 BYC 직영점과 BYC 쇼핑몰을 포함한 BYC 온·오프라인 판매처에서 확인 가능하다.BYC 관계자는 “올해 패션 트렌드는 유행보다 실용성을 최우선으로 하는 흐름이 이어질 것으로 보인다”며 “자신만의 스타일을 유지하면서도 다양하게 활용할 수 있는 이번 신제품으로 따뜻하고 편안한 겨울을 보내시길 바란다”고 전했다.◆ 스와치, 구겐하임 미술관과 협업 컬렉션 출시스위스 시계 브랜드 스와치가 세계적인 미술관 구겐하임과 협업한 컬렉션을 선보인다. 이번 컬렉션은 예술 작품을 감상하는 경험을 일상의 시간으로 확장한다는 콘셉트로, 구겐하임 뉴욕과 퍼기 구겐하임 컬렉션을 대표하는 명작에서 영감을 받아 탄생했다.파울 클레, 클로드 모네, 에드가 드가, 잭슨 폴록 등 시대를 초월한 네 명의 예술가의 작품 세계를 스와치만의 감각적인 언어로 풀어냈다.먼저 KLEE’S BAVARIAN DON GIOVANNI는 파울 클레의 ''The Bavarian Don Giovanni''(1919)에서 착안한 모델이다. 유머러스한 기하학적 형태와 상징적 모티프가 돋보이는 작품 세계를 현대적으로 재해석했다.작가의 자화상으로 해석되는 인물을 중심으로, 다이얼에는 클레 특유의 선과 컬러를 활용한 캐릭터를, 스트랩에는 여성들의 이름을 디자인 요소로 적용해 예술적 서사를 완성했다.클로드 모네의 작품에서 영감을 받은 모델은 ''The Palazzo Ducale, Seen from San Giorgio Maggiore''(1908)를 기반으로 디자인됐다. 스트랩에는 베니스 라군의 흐름을 표현한 패턴이 적용되었으며, 다이얼은 자외선 노출 시 선명한 오렌지 컬러로 변화해 빛에 따라 달라지는 베니스의 찬란한 아름다움을 감각적으로 담아냈다.DEGAS’S DANCERS는 에드가 드가의 ''Dancers in Green and Yellow''(1903)를 모티프로 한 모델이다. POLLOCK’S ALCHEMY는 잭슨 폴록의 대표작 ''Alchemy''(1947)에서 착안한 모델로, 물감을 흘리고 튀기는 폴록 특유의 실험적 기법에서 영감을 받아, 자유로운 표현성을 다이얼과 스트랩 전반에 담아냈다.이번 컬렉션은 미술관 속 작품을 단순히 재현하는 것을 넘어 예술의 감성과 스토리를 일상 속에서 경험할 수 있도록 제안하는 스와치만의 창의적인 아트 프로젝트다. 특히 이번 컬렉션은 스위스 시계 디자인의 정교함과 미술관 수준의 섬세한 표현력이 조화를 이룬 것이 특징이다.◆ 동국제약, 센텔리안24 ‘마데카 크림 하이드라 카밍’ 출시동국제약이 더마코스메틱 브랜드 센텔리안24의 신제품 ''마데카 크림 하이드라 카밍''을 출시했다. 이번 신제품은 계절별 열 자극으로 인한 피부 장벽 손상과 피지·모공 문제 완화를 목표로 개발됐다.주요 성분은 동국제약이 개발한 ''하이드라-TECA™''로, 캡슐 형태로 안정화돼 있다.피부에 바를 때 캡슐이 터지며 성분이 전달되고, 피부 온도 32℃ 이상에서 작용하도록 설계됐다. 회사는 이를 통해 열 자극으로 인한 피부 반응 완화 효과를 기대하고 있다.제품에는 병풀 유래 성분, 탄력 관련 성분, 카페인, 녹차, 호박추출물이 포함됐다. 제형은 끈적임이 적은 크림 타입이다.동국제약 센텔리안24 담당자는 “이번 신제품은 일상 속 다양한 열 자극 환경에서 피부 컨디션을 케어하는 데 초점을 둔 제품”이라며, “’마데카 크림 하이드라 카밍’과 함께 수분·진정·탄력 등 복합적인 피부 고민을 스마트하게 관리하시길 바란다”고 말했다.◆  ''러닝 인구 1000만 시대''...프로스펙스, 러닝화 라인업 강화프로스펙스는 늘어나는 러닝 인구와 함께 러닝화 수요가 급증함에 따라 인피니트 러시, 스피드 러시2, 듀플렉스 GF 등 러닝화 라인업을 확대했다고 16일 밝혔다.먼저 ‘인피니트 러시’는 PEBA 폼 미드솔을 적용해 에너지 손실을 최소화하고, 확장된 카본 플레이트로 추진력을 극대화한 레이싱 전용 러닝화다. 넓은 전족부 설계로 고속 주행에서도 안정적인 착지와 주행이 가능해, 기록 단축을 목표로 하는 러너들에게 최적의 퍼포먼스를 제공한다고 업체 측은 전했다.‘스피드 러시2’는 업그레이드된 쿠셔닝과 경량성에 가성비까지 갖춰 입문자부터 레이스를 준비하는 러너까지 폭넓은게 착용할 수 있다. 부상 위험을 줄여주는 안정화 타입으로 출시된 ‘듀플렉스 GF’는 G-FRAME 구조로 과내전을 제어해 장시간 러닝에도 안정감을 제공한다.프로스펙스는 팝업스토어와 러닝 프로그램을 통해 러너들과의 접점을 확대하고 있다.프로스펙스 관계자는 "러닝이 일상화된 만큼 러너 개개인의 발에 맞는 제품 개발에 집중할 것"이라고 말했다.◆ 푸쉬레 홈웨어, 2026 첫 컬렉션 출시홈웨어 브랜드 푸쉬레(POUSIERÉ)가 2026년 첫 번째 컬렉션 ‘Afternoon Girl(오후소녀)’를 런칭했다고 16일 밝혔다.이번 컬렉션은 런칭 직후부터 꾸준히 이어진 고객들의 요청을 반영해 코튼 소재의 저지 스타일 셋업을 메인으로 구성했다. 스포츠웨어에서 주로 보이는 ‘저지(Jersey)’의 실루엣을 홈웨어의 문법으로 차분하게 풀었다.활동성을 강조한 브이넥 라인과 배색 스티치, 허리와 발목 밴딩 등 스포티한 디테일은 유지하되, 기능성 소재 대신 포근한 촉감의 와플 텍스처 원단을 사용하고, 드롭 숄더 스타일로 ''빌려 입은 듯''한 사랑스러움을 더하는 등 브랜드 고유의 페르소나를 투영해 활동성과 편안함 사이의 균형을 맞췄다.이 외에도 ▲도트 패턴과 레이스 디테일이 돋보이는 ‘캐시(CASSIE)’, ▲두 개의 하트가 포개어진 자수 패치를 적용한 ‘베티(BETTY)’ 등 각기 다른 매력의 홈웨어를 만나볼 수 있다.푸쉬레 이민미 크리에이티브 디렉터는 “아직 오지 않은 날들에 대한 조바심 대신, 고요하고 평화로운 단상들로 채우는 시작이 되셨으면 해서 오후의 볕처럼 부드러운 소재와 포근한 컬러들, 한층 더 느슨한 실루엣으로 따뜻하게 준비했다”고 전했다.푸쉬레는 지난 10월 첫 번째 컬렉션을 선보인 후, 독창적인 비주얼을 통해 ''푸쉬레 걸(PSR girl)''이라는 브랜드 페르소나를 대중에게 꾸준히 전달하고 있다. 푸쉬레 공식 인스타그램 계정은 런칭 3개월이 채 되지 않은 시점에 1만 명 이상을 달성하는 등 두터운 팬층을 기반으로 브랜드 입지를 탄탄히 다져나가고 있다.', NULL, '세계일보', 'https://n.news.naver.com/mnews/article/022/0004098176', 'https://imgnews.pstatic.net/image/022/2026/01/16/20260116511401_20260116162014780.jpg?type=w800', 'NEWS_CONSUMER', NULL, '2026-01-16 16:20:14', 0, true, '2026-03-09 05:46:31.220530') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (622, 'BYC, 보온성·실용성 갖춘 ''보디히트 올데이기모후드'' 선봬', '가볍고 포근한 착용감은 물론 보온성까지 갖춰BYC는 추운 겨울에도 편안하게 착용할 수 있는 실용적인 패션 아이템 ''보디히트 올데이기모후드''를 선보였다(BYC제공)(서울=뉴스1) 김진희 기자 = BYC(001460)는 추운 겨울에도 편안하게 착용할 수 있는 실용적인 패션 아이템 ''보디히트 올데이기모후드''를 선보였다고 16일 밝혔다.보디히트 올데이기모후드는 양면 피치 가공을 적용해 부드러운 촉감과 내구성을 강화했고 가볍고 포근한 착용감을 제공한다. 중량 대비 부피감을 높여 가볍지만 보온성이 뛰어난 것이 특징이다.클래식한 칼리지 프린트를 활용한 아트워크로 포인트를 더했고, 끈 조절이 가능한 후디 디자인을 적용해 찬바람을 효과적으로 차단한다. 양손 포켓 스타일로 실용성도 강화했다.BYC 보디히트 올데이기모후드는 BYC 직영점과 BYC 쇼핑몰을 포함한 BYC 온오프라인 판매처에서 만나볼 수 있다.BYC 관계자는 "올해 패션 트렌드는 유행보다 실용성을 최우선으로 하는 흐름이 이어질 것으로 보인다"며 "자신만의 스타일을 유지하면서도 다양하게 활용할 수 있는 이번 신제품으로 따뜻하고 편안한 겨울을 보내시길 바란다"고 말했다.', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008717696', 'https://imgnews.pstatic.net/image/421/2026/01/16/0008717696_001_20260116094920676.jpg?type=w800', 'NEWS_CONSUMER', NULL, '2026-01-16 09:48:58', 0, true, '2026-03-09 05:46:31.220530') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (623, '[연합뉴스 이 시각 헤드라인] - 18:00', '■ 냉온탕 오간 금융시장…코스피 9%대 반등·환율은 1,460원대로중동 전쟁 여파로 패닉에 빠졌던 국내 금융시장이 하루 만에 방향을 틀어 가파르게 등락하는 ''롤러코스터'' 장세를 보였다. 이틀간 1,000포인트 넘게 떨어졌던 코스피는 이날 사상 최대폭으로 올라 단숨에 5,580선을 회복했다. 환율은 전날 야간거래 장중 1,500원을 넘었다가 이날 1,460원대로 내려왔다. 5일 유가증권시장에서 코스피는 전날보다 490.36포인트(9.63%) 오른 5,583.90에 장을 마쳤다.전문보기: https://www.yna.co.kr/view/AKR202603051515000025,580대 회복한 코스피(서울=연합뉴스) 박동주 기자 = 최근 연이틀 폭락한 코스피가 급반등해 단숨에 5,580대를 회복한 5일 서울 중구 하나은행 딜링룸에서 직원이 업무를 보고 있다.이날 코스피는 전장보다 490.36포인트(9.63%) 오른 5,583.90에 장을 마쳤다. 2026.3.5 pdj6635@yna.co.kr■ 두바이서 韓관광객 114명 빠져나와…나머지도 속속 항공편 확보중동 사태 여파로 두바이 공항 운항 차질이 빚어지면서 현지에 발이 묶여 있던 한국인 관광객 95명이 이날 오후부터 잇따라 귀국한다. 여행사들이 자사 패키지여행 고객들에 대한 대체 항공편을 계속 확보해 추가 귀국자는 계속 늘어날 것으로 전망된다. 두바이에 체류 중인 관광객 520여명 중에서 415명이 항공편을 확보했고, 110여명은 아직 항공편을 구하지 못한 상태다. 현지 항공 사정에 변수가 많아 여행업계는 육로로 이동하는 방안 등도 다각적으로 검토 중이다.전문보기: https://www.yna.co.kr/view/AKR20260305071652030■ 이란 민중봉기 판까는 미·이스라엘…경찰 치우고 쿠르드족 동원이란을 공격 중인 미국과 이스라엘이 이란 국민들의 반체제 민중 봉기를 부채질하기 위해 판을 깔고 있다. 공습 첫날 아야톨라 세예드 알리 하메네이 최고지도자를 제거하는 데 성공했지만, 사람만 바뀔 뿐 신정체제가 그대로 존속할 가능성이 커지는 상황에서 진정한 ''레짐 체인지''(정권 교체)를 지원하는 쪽에 초점을 맞춘 것으로 보인다. 월스트리트저널(WSJ)은 4일(현지시간) 이스라엘군이 그동안 자국 내 반정부 시위대를 탄압해온 이란의 ''경찰 국가'' 체제를 무너뜨리는 데 공격을 집중하고 있다고 보도했다.전문보기: https://www.yna.co.kr/view/AKR20260305145800009■ 구윤철 "석유류값 인상 몰염치…최고가 지정, 신속 검토해달라"구윤철 부총리 겸 재정경제부 장관은 5일 중동 사태와 관련, 일부 석유류 가격의 과도한 인상이 포착됐다면서 "정부는 최고가격 지정 등을 포함해 가능한 모든 행정조치를 활용해 철저히 대응하겠다"고 밝혔다. 산업통상부 등에는 석유사업법상 석유판매가격 최고액 지정을 신속히 검토해달라고 당부했다. 구 부총리는 이날 오후 정부서울청사에서 주재한 ''민생물가 특별관리 관계장관 태스크포스''(TF) 3차 회의에서 "국제가격의 반영 시차 등을 감안할 때 아직 국내 가격에 실질적 영향을 줄 시점이 결코 아닌데도, 과도하게 가격을 인상해 폭리를 취하는 것은 민생을 좀먹는 몰염치한 행위"라며 이같이 언급했다.전문보기: https://www.yna.co.kr/view/AKR20260305134251002■ 李대통령 "빈말하지 않는다…규칙 어겨 이익 보는 시대는 갔다"이재명 대통령은 5일 "부당한 시스템에 의존하고 정당한 정부 정책에 역행해 이익을 얻는 것을 불가능하게 만드는 것이 이 정부의 1차 목표"라며 금융시장 교란 행위에 대한 엄단 의지를 재차 강조했다. 이 대통령은 이날 엑스(X·옛 트위터)에 국세청이 주가 조작 등으로 주식 시장을 교란한 27개 기업과 관련자 200여명에 대해 세무조사를 벌여 2천576억원을 추징하고 관련자를 검찰에 고발했다는 내용의 보도를 링크하고 이같이 적었다.전문보기: https://www.yna.co.kr/view/AKR20260305126000001■ 김건희특검 준비부족에 재판 종결 연기…법원 "이런 경우 처음"삼부토건 주가조작 의혹 핵심 인물인 이기훈 전 부회장을 도피시킨 혐의로 기소된 코스닥 상장사 회장 이모 씨의 1심 결심(심리종결) 절차가 민중기 특별검사팀의 준비 부족으로 연기됐다. 서울중앙지법 형사합의22부(조형우 부장판사)는 5일 범인도피 등 혐의로 재판받고 있는 이씨와 공범 6명의 속행 공판에서 오는 13일 변론을 종결하겠다고 밝혔다. 재판부는 당초 이날 결심 절차를 진행하려 했으나 특검팀이 증거목록을 준비해오지 않아 일정에 차질이 빚어졌다. 공판 검사가 도중에 바뀌면서 발생한 일인 것으로 알려졌다.전문보기: https://www.yna.co.kr/view/AKR20260305130000004■ UAE, 한국 정부에 ''천궁-Ⅱ'' 요격미사일 조기 공급 요청한국산 미사일 요격체계인 ''천궁-Ⅱ''를 운용 중인 아랍에미리트(UAE)가 우리 정부에 요격미사일 조기 공급을 요청한 것으로 전해졌다. 5일 연합뉴스의 취재를 종합하면, UAE는 이란의 공격을 받아 방공무기에 대한 수요가 늘어나자 한국 정부에 천궁-Ⅱ 포대를 계약서에 명기된 납기보다 빨리 공급해달라고 요청했지만, 정부는 이에 난색을 표한 것으로 알려졌다. 우리 군은 물론 사우디아라비아, 이라크 등 계약을 체결한 나라에 공급해야 하는 물량이 있고, 현재로선 군사적 충돌이 격화하는 중동 지역으로 포대를 이송하기도 쉽지 않기 때문으로 풀이된다.전문보기: https://www.yna.co.kr/view/AKR20260305127600504■ 특검, ''쿠팡 의혹'' 기소로 마무리…''관봉권 폐기'' 사실상 무혐의쿠팡 퇴직금 미지급 관련 의혹''과 ''관봉권 폐기 의혹''을 수사하기 위해 출범한 안권섭 상설특별검사팀이 90일간의 수사를 마쳤다. 쿠팡 의혹과 관련해서는 쿠팡 측과 엄희준·김동희 검사를 기소하는 결과를 내놨지만, 관봉권 폐기를 둘러싼 의혹은 마무리 짓지 못한 채 사건을 이첩했다. 특검팀은 수사 기간 마지막 날인 5일 브리핑을 열고 그간의 수사 결과와 향후 계획 등을 발표했다.전문보기: https://www.yna.co.kr/view/AKR20260305132200004■ 美법원, ''대법 무효판결'' 트럼프 관세 "기업에 돌려주라" 결정미국 연방대법원에서 지난달에 무효 판결이 나온 이른바 ''트럼프 상호관세''를 수입업자들이 실제로 환급받을 길이 연방법원 결정으로 열리게 됐다. 미국 국제무역법원(USCIT) 소속 리처드 이턴 원로판사는 4일(현지시간) 모든 수입업체가 대법원의 무효판결에 따른 수혜 대상이 될 자격이 있다고 결정문에서 밝혔다. 그는 트럼프 대통령이 국제비상경제권한법(IEEPA)에 근거해 부과했다 위법으로 판결된 상호관세의 환급에 관한 사건은 자신만 심리하게 될 것이라고 밝혔다.전문보기: https://www.yna.co.kr/view/AKR20260305126300009■ 치약서 금지 성분 검출…애경산업 수입업무 3개월 정지구강용품 사용 금지 성분인 트리클로산이 함유된 치약을 수입·판매한 애경산업이 수입업무정지 3개월 처분을 받았다. 5일 식품의약품안전처에 따르면 ''허가(신고)받지 않은 성분(트리클로산) 검출''과 ''회수절차 미준수''와 관련, 애경산업에 대해 해당 품목 수입업무정지 4개월 15일(3월 18~8월 1일) 처분이 4일 내려졌다. 또, 식약처는 수입업자의 준수사항 위반(품질 부적합) 관련, 전 수입업무정지 3개월(3월 18~6월 17일) 처분을 결정했다.전문보기: https://www.yna.co.kr/view/AKR20260305134600017', NULL, '연합뉴스', 'https://n.news.naver.com/mnews/article/001/0015940848', 'https://imgnews.pstatic.net/image/001/2026/03/05/PYH2026030517340001300_P4_20260305180015061.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-05 18:00:01', 0, true, '2026-03-09 05:46:51.819344') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (624, '남광토건, 26년 정비사업 마수걸이…가락7차 가로주택 시공권 확보', '1·2차 단독입찰, 총회서 최종 확정… 개롱역 초역세권 113가구 신축창사 80주년 앞두고 브랜드 리뉴얼 본격화…수도권 정비사업 확대서울 송파구 가락7차 현대아파트 가로주택정비사업 조감도. 남광토건 제공남광토건이 서울 송파구 가락동 소재 가락7차 현대아파트 가로주택정비사업(이하 가락7차) 시공권을 확보하며 2026년 정비사업 마수걸이에 성공했다.남광토건은 지난달 28일 개최된 조합 총회에서 시공사로 최종 확정됐다고 밝혔다. 가락7차 가로주택정비사업은 지난해부터 시공사 선정 절차를 진행해 왔으며, 1·2차 입찰 모두 남광토건이 단독으로 응찰했다. 이후 조합은 남광토건을 우선협상대상자로 지정했고, 총회 의결을 거쳐 최종 시공사로 확정했다.가락7차는 기존 72세대 규모의 단지를 113세대 규모로 재건축하는 가로주택정비사업이다. 사업 규모는 비교적 작지만, 서울 지하철 5호선 개롱역 바로 앞에 위치한 초역세권 단지라는 점에서 입지 경쟁력을 갖췄다는 평가다. 송파구 내 학군·생활편의시설·의료·상업 인프라를 고루 누릴 수 있어 실수요자 중심의 관심을 받아온 사업지다.업계에서는 최근 대형 정비사업 위주의 수주 경쟁이 심화되는 가운데, 도심 내 소규모·중규모 정비사업을 통한 안정적 수주 전략이 다시 주목받고 있다는 분석도 나온다. 특히 역세권 소형 정비사업은 사업 리스크를 상대적으로 낮추면서도 브랜드 인지도를 확대할 수 있는 교두보 역할을 한다는 점에서 의미가 있다는 평가다.남광토건은 내년 창사 80주년을 앞두고 주택사업 부문 강화에 속도를 내고 있다. 1947년 7월 7일 창립한 남광토건과 1947년 4월 28일 창립한 극동건설은 브랜드 통합 및 리뉴얼을 준비 중이며, 이를 계기로 민간 주택시장 공략을 본격화할 방침이다.양사는 서울·수도권 정비사업을 핵심 전략 지역으로 설정하고 있다. 극동건설은 극동강변아파트 소규모재건축사업에 단독 응찰했으며, 남광토건은 마포로5구역 제2지구 재개발사업에도 참여하는 등 서울 도심권 내 입지 경쟁력을 갖춘 사업지를 중심으로 추가 수주를 추진 중이다.남광토건 관계자는 “가락7차 수주는 올해 민간부문 마수걸이 수주로 창사 80주년을 맞아 새롭게 주택 분야를 강화하겠다는 회사의 의지를 담고 있다”며 “리뉴얼되는 ‘하우스토리’ 브랜드에 걸맞게 서울 도심권 등 검증된 입지의 정비사업에 적극 참여할 계획”이라고 밝혔다.한편, 1947년 창립된 남광토건과 극동건설은 한국전쟁 이전 설립된 건설사로 DL이앤씨, 현대건설, 삼부토건 등과 함께 국내에서 가장 오랜 역사를 가진 건설사로 꼽힌다. 창사 80주년을 기점으로 브랜드 통합과 조직 재정비를 통해 민간 주택시장 내 존재감을 확대할지 주목된다.', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005257537', 'https://imgnews.pstatic.net/image/015/2026/03/03/0005257537_001_20260303162614986.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-03 16:24:12', 0, true, '2026-03-09 05:46:51.819344') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (625, '남광토건, 송파 가락7차 현대아파트 가로주택 시공권 확보', '총회서 최종 확정…개롱역 초역세권 113세대 신축올해 마수걸이 수주...서울·수도권 정비사업 확대 박차송파 가락7차 현대아파트 가로주택정비사업 조감도.ⓒ남광토건[데일리안 = 이홍석 기자] 남광토건이 서울 송파구 가락동 소재 가락7차 현대아파트 가로주택정비사업 시공권을 확보하며 올해 정비사업 마수걸이에 성공했다.남광토건은 지난달 28일 개최된 조합 총회에서 시공사로 최종 확정됐다고 3일 밝혔다.가락7차 가로주택정비사업은 지난해부터 시공사 선정 절차를 진행해 왔으며 1·2차 입찰 모두 남광토건이 단독으로 응찰했다. 이후 조합은 남광토건을 우선협상대상자로 지정했고 총회 의결을 거쳐 최종 시공사로 확정했다.가락7차는 기존 72세대 규모의 단지를 113세대 규모로 재건축하는 가로주택정비사업이다. 사업 규모는 비교적 작지만 서울 지하철 5호선 개롱역 바로 앞에 위치한 초역세권 단지라는 점에서 입지 경쟁력을 갖췄다는 평가다. 송파구 내 학군·생활편의시설·의료·상업 인프라를 고루 누릴 수 있어 실수요자 중심의 관심을 받아온 사업지다.업계에서는 최근 대형 정비사업 위주의 수주 경쟁이 심화되는 가운데 도심 내 소규모·중규모 정비사업을 통한 안정적 수주 전략이 다시 주목 받고 있다는 분석도 나온다. 특히 역세권 소형 정비사업은 사업 리스크를 상대적으로 낮추면서도 브랜드 인지도를 확대할 수 있는 교두보 역할을 한다는 점에서 의미가 있다는 평가다.남광토건은 내년 창사 80주년을 앞두고 주택사업 부문 강화에 속도를 내고 있다. 지난 1947년 7월 7일 창립한 남광토건과 1947년 4월 28일 창립한 극동건설은 브랜드 통합 및 리뉴얼을 준비 중으로 이를 계기로 민간 주택시장 공략을 본격화할 방침이다.양사는 서울·수도권 정비사업을 핵심 전략 지역으로 설정하고 있다. 극동건설은 극동강변아파트 소규모재건축사업에 단독 응찰했으며 남광토건은 마포로5구역 제 2지구 재개발사업에도 참여하는 등 서울 도심권 내 입지 경쟁력을 갖춘 사업지를 중심으로 추가 수주를 추진 중이다.남광토건과 극동건설은 DL이앤씨·현대건설·삼부토건 등과 함께 국내에서 가장 오랜 역사를 가진 건설사로 창사 80주년을 기점으로 브랜드 통합과 조직 재정비를 통해 민간 주택시장 내 존재감을 확대할지 주목된다.남광토건 관계자는 “가락7차 수주는 올해 민간부문 마수걸이 수주로 창사 80주년을 맞아 새롭게 주택 분야를 강화하겠다는 회사의 의지를 담고 있다”며 “리뉴얼되는 ‘하우스토리’ 브랜드에 걸맞게 서울 도심권 등 검증된 입지의 정비사업에 적극 참여할 계획”이라고 말했다.', NULL, '데일리안', 'https://n.news.naver.com/mnews/article/119/0003064722', 'https://imgnews.pstatic.net/image/119/2026/03/03/0003064722_001_20260303134608198.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-03 13:46:08', 0, true, '2026-03-09 05:46:51.819344') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (626, '"내 주식은 도대체 왜?"…코스피 종목 25%는 ''손실''[육천피 시대]', '반도체·대형주 쏠림에 상대적 소외감 커져1년간 코스피 941개 종목 중 232개는 내려중대형주 137% 오를 때 초소형주는 13%↑[서울=뉴시스] 김혜진 기자 = 코스피가 장중 6,000을 넘은 25일 오전 서울 중구 하나은행 딜링룸에서 관계자들이 코스피 6000 돌파를 축하하고 있다. 2026.02.25. jini@newsis.com[서울=뉴시스] 박주연 기자 = "삼성전자나 SK하이닉스를 사둘 걸 후회돼요. 반도체 상장지수펀드(ETF)라도 사둘걸…. 저만 벼락거지가 되고 있는 거 같아요."코스피가 5000선 돌파 한 달만에 6000선을 뚫으며 질주하는 가운데 반도체·대형주 쏠림으로 인한 투자자들의 상대적 소외감도 커지고 있다.25일 한국거래소에 따르면 코스피는 최근 1년간 2600선에서 6000선까지 질주하며 125% 가량 상승했다.하지만 코스피 941개 종목 중 최근 1년간(2025년 2월 24일~2026년 2월 24일) 내린 종목은 232개로, 24.7%에 이르는 종목이 마이너스 수익률을 나타냈다. 오른 종목은 700개, 보합은 9개였다.특히 소형주의 상대적 소외가 심각했다.''KRX 초소형 TMI(토탈마켓인덱스) 지수''는 최근 1년간 12.60% 오르는데 그친 반면 ''중대형 TMI 지수''는 137.18%, ''중형 TMI 지수''는 65.32% 상승했다. TMI는 거래소가 코스피와 코스닥을 모두 반영해 구성한 시황지수다. 중대형은 누적 시가총액 94% 이상, 소형은 94∼99%, 초소형은 99% 미만 종목으로, 관리종목과 저유동성종목, 거래정지종목 등 투자 부적격 기업을 제외하고 산출한다.실제 최근 1년간 코스피 하락률 1~6위는 모두 1000원 미만 동전주였다. 인스코비는 1909원에서 546원으로 주가가 71.4% 하락했다.이스타코(-66.32%), 다이나믹디자인(-64.20%), 삼부토건(-64.20%), 오리엔트바이오(-59.69%), 윌비스(-59.68%) 등이다.진양화학(-47.49%), DI동일(-47.72%), 티웨이항공(-45.57%), DS단석(-36.39%), 대상홀딩스우(-36.09%), 티웨이홀딩스(-35.85%), 진원생명과학(-35.84%), 세아제강지주(-35.76%), 한솔홈데코(-32.95%), 남양유업(-30.45%)은 30% 넘는 하락률을 나타냈다.비비안(-29.95%), 아시아나항공(-28.06%), 진에어(-27.36%), 모나리자(-24.96%), 대교(-24.04%), 쏘카(-23.33%), SKC(-22.83%), 형지엘리트(-21.61%), 더본코리아(-20.91%)도 20%대 손실을 나타내고 있다.업종별로는 K-콘텐츠(게임·엔터)가 상대적 약세를 나타냈다. KRX 반도체지수가 174% 상승하는 동안 KRX K콘텐츠지수는 16% 오르는데 그쳤다.증권사 리서치센터장들은 대체로 올 상반기까지는 반도체·대형주 중심 랠리가 지속될 것으로 전망했다. 다만 하반기부터는 경기방어주 위주의 분산투자 전략이 필요할 것으로 내다봤다.유종우 한국투자증권 리서치센터장은 "반도체 랠리가 지속될 것"이라며 "반도체 비중은 유지하면서 기타 유망 업종 비중을 확대할 필요가 있다"고 조언했다.윤석모 삼성증권 리서치센터장 역시 "상반기 중에는 반도체 업종 주가가 양호할 것"이라며 "반도체 가격 상승률이 둔화되는 상반기 말부터는 분산 투자 전략이 필요할 수 있다"고 조언했다. 차기 유망업종으로는 내수·금융·방산 업종 등을 꼽았다.이승호 IBK투자증권 리서치센터장은 "상반기까지는 반도체, 증권 등 현재의 시장 주도주를 중심으로 포트폴리오를 구성하고 하반기에는 경기방어주나 배당주 등 보수적 포트폴리오에 유리한 업종들의 비중을 확대할 필요가 있다"고 조언했다. 이 센터장은 "정부 정책 기대감에 따른 코스닥 시장 재평가 기대감이 코스닥 대형주를 중심으로 선제적으로 유입될 가능성도 높다"고 덧붙였다.황승택 하나증권 리서치센터장 역시 "반도체는 국내 증시에서 2026년 이익 증가율 전망치가 가장 높은 섹터로, 주도주 역할을 지속할 가능성이 크다"며 "실적 가시성이 높은 대형주와 우량주 중심의 선별 투자를 하는 것이 포트폴리오 변동성을 낮추고 장기적으로 더 안정적인 수익률을 가져다줄 것"이라고 제언했다．', NULL, '뉴시스', 'https://n.news.naver.com/mnews/article/003/0013786840', 'https://imgnews.pstatic.net/image/003/2026/02/25/NISI20260225_0021186328_web_20260225092454_20260225110923963.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-25 11:04:15', 0, true, '2026-03-09 05:46:51.819344') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (627, '코스닥 상폐 대상 최대 220곳…''시총·동전주·재무'' 3중 덫', '7월 시총 기준 200억으로 상향…경계구간 기업 ''발등에 불''동전주 퇴출 대상 100여곳...액면병합 ''꼼수''도 안 통해심사기간 단축에 퇴출 앞당기는 거래소[이데일리 김경은 기자] 올해부터 단계적으로 강화되는 상장폐지 제도 개선안에 따라 시가총액·주가·재무 요건을 동시에 충족하지 못하는 ‘다중 위험지대’ 기업들이 무더기 퇴출 기로에 놓였다.한국거래소의 시뮬레이션 결과 올해 코스닥 상장폐지 대상 기업은 기존 예상 50곳에서 최대 220개사까지 불어날 수 있다는 전망이 나오는 가운데, ‘어떤 유형의 기업이 가장 먼저 정리되는가’를 둘러싼 투자자들의 관심이 집중되고 있다.‘다중 위험지대’ 기업 집중 타격 전망19일 한국거래소에 따르면 지난 13일 기준 시가총액 기준만 놓고 보면 당장 퇴출 대상에 오른 150억원 미만 코스닥 상장사는 11곳이다. 시총 200억원 미만 코스피 상장사 7곳도 대상이다. 오는 7월 강화된 퇴출 기준에 해당하는 150억~200억원 사이(코스닥), 200억~300억원 사이(코스피) 상장사들도 현 주가 기준 각각 20곳, 18곳으로 추산된다.기준 변경을 불과 수개월 앞두고 있다는 점에서 이들 구간 기업들의 발등에 불이 떨어진 셈이다. 단기간에 시가총액을 끌어올릴 호재나 실적 개선 없이는 기준 시행과 동시에 심사 레이더에 오르게 된다.시총 위기에 주가 요건까지 겹친 기업들은 가장 먼저 탈락 후보로 꼽힌다. 새 제도에서는 주가 1000원 미만 동전주가 관리종목으로 지정된 뒤, 90일 중 45일 이상 기준가를 회복하지 못하면 상장폐지로 직결된다.현재 1000원 미만 동전주는 코스닥 163개, 코스피 8개(보통주)로 시총 기준 퇴출 대상보다 수가 훨씬 많다. 현재 동전주 가운데 시가총액이 200억원에 못 미치는 곳만 추리면 수십 개사가 이미 ‘이중 위험지대’에 들어와 있다. 이들 기업은 주가를 1000원 이상으로 끌어올리는 동시에 시총 200억·300억원선까지 방어하지 못하면 사실상 시장 퇴출이 불가피하다는 평가다.[이데일리 김정훈 기자]시총 기준 면했지만 ‘액면가’ 미달 동전주 ‘덜덜’시총 기준은 피했지만 동전주 상폐 기준 신설로 새롭게 대상에 오를 곳도 대폭 늘었다. 시총 요건을 충족한 코스닥 상장사 104곳이 동전주 상태인데, 이 가운데 현 주가가 액면가에 미달해 액면병합을 하더라도 상장폐지 위기를 벗어나기 어려운 곳이 10여 개에 달한다.새 제도는 ‘액면병합 후에도 주가가 액면가 미만인 경우’ 동전주 상장폐지 요건을 그대로 적용해 이 우회로를 원천 차단했다. 예컨대 큐캐피탈(016600)의 경우 시가총액은 약 600억원에 달해 시총 요건은 문제가 되지 않지만, 현재가가 333원으로 액면가 500원을 하회해 단순 액면병합만으로는 제도의 덫에서 벗어날 수 없다. 7월 제도 시행을 앞두고 동전주를 벗어날 방안을 강구해야 한다. 이 외에 바른손(018700)이앤아이, 제이엠아이(033050), 엔시트론(101400), 플루토스(019570), 바른손(018700), 에이전트AI(060900), 기가레인(049080), 디에이테크놀로지(196490), 에이비프로바이오(195990), THE CUBE&(013720)amp;, 앱토크롬(109960) 등도 액면가에 미달하는 동전주다.반기 기준 완전자본잠식 요건도 새로 신설되면서 재무 리스크를 안고 있는 기업들도 긴장을 놓을 수 없게 됐다. 지난해 반기보고서 기준 완전자본잠식 기업들은 범양건영(002410), 삼부토건(001470), 제일엠앤에스(412540), 선샤인푸드(217620), 넥스트칩(396270), 셀레스트라(352770), 시스웍(269620), 이오플로우(294090) 등이다.심사 절차도 기존 3심제에서 2심제로 단축되고 최대 개선기간도 기존 1.5년에서 1년으로 줄어들면서, 재무·공시·시총·주가 네 가지 요건을 모두 버티지 못한 기업들은 올해 안에 대거 시장에서 사라질 것이라는 전망이 나온다.거래소는 “코스닥시장은 부실기업을 선별하고 상장적격성 회복 가능성이 현저히 떨어지는 한계기업의 신속한 퇴출에 역량을 집중할 예정”이라며 “엄격하고 신속한 부실기업 퇴출 체계 확립을 통해 코스닥 시장이 투자자에게 신뢰받는 시장으로 자리 잡을 것으로 기대한다”고 말했다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006221006', 'https://imgnews.pstatic.net/image/018/2026/02/19/0006221006_001_20260219193114929.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-19 17:25:11', 0, true, '2026-03-09 05:46:51.819344') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (628, '''돈만 벌면 된다'' 윤리 잊은 기자들…''선행매매'' 사건 총정리', 'KBS 첫 보도부터 국감, 한국경제 압수수색까지…1년 넘게 이어진 언론계 개혁 과제▲ 7월7일 송수진 KBS 기자의 단독 기사 ''기자 선행매매 수사, 특징주 100여 개 뒤진다'' 보도 화면 갈무리.2025년 7월4일 KBS의 <[단독] 주식 사고, 기사쓰고, 주식 팔고…기자 20여 명 수사> 보도로 ''기자 선행매매'' 사건이 수면 위로 드러났다. 기자들이 미공개 정보를 이용해 주식을 매매하고 호재성 기사를 직접 쓴 뒤 주가를 띄워 되파는 ''선행매매''는 이전부터 포착되어 온 것이 사실이나, 본격적으로 알려지진 않았다. 지난해 KBS 기사가 나온 이후에도 이를 보도하는 언론사는 극소수였다. 이후 10월 정무위 국정감사에서 한창민 사회민주당 의원이 관련 질의를 한 후 다시 한번 주목을 받았으나 이 역시 기자들의 부정 행위 크기에 비해 미약했다. 그러나 지난 5일 한국경제신문 압수수색 이후 대통령이 이 사안을 SNS에 공유하며 언론계 전반을 흔드는 사안으로 주목받기 시작했다. 미디어오늘은 지난해 첫 보도 이후 지금까지의 흐름을 시간순으로 정리했다."호재성 기사로 부당이득" 매일경제 기자 퇴사지난 5일 한국경제 압수수색으로 선행매매 사건과 관련해 한국경제 매체명이 크게 오르내렸으나 매일경제에서도 관련 혐의로 퇴사를 한 기자가 있었다. 2025년 3월 금융위원회 산하 증권선물위원회로부터 부정거래행위 금지 위반 혐의로 매일경제 기자가 고발 조치됐고, 퇴사를 하는 사건이 벌어졌다. 해당 기자는 2023년 7월~2024년 6월 10개 종목을 매수하고 관련 기사를 보도하면서 매매를 유인한 뒤 매도한 방식으로 부정거래 행위를 한 혐의를 받았다. 다만 이때 매일경제는 회사 차원에서의 진상 조사나 입장 발표를 하지 않았다.[관련 기사: ''주식 호재'' 보도로 부당이득 혐의, 매일경제 기자 퇴사]▲매일경제 미디어센터 ⓒ연합뉴스KBS의 단독 보도…그러나 언론에선 조용''기자 선행매매''가 크게 관심을 받게 된 계기는 KBS 송수진 기자의 <[단독] 주식 사고, 기사 쓰고, 주식 팔고…기자 20여명 수사>(2025년 7월4일) 기사다. 해당 기사는 전현직 기자 등 20여 명이 선행매매 혐의로 금융 당국의 수사를 받고 있다고 보도했다. 금융감독원 자본시장특별사법경찰(특사경)이 포착한 혐의를 보도했는데 기자가 무더기로 수사 대상에 올랐기에 큰 충격을 던졌다.같은달 7일 KBS는 <기자 선행매매 수사, ''특징주'' 100여 개 뒤진다>에서 선행매매 혐의를 받고 있는 기자들이 특징주를 중심으로 부정행위를 저질렀다고 전했다. 또한 이 보도에서는 일부 기자들이 공모를 해 여러 명이 한 그룹으로 움직이며 특징주 기사를 비슷한 시점에 잇따라 출고했다고 보도했다. 또한 기자의 배우자까지 특징주 선행매매에 연루됐다고 전했다. 당시 송수진 기자는 미디어오늘에 "이런 선행매매는 업계의 공공연한 비밀이었다"라면서 이 사건을 전하는 언론 보도가 적다는 사실도 지적했다.[관련 기사: ''선행매매'' 기자·언론사 압수수색에도 조용한 언론계]KBS 다큐 폭로·국감 쟁점화…정치권으로 확장된 선행매매 사건2025년 10월5일 KBS 시사 다큐멘터리 <개미 홀리기- 작전 세력이 된 기자들>에서는 기자들이 소형 특징주 기사를 쓰면서 수억원대 이익을 올린 사례와 함께, 기자들이 호재성 기사를 쓰면서 해당 회사의 주식을 받아 이득을 얻은 사례도 언급됐다. 또한 주가조작 혐의로 기소된 관계자가 해당 다큐에 나와 특징주 기사를 써준 기자에 1000만원 씩 줬다는 폭로도 다뤄졌다. 기자들이 기사를 쓰고 이득을 얻는 식의 부정행위를 넘어 ''주가조작 생태계와의 연결 가능성''까지 제기된 것이다.[관련 기사: KBS 다큐 "주가조작 세력 ''기자에 1000만 원 준 적 있다'' 폭로"]▲2025년 10월5일 KBS 시사 다큐멘터리 ''더 보다'' 가운데 ''개미 홀리기- 작전세력이 된 기자들'' 편 화면 갈무리. 사진출처= KBS 홈페이지.기자들이 주가조작 범죄자들과 연루된 사례는 또 있다. 김건희 특검(김건희와 명태균·건진법사 관련 국정농단 및 불법 선거 개입 사건 등 진상규명을 위한 특별검사)이 들여다보고 있는 삼부토건 주가조작 의혹에, 이기훈 전 삼부토건 부회장이 관계자들과 공모하여 허위·과장 보도자료를 만들어 배포, ''테마주'' 등의 제목을 단 언론 기사를 통해 주가조작을 한 정황이 드러난 것이다. 허위·과장 보도자료가 기사 형태로 유통돼 시세조종의 수단으로 활용된 구조가 드러나 충격을 줬다.[관련 기사: ''허위 보도자료'' 그대로 기사화…''삼부토건 주가조작'' 통로된 언론]같은 시기 10월 정무위 국정감사에서도 언론인의 주식 거래 문제가 의제로 떠올랐다. 한창민 사회민주당 의원에 의해 금융당국의 관리·감독 책임과 함께 언론사의 내부 통제 부실이 도마에 올랐고, "언론은 징계나 사과조차 없다"는 비판이 제기됐다. 한창민 의원은 이후 12월4일 국회 토론회를 열어 기자들의 선행매매 등 부정행위에 대해 정부 차원의 지원과 규제 정책에 대한 본격적인 고민이 시작되어야 한다고 밝혔다.[관련 기사: 국감서 다뤄진 ''기자 선행매매''…"언론, 징계나 사과조차 없어 대책 필요"][관련 기사: 한창민 "금융당국, 언론인 주가조작 범죄 국민께 보고 할 의무 있다"]▲2025년 10월20일 국회 정무위원회 국정감사에서 한창민 의원이 이억원 금융위원장에 기자 선행매매 사건 관련 질의를 하고 있다. 사진출처=국회방송 유튜브 갈무리.선행매매로 112억 번 기사 기소…이투데이, 서울경제TV 언급됐음에도 ''꼬리 자르기''2025년 말 ''전직 경제신문 기자''가 장기간 선행매매로 약 112억 원대 부당이익을 얻었다는 사건이 드러나며 파장이 확대됐다. 해당 인물은 서울경제, 이투데이, 서울경제TV를 거친 기자였다. 그러나 해당 언론사들은 진상 조사나 공식 사과문 등을 밝히지 않았다.[관련 기사: [단독] 선행매매로 112억 번 기자, 이투데이-서울경제-서울경제TV 거쳤다]한국경제 압수수색·사장 사임…윤리 지침 1면까지2026년 2월 주가조작 근절 합동대응단이 한국경제신문을 압수수색했다. 연루된 구성원만 5명인 이 사건에서 미공개 정보를 이용해 수억 원을 취득한 사례가 알려지면서 사건은 대형 언론사 차원의 문제로 확장됐다. 압수수색 이후 대통령까지 관련 기사를 공유했고 한국경제는 사과문 발표와 함께 사장 사임이 이어졌다. 한국경제는 단기 주식 거래를 원천 금지하는 윤리지침을 발표했고, 지면을 통해 ''주식 단기매매를 하지 않겠다''는 결의를 내놓았다. 이후 다른 언론사들도 내부 투자 가이드라인을 재검토하기 시작하며 파장은 업계 전반으로 확산됐다.[관련 기사: 대통령도 공유한 ''기자 선행매매''…한국경제, 사장 사임 이후 TF 꾸렸다]▲한국경제 사옥과 한국경제 12일 1면 지면 기사 제목을 합친 이미지.지난 1년간 이어진 관련 사건 보도는 선행매매 사건이 언론 개혁 의제가 되어야 한다는 점을 보여주고 있다.', NULL, '미디어오늘', 'https://n.news.naver.com/mnews/article/006/0000134361', 'https://imgnews.pstatic.net/image/006/2026/02/17/0000134361_001_20260217055012473.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-17 05:50:12', 0, true, '2026-03-09 05:46:51.819344') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (629, '삼부토건 매각 속도 … 인수 후보 6곳 압축', '이달 우선협상자 선정지난해 말 인가 전 인수·합병(M&A)이 한 차례 무산됐던 삼부토건 매각전이 다시 속도를 내고 있다. 삼부토건은 조만간 인수후보 6곳 중 1곳을 우선협상대상자로 선정할 방침인 것으로 전해졌다.3일 투자은행(IB) 업계에 따르면 최근 진행한 삼부토건 매각 입찰에 인수후보 6곳이 참여해 절차를 밟고 있다. 이번 입찰은 삼부토건이 진행하는 2차 인가 전 M&A 입찰이다. 삼부토건은 지난해 3월 6일 서울회생법원에서 회생 절차 개시 결정을 받았다. 이후 안진회계법인을 매각 주관사로 선정하고 10월부터 1차 공개 매각을 진행했다. 1차 매각 당시에는 원매자 5곳이 인수의향서를 제출했다. 하지만 본입찰 단계에서는 1곳도 입찰에 참여하지 않았다.서울회생법원은 지난달 회생계획안 제출 기간을 기존 1월 17일에서 3월 6일까지 연장하기로 결정했다. 매각 측은 회생 일정을 고려해 2월 말까지 우선협상대상자를 선정할 계획이다. 삼부토건은 최대주주 디와이디(DYD) 지분 3.4%를 제외하면 96%가량의 지분이 모두 소액주주로 구성돼 있다. 디와이디는 이일준 삼부토건 회장이 지배하는 회사다.[박제완 기자]', NULL, '매일경제', 'https://n.news.naver.com/mnews/article/009/0005631775', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2026-02-03 17:59:15', 0, true, '2026-03-09 05:46:51.819344') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (630, '센터필드 펀드, 만기 연장 협의 착수했지만…GP·LP 충돌에 대체투자 업계 ''긴장''', '이지스운용, 매각 절차 중단…국민연금·신세계와 협상 돌입펀드 만기 앞두고 불거진 갈등…만기 대응 vs 일방적 판단GP·LP 힘겨루기에 업계 촉각…운용 판단 위축 우려 제기이지스자산운용서울 강남에 위치한 역삼 센터필드의 매각을 둘러싸고 정면충돌 양상으로 치닫던 GP(운용사)와 LP(출자자) 간 갈등이 일단 숨 고르기에 들어갔다. 시장에서는 이지스자산운용이 매각 절차를 중단하고 국민연금공단, 신세계프라퍼티와 펀드 만기 연장 논의에 착수하기로 하면서 사태가 일단락될 것으로 보면서도 끝까지 긴장을 놓지 못하는 모습이다.28일 금융투자업계에 따르면 이지스자산운용은 강남 역삼동 소재 센터필드의 매각 자문사 입찰 접수 마감을 하루 앞둔 지난 26일 저녁께 입찰제안요청서(RFP)를 수령했던 자문사들에 매각 취소를 고지했다.이지스운용 측은 27일 입장문을 통해 "이지스자산운용은 강남 역삼동 소재 ''센터필드'' 자산의 매각 절차를 중단한다"며 "펀드 만기 연장을 위한 수익자 간 협의를 공식적으로 개시함을 알린다"고 밝혔다.이어 "최근 주요 수익자인 신세계프라퍼티 측으로부터 펀드 만기 연장에 대한 공식적인 요청이 접수됐고 공동 수익자인 국민연금공단 역시 매각보다는 펀드 운용 기간 확보가 필요하다는 입장임을 확인했다"며 "당사는 현재 진행 중이던 매각 절차를 중단하고 모든 수익자와 협의해 수익자의 이익과 펀드의 안정적인 운용을 위한 펀드 만기 연장에 대한 협의를 우선적으로 진행하기로 했다"고 설명했다.◆''르네상스의 저주'' 푼 역삼 센터필드, 부동산 개발 대표 성공 사례역삼 센터필드는 서울 테헤란로 옛 르네상스호텔 부지에 들어선 프라임 오피스로 현재 이지스운용이 운용 중인 ''이지스210호전문투자형사모부동산투자회사''의 핵심 자산이다. 신세계프라퍼티는 ''캡스톤APAC전문투자형사모투자신탁2호''를 통해 에쿼티 포함 총 5548억원을 투입해 센터필드 지분의 48.4%(신세계그룹 전체 49.7%)를 보유 중이다. 나머지 지분 대부분(49.7%)도 국민연금이 들고 있으며 이지스자산운용은 약 0.5% 안팎으로 보유 중이다.앞서 이지스자산운용은 지난 2015년 삼부토건의 법정관리로 시장에 나온 부지를 2018년 인수해 2021년 센터필드를 준공했다. 이후 아마존코리아, 크래프톤 등 우량 임차인들과 5성급 호텔 ''조선 팰리스''도 입점해 강남역권(GBD) 최대 오피스 자산으로 성장하면서 ''르네상스 저주''를 푼 부동산 개발 대표 성공 사례로 꼽힌다.◆펀드 만기 앞두고 극명해진 입장차…"매각" vs "GP 교체" 초강수하지만, GP인 이지스운용과 국민연금 등 주요 LP 간 갈등은 역삼 센터필드 펀드 만기를 앞두고 이해당사자 간 입장차로 시작됐다. 당초 이지스운용은 지난 2024년부터 출자자들에게 ''중장기 연장 사업계획''을 제안했다. 신세계프라퍼티는 펀드 만기 연장에 찬성했지만, 국민연금은 부정적인 입장을 고수하면서 지난해 10월 1년간의 단기 연장만 이뤄졌다.이후 이지스운용은 센터필드가 포함된 부동산 펀드의 만기(10월)와 대출 상환 일자(9월)를 앞두고 매각 절차를 추진했다. 반면 국민연금과 신세계프라퍼티는 매각을 ''독단적 결정''으로 규정하고 법적 대응·GP 교체를 시사하며 강하게 반발했다.특히 국민연금은 지난 20일 내부 투자위원회 등을 가동해 센터필드의 GP 교체와 고양 스타필드의 매각을 결정했는데, 시장에서는 이를 두고 ''성과 보수 삭감''이라는 해석이 나온다. 통상 센터필드와 같은 대형 자산이 매각되면 공개경쟁을 통해 형성된 ''실제 매각가''가 성과 보수 산정의 기준이 되지만, 운용사를 교체하거나 자산 이관의 경우에는 실제 시장가보다 보수적으로 책정되는 ''감정평가액''을 기준으로 정산하기 때문이다.한 대체투자 업계 관계자는 "GP 교체나 자산 이관으로 방향이 바뀌면 감정평가액을 적용하게 되는데, 이 경우 감정가가 시장가보다 보수적으로 나오는 만큼 결과적으로 운용사 입장에서는 성과 보수가 줄어들 수 있다"고 말했다.◆봉합 국면 속 여전히 남은 변수…업계도 ''긴장''GP와 LP간 정면충돌이 이례적인 만큼 업계에서도 역삼 센터필드를 둘러싼 세 회사의 갈등을 예의주시하고 있다. 이지스운용이 매각 절차를 중단하면서 갈등이 봉합 국면에 접어든 것처럼 보이지만, 국민연금이 여전히 자산 이관을 진행하겠다는 입장인 것으로 전해지면서 대체투자 시장은 살얼음판이 됐다.일각에서는 이번 사안이 단순히 개별 자산의 운용 갈등을 넘어 국내 대체투자 시장 전반을 위축시킬 수 있다고 우려했다. 자본시장 큰손인 국민연금이 운용 전략 이견 국면에서 GP 교체라는 강수를 두는 선례가 쌓일 경우 운용사들은 향후 매각 시점이나 운용 판단에서 시장 상황보다 LP의 입장을 우선적으로 고려할 수밖에 없다는 설명이다. 또한 글로벌 기관투자가들의 의사결정에도 부정적 영향을 줄 수 있다는 주장도 제기된다.업계 관계자는 "국민연금과 같은 핵심 LP가 운용 판단에 강하게 개입하는 사례가 반복되면 GP들은 결국 ''눈치 보기''를 하게 된다"며 "이는 시장 전체의 활력을 떨어뜨리는 신호가 될 수 있다"고 했다.다만, 이번 갈등이 업계 전반 위축으로 이어질 가능성은 낮다는 전망이 지배적이다. 국민연금과 신세계프라퍼티가 펀드 만기 연장 의사를 밝히면서 최악의 상황으로 치닫진 않은 데다 세 회사의 충돌은 내부 이해관계자 간 감정의 골이 깊어지며 발생한 하나의 ''이벤트''로 보는 모습이다.또 다른 업계 관계자는 "국민연금도 AMC(자산관리전문회사) 교체에 적지 않은 계약·법적 리스크가 있을 테고 이지스운용도 연초 전주에 사무소를 개소하는 등 양사 간 소통이 아예 없는 것은 아니다"라며 "민간 운용사를 강하게 압박한다는 인식을 주게 되면 향후 해외투자자 유치 등에도 어려움이 확대될 것이기 때문에 국민연금도 섣불리 강한 조치를 내리긴 어려울 것"이라고 말했다.', NULL, '매일신문', 'https://n.news.naver.com/mnews/article/088/0000994174', 'https://imgnews.pstatic.net/image/088/2026/01/28/0000994174_001_20260128111507638.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-28 11:15:07', 0, true, '2026-03-09 05:46:51.819344') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (633, '4년 만에 다시 ''오일 쇼크''…국내 유가 ''고공행진''', '■ 용감한 토크쇼 ''직설'' - 손석우 앵커 경제평론가 (건국대 겸임교수), 서상현 고려대 아시아·아프리카 개발협력센터 연구위원, 박형중 우리은행 이코노미스트, 김재승 현대차증권 연구원- 4년 만에 다시 ''오일 쇼크''…국내 유가 ''고공행진''- 이란, 의도적으로 정유시설 공격하나?- 이란 "중동 내 인프라 완전 파괴"- 사우디 아람코 최대 정유시설 또 드론 공격- 카타르 가스·사우디 정유공장 ''셧다운''- 바레인 "이란, 마아미르 정유시설 공격"- 이란 걸프해역 유조선 산발 공격 지속(자세한 내용은 동영상을 시청하시기 바랍니다.)당신의 제보가 뉴스로 만들어집니다.SBS Biz는 여러분의 제보를 기다리고 있습니다.홈페이지 = https://url.kr/9pghjn', NULL, 'SBS Biz', 'https://n.news.naver.com/mnews/article/374/0000496659', 'https://imgnews.pstatic.net/image/374/2026/03/09/0000496659_001_20260309140808106.png?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 14:08:07', 0, true, '2026-03-09 05:47:13.922165') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (634, '중동 리스크 악재 속…코스피 7000 전망?', '■ 용감한 토크쇼 ''직설'' - 손석우 앵커 경제평론가 (건국대 겸임교수), 서상현 고려대 아시아·아프리카 개발협력센터 연구위원, 박형중 우리은행 이코노미스트, 김재승 현대차증권 연구원- 중동 리스크 악재 속…코스피 7000 전망?- 외국인의 매도세, 잦아들까?- 골드만삭스, 코스피 6400→7000 상향 조정- JP모간, 삼성전자 목표 주가 24만 원으로 유지- 글로벌 IB, 코스피 상승 여력에 무게- 정부, 홍콩서 골드만삭스 등 투자자 소통- 정부 "韓 경제 펀더멘털 견고"- 대신證 "올해 코스피 목표치 7,500"- 중동 리스크 악재 속 코스피 회복 속도 관건(자세한 내용은 동영상을 시청하시기 바랍니다.)당신의 제보가 뉴스로 만들어집니다.SBS Biz는 여러분의 제보를 기다리고 있습니다.홈페이지 = https://url.kr/9pghjn', NULL, 'SBS Biz', 'https://n.news.naver.com/mnews/article/374/0000496660', 'https://imgnews.pstatic.net/image/374/2026/03/09/0000496660_001_20260309140816618.png?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 14:08:16', 0, true, '2026-03-09 05:47:13.922165') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (635, '''롤러코스터 증시'' 투자전략은…증권가 "V자 아닌 W자 반등 가능성"', '"W자 반등 가능성…두 번째 바닥 대비""과도한 조정 시 매수 전략 여전히 유효"[서울=뉴시스] 황준선 기자 = 코스피가 전 거래일(5584.87)보다 319.50포인트(5.72%) 하락한 5265.37에 개장한 9일 오전 서울 중구 하나은행 딜링룸에 지수가 표시돼 있다. 2026.03.09. hwang@newsis.com[서울=뉴시스]이지민 기자 = 중동 사태 여파로 국내 증시가 급등락을 반복하는 가운데 증권가에서는 ''V자'' 반등보다는 ''W자'' 반등 가능성을 염두에 둬야 한다는 조언이 나온다.9일 한국거래소에 따르면 이날 코스피는 전 거래일보다 319.50포인트(5.72%) 내린 5265.37에 개장, 이후 낙폭을 확대하며 장중 8% 하락하고 있다.미국과 이스라엘의 이란 공습으로 시작된 중동 분쟁이 국제 유가를 끌어올리면서 증시에 부담으로 작용했다. 이날 국제 유가의 기준점 역할을 하는 브렌트유와 서부텍사스산원유(WTI)는 모두 배럴당 100달러를 돌파했다.중동 사태가 장기화될 조짐을 보이면서 국내 증시의 변동성도 크게 확대되는 모습이다. 코스피 지수는 지난 3일과 4일 각각 -7.24%, -12.06% 급락했으나, 지난 5일 다시 9.36% 급등한 바 있다.증권가에서는 유가 급등과 원·달러 환율 상승 등에 따른 변동성 장세가 당분간 지속될 수 있다는 경고음이 나온다. 이에 따라 국내 증시는 ''V자'' 반등 보다는 ''W자'' 반등 가능성이 높게 점쳐진다.이은택 KB증권 연구원은 "지금처럼 증시가 급락했던 사례에서 V자 반등은 드물며, 대부분 W자 반등이었다"고 말했다. 이 진단대로라면 앞으로 몇 번의 조정이 더 나타날 수 있다.이어 "과거 두 번째 바닥이 더 낮게 나타났던 이유는 불확실성이 확정되는 데까지 공포를 반영하는 과정과 시간이 필요했기 때문"이라며 "다시 말해 최악의 공포가 시장을 덮칠 때가 증시 바닥이었다"고 설명했다.노동길 신한투자증권 연구원도 "현재는 가격 패턴만으로 V자 회복을 단정할 수 없다"며 "W자 리테스트 가능성을 열어둔 분할 매수 형태가 합리적"이라고 짚었다.또 "현재 유가 상승이 지속되고 있고 환율은 상단 부담을 완전히 벗어나지 못했다"며 "금리와 금리 변동성도 높은 수준에 머물고 있다"고 분석했다. 이에 "가격의 방향보다 지속성을 확인해야 한다"고 조언했다.일각에서는 ''바이 더 딥''(Buy the dip·조정 시 매수) 전략이 여전히 유효하다는 의견도 나온다.김재승 현대차증권 연구원은 "중동의 전쟁 이벤트에 따른 고유가 장기화는 코스피의 조정 요인으로 작용하겠지만, 역사적으로 봤을 때 코스피는 중동 이벤트를 한 달 안에 극복했다"며 "과도한 조정 시 매수 전략을 추천한다"고 말했다. 그 이유로는 코스피 펀더멘털이 여전히 탄탄하고, 외국인과 개인의 수급이 더 확대될 여력이 있다고 짚었다.', NULL, '뉴시스', 'https://n.news.naver.com/mnews/article/003/0013810197', 'https://imgnews.pstatic.net/image/003/2026/03/09/NISI20260309_0021200890_web_20260309093317_20260309140918591.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 14:08:34', 0, true, '2026-03-09 05:47:13.922165') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (636, '[직설] 중동 지정학적 리스크에 흔들리는 금융시장…이란 사태 전개 향방은?', '■ 용감한 토크쇼 ''직설'' - 손석우 앵커 경제평론가 및 건국대 겸임교수, 서상현 고려대 아시아·아프리카 개발협력센터 연구위원, 박형중 우리은행 이코노미스트, 김재승 현대차증권 연구원미국과 이스라엘, 그리고 이란의 전쟁이 계속되면서 중동 전역에 긴장감이 흐르고 있습니다. 이런 지정학적 리스크가 부각되면서 전 세계 금융시장도 긴장의 끈을 놓지 못 하고 있는데요. 이란 사태가 어떤 방향으로 전개될지, 그럼 지금부터 이야기 나눠보겠습니다. 오늘(9일) 함께 해주실 세 분을 모셨습니다. 고려대 아시아·아프리카 개발협력센터 서상현 연구위원, 우리은행 박형중 이코노미스트, 현대차증권 김재승 연구원 나오셨습니다.트럼프 미국 대통령은 지상군 투입에는 말을 아꼈습니다. 그러면서도 이란의 차기 지도자 선출에 관여하겠다는 뜻을 밝혔는데요. 먼저 트럼프 대통령의 발언 듣고 본격적인 이야기 시작하겠습니다.[도널드 트럼프/미국 대통령 : 말하고 싶지 않습니다. 부적절한 질문 같습니다. 대답하지 않을 겁니다. 아주 타당한 이유가 있어야 (투입이) 가능할 겁니다.][도널드 트럼프/미국 대통령 : 5년, 10년마다 이런 공격을 반복하고 싶지 않습니다. 자기 나라를 전쟁으로 이끌지 않을 대통령을, 우리가 선택하고 싶습니다.]Q. 이란이 새 최고지도자로 하메네이 차남 모즈타바를 만장일치로 선출했습니다. 그런데 트럼프는 모즈타바에 대해서 대놓고 부정적인 뜻을 밝혔는데요. 모즈타바와 트럼프가 강대강 대치할까요?Q. 이란 사태가 발생한 지, 일주일이 넘었습니다. 현재의 시장은 사태를 어떻게 보고 있는 것 같습니까?Q. 변동성이 심한 가운데 개인들은 레버리지와 곱버스 ETF에 과감하게 투자하고 있는데요. 이건 괜찮을까요?Q. 이란 사태로 유가에 대한 걱정이 커져가고 있는 가운데 이란이 은근 국가들의 정유시설 공격에 나섰는데요. 에너지 공급망을 인질로 삼겠단 작전일까요?Q. 중동 정세에 따라서 국제유가도 출렁이고 있는데요. 트럼프 행정부가 필요할 경우, 미 해군이 유조선을 호위하겠다고까지 했습니다. 그럼에도 여전히 배럴당 100달러를 넘길 가능성은 살아있는 건가요?Q. 국제유가가 오르면 통상 국내 시장에 반영되기까지 2-3주의 시차가 발생하는데요. 그런데 이번엔 국내 휘발유 가격가 굉장히 빠른 속도로 오르고 있습니다. 이렇게 되면 실물경제에도 충격을 주지 않을까요?Q. 쿠르드족의 이란 공격을 찬성한다는 공개 발언을 했던 트럼프 대통령이 또 다시 말을 바꿨습니다. 참전을 원치 않는다는 건데요. 트럼프 대통령의 의중은 뭘까요?Q. 중동 갈등으로 국내 증시가 위아래로 출렁이는 가운데 골드만삭스가 최근 올해 코스피지수 목표치를 6400에서 7000으로 상향 조정했습니다. 그럼 아직 7천피의 꿈, 계속 갖고 있어도 될까요?Q. 트럼프 대통령은 "무조건적인 항복"을 요구하고 있고 이란도 협상을 거부하고 있는 상황입니다. 미국과 이란의 극적인 협상 가능성은 멀어졌을까요?Q. 이란이 주변 국가를 향해서 무차별적인 공격에 나서면서 분쟁이 최소 12개국으로 확대되고 있습니다. 이렇게 될 경우, 아랍에미리트, 사우디아라비아등이 미국 편에 서서 참전할 가능성도 있을까요?Q. 중동 전역으로 긴장감이 확산되는 가운데, 아랍에미리트에 실전 배치된 천궁-2가 요격률이 90%가 넘는 것으로 알려지면서 크게 주목받고 있습니다. 방산주의 시간, 이제부터 시작일까요?Q. 미군 사상자가 발생하자 미국 내에서는 “트럼프의 아들을 전쟁터로 보내라”는 여론이 등장하기도 했습니다. 시간이 갈수록 전쟁 비용과 함께 정치적 부담도 커질 텐데요. 트럼프 대통령이 출구전략을 고민하고 있을까요?Q. 중동 사태 이후 달러 원 환율도 오름세를 보이고 있는데요. 그래도 지난 4일 새벽에 있었던 1500원 돌파와 같은 공포감은 일단 진정된 걸까요?Q. 요즘 시장을 보고 있으면 일희일비를 안 할 수 없습니다. 이럴 때는 투자자들이 어떤 전략으로 시장을 접근해야 할까요?(자세한 내용은 동영상을 시청하시기 바랍니다.)당신의 제보가 뉴스로 만들어집니다.SBS Biz는 여러분의 제보를 기다리고 있습니다.홈페이지 = https://url.kr/9pghjn', NULL, 'SBS Biz', 'https://n.news.naver.com/mnews/article/374/0000496651', 'https://imgnews.pstatic.net/image/374/2026/03/09/0000496651_001_20260309133907503.png?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 13:39:07', 0, true, '2026-03-09 05:47:13.922165') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (637, '희토류 전쟁은 변신의 기회…‘자원 밸류체인 기업’으로 진화[그 회사 어때?- 포스코인터내셔널]', 'LNG서 희토류까지, 종합 에너지 기업조달·정제 등 희토류 공급망 구축 추진대미투자 흐름에 현지 합작공장 설립에너지·식량·소재 신사업에 3조 투자세상에는 기업이 참 많습니다. 다들 무얼 하는 회사일까요. 쪼개지고 합쳐지고 간판을 새로 다는 회사도 계속 생겨납니다. 새로운 사업을 시작하기도, 수년을 하던 사업을 접기도 합니다. 다이내믹한 기업의 산업 이야기를 현장 취재, 데이터 분석 등을 통해 쉽게 전달해드립니다.포스코인터내셔널은 희토류 밸류체인을 비롯해 다양한 사업을 영위하고 있다. 구동모터 사업은 친환경 영역으로 확대해 2030년 750만대까지 생산량을 늘릴 계획이다. 포스코인터내셔널의 첫 구동모터코아 시제품 [포스코인터내셔널 제공]“희토류는 이제 시장에서 사고파는 자원이 아닌, ‘전략 무기’입니다.”(최영재 포스코인터내셔널 상무)희토류 생태계를 장악하고 있는 중국에게 희토류는 가장 강력한 외교 무기이자, 미국의 약한 고리다. 미중 갈등이 최근 ‘희토류 전쟁’으로 비화한 배경이다. 미국의 관세 부과에 중국이 희토류 수출 통제로 맞서면서다. 한국을 비롯한 각국은 난데 없는 희토류 공급난을 맞닥트렸다.이런 가운데, 갈등의 핵심이자 전략 자원인 희토류에서 최근 신사업을 개척하고 있는 기업이 있다. 바로 포스코인터내셔널이다.미중 자원 전쟁 속 희토류 사업기회 포착포스코인터내셔널은 1967년 설립된 종합 상사로서, 희토류를 조달하고 공급하는 매개 역할을 맡아왔다. 지난해부터는 희토류 등 신사업을 적극 모색하면서 종합 에너지 기업으로 탈바꿈하고 있다.특히 희토류가 단순히 산업 원료를 넘어, 전략 자원으로 떠오른 시대에 맞춰 ‘희토류 밸류체인’을 구축하겠다는 게 회사의 구상이다.희토류는 자연계에 극히 드문 17가지 화학 원소를 묶어서 이르는 말이다. 이 중 네오디뮴(Nd), 이트륨(Y) 등을 합금해 만드는 대표적인 부품이 전기차 구동모터에 들어가는 영구자석이다.현재 글로벌 희토류 80% 가량이 중국에서 채굴되고 있다. 영구자석을 전 세계에서 가장 많이 생산하는 나라 역시 중국이다. 중국이 희토류 수출을 틀어쥐면 미국도 휘청일 수밖에 없는 구조다.최영재 상무는 지난달 24일 국회에서 열린 ‘핵심광물 주도형 공급망 구축 토론회’에서 “희토류 공급망 문제의 본질은 미중 패권 경쟁이라는 구조적 충돌에 있다”며 “미국은 기술과 공급망을 동맹 중심으로 재편하면서 중국 의존을 낮추려 하고, 중국은 전략 자원을 통제함으로써 글로벌 영향력을 강화하려 하고 있다”고 설명했다.미국은 중국 의존적인 구도를 깨고 ‘탈중국 희토류 공급망’을 구축하려 하고 있다. 미국은 중국 다음으로 희토류를 많이 생산하는 나라이지만, 그 규모는 7분의 1 정도로 턱없이 작다. 이 때문에 파트너가 절실한 상황이다. 포스코인터내셔널은 이런 미국과 손을 잡아 사업 기회를 모색하겠다는 방침이다.美와 손잡고 희토류 밸류체인 구축포스코인터내셔널은 미국에서 희토류 채굴 및 영구자석 생산 사업을 키워 이를 수출하고, 동시에 포스코의 친환경 구동모터 제조 자회사 포스코모빌리티솔루션 공급망에도 적용할 계획이다. 나아가 정제 기술을 통해 폐영구자석을 재활용해 다시 원료로 삼는 순환 경제도 모색하고 있다.최 상무는 “현재의 목표는 단기간 내에 자산을 확보해, 안정적인 희토류 조달 단계를 구축하고 동시에 판매처를 다변화해 ‘양적 성장’을 추진하는 것”이라고 말했다. 광산 보유 회사 및 영구자석 분리·정제 회사에 투자해 미국 내 포스코 영구자석 공장에 미국 협력사와의 합작공장을 설립한다는 계획이다.초기 투자와 파트너십은 이미 현실화돼 있다. 포스코인터내셔널은 지난해 9월 미국 소재회사 ‘리엘레멘트 테크놀로지스’와 업무협약을 맺었다. 해당 회사는 희토류를 정제해 산업용 소재로 만드는 기술을 보유하고 있다.양사 협약은 정부가 추진하는 대미 투자 프로젝트와도 연결돼 있다. 지난해 9월 열린 양사 협약식에는 이계인 포스코인터내셔널 사장을 비롯해 나성화 산업통상자원부 산업공급망정책국장과 조셉 윤 주한미국대사대리 등 정부 관계자도 참석했다. 양사는 희토류부터 영구자석까지 한번에 생산하는 최초의 미국 시설이 될 전망인데, 여기에 필요한 규제 완화 등을 한미 양국 정부가 논의할 예정이다.포스코인터내셔널의 친환경 자동차 부품 자회사인 포스코SPS 포항공장 [포스코인터내셔널 제공]내년까지 3대 신사업에 3.2조원 투입포스코인터내셔널은 ‘에너지·식량·소재’를 3대 핵심 신사업으로 추진하고 있다. 에너지 사업에선 2023년 포스코에너지와의 합병을 기점으로 액화천연가스(LNG) 탐사·생산(E&P), 수송, 저장, 발전에 이르는 밸류체인을 구축했다.현재는 전남 광양 LNG 터미널 저장 용량을 133만킬로리터(㎘)로 기존 대비 40% 이상 늘리는 증설이 진행 중이다. 2022년 인수한 호주 천연가스 기업 세넥스에너지 역시 기존 생산량 대비 60페타줄(PJ) 규모로 증산을 진행 중이다.식량 사업에는 지난 2015년 본격적으로 진출해 연간 수백만톤 규모의 곡물을 거래하고 있다. 오는 2030년까지는 연간 1000만톤의 식량을 취급한다는 목표로, 지난해 11월 인도네시아 대형 팜유 기업 기업 ‘삼푸르나 아그로’를 인수했다. 이를 포함 포스코인터내셔널이 확보하고 있는 영농 기반은 15만헥타르(ha)에 달한다.소재 부문에선 희토류 밸류체인을 비롯해 다양한 사업을 영위하고 있다. 기존 구동모터는 친환경 영역으로 확대해 2030년 750만대까지 생산량을 늘릴 계획이다. 전기차 배터리 핵심 소재인 흑연 영역도 키워, 지난해에는 매장량 세계 2위 규모인 탄자니아 흑연 광산 개발에 착수했다.포스코인터내셔널이 이같은 신사업에 지난해부터 2027년까지 투입할 예정인 자본은 총 3조 2000억원이다. 지난 2024년 발표한 기업가치 제고 계획에 따르면 구체적인 투자 내역은 ▷미얀마 가스전 4단계 개발 ▷광양 제2 LNG터미널 건설 ▷팜유 정제사업 진출 ▷인도네시아 팜농장 인수 ▷구동모터코아 생산공장 건설(멕시코·폴란드) 등이다.포스코인터내셔널의 미얀마 해상 가스전 모습.  [포스코인터내셔널 제공]“올해 신사업 결실 원년”증권가에선 포스코인터내셔널이 올해부터 본격적으로 신사업 결실을 볼 것으로 기대하고 있다.강동진 현대차증권 연구원은 “2023~2025년 영업이익이 3년간 정체했으나 올해부터 영업이익 성장 사이클에 진입하고 있다”며 “올해는 세넥스 증산 효과 및 신규 팜 농장 인수 효과가 주요 성장 동력이며, 향후 팜 원유 증산 및 광양 LNG 터미널 7, 8호기 증설 등을 통해 안정적인 성장 기조를 이어잘 전망”이라고 내다봤다.이런 실적 반전 조짐은 지난 연말부터 가시화된 분위기다. 지난해 4분기 포스코인터내셔널 영업이익은 전년 대비 83.6% 성장한 2655억원을 기록했다. 호주 세넥스 에너지 증산 및 팜 농장 영업이익이 반영된 결과다.포스코인터내셔널 관계자는 “포스코그룹차원에서 2차전지 소재와 LNG·에너지 사업, 리사이클링을 넥스트코어로 지정하고 꾸준히 지원해왔기 때문에 현재의 성과와 수익으로 이어질 수 있었다”고 강조했다.박혜원 기자', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002610489', 'https://imgnews.pstatic.net/image/016/2026/03/09/0002610489_001_20260309111412619.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 11:14:12', 0, true, '2026-03-09 05:47:13.922165') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (638, '막오른 2026 한경 스타워즈…투자 고수 ''별들의 전쟁''', '제32회 한경스타워즈 하반기 대회 개막6월26일까지 16주 진행…10개 팀 참가한경닷컴 스타워즈 홈페이지서 현황 공유사진=한경스타워즈여의도 증권가 투자 고수들이 진검승부를 펼치는 ''2026 제32회 한경스타워즈 실전투자대회(상반기)''가 9일 개막했다. 올해로 31년째를 맞은 한경스타워즈는 국내에서 가장 오래된 실전투자대회로 한국경제신문사가 주최하고 한경닷컴이 주관한다.이번 대회는 이날부터 오는 6월26일까지 16주간 진행된다. 국내 대표 증권사에서 선발된 10개 팀이 참가해 치열한 경쟁을 펼칠 예정이다.신한투자증권에선 센트럴금융센터의 10년차 PB 안지원 과장과 안준성 주임이 ''안스클럽'' 팀으로 도전에 나섰다. 상반기 반도체 대형주 중심 랠리가 이어지고 코스닥 반도체 소부장(소재·부품·장비)과 바이오 로봇 이차전지 통신장비 업종의 강세가 예상돼 관련주를 중심으로 투자에 나설 것이란 계획을 밝혔다.메리츠증권에서는 도곡WM센터 1지점의 나상하 차장이 실력 증명을 시도한다. 나 차장은 과거 9년간 지점운용형 랩어카운트 운용 경력을 보유하고 있다. 나 차장 역시 반도체와 AI데이터센터 등 핵심 산업 밸류체인(가치사슬)에 집중 투자한다는 방침이다.유안타증권에서는 골드센터 수성점 소속 이재석 부장이 참가했다. 기업 실적 상향 조정이 기대되는 반도체, 방산, 전력 업종과 시장의 주목을 받는 우주, 로봇, 바이오 업종에 주목한다는 방침이다.IM증권에서는 김명성 부산중앙WM센터 과장이 출전했다. 증시 추가 상승에 비중을 두되, 변동성 장세에 대응하는 전략을 취하겠다는 계획이다.SK증권에서는 백상철 부산금융센터 부장이 주도업종을 중심으로 한 분산투자 매매 전략을 들고 대회에 참가했다.직전 대회에서 우승팀을 배출한 현대차증권에서는 강남프리미엄PB센터의 김민분·최원석 책임매니저가 도전했다. 종목 분석으로 리스크를 관리하며 초과 수익을 추구한다는 전략이다.하나증권에선 이재찬 명동금융센터·배재원 인천지점·김응수 대전법조WM라운지 PB가 ''2배수'' 팀을 이뤄 출사표를 던졌다. 각 PB는 하나증권의 주식 코치 서비스와 사내 수익률에서 우수한 성과를 거뒀고, 경제 전문 유튜브 채널 ‘삼프로TV’ 패널로 활약한 바 있다.KB증권에서는 두 팀이 출전한다. 우선 둔촌역PB센터의 범기원 과장·김진규 대리가 ''금메달'' 팀을 구성했다. 추세추종의 원칙을 기반으로 정부 수혜가 기대되는 코스닥 시장에 중점적으로 투자한다는 계획이다.가산디지털지점에서는 조원재 차장과 최승호 대리가 ''더블호재'' 팀으로 도전에 나섰다. 리스크를 관리하며 코스닥 중심의 바이오, 인바운드 여행(외국인의 한국 여행) 관련주의 상승에 편승한다는 계획이다.내로라하는 주식 고수들이 참가하는 2026 제32회 한경스타워즈 실전투자대회는 오는 6월26일까지 열린다. 10개 팀의 투자 대상은 유가증권·코스닥시장 상장사와 상장지수펀드(ETF) 전 종목이다. 팀별 투자 원금은 5000만원이다. 가장 높은 수익률을 기록한 참가팀이 우승하며 누적 손실률이 20%를 넘으면 중도 탈락한다.대회에서 1위를 차지한 우승팀에는 상금 1000만원이 수여된다. 2위와 3위에게는 각각 상금 500만원과 300만원이 주어진다. 참가자의 실시간 매매 내역은 한경닷컴 스타워즈 홈페이지를 통해 무료로 확인할 수 있다.', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005259723', 'https://imgnews.pstatic.net/image/015/2026/03/09/0005259723_001_20260309100216760.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 10:02:16', 0, true, '2026-03-09 05:47:13.922165') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (639, '현대차證 “풀무원, 실적 개선 기대…목표가 1만6000원”', '현대차증권은 풀무원에 대해 미국과 중국 등 해외 법인 매출 성장으로 수익성 개선이 기대된다고 9일 전망했다. 그러면서 투자 의견 ‘매수(Buy)’와 목표 주가 16만원을 신규 제시했다. 전 거래일 풀무원의 종가는 1만2030원이다.풀무원 로고.(풀무원 제공)지난해 4분기 풀무원의 연결 기준 매출액은 전년 동기 대비 5% 증가한 8592억원, 영업이익은 6.6% 감소한 343억원을 기록했다.현대차증권은 국내 기업과 소비자 간 거래(B2C), 미국·중국 등 법인 실적이 견조한 흐름을 보였다고 분석했다. 다만, 풀무원 샘물 부문의 경쟁이 심화돼 일부 수익성이 감소했다고 설명했다.향후 풀무원은 식품 제조 부문에서 운영 효율이 높은 상온 사업에 집중하며 실적이 개선될 것으로 전망됐다.하희지 현대차증권 연구원은 “시장의 소비 위축 영향에도 B2C, 기업과 기업 간 거래(B2B) 신제품 판매 호조가 지속되며 성장이 이어졌다”며 “향후 운영 효율이 높은 상온 사업 집중 육성 통한 외형 성장이 기대된다”고 분석했다.식품 서비스 유통 부문도 성장세가 지속되고 있다. 하 연구원은 “산업체 캡티브(계열사 간 내부 시장), 군급식, 신규 수주 등을 통한 견조한 매출 성장세 지속되고 있다”며 “인력·운영 효율화 통한 이익 개선세가 함께 나타나고 있다는 점이 긍정적”이라고 했다.해외 법인도 매출이 증가할 것으로 기대됐다. 지난해 미국과 중국 법인 모두 매출이 증가했다. 하 연구원은 “미국 법인은 두부 등 안정적인 성장세 지속되는 가운데 K푸드, 누들 카테고리 확장을 통해 전년 동기 대비 매출이 10% 성장했다”며 “두부, 파스타, 냉동제품 등 중국 주력 제품들이 고르게 성장하며 매출이 8% 증가했다”고 했다.다만, 일본 법인 매출은 둔화했으나 점차 수익성이 개선될 것으로 기대됐다. 하 연구원은 “일본의 경우 기존 주력 제품 매출 성장 둔화로 매출이 전년 동기 대비 10% 감소했다”며 “올해 3분기까지 현재 일본 내 5개의 공장을 3개로 통합하며 점진적인 수익성 개선이 기대된다”고 했다.', NULL, '조선비즈', 'https://n.news.naver.com/mnews/article/366/0001146801', 'https://imgnews.pstatic.net/image/366/2026/03/09/0001146801_001_20260309092308622.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 09:23:08', 0, true, '2026-03-09 05:47:13.922165') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (640, '테슬라, ‘AI 로봇 기업’으로 변신?…월가서 다시 "매수" 외치는 이유는', '[주목!e해외주식] TESLA전기차 성장 둔화 속 AI·로봇 사업이 새로운 성장 스토리모델S·X 생산 축소, 휴머노이드 로봇 ‘옵티머스’ 투자 확대“테슬라 가치 절반은 로보택시” 분석도…AI·자율주행 기대[이데일리 신하연 기자] 미국의 전기차 업체 테슬라(티커명 TSLA)가 자율주행과 휴머노이드 로봇을 중심으로 ‘AI 플랫폼 기업’으로의 변신을 가속화하고 있다는 분석이 나오면서 월가에서도 투자 의견이 다시 긍정적으로 바뀌고 있다. 전기차 시장 성장 둔화로 단기 실적 압박이 이어지고 있지만, 로보택시와 로봇 사업이 새로운 성장 스토리로 부상하고 있다는 평가다.일론 머스크 테슬라 최고경영자(CEO). (사진=연합뉴스)최근 뱅크오브아메리카(BoA)가 테슬라에 대한 분석을 재개하며 투자의견 ‘매수(Buy)’와 목표주가 460달러를 제시했다. 전거래일인 현지시간 5일 기준 테슬라 주가는 405.55달러다.BoA 분석가 알렉산더 페리는 보고서를 통해 “우리는 테슬라를 로보택시 선두 주자로 보고 있다”며 “테슬라가 새로운 이동 시대에서 가장 중요한 변혁의 주체가 될 것”이라고 언급했다.특히 테슬라가 단순한 전기차 제조업체를 넘어 자율주행 소프트웨어와 로봇 기술을 기반으로 한 AI 플랫폼 기업으로 전환하고 있다고 평가했다. 특히 자율주행 기반 모빌리티 서비스인 로보택시 사업의 잠재력을 높게 보며 “테슬라 기업가치의 상당 부분이 로보택시에서 창출될 것”이라고 분석했다.실제로 테슬라의 사업 전략은 이러한 방향으로 이동하는 모습이다. 고가 차량인 모델S와 모델X 생산을 중단하고 생산라인 일부를 휴머노이드 로봇 ‘옵티머스(Optimus)’ 개발과 생산에 활용하는 등 구조 전환을 추진하고 있다.지난 1월 실적발표를 통해 자율주행과 휴머노이드 로봇 중심의 ‘피지컬 AI’ 기업으로의 전환을 발표했다. 올해 1분기 중 휴머노이드 신모델 ‘옵티머스 V3’를 출시하고, 이르면 내년부터 일반 소비자에게 판매할 계획이다.장문영 현대차증권 연구원은 “모델 S·X 생산 중단 결정은 단순한 라인업 조정이 아니라 하드웨어 중심 성장 전략에서 벗어나 자율주행·소프트웨어 중심 기업으로 재편하겠다는 전략적 선택으로 해석된다”며 “FSD(완전자율주행) 구독 모델 확대 역시 차량 판매 중심 구조에서 반복 수익 기반 소프트웨어 모델로 전환하는 과정”이라고 설명했다.이처럼 테슬라의 장기 성장 스토리는 자율주행과 로봇으로 요약된다. 자율주행 소프트웨어 FSD는 월 구독 방식으로 판매되며 향후 차량 판매와 별도로 지속적인 수익을 창출할 수 있는 구조다. 여기에 자율주행 차량을 기반으로 한 로보택시 서비스가 본격화되면 테슬라는 차량 제조사를 넘어 모빌리티 플랫폼 기업으로 자리 잡을 수 있다는 전망이 나온다.증권가에서는 특히 로보택시와 휴머노이드 로봇이 테슬라의 기업가치를 결정짓는 핵심 변수로 떠오르고 있다고 보고 있다. 임은영 삼성증권 연구원은 “2026년은 테슬라가 더 이상 전기차 업체가 아니라 로보택시와 로봇 중심 플랫폼 기업으로 변화하는 패러다임 전환기”라며 “로보택시 서비스가 확산되면 테슬라는 ‘피지컬 AI(Physical AI)’ 시장의 핵심 기업으로 자리 잡을 수 있다”고 진단했다.다만 단기적으로는 전기차 사업 환경이 녹록지 않다. 글로벌 전기차 시장 성장률이 둔화되고 가격 경쟁이 심화되면서 차량 부문 실적은 압박을 받고 있다. 실제로 테슬라의 연간 매출은 최근 성장세가 둔화되며 감소 흐름을 보인 바 있다. 지난해 연간 기준 매출은 전년 대비 3% 감소해, 처음으로 연간 매출 감소를 기록했다.그럼에도 시장에서는 테슬라의 기술 경쟁력과 장기 성장 가능성에 주목하고 있다. 로보택시 상용화와 휴머노이드 로봇 생산 확대가 현실화될 경우 테슬라는 전기차 제조사를 넘어 AI 기반 기술 기업으로 재평가될 수 있다는 기대가 나온다.결국 투자자들의 관심은 전기차 판매보다 자율주행과 로봇 사업의 현실화 속도로 이동하는 모습이다. 로보택시와 로봇 기술이 본격적으로 상용화될 경우 테슬라가 다시 한 번 기술 기업 프리미엄을 받을 수 있을지 관심이 쏠린다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006230039', 'https://imgnews.pstatic.net/image/018/2026/03/07/0006230039_001_20260307080214756.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-07 08:02:14', 0, true, '2026-03-09 05:47:13.922165') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (641, '“호르무즈 봉쇄 장기화 수혜… SK가스 목표가 33만 원”', '[오늘의 픽] NH투자증권 “SMP 상승·LNG-LPG 차익거래 기회 확대”SK가스 울산GPS 전경. SK가스 제공호르무즈 해협 봉쇄가 장기화할 경우 SK가스가 수혜를 입을 것이라는 전망이 나왔다. 이민재 NH투자증권 연구원은 3월 9일 낸 보고서에서 “울산 GPS(LNG·LPG 겸용 가스복합발전소)의 평균 전력도매가격(SMP) 상승이 예상된다. 또 LNG와 LPG간 차익 거래로 수혜를 보는 것도 가능하다”며 SK증권 목표주가를 기존 28만 원에서 33만 원으로 상향하고 투자의견 ‘매수’를 유지했다.LNG는 세계 공급량의 약 20%가 카타르와 UAE에서 출하된다. 호르무즈 해협 봉쇄 시 타격이 크다. 특히 아시아는 카타르산 LNG 의존도가 높아 가격이급등이 불가피하다.반면 LPG는 공급원이 중동 외에도 미국·아프리카·북해 등으로 분산돼 있어 가격 상승 속도가 상대적으로 완만하다. 호르무즈 해협 봉쇄가 길어지면 LNG와 LPG 가격차가 확대될 가능성이 크고, 이는 SK가스 사업 구조에 긍정적으로 작용할 수 있다는 게 이 연구원의 분석이다.SK가스는 국내 LPG 시장 점유율 1위 기업이다. 2024년 12월부터 울산 GPS 상업 가동을 시작했다. 세계 최초로 LNG와 LPG 겸용 시스템을 장착해 연료 수급 상황에 따라 단가 변동성을 보완할 수 있는 게 장점이다. LNG 확보가 어려울 경우 LPG로 발전기를 돌려 단가를 낮추고, 미리 확보한 물량을 거래해 차익을 낼 수 있다. 이 연구원은 SK가스의 경우 중동산 LPG 수입 비중이 30% 미만이라 공급 차질도 크지 않을 것으로 봤다.이 연구원은 “러시아-우크라이나 전쟁 발발 시 울산GPS가 가동됐다면 SK가스는 2021년 하반기부터 2년간 약 1조2000억 원의 이익을 봤을 것”이라며 “LNG는 단기 대체가 어렵지만, LPG는 가능해 두 원자재 간 차익거래 기회는 호르무즈 해협 봉쇄가 장기화할수록 점차 늘어날 전망”이라고 분석했다. 3월 기준 LNG는 MMBtu(열량 단위)당 15달러, LPG는 Mt(메가톤)당 780달러로 2021년 하반기와 비슷한 수준이다.한국거래소에 따르면 3월 9일 오전 11시 17분 기준 SK가스는 전 거래일보다 6.05%(1만4000원) 오른 24만5500원에 거래됐다.*유튜브와 포털에서 각각 ‘매거진동아’와 ‘투벤저스’를 검색해 팔로잉하시면 기사 외에도 동영상 등 다채로운 투자 정보를 만나보실 수 있습니다.', NULL, '주간동아', 'https://n.news.naver.com/mnews/article/037/0000037799', 'https://imgnews.pstatic.net/image/037/2026/03/09/0000037799_001_20260309113312847.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 11:33:12', 0, true, '2026-03-09 05:47:34.678139') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (655, '우리금융 ''3조클럽'' 안착 동양·ABL생명 인수 효과', '작년 순익 3조1413억 기록이익증가율은 1%대로 저조주주환원율도 40% 못넘어우리금융그룹이 2025년 당기순이익 3조1413억원을 기록하며 2년 연속 ''3조원 클럽''을 달성했다고 6일 밝혔다. 동양생명 인수 효과로 비이자이익이 25% 증가하는 등 ''포트폴리오 다변화''에 힘입었다는 평가가 나온다.우리금융은 임종룡 회장 취임 첫해인 2023년 2조5167억원으로 출발해 2024년 3조860억원의 당기순이익을 기록한 바 있다. 지난해에도 소폭 상승하며 3조원대에 안착한 것으로 분석된다. 이는 비이자이익이 1조9266억원으로 역대 최대치를 기록한 데 힘입은 결과다. 지난해 동양·ABL생명 동시 인수로 1000억원가량의 보험손익이 반영됐다.다만 공정거래위원회가 주택담보대출비율(LTV) 담합 혐의로 부과한 과징금 515억원 전액이 지난해 충당금으로 반영되면서 실제 순익 증가는 전년 대비 1.8% 수준에 그쳤다. KB금융·신한금융·하나금융 등 다른 3개 지주사의 평균 순익 증가율이 11.3%인 것과 비교하면 크게 낮은 수치다.지난해 우리금융 자본건전성이 대폭 개선된 점은 성과로 꼽힌다. 건전성 핵심 지표인 보통주자본(CET1)비율은 12.9%로 2024년(12.1%) 대비 0.8%포인트 올랐다.강화된 자본비율을 바탕으로 역대 최대 규모의 주주환원도 실시한다. 누적 배당금이 주당 1360원으로 책정됨에 따라 총 주주환원 금액은 1조1489억원이다. 우리금융의 지난해 실질 주주환원율은 39.8%로 전년도(34.7%)보다 증가했지만 40%를 넘지는 못했다. KB(52.4%), 신한(50.2%), 하나(46.8%) 등 다른 지주사들이 50%를 넘겼거나 육박한 것에 비하면 상대적으로 저조하다.우리금융은 올해 주주환원 여력을 추가 확대할 계획이다. 우선 자사주 매입·소각 규모를 전년(1500억원) 대비 약 33% 증가한 2000억원으로 늘린다.[안정훈 기자]', NULL, '매일경제', 'https://n.news.naver.com/mnews/article/009/0005633736', 'https://imgnews.pstatic.net/image/009/2026/02/06/0005633736_001_20260206200223015.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-06 17:48:40', 0, true, '2026-03-09 05:47:54.591236') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (642, '한투운용 "''한국투자테크펀드'', 테크 펀드 중 연초 이후 수익률 1위"', '집중·선제적·선별·알파 추구 등 4가지 전략 구사한국투자신탁운용한국투자신탁운용은 한국투자테크펀드의 연초 이후 수익률이 테크 펀드 중 가장 높게 나타났다고 9일 밝혔다.한국투자테크펀드는 한국투자신탁운용이 지난 2005년 최초 설정한 모자형 상품으로 2개의 자펀드(한국투자테크펀드1호·한국투자테크펀드2호)로 운용 중이다. 에프앤가이드에 따르면 전 영업일(6일) 기준 테크 펀드 중 연초 이후 수익률 1위는 한국투자테크펀드2호, 2위는 한국투자테크펀드1호로 나타났다.테크 펀드는 상품명에 ''테크'' 키워드가 들어간 펀드(ETF 포함)를 기준으로 분류됐으며 현재 114개 펀드(클래스펀드 기준 495개)가 설정돼 있다.클래스펀드 기준으로 볼 때 수익률 상위권을 모두 차지했다. 한국투자테크펀드1호와 2호는 각각 7개와 3개 클래스가 설정돼 있는데, 2종 합산 10개 클래스가 테크 펀드 클래스 495개 중 연초 이후 수익률 1위부터 10위까지 석권했다.431개 중 가장 높은 수익률은 한국투자테크펀드 2호의 C-W클래스(53.82%)이고 2호 펀드의 S클래스(53.78%)와 C5클래스(53.63%)가 뒤를 이었다. 4위부터 10위는 한국투자테크펀드 1호의 7개 클래스가 이름을 올렸다(53.33~53.48%). 최근 1년 및 3년 수익률은 170.19%와 159.80%, 설정 이후 수익률은 132.77%로 집계됐다.한국투자테크펀드는 1호와 2호 모두 곽찬 기업분석부 부장이 책임 운용을 맡고 있다. 곽 부장은 정보기술(IT) 애널리스트 출신 운용역으로 2010년부터 16년간 테크 섹터 분석과 관련 펀드 운용을 맡고 있다.곽 부장은 16년 경력의 테크 분석 전문성에 4가지 핵심 운용 전략을 가미해 한국투자테크펀드를 운용 중이다. 4가지 핵심 전략은 ▲집중 투자(테크 섹터 내 고성장 산업에 집중) ▲선제적 투자(반도체 업황 턴어라운드를 포착해 선제적인 비중 확대) ▲선별 투자(구조적 기술변화 수혜 종목 편입) ▲알파 추구(서브섹터 및 저베타 종목 편입을 통한 IT 침체기 등 대응)을 말한다.한국투자테크펀드 포트폴리오 상위권에는 ▲삼성전자 ▲SK하이닉스 ▲원익QnC ▲삼성전기 ▲원익IPS ▲한솔케미칼 등이 편입돼 있다. 한국투자테크펀드는 KB증권, SK증권, 대신증권, 신한투자증권, 우리은행, 유안타증권, 한국투자증권, 한화투자증권, 한국포스증권 등을 통해 가입 가능하다.곽 부장은 "한국투자테크펀드는 메모리·반도체 소부장 등 핵심 분야를 중심으로 전자부품이나 모바일 등 시장 트렌드를 반영한 서브섹터까지 투자 가능한 상품"이라며 "알파 수익률을 위해 서브 섹터 내 구조적 변화에 빠르게 대응하고 있고 이를 위해 기업 탐방 및 리서치를 지속 중"이라고 설명했다.', NULL, '매일신문', 'https://n.news.naver.com/mnews/article/088/0001000046', 'https://imgnews.pstatic.net/image/088/2026/03/09/0001000046_001_20260309104621824.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 10:46:21', 0, true, '2026-03-09 05:47:34.678139') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (643, '유가 급등에 코스피 6% 하락 출발...5000피 위협', '유가 100달러 돌파, 인플레이션 우려까지 겹쳐이란전쟁에 따른 유가 급등에 증시가 다시 휘청이고 있다. 9일 한국거래소에 따르면 코스피 지수는 전거래일 대비 319.5포인트(5.04%) 하락한 5265.37로 출발하며 가파른 하락세를 보이고 있다.오전 9시 15분 현재 삼성전자는 8.24% 떨어진 17만2800원, SK하이닉스는 8.12% 내린 84만9000원에 거래된다. 한미반도체는 9.45%, 현대차는 9.58% 급락하며 장을 시작하고 있다.장 초반 주요 종목 하락에 코스피는 오전 9시 6분 매도사이드카도 발동하며 5분간 프로그램매매 매도호가 효력이 정지되기도 했다. 3월에만 벌써 세번 째 사이드카다.코스닥도 전거래일보다 58.19포인트(5.04%) 내린 1096.48로 장을 시작했다. 에코프로(-5.59%), 알테오젠(-4.96%), 삼천당제약(-7.07%, 레인보우로보틱스(-7.69%) 등 시가총액 상위 종목 대부분이 파란불로 장을 열고 있다.전쟁공포와 경기침체라는 대형 악재가 동시에 증시에 영향을 주고 있다. 국제 유가가 배럴당 100달러를 돌파해 ''오일쇼크'' 공포가 확산하고 있고, 미국과 이란의 전쟁이 장기화할 가능성까지 나오면서 인플레이션을 자극할 거라는 우려에 투자심리가 얼어붙은 상황이다.황지우 SK증권 연구원은 "중동 리스크에 따른 유가급등과 일부 AI인 인프라 프로젝트 조정이 아직 추세 훼손을 단정할 단계는 아니지만, 국내외 주도주의 밸류에이션 민감도를 높이는 변수가 될 것"이라고 말했다.', NULL, '비즈워치', 'https://n.news.naver.com/mnews/article/648/0000045059', 'https://imgnews.pstatic.net/image/648/2026/03/09/0000045059_001_20260309093508501.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 09:35:08', 0, true, '2026-03-09 05:47:34.678139') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (644, '[유가 100달러]호르무즈 봉쇄에 해운 ‘운임 쇼크’ 현실화', 'LNG선 스팟 약 6배 급등..VLCC는 ''사상 최고''원유탱커 新 대규모 발주 사이클 촉발 기대북미 LNG 프로젝트 최종투자결정 가능성..韓 조선 3사 수혜한화오션의 LNG운반선 레브레사호. 한화오션 제공[파이낸셜뉴스]이란의 호르무즈 해협 봉쇄로 인한 ''운임 쇼크''가 현실화됐다. LNG(액화천연가스)선 스팟(단발성) 요금은 일주일 만에 약 6배 급등했고, 초대형원유운반선(VLCC) 스팟 요금도 ''사상 최고치''를 경신했다. 국내 선사들은 선종(탱커·LNG·컨테이너)과 항로 노출도에 따라 희비가 엇갈리는 양상이다.9일 업계에 따르면 174K급 LNG선 스팟 요금은 2월 27일 3만5500달러/일에서 3월 6일 20만5000달러/일로 약 6배 급등했다. VLCC 스팟 운임은 사실상 사상 최고치로 평가됐다. 봉쇄 이전 일평균 약 150척이 통과하던 호르무즈가 봉쇄 이후 통과량이 90% 이상 급감했고, 페르시아만 내 3230척(글로벌 운항선 1129척)이 체류하며 총톤수 기준 글로벌 선복량의 약 2%, 원유탱커 선복량의 6%가 사실상 시장에서 잠긴 영향이다.운임 급등이 단기 이벤트로 끝나지 않을 수 있다는 해석도 나온다. 봉쇄가 길어지면 높은 레벨의 탱커·LNGC 운임 및 용선료가 유지될 가능성이 높고, 과거 컨테이너선에서 ‘병목발 운임 급등→신조 발주 사이클’이 재현될 수 있다는 시각도 있다.한승한 한승한 SK증권 연구원은 "호르무즈 해협 봉쇄가 장기화될 경우 높은 레벨의 원유탱커, LNGC 운임 및 용선료가 유지될 것"이라며 "호르무즈 해협 봉쇄 후 기존 페르시아만을 통과하는 원유 수송 항로가 막히면서 사우디아라비아 홍해 연안 항구인 얀부항에서 원유를 선적해 아시아로 수송하고 있다"고 밝혔다.그러면서 "다만 호르무즈를 우회할 수 있는 사우디아라비아 이스트-웨스트 파이프라인은 자국 수요를 제외하면 약 5mbpd로 추정된다"면서 "아랍에미리트 아부다비, 이라크-터키 파이프라인을 합쳐도 7mbpd에 불과하다. 기존 호르무즈를 통해 운송되던 원유는 약 20mbpd다. 결과적으로 약 13mbpd가 병목에 걸리는 구조가 만들어졌다"고 말했다.카타르 국영 에너지기업 카타르에너지(QE)가 이란의 드론 공격으로 라스라판 액화천연가스(LNG) 시설의 가동을 중단한 것도 LNG 밸류체인 전반의 불확실성을 키운 요인으로 꼽힌다.한 연구원은 "호르무즈 해협 봉쇄가 장기화될 경우 높은 노후선대 비중 및 잠재적인 친환경 교체 수요 기반의 원유탱커 시장에서도 새로운 대규모 발주 사이클이 촉발될 가능성이 높다"며 "기존 카타르 LNG 수입 의존도가 높았던 국가들이 미국 LNG 수입으로 전환하게 될 가능성이 높아지면서, 톤-마일 증가 효과와 동시에 곧 북미 LNG 프로젝트들의 FID(최종투자결정) 가능성을 확대시킬 것"이라고 밝혔다. 이에 "북미 LNGC 대규모 물량 수주를 기다리고 있는 국내 조선 3사에게 수주 실적 및 선가 측면 모두에서 수혜가 될 전망"이라고 덧붙였다.앞서 팬오션은 카타르에너지 장기계약 수행을 위한 친환경 LNG선 3척 명명식을 공지하며 프로젝트 수행을 공식화한 바 있다. 카타르 프로젝트는 KGL이 카타르에너지와 장기대선을 맺고 국내 선사들이 KGL과 다시 계약하는 ‘백투백’ 구조로 알려졌다. 운임 급등이 실적에 즉시 반영되기보다는 보험료·지연·대체항만 비용의 귀속과 재계약 단가가 핵심 변수가 될 공산이 크다.현대LNG해운은 중동 리스크가 장기화할수록 ‘추가 용선·재계약 단가’가 관전 포인트다. 2023년 LNGBV 1척·VLGC 5척 인도, 2024년 LNGC 7척 취항 등 LNG 전용선사로서 선대 확장 국면이 뚜렷한 상황이기 때문이다.고려해운 등 역내 정기선사는 호르무즈 직격 노출은 상대적으로 낮지만 ‘무풍지대’는 아니라는 지적이다. 유가·보험료·환적 지연이 비용으로 전이될 수 있다. 중동발 비용 충격이 역내 네트워크로 확산될 경우 운항 계획과 비용 관리가 관건이 될 수 있다.HMM은 호르무즈 인근 운항 선박을 두바이항에 정박시키는 등 대피 조치에 나섰고, 정부·업계도 위험구역 선박 대피와 함께 해협 내 항만 대신 대체 항만 하역을 검토하고 있다고 전해졌다. 컨테이너는 운임보다 스케줄(정시성)과 보험·보안 비용이 손익에 먼저 반영되는 구조인 만큼, ‘대피=손익관리’라는 평가가 나온다.', NULL, '파이낸셜뉴스', 'https://n.news.naver.com/mnews/article/014/0005488004', 'https://imgnews.pstatic.net/image/014/2026/03/09/0005488004_001_20260309083212707.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 08:32:12', 0, true, '2026-03-09 05:47:34.678139') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (645, '삼전닉스, 개인은 사고 외인은 팔았다…반도체株 향방은', '개인 순매수 1~2위 차지…외인은 7조 이상 매도중동 사태에 국장 ‘출렁’…삼전·하이닉스에도 제동반도체주 전망 여전히 ‘맑음’…“펀더멘털에 주목”국내 주식시장이 중동 사태 여파로 크게 흔들린 가운데 삼성전자와 SK하이닉스에 대한 개인과 외국인 투자자의 베팅 전략이 정반대로 나타났다. ⓒAI 이미지[데일리안 = 서진주 기자] ‘국내 반도체 투톱’인 삼성전자와 SK하이닉스에 대한 투자자별 전략이 엇갈리고 있다.개인은 추가 상승을 기대하며 적극 베팅한 반면 외국인은 정반대 행보를 보이고 있다.9일 한국거래소에 따르면 지난주(3~6일) 개인 투자자들은 삼성전자를 5조2723억원어치 순매수했다. 이에 삼성전자는 개인 투자자의 순매수 1위 종목에 이름을 올렸다.같은 기간 개인 순매수 2위 종목은 SK하이닉스로, 개인 투자자들은 SK하이닉스를 2조848억원 사들였다.반면 외국인 투자자들은 삼성전자와 SK하이닉스를 각각 5조4108억원, 1조9303억원 순매도했다. 두 종목에서만 7조원 이상의 주식을 팔아 치운 셈이다.그동안 코스피 상승을 주도한 삼성전자와 SK하이닉스를 두고 개인과 외국인의 투자 전략이 상반되게 나타난 것이다.삼성전자와 SK하이닉스는 연초 이후 신고가를 연일 경신하며 ‘22만전자’, ‘100만닉스’ 타이틀을 거머 쥐었다.하지만 중동 전쟁 여파로 국내 증시가 천국과 지옥을 오간 지난주에는 ‘17만전자’, ‘80만닉스’ 수준까지 밀려났다.조준기 SK증권 연구원은 “조정 국면에서는 가장 많이 오른 업종에 대한 매도 압력이 강하게 나타나는 것이 일반적”이라며 “지정학적 리스크와 수급에 대해서는 예측보다는 대응의 영역이기에 섣부른 예측은 금물”이라고 당부했다.업계에서는 반도체주 전망에 대해 여전히 긍정적인 견해를 제시하고 있다.증시에 영향을 미치는 리스크 요인이 완화될수록 펀더멘털(기초체력)에 회귀할 가능성이 높은 만큼, 증시 변동성 장세에서 펀더멘털에 집중해야 한다는 설명이다.그러면서 국내 증시의 상승 원동력이 반도체를 중심으로 한 이익 성장이라는 점과 반도체 1분기 실적에 대한 관심이 확대되면서 레벨 만회 시도가 나타날 가능성에 주목했다.미국 내 AI 투자 사이클이 유효하다는 점도 근거로 제시했다.황승택 하나증권 리서치센터장은 “중장기적 측면에서 국내 반도체 수출 호조와 실적 기대감이 계속되면서 상승 추세가 지속될 것”이라며 “국내 증시의 밸류에이션에 긍정적인 영향을 줄 수 있는 3차 상법개정안도 호재로 작용할 것”이라고 진단했다.김병연 NH투자증권 투자전략부 이사는 “미국·이란 전쟁의 장기전 우려에도 국내 기업이익은 상승하고 있다”며 “AI 인프라 병목 인플레 상황에 추가적인 물류 병목 인플레는 가격 전가력이 강한 반도체 가격을 추가 상승시키는 요인”이라고 분석했다.', NULL, '데일리안', 'https://n.news.naver.com/mnews/article/119/0003066585', 'https://imgnews.pstatic.net/image/119/2026/03/09/0003066585_001_20260309070412332.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 07:04:12', 0, true, '2026-03-09 05:47:34.678139') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (646, '[주末머니]이차전지 ''캐즘''?…나홀로 고실적 보여준 ''이 기업''', '전고체 배터리 수주 속도 가장 빠를 전망주주환원도 적극적…동종업계 대비 저평가이차전지 장비 업체 엠플러스가 글로벌 배터리 업황 둔화 속에서도 두드러진 실적 성장과 수익성 개선을 기록하며 업계에서 ''군계일학''으로 평가받고 있다.엠플러스는 지난해 매출액 1842억원, 영업이익 246억원을 기록했다고 밝혔다. 전년 대비 매출액은 43.0%, 영업이익은 143.4% 증가한 수치다.글로벌 이차전지 시장이 숨 고르기 국면에 들어서면서 신규 장비 발주는 줄어드는 흐름이 이어졌지만, 기존 납품 장비의 유지보수와 고객사의 생산 라인 조정 등을 통해 외형 성장을 이어갔다. 특히 전기차(EV)에서 에너지저장장치(ESS)로 생산 라인을 전환하는 과정에서 관련 장비 수요가 발생하면서 실적 개선에 힘을 보탰다. 여기에 제품 라인 다변화와 고수익성 장비 중심의 수주 전략이 더해지며 수익성 개선에도 성공했다.나승두 SK증권 연구원은 "엠플러스는 지난해 글로벌 이차전지 장비 업체들 가운데 가장 뚜렷한 실적 개선세와 높은 수익성을 보였다"며 "제품 라인 다변화 추진을 통해 사업 영역을 확대함은 물론 고수익성 장비 수주에 집중하면서 수익성 개선에도 성공했다"고 설명했다.엠플러스의 경쟁력은 높은 생산 효율성에서 비롯된다는 평가다. 회사는 90%를 웃도는 종합 설비 효율(OEE)을 기반으로 파우치형과 각형 이차전지 조립 전 공정 장비를 턴키 방식으로 공급하고 있으며, 세계 최고 수준의 생산 속도와 정확도를 확보하고 있다.나 연구원은 "엠플러스는 파우치형·각형 이차전지 조립 전 공정 장비를 턴키로 공급함은 물론 세계 최고 수준의 생산 속도와 정확성을 자랑한다"며 "이를 바탕으로 전극 공정까지 사업 영역 확대를 추진하고 있다"고 말했다.차세대 배터리 분야로의 확장도 눈에 띈다. 엠플러스는 전고체 배터리 장비 시장에도 본격적으로 진출하고 있다. 2024년에는 미국 전고체 배터리 전문 업체로부터, 2025년에는 국내 업체로부터 전고체 배터리 조립 라인을 수주했다.그는 "아직은 연구(Pilot) 단계 수준의 수주지만 향후 수주 성장 속도는 가장 빠를 것으로 기대된다"며 "전고체 배터리가 높은 에너지 밀도 및 안전성 등 장점을 바탕으로 휴머노이드 로봇 등에 빠르게 확대 적용될 것으로 예상되기 때문"이라고 분석했다.실적 개선을 기반으로 한 적극적인 주주환원 정책도 투자자들의 관심을 끌고 있다. 엠플러스는 지난해 3월 기업가치 제고 계획을 공시하면서 주주환원 정책을 공개했으며, 6월에는 지속가능경영보고서(ESG 보고서)를 발간해 공시했다.그는 "10% 이상의 배당 성향을 유지하겠다는 주주환원 정책을 바탕으로 추정하면 기존 주당 100원의 배당금은 최소 주당 160원 수준까지 커질 가능성이 높다"고 설명했다. 또한 회사는 만기 전 전환사채 취득 및 소각, 자사주 소각에도 적극적으로 나서며 주주가치 제고 행보를 이어가고 있다.나 연구원은 "대부분의 이차전지 장비 업체들이 적자를 기록 중인 가운데 흑자를 기록 중인 전극·조립 공정 동종 기업들은 평균 12~22배 수준의 주가수익비율(PER)을 기록 중"이라며 "올해 예상 실적 기준 PER 7배 수준에 불과한 엠플러스의 저평가 매력에 주목한다"고 말했다.', NULL, '아시아경제', 'https://n.news.naver.com/mnews/article/277/0005730849', 'https://imgnews.pstatic.net/image/277/2026/03/08/0005730849_001_20260308094016937.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-08 09:39:00', 0, true, '2026-03-09 05:47:34.678139') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (647, 'K변압기 765kV 수주 랠리 더 가팔라진다..증설도 잇따라', '공급자 우위 시장 계속 이어져…HD현대일렉·효성중공업 북미 생산능력 확대효성중공업이 2025년 영국 스코틀랜드에 설치한 초고압변압기/사진=뉴스1국내 전력기기 기업들의 765kV(킬로볼트) 초고압 변압기 수주 랠리가 더욱 가팔라질 것으로 보인다. 실제로 미국에서 승인된 765kV 신규 송전망 규모는 6360마일(약 1만200㎞)에 달하는 것으로 전해졌다. 변전소 18~30개가 필요한 규모로 765kV 변압기 약 200대 내외의 잠재 수요가 예상된다. 용량이나 세부 설계에 따라 가격 편차가 있지만 대당 70억~140억원 수준을 적용하면 765kV 변압기만으로 수조원 규모의 시장이 형성될 전망이다.8일 관련업계에 따르면 지난 1~2월 국내 변압기 수출금액은 4억500만달러로 전년 동기 대비 6% 증가했다. 수출 단가는 같은 기간 톤당 1만3900달러로 4% 늘었다. 특히 북미 시장을 중심으로 초고압 변압기가 이를 견인한 것으로 분석됐다. 업계 관계자는 "생산능력 한계로 모든 주문을 소화하지 못하는 상황"이라며 "올해 들어서도 공급자 우위 시장이 이어지고 있다"고 강조했다.이에 국내 주요 기업들은 765kV 초고압 변압기 특수를 톡톡히 누리고 있다. 지난해 HD현대일렉트릭과 효성중공업 모두 765kV 변압기 판매가 늘면서 수익성이 크게 개선됐다. 올해도 마찬가지다.북미에서 765kV 변압기를 공급할 수 있는 기업은 HD현대일렉트릭과 효성중공업을 포함해 5개 업체에 불과하다. 미국의 대형 전력회사 AEP도 지난해 4분기 실적 컨퍼런스콜에서 "4분기 계약부하가 56GW(기가와트)로 3분기(28GW) 대비 2배 가까이 증가했다"며 "대부분이 데이터센터 수요이며 2030년까지 크게 늘어날 것"이라고 밝혔다.국내 기업들도 현지 생산능력 확대에 속도를 내고 있다. HD현대일렉트릭은 미국 앨라배마에 위치한 북미 생산법인 제2공장을 조성한다. 2만9000㎡(약 8800평) 규모이며 내년 4월 준공될 예정이다. 초고압 변압기 생산능력을 50% 확대함과 동시에 765kV 시험·생산 설비를 구축한다. 효성중공업 역시 2024년 발표한 미국 멤피스 공장 2차 증설을 올해 완료하고, 지난해 발표한 3차 증설도 본격화할 계획이다.업계에 따르면 765kV 변압기는 전용 생산라인 없이 기존 공장의 생산 슬롯(장비·부품)을 활용할 수 있다. 이에 따라 가격과 마진이 높은 765kV 변압기가 우선 배정되면 기존 주력 제품이던 300~500kV 변압기도 공급이 줄어 가격 상승으로 이어질 수 있다.국내 기업들의 경쟁력은 충분하다는 평가다. HD현대일렉트릭과 효성중공업은 모두 1990년대부터 765kV 변압기 개발·공급에 나섰다. HD현대일렉트릭은 최근 미국 송전사와 765kV 변압기 및 리액터 29대 공급 계약을 체결했다. 효성중공업도 한국과 미국, 인도 등에 160대 이상 공급한 실적을 보유하고 있다.나민식 SK증권 연구원은 "지난해부터 AI 데이터센터 증가로 발전소 건설 자체가 늘고 있다"며 "발전소 건설이 급증했다는 것은 올해 대규모 전력기기 발주가 이어질 가능성이 높다는 의미"라고 말했다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005326736', 'https://imgnews.pstatic.net/image/008/2026/03/08/0005326736_001_20260308092016573.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-08 09:20:00', 0, true, '2026-03-09 05:47:34.678139') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (648, '임종룡 우리금융 회장 “핵심 직무 내 여성 리더 역할 확대”', '‘그룹 여성리더 네트워킹 데이’ 개최“다양성은 성장 직결되는 필수 전략”인재 발굴·육성 프로그램 적극 독려임종룡(앞줄 왼쪽 열 번째) 우리금융그룹 회장이 지난 6일 서울 중구 우리은행 본점에서 열린 ‘2026 우리금융그룹 여성리더 네트워킹 데이’에서 참석자들과 기념촬영을 하고 있다. [우리금융 제공][헤럴드경제=김은희 기자] 임종룡 우리금융그룹 회장이 ‘세계 여성의 날’을 맞아 전 그룹사 여성 리더와 만나 “핵심 직무 내 여성 리더의 역할을 확대할 수 있도록 제도를 지속 정비하겠다”고 약속했다.9일 우리금융에 따르면 임종룡 회장은 지난 6일 서울 중구 우리은행 본점에서 열린 ‘여성리더 네트워킹 데이’에 참석해 “다양성은 기업의 지속 성장과 직결되는 필수 전략”이라며 이같이 밝혔다.이번 행사는 ‘연결과 성장, 미래를 이끄는 여성 리더십’을 주제로 다양성을 존중하는 문화를 확산하고 국내외 ESG(환경·사회·지배구조) 평가에 대응하기 위해 마련됐다. 지난해 편입한 동양·ABL생명을 포함해 17개 전 그룹사 본부부서 여성 부장 80여명이 참석해 상호 성장을 위한 파트너십을 다졌다.임 회장은 이 자리에서 “서로 든든한 조력자가 돼 그룹 내 시너지를 더욱 강화해 달라”고 당부했다.초청 특강에서는 박명신 우리카드 부사장이 함께 성장하는 코칭 리더십을 주제로 강연을 펼쳤다. 박 부사장은 자신의 커리어 패스와 성장 과정의 고민을 진솔하게 나누며 조직 내 리더십과 소통·피드백 균형의 중요성을 전달했다.이어 최지은 메타(Meta) 아시아태평양 본부 전무가 외부 초청 강사로 나서 ‘링 위로 올라온 사람만이 기회를 갖는다’는 역동적인 게임의 법칙을 소개했다. 최 전무는 성과를 알리기 위한 스토리텔링과 영향력 확장에 대한 구체적인 조언을 건네며 글로벌 환경에서 쌓아온 생생한 리더십 경험을 공유했다.우리금융은 이번 행사로 다진 연대를 바탕으로 그룹사별 인재 발굴과 육성 프로그램 연계를 적극 독려할 방침이다. 나아가 주요 그룹사는 여성 리더 후보군 확대를 위한 별도의 특화 과정을 운영하며 지속가능한 성장을 이끌어갈 계획이다.', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002610246', 'https://imgnews.pstatic.net/image/016/2026/03/09/0002610246_001_20260309081513655.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 08:15:13', 0, true, '2026-03-09 05:47:54.591236') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (649, 'KB·신한 이어 우리금융까지…''공룡자본'' 잇단 전북행, 왜', '서울 중구 우리금융그룹 본사 전경 /사진 제공=우리금융전북특별자치도가 국내 금융그룹의 전략 거점으로 떠오르고 있다. KB금융과 신한금융에 이어 우리금융까지 가세하면서 국민연금공단 기금운용본부가 자리 잡은 전주를 둘러싼 자산운용 허브 경쟁이 본격화하는 분위기다.26일 금융권에 따르면 우리금융은 전북을 자본시장 전진기지로 삼겠다는 계획을 내놨다. 핵심은 자산운용 기능의 현지화다. 우리금융은 현재 200여명 수준인 전주 지역 근무 인력을 계열사 추가 진출을 거쳐 300명 이상으로 늘린다는 목표를 세웠다. 특히 자본시장부문 계열사인 우리자산운용 전주사무소를 개설해 국민연금과의 접점을 넓히고 현지 채용과 인턴십 운영으로 자본시장 인력을 키울 계획이다.우리은행도 전북BIZ프라임센터를 신설하며 이러한 전략에 발맞춘다. 전북 지역 기업을 전담 지원하기 위해서다. 우리은행은 첨단전략산업 및 관련 밸류체인의 성장 발전 지원에 역량을 집중할 방침이다.보험과 채권관리 계열사도 전주에 거점을 둔다. 동양·ABL생명보험은 현지 설계사 채용을 늘려 지역 밀착 영업을 강화한다. 우리신용정보는 전주영업소를 신설해 계열사와 지역 금융사의 채권관리 수요를 흡수한다. 금융그룹 차원에서 은행·운용·보험·신용관리 기능을 한 축에 묶는 구조다.이에 더해 우리금융은 2030년까지 전북 중소기업과 소상공인에 1조6000억원 규모의 자금을 공급한다는 계획이다. 여신 공급에 그치지 않고 벤처 창업지원 프로그램 ''디노랩''을 활용해 스타트업 기업의 성장 단계에 맞춘 투자 및 금융 서비스도 제공한다. 자본시장 기능과 기업금융을 함께 묶어 지역 내 투자와 고용으로 이어지는 구조를 만들겠다는 계산이다.전북금융중심지를 둘러싼 움직임은 우리금융에 그치지 않는다. 앞서 KB금융그룹과 신한금융그룹 역시 전북혁신도시를 자산운용 허브로 육성하겠다는 전략을 밝혔다. 자산운용, 증권, 펀드 서비스 기능을 모아 연기금 연계 사업을 확대하겠다는 구상이다.전북 전주 국민연금공단 기금운용본부 전경 / 사진 = 국민연금배경에는 국민연금 기금운용본부가 있다. 연기금이 위치한 도시는 운용사와 금융그룹 입장에서 전략적 의미가 크다. 대체투자와 글로벌 자산 배분, 위탁운용 선정 과정에서 물리적 거리는 곧 협업 효율과 연결된다. 연기금이 앵커 투자자로 작동하면 벤처펀드와 사모펀드 시장도 함께 성장할 가능성이 있다.금융그룹 입장에서도 전주 거점은 수익 구조 다변화를 위한 선택지다. 수도권에 집중된 자본시장 기능을 일부 분산하고 연기금과의 접점을 강화해 대체투자와 공동투자 기회를 넓힐 수 있다. 자산운용 경쟁력이 그룹 가치로 이어지는 구조에서 전북 거점은 중요한 전략 기반이 될 수 있다는 평가다.그럼에도 과제는 남는다. 사무소 설치와 인력 배치만으로 생태계가 완성되지는 않기 때문이다. 실제 운용 기능과 투자 의사결정 권한을 얼마나 현지에 둘지, 전문 인력을 안정적으로 확보할 수 있을지가 관건이다.전북이 서울·부산에 이어 제3 금융중심지로 지정될지도 변수다. 지정 여부에 따라 자산운용 특화 도시라는 성격이 더욱 뚜렷해질 수 있다. 연기금을 품은 전주가 혁신도시 단계를 넘어 자산운용과 자본시장의 또 다른 축으로 올라설지 주목된다.우리금융 관계자는 "세계 3대 연기금 가운데 하나인 국민연금이 위치한 전주에 자본시장 거점을 확보하는 것은 우리금융의 자본시장 경쟁력을 획기적으로 강화하는 계기"라며 "전북에 금융 인프라를 구축해 지역균형발전이라는 시대적 과제에 부응하고 지역경제 활성화를 위해 더 큰 노력을 기울이겠다"고 말했다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000079976', 'https://imgnews.pstatic.net/image/293/2026/02/26/0000079976_001_20260226150706469.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-26 15:07:06', 0, true, '2026-03-09 05:47:54.591236') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (650, '보험 팔아 이익? 옛말…삼성생명만 웃었다', '손보 6개사 순익 11.1%·생보 6개사 1.8% 줄어투자손익이 실적 방어…현대해상은 둘다 부진본업 잘한 삼성생명…보험손익 79.8% 급증지난해 보험업계가 본업 수익성 악화 직격탄을 맞았다. 손해보험사들은 장기보험 예실차 손실과 자동차보험 적자가 겹치며 순이익이 줄었다. 생명보험업계에서는 삼성생명이 독주 체제를 지속한 반면, 중견사들은 역성장을 면치 못했다.25일 보험업계에 따르면 주요 손해보험사 6곳(삼성화재·메리츠화재·DB손보·KB손보·현대해상·한화손보)의 합산 순이익은 6조9346억원으로 전년 대비 11.1% 감소했다. 생명보험사 6곳(삼성·한화·신한라이프·KB라이프·동양·미래에셋생명)의 순이익은 4조1461억원으로 전년보다 1.8% 줄었다.예실차·자동차보험 적자에 손보사 ''쇼크''삼성화재는 연결기준 지배주주지분 순이익 2조183억원(-2.7%)으로 소폭 감소했다. DB손해보험은 연결기준 순이익 1조5349억원(-13.4%)으로 두자릿수 감소했다. 메리츠화재는 별도기준 순이익 1조6810억원(-1.7%), KB손해보험은 그룹연결 지배기주주순이익 7782억원(-7.3%)으로 집계됐다.특히 현대해상은 연결기준 순이익 5611억원(-45.6%)으로 가장 큰 감소 폭을 보였다. 한화손해보험 역시 별도기 순이익 3611억원(-5.6%)으로 줄었다.손보업계 실적 둔화의 핵심은 예실차와 자동차보험이었다. 대부분 보험사에서 장기보험 보험금예실차가 발생했다. 자동차보험은 수년간 이어진 보험료 인하 압박과 손해율 상승이 맞물리며 적자로 돌아섰다.삼성화재는 2024년 1464억원 흑자였던 보험금예실차가 지난해 1247억원 손실로 전환됐다. DB손해보험 역시 같은 기간 69억원 흑자에서 2410억원 손실이 났다. 현대해상은 1883억원 손실에서 3498억원 손실로 적자 폭이 더 확대됐다.자동차보험손익에서는 삼성화재가 2024년 958억원 흑자에서 지난해 1590억원 적자로 전환됐으며 △KB손해보험(-1077억원) △현대해상(-908억원) △DB손해보험(-547억원) △메리츠화재(-463억원) 등 주요 5개사 모두 줄줄이 마이너스 성적표를 받았다. 이들 5개사의 자동차보험 합산 손실액은 4585억원에 달한다.본업 위기를 상쇄한 것은 투자였다. KB손해보험은 투자손익이 전년 대비 198% 폭증하며 전체 순이익 하락을 방어했고, 삼성화재(43.5%)와 DB손해보험(44.9%)도 투자 부문에서 높은 성장률을 기록했다. 다만 현대해상은 보험손익(-62%)과 투자손익(-6.2%)이 동반 하락하며 순이익이 45.6% 급감했다.삼성생명 ''나홀로 미소''… 중견사들 가시밭길생명보험업계는 삼성생명의 독주와 중견사들의 부진으로 요약되는 ''양극화'' 현상이 뚜렷했다. 삼성생명은 보험 손익에서만 전년 대비 79.8% 급증한 9750억원을 기록하며 연결기준 지배주주지분 전체 순이익 2조3028억원으로 업계 1위 자리를 공고히 했다.반면 나머지 주요사들은 일제히 역성장했다. 한화생명은 연결기준 순이익 8363억원(-3.4%)을 기록했고 신한라이프는 연결기준 순이익이 5077억원(-3.9%), KB라이프는 별도기준 순이익 2440억원(-9.4%)에 그쳤다. 특히 동양생명은 연결기준 순이익 1245억원(-60.4%)으로 가장 가파른 하락세를 보였다. 미래에셋생명 역시 연결기준 순이익 1308억원(-3.9%)으로 주춤했다.신한라이프와 KB라이프 등 은행계 생보사들은 투자손익에서 각각 34.2%, 73.3% 성장하며 분전했으나, 보험 본연의 수익성 악화를 완전히 극복하기에는 역부족이었던 것으로 분석된다.보험업계 한 관계자는 "향후 본업 경쟁력을 끌어올리기 위해서는 상품개발 역량을 한층 고도화하고 차별화된 담보와 서비스를 지속적으로 선보이고, 신사업 영역 확장 등 노력이 필요하다"면서 "또 대내외 경제 불확실성이 이어지는 만큼 건전성과 지속가능경영을 확보하기 위해 안정적인 자산운용 역량이 뒷받침돼야 할 것"이라고 말했다.', NULL, '비즈워치', 'https://n.news.naver.com/mnews/article/648/0000044744', 'https://imgnews.pstatic.net/image/648/2026/02/25/0000044744_001_20260225134812546.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-25 10:36:10', 0, true, '2026-03-09 05:47:54.591236') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (651, '[마켓인]SK인텔릭스, 회사채 수요예측서 목표액 5배 주문', '1500억원 모집에 총 7750억원 주문신용등급 하향 요인 충족에도 ‘흥행’[이데일리 마켓in 김연서 기자] 가전 렌탈업체 SK인텔릭스(A+)가 공모 회사채 수요예측에서 목표액의 5배가 넘는 주문이 몰렸다. 신용도 하향 요인을 충족하고 있음에도 불구하고 무난하게 수요를 끌어모았단 평가다.23일 투자은행(IB) 업계에 따르면 SK인텔릭스는 이날 총 1500억원을 목표로 진행한 공모 회사채 수요예측에서 총 7750억원의 주문을 받았다.트랜치(만기) 별로는 2년물 500억원 모집에 3100억원, 3년물 1000억원 모집에 4650억원의 주문이 들어왔다.SK인텔릭스는 희망 금리밴드로 개별 민간채권평가사(민평) 평가금리 대비 –30bp(베이시스포인트·1bp=0.01%포인트)~+30bp를 가산한 이자율을 제시해 2년물과 3년물 모두 –5bp에서 목표액을 채웠다.대표주관은 SK증권, 한국투자증권이 맡았다. 발행 예정일은 내달 4일이다.SK인텔릭스는 지난 2013년 동양의 가전사업부분 물적분할로 설립된 생활·환경 가전 렌탈업체다. 지난해 7월 SK매직에서 SK인텔릭스로 사명을 변경했다.한국기업평가, 한국신용평가, NICE(나이스)신용평가는 SK인텔릭스의 신용등급을 ‘A+(안정적)’로 평가했다. 다만 현재 SK인텔릭스는 신용등급 하향변동요인을 충족한 상태다.최정현 한기평 선임연구원은 “신사업 준비 단계에서의 수익성 저하로 2025년 9월말 연결기준 ‘EBITDA마진’과 ‘순차입금/EBITDA’가 하향변동요인을 충족하고 있다”고 밝혔다.이어 “신사업 실적과 투자부담에 대한 모니터링이 필요하나 초기 비용 부담이 해소됨에 따라 중장기적으로 ‘EBITDA마진’이 20% 내외, 차입부담을 통제하며 ‘순차입금/EBITDA’도 3.5배 내외를 기록할 것”이라고 전망했다.또 “기존 사업 경쟁력 유지 및 신사업 안정화에 따른 안정적 이익창출 지속 여부를 모니터링할 계획”이라고 덧붙였다.SK인텔릭스는 이번 회사채 발행을 통해 조달한 자금을 채무상환에 사용할 예정이다. 증액 발행될 경우 증액분은 추가 채무상환과 운영자금으로 사용된다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006222944', 'https://imgnews.pstatic.net/image/018/2026/02/23/0006222944_001_20260223165111236.png?type=w800', 'NEWS_ETC', NULL, '2026-02-23 16:51:11', 0, true, '2026-03-09 05:47:54.591236') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (652, '유진그룹 동양, 레미콘 제조업 안전지침서 ''위험성평가 바이블'' 발간', '◆…동양의 위험성평가 바이블. 사진=유진그룹 제공유진그룹 계열 동양이 레미콘 제조업 현장의 특성을 반영한 실무 중심 안전보건관리 지침서 ''위험성평가 바이블(BIBLE)''을 발간했다.유진그룹은 동양이 기존 위험성평가 활동의 한계를 보완하고 현장에서 작동하는 안전관리 체계를 구축하고자 지침서를 기획했다며 23일 이같이 밝혔다.이번 지침서는 중대재해처벌법 판시 사례를 분석해 개선이 필요한 지점을 구체적으로 짚고 실무자가 즉시 적용할 수 있도록 구성됐다. 레미콘 제조업 공정 특성과 현장 작업 환경을 반영해 특화 제작된 실무 지침서로, 단순히 문서화 수준을 높이는 데 그치지 않고 작업 현장에서 즉시 적용할 수 있는 현장 작동성이 핵심 가치로 강조됐다.동양은 지침서를 회사 사업장 외에 동종 업계에도 무상 보급할 예정이다. 이와 함께 근로자 인터뷰와 현장 피드백을 통해 내용을 지속적으로 개선·보완해 나갈 방침이다. 이를 통해 위험성 평가가 일회성 행정 절차가 아닌 현장 안전을 실질적으로 강화하는 관리 체계로 정착하토록 한다는 계획이다.김진용 동양 환경안전팀 팀장은 "안전사고 예방의 핵심은 결국 현장에서 실제로 작동하는 시스템을 만드는 것"이라며 "위험성 평가 활동에는 업무를 수행하는 근로자가 반드시 참여해야 하며, 현장의 목소리를 반영한 실질적인 개선이 이뤄질 때 비로소 사고 예방 효과가 극대화될 것"이라고 강조했다.', NULL, '조세일보', 'https://n.news.naver.com/mnews/article/123/0002378221', 'https://imgnews.pstatic.net/image/123/2026/02/23/0002378221_001_20260223164614551.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-23 16:46:14', 0, true, '2026-03-09 05:47:54.591236') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (653, '세뱃돈에 휘청? 유진그룹 50대 부장들 "설 명절 101만원 써요"', '유진그룹 임직원들이 올해 설 명절 경비로 60만원 이상 사용하는 것으로 나타났다. 사진은 유진그룹 증권 계열사 유진투자증권의 여의도 사옥 전경./사진=유진투자증권유진그룹 50대 이상 임직원들이 설 명절에 100만원 이상 쓰는 것으로 나타났다.유진그룹은 최근 유진기업, 유진투자증권, 동양, 유진홈센터, 유진한일합섬, 유진로지스틱스 등 계열사 임직원 1076명을 대상으로 설 명절 관련 조사를 실시했다고 12일 밝혔다.이번 설문조사 결과 올해 설 명절 평균 예상 경비는 94만3000원으로 집계됐다.이는 전년(87만5000원) 대비 약 7.8% 증가한 수치다. 명절 경비는 매년 상승세를 보이고 있다.2021년 68만6000원과 비교하면 37.5% 늘어난 수준이다. 세대별로는 20대가 평균 61만2000원, 30대는 84만1000원, 40대는 104만5000원, 50대 이상 101만4000원으로 나타났으며, 전 세대에서 명절 예상 경비가 전년보다 증가했다.최근 가족, 친지들과의 교류가 줄어든 상황에서도 명절은 가족 간 관계를 이어가는 중요한 시간이라는 인식도 두드러졌다.직계 가족을 제외한 가족·친지들과의 만남 빈도를 묻는 질문에는 ''분기 1회 정도(29.7%)'', ''명절 이외에는 만나기 어렵다(27.6%)'', ''연 1회 정도(21.2%)'' 등 분기 1회 이하로 만난다는 응답이 78.5%를 차지했다.과거 대비 만남과 연락 빈도 변화를 묻는 질문에서는 ''많이 줄었다(43.6%)''와 ''다소 줄었다(32.7%)''가 전체의 76.3%를 차지했다.교류가 줄어든 이유로는 ''각자 일과 생활이 바빠져서(40.1%)'', ''예전만큼 자주 만날 계기가 줄어서(14.0%)'', ''가족의 개념이 친지에서 직계 가족으로 축소돼서(13.1%)'' 순으로 나타났다.설 명절에 가장 많은 시간을 보내는 활동으로는 ''함께 식사하며 이야기 나누기''가 78.9%로 압도적이었다.대화 주제로는 ''일과 생계(28.2%)''가 가장 많았으며 ''건강과 안부(21.6%)'', ''추억(14.0%)'' 순이었다. 특히 ''일과 생계''는 모든 세대에서 가장 높은 비중을 차지했다.  급변하는 경제, 사회 환경 속에서 명절 대화의 중심 주제로 자리 잡았다.유진그룹 관계자는 "이번 설문조사를 통해 명절을 바라보는 임직원들의 인식의 변화를 확인할 수 있었다"며 "임직원들이 부담을 덜고 더욱 즐거운 명절을 보낼 수 있도록 다양한 지원 방안을 지속적으로 마련하겠다"고 밝혔다.', NULL, '동행미디어 시대', 'https://n.news.naver.com/mnews/article/417/0001129606', 'https://imgnews.pstatic.net/image/417/2026/02/12/0001129606_001_20260212085408497.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-12 08:53:43', 0, true, '2026-03-09 05:47:54.591236') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (654, '우리금융, 4대 금융중 나홀로 ''경영 효율성 지표'' 악화… 왜?', '우리금융 "동양·ABL생명 인수로 판관비 증가 여파"[사진=우리금융지주]- 작년 우리금융 CIR 45.7%… 전년 대비 2.7%p↑- 판관비 전년 대비 13.7% 상승 영향 커[디지털데일리 강기훈기자] 작년 호실적을 거둔 우리금융지주가 경영 효율성 면에선 아쉬운 성적을 거둔 것으로 나타났다. 금융지주 중 유일하게 경영 관련 지표인 영업이익경비율(CIR)이 상승한 것이다.CIR은 총 영업이익(이자이익+비이자이익)에서 인건비, 임대료 등 판매관리비(판관비)가 차지하는 비중을 뜻한다. 수치가 오를수록 경영 환경이 악화됐음 의미한다.이에 우리금융 측은 "동양·ABL생명 인수합병(M&A) 여파로 판관비가 늘었기 때문"이라고 설명했다.10일 금융권에 따르면 우리금융의 작년 CIR은 45.7%를 기록했다. 전년(42.8%)보다 2.7%포인트(p) 상승한 수치다. 외형상 경영 효율성이 악화된 것이다. 같은 기간 다른 금융지주들의 경영 환경이 개선된 것과 대조되는 모습이다.KB금융의 경우 CIR이 40.7%에서 39.3%로 1.4%p 하락했다. 신한금융은 41.7%에서 41.5%로 0.2%p 내렸으며 하나금융 또한 42.4%에서 41.2%로 1.2%p 하락했다.우리금융의 판관비가 큰 폭으로 상승한 점이 경영 효율성 악화의 주요 원인으로 꼽힌다. 실제로 작년 우리금융의 판관비는 5조1810억원을 기록해 전년 대비 15.9% 증가했다.4분기만 놓고 봤을 때도 우리금융의 판관비는 1조4910억원으로 나타났다. 이는 전년 동기보다 13.7% 상승한 수치다. 이에 대해 우리금융 측은 작년 동양·ABL생명을 자회사로 편입한 영향이 크다는 입장이다.우리금융 관계자는 "두 생명보험사를 인수함에 따라 인건비와 물건비가 크게 증가했다"면서 "아울러 우리투자증권의 모바일 트레이딩 시스템(MTS)을 구축하는 비용 또한 포함됐다"라고 설명했다.한편으로는 단기간에 우리금융이 CIR을 낮추기란 무리라는 분석 또한 존재한다.금융권 한 관계자는 "우리투자증권의 사세 확장을 위해 우리금융 측이 조만간 유상증자를 여러 차례 단행할 것으로 안다"라면서 "그렇다면 인원 확충은 필연적"이라고 말했다.그러면서 "우리금융은 다양한 수익원 다각화를 위해 그룹 차원에서 비은행 강화에 사활을 걸고 있다"라며 "비은행 강화 작업이 어느 정도 완료돼야 CIR이 낮아질 것"이라고 내다봤다.', NULL, '디지털데일리', 'https://n.news.naver.com/mnews/article/138/0002217657', 'https://imgnews.pstatic.net/image/138/2026/02/10/0002217657_001_20260210133309611.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-10 13:33:09', 0, true, '2026-03-09 05:47:54.591236') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (661, '[이 시각 시황] 삼성·SK하닉, 역대급 실적…HBM 관련주 상승세', '■ 머니쇼 ''이 시각 시황'' - 장연재이 시각 시황입니다.ai 투자 위축 우려에도 국내증시 양대지수 모두 상승합니다.코스피가 0.64% 오름세로 5,251포인트 가리키고 있습니다.코스닥은 약보합권으로 1,163선에서 움직임 전개됩니다.수급상황 보시죠.유가증권 시장 매매 동향입니다.외국인이 2,143억 원, 기관이 420억 원 매도 우위 기록 중입니다.개인만 홀로 2,814억 원 순매수 기록 중입니다.코스닥 시장입니다.기관이 1,370억 원 사들입니다.반면, 외국인이 446억 원, 개인이 421억 원 팔아 냅니다.등락률 상하위 업종입니다.오늘(30일)은 석유와 가스, 우주항공과 국방, 전자장비와 기기 업종이 상승률 상위권에 위치해 있습니다.반면, 자동차, 항공화물운송과 물류, 건강관리장비와 용품 업종이 하락폭이 큰 것으로 집계됩니다.시장을 주도하는 테마, 종목별 시세 체크하시죠.오늘 비철금속 관련주가 강합니다.구리 가격이 미국과 중국발 수요 기대가 맞물려 사상 최고치를 잇따라 경신하고 있는데 따른 겁니다.현지시간 29일 뉴욕상품거래소(COMEX)에서 3월 물 구리 선물 가격은 파운드당 6.20달러로 마감해 사상 최고 종가를 기록한 바 있습니다.삼아알미늄이 18% 강세로 36,750원에 거래되고 있습니다.남선알미늄이 4.4% 오름세로 1,294원입니다.풍산이 7.8% 오르면서 거래가 139,600원 집계되고 있습니다.조일알미늄이 4.2%, DI동일이 2% 강세 기록 중입니다.반도체 관련주도 상승세 이어갑니다.고대역폭메모리 관련주가 오름세입니다.삼성전자의 7세대 HBM 양산 준비와 SK하이닉스 호실적이 섹터 전반에 온기를 불어넣고 있습니다.관련주 내에서는 디아이티가 12.2% 강세로 22,450원에 거래되고 있습니다.한화비전이 4.3% 오르면서 57,800원에 거래되고 있습니다.오픈엣지테크놀로지가 2.6% 강세로 거래가 15,400원입니다.SK하이닉스가 4.4% 오르면서 900,000원 돌파했습니다.레이저쎌이 1.1% 오름세로 거래가 2,240원입니다.로봇주도 강세 계속됩니다.테슬라가 모델 S와 X를 단종하고, 로봇 사업에 집중하겠다는 뜻을 밝히면서 로봇주 어제(29일) 주목받았었는데요.이재명 대통령이 어제 인공지능(AI) 시대로 도래한 로봇의 생산 현장 투입을 ‘다가오는 거대한 수레’에 비유하며 “피할 수 없다”고 말한 점도 호재로 작용하며 추가적인 상승세 나타냅니다.현재 한라캐스트가 15% 강세로 거래가 22,100원입니다.로보티즈가 5.3% 오르면서 346,000원에 거래되고 있습니다.티엑스알로보틱스가 6.5% 오름세로 22,150원입니다.라온로보틱스가 6.6% 오르면서 20,100원에 거래되고 있습니다.클로봇이 2.7% 강세로 현재 75,500원에 거래되고 있습니다.양자컴퓨터 관련주도 계속 상승합니다정부가 2035년까지 한국을 양자컴퓨터의 두뇌인 ''퀀텀 칩'' 세계 1위 제조국으로 만들겠다는 청사진을 발표한 영향입니다.한국정보인증이 3% 강세로 거래가 6,970원입니다.SK텔레콤이 6.8% 오르면서 74,200원입니다.우리로가 1% 오름세, 엑스게이트가 1.3% 강세로 거래가 8,120원에 집계되고 있습니다.AI 투자심리 악화에도 코스피는 상승세 이어갑니다.다만 코스닥이 살짝 조정받는 모습인데 조정을 노린 매수세가 들어올지, 아니면 차익실현이 강해질지 장중 흐름 좀 더 지켜보시죠.지금까지 시장 상황 전해드렸습니다당신의 제보가 뉴스로 만들어집니다.SBS Biz는 여러분의 제보를 기다리고 있습니다.홈페이지 = https://url.kr/9pghjn', NULL, 'SBS Biz', 'https://n.news.naver.com/mnews/article/374/0000489687', 'https://imgnews.pstatic.net/image/374/2026/01/30/0000489687_001_20260130094028133.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-30 09:40:28', 0, true, '2026-03-09 05:48:13.883399') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (656, '[단독] ‘패가망신 1호 사건’ 마무리…내부자 결탁에 자사주 동원 확인', '[앵커]''주가조작 패가망신''을 내걸고 출범한  합동 대응단의  1호 사건 조사가 마무리 수순입니다.KBS 취재결과 단순한 외부 세력의 시세 조종이 아니라  회사 내부자인 임원이 결탁한 사건으로 파악됐습니다.대응단은 이 임원이  자사주 매입 정보를 유출한 정황을  포착했습니다.송수진 기자의 단독 보도입니다.[리포트]주가조작 근절 합동 대응단의 1호 사건은 ''DI동일'' 주가 조작입니다.[권대영/금융위원회 부위원장/지난해 7월 : "주가 조작범은 반드시 패가망신한다는 점을 보여 올해를 주가조작 근절의 원년이 되도록 하겠습니다."]병원장 등의 재력가, 금융 전문가 등이  짜고 치는 거래로 주가를 올린 뒤 팔아 부당 이득을 챙긴 사건으로 알려졌습니다.주가조작의 대상이 된 DI동일은 피해자란 입장이었습니다.그런데 조사 착수 5개월여 만에 사건의 성격이 바뀌었습니다.DI동일의 임원이  작전세력과 손을 잡은 정황이 포착됐습니다.작전세력이 DI동일 주식을 비싸게  사고팔면서 주가를 띄우고 있던 2024년, DI동일은  회계 부정이 적발돼 20일간 거래가 정지됐습니다.거래 재개 후 주가 하락이 우려됐지만, 오히려 급등합니다.회사가 100억 원 규모 자사주 매입에 나선 덕분인데, 대응단은 이 내부 정보가 임원 A씨를 통해 작전세력에 흘러 들어갔다고 보고 있는 거로 파악됐습니다.자사주 매입 정보를 미리 알고 있었기 때문에 작전세력은 거래정지란 악재에도 주식을 팔지 않고 버텼고, 주가가 최고점을 찍을 때 팔아 시세차익을 얻을 수 있었단 겁니다.이들이 얻은 부당 이득은  모두 400억 원대로 추정됩니다.금융위원회 증권선물위원회는 이르면 오는 11일, ''1호 사건''에 대한 최종 처분을 의결하고  이들을 검찰에 고발할 계획입니다.KBS 뉴스 송수진입니다.촬영기자:강현경/영상편집:김형기/그래픽:유건수■ 제보하기▷ 전화 : 02-781-1234, 4444▷ 이메일 : kbs1234@kbs.co.kr▷ 카카오톡 : ''KBS제보'' 검색, 채널 추가▷ 네이버, 유튜브에서 KBS뉴스를 구독해주세요!', NULL, 'KBS', 'https://n.news.naver.com/mnews/article/056/0012137169', 'https://imgnews.pstatic.net/image/056/2026/03/07/0012137169_001_20260307063712246.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-07 06:25:43', 0, true, '2026-03-09 05:48:13.883399') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (657, '[단독] ‘패가망신 1호 사건’ 마무리…내부자 결탁에 자사주 동원 확인', '[앵커]''주가조작 패가망신''을 내걸고 출범한  합동 대응단의  1호 사건 조사가 마무리 수순입니다.KBS 취재결과 단순한 외부 세력의 시세 조종이 아니라  회사 내부자인 임원이 결탁한 사건으로 파악됐습니다.대응단은 이 임원이  자사주 매입 정보를 유출한 정황을  포착했습니다.송수진 기자의 단독 보도입니다.[리포트]주가조작 근절 합동 대응단의 1호 사건은 ''DI동일'' 주가 조작입니다.[권대영/금융위원회 부위원장/지난해 7월 : "주가 조작범은 반드시 패가망신한다는 점을 보여 올해를 주가조작 근절의 원년이 되도록 하겠습니다."]병원장 등의 재력가, 금융 전문가 등이  짜고 치는 거래로 주가를 올린 뒤 팔아 부당 이득을 챙긴 사건으로 알려졌습니다.주가조작의 대상이 된 DI동일은 피해자란 입장이었습니다.그런데 조사 착수 5개월여 만에 사건의 성격이 바뀌었습니다.DI동일의 임원이  작전세력과 손을 잡은 정황이 포착됐습니다.작전세력이 DI동일 주식을 비싸게  사고팔면서 주가를 띄우고 있던 2024년, DI동일은  회계 부정이 적발돼 20일간 거래가 정지됐습니다.거래 재개 후 주가 하락이 우려됐지만, 오히려 급등합니다.회사가 100억 원 규모 자사주 매입에 나선 덕분인데, 대응단은 이 내부 정보가 임원 A씨를 통해 작전세력에 흘러 들어갔다고 보고 있는 거로 파악됐습니다.자사주 매입 정보를 미리 알고 있었기 때문에 작전세력은 거래정지란 악재에도 주식을 팔지 않고 버텼고, 주가가 최고점을 찍을 때 팔아 시세차익을 얻을 수 있었단 겁니다.이들이 얻은 부당 이득은  모두 400억 원대로 추정됩니다.금융위원회 증권선물위원회는 이르면 오는 11일, ''1호 사건''에 대한 최종 처분을 의결하고  이들을 검찰에 고발할 계획입니다.KBS 뉴스 송수진입니다.촬영기자:강현경/영상편집:김형기/그래픽:유건수■ 제보하기▷ 전화 : 02-781-1234, 4444▷ 이메일 : kbs1234@kbs.co.kr▷ 카카오톡 : ''KBS제보'' 검색, 채널 추가▷ 네이버, 유튜브에서 KBS뉴스를 구독해주세요!', NULL, 'KBS', 'https://n.news.naver.com/mnews/article/056/0012137132', 'https://imgnews.pstatic.net/image/056/2026/03/06/0012137132_001_20260307000513420.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-06 23:48:41', 0, true, '2026-03-09 05:48:13.883399') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (658, '[특징주]알루미늄박 전성시대 오나…DI동일 7%대 ↑', '배터리 시장에서 주목받지 못했던 알루미늄박의 수요 증가 기대감에 DI동일 주가가 7%대 상승률을 보이고 있다.19일 오전 10시 38분 기준 DI동일의 주가는 7.08%(1650원) 오른 2만4950원에 거래되고 있다.유진투자증권은 이날 DI동일에 대해 투자의견 매수를, 목표주가 4만원을 유지했다.한병화 유진투자증권 연구원은 "DI동일의 올해 매출과 영업이익은 각각 6888억원, 123억원으로 영업손익은 흑자전환할 것"이라며 "지난해 실적 부진의 원인이던 자회사 동일알루미늄 합병 일회성 비용과 환경플랜트 자회사들의 영업적자가 올해는 없을 것으로 추정되기 때문"이라고 분석했다.한 연구원은 "에너지저장시스템(BESS)향 리튬인산철(LFP) 배터리용 코팅 알루미늄박 매출이 증가해 알루미늄박 사업부의 올해 매출은 2780억원으로 전년비 24% 늘어날 것"이라며 "환경플랜트 자회사들의 매출도 전년의 약 210억원에서 올해 510억원 수준으로 회복될 것으로 예상된다"고 했다.이어 "반도체 생산 설비 향 매연 저감 장치를 공급하는 플라즈마텍의 주 고객인 삼성반도체의 설비 증설 재개로 매출이 회복되고, 디스플레이 업체에 환경 설비를 공급하는 동일씨엔이는 신규 고객사를 확보한 것으로 판단된다"고 덧붙였다.한 연구원은 특히 알루미늄박의 성장성에 주목했다. 그는 "알루미늄의 가격이 구래 대비 1/4 수준으로 시장 규모가 작지만 향후 배터리 발전 기술 발전은 알루미늄박에게 매우 유리한 구도로 진행되고 있다"며 "차세대 보급형 배터리 기술 표준이 될 가능성이 높은 소디움 배터리에는 알루미늄박이 양극은 물론 음극까지 사용되고 전고체 배터리에도 알루미늄박의 사용은 사실상 확정된 상태"라고 전했다.그러면서 "1GWh 당 필요한 배터리 알루미늄박 사용량은 삼원계 300~400t, LFP 400~600t, 소디움 700~1000t 수준"이라고 말했다.', NULL, '아시아경제', 'https://n.news.naver.com/mnews/article/277/0005723029', 'https://imgnews.pstatic.net/image/277/2026/02/19/0005723029_001_20260219104213740.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-19 10:41:20', 0, true, '2026-03-09 05:48:13.883399') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (659, 'DI동일, 차세대 알루미늄박 코팅 설비 1100억 투자…ESS시장 공략', 'DI동일이 1100억원 규모의 신규 시설 투자로 차세대 이차전지 소재 시장 공략에 본격적으로 나선다.DI동일은 공시를 통해 올해 완공 예정인 청주 알루미늄 공장에 1100억원을 투자해 LFP(리튬인산철) 전지용 카본 코팅 알루미늄박 생산 시설을 구축할 계획이라고 11일 밝혔다.이번 투자는 올해 2월부터 2030년까지 단계적으로 진행되고, 올해 200억원이 우선 집행된다. 투자금액은 토지와 건축, 기계설비 등을 포함한 금액으로, 2024년도 말 연결재무제표 기준 자기자본 대비 약 19.6%에 달하는 규모다.최근 글로벌 전기차 및 ESS(에너지저장장치) 시장에서는 안전성과 가격 경쟁력이 뛰어난 LFP 전지의 채택이 확대되고 있다.미국 에너지 시장조사업체 블룸버그NEF(BNEF)는 2027년 전 세계 ESS 시장에서 LFP 채택 비율이 94%까지 올라갈 것이라고 전망했다.LFP 전지는 원가 부담이 낮고 열 안정성이 뛰어나 화재 위험이 적은 반면, 에너지 밀도가 낮아 성능 활용에 한계가 있다. 이를 보완하기 위해 알루미늄박 표면에 카본 코팅을 적용해 전류 흐름을 원활하게 함으로써, 실질적인 출력과 활용 가능한 에너지 효율을 높이고 배터리의 성능과 내구성을 개선하고 있다.DI동일은 이번 신규시설 투자를 통해 LFP 전지용 고부가 알루미늄 소재 생산 역량을 내재화하고, 글로벌 배터리 소재 시장에서의 경쟁력을 한층 강화한다는 전략이다.특히 오는 2030년에는 2만500MT(메트릭톤)의 카본 코팅 알루미늄박 생산으로 연간 약 2500억원 규모의 신규 매출 달성이 가능할 것으로 전망했다.청주 알루미늄 공장은 독일산 아헨바흐(Achenbach) 최신 압연기와 공정 기술을 기반으로, 고품질 알루미늄박을 안정적으로 공급할 수 있는 핵심 거점으로 활용될 예정이다.DI동일 관계자는 "이번 투자는 LFP 전지 시장 확대라는 산업 흐름에 선제적으로 대응하기 위한 전략적 결정"이라며 "이번 투자를 통해 중장기 성장 동력 확보와 함께 사업 포트폴리오 고도화를 추진해 나갈 것"이라고 밝혔다.', NULL, '아시아경제', 'https://n.news.naver.com/mnews/article/277/0005720682', 'https://imgnews.pstatic.net/image/277/2026/02/11/0005720682_001_20260211145309617.png?type=w800', 'NEWS_ETC', NULL, '2026-02-11 14:52:16', 0, true, '2026-03-09 05:48:13.883399') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (660, 'DI동일, 지난해 영업손 15억…적자전환', '[헤럴드경제=증권부] DI동일은 지난해 연결기준 영업손실이 15억4476만원으로 전년대비 적자전환했다고 11일 공시했다.같은 기간 매출액은 6013억5167만원으로 7.7% 감소한 것으로 집계됐다.당기순손실 역시 99억6860만원으로 적자전환했다.', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002599535', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2026-02-11 13:55:11', 0, true, '2026-03-09 05:48:13.883399') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (664, '이란 사태에 비료株 ''들썩''…조비·남해화학 29% 급등', '호르무즈 해협 봉쇄 우려 확산[호르무즈=AP/뉴시스]2023년 5월 19일(현지 시간) 호르무즈 해협에서 대형 컨테이너선 등이 항행하고 있다. 2026.03.05.[서울=뉴시스]송혜리 기자 = 이란 사태 장기화 가능성이 제기되면서 글로벌 비료 수급 불안이 커지는 가운데 9일 장 초반 국내 비료 관련주가 일제히 급등세를 보이고 있다.오전 10시20분 기준 조비는 전 거래일 대비 4370원(29.95%) 오른 1만8960원에 거래되며 개장 직후 상한가를 기록했다.같은 시각 남해화학도 29.91% 뛰었고, 효성오앤비와 누보 역시 각각 29.87%, 21.98% 상승하며 강세를 나타내고 있다.호르무즈 해협이 이란 사태로 장기간 봉쇄될 경우 전 세계 비료 공급망이 흔들릴 수 있다는 우려가 매수세를 자극한 것으로 풀이된다. 호르무즈 해협은 전 세계 원유·액화천연가스(LNG) 물동량의 약 20%, 비료 무역의 3분의 1을 담당하는 핵심 운송 통로다．', NULL, '뉴시스', 'https://n.news.naver.com/mnews/article/003/0013809432', 'https://imgnews.pstatic.net/image/003/2026/03/09/NISI20260131_0000966163_web_20260131154344_20260309105515085.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 10:32:02', 0, true, '2026-03-09 05:48:33.886382') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (665, '[하우머니] 이란 전쟁 엿새째…ETF 시장 상황은?', '■ 머니쇼 ''하우머니'' - 김승현 하나자산운용 ETF·퀀트솔루션 본부장Q. 미국 이스라엘의 공습으로 시작된 이란 사태가 장기화할 것이라는 전망이 나오면서, 국내 증시 변동성도 크게 확대되는 모습입니다. ETF 시장 내에서도 종목별 희비가 극명하게 갈리고 있을 거 같은데, 구체적인 상황은 어떻습니까?- 이란 전쟁 장기화 조짐…ETF 시장 상황은?Q. 3월 첫 거래일 개인 순매수 1, 2위 종목이 모두 코스피 2배 레버리지 ETF였습니다. ''공포에 사야 한다''는 격언을 따른 모양새지만, 어제(4일) 지수가 추가 하락하면서 벌써 손실 폭이 걷잡을 수 없이 불어났을 것 같습니다. 현재 개인들의 이런 위험한 베팅, 어떻게 진단하고 계십니까?- 바닥인 줄 알고 풀베팅…레버리지 담는 개인투자자?- 급락장 속 개인, 레버리지 ETF에 저가 매수 베팅- 코스피·코스닥 연속 약세…''전투 개미'' 손실 확대 우려- 개인 순매수 1위 KODEX 레버리지…4,625억 원 몰려- 2위 KODEX 코스닥150레버리지…2,310억 원 순유입- 지수 2배 추종 상품에 자금 집중…공격적 반등 베팅- 외국인 매도 폭탄에도 개인은 ''하락은 기회'' 인식- 반도체 레버리지 ETF도 강세…반도체 투심 유지- 레버리지 투자, 수익·손실 모두 ‘배율 리스크’ 경고Q. 지수 변동성이 극심해지면서 소나기를 피하려는 ''방어형 ETF''에 대한 매수세도 강해지고 있다는데, 구체적으로 어떤 상품들이 방어형 ETF로 분류되는 겁니까? 또 지금 같은 하락장에서 실제로 얼마나 효과적인 방어막 역할을 하고 있는지 짚어주시죠.- 극심한 증시 변동성…주목해야 할 방어형 ETF는?- 증시 변동성 확대…방어형 ETF로 자금 이동 뚜렷- KODEX 200타겟위클리커버드콜, 691억 원 순유입- ACE KRX금현물, 185억 원 유입…안전자산 수요 증가- 하락장 속 배당·금 ETF로 ''소나기 피하기'' 전략- 해외보다 낙폭 컸지만 자금은 여전히 ''국장''으로- 국내 주식형 ETF 설정액 하루 새 2조 원 이상 급증- 공모 펀드 포함해도 국내↑·해외↓ 흐름 뚜렷- 변동성 장세 속 ''국내 선호'' 자금 쏠림 현상 심화Q. 최근에는 미국 시장으로 쏠렸던 자금이 국내로 빠르게 유턴하면서 국내 주식형 ETF 순자산 규모가 해외 주식형을 압도했다는 소식이 들립니다. 1조 원 규모의 ‘메가 ETF’도 속출하고 있다고요?- 400조 육박한 ETF 시장…해외도 제친 국내 주식형?- ETF 시장 400조 원 눈앞…1년 새 200조 원 넘게 급팽창- 국내 주식형 ETF 169조 원…해외형 크게 앞질러- 지난해와 정반대 흐름…미국 대신 ''국장''으로 자금 유턴- 전체 ETF 순자산 387조 원…상장 상품 1073개로 증가- 순자산 1조 원 이상 ''메가 ETF'' 80개- 새 1조 클럽 70% 이상 국내 투자형…반도체·방산·조선 주도- 고배당·커버드콜 월배당 ETF 인기…연금 자금 유입 확대- 퇴직연금 계좌 내 국내 ETF 비중 상승…장기 자금 ‘버팀목’ 역할Q, 최근 ETF 수익률 상위 10개 종목들도 분석해 보겠습니다. 지난 한 주간 어떤 ETF가 수익률 최상위권에 들었습니까?- 투자자 몰리는 ETF 시장…수익률 최상위권 ETF는?- 반도체 소부장 ETF ''톱10'' 싹쓸이…AI 투자 확대 수혜- SOL 반도체후공정, 주간 수익률 1위 차지- 한미반도체 급등 효과…패키징·테스트 장비주 강세- KODEX AI반도체핵심장비, HBM 장비주 비중 83%- 현대차·기아 효과…SOL 자동차TOP3플러스 급등- 자금은 지수형으로…KODEX 200에 1조 원 넘게 순유입- 미국 지수 ETF 인기 지속…1000억 원 이상 유입- 배당 ETF도 투자자에 인기…고배당 상품 자금 몰려Q, 증시 변동성이 커지면서 지수를 단순히 따라가는 상품보다, 시장 상황에 맞춰 발 빠르게 종목을 갈아 끼우는 ''액티브 ETF''에도 관심이 쏠리고 있는데요. 최근에는 액티브 ETF에서 바이오 종목들은 덜어내는 대신, 반도체와 증권, 그리고 인프라 관련주를 늘리고 있다고요?- 코스피 액티브 ETF, 달라진 운용 전략?- 액티브 ETF 운용 전략 대대적 재편…''선별 투자'' 강화- 액티브 ETF, 바이오 비중 축소, 반도체·증권주 확대- 삼성전자·SK하닉 비중 50% 돌파…반도체 비중 확대- ''피지컬 AI'' 기대감에 현대자동차 편입 확대- SK스퀘어 비중 확대…반도체 슈퍼사이클 베팅- 미래에셋증권 편입 확대…거래대금 증가 수혜 기대 반영- 타임폴리오자산운용, 포트폴리오 AI·증권 중심 재편- 액티브 ETF, 시장 전망 반영해 종목·비중 유연 조정Q. 지난해 개인 투자자들이 가장 많이 매수한 주식형 ETF가 하나자산운용의  ''1Q 미국우주항공테크'' ETF 였다고 합니다. 이 상품의 현재 수익률은 어떻습니까? 또 실제로 스페이스X가 상장할 경우 이 ETF에는 어떤 변화가 생기는 건가요?- "스페이스X 상장 전 시장 선점"…우주항공 ETF 1위는?- ''1Q 미국우주항공테크'' ETF, 지난해 개인 순매수 1위- 상장 이후 63거래일 연속 개인투자자 순매수 행진- 1Q 미국우주항공테크 ETF, 누적 수익률 27% 수준- 미국 우주 및 항공테크 대표기업에 집중 투자하는 ETF- 로켓랩·조비 에비에이션·GE에어로스페이스 편입- 스페이스X 상장 기대감…순자산 규모 5천억 원 돌파- 스페이스X IPO 시 최대 비중 편입 예정- 스페이스X, 올해 상장 추진…우주산업 모멘텀 확대Q. 코스피가 2001년 9·11 테러 당시 기록했던 하락 폭을 넘어서는 등 역대 최대 낙폭을 연일 경신하며 극심한 변동성을 보이고 있습니다. 그 어느 때보다 신중한 대응이 필요한 시점이라는 지적이 나오는데요. 지금 시장 상황에서 투자자들은 어떤 전략으로 접근하는 것이 바람직하다고 보십니까?- 증시 급락·커지는 환율 변동성…대응 전략은?- 코스피, 12.06% 폭락…9·11 테러 이후 최대 낙폭- 4일, ''서킷브레이커'' 발동…양시장 동시 거래 중단- 중동 전쟁 장기화 우려에 투자심리 급랭- 연초 상승률 세계 1위 코스피, 하락률도 세계 1위- "기존 포지션 유지 낙폭 과대 주도주 분할매수 전략"(자세한 내용은 동영상을 시청하시기 바랍니다.)당신의 제보가 뉴스로 만들어집니다.SBS Biz는 여러분의 제보를 기다리고 있습니다.홈페이지 = https://url.kr/9pghjn', NULL, 'SBS Biz', 'https://n.news.naver.com/mnews/article/374/0000495962', 'https://imgnews.pstatic.net/image/374/2026/03/05/0000495962_001_20260305105425352.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-05 10:54:25', 0, true, '2026-03-09 05:48:33.886382') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (666, 'FAA인증·탑승장… 조비, UAM 비상위한 성공열쇠는?', '일평균 50만명 이용 네트워크원가절감, 대량생산 체계 필수소비자 인식 변화 등도 숙제로투자자 입장에서 중요한 것은 조비에비에이션(이하 조비) 주가의 방향성이다. 월가 전문가들은 조비의 UAM(도심항공교통)사업이 진정한 시장성을 갖추기 위해서는 비행기술의 완성을 넘어 몇 가지 구조적 전제조건이 충족돼야 한다고 입을 모은다.조비 에비에이션 주가 추이.◇현재 10달러선 조비, 앞으로 주가는첫째 조건은 미국 연방항공청(FAA) 형식인증이다. 조비는 연내 FAA 형식인증을 목표로 하지만 리스크가 없지 않다. 유럽 최대 항공기 제조사인 에어버스조차 신형기 인증과정에서 수년의 지연을 경험했다.조비의 성공을 좌우할 두 번째 변수는 탑승장이다. 포르쉐컨설팅 보고서는 UAM이 경제적으로 의미있는 시장으로 성장하려면 전세계 30개 이상 도시에 최소 1000개에서 2500개의 버티포트(전용 이착륙장)가 구축돼야 하며 하루 50만명 이상이 이용 가능한 네트워크 밀도를 확보해야 한다고 분석했다.이는 최대의 비용폭탄이 될 수 있는 이슈다. 뉴욕 맨해튼 기준으로 현재 헬기 착륙장의 착륙료는 1회에 150~200달러 수준으로 높다. 이 비용은 조비 1회 비행원가의 최대 40~50%를 차지할 것으로 분석된다. 조비가 버티포트를 직접 운영하는 수직통합 전략을 선택한 것도 이 비용을 1회당 43달러 수준으로 낮추기 위한 계산이다.세번째 관문은 제조원가 절감과 대량생산 체계확보다. 원리서치 분석에 따르면 수익성 있는 드론택시 서비스를 위해 조비가 목표로 하는 항공기 제조원가는 대당 130만달러다. 조비 경영진은 항공기 대당 연간 약 220만달러의 순매출과 100만달러 수준의 순이익을 올릴 수 있다고 자료로 밝혔다. 이 경우 항공기 1대의 투자회수 기간은 약 1.3년이다.네번째 이슈는 소비자들의 반응이다. 포르쉐컨설팅은 UAM 시장의 성패를 가르는 가장 결정적 변수로 사회적 수용성을 꼽았다. 수백 대의 에어택시가 도심 저고도를 동시에 비행할 경우 누적 소음에 대한 주민의 반발이 예상된다. 가격도 잠재 리스크다. 초기 서비스가 고소득층 위주로 제공될 경우 부자들의 ''하늘택시''라는 이미지가 고착돼 규제기관의 역풍을 맞을 수 있다.조비는 장기적으로 좌석·마일당 3달러의 요금 수준을 목표로 한다. 평균 비행거리를 25마일(40㎞)로 가정하면 1인당 약 75달러(11만원), 4인 만석 기준으로는 비행 1회당 300달러의 매출이 발생한다. 비용변수는 자율비행 전환이다. 현재 조비 에어택시 1회 비행에는 파일럿 급여, 지상 지원인력 인건비 포함 약 38달러의 인건비가 발생한다. 조비는 2025년 11월 VTOL(자율 수직이착륙) 시제기의 첫 비행에 성공했다.월가에서는 주가전망에 대한 의견이 갈린다. 투자기관의 컨센서스 목표주가는 12달러50센트며 일부 낙관론자는 최고 22달러를 제시하기도 하지만 리스크를 감안하면 6~7달러가 적정주가라는 평가도 있다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005324201', 'https://imgnews.pstatic.net/image/008/2026/03/03/0005324201_001_20260303041014162.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-03 04:10:00', 0, true, '2026-03-09 05:48:33.886382') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (667, '숲속 헛간의 미친 두 남자, 10년 뒤 이들에게 일어난 일', '[반준환의 미국 스몰캡⑧] 숲속 헛간 연구실에서 만든 무소음 드론-조비 에비에이션(2/4)[편집자주] 숫자 뒤 스토리를 읽어야 진짜 투자가 보입니다. 한국주식도 미국 스몰캡 생태계를 알면 α를 낼 수 있습니다. 기술의 언어를 투자의 언어로 풀어내는 전문기자와 글로벌 특화분석 원리서치의 투자 나침반으로 여러분을 안내하겠습니다. 반보(半步)만 앞서면 남들이 모르는 길이 보일겁니다. 난해한 기술주 투자, 이제 쉽고 재미있게 즐겨보세요.벨로시티11의 지분을 매각한 자금으로 조벤은 본격적으로 드론개발에 착수했다. 더 넓은 제작·실험 공간이 필요하다고 판단하고, 자신의 어린 시절 고향 남쪽의 땅을 매입해 하드웨어 인큐베이터로 운영했다. 2009년 9월 조비 에어로(현재 조비 에비에이션)를 창업한 뒤 10년간 이곳에 칩거하면서 소규모 엔지니어 연구팀을 운영했다.산속 헛간이라고 부른 작업장에서 전기모터, 비행 소프트웨어, 리튬이온 배터리, 비행체, 센티미터 단위 GPS 시스템 등을 개발했다. 이곳은 조벤의 유년시절과 비슷했는데 엔지니어들은 목장 내 텃밭에서 달걀을 가져오고 베리를 따 먹으며 일했다고 한다.그러나 개발은 좀처럼 진척되지 않았고 시간과 돈은 계속 흘러 나가고 있었다. 이 때 조벤에게 알렉스 스톨이라는 구원자가 들어온다. 스티브 잡스에게 워즈니악이 있었고, 일론 머스크에게 그윈 숏웰이 있었는데, 조벤에게는 알렉스가 그랬다.2012년 조벤은 드론개발에 난항을 겪고 있었다.  3년동안 산타크루즈 산맥의 낡은 헛간에서 고생을 하고 있었지만 소음없는 드론이라는 직관을 현실화할 브레인이 절실했다. 이 때 만난 게 스탠퍼드 대학교 항공우주공학 석사논문을 쓰고 있었던 알렉스였다 . 주제는 저소음 프로펠러 설계. 조벤은 "이 사람이 내 비행기를 완성해줄 마지막 퍼즐"이라고 직감했다.━소음에 미친 CEO와 정규직 1호 사원, 두 천재가 만들어낸 저소음 드론━조비 에비에이션 연혁/그래픽=이지혜조벤은 산업계 곳곳에서 러브콜을 받던 청년 알렉스를 자신의 숲속 헛간으로 초대했다. 화려한 연구실 대신 기름때 묻은 작업대와 프로펠러 파편이 뒹구는 그곳에서, 두 천재는 밤을 새워 토론했다. 알렉스는 조벤의 눈에서 광기를 봤고, 조벤은 알렉스의 수식에서 미래를 봤다. 몇일 뒤 알렉스는 짐을 챙겨 돌아왔고 조비의 첫 번째 정규직 직원으로 합류했다.이후 11년 동안 두 사람은 말 그대로 동고동락했다. 소음에 대한 조벤의 편집증이 도질 때면 알렉스는 며칠 밤을 꼬박 새워 그 소음을 상쇄할 수학적 공식을 찾아냈다. 특히 알렉스는 조비의 6개 프로펠러 시스템 창시자다. 4개는 엔진 고장 시 위험하고, 8개는 너무 무겁다. 알렉스는 수천 번의 시뮬레이션 끝에 6개가 안전과 효율의 황금비율임을 찾아냈다.여기 그치지 않고 6개의 프로펠러가 각기 다른 회전수(RPM)로 돌며 서로의 소음 파장을 잡아먹는 능동형 소음제어 시스템을 구축했다. 조비 기체가 헬기보다 100배 조용한 이유는 알렉스 스톨이 남긴 이 수학적 정적 덕분이다.알렉스는 사업적인 판단도 뛰어났다. 조벤의 거친 직관을 다듬어 승객 1마일당 비용 최소화라는 냉철한 수익모델을 구축했다. 조비의 기체가 1인승에서 지금의 5인승(S4)으로 진화한 것은 "사람이 더 타야 가격이 내려가고, 그래야 세상이 바뀐다"는 알렉스의 집요한 계산이 바탕이 됐다.두 사람은 단순히 사장과 직원이 아니었다. 금요일 오후면 함께 기타를 치며 노래를 불렀고, 비행 테스트가 성공하는 날엔 아이처럼 서로를 껴안고 울었다. 조벤은 사석에서 늘 이렇게 말했다. "알렉스는 내가 로또에 당첨된 것보다 더 큰 행운이다. 그는 조비의 영혼 그 자체다"2022년 조비가 나사와 공동음향 시험을 통해 발표한 결과에 따르면, S4기체가 고도 500m에서 100노트(약 185km/h)로 순항할 때 지상 소음은 45.2dBA에 불과했다. 이착륙 시에도 100m 거리에서 65dBA 이하를 기록했다. 이는 일상 대화 수준(60dBA)과 비슷하거나 더 낮은 수치다. 조비 측은 "동급 중량 헬리콥터 대비 100배 조용하다"고 밝혔다.경쟁사 아처 에비에이션(NYSE : ACHR)의 ''미드나이트''도 순항 고도 2000피트(약 610m)에서 약 45dBA를 주장하며 조비와 대등한 수준을 내세웠다. 다만 아처의 수치는 자체 설계치로, NASA 등 제3자 검증을 거친 조비와는 데이터의 신뢰도에서 차이가 있다. 독일 볼로콥터의 ''볼로시티''는 멀티콥터 방식(18개 로터)을 채택해 호버링 시 75m 거리에서 65dBA를 기록했다. 파리 공항공사(Groupe ADP)는 실측 결과 "헬리콥터 대비 수배 조용하지만 여전히 청취 가능한 수준"이라고 평가했다.━누가 조비에 대항할까...거인이 되고 있는 현금부자━eVTOL 주요 기업 경쟁 비교 분석/그래픽=이지혜2023년 2월 청천벽력 같은 소식이 들려왔다. 알렉스가 갑작스런 교통사고로 세상을 떠난 것이다. 그의 나이 고작 37세였다. 조벤은 무너져 내렸다. 공식 성명을 발표하는 자리에서 말을 잇지 못하고 오열했다. 조비의 직원들은 그를 기리기 위해 본사에 추모 공간을 마련했고, 그가 좋아했던 음악을 틀며 눈물로 그를 배웅했다. 조벤은 한동안 알렉스의 빈자리를 보며 헛간의 추억에 잠겨 업무를 보지 못할 정도로 깊은 슬픔에 빠졌다.하지만 알렉스가 남긴 수천 장의 설계도와 수식들은 여전히 조비의 서버 안에서 살아 움직이고 있었다. 올해 두바이와 미국의 하늘을 조용히 오갈 조비의 6개 프로펠러의 정숙함은 알렉스가 마지막까지 깎고 다듬었던 수학적 영혼 덕분이다. 조벤은 여전히 중요한 결정을 내릴 때 알렉스의 사진을 보며 "알렉스라면 이 문제를 어떻게 해결했을까"를 반문한다 고 털어놨다.  현재 조비가 보유한 핵심 특허에는 여전히 그의 이름이 새겨져 있다.조비는 현재 드론업체 가운데 가장 많은 자금을 지닌 곳이다. 2025년말 기준 현금성자산 14억달러에 지난 2월 추가로 12억달러(유상증자, 전환사채 발행)가 수혈되면서 금고에는 총 26억달러(약 3.5조 원)라는 거액이 쌓였다. 경쟁사들이 펀딩을 위해 투자자 눈치를 볼 때, 조비는 오직 상용화와 양산에만 집중할 수 있다는 뜻이다. 월가의 관심사는 "누가 얼마나 훌륭한 드론을 만드냐가 아니라, 누가 조비의 자금력을 따라갈 수 있을까"에 집중된다.조비는 최근 오하이오주 데이턴에 70만 평방피트(약 2만평) 규모의 거대 제조 시설을 인수했다. 데이턴은 ''항공의 아버지'' 라이트 형제의 고향이자, 항공 인프라의 심장부다. 조비는 이곳에서 2027년까지 월 4대 이상의 기체 생산 능력을 갖출 계획이다. 한 대씩 정성껏 깎던 공방 수준을 넘어, 컨베이어 벨트 위에서 비행기를 찍어내는 대량양산 시대로 진입한 것이다.이 기적 같은 공정 설계 뒤에는 세계 최대 자동차 제조사인 토요타가 있다. 토요타는 조비의 최대 주주이자 제조 파트너로서, 수십 명의 베테랑 엔지니어를 파견해 토요타 생산 방식(TPS)을 조비 공장에 이식했다. 비행기를 자동차처럼 정밀하고 빠르게 만드는 기술은 조비의 또 다른 힘이다.경쟁사 아처가 기존 항공부품을 사다 조립하는 방식을 택해 초반 경쟁력을 확보할 때 조비는 부품의 90% 이상을 직접 만드는 고집을 부렸다. 초기에는 느려 보였지만, 양산 단계에 들어서자 강력한 시너지를 내고 있다. 외부 공급망에 휘둘리지 않고 자체 입맛에 맞는 고성능 부품을 무한정 찍어낼 수 있기 때문이다. 특히 전기 모터와 배터리 팩의 자체 생산 능력은 조비 기체의 조용한 성능을 유지하면서도 단가를 획기적으로 낮추는 무기가 되고 있다.물론 아처의 판단이 잘못된 것도 아니다. 조비는 부품을 직접 만들기 때문에 모든 부품에 대한 FAA 인증이 필요하고, 시간과 비용이 엄청나게 든다. 반면 아처는 이미 인증된 기존 항공사 부품을 쓰기 때문에 FAA인증이 빠르다. 아처의 기체 미드나잇(Midnight)은 조비보다 소음은 조금 더 크지만, 대량 양산 효율은 더 높을 것으로 평가받는다.조비 에비에이션 주가/그래픽=이지혜', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005324052', 'https://imgnews.pstatic.net/image/008/2026/03/02/0005324052_001_20260303041839330.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-02 13:30:00', 0, true, '2026-03-09 05:48:33.886382') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (668, '“미국, 북한과 조건 없는 대화 열어둬”…남북경협주 ‘불기둥’[이런국장 저런주식]', '코데즈컴바인 13.23% 급등좋은사람들 10%·아난티 4%지난 2019년 판문점서 만난 북미 정상.  연합뉴스미국이 북한과의 ‘전제 조건 없는 대화’ 기조를 재확인했다는 소식에 남북경협주로 분류되는 종목들이 27일 장 초반 일제히 강세를 보이고 있다.이날 코스닥시장에서 오전 9시 47분 현재코데즈컴바인(047770)은 전 거래일 대비 13.23% 오른 5650원에 거래 중이다. 좋은사람들도 9.70% 상승했고,아난티(025980)(4.15%),제이에스티나(026040)(3.12%),일신석재(007110)(1.97%),신원(009270)(2.22%) 등 다른 경협 관련 종목들도 동반 오름세를 나타냈다.조비(001550)(6.12%),인디에프(014990)(6.35%),현대건설(000720)(2.96%) 등도 상승 흐름을 보이고 있다.정부 북핵 수석대표인 정연두 외교부 외교전략정보본부장이 한국시간으로 이날 새벽 “미국이 북한과 전제 조건 없는 대화에 열린 입장에 변함이 없음을 확인했다”고 밝힌 것이 투자심리를 자극한 것으로 보인다.그는 이번 방미 기간 앨리슨 후커 국무부 정무차관, 토마스 디나노 군비통제·국제안보 담당 차관, 마이클 디솜브레 동아태 차관보 등 미 국무부 주요 인사들과 폭넓은 협의를 진행했다고 설명했다.다만, ‘북한과의 조건 없는 대화에 열려 있다’는 미국 측 입장과 관련, 정부 고위 당국자는 북미 간의 접촉이 진행 중인지에 대해 “(북미 간의) 실무접촉 같은 새로운 뉴스는 없다”고 밝혔다.전날 공개된 북한의 제9차 노동당 대회 총화 보고에서 김정은 북한 국무위원장은 북한의 핵보유국 지위를 인정하고 대북 적대시 정책을 철회하면 미국과 좋게 지낼 수 있다는 취지의 언급을 했다.외교가에서는 내달 말부터 4월 초 사이로 예상되는 트럼프 대통령의 중국 방문을 계기로 북미 정상 간 소통이 재개될 가능성에 주목하고 있다. 트럼프 대통령은 1기 집권 당시인 2018년 6월 싱가포르, 2019년 2월 하노이에서 김 위원장과 정상회담을 가졌고, 2019년 6월에는 판문점에서 ‘번개 회동’을 했다.싱가포르 회담에서는 새로운 북미 관계 수립과 한반도 평화체제 구축, 완전한 비핵화 노력 등을 담은 합의문이 도출됐지만, 하노이 회담에서는 비핵화 조치와 제재 완화의 맞교환을 둘러싼 이견으로 구체적 이행 합의에 이르지 못했다. 이후 북미 간 실질적 비핵화 협상은 사실상 중단된 상태다.', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004594196', 'https://imgnews.pstatic.net/image/011/2026/02/27/0004594196_001_20260227095416210.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-27 09:54:16', 0, true, '2026-03-09 05:48:33.886382') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (669, '반토막난 ''조비'' 지금이 주목할때', '마켓 칼럼이 기사는 국내 최대 해외 투자정보 플랫폼한경 글로벌마켓에 게재된 기사입니다.작년 8월 20달러까지 치솟았던 조비에비에이션 주가가 10달러 수준으로 내려왔다. 가장 큰 이유는 최근 이뤄진 대규모 자본 조달에 따른 주식 희석이다. 조비는 작년 10월 이후 유상증자와 전환사채 발행을 통해 총 18억8000만달러를 조달했다.하지만 이번 자금 조달은 상용화와 대량생산 준비를 위한 전략적 투자라는 점에 주목할 필요가 있다. 회사가 보유한 현금은 약 28억달러로 향후 2~3년간의 운영에 충분한 수준으로 평가된다.올해 조비의 목표는 두바이 상용 서비스 개시와 미국 연방항공청(FAA) 형식 인증 획득이다. 두바이에서는 시제기를 통한 비행 테스트가 성공적으로 이뤄졌고, 4곳의 버티포트도 건설 중이다. 인증 이전 단계지만 제한적인 상업 서비스가 연내 시작될 가능성이 크다.미국 서비스도 기대된다. 조비는 5단계 FAA 인증 중 마지막 단계를 밟고 있다. 인증을 위해 총 5대의 전기수직이착륙기(eVTOL)를 제작 중이며, 이 중 첫 번째 기체는 조립을 마쳤다. 인증 절차가 순조롭게 진행된다면 2027년 이전 완료될 가능성도 있다. 인증 전에 서비스를 시작할 수 있는 길이 열렸다는 점도 호재다. 작년 6월 발표된 백악관 행정명령 eIPP(eVTOL Integrated Pilot Program)에 따라 특정 노선에서 시범적으로 조기 운항이 가능해졌다.최근 주가 하락은 기존 투자자에겐 부담이지만 새롭게 진입하려는 투자자에겐 매력적인 기회다. 상용화를 앞두고 불확실성을 해소한 지금이야말로 조비에 다시 주목할 시점이다.이재광 NH투자증권 리서치본부 수석연구원', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005248972', 'https://imgnews.pstatic.net/image/015/2026/02/09/0005248972_001_20260210004309943.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-09 17:46:10', 0, true, '2026-03-09 05:48:33.886382') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (670, '[서울데이터랩]대성에너지 29.95% 폭등…금일 증시 상승률 1위로 마감', '4일 오후 3시 35분 대성에너지(117580)가 등락률 +29.95%로 상승률 1위로 마감했다. 대성에너지는 장 중 10,775,712주가 거래되었으며 주가는 공모가 대비 3,130원 오른 13,580원에 마감했다.한편 대성에너지의 PER은 13.74로 시장 평균과 비교했을 때 보통 수준으로 평가될 수 있으며, ROE는 5.32%로 수익성이 다소 낮은 편이다.이어 상승률 2위 한국석유(004090)는 주가가 29.79% 폭등하며 종가 27,450원에 상승 마감했다. 상승률 3위 극동유화(014530)의 주가는 5,990원으로 29.79% 폭등하며 강세를 보였다. 상승률 4위 한국ANKOR유전(152550)은 29.75% 폭등하며 362원에 마감했다. 상승률 5위 흥아해운(003280)은 24.68%의 급등세를 타고 2,905원에 마감했다.6위 SH에너지화학(002360)은 550원으로 14.58% 급등 마감했다. 7위 STX그린로지스(465770)는 종가 8,350원으로 8.58% 상승 마감했다. 8위 고려산업(002140)은 종가 2,870원으로 7.29% 상승 마감했다. 9위 제일연마(001560)는 11,000원으로 4.46% 상승 마감했다. 10위 남선알미늄(008350)은 1,206원으로 3.08% 상승 마감했다.이밖에도 동양2우B(001527) ▲2.93%, KIWOOM 미국달러선물레버리지(225800) ▲1.61%, 진흥기업우B(002785) ▲1.52%, KIWOOM 미국고배당＆AI테크(0107F0) ▲1.07%, KIWOOM 미국달러선물(138230) ▲0.95%, KIWOOM 미국달러SOFR금리액티브(합성)(460270) ▲0.73%, KIWOOM 미국S＆P500＆배당다우존스비중전환(0127T0) ▲0.52%, 새론오토모티브(075180) ▲0.48%, KIWOOM 미국대형주500월간목표헤지액티브(0084E0) ▲0.45%, KIWOOM 미국S＆P500 TOP10＆배당다우비중전환(0127V0) ▲0.45% 등을 기록하며 금일 증시를 상승으로 마감했다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003622882', 'https://imgnews.pstatic.net/image/081/2026/03/04/0003622882_001_20260304165321441.png?type=w800', 'NEWS_ETC', NULL, '2026-03-04 16:53:21', 0, true, '2026-03-09 05:48:52.791623') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (671, '기업 공시 [3월 3일]', '<코스피 시장>▲SGC에너지(005090)=1주당 1300원 현금배당 결정, 시가배당률 5.5% ▲환인제약(016580)=1주당 300원 현금배당 결정, 시가배당률 2.5% ▲대한조선(439260)=중대재해 발생으로 내업1공장 내 중량물 취급작업 중단 ▲계룡건설(013580)=882억 원 규모 역곡현대 가로주택정비사업 수주 ▲제일연마(001560)=155억 원 규모 자사주 소각 결정<코스닥 시장>▲대양전기공업(108380)=1주당 200원 현금배당 결정, 시가배당률 0.66% ▲모두투어(080160)=17억 원 규모 자사주 처분 결정 ▲아이티센글로벌(124500)=지난해 영업이익 2799억 원으로 전년 대비 378% 증가', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004595269', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2026-03-03 17:14:17', 0, true, '2026-03-09 05:48:52.791623') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (672, '제일연마, 155억 규모 자사주 220만주 소각…주주가치 제고', '제일연마가 주주가치 제고를 위해 155억원 규모의 자사주 소각을 결정했다고 3일 공시했다.소각 대상 주식은 보통주 220만주이며, 소각 예정 금액은 이사회 결의일 현재 장부가액 기준 155억3640만원이다. 이는 전체 발행주식 총수 980만주의 약 22.4%에 달하는 대규모 물량이다. 이번 소각은 기취득한 자기주식을 활용하며 소각 예정일은 3월30일이다.이번 결정은 배당가능이익 범위 내에서 취득한 자사주를 소각하는 것으로, 주식 수만 줄어들 뿐 실제 자본금의 감소는 없다. 특히 제일연마는 지난 2024년 3월 이사회에서 결의했던 2026년과 2027년 각 10만주 규모의 소각 계획을 이번 220만주 소각으로 대체하기로 했다고 밝혔다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000080162', 'https://imgnews.pstatic.net/image/293/2026/03/03/0000080162_001_20260303135507346.png?type=w800', 'NEWS_ETC', NULL, '2026-03-03 13:55:07', 0, true, '2026-03-09 05:48:52.791623') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (674, '올해 하반기 ''대한민국 엔지니어상'' 17명 시상', '12월 및 여성·영엔지니어 부문 수상자 선정과학기술정보통신부 /뉴스1(서울=뉴스1) 이기범 기자 = 과학기술정보통신부와 한국사업기술진흥협회는 11일 2025년 하반기 ''대한민국 엔지니어상'' 시상식을 열고 수상자로 선정된 17명에게 상패를 수여했다.대한민국 엔지니어상은 산업 기술 혁신을 장려하고 공학자를 우대하기 위해 매월 기술 현장에서 크게 기여한 엔지니어를 선정해 부총리(과기정통부 장관)상과 상금 500만 원을 수여하는 포상 제도다.12월 수상자로는 △(대기업) 진형국 HD한국조선해양 책임연구원, △(중소기업) 이성만 센서테크 상무이사를 선정했다. 하반기 여성 및 영엔지니어 부문 수상자로는 △(여성) 유은영 현대모비스 책임연구원, 조영선 삼아알미늄 팀장, 김연진 일등인터내셔널 대표 △(영) 이강수 제일연마공업 팀장, 이정빈 코모텍 선임연구원을 선정했다.이번 시상식에서는 지난 6월~11월 대기업 및 중소기업 수상자 10명을 포함해 총 17명의 엔지니어를 대상으로 시상이 이뤄졌다.진형국 HD한국조선해양 책임연구원은 "국내 조선 산업의 지속적인 발전과 월등한 기술력 확보를 위해 생산기술 분야 발전에 기여할 수 있도록 최선을 다하겠다"고 말했다.조영선 삼아알미늄 팀장은 "오늘의 수상은 친환경 공정과 포장재 설계에 대해 동료들과 아이디어 교류를 통해 이룬 값진 성과이며, 앞으로도 끊임없이 도전하는 인재가 되겠다"고 소감을 전했다.구혁채 과기정통부 제1차관은 "앞으로도 창의와 기지를 바탕으로 과학기술 및 산업 혁신에 기여해 주시기를 간곡히 부탁드린다"며 "과기정통부는 기업 발전과 산·학·연 협력 활성화를 지속 지원하겠다"고 말했다.', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008655358', 'https://imgnews.pstatic.net/image/421/2025/12/11/0008655358_001_20251211113125173.jpg?type=w800', 'NEWS_ETC', NULL, '2025-12-11 11:30:00', 0, true, '2026-03-09 05:48:52.791623') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (675, '대한민국 엔지니어상 여성부문에 유은영·조영선·김연진', '영 엔지니어에 이강수·이정빈…12월 수상자에 진형국·이성만대한민국 엔지니어상 여성부문 유은영·조영선·김연진(왼쪽부터)[과학기술정보통신부 제공. 재판매 및 DB 금지](서울=연합뉴스) 조승한 기자 = 과학기술정보통신부와 한국산업기술진흥협회는 올해 하반기 대한민국 엔지니어상 여성 부문 수상자로 유은영 현대모비스 책임연구원, 조영선 삼아알미늄 팀장, 김연진 일등인터내셔널 대표를 선정했다고 11일 밝혔다.유 책임연구원은 첨단운전자보조시스템(ADAS) 분야 주행편의기능(LKA, HDA)과 주행안전기능(FCA) 기술 개발 및 양산 적용을 주도했다.조 팀장은 식품포장재 제조 공정에 쓰이는 에틸아세테이트(EA) 용제를 회수·정제해 재활용하는 친환경 합지 공정을 구축해 약 3억원의 원가 절감에 기여했다.김 대표는 국내 최초 방수 및 방화 기능을 가진 맨홀 관로구 안전 기술을 적용해 높은 기밀성과 방재 기능을 갖는 복합재료를 개발했다.이강수 제일연마공업 팀장·이정빈 코모텍 선임연구원(왼쪽부터)[과기정통부 제공. 재판매 및 DB 금지]차세대 리더 성장 지원을 위해 지난해 처음 만들어진 영 엔지니어상에는 이강수 제일연마공업 팀장과 이정빈 코모텍 선임연구원이 선정됐다.이 팀장은 대형 절단휠과 철도 레일연마 공구, 베어링 연삭 및 슈퍼피니싱 하이브리드 연마 디스크를 개발해 연삭공구 성능을 50% 올리고 생산원가 25% 절감에 성공했다.이 선임연구원은 방위산업 구동모터 기술 국산화를 수행하며 기존 중량 대비 출력을 30% 이상 높인 감속기 없는 직구동 추진전동기를 개발하고 수출 성과를 냈다.과기정통부와 산기협은 12월 엔지니어상 수상자로는 진형국 HD한국조선해양 책임연구원과 이성만 센서테크 상무이사를 선정했다.대기업 수상자인 진 책임연구원은 로봇 기반 자동화 기술 및 선체 변형·제어 기술 분야에서 100건 이상 특허를 출원했으며 선체 곡 외판 자동 성형 로봇시스템을 국산화했다.중소기업 수상자인 이 상무이사는 화학·생물·방사능 및 환경 분야 센서 및 분석장비 연구개발·제품화를 수행하며 플라스마 크로마토그래피 기술을 국산화했다.진형국 HD한국조선해양 책임연구원(왼쪽)·이성만 센서테크 상무이사[과기정통부 제공. 재판매 및 DB 금지]shjo@yna.co.kr', NULL, '연합뉴스', 'https://n.news.naver.com/mnews/article/001/0015790807', 'https://imgnews.pstatic.net/image/001/2025/12/11/AKR20251210148400017_01_i_P4_20251211113016667.jpg?type=w800', 'NEWS_ETC', NULL, '2025-12-11 11:30:00', 0, true, '2026-03-09 05:48:52.791623') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (676, '인그리드, AI로 소성로 편차 잡았다... 고온 제조공정 안정성 대폭 향상', '- 경북 포항 제일연마공업에 AI 기반 자동 온도·압력 제어 솔루션 실증- 생산성 향상·불량률 감소·안전사고 예방… 동남권 제조업 AX 전환 가속화고온 소성로의 온도 편차는 오랫동안 제조 현장의 대표적인 불안정 변수로 꼽혀왔다. 데이터 기반 AI·디지털트윈 전문기업 ㈜인그리드는 AI 기반 자동 제어 소성로 시스템을 구축해 고온 제조공정의 고질적인 문제를 해결했다고 밝혔다.이번 사업은 경상북도와 포항시, (재)포항테크노파크 경북디지털혁신본부가 수행하는 ‘광역연계형 AI 솔루션 개발·실증 지원 과제(2025~2026)’를 통해 추진 된 것으로, 인그리드는 창진에스씨와 함께 ‘소성로 제조 공정 최적화를 위한 통합 AI 기반 공정 관리 시스템’을 개발해 수요기업 제일연마공업㈜에 실증 적용했다.<사진설명 = 인그리드가 개발한 AI 연동 소성로 제어 구조>인그리드의 AI 알고리즘은 공정 레시피(목표 온도 곡선)를 실시간 분석해 소성로 상태를 자동으로 제어한다. 압력·온도 변화, 산소 유입 불안정 등 외부 변수가 감지되면 즉시 보정값을 산출해 자동으로 반영하며, 기존 수동 조정 방식 대비 반응 속도와 제어 정밀도가 크게 향상됐다.현장에서는 “작업자가 보던 온도 곡선을 AI가 선제적으로 분석하고 대응한다”는 평가가 나온다. 공정 안정성이 높아지면서 불량률 감소, 품질 균일화, 연료 절감 효과가 동시에 나타나고 있다.인그리드는 이번 실증을 위해 3D 디지털트윈 기반 ‘가상 소성 시뮬레이터’도 구축했다. 실제 설비를 가상공간에 그대로 구현해 공정 조건을 사전 검증함으로써 AI 제어 알고리즘의 위험 요소를 미리 제거할 수 있도록 했다. 실시간 이상 감지 기능도 적용해 공정 중 발생하는 미세한 패턴 변화를 즉시 포착하고, 작업자 개입을 최소화해 인적 오류와 고온 작업에 따른 안전 리스크를 크게 줄였다.메타버스 기반 설비 모니터링 기술과 배출가스·에너지 관리 디지털트윈, 3D 설비–실시간 데이터 인터페이스 기술도 함께 적용돼 고온 공정 전반을 통합 관리하는 AX(디지털 전환) 플랫폼을 완성했다는 평가다.고온 공정은 에너지 소비가 크고 위험도가 높아 ESG 관점에서도 혁신이 요구되는 영역이다. 인그리드의 자동 제어 시스템은 열에너지 낭비를 최소화하고 탄소 배출을 줄이는 동시에, 작업자 개입을 줄여 안전사고 요인을 원천적으로 낮추는 효과를 거뒀다.이번 성과는 포항에서 먼저 검증됐지만 확산 가능성이 더 크다는 점에서 의미가 크다. 인그리드는 내년 아주테크로 실증을 확대하고, 금속·자동차·조선·항공부품 산업이 밀집한 경남·부산·울산 등 동남권 제조벨트로 적용 범위를 넓힐 계획이다. 향후에는 멀티모달 AI와 대규모언어모델(LLM)을 결합한 고도화 플랫폼 개발에도 투자를 이어간다는 방침이다.한편 이번 사업은 과학기술정보통신부와 정보통신산업진흥원(NIPA)이 지원하는 ‘제조업 AI융합 기반 조성 사업(2024~2026)’의 2차년도 과제로, 지역 간 AI 기술을 연계·표준화하고 산업별로 분절된 제조 데이터를 통합·활용하는 기반을 구축하는 데 목적이 있다.', NULL, '매일경제', 'https://n.news.naver.com/mnews/article/009/0005597993', 'https://imgnews.pstatic.net/image/009/2025/11/28/0005597993_001_20251128173214282.jpg?type=w800', 'NEWS_ETC', NULL, '2025-11-28 17:32:14', 0, true, '2026-03-09 05:48:52.791623') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (677, '공장 스스로 데이터 수집… ''현장형 AI''가 포항 철강산업 바꾼다', '수요맞춤형 AI솔루션 개발·실증 지원사업품질 검사 속도 70% 향상정비 효율 25% 개선 효과공정 조건 바뀌어도 자율보정공장서 헬멧 안 쓰면 ''삐삐''포항 한 공장의 성형·압연 작업 라인에서 작업자가 제품 표면과 공정 상태를 가까이서 확인하고 있다. 철강 중소기업 한금과 라라스틸은 포인드 AI 비전검사 시스템을 채택해 검사 속도가 기존보다 70% 향상되고, 불량률은 20% 감소하는 효과를 거뒀다.고열의 강판이 자동화 라인을 따라 이동하면 초정밀 센서와 고해상도 카메라가 실시간으로 움직임을 포착하고 촬영한다. 여기서 들어오는 수많은 데이터를 바탕으로 인공지능(AI)은 품질검사와 결함 검출을 진행한다. ''스마트 AI 공장''으로 변신하고 있는 철강 중소기업 한금과 라라스틸의 모습이다. 이를 통해 이들 기업은 검사 속도가 기존보다 70% 향상되고, 불량률은 20% 감소하는 효과를 거뒀다. 검사 정확도도 95% 이상을 기록했다. AI 기반 품질검사 및 결함 검출 시스템을 공급한 AI 비전검사 전문기업 포인드의 이채수 대표는 "AI가 사람의 판단을 대신해 품질의 표준을 세우는 시대"라며 "데이터 기반 품질 관리가 제조 경쟁력의 핵심으로 자리 잡을 것"이라고 말했다.연구소가 아닌 공장 한가운데서 데이터를 수집·학습해 스스로 판단하는 ''현장형 AI''가 포항의 철강 산업을 탈바꿈시키고 있다. 공정 속도는 빨라지고, 불량률은 줄었으며, 에너지 효율은 올라갔다. 과학기술정보통신부와 정보통신산업진흥원(NIPA)이 지원하고 경북도와 포항시 주관으로 포항테크노파크가 수행 중인 ''제조업 AI 융합 기반 조성사업''을 통해서다. 경북 지역의 주력 산업을 AI 기반으로 전환해 AX(AI 전환)을 촉진하는 국가 핵심 프로젝트로 철강 제조공정의 생산·안전·에너지 관리 전반을 데이터 기반으로 혁신하고 있다. 지난해부터 하위 프로젝트인 ''수요 맞춤형 AI 솔루션 개발·실증 지원사업''을 통해 5개 AI 기업 기술이 제조 현장에 투입돼 가동되고 있다.AI 융합 기술기업 감소프트는 화진철강과 엔다이브의 생산 라인에 시계열 분석 기반의 에너지 절감 및 탄소 저감 솔루션을 구축했다. AI가 설비 전력 데이터를 실시간으로 분석해 피크 시간대 전력 사용을 자동 조정하고, 3D 디지털 트윈 시뮬레이션으로 설비 효율을 시각화한다. 또 AI가 공정별 에너지 흐름을 세밀히 추적해 불필요한 대기전력을 차단하고, 설비별 최적 운전조건을 스스로 계산해 제안하기도 한다. 이들 기업은 AI 제어를 통해 전력 사용량 15% 절감, 생산단가 20% 인하, 탄소 배출량 12% 감소 등 효과를 달성했다. 최성열 감소프트 대표는 "AI는 이제 에너지 효율 향상과 탄소 절감을 달성하는 공장 운영의 핵심 도구가 됐다"며 "데이터 기반의 탄소 관리 체계를 구축해 지속가능한 산업 전환을 선도하겠다"고 말했다.제조 AI 전문기업 에이엠스퀘어는 종합 연마재 제조공장인 제일연마공업에 AI 영상분석 기반 안전 관리 시스템을 구축했다. AI가 CCTV 영상을 실시간 분석해 작업자의 동작과 설비 상태를 감지하고, 방호구 미착용·협착·추락 등 위험 상황을 탐지하면 즉시 경보를 울린다. 위험 상황 탐지 정확도는 95%가 넘는다. 그 결과 사람이 직접 순찰하는 안전순찰 시간도 20% 단축됐다. 황형주 에이엠스퀘어 대표는 "사람이 위험을 보기 전에 AI가 먼저 알려주는 시대"라며 "예측형 안전 관리가 산업 현장의 새로운 표준이 되고 있다"고 말했다.오픈인은 유니온머티리얼의 철강 압연 공정에 AI 기반 강도 예측 및 속도 제어 시스템을 구축했다. AI가 온도·압력·전류 등 센서 데이터를 실시간 분석해 제품 강도를 예측하고, 목표 강도에 도달하면 자동으로 속도를 제어한다. 특히 데이터 누적 학습을 통해 공정 조건이 바뀌어도 스스로 적응하며 품질 편차를 최소화하는 자율 보정 기능을 구현했다. 유니온머티리얼은 이를 통해 생산 속도 12% 향상, 불량률 18% 감소, 정비 효율 25% 개선 효과를 거뒀다. 박정호 오픈인 대표는 "AI가 생산 현장의 리듬을 스스로 조율하는 시대"라며 "데이터가 사람의 감을 대신해 공정을 지휘하는 자율 제조의 전환점이 됐다"고 말했다.AI 수요예측 기업 임팩티브에이아이는 AI 기반 원재료 수요·가격 예측 및 재고 관리 솔루션을 동국산업에 공급했다. AI가 발주 주기, 리드타임, 안전재고 수준을 자동 모니터링하고, 환율·물류·날씨 등 5만여 개 외부 변수를 학습해 가격 변동을 예측한다. 이를 통해 동국산업은 원재료 재고 부족·과잉이 20% 이상 감소하고 업무 시간도 80% 이상 단축하는 성과를 냈다. 정두희 임팩티브에이아이 대표는 "AI가 수급과 가격 흐름을 동시에 읽어내며, 기업의 구매 전략을 더 똑똑하게 만들어주고 있다"고 말했다.AI는 생산성 혁신을 끌어냈을 뿐만 아니라 고급 신규 일자리도 창출하고 있다. 포항테크노파크에 따르면 ''수요 맞춤형 AI 솔루션 개발·실증 지원사업''으로 지난해와 올해 창출된 일자리는 67개에 달한다. 포항테크노파크 관계자는 "AI가 단순 자동화가 아니라 제조 공정 전반의 의사결정 구조를 바꾸는 수준으로 진화하고 있다"며 "에너지·품질·안전·재고·검사 등 제조의 전 과정을 데이터로 연결하고, AI가 실시간으로 판단해 실행하는 체계가 현장에 뿌리내리고 있다"고 말했다.[서정원 기자]', NULL, '매일경제', 'https://n.news.naver.com/mnews/article/009/0005595239', 'https://imgnews.pstatic.net/image/009/2025/11/24/0005595239_001_20251125105418594.jpg?type=w800', 'NEWS_ETC', NULL, '2025-11-24 16:33:21', 0, true, '2026-03-09 05:48:52.791623') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (678, '코스닥 혁신한다는데…AI로 먼저 발견하는 좀비기업 신호는? [재무제표 AI 독해]', '[재무제표 AI 독해]이번엔 밸류업의 가능성이 높은 기업을 찾는 게 아니라 전혀 불가능한 곳을 골라내는 방법에 관한 이야기다.잘된다는 기업에 대한 정보는 수없이 많지만 몇 달 뒤 벌어질 리스크 경고는 의외로 찾기 힘들다. 그나마 가장 객관적인 정보가 재무제표다. 왜냐면 숫자는 거짓말을 못한다.다만 주의할 점은 숫자로 거짓말을 하는 사람들이 있을 뿐이다. 예를 들어 SSD 컨트롤러 제조업체인 파두는 2023년 ‘뻥튀기 상장’ 논란으로 거래가 정지됐다. 2023년 IPO 당시 투자설명서에는 추정 손익계산서를 통해 매출 1200억원 이상의 장밋빛 전망을 제시했다.하지만 상장 이후 공개된 분기보고서는 전혀 다른 숫자를 보여줬다. 시장은 즉각 “상장 근거 자료에 문제가 있었던 것 아니냐”는 의문을 제기했고 결국 거래정지와 상장적격성 실질심사에 돌입할 뻔했다. 최근 관련 사유가 해소되어 주가 역시 빠르게 회복했지만 화려한 IPO를 보여준 기업이 곧바로 상장 폐지가 될 수 있었던 초유의 사태다.<출처 &ndash; DART 파두 투자설명서 2023.7.26>파두의 사례는 상장 당시 고의로 기업가치 정보를 은폐했는지 따지기 위해 상장폐지 절차 직전 단계가 거론되었지만 재무적 위기를 겪는 상장사는 ‘관리종목 지정’이 먼저 찾아온다.관리종목은 “너희 회사, 상장사 치고는 장사 너무~ 못하는 거 아냐?”라는 메시지인데 의외로 투자자들은 2개를 헷갈리고, 3월 감사보고서 시즌에 ‘관리종목 지정’ 공시에 매우 당황한다. 투자자는 ‘내가 잘못 투자했구나! 그런데 왜 미리 못 알았지?’하고 탄식하는데 사실 답은 이미 지난 3분기 보고서 안에 찾아볼 수 있었다.한국 자본시장의 패러다임이 기업가치 제고, 부실기업 신속 처리를 강조하기에 이런 후회를 반복하지 말아야 한다.관리종목 지정과 상장적격성 실질심사우선 두 용어는 비슷해 보이지만 무게는 전혀 다르다.관리종목 지정은 ‘옐로카드’이며 상장적격성 실질심사는 VCR 판독 후 ‘퇴장 여부’를 가리는 단계다. 관리종목 지정은 일정한 계량 기준을 다년간 충족하지 못했을 때 나온다. 매출액 미달(코스닥 기준 30억원 미만), 장기 영업손실(4년 연속), 자본잠식(잠식률 50% 이상), 감사의견 ‘한정’ 등이 조건이다. 지정되면 단일가 매매로 전환되고 신용거래가 막히지만 당장 상장폐지되는 것은 아니다. 말 그대로 ‘경고’다.반면 상장적격성 실질심사는 기업의 지속가능성 자체를 묻는다. 횡령·배임, 분식회계, 불성실공시, 주된 사업의 실체 부재, 혹은 관리종목 사유를 끝내 해소하지 못했을 때 발동된다. 이 단계에 들어가면 즉시 주식 거래가 정지되고 기업심사위원회가 상장 유지, 개선 기간, 상장 폐지 중 하나를 선택한다. 관리종목은 그나마 투자금 회수 등의 시간적 여유가 있으나 상장적격성을 묻을 때는 시간은 투자자의 편이 아니다.특히 2026년부터 시가총액 기준이 관리종목 지정에서 가장 크게 달라지는 점이다. 코스닥 상장사는 시가총액 150억원을 넘겨야 하는데 2027년 200억원, 2028년 300억원으로 단계적으로 올라갈 예정이다. 과거에 40억원이었으니 3.7배 상향된 것이고 “회사의 재무상태는 좋은데 시장이 몰라준다”는 변명이 더 이상 통하지 않는다.시가총액 기준 강화가 얼마나 파급력이 큰지 코스닥 기업을 사례로 살펴보자. 2월 15일 종가 기준 1821개사의 코스닥 기업 중에 이미 관리종목에 지정된 곳이 65개나 있다. 여기에 시가총액 150억원을 적용하면 90개, 200억원이면 136개 회사다.물론 SPAC(기업인수목적회사)가 다수 끼어 있지만 내가 투자하고 있는 회사의 시가총액이 200억원에 미달한다면 투자 경고등을 울려야 한다. 또한 그동안 주가가 1000원 미만이라서 초보 투자자에게 매력적이었던 ‘동전주’는 살얼음판에 서게 된 꼴이다.‘동전주’ 회사는 가뜩이나 재무제표 지표가 안 좋은데 실시간으로 변동하는 주가를 관리(30일 연속 150억원 미달 시)하지 못하면 바로 시장에서 쫓겨날 판이기 때문이다. 회계 기준도 한층 날카로워졌다. 감사범위 제한으로 인한 ‘한정’ 의견만 받아도 관리종목에 직행할 수 있고 의견거절이 2년 연속이면 상장폐지 절차가 시작된다. 2차전지로 인기를 끌었던 금양, 코스피 상장 건설사 범양건영 등은 감사인의 의견거절로 신뢰를 잃었다.<출처 &ndash; 기업공시채널 KIND 투자유의사항: 관리종목 지정 리스트>2026년 투자주의! 관리종목의 계절이 온다이미 경고등이 켜진 기업을 계속 보유하고 있다면 손실은 예측 가능한 결과에 가깝다. 문제는 대부분의 투자자가 위험 신호를 인지하고도 움직이지 않는다는 점이다. 그러나 시장은 기다려주지 않는다. 3~4월은 지난해 결산 결과가 공개되는 시기로 관리종목 지정 여부와 관련된 공시가 집중적으로 쏟아진다. 감사보고서를 통해 감사의견, 자본잠식 여부, 영업손실 지속 여부 등 기업의 재무 상태가 공식적으로 드러나는 시기다.게다가 시장의 구조적 변화 가능성이 높다. 2026년 하반기로 갈수록 관리종목 지정 기업 수가 늘어날 것이다. 이는 단순히 경기 둔화의 결과만은 아니고 ‘한계 기업’을 정리하려는 정책적 의지가 강화되고 있다는 점이 더 중요한 배경이다. 연속적인 감사의견 비적정 기업의 신속한 퇴출, 시가총액 기준을 충족하지 못하는 소형주의 구조조정 등은 시장의 자연스러운 조정이 아니라 의도된 질적 재편 과정에 가깝다. 한국 자본시장이 ‘성장 중심 시장’에서 ‘생존 경쟁 시장’으로 이동하고 있음을 보여준다.코스피 6000의 시대는 시장의 자정 작용이 동반되어야 정착될 수 있다는 신호다. 이러한 환경에서 투자자는 세 가지 관점으로 관리종목 지정 리스크를 관리해야 한다.첫째, 재무제표를 단순 수치가 아닌 질적 관점에서 분석해야 한다. 감사의견이 ‘적정’이라 하더라도 자본잠식률이 높거나 법인세비용차감전계속사업손실 비중이 큰 기업은 잠재 위험군이다.둘째, 시가총액 기준을 단순히 현재 요건 충족 여부로 판단해서는 안 된다. 향후 기준 강화 가능성을 고려해 최소 200억원 이상의 기업가치를 유지할 수 있는 펀더멘털을 갖추었는지 점검해야 한다.셋째, 공시 신뢰도와 지배구조를 투자 판단의 핵심 요소로 포함해야 한다. 불성실공시 이력이 있는 기업은 재무 수치와 무관하게 언제든 시장 신뢰를 잃을 수 있다.2026년 관리종목 지정 확대는 단기적으로 변동성을 키우고 개인 투자자에게 고통을 줄 수 있다. 그러나 장기적으로는 부실 기업의 퇴출을 통해 자본이 생산적인 기업으로 이동하는 계기를 만들 가능성이 크다. 이는 결국 한국 증시의 고질적인 ‘코리아 디스카운트’를 완화하고 시장의 밸류에이션 체질을 개선하는 과정이기도 하다. 2026년은 더 이상 ‘기대’만으로 버틸 수 있는 해가 아니다.관리종목 지정과 상장폐지는 단순한 규제가 아니라 시장이 기업에게 보내는 최종 통지서다. 이 과정은 고통스럽지만 장기적으로는 자본시장을 건강하게 만드는 정화 작업이다. 막연한 테마와 희망 회로 대신 분기마다 공개되는 숫자를 확인하는 것. 그것이 2026년 투자자가 자신의 자산을 지키는 가장 현실적인 방법이다.<AI에게 묻는다>관리종목 위험 점검 핵심 지시어는?상장폐지는 갑자기 오지 않는다. 대부분의 투자자는 뉴스가 나오고 나서야 위험을 인식하지만 기업은 숫자를 통해 신호를 보낸다. 하지만 재무제표의 영업손실, 자본잠식, 감사의견, 법차손 같은 용어는 투자자에게 낯설고 복잡하다. 그렇다면 생성형 AI에게 관리종목 위험을 점검하는 ‘상장 규정의 문법’을 알려주고 나의 투자회사를 점검해야 한다. 미리 알 수 있다면 리스크는 최소화가 가능하다.관리종목 위험 점검 핵심 지시어는 다음과 같다.너는 한국거래소 상장심사 담당자 역할이다. 업로드한 재무제표를 기준으로 해당 기업의 관리종목 지정 가능성을 점검해줘. 다음 항목을 반드시 계산·판단해라.①최근 3년간 법인세비용차감전계속사업손실(법차손) ÷ 자기자본 비율을 각각 계산하고 ②최근 4개 사업연도 영업이익 추이를 정리해줘(재무제표 4년치를 꼭 업로드해야 한다) ③자본총계 추이를 분석해 ④감사의견(적정·한정·의견거절·부적정)을 연도별로 정리하고 ⑤영업현금흐름과 당기순이익을 비교하여 이익의 질(현금 창출 능력)을 평가해라. 위험 징후가 이미 있더라도 현금창출 능력이 있다면 개선기간 동안 탈출할 수 있는 여력이 있다. 마지막으로, 현재 상태를 정상·주의·위험·레드존 4단계로 등급화해라.이승환 재무제표 칼럼니스트', NULL, '한경비즈니스', 'https://n.news.naver.com/mnews/article/050/0000103088', 'https://imgnews.pstatic.net/image/050/2026/03/04/0000103088_001_20260304070109398.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-04 07:01:09', 0, true, '2026-03-09 05:49:11.942167') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (679, '국내 최대 배터리 축제 ‘인터베터리’ 개최…부산 울산업체도 참가', '11~13일 제14회 행사 코엑스에서LG엔솔 삼성SDI SK온 등 대거 참가부산TP 신성정밀공업 등 지역업체도울산TP 이차전지 공동홍보관 마련인터배터리2026에 참가하는 LG에너지솔루션 전시 부스. LG에너지솔루션 제공국내 최대 배터리 전시회인 ‘인터배터리 2026’이 오는 11~13일 서울 강남구 코엑스에서 열린다. 전기차 수요 침체가 지속되는 가운데 각 업체는 도심항공교통(UAM), 전기선박, 로봇, 인공지능(AI)으로 수요처를 다각화해 난관을 돌파하는 비전들을 보여줄 예정이다.▮ 배터리 3사 출격2일 인터배터리에 따르면 이번 행사에는 세계 688개 업체가 2330 부스 규모로 치러진다. 7만5000여 명의 배터리 산업 바이어가 방문할 것으로 예상된다.LG에너지솔루션, 삼성SDI, SK온은 물론 포스코퓨처엠, 고려아연, 에코프로, LG화학, 동원시스템즈 등이 참가한다. LG에너지솔루션은 전기차(EV), 에너지저장장치(ESS) 뿐 아니라 로보틱스, 드론 등 주요 산업에 적용되는 핵심 배터리 기술과 사례를 다채롭게 전시한다. 세계 최대 IT·가전 전시회 CES 2026에서 공개된 홈로봇 LG 클로이드를 비롯해 베어로보틱스 자율주행로봇, 혈액수송용 드론, 항공-큐브위성 등이 대표적이다. 가격과 성능의 균형을 극대화한 LMR(리튬망간리치) 배터리도 처음 선보인다.삼성SDI는 AI 시대를 겨냥한 배터리 비전을 제시한다. 삼성SDI의 핵심 전시물은 AI 시대의 핵심 인프라인 데이터센터에 필요한 초고출력·고품질 배터리 기술이다. 삼성SDI는 참가업체 가운데 최대 규모인 부스 중앙에 무정전전원장치(Uninterruptible Power Supply, UPS), 배터리 백업 유닛(Battery Backup Unit, BBU)용 배터리 설루션을 전시해 AI 데이터센터의 ‘전력 공백 제로화’를 뒷받침하는 초고출력 배터리의 중요성을 강조할 계획이다.SK온 역시 전기차 중심에서 ESS와 로봇 등으로 영역을 확장한 포트폴리오를 전시한다. SK온의 올해 중점 사업은 ESS다. 이번 전시에는 ESS용 고에너지밀도 리튬인산철(LFP) 파우치 배터리를 소개한다. SK온은 LFP 배터리 에너지밀도를 기존 350~450Wh/L에서 500Wh/L 수준으로 높이기 위한 연구개발을 진행 중이다. SK온은 하이니켈 삼원계 배터리가 탑재된 현대위아 물류로봇(AMR, Autonomous Mobile Robot)을 전시한다.포스코퓨처엠은 자율주행 EV, ESS, 휴머노이드 로봇 등 다양한 기기들이 요구하는 특성에 맞는 혁신 소재 설루션을 전면에 내세운다. 자율주행 EV의 주행거리와 안정성을 높이기 위해 니켈 함량을 95% 이상으로 높인 Ultra High-Ni(울트라 하이니켈) 양극재, 저렴한 가격과 긴 수명이 장점으로 ESS와 엔트리급 전기차에 활용되는 LFP 양극재, 높은 에너지 밀도로 로봇 등 차세대 산업의 ‘게임체인저’로 주목받는 전고체 배터리용 양극재와 실리콘 음극재 등 차세대 소재의 개발 현황과 로드맵을 전시한다.삼성SDI 인터배터리 2026 부스 구상도. 삼성SDI 제공SK온 인터배터리 2026 전시관 내 ESS 모습. SK온 제공▮ 동남권 단체 기업도 참가셀 케이스 제조장비 업체인 신성정밀공업(부산 강서구)은 이차전지용 각형·원통형 배터리 케이스 생산 라인과 유지보수 서비스를 턴키 방식으로 제공하는 점을 소개한다. 이 회사는 “고객 요구에 맞춰 유연하게 설계된 맞춤형 생산 라인을 공급한다”고 강조했다. 배터리 제조업체인 부산 사상구 소재 금양은 이번 행사에는 회사 사정으로 불참한다.재단법인 부산테크노파크는 ‘지역특화 프로젝트인 레전드50+’ 특별관을 마련한다. ‘지역특화 프로젝트 레전드 50+’는 지역 중소기업 육성 대표 정책이다. 부산테크노파크는 배터리 관련 유망 기업들을 이번 특별관에서 소개한다. 울산테크노파크는 울산지역 이차전지 공동홍보관을 마련한다. 경남 하동군은 군 단위 지방자치단체로서는 유일하게 이번 전시회에 참가한다. 하동군은 광양만권경제자유구역 하동지구 내 대송산업단지가 이차전지 모빌리티 소재지구 기회발전특구로 지정된 점을 강조할 계획이다.올해 14회를 맞는 인터배터리는 산업통상부가 주최하고 한국배터리산업협회, 코엑스, 코트라가 공동 주관하는 국내 최대 규모의 배터리 산업 전시회다.', NULL, '국제신문', 'https://n.news.naver.com/mnews/article/658/0000136735', 'https://imgnews.pstatic.net/image/658/2026/03/03/0000136735_001_20260303030455441.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-03 03:04:55', 0, true, '2026-03-09 05:49:11.942167') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (680, '금양, 거래정지 속 유증만 7차례 정정…"사실상 상장폐지 수순"', '4050억 유증 납입 7차례 연기…자금 유입 여전히 불투명4월14일 개선기한 코앞…재무구조 개선 입증해야한때 2차전지 대장주로 떠올랐던 금양은 수차례 유상증자 납입 지연으로 자금 조달에 실패하며 상장폐지 위기에 내몰렸다. /금양[더팩트ㅣ박지웅 기자] 부산 ''배터리 신화''로 불리며 2차전지 테마의 상징처럼 떠올랐던 금양이 결국 상장폐지의 갈림길에 섰다. 4000억원대 제3자 배정 유상증자 납입 일정이 7차례나 연기되면서 유동성 위기가 장기화되고, 거래 정지 상태도 이어지고 있다. 시장에선 사실상 상장폐지 수순에 들어갔다는 냉정한 평가가 나온다.23일 금융감독원 전자공시시스템(DART)에 따르면 금양은 4050억원 규모 제3자 배정 유상증자 납입일을 기존 2월 15일에서 3월 31일로 변경했다. 신주 상장 예정일도 3월 9일에서 4월 21일로 조정됐다. 최초 납입 예정일이 지난해 8월 초였다는 점을 감안하면 반년 넘게 자금이 실제로 들어오지 않고 있는 셈이다. 이번 정정 공시는 7차 변경에 해당한다.이번 증자는 사우디아라비아 투자사 ''스카이브 트레이딩&인베스트먼트(SKAEEB)''를 대상으로 한 제3자 배정 방식이다. 그러나 해당 투자사가 납입일을 반복적으로 미루면서 자금 조달 계획은 공시상 일정 변경만 거듭하고 있다. 금양은 홈페이지를 통해 "4월 14일 거래 재개를 목표로 하고 있으며, 현재 임원이 사우디 현지에서 협의를 진행 중"이라고 밝혔지만, 시장의 시선은 차갑다. 실제 입금이 확인되기 전까지는 어떤 설명도 신뢰를 회복하기 어렵다는 분위기다.문제는 이번이 첫 번복이 아니라는 점이다. 금양은 2024년 9월 4500억원 규모 주주배정 유상증자를 추진하겠다고 발표했다가 이듬해 1월 이를 전면 철회했다. 이 과정에서 불성실공시법인으로 지정되며 시장의 신뢰에 상처를 남겼다. 이후 제3자 배정 방식으로 선회했지만 납입 일정은 줄줄이 연기됐다. 계획 발표와 정정 공시가 반복되면서 기업의 자금 조달 능력 자체에 대한 의문이 커지고 있다.자금난은 사업 차질로 직결됐다. 금양이 2023년 9월부터 부산 기장군에 조성해온 이차전지 생산공장 ''기장 팩토리''는 2024년 11월 공사가 중단됐다. 해당 공장은 원통형 2170 배터리셀 양산의 핵심 거점으로, 금양이 미래 성장 동력으로 내세워 온 프로젝트다. 그러나 자금 유입이 지연되면서 공장 준공 일정도 불투명해졌다.금양은 2024년 9월 미국 나노테크에너지(Nanotech Energy)와 17억2000만 달러(약 2조3000억원) 규모의 2170 원통형 배터리셀 공급 계약을 체결했다고 밝힌 바 있다. 당초 공장 준공 이후 납품을 시작할 예정이었으나, 구매주문서(PO)를 변경해 납기를 올해로 연기했다. 변경된 일정에 따르면 올해 4월부터 12월까지 네 차례에 걸쳐 제품을 공급할 계획이다. 하지만 공장 가동이 전제되지 않으면 계약 이행 가능성 역시 장담하기 어렵다는 우려가 제기된다.재무적 위기도 심각하다. 금양은 지난해 외부 감사인으로부터 감사의견 거절을 받았고, 이에 따라 관리종목으로 지정됐다. 주식 거래도 정지된 상태다. 한국거래소는 금양에 4월 14일까지 재무구조 개선 기간을 부여했다. 이 기한 내 가시적인 자금 조달 성과를 내지 못할 경우 상장적격성 실질심사 또는 상장폐지 절차로 이어질 수 있다. 이번 유상증자가 사실상 마지막 카드라는 평가가 나오는 이유다.시장에선 설령 4050억원이 실제 납입되더라도 정상화까지는 갈 길이 멀다는 지적도 나온다. 금양 소액주주 A씨는 "4000억원이 들어와도 밀린 공사대금과 체납 세금, 체불 임금, 각종 지연이자 등을 정리하면 대부분 소진될 가능성이 크다"며 "실제 공장 정상화와 추가 설비 도입, 연구개발 투자, 인력 충원까지 감안하면 최소 1조원 이상이 필요해 보인다"고 주장했다. 그는 "지금 단계에서는 상장폐지 여부를 넘어 회사 존속 자체를 걱정해야 할 상황"이라고 말했다.논란은 제도적 측면으로도 번지고 있다. 코스닥 상장사의 경우 최초 공시한 유상증자 납입일을 6개월 이상 연기하면 불성실공시법인으로 지정된다. 반면 코스피에는 자금 조달 지연에 대한 동일한 명시적 규정이 없다. 금양은 유가증권시장 상장사라는 이유로 납입일이 장기간 미뤄졌음에도 추가 제재를 받지 않고 있다. 시장 공정성과 투자자 보호 측면에서 형평성 문제가 제기되는 배경이다.발로 뛰는 더팩트는 24시간 여러분의 제보를 기다립니다.▶카카오톡: ''더팩트제보'' 검색▶이메일: jebo@tf.co.kr▶뉴스 홈페이지: http://talk.tf.co.kr/bbs/report/write', NULL, '더팩트', 'https://n.news.naver.com/mnews/article/629/0000474538', 'https://imgnews.pstatic.net/image/629/2026/02/23/202696781771809793_20260223105914857.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-23 10:59:14', 0, true, '2026-03-09 05:49:11.942167') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (681, '상장폐지 위기 몰린 금양…유상증자 납입 또 미뤘다', '상장폐지 위기에 몰린 금양이 제3자배정 유상증자 납입일을 또 연기했다.20일 금융감독원 전자공시시스템에 따르면 금양은 4050억원 규모 제3자배정 유상증자 납입일을 이달 15일에서 다음달 31일로 변경했다. 신주 상장 예정일도 3월 9일에서 4월 21일로 늦췄다. 최초 납입일은 지난해 8월 2일이었으나 지금까지 일곱 차례 연기했다. 사우디아라비아 업체 스카이브트레이딩&인베스트먼트가 대금 납입을 미루면서다.금양은 2024년 9월 유상증자 계획을 밝혔다가 철회해 불성실공시법인으로 지정됐다. 부산 기장군에 조성하려던 2차전지 생산공장은 건립이 중단됐고, 지난해 외부 감사인으로부터 ‘감사의견 거절’을 받아 주식 거래도 정지됐다. 거래소는 오는 4월 14일까지 재무 구조 개선 기간을 부여했다.', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005253123', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2026-02-20 17:42:20', 0, true, '2026-03-09 05:49:11.942167') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (682, '금양, 1356억 대출금 연체...상환자금 부족', '금양은 상환 자금이 부족해 대출 원리금이 연체됐다고 20일 공시했다. 연체 금액은 원금 1348억원, 이자 8억원 등 1356억원이다. 금양은 "금융기관과 상환 일정 등 대출 조건 조정을 진행할 예정"이라고 밝혔다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000079690', 'https://imgnews.pstatic.net/image/293/2026/02/20/0000079690_001_20260220165810594.png?type=w800', 'NEWS_ETC', NULL, '2026-02-20 16:58:10', 0, true, '2026-03-09 05:49:11.942167') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (683, '유증 또 연기 금양 “기장공장 위해 모든 투자 수용”', '납입 미룬 투자사 재차 불이행…4050억 일정 7차례 정정고시- 지난 15일서 내달 31일로 변경- 기장공장 정상화 의지도 표명- “준공 급선무… 자금조달 총력”주식 거래정지 상태인 부산의 배터리기업 ‘금양’이 4050억 원 규모의 유상증자 일정을 또 연기했다. 금양은 투자사에 납입일 경과에 따른 계약 불이행 경고를 통보하고 기장군에 조성 중인 이차전지 공장 완공을 최우선 당면과제로 삼아 어떤 투자 방식이라도 받아들이겠다는 뜻을 밝혔다.금양의 부산 기장군 이차전지 공장(드림팩토리2) 전경. 국제신문DB19일 금융감독원 전자공시시스템에 따르면 금양은 4050억 원 규모 유상증자 납입일을 애초 지난 15일에서 다음 달 31일로 변경했다. 7차 정정 고시다.금양은 이날 입장문을 내고 “지난 16일 투자금 납입일 경과에 따른 최종 통보 공문을 투자사에 송부하면서 계약 불이행에 대한 경고를 했다”며 “납입일이 지난 이날까지 납입은 이뤄지지 않고 계약 연장에 관한 답변만 받았다”고 밝혔다. 금양은 기장군 ‘동부산 이-파크 산업단지 이차전지 공장’ 완공 등을 위해 지난해 6월 사우디아라비아에 모회사를 둔 신생법인 ‘스카이브 트레이딩&인베스트먼트’와 총 4050억 원 규모의 제3자배정 유상증자 계약을 체결했다.하지만 투자사가 자금 준비 등의 문제로 금양에 연이어 일정 연기를 요청하면서 금양은 지난해 8월부터 현재까지 유상증자 납입일을 미루고 있다. 지난해 12월 24일 금양은 유상증자 일정 연기를 위한 6차 정정고시를 했고, 최종적으로 지난 15일까지 투자사로부터 자금을 받기로 했으나 성사되지 않았다. 금양 측은 “지난달 8, 13, 27일 등 3회에 걸쳐 투자사에 투자금 납입 현황에 대한 질의 공문을 보냈지만 아무런 답변을 받지 못했다”며 “지난 1일 당사 임원이 직접 사우디아라비아 현지로 갔으며 현재까지도 모회사인 ‘스카이브 홀딩스’ CEO와 투자금 미납입 관련 협의를 진행 중”이라고 설명했다.이런 상황에서 금양은 스카이브 측과 별개로 기장공장 완공을 위한 국내외 자금 조달을 계속 진행한다는 방침이다. 또 기장공장의 준공 및 정상화를 위해 최대주주 등 모든 것을 내려놓겠다는 뜻을 나타냈다.금양 측은 “기장공장을 준공할 수만 있다면 어떤 투자 방식이라도 기꺼이 받아들이고, 최대주주 등 모든 것을 내려놓겠다”며 “반드시 기장공장을 완공해 이차전지 사업을 정상화하고 대규모 해외 배터리 공급 수출계약을 이행하겠다. 급선무 목표는 기장공장 완공”이라고 강조했다.앞서 금양은 지난해 3월 외부 감사인으로부터 의견거절을 받으면서 주식 거래가 정지됐다. 한국거래소는 금양에 대해 상장폐지 사유가 발생했다고 판단, 오는 4월 14일까지 개선기간을 부여했다. 개선기간 만료가 두 달여가 채 남지 않은 상황에서 금양은 투자사의 자금 납입이 이뤄지지 않자 납입일 연기와 함께 기장 공장 정상화에 대한 의지를 표명한 것으로 풀이된다.금양의 투자금 유치가 안갯속을 걸으면서 기장군 이차전지 공장 완공이 불투명한 상태다. 금양은 2023년 9월부터 기장군 동부산 이-파크 일반산업단지 18만1500㎡ 부지에 1조2000억 원이 투입되는 대규모 생산공장(드림팩토리2)을 짓고 있지만 2024년 11월부터 공사가 중단된 상태다.', NULL, '국제신문', 'https://n.news.naver.com/mnews/article/658/0000135703', 'https://imgnews.pstatic.net/image/658/2026/02/19/0000135703_001_20260220030526691.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-19 19:23:11', 0, true, '2026-03-09 05:49:11.942167') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (684, '부산 상장 7개사 ''줄줄이'' 퇴출 위기…"시가총액 8000억대"', '국보 27일 상폐…부산주공·한창·비유테크놀러지 등도 ''초읽기''한국거래소 본사가 있는 부산국제금융센터 앞에 설치된 황소상 (거래소 제공. 재판매 및 DB금지)(부산=뉴스1) 홍윤 기자 = 부산에 본사를 둔 물류기업 ''국보''가 27일 상장폐지를 앞둔 가운데, 부산에서는 총 7곳의 기업이 관리종목으로 지정돼 증권시장 퇴출 위기에 처한 것으로 나타났다. 이들 기업의 시가총액은 약 8183억 원에 달한다.26일 한국거래소 기업공시 채널(KIND)에 따르면 국보는 ‘2년 연속 감사 의견 의견거절’ 등 사유로 지난 12일 상장폐지가 확정돼 16~26일 정리매매가 진행됐다.관련 업계에선 ''국보의 상장폐지는 예견된 수순이었다''는 평가가 나온다. 국보는 작년 5월 19일 상장폐지 공시가 올라왔지만, 효력정지 가처분 신청으로 시간을 벌었다. 그러다 이달 12일 해당 가처분 신청이 기각되며 결국 상장폐지에 이르렀다.국보에 이어 자동차부품 제조사 ''부산주공'', 부동산개발 등을 영위하는 ''한창'', 소프트웨어 개발사 ''비유테크놀러지'' 등도 상장폐지 ''초읽기''에 들어갔단 관측이 나오고 있다. 현재 이들 세 기업은 국보처럼 가처분을 통해 상장폐지 절차를 일시적으로 멈춘 상태다.그러나 개선기간 부여 뒤 당국의 심의를 거쳐 각 기업의 상장폐지가 결정된 데다, 2022년 이후 가처분이 인용된 경우가 극소수란 점에서 이들 기업도 결국 상장폐지에 이를 것이란 전망이 지배적이다.부산주공은 2023년 횡령 및 배임 혐의 사건으로 상장 적격성 실질 심사 대상에 포함됐고 2번에 걸쳐 개선기간을 부여받았다. 한창은 2년 연속 감사 의견 의견거절로 심사 대상에 올랐고, 비유테크놀러지는 기업 존속 능력 불확실성 등에 따른 감사 의견 거절로 거래소로부터 상장폐지 통보를 받았다.부산 지역 관리종목 현황. 총 7개사에 달하며 이들의 시가총액은 총 8000억원에 달한다. 국보의 시총은 정리매매 전 기준 (한국거래소 자료 갈무리. 재판매 및 DB금지)해상통신장비 제조사 ''삼영이엔씨''도 상장폐지가 유력한 기업으로 거론된다. 삼영이엔씨는 횡령 및 배임 혐의 사건 등으로 실질 심사 대상이 됐고 오는 4월 4일 개선기간이 종료된다. 기간 종료일로부터 15일 이내에 개선계획 이행 결과에 대한 평가를 받는 만큼, 4월 중에는 이 회사의 상장폐지 여부가 결정될 것으로 보인다.이 기업은 현재 법원에 회생절차를 신청한 가운데, 경영 분쟁으로 인한 법정 공방이 지속되고 있고, 지난 16일 공시도 번복해 추가로 불성실공시법인 지정이 예고돼 있다.그 외에 금양과 범양건영도 4월 중 상장폐지 여부가 결정될 전망이다. 금양의 경우 2차전지 대장주로 소액주주만 24만 명에 이르고, 범영건영의 경우에도 건설경기의 바로미터가 되는 중견급 건설사라는 점에서 상장폐지 여부가 주목되고 있다.이런 가운데 범양건영은 법원 회생절차를 밟으면서 물류 부문 자회사(고려종합물류) 매각 등 다양한 방안을 검토 중인 것으로 알려졌다. 금양은 제3자배정 유상증자, 단기차입 등을 통해 재무안정성 확보를 위한 자금조달에 나서고 있지만, 작년 8월부터 유상증자 일정을 6차례에 걸쳐 연기하는 등 난항을 겪고 있다.증권업계 관계자는 "부산의 경우 전국에서 상장사 수 대비 관리종목 수가 많은 편에 속한다"며 "부실기업의 신속한 퇴출과 재무 수치 관련 요건 완화 등 정책변화가 실제 상장폐지의 중요한 변수가 될 수 있다"고 분석했다.', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008735272', 'https://imgnews.pstatic.net/image/421/2026/01/26/0008735272_001_20260126162028811.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-26 16:12:13', 0, true, '2026-03-09 05:49:11.942167') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (687, 'KBI동국실업, 준법·부패방지 관리체계 공식 인증', 'KBI동국실업)은 한국경영인증원(KMR)으로부터 부패방지경영시스템(ISO 37001)과 규범준수경영시스템(ISO 37301)에 대한 통합인증을 획득했다고 13일 밝혔다.국제표준화기구(ISO)가 제정한 국제표준으로 ISO 37001은 조직 내 발생 가능한 부패를 예방·탐지·대응하기 위한 반부패 경영시스템이 구축·운영되고 있음을 평가하는 기준이고 ISO 37301은 법규와 윤리 규범을 준수하기 위한 조직 차원의 관리 체계와 준법경영 시스템이 실제로 작동하는지를 종합적으로 평가한다.KBI동국실업은 이번 통합인증을 통해 부패 및 준법 리스크를 체계적으로 관리하고, 관련 법규와 내부 규정을 충실히 준수하기 위한 전사적 준법경영 체계를 구축 및 운영하고 있음을 공식적으로 인정받았다.KBI동국실업은 이번 인증을 계기로 협력사 및 이해관계자와의 신뢰를 더욱 강화하고, 글로벌 수준의 준법 경영을 바탕으로 지속가능한 성장을 이어갈 계획이다.김용희 KBI동국실업 대표는 “이번 ISO 37001·ISO 37301 통합인증은 규범준수시스템과 부패방지경영시스템 구축을 위한 전사적인 노력의 결과”라며 “앞으로도 체계적인 운영과 지속적인 개선을 통해 투명하고 신뢰받는 기업으로 성장해 나가겠다”고 말했다.KBI동국실업이 한국경영인증원(KMR)으로부터 부패방지경영시스템(ISO 37001)과 규범준수경영시스템(ISO 37301)에 대한 통합인증을 획득했다. 사진은 12일 KBI동국실업 신아산공장에서 진행된 인증 수여식에서 김용희(왼쪽) KBI동국실업 대표이사가 인증서를 수여받은 모습. KBI동국실업 제공', NULL, '디지털타임스', 'https://n.news.naver.com/mnews/article/029/0003004663', 'https://imgnews.pstatic.net/image/029/2026/01/13/0003004663_001_20260113171812800.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-01-13 17:17:18', 0, true, '2026-03-09 05:49:31.548637') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (688, 'KB오토텍 "현대차 이어 해외 공조시장 공략"', '희망을 쏘는 강소기업(4) 흑자 전환한 KB오토텍1t 트럭 냉난방 공조 시장 선도육군 이어 인도 타타에 공급노사갈등 줄여 실적 개선 기반"2년 연속 최대 매출 경신할 것"팽현성 KB오토텍 대표가 차량 공조 기술에 관해 설명하고 있다.  원종환 기자지난 9일 충남 아산에 있는 KB오토텍 본사에선 작업자 대여섯 명이 ‘전기버스용 배터리 열 관리 시스템’을 적용한 냉난방 제품을 조립하는 데 한창이었다. 전기 냉난방 장치(히트펌프)를 부착한 이 제품은 올해 초 양산을 시작해 현대자동차에 납품할 예정이다. 5일 취임한 팽현성 KB오토텍 대표는 “지난해 50억원을 투자해 차세대 트럭에 들어갈 냉난방공조(HVAC) 생산 라인을 늘렸다”며 “지난해 흑자 전환한 데 이어 기술 격차를 벌려 업계를 선도할 것”이라고 말했다.◇1t 트럭 공조 장치 독점코스닥시장 상장사 KBI메탈의 비상장 계열사 KB오토텍은 자동차 냉난방공조 전문 업체다. 외국인 근로자 없이 국내 임직원 500여 명이 제품 설계와 생산, 풍동 실험 등 전 공정을 자체적으로 처리한다. 200억원을 들여 지은 풍동 실험실은 온도와 습도, 풍속 등을 자유자재로 조절할 수 있다. 국내 최대 규모로 극한의 기후를 재현해 제품 성능을 확인할 수 있다. 국내 1t 트럭 냉난방공조 장치 시장을 주도하고 승합차 분야에서 과반의 시장 점유율을 유지하는 비결이다.독보적인 입지를 다졌지만 큰 위기를 겪었다. 2016년 시작한 노사 갈등으로 1500억원대 매출 손실이 발생하면서다. 팽 대표는 “연말마다 ‘테크 데이’를 열고 회사의 신기술과 미래 비전을 임직원 전원이 토론하며 노사가 다시 화합해 손실을 최소화해 온 것이 KB오토텍의 숨은 저력”이라며 “이런 문화를 계승하고 모두가 원팀으로 뛸 수 있도록 회사를 만들어갈 것”이라고 강조했다.96개의 기술 특허를 보유한 것도 이 회사의 강점으로 꼽힌다. 인공지능(AI)이 차량 탑승 인원과 위치를 파악해 바람을 효율적으로 보내는 기술이 대표적이다. 계열사인 동국실업과 함께 생산하는 자동차용 복사열 난방 기술은 히터 바람이 나오기 전 사람 몸에 직접 열을 보낼 수 있다.◇군용 냉난방공조로 시장 확대현대차 매출 비중이 80%인 이 회사는 고객층도 넓히고 있다. 지난달 글로벌 자동차 업체의 후방 냉난방공조 제품을 새로 수주했다. 지난해 7월엔 육군 중형표준차(KMTV)에 냉난방공조 제품을 독점 공급하기 시작했다. 인도 최대 자동차 회사 타타모터스가 중동 등에 수출하는 버스에는 KB오토텍의 에어컨이 독점으로 쓰인다. 팽 대표는 “중장기적으로 현대차를 제외한 매출 비중을 40%로 끌어올리는 것이 목표”라고 말했다.이 회사는 2024년 자사 냉난방공조 제품에 특화한 표면실장기술(SMT) 생산 라인을 가동했다. SMT는 인쇄회로기판(PCB) 위에 전자부품을 부착하는 공정 기술이다. 연간 30만 개인 생산능력을 올해 안에 두 배 이상 늘릴 계획이다. 팽 대표는 “범용 제품은 기존의 외주 생산 방식을 유지하되 고난도 기술의 신제품 위주로 자체 설비를 활용할 계획”이라고 설명했다. 이런 성과를 토대로 지난해 최대 매출을 냈을 것으로 회사는 추정하고 있다. 이 회사의 2024년 매출은 2549억원이다.2011년 KBI그룹에 합류한 팽 대표는 14년간 KBI메탈 전기장치 사업을 총괄했다. 그는 “통합 공조 솔루션을 구현할 수 있는 연구개발(R&D)에 적극 투자할 것”이라며 “전장 사업 경험을 살려 올해도 사상 최대인 매출 3000억원을 내겠다”고 포부를 밝혔다.아산=원종환 기자 won0403@hankyung.com', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005235955', 'https://imgnews.pstatic.net/image/015/2026/01/12/0005235955_001_20260113024818757.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-01-12 16:20:26', 0, true, '2026-03-09 05:49:31.548637') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (689, '“형제는 함께 책임지는 것”…KBI그룹, 아름다운 형제 승계', 'KBI그룹 새해 삼남 박한상 회장 체제로10년전 장남 박유상 은퇴 이어차남 박효상 연말 회장직 은퇴3형제 우애로 평화승계 이어가1代 이어 2代까지 온 형제경영포목상서 車부품·소재 등 확장70년만에 매출 3조원 기업으로“아버지 대(代)에서 소중한 가치로 여겼던 형제 우애 경영을 대를 이어 잘 지켜내고 싶습니다.”국내 중견그룹인 KBI그룹을 이끌고 있는 3형제(장남 박유상 고문·차남 박효상 회장·삼남 박한상 부회장)가 크리스마스를 하루 앞둔 지난 24일 서울 용산구 갈월동 KBI그룹 본사 9층 전시관에 모였다. 선친인 고(故) 박재을 갑을그룹 회장대부터 현재까지 KBI그룹의 활약상을 한 눈에 볼 수 있는 공간이었다. 이날 3형제는 아버지의 역사가 남아있는 이곳에서 “지금까지 회사가 잘 성장한 건 큰 형님이 잘 이끄신 덕분” “둘째가 참 잘 했다” “셋째가 우리보다 낫다”며 마음 속 이야기를 서로에게 전했다.KBI그룹 본사 전시관에 모인 3형제. 사진 왼쪽부터 새해 KBI그룹 새 회장을 맡는 삼남 박한상 회장, 차남 박효상 현 회장, 장남 박유상 고문. 김재훈 기자29일 KBI그룹에 따르면 박효상 KBI그룹 회장이 올해 말 전격 사임하고 동생인 박한상 부회장에게 회장직을 승계한다. 지난 2015년 박유상 당시 KBI그룹 회장이 한 살 터울 동생인 박효상 회장에게 직을 물려준 데 이은 두 번째 형제 승계다. 최근 재계에서는 가족간 승계 갈등이 빈번한데, 이들 3형제는 ‘늘 형이 스스로 먼저 물러나는’ 승계를 선택해 눈길을 끈다.재계 한 관계자는 “박효상 회장은 최근 자신은 형님이 맡긴 경영을 책임지고 해 온 것이니, 이제 동생한테 물려줄 때가 왔다는 말을 자주 해왔다”고 말했다.KBI그룹은 대구 서문시장에서 포목상으로 활동하던 고(故) 박재갑·박재을 형제가 1956년 공동 설립한 신한견직이 모태다. 섬유업을 기반으로 빠르게 성장했고, 1974년에는 형제 이름에서 한 글자씩 딴 ‘갑을(甲乙)’ 그룹을 탄생시키며, 형제 회사로 입지를 공고히 다졌다.동생 박재을 창업주는 형님 사후에 갑을그룹을 조카들에게 맡기고, 본인은 1987년 일부 계열사를 기반으로 갑을상사그룹으로 경영분리에 나섰다. 2019년에 KBI그룹으로 사명을 변경한 후 현재 KBI동국실업, KBI메탈, KBI동양철관 등 상장사를 비롯해 총 30여개 계열사를 거느린 매출 3조원대의 중견그룹으로 우뚝 섰다. 특히 올해는 라온저축은행 인수와 상상인저축은행 인수계약으로도 주목받았다.KBI그룹 관계자는 “삼형제 사이에서는 이미 오래 전부터 ‘맏형 박유상이 그룹의 기반과 외형을 키우면 둘째 박효상은 해외사업개발로 발판을 만들고, 막내 박한상은 다음 단계의 그룹 도약을 책임진다’는 공감대가 형성돼 있었다”며 “이번 결정은 오랜 기간 준비된 자연스러운 바통터치에 가깝다”고 설명했다.이같은 아름다운 형제 승계가 가능했던 건 무엇보다 ‘형제간 우애’가 가장 큰 요인으로 꼽힌다. 박유상 고문은 “아버지와 큰아버지 사이도 각별했는데 지금 우리 3형제에겐 아버지 세대의 형제경영 DNA가 고스란히 전해진 것 같다”며 “스웨덴 발렌베리 가문처럼 모범이 되는 기업을 만들고 싶다”며 웃었다.일각에서는 ‘황금 분할’로 불리는 지주사 공동 소유 구조도 평화적 승계를 이끈 요인으로 보고 있다. 그룹 지주사 역할을 하는 KBI국인사업은 장남 박유상 고문이 44%를, 차남 박효상 회장과 삼남 박한상 부회장이 각각 28%씩 소유하고 있다. 어느 한 사람이 다른 두 형제를 압도하는 지분을 가질 수 없는 구조로, 형제 간 합의와 신뢰를 전제로 경영이 이뤄질 수 밖에 없는 것이다.KBI그룹 본사 전시관에 모인 3형제가 부친 고(故)박재을 창업회장이 박정희 대통령으로부터 수출 훈장을 받고 있는 사진을 보며 웃고 있다. 사진 왼쪽부터 차남 박효상 현 회장, 장남 박유상 고문, 새해 KBI그룹 새 회장을 맡는 삼남 박한상 회장. 김재훈 기자박 고문은 KBI그룹 창업자인 선친 박재을 회장이 작고한 1991년부터 2015년까지 회사를 이끌었다. 24년 간 적극적 인수합병(M&A)을 통해 업종 다각화와 매출 성장에 크게 기여했다는 평가다. 지금도 동생들에게 경영 멘토로서 조언을 아끼지 않는다.연말 물러나는 박효상 회장은 2015년 당시 맏형인 박유상 고문의 용퇴 덕분에 2015년 그룹 총수 자리에 올랐다. 박 회장은 지난 10년간 섬유 중심의 사업 구조를 자동차 부품, 소재, 에너지, 건설, 의료 등으로 확장하고 해외 11개국에 생산기지와 영업망을 구축했다.새해 회장에 오르는 삼남 박한상 부회장은 현재 KBI메탈 등 그룹 내 핵심 제조·소재 계열사를 진두지휘하며 의료·건설 부문도 챙기고 있다. 갑을의료재단 이사장, 대한건설협회 경상북도회장 뿐만 아니라 한국경제인연합회 기업경영협의회장도 맡아 활발한 대외활동을 펼치고 있다. 최근 전선·강관 등 미국 수출부터 텍사스 현지 배터리 에너지 저장장치(ESS) 사업까지 굵직한 프로젝트도 성사시켰다.박 부회장은 “수양산 그늘이 천리를 간다는 말처럼, 형님들 덕분에 이 자리에 왔고 더 열심히 하겠다”며 “내실을 잘 다져 장수하는 기업을 일구고 싶다”고 말했다.', NULL, '매일경제', 'https://n.news.naver.com/mnews/article/009/0005614290', 'https://imgnews.pstatic.net/image/009/2025/12/31/0005614290_001_20251231093618041.png?type=w800', 'NEWS_AUTO', NULL, '2025-12-31 08:22:09', 0, true, '2026-03-09 05:49:31.548637') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (690, '"형제는 함께 책임지는 것"… KBI그룹, 아름다운 형제 승계', '새해 삼남 박한상 회장 체제로10년전 장남 박유상 은퇴 이어차남 박효상 연말 회장직 은퇴1代 이어 2代까지 온 형제경영포목상서 車부품·소재 등 확장70년만에 매출 3조원 기업으로KBI그룹 본사 전시관에 모인 3형제. 왼쪽부터 새해 KBI그룹 새 회장을 맡는 삼남 박한상 부회장, 차남 박효상 현 회장, 장남 박유상 고문."아버지 대(代)에서 소중한 가치로 여겼던 형제 우애 경영을 대를 이어 잘 지켜내고 싶습니다."국내 중견그룹인 KBI그룹을 이끌고 있는 3형제(장남 박유상 고문·차남 박효상 회장·삼남 박한상 부회장)가 크리스마스를 하루 앞둔 지난 24일 서울 용산구 갈월동 KBI그룹 본사 9층 전시관에 모였다. 선친인 고(故) 박재을 갑을그룹 회장대부터 현재까지 KBI그룹의 활약상을 한눈에 볼 수 있는 공간이었다. 3형제는 아버지의 역사가 남아 있는 이곳에서 "지금까지 회사가 잘 성장한 건 큰 형님이 잘 이끄신 덕분" "둘째가 참 잘했다" "셋째가 우리보다 낫다"며 마음속 이야기를 서로에게 전했다.30일 KBI그룹에 따르면 박효상 KBI그룹 회장이 올해 말 전격 사임하고 동생인 박한상 부회장에게 회장직을 승계한다. 2015년 당시 박유상 KBI그룹 회장이 한 살 터울 동생인 박효상 회장에게 직을 물려준 데 이은 두 번째 형제 승계다. 최근 재계에서는 가족 간 승계 갈등이 빈번한데, 이들 3형제는 ''늘 형이 스스로 먼저 물러나는'' 승계를 선택해 눈길을 끈다.KBI그룹은 대구 서문시장에서 포목상으로 활동하던 고 박재갑·박재을 형제가 1956년 공동 설립한 신한견직이 모태다. 섬유업을 기반으로 빠르게 성장했고, 1974년 형제 이름에서 한 글자씩 딴 ''갑을(甲乙)그룹''을 탄생시키며, 입지를 공고히 다졌다.동생 박재을 창업주는 형님 사후에 갑을그룹을 조카들에게 맡기고, 본인은 1987년 일부 계열사를 기반으로 갑을상사그룹으로 경영 분리에 나섰다. 2019년에 KBI그룹으로 사명을 변경한 후 현재 KBI동국실업, KBI메탈, KBI동양철관 등 상장사를 비롯해 총 30여 개 계열사를 거느린 매출 3조원대의 중견그룹으로 우뚝 섰다. 올해는 라온저축은행 인수와 상상인저축은행 인수계약으로도 주목받았다.아름다운 형제 승계가 가능했던 건 무엇보다 ''우애''가 가장 큰 요인으로 꼽힌다. 박 고문은 "아버지와 큰아버지 사이도 각별했는데 지금 우리 3형제에겐 아버지 세대의 DNA가 고스란히 전해진 것 같다"며 "스웨덴 발렌베리 가문처럼 모범이 되는 기업을 만들고 싶다"고 웃으며 말했다. 일각에서는 ''황금 분할''로 불리는 지주사 공동 소유 구조도 평화적 승계를 이끈 요인으로 본다. 지주사 역할을 하는 KBI국인산업은 장남 박유상 고문이 44%를, 차남 박효상 회장과 삼남 박한상 부회장이 각각 28%를 소유하고 있다.박유상 고문은 선친 박재을 회장이 작고한 1991년부터 2015년까지 회사를 이끌었다. 24년간 적극적 인수·합병(M&A)을 통해 업종 다각화와 매출 성장에 크게 기여했다는 평가다. 지금도 동생들에게 경영 멘토로서 조언을 아끼지 않는다. 연말에 물러나는 박효상 회장은 2015년 박유상 고문이 용퇴한 후에 그룹 총수 자리에 올랐다. 박효상 회장은 지난 10년간 섬유 중심 사업 구조를 자동차 부품, 소재, 에너지, 건설, 의료 등 분야로 확장하고 해외 11개국에 생산기지와 영업망을 구축했다.새해 회장에 오르는 삼남 박한상 부회장은 현재 KBI메탈 등 그룹 내 핵심 제조·소재 계열사를 진두지휘하며 의료·건설 부문도 챙기고 있다.박 부회장은 "수양산 그늘이 천 리를 간다는 말처럼 형님들 덕분에 이 자리에 왔고 더 열심히 하겠다"며 "내실을 잘 다져 장수기업을 일구고 싶다"고 말했다.[서정원 기자 / 사진 김재훈 기자]', NULL, '매일경제', 'https://n.news.naver.com/mnews/article/009/0005614041', 'https://imgnews.pstatic.net/image/009/2025/12/30/0005614041_001_20251231130907232.jpg?type=w800', 'NEWS_AUTO', NULL, '2025-12-30 17:45:14', 0, true, '2026-03-09 05:49:31.548637') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (691, 'KBI그룹 건설부문 ''2026년 무재해 달성'' 결의', '진광우 대표 "안전은 타협할 수 없는 절대원칙"KBI건설은 지난 19일 오후 2시 본사 대회의실에서 임직원 및 전국 현장소장이 참석한 가운데''2026년 무재해 달성 및 안전 최우선 경영 결의 서약식''을 가졌다.ⓒKBI그룹[데일리안 = 백서원 기자] KBI그룹의 건설부문 계열사인 KBI건설은 최근 임직원 및 전국 현장소장이 참석한 가운데 ''2026년 무재해 달성 및 안전 최우선 경영 결의 서약식''을 가졌다고 29일 밝혔다.지난 19일 오후 2시 본사 대회의실에서 진행된 서약식에서 진광우 KBI건설 대표이사는 ‘안전은 타협할 수 없는 절대원칙’이라는 점과 ‘안전하지 않으면 절대 하지 마십시오’라는 강력한 메시지를 전달했다.또한 ‘모든 근로자가 퇴근 후 무사히 가족의 품으로 돌아갈 수 있도록 하는 것은 우리 모두의 최우선 책임’이라고 강조하며 안전예산의 과감한 투자를 약속했다.올해 건설업계가 어려운 시기를 겪고 있지만 KBI건설은 ▲오송 제조혁신센터 ▲KBI동양철관 및 KBI동국실업 태양광 발전소 ▲신정동 근린생활시설 ▲목동 근린생활시설 ▲사부지구 농촌용수개발 ▲외동 공공하수처리시설 ▲500kV 동해안#2 변환소 토건공사 ▲청도군 생활폐기물소각시설증설사업 ▲경상북도 농식품유통교육진흥원 건립공사 ▲여수 세포항 지방어항 건설공사 ▲GTX-B ▲GTX-C 등 총 4,000억원 규모의 수주 잔고를 달성하며 괄목할 만한 성과를 이뤄냈다.내년에도 탄탄한 사업 기반 위에서 전망이 밝지만 원가관리, 공기관리, 품질관리는 기본으로 유지하되 안전을 최우선 가치로 두고 무재해 달성 의지를 천명했다.이번 서약식에서 KBI건설 임직원과 전국 현장소장들은 ▲안전 최우선 원칙 준수 ▲위험 시 작업중지권 행사 ▲원칙과 절차의 철저한 이행 ▲솔선수범하는 안전 리더십 등 4대 안전 실천 원칙을 다짐했다.진광우 KBI건설 대표이사는 "임직원의 강력한 안전 의지와 현장소장들의 결의가 하나로 모아진 뜻 깊은 자리였다"며 "2026년 무재해 목표 달성과 안전을 최우선 가치로 실천하여 탄탄한 수주 기반 위에 안전경영을 더해 지속가능한 성장 동력을 확보할 것"이라고 말했다.', NULL, '데일리안', 'https://n.news.naver.com/mnews/article/119/0003042089', 'https://imgnews.pstatic.net/image/119/2025/12/29/0003042089_001_20251229100509704.jpg?type=w800', 'NEWS_AUTO', NULL, '2025-12-29 10:05:09', 0, true, '2026-03-09 05:49:31.548637') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (692, '글로벌 공급망 ‘윤리 검증’ 시대…한국경영인증원, 부패방지·규범준수경영시스템 확산 본격화', '< 사진 제공 : 한국경영인증원(KMR) >한국경영인증원(KMR)이 부패방지·규범준수경영시스템(ISO 37001·ISO 37301)을 기반으로 한 글로벌 공급망 실사 대응 지원에 본격 나섰다. 2026년부터 강화되는 글로벌 공급망 실사 체계에 대비해, 한국경영인증원은 국내 기업들이 국제 기준에 부합하는 준법·윤리 경영 시스템을 구축할 수 있도록 인증·평가 중심의 전문 역량을 강화하고 있다.글로벌 제조·수출 시장에서 협력사 선정 기준 역시 빠르게 변화하고 있다. 과거에는 품질과 가격 경쟁력이 핵심 요소였다면, 최근에는 투명한 거버넌스와 윤리 경영 체계를 갖추고 있는지가 중요한 판단 기준으로 자리 잡고 있다. 이에 따라 글로벌 발주처들은 협력사 리스크 관리 책임이 확대되면서, 국제표준 인증 여부를 신뢰의 지표로 활용하는 추세다.이 같은 변화의 배경에는 2026년 본격 시행되는 유럽연합(EU)의 기업지속가능성 실사지침(CSDDD)이 있다. 해당 지침은 기업이 자사 사업장뿐만 아니라 가치사슬 전반에 걸쳐 부패, 인권, 환경 리스크를 관리하도록 요구한다. 그 영향은 국내 수출 기업은 물론, 이들과 거래하는 협력사 전반으로 확산하고 있다.업계에서는 협력사가 부패 방지나 규범 준수 체계를 객관적으로 입증하지 못할 경우, 신규 입찰 배제나 기존 거래 중단 등 실질적인 경영 리스크에 직면할 수 있다고 보고 있다. 단순한 윤리 선언이나 내부 규정만으로는 글로벌 발주처의 강화된 실사 요구를 충족하기 어렵다는 분석이다.이러한 환경 변화 속에서 ISO 37001과 ISO 37301의 중요성도 점차 커지고 있다. ISO 37001은 뇌물 수수 등 부패 리스크를 사전에 식별·관리하기 위한 경영시스템 국제표준이며, ISO 37301은 국가별 법규와 산업 규정을 체계적으로 준수하고 있는지를 관리하는 규범준수경영시스템 표준이다. 전문가들은 국제적으로 공인된 ISO 인증 보유 여부가 공급망 평가에서 가장 신뢰도 높은 기준으로 작용하고 있다고 설명한다.국내 수출 산업에서도 이에 대한 선제적 대응이 이어지고 있다. 자동차 부품 업계를 중심으로 현대트랜시스, 디와이덕양, 비츠로셀, 삼보모터스, 프라코, 피에이치에이, 선일다이파스, 엘앤에프, 태양금속공업, KBI동국실업 등 다수의 기업이 한국경영인증원으로부터 ISO 37001 인증을 취득하거나 유지하며, 글로벌 완성차 및 부품사와의 협력 경쟁력을 강화하고 있다.이에 한국경영인증원은 중소·중견 협력사를 대상으로 규제 진단부터 전담 조직 구성, 리스크 식별, 경영시스템 구축, 제3자 검증을 통한 인증 취득까지 단계별 대응 전략도 제시하고 있다.한국경영인증원 관계자는 “ISO 37001과 ISO 37301 도입은 단순한 인증 취득을 넘어, 글로벌 공급망 내에서 지속 가능한 거래 관계를 유지하기 위한 전략적 자산”이라며 “국내 기업들이 변화하는 글로벌 기준에 효과적으로 대응할 수 있도록 체계적인 인증 지원을 이어가겠다”라고 밝혔다.', NULL, '매일경제', 'https://n.news.naver.com/mnews/article/009/0005612965', 'https://imgnews.pstatic.net/image/009/2025/12/29/0005612965_001_20251229090107910.jpg?type=w800', 'NEWS_AUTO', NULL, '2025-12-29 09:01:07', 0, true, '2026-03-09 05:49:31.548637') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (693, '만년적자로 고생한 ''이 회사''…흑자전환 ''대반전'' 비결 [원종환의 中企줌인]', '이은창 KB오토텍 대표 인터뷰''자동차 냉난방공조'' 업계 숨은 강자"만년 적자 탈출하고 흑자전환 예상"KB오토텍 작업자들이 BTMS를 제조하고 있다. 사진=원종환 기자지난 19일 충남 아산에 있는 KB오토텍 본사 생산 라인에 들어서자 작업자 대여섯 명이 ‘전기버스용 배터리 열 관리 시스템(BTMS)’을 적용한 냉난방 제품을 조립하는 데 한창이었다.히트 펌프(전기 냉난방 장치) 두 개를 부착한 이 제품은 내년 초 양산을 시작해 현대차에 납품할 예정이다. 향후 10년간 500억원이 매출이 발생할 것으로 예상되는 국내 최초 제품이다.이은창 KB오토텍 대표는 “약 50억원을 투자해 차세대 트럭에 들어갈 냉난방공조(HVAC) 제품의 생산 라인을 늘리는 등 미래 먹거리 발굴에 적극 나서고 있다”며 “올해는 만년 적자에서 벗어날 것으로 점쳐진다”고 말했다.''테크 데이'' 열어 차세대 공조 기술 주도비상장사인 이 회사는 자동차 냉난방공조 업계의 숨은 강자다. KBI그룹의 계열사로 외국인 근로자 없이 임직원 500여 명이 근무하는 KB오토텍은 제품 설계와 생산, 풍동 실험 등의 전 공정을 자체적으로 소화한다. 200억원을 들여 지은 풍동 실험실은 온도와 습도, 풍속 등을 자유자재로 조절한다.국내 최대 규모로 극한의 기후를 재현해 제품 성능을 확인할 수 있다. 현대차 1t트럭의 냉난방공조 장치를 독점 공급하는 등 승합차 분야에서 과반의 시장 점유율을 유지하고 있다.KB오토텍 풍동 실험실에서 작업자들이 성능 테스트를 하고 있다. 사진=원종환 기자독보적인 입지를 다졌지만 사세가 휘청인 적도 있었다. 2016년 시작한 노사 갈등으로 약 1500억원의 매출 손실이 발생하면서다. 2018년 구원투수로 등판한 이 대표는 회사를 안정화하고 기술개발(R&D) 역량을 회복하는 데 힘썼다.이 대표는 “매해 연말마다 ‘테크 데이’를 열고 회사의 신기술과 미래 비전을 임직원 전원에게 가감 없이 공유하며 소통하고 있다”며 “일감 확보를 위해 합의를 거쳐 노조 사무실 자리에 생산 라인을 구축하는 등 모두가 원팀으로 뛸 수 있도록 노력하고 있다”고 강조했다.여러 신기술을 상용화하려고 노력하고 있다. 인공지능(AI)이 차량의 탑승 인원과 위치를 파악해 사람에게 효율적으로 바람을 보내는 기술이 대표적이다.계열사인 동국실업과 협업해 만들고 있는 자동차용 복사열 난방 기술은 히터 바람이 나오기에 앞서 사람 몸에 직접 열을 쬐도록 해 승차감을 높이는 게 특징이다. 이 회사가 보유한 기술 특허는 96개에 달한다.軍 육군 KMTV 냉난방공조 부품 독점이은창 KB오토텍 대표가 SMT 라인을 설명하고 있다. 사진=원종환 기자최근 고객사 포트폴리오도 다양화하고 있다. 현대차 매출 비중이 80％ 내외인 이 회사는 이달 초 글로벌 자동차 회사의 후방 냉난방공조 제품을 새로 수주했다. 지난 7월 육군 중형표준차(KMTV)에 독점으로 냉난방공조 부품을 공급하고 있다.인도 최대 자동차 회사인 타타모터스가 중동, 아프리카에 수출하는 버스에는 사실상 KB오토텍의 에어컨이 쓰인다. 이 대표는 “중장기적으로 현대차를 제외한 매출 비중을 40％까지 끌어올리는 것이 목표”라고 부연했다.지난해에는 자사 냉난방공조 제품에 맞춤화한 표면실장기술(SMT) 라인을 가동했다. SMT는 인쇄회로기판(PCB)을 위에 전자부품을 부착하는 공정 기술이다. 연간 약 30만 개를 찍어낼 수 있는 생산능력(캐파)을 내년 안에 두 배 이상 늘릴 계획이다.이 대표는 “범용 제품은 기존의 외주 생산 방식을 유지하되 고난도 기술의 신제품 위주로 자체 설비를 활용할 계획”이라고 말했다.지난해 매출 2549억원을 이 회사는 올해 최대 매출이 날 것으로 점쳐지고 있다. 이 대표는 “올해 성과를 발판 삼아 단순한 제조 기업을 넘어 우리만의 제품 솔루션을 제공할 수 있는 기업으로 탈바꿈할 것”이라고 포부를 다졌다.아산=원종환 기자 won0403@hankyung.com', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005227397', 'https://imgnews.pstatic.net/image/015/2025/12/22/0005227397_001_20251222090014198.jpg?type=w800', 'NEWS_AUTO', NULL, '2025-12-22 06:01:20', 0, true, '2026-03-09 05:49:31.548637') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (694, 'KBI그룹, 경북지역 인재 양성위한 장학금 쾌척', 'KBI그룹 계열사 중 KBI건설과 KBI국인산업에서 장학금 마련경북 지역 인재 양성을 위한 지원 지속할 것박한상 KBI그룹 부회장(사진 우측)은 지난 20일 김학동 예천군수와 장학재단 담당자를 만나 KBI건설에서 마련한 장학금 500만원을 전달했다. KBI그룹 제공전선·동소재 사업과 자동차부품 사업을 주력으로 하는 KBI그룹이 경북지역 인재 양성을 위해 장학금을 전달했다고 21일 밝혔다.박한상 KBI그룹 부회장은 20일 봉화군, 영주시, 예천군을 차례로 방문해 각 지역 군수 및 시장, 장학재단 관계자들과 면담을 가졌다.이날 박 부회장은 지역 내 취약계층 학생들의 교육 지원을 위해 KBI건설과 KBI국인산업 명의로 준비한 장학금 1천500만원을 세 지역에 500만원씩 전달했다.KBI국인산업은 4개 사업장 중 군산사업장을 제외한 구미사업장, 왜관사업장, 안동사업장 3곳이 경상북도에 위치해 이 지역사회와 긴밀히 협력하며 특화된 환경사업을 운영하고 있다.구미사업장은 각종 사업장에서 배출되는 폐자원을 소각해 재생에너지(스팀)를 생산하고, 이를 인근 공장의 생산공정에 공급하는 자원순환 사업을 운영 중이다.왜관사업장은 폐기물 중 재사용이 가능한 폐자원을 선별해 재이용·재활용하는 사업을 준비하고 있다.안동사업장은 사용이 종료된 매립시설을 안전하게 사후관리하며, 침출수·지하수·토양에 대한 정기 조사를 실시해 매립 종료 시까지 철저한 환경 안전관리를 이행하고 있다.KBI건설은 경상북도 예천군에 지난 2018년 연면적 8천283㎡, 지하 1층, 지상 4층 규모로 경북도립도서관을 완공했다. 연면적 4천589㎡, 지하 1층, 지상 3층규모로 농식품유통교육진흥원 건립 공사를 조만간 진행할 예정이다.박한상 KBI그룹 부회장은 "지역사회와 함께 성장해온 기업으로서 미래 인재 육성에 기여하는 것은 당연한 책임이기에 어려운 환경 속에서도 꿈을 키워가는 학생들에게 작은 힘이 되길 바란다"며 "앞으로도 경북지역 인재 양성을 위한 지원을 지속해 나가겠다"고 말했다.한편, KBI그룹은 현재 KBI메탈, KBI코스모링크 등 전선·동소재 사업과 KBI동국실업, KB오토텍 등 자동차부품 사업을 주력으로 ▷환경/에너지 ▷건설/부동산 ▷섬유/용기 ▷의료 등 6개 부문에 30여개 계열사를 영위하며 국내외 자동차산업과 각종 인프라 사업 발전에 이바지하며 전세계 11개국 거점에서 글로벌 사업을 활발히 전개 중이다.', NULL, '매일신문', 'https://n.news.naver.com/mnews/article/088/0000982792', 'https://imgnews.pstatic.net/image/088/2025/11/23/0000982792_001_20251123145907504.jpg?type=w800', 'NEWS_AUTO', NULL, '2025-11-23 14:59:07', 0, true, '2026-03-09 05:49:31.548637') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (695, 'KBI그룹, ‘경북지역 인재 양성’ 장학금 전달...“교육 지원 지속”', 'KBI건설·KBI국인산업서 장학금 마련박한상 KBI그룹 부회장(사진 우측)은 임직원들과 함께 지난 20일 예천군을 방문해 김학동 예천군수와 장학재단 담당자를 만나 KBI건설에서 마련한 장학금 500만원을 기탁하고 기념촬영을 했다.ⓒKBI그룹[데일리안 = 백서원 기자] 전선·동소재 사업과 자동차부품 사업을 주력으로 하는 KBI그룹이 경북지역 인재 양성을 위해 장학금을 전달했다고 21일 밝혔다.박한상 KBI그룹 부회장은 전날 봉화군·영주시·예천군을 차례로 방문해 각 지역 군수 및 시장, 장학재단 관계자들과 면담을 가졌다.이날 박 부회장은 지역 내 취약계층 학생들의 교육 지원을 위해 KBI건설과 KBI국인산업 명의로 준비한 장학금 1500만원을 세 지역에 각각 500만원씩 전달했다.KBI국인산업은 4개 사업장 중 군산사업장을 제외한 구미사업장, 왜관사업장, 안동사업장 3곳이 경상북도에 위치해 이 지역사회와 긴밀히 협력하며 특화된 환경사업을 운영하고 있다.구미사업장은 각종 사업장에서 배출되는 폐자원을 소각해 재생에너지(스팀)를 생산하고 이를 인근 공장의 생산공정에 공급하는 자원순환 사업을 운영 중이다. 왜관사업장은 폐기물 중 재사용이 가능한 폐자원을 선별해 재이용·재활용하는 사업을 준비하고 있다. 안동사업장은 사용이 종료된 매립시설을 안전하게 사후관리하며, 침출수·지하수·토양에 대한 정기 조사를 실시해 매립 종료 시까지 철저한 환경 안전관리를 이행해왔다.KBI건설은 경상북도 예천군에 지난 2018년 연면적 8283㎡, 지하 1층, 지상 4층 규모로 경북도립도서관을 완공했고 연면적 4589㎡, 지하 1층, 지상 3층규모로 농식품유통교육진흥원 건립 공사를 조만간 진행할 예정이다.박 부회장은 “지역사회와 함께 성장해온 기업으로서 미래 인재 육성에 기여하는 것은 당연한 책임이기에 어려운 환경 속에서도 꿈을 키워가는 학생들에게 작은 힘이 되길 바란다”며 “앞으로도 경북지역 인재 양성을 위한 지원을 지속해 나가겠다”고 말했다.KBI그룹은 현재 KBI메탈, KBI코스모링크 등 전선·동소재 사업과 KBI동국실업, KB오토텍 등 자동차부품 사업을 주력으로 환경·에너지, 건설·부동산, 섬유·용기, 의료 등 6개 부문에 30여개 계열사를 영위하며 전세계 11개국 거점에서 글로벌 사업을 전개 중이다.', NULL, '데일리안', 'https://n.news.naver.com/mnews/article/119/0003027921', 'https://imgnews.pstatic.net/image/119/2025/11/21/0003027921_001_20251121090208470.jpg?type=w800', 'NEWS_AUTO', NULL, '2025-11-21 09:02:08', 0, true, '2026-03-09 05:49:31.548637') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (768, '[애프터마켓 리뷰] AI 슈퍼사이클 타고 MLCC 가격도 들썩', '■ 모닝벨 ''애프터마켓 리뷰'' - 도지은애프터마켓 정리해 드립니다.최근 기업들의 실적만큼이나 시장에서 뜨거운 관심을 받는 효자 부품이 있죠.바로 MLCC, 적층세라믹 커패시터입니다.어제(23일) 이 MLCC 관련주들의 기세가 대단했습니다.대표적으로 삼성전기가 14%대 급등했고요.삼화콘덴서는 상한가로 마감하면서 기분 좋은 흐름을 보였습니다.반도체가 전자기기의 ''두뇌''라면, 이 MLCC는 두뇌가 안정적으로 작동하도록 전기를 공급하고 관리하는 ''심장''의 역할을 합니다.전류가 일정하고 안정적으로 흐르게 제어해 주는 역할을 하는데, 최근 인공지능 투자 열풍과 함께 많이 필요해진 겁니다.실제로 일반 스마트폰에는 천 개 정도 들어가는 MLCC가, 최신 AI 서버 한 대에는 무려 수십만 개나 들어간다고 하는데요.수요가 이렇게 폭발하다 보니 세계 1위 업체인, 일본의 무라타 제작소는 물론 삼성전기도 가격 인상 기조를 이어갈 가능성이 거론되고 있습니다.업계에서는 AI 붐이 최소 3~5년은 더 갈 것으로 보고 있는데, 반도체뿐만 아니라, 그 반도체를 뒷받침하는 핵심 부품인 MLCC 시장도 이제 막 본격적인 성장 가도에 올라탄 모습입니다.이런 부품주들이 어디까지 우상향 곡선을 그려갈지 계속해서 주목해 봐야겠습니다.한편 어제 코스피가 장중 5900선을 돌파하면서 역사적 고점을 또 한 번 새로 썼습니다.미국 연방대법원이, 도널드 트럼프 대통령의 상호관세 정책에 위법 판단을 내린 점이 투자심리에 영향을 미친 것으로 보입니다.글로벌 단기 불확실성이 해소되고, 앞서 짚었던 것처럼 인공지능 인프라가 확산되면서 MLCC 가격 인상 전망도 긍정적으로 작용했는데요.특히 전자제품, 전자장비, 전기장비, 디스플레이패널 등 반도체 관련주들도 강세 보였습니다.어제 삼성전자, SK하이닉스 각각 2.16%, 0.74% 상승했습니다.반도체 투톱은 연일 사상 최고치를 갈아치우는 중이고요.관세 이슈로 현대차도 3%대 올랐는데, ''관세 폭주''에 제동이 걸린 것 자체는 청신호로 볼 수 있지만, 자동차 등에 대한 품목별 관세는 이번 판결에 영향을 받지 않습니다.반면 LG에너지솔루션은 0.62% 하락으로 마감했습니다.코스닥으로 넘어가 보시죠.코스피에서 상승 흐름을 놓친 개인 투자자들이 특히 코스닥에 집중하고 있는데요.어제저녁에는 알테오젠을 제외하곤 모두 하락으로 마감했습니다.고공 행진하던 삼천당제약이 3.73% 가장 큰 폭으로 빠졌고, 레인보우로보틱스까지 1.26% 하락 마감했습니다.미국의 상호관세 변수에도 개인 투자자들의 매수세가 지수를 떠받쳤는데요.과연 오늘(24일)장 출발 분위기는 어떨지, 잠시 후 프리마켓 통해서 미리 살펴보시죠.애프터마켓 리뷰였습니다.당신의 제보가 뉴스로 만들어집니다.SBS Biz는 여러분의 제보를 기다리고 있습니다.홈페이지 = https://url.kr/9pghjn', NULL, 'SBS Biz', 'https://n.news.naver.com/mnews/article/374/0000493920', 'https://imgnews.pstatic.net/image/374/2026/02/24/0000493920_001_20260224075411981.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-02-24 07:54:11', 0, true, '2026-03-09 05:52:50.425799') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (769, 'LG전자·삼성전기 52주 신고가, 전기·전자 업종 강세[핫종목](종합)', 'LG전자, 美 상호관세 무효 판결·B2B 사업 성장 긍정적삼성전기, AI 서버향 MLCC 가격 인상 호재…관련 업종 동반상승코스피 지수가 종가 기준 사상 최고치를 경신한 23일 오후 서울 중구 하나은행 본점 딜링룸 전광판에 코스피 종가가 표시되고 있다. 이날 코스피는 전 거래일 대비 37.56포인트(0.65%) 오른 5846.09, 코스닥은 2.01포인트(0.17%) 내린 1151.99에 장을 마쳤다. 2026.2.23 ⓒ 뉴스1 오대일 기자(서울=뉴스1) 박주평 기자 = LG전자(066570)가 52주 신고가를 경신하고, 삼성전기(009150)는 사상 최고가를 갈아치우는 등 전기·전자 업종이 강세를 보였다. 미국 상호관세를 무효화는 대법원 판결로 단기 불확실성이 해소되고, 인공지능(AI) 인프라 확산에 따른 적층세라믹콘덴서(MLCC) 가격 인상 전망이 긍정적으로 작용한 것으로 보인다.23일 한국거래소에 따르면 LG전자 주가는 이날 전 거래일 대비 9000원(7.28%) 오른 13만 2600원으로 장을 마감했다. 주가는 장중 한때 13만 9500원까지 오르며 52주 신고가를 경신했다.LG전자 우선주도 12.16% 오른 6만2700원으로 장을 마쳤다.도널드 트럼프 미국 대통령의 상호관세 부과 조치에 제동이 걸리고 로봇 등 신성장동력에 대한 기대가 맞물리면서 주가가 상승한 것으로 풀이된다.앞서 미국 연방대법원은 20일(현지시간) 트럼프 대통령이 국제긴급경제권한법(IEEPA)을 근거로 주요 교역국에 부과한 상호관세에 대해 위법 판결을 내렸다.트럼프 행정부는 IEEPA에 따라 한국 15% 등 각국에 상호관세를 부과한 바 있다. 이에 LG전자, 삼성전자 등은 관세를 적용받지 않는 멕시코 현지 생산을 확대하는 등 생산지 효율화를 통해 관세에 대응해왔다.이번 대법원 판결로 시장에서 불확실성이 해소됐다는 판단이 나오지만, 전자제품에 함유된 철강, 알루미늄 함량에 비례되는 품목관세는 유효하다. 또 트럼프 대통령이 무역법 122조에 근거해 전 세계를 상대로 10% 추가 관세를 부과하는 행정명령에 서명하는 등 여전히 위험 요인이 남아있다.LG전자가 로봇 등 B2B 신사업 성장세가 두드러진 점도 긍정적으로 평가된다. LG전자는 지난달 CES2026에서 AI 홈 로봇 ''클로이드''를 새로 공개하며 가정용 로봇 사업을 적극적으로 육성하겠다는 의지를 드러냈다. 또 로봇 외 냉난방공조, 전장 등 B2B 사업이 기존 주력 사업인 생활가전과 TV 못지않은 수익사업으로 성장하고 있다.삼성전기도 이날 전 거래일 대비 12.20% 오른 42만3000원으로 장을 마감하며 사상 최고가를 새로 썼다.삼성전기를 비롯해 MLCC 관련 기업인 삼화콘덴서공업(001820)(29.99%), 아모텍(052710)(052710)(25.00%), 코칩(126730)(19.17%), 지아이에스(306620)(14.94%) 등도 일제히 급등했다.MLCC는 전기를 저장했다가 반도체 등 능동 제품이 필요로 하는 만큼 전기를 안정적으로 공급하는 일종의 ''댐'' 역할을 하는 부품이다. AI 서버용 MLCC의 경우 일반 제품보다 고용량·고성능이 요구돼 고도의 기술력이 요구되고 그만큼 가격도 비싸다. 세계 최대 MLCC 공급업체인 일본 무라타 제작소와 삼성전기 등 일부 기업이 기술력을 바탕으로 AI 관련 시장을 선도하고 있다.앞서 무라타 제작소는 지난 17일 AI 서버용 MLCC 수요가 공급을 상회하고 있다며 가격 인상 가능성을 시사했다. 업계 선두인 무라타 제작소가 제품 가격을 인상할 경우 MLCC 업계 전반의 가격 인상 흐름으로 연결돼 수익성 제고가 기대된다.이창민 KB증권 연구원은 삼성전기에 대한 목표주가를 기존 37만 원에서 46만 원으로 상향하면서 "AI발 수요 폭증이 본격화되면서 반도체가 그리고 있는 가파른 상승 궤적을 MLCC도 후행할 것"이라고 예상했다.', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008788198', 'https://imgnews.pstatic.net/image/421/2026/02/23/0008788198_001_20260223164223152.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-02-23 16:41:59', 0, true, '2026-03-09 05:52:50.425799') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (696, '종근당홀딩스, 종근당 지분 장내 매수...지분율 0.19%↑', '서울시 서대문구에 위치한 종근당 사옥 전경./종근당종근당홀딩스가 종근당 지분을 추가 매입했다. 최대주주 및 특수관계인 합산 지분율은 40%에 근접했다.5일 금융감독원 전자공시시스템에 따르면 종근당은 최대주주인 종근당홀딩스와 특수관계인 6인의 보유 지분이 직전 보고일(2025년 12월 22일) 대비 0.19%포인트 상승한 39.93%로 집계됐다고 공시했다. 보유 주식 수는 548만5063주에서 551만1063주로 2만6000주 증가했다.지분 변동은 종근당홀딩스의 장내매수에 따른 것이다. 종근당홀딩스는 2월 27일부터 3월 6일까지 5거래일에 걸쳐 ▲2월 27일 5000주 ▲3월 3일 4692주 ▲3월 4일 4308주 ▲3월 5일 6000주 ▲3월 6일 6000주를 각각 매수했다. 이에 따라 종근당홀딩스의 지분율은 26.48%로 높아졌다.', NULL, '조선비즈', 'https://n.news.naver.com/mnews/article/366/0001146171', 'https://imgnews.pstatic.net/image/366/2026/03/05/0001146171_001_20260305182209030.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-05 18:22:09', 0, true, '2026-03-09 05:49:52.399326') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (697, '“훗날 누군가에게 희망을 줄 수 있는 사람이 되겠습니다”...종근당 고촌재단 국내외 403명에 장학금·기숙사 지원', '종근당고촌재단은 지난달 27일 서울 충정로 종근당 본사에서 ‘2026년도 장학증서 수여식’을 가졌다고 3일 밝혔다.종근당고촌재단은 올해 신규 선발된 110명을 포함한 국내·외 장학생 403명에게 졸업시까지 장학금과 무상기숙사를 지원하고, 학술사업 등을 포함한 공익사업 전반에 연간 약 30억원 규모의 장학사업을 진행한다.2월 27일 충정로 종근당빌딩에서 열린 2026년 종근당고촌재단 장학증서 수여식에서 종근당고촌재단 정재정 이사장(왼쪽 네번째), 종근당홀딩스 최희남 대표(왼쪽 첫번째)와 장학생들이 기념촬영을 하고 있다. 종근당 제공선발된 장학생 중 168명에게는 11억원의 학자금 및 생활비 장학금을 지원할 예정이다.학자금 장학생 98명(국내 57명·해외 41명)에게는 대학 등록금을 전액 지급하고, 생활비 장학생 70명에게는 매달 50만원의 생활비를 지원한다.지방 출신 대학생 235명에게는 공과금을 포함한 일체의 비용 부담 없이 거주할 수 있는 무상기숙사 ''종근당고촌학사''를 제공한다. 이를 통해 기숙사 장학생들은 연간 800만원 이상의 주거비를 절감할 수 있어 전체 지원 규모가 연간 약 19억원에 달한다고 재단이 전했다.종근당고촌학사는 전월세난으로 주거 문제를 겪는 지방 출신 대학생들을 위해 설립한 민간 장학재단 최초의 주거지원 시설이다. 청년들이 겪는 어려움을 실질적으로 해결해 보자는 종근당 이장한 회장의 제안으로 마련됐다. 현재 서울 주요 대학 밀집 지역인 마포구 동교동(1호관), 동대문구 휘경동(2호관), 광진구 중곡동(3호관), 영등포구 영등포동(4호관)에서 운영 중이다.올해 장학생으로 선발된 김문경(숙명여대) 학생은 “저의 성장 가능성을 발견하고 미래를 위해 적극 지원해 주신 재단에 감사하다”며 “이번 장학금이 꿈을 향한 강력한 동기부여가 된 만큼, 전공 분야에서 전문성을 쌓아 훗날 누군가에게 다시 희망을 줄 수 있는 사람으로 거듭날 것”이라고 밝혔다.종근당고촌재단 정재정 이사장은 “무한한 가능성을 지닌 학생들이 경제적 어려움 없이 학업에 전념하여 자신의 꿈을 마음껏 펼칠 수 있는 환경을 만드는 것이 재단의 사명”이라며 “장학생들이 전문 지식과 따뜻한 인성을 겸비한 융합형 인재로 성장할 수 있도록 다각적인 지원을 아끼지 않을 것”이라고 말했다.종근당고촌재단은 1973년 기업 이윤의 사회 환원을 목표로 종근당 창업주 고(故) 고촌(高村) 이종근 회장의 사재로 설립된 장학재단이다. 국내를 넘어 인도네시아 베트남 등 해외 장학생까지 지원범위를 확대하고 있으며, 설립 이후 53년간 1만926명에게 761억원을 지원하며 국내 제약기업 최대 규모의 장학사업을 운영하고 있다.', NULL, '세계일보', 'https://n.news.naver.com/mnews/article/022/0004109710', 'https://imgnews.pstatic.net/image/022/2026/03/03/20260303506621_20260303102810234.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-03 10:28:10', 0, true, '2026-03-09 05:49:52.399326') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (698, '종근당홀딩스, 주당 1400원 현금배당 결정', '[헤럴드경제=증권부] 종근당홀딩스는 보통주 1주당 1400원의 현금 결산배당을 결정했다고 25일 공시했다.시가배당율은 2.6%이며 배당금총액은 66억6478만원이다.', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002605002', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2026-02-25 14:43:09', 0, true, '2026-03-09 05:49:52.399326') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (699, '종근당, R&D 부담에 영업익 두 자릿수 감소', '주력·신제품 매출 성장에도매출 6.7%↑·영업익 19%↓“일회성 비용 증가 따른 것”종근당 본사. 사진제공=종근당종근당홀딩스(001630)의 지난해 매출액이 6.7% 증가한 것으로 나타났다.종근당(185750)홀딩스는 2일 지난해 연결 기준 매출이 1조 6924억 원, 영업이익은 806억 원으로 잠정 집계됐다고 공시했다. 매출은 전년 동기 대비 6.7% 증가했지만 영업이익은 19% 줄었다. 같은 기간 당기순이익은 778억 원으로 30.2% 감소했다.매출 증가는 기존 주력 품목과 신제품의 고른 성장에 따른 것으로 분석된다. 회사의 한 관계자는 “위식도역류질환 치료제 펙수클루와 간 기능 개선제 고덱스, 골다공증 치료제 프롤리아, 고지혈증 치료제 리피로우 등 기존 주력 품목이 안정적인 성장세를 이어갔다”며 “항암 관련 신제품 뉴라펙과 비만 치료제 위고비, 항암제 스티바가 등의 매출도 반영됐다”고 설명했다.다만 비용 증가와 일회성 요인이 수익성에 부담으로 작용했다. 회사의 또 다른 관계자는 “판매관리비와 연구개발비가 늘어난 데다 법인세 환급 등 일회성 요인이 발생하면서 영업이익이 감소했다”고 설명했다.증권가에서는 종근당의 중장기 실적에 기대감을 나타내고 있다. 김민정 DS투자증권 연구원은 “올해는 그동안 하향 조정돼 온 종근당의 실적이 안정화되는 해가 될 것”이라며 “파이프라인에서 가시적인 성과가 확인될 경우 국내 동종 제약사 대비 저평가된 종근당의 기업가치가 재평가될 가능성이 있다”고 전망했다.', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004585879', 'https://imgnews.pstatic.net/image/011/2026/02/03/0004585879_001_20260203071214061.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-03 07:12:14', 0, true, '2026-03-09 05:49:52.399326') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (700, '종근당, R&D 부담에 영업익 두 자릿수 감소', '주력·신제품 매출 성장에도매출 6.7%↑·영업익 19%↓“일회성 비용 따른 역기저효과”종근당 본사. 사진제공=종근당종근당홀딩스(001630)의 지난해 영업이익이 전년 대비 두 자릿수 감소했다.종근당(185750)홀딩스는 2일 지난해 연결 기준 매출이 1조 6924억 원, 영업이익은 806억 원으로 잠정 집계됐다고 공시했다. 매출은 전년 동기 대비 6.7% 증가했지만 영업이익은 19% 줄었다. 같은 기간 당기순이익은 778억 원으로 30.2% 감소했다.매출 증가에는 기존 주력 품목과 신제품의 고른 성장이 영향을 미쳤다는 설명이다. 종근당홀딩스 관계자는 “위식도역류질환 치료제 펙수클루와 간 기능 개선제 고덱스, 골다공증 치료제 프롤리아, 고지혈증 치료제 리피로우 등 기존 주력 품목이 안정적인 성장세를 이어갔다”며 “항암 관련 신제품 뉴라펙과 비만 치료제 위고비, 항암제 스티바가 등의 매출도 반영됐다”고 말했다.다만 비용 증가와 일회성 요인이 수익성에 부담으로 작용했다. 회사 측은 “판매관리비와 연구개발비가 늘어난 데다 법인세 환급 등 일회성 요인에 따른 역기저효과가 발생하면서 영업이익이 감소했다”고 설명했다.증권가에서는 종근당의 중장기 실적에 기대감을 나타내고 있다. 김민정 DS투자증권 연구원은 “올해는 그동안 하향 조정돼 온 종근당의 실적이 안정화되는 해가 될 것”이라며 “연구개발(R&D) 모멘텀에 집중할 필요가 있다”고 평가했다.DS투자증권에 따르면 종근당이 시나픽스로부터 도입한 CKD-703은 암세포 성장과 전이에 관여하는 표적 단백질인 c-MET을 겨냥한 항체약물접합체(ADC)로, 지난해 7월 미국 식품의약국(FDA)으로부터 임상 1/2a상 임상시험계획(IND) 승인을 받아 미국에서 임상을 진행 중이다. 경구용 비만 치료제 후보물질 CKD-514는 2026년 하반기 임상 1상 진입이 기대된다.김 연구원은 “파이프라인에서 가시적인 성과가 확인될 경우 국내 동종 제약사 대비 저평가된 종근당의 기업가치가 재평가될 가능성이 있다”고 전망했다.', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004585687', 'https://imgnews.pstatic.net/image/011/2026/02/02/0004585687_001_20260202160712728.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-02 16:07:12', 0, true, '2026-03-09 05:49:52.399326') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (701, '종근당바이오, 보툴리눔톡신 中임상서 비열등성 입증에 급등', '종근당홀딩스도 상승세종근당바이오 CI(사진=종근당바이오 제공) *재판매 및 DB 금지[서울=뉴시스]송혜리 기자 = 종근당바이오가 개발 중인 보툴리눔 톡신이 중국 임상 3상에서 효능을 입증했다는 소식에 따라 회사 주가도 상승세다.20일 한국거래소에 따르면 오전 10시43분 기준 종근당바이오는 전 거래일 대비 17.43% 상승한 2만2500원에 거래 중이다. 같은 시각 종근당홀딩스도 전장보다 4.79% 상승세다.종근당바이오는 개발 중인 보툴리눔 톡신의 중국 임상 3상시험 결과 ''보톡스'' 대비 비열등성을 입증했다고 전날 장 마감 후 공시했다.종근당바이오는 "이번 임상을 통해 CKDB-501A의 중등증 또는 중증의 미간주름 개선에 효과가 있음을 보여줬다"며 "임상결과보고서를 작성해 중국 품목허가를 신청하고자 한다"고 말했다.이어 "CKDB-501A는 제조공정에 비동물성 원료 및 첨가제를 적용해 혈액 유래 병원체 감염 가능성을 최소화한 제품"이라며 "3상 결과를 기반으로 중국 내 미간주름 개선용 보툴리눔 톡신 시장에서의 수입 제품 대체 및 수출 확대 가능성을 봄으로써 경제적 효과를 기대할 수 있다"고 말했다.', NULL, '뉴시스', 'https://n.news.naver.com/mnews/article/003/0013719927', 'https://imgnews.pstatic.net/image/003/2026/01/20/NISI20221226_0001162105_web_20221226142218_20260120105711806.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-20 10:56:28', 0, true, '2026-03-09 05:49:52.399326') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (702, '[어바웃 G] 종근당, 父子 승계 경로 분기점…본체서 이주원 입지 확대', '기업 지배구조(Governance)를 분석합니다./사진=종근당·픽사베이, 이미지 제작=이승준 기자종근당 오너3세인 이주원 상무가 본체 내부에서 직급과 역할을 쌓는 승계경로로 움직이고 있다. 부친인 이장한 회장이 계열사·합자회사를 거쳐 종근당 대표로 직행했던 방식과는 다른 선택이다. 아울러 이 상무는 벨에스엠을 통해 종근당홀딩스 지분과 연결되는 구조를 만들고 있다. 이에 전면에서는 내부 경영수업을 받고 후면에서는 지배구조 연결고리를 구축하는 이중경로가 형성됐다는 분석이 나온다. 이는 종근당의 승계전략이 과거와 달라졌음을 보여준다.본체 내부에서 시작된 이주원 경영트랙/자료=금감원 전자공시시스템, 그래픽=이승준 기자7일 업계에 따르면 이주원은 올해 종근당 정기인사 때 이사에서 상무로 승진했다. 이 상무는 2018년 3월 계열사인 종근당산업의 사내이사를 맡으며 그룹 내 행보를 시작했다. 그는 지난해 정기 임원인사에서 이사보 승진 4년 만에 이사로 올라선 뒤 2년 연속 승진했다. 이 상무는 신약사업기획 담당임원으로서 업무를 이어갈 예정으로, 회사 측은 직급 승진만 이뤄졌다고 설명했다.시장은 이 상무가 종근당 내부에서 단계적으로 직급을 올리고 있다는 데 주목한다. 그는 대표 선임이나 계열사 책임자 이동 없이 본체 조직에서만 직무를 수행해왔다. 승계 국면에서 흔히 나타나는 조기 경영 전면배치와는 다른 흐름이다. 현재까지 이 상무에게 부여된 역할은 조직 내에서의 검증과 경험 축적으로, 승계 속도보다 과정이 먼저 작동하고 있다는 해석이 나오는 이유다.실제로 이 상무는 입사 이후 특정 사업부를 단독으로 총괄하거나 계열사 대표를 맡은 이력이 없는 것으로 알려졌다. 다만 종근당 내에서 직급이 오르며 담당 범위가 점차 넓어지고 있다. 이는 부친인 이 회장이 종근당 합류 당시부터 대표 겸 부회장으로 경영 전면에 나섰던 것과 대비된다. 책임자로 출발한 과거와 달리 현재는 내부축적형 경영 트랙이 선택되며 출발점이 상이해졌다.지분구조에서도 같은 흐름이 확인된다. 지난 10년간의 추이를 보면 이 상무의 종근당 지분은 2017년 13만5000주에서 현재 20만4813주까지 증가했지만 같은 기간 지분율은 1.43%에서 1.48%로 소폭 올랐다. 종근당홀딩스 지분도 2017년 8만589주(1.15%)에서 현재 14만4867주(2.89%)로 늘어나는 데 그쳤다. 경보제약 역시 종근당홀딩스가 지분 43.41%를 보유한 핵심 자회사지만 이 상무의 보유 지분은 3.09%에서 6.21%로 증가했을 뿐이다.계열·합자사 거쳤던 이장한 승계경로/자료=금감원 전자공시시스템, 그래픽=이승준 기자시장은 이 회장의 승계경로가 이 상무의 경우와 구조적으로 다르다고 본다. 이 회장은 안성유리공업, 한국로슈, 한국롱프랑로라제약 등 계열사·합작사에서 임원과 대표 경력을 쌓았다. 이후 1993년 부친인 이종근 선대회장이 별세하면서 종근당 대표 겸 부회장으로 합류한 뒤 곧바로 경영 전면에 나섰고 1994년에는 회장에 올랐다. 본체에서의 경영수업 없이 책임자가 된 것으로, 이 상무와 출발선이 달랐다는 분석은 이에 근거한다.이 같은 경로는 그동안 업계에서 일반적으로 활용되던 승계방식과 궤를 같이한다. 외곽회사나 합작사를 성장시킨 뒤 내부거래와 합병으로 지배회사의 지분을 확보하는 전략이다. 이는 상속·증여 과정에서 발생하는 부담을 낮추기 위한 선택지로 활용돼왔다. 이 회장의 행보 역시 이런 업계의 관행에 따른 것으로 낯선 선택은 아니었다.유사한 방식은 최근 업계 내부에서도 찾을 수 있다. 제일약품의 경우 오너3세인 한상철 대표가 관여한 온코닉테라퓨틱스를 중심으로 지배구조가 형성돼왔다. 온코닉테라퓨닉스는 그룹 외곽에서 신약 파이프라인을 키워 외형을 확장하면서 제일약품 지배구조의 한 축으로 자리 잡았다는 평가를 받아왔다. 외곽회사를 성장시킨 뒤 지배회사와의 연결고리를 만드는 방식이 실현된 사례다.이 상무의 승계경로가 이 회장과 다른 배경으로는 ''환경 변화''가 지적된다. 외곽회사의 성장과 합병을 이용한 지배력 이전은 규제와 시장의 직접적인 감시 대상이 됐다. 환경·사회·지배구조(ESG)가 기업가치 판단의 주요 기준으로 부상하면서다. 이에 따라 지배구조와 내부거래에 대한 공시 부담도 과거보다 커졌다. 같은 방식을 반복하기 어려운 조건이 형성되며 전략 선택의 전제가 달라진 셈이다.벨에스엠 통한 지배구조 연결 유효/자료=금감원 전자공시시스템, 그래픽=이승준 기자향후 경영구도 변화는 ''지배구조 전면과 후면''의 관계 설정에서 나타날 것으로 보인다. 현재까지 종근당은 이 상무를 내세운 외곽회사 활용 전략을 취하지 않고 있다. 다만 그는 본체 임원을 맡아 경영이력을 축적하고 있다. 반면 지배구조 바깥에서는 벨에스엠을 통해 종근당홀딩스의 지분이 연결됐다. 전면과 후면이 분리된 승계구도가 드러난 상황이다.실제로 이 상무가 ''외곽회사 카드''를 전혀 가지지 않은 것은 아니다. 그는 벨에스엠 지분 2만주(40%)를 보유한 최대주주다. 벨에스엠은 2024년 12월에 종근당홀딩스 주주로 처음 등장해 190주를 확보했다. 같은 해 지분을 945주(0.02%), 지난해에는 1만4909주(0.3%)까지 확대했다. 법적 보유 주체는 벨에스엠이지만 지배력 귀속 측면에서는 이 상무와 연결된 지분이다.이 상무의 향후 행보에서 핵심 변수는 전면의 경영트랙과 후면의 지배구조 연결을 ''언제 어떻게 접합하느냐''다. 현재까지는 종근당 본체에서 임원으로서의 경영이력 축적이 우선시되고 지분 측면에서는 벨에스엠을 통한 종근당홀딩스와의 연결이 제한적이기 때문이다. 이에 본체 내부에서의 역할 확대와는 별도로 현재의 지분구조가 향후 어떤 방식으로 재편될지가 관전 포인트로 꼽힌다.종근당 관계자는 "이 상무는 개발전략이라는 역할을 그대로 이어갈 것"이라며 "이번에는 직급만 승진했고 의사결정도 담당임원으로서 할 수 있는 범위 그대로 유지된다"고 설명했다. 또 "이 회장은 1993년 부친이 별세하면서 부회장 겸 대표로 취임했다"면서도 "그는 계열사인 안성유리공업 상무, 합자회사 한국로슈와 한국롱프랑로라제약 대표를 역임한 뒤 경영진으로 합류한 것"이라고 덧붙였다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000077452', 'https://imgnews.pstatic.net/image/293/2026/01/07/0000077452_001_20260107151108354.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-07 14:06:07', 0, true, '2026-03-09 05:49:52.399326') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (703, '이장한 종근당 회장 “AI로 신약개발 속도낼 것”… 오너3세 이주원 상무 승진', '종근당 본사이장한 이장한 종근당 회장은 5일 서울 충정로 본사에서 열린 2026년도 시무식에서 인공지능(AI)을 활용한 신약개발 가속화로 성장의 선순환 구조를 구축해야 한다고 강조했다.이 회장은 이날 신년사를 통해 “올해는 종근당 창립 85주년을 맞는 뜻깊은 해”라며 “비약적인 혁신으로 미래를 선점하겠다는 각오로 ‘지속 성장을 위한 내실 경영의 완성’을 위해 핵심 역량을 집중해야 할 시점”이라고 밝혔다.특히 AI를 둘러싼 산업 환경 변화를 언급하며 위기의식을 강조했다. 이 회장은 “모든 산업 전반에 AI가 본격적으로 적용되는 시대적 변곡점에 접어들었다”며 “AI의 개념을 정확히 이해하고 이를 효과적으로 활용하는 기업만이 생존할 수 있다”고 말했다.이어 “AI 융합 기술을 통해 후보물질 발굴부터 임상 설계에 이르는 전 과정을 획기적으로 단축함으로써 신약개발 속도를 가속화해야 한다”며 “AI를 활용한 연구개발 혁신으로 글로벌 경쟁력을 강화해야 한다”고 강조했다.또한 그는 “AI를 통해 창출된 수익이 다시 연구개발 투자로 이어지고, 그 혁신의 결과가 더 큰 수익으로 환원되는 성장의 선순환 구조를 구축해야 한다”며 “이를 통해 환자를 질병에서 자유롭게 한다는 제약업의 숭고한 사명을 완수해 달라”고 당부했다.한편 종근당과 계열사는 1월 1일 자로 2026년 정기 승진 인사를 단행했다. 이번 인사에서는 이주원 상무의 승진이 특히 주목된다.이주원 상무는 종근당 창업주 고(故) 이종근 회장의 손자이자 이장한 회장의 장남으로 종근당 오너 3세다. 2018년 종근당산업 사내이사로 입사한 뒤 2020년부터 종근당 개발기획팀장을 맡아왔으며 지난해 1월 이사로 승진한 데 이어 1년 만에 상무로 승진했다. 종근당 측은 “이번 승진은 직급 조정에 따른 것으로 기존 담당 업무에는 변화가 없다”고 설명했다.아래는 이번 인사 신규 임원 승진자 명단.[종근당] 총 21명◇ 전무 승진(1명)▲ 이규웅 전무◇ 상무 승진(2명)▲ 이주원 상무▲ 이창식 상무◇ 이사 승진(5명)▲ 심영곤 이사▲ 윤수미 이사▲ 이진오 이사▲ 송지수 이사▲ 정병무 이사◇ 이사보 승진(10명)▲ 경대성 이사보▲ 송영필 이사보▲ 허승제 이사보▲ 이영훈 이사보▲ 김성진 이사보▲ 이강원 이사보▲ 배의섭 이사보▲ 양대혁 이사보▲ 조소라 이사보▲ 이용재 이사보[종근당홀딩스] 총 2명◇ 이사보 승진(2명)▲ 김정호 이사보▲ 김민효 이사보[종근당바이오] 총 3명◇ 이사 승진(1명)▲ 김진오 이사◇ 이사보 승진(2명)▲ 홍대선 이사보▲ 강흥모 이사보[경보제약] 총 5명◇ 사장 승진(1명)▲ 김태영 사장◇ 전무 승진(1명)▲ 채현숙 전무◇ 상무 승진(1명)▲ 김병옥 상무◇ 이사보 승진(2명)▲ 장선희 이사보▲ 현재중 이사보▲ 김영택 이사보[종근당건강] 총 1명◇ 이사보 승진(1명)▲ 김상균 이사보[벨에스엠] 총 1명◇ 이사보 승진(1명)▲ 윤병현 이사보', NULL, '동아일보', 'https://n.news.naver.com/mnews/article/020/0003686902', 'https://imgnews.pstatic.net/image/020/2026/01/05/0003686902_001_20260105161016637.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-05 16:10:16', 0, true, '2026-03-09 05:49:52.399326') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (704, '종근당, 오너 3세 이주원 상무 승진', '경보제약 김태영 대표 사장 승진종근당그룹 이장한 회장의 장남 이주원(39) 이사가 상무로 승진했다.종근당그룹은 지난 1일 임원 인사를 단행했다고 5일 밝혔다.사장, 전무, 상무, 이사 직급 승진자 명단에는 종근당 8명, 종근당바이오 1명, 경보제약 1명이 이름을 올렸다.그중 한 명인 이주원 상무는 종근당 창업주 이종근 회장의 손자이자 이장한 회장의 장남이다. 2018년 종근당산업 사내이사로 입사해 2020년부터 종근당 개발기획팀장을 맡았다. 지난해 1월 이사로 승진한 데 이어 1년 만에 상무로 승진했다. 회사 측은 “직급이 오른 것이고, 기존 업무에 변화는 없다”고 설명했다.계열사 경보제약 김태영 대표는 부사장에서 사장으로 승진했다. 김 대표는 2018년부터 경보제약을 이끌고 있다. 2021년 3월부터 2024년 3월까지 종근당홀딩스 대표를 역임했다.그래픽=정서희', NULL, '조선비즈', 'https://n.news.naver.com/mnews/article/366/0001134287', 'https://imgnews.pstatic.net/image/366/2026/01/05/0001134287_001_20260105164810005.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-05 15:51:17', 0, true, '2026-03-09 05:49:52.399326') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (705, '30주년 맞은 대상 청정원… “일상 책임지는 라이프푸드 브랜드로 도약”', '브랜드 고유 정체성 숫자 30에 투영한 기념 상징물 공개고유 색상과 곡선미 유지해 브랜드 유산 시각적으로 형상화시인성 강화한 BI 리뉴얼 단행으로 온오프라인 경쟁력 제고순창·호밍스 등 대표 품목 패키지에 순차 적용해 고객 접점 확대대상 청정원이 브랜드 출범 30주년을 맞아 그간의 발자취를 기리는 기념 엠블럼을 9일 발표했다.지난 1996년 첫선을 보인 청정원은 장류와 소스, 간편식 등 식품 전반을 아우르며 한국인의 식생활에 깊숙이 자리 잡은 종합식품 브랜드다. 이번에 선보인 엠블럼은 청정원이 지켜온 브랜드 유산을 시각적으로 재해석해 소비자들과 함께 호흡해 온 30년의 세월을 기념하는 취지에서 제작됐다고 한다.30주년 기념 엠블럼은 기존 BI의 핵심 구성 요소를 숫자 30 속에 녹여내 정체성을 명확히 드러내는 데 집중했다. BI 특유의 타원형 구조와 곡선의 흐름을 숫자에 그대로 반영했으며, 상징 색상인 프레시 블루와 트루 옐로우를 사용하여 시각적 통일감을 부여했다.해당 엠블럼은 대형마트를 비롯한 주요 오프라인 매장의 홍보물뿐 아니라, 자사몰, 네이버, 쿠팡, 컬리 등 주요 이커머스 채널의 배너와 제품 상세 페이지에 폭넓게 활용될 예정이다.브랜드 정체성 강화를 위한 BI 고도화 작업도 병행했다. 서체와 심볼의 굵기, 조형적 비례를 세밀하게 조정해 다양한 매체 환경에서도 브랜드 이름이 선명하게 읽히도록 시인성을 개선했다. 개편된 BI는 청정원 순창, 호밍스, 맛선생, 햇살담은 등 주요 제품군 포장에 순차적으로 반영된다.김성준 대상 브랜드디자인팀장은 30년간 축적된 브랜드 DNA를 시각적으로 투영해 청정원만의 차별화된 가치를 전달하고자 했다며, 새로워진 상징물들을 통해 브랜드 존재감을 각인시키고 일상 속 신뢰도를 강화하겠다고 설명했다.대상 청정원은 이달 초부터 소비자 일상 전반을 책임지는 라이프푸드 전문 브랜드로의 도약을 선언하고, 배우 임윤아를 모델로 기용한 캠페인을 전개하며 브랜드 소통을 이어가고 있다.', NULL, '동아일보', 'https://n.news.naver.com/mnews/article/020/0003702432', 'https://imgnews.pstatic.net/image/020/2026/03/09/0003702432_001_20260309114415815.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 11:44:15', 0, true, '2026-03-09 05:50:16.154557') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (706, '대상 청정원, 브랜드 출시 30주년 기념 엠블럼 공개', '[대상 제공. 재판매 및 DB 금지](서울=연합뉴스) 한주홍 기자 = 대상의 식품 브랜드 청정원은 출시 30주년을 맞아 기념 엠블럼을 공개했다고 9일 밝혔다.이번 엠블럼은 청정원 브랜드 이미지(BI)의 타원 형태와 곡선 디자인을 숫자 ''30''에 반영해 브랜드 정체성을 강조한 게 특징이다. 브랜드 대표 색상인 파란색과 노란색도 적용했다.엠블럼은 대형마트 등 오프라인 매장 홍보물과 대상 공식 온라인 쇼핑몰 ''정원e샵'', 네이버·쿠팡 등 온라인 채널 배너와 제품 상세 페이지 등에 활용될 예정이다.청정원은 이와 함께 브랜드 BI도 재단장했다. 글씨체와 마크의 굵기와 비율을 조정해 가독성을 높였다. 새 BI는 청정원 순창, 맛선생 등 주요 제품 패키지에 순차적으로 적용할 계획이다.대상 관계자는 "새로워진 엠블럼과 BI를 앞세워 청정원의 브랜드 존재감을 각인시키고, 브랜드 신뢰도와 친밀도를 강화해 나갈 것"이라고 말했다.juhong@yna.co.kr', NULL, '연합뉴스', 'https://n.news.naver.com/mnews/article/001/0015946660', 'https://imgnews.pstatic.net/image/001/2026/03/09/AKR20260309084100030_01_i_P4_20260309112732325.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 11:27:05', 0, true, '2026-03-09 05:50:16.154557') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (707, '"보기 좋은 떡이"⋯''K-푸드'' 글로벌 디자인 경쟁력까지 입증', '''iF 디자인 어워드'' 등 세계적 권위 어워드서 잇따라 수상 쾌거식품 디자인 중요성 점점 커져⋯브랜드 철학·소비자 경험 요소국내 식품 업체들이 세계적 권위의 디자인 시상식에서 잇따라 수상 소식을 전하고 있다. 단순히 맛을 넘어, 디자인 분야에서도 K-푸드의 글로벌 경쟁력이 입증되고 있다는 평가가 나온다.삼립이 iF 디자인 어워드 2026에서 2관왕을 달성했다. [사진=삼립]9일 식품업계에 따르면 삼립은 ''iF 디자인 어워드 2026''에서 본상 2개를 수상했다. iF디자인 어워드는 지난 1954년 독일 하노버에서 시작된 국제 디자인 경연으로 독일 ''레드닷 디자인 어워드'', 미국 ''IDEA''와 함께 세계 3대 디자인 어워드로 꼽힌다. 이번 어워드는 총 9개 부문 93개 분야에서 전 세계 68개국, 약 1만개 이상의 작품이 출품됐으며, 21개국에서 모인 129명의 전문가로 구성된 심사위원단이 심사를 진행했다.삼립은 ''브랜딩&커뮤니케이션 디자인'' 부문에서 ''재미스''와 ''골든 모먼츠''로 본상을 수상했다. 재미스는 잼을 활용한 삼립의 쿠키 제품으로 ''맛의 즐거움''이란 메시지를 직관적으로 전달하는 데 초점을 맞춰 브랜딩을 전개했다. 로고 디자인은 알파벳 ''m''을 이중(mm)으로 배치해, 음식을 음미할 때의 소리를 시각적으로 형상화했다. 패키지에는 잼의 질감을 연상시키는 그래픽 패턴과 다채로운 색감을 적용해 생동감을 더했다.골든 모먼츠는 선물용 디저트 브랜드로 디저트를 즐기는 순간을 리듬감있는 패턴으로 표현했다. 로고에는 은은하게 반짝이는 빛의 형상을 담아 고급스러움을 더했으며, 파스텔 톤과 생동감 있는 컬러 조합을 패키지에 조화롭게 구현했다.삼립은 2021년 빚은, 2023년 미각제빵소, 2025년 프로젝트:H·삼립약과·크리미화이트폰트 등으로 꾸준히 iF디자인어워드 수상 명단에 이름을 올리고 있다. 지난해에는 레드닷 디자인 어워드에서 출품작 상위 1%에만 수여되는 최우수상을 포함한 4관왕을 달성하기도 했다.iF 디자인 어워드에서 본상을 수상한 아이시스 8.0 초경량. [사진=롯데칠성음료]롯데칠성음료는 올해 iF 디자인 어워드에서 본상 6개를 수상했다. 패키징 부문에서 생수 ''아이시스 8.0 초경량'', 소주 ''새로 다래'', 차 ''더하다'', 수분 보충 음료 ''2% 부족할 때''를 출품해 본상을 수상했다. 브랜딩&커뮤니케이션 디자인 부문에서는 소주 ''새로'' 팝업스토어 ''새로도원'', 제품 디자인 부문에서는 ''새로도원 구슬 식기''로 각각 본상을 받았다.대상 청정원 ''로우태그'' 제품들. [사진=대상]대상 청정원의 저당·저칼로리 엠블럼 ''로우태그'' 캠페인 역시 iF 디자인 어워드 2026에서 브랜드&커뮤니케이션 디자인 부문 본상 수상의 영광을 안았다. 대상의 iF 디자인 어워드 수상은 지난 2023년 ''미원체'', 2024년 ''김치 블라스트 서울''에 이어 세번째다.iF 디자인 어워드 2026 본상 수상한 삼양식품 프리미엄 파스타 브랜드 ''탱글''. [사진=삼양식품]삼양식품의 프리미엄 단백질 파스타 브랜드 ''탱글''도 iF 디자인 어워드 2026 본상 수상에 성공했다. 탱글은 지난해 2025 레드닷 디자인 어워드 커뮤니케이션 디자인 분야 브랜딩, 패키징 부문에서도 각각 본상을 받은 바 있다. 이에 따라 탱글은 세계적인 디자인 어워드에서 2년 연속 수상 성과를 이어가게 됐다.''킹커피'' 패키징 디자인. [사진=서울우유협동조합]서울우유협동조합의 프리미엄 커피·티 블랜딩 브랜드 ''킹커피''는 iF 디자인 어워드 2026에서 패키징 디자인 부분 본상을 수상했다. 함(函)의 재료이자 한국 전통 공예의 정수로 꼽히는 ''자개''를 핵심 디자인으로 브랜드 정체성을 구현한 점이 높이 평가 받았다.최근 소비 과정에서 ''경험''을 중시하는 경향이 뚜렷해지면서, 식품의 패키지·디자인 등은 브랜드 완성도를 결정하는 핵심 요소로 떠오르고 있다. 국내 식품업체들이 주요 디자인 어워드를 석권하면서, K-푸드가 맛은 물론 디자인 분야에서도 글로벌 경쟁력을 입증하고 있다는 평가가 나온다.업계 관계자는 "식품을 고려할 때 맛은 물론이고 디자인의 중요성이 커진 지 오래됐다"며 "브랜드 정체성과 철학을 알리고, 소비자 경험을 확장하는 중요한 요소로 주목받는 분위기"라고 말했다.', NULL, '아이뉴스24', 'https://n.news.naver.com/mnews/article/031/0001011334', 'https://imgnews.pstatic.net/image/031/2026/03/09/0001011334_001_20260309054506625.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 05:45:06', 0, true, '2026-03-09 05:50:16.154557') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (708, '''두쫀쿠'' 다음은 ''봄동''…제철 먹거리 소비 ''제철코어'' 뜬다 [트렌드 경제]', '봄동 도매가격 한 달 새 30%↑…비빔밥·겉절이 등 수요 급증봄나물 마케팅 확산…건강한 제철 음식 소비 트렌드 확산''두바이 쫀득 쿠키''(두쫀쿠)에 이어 ''봄동 비빔밥''이 인기를 끌면서 봄 제철 채소인 봄동 가격이 한 달 새 30% 가까이 오른 것으로 나타났다. 농산물유통정보에 따르면 지난 2일 서울 가락시장 봄동(상 등급) 15kg 평균 도매가는 4만8천841원으로 한 달 전보다도 1만 원 넘게(29%) 올랐다. 지난달 11일엔 같은 등급의 봄동 가격이 6만456원으로 최고점을 찍는 등 최근 한 달간 큰 가격 변동을 보였다. 사진은 4일 서울의 한 시장에서 봄동을 고르는 시민. 연합뉴스전국적인 품귀 현상을 빚었던 ''두쫀쿠''(두바이 쫀득 쿠키)에 이어 ''봄동''이 새로운 대세로 떠올랐다. 봄이 제철인 봄동과 냉이, 달래에 대한 관심이 높아지면서 봄 채소와 나물을 전면에 내세운 마케팅이 활발해지는 분위기다. 계절에 맞는 건강한 음식을 적극적으로 소비하는 ''제철 코어''가 새로운 먹거리 트렌드로 각광받고 있다.배달플랫폼 인기검색어 1위를 차지한 ''봄동 비빔밥''◆ 봄동 가격 한달새 30% 급등최근 젊은 층을 중심으로 봄동 비빔밥이 재조명되고 있다. 아삭한 식감과 달큰한 향, 짧은 시간에 완성이 가능하다는 간편한 레시피로 주목 받으면서다. 추위를 견디고 자란 봄동은 단맛이 강하지만 열량이 낮고 영양소가 풍부하다는 점도 인기 요인이다.높아진 관심 만큼 수요도 급증하면서 가격도 덩달아 오르는 추세다. 8일 한국농수산식품유통공사에 따르면 봄동 15㎏ 한 상자 가락시장 도매가격은 4만7천99원(5일 기준)이다. 이는 한 달 전인 2월 초와 비교하면 33% 이상 오른 수치다.봄동은 통상 11월부터 수확이 시작되지만 한겨울보다 1∼3월 재배 물량이 식감이 좋아 이른 봄까지 수요가 꾸준하다.농림축산식품부 관계자는 "수급에는 문제가 없지만 생산량은 한정돼 있는데 수요가 증가하다 보니 가격이 올랐다"며 "인기가 높아 물량을 조기 출하한 상황으로, 이달 중순까지는 평년 대비 높은 가격이 이어질 가능성이 있다"고 했다.대형마트에서도 봄동을 찾는 수요가 늘었다. 이마트에 따르면 지난달 봄동 판매량은 지난해 같은 기간보다 78.3% 증가했다. 또 배달 플랫폼에서도 봄동 비빔밥이 검색 1위에 오르는 등 관련 메뉴에 대한 관심이 높아지는 분위기다.식품업체 ''대상''의 김치 브랜드 ''종가''는 지난 1월 한정판으로 ''봄동 겉절이''를 출시했다. 대상에 따르면 봄동 겉절이는 출시 두 달 만에 2만개 넘게 팔렸다. 중량으로 따지면 약 22t 규모다.본도시락 냉이 관련 신제품. 본도시락 제공◆ 건강한 제철 음식이 대세봄동뿐 아니라 제철에 맛 볼 수 있는 식재료를 찾는 수요가 증가하고 있다. 자극적인 디저트가 아닌 맛과 건강을 동시에 챙길 수 있는 먹거리를 찾는 것.한식 브랜드 ''본도시락''은 냉이를 활용한 신메뉴 4종을 출시했다. 지난 2014년 출시 후 월 평균 2만 그릇을 판매하며 인기를 얻었던 ''이런 냉이 된장 도시락''을 새롭게 구성해 새로운 메뉴를 만들었다. 여기에 쌈 채소를 추가해 신선함을 더한다는 전략이다.냉이 특유의 향긋한 향과 알알이 톡톡 터지는 보리를 더해 식감까지 살린 ''봄냉이무침''도 제공한다. 쌈장처럼 쌈채소에 올려 먹거나 밥에 비벼 먹도록 해 입맛을 돋우고 산뜻한 생기를 더할 수 있다는 것이 사측의 설명이다.플랫폼에서도 제철 식재료를 접할 수 있도록 관련 서비스를 강화하고 있다.카카오는 새벽배송 허용 추진에 맞춰 장보기 편의성을 높이는 데 역량을 집중하고 있다. 앞서 지난 달 롯데마트와 온라인 장보기 경쟁력 강화를 위한 전략적 업무협약(MOU)을 체결했고 하반기 중 카카오 쇼핑 내 롯데마트 장보기 서비스를 선보인다.향후 카카오는 카카오톡 앱을 통해 손쉽게 장보기를 완료할 수 있도록 이용 편의성을 높인다는 방침이다. 과일·채소·축산·수산물 등 장보기 수요가 높은 신선식품을 비롯해 냉장·냉동 식품, 생활 필수품 등 일상 소비 중심 상품 포트폴리오를 확대한다.업계 관계자는 "짧은 기간 가장 신선한 맛을 즐길 수 있는 제품 음식에 대한 관심이 높다. 이를 반영한 마케팅도 더욱 활발해지는 추세"라고 했다.', NULL, '매일신문', 'https://n.news.naver.com/mnews/article/088/0000999917', 'https://imgnews.pstatic.net/image/088/2026/03/08/0000999917_001_20260308195414062.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-08 12:21:07', 0, true, '2026-03-09 05:50:16.154557') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (709, '증시 급락에 개인 ‘저가 매수’…5조 넘게 사들였다', '■AI 프리즘 [직장인 뉴스]개인, 외국인 매도 맞서 7거래일 연속 순매수기획예산처 여성 관리자 21%→33% 확대전분당 4사, 7년 6개월간 6.2조 원 담합▲ AI 프리즘* 맞춤형 경제 브리핑* 편집자 주: ‘AI PRISM’(Personalized Report &amp; Insight Summarizing Media)은 한국언론진흥재단의 지원을 받아 개발한 ‘인공지능(AI) 기반 맞춤형 뉴스 추천 및 요약 서비스’입니다. 독자 유형별 맞춤 뉴스 6개를 선별해 제공합니다.[주요 이슈 브리핑]■ 스마턴트 부상:코스피가 연일 급락하는 상황에서 개인투자자들이 외국인·기관의 대규모 매도를 받아내며 7거래일 연속 순매수를 이어갔다. 투자자 예탁금은 132조 원을 돌파해 역대 최대치를 경신했고, ETF(상장지수펀드) 분산투자와 바벨 전략(레버리지·안전자산 동시 투자)이 개인 포트폴리오의 주류로 자리 잡았다.■ 공직사회 세대교체:기획예산처가 53회 출신 첫 과장을 발탁하고 1980년대생 과장을 11명으로 확대하는 과장급 정기인사를 단행했다. 여성 관리자 비율이 21%에서 33%로 높아지고 특채·7급 공채 출신 인사를 핵심 보직에 배치하며 성과·역량 중심 인사 기조를 강화했다.■ 식품업계 담합 파문:대상(001680)·사조CPK·삼양사(145990)·CJ제일제당(097950)등 4개 업체가 7년 6개월간 전분당(옥수수 분쇄 원료) 가격을 담합한 혐의로 공정거래위원회 심사보고서를 받았다. 담합 관련 매출액은 6조 2000억 원으로, 최대 1조 2400억 원의 과징금이 예고된다.[신입 직장인 관심 뉴스]1. 재무제표·해외 리포트까지 섭렵…전쟁 뉴스 뜨자 투자실탄 장전- 핵심 요약: 미국·이스라엘의 이란 공습 소식이 전해지자 개인투자자들이 은행 자금을 증권 계좌로 신속히 이동시키며 저가 매수에 나섰다. 코스피가 7.24% 하락한 3일 개인은 5조 7974억 원을 순매수했고, 사상 최대 하락폭(12.06%)을 기록한 4일에도 796억 원을 순매수하며 외국인 매도를 받아냈다. 텔레그램과 유튜브 등 소셜미디어를 통한 정보 수집 채널이 다양해지면서 글로벌 투자은행(IB) 리포트 활용까지 개인투자자의 전략이 고도화되고 있다. 생성형 인공지능(AI)을 활용해 투자 아이디어를 얻거나 재무제표를 분석하는 사례도 늘고 있는 상황이다.2. 기획예산처 첫 과장급 인사 실시…세대교체·여성 관리자 확대- 핵심 요약: 기획예산처가 총괄과장급 인사 연차를 46·47회 중심으로 재편하고 53회 출신 첫 과장을 발탁하는 세대교체 인사를 단행했다. 1980년대생 과장이 지난해 8명에서 11명으로 늘었으며, 최연소 과장으로 1984년생 김남희 재정집행과장이 임명됐다. 여성 관리자 비율은 기존 21%에서 33%로 확대되며 포용사회전략과장·재정혁신총괄과장·예산총괄과장 등 주요 보직에 여성 간부가 배치됐다. 이와 함께 외교부와 국제재정협력과 과장급 교류 직위를 지정하는 등 부처 간 인사 교류도 확대됐다.[신입 직장인 참고 뉴스]3. 전분당도 7년 6개월간 6.2조원 담합…또 1조원대 과징금 예고- 핵심 요약: 공정거래위원회가 대상·사조CPK·삼양사·CJ제일제당 등 4개 전분당(옥수수 분쇄 원료) 제조·판매 업체들에 담합 혐의 심사보고서를 송부했다. 이들 업체는 2018년 5월부터 지난해 10월까지 7년 6개월에 걸쳐 전분당 가격을 반복·조직적으로 담합했으며, 국내 기업간거래(B2B) 전분당 시장에서 점유율 90%를 차지한다. 담합 관련 매출액은 6조 2000억 원으로 앞서 적발된 밀가루 담합(5조 8000억 원)보다 큰 규모이며, 과징금은 최대 1조 2400억 원에 달할 것으로 예상된다. 한편 전분당은 라면·제과·음료·빵 등 식품과 접착·코팅 등 제조업에 두루 쓰이는 원재료로, 가공식품 가격에 간접적 영향을 미쳤을 가능성이 있다는 것이 공정위의 판단이다.4. ‘스마턴트’의 힘…증시 버팀목 됐다- 핵심 요약: ‘스마턴트(스마트+개미의 합성어)’로 불리는 개인투자자들이 7거래일 연속 순매수에 나서며 중동 쇼크 속 코스피 하단을 지지했다. 6일 유가증권시장에서 개인은 2조 9485억 원을 포함해 7거래일간 총 17조 7784억 원을 사들였으며, 이날 코스피는 장중 3.63% 하락 후 전장 대비 0.02% 상승 마감했다. 개별 종목 중심의 투자에서 벗어나 ETF(상장지수펀드)를 통한 분산투자가 주요 전략으로 자리 잡는 양상으로, 지난해 국내 ETF 시장 거래 대금은 사상 처음 1329조 원을 기록했다. 올해는 이달 초 기준 760조 원을 넘어서며 지난해 전체의 절반을 이미 웃도는 모습이다.▶기사 바로가기:호르무즈 쇼크…여천NCC “제품 공급 차질”▶기사 바로가기:경영권 프리미엄 없애고 소액주주도 보호▶기사 바로가기:개미가 주도한 머니무브…증권사 10년만의 호황', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004596666', 'https://imgnews.pstatic.net/image/011/2026/03/07/0004596666_001_20260307063116859.jpeg?type=w800', 'NEWS_ETC', NULL, '2026-03-07 06:31:16', 0, true, '2026-03-09 05:50:16.154557') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (710, '전분당도 7년 6개월간 6.2조원 담합…또 1조원대 과징금 예고', '◆공정위, 제조·판매사 4곳에 심사보고서 발송4개社 국내 B2B시장 90% 점유조직적 공조로 가격 ‘좌지우지’담합 인정되면 최대 1.2조 철퇴사료용 부산물 담합도 추가 조사2월 27일 서울의 한 대형마트에서 직원이 밀가루를 정리하고 있다. 연합뉴스국내 주요 식품 업체들이 7년 넘게 가공식품·제조업에 두루 쓰이는 전분당 판매 가격을 담합한 것으로 적발됐다. 경쟁 당국이 산출한 담합 규모는 앞서 적발된 밀가루 담합 사건보다 큰 6조 2000억 원에 달한다. 업계에서는 담합 기업들이 받게 될 과징금 규모가 최대 1조 2000억 원 수준에 이를 것이라는 관측이 나온다.공정거래위원회는 6일대상(001680)·사조CPK·삼양사(145990)·CJ제일제당(097950)등 4개 전분당 제조 및 판매 업체들에 전분당 담합 사건에 관한 심사보고서를 송부하고 위원회에 제출했다고 밝혔다. 공정위 심사보고서는 검찰의 공소장에 해당하는 문서로 최종 제재 여부와 수위는 향후 위원회 심의를 거쳐 결정된다.전분당은 옥수수를 분쇄해 생산된 전분과 전분에 물을 넣어 분해한 물엿·포도당·액상과당 등 당류를 가리키는 원재료다. 식품 산업에서는 라면·제과·음료·빵·아이스크림 등에 두루 쓰이고 제조업에서는 접착·코팅·결합 등 용도로 활용된다.공정위에 따르면 이들 4개 업체는 2018년 5월부터 지난해 10월까지 7년 6개월에 걸쳐 반복적·조직적으로 전분당 판매 가격을 모의해 결정했다. 전분당의 99%는 기업간거래(B2B)로 판매되는데 4개 업체의 국내 B2B 판매 시장점유율은 90%에 이른다. 사실상 4개 업체들이 국내 전분당 가격을 좌지우지한 셈이다.유성욱 공정위 조사관리관은 전분당 가격 담합이 라면·과자 등 가공식품 가격을 끌어올렸을 가능성에 대해 “전분당을 기본 원료로 쓰는 과자 등의 경우 간접적으로 영향을 받았을 것으로 본다”고 말했다.담합 사실이 최종 인정될 경우 4개 업체에 부과될 과징금은 단일 사건 기준 역대 최고 규모가 될 가능성도 있다. 전분당 담합을 통해 4개 업체가 벌어들인 것으로 추산된 매출액이 6조 2000억 원에 달하기 때문이다. 이는 공정위가 지난달 말 산정한 밀가루 담합 관련 매출액(5조 8000억 원)보다도 큰 규모다. 과징금은 관련 매출액의 최대 20%까지 부과될 수 있는 만큼 4개 업체의 과징금 규모는 최대 1조 2400억 원에 이를 것으로 예상된다. 앞서 공정위는 지난달 13일 설탕 가격을 담합한 CJ제일제당·삼양사·대한제당 등 제당 3사에 담합 관련 매출액의 15% 수준인 4083억 원을 과징금으로 부과한 바 있다.유 관리관은 “설탕 담합 사건 조사 과정에서 전분당 관련 합의 혐의를 포착해 지난해 10월부터 이달 초까지 끈질기고 집요한 추적 조사를 진행했다”며 “이번 담합 행위는 매우 중대한 위법 행위라고 판단해 가격 재결정 명령을 포함한 시정 조치, 과징금 부과 및 임직원 고발 의견을 제시했다”고 설명했다.이날 심사보고서를 송부받은 4개 업체들은 8주 이내 서면 의견 제출과 증거 자료 열람·복사 신청 등 방어권을 행사할 수 있다. 다만 정부는 심의 과정에서 최근 전분당 제조 업체들의 가격 인하 결정을 반영하겠다는 방침이다. 공정위가 담합 조사에 나서자 대상은 지난달 올리고당·물엿 등 소비자용 제품 가격을 5%, B2B용 제품 가격을 3~5% 낮춘 바 있다. CJ제일제당·사조CPK도 소비자용 및 B2B 제품 가격을 일제히 3~5% 낮췄다.유 관리관은 “피심의 업체들의 가격 인하에 대해 인하 폭이 적정한지 등도 감안해 결정할 것”이라며 “방어권 보장 절차가 종료되는 대로 최대한 신속하게 위원회를 개최해 최종 판단을 내릴 계획”이라고 말했다.한편 공정위는 4개 업체들이 일부 실수요처에 대해 입찰 담합을 벌인 혐의, 사료용으로 쓰이는 전분당 부산물 가격을 담합한 행위에 대해서도 추가로 조사를 진행하고 있는 것으로 나타났다. 공정위는 이 사안도 조속히 조사를 마무리한다는 계획이다. 공정위 관계자는 “민생에 부담을 유발하는 불공정 행위에 대해서는 철저한 감시와 엄중한 제재, 신속한 가격 정상화가 이뤄져 국민들이 체감할 수 있도록 모든 수단을 강구하겠다”고 강조했다.', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004596457', 'https://imgnews.pstatic.net/image/011/2026/03/06/0004596457_001_20260306233817173.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-06 12:01:08', 0, true, '2026-03-09 05:50:16.154557') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (711, '식용유·라면 업체 소집한 정부…라면값 인하 "글쎄"', '농식품부, 가공식품 품목별 점검 차원식용유 6사·라면 4사 이틀 연속 회의정부 "민생 물가 안정 기조 동참" 당부업계 "변수 커, 가격 입장 변화 없어"[이데일리 김미경 기자] 먹거리 물가 관리에 고삐를 죄고 있는 이재명 정부가 이틀 연속 주요 식품업체를 소집하면서 밀가루와 빵에 이은 식료품 가격 인하로 이어질지 관심이 쏠린다.5일 식품업계에 따르면 농림축산식품부는 이날 오후 2시 서울역 인근의 한 오피스에서 농심·오뚜기·삼양·팔도 등 라면업계 주요 4개사 실무진과 만나 최근 시장 동향과 업계 애로사항을 청취했다. 지난 4일에는 CJ제일제당·사조대림·오뚜기·대상·동원F&B·롯데웰푸드 등 식용유 업체 6개사를 불렀다.서울시내 한 대형마트에 컵라면이 진열돼 있다. (사진=뉴시스).소집 명분은 이란 공습으로 인한 대내외 환경 변화와 애로사항 청취 및 원가 동향을 살피기 위한 자리라는 게 농식품부의 설명이다. 또한 이날 자리에는 실국장급이 아닌 가공식품 물가를 관리하는 농식품부 푸드테크정책과장이 참석한 것으로 알려졌다.이번 소집에 참석한 업계 한 관계자는 “정부의 물가 안정 기조에 대한 설명을 들은 뒤 ‘물가 안정에 동참해달라’는 뜻을 전달 받았다”고 말했다. 또 다른 관계자는 “원재료 가격과 환율, 물류비 등 비용 요인을 점검한 뒤 가격 인하 및 변동 요인 등을 종합적으로 검토해달라는 요청을 받았다”며 “중동 이슈가 생각보다 길어질 것 같다는 의견과 함께 관련 애로사항과 정부 지원책도 이야기했다. 다만 직접적인 가격 인하 언급은 없었다”고 전했다. 다른 관계자 역시 “장바구니 물가 안정이 정부의 민생 물가의 방향이라는 기조를 설명한 뒤 지난 2월 출범한 ‘민생물가 특별관리 관계장관 태스크포스’(TF)를 언급하며 공정한 거래를 강조했다”고 덧붙였다.업계는 정부의 이번 소집을 사실상 ‘가격 인하 압박’ 신호로 해석하고 있다. 정부가 품목별로 간담회를 진행한 건 이번이 처음이다. 이번 점검은 최근 출범한 ‘민생물가 특별관리 관계장관 태스크포스(TF)’의 연장선이다. 이재명 대통령이 범정부 차원의 물가 집중관리 체계 구성을 지시한 후속 조처다. 농식품부는 그동안 업계 전체를 대상으로 간담회를 진행해 왔다면 품목별 회의를 열어 가격 결정 구조를 세밀하게 살펴보겠다는 계획이다.업계는 원가부담이 여전히 큰 상황인 만큼, 가격인하에 전반적으로 신중한 태도를 보이고 있다. 라면업계 한 관계자는 “원자재 품목별 가격 변동성이 크고, 국제유가, 환율 등 고려할 변수가 많다”며 “가격 인하가 어렵다는 입장에는 변함이 없다”고 말했다. 식품업계 관계자는 “정부에서 공식적으로 제품가격 인하를 요구하지는 않았지만 실무진을 만나 원재료를 언급했다는 점에서 압박 효과가 있다”며 “선두 업체의 가격 조정 여부가 관건”이라고 말했다.일각에선 최근 정부 압박 후 형성됐던 가격 인하 분위기가 중동발 리스크로 꺾일 수 있다는 얘기도 나온다. 식품업계 한 관계자는 “중동 사태 이후 국제유가 급등으로 운임, 환율 등 원가 변동성이 커진 만큼 한동안 인하를 고려하기보다 동결 등을 고민할 가능성이 크다”고 전했다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006229256', 'https://imgnews.pstatic.net/image/018/2026/03/05/0006229256_001_20260305172816324.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-05 17:27:07', 0, true, '2026-03-09 05:50:16.154557') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (712, '한국거래소, 2026년도 밸류업 컨설팅 대상·범위 확대…공시 참여 활성화', '사진=연합뉴스[파이낸셜뉴스] 한국거래소는 올해부터 밸류업 컨설팅 대상 및 범위를 대폭 확대한다고 5일 밝혔다. 기존 5000억원 미만 기업에서 자산총액 2조원 미만까지로 대상 기업이 확대됐다.특히 기업가치 제고 계획 공시 안착을 위해, 고배당 기업과 기술특례 신규상장 기업을 우선 지원한다는 방침이다.공시 연계 강화를 위해 기업이 직접 작성한 ‘기업가치 제고 계획’ 초안을 검토해주는 ‘2차 컨설팅’도 도입한다.상장기업이 실제 공시에 활용할 수 있도록 공시 초안에 대한 구조·표현·수준 등 적정성을 검토하고, 실행 과제의 일관성과 실현 가능성에 대한 객관적 피드백을 제공할 계획이다.컨설팅은 복수의 외부 전문기관이 진행하며, 상장사의 신청을 거쳐 컨설팅 대상기업을 선정한 후 사전진단, 현장방문, 결과보고 순으로 진행할 예정이다.한국거래소는 이달 중 컨설팅 기관을 선정하고, 상장법인 대상 안내 및 신청을 거쳐 다음 달부터 컨설팅을 진행한다.', NULL, '파이낸셜뉴스', 'https://n.news.naver.com/mnews/article/014/0005486877', 'https://imgnews.pstatic.net/image/014/2026/03/05/0005486877_001_20260305163415511.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-05 16:34:15', 0, true, '2026-03-09 05:50:16.154557') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (718, '뉴욕증시, 이란 전쟁 확전 불안감‥다우 급락 마감', '[뉴스투데이]◀ 앵커 ▶이번엔 신영증권 연결합니다.안예은 캐스터, 중동 상황 때문에 밤사이 국제 유가가 크게 올랐는데, 뉴욕 증시도 영향을 좀 받았습니까?◀ 안예은/신영증권 ▶신영증권입니다.뉴욕증시 주요 3대 지수가 일제히 하락했습니다.다우지수는 1.6% 급락했고 S&P500 지수와 나스닥 지수도 각각 0.5%와 0.2% 내렸는데요.중동에서의 무력 충돌이 격화되면서 국제유가가 급등세를 나타내자 뉴욕증시는 힘없이 내려앉았습니다.세계 원유 수송량의 약 20%를 담당하는 호르무즈 해협이 사실상 봉쇄되면서 ''서부 텍사스산 원유''는 8.5% 급등한 배럴당 81달러 선에서 거래되고 있습니다.유가가 급등하면서 항공주들은 일제히 하락했는데요.''아메리칸 에어라인''은 5.3%, ''델타항공''은 3.9% 급락했습니다.이밖에 ''마이크론 테크놀로지''가 0.9% 하락했고 ''테슬라''도 0.1% 내렸습니다.반면 ''브로드컴''은 작년 4분기 호실적을 기록했다는 소식이 나오면서 4.8% 올랐습니다.이번 주말이면 미국-이란 전쟁이 시작된 지 1주일이 경과하게 됩니다.전쟁이 단기에 수습될지 장기전으로 전개될지 가늠할 수 있는 결정적 국면이 아닐까 싶은데요.글로벌 증시는 중동에서 들려오는 전황에 따라 하루하루 등락이 엇갈리는 극심한 변동성 장세를 이어갈 것으로 전망됩니다.지금까지 신영증권이었습니다.MBC 뉴스는 24시간 여러분의 제보를 기다립니다.▷ 전화 02-784-4000▷ 이메일 mbcjebo@mbc.co.kr▷ 카카오톡 @mbc제보', NULL, 'MBC', 'https://n.news.naver.com/mnews/article/214/0001484351', 'https://imgnews.pstatic.net/image/214/2026/03/06/today_20260306_074203_2_31_Large_20260306074823547.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-06 07:43:18', 0, true, '2026-03-09 05:50:35.733881') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (719, '코스피 역대급 ''냉온탕''‥당분간 불확실성 계속', '[뉴스투데이]◀ 앵커 ▶연이틀 사상 최대로 폭락했던 코스피는, 단 하루 만에 10% 가까이 급등했습니다.너무 빨리 많이 올라서 5분간 매수를 금지하는, 사이드카까지 내려졌습니다.구민지 기자입니다.◀ 리포트 ▶코스피는 장이 열리자마자 4분 만에 7% 넘게 치솟았습니다.코스피와 코스닥 시장 모두 장 초반부터 거래가 5분간 중단되는 매수 사이드카가 발동됐습니다.종가는 5,583.장 끝날 때까지 기세가 꺾이지 않았고, 결국 10% 가까이 급등한 채 마감했습니다.상승폭으로는 역대 최대를 기록했고, 상승률로는 금융위기 때인 지난 2008년 10월 이후 역대 2번째 급등입니다.내린 종목은 단 22개에 불과했고 오른 종목은 9백여 개로, 40배 넘게 많았습니다.삼성전자는 11% 넘게 올라 19만 원을 되찾았고, SK하이닉스도 94만 원대로 올라섰습니다.미국과 이란이 물밑 협상에 들어갔단 소식에 유가 급등세가 안정을 찾으면서 공포에 질렸던 시장이 단 하루 만에 심폐소생한 겁니다.[박상현/iM증권 수석전문위원]"미국과 이란 간의 종전 협상 가능성이 대두가 됐고요. 거기에 따라서 에너지 가격 자체가 전체적으로 안정세를 보인 것이, 이란발 리스크 자체가 조금 진정이 되는 것이…"큰 고비는 넘겼지만, 상승세가 계속될지는 불투명합니다.여전히 중동 상황의 불확실성이 남아있는 만큼, 당분간 주가가 요동칠 수 있습니다.[김학균/신영증권 리서치센터장]"10% 떨어지고 올라가는 거에 대해서 심오한 의미를 부여하면 안 돼요. 일정한 방향을 가지고 움직이는 추세보다는 굉장히 급등락이 이어지는 변동성으로 봐야 될 것 같아요."반도체 호황이 계속되고 있는 만큼 중동 상황이 금방 끝난다면 예상보다 빠르게 회복할 수도 있습니다.하지만 미국에서 불거지고 있는 사모 대출 업계의 부실로, 투자금 이탈이 본격화된다면 또 다른 뇌관이 될 거란 우려도 나오고 있습니다.MBC뉴스 구민지입니다.MBC 뉴스는 24시간 여러분의 제보를 기다립니다.▷ 전화 02-784-4000▷ 이메일 mbcjebo@mbc.co.kr▷ 카카오톡 @mbc제보', NULL, 'MBC', 'https://n.news.naver.com/mnews/article/214/0001484311', 'https://imgnews.pstatic.net/image/214/2026/03/06/today_20260306_061000_1_5_Large_20260306061313064.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-06 06:10:38', 0, true, '2026-03-09 05:50:35.733881') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (720, '외인이 5조 던질 때, 개미는 5조 받았다…‘스마트 개미’들의 반격', '‘검은 화요일’에도 개인은 5조 순매수로 맞대응하락장에도 오히려 예탁금 증가“변동성 민감한 레버리지 자금은 주의해야”미국과 이스라엘의 이란 공습 여파로 국내 증시가 급락하는 과정에서 외국인이 대규모 매도에 나선 반면 개인 투자자는 오히려 저가 매수에 나선 것으로 나타났다. 공포감에 무턱대고 팔아치우는 것이 아닌 하락장을 기회로 보고 매수에 나서는 ‘스마트 개미’가 늘고 있다는 분석이 나온다.일러스트=챗GPT6일 한국거래소에 따르면 지난 3~4일 이틀 동안 유가증권시장에서 외국인은 4조6729억원을 순매도했다. 반면 개인 투자자는 같은 기간 6조1404억원을 순매수하며 물량을 받아냈다. 중동 사태 여파로 지수가 급락했지만 개인 투자자들은 지수 하락을 매수 기회로 보고 ‘지수 쇼핑’에 나선 셈이다.개인 투자자들이 집중적으로 사들인 종목은 낙폭이 컸던 대형주였다. 한국거래소에 따르면 이 기간 개인 순매수 1·2위 종목은 삼성전자와 SK하이닉스였다.다만 날짜별 수급 흐름을 보면 개인 투자자의 불안 심리도 일부 나타났다. 3일 중동 사태 발발로 코스피 지수가 450포인트 넘게 급락하자 외국인은 5조원 넘게 매도한 반면 개인은 5조8000억원을 순매수했다. 하지만 다음 날에도 12% 가까운 폭락이 이어지자 장 초반 개인은 1조원 규모 순매도에 나섰다. 이후 장 마감에 가까워지며 지수가 5000포인트대에 근접하자 다시 790억원 순매수로 돌아섰다.증시 하락장을 대하는 개인 투자자들의 투자 방식이 과거와 달라지고 있다는 평가가 나온다. 과거에는 시장 급락 시 개인 투자자들이 공포감에 매도하는 경우가 많았지만 최근에는 낙폭 과대 구간에서 매수에 나서는 경향이 나타난다는 것이다.이상연 신영증권 연구원은 “지정학적 리스크가 있었지만 기업의 펀더멘털(기초 체력)에 미치는 영향은 크게 없을 거란 분석이 이어졌고 과거 하락장 시기에도 늦어도 일주일 뒤엔 낙폭을 회복했던 경향이 있었다”며 “이를 고려한 개인 투자자들이 전략적으로 매수에 나선 것으로 보인다”고 했다.실제로 하락장에서도 투자자 예탁금은 줄지 않고 오히려 증가했다. 금융투자협회에 따르면 투자자 예탁금은 지난 3일 역대 최고인 129조8188억원을 기록했다. 투자자 예탁금은 주식 투자를 위해 넣어둔 현금으로 ‘증시 대기 자금’을 의미한다.이경민 대신증권 연구원은 “하락장에서도 투자자 예탁금이 늘었다는 것은 투자자들의 저가 매수 심리가 계속 남아 있던 것으로 추정된다”며 “이번 지수 하락을 기회로 보고 저점에서 매수하려는 니즈에 맞추어 대기성 자금이 더 들어온 것으로 보인다”고 했다.증권사에서 돈을 빌려 주식 투자를 하는 신용 거래 융자 규모도 크게 증가했다. 5일 금융투자협회에 따르면 지난 3일 기준 신용 거래 융자 잔고는 32조8040억원으로 사상 최대 수준을 기록했다.다만 일각에서는 신용 거래 융자 잔고 규모가 크게 증가한 만큼, 급락장에 개인 투자자가 급하게 들어갈 경우 손실이 확대될 수 있다는 우려가 나온다.증권사는 주가가 하락해 신용거래융자의 담보비율이 140% 이하로 떨어지면 추가 증거금 납입을 요구하고, 투자자가 다음 날까지 채우지 못하면 그다음 날(D+2) 장 시작과 동시에 보유 주식을 하한가로 강제 청산할 수 있다. 3~4일 동안 코스피가 20% 급락한 만큼, 담보 부족에 따른 투자자의 위험도가 증가할 것이란 분석이다.외국인이 팔고 개인이 받아내는 수급 구조가 장기화될 경우 시장에는 부담이 될 수 있다는 분석도 나온다. 개인 투자자의 경우 단기 투기성 자금의 비율이 상대적으로 더 높기 때문이다. 코스콤 ETF체크에 따르면, 지난달 26일부터 이달 4일까지 개인 순매수 상위 상장지수펀드(ETF) 1, 2위는 ‘KODEX 레버리지’(1조762억원), ‘KODEX 코스닥150레버리지’(7458억원)였다.이상연 연구원은 “개인 투자자의 자금은 변동성에 민감해 수급 안정성이 떨어질 수 있다”며 “증시 자금 유입은 긍정적인 일이지만 증시 입장에서는 안전판이 될 수 있는 중장기성 자금들이 많이 있어야 한다”고 했다.', NULL, '조선비즈', 'https://n.news.naver.com/mnews/article/366/0001146218', 'https://imgnews.pstatic.net/image/366/2026/03/06/0001146218_001_20260306061611285.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-06 06:02:00', 0, true, '2026-03-09 05:50:35.733881') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (721, '유가 충격에 K자형 증시 더 심해진다', '9일 코스피 ''매도 사이드카''…환율 금융위기후 최고4분기 소비·건축株 영업익, 추정치보다 훨씬↓반도체·해운·통신 등은 ''어닝 서프라이즈''반도체·운송·조선·방산 가격전가력 높아 ''주목''중동발 지정학적 리스크로 국제 유가가 치솟으면서 국내 증시가 또다시 크게 흔들리고 있다. 이미 두드러지게 나타나고 있는 업종별 K자형 양극화는 증시에서 더욱 심화될 것이란 전망이 나온다.코스피가 장중 6% 이상 하락하며 매도사이드카가 발동한 9일 서울 하나은행 본점 딜링룸에서 직원들이 증시와 환율 등을 모니터 하고 있다. 이날 코스피는 9일 전 거래일 대비 319.50p(5.72%) 하락한 5265.37에 코스닥은 58.19p(5.04%) 내린 1096.48에 장을 시작했다. 조용준 기자9일 코스피는 전 거래일 대비 5.72% 내린 5265.37로 개장한 뒤 장 중 7.40% 떨어진 5171.53까지 하락했다. 코스닥 역시 5.04% 내린 1096.48로 출발했다. 주가가 크게 하락하면서 오전 9시6분께 코스피 매도 사이드카(프로그램매도호가 일시효력정지)가 발동됐다. 매도 사이드카는 코스피200선물 지수가 5% 이상 하락해 1분간 지속되는 경우 발동된다.시가총액 상위주가 대거 하락했다. 삼성전자는 오전 9시30분 기준 전거래일 대비 8.98% 내린 17만1300원에 거래 중이다. SK하이닉스(-9.20%), 현대차(-9.67%),LG에너지솔루션(-5.30%), 한화에어로스페이스(-3.58%),  삼성바이오로직스(-6.02%),SK스퀘어(-10.94%), 두산에너빌리티(-2.96%), 기아(-8.86%)  등 다른 대형주들도 하락세다.이날 서울외환시장에서 미국 달러화 대비 원화 환율은 16.6원 오른 1493.0원으로 출발해 오전 장중 1490원대에서 등락하고 있다. 이날 환율은 금융위기였던 2009년 3월 12일(고가 1500.0원) 이후 가장 높다.지난주 국내 증시는 중동 전쟁 여파로 ''롤러코스터 장세''를 보였다. 미국과 이스라엘의 이란 공습 직후 거래일인 지난 3일 코스피는 7% 급락했고, 4일엔 12% 폭락해 역대 최대 하락률을 기록했다. 반면 5일엔 저가 매수세에 9.6% 급등했고, 2008년 금융위기 이후 최대 상승률을 기록했다. 지난 6일엔 중동 전쟁 확대 불안감 속 등락하다 0.02% 오른 5584.87에 거래를 마쳤다. 이경민 대신증권 연구원은 "추가적인 변동성 확대, 등락은 감안해야겠지만 코스피는 5000선 전후에서 지지력 확보 예상한다"며 "당분간 미국, 이란 등의 주요 인사들의 발언에 의한 일희일비 국면은 불가피하다"고 말했다.한편 지난해 4분기 실적발표 시즌이 막바지에 접어든 가운데 지금까지 실적을 공개한 상장사 중 절반은 시장 기대치를 밑돈 성적을 낸 것으로 나타났다. 여기에 최근 유가 충격이라는 대외 변수까지 더해지면서, 업종별 희비가 극명하게 갈리는 ''K자형 증시'' 양상이 더욱 심화될 것이라는 우려가 나온다.금융정보업체 에프앤가이드에 따르면 지난 5일까지 증권사 3곳 이상이 영업이익 추정치를 제시한 245개사 중 124개사가 컨센서스(시장 평균 전망치)를 밑도는 영업이익을 기록했다.업종별로 살펴보면 드림텍 등 휴대폰 및 관련 부품(-75.8%), 한샘등 내구소비재(-63.7%), 현대지에프홀딩스 등 복합 산업(-63.3%), KCC 등 건축자재(-59.4%), 솔루엠 등 전자 장비 및 기기(-59.3%), LG디스플레이 등 디스플레이 및 관련 부품(-46.7%) 등이 시장 전망치를 하회했다.반면 인텔리안테크 등 통신장비(60.1%),더존비즈온 등 일반 소프트웨어(22.6%), KB금융 등 상업은행(21.0%),  CJ ENM 등 미디어(14.2%),HMM 등 해상운수(14.0%), ISC 등 반도체 및 관련 장비(12.0%) 등은 컨센서스를 상회했다.지난해 4분기 영업이익이 예상치를 가장 크게 밑돈 기업은 크래프톤으로, 영업이익이 컨센서스(1232억)보다 98.1% 낮은 24억원을 기록했다. 성수 신사옥 이전을 대비해 향후 4년간 사용할 재원으로 공동근로복지기금 816억원을 출연하는 등 일회성 비용이 일시에 반영된 탓이다.금호석유화학은 컨센서스(483억원)를 96.9% 하회하는 15억원의 영업이익을 냈다. 연말 시장 수요 둔화 및 원재료 가격 하락으로 합성고무 부문 수익 등이 감소한 영향이다. POSCO홀딩스의 영업이익은 156억원으로 컨센서스(4100억원)를 96.2% 밑돌았다. 철강 사업 수익성은 회복했으나 이차전지 소재 및 건설 부문 부진 등이 영향을 줬다. 이어 한화시스템(-84.7%), 씨앤씨인터내셔널(-82.3%), 코오롱인더(-78.7%), SK네트웍스(-76.9%),드림텍(-75.8%) 등 순이었다.시가총액 상위 종목에선 반도체 대형 기업의 호실적이 두드러졌다.삼성전자가 20조737억원의 영업이익을 기록하며 컨센서스를 8% 웃도는 실적을 냈다. SK하이닉스 영업이익은 19조1696억원으로 컨센서스를 16% 상회했다. 양사는 인공지능(AI) 확산으로 범용 D램·고대역폭 메모리(HBM) 등의 수요 증가와 반도체 가격 상승이 맞물리면서 ''슈퍼사이클(호황기)''에 진입했다는 평가가 나온다.중동발 유가상승 여파로 기업에는 비용부담, 가계에는 물가상승 우려가 커지고 있다. 이에 증시 전문가들은 판매가격에 비용을 많이 전가할 수 있는 업종과 기업에 대한 비중을 확대하는 투자 전략을 짜야한다고 조언한다.이재만 하나증권 스트래지스트는 "2015년 이후 WTI 가격이 전월 대비 상승 시 12개월 예상 영업이익률이 전월대비 상승 폭이 크고, 또한 12개월 예상 매출액이 전월 대비 증가시 12개월 예상 영업이익률 상승 폭이 큰 업종 으로 반도체, 운송, 조선, 방산, 기계 등이 있다"고 분석했다.결국 향후 실적 전망치의 변화에 지속적인 관심을 가져야한다는 뜻이다. 신한투자증권에 따르면 올해 영업이익 증가율 전망에서는 IT, 에너지, 소재, 산업재, 헬스케어 순으로성장률이 높게 나타나고 있다. IT 업종의 증가율이 가장 높은 형국은 계속되고있다. 전년부터 메모리 공급 부족이 구조적으로 심화되는 국면에 진입한 가운데, 메모리 수급이 타이트한 상황이 장기화되고 있기 때문이다. 여기에 AI 관련 수요는 지속 확대되며 고부가 메모리 중심의 업황 개선 흐름이 강화되고 있다.이정빈 신한투자증권 연구원은 "영업이익 서프라이즈를 기록한 종목군의 사전 수익률 역시 양호한 흐름을 보였고 실적 발표 이전부터 시장이 일부 긍정적신호를 선반영했다"며 "이러한 호실적이 주가 강세로 이어지는 연결 고리는 최근 분기에도 유지되고 있으며 향후에도 실적 개선 종목 중심의 선택적 매수세가 유지될 가능성이 높다"고 말했다.', NULL, '아시아경제', 'https://n.news.naver.com/mnews/article/277/0005731238', 'https://imgnews.pstatic.net/image/277/2026/03/09/0005731238_001_20260309112427506.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-03-09 09:55:49', 0, true, '2026-03-09 05:50:55.943577') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (722, '인크로스, 현대차 ‘블루핸즈’ 디지털 사이니지 광고 운영권 확보', '814개 전국 매장 ‘B tv 온애드’ 광고 운영 담당SK네트웍스 통합 마케팅 전문 자회사 인크로스가 현대자동차 공식 정비 네트워크인 블루핸즈 전국 매장의 디지털 사이니지 광고 매체 운영권을 확보했다고 9일 밝혔다.인크로스는 지난 4일 SK브로드밴드, 현대정비가맹점협동조합연합회와 함께 ‘B tv 온애드’ 광고 매체 사업 협력을 위한 3자 업무협약을 체결했다.협약을 통해 인크로스는 전국 814개 블루핸즈 매장에 설치된 디지털 사이니지 ‘B tv 온애드’의 광고 운영을 단독으로 담당했다.인크로스가 지난 4일 SK브로드밴드, 현대정비가맹점협동조합연합회와 함께 ‘B tv 온애드’ 광고 매체 사업 협력을 위한 3자 업무협약을 체결했다. (왼쪽부터) 이상화 인크로스 커머스미디어사업본부장, 김정현 현대정비가맹점협동조합연합회 연합회장, 홍도희 SK브로드밴드 기업고객담당 (사진=인크로스)‘B tv 온애드’는 매장 내 디스플레이를 통해 홍보 영상, 이미지, 텍스트 등 콘텐츠를 송출할 수 있는 SK브로드밴드의 디지털 광고 솔루션이다. 인크로스는 B tv온애드와 자사 동영상 광고 플랫폼 ‘다윈’을 연동해 자동차 정비를 위해 매장을 방문한 고객들에게 최적화된 타겟 광고를 제공할 계획이다.차량 정비를 기다리는 고객들의 특성을 분석해 광고 효과를 극대화하는 것이 인크로스의 전략이다. 회사 측은 대기 시간이 긴 블루핸즈 매장의 특성상 고객들의 주목도가 높아 광고 노출 효과가 우수할 것으로 기대된다고 설명했다.차량 관리 정보와 정비 팁 등 유용한 콘텐츠를 제공하는 동시에 지역 맞춤형 광고와 상품 서비스 광고를 전략적으로 배치해 광고주와 고객 모두의 만족도를 높일 방침이다.협약은 인크로스의 디지털 광고 역량과 현대차 블루핸즈의 전국적 네트워크, SK브로드밴드의 기술 인프라가 결합한 상생 모델로 평가받고 있다. 인크로스는 이를 기반으로 오프라인 공간의 디지털 전환을 선도하고, 새로운 광고 수익 모델을 창출해 나갈 계획이다.인크로스는 향후 광고주 유치를 본격화하고, 데이터 분석을 통해 광고 효과를 지속적으로 개선해 나갈 예정이다. 또한 디지털 사이니지 광고 운영 노하우를 바탕으로 향후 오프라인 광고 사업 확대도 검토할 계획이다.이상화 인크로스 커머스미디어사업본부장은 “현대차 블루핸즈 전국 매장을 광고 매체로 확보하게 돼 매우 기쁘게 생각한다”며, “자동차 정비 고객의 특성에 맞는 타깃 광고를 제공해 모두에게 가치를 제공하는 모델을 만들어가겠다”고 말했다.', NULL, '지디넷코리아', 'https://n.news.naver.com/mnews/article/092/0002413379', 'https://imgnews.pstatic.net/image/092/2026/03/09/0002413379_001_20260309092910614.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-03-09 09:29:10', 0, true, '2026-03-09 05:50:55.943577') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (723, 'IPO 앞둔 업스테이지, SBVA 출신 CFO 영입…''AI 대어'' 부상할까', '진윤정 CFO 합류로 IPO 준비 본격화…연내 상장 기대감 고조국내 인공지능(AI) 스타트업 업스테이지가 벤처캐피털(VC) 출신 최고재무책임자(CFO)를 영입하며 기업공개(IPO) 준비에 속도를 높이고 있다. 글로벌 투자은행과 벤처투자 업계를 두루 경험한 인사를 전면에 배치하면서 상장 작업을 본격화하는 모습이다.6일 업계에 따르면 업스테이지는 최근 SBVA(옛 소프트뱅크벤처스아시아) 출신 진윤정을 최고재무책임자(CFO)로 영입했다. 진 CFO는 이달 말 회사에 합류해 재무·회계 전반을 총괄하고 향후 IPO 추진 과정에서도 핵심 역할을 맡을 전망이다.진 CFO는 미국 조지타운대를 졸업한 뒤 크레디트스위스(Credit Suisse)와 뱅크오브아메리카 메릴린치(BofA Merrill Lynch)에서 IPO와 인수합병(M&A) 업무를 담당한 투자은행 출신 인사다. 이후 스탠퍼드대 경영대학원(MBA)을 거쳐 벤처투자 업계에 합류했으며 2014년부터 SBVA에서 국내외 스타트업 투자 업무를 맡아왔다.진윤정 업스테이지 CFO (사진=김성훈 업스테이지 대표 페이스북)진 CFO는 업스테이지와도 인연이 깊다. SBVA에서 업스테이지 투자를 주도하며 2021년 시리즈A와 2024년 시리즈B 투자에 참여했고 이후 사외이사로도 활동하며 회사의 성장 전략을 가까이서 지켜봐 왔다. 투자자로 함께했던 인사가 경영진으로 합류하면서 상장 준비 과정에서 회사 이해도와 자본시장 경험을 동시에 활용할 수 있을 것으로 업계는 보고 있다.김성훈 업스테이지 대표는 자신의 사회관계망서비스(SNS)를 통해 "진 CFO는 회사가 힘들 때와 빠르게 성장할 때 등 모든 과정을 가장 가까이에서 지켜본 만큼 업스테이지의 잠재력과 가치를 누구보다 잘 이해하고 있다"며 "글로벌 시장에서 수많은 메가 딜을 이끌어 온 경험이 업스테이지의 성장 과정에서 큰 역할을 할 것"이라고 말했다. 그러면서 "앞으로 업스테이지가 글로벌 AI 생태계를 선도하고 ''메이킹 AI 베네피셜(Making AI beneficial, AI를 유익하게 만들기)''이라는 비전을 실현하는 데 중요한 힘이 될 것으로 기대한다"고 덧붙였다.이번 일로 업스테이지의 연내 상장 목표도 더욱 힘을 얻게 됐다. 현재 KB증권과 미래에셋증권을 상장 주관사로 선정하고 IPO 준비 작업을 진행 중으로, 업계에선 이르면 5월 상장 예비심사를 청구하고 올해 하반기 증시 입성을 추진할 것으로 예상했다.업스테이지의 상장 준비와 맞물려 투자도 이어지고 있다. 업스테이지는 설립 이후 시리즈A와 시리즈B 등을 통해 약 2000억원 이상의 투자를 확보했다. 최근에는 SK네트웍스가 기존 투자 당시 확보했던 콜옵션을 행사해 약 470억원을 추가 투자했다. 이에 따라 SK네트웍스의 업스테이지 누적 투자액은 약 720억원으로 늘었고 지분율도 약 13% 수준까지 확대됐다.글로벌 기업들의 참여도 눈에 띈다. 지난해 진행된 시리즈B 브릿지 투자에는 아마존과 AMD가 전략적 투자자로 합류하며 업스테이지의 기술력과 성장 가능성에 대한 기대감을 높였다.업스테이지는 프리 IPO 과정에서 1조3000억원 정도의 기업가치를 인정받았다. 이를 고려하면 최소 2조원 이상의 기업가치를 목표로 IPO를 추진할 것으로 보인다.업계 관계자는 "AI 산업에 대한 시장 관심이 높아진 상황에서 업스테이지가 상장에 성공할 경우 국내 AI 기업 가운데 대표적인 ''대어''로 평가받을 가능성이 있다"며 "최근 리벨리온, 퓨리오사AI 등 주요 AI 기업들이 IPO를 검토하는 가운데 업스테이지가 상장에 성공하면 국내 AI 스타트업의 기업가치 기준을 새로 제시하는 사례가 될 수 있다"고 말했다.', NULL, '지디넷코리아', 'https://n.news.naver.com/mnews/article/092/0002413226', 'https://imgnews.pstatic.net/image/092/2026/03/06/0002413226_001_20260306150311761.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-03-06 15:03:11', 0, true, '2026-03-09 05:50:55.943577') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (724, '마음AI "로봇은 멈추면 끝…피지컬 AI는 온디바이스가 답"', '판교 시스템반도체 포럼서 온디바이스 강조"VLA는 지연이 곧 리스크…로봇은 멈추면 끝"GPU 기반 개발 후 양산 단계서 NPU 등 대안 거론경기도 35억 투입…팹리스-수요기업 연결 지원"웹(Web) 서비스는 좀 느려도 됩니다. 그런데 로봇은 멈추면 끝입니다."피지컬AI 기업 마음AI의 최홍섭 최고경영자(CEO)는 5일 오전 경기 성남시 판교 ''그래비티 조선 서울판교''에서 열린 ''경기도 시스템반도체 산업 연계·협력 포럼'' 에서 "피지컬(물리적) AI는 구조적으로 온디바이스(기기내장형)일 수밖에 없다"며 이같이 말했다.최홍섭 ''마음AI'' 기술총괄 최고경영자(CEO) [사진=권서아 기자]마음AI가 SK ''나무엑스''에 공급한 온디바이스 음성 AI 솔루션 소개 화면. [사진=권서아 기자]마음AI는 음성 인식과 대화형 인공지능을 주력으로 하는 기업이다. 로봇과 산업용 디바이스에 AI를 적용해 왔으며, SK네트웍스 산하 웰니스 로보틱스 브랜드 ''나무엑스(NAMUH X)''에 자사 기술을 공급한 바 있다. 나무엑스는 세계적 팹리스(반도체 설계) 기업 퀄컴의 드래곤윙 QCS6490 기반으로 설계됐으며, 기기 내에서 거대언어모델(LLM)을 구동할 수 있는 구조다.이날 포럼은 경기도와 차세대융합기술연구원이 공동 주최하고 한국팹리스산업협회가 후원했다. 시스템반도체 기업과 수요기업, 연구기관 관계자들이 참석해 설계 생태계와 지원 정책을 논의했다."피지컬 AI는 VLA…지연이 곧 리스크"최 대표는 로봇과 자율주행에 적용되는 AI는 챗지피티(GPT) 같은 LLM과 다르다고 강조했다.핵심은 VLA(비전·언어·행동) 모델이다. 시각 입력과 언어 이해를 거쳐 실제 물리적 행동으로 이어지는 구조다.그는 "로봇은 여러 대 카메라에서 영상이 동시에 들어온다"며 "이를 클라우드(가상 서버)로 보내 처리하면 전송 부담과 레이턴시(지연시간)가 발생한다"고 말했다.그는 "통신이 순간적으로 불안정해지면 로봇 동작이 끊길 수 있다"며 "텍스트 서비스와 달리 지연이 허용되지 않는 구조"라고 했다.발표 자료에 따르면 10억(1B) 파라미터(매개변수)급 VLA 모델을 온디바이스에서 구동하려면 최소 100TOPS(1초당 1조번 연산) 수준의 성능이 필요하다.KV 캐시(문맥 유지 메모리) 특성상 토큰(AI 모델의 입출력 단위) 생성 때마다 메모리 접근이 반복돼 고대역폭 구조도 요구된다."개발은 GPU, 상용 단계에선 전력·지연 따져야"최 대표는 피지컬 AI 칩 선택 기준도 언급했다.그는 "개발 단계에서는 엔비디아 그래픽처리장치(GPU)로 시작하는 경우가 많다"고 말했다. 실제 로봇·엣지(Edge) 분야에서는 엔비디아 젯슨 오린(Jetson Orin) 시리즈가 온디바이스 개발 플랫폼으로 사용되고 있다.다만 피지컬 AI 제품에 실제로 탑재하는 칩은 별도의 판단이 필요하다고 했다.최홍섭 마음AI 대표의 발표 자료. [사진=권서아 기자]그는 "피지컬 AI는 지연이 허용되지 않고 전력 제약이 크다"며 "LLM을 구동할 수 있으면서도 발열과 소비전력을 감당해야 하고, 양산 시 가격과 공급 안정성까지 고려해야 한다"고 말했다.GPU와 신경망처리장치(NPU)의 차이도 설명했다.마음AI 발표 자료. 연구 단계에선 GPU를 늘리는 방식이 통하지만, 상용 단계에선 경량화·속도·가격을 맞춘 ''최적화''가 핵심이라고 설명하고 있다. [사진=권서아 기자]GPU는 초거대 모델 ''학습''에 주로 쓰이는 범용 가속기다. NPU는 실제 서비스 단계의 ''추론''에 초점을 맞춘 전용 칩으로, 전력 효율성과 비용 면에서 강점을 지닌다.최 대표는 "대부분 고객사가 개발 단계에선 쓰기 편해서 GPU로 시작하지만, 개발이 끝나면 양산 단계에선 어떤 칩을 쓸지 따로 정한다"고 말했다.이 과정에서 리벨리온와 퓨리오사AI 등 국내 NPU 기업도 검토 대상이라고 덧붙였다.경기도, 35억 투입해 ''팹리스-수요 기업 연계'' 양산 지원이날 포럼에서는 경기도의 시스템반도체 지원 정책도 공유됐다.권정훈 차세대융합기술연구원 본부장은 "지난해 7월 추가경정예산(추경)으로 35억원 예산을 확보해 ''경기도 팹리스 수요연계 양산지원 사업''을 시작했다"며 "성능평가와 실증, 양산 단계 지원을 추진 중"이라고 밝혔다.그는 "지난해 9개 컨소시엄에 3억원씩 지원했고, 올해는 3억원 규모 컨소시엄 4개와 5000만원 실증지원 4개 기업을 공모 중"이라고 말했다.이제영 경기도의회 미래과학협력위원장은 "설계, 설계자산(IP), 팹리스, 수요기업이 연결된 생태계를 갖추는 것이 중요하다"고 말했다.현병천 경기도 미래성장산업국장도 "설계기업과 수요기업, 연구기관, 대학이 유기적으로 이어져야 경쟁력이 생긴다"고 강조했다.', NULL, '아이뉴스24', 'https://n.news.naver.com/mnews/article/031/0001010846', 'https://imgnews.pstatic.net/image/031/2026/03/06/0001010846_001_20260306080210008.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-03-06 08:02:10', 0, true, '2026-03-09 05:50:55.943577') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (770, '[애프터마켓 브리핑] 삼성전자·SK하이닉스, 반도체 관세 임시 면제에↑', '■ 머니쇼+ ''애프터마켓 브리핑'' - 김유민애프터마켓 브리핑입니다.오늘(23일) 시장은 장 초반 상승폭을 반납하고, 오후장으로 접어들수록 수급도 저조했습니다.그래도 장 후반에 고개를 든 코스피는 5,845선에서 마감했습니다.코스닥은 0.18% 내린 1,151선에서 장 마쳤는데요.현재 애프터마켓 분위기는 어떤지 시세 짚어보겠습니다.우선 시가총액 순위권 종목들입니다.미국 의회가 트럼프의 관세에 제동을 걸면서 국내 반도체주들은 상승세를 보입니다.삼성전자는 1.95% 오른 193,800원에 거래되고 있고요.SK하이닉스는 0.42% 오른 953,000원입니다.현대차는 급등 후 상승폭을 축소했지만, 그래도 빨간 불 켜고 있습니다.25% 관세율이 복귀될 우려가 있지만, 엔비디아 GTC, 보스턴다이나믹스 IPO 추진 등이 전반적으로 작용하며 우려가 상쇄됐습니다.현재 2.7% 넘게 오르며 523,000원에 거래되고 있습니다.다음으로 상승률 1위에서 5위 종목들 보겠습니다.삼화콘덴서는 현재 상승률 2위로 56,600원에 거래되고 있는데요.MLCC 가격 인상 기대감 속에 상승 중입니다.더존비즈온은 유럽 최대 사모펀드인 EQT파트너스가 지분 전량을 공개매수했고,  규모가 2조 원이 넘기 때문에 주가도 반응하고 있습니다.현재 상승률 3위로, 23.44% 오르며 118,500원에 거래되고 있습니다.이외에도 정규장 마감 후에는 증권주들 시세가 뜨겁습니다.부국증권과 신영증권은 마감 후 크게 올라가고 있고요.대신증권은 낙폭 회복에 나섰습니다.그리고 매커스도 자사주 소각 기대감 안고 현재 애프터마켓에서 더 올라가고 있습니다.이외에도 삼성자산운용에서 에스피지 지분 5% 매수 공시를 내면서 에스피지, NXT에서 크게 올라갑니다.이어서 하락률 순위권 종목들도 함께 보겠습니다.코스메카코리아가 하락률 1위로, 17.36% 내린 83,800원에 거래되고 있습니다.실적 발표에서 영업이익이 예상치를 하회했죠.다만 유안타증권에서는 영업이익 감소가 일회성 비용 때문이라고 보며, 수익성 개선 기대감을 가져갈 수 있다고 밝혔습니다.목표주가도 12만 원으로 상향한 점 참고하셔야겠습니다.유니테스트는 태양광 대장주인 한화솔루션 주가가 떨어지면서 함께 하락세 보입니다.현재 10% 넘게 밀리며 19,060원에 거래 중입니다.피에스케이홀딩스도 52주 신고가 달성 이후 오늘은 빠집니다.마지막으로 거래량 동반해서 움직이는 종목들도 체크해보겠습니다.보험주인 미래에셋생명은 장중 상한가를 찍었는데요.다만 증권사에서는 실적이나 업황 모멘텀으로 주가가 올라가지 않았다고 봤기 때문에 단기 과열 우려도 나옵니다.실제로 오늘 현대해상은 장 마감 직전 실적을 발표했는데, 좋지 않게 나오자 하락으로 전환했고요.남은 보험주들 실적도 지켜보셔야겠습니다.이렇게 애프터마켓 흐름부터 특징주까지 살펴봤습니다.오늘 밤 열리는 뉴욕증시는 안자은 캐스터와 함께 대비해보시죠.지금까지 애프터마켓 브리핑이었습니다.당신의 제보가 뉴스로 만들어집니다.SBS Biz는 여러분의 제보를 기다리고 있습니다.홈페이지 = https://url.kr/9pghjn', NULL, 'SBS Biz', 'https://n.news.naver.com/mnews/article/374/0000493814', 'https://imgnews.pstatic.net/image/374/2026/02/23/0000493814_001_20260223163624017.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-02-23 16:36:23', 0, true, '2026-03-09 05:52:50.425799') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (725, '인크로스, ‘구글 프리미어 파트너’ 10년 연속 선정', '"국가별 상위 3% 이내 성과 거둔 기업에만 부여"SK네트웍스 자회사 인크로스는 ‘2026년 구글 프리미어 파트너’로 선정됐다고 4일 밝혔다.구글 프리미어 파트너는 국가별 상위 3% 이내 성과를 거둔 기업에만 부여되는 자격이다. 구글은 매년 고객 성장, 신규 고객 유치, 고객 유지, 제품 다각화, 연간 광고비 지출 등을 종합적으로 평가해 파트너사를 선정한다.인크로스는 자사가 구글의 다양한 광고 솔루션을 활용해 광고주의 실질적인 성과를 창출해 온 전문성을 인정받아 이번 프리미어 파트너 명단에 이름을 올렸다고 설명했다.인크로스 로고 (사진=인크로스)이번 선정에 따라 인크로스는 구글로부터 광고 효과 극대화를 위한 신규 기능과 기술 지원, 전문 교육, 전용 프로모션 등 다각적 지원을 받는다.인크로스는 구글의 지원과 자사의 디지털 광고 운영 노하우를 결합해, 광고주의 비즈니스 성장을 견인하는 고도화된 마케팅 솔루션을 지속 제공한다는 방침이다.손윤정 인크로스 대표는 “10년 연속 프리미어 파트너 선정은 인크로스의 전문성과 운영 역량이 꾸준히 성장하고 있음을 증명하는 것”이라며 “앞으로도 광고주에게 차별화된 가치를 제공하는 전략적 파트너로서의 입지를 더욱 공고히 하겠다”고 밝혔다.', NULL, '지디넷코리아', 'https://n.news.naver.com/mnews/article/092/0002412710', 'https://imgnews.pstatic.net/image/092/2026/03/04/0002412710_001_20260304090912740.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-03-04 09:09:12', 0, true, '2026-03-09 05:50:55.943577') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (726, '인크로스, AI 배너 제작 자동화 ‘리사이즈애드’ 시범 실시', '31일까지…정식 런칭 후 가격 인상SK네트웍스 통합 마케팅 전문 자회사 인크로스는 생성형 AI 기술을 활용한 배너 제작 자동화 에이전트 ‘리사이즈애드(ResizeAD)’의 오픈 베타 테스트(OBT)를 3일부터 실시한다고 밝혔다.OBT는 31일까지 약 한 달간 진행된다. 인크로스는 OBT에 참여하는 기업 및 개인 고객에 200 크레딧 무료 제공(배너 200개 무료), 유상 크레딧 특별가 적용(건당 1500원), 90일간 재다운로드 무제한 서비스 등을 제공한다. 정식 런칭 후에는 가격이 인상될 예정이라고 회사 측은 설명했다.리사이즈애드는 AI 전문기업 넥서스AI가 개발하고 인크로스가 국내 사업권을 보유해 운영하는 서비스다. 마케터나 디자이너가 원본 파일 하나만 업로드하면 네이버 구글 등 주요 광고 플랫폼을 비롯해 다양한 매체의 규격에 맞춰 배너 규격을 자동으로 변환하고 생성해주는 것이 핵심 기능이다.사진=인크로스기존 이미지 크기 변환 툴과 달리 리사이즈애드는 ‘AI에이전트’ 개념을 도입했다. 리사이즈애드는 원본 디자인의 레이어 구조를 정밀 분석한 뒤, 규격 변경 시 발생하는 빈 공간을 생성형 AI 기술로 자연스럽게 확장하고 생성한다.텍스트 자동 줄바꿈, CTA 버튼 최적 배치 등 세부 가이드라인도 매체별로 자동 적용돼 즉시 사용 가능한 수준의 결과물을 제공한다. 이를 통해 디자이너가 일일이 수작업으로 수정해야 했던 반복 업무를 획기적으로 줄여주며, 디자인 퀄리티도 유지할 수 있다.회사 측은 리사이즈애드 도입 시 기존 디자인 에이전시 대비 약 80% 이상의 비용 절감이 가능하며, 제작 시간도 시간 단위에서 분 단위로 단축될 것으로 예상된다고 강조했다.손윤정 인크로스 대표는 “리사이즈애드는 단순한 업무 효율화 도구를 넘어 마케터의 생산성을 강화하는 AI에이전트 역할을 할 것”이라며 “앞으로도 인크로스는 우수한 AI 기술 기업과의 파트너십을 통해 광고주와 대행사의 업무 편의성을 강화하고, 고객들이 창의적인 전략 수립에 집중할 수 있는 마케팅 환경을 만들어 가겠다”고 밝혔다.', NULL, '지디넷코리아', 'https://n.news.naver.com/mnews/article/092/0002412566', 'https://imgnews.pstatic.net/image/092/2026/03/03/0002412566_001_20260303110010265.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-03-03 11:00:10', 0, true, '2026-03-09 05:50:55.943577') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (727, '"잘해 봅시다" SK네트웍스 사내 소통 강화', 'AI 중심 전환 사업 방향성 공유통상적 신년사 대신 대담 개최 등경영진 직원 간 소통 시간 마련이호정 SK네트웍스 대표이사(오른쪽)가 지난달 사내 신년 대담 자리에서 구성원에게 2026년 사업 방향성을 설명하고 있다. SK네트웍스 제공"올해 목표는 물류·유통 사업 경쟁력을 강화하고, 인공지능(AI)을 중심으로 한 새로운 성장동력을 구체화하는 것입니다." (이호정 SK네트웍스 대표이사 사장)"새해에도 더 많은 구성원들과 ''한끼수다'' 가능할까요?" (SK네트웍스 직원)"언제든지, 편하실 때 잡아주시면 ''잘 놀아드리겠습니다''." (이호정 사장)지난해 말 사내 방송과 유튜브 채널을 통해 공개된 이호정 SK네트웍스 대표이사 사장과 직원들 간 소통 행사 ''한끼수다'' 콘텐츠의 한 장면이다. 이날 직원들은 이 대표에게 2026년도 사업 방향을 비롯해 평소 주량, 취미, 경영자로서의 소회, 나아가 SK네트웍스 자회사 SK인텔릭스가 지난해 세계 최초로 선보인 로봇 공기청정기 ''나무엑스(NAMUHX)''에 대한 실제 사용 후기까지 직접 물어보는 등 거리낌 없는 장면 연출했다.2일 SK네트웍스는 소통 확대에 대한 ''이날의 약속''이 이어지면서 경영진의 사내 소통 행보가 한층 강화됐다고 전했다. 인공지능(AI) 중심 사업지주회사로의 빠른 전환을 목표로, 미래 비전과 사업 방향성에 대한 구성원들과의 공유가 필요하다는 판단이 작용한 것으로 풀이된다.이호정 대표이사 사장과 최성환 사업총괄 사장 등은 매월 세 번째 금요일을 ''SKMS Day''로 정해 경영층이 직접 회사 현황을 공유하는 시간을 마련했다. SK네트웍스는 주목도 높은 프로그램을 준비해 행사의 질과 규모를 한층 발전시킨다는 구상이다.이 대표는 연초에도 통상적인 신년사 대신 ''신년 대담'' 행사를 열어 직원들에게 ''성장과 실행력'', ''전략적 민첩성''이라는 올해 사업 키워드를 공유했다. SK네트웍스 관계자는 "신년사 공지에 그치지 않고 경영층과 구성원이 직접 마주하며 새해를 열어가겠다는 소통 경영의 장이었다"고 전했다.최성환 사업총괄 사장도 지난달 중순 SK스피드메이트를 시작으로 SK네트웍스 주요 부서와 자회사 사업 현장을 방문해 타운홀 미팅 형태의 구성원 간담회를 진행하고 있다. 사업 실행력 강화, 사업 간 시너지 확대, 밸류체인 재정비 등 전략적 민첩성을 높이기 위한 방안들이 논의된 것으로 전해졌다.', NULL, '파이낸셜뉴스', 'https://n.news.naver.com/mnews/article/014/0005484891', 'https://imgnews.pstatic.net/image/014/2026/03/02/0005484891_001_20260305162023825.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-03-02 18:10:19', 0, true, '2026-03-09 05:50:55.943577') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (728, '인크로스 ''스텔라이즈'', 앤어워드 AI 분야 골드 수상', '크리에이터 매칭부터 기획안 자동 생성까지AI 기술로 콘텐츠 마케팅 효율 극대화손윤정 인크로스 대표이사(오른쪽)가 앤어워드에서 디지털 서비스 부문 AI 분야 골드(Gold) 인증서를 수여받고 기념 촬영을 하고 있다. (사진=인크로스) *재판매 및 DB 금지[서울=뉴시스] 김경택 기자 = SK네트웍스 자회사인 통합 마케팅 전문 기업 인크로스는 회사의 AI(인공지능) 기반 콘텐츠 마케팅 플랫폼 ''스텔라이즈(Stellaize)''로 ''2025 앤어워드(A.N.D Award)'' 디지털 서비스 부문 AI 분야에서 골드(Gold)를 수상했다고 27일 밝혔다.회사 측에 따르면 앤어워드는 한국디지털기업협회가 주관하고 과학기술정보통신부가 공식 후원하는 국내 최대 규모의 디지털 콘텐츠 수상식이다. 매년 디지털 산업 발전에 기여한 우수 기업과 서비스를 선정해 시상한다. 올해 시상식은 전날 서울 코엑스 컨퍼런스 E홀에서 개최됐다.이번 수상작인 스텔라이즈는 ''별(Stella)처럼 수많은 크리에이터와의 협업을 AI로 최적화(Optimize)한다''는 의미를 담은 플랫폼이다. 크리에이터 발굴부터 계약, 협업, 성과 분석에 이르는 인플루언서 마케팅의 전 과정을 AI 기술로 자동화했다. 지난해 4월 프라이빗 오픈을 시작으로 7월 그랜드 오픈을 거쳐 현재 약 7000여개의 입점 채널 및 크리에이터를 확보하며 시장에 안착했다.스텔라이즈는 크리에이터 탐색부터 콘텐츠 기획, 운영, 성과 분석에 이르는 전 과정에 AI 기술을 적용, 인플루언서 마케팅 업계의 구조적인 비효율을 AI 로 해결했다는 점에서 높은 평가를 받았다. 이러한 문제를 해결하기 위해 스텔라이즈는 ▲AI 매칭을 통한 캠페인별 최적 크리에이터 추천 ▲AI 포트폴리오 어시스턴트를 통한 맞춤형 콘텐츠 기획안 자동 생성 ▲플랫폼 내 실시간 채팅과 캠페인 관리 일원화 ▲캠페인 전후 자동화 리포트를 통한 성과 측정 등의 핵심 기능을 제공한다.손윤정 인크로스 대표는 "이번 수상은 스텔라이즈가 크리에이터 매칭 플랫폼을 넘어 인플루언서 마케팅의 패러다임을 혁신하는 솔루션임을 인정받은 것"이라며 "검증된 파트너사를 통한 브랜드 안전성 확보와 AI 기술을 통한 업무 효율화로 브랜드와 크리에이터 모두에게 빛나는 성과를 선사하는 플랫폼으로 발전시켜나가겠다"고 말했다.인크로스는 향후 스텔라이즈의 AI 기능을 더욱 고도화하고, 국내 시장에서의 성과를 바탕으로 글로벌 콘텐츠 마케팅 시장으로의 확장도 추진할 계획이다.', NULL, '뉴시스', 'https://n.news.naver.com/mnews/article/003/0013791776', 'https://imgnews.pstatic.net/image/003/2026/02/27/NISI20260227_0002071888_web_20260227090439_20260227090616928.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-02-27 09:05:05', 0, true, '2026-03-09 05:50:55.943577') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (729, '[클릭 e종목]"케어젠, ''코글루타이드'' 상업화·신약 기대…코스닥 대장주 부상"', '한양증권은 9일 케어젠에 대해 경구용 GLP-1 보충제 상업화와 신약 파이프라인 개발을 앞세워 코스닥 대형 바이오주로서 존재감을 키우고 있다고 분석했다. 글로벌 공급 계약 가능성과 혁신 치료제 개발 기대가 동시에 부각되면서 성장 모멘텀이 풍부하다는 평가가 나온다.오병용 한양증권 연구원은 "케어젠은 1월 30일 경구용 GLP-1 보충제 ''코글루타이드''의 미국 FDA NDI(신규기능성원료) 등재에 성공했다"며 "이제 상업화 전략이 관건"이라고 밝혔다.회사에 따르면 현재 미국 내 다국적 기업과 공급 계약을 논의 중이며, 최근 화성 공장 실사를 완료하는 등 협상이 마무리 단계에 들어간 것으로 파악된다. 근육 증가 보충제인 마이오스타틴 억제제 ''마이오키''도 함께 공급될 가능성이 제기된다.오 연구원은 "''코글루타이드''는 건강기능식품이지만 합성 펩타이드 원료로 GLP-1 의약품 수준의 효과를 기대할 수 있는 유일한 제품"이라며 "글로벌 GLP-1 산업이 급격하게 커지고 있지만 아직까지 위고비나 마운자로 같은 GLP-1 약물을 경험한 사람은 전 세계 비만 인구의 1% 미만"이라고 설명했다. 이어 "케어젠의 목표는 ''GLP-1의 대중화''"라며 "물론 계약은 끝까지 어떻게 될지 모르지만 대형 공급 계약 가능성을 기대해 본다"고 말했다.신약 파이프라인도 주목된다. 점안제 형태의 황반변성 치료제 ''GC-P5''는 임상 1상에서 유의미한 효능을 확인하며 후속 임상 준비에 들어갔다. 오 연구원은 "''GC-P5''는 임상 1상에서 점안제임에도 습성 황반변성에서 아일리아 수준의 유효성을 확인했다"며 "3~4월 중 미국 FDA 임상 2상 IND를 신청할 것으로 예상된다"고 밝혔다.특히 케어젠은 이번 임상에서 습성 황반변성뿐 아니라 건성 황반변성까지 적응증 확대를 노리고 있다. 건성 황반변성은 환자 수가 습성 대비 약 10배 많지만 아직 뚜렷한 치료제가 없는 분야다.오 연구원은 "건성에서 유효성이 확인되면 신약의 가치는 훨씬 커진다"며 "IND 신청과 함께 FDA ''Breakthrough therapy designation(BTD, 혁신치료제)''도 신청할 예정"이라고 설명했다. 이어 "BTD 지정은 FDA가 초기 유효성을 인정했다는 강력한 시그널이며 2상 이후 시판 가능성이 열리는 중요한 이벤트"라고 강조했다.GC-P5의 임상 1상 데이터는 안과 분야 국제 학회인 COPHy(3월)와 RWC(5월)에 초록이 채택된 상태다. 회사에 따르면 현재 글로벌 빅파마 3곳과 기술이전 협의도 진행 중이다.신규 펩타이드 소재 개발도 새로운 성장 스토리로 평가된다. 오 연구원은 "동사는 신제품으로 10개 아미노산으로 구성된 펩타이드 ''히알룩스''를 개발했다"며 "피부 속 히알루론산 구조를 약화시켜 약물이 피부 아래로 침투할 수 있도록 돕는 물질"이라고 설명했다.히알루로니다제 효소는 일반적으로 정맥주사(IV) 약물을 피하주사(SC)로 전환할 때 사용되지만, 케어젠은 이를 화장품 시장으로 확장하려 하고 있다. 분자량이 큰 화장품 유효 성분이나 스킨부스터 성분을 주사 없이도 피부 아래 지방층까지 흡수되도록 하는 것이 목표다.오 연구원은 "''히알룩스''는 더 큰 시장인 화장품 분야를 노리고 있다"며 "사업은 초기지만 주식시장에서 열광할 만한 스토리"라고 평가했다. 이어 "당장 올해 글로벌 파트너십을 통해 상업화를 진행할 계획"이라고 덧붙였다.케어젠이 다양한 혁신 제품을 내놓을 수 있는 배경으로는 오랜 기간 축적된 펩타이드 연구 역량이 꼽힌다. 회사는 수십 년간의 연구를 통해 방대한 펩타이드 라이브러리와 수백 건의 특허를 보유하고 있다.오 연구원은 "''히알룩스''가 갑자기 등장한 것처럼 케어젠은 앞으로 또 어떤 혁신 제품을 가지고 나올지 모른다"며 "이는 동사 사업의 강력한 확장성이자 성장 잠재력"이라고 말했다. 최근 정부의 코스닥 시장 활성화 정책으로 코스닥 대형주에 대한 관심이 높아지는 점도 긍정적인 요인으로 꼽힌다.현재 코스닥 시가총액 상위 10개 종목 가운데 바이오 기업은 6곳에 달한다. 케어젠의 시가총액은 약 6조9000억원으로 코스닥 10위권 기업에 해당한다.오 연구원은 "앞 순위 바이오 종목인 삼천당제약, 에이비엘바이오, 코오롱티슈진 등과 비교해 단기 주가 상승 이벤트가 많아 보인다"며 "상대적인 저평가에 모멘텀도 풍부한 케어젠을 주목할 때"라고 강조했다.', NULL, '아시아경제', 'https://n.news.naver.com/mnews/article/277/0005731211', 'https://imgnews.pstatic.net/image/277/2026/03/09/0005731211_001_20260309093914285.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 09:39:04', 0, true, '2026-03-09 05:51:12.831471') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (730, '루닛·뷰노·코어라인 상장 후 지속된 시장조달…자생력 갖추려면', '이 기사는 2026년03월01일 08시20분에팜이데일리 프리미엄 콘텐츠로 선공개 되었습니다.[이데일리 임정요 기자] 영상의학과 보조 인공지능(AI) 소프트웨어 개발사들이 모두 상장 후 지속적인 시장조달을 필요로 하고 있다. 뷰노, 루닛, 코어라인소프트 얘기다. 이데일리는 ''진단 AI'' 회사들이 흑자전환하지 못하고 고전하는 이유를 각 사의 재무총괄임원(CFO)에게 물었다.(그래픽=김정훈 기자)뷰노 691억·루닛 6219억·코어라인 589억 조달엑스레이, CT, MRI 등 영상진단을 AI로 보조하는 뷰노(338220), 루닛(328130), 코어라인소프트(384470)가 연초 일제히 외부조달에 나섰다.이 세 회사는 코스닥에 상장한지 3년~5년의 시간이 흘렀지만 아직 영업적자에서 벗어나지 못하고 있다. 이번 발행계획까지 합하면 지난 2021년 상장한 뷰노는 상장 후 누적 691억원, 2022년 상장한 루닛은 누적 6219억원, 2023년 상장한 코어라인은 누적 589억원을 시장 조달한다.조달 방식은 차이가 있다. 뷰노는 상환기간이 30년인 ''영구'' 전환사채(CB), 루닛은 주주배정 후 실권주 일반공모, 코어라인소프트는 CB 발행 형태를 선택했다.이들은 구독형 사업모델로 지속적인 매출 실현, 해외 진출을 통한 시장 확대 등 공통적인 숙제가 있다. 숙제를 풀어야 수익성 있는 사업으로 자생력을 갖출 수 있을 전망이다.미국 현지 법인을 키우고 뉴질랜드 소재 볼파라를 인수하기까지 하며 가장 적극적인 행보를 보인 루닛은 가장 극심한 적자에 시달리고 있다. 뷰노와 코어라인소프트는 루닛에 비해 점진적인 단계를 밟고 있다. 이들 또한 미국, 유럽, 호주 등지에서 매출을 키우기 위한 노력을 기울이고 있는 상황이다.국내에 집중한 뷰노, 신의료기술 평가 유예로 그간 ''선방''3사 중 가장 재무적 안정권에 들어선 것은 당장은 뷰노다. 지난 2021년 상장한 뷰노는 작년 매출이 348억원으로, 직전연도 대비 34.7% 증가했다. 영업손실은 49억원으로 직전연도 124억원 대비 크게 개선했다. 뷰노는 루닛에 비해 매출 규모는 작지만 영업이익률 면에서는 더 빠른 개선을 보이고 있는 점이 주목된다.김준홍 뷰노 CFO는 "의사들이 못하거나 안하는 일을 하면 돈이 된다. 영상 진단보조는 대부분이 ''보조''의 역할에서 끝나지만 당사의 ''딥카스''는 의사들이 하지 못하는 ''심정지 예측''을 통해 가치를 창출하고 있다"고 말했다.뷰노의 딥카스는 간호사들이 수기로 기록하는 전자의무기록(EMR)을 기반으로 병원에 입원한 환자의 심정지를 조기에 예측하는 솔루션이다. 뷰노는 ''진단'' 제품도 있지만 ''예후·예측'' 제품인 딥카스를 통해 적지 않은 매출 신장을 이뤘다.작년 3분기 기준 뷰노의 진단솔루션 매출은 수출과 내수를 합해 13억원이었지만 예후·예측솔루션은 내수시장에서만 199억원을 벌어들였다. 딥카스는 국내 신의료기술 평가 유예를 통해 지난 2022년 8월부터 3년간 비급여 처방이 실시되고 있는 점이 빠른 매출 신장으로 이어졌다.김 CFO는 "딥카스는 2024년~2025년 총 비용이 늘지 않았다. 해외 진출을 하더라도 수가를 인정받으면 국내에서 보여지는 모습과 동일하게 빠르게 성장할 것"이라고 말했다. 뷰노는 미국, 유럽, 중동 등 심포지움에 참가해 딥카스의 해외 진출에 노력하고 있다.김 CFO는 "(뷰노의) 사업모델은 서비스형소프트웨어(SaaS)가 메인이다. 구독 모델로, ''원타임'' 매출이 아니기에 대략적인 매출 예측이 가능하다. 이 같은 점이 투자자들로 하여금 영구 CB에 베팅할 수 있게끔 했다"고 말했다.뷰노는 최근 연달아 영구 CB 발행으로 조달을 받았다. 영구 CB란 만기가 30년이고 채권자가 중도에 상환을 요구할 수 없어 부채가 아닌 자본으로 인정받는 회사채다. 발행 후 3년 경과 시점인 2028년부터 만기이율 5%에 해마다 4% 이율이 가산되는 조항이 존재한다.김 CFO는 "이율 가산 내용은 영구 CB에 의례적"이라며 "미상환 CB 541억원의 보통주 전환도 기대하고 있지만, 회사에 현금이 없는 상황이 아니기에 상환도 가능하다"는 입장을 보였다.김 CFO는 뷰노의 흑자전환 예상 시점에 대해서는, "내부적 고민"이라며 "당장 흑자를 맞추는게 중요한지 구조적으로 흑자가 되는 시스템을 만드는게 좋은지에 대해, 후자에 기울고 있다"고 말했다.뷰노는 앞으로 딥카스의 신의료기술평가 유예 연장 및 유사한 심정지 예측 서비스 회사 에이아이트릭스와의 법적 분쟁이 지켜볼 대목이다.루닛, 해외시장 점유율 확대 ''관건''해외 진출에 가장 적극적으로 임한 루닛은 지난 2022년 상장해 작년 매출로 831억원을 기록했다. 이는 직전연도 대비 53.4% 늘어난 수치이나 영업손실이 매출과 비등한 830억원으로, 직전연도 626억원에서 악화됐다. 루닛은 3사 중 가장 매출이 크지만 유일하게 영업손실이 심화된 기업이다.루닛의 연결실적에 포함되는 볼파라는 작년 3분기에 367억원의 매출을 냈지만 영업적자로, 순손실은 19억원을 기록했다.박현성 루닛 CFO는 "2025년 비용이 증가한 것은 사실 ''착시효과''가 많은 부분을 차지한다"며 "지난 2023년 보고서에는 루닛의 재무제표만 반영됐고 2024년에는 루닛 재무제표에 볼파라의 8개월치 재무제표를 합산 반영했다. 이후 2025년에는 루닛의 재무제표와 볼파라의 12개월치 재무제표를 온전히 합산하기 시작했다"고 말했다.이 같은 이유로 각 법인별 비용이 크게 변화하지 않았더라도 연결 기준으로 비용이 매우 커진 것 같은 오해를 부른다는 설명이다.박 CFO는 "영업적자의 상당 부분이 주식보상비용"이라며 "현금이 나가지 않는 회계상 비용이지만 2025년에만 260억원이 계상되어, 영업손실이 악화된 느낌을 준다"며 "현금영업이익/손실(EBITDA) 기준으로는 오히려 2024년 540억원에서 2025년 570억원으로 소폭의 증가를 보였다"고 말했다.루닛은 시장 조달 측면에서도 3사 중 집중포화를 받고 있다. 지난 2024년 볼파라 인수를 위해 기관투자자들을 대상으로 1715억원어치 CB를 발행했고 이를 상환하고자 올 2월 2500억원 규모의 주주배정 유상증자를 발표했다.박 CFO는 "CB 상환(풋옵션)에 대한 리스크로 작년 여러 호재들이 기업가치에 온전히 반영되지 않는 모습을 수차례 목격했고, 외부 투자자들도 유사한 피드백을 줬다"며 "CB 상환을 위한 주주배정 유상증자는 주주가치 제고를 위해서도 꼭 필요한 부분"이라고 말했다.일각에서는 기존 CB 투자자들에 저렴한 가격에 재투자를 받는 방향이 나았을 거라는 의견도 제기된다. 루닛 CB에는 이앤인베스트먼트, 산은캐피탈, 미래에셋증권, 키움증권, 한양증권, 신한투자증권, 타이거자산운용, GVA자산운용, 시너지아이비투자, 지씨테크 등이 투자했다.박 CFO는 "부채를 부채로 막는 것은 리스크라고 생각했다"며 "제3자 배정 유상증자도 의미있는 수준으로 논의했으나 약 1970억원의 CB 풋옵션은 대규모 주주배정 유증을 통해서만 대응 가능하다는 판단이었다"고 말했다.박 CFO는 "루닛이 아직 적자지만 지난 2019년 매출 2억원에서 2025년 831억원으로 급성장했다"며 "내부적으로 작년 4분기에 구조조정을 시작했고 2026년부터 비용절감 효과가 나타난다. 올해 온기 기준 현금영업이익(EBITDA)을 창출할 것"이라고 말했다.코어라인소프트, 올해 해외 성과 원년코어라인소프트는 지난 2023년 상장해 작년 42억원의 매출로 직전연도 대비 45.62% 증가했다. 영업손실도 29억원으로, 직전연도 35억원에서 개선했다.정우석 코어라인소프트 CFO는 "현재 국내에서만 16만명, 작년 기준 전세계적으로 40만명이 코어라인소프트 솔루션을 쓰고 있다. 일회성 매출에서 SaaS형(구독형) 매출로 전환을 유도하고 있으며 지난 2024년 29%이던 비중이 작년 45%로 늘어났다. 중요한 포인트"라고 말했다.코어라인소프트는 유럽과 호주를 중심으로 국가 단위 폐암검진 사업과 대형 병원 도입이 확대되는 국면에 진입했다. 비용 통제 기조를 유지하면서 반복형 매출 기반을 확장해 실적 가시성을 높인다는 전략이다.정 CFO는 "(당사는) 해외시장에 집중하고 있다. 가장 큰 독일시장이 열리고 있다. 독일 중심으로 폐암검진 수가 제도에 녹아들 것이며, 올해가 글로벌 사업 성과가 본격적으로 수치화되는 전환점이 될 것"이라고 말했다.코어라인소프트는 올 2월 전환가 4100원에 시가하락에 따른 전환가 조정(리픽싱) 조항이 없는 내용으로 125억원을 CB 조달했다. 한양증권, DB증권, DS투자증권 등이 투자했다.정 CFO는 "리픽싱 조항이 있으면 싸게 전환할 수 있는 장점이 있지만 리픽싱으로 인한 평가손실이 반영될 시 코어라인소프트에 재무적인 부담이 작용할 수 있다"며 "투자자들 입장에서는 코어라인소프트의 하락보다는 상승을 바라는 바음으로 리픽싱을 설정하지 않은 것"이라며 "이미 리픽싱 없이도 충분히 싼 가격"이라고 말했다.정 CFO는 "한눈에 훤히 보이는 엑스레이 영상과 달리 CT 영상은 의사들이 전체를 다 볼 수 없다. AI가 필요한 것은 확실"하다며 "특히 일반 검진자들에서는 문제가 있는 경우가 2~3%에 불과에 이들에게서 폐암을 조기 검진해내는 데에 (당사의) 솔루션이 가치를 보일 것"이라고 말했다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006230583', 'https://imgnews.pstatic.net/image/018/2026/03/09/0006230583_001_20260309082215372.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 08:22:15', 0, true, '2026-03-09 05:51:12.831471') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (731, '중동發 ‘금리 변동성’ 무색…신한지주, 영구채 수요예측서 목표액 2배 확보', '4000억 증액 예정…금리 4.2% 결정이 기사는 2026년 3월 6일 18:42자본시장 나침반  ''시그널(Signal)''에 표출됐습니다.중동발(發) 지정학적 리스크 확대 여파로 금리 변동성이 확대된 가운데 신한금융지주(신한지주)가 신종자본증권 발행을 위한 수요예측에서 목표액의 2배 가까운 금액을 모집하는 데 성공했다.6일 투자은형(IB) 업계에 따르면 신한지주는 이날 진행한 수요예측에서 총 2700억 원 모집에 5290억원의 유효 주문을 받았다. 이런 수요예측 결과를 기반으로 신한지주는 최대 4000억 원까지 증액할 예정이다. 발행 주관사로 한양증권과 메리츠증권이 참여했다.신한지주는 희망 금리 밴드(범위) 내에서 목표액을 채웠다. 공모 희망 금리로 3.60% ~ 4.20%를 제시한 결과 4.15% 수준에서 목표액에 도달했다. 4000억 기준으로는 밴드 상단인 4.20%에서 금리가 결정됐다. 미국의 이란 공습이 시작되면서 이달 3일 하루에만 장단기 금리가 모두 15bp 이상 급등하는 등 채권 투심이 악화되는 상황에서도 우량 기관에 대한 견조한 투심을 확인했다는 게 업계의 중론이다.아울러 최근 주식시장으로의 머니무브로 개인 투자자들의 채권 상품에 대한 관심이 많이 낮아졌음에도 불구하고 연기금, 보험사, 퇴직자금 등을 주요 기관을 집중 공략한 점이 수요예측 흥행으로 이어졌다는 의견도 나온다. 업계 관계자는 “금리 방향성의 변곡점에서 회사채 시장의 금리 결정은 발행사와 투자 기관 모두에게 어려운 상황”이라며 “신한지주는 시장과 투자 기관들과의 적극적인 소통을 통해 마중물을 역할을 수행하고 있다”고 설명했다.', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004596613', 'https://imgnews.pstatic.net/image/011/2026/03/06/0004596613_001_20260306185410043.png?type=w800', 'NEWS_FINANCE', NULL, '2026-03-06 18:54:10', 0, true, '2026-03-09 05:51:12.831471') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (771, 'KISCO홀딩스, 주당 850원 현금배당 결정', '[헤럴드경제=증권부] KISCO홀딩스는 보통주 1주당 850원의 현금 결산배당을 결정했다고 4일 공시했다.시가배당율은 3.2%이며 배당금총액은 104억5205만원이다.', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002608397', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2026-03-04 16:25:10', 0, true, '2026-03-09 05:53:13.811617') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (772, '장마감했는데 살 수 있네…대체거래소, 종목 700개로 늘어난다', '서울 여의도 넥스트레이드에서 직원들이 업무를 보고 있다. [사진 연합뉴스]대체거래소(ATS) 넥스트레이드에서 내년 1분기 거래 가능한 종목이 현 630개에서 700개로 늘어난다.넥스트레이드는 24일 내년 1분기 매매체결대상종목으로 코스피 375종목과 코스닥 325종목 등 총 700종목을 선정했다고 밝혔다.코스피200지수와 코스닥150지수를 구성하는 350개 종목에 더해 유가증권시장과 코스닥 시장에서 각각 시가총액 상위 175종목씩이 매매종목으로 선정됐다.다만 원활한 거래한도 관리를 위해 상장종목의 주가분포 등을 고려해, 주가 수준이 낮아 거래량의 변화가 큰 종목은 제외했다고 넥스트레이드 측은 설명했다.삼성전자, 알테오젠 등 477종목은 직전 분기에 이어 계속 매매체결 대상종목에 포함됐고, 신규 편입된 종목은 삼성에피스홀딩스, 에임드바이오 등 120종목이다.직전 분기 거래대상 종목 중 자본시장법상 거래량 한도 관리 목적으로 편출됐던 한국전력, 에코프로 등 103개 종목도 재편입됐다.반면, SK네트웍스, 파트론 등 152종목은 편출 처리됐다.넥스트레이드 측은 "매매체결대상종목은 매 분기 선정이 원칙이나, 거래량 규제를 준수하기 위해 지난 3분기 이후에는 매매체결 대상종목을 변경하지 않고 종목수를 축소해 왔다"면서 "그 결과 12월 말 기준으로는 한도 규제를 준수할 전망"이라고 말했다.현행 자본시장법 시행령은 대체거래소의 최근 6개월 일평균 거래량이 한국거래소(KRX) 일평균 거래량의 15%를 초과하면 안 되도록 하고 있다.그러나 올해 3월 출범한 국내 첫 대체거래소인 넥스트레이드는 급성장을 거듭하며 반년도 되지 않아 거래량 상한선에 도달했다.이에 지난 8월부터 네차례에 걸쳐 165개 종목을 순차적으로 편출하면서 거래대상 종목수가 630개로 감소했으나, 내년 1분기부터는 다시 700개로 종목수가 늘게 됐다.여기에는 SK하이닉스의 투자경고종목 지정, 한국거래소의 수수료 인하 등의 영향으로 최근 시장점유율이 하락할 조짐이 보이는 것도 일부 영향을 미쳤을 것으로 보인다.넥스트레이드 관계자는 "일별·주기별 거래량 비율의 모니터링 등을 통해 한도규제를 선제적으로 준수함과 동시에 매매체결대상 종목수를 700개 이내로 유지해 투자자의 투자수요에 부응할 예정"이라고 말했다.아래는 2026년 1분기 거래종목 신규·재편입 현황.▲코스피 신규편입 종목BYC, DB증권, F&F홀딩스, HL홀딩스, INVENI, KCC글라스, KISCO홀딩스, KPX홀딩스, LF, LX하우시스, NICE, 고려제강, 광주신세계, 교보증권, 국도화학, 농심홀딩스, 대덕, 대한제분, 명인제약, 모토닉, 미래에셋생명, 부국증권, 삼성에피스홀딩스, 삼양바이오팜, 삼양사, 삼영무역, 삼진제약, 서울가스, 서흥, 세방, 스틱인베스트먼트, 신대양제지, 신도리코, 쏘카, 아세아, 아세아시멘트, 에이블씨엔씨, 유나이티드제약, 일성아이에스, 일신방직, 잇츠한불, 조광피혁, 종근당홀딩스, 케이씨, 쿠쿠홀딩스, 쿠쿠홈시스, 티엠씨, 퍼시스, 한국철강, 한섬, 한양증권, 한일홀딩스, 한진, 현대홈쇼핑 등 54종목▲코스피 재편입 종목DB하이텍, HD현대건설기계, HJ중공업, LG씨엔에스, LX홀딩스, SK오션플랜트, SK이터닉스, STX엔진, 넥스틸, 대덕전자, 대신증권, 대한전선, 대한조선, 두산퓨얼셀, 디아이, 롯데관광개발, 미래에셋증권, 비에이치, 산일전기, 삼화콘덴서, 세진중공업, 솔루엠, 신풍제약, 애경산업, 애경케미칼, 우진, 이수페타시스, 일동제약, 일진전기, 제주은행, 카카오, 코리아써키트, 코스모신소재, 코오롱, 콜마홀딩스, 파라다이스, 파미셀, 포스코DX, 풀무원, 한국전력, 한미반도체, 한온시스템, 한화시스템, 한화엔진, 현대건설, 화신, 후성 등 47종목▲코스닥 신규편입 종목AP시스템, CJ프레시웨이, HEM파마, KH바텍, 가비아, 강원에너지, 나라스페이스테크놀로지, 나무가, 나이스정보통신, 네오팜, 노타, 뉴로핏, 대양전기공업, 대원산업, 더핑크퐁컴퍼니, 디아이티, 디오, 매커스, 메카로, 바텍, 브이엠, 비나텍, 비츠로넥스텍, 삼목에스폼, 상아프론테크, 석경에이티, 세나테크놀로지, 씨어스테크놀로지, 씨엠티엑스, 아크릴, 안트로젠, 알지노믹스, 에스투더블유, 에임드바이오, 에코마케팅, 우리기술, 우주일렉트로, 원익머트리얼즈, 유니셈, 이노테크, 인바디, 인화정공, 제이브이엠, 제이에스링크, 케이아이엔엑스, 케이엔알시스템, 케이프, 코세스, 코오롱생명과학, 큐리오시스, 티에프이, 파인엠텍, 폰드그룹, 프로티나, 피에이치에이, 하나기술, 하이록코리아, 한국피아이엠, 한라IMS, 한라캐스트, 한솔아이원스, 한스바이오메드, 한양디지텍, 한양이엔지, 현대무벡스, 휴온스 등 66종목▲코스닥 재편입 종목KG이니시스, LS마린솔루션, 감성코퍼레이션, 갤럭시아머니트리, 고영, 나우로보틱스, 디앤디파마텍, 로보스타, 로보티즈, 로킷헬스케어, 미코, 범한퓨얼셀, 비에이치아이, 삼양컴텍, 삼현, 성우하이텍, 셀비온, 솔트룩스, 쏠리드, 쓰리빌리언,씨메스, 아난티, 아스테라시스, 아이티센글로벌, 에스엔시스, 에이디테크놀로지, 에이프릴바이오, 에코프로, 엑스게이트, 오리엔탈정공, 온코닉테라퓨틱스, 올릭스, 와이바이오로직스, 원익홀딩스, 유니테스트, 유진로봇, 이뮨온시아, 인벤티지랩, 인투셀, 지엔씨에너지, 지투지바이오, 켐트로닉스, 코나아이, 큐리옥스바이오시스템즈, 클로봇, 태광, 토모큐브, 티로보틱스, 티엑스알로보틱스, 티엘비, 포스코엠텍, 퓨쳐켐, 하나마이크론, 한텍, 현대힘스, 휴메딕스 등 56종목', NULL, '이코노미스트', 'https://n.news.naver.com/mnews/article/243/0000090090', 'https://imgnews.pstatic.net/image/243/2025/12/24/0000090090_001_20251224161013152.jpg?type=w800', 'NEWS_ETC', NULL, '2025-12-24 16:10:13', 0, true, '2026-03-09 05:53:13.811617') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (773, '배당소득 분리과세, 혜택 누리려면 최소 1.2억 투자해야 [뜨거운 배당주, 新투자전략]', '배당률 상위 배당성향 40% 이상 기업1.2억~2.6억원 투자시 분리과세 혜택정부가 고배당 기업을 대상으로 배당소득에 14~30% 분리과세를 적용하기로 하면서 투자자들은 과연 얼마나 투자해야 혜택을 받을 수 있을지 주목하고 있다.특히, 분리과세 최저 구간인 연 2000만원 배당이 포인트다. 종목과 구성에 따라 세부적으론 차이가 있지만, 대체로 어느 기업이 얼마나 투자해야 분리과세 최저구간에 적용받을지 관심사다.1일 본지가 국내 기업 가운데 배당률 상위 기업을 분석한 결과에 따르면, 시가배당률이 7~16% 수준인 고배당 종목에 투자할 경우 연 2000만원 배당을 확보하는 데 필요한 자산 규모는 종목별로 최소 1억2000만~2억6000만원 사이로 나타났다. 배당소득 분리과세에 해당하는 배당성향 40% 이상의 기업 가운데 배당률 상위 종목을 바탕으로 계산한 결과다.다시 말해, 1.2억~2.6억원의 투자 자산 규모를 가진 투자자라면, 배당 수익에서 분리과세 적용 여부를 살펴볼 만하다는 의미다.한국거래소 정보데이터시스템에 따르면, 한샘의 시가배당률은 16.6%다. 연 2000만원의 배당소득을 만들기 위해서는 약 1억2000만원이 필요하다. 현대엘리베이터는 9.3%로 2억1500만원, 케이카는 8.6%로 2억320만원 수준의 투자금이 있어야 한다.금속업종의 KISCO홀딩스와 한국철강은 약 8.3%의 배당률로 2억4000만원 안팎이 필요하며 한국쉘석유·유안타증권·인베니(옛 에스코홀딩스)의 경우 7%대 배당률을 감안하면 2억5000만~2억6300만원 규모의 자금이 요구된다.개편안에 따르면 배당성향 40% 이상 또는 배당성향 25% 이상, 배당액이 전년 대비 10% 이상 증가한 기업의 배당은 내년부터 14~30% 구간형 분리과세가 적용된다. 현행 제도는 배당소득을 이자소득과 합산해 연간 2000만원 이하일 경우 15.4% 세율로 분리과세하고, 연간 2000만원을 초과하면 근로·사업소득과 합산해 최고 49.5%(지방소득세 포함)의 종합소득세율을 적용한다.국내 배당주 정책이 변경되면서 해외 고배당주와의 과세정책 비교도 중요해졌다. 통상 미국 주식 등은 배당 위주의 포트폴리오를 구성하는 데에 널리 활용됐다. 미국은 분기배당이 활성화돼 있어 구성에 따라 마치 월세처럼 배당을 수령할 수 있기 때문이다.국내에서도 정부 정책 기조 등과 맞물려 점차 배당주의 혜택을 늘려가는 추세다. 과거보다 상대적으로 국내 고배당주의 매력이 커질 수 있다. 미국 등 해외 주식 투자가 활발해지면서 투자자들은 국내와 해외의 배당 관련 정책을 꼼꼼하게 살펴 비교해 볼 필요가 있다.우선, 국내 고배당주에는 세제 인센티브가 적용되지만 해외 고배당주는 여전히 종합과세 대상이기 때문에 세 부담 측면에서는 국내 고배당주 투자가 상대적으로 유리하다.만약 해외주식에 투자할 경우에는 수령 시점에서 해당 국가가 먼저 세금을 원천 징수한다. 이후 연간 배당·이자 등 금융소득이 2000만원을 넘으면 금융소득종합과세 대상이 된다.5월 종합소득세 신고 과정에서 해외 조세당국에서 떼인 세금은 외국납부세액공제로 차감하고 차액은 종합소득세율(6.6~49.5%)로 합산 과세가 된다.일례로 미국 대표 고배당주인 버라이즌에 투자해 연 2000만원의 배당소득을 확보할 경우 세 부담은 국내 고배당 기업과 크게 달라진다. 버라이즌의 배당수익률(6.71%)을 적용하면 연 2000만원의 배당을 만들기 위해서는 약 2억9800만원의 투자금이 필요하다.미국은 배당 지급 시점에 15%의 원천징수세를 먼저 부과한다. 이에 따라 2000만원 배당 중 300만원이 미국에서 차감되고, 배당수익으로 1700만원이 들어온다. 이후 금융소득이 2000만원을 넘으면 배당과 이자소득 전체가 다른 소득과 합산돼 자신의 소득수준에 따라 종합소득세율을 적용받는다. 이때 미국에서 원천징수된 15%는 외국납부세액공제로 차감되며 부족분은 추가로 납부하게 되는 식이다.염동창 한국투자증권 연구원은 “이자소득이 배당소득으로 이동한다면 해당 자금은 보수적인 성격을 지닌 자금일 가능성이 크다”라며 “2024년 기준으로 배당소득 분리과세 대상이 되는 요건을 만족하면서 5년 평균 배당수익률이 4% 이상인 기업들이 해당 자금의 수요처가 될 가능성이 높다”고 짚었다.그러면서 “이익의 성장보다는 안정적인 배당금을 지급하는 해당 기업에 대한 관심이 필요하다”고 설명했다. 신주희 기자', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002565431', 'https://imgnews.pstatic.net/image/016/2025/12/01/0002565431_001_20251201113228993.jpg?type=w800', 'NEWS_ETC', NULL, '2025-12-01 11:32:28', 0, true, '2026-03-09 05:53:13.811617') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (732, '[마켓인]신한금융지주, 신종자본증권 수요예측에 5290억원 주문 들어와', '2700억원 모집에 5290억원 수요 확인최대 4000억원까지 증액 발행 검토“지주사 자체 운영자금으로 사용 예정”[이데일리 마켓in 김연서 기자]신한금융지주가 신종자본증권 발행을 위해 진행한 수요예측에서 목표액을 채우는 데 성공했다. 신한금융지주는 최대 4000억원까지 증액 발행을 검토 중이다.6일 투자은행(IB) 업계에 따르면 신한금융지주는 이날 신종자본증권 발행을 위한 기관투자자 대상 수요예측에서 2700억원 모집에 5290억원의 주문을 받았다.희망 금리는 3.6%~4.2%를 제시한 가운데 2700억원 기준 4.15%로 책정됐다. 최대 증액 금액인 4000억원까지 증액 발행할 경우 밴드 상단인 4.2%에서 발행이 가능할 전망이다.신종자본증권은 만기가 없거나 30년 이상으로 매우 길어 사실상 영구적이며 채권처럼 이자를 지급하지만 회계상 자본으로 인정받는 하이브리드 채권을 의미한다.신한금융지주는 이번 신종자본증권 발행을 통해 조달한 자금을 지주사 자체 운영자금으로 사용할 계획이라고 밝혔다.대표주관 업무는 한양증권과 메리츠증권이 맡았다. 신종자본증권 발행 예정일은 이달 16일이다.한국기업평가, 한국신용평가, NICE신용평가는 신한금융지주의 신종자본증권 신용등급을 ‘AA-’로 평가했다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006229938', 'https://imgnews.pstatic.net/image/018/2026/03/06/0006229938_001_20260306180912663.png?type=w800', 'NEWS_FINANCE', NULL, '2026-03-06 18:09:12', 0, true, '2026-03-09 05:51:12.831471') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (733, '불장 소외되는 중소 증권사, 새 먹거리 사활', '[앵커]최근 증시의 급등락 속에서 관심을 받았던 업종 중 하나는 증권사들이었습니다.그런데 거래 수익을 대형사들이 많이 가져가고 중소형사들은 양극화가 더 심해진다는 평가가 많은데요.이런 상황을 돌파하기 위해 중소 증권사들이 신사업 추진에 나섰습니다.취재기자 연결합니다.신성우 기자, 개인을 이제 와서 끌어모으긴 쉽지 않을 테고, 기관들을 노려야겠죠?[기자]네, 그렇습니다.유진투자증권이 ''기관전용 사모펀드의 업무집행사원'' 업무를 신규 사업에 추가하기로 했습니다.업무집행사원이란 사모펀드 재산을 운용, 관리하는 핵심 주체를 말하는데요.유진투자증권은 "지난달 금융당국으로부터 업무집행사원 라이선스를 취득했다"며, "이달 말 주주총회를 거쳐 관련 사업을 본격적으로 추진한다"고 설명했습니다.부동산 PF를 담당하던 구조화금융본부에서 해당 업무를 맡아 부동산 관련 펀드를 조성하고 또 자금을 운용할 계획입니다.유진투자증권은 지난해 645억 원의 순이익을 거둔 바 있는데요.실적 개선세가 뚜렷하게 나타나고 있지만, 조 단위 순이익을 내는 대형사들에 비하면 아직 초라합니다.이에 새로운 성장 동력을 확보하기 위해 신규 사업 기회를 모색하는 것으로 풀이됩니다.[앵커]중소 증권사들의 사업 환경이 녹록지 않죠?[기자]한양증권도 지난달 기관전용 사모펀드 업무집행사원 등록을 마치고 사모펀드 비즈니스 역량 강화에 나선다고 밝힌 바 있습니다.그간 대형사 위주로 관련 사업이 진행되어 왔으나, 이제 중소형사들도 적극 뛰어드는 양상인데요.증권사 입장에선 운용 규모를 키워 딜 경쟁력을 강화하고 이를 통해 수익성 확대를 기대해 볼 수 있습니다.증권업계 관계자는 "부동산 시장 상황이 좋지 않은 가운데, 중소형사들도 얼마 남지 않은 우량 사업장에 뛰어들 기회를 모색하고 있다"고 설명했습니다.SBS Biz 신성우입니다.당신의 제보가 뉴스로 만들어집니다.SBS Biz는 여러분의 제보를 기다리고 있습니다.홈페이지 = https://url.kr/9pghjn', NULL, 'SBS Biz', 'https://n.news.naver.com/mnews/article/374/0000496281', 'https://imgnews.pstatic.net/image/374/2026/03/06/0000496281_001_20260306134509803.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-06 11:58:08', 0, true, '2026-03-09 05:51:12.831471') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (734, '손해보며 전환 아니었어?... 7배 차익 기대하는 코오롱티슈진 CB 투자자, 그만큼 오버행 우려', '이 기사는 2026년 3월 5일 16시 30분 조선비즈 머니무브(MM) 사이트에 표출됐습니다.코스닥 상장사 코오롱티슈진의 전환사채(CB)에 투자한 기관 투자자들이 짧은 기간 투자에도 불구하고 큰 차익을 낼 것으로 예상된다.최근 나온 CB 전환 공시를 언뜻 보면 시장 가격보다 비싼 가격에 전환권을 행사, 손실을 보는 거래인 것으로 해석되지만 실제로는 2.5~7배의 차익을 낼 것이라는 게 업계의 분석이다. 이와 동시에 공시상 문구로 보이는 것보다 오버행 우려(잠재적 매도 대기 물량)도 클 것으로 보인다. 전체 시가총액의 10%에 가까운 매물이 대기하고 있기 때문이다.코오롱티슈진의 무릎 골관절염 치료제 TG-C 1약(왼쪽)과 2약./뉴스15일 투자은행(IB) 및 금융감독원 전자공시시스템에 따르면, 코오롱티슈진은 2·3회차 CB 일부에 대한 전환청구권이 행사됐다고 지난 4일 공시했다. 2회차 CB는 10억원어치로, 전환가액은 7만1285원이다. 반면 3회차 CB 315억원어치는 전환가액 19만2210원에 전환된다.코오롱티슈진은 2024년 골관절염 치료제 TG-C(옛 인보사)의 임상시험 3상 진입을 앞두고 자금 조달에 나섰다. 그해 6월 2회차 CB 245억원을 발행한 데 이어, 이듬해인 지난 2025년에는 3·4회차 CB로 각각 565억원, 1225억원을 조달했다. 투자자로는 유진투자증권, 한양증권 등 증권사와 지브이에이자산운용, 한국투자밸류자산운용 등 자산운용사가 참여했다.투자자들은 만기 상황보다는 주식 전환을 염두에 둔 것으로 보인다. 표면 이자율과 만기 이자율 모두 0%로 이자 수익을 기대하기는 어려운 조건이었다. 투자자가 원금 외 추가 수익을 위해서는 주식 전환과 주가 상승이 함께 이뤄져야 했다.이번에 전환된 3회차 CB 315억원의 경우, 언뜻 보면 전환가액이 현재 주가보다 높은 수준이다. 코오롱티슈진의 현재 주가는 10만원대다. 전환가액을 단순 계산하면 투자금의 절반만 회수하는 것으로 보인다.하지만 이는 미국 법인인 코오롱티슈진이 국내 주식 시장에 한국주식예탁증서(KDR) 형태로 상장해 있어 나타난 착시다. 코오롱티슈진은 미국 본주 1주당 5주의 KDR이 코스닥 시장에 상장해 있다. 미국 본주 1주를 코스닥 시장에 상장된 KDR 5주로 교환하거나, 역으로 KDR 5주를 미국 본주 1주로 교환할 수 있다.코오롱티슈진의 CB 전환가액은 미국 본주 기준으로 책정된 만큼 CB 투자자 입장에서는 현재 주가를 5배 곱해야 하는 셈이다. 3회차 CB 전환가액 19만2210원으로 얻을 수 있는 KDR은 5주인 만큼, 시장 가치는 약 50만원에 달한다. 투자 1년 만에 2.5배의 차익을 낸 것이다. 그보다 앞서 투자한 2회차 CB 투자자들은 2년 만에 약 7배의 차익을 얻을 수 있다.즉 개인 투자자 입장에서는 앞으로 나올 대기 물량도 현재 공시상으로 드러난 것보다 5배 많다는 점을 인지해야 한다.현재까지 발행된 CB가 본주 기준 약 119만9311주였던 점을 고려하면 KDR 기준으로는 599만6555주에 달한다. 코오롱티슈진의 발행 주식이 8325만주 수준임을 감안하면 CB 전량이 전환되면 7% 가까운 신규 주식이 발행될 수 있다.금융투자업계의 한 관계자는 “일반적인 CB와 달리 주가와 5배의 괴리가 있어 주식 전환으로 인한 영향이 눈에 보이는 것보다 훨씬 크다”며 “CB 구조상 모든 물량이 전부 전환될 가능성이 큰 만큼, 대규모 오버행 우려가 불거질 수 있다”고 설명했다.다행히 코오롱티슈진의 주가는 최근 급등세를 보이고 있다. 2024년 1만원대에 머무르던 코오롱티슈진 주가는 지난해 초 2만원대를 넘었고, 최근에는 10만원대까지 급등했다. 골관절염 신약 TG-C의 임상시험 3상 결과가 올해 하반기 발표 예정으로, 이에 대한 기대감이 반영된 것으로 보인다.TG-C는 정상 연골세포와 유전자 변형 세포를 혼합해 관절 내에 직접 주사하는 골관절염 치료제다. 단순히 골관절염 증상을 완화하는 기존 치료제와 달리 연골을 재생하는 근본적인 골관절염 치료제(DMOAD) 후보로 꼽힌다. DMOAD가 규제기관의 허가를 받은 사례는 아직 없다.‘인보사 사태’로 불거진 법정 리스크도 해소되는 국면이다. 인보사는 2017년 국내 허가를 받았으나 이후 미국에서 임상시험을 진행하던 도중 허가받지 않은 세포가 혼입된 것이 확인됐다. 2019년 식품의약품안전처는 인보사에 대해 판매 중단, 품목허가 취소 처분을 내렸다. 이후 코오롱티슈진의 주식 거래가 중단되기도 했다. 주주들은 코오롱티슈진과 코오롱생명과학에 대해 손해배상 청구 소송을 제기했으나, 최근까지 진행된 재판에서는 모두 회사가 승소했다.', NULL, '조선비즈', 'https://n.news.naver.com/mnews/article/366/0001146213', 'https://imgnews.pstatic.net/image/366/2026/03/06/0001146213_001_20260306161010432.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-06 06:01:29', 0, true, '2026-03-09 05:51:12.831471') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (735, '[클릭 e종목]"제이엘케이, 美의료 AI 권고…올해 실적 가시화"', '한양증권은 5일 제이엘케이에 대해 미국 뇌졸중 치료 가이드라인이 약 8년 만에 업데이트되면서 수혜가 전망된다고 분석했다.이준석 한양증권 연구원은 "최근 약 8년 만에 업데이트된 미국 뇌졸중 치료 가이드라인에서 AI 기반 영상 분석 솔루션이 권고 형태로 반영되며 의료 AI 기술의 임상적 유효성이 다시 한번 확인되었다"며 "이는 의료 AI가 단순한 보조 기술을 넘어 실제 임상 프로세스에 포함되는 표준 진단 도구로 자리잡고 있음을 의미한다"고 분석했다.고령화에 따른 환자 증가와 전문의 부족이라는 구조적 불균형은 의료 AI 확산의 배경으로 꼽힌다. 특히 뇌졸중은 발병 후 약 4시간30분의 골든타임 내 치료 여부가 생존율과 예후를 좌우하는 대표적 응급 질환이다. CT·CTA·MRI 등 영상 기반 진단에서 수분 단위의 판단 지연이 치료 결과에 직결되는 만큼 빠르고 정량화된 판독을 지원하는 AI 솔루션의 필요성이 커지고 있다.이 연구원은 "특히 의료 AI가 가장 빠르게 확산되고 있는 영역은 뇌졸중"이라며 "영상 기반 진단에서 수분 단위의 판단 지연이 치료 결과에 직접적인 영향을 미친다"고 설명했다.이 같은 흐름 속에서 제이엘케이는 응급, 진단, 시술, 입원, 예후 및 재활에 이르는 뇌졸중 치료 전 과정에 대응하는 12종의 AI 솔루션 포트폴리오를 구축했다. 경쟁사가 단일 솔루션에 집중하는 것과 달리, 전주기를 커버하는 풀라인업을 확보한 점이 차별화 요소다. 환자의 CT 및 MRI 영상 데이터를 기반으로 병변 위치와 중증도를 빠르게 정량 분석할 수 있으며 병원 내 PACS 및 EMR 시스템과 연동돼 추가적인 워크플로우 변경 없이 적용 가능하다.현재 제이엘케이 솔루션은 국내 210개 이상의 병원에 설치돼 있으며 일부 병원에서는 구독 기반 유료 모델이 적용되고 있다. 구독 병원 확대에 따른 반복 매출 기반 형성 가능성도 거론된다. 다양한 의료 영상 장비 환경에 대응 가능한 소프트웨어 구조와 모바일 기반 의료 AI 애플리케이션 역시 경쟁력으로 평가된다.이 연구원은 "이제는 그동안 준비해온 스토리가 실제 숫자로 전환되는 구간에 진입한다"고 강조했다. 국내에서는 의료 AI 비급여 항목이 기존 1개에서 3개로 확대됐다. 기존 혁신의료기술 항목은 1만8100원의 가격 상한이 존재했지만, 최근 신청된 신의료기술 비급여 항목은 가격 상한 제한이 없어 향후 건당 약 5만원 이상의 비급여 가격이 기대된다는 설명이다.해외에서도 실적 가시화가 진행 중이다. 미국에서는 기존 건당 과금 모델에서 구독 기반 모델로 비즈니스 구조 전환이 이뤄지고 있으며, 현재 약 23개 병원에서 초기 도입이 진행된 상태다. 경쟁사인 HeartFlow는 지난해 8월 나스닥 상장 이후 현재 약 3조원 규모의 시가총액으로 평가받고 있다. 미국 시장 점유율이 10% 미만임에도 연간 약 2400억원 수준의 매출을 기록하며 의료 AI 산업의 성장 잠재력을 보여줬다는 평가다.일본에서는 마루베니 그룹 의료기기 유통 자회사와 협력해 약 500개 병원을 대상으로 판매가 추진되고 있으며, 올해 약 150개 병원 설치가 예상된다.한양증권은 제이엘케이가 2026년 국내 60억원, 일본 50억원, 미국 25억원 등 총 135억원의 매출을 기록할 것으로 전망했다. 4분기 기준 분기 손익분기점 달성 가능성도 제기된다. 2분기 신의료기술 평가 유예 제도 결과, 일본 매출 본격화, 4분기 미국 CPT 보험 코드 확보 여부 등 주요 이벤트도 주가에 긍정적으로 작용할 요인으로 꼽힌다.이 연구원은 "지난 2년간 동사는 의료 AI에 관련된 인허가 및 레퍼런스 구축 단계에 머물러 있었다"며 "하지만 이제는 실제 매출과 손익 구조로 연결되는 구간에 진입하고 있다는 점에서 2026년은 동사에게 중요한 변곡점이 될 것"이라고 내다봤다.', NULL, '아시아경제', 'https://n.news.naver.com/mnews/article/277/0005729637', 'https://imgnews.pstatic.net/image/277/2026/03/05/0005729637_001_20260305094433726.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-05 09:44:02', 0, true, '2026-03-09 05:51:12.831471') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (736, 'SHD, 지난해 영업익 27억…흑자전환', 'SHD는 지난해 개별기준 영업이익이 27억3769만원으로 전년 대비 흑자전환했다고 2일 공시했다.같은 기간 매출은 1003억9778억원으로 5.8% 감소했고, 당기순이익은 19억5614억원으로 33.2% 줄어든 것으로 집계됐다.SHD는 실적 변동 주요 원인에 대해 "매출원가 변동에 따른 이익 증가"라고 설명했다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000078798', 'https://imgnews.pstatic.net/image/293/2026/02/02/0000078798_001_20260202160908974.png?type=w800', 'NEWS_ETC', NULL, '2026-02-02 16:09:08', 0, true, '2026-03-09 05:51:35.307194') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (737, 'SHD, 지난해 영업익 27억…흑자전환', '[헤럴드경제=증권부] SHD는 지난해 개별기준 영업이익이 27억3769만원으로 전년대비 흑자전환했다고 2일 공시했다.같은 기간 매출액은 1003억9778만원으로 5.82% 감소한 것으로 나타났다.당기순이익은 19억5614만원으로 33.19% 줄어든 것으로 집계됐다.', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002594616', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2026-02-02 14:29:08', 0, true, '2026-03-09 05:51:35.307194') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (738, '''좀비기업'' 더는 못 품어…강화된 ''상폐''에 경고등 켜진 종목은?', '올해부터 상장폐지 요건 강화코스피 5개·코스닥 21개, 관리 종목 지정 ''빨간불''/그래픽=임종철올해부터 코스피와 코스닥 기업의 상장폐지 시가총액 요건이 강화된다. 강화된 요건에 따라 관리 종목 지정 가능성이 높아진 종목들은 코스피 5개, 코스닥 21개 등 26개에 달한다. 금융투자업계에서는 재무상태가 부실한 좀비기업 퇴출이 필요하다고 목소리를 높여왔던만큼 이번 조치가 한국 증시 저평가(코리아 디스카운트) 해소에 도움이 될 것이라고 평가한다.7일 한국거래소에 따르면 코스피 상장 기업의 경우 시가총액 200억원에 미치지 못하는 날이 30거래일 연속 이어지면 관리종목에 지정된다. 이후 90거래일 중에서 연속 10거래일 또는 누적으로 30거래일 연속 시가총액 기준에 부합하지 못할 경우 상장폐지된다. 코스닥 상장 기업은 시가총액 기준이 150억원이라는 점만 제외하고 관리종목 지정과 상장폐지 절차는 코스피 상장 기업과 동일하게 적용받는다.그간 금융투자업계에서는 국내 증시에서 시가총액이 지나치게 작은 종목에 대한 퇴출장치가 필요하다는 지적이 꾸준히 나왔다. 지난해까지 적용되던 코스피 시가총액 상장폐지 요건인 50억원과 코스닥 40억원은 2009년 설정된 이후 10년 넘게 유지돼 현실성이 떨어진다는 비판도 뒤따랐다.시가총액이 100억원도 채 되지 않은 상장사는 대부분 실적 개선 가능성도 낮아 한국 증시 저평가 원인으로 꼽히기도 했다. 이런 지적이 이어지자 지난해 7월 거래소는 시가총액과 매출액 기준을 단계적으로 상향하도록 시행세칙을 개정했다.다만 우선주에 해당하는 상장 기업은 상장폐지 시가총액 기준이 20억원으로 유지되고 SPAC(기업인수목적회사·스펙)과 리츠도 이번에 강화된 시가총액 요건 적용 대상에서 제외된다.이를 고려하면 전날 기준 코스피 상장 기업 중에서는 시가총액 200억원에 미치지 못하는 기업은 KC그린홀딩스, 일정실업, 아센디오, 참엔지니어링, 에이엔피로 집계됐다. 한국주강, 윌비스, SHD는 시가총액 규정을 간신히 충족하고 있는 것으로 나타났다.IHQ와 KH 필룩스는 지난달 거래소로부터 상장폐지 결정 효력 정지 가처분 신청이 기각되며 정리매매에 돌입한 상태다.코스닥 상장 기업 중에서는 시가총액 150억원에 미치지 못하는 기업은 KH 건설, KH 미래물산, 장원테크 등 정리매매 절차를 밟고 있는 기업을 제외하고 더테크놀로지, 아이엠, 투비소프트, 아이톡시, 스타코링크, 한주에이알티, 삼영이엔씨, 디에이치엑스컴퍼니, 메디콕스, 서울전자통신, 올리패스, 드래곤플라이, 코이즈, 셀레스트라, 앤씨앤, 세니젠, 캐리, 비엘팜텍, 케이엠제약, 프로브잇, CS 21개 기업으로 집계됐다.이들 기업 가운데 더테크놀로지, 아이엠, 투비소프트 등 절반에 가까운 10개 기업은 관리종목으로 지정돼 현재 거래가 정지된 상태다.코스닥 시장에서는 이처럼 시가총액 기준을 충족하지 못하는 종목 상당수가 거래정지 상태에 놓여있는데 거래가 재개될 경우 거래정지 이전에 시가총액 기준을 밑돌았던 일수에 거래 재개 이후 기준을 충족하지 못한 일수가 합산된다. 이 기간이 누적으로 30거래일에 이르면 상장폐지 요건을 충족하게 된다.모바일 게임 관련 사업을 영위하는 코스닥 상장사 드래곤플라이는 지난해 3월 관리종목으로 지정돼 거래가 정지된 상태인데 향후 거래가 재개될 경우 이전에 시가총액이 150억원 미만이었던 5거래일이 합산된다.한편 지난달 30일 시가총액이 69억원에 그쳤던 디스플레이 사업을 영위하는 코스닥 상장사 인베니아는 올해 들어 4거래일 연속 상한가를 기록하며 시가총액이 200억원으로 급증해 상장폐지 요건에서 벗어나 투자자 이목을 끌고 있다.인베니아는 지난 2일 중국 디스플레이 기업에 132억원 규모 공급계약을 체결했다고 공시했다. 계약 규모는 2024년 매출액의 60.2%다. 인베니아는 구동범 대표이사 등이 지분 29.67%를 보유해 범LG가로 시장에서 인식된다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005301588', 'https://imgnews.pstatic.net/image/008/2026/01/07/0005301588_001_20260108041725290.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-07 15:26:00', 0, true, '2026-03-09 05:51:35.307194') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (739, '[서울데이터랩]금일 코스피 거래량 1위 삼성전자 거래대금 3조 8천억 돌파', '코스피 거래량 상위 종목들이 전반적으로 엇갈린 흐름을 보인다. 29일 한국거래소에 따르면, 삼성전자(005930)가 23,977,050주 이상 거래되며 코스피 종목 중 실시간 거래량 1위를 차지한다. 현재 주가는 162,600원으로, 거래대금은 3조 8,760억 원에 이른다. 시가총액 대비 거래대금 비율은 40.26%로, 매수와 매도세가 접전을 펼치는 가운데 많은 투자자들의 이목이 집중될 것으로 보인다. PER은 33.76, ROE는 9.03으로 수급과 재무 지표 모두에서 안정적인 모습을 보인다. 신성이엔지(011930)는 17,805,507주가 거래되며 거래량 2위를 기록하고 있으며, 현재 주가는 1,798원이다. 거래대금은 32,291백만원으로 시가총액 대비 거래대금 비율은 8.72%다. PER은 -30.47, ROE는 -5.85로 나타난다.한국ANKOR유전(152550)은 16,648,061주가 거래되며 거래량 3위를 기록하고 있다. 현재 주가는 211원으로, 등락률은 3.43%를 보인다. 흥아해운(003280)은 12,663,076주가 거래되며 3.05% 상승, 거래량 4위를 차지했다. SK증권(001510)은 8,438,720주가 거래되며 6.83% 상승했다. 두산에너빌리티(034020)는 8,000,190주 거래와 함께 2.17% 상승 중이다. 미래에셋증권(006800)은 7,331,882주가 거래되며 7.90% 상승 중이다. 윌비스(008600)는 6,626,217주가 거래되며 -2.91% 하락했고, KG모빌리티(003620)는 6,600,248주가 거래되며 -2.01% 하락 중이다. 한미반도체(042700)는 5,682,597주 거래와 함께 14.29% 급등하고 있다.한편 거래량 상위 20위권 종목들은 한화투자증권(003530) ▲3.45%, 형지엘리트(093240) ▲1.09%, 보락(002760) ▼-1.64%, 에이프로젠(007460) ▲1.83%, SK하이닉스(000660) ▲3.09%, 알루코(001780) ▲2.92%, 삼성중공업(010140) ▼-1.99%, 한온시스템(018880) ▼-1.47%, LG디스플레이(034220) ▼-3.30%, 삼성전자우(005935) ▲0.34% 등의 성적을 기록했다.주목할 만한 종목으로는 한미반도체와 미래에셋증권이 있다. 한미반도체는 14.29% 급등하며 거래대금이 1,136,344백만원에 달한다. 시가총액 대비 거래대금 비율은 57.32%로, 높은 투자 심리를 반영한다. 미래에셋증권 역시 7.90% 상승하며 거래대금이 265,173백만원에 달한다. 반면, 윌비스와 KG모빌리티는 각각 -2.91%, -2.01% 하락하며 주춤하고 있다. 윌비스는 거래대금이 2,522백만원에 그쳤다.전체적으로 코스피 시장은 일부 종목에서 강한 매수세가 유입되며 상승세를 보이는 반면, 다른 종목들은 하락세를 보이며 혼조세를 이어가고 있다. 투자자들은 종목별로 분명한 매수·매도 전략을 세워야 할 것으로 보인다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003612756', 'https://imgnews.pstatic.net/image/081/2026/01/29/0003612756_001_20260129143118152.png?type=w800', 'NEWS_ETC', NULL, '2026-01-29 14:31:18', 0, true, '2026-03-09 05:51:42.211475') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (774, '정치 연줄보다 ‘사돈 네트워크’…달라진 재벌가 혼맥 지도', '[비즈니스 포커스]최태원 SK그룹 회장 차녀인 최민정씨 웨딩 화보. 최씨는 중국계 미국인 사업가 케빈 리우 황과 2024년 결혼했다. 사진=웨딩업체 ''zola'' 홈페이지 캡처재계 혼맥 지형에 변화가 나타나고 있다. 과거 대기업 총수 일가는 정·관계 중심의 정략결혼이 일반적이었지만 2000년을 기점으로 정치권·관료 집안과의 혼맥 비중은 급격히 줄고 일반인과의 결합이 늘고 있다.CEO스코어 분석에 따르면 2000년 이전 총수 일가 결혼 중 24.2%가 정치·관계 집안과 이뤄졌으나 2000년 이후에는 7.4%로 감소했다. 세대가 내려갈수록 정·관계 혼맥 비율은 더 낮아져 2세대 24.1%, 3세대 14.1%, 4~5세대는 6.9%에 불과하다.이는 과거 정략결혼이 사업 확장 수단으로 작용했지만 최근에는 감시와 규제 리스크가 커진 데 따른 결과로 해석된다.2000년 이후 정·관계 혼맥 급감반면 재계 내부 결혼은 2000년 이전 39.2%에서 이후 48.0%로 늘었고 세대별로도 2세대 34.5%, 3세대 47.9%, 4~5세대 46.5%로 증가하며 재계 네트워크가 강화되는 모습이다. 일반인과의 결혼도 4~5세대에서 37.2%로 크게 늘었다.과거 창업·2세대에서는 결혼이 사업 확장과 인맥 구축 수단이었지만 3~4세대는 ‘정치권’에서 ‘재계 내부’로, 나아가 ‘일반인·연예인’으로 중심축이 이동하고 있다. 최근 오너 자녀의 결혼은 권력 기반 연줄보다 기업 생태계 내부 네트워크와 개인 선택에 의해 결정되는 경향이 뚜렷하다.LS·LG·GS 등 주요 그룹은 여전히 재계 혼맥의 중심축 역할을 하고 있다. LS는 두산, 현대자동차, OCI, BGF, 삼표, 사조, KISCO홀딩스(범동국제강) 등 7개 그룹과 혼맥을 맺고 있다. 특정 재벌가에 한정되지 않고 다양한 대기업 가문과 연계된 광범위한 혼맥 네트워크를 형성하고 있다.구동휘 LS MnM 사장(구자열 LS 이사회 의장 장남)은 박정원 두산그룹 회장의 장녀 박상민 씨와 결혼했다. 구윤희 씨(구자명 LS MnM 회장의 장녀)는 정도원 삼표그룹 회장의 장남 정대현 씨와 혼인했다.구희나 씨(구자용 E1 회장의 장녀)는 홍석조 BGF그룹 회장의 장남 홍정국 BGF 부회장과 결혼했다. 구은희 씨(구자엽 LS전선 회장의 장녀)는 정일선 현대비앤지스틸 대표(범현대가)와 부부 관계다. 구은아 씨(구자열 LS 의장의 장녀)는 SGC에너지 이우성 사장과 결혼했으며 이우성 사장은 OCI 창업주 일가인 이복영 SGC그룹 회장의 장남이다.대기업집단 혼맥 지도. 그래픽=박명규 기자LS·LG·GS 중심 ‘사돈망’ 확대LG그룹도 DL, 삼성, GS, 두산, 보락그룹 등과 탄탄한 혼맥을 잇고 있다. 허만정 GS 창업주의 3남 허준구 명예회장은 구인회 창업주의 조카 구위숙 여사와 결혼해 LG와 GS를 연결했다.구자학 아워홈 회장은 삼성 창업주 이병철의 차녀 이숙희 씨와 결혼해 삼성, LG, 한진, 롯데를 잇는 복합 사돈망의 중심 역할을 했다. 구철회 창업 고문의 딸 구선희 씨는 두산가 박용훈 전 두산건설 부회장과 결혼해 LG와 두산을 사돈으로 연결했다.또 구광모 LG그룹 회장은 중소기업 보락 가문과의 연애 결혼으로 혼맥을 형성했다. 이해욱 DL그룹 회장은 구자경 LG 명예회장의 외손녀 김선혜 씨와 결혼해 LG 오너 일가와 긴밀한 연결을 유지 중이다.GS그룹은 LG, 삼표, 중앙, 태광 등과 사돈 관계를 맺고 있으며 이 네트워크는 재계는 물론 정·관계, 언론계까지 광범위하게 확장된 화려한 통혼 네트워크를 자랑한다. 허세홍 GS칼텍스 부회장은 부방그룹 이동건 회장의 차녀 이희정 씨와 결혼해 두 딸을 두고 있다.허윤홍 GS건설 대표는 미국 MBA 유학 중 만난 중소기업 오너 딸과 결혼했다. 허준홍 삼양통상 사장은 유유제약 유특한 창업주(유한양행 유일한 창업주 동생)의 증손녀이자 유승지 홈텍스타일코리아 회장 딸인 유재상 씨와 혼인했다.허광수 삼양인터내셔날 회장은 언론계와 사돈을 맺었으며 그의 장남 허서홍 GS리테일 대표는 중앙홀딩스 홍석현 회장 장녀와 결혼했다. 허광수 회장의 장녀 허유정 씨는 조선일보 방준오 사장과 결혼했다.태광그룹과도 깊은 혼맥이 있는데 GS 창업주 허만정 회장의 8남 허승조 전 GS리테일 부회장은 태광그룹 창업주 이임용 회장 장녀 이경훈 씨와 결혼했다. 허승조 전 부회장은 태광그룹 고문으로도 활동해 왔다.2017년 6월 서울 중구 명동성당에서 열린 HD현대 대주주 정몽준 아산재단 이사장의 장녀 정남이 아산나눔재단 상임이사와 서승범 유봉 대표의 결혼식에서 가족 및 하객들이 기념사진을 찍고 있다. 사진=연합뉴스동국제강, 동방·태광·LS와 연결…사돈 네트워크 교차점동국제강그룹은 창업주의 대가족을 중심으로 견고한 혼맥 네트워크를 구축해왔다. 창업주 장경호 회장은 추명순 여사와 6남 5녀를 두었으며 3남 장상태 회장이 경영권을 승계했다. 그룹은 동국산업, 한국철강, 조선선재 등으로 분리됐으나 각 계열사는 독자적인 경영을 이어가고 있다.동국제강은 태광, 동방, LS그룹과 긴밀한 혼맥 관계를 형성해왔다. 장상준 전 회장 막내딸 장옥빈 씨는 태광그룹 창업주 이임용 회장 아들 이영진 부회장과 결혼했고, 장상돈 한국철강 회장 차남 장세홍 KISCO홀딩스 대표는 금호그룹 박정구 회장 딸과, 동국산업 장상건 회장 아들 장세희 전 동국산업 부회장은 동방그룹 창업주 김용대 회장 딸과 각각 결혼했다.3세대 경영자 장세주 회장은 상명대 교수 남희정 씨와 결혼했고 그의 아들 장승익 씨는 조윤선 전 문체부 장관의 딸과 혼인해 정·관계 접점을 넓혔다.장세욱 부회장은 산업은행 총재 등을 역임한 김흥기 씨의 딸과 결혼했다. 장경호 창업주의 손녀 장인영 씨는 LS그룹 구자은 회장과 결혼해 철강과 전기·전자 업계를 잇는 상징적 혼맥을 완성했다.3·4세, 가치관·경력 공유 배우자 선호…연애결혼↑최근 3~4세대 오너들의 결혼 사례를 보면 연애결혼이 뚜렷하다. 김동관 한화그룹 부회장은 2살 연하 한화 입사 동기와 연애결혼했고 정기선 HD현대 회장은 띠동갑, 연세대 동문인 교육자 집안 출신 정현선 씨와 결혼식을 올렸다. 최태원 SK그룹 회장 자녀들도 일반인, 해외 사업가와 각각 혼인했다.최태원 회장의 장녀 최윤정 SK바이오팜 부사장은 2017년 당시 회사원이던 윤도연 씨와 결혼했고 차녀 최민정 씨는 중국계 미국인 사업가인 케빈 리우 황 씨와 2024년 혼인했다. 황 씨는 미군 특수부대에서 소령으로 복무 중인 것으로 알려졌다.김홍국 하림그룹 회장 장남 김준영 팬오션 책임은 미국 하버드대 출신 여성과 결혼하는 등 글로벌 인재와의 연애결혼 사례도 늘어난다. 또 아나운서, 연예인, 프로골퍼와의 결합도 증가한다.CJ 3세 이선호 미래기획그룹장은 아나운서 이다희 씨와 혼인했고 정태영 현대카드 부회장 자녀 정준 씨는 세계적 골퍼 리디아 고와 결혼했다. 김대헌 호반건설 대표는 전 SBS 아나운서 김민형 씨와 결혼했고 두산 4세 박서원 두산매거진 대표는 전 JTBC 아나운서 조수애 씨와 혼인한 바 있다. 김동선 한화갤러리아 부사장은 종합편성채널 기자 출신인 H 씨와 결혼했다.혼맥, 단순 혈연 넘어 전략적 도구로재계 사돈 네트워크는 여전히 재계의 보이지 않는 연결망을 형성하는 핵심 수단으로 작동한다. 혼맥은 단순한 혈연을 넘어 사업 포트폴리오, 지분, 경영권 안정성 등과 자연스럽게 연계돼 있다.재벌 혼맥의 변화는 정치·사회·경영환경이 동시에 바뀐 결과라는 분석이 제기된다. 먼저 정치적 리스크가 커지면서 정치권과의 혼맥이 오히려 부담으로 인식되는 흐름이 강해졌다. 동시에 유학·글로벌 경험이 많은 3·4세 오너들은 가치관·라이프스타일을 공유하는 배우자를 선호하며 기존 재벌가식 정략혼에서 벗어난 선택을 하고 있다는 평가다.그럼에도 LS·GS·LG·동국제강 등 혼맥 중심축이 되는 그룹은 사돈 네트워크를 통해 여전히 내부 협업과 자본·정보 흐름을 관리하는 전략적 기능을 유지한다. 이를 두고 권력 중심 혼맥의 축소가 아니라 내부 네트워크 중심으로 재편된 ‘전략의 진화’로 보는 시각도 있다.재계 관계자는 “3·4세대의 결혼에서 가문 네트워크 확장을 통한 사업적 목적보다 개인의 선택이 중시되는 것은 단순 트렌드가 아니라 기업 내부 자본과 네트워크를 통한 지배구조 안정화 전략이 그만큼 성숙했다는 것을 의미한다”며 “정치권과의 연줄은 줄었으나 그룹 간 내부 네트워크는 여전히 강력히 유지되고 있어 단순한 탈정략화라기보다는 ‘전략의 진화’로 해석해야 한다”고 평가했다.', NULL, '한경비즈니스', 'https://n.news.naver.com/mnews/article/050/0000098922', 'https://imgnews.pstatic.net/image/050/2025/11/27/0000098922_001_20251127104613682.jpg?type=w800', 'NEWS_ETC', NULL, '2025-11-27 06:22:12', 0, true, '2026-03-09 05:53:13.811617') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (775, '금감원, 상장사 내부감사기구 첫 간담회…"경영진 배제 회의 분기 1회는 해야"', '"회계부정 1차 방어선" 역할 강조김은순(왼쪽부터) 금융감독원 회계감독국장, 진성훈 코스닥협회 그룹장, 오명전 대성홀딩스 감사위원장, 안희준 아모레퍼시픽 감사위원장, 김경 서부T&D 감사위원장, 김준철 유한양행 감사위원장, 윤정숙 금융감독원 전문심의위원, 한덕철 GS 감사위원장, 김장래 심텍 감사, 김동회 KISCO홀딩스 감사위원장, 유상열 에스에프에이 감사위원장, 전성한 세나테크놀로지 감사위원, 강경진 상장회사협의회 본부장이 26일 서울 마포구 상장회사 회관에서 내부감사기구 대상 간담회를 열고 기념사진을 촬영하고 있다. 사진 제공=금융감독원[서울경제]금융감독원이 상장사 내부감사기구를 대상으로 간담회를 열고 ‘회계부정의 1차 방어선 기능’을 강조했다.금감원은 26일 서울 마포구 상장회사회관에서 상장회사 9곳의 감사위원·감사 등과 간담회를 열고 자본시장 투명성과 신뢰성 제고를 위한 내부감사기구의 역할을 논의했다. 금감원의 상장사 내부감사기구 대상 간담회는 이번이 처음이다. 최근 신외감법 도입과 내부회계관리제도 고도화로 내부감사기구의 책임과 권한이 커지면서 감독당국과의 직접 소통 필요성이 높아졌다는 배경에서다.윤정숙 금감원 회계전문심의위원은 신외감법 도입으로 외부감사인 선정 권한이 경영진에서 내부감사기구로 이관된 점을 언급하며 비용 절감 대신 감사품질 중심의 외부감사인 선정을 해달라고 주문했다. 외부감사인과의 유기적인 협력 체계 중요성도 강조했다.윤 위원은 “복잡하고 교묘한 회계분식을 방지하기 위해 감사계획-실시-종료 등 전 과정에서 내·외부감사인 간의 긴밀한 협업이 중요하다”고 말했다. 이어 “‘경영진 배제’ 회의를 분기당 최소 1회 개최하되, 대면 회의를 통해 양방향으로 정보를 교류하는 등 실질적인 소통이 필요하다"고 덧붙였다.금감원은 회계부정 발견 시 자체 감사나 외부전문가 활용 조사를 통해 빠르게 시정하고 필요시 조사·조치 결과를 금융당국 및 감사인에게 제출해달라고도 요청했다.간담회 참석자들은 변화되는 규제환경 하에서 내부감사기구의 역할과 책임이 확대되고 있는 바 회사의 내부통제와 지배 구조 체계를 보다 실효성 있게 운영하도록 지속 노력해 기업문화와 실무 관행을 함께 점검해 나가겠다는 의지를 표명했다. 그러면서 내부감사기구의 회사·감사인에 대한 소통 및 정보 접근성 강화, 내부감사 전문성 교육 확대 등 개선 의견을 제시했다. 이날 간담회에 참석한 상장사는 대성홀딩스, 아모레퍼시픽, 서부T&D, 유한양행, GS, 심텍, KISCO홀딩스, 에스에프에이, 세나테크놀로지 등이다.', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004560416', 'https://imgnews.pstatic.net/image/011/2025/11/26/0004560416_001_20251126165016190.jpg?type=w800', 'NEWS_ETC', NULL, '2025-11-26 16:50:16', 0, true, '2026-03-09 05:53:13.811617') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (873, '기업 공시 [3월 5일]', '<코스피 시장>▲포스코퓨처엠(003670)=퓨처머티리얼에 3579억 원 출자▲HS화성=313억 원 규모 케냐 나이로비 BRT 도로공사 수주 ▲HD한국조선해양(009540)=1조 4872억 규모 LNG 운반선 4척 수주 ▲코리안리(003690)=지난해 영업이익 4억 7093만 원으로 전년 대비 16.2% 증가 ▲현금배당결정=한신기계(011700)1주당 보통주 20원,문배철강(008420)50원,NI스틸(008260)100원,동부건설(005960)300원·우선주 350원<코스닥 시장>▲한양이엔지(045100)=자기주식 248억 원 규모 자사주 78만 3018주 소각 ▲서산(079650)=지난해 영업이익 -33억 3055만 원으로 전년 대비 33.51% 감소 ▲현금배당결정=프로텍(053610)1주당 400원,피엔케이피부임상연구센타(347740)50원', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004596148', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_CONSTRUCT', NULL, '2026-03-05 16:44:17', 0, true, '2026-03-09 06:10:47.558980') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (740, '[서울데이터랩]‘KIWOOM 코스닥150선물레버리지’ 29.18% 폭등…실시간 상승률 1위', '29일 오전 9시 10분 ##KIWOOM 코스닥150선물레버리지(291630)_0##가 등락률 +29.18%로 폭등하며 상승률 1위를 차지했다. KIWOOM 코스닥150선물레버리지는 개장 직후 5분간 2만 9008주가 거래되었으며 주가는 공모가 대비 2845원 오른 1만 2595원이다.이어 상승률 2위 SNT에너지(100840)는 현재가 4만 6450원으로 주가가 15.98% 급등하고 있다. 상승률 3위 한미반도체(042700)는 현재 20만 4500원으로 12.36% 급등하며 긍정적인 모습을 보이고 있다. 상승률 4위 사조산업(007160)은 10.52% 상승하며 6만 6200원에 거래되고 있다. 상승률 5위 코아스(071950)는 8.84%의 상승세를 타고 5170원에 거래되고 있다.6위 SK(034730)는 현재가 32만 6500원으로 6.87% 상승 중이다. 7위 TYM(002900)은 현재가 7260원으로 5.07% 상승 중이다. 8위 자화전자(033240)는 현재가 2만 4000원으로 5.03% 상승 중이다. 9위 차AI헬스케어(025620)는 현재가 1만 1210원으로 4.96% 상승 중이다. 10위 SK스퀘어(402340)는 현재가 52만 9000원으로 4.96% 상승 중이다.이밖에도 경동인베스트(012320) ▲4.76%, 사조씨푸드(014710) ▲4.60%, SK이터닉스(475150) ▲4.49%, 우진(105840) ▲4.40%, SK하이닉스(000660) ▲4.28%, 알루코(001780) ▲4.27%, 성문전자(014910) ▲4.06%, SK우(03473K) ▲4.04%, KIWOOM 코스닥150(316670) ▲3.94%, KIWOOM K-반도체북미공급망(488210) ▲3.92% 등을 기록하며 시장에서 활발히 거래되고 있다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003612660', 'https://imgnews.pstatic.net/image/081/2026/01/29/0003612660_001_20260129094516795.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-29 09:45:16', 0, true, '2026-03-09 05:51:42.211475') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (741, '[서울데이터랩]금일 코스피 거래량 1위 한화갤러리아 거래대금 945억 돌파', '코스피 거래량 상위 종목들이 전반적으로 엇갈린 흐름을 보인다.19일 한국거래소에 따르면, 한화갤러리아(452260)가 42,924,509주 이상 거래되며 코스피 종목 중 실시간 거래량 1위를 차지한다. 현재 주가는 2,290원이며, 시가총액은 4,439억원이다. 거래대금은 94,551백만원으로 시가총액의 2%를 넘는 자금이 유입되고 있다. PER -12.72, ROE -2.31로, 재무지표는 다소 부진하지만 높은 거래량이 주목받고 있다. 서원(021050)은 21.64%의 급등세를 보이며 22,829,910주가 거래되고 있으며, 현재 주가는 1,349원이다. 시가총액은 640억원으로, 거래대금은 31,712백만원으로 시가총액 대비 높은 거래대금 비율을 보인다. PER -6.10, ROE 35.82로 재무 상태는 양호하다.삼성전자(005930)는 14,103,134주의 거래량을 기록하며 현재가 148,500원으로 -0.27% 하락하고 있다. 웰바이오텍(010600)은 12,502,218주의 거래량을 보이며 5.88% 하락한 모습을 보인다. 한국무브넥스(010100)는 상한가를 기록하며 12,093,306주가 거래되고 있다. 삼성중공업(010140)은 9,294,654주가 거래되며 5.88% 상승 중이다. 대우건설(047040)과 SJG세종(033530)은 각각 8,522,182주, 7,407,880주가 거래되며 소폭 상승 중이다. 알루코(001780)는 6,383,464주가 거래되고 있으며 두산에너빌리티(034020)는 6,010,202주가 거래되며 보합세를 보이고 있다.한편 거래량 상위 20위권 종목들은 DYP(092780) ▲8.24%, SK증권(001510) ▲1.76%, 대창(012800) ▲4.04%, 두산로보틱스(454910) ▲18.03%, 현대약품(004310) ▲2.43%, 현대차(005380) ▲15.50%, 한온시스템(018880) ▲0.32%, 한화생명(088350) ▲2.17%, 한화갤러리아우(45226K) ▲28.56%, 포스코DX(022100) ▼1.43% 등의 성적을 기록한다.주목할 만한 종목으로는 급등세를 보이는 서원과 SJG세종이 있다. 서원은 거래량과 거래대금에서 큰 폭의 상승을 보이며 시가총액 대비 거래대금 비율이 높아 투자자들의 관심을 끌고 있다. 반면, 웰바이오텍과 포스코DX는 하락세를 보이며 거래량과 거래대금이 시가총액 대비 다소 낮은 수준이다.전체적으로 코스피 시장은 긍정적인 흐름과 부정적인 흐름이 혼재되어 있으며, 일부 종목들은 급등세를 보이며 시장의 이목을 집중시키고 있다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003609810', 'https://imgnews.pstatic.net/image/081/2026/01/19/0003609810_001_20260119131522180.png?type=w800', 'NEWS_ETC', NULL, '2026-01-19 13:15:22', 0, true, '2026-03-09 05:51:42.211475') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (742, '알루코 그룹, 미국 AI기반 알루미늄 복합단지 구축 속도...내년 3월 양산', '박도봉 알루코 회장(가운데)이 17일 오전 10시(현지시간·한국시간 18일 오후 1시) 미국 테네시주 로더데일 카운티 현지 공장에서 맥 호터 주정부 부지사, 게인스 모리스 로더데일 카운티 시장 등이 참석한 가운데 기공식을 하고 기념사진을 찍고 있다./사진=알루코국내 대표 알루미늄 전문기업 알루코 그룹은 미국 테네시주 홀스 복합단지에 대형 알루미늄 생산 단지의 기공식을 개최하고 당초 계획보다 앞당긴 내년 3월 양산에 돌입할 계획이라고 19일 밝혔다. 미국 정부가 철강·알루미늄에 품목관세 50%와 상호관세 15%를 부과한 정책을 위기가 아닌 기회로 판단하고, 미국 내 생산확대에 속도를 내고 있다홀스 복합단지는 잭슨(Jackson)에 위치한 2000 평 규모의 전기차 배터리용 알루미늄 부품 공장에 이은 알루코 그룹의 두 번째 미국 생산 거점으로, 약 10만 평 규모의 대형 복합 생산시설이다. 베트남 공장에서 적용중인 AI(인공지능) 시스템을 도입하여 연간 15만6000 톤의 생산능력을 갖춘 AI 기반 무인 스마트팩토리로 운영되며, 소재-용해-주조-압출-가공-조립 등 전 공정을 자동화해 One Stop 생산 기지로 도약할 예정이다.이곳에서는 알루미늄 소재 및 부품 생산에 필요한 전 공정을 일괄 수행하게 되며, 알루코 그룹 산하 그린리사이클테크놀로지 아메리카(GRT), 알루머티리얼스 아메리카(AMA), 현대알루미늄 아메리카(HDAA) 등 3개 법인이 입주해 북미 공급망을 구축한다. 이는 한국·베트남과 함께 삼각 축으로 글로벌 생산 거점 역할을 담당할 예정이다.AMA는 GRT의 친환경 빌렛을 기반으로 압출·피막·가공·조립까지 일관된 생산체계를 갖추고, 전기차 배터리 케이스·태양광 모듈 프레임·TV·생활가전·자동차 부품 등을 미국산으로 안정적으로 공급한다. GRT는 알루코 그룹의 독자적인 AI 기반 알루미늄 재활용 기술을 바탕으로 친환경 빌렛을 생산하는 주조 공장으로 건설되며, 탄소 저감과 자원 순환이라는 시대적 요구에 부응하는 핵심 사업을 전개한다.HDAA는 한국·베트남·대만에서 축적한 시공 역량을 바탕으로 초고층 커튼월, 방화창, 알폼, 창호재 등을 앞세워 북미 건축 및 건자재 시장을 공략한다. 특히 미국 알루미늄 윈도우 시장과 커튼월 시장에 본격 진출할 계획이다.미국 알루미늄 압출재 시장은 2024년 기준 약 220만 톤 규모이고, 2033년까지 연평균 7.5% 성장할 것으로 전망된다(출처: Precedence Research 2024). 알루코 그룹은 친환경 알루미늄 압출재를 앞세워 자동차 부품, 전기차 배터리 케이스, 태양광 발전 모듈, TV·생활가전, 커튼월 및 건축 자재 등 다양한 분양에서 공급망을 구축해 향후 5년 내 북미 시장 점유율을 확대할 계획이다.알루코 그룹 관계자는 "한국·베트남·미국을 잇는 그룹 전체의 시너지 효과를 기반으로 북미 산업 생태계의 핵심 플레이어로 자리잡을 것"이라며 "AI 기반 제조 혁신을 통해 기존 B2B 시장(전기차 배터리 부품, 태양광 모듈 프레임, TV·생활가전, 자동차 부품, 커튼월)에 독자적 영역을 확보하고, 나아가 B2C 시장(알루미늄 윈도우·건자재)과 특수 방산·우주항공 부품 등으로 품목을 다각화할 것"이라고 말했다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005294405', 'https://imgnews.pstatic.net/image/008/2025/12/19/0005294405_001_20251219160212779.jpg?type=w800', 'NEWS_ETC', NULL, '2025-12-19 16:01:13', 0, true, '2026-03-09 05:51:42.211475') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (743, '알루코, 미국 AI 알루미늄 복합단지 구축… 조기 양산 본격화', '테네시주 홀스 10만평 자가공장, 내년 3월 전 공정 양산 돌입알루코 그룹의 미국 테네시주 홀스 복합단지 모습. 알루코 제공대전에 본사를 둔 알루미늄 전문기업 알루코 그룹이 미국 내 알루미늄 생산 확대에 속도를 내고 있다.알루코 그룹은 현지 기업들의 급증하는 미국산 알루미늄 수요에 대응하기 위해 내년 3월부터 미국 테네시주 홀스 복합단지에서 알루미늄 양산에 조기 돌입한다고 18일 밝혔다.현재 알루코 그룹의 테네시주 홀스 복합단지에선 내년 3월 전 공정 가동을 목표로 용해부터 압축·가공에 이르는 대형 알루미늄 생산장비 반입·설치 작업이 진행 중이다.홀스 복합단지는 알루코 그룹의 2번째 미국 생산 거점으로, 약 10만 평 규모의 알루미늄 소재 및 부품 생산에 필요한 전 과정을 수행하는 대형 복합 생산시설이다.단지엔 알루코 그룹 산하 그린리사이클테크놀로지 아메리카(GRT)와 알루머티리얼스 아메리카(AMA), 현대알루미늄 아메리카(HDAA) 등 3개 법인이 입주해 북미 공급망을 구축하며, 한국·베트남과 함께 삼각 축으로 글로벌 생산 거점 역할을 담당할 예정이다.특히 복합단지는 인공지능(AI) 시스템을 도입해 연간 15.6만 톤(t)의 생산 능력을 갖춘 AI 기반 무인 스마트팩토리로 운영된다. 알루코 그룹은 AI 생산 알고리즘을 기존 R&D 데이터와 접목해 전 공정을 자동화하는 기지로 활용한다는 방침이다.또 미국 정부의 인플레이션감축법(IRA) 정책 프레임워크에 따라 현지 생산 비율 요건을 충족하고, 알루미늄 관세를 회피함으로써 미국 내 핵심 경쟁력을 확보할 것이라고 알루코는 설명했다.알루코 그룹 관계자는 "한국·베트남·미국을 잇는 그룹 전체의 시너지 효과를 기반으로 북미 산업 생태계의 핵심 플레이어로 자리 잡을 것"이라고 말했다.', NULL, '대전일보', 'https://n.news.naver.com/mnews/article/656/0000159995', 'https://imgnews.pstatic.net/image/656/2025/12/18/0000159995_001_20251218185420084.jpg?type=w800', 'NEWS_ETC', NULL, '2025-12-18 18:54:20', 0, true, '2026-03-09 05:51:42.211475') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (744, '윤진식 무협 회장 “테네시주와 공급망 협력 강화”', '빌 리 주지사 초청 무역업계 간담회리 지사 “첨단 제조 파트너십 지원”한국무역협회(회장 윤진식·사진)는 23일 서울 강남구 삼성동 그랜드인터컨티넨탈 호텔에서 빌 리 미국 테네시 주지사 초청 무역업계 간담회를 개최했다고 24일 밝혔다.간담회에는 윤진식 회장을 비롯해 오석송 메타바이오메드 회장, 송호근 와이지-원 회장, 최명배 엑시콘 회장, 김동욱 현대자동차 부사장 등 무역협회 회장단과 한미경제협의회(KUSEC) 회원사, 테네시주에 진출했거나 진출을 검토 중인 기업 관계자 등 25명이 참석했다. 테네시주 측에서는 빌 리 주지사, 스튜어트 맥호터 부지사 겸 상무장관, 앨런 보든 부상무장관 등 사절단원 10명이 참석했다.윤 회장은 환영사에서 “글로벌 완성차의 핵심 생산 거점이자 북미 전기차 전환을 선도하는 테네시주와 우리 기업 간 협력을 통해 한미 양국의 첨단 산업 분야 공급망 협력이 한층 더 강화되기를 희망한다”며 “원활한 현지 진출을 위해 우리 기술자의 비자 애로에 주정부 차원의 각별한 관심과 지원을 부탁드린다”고 강조했다.빌 리 주지사는 “한국은 배터리 소재·셀, 완성차 등 첨단 제조 분야에서 테네시주의 핵심 경제 파트너”라며 “한국 기업이 테네시주의 경제 성장과 일자리 창출에 크게 기여해온 만큼 주정부도 경쟁력 있는 인력 확보와 비즈니스 친화적 환경 조성, 안정적인 에너지 공급 등을 위한 지원을 아끼지 않겠다”고 화답했다.KUSEC은 한미 경제 협력 증진을 위한 무역 투자, 기술 협력, 문화 및 학술 교류를 목적으로 1973년 한국무역협회 등 경제 3단체가 설립한 최초의 국별 경제협력 상설기구다. 무역협회가 사무국 역할을 수행하고 있다.테네시주는 미국 내에서도 손꼽히는 수준의 제조업 역량을 가지고 있는 곳으로 LG전자, 효성중공업, 한국타이어 등 우리 기업들이 활발히 진출해 있다. 여기에 닛산, 제너럴모터스(GM), 폭스바겐 등 3대 완성차 공장을 중심으로 주 전역에 탄탄한 자동차 밸류체인도 갖추고 있다는 평가다.최근에는 포드·SK온 합작 배터리 공장과 GM·LG에너지솔루션 합작 배터리 공장 설립이 추진 중이며, LG화학의 양극재 공장 건설도 진행되며 관련 국내 중소·중견기업의 진출도 잇따르고 있다. 테네시주 정부에 따르면 지난해 누적 기준 우리 기업 24개사가 약 59억달러(약 8조4700억원)를 투자해 4200여개의 일자리를 창출했다.한편 이날 행사에는 테네시주 진출 기업 중 덕산일렉테라(2차전지), 알루코(알루미늄), 유니테크(산업용 접착제), SL(자동차부품) 등이 참석해 주정부 주요 인사와 직접 소통하는 시간을 가졌다.김성우 기자', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002546814', 'https://imgnews.pstatic.net/image/016/2025/10/24/0002546814_001_20251024111911786.jpg?type=w800', 'NEWS_ETC', NULL, '2025-10-24 11:19:11', 0, true, '2026-03-09 05:51:42.211475') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (780, '코스닥 바이오 자금 조달 잇달아…VC·최대주주 참여', '인벤티지랩 985억원·지니너스 200억원 유치코오롱티슈진, 최대주주서 600억원 확보지니너스와 인벤티지랩 등 코스닥 바이오 기업들이 연구개발(R&D)과 생산 시설 투자를 위해 유상증자 방식 등으로 대규모 자금 조달에 나서고 있다. 이들 기업 투자에 일반 투자자 외 벤처캐피탈(VC)이 대규모로 참여해 눈길을 끈다.지니너스, 신약 타겟 발굴 위해 200억원 확보9일 금융감독원에 따르면 지니너스는 약 200억원 규모의 제3자배정 유상증자를 결정했다. 지난해 5월 한국투자파트너스 등으로부터 100억원을 조달한 데 이어 10개월 만에 200억원을 추가로 확보했다.이번 유상증자에는 KB인베스트먼트의 ''케이비 디지털 플랫폼 펀드''를 비롯해 컴퍼니케이파트너스가 운용하는 펀드 등 벤처캐피탈이 주요 투자자로 참여했다.지니너스는 확보한 자금을 멀티오믹스 데이터 기반의 신약 타겟 발굴 등 연구개발(R&D) 비용으로 투입할 예정이다.  최근 관련 연구를 위한 핵심 인력을 확보하는 등 신약 연구에 집중하고 있다.인벤티지랩, 메자닌·우선주로 총 985억원 조달인벤티지랩은 전환사채(CB), 신주인수권부사채(BW), 제3자배정 유상증자를 동시에 진행하며 총 985억원에 달하는 대규모 자금을 확보한다.구체적으로는 372억5000만원 규모의 제4회차 사모 전환사채와 85억원 규모의 제5회차 사모 신주인수권부사채를 발행한다. 이와 함께 다수의 투자조합과 펀드를 대상으로 약 527억5000만원 규모의 기명식 전환우선주(CPS)를 발행하는 제3자배정 유상증자도 결정했다.미래에셋벤처투자, 아주IB투자, 스톤브릿지벤처스 등 다수의 벤처캐피탈이 투자에 참여한 것이 특징이다. 인벤티지랩은 확보한 자금을 장기지속형 주사제 플랫폼 및 바이오의약품 피하주사제형 플랫폼 연구와 GMP 공장 시설 투자 등에 활용할 계획이다.코오롱티슈진, 최대주주 대상 600억원 유상증자코오롱티슈진은 최대주주인 (주)코오롱을 대상으로 약 600억원 규모의 제3자배정 유상증자를 진행한다. 발행되는 신주는 보통주 11만8040주이며, 신주 발행가액은 1주당 50만8325원이다.조달된 자금은 미국 식품의약국(FDA) 품목허가 및 골관절염 세포유전자치료제 ''TG-C''의 상업화 준비를 위한 운영자금으로 사용될 계획이다.  코오롱티슈진은 지난해에도 TG-C 상업화 자금으로 2231억원을 조달한 바 있다.', NULL, '비즈워치', 'https://n.news.naver.com/mnews/article/648/0000045068', 'https://imgnews.pstatic.net/image/648/2026/03/09/0000045068_001_20260309110016033.gif?type=w800', 'NEWS_ETC', NULL, '2026-03-09 11:00:16', 0, true, '2026-03-09 05:53:37.151893') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (745, '무협, 美 테네시 주지사 초청 간담회', '한국무역협회가 23일 서울시 강남구 삼성동 그랜드인터컨티넨탈 호텔에서 개최한 ‘美 테네시 주지사 초청 무역업계 간담회’에 참석한 주요 인사들이 기념사진을 촬영하고 있다. 왼쪽부터 앨런 보든 미국 부상무장관, 오석송 메타바이오메드 회장, 장재진 오리엔트바이오 회장, 빌 리 미국 테네시 주지사, 김동욱 현대자동차 부사장, 윤진식 한국무역협회 회장, 노희열 오로라월드 회장, 스튜어트 맥호터 미국 테네시 부지사 겸 상무장관, 송호근 와이지-원 회장. 한국무역협회 제공.한국무역협회는 23일 서울 삼성동 그랜드인터컨티넨탈 호텔에서 ‘빌 리 美 테네시 주지사 초청 무역업계 간담회’를 개최했다.이날 간담회에는 윤진식 한국무역협회 회장을 비롯해 오석송 메타바이오메드회장, 송호근 와이지-원회장, 최명배 엑시콘회장, 김동욱 현대자동차 부사장 등 무역협회 회장단과 한미경제협의회(KUSEC) 회원사, 테네시주에 진출했거나 진출을 검토 중인 기업 관계자 등 25명이 참석했다.테네시 측에서는 빌 리(Bill Lee) 주지사, 스튜어트 맥호터(Stuart McWhorter) 부지사 겸 상무장관, 앨런 보든(Allen Borden) 부상무장관 등 10명이 자리했다.테네시주 진출 기업 중 덕산일렉테라(2차전지), 알루코(알루미늄), 유니테크(산업용 접착제), SL(자동차부품) 등도 함께했다.윤 회장은 환영사에서 “글로벌 완성차의 핵심 생산 거점이자 북미 전기차 전환을 선도하는 테네시주와 우리 기업 간 협력을 통해, 한미 양국의 첨단 산업 분야 공급망 협력이 한층 더 강화되기를 희망한다”며 “원활한 현지 진출을 위해 우리 기술자들의 비자 애로에 주정부 차원의 각별한 관심과 지원을 부탁드린다”고 말했다.리 주지사는 “한국은 배터리 소재·셀, 완성차 등 첨단 제조 분야에서 테네시주의 핵심 경제 파트너”라며 “한국 기업들이 테네시주의 경제 성장과 일자리 창출에 크게 기여해온 만큼 주정부도 경쟁력 있는 인력 확보와 비즈니스 친화적 환경 조성, 안정적인 에너지 공급 등을 위한 지원을 아끼지 않겠다”고 답했다.윤진식(오른쪽) 한국무역협회 회장과 빌 리 테네시 주지사가 23일 서울시 강남구 삼성동 그랜드인터컨티넨탈 호텔에서 열린 ‘美 테네시 주지사 초청 무역업계 간담회’에서 만나 인사를 나누고 있다.', NULL, '디지털타임스', 'https://n.news.naver.com/mnews/article/029/0002989006', 'https://imgnews.pstatic.net/image/029/2025/10/23/0002989006_001_20251023175018051.jpg?type=w800', 'NEWS_ETC', NULL, '2025-10-23 17:49:56', 0, true, '2026-03-09 05:51:42.211475') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (746, '美 이민 단속에 충청권 기업들 술렁… 투자·수출 막막', '미국, 조지아 LG엔솔 공장 단속… 韓 근로자 300명 체포미국 진출 기업 당혹… 알루코 등 조지아주 사업장 다수품목 관세까지 여파 가능성… 車 부품·반도체 관세 미지수외교부 신속대응팀과 총영사관 관계자들이 8일(현지시간) 미국 당국의 이민단속으로 체포된 현대차-LG엔솔 배터리공장 건설 현장 직원들이 수감있는 조지아주 포크스턴의 이민세관단속국(ICE) 구금시설로 향하고 있다. 연합뉴스미국 정부가 한국인 근로자를 대규모 구금하면서 충청권 기업들이 술렁이고 있다.미국 진출을 계획 중이거나 인력을 파견하는 지역 기업들에 비자라는 또 다른 불확실성이 생겨서다. 또 이번 구금 사태로 한미 통상 협상에도 변수가 발생 예상, 수출업계도 고심하는 상황이다.10일 지역 산업계에 따르면 미국에 공장 건설 등을 진행 중인 한국 기업들은 현재 작업을 일시 중단한 것으로 알려졌다. 미국의 대대적인 불법체류자 단속으로 인해 미국 출장을 중단하거나, 현지 출장자를 긴급 귀국시키면서다.앞서 미국 이민 당국은 지난 4일(현지시간) 조지아주 서배너의 현대차그룹-LG에너지솔루션 합작 배터리 공장 건설 현장에서 대대적인 불법체류자 단속을 벌였다.이 과정에서 한국인 300여 명이 체포·구금된 것으로 전해졌다. 이들은 대부분 회의 참석이나 계약 등을 위한 단기 비자인 B1 비자나, 무비자인 전자여행허가(ESTA)를 소지한 채 현지에서 일하고 있었던 것으로 파악됐다.이처럼 미국 조지아주에서 대규모 단속을 벌이자, 미국에 투자한 충청권 기업들은 당혹스러워하고 있다. 충청권에서도 미국 현지에 법인을 둔 기업들이 상당하기 때문이다.대한무역투자진흥공사에 따르면 대전 지역 알루미늄 부품소재 기업인 알루코는 미국 조지아주 덜루스에 법인을 두고 있다.또 충남 천안에 본사를 둔 덕신EPC는 조지아 덜루스에 공장이 있으며, 충북 유니언스와 엔켐 등도 조지아 법인을 설립했다.미국 진출을 계획 중인 지역 중소기업들도 우려가 커지고 있다. 특히 협력업체들은 그간 B1 비자·ESTA 등으로 입국해 단기간 근무하는 게 관행적으로 여겨졌는데, 비자 단속이 강화되면서 인력 운용에 차질이 예상되고 있다.한국무역협회 대전세종충남지역본부 관계자는 "조지아주 사태로 인해 현지 투자 법인 설립이 늦어질 경우, 공급망 등에 영향도 있을 것으로 보인다"라며 "또 정식 비자 발급은 장기간 소요돼 지역 기업이 어려움을 겪을 수 있다"라고 말했다.더욱이 미국 비자 문제로 인해 한미 관세 협상이 지연되면서, 지역 수출업계마저 고심이 깊다.앞서 미국 정부는 한국과 협상을 타결해 자동차 및 부품 관세를 15%로 인하하겠다고 약속했지만, 현재까지 구체적인 조치를 취하지 않고 있다. 대규모 관세를 예고한 반도체·의약품 최혜국 대우 이행 여부도 장담할 수 없는 실정이다.한국 정부는 실무협의를 진행할 계획이지만, 조지아주 단속 사태로 인해 협의가 장기화될 가능성도 나온다. 충청권 주요 수출품이 자동차 부품과 반도체인 만큼, 품목 관세 영향은 상당할 수밖에 없다.이에 정부는 미국 현지 대사관·영사관, 관계부처 등과 함께 기업들의 비자 및 입국 문제가 해결될 수 있도록 노력하겠다는 입장이다.이재명 대통령은 국무회의 모두발언에서 "위한 우리 국민과 기업 활동에 부당한 침해가 가해지는 일이 재발하지 않길 바란다"라며 "정부는 유사 사례가 반복되지 않도록 미국과 긴밀한 협의를 통해 합리적 제도 개선을 신속하게 추진하겠다"라고 강조했다.한편 조지아주 공장에서 체포·구금된 한국인들은 현지시간 10일 오후 2시 30분에 전세기로 출발할 예정이었으나, 미국 측의 사정으로 10일 출발이 어렵게 됐다고 외교부는 설명했다.', NULL, '대전일보', 'https://n.news.naver.com/mnews/article/656/0000147219', 'https://imgnews.pstatic.net/image/656/2025/09/10/0000147219_001_20250910184112880.jpg?type=w800', 'NEWS_ETC', NULL, '2025-09-10 18:41:12', 0, true, '2026-03-09 05:51:42.211475') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (747, '담합 사건 ‘속도전’이 능사 아니다[현장에서]', '(사진=연합뉴스)[세종=이데일리 강신우 기자] 요즘 관가에서는 업무 처리를 둘러싼 부담이 커졌다는 말이 나온다. ‘신속’과 ‘정확’은 기본이고 여기에 사회적 이슈까지 고려해야 하니 “죽을 맛”이라는 하소연도 심심치 않게 들린다. 오는 6월 대통령 업무보고를 앞두고 가시적인 정책 성과를 보여야 하는 부처일수록 이런 압박은 더 크게 느껴진다는 분위기다.그러나 카르텔(담합) 사건만큼은 이러한 속도전의 예외가 돼야 한다. 담합은 애초에 들키지 않도록 설계된 위법행위다. 가격 합의를 보여주는 문서를 찾는 건 쉽지 않다. 대신 회의 정황이나 가격 움직임, 내부 이메일, 자진신고(리니언시) 진술 등을 종합해 위법성을 가려내야 한다. 경제분석까지 동원되는 경우도 적지 않다. 그만큼 조사 난이도가 높을 수밖에 없다.절차 역시 단순하지 않다. 공정위 사건은 조사를 마친 뒤 심사보고서를 피심인에게 송달하면서 본격적인 심의가 시작된다. 기업은 자료 열람이나 의견서 제출·진술 등을 통해 방어권을 행사한다. 통상 두 차례 이상 서면 의견이 오가고 추가 자료 제출도 이어진다. 이후 전원회의 또는 소회의 심의를 거쳐 위법 여부와 과징금 부과 여부, 금액이 결정된다.문제는 속도 압박이 강해질수록 이런 절차가 흔들릴 수 있다는 점이다. 충분한 의견 제출 기회를 보장하지 않거나 증거 검토가 미흡한 상태에서 결론을 내리면 방어권 침해 논란은 물론 공정위 조사에 대한 불신으로 이어질 수 있다.이처럼 조사 과정에서 따져야 할 사안이 많고 기업 방어권 보장과 과징금 산정에도 상당한 시간이 필요하다. 여러 기업을 동시에 조사해야 하는 담합 사건은 더 많은 시간과 행정력이 투입될 수밖에 없다.그럼에도 공정위는 담합 사건 처리 기간 단축을 성과로 강조하고 있다. 지난달 13일 설탕 가격을 담합한 CJ제일제당·삼양사·대한제당 등 제당 3사 사건을 평균보다 빠른 약 220일 만에 조사했다는 점을 내세운 것이다. ‘검찰 수사(기소)에 비해 공정위 처분이 늦다’는 지적에 대한 답변이지만, 처리 속도보다 담합 사건의 절차적 정당성을 강조하는 편이 오히려 더 설득력 있었을 것이다.성급한 심결로 시간을 더 낭비할 수 있다. 행정소송에서 패소하면 수년간의 조사와 심의가 사실상 원점으로 돌아가기 때문이다. 실제로 생명보험사 예정이율 정보교환 사건이나 국제 해운 운임 담합 사건처럼 대형 담합 사건에 대한 제재가 법원에서 뒤집힌 사례도 있다. 공정위 통계에 따르면 행정소송에서 공정위의 완전 승소율(2024년 기준)은 약 70% 수준이다. 그러나 일부 패소까지 포함하면 약 30% 가까운 사건에서 법원이 공정위 판단을 뒤집거나 일부 인정하지 않았다.공정위 사건 처리 속도를 높이려는 노력 자체는 필요하다. 다만 카르텔 사건에서 중요한 것은 ‘얼마나 빨리 결론을 내느냐’가 아니라 ‘얼마나 흔들리지 않는 결론을 내느냐’다. 담합을 다루는 일은 속도전이 아니라 정밀전에 가까워야 한다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006230498', 'https://imgnews.pstatic.net/image/018/2026/03/09/0006230498_001_20260309051307390.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 05:13:07', 0, true, '2026-03-09 05:52:10.600174') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (748, '“7년6개월간 6조2000억원 담합”… 공정위, 설탕, 밀가루 이어 전분당도 제재 절차 돌입', '공정위, 가격 재결정 명령 검토1조2400억원 과징금 부과 가능성도설탕·밀가루 등의 담합에 이어 공정거래위원회가 전분당 제조·판매 업체들의 담합 의혹에 대한 제재 절차에 착수했다. 전분당은 옥수수를 분쇄해 만드는 전분과 이를 분해해 생산하는 물엿·포도당·액상과당 등을 통칭한다. 라면, 빵, 과자 등 식품 원재료로 사용되며 제지·철강 등 산업용 접착·코팅 소재로도 쓰인다. 국내 4개 제당사의 담합 관련 매출 규모는 6조2000억원으로, 공정위는 이 업체들에 최대 1조2400억원의 과징금을 부과할 수 있다.세종시 정부세종청사 공정거래위원회 전경./뉴스16일 공정위는 전분당 제조·판매 업체들의 가격 담합 사건에 대해 심사 보고서를 송부하고 위원회 심의 절차를 개시했다고 밝혔다. 대상 기업은 CJ제일제당, 삼양사, 사조씨피케이, 대상 등 4사다.공정위에 따르면, 4사는 2018년 5월~2025년 10월 약 7년 6개월 동안 전분당 판매 가격을 담합한 혐의를 받고 있다. 공정위 심사관은 담합으로 영향을 받은 관련 매출 규모가 약 6조2000억원으로 추산했다. 공정위는 담합 관련 매출액의 최대 20%까지 과징금을 부과할 수 있어, 과징금은 최대 1조2400억원이 될 수 있다.공정위는 심사 보고서 조치 의견에 가격 재결정 명령도 포함했다. 가격 재결정 명령은 담합으로 왜곡된 가격을 정상 가격으로 낮추도록 하는 시정 명령이다.공정위는 지난달 대선제분, 대한제분, 사조동아원, 삼양사, 삼화제분, CJ제일제당, 한탑 등 7개 제분업체의 밀가루 담합 행위에 대해 제재 절차를 개시한 바 있다. 공정위는 또 CJ제일제당, 삼양사, 대한제당 등 3개 설탕 제조·판매사의 담합 혐의에 대해 과징금 4083억원을 부과하기로 결정하기도 했다.', NULL, '조선일보', 'https://n.news.naver.com/mnews/article/023/0003962878', 'https://imgnews.pstatic.net/image/023/2026/03/06/0003962878_001_20260306233616471.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-06 12:08:06', 0, true, '2026-03-09 05:52:10.600174') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (749, '공정위, 6조 원대 ''전분당 담합'' 4개 업체에 가격 재결정 의견', '공정위, 심사보고서 발송위원회 심의 거쳐 제재 확정전분당 부산물 담합도 조사공정위원회.공정거래위원회가 전분당 제조·판매 사업자 4곳의 담합 행위에 대한 제재 절차를 개시했다. 담합은 생활 물가를 끌어올리는 중대한 민생 범죄로 지목된 만큼 고강도 처벌이 예상된다.공정위는 대상과 사조CPK, 삼양사, CJ제일제당의 공정거래법 위반 혐의에 대한 심사보고서를 업체들에 송부하고, 위원회에 제출했다고 6일 밝혔다. 검찰의 공소장에 해당하는 심사보고서는 법 위반 사건에 대한 공정위의 조사 결과와 조치 의견 등이 담긴다.공정위는 심사보고서를 통해 가격 재결정 명령을 포함한 시정조치와 과징금 부과, 관련 임직원의 고발 의견을 제시했다. 검찰의 요청에 따라 각 법인에 대한 고발은 지난달 이뤄졌다.공정위에 따르면, 전분당 업체들은 2018년 5월부터 지난해 10월까지 반복적이고 조직적으로 전분당 판매가격을 담합했다. 전분당은 옥수수를 분쇄해 생산한 전분(녹말)을 가수분해함으로써 만든 당이다. 면이나 제과 등 식품 원재료에 필요하고, 산업용으로도 쓰인다. 전분당 시장은 대부분 기업간거래(B2B)로 구성되는데, 업체들의 시장 점유율은 90%에 달한다. 공정위는 전분당 가격 담합이 가공식품 가격 상승에 영향을 미친 것으로 보고 있다.담합 규모도 막대했다.공정위는 담합 행위로 영향을 받은 관련 매출액이 6조2,000억 원에 이를 것으로 산정했다.공정위는 관련 매출액의 최대 20%까지 과징금을 부과할 수 있다. 전분당 업체들에 대한 최종 제재 수위는 위원회 심의를 통해 확정될 예정이다.업체들의 전분당 담합 정황은 공정위가 3개 제당사(CJ제일제당·삼양사·대한제당)의 설탕 담합 사건을 조사하는 과정에서 드러났다. 공정위는 지난해 10월부터 이달 초까지 장기간에 걸쳐 추적 조사를 실시했다.전분당 업체들은 공정위 조사가 시작되자 주요 전분당 제품 가격을 3~5% 인하했다.유성욱 공정위 조사관리관은 "위원회가 심의에서 업체들의 가격 인하 폭이 적정한지를 판단해 가격 재결정 명령 여부를 결정할 것"이라고 설명했다.연관기사• 공정위 칼끝에… 업체들, 물엿 등 전분당 제품 줄줄이 인하(www.hankookilbo.com/news/article/A2026022313580001836)공정위는 전분당 업체들에 대한 조사 범위를 확대하고 있다. 업체들이 전분당 부산물에 대해서도 가격 담합을 한 것으로 확인됐기 때문이다.전분당 수요처의 입찰 담합 행위도 포착됐다.유 관리관은 "민생을 위협하는 담합 행위에 대해서는 집중 감시와 엄중한 법 집행을 통해 담합 유인이 실질적으로 차단될 수 있도록 노력할 것"이라고 밝혔다.', NULL, '한국일보', 'https://n.news.naver.com/mnews/article/469/0000917900', 'https://imgnews.pstatic.net/image/469/2026/03/06/0000917900_001_20260307061436743.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-06 12:01:10', 0, true, '2026-03-09 05:52:10.600174') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (750, '중동 전쟁에 식품업계 가격 인하 흐름 제동 걸리나', '국제 유가·환율 불안정에 원재료 수입 단가 상승 가능성정부는 식품업계 소집해 물가 안정 기조 동참 요청업계 “가격 인하 부담 커져... 사태 장기화 예의 주시”미국·이스라엘과 이란 간 군사 충돌이 중동 전반으로 확산 조짐을 보이면서 국제 유가와 원·달러 환율이 동시에 불안정해지고 있다. 식품업계에서는 최근 정부 압박 후 형성됐던 가격 인하 분위기가 중동발 리스크로 꺾일 수 있다는 얘기가 나온다.지난달 27일 서울의 한 대형마트에 밀가루 제품이 진열돼 있다. /뉴스15일 관련 업계에 따르면 중동 사태 이후 국제 유가가 급등하면서 물류비 부담이 커질 가능성이 커졌다. 특히 글로벌 원유 수송의 핵심 요충지인 호르무즈 해협 완전 봉쇄 가능성까지 거론되면서 해상 운임 등이 상승 압박을 받는 상황이다. 지난 3일(현지 시각) 기준 ICE선물거래소에서 브렌트유 선물 종가는 배럴당 81.4달러로 전장 대비 3.66달러(4.71%) 올랐다. 뉴욕상품거래소에서 서부 텍사스산 원유(WTI)는 3.33달러(4.67%) 상승한 배럴당 74.56달러에 거래를 마쳤다.제분업계는 국내 밀 자급률이 1% 안팎에 불과해 수입에 의존하고 있다. 국제 유가와 물류비 상승에 직접적인 영향을 받는다. 유가·운임·환율이 동시에 가격에 반영되는 구조로 원가 변동성이 크게 나타나는 업종으로 꼽힌다.제분업계는 최근 담합 수사와 공정거래위원회의 가격 인하 압박 후 수익성 악화 가능성이 커진 상황에서 대외 변수까지 겹치며 부담이 가중됐다. 공정위는 CJ제일제당, 대한제분 등을 비롯한 국내 제분사 7곳에 대해 밀가루 가격 담합 혐의를 조사 중이다. 앞서 공정위는 CJ제일제당, 삼양사, 대한제당 등 제당 3사가 2021년 2월부터 지난해 4월까지 약 4년간 설탕 판매 가격을 담합했다며 4083억원(잠정)의 과징금 제재를 내렸다.CJ제일제당, 삼양사 등 국내 주요 제당·제분사는 공정위의 담합 조사 후 밀가루·설탕 가격을 평균 5% 인하했다. 이어 CJ제일제당은 밀가루 제품 가격을 평균 5% 추가 인하하겠다고 밝혔다.일부 프랜차이즈 등 제빵업계도 가격을 내릴 예정이다. CJ푸드빌이 운영하는 뚜레쥬르는 오는 12일부터 빵과 케이크 등 총 17종의 공급가를 평균 8.2% 인하한다. 파리바게뜨도 오는 13일부터 빵과 케이크 등 제품 11종의 가격을 인하한다. 업계 관계자는 “아직 중동 사태로 인한 밀가루 수급 이슈는 없는 상황”이라며 “다만 사태가 장기화할 경우 유가, 물류비, 환율 등에 따른 타격이 있을 수 있어 예의주시하고 있다”고 했다.식품업계는 정부 압박에 따른 밀가루 가격 인하 이후 가격 조정을 고려하던 시점이었지만, 유가와 환율이 계속 오를 경우 원가 부담은 다시 커질 전망이다. 공정위는 최근 치킨 등 주요 프랜차이즈 관계자들을 소집해 가격 인상 사전 고지 협약에 서명하는 행사를 열었다. 농림축산식품부는 전날 CJ제일제당·사조대림·오뚜기·대상·동원F&B·롯데웰푸드 등 식품 업체들을 불렀다. 이날은 농심·오뚜기·삼양식품·팔도 등 라면 4사를 소집한다. 농식품부는 정부의 물가 안정 기조에 동참해 달라고 요청할 것으로 알려졌다.한 식품업계 관계자는 “국제 정세의 불확실성이 커 수입 원재료 가격, 환율, 물류비 등에 어떤 변동이 있을지 예측하기 어려운 상황”이라며 “한동안 인하를 고려하기보다 동결 등을 고민할 가능성이 크다”고 했다.', NULL, '조선비즈', 'https://n.news.naver.com/mnews/article/366/0001145983', 'https://imgnews.pstatic.net/image/366/2026/03/05/0001145983_001_20260305105112709.JPG?type=w800', 'NEWS_ETC', NULL, '2026-03-05 10:01:12', 0, true, '2026-03-09 05:52:10.600174') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (751, '[취재수첩] 올릴 땐 로켓, 내릴 땐 깃털…식품업계 ''뒤늦은 가격 인하''', '2월28일 서울 시내 한 대형마트에 설탕 등 당류가 진열돼 있다. [사진=연합뉴스][디지털데일리 유채리기자] 요즘 식품업계에서 이례적인 일이 벌어지고 있다. 제품 가격 인하다.사조CPK·대상·CJ제일제당 등이 주요 제품 가격을 내렸고, 파리바게뜨·뚜레쥬르 역시 빵과 케이크 가격을 낮췄다. 가격 인하 흐름이 라면과 과자 등 다른 식품군으로 확산될 조짐도 보인다.기업이 가격을 내리는 일은 흔치 않다. 값이 오를 때는 로켓처럼 빠르고, 내릴 때는 깃털처럼 천천히 떨어진다는 ''로켓과 깃털 효과''라는 경제학 용어가 있을 정도다.하지만 이번 가격 인하를 마냥 반길 수만은 없다. 그 배경에 제분·제당업계의 담합 문제가 자리하고 있기 때문이다.공정거래위원회는 최근 CJ제일제당과 대한제분 등 7개 제분사가 2019년 11월부터 지난해 10월까지 기업 간 거래(B2B)에서 밀가루 판매 가격과 물량 배분을 사전에 합의한 혐의에 대해 전원회의 심의를 진행하고 있다.앞서 공정위는 CJ제일제당·삼양사·대한제당이 설탕 판매가격 인상 폭과 시기를 합의했다며 총 4083억원의 과징금을 부과하기도 했다.업계는 가격 인하와 함께 담합 재발 방지를 위한 대책을 내놓고 있다. 대한제당협회 탈퇴, 가격 결정 시스템 개선, 윤리경영 지침 강화 등이 대표적이다.그러나 진정성에 대한 의문은 여전히 남는다. 가격 인하 자체가 과징금 감경을 위한 포석일 가능성도 배제하기 어렵다. 무엇보다 이들의 담합은 이번이 처음이 아니다.문제의 근간에는 뿌리 깊은 독과점 구조가 있다. 한국전쟁 이후 정부 주도로 성장한 밀가루, 면직물, 설탕 등 이른바 ''삼백(三白) 산업''은 효율을 명분으로 시장을 사실상 독점하며 몸집을 키웠다. 그 과정에서 성장한 기업들이 지금의 CJ제일제당과 삼양사 등이다.민간 기업이지만 성장의 기반에는 국가 정책과 서민 소비가 있었다. 그렇다면 지금 필요한 것은 단순한 가격 인하가 아니다. 담합의 고리를 끊고 시장 구조를 바꾸는 근본적인 개혁이다.가격 인하는 생색일 수 있다. 그러나 담합 기업이 져야 할 책임의 무게는 결코 가볍게 끝나서는 안 된다.', NULL, '디지털데일리', 'https://n.news.naver.com/mnews/article/138/0002219512', 'https://imgnews.pstatic.net/image/138/2026/03/04/0002219512_001_20260304155006864.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-04 15:50:06', 0, true, '2026-03-09 05:52:10.600174') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (752, '李 "담합은 암적 존재"…교복·밀가루·전분당, 떨고 있니?', '교복 제조사·대리점 대상 전국 조사 착수돼지고기·계란·교복 등 3~5월 순차 심의설탕 3사에 시정명령·4000억 과징금 부과''밀가루'' 심의 개시…전분당 이달 조사 마무리위원장 "반복 담합엔 시장 퇴출 수준" 경고압박에 ''설탕·밀가루·전분당'' 자발적 가격 인하[서울=뉴시스] 추상철 기자 = 지난달 21일 오후 서울 송파구 ''나눔교복 매장''에서 학부모와 학생이 교복을 고르고 있는 모습.  송파구는 고물가 시대 새 학년을 맞이해 졸업생과 각 학교로 부터 기증받은 교복을 기증 받아 저렴하게 판매하는 ''나눔교복 매장''을 상설 운영하고 있다. 2025.02.21. scchoo@newsis.com[세종=뉴시스]손차민 기자 = 이재명 대통령이 담합을 ''암적 존재''라고 강하게 비판한 가운데, 공정거래위원회가 국민 생활에 밀접한 품목에 대한 담합 조사에 속도를 내고 있다.설탕 제조사들에 4000억원대 과징금을 부과한 데 이어, 교복·밀가루·전분당 등으로 제재 범위를 넓히는 모습이다.2일 공정위에 따르면 본부와 5개 지방사무소는 최근 4개 교복 제조사 및 전국 40여개 대리점을 대상으로 전국 단위 조사에 착수했다.이와 별개로 광주 지역의 교복 업체 27곳의 입찰 담합 사건 심의도 이번 달 예정돼 있다.고가 논란이 제기되는 교복은 관행적인 담합이 반복돼 온 품목으로 꼽힌다. 실제로 공정위는 지난해 3월 경기도 구리, 6월에는 경북 구미 지역 교복업체들의 짬짜미를 제재한 바 있다.공정위는 교복을 포함해 계란·돼지고기 등 진행 중이던 조사를 신속하게 마무리하고 제재 절차에 들어갔다. 제재 수위는 전원회의 심의를 통해 확정될 전망이다.주병기 공정위 위원장은 최근 국무회의에서 "제재 절차에 착수한 돼지고기, 계란, 교복 등 민생 품목은 이번 달부터 5월까지 순차적으로 심의할 것"이라고 말했다.[서울=뉴시스] 조성우 기자 = 서울 시내의 한 대형마트에 CJ제일제당의 브랜드 백설과 삼양사의 큐원 등 설탕 제품이 진열돼 있다. 2026.02.12. xconfind@newsis.com특히 공정위가 주목하는 건 설탕·밀가루·전분당 등 가공식품 원재료가 되는 품목들이다.앞서 공정위는 지난달 CJ제일제당·삼양사·대한제당 등 설탕업체들의 담합에 대해 시정명령과 과징금 총 4083억원을 부과했다.해당 업체들은 원당 가격이 오를 땐 설탕 가격을 빠르게 인상하고, 원당 가격이 내려가면 시차를 두고 늦게 가격에 반영하는 방식으로 3조2884억원의 관련 매출액을 형성한 것으로 조사됐다.밀가루 담합 건의 경우 조만간 결론이 나올 것으로 보인다. 공정위 사무처는 대선제분·대한제분·사조동아원·삼양사·삼화제분·CJ제일제당·한탑 등 밀가루 제조업체 7곳에 대한 담합 조사를 마치고, 심사보고서를 발송했다.심사보고서는 심사관이 조사 과정에서 파악한 위법성 및 그에 대한 조치의견을 기재한 것으로, 검찰의 공소장 격에 해당한다. 공정위의 제재 절차가 본격화됐음을 의미다.공정위는 해당 사건의 관련 매출액이 약 5조8000억원에 이를 것으로 추산한다. 담합 과징금이 관련 매출액의 20% 범위에서 부과되는 걸 감안하면 1조1600억원대의 과징금이 결정될 가능성도 제기된다.전분·물엿·과당 등을 제조하는 전분당 업체들도 조사 대상에 올랐다. 최근 공정위는 대상·삼양사·사조CPK·CJ제일제당 등 업체 4곳의 담합 의혹을 들여다보고 있다. 국내 전분당 시장은 해당 4개사가 과점 구조를 형성 중이다.공정위는 전분당 담합 조사도 이번 달 초까지 마무리할 계획이다.여기에 검찰도 직접 수사에 착수하기로 했다. 전분당 시장의 구조 등을 감안했을 때 밀가루·설탕보다 담합 규모가 더 크다고 봤기 때문이다. 이에 수천억원대의 과징금이 부과될 수 있다는 관측도 나온다.[서울=뉴시스] 황준선 기자 =  6일 서울 시내 한 대형마트에 밀가루가 진열돼 있다. 이재명 대통령의 물가 안정 주문과 담합 수사 여파 속에서 CJ제일제당과 대한제분, 사조동아원, 삼양사 등 제분·제당업계는 설탕 및 밀가루 가격을 4~6% 인하했다. 2026.02.06. hwang@newsis.com정부는 공정위를 중심으로 국세청·관세청·검찰·경찰 등 관계기관 협력을 통한 강경한 대응에 나설 방침이다.이에 지난달부턴 민생물가 특별관리 관계장관 태스크포스(TF) 산하에 불공정거래 점검팀도 설치해 운영 중이다.더욱이 공정위는 담합 재발에 대한 엄벌까지 예고했다.주 위원장은 "반복적으로 담합에 가담하는 업체에 대해서는 선진국처럼 시장 퇴출 수준으로 하는 방안을 관계부처와 협의하고 있다"고 밝혔다.정부의 담합 근절 의지가 시장에 영향을 미치면서, 기업들의 자발적인 가격 인하 움직임이 나타나고 있다.공정위는 설탕 16.5%, 밀가루 7.9%, 전분당 16.7% 수준의 가격 인하가 이뤄졌다고 분석했다.여기에 설탕, 밀가루 등의 원재료 가격 정상화가 실제 외식 물가로 이어질 수 있도록 유도할 방침이다.주 위원장은 지난 27일 주요 프랜차이즈 업체 7곳과 ''가격인상 등 정보제공 협약''을 체결했다.교촌에프앤비(교촌치킨), 다이닝브랜즈그룹(BHC 등), 롯데지알에스(롯데리아 등), 비알코리아(던킨도너츠 등), 씨제이푸드빌(뚜레쥬르 등), 제너시스비비큐(BBQ), 파리크라상(파리바게뜨 등)이 참여했다.이들 업체는 음식 가격을 인상하거나 중량을 줄일 경우 이를 사전에 소비자에 알리기로 했다.주 위원장은 이 자리에서 "최근 외식 상품의 주요 원재료인 설탕이나 밀가루 시장에서의 가격 왜곡이 정상화되고 있다"며 "그 효과를 국민들이 가까운 곳에서 조속하게 체감하실 수 있도록 소비자에게 매일의 먹거리를 공급하는 7개사가 특별히 신경 써달라"고 당부했다.[세종=뉴시스] 강종민 기자 = 주병기 공정거래위원장이 12일 세종시 정부세종청사에서 CJ제일제당, 삼양사, 대한제당 등 3개 제당사의 담합사건 심의 결과를 발표하고 있다. 2026.02.12. ppkjm@newsis.com', NULL, '뉴시스', 'https://n.news.naver.com/mnews/article/003/0013795647', 'https://imgnews.pstatic.net/image/003/2026/03/02/NISI20250221_0020708827_web_20250221143618_20260302091621130.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-02 09:00:00', 0, true, '2026-03-09 05:52:10.600174') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (753, 'GS25, 영월 지역 매출 전년 比 최대 54% 성장… ‘왕사남’ 열풍에 특수 상권 활기', '10여개 점포서 유의미하게 매출 늘어강원도 영월군에 위치한 GS25 매장. 사진제공=GS리테일왕과 사는 남자(왕사남) 열풍이 지역 상권까지 달구고 있다.7일 GS리테일에 따르면 편의점 GS25는 영화 ‘왕사남’ 열풍에 힘입어 영월 지역 점포 매출이 최대 54% 증가했다고 밝혔다. ‘왕사남’은 개봉 직후 700만·800만·900만 관객을 빠르게 돌파하며 ‘범죄도시4’ 이후 2년 만에 1000만 관객 돌파에 성공했다.스크린 속 감동은 관객들의 발길을 실제 역사 현장으로 이끌고 있다는 분석이다. 특히 영화 속 주인공이자 조선 제5대 국왕 단종의 유배지인 영월이 특히 새로운 ‘성지’로 주목받고 있다. 영월문화관광재단에 따르면 설 연휴 기간 단종 유배지인 청령포 방문객은 1만 641명으로 전년 대비 5배 증가했다. 장릉 방문객은 7275명으로 약 7배 늘었다. 영화 흥행이 지역 관광 수요로 직결된 셈이다.‘왕과 사는 남자’ 스틸컷. 사진 제공=쇼박스이 같은 방문객 증가는 편의점 매출로도 이어졌다. 2월 4일 이후 약 한 달간 영월 지역 내 10여 개 GS25 점포 매출은 전년 동기 대비 15% 이상 신장했다. 한 점포는 최대 54%까지 매출이 증가한 것으로 나타났다.상품 카테고리별로 살펴보면 도시락(18.3%), 김밥(11.5%) 등 간편 식사류를 비롯해 아이스크림(48.7%), 얼음(30.7%), 생수(28.4%), 맥주(28.3%), 스낵(18.7%) 등 먹거리 상품 매출이 크게 늘었다. 숙박과 연계된 치약(64.5%), 면도용품(39.7%), 칫솔(39.0%), 의류용품(50%) 등 생활용품 매출도 상승했다.GS25는 당분간 영화 흥행과 함께 ‘단종 앓이’에 나선 팬들의 영월 방문이 이어질 것으로 내다보고 있다. 이에 따라 관광객 수요에 맞춘 상품 구색 강화와 재고 확대, 쾌적한 매장 운영 등을 통해 지역 방문객 만족도를 높인다는 계획이다.청령포 매표소에 길게 늘어선 관광객. 사진 제공=영월군GS25 관계자는 “영월 관광객과 지역 주민 모두가 편리하게 이용할 수 있도록 먹거리와 여행 필수품 중심으로 상품 재고와 구색을 강화해 영월에서의 긍정적인 경험이 이어질 수 있도록 최선을 다하겠다”고 말했다.한편 GS25 외에도 오리온 역시 영화 왕사남 열풍의 수혜가 기대된다. 왕사남의 배급사인 쇼박스의 최대주주가 지분 57.5%를 보유한 오리온홀딩스이기 때문이다. 쇼박스는 지난해 매출액 627억 원을 기록하며 전년 동기 대비 32.6% 감소했지만, 올해는 왕사남 흥행 효과에 힘입어 실적이 크게 개선될 것으로 전망된다.', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004596677', 'https://imgnews.pstatic.net/image/011/2026/03/07/0004596677_001_20260307070124966.png?type=w800', 'NEWS_ETC', NULL, '2026-03-07 07:01:24', 0, true, '2026-03-09 05:52:29.436578') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (754, '실적 부진에 ''신사업'' 실종…유통가 슈퍼 주총데이 미리 보니', '상법개정안 반영한 정관 변경…사내이사 재선임 안건도 다수유통업계가 이달 19일 호텔신라와 GS리테일, 롯데칠성음료를 시작으로 본격적인 주주총회 시즌에 돌입한다. 올해에는 상법 개정안 시행에 맞춘 정관 변경이 주요 안건으로 처리될 것으로 보인다. 지난해 신사업 진출 의지를 드러내던 모습은 실적 부진으로 인해 실종됐고, 이사진 연임으로 경영 안정화에 방점을 두고 있는 모습이다.6일 금융감독원에 따르면 ▲호텔신라·GS리테일·롯데칠성음료(19일)를 시작으로 ▲농심·롯데웰푸드·롯데쇼핑(20일) ▲샘표(23일) ▲신세계(24일) ▲삼양식품·오리온·이마트·현대백화점·BGF리테일·오뚜기·오리온홀딩스·한화갤러리아·SPC삼립·해태제과식품·아모레퍼시픽(26일) ▲현대지에프홀딩스·풀무원(31일) 등의 순으로 주총이 개최된다.특히 26일은 10개가 넘는 상장사가 주총 개최를 확정하면서 ‘슈퍼 주총데이’가 될 것으로 전망된다.국내 주요 유통·식품 상장사들이 이달 주주총회를 개최한다. (사진=클립아트 코리아)상법 개정안 반영…집중투표제 도입·자사주 소각이번 정기주총 안건은 대부분 정관 변경이 차지했다. 다만 지난해와 같이 신사업 진출을 위한 정관 변경이 아닌 상법 개정안의 단계적 시행에 발맞추기 위해서다.정부와 여당은 지난해 1·2차 상법 개정안을 각각 통과시켰다. 1차 개정안은 이사의 충실의무 대상을 기존 회사에서 ‘회사 및 총주주’로 확대하는 내용이 골자며, 2차 개정안은 감사위원 분리선출 인원 확대와 집중투표제 의무화를 담고 있다.지난달 말에는 회사가 자기주식을 취득할 경우 1년 이내에 소각하는 것을 원칙으로 하는 3차 상법개정안이 국회 본회의를 통과한 바 있다.공포 후 1년이 지난 시점부터 적용되기 때문에 올해 하반기부터 본격 시행된다. 이에 이번 주총이 1·2차 상법 개정안이 반영되기 전 사실상 마지막 주총인 셈이다.국회의사당 (제공=클립아트코리아)GS리테일은 집중투표제 배제 조항 삭제와 전자주주총회 도입 근거 마련, 감사위원 분리선출 인원 상향 및 감사위원 선·해임 시 의결권 제한 강화를 위한 정관 일부 변경과 사외이사 재선임 및 신규선임안을 올린다.현대백화점은 최자영 한국유통학회 회장과 정연승 단국대 교수의 사외 이사 신규 선임안을, 롯데쇼핑은 우미영 아마존웹서비스 사내비즈니스 트레이너와 박세훈 모건스탠리 고문을 사외이사로 신규 선임하는 안건을 각각 주총에 상정했다.또 삼양식품은 목승호 김앤장 법률사무소 변호사를 사외이사로, 오리온은 이현규 무법인 아림 대표를 사외이사 신규 선임하는 안건을 각각 상정했다.자사주 소각 관련 안건도 오른다. 이마트는 ‘자기주식 보유 및 처분 계획 승인’안을 상정했다. 이마트는 지난해 2월 발표한 기업가치 제고계획에 따라 올해 약 28만주를 소각할 예정이다. 이 외 기업들도 ‘자기주식 보유 및 처분 절차 신설을 위한 정관의 변경’을 의안으로 올렸다.''신성장 동력 찾기''는 실종다만 지난해와 같은 신규 사업 목적 추가를 위한 정관 변경은 찾아보기 어려웠다.이마트가 2025년 3월 26일 오전 정기 주주총회를 개최했다.지난해에는 호텔신라가 종합휴양업과 콘도미니엄 분양·운영업, 노인주거·여가복지 설치 및 운영사업을 정관에 추가했고 농심은 스마트팜 사업을 정관상 사업목적에 넣었다. 동원F&B도 전자상거래 및 통신판매 중개업부터 식품 가공, 애완동물 관련 용품 판매 등 17개의 신규 사업을 정관상 사업목적에 추가했었다.이는 경기 불황 여파로 해석된다. 신성장 동력을 찾기보다 기존 사업을 강화하거나 효율화를 통해 수익성을 찾겠다는 움직임으로 보인다. 실제 지난해 말 대한상공회의소가 실시한 ‘2026년 유통산업 전망 조사’ 결과에 따르면 올해 국내 소매유통시장 성장률은 0.6%에 그칠 것이라는 예상이 나왔다. 최근 5년 내 가장 낮은 수준이다.대신 사내이사 재선임을 통해 조직 안정화에 무게를 뒀다. 롯데웰푸드는 신동빈 롯데그룹 회장 및 롯데웰푸드 회장을 사내이사로 재선임하기로 했다. 신 회장은 2017년부터 롯데웰푸드 사내이사직을 연임하고 있다.BGF리테일 역시 민승배 대표를 사내이사로 재선임하는 안건을, 호텔신라는 이부진 사장의 사내이사 재선임 건을 상정했다. 민 대표는 지난 2023년 사내이사로 신규 선임됐다. 이번에 재선임 안건이 의결되면 향후 3년간 사내이사직을 이어간다.이 사장 역시 2011년부터 호텔신라 대표 및 이사회 의장을 맡아왔다. 이번 안건이 의결되면 향후 3년간 사내이사직을 맡으며 6연임 하게 된다.', NULL, '지디넷코리아', 'https://n.news.naver.com/mnews/article/092/0002413265', 'https://imgnews.pstatic.net/image/092/2026/03/06/0002413265_001_20260307074714029.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-06 16:57:12', 0, true, '2026-03-09 05:52:29.436578') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (755, '[단독] 150억 추가 수혈…오리온홀딩스, 바이오 확장 가속', '합작 파트너사 하이센스 20억 출자바이오로직스 자본금 165억 확대지난해 배당금 490억…실탄 ‘두둑’치과치료·결핵백신 등 신사업 확장오리온홀딩스(001800)가 지난해 말 바이오 계열사 2곳에 150억 원대의 자금을 투입하며 신사업을 확대한 것으로 확인됐다. 중국 상하이 소재 안라이바이오로직스와오리온(271560)바이오로직스의 유상증자에 각각 78억 원, 54억 원 규모로 참여한 데 이어, 합작 파트너사인 하이센스바이오에도 약 20억 원을 직접 출자했다. 제과 중심 사업 구조에서 벗어나 바이오를 미래 성장 동력으로 키우겠다는 전략에 따른 자본 보강으로 풀이된다.26일 금융감독원에 따르면 오리온홀딩스는 지난해 11월 계열사인 안라이바이오로직스와 오리온바이오로직스에 각각 78억 원과 54억 원을 출자했다. 오리온바이오로직스는 지난해 8월 자본금을 75억 원에서 115억 원으로 늘린 데 이어, 11월 50억 원을 추가로 확충하며 자본금을 총 165억 원(4억 원은 주식발행초과금)으로 확대했다. 지난 해에만 두 차례 자본 확충이 이뤄졌다.오리온홀딩스는 오리온바이오로직스를 합작한 파트너사 하이센스바이오에도 직접 투자에 나섰다. 지난해 12월 하이센스바이오가 발행한 상환전환우선주(RCPS) 16만 1290주를 약 20억 원에 인수한 것이다. 오리온홀딩스와 하이센스바이오는 60대 40 지분 구조로 합작 법인 오리온바이오로직스를 2022년 설립한 바 있다. 오리온홀딩스가 그동안 합작법인에 대한 자금 지원에 집중했다면, 이번에는 핵심 기술 보유사인 하이센스바이오 본사에도 직접 투자하며 전략적 연계를 강화했다는 분석이다.오리온바이오로직스는 치과질환 치료제 사업을 맡고 있다. 하이센스바이오의 원천기술을 기반으로 시린이·잇몸 기능성 치약을 개발해 태국과 베트남에서 판매 허가를 받았으며, 인도네시아(할랄 인증 포함) 허가도 준비 중이다. 안라이바이오로직스는 중국에서 결핵백신 개발을 추진하는 법인으로 2024년 10월 설립됐다. 2032년 상업화를 목표로 연구개발 인프라를 확충하고 있다. 중국 정부가 2035년까지 결핵 퇴치를 목표로 내세운 만큼 정책적 환경도 우호적이라는 평가다. 오리온홀딩스 관계자는 “현재 전 세계에서 상용화된 결핵백신은 영유아용 BCG 백신이 유일하다”며 “청소년·성인용 백신이 상용화될 경우 글로벌 시장을 선도할 가능성이 매우 높을 것으로 기대된다“고 설명했다.이 밖에도 오리온홀딩스는 대장암 체외진단키트와 항체약물접합체(ADC) 신약 분야에도 투자하고 있다. 2021년 중국 산둥루캉의약과 합자법인 ‘산둥루캉하오리요우’를 설립해 대장암 진단키트 상업화를 추진 중이며, 2024년 3월에는 리가켐바이오 지분 25.73%를 인수해 ADC 신약 플랫폼 사업에 진출했다. 리가켐바이오는 23개의 파이프라인을 보유·개발 중이며 글로벌 제약사와 약 10조 원 규모의 기술수출 계약을 체결한 바 있다.업계에서는 오리온그룹이 제과 사업에서 창출한 현금을 지주로 끌어올린 뒤 바이오 등 신사업에 재투자하는 현금 순환 구조를 강화하고 있다고 분석하고 있다. 오리온과 오리온홀딩스는 이달 11일 주당 배당금을 지난해 대비 각각 40%, 37% 늘어난 각각 3500원, 1100원으로 의결했다. 오리온홀딩스는 오리온 지분 약 37%를 보유한 최대주주로, 지난해 오리온으로부터 수령한 배당 수익(369억 원), 상표권 사용 수익 등은 총 487억 원에 달한다. 식품업계 한 관계자는 “합작법인을 넘어 핵심 기술 보유사까지 직접 투자한 것은 단순 재무적 투자를 넘어 전략적 지배력을 강화하려는 움직임으로 볼 수 있다”고 말했다.', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004593920', 'https://imgnews.pstatic.net/image/011/2026/02/26/0004593920_001_20260226234618311.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-26 16:36:07', 0, true, '2026-03-09 05:52:29.436578') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (756, '오리온, 허인철 부회장 사내이사 재선임…5연임 앞둬', '국세청 출신 이현규 대표 사외이사 선임[서울=뉴시스] 오리온 글로벌 대표 제품 모습.(사진=오리온 제공) *재판매 및 DB 금지[서울=뉴시스] 이혜원 기자 = 오리온은 다음달 26일 서울 용산구 문배동 본사에서 정기주주총회를 열고 허인철 오리온홀딩스 및 오리온 부회장을 사내이사로 재선임한다고 25일 공시했다.1960년생인 허인철 부회장은 신세계그룹 경영전략실, 이마트 대표이사를 거쳐 2014년부터 오리온을 이끌고 있다.오리온은 이와 함께 국세청 출신인 이현규 세무법인 아림 대표를 사외이사로 선임할 예정이다.1964년생인 이현규 대표는 부산지방국세청 조사2국장, 국세청 국세공무원교육원장, 인천지방국세청장 등을 지냈다.오리온은 또 송찬엽 법무법인 광장 변호사를 사외이사로 재선임한다.', NULL, '뉴시스', 'https://n.news.naver.com/mnews/article/003/0013788330', 'https://imgnews.pstatic.net/image/003/2026/02/25/NISI20260205_0002056797_web_20260205120627_20260225165031130.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-25 16:49:58', 0, true, '2026-03-09 05:52:29.436578') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (757, '“주식 들고만 있어도 수익 기대감”…유통家, ‘자사주 소각’ 띄우고 배당 확대', '잠잠했던 주주들의 계좌에 모처럼 반가운 소식이 전해졌다. “기업만 배 불린다”는 비판을 받던 유통 공룡들이 앞다투어 금고를 열기 시작했다. 단순히 배당금을 조금 얹어주는 수준을 넘어, 주식 수를 줄여 주당 가치 개선 효과를 노리는 ‘자사주 소각’ 카드까지 꺼내 들었다.게티이미지뱅크21일 업계에 따르면 가장 적극적인 행보를 보이는 곳은 현대백화점그룹이다. 현대지에프홀딩스와 현대홈쇼핑은 지난 11일 이사회를 통해 530억원 규모의 현대홈쇼핑 자사주(지분 약 6.6%)를 즉시 소각하기로 의결했다. 주식 교환이 완료되면 현대홈쇼핑은 상장 폐지돼 지배구조가 단순해진다.진짜 ‘빅뱅’은 그룹 차원의 결단이다. 현대백화점, 한섬, 리바트 등 계열사 10곳이 보유한 자사주 전량을 소각하기로 했다. 10일 종가 기준 약 2100억원 규모다. 이 작업이 끝나면 그룹 내 13개 상장사 전체가 자사주 ‘제로’ 상태가 된다. 주주 입장에서는 주당 가치 개선 효과를 기대할 수 있는 대목이다.전통의 유통 강자들도 배당 확대에 가세했다. 이마트는 주당 최소 배당금을 2000원에서 2500원으로 25% 올렸다. 여기에 발행주식의 2%에 달하는 자사주 소각도 매년 이어가며 약속을 이행 중이다.식품업계 ‘배당 대장’으로 떠오른 오리온의 행보도 눈에 띈다. 주당 배당금을 2500원에서 3500원으로 40% 높였다. 지주사인 오리온홀딩스의 시가배당률은 5% 수준으로, 최근 주요 시중은행 정기예금 금리 수준을 상회한다. 롯데쇼핑 역시 상장 이후 처음으로 중간배당을 도입하며 연간 배당금을 4000원까지 끌어올렸다. 배당성향 40% 이상을 유지하며 정부의 고배당기업 기준을 충족했다.동원산업도 배당 확대 기조를 명확히 했다. 결산 배당금을 600원으로 확정했다. 특히 지난해 포괄적 주식 교환 과정에서 발생한 자사주 7137주를 전량 소각하며 주주 가치 제고 의지를 보였다. 코웨이는 2027년까지 주주환원율 40%를 유지하겠다는 방침과 함께 사외이사 비중을 67%까지 확대하고 독립이사 제도를 신설하는 등 지배구조 개선 계획도 내놨다.', NULL, '세계일보', 'https://n.news.naver.com/mnews/article/022/0004107291', 'https://imgnews.pstatic.net/image/022/2026/02/21/20260221503148_20260221082110023.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-21 08:21:10', 0, true, '2026-03-09 05:52:29.436578') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (758, '''진격의 코스피'', 장중 5500 돌파…강한 고용지표에도 美 증시 하락', '[앵커]최근 며칠 등락을 반복하며 숨을 고르던 코스피가 오전 계속해서 고점을 높이면서, 역대 최고치 경신은 물론이고 5400선과 5500선을 연달아 뚫었습니다.특히 대장주 삼성전자가 6% 넘는 급등세를 보여 증시를 이끄는 모습입니다.김종윤 기자, 코스피가 실시간으로 고점을 높이고 있는데 현재 어떻습니까?[기자]코스피는 5425로 5400선을 넘긴 후에도 상승폭을 빠르게 키워 장중 5500선 마저 사상 처음 돌파했습니다.코스닥은 1122에 상승세로 문을 열었지만 현재는 1110선에서 강보합세를 보이고 있습니다.코스피에선 외국인과 기관이 각각 1조 3천억 원과 9천 9백억 원 넘게 순매수하며 지수를 끌어올리고 있습니다.반면 개인은 2조 3천억 원 이상 순매도하며 설 연휴를 앞두고 오늘(12일)도 적극적으로 차익을 실현하고 있습니다.삼성전자는 5% 넘게 급등해 사상 처음 ''17 만전자''에 올라섰고, SK하이닉스도 3% 이상 상승했습니다.한미반도체는 10% 이상 급등하고, SK스퀘어도 5% 넘게 오르는 등 반도체 관련주도 동반 강세입니다.한투증권이 업계 최초 영업이익과 순익 모두 ''2조 클럽''에 입성한 한국금융지주는 신고가를 기록했습니다.배당금을 전보다 40% 늘린 오리온홀딩스와 작년 영업이익이 전년 대비 48% 증가한 카카오도 올랐습니다.어제(10일) 급등했던 LG전자는 차익실현 매물에 5%대 급락 중입니다.달러-원 환율은 어제보다 1.5원 내린 1448.6원에 거래를 시작해 나흘 연속 하락하면서 1440원 초반에서 거래되고 있습니다.[앵커]간밤 뉴욕증시는 흔들렸죠?[기자]강한 고용지표에도 금리인하 기대가 줄면서 뉴욕증시는 약보합으로 장을 마쳤습니다.다우와 나스닥 지수는 각각 0.13%와 0.16% 소폭 하락했습니다.AI투자를 위해 회사채 발행을 늘리는 알파벳과 MS, 아마존 등 빅테크들은 국채금리 상승에 2%가량 하락했습니다.반면 UBS가 목표주가를 올린 엔비디아와 브로드컴은 1%가량 올랐습니다.경기둔화 우려에 어제 하락했던 월마트는 강한 고용지표 발표 후 1.6% 상승했습니다.SBS Biz 김종윤입니다.당신의 제보가 뉴스로 만들어집니다.SBS Biz는 여러분의 제보를 기다리고 있습니다.홈페이지 = https://url.kr/9pghjn', NULL, 'SBS Biz', 'https://n.news.naver.com/mnews/article/374/0000492329', 'https://imgnews.pstatic.net/image/374/2026/02/12/0000492329_001_20260212115815654.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-12 11:37:09', 0, true, '2026-03-09 05:52:29.436578') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (759, '곳간 연 K-푸드·유통가, ''역대급 돈 보따리''에 개미들 웃음', '실적 대박에 배당금 확대, 자사주 소각 등 ''밸류업'' 총공세''주주 친화 정책''에 주가도 상승 흐름…"선택 아닌 필수"오리온그룹은 11일 이사회를 열고, 사업회사인 오리온과 지주사인 오리온홀딩스의 총 배당 규모를 지난해보다 577억원 증가한 2046억원으로 의결했다. 오리온그룹은 주주가치 제고를 위해 주주환원 정책을 대폭 강화하겠다는 설명이다. /오리온[더팩트ㅣ유연석 기자] 정부의 ''기업 밸류업(가치 제고)'' 프로그램이 본격 가동된 가운데, 식품·유통업계가 역대급 주주 환원 정책을 쏟아내고 있다. 글로벌 시장에서 실적 ''대박''을 터뜨린 식품 기업들은 곳간을 열어 이익 공유에 나섰고, 만년 저평가에 시달리던 유통 공룡들은 자사주 소각과 구조 개편이라는 강수를 두며 주주 달래기에 나섰다.◆ ''잘 번 만큼 돌려준다''…K-푸드, 실적 기반 배당 확대12일 관련 업계에 따르면 가장 눈에 띄는 곳은 K-푸드 열풍의 주역인 식품업계다. 해외 시장에서의 폭발적인 성장이 주주 환원 확대로 이어지는 선순환 구조가 자리를 잡은 모습이다.오리온그룹은 주주 가치 제고를 위해 배당 규모를 대폭 키웠다. 오리온은 전날 이사회를 열고 주당 배당금을 지난해 2500원에서 40% 늘린 3500원으로 결정했다. 지주사인 오리온홀딩스 역시 37% 늘어난 1100원을 배당하기로 했으며, 시가 배당률은 시중 금리를 상회하는 5%에 달한다. 이는 글로벌 사업 호조로 연결 기준 매출이 7.3% 성장하는 등 탄탄한 실적이 뒷받침됐기에 가능했다.''불닭볶음면'' 신화를 쓰고 있는 삼양식품의 행보는 더욱 파격적이다. 창사 이래 처음으로 매출 2조원을 돌파한 삼양식품은 올해 결산 배당금 2600원을 포함해 연간 총 4800원을 배당하기로 했다. 전년(3300원) 대비 45.4% 증가했으며 10년 전인 2016년(150원)과 비교하면 무려 3000% 이상 급증한 수치다. 연결 기준 배당 성향은 9~11%로 타 식품업체(약 20% 이상) 대비 낮다는 지적도 있지만, 삼양식품 측은 투자 확대를 통해 성장을 이어가면서 배당금 규모를 지속 키워가겠다는 방침이다.현대백화점그룹은 그룹 내 13개 상장사가 보유한 총 3500억원 규모의 자사주를 전량 소각하며 주주환원 정책을 강화하기로 결정했다. /현대백화점그룹◆ ''저평가 탈출 사활''…유통가, 자사주 태우고 배당 성향 높이고성장 정체 우려로 주가가 눌려있던 유통업계는 정부의 밸류업 기조에 맞춰 체질 개선과 환원 정책을 동시에 추진하고 있다.현대백화점그룹은 ''자사주 제로(Zero, 0)''를 선언하며 가장 공격적인 행보를 보였다. 그룹 내 13개 상장사가 보유한 총 3500억원 규모의 자사주를 전량 소각하며 주주환원 정책을 강화하기로 결정한 것이다. 또한 지주사 현대지에프홀딩스와 현대홈쇼핑 간의 주식 교환을 통해 현대홈쇼핑을 완전 자회사로 편입, 상장 폐지함으로써 모자 회사 동시 상장에 따른 중복 상장 이슈까지 해소하겠다는 계획을 내놨다.이마트 역시 주주와의 약속을 이행하며 신뢰 회복에 나섰다. 이마트는 주당 최소 배당금을 기존 2000원에서 2500원으로 25% 상향 조정하고, 발행 주식 수의 2%에 달하는 자사주를 소각하겠다는 계획을 실행에 옮기고 있다. 지난해 4이는 실적 부진 속에서도 주주 가치를 방어하겠다는 경영진의 강력한 의지가 반영된 결과다.◆ 반도체 쉴 때 달리는 내수주…옥석 가리기 본격화이러한 주주 환원 강화 움직임은 주가 흐름도 바꿔놓았다. 최근 반도체 등 수출 대형주가 주춤하는 사이, 밸류업 모멘텀을 탄 내수주들은 가파른 상승세다. 실제로 2월 들어 ''KRX필수소비재 지수''는 약 8% 상승해 코스피 상승률을 크게 웃돌았다.유통업계 한 관계자는 "실적 성장세에 걸맞은 보상이 따르지 않으면 자본시장에서 외면받을 수 있다는 위기감이 기업들 사이에서 공통적으로 감지된다"며 "이익의 과실을 투명하게 공유하는 주주 친화 정책은 이제 선택이 아닌 필수이며, 자산 가치가 재평가되고 있는 유통·식품주를 중심으로 이 같은 환원 기조가 더욱 가속화될 것"이라고 내다봤다.결국 이번 배당 확대 물결은 단순한 현금 뿌리기를 넘어, 한국 증시의 고질적인 문제였던 낮은 주주 환원율을 개선하고 기업 가치를 재평가받으려는 거대한 변화의 시작점이라는 분석이다.발로 뛰는 더팩트는 24시간 여러분의 제보를 기다립니다.▶카카오톡: ''더팩트제보'' 검색▶이메일: jebo@tf.co.kr▶뉴스 홈페이지: http://talk.tf.co.kr/bbs/report/write', NULL, '더팩트', 'https://n.news.naver.com/mnews/article/629/0000472307', 'https://imgnews.pstatic.net/image/629/2026/02/12/202688781770860832_20260212110311685.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-12 11:03:11', 0, true, '2026-03-09 05:52:29.436578') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (760, '[ET특징주]오리온, 배당금 확대 소식에 상승세', '오리온이 배당금 확대 소식에 상승세다.오리온(271560)은 2월 12일 오전 10시 38분 기준 전 거래일보다 6.31% 상승한 138,200원에 거래되고 있다.전날 오리온그룹은 이사회에서 사업회사인 오리온과 지주사인 오리온홀딩스의 현금배당을 의결했다고 밝혔다. 오리온은 주당 배당금을 지난해 2500원에서 40% 늘린 3500원으로 결정했다. 총배당금은 1384억원이다.오리온홀딩스는 주당 배당금을 지난해 800원에서 37% 증가한 1100원으로 확정했다. 총배당금은 662억원으로 시가배당률은 시중 금리보다 높은 5% 수준이다. 올해 오리온그룹의 총배당 규모는 지난해보다 577억원 증가한 2046억원으로 확대됐다.증권가는 오리온의 목표주가를 상향하고 있다. KB증권은 오리온의 목표주가를 기존 14만원에서 15만원으로 상향했다. 류은애 KB증권 연구원은 “목표주가 상향은 위안화 강세와 베트남 내수 소비 반등을 반영해 2026년 실적 추정치를 상향 조정했기 때문”이라고 밝혔다.이원지 기자 news21g@etnews.com', NULL, '전자신문', 'https://n.news.naver.com/mnews/article/030/0003398965', 'https://imgnews.pstatic.net/image/030/2026/02/12/0003398965_001_20260212104415689.gif?type=w800', 'NEWS_ETC', NULL, '2026-02-12 10:44:15', 0, true, '2026-03-09 05:52:29.436578') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (761, '오리온, 주주환원 강화… 배당금 40% 확대', '오리온그룹이 주주가치 제고를 위해 주주환원 정책을 대폭 강화한다.오리온그룹은 이사회에서 사업회사인 오리온과 지주사인 오리온홀딩스의 현금배당을 의결했다고 11일 밝혔다.오리온은 주당 배당금을 지난해 2500원에서 40% 확대된 3500원으로 결정했다. 총 배당금은 1384억원이다.오리온홀딩스는 주당 배당금을 지난해 800원에서 37% 늘어난 1100원으로 확정했다. 총 배당금은 662억원이다.오리온그룹의 총 배당 규모는 지난해보다 577억원 증가한 2046억 원이다. 정부가 자본시장 활성화를 위해 지난달 도입한 배당소득 분리과세 적용 대상인 고배당기업 요건도 충족했다.오리온의 연결기준 배당성향은 지난해 26%에서 10%p 높아진 36%, 오리온홀딩스는 지난해 30%에서 25%p 높아진 55%이다.오리온은 지난해 6월 공시한 ''기업가치 제고 계획''에서 배당성향 20% 이상 배당정책 이행, 향후 3개년 배당성향 점진적 상향, 중간배당 검토 등 주주환원 강화 정책을 밝힌 바 있다.', NULL, '파이낸셜뉴스', 'https://n.news.naver.com/mnews/article/014/0005477348', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2026-02-11 18:16:22', 0, true, '2026-03-09 05:52:29.436578') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (762, '에이텀 자회사 청한전자…MLCC 슈퍼사이클 수혜주 부각', '인공지능(AI) 서버 및 데이터센터 투자가 급증하면서 ''산업의 쌀''로 불리는 MLCC(적층세라믹콘덴서) 시장이 슈퍼사이클 국면에 진입했다. MLCC는 AI 서버의 고전력·고집적 구조 확산에 따라 일반 서버 대비 탑재량이 크게 늘어나는 대표적 수혜 부품으로 꼽힌다.주식시장에서는 MLCC 수혜주 찾기가 이어지는 가운데, 코스닥 상장사 에이텀의 자회사 청한전자가 실적과 공급망을 갖춘 기업으로 부각되고 있다.3일 증권업계에 따르면 최근 MLCC 관련 기업인 삼성전기, 삼화콘덴서, 아모텍, 코칩, 지아이에스 등의 주가는 두 자릿수 상승률을 기록했다. 글로벌 빅테크의 AI 투자 확대에 힘입어 반도체 업종이 강세를 보이는 가운데, 수요 확대 흐름이 MLCC 등 전력 안정화 부품으로 확산하는 모습이다.이 같은 업황 속에서 에이텀이 지분 60%를 보유한 핵심 종속회사 청한전자는 MLCC 전문 유통 및 기술 지원 사업에 집중하며 안정적인 실적을 이어가고 있다. 청한전자의 매출은 2024년 272억원, 2025년 312억원으로 증가했다. MLCC 수급이 점차 타이트해지는 올해는 330억원 이상 매출 달성도 가능할 것으로 전망된다.업계 관계자는 "MLCC 수급이 타이트해질수록 전문 유통사의 공급 수행 능력이 실적과 직결될 가능성이 높다"고 분석했다.MLCC 산업은 높은 기술적 진입장벽과 함께 ''공급망 확보''가 핵심 경쟁력으로 꼽힌다. 1989년 설립된 청한전자는 올해로 36년의 업력을 보유하고 있으며, 삼성전기와 무라타 등 글로벌 톱티어 MLCC 벤더들과 장기간 네트워크를 구축해 왔다. 단순 유통을 넘어 설계 대응과 양산 연계 지원 체계까지 갖춘 점이 특징이다.MLCC는 전기를 저장했다가 일정량씩 방출하는 역할을 한다. 회로에 전류가 일정하게 흐르도록 조절하고 부품 간 전자파 간섭을 줄여주는 핵심 부품이다. 최근에는 AI 서버와 전장(차량용 전자·전기장비) 등 고성능·고신뢰 분야로 적용 영역이 확대되고 있다. 특히 AI 서버 1대에 탑재되는 MLCC는 약 3만개 수준으로, 일반 서버 대비 수십 배 이상 많은 것으로 전해진다.특히 MLCC 업계에서 청한전자가 주목받는 이유는 과거 위기관리 경험에 있다. 청한전자는 2018~2019년 글로벌 MLCC 품귀 당시 단기 수익 확대보다 제조사와의 전략적 협력을 택했고, 확보한 물량을 고객사에 적기 공급하며 신뢰를 구축했다는 평가를 받는다.업계 관계자는 "MLCC는 쌀 한 톨 크기의 250분의 1 수준, 0.3mm 두께 내부에 수백 개의 층을 정밀하게 적층해야 하기 때문에 고도의 기술력이 요구된다"며 "공급난을 거치며 경쟁력을 입증한 기업일수록 AI발 수요 확대 국면에서도 강점을 보일 가능성이 높다"고 설명했다.청한전자의 성장세는 모회사 에이텀의 기업가치 재평가 기대를 높이고 있다. 에이텀은 청한전자의 고부가 MLCC 공급망을 기반으로 고효율 파워모듈 기술을 고도화하고 있으며, 이를 전략적 파트너 글로벌탑넷의 AI 서버 플랫폼에 적용하고 있다. 부품?모듈?시스템으로 이어지는 구조를 통해 AI 인프라 시장 내 사업 영역을 확대하고 있다.증권업계에서는 에이텀의 현재 주가가 청한전자의 MLCC 매출 규모와 성장성을 충분히 반영하지 못하고 있다는 평가도 나온다.에이텀 관계자는 "MLCC 수요 확대에 따른 청한전자의 성과가 연결 실적에 반영될 것"이라며 "제조사 협력 강화와 전략적 재고 운영을 통해 안정적인 성장 기반을 구축해 나가겠다"고 밝혔다.', NULL, '아시아경제', 'https://n.news.naver.com/mnews/article/277/0005728113', 'https://imgnews.pstatic.net/image/277/2026/03/03/0005728113_001_20260303081715487.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-03-03 08:15:48', 0, true, '2026-03-09 05:52:50.425799') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (763, '[증시 인사이트] 최근 한달 새 반도체 투톱에만 자금 7.5조 원 몰려', '■ 머니쇼+ ''증시 인사이트'' - 김윤정 LS증권 연구원, 이지은 이지스탁 대표오늘(25일) 장 초반부터 6000선을 돌파한 코스피, 어느새 6100선까지 넘어섰습니다. 매일 놀라운 흐름을 이어가고 있어요. 5000선을 넘어선 지 한 달여 만에 6000선도 돌파했는데요. 변동성과 유동성이 번갈아 가며 작용하는 듯합니다. 우리 시장, 어떻게 봐야 할지 투자 전략 세워보겠습니다. LS증권 김윤정 연구원, 이지스탁 이지은 대표 모셨습니다.Q. 오늘 장 우리 증시 개장부터 마감까지의 흐름, 어떻게 보셨습니까?- 코스피 사상 첫 6000선…"꿈 넘어 새 역사 기록"- 코스피, 장중 5천 선 넘은 지 한 달 여 만에 6천 선- 코스피, 사상 처음으로 종가 기준 6100선 돌파- 코스피 고공행진에 축포와 함께 ''버블 경고음''도- 삼성전자·SK하이닉스, 나란히 오늘 ''신고가'' 경신- 코스피, 오늘 사상 최초 6천 선·시총 5천조 원 돌파- 20일 기준 대차거래잔고 153조 원…"단기급등 경고"- 엔비디아, 우리 시간 기준 26일 오전 실적 발표 예정- 블룸버그 "엔비디아에 대한 시장 기대치 천장에"- 월가 "엔비디아 4분기 매출 전년비 60%↑ 전망"- 노무라 "올해 상반기 코스피 8000까지 갈 수 있어"- 美하원 스튜비 의원 ''중국산 ESS 수입 금지법'' 발의- 일부 언론 "美, 중국산 ESS 전면차단 움직임 보여"- 미국의 중국산 ESS 제재…K- 배터리 반사이익 기대감- 업계 "중국산 ESS 제재, CATL·BYD 정조준"- AI 데이터센터 수요로 전력 소비 따라 ESS 설치량↑- LG엔솔, 지난해 美서 ESS용 LFP배터리 양산- LG엔솔, 한화솔루션과 ESS 파트너십…美 시장 공략- 삼성SDI, 美 에너지기업에 ESS용 LFP배터리 공급- SK온, 지난해 美 재생에너지 기업서 ESS 수주- 트럼프 ''상호관세'' 무효에도 2차전지는 관세 25%- LG엔솔·삼성SDI·SK온, 미국 내 생산시설 보유- 미국 내 생산시설 확보…국내 배터리 기업 경쟁력↑- K- 배터리, 인력 줄이고 자산 매각…고강도 자구책- 전기차 캐즘·中 저가공세…K- 배터리 실적 ''쇼크''- 반도체 이어 원전·방산·2차전지 랠리…순환매 확대- 트럼프, 집권 2기 첫 국정연설…"관세 정책 그대로"- 트럼프, 2기 첫 국정연설서 "지금이 美 황금시대"- 트럼프 "이란 핵 절대 불가"…군사 대응 압박 강화- 트럼프 "교역국, 우리와 한 무역 합의 유지 원해"- 트럼프, 대법원 보란 듯 "관세가 소득세 대체해"Q.코스피가 6천 선을 돌파하고 엄청난 강세를 보이는 데 가장 크게 기여한 업종이 바로 반도체, 특히 반도체 투톱인 듯합니다. ''20만전자'', ''100만닉스''와 함께 ''6천피''도 현실화됐고 가보지 않았던 새로운 길을 계속 나아가는 상황인데 오히려 불안이나 의구심은 없는 느낌이에요?- 최근 한달 새 반도체 투톱에만 자금 7.5조 원 몰려- 코스피 5천 선 돌파 후 개인 반도체 투톱 순매수↑- 증권가 "HBM4 경쟁력 회복돼 재평가해야 할 시점"- 삼성전자·SK하이닉스, ''코스피 6천 시대'' 견인 주역- 반도체 투톱 중심 개인 매수세↑…이외 종목은 매도- 블랙록, 하이닉스 지분 5% 보유…외인 자금 유입↑- 메모리 가격 상승 기대…삼전·하이닉스 주가에 반영- 증권가 "빅테크 투자 확대…서버용 메모리 수요↑"- 평균판매가, 범용D램 150%·낸드 90% 상승 가능성- 반도체 메가 사이클…삼성전자·하이닉스 ''초강세''- SK하이닉스 올해 영업익 185조 원 전망도 등장Q.최근 주목받았던 MLCC 관련주, 특히 삼성전기는 오늘 장에서도 강세를 보였고, 증권가도 목표가 상향에 나섰습니다. 무라타가 가격 인상을 고려 중이라는 소식 때문인 데다 AI발 슈퍼사이클 수혜가 기대된다는데, 그래서인지 유독 삼성전기만 잘 가는 느낌이에요? 반도체 소부장 중에서도 장비주의 대표 격인 한미반도체와 한화비전, 오늘은 엇갈린 흐름을 보였습니다. 어제(24일) 한화비전이 유독 강세를 보인 것은 ''삼성전자가 발주를 할 수도 있다''라는 일부 언론의 보도 때문인 듯한데, 확실한 뭔가가 나와줘야 할 듯해요? 최근 MLCC 관련주로 주목받았던 지아이에스나 삼화콘덴서, 오늘은 조정을 받는 모습이었습니다. MLCC 관련주로는 삼성전기만 보는 게 맞는 걸까요? 특별히 조정받은 이유가 있을까요?- 삼성전기, 오름세 지속…"MLCC 가격 인상 가능성"- AI용 MLCC 가격 인상 시 삼성전기 실적에 긍정적- 무라타, MLCC값 인상 검토…"수요 대비 공급 부족"- 쏟아지는 MLCC 주문에 삼성전기 공장 ''풀 가동''- 메릴린치 "한미반도체 TC본더 독주체제 굳힐 것"- 메릴린치, 한미반도체 목표주가 30만 원으로 상향- TC본더, HBM 공정서 열·압력으로 칩 적층 및 접착- KB證 "삼성전기, AI발 슈퍼사이클 수혜 기대"- KB證 "다중적층세라믹콘덴서 슈퍼사이클 진입"- MLCC 수요처, IT 기기에서 AI 서버·전장으로 확대- 마이크로·미니LED 시장 개화…핵심 장비주 주목- MLCC, 안정적이고 일정하게 전류 흐르도록 제어- AI 서버, 전압 제어必…고용량·고적층 MLCC 필요Q.오늘 장에서 현대차, 기아 등 현대차그룹주들이 대부분 상승세를 보였습니다. 피지컬AI, 미국 내 생산 호조에 주목받으며 현대차가 진행하는 사업 관련 업종에도 좋은 기운을 퍼뜨린 느낌이에요? 특히 수소 부문 사업은 현대차그룹이 꾸준히 추진하긴 했어도 뚜렷한 성과가 없는가 싶기도 했거든요. 캐나다 잠수함 사업 수주 지원을 위해 이번에 빛을 보는 게 아닌가 기대하게 되는 듯해요?- 현대차·기아 "관세 우리가 낸다"…미국서 정면돌파- 현대차그룹, 지난해 美 점유율 11.3%…"역대 최고"- 현대차·기아, 유럽 현지화 전략 및 라인업 확대- 현대차 "유럽 수요 대응 위해 맞춤형 전략 구사"- 현대차, 5년 간 125조 원 투입 "피지컬AI 체계 구축"- 현대차그룹의 미래 모빌리티 핵심 축 ''로보틱스''- 현대차, 산업 생태계 ''로봇 중심 재편'' 의지 확고- 현대차, 새만금에 10조 원 투자…신사업 단지 건설- 현대차, 아트리아AI 중심 자율주행기술 고도화 추진- 박민우 본부장 "R&D본부와 협업 강화…원팀 돼야"- 현대차그룹, 캐나다에 수소연료전지 인프라 제안- 현대차, 캐나다 정부와 수소 인프라 관련 협의 중- 현대차그룹 "캐나다와 다양한 협력 기회 검토 중"- 캐나다 차세대 잠수함 수주전, 팀 코리아 VS 독일- 현대차그룹, 美 메타플랜트에 아틀라스 투입 계획Q.현대차 대비 덜 오르는가 싶던 기아, 오늘은 강세를 보이며 52주 신고가를 경신했습니다. 미국 조지아 공장의 500만대 생산 돌파가 호재로 작용했다는 평인데, 기아는 현대차에 비해 철저히 전통차 기업으로 보는 게 맞는 걸까요? 현대차그룹 성 김 사장이 대미투자법 신속 처리를 촉구했다는 소식도 현대차그룹의 주가 오름세에 긍정적 영향을 미쳤다는 평도 있습니다. 이 부분에 대해서는 어떻게 보세요?- 기아, 보스턴 다이내믹스 지분 16.7% 보유 중- 기아, SW 중심 자동차(SDV)로의 전환 기대감- 기아 美 조지아 법인 누적 생산 500만 대 달성- 증권가, 현대차 이어 기아 목표주가도 줄상향- 흥국證 "피지컬AI 모멘텀, 기아 소외될 이유없어"- 美 메타플랜트, 현대차·기아의 공동 생산 거점- "관세 압박 우려"…현대차, 대미투자법 처리 촉구- 성 김 "트럼프, 車 등 특정산업 관세 인상할 수도"- 성 김 "지난해 美 관세로 7.2조 원의 재무적 타격"- 美 연방대법원 "트럼프 행정부의 상호관세는 위법"- iM證 "트럼프 관세 정책 구조적 약화…증시에 호재"- 美 "현지시간 24일, 글로벌 관세 일단 10% 발효"- 백악관 "글로벌 관세 15%로 올리는 작업 진행 중"- 美 ''국가안보 관세'' 추진…배터리·전력망 등 겨냥Q.최근 건설주들도 좋은 흐름을 보이고 있습니다. 부동산 관련이 아닌 원전 수주 기대감 때문인 듯한데요. 오늘 건설주들은 원전 대표주들보다 강세를 보인 듯합니다. 단순히 원전 수주 기대감 때문이라고 봐야 할까요?- 경주, SMR 유치 추진…정부 원전 정책 확대 기대감- 최근 2월 임시국회 본회의서 ''SMR 특별법'' 통과- SMR 특별법, 지난 2년간 표류 끝 국회 본회의 통과- 원전 업계 "SMR 특별법 통과로 기술 개발 상용화"- 美, 노후 원전 교체·전력 수급 안정 추진 본격화- 글로벌 원전 산업 활성화…대규모 수주 기대감↑- 현대건설, 시공 경험 풍부…''UAE 원전'' 성공 주역- 현대건설, 웨스팅하우스와 대형 원전 협력 관계- 한화證 "현대건설, 포함 대규모 수주 쏟아질 전망"- 올해, 데이터센터·해상 풍력 등 대규모 수주 기대- 한화證 "현대건설 수주전망, 지나치게 보수적"- 건설사, ''출혈경쟁'' 피하자며 정비사업 수주 ''신중''- 건설업도 로봇 바람…외벽 도장부터 사각지대까지- 한국- 튀르키예, 신규 원전 협력 구체적 방안 논의Q.국회에서 AI 데이터센터 지원에 관한 특별법 제정안이 법안심사소위원회에 상정됐고, 업계에서는 촉각을 곤두세우고 있는데요. 그 기대감 때문인지 오늘 장에서 전선주들이 급등세를 보였어요? 그렇다면 건설주들이 오른 것도 원전주 때문이 아닌, 국내 AI 데이터센터 추진 기대감 때문에 올랐다고 봐도 되는 걸까요?- AI 데이터센터 지원에 관한 특별법, 법안소위 상정- AI 데이터센터 특별법, 쟁점은 전력 직접거래 허용- AI 데이터센터 특별법, 전력계통영향평가 특례 주목- AI 데이터센터 특별법, 절차 간소화·지원책 등 포함- 美 등 주요국, GW급 데이터센터 전력 확보 나서- AI 데이터센터 특별법 통과 시 인프라 투자 환경 개선- AI 데이터센터 특별법 논의에 전선주 강세 보여- 전력 인프라 수요 확대 기대감…''전선주'' 주목- 주요국 노후화된 전력망 교체 흐름…전선주 수혜- 전선 업황, 수년간 지속될 구조적 성장기에 진입- 증권가 "전력기기주, 호황의 끝이 안 보이는 상황"- LS전선·대한전선, 지난해 사상 최대 수준 실적- 전력 인프라 투자 확대…초고압·해저케이블 주목Q.3차 상법개정안이 국회 본회의 처리를 앞두고 있습니다. 오늘 오후 표결을 진행할 예정이라고 하는데요. 기업들은 자사주 소각을 서둘러야 하는 상황이 됐지만, 그래도 증시와 개인 투자자들에게는 긍정적일 수밖에 없는 듯해요?- 지난 20일, 국회 법제사법위 ''3차 상법개정안'' 통과- 3차 상법개정안 골자, 신규 자사주 1년 내 소각必- 3차 상법개정안, 기존 보유 자사주 유예기간 6개월- 3차 상법개정안 시행 시 자사주 1년 6개월 내 소각必- 외국인 지분 법정 한도 있는 공공·방송·통신은 예외- 특수한 경우, 자사주 처분 계획 작성 후 주총 승인必Q.상법개정안 처리 여부도 주목해야 하지만 워낙 증시가 잘 가다 보니 오늘 장에서 대부분의 증권주도 흐름이 좋았습니다. 게다가 미래에셋증권은 지난해 자사주 소각과 더불어 4,600억 원 규모의 배당도 결정하면서 오름세를 보였습니다. 증권주는 ''강세장'' 영향에 주주환원책까지 함께 챙기며 봐야겠죠? 상법개정안 기대감에 증권주와 더불어 은행주, 보험주가 번갈아 오름세를 보이기도 했습니다. 그래도 금융주 중에서는 증권주가 제일 유효한 선택이라고 봐야 할까요?- 최근 상법개정안 기대에 증권·은행·보험주 오름세- 미래에셋증권, 4,600억 원 규모 배당 최종 결정- 미래에셋證, 지난해 주주환원 총 6,354억 원 진행- ''코스피 6000'' 불장 효과에 대부분 증권주 강세- 3차 상법개정안, 주식 소각 관련 감자 절차 간소화- 특정 목적으로 취득한 자사주, 이사회서 감자 가능- 자사주, 보유 기간 의결권·신주인수권 등 권리 배제- 3차 상법개정안, 신주 발행처럼 자사주도 균등 처분- 3차 상법개정안 통과 시 기업 경영권 위협 우려도- 야당, 적대적 M&A 방지 3법 발의…통과 여부 미지수- 적대적 M&A 방지 3법, 정부 추진 방침과 충돌(자세한 내용은 동영상을 시청하시기 바랍니다.)당신의 제보가 뉴스로 만들어집니다.SBS Biz는 여러분의 제보를 기다리고 있습니다.홈페이지 = https://url.kr/9pghjn', NULL, 'SBS Biz', 'https://n.news.naver.com/mnews/article/374/0000494398', 'https://imgnews.pstatic.net/image/374/2026/02/25/0000494398_001_20260225163609613.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-02-25 16:36:09', 0, true, '2026-03-09 05:52:50.425799') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (764, '''칠천피'' 꿈 아니네?…코스피, 올 들어 40% 올랐다', '삼성전자 88.8%·SK하이닉스 54.4%↑증권사 연일 목표치 상향…8000 전망도[서울=뉴시스] 정병혁 기자 = 24일 서울 중구 하나은행 딜링룸에 설치된 전광판에 코스피 등 시활 정보가 나타나 있다.이날 코스피는 전 거래일(5846.09)보다 123.55포인트(2.11%) 오른 5969.64에 마감했다.코스닥 지수는 전 거래일(1151.99)보다 13.01포인트(1.13%) 상승한 1165.00에 거래를 마쳤다.서울 외환시장에서 원·달러 환율은 전 거래일(1440.0원)보다 2.5원 오른 1442.5원에 주간 거래를 마감했다. 2026.02.24. jhope@newsis.com[서울=뉴시스] 박주연 기자 = 코스피가 연초 이후 40% 넘는 상승률을 기록하며 사상 유례 없는 랠리를 이어가고 있다.몇 달 전까지만 해도 ''꿈의 지수''로 불렸던 5000포인트가 견고한 하방 지지선으로 자리 잡고, 7000선 도달이 현실적인 목표로 다가오는 분위기다.25일 한국거래소에 따르면 코스피는 연초 이후 1755.47포인트 오르며 41.7%에 이르는 상승률을 나타냈다.지난해 말 4214.17로 장을 마쳤던 코스피는 지난달 22일 장중 5000선을 돌파했고, 3주 후인 지난 12일에는 5500선을 넘겼다. 지난 24일에는 5969.64로 장을 마무리, 6000선에 바짝 근접했다.코스피가 거침없이 질주하며 글로벌 투자은행(IB)과 국내 증권사들의 목표치도 연일 상승 중이다.노무라증권이 상반기 8000포인트를 목표치로 제시한 가운데 하나증권(7900), JP모건(7500), NH증권(7300), 키움증권(7300), 한투증권(7250) 등도 목표치를 7000포인트대로 잇따라 상향 조정했다.신디 박 노무라 연구원은 지난 23일 보고서를 통해 "2026년 상반기 코스피 목표치를 기존 전망 대비 대폭 상향한 7500~8000선으로 제시한다"고 밝혔다. 올해 예상 주가수익비율(PER) 12.0~13.0배, 주가순자산비율(PBR) 2.1~2.2배를 적용한 결과다.목표치 상향의 배경으로는 메모리 업종 이익 확대를 중심으로 한 일반 메모리 및 HBM 슈퍼 사이클, 인공지능(AI) 인프라 체인과 방산 업종의 이익 강세를 꼽았다.이재만 하나증권 연구원은 "반도체 업종의 주가수익비율(PER)은 6.7배로 2년 이상 연속으로 순이익이 증가하는 연도의 PER 고점 평균은 12.1배"라며 "반도체 업종의 12개월 예상 순이익에 해당 PER을 적용할 경우 이론적으로 현재 대비 74.8%의 주가 상승 여력이 있다"고 분석했다.이어 "해당 시나리오에서 코스피 장기 기대수익률은 43.1%로, 코스피 고점은 7870포인트로 높아진다"고 설명했다.코스피가 올 들어 40% 이상 오르는 가운데 가장 큰 폭의 상승세를 보인 종목은 우주테마와 증시랠리에 동시에 올라탄 미래에셋증권(187.37%)이었다.미래에셋증권 주가는 이 기간 2만3350원에서 6만7100원으로 3배 가까이 올랐다.뒤를 이어 SK증권(181.80%), 한전산업(140.40%), 한화갤러리아(125.51%), 현대지에프홀딩스(125.36%), 와이투솔루션(120.51%), SGC에너지(114.35%), 대우건설(112.30%), 삼화콘덴서(107.52%), 한화시스템(103.68%), SG세계물산(101.47%) 순이었다.코스피 시총 1·2위이자 반도체 투톱인 삼성전자와 SK하이닉스도 거센 상승세를 보였다.삼성전자는 11만9900원에서 20만원으로 88.8%, SK하이닉스는 65만1000원에서 100만5000원으로 54.4% 상승했다.업종별로는 증권, 건설, 전기전자 등의 오름세가 가팔랐다.국내 주요 증권사들을 담은 코스피 증권지수는 연초 이후 98.89% 상승, 두 배 가까이 올랐다. 코스피200 건설지수는 58.44%, 코스피 전기전자지수는 56.49% 각각 상승했다．', NULL, '뉴시스', 'https://n.news.naver.com/mnews/article/003/0013786003', 'https://imgnews.pstatic.net/image/003/2026/02/25/NISI20260224_0021185918_web_20260224160429_20260225061714591.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-02-25 05:00:00', 0, true, '2026-03-09 05:52:50.425799') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (765, '''롤러코스터'' 코스피 다시 5900 회복…''100만닉스'' 돌파', '[앵커]장 초반 미끄러지나 싶었던 코스피가 이내 상승으로 방향을 바꾸면서 5900선 탈환에 바짝 다가섰습니다.다만 외국인이 5 거래일째 주식을 팔고 있는 점은 부담 요인인데, 그럼에도 증시가 오르는 배경 짚어보겠습니다.김종윤 기자, 코스피 현재 흐름 어떻습니까?[기자]코스피는 5853에 상승 출발했지만 장 초반 5800선을 3 거래일만에 내줬습니다.하지만 코스피는 다시 수직 상승하며 5900선을 회복한 뒤 거래 중입니다.코스닥은 1159에 문을 연 뒤 1160선에서 상승하고 있습니다.코스피에선 외국인과 개인이 각각 1,000억 원과 1조 원 넘게 주식을 파는 가운데 오늘(24일)도 기관이 1조 1천억 원 이상 순매수하며 매도 물량을 받아내고 있습니다.뉴욕증시 AI 대형 기술주 하락에도 SK하이닉스는 장중 5% 넘게 급등해 100만 원을 터치했고, 삼성전자도 3% 이상 올라 20만 원을 향하고 있습니다.반면 트럼프 미 대통령의 관세 위협 여파에 현대차는 약보합, 기아는 강보합세입니다.미 의회가 중국산 ESS 에너지저장장치 수입차단을 추진하자 LG에너지솔루션은 반사이익 기대감에 반등하고 있고, 고부가 적층세라믹콘덴서 MLCC 품귀 현상에 삼화콘덴서도 강세입니다.달러-원 환율은 미 관세정책 혼선이 겹치면서 어제(23일)보다 4.7원 오른 1444.7원에 개장해 1,440원 중반에서 상승하고 있습니다.[앵커]특히나 현재 증시 상승은 앞선 뉴욕증시 하락을 딛고 이뤄졌다는 게 더 눈에 띄는데, 간밤 뉴욕은 어땠습니까?[기자]다우지수는 1.66%, 800포인트 넘게 급락했고, 나스닥과 S&P500 지수도 각각 1.13%와 1.04% 하락했습니다.AI 공포와 트럼프 관세 불확실성 확대가 빅테크 투매로 이어졌습니다.구독형 소프트웨어 중심 마이크로소프트는 AI로 서비스 대체될 우려에 3% 넘게 떨어졌습니다.컴퓨터언어 코볼을 현대적인 언어로 전환할 수 있다는 앤트로픽 발표에 IBM 주가 역시 13% 급락했습니다.자율주행 사망사고에 3천5백억 원을 배상하라는 법원 판결에 테슬라도 3% 가까이 하락했습니다.SBS Biz 김종윤입니다.당신의 제보가 뉴스로 만들어집니다.SBS Biz는 여러분의 제보를 기다리고 있습니다.홈페이지 = https://url.kr/9pghjn', NULL, 'SBS Biz', 'https://n.news.naver.com/mnews/article/374/0000493995', 'https://imgnews.pstatic.net/image/374/2026/02/24/0000493995_001_20260224113809794.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-02-24 11:37:10', 0, true, '2026-03-09 05:52:50.425799') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (766, '[이 시각 시황] K-배터리 ''반사이익'' 기대감…2차전지주 상승세', '■ 머니쇼 ''이 시각 시황'' - 장연재이 시각 시황입니다.상승 출발했던 국내증시 양대지수, 하락 전환되더니 낙폭을 조금씩 키우고 있습니다.코스피가 현재 0.4% 가까이 하락하면서 5825선, 코스피는 약보합 정도입니다.1,151포인트 정도에서 움직임 전개되고 있습니다.수급 상황 보시죠.유가 증권 시장에서 오늘 기관만 삽니다.외국인 현재 1,647억 원 팔아내고 있고요.반면 기관이 1,888억 원.2,500억 원 넘는 사자 포지션 취하고 있습니다.개인은 782억 원 매도 우위 기록하고 있습니다.코스닥 시장 보시죠.코스닥 시장에서는 개인이 사고 메이저 수급 주체 양매도가 나옵니다.외국인이 851억 원 팔아내고 있고, 기관 역시도 500억 원 가까운 매도 우위 기록하고 있습니다.개인만 홀로 1,383억 원 순매수하고 있습니다.등락률 상하위 업종입니다.현재 전기제품과 비철금속, 제약 업종이 상승률 상위권에 위치해 있습니다.반면 증권과 창업투자, 조선업종은 하락폭이 큰 것으로 집계됩니다.시장을 주도하는 테마 종목별 시세 체크하시죠.오늘 2차전지단이 강합니다.전고체 배터리 관련주가 상승합니다.이쪽에서는 한농화성이 12.5% 강세로 26,500원.삼성SDI가 5.5% 가까이 상승하며 413,000원에 거래되고 있습니다.씨아이에스와 레이크머터리얼즈가 4%대 강세고요.이수스페결티케미컬도 3.7% 오름세, 거래가 100,000원으로 집계됩니다.원격진료, 비대면 진료 관련주도 강세입니다.정부가 원격의료를 위해 별도의 ‘원격진료실’을 설치하도록 한 규제를 완화한다 한 소식에 영향을 받고 있습니다.정부는 인터넷 PC 등 장비를 갖춘 일반 외래진료실에서도 원격진료가 가능하도록 허용해 의료기관의 시설 부담을 줄이겠다는 방침입니다.이 소식에 비대면 진료 관련주 내에서는 나노엔텍이 상한가고요.네오펙트가 24.2% 시세 분출하고 있습니다.소프트센이 3.46% 오름세, 그 외의 인피니트헬스케어가 강보합 정도.인성정보, 보합권에서 움직임 보여주고 있습니다.에너지저장장치, ESS 관련주 오름세입니다.미국이 원격 모니터링 기능을 탑재한 중국산 에너지저장장치(ESS)의 수입 차단을 추진한다는 소식에 관련주 수혜 기대감이 커지고 있습니다.ESS 관련주 내에서는 삼화콘덴서가 17.2% 오름세, 거래가 66,800원이고요.이랜텍이 15.2% 오르면서 12,300원.한중엔시에스가 9.2% 강세로 50,400원대 거래되고 있습니다.또 지투파워가 두 자릿수 수익률 내고 있습니다.13.4% 강세로 13,210원.LS일렉트릭도 4% 오름세입니다.거래가 753,000원으로 집계되고 있습니다.전력설비 관련주가 강세 기록 중입니다.지속되는 인공지능(AI) 호황이 관련 부품 업계까지 온기가 퍼지며 전력설비 관련주들 주목받고 있습니다.전력 설비주 내에서는 비츠로시스가 22.6% 급등하고 있고요.지투파워가 13%대 강세 유지하고 있습니다.LS일렉트릭도 4.4% 오름세로 현재 거래가 754,000원이고요.LS마린솔루션도 3.8% 오름세, 32,900원.서남도 3.5% 가까운 오름세 기록하고 있습니다.당신의 제보가 뉴스로 만들어집니다.SBS Biz는 여러분의 제보를 기다리고 있습니다.홈페이지 = https://url.kr/9pghjn', NULL, 'SBS Biz', 'https://n.news.naver.com/mnews/article/374/0000493942', 'https://imgnews.pstatic.net/image/374/2026/02/24/0000493942_001_20260224093613059.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-02-24 09:36:12', 0, true, '2026-03-09 05:52:50.425799') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (885, '“정년연장, 성과·직무중심 개편 연계를” 경총, 고령자 계속고용 대응 전략 제시', '계속고용시대 맞춤 임금·직무재설계 필요日·싱가포르식 ‘하이브리드 재고용’ 제안한국경영자총협회(경총)는 ‘고령자 계속고용 시대, HR 재설계 전략’을 주제로 정기간행물 ‘임금·HR연구’ 2026년 상반기호(사진)를 발간했다고 3일 밝혔다.경총은 고령자 계속고용에 관한 사회적 논의가 본격화됨에 따라, 이번 ‘임금·HR연구’ 상반기호 특집주제를 ‘고령자 계속고용시대, HR 재설계 전략’으로 선정해 인사관리 대응 전략을 살펴보고 사례 분석을 통해 시사점을 제시했다고 밝혔다.주제발표를 맡은 최현진 콘페리 시니어파트너는 “경직된 고용구조, 직무와 무관한 다단계 직급구조와 정기 승진체계, 연공적 보상체계 등이 기업 생산성을 떨어뜨리는 상황에서, HR 체질 개선 없는 정년 연장은 고령화 시대에 더 큰 재앙으로 작용할 수 있다”고 진단했다.그러면서 “특히, 국내 기업들은 여전히 근무시간이나 업무강도 중심으로 평가하고 형평성을 중요하게 생각하는 경향이 강해 직무별 임금 차등이 매우 어려운 상황”이라면서 “직무별 차등이 빠른 시간 내 정착되기 어렵다면 성과 차등 비중을 늘려가야 한다”고 강조했다.사례연구에서는 고령자 재고용으로 정량적 성과를 창출한 일본ㆍ싱가포르 기업과 ‘일의 재설계’를 통해 고령 인력의 경쟁력을 유지해 온 영국 기업 사례를 살펴보고, 고령인력 활용 방안과 정책적 시사점을 제시했다. 또한 숙련·기능인력 공백을 메우기 위해 정년 후 재고용을 활용하는 국내 철강업계 사례도 함께 소개했다.김소현 퍼솔 코리아 전무는 “노동시장 성격이 다른 일본과 싱가포르에서 공통적으로 재고용 모델이 주류로 자리잡은 것은 결국 재고용 모델이 기업의 인건비 관리 유연성, 직무 재설계 가능성, 그리고 세대 간 역할 분담이라는 세 가지 핵심 요건을 동시에 충족했기 때문”이라고 분석했다.일본, 싱가포르 기업들의 재고용 활용 사례도 상세히 소개하면서 “우리나라도 재고용 중심 계속고용 모델이 가장 합리적인 대안”이라며 ”일본식 점진적 접근(단계적 의무화)과 싱가포르식 유연한 재고용 모델(임금·직무 재설계)을 결합한 하이브리드 재고용 전략이 가장 현실적 대안”이라고 제안했다.이재진 옥스퍼드대 연구교수는 ”고령자 계속고용이 실패하는 이유는 조직이 여전히 젊은 인력을 전제로 설계된 일을 요구하기 때문”이라고 지적하며, 영국 기업들이 고령인력을 어떻게 재배치하고 활용하고 있는지에 대해 소개했다.이상훈 TCC스틸 이사는 “대다수 철강기업은 정년을 60세로 유지하고 퇴직 인력에 대해 계약직·촉탁직 방식으로 1년간 재고용하는 방식을 여전히 선호하고 있다”며 “계속고용을 실질적으로 정착시키기 위해서는 성과와 역할에 기반한 합리적 보상 설계가 필수적”이라고 강조했다.연구논단에는 계속고용 시대 주목해야 할 HR 이슈를 세부적으로 살펴보고, HR 부문별 대응전략을 모색하기 위해 박상현 삼정KPMG P&C 이사와 김희봉 대한리더십학회 상임이사, 정순둘 이화여대 사회복지학과 교수, 김진실 한국스킬문화연구원 원장 등 네 필진의 글을 수록했다.특집논단은 이수영 고려대학교 고령사회연구원 특임교수가 세대간 상생을 위한 고용연장 정책의 방향과 구체적인 대안을 제시했다. 이 교수는 “일률적인 정년연장은 청년고용을 축소시키고, 기업 인건비 부담을 증가시키며, 대·중소기업간 이중구조를 심화시킬 가능성이 높다”고 지적했다.이어 이 교수는 “정년연장 제도 도입 시 취업규칙 불이익 변경 제한으로 임금조정이 어려워 대·중소기업 근로자 간에 양극화가 더욱 심화될 우려가 있다”며 “고용연장 제도, 특히 정년 연장은 반드시 임금체계 개편과 연계하도록 법률에 구체적 규정을 두어야 한다”고 제안했다.하상우 경총 경제조사본부장은 “연공 중심 인사·임금 관행과 경직된 역할 분담 구조를 개선하기 위한 HR 체계의 신속한 재설계가 요구된다”고 지적했다. 그러면서 “일본과 싱가포르처럼 기업이 임금과 직무를 합리적이고 유연하게 조정하고 다양한 선택지를 가질 수 있는 제도적 기반이 필요하다”며 “정년 연장은 직무·성과 중심 임금체계 확산 등 노동시장 제반 여건이 조성되는 추이를 보고 신중하게 검토돼야 한다”고 강조했다. 서재근 기자', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002607467', 'https://imgnews.pstatic.net/image/016/2026/03/03/0002607467_001_20260303112518181.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-03-03 11:25:18', 0, true, '2026-03-09 06:11:30.516364') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (776, '"재벌가 ''정략결혼''? 이젠 옛말"…평범한 며느리·사위 맞는 ''이유'' 있었다', '지난 2022년 결혼한 프로골퍼 리디아 고와 정태영 현대카드 부회장의 아들 정준씨. 뉴스1[서울경제]국내 대기업 오너 일가가 과거 정·관계 중심의 ‘정략 결혼’에서 벗어나고 있다는 분석이 나왔다. 재계나 일반인과의 결혼을 선택하는 사례가 늘어나면서다.12일 기업데이터연구소 CEO스코어가 올해 지정 총수가 있는 공시 대상 기업 집단(대기업 집단) 81곳 중 혼맥 분류가 가능한 380명을 조사한 결과, 오너 4~5세의 정·관계 혼맥 비율은 6.9%로 집계됐다. 오너 2세 24.1%, 오너 3세 14.1% 등과 비교하면 세대가 지날수록 낮아지고 있다.2000년 이전엔 정·관계 혼맥이 24.2%였지만 2000년 이후 7.4%로 3분의 2 가까이 줄었다. 같은 기간 재계 간 혼맥은 39.2%에서 48.0%, 일반인과의 혼맥은 24.6%에서 31.4%로 모두 증가했다.구체적 사례도 흐름을 뒷받침한다. 정태영 현대카드 부회장의 아들 정준 씨는 2022년 12월 세계 1위 프로골퍼 리디아 고와 결혼했고, 정몽구 현대차그룹 회장의 외손녀 선아영 씨는 2016년 배우 길용우의 아들 길성진 씨와 백년가약을 맺었다. HL그룹 정몽원 회장의 차녀 정지수 씨는 지난해 방송인 백지연의 아들 강인찬 씨와 결혼했다. 한화 김동관 부회장은 2019년 회사 동료였던 일반인 배우자와 혼인했으며, 호반건설 김대헌 대표(전 SBS 아나운서 김민형), 두산 박서원 전 대표(전 JTBC 아나운서 조수애) 등 ‘일반인·언론인’과의 결혼도 이어졌다.CEO스코어는 “과거엔 정·관계 혼맥이 사업에 도움이 됐지만, 지금은 정치적 노출·감시·규제 리스크가 커졌다”며 “결과적으로 재계 내부 네트워크나 일반인과의 결혼이 더 안전하고 실용적인 선택으로 자리 잡았다”고 해석했다.그룹 간 연결망을 보면 LS가 현대차·OCI·BGF·삼표·사조·범 동국제강(KISCO홀딩스) 등과 가장 폭넓게 사돈을 맺었다. LG는 DL·삼성·GS·두산과, GS는 LG·삼표·중앙·태광과 이어졌고, 범GS로 넓히면 금호석유화학·세아와의 연결도 확인된다.', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004555144', 'https://imgnews.pstatic.net/image/011/2025/11/12/0004555144_001_20251112193309722.png?type=w800', 'NEWS_ETC', NULL, '2025-11-12 19:33:09', 0, true, '2026-03-09 05:53:13.811617') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (777, '"정략결혼보단 사랑" 달라진 재벌가 혼인', '[김혜인 디지털팀 기자 haileykim0516@gmail.com]정·관계 결연 줄고 재계·일반인 혼인 증가LS그룹, 혼맥 네트워크 최다지난 2016년 명동성당에서 열린 정성이 이노션 고문의 딸 선아영 씨 결혼식에서 참석자들이 기념촬영을 하고 있다. ©연합뉴스국내 대기업 오너 일가의 결혼 양상이 과거 정·관계 중심의 ''정략결혼''에서 벗어나 실리와 개인의 선택을 중시하는 방향으로 변화한 것으로 나타났다.12일 기업데이터연구소 CEO스코어가 발표한 대기업 혼맥 조사에 따르면, 지정 총수가 있는 공시대상 대기업집단 81곳 가운데 혼맥이 확인된 380명 중 오너 2세의 정·관계 혼맥 비중은 24.1%였으나, 오너 3세는 14.1%, 오너 4~5세는 6.9%로 감소했다.반면 기업 간 혼맥은 꾸준히 증가했다. 재계 내 결혼 비중은 오너 2세 34.5%, 오너 3세 47.9%, 오너 4~5세 46.5%로 상승세를 보였다. 오너 일가가 일반인과 혼인하는 경우도 확대됐다. 오너 2세는 29.3%였으나 오너 4~5세는 37.2%로 늘었다.시기별 변화도 뚜렷하다. 2000년 이전 재계의 정·관계 혼맥 비중은 24.2%(58명)에 달했지만, 2000년 이후에는 7.4%(9명)로 감소했다. 같은 기간 재계 간 혼맥은 39.2%(94명)에서 48.0%(58명)로 늘었고, 일반인과의 결혼 비중도 24.6%(59명)에서 31.4%(38명)로 증가했다.CEO스코어는 이러한 흐름에 대해 "정·관계 혼맥이 과거에는 경영 안정과 사업 확장에 도움이 됐지만 지금은 오히려 정치적 감시와 규제 위험에 노출되는 요인으로 작용하고 있다"고 분석했다.그룹별 혼맥 네트워크를 보면 LS그룹이 현대차·OCI·BGF·삼표·사조·범동국제강(KISCO홀딩스) 등 가장 많은 대기업과 사돈 관계를 맺은 것으로 조사됐다.LG와 GS그룹은 각각 4개 그룹과 혼맥으로 연결됐다. LG는 DL·삼성·GS·두산과 혼인 관계를 형성했고, GS는 LG·삼표·중앙·태광과 이어졌다. 특히 GS그룹의 범계열로 확장하면 금호석유화학과 세아 등과도 혼맥 관계가 형성된다.', NULL, '시사저널', 'https://n.news.naver.com/mnews/article/586/0000115745', 'https://imgnews.pstatic.net/image/586/2025/11/12/0000115745_001_20251112105211311.jpg?type=w800', 'NEWS_ETC', NULL, '2025-11-12 10:52:11', 0, true, '2026-03-09 05:53:13.811617') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (778, '"배당 늘려달라"…동학개미 목소리 커졌다', '[앵커]최근 코스피의 역대급 상승세에는 다양한 변수가 작용했습니다만, 상법 개정안 등 정부의 정책적 움직임도 투자심리에 적잖은 영향을 줬습니다.그 영향이 드러나는 또 다른 영역이 소액주주들의 움직임인데요.올해 들어 소액주주들의 주주제안이 급증한 것으로 나타났습니다.이민후 기자, 소액주주들의 주주제안, 얼마나 늘었습니까?[기자]올해가 아직 다 지나지 않았지만 3년 새 9배 넘게 증가했습니다.국회 정무위원회 소속 김상훈 국민의힘 의원실에 따르면 소액주주의 주주제안 건수는 지난 2022년 10건에 그쳤지만 이듬해 43건, 지난해 47건을 기록했는데요.올해는 92건으로 지난해보다 벌써 2배 가까이 늘었습니다.기업별로는 DB하이텍, 베뉴지, 오스코텍이 2022년부터 4년 중 3개년간 주주제안받았고 KISCO홀딩스, 케스텍코리아, 오로라, 젬백스링크는 2개년 동안 주주제안을 받았습니다.중복된 상장사의 주주제안을 다 제외하면 65개 기업이 주주제안을 받았는데 이중 7개 종목은 상폐됐거나 상폐위기에 놓이면서 거래가 정지됐습니다.사실상 소액주주들의 주주가치 활성화 요구만큼이나 경영투명성을 강화하라는 소액주주 목소리도 활발했던 셈입니다.[앵커]구체적인 주주제안의 안건은 어떤 것들이었습니까?[기자]주주제안 중에서 이사 선임 및 해임안건이 36건으로 제일 많았습니다.특히 사내, 사외이사 선임과 해임에 안건을 올렸는데 그만큼 경영구조 개선안에 관심이 있다는 방증입니다.주주가치 제고 안 가운데에서는 이익배당 증액은 25회 자기주식 소각·매입이 13회에 달했습니다.또 경영투명성 강화를 위해 기업IR, 전자투표제, 주주총회 보수심의제 등 정관변경 제안도 논의됐습니다.특히 상법 개정안이 통과되면서 내년부터 주주가치 제고와 경영구조 개선, 경영투명성 강화를 제안하는 소액주주들의 움직임은 더 활발해질 전망입니다.SBS Biz 이민후입니다.당신의 제보가 뉴스로 만들어집니다.SBS Biz는 여러분의 제보를 기다리고 있습니다.홈페이지 = https://url.kr/9pghjn', NULL, 'SBS Biz', 'https://n.news.naver.com/mnews/article/374/0000468825', 'https://imgnews.pstatic.net/image/374/2025/10/16/0000468825_001_20251016151516624.jpg?type=w800', 'NEWS_ETC', NULL, '2025-10-16 15:14:15', 0, true, '2026-03-09 05:53:13.811617') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (779, '"李 대통령, 배당 확대 강조…고배당 테마 부각 가능성"-한국', '사진=연합뉴스한국투자증권은 12일 이재명 대통령 취임 100일 기자회견과 관련해 "양도세 대주주 기준에 대한 불확실성은 여전하지만 밸류업 기조 유지는 확인한 만큼 3차 상법 개정과 세제 개편안을 축으로 선별적 대응이 필요하다"고 조언했다.이 증권사 박기훈 연구원은 "투자자들이 가장 주목한 대목은 양도소득세 대주주 기준이었고 시장은 현행 50억원을 유지한다는 명확한 메시지를 기대했으나 대통령은 공을 국회 논의로 넘기며 불확실성을 남겼다"며 "다만 이를 단순히 기대 미달로만 평가할 필요는 없다"고 분석했다.이어 "배당소득 분리과세에 대해 ''배당을 최대한 늘리는 방향으로 교정 가능하다''는 점을 강조했고 주가 조작에 대해선 ''엄벌''이라는 강경한 태도를 확인해 밸류업 기조가 여전히 유효하다는 전략적 의미를 찾을 수 있다"며 "때문에 투자전략의 무게중심이 다시 고배당 테마로 돌아올 가능성이 있다"고 평가했다.또 "정책적 관점에서 가장 주목할 두 가지 축은 3차 상법개정과 세제 개편안"이라며 "3차 상법개정은 자사주 의무 소각을 핵심으로 하고 9월 정기국회 처리가 유력시된다"고 했다.박 연구원은 "이미 불분명한 소각 기준을 앞두고 기업들이 선제적으로 자사주 소각이나 매입에 나서는 움직임도 확인된다"며 "단순히 자사주 비중이 높은 기업보다는 최대주주 지분율이 30% 이상 유지되고 최근 주가 상승률이 과도하지 않다는 조건을 고려해야 한다"고 분석했다.아울러 "정부안은 배당성향 40% 이상을 유지하거나 혹은 배당성향 25% 이상이면서 직전 3년 평균 대비 5% 이상 배당을 확대한 기업을 대상으로 설계돼 있다"며 "따라서 이 같은 모든 요건을 충족하는 종목을 가려내는 접근이 필요하다"고 했다.한국투자증권은 이 같은 조건을 충족하는 기업으로 △일성아이에스 △부국증권 △한샘 △대한제강 △한국철강 △KISCO홀딩스 △INVENI 등을 제시했다.', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005184010', 'https://imgnews.pstatic.net/image/015/2025/09/12/0005184010_001_20250912082912648.jpg?type=w800', 'NEWS_ETC', NULL, '2025-09-12 08:29:12', 0, true, '2026-03-09 05:53:13.811617') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (886, 'TCC스틸, 지난해 영업손 109억…적자전환', '[헤럴드경제=증권부] TCC스틸은 지난해 연결기준 영업손실이 109억933만원으로 전년대비 적자전환했다고 5일 공시했다.같은 기간 매출액은 6115억1391만원으로 5.1% 증가한 것으로 나타났다.당기순손실은 72억1557만원으로 적자전환했다.', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002596564', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ENERGY', NULL, '2026-02-05 14:42:13', 0, true, '2026-03-09 06:11:30.516364') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (781, '[클릭 e종목]"코오롱인더, 유효한 상승 모멘텀…목표가↑"', '목표주가 기존 대비 66% 상향 조정신한투자증권은 9일 코오롱인더에 대해 상승 모멘텀이 유효하다고 보고 목표주가를 기존 5만3000원에서 8만8000원으로 상향 조정했다. 투자의견은 ''매수''를 유지했다.이진명 신한투자증권 연구원은 "동종업계 멀티플 상승 및 투자자산가치 등을 반영해 목표주가를 기존 대비 66% 상향 조정했다"면서 "올해 영업이익은 주요 사업부 실적 개선에 힘입어 전년 동기 대비 96% 증가한 2137억원을 기록할 것으로 예상되며 특히 코오롱스포츠차이나 및 우리·하나금융지주 지분가치까지 감안하며 업사이드가 유효하다"고 설명했다.코오롱인더는 지난해 4분기 영업이익이 전분기 대비 64% 감소한 98억원을 기록해 컨센서스(증권사 전망치 평균) 461억원을 하회했다. 이 연구원은 "전방 수요 둔화 속 자동차 소재 및 아라미드에서 일회성(정기보수, 재고손실) 약 100억원이 반영됐다"면서 "다만 타이어코드 수출 가격은 하락세가 진정됐으며 아라미드는 10개 분기만에 반등했다"고 분석했다.올해는 주요 사업부들의 실적 개선 흐름이 나타날 것으로 전망된다. 이 연구원은 "타이어코드는 점진적인 판가 정상화 속 베트남 공장을 통한 수익성 개선이 가능할 것"이라며 "아라미드는 광케이블향 수요 회복에 따른 가동률 상승 및 경쟁사 물량 이탈 등으로 적자폭 축소가 기대된다. 화학은 경쟁사 설비폐쇄 및 mPPO(변성 폴리페닐렌 옥사이드) 증설로 수익성과 성장성을 모두 확보 가능할 것"이라고 말했다. 이어 "코오롱스포츠차이나는 중국 내 견고한 입지를 통해 실적 성장이 기대되며 올해 지분법이익 전년 대비 38% 증가한 595억원으 기대된다"고 덧붙였다.', NULL, '아시아경제', 'https://n.news.naver.com/mnews/article/277/0005731064', 'https://imgnews.pstatic.net/image/277/2026/03/09/0005731064_001_20260309080911118.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 08:08:51', 0, true, '2026-03-09 05:53:37.151893') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (782, '코오롱 "코오롱티슈진 주식 600억원에 추가취득"', '코오롱은 미국의 기초 의약물질 및 생물학적 제제 제조업 계열사 코오롱티슈진의 주식 11만8천40주를 약 600억원에 추가 취득한다고 6일 공시했습니다.주식 취득 뒤 코오롱의 코오롱티슈진 지분율은 39.4%가 됩니다.주식 취득 예정일은 24일입니다.코오롱은 이번 주식 취득의 목적을 "코오롱티슈진주식회사 운영자금 조달 (임상비용 등)"이라고 밝혔습니다.당신의 제보가 뉴스로 만들어집니다.SBS Biz는 여러분의 제보를 기다리고 있습니다.홈페이지 = https://url.kr/9pghjn', NULL, 'SBS Biz', 'https://n.news.naver.com/mnews/article/374/0000496376', 'https://imgnews.pstatic.net/image/374/2026/03/06/0000496376_001_20260306182410275.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-06 18:14:11', 0, true, '2026-03-09 05:53:37.151893') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (783, '軍 전투복 원사 국산화…태광·효성 "연 200t 섬유 수요 발생"', '섬유업계, 피복류 4종 건의방사법 개정 건의안 제출 계획"兆단위 시장 창출 가능성"태광산업, 효성티앤씨 등 국내 섬유업계가 방상내피를 비롯한 군 피복류 4종에 들어가는 원사(原絲)를 전면 국산화하는 방안을 정부와 국회에 건의한다. 중국·동남아시아산 저가 공세로부터 국내 생산 기반을 보호하고, 국방 소재 공급망 자립으로 국가 안보에도 기여한다는 취지에서다. 업계에선 건의안이 반영되면 나일론을 비롯해 연간 약 200t 규모의 내수가 살아날 것으로 보고 있다.6일 섬유업계에 따르면 한국섬유산업연합회는 국방 섬유 소재 국산화를 위한 방위사업법 개정 건의안을 상반기에 국회와 국방부에 제출할 계획이다. 방상내피, 방상외피, 궤도차량승무원복, 컴뱃셔츠 등 군 피복류 4종에 들어가는 원사의 국산 사용을 의무화하는 내용이 핵심이다. 업계는 향후 전술조끼, 침낭, 개인천막 등으로 건의 대상을 확대한다는 방침이다.현행 방위사업법은 방위사업청이 국내에서 생산된 군수품을 우선적으로 구매한다는 조항을 두고 있다. 하지만 조항이 ‘국내 생산’에 초점을 둬 수입 원사를 사용해도 국내에서 염색·가공·봉제하면 국내 생산품으로 간주했다. 업계 관계자는 “군 피복류에 들어가는 원사의 약 70~80%가 외국산”이라며 “저렴한 중국·인도네시아산 원사를 활용하는 봉제업체가 공공입찰에서 유리한 사례가 많다”고 말했다.국방부가 2021년부터 공공입찰 시 국산 원사를 사용한 기업에 가산점을 주는 국산섬유인증제도를 시행하고 있지만 실제 적용 대상은 전투복이 유일하다는 것이 업계의 설명이다. 올해 국방부 전투복 예산은 362억원으로, 국방 피복 예산(5854억원)의 약 6.2%에 해당한다.업계에선 건의 대상에 오른 피복류 4종의 원사를 국산화하면 나일론 70t, 폴리에스테르 125t, 폴리우레탄 5t 등 연간 약 200t 규모의 국산 섬유 수요가 발생할 것으로 추산했다. 폴리에스테르는 방상외피 등 의류 전반에 사용되며, 나일론은 상대적으로 높은 내구성이 요구되는 전술조끼 등에 쓰인다. 폴리우레탄은 스판덱스 섬유를 가공하는 원료다.국내 유일한 나일론 생산업체 태광산업은 45%대로 떨어진 나일론 공장 가동률을 회복할 기회로 보고 있다. 중국 기업의 저가 공세에 한국 나일론산업은 코너에 몰렸다. 코오롱, KP케미칼(현 롯데케미칼) 등이 국내 사업을 접은 게 대표적인 사례로 꼽힌다. 스판덱스용 폴리우레탄 생산 기업 역시 효성티앤씨 한 곳뿐이다. 폴리에스테르는 대한화섬, 효성티앤씨, 휴비스, 도레이첨단소재 등 네 곳이 생산한다.업계 관계자는 “미국은 국가 안보 및 자국 산업 보호를 위해 군 피복류와 장구류 전반에 ‘메이드 인 USA’를 의무화하고 있다”며 “한국에서도 연간 6000억원 규모의 국방 섬유를 비롯해 경찰·소방복 등 단체복 시장까지 확대하면 조 단위 내수시장이 창출될 것”이라고 말했다.', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005259206', 'https://imgnews.pstatic.net/image/015/2026/03/06/0005259206_001_20260307002316478.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-06 17:30:10', 0, true, '2026-03-09 05:53:37.151893') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (784, 'W컨셉, LF·코오롱 출신 이지은 신임 대표 선임', '첫 여성 대표신세계그룹 패션 플랫폼 더블유컨셉(W컨셉)이 이지은 상품2담당 상무를 새 대표이사로 선임했다고 6일 밝혔다.이지은 W컨셉 신임 대표이사. /W컨셉 제공이 신임 대표는 W컨셉 최초의 여성 대표로 LF, 코오롱 등 패션 기업에서 경력을 쌓았다.W컨셉 관계자는 “패션 전문가 대표 선임을 통해 W컨셉의 독보적인 상품 기획 경쟁력이 한층 강화될 것”이라고 했다.', NULL, '조선비즈', 'https://n.news.naver.com/mnews/article/366/0001146329', 'https://imgnews.pstatic.net/image/366/2026/03/06/0001146329_001_20260306120407565.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-06 12:04:07', 0, true, '2026-03-09 05:53:37.151893') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (785, '생산부터 사무까지…코오롱인더, 전사 AX 본격화', 'AI 활용 공정 지능형 제어 시스템 도입사업장 안전, 사무효율 개선에도 AI 역할 확장코오롱 원앤온리 타워 [코오롱인더스트리 제공][헤럴드경제=한영대 기자] 코오롱인더스트리가 전사적인 인공지능 전환(AX)에 속도를 내고 있다. 생산부터 사무 작업까지 모든 업무에 AI(인공지능) 시스템을 도입해 리스크는 최소화하고 비용·효율은 개선한다는 전략이다.6일 업계에 따르면 코오롱인더스트리의 케미칼 사업부는 지난해 AI를 활용한 공정 지능형 제어 시스템을 도입했다. 이를 통해 그간 수작업 과정에서 발생했던 오류를 최소화하고 공정을 표준화해 품질 안전성을 대폭 향상했다. 또 핵심 공정 중 하나인 수분리 공정에도 AI 를 도입해 완전 자동화를 단계적으로 확대하고 있다.AMS 사업부는 카시트 모듈 생산 공정에서 비전 검사기 구축을 통한 검사지능화 과제를 추진 중이다. 시각 인공지능 기술을 적용해 제품 외형의 객체 인식 및 패턴 분석을 고도화하는 것이 핵심이다. AI가 사람의 눈을 대신해 파츠 유무를 감지함으로써 품질관리 효율을 극대화할 수 있을 것으로 예상된다.아라미드 사업부는 올해 1월부터 생산 공정을 AI 가상 환경 내에서 사전 검증하는 시스템의 도입을 검토하고 있다. AI로 공정에 필요한 운영 조건을 미리 점검, 이에 따라 공정을 최적화하고 생산 효율을 최대로 끌어 올리는 것이 목적이다.AI 역할은 사업장 안전과 사무효율 개선으로도 확장되고 있다. 코오롱인더스트리는 지난해 5월부터 주요 사업장인 김천 1·2공장, 구미 1공장, 경산 공장 등에 안전 사고 예방용 AI 영상 관제 시스템을 도입하고 있다. 해당 시스템은 영상 속 작업자의 상황을 판단해 위험을 사전에 경고 및 예방하는 역할을 한다. 모자이크 자동화 처리도 가능해 개인정보 보호에도 기여하고 있다.일반 사무직군에서도 AI를 통한 업무 자동화를 검토하고 있다. 기존에 일부 전문가나 협력업체를 통해 구축했던 RPA(로보틱 프로세스 오토메이션) 방식에서 벗어나 채팅 기반으로 업무를 수행하는 방식이다. 공시, 환율, 제품 가격와 같은 정보에서의 특정 지표를 기존 양식에서 업데이트하거나 계약서 작성을 자동화하는 등 실질적인 업무를 대체하는 방식을 검증하고 있다.', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002609287', 'https://imgnews.pstatic.net/image/016/2026/03/06/0002609287_001_20260306083013216.png?type=w800', 'NEWS_ETC', NULL, '2026-03-06 08:30:13', 0, true, '2026-03-09 05:53:37.151893') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (786, '''AI에 진심'' 직원들 가슴에 AX 새긴 이 회사', '코오롱그룹, 지향점 AX 박힌 배지와 팔찌 제작이규호 부회장 AI 가속화, 신사업 추진 강력 의지이규호 부회장. 코오롱 제공[이코노미스트 김두용 기자]정체기를 걸었던 코오롱그룹에 변화의 물결이 일고 있다. 인공지능(AI)으로 인한 산업 전환기에 그룹의 지향점인 ‘AX’(AI 전환)를 직원들의 배지와 팔찌에 아로새기며 강력한 의지를 드러내고 있다. 여기에 오너가 이규호 코오롱그룹 부회장의 주도로 합병과 신사업 등을 추진하며 돌파구 마련에 나서고 있다.배지에 새겨진 AI, 코오롱의 ‘원팀’ 전략코오롱그룹의 임직원들은 매일 AX를 가슴에 새기고 출근을 준비한다. 업무 전부터 그룹의 2026년 경영메시지를 담은 배지와 팔찌를 장착하기 때문에 ‘정신무장’하는 효과가 뚜렷하다.코오롱은 ‘배지 경영’으로 유명하다. 지난 2013년부터 매년 그룹의 경영메시지를 형상화해 배지와 팔찌 형태로 만들어 임직원들과 공유하는 독특한 소통문화가 이어지고 있다.올해는 AI의 전략적 활용을 통해 혁신과 성장을 가속화하자는 의미를 담아 ‘엑셀런스’(AXcellence)를 경영메시지로 선정했다. ‘AI’와 ‘Excellence’(탁월함)를 결합한 조어로 지향점인 AX와 맞닿아있다.이에 배지 이미지는 그룹 CI 삼각형 디자인에서 착안한 프리즘을 형상화했다. 팔찌에는 AX가 더욱 또렷하다. 배지와 팔찌에 새겨진 엑셀런스 프리즘을 통해 코오롱만의 성공 스펙트럼을 완성하겠다는 의지를 표현한 것이다.코오롱 관계자는 “AI 기술과 발맞춰 산업지형이 대전환하는 시기를 맞아 사고를 넓히고 창의적 영감을 얻는 데 AI 플랫폼을 더욱 적극적으로 활용해보자는 취지를 담았다”고 설명했다.AX 형상화 한 코오롱그룹의 2026년 배지와 팔찌. [사진 코오롱]배지와 팔찌에 새겨진 AX는 도구 AI를 넘어서 ‘구성원’으로 받아들여야 한다는 강력한 메시지를 담고 있다. AI를 포함한 임직원 모두가 ‘원팀’이라는 전략이다. 특히 사업 현장에서 ‘AI로 무엇을 할 수 있느냐’를 먼저 생각하며 해법을 실행할 수 있는 추진력을 발휘하기를 기대하고 있다.그룹의 강한 드라이브로 계열사마다 AI 플랫폼을 적극 활용하고 있다. 먼저 그룹의 IT서비스 전문계열사인 코오롱베니트가 AX의 최전선에서 나서고 있다. 코오롱베니트는 고객의 AX를 돕는 ‘AX 조력자’를 자처하며 DX(디지털 전환) 사업과 AI 생태계 공략에 속도를 내고 있다.이를 위해 올해 전담 조직인 AX센터를 신설했다. AX센터는 기획·검증·적용·확산을 통합 수행하는 실행형 조직으로, 기업용 생성형AI 플랫폼 ‘프롬튼’(PromptON)을 필두로 그룹 전반의 AI 전환을 단계적으로 주도하고 있다.제조 분야에서 자율제조 전환이 핵심이다. 자사의 DX 패키지를 통해 설비와 데이터를 통합하고 공정 무인화를 추진 중이다. 실제 코오롱인더스트리의 김천 2공장에 품질 예측과 첨단 공정제어 기술을 적용해 자율제조의 실효성을 입증했다.대외적으로는 ‘코오롱베니트 AI 얼라이언스’를 통해 국산 AI 기술의 시장 진출을 돕는 생태계 확장 전략을 펼치고 있다. 지난해 9월 약 800여명의 고객과 파트너사가 참가한 서밋을 개최해 AX 생태계 확장 전략을 발표했다. 향후 협업 솔루션인 ‘프리패키지 프롬튼팩’을 공개하고, 지속적으로 확대한다는 방침이다.핵심 계열사인 코오롱인더스트리에서도 AI를 적극 도입 중이다. 케미칼 사업부는 지난해 AI를 활용한 공정 지능형 제어 시스템을 도입했다. 또 핵심 공정 중 하나인 ‘수분리 공정’에도 AI 비전을 도입해 완전 자동화를 단계적으로 확대하고 있다. 사업장 안전을 위해 지난해 5월부터 김천 1·2공장, 구미 1공장, 경산공장 등에 ‘안전사고 예방용 AI 영상 관제 시스’템을 도입하기도 했다.코오롱 원앤온리타워 전경. [사진 코오롱]이규호 부회장 합병과 신사업으로 돌파구코오롱그룹은 이웅열 명예회장이 경영 일선에서 물러나며 오너가 4세인 이규호 부회장이 경영 주도권을 잡고 있다. ‘인보사 사태’로 지속됐던 이 명예회장의 사법리스크도 올해 2월 마침표를 찍으면서 ‘어두운 터널’에서 빠져나올 채비를 하고 있다. 관절염 유전자 치료제인 인보사 사태와 관련한 형사사건은 검사 기소 5년7개월 만에 종결됐다.한때 재계 10위를 넘봤던 코오롱그룹은 재계 40위권까지 떨어지는 등 성장 정체기를 겪고 있다. 초고속 승진을 이어가며 지휘봉을 잡은 이 부회장은 합병과 신사업 카드로 돌파구 마련에 나서고 있다. 코오롱은 이런 움직임들로 2025년 공정거래위원회 발표 재계 순위가 40위에서 38위로 상승했다.이 부회장은 지난해 말 처음으로 핵심 계열사 코오롱글로벌과 코오롱인더스트리의 지분을 소량 매입하는 등 경영 승계를 준비하는 모습도 보였다.그룹은 지난해 리조트·호텔·골프장의 운영사 MOD와 부동산 자산관리사 LSI를 코오롱글로벌에 흡수합병했다. 또 올해 4월에는 코오롱인더스트리가 자회사 코오롱ENP 흡수합병해 고부가 엔지니어링 플라스틱 시장의 경쟁력을 강화한다는 계획이다.또 이 부회장을 중심으로 사업 재편과 신사업 발굴에 힘쓰고 있다. 이 부회장은 신성장동력으로 ▲바이오 ▲첨단 복합소재 ▲수소 등을 점찍었다. 다양한 미래 고부가가치 산업에 적극적으로 투자하며 차별화된 경쟁력 확보한다는 계획이다.우선 코오롱인더스트리는 미래 성장 동력 확보를 위해 전자소재 분야 투자를 강화하고 있다. 지난해 6월 340억원을 투자해 생산시설을 새롭게 조성하고 있다. 글로벌 시장 선도 제품인 타이어코드의 경우 현재 3만6000톤(t) 수준에서 2027년 5만7000톤 규모로 확대해 프리미엄 시장 대응력과 제품 경쟁력을 높여갈 방침이다.코오롱글로벌의 경우 신재생에너지 분야를 성장동력의 한 축으로 삼고 풍력발전사업에 주력하고 있다.재계 관계자는 “코오롱그룹이 오너가의 사법리스크 등으로 그동안 소극적인 움직임을 보인 터라 다른 그룹만큼의 성장세를 보여주지 못했다. 하지만 최근 젊은 이규호 부회장이 주도권을 잡으면서 AI 전환기를 맞아 새로운 바람이 기대된다”고 말했다.', NULL, '이코노미스트', 'https://n.news.naver.com/mnews/article/243/0000093840', 'https://imgnews.pstatic.net/image/243/2026/03/03/0000093840_001_20260303070014106.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-03 07:00:14', 0, true, '2026-03-09 05:53:37.151893') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (787, '코오롱제약, 플랫바이오 다시 분할하나…엑시트 성패 기준선 ''350억''', '/사진 제공=코오롱제약, 이미지 제작=이승준 기자코오롱제약이 2023년 흡수합병으로 편입한 플랫바이오를 다시 분할할 수 있다는 관측이 시장에 자리 잡고 있다. 이에 따라 편입 당시 반영된 미래가치의 회수 여부가 관전 포인트로 떠올랐다. 합병과 동시에 신약개발부문을 신설하며 체질전환을 선언했던 만큼 이번 구조조정은 투자 성과의 평가로 주목받는다. 매각 조건에 따라 ''성공적 엑시트''가 될지 ''프리미엄 소멸''로 남을지가 갈릴 전망이다.관건은 ''350억 가치'' 회수 기준선28일 업계에 따르면 코오롱제약은 2023년 3월 흡수합병한 플랫바이오 관련 사업을 분할하는 방안을 추진하고 있다. 합병으로 신설했던 신약개발부문을 다시 떼어내는 구조가 검토되고 있는 것으로 알려졌다. 해당 사안이 이사회에서 의결된다면 코오롱제약은 플랫바이오를 흡수합병한 지 3년 만에 다시 분할하는 셈이다.시장에서는 이번 분할의 성패가 합병 당시 인정한 기업가치 대비 회수 규모에 달려 있다고 바라본다. 매각가가 당시 기업가치에 미치지 못할 경우 합병 당시 반영된 미래가치 프리미엄의 상당 부분이 소멸할 것으로 해석될 수 있다는 시각이다. 반대로 전략적 투자자 유치나 기술 진전 등이 입증된다면 가치 재평가로 볼 여지가 있다고 여겨진다.합병 당시 플랫바이오에 최소 300억원대 가치가 반영된 것으로 추정된다는 점도 판단 기준으로 거론된다. 코오롱제약은 2023년 플랫바이오를 흡수합병하며 보통주 120만주를 발행했고 합병비율은 1대2.3849273으로 산정됐다. 이는 현금이 아닌 지분 교부 방식이었다. 교환비율이 적용된 만큼 일정 수준 이상의 미래가치가 전제됐다는 의미로 읽힌다.이 같은 분석이 제기되는 것은 플랫바이오에 반영된 최소 가치가 350억원으로 추정되기 때문이다. 2023년 코오롱제약의 자본총계 700억2000만원과 발행주식수 240만주를 기준으로 계산하면 주당 순자산가치는 2만9175원이다. 이는 순자산가치인 주가수익률(PBR) 1배 기준의 보수적 산정이다. 프리미엄을 감안할 경우 실제 평가액은 더 높았을 가능성도 있다.플랫바이오의 당시 재무 상태는 미래가치 기반 딜이었다는 점을 뒷받침한다. 합병 직전 플랫바이오의 자본총계는 28억원, 당기순손실은 21억원이었다. 실적 기반 가치로 보기 어려운 구조였다는 시각이 자리 잡은 것도 이 때문이다. 그럼에도 불구하고 교환비율이 적용됐다는 점은 신약개발 성과와 기술 확장 가능성에 대한 기대가 가격에 반영된 것으로 풀이된다.바이오 예외였던 ''재편 기준'' 변동이번 분할 추진의 배경으로는 3년간 가시적 성과가 제한적이었다는 점이 지목된다. 합병 이후 대외적으로 확인되는 대형 기술이전(LO)이나 임상 진입 사례는 공개적으로 드러나지 않았다. 지난 3년간 신약개발부문 관련 공시나 보도자료 배포도 찾기 어렵다. 시장에서는 미래가치 실현 속도가 기대에 미치지 못했다는 해석이 나온다.일각에서는 ''그룹 내부전략 조정 신호''가 아니냐는 분석도 제기된다. 이번 결정은 그룹 차원에서 바이오 부문이 재편 전략의 예외 영역으로 분류돼왔다는 점에서 더욱 주목된다. 코오롱그룹은 최근 수년간 코오롱엘에스아이, 엠오디, 코오롱모빌리티 등을 통폐합하며 구조 단순화를 진행해왔지만 제약바이오 부문은 전략적 선택 영역으로 남겨왔다.2023년 합병은 신약개발 역량 강화를 위한 전략적 선택으로 제시됐다. 회사는 당시 합병 목적을 ''새로운 사업영역으로의 확대를 통한 기업가치 제고''로 명시했다. 기존 제약 사업에 연구개발(R&D) 축을 더해 항암신약 개발까지 영역을 확대하겠다는 구상이었다. 플랫바이오의 주요사업은 신약 R&D, 컨설팅, 연구용역 등으로 알려져 있다.다만 회사 측은 합병 당시 가치 산정 금액을 외부에 공개한 적이 없으며 사업부 단위로 손상손실을 별도로 계산하지 않는다고 밝혔다. 또 현재로서는 분할을 비롯해서 플랫바이오 관련해서 정해진 바가 없다는 입장이다. 내부 평가액이나 매각 조건에 대해서도 언급을 피했다. 향후 구체적인 거래 구조가 공개돼야 최종 평가가 가능할 전망이다.㈜코오롱 관계자는 "해당 사안에 대해서는 결정된 바가 전혀 없다"며 "말씀드릴 수 있는 부분도 없다"고 말했다. 코오롱생명과학 관계자도 김선진 대표의 행보에 대해 "관련해서 정해진 것이 없다"며 "따로 말씀드릴 수 있는 부분은 없다"고 답변했다. 김 대표는 2018년 플랫바이오를 창업하고 2023년 5월까지 대표직을 맡았다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000080083', 'https://imgnews.pstatic.net/image/293/2026/02/28/0000080083_001_20260228132308833.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-28 13:23:08', 0, true, '2026-03-09 05:53:37.151893') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (788, '''인보사 사태'' 피해주주들, 코오롱 상대 손배소송 패소', '[강병철 특파원 = 미국 메릴랜드주 록빌의 코오롱티슈진의 연구소에서 지난 11일(현지시간) 연구원들이 실험을 진행하고 있다. (록빌(메릴랜드주)=연합뉴스)]''인보사(인보사케이주) 사태''로 손실을 본 주주들이 코오롱생명과학과 코오롱티슈진을 상대로 제기한 손해배상 소송에서 잇달아 패소했습니다.28일 법조계에 따르면 서울중앙지법 민사합의30부(김석범 부장판사)는 지난달 22일 주주 149명이 코오롱티슈진을 상대로 낸 38억원 규모의 손해배상 청구 소송에서 원고 패소로 판결했습니다.재판부는 주주 78명이 코오롱생명과학을 상대로 낸 30억원 규모의 손해배상 청구도 기각했습니다.코오롱생명과학의 미국 자회사인 코오롱티슈진이 개발한 인보사는 사람 연골세포가 담긴 1액과 연골세포 성장인자(TGF-β1)를 도입한 형질전환 세포가 담긴 2액으로 구성된 관절염 유전자치료제 주사액으로, 2017년 국내 첫 유전자 치료제로 식품의약품안전처(식약처) 허가를 받았습니다.하지만 2액을 만드는 데 사용된 세포가 허가받은 연골세포 대신 종양 유발 위험이 있다고 알려진 신장유래세포(GP2-293) 성분임이 드러나 식약처는 2019년 7월 허가를 취소했고, 해당 파문으로 주가가 급락했습니다.이에 주주들은 코오롱티슈진과 코오롱생명과학이 인보사의 주성분이 바뀐 사실을 인지하고도 허위 공시를 하는 등 중요사항을 거짓 기재해 손해를 입었다며 소송을 제기했습니다.재판부는 증권신고서에 인보사의 핵심 구성성분인 2액이 ''연골재생을 촉진하는 유전자가 삽입·도입된 동종연골세포''라는 취지로 공시됐다며 회사가 인보사의 주성분에 대해 거짓 기재한 것은 맞는다고 봤습니다.다만, 해당 부분이 자본시장법에서 말하는 ''중요사항''은 아니라면서 "이 사건에서 원고들이 주장하는 것처럼 합리적인 투자자들의 투자 판단을 그르치게 할 정도라고 볼 수 없습니다"라고 판단했습니다.자본시장법 162조는 사업보고서 중 ''중요사항''에 관해 거짓 기재가 있고, 이로 인해 증권 취득자가 손해를 입은 경우 손해배상 책임을 진다고 규정합니다.재판부는 그러면서 "증권신고서의 전체적인 취지를 고려하면 핵심 성분의 기원·유래 등에 관한 일부 거짓 기재를 통해 인보사의 의학적 안정성에 관해 착오를 유발하기 위해 작성된 것이라 보기는 어렵습니다"라고 짚었습니다.오늘(기존 ''이날'' 수정) 재판부는 당시 주가 급락에 대해서도 "인보사의 개발 과정이나 임상 중단 등 구체적인 경위에 대해 제한적으로만 접근이 가능한 제3자의 부정확한 보도 또는 논평·의견 등이 무분별하게 확대됨으로써 발생한 시장 공포에 기인했다고 볼 여지도 상당합니다"라고 지적했습니다.''인보사 사태''와 관련해 소액주주들은 비슷한 취지의 손해배상 소송을 다수 제기했지만, 법원은 잇따라 주주 패소로 판결하고 있습니다.법원은 지난해 12월 피해 주주 170여명이 낸 64억대의 손해배상 소송에서 원고 패소로 판결한 데 이어 지난달 주주 500여명이 낸 86억원 규모의 손해배상 소송에서 원고 청구를 기각했습니다.이달 들어서도 주주 1천82명이 낸 197억원 규모의 손해배상 청구 등을 원고 패소로 판결했습니다.코오롱생명과학과 티슈진 경영진 및 임원들은 인보사 사태와 관련한 별도의 형사재판에서도 무죄를 선고받았습니다.이웅열 명예회장은 2017년 11월부터 2019년 3월까지 인보사를 허가받은 성분과 다른 ''신장유래세포'' 성분으로 제조·판매해 160억원의 매출을 올린 혐의(약사법·자본시장법 위반) 등으로 2020년 7월 기소됐으나 1·2심에서 모두 무죄가 선고됐습니다.함께 재판에 넘겨진 이우석 전 코오롱생명과학 대표 등도 1심과 항소심에서 모두 무죄를 선고받았습니다. 해당 판결은 검찰의 상고 포기로 확정됐습니다.당신의 제보가 뉴스로 만들어집니다.SBS Biz는 여러분의 제보를 기다리고 있습니다.홈페이지 = https://url.kr/9pghjn', NULL, 'SBS Biz', 'https://n.news.naver.com/mnews/article/374/0000495069', 'https://imgnews.pstatic.net/image/374/2026/02/28/0000495069_001_20260228094107752.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-28 09:39:07', 0, true, '2026-03-09 05:53:37.151893') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (789, '[주총 포커스] ''합병 앞둔'' 코오롱인더스트리, 경영진 재정비', '코오롱 원앤온리타워 전경 /사진 제공=코오롱인더스트리코오롱ENP와 합병을 앞둔 코오롱인더스트리가 사내이사진을 재정비한다. 기존 허성 대표 외에 사내이사 3인이 추가로 선임될 예정이며 특히 법률 전문가인 이병인 최고법무책임자(CLO)가 사내이사로 합류하는 점이 눈길을 끈다. 최근 화학 및 산업자재 분야에서 소송이 빈번하게 발생하면서 법률전문가를 사내이사로 선임해 전문성을 강화한 것으로 보인다.코오롱인더스트리는 오는 3월 31일 서울 마곡동 코오롱 원앤온리타워에서 제16기 정기주주총회를 열고 △김민태 FnC부문 부사장 △우영진 제조부문 최고재무책임자(CFO) △이병인 제조부문 CLO 등 사내이사 3인 선임의 건을 의결할 계획이다.코오롱인더스트리는 고부가 스페셜티 중심의 제품 포트폴리오 구축과 운영 효율화를 위해 지난해 11월 자회사인 코오롱ENP와의 합병을 결정했다. 코오롱ENP는 고기능성 엔지니어링 플라스틱 소재 기업으로 폴리옥시메틸렌(POM), 컴파운드, 복합소재 등 고부가 제품들을 자동차, 의료와 같은 첨단 산업에 공급하고 있다. 양사의 합병 기일은 올해 4월 1일이다.양사의 합병으로 인사에도 일부 변화가 생겼다. 지난해 연말 인사에서 김영범 코오롱ENP 대표가 코오롱글로벌 대표로 이동했으며, 김민태 코오롱ENP 부사장이 코오롱인더스트리 FnC부문 대표로 내정됐다.그간 코오롱인더스트리는 제조부문 대표와 패션 사업을 담당하는 FnC부문 대표 등 각자대표 체제를 유지해왔다. 이사회에는 지주사인 ㈜코오롱 또는 계열사 임원, CFO, COO 등이 사내이사로 참여해왔다.이번 사내이사 선임에서 가장 눈에 띄는 점은 이병인 CLO의 합류다. 이 CLO는 △2011년 폴 헤이스팅스(Paul Hastings LLP) 미국변호사 △2015년부터 2025년까지 김앤장 법률사무소 미국변호사로 활동했다. 2025년 7월 코오롱인더스트리 법무실장으로 합류했으며 올해부터 CLO로서 사내이사로 참여할 예정이다.최근 화학 및 산업자재 분야의 경쟁이 치열해지면서 기업 간 특허 분쟁도 빈번하게 발생하고 있다. 실제로 코오롱인더스트리는 HS효성첨단소재와 약 3년간 특허 소송을 이어왔으며 이달 13일 양사 합의하에 특허 분쟁 종료 협약을 체결했다. 이 CLO의 사내이사 합류 역시 향후 특허 분쟁은 물론 미국 시장에서의 소송에 원만하게 대처하기 위한 것으로 풀이된다.코오롱인더스트리 이사회는 이 CLO에 대해 "김앤장 법률사무소에 재직했던 법률 전문가이자 현재 당사 제조부문 CLO"라며 "법률 분야의 전문성과 풍부한 경험을 바탕으로 회사의 중요한 경영상 의사결정과 발전에 기여할 것으로 판단해 사내이사 후보로 추천했다"고 설명했다.코오롱인더스트리는 외부 인사인 우영진 CFO도 사내이사로 신규 선임할 예정이다. 우 CFO는 △2014년 ㈜한화 지원부문 재무팀 △2020년 한화디펜스 재무실장 △2022년 대우조선해양 인수단 재무담당 임원 △2023년 한화오션 재무실장 등을 거쳐 2025년 4월 코오롱인더스트리 CFO로 합류했다.이사회는 우 CFO에 대해서도 "한화오션㈜ 재무실장 등을 역임한 재무 및 금융 분야 전문가"라며 "경영 전반에 대한 높은 이해도와 풍부한 경험을 기반으로 중요한 경영상 의사결정과 발전에 기여할 것으로 판단해 사내이사 후보로 추천했다"고 밝혔다.한편 코오롱인더스트리는 이번 주총에서 신규 사외이사로 △강민아 이화여자대학교 행정학과 교수 △김재욱 비엔더블유인베스트먼트 대표 등을 신규 선임할 계획이다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000080064', 'https://imgnews.pstatic.net/image/293/2026/02/27/0000080064_001_20260303093309625.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-27 16:16:13', 0, true, '2026-03-09 05:53:37.151893') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (797, '아세아, 자기주식 40억 소각…1주당 630원 중간배당', '아세아가 40억원 규모의 자기주식 소각과 보통주 1주당 630원의 중간배당을 결의했다고 7일 공시했다.아세아는 기취득 자기주식 1만1494주를 이번 달 26일 소각할 예정이다. 배당가능이익 범위 내에서 취득한 것으로, 발행주식의 총수는 감소하지만 자본금은 줄지 않는다. 소각 예정금액 40억원은 전날(6일) 종가 34만8000원을 기준으로 산정됐다.이와 함께 아세아는 보통주 1주당 650원의 중간배당도 실시한다. 배당금 총액은 10억3900만원가량이다. 배당기준일은 10월31일로, 배당금 지급 예정일자는 14일이다.아세아는 "소각 예정일은 관계기관과 협의에 따라 변동될 수 있다"고 설명했다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000074719', 'https://imgnews.pstatic.net/image/293/2025/11/07/0000074719_001_20251107144909255.png?type=w800', 'NEWS_ETC', NULL, '2025-11-07 14:49:09', 0, true, '2026-03-09 05:53:59.111060') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (790, 'VIP운용, 아세아 지분 낮추고 ‘단순투자’로 전환…주주행동 사실상 종료', '2021년부터 아세아 대상 주주환원 정책 변화 요구“회사 충분히 선진화”가치투자 운용을 하는 VIP자산운용이 지주회사 아세아를 상대로 이어온 주주행동주의를 사실상 멈출 것으로 보인다. VIP자산운용은 최근 2021년부터 꾸준히 늘려온 아세아 지분을 매각하기 시작했으며, 주식 보유 목적 또한 기존 ‘일반투자’에서 경영권 영향 의사가 없는 ‘단순투자’로 변경 공시했다.. /아세아 홈페이지 캡쳐18일 금융감독원 전자공시시스템에 따르면, VIP자산운용은 주식 등 대량보유상황 보고서를 통해 아세아 지분율을 기존 11.81%에서 10.61%로 낮췄다고 공시했다.특히 보유 목적도 변경됐다. 기존 일반투자 목적에서 단순투자로 전환된 것이다. 지분 보유 목적 중 일반투자는 경영권 영향 없이 의결권이나 신주인수권 등 적극적인 주주 활동을 의미하며, 단순투자는 회사 경영과 무관하게 최소한의 주주 권리만 행사하겠다는 뜻이다.아세아는 아세아시멘트와 아세아제지 등을 산하에 둔 지주사다. 아세아 3사는 그동안 주가 저평가 지적을 받아왔으며, 이에 따라 지난 몇 년간 활발한 주주행동주의 활동이 이어졌다.VIP자산운용은 2021년 8월 처음으로 아세아 지분을 5% 이상 확보한 뒤 지분율을 꾸준히 높여 11.81%까지 확대했으며, 보유 목적을 일반투자로 변경해 주주행동을 시작했다. 아세아시멘트에서도 같은 해 9월 지분 6.36%를 확보한 후 7.66%까지 늘렸다.이후 여러 차례 주주서한을 보내고 경영진 미팅을 통해 주주환원 정책 변화를 지속적으로 요구해왔다. 주주환원 활동 시작 전 12만원대였던 아세아 주가는 최근 34만원대를 기록하며 166% 이상 상승했다.아세아는 주주행동이 시작된 후 현금배당 강화, 자사주 매입·소각 등을 시행하며 주주환원 정책을 펼치기 시작했다. 아세아는 지난해 12월 2개년 주주환원 정책을 발표했다. 여기에는 올해부터 내년까지 연간 현금배당을 5600원(중간배당 포함) 이상 실시하고, 연간 80억원 이상 취득할 예정이라는 내용이 담겼다. 2021년 당시 3000원이었던 주당배당금은 점차 상승해 지난해 5330원까지 올랐다.VIP자산운용 관계자는 “이제는 압박을 하지 않더라도 충분히 주주 환원에 적극 나서고 있다”면서 “더 이상 일반투자 목적으로 가져갈 필요가 없다고 생각해 단순투자 목적으로 변경했다”고 했다.', NULL, '조선비즈', 'https://n.news.naver.com/mnews/article/366/0001131030', 'https://imgnews.pstatic.net/image/366/2025/12/18/0001131030_001_20251218152214718.jpg?type=w800', 'NEWS_ETC', NULL, '2025-12-18 15:22:14', 0, true, '2026-03-09 05:53:59.111060') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (791, '내년 주총 노리는 행동주의…''타깃 기업'' 리스트 나온다', '올 하반기부터 행동주의 기지개상법 개정에 내년 본격 활동 관측현금 쌓아두고 주주환원은 외면적극적 배당 필요한 기업들 표적저평가 웹젠·DL이앤씨 등 주목[서울경제]새 정부 출범 후 상법 개정이 연달아 이뤄지면서 내년 3월 정기 주주총회에서 행동주의 펀드들이 활발하게 활동할 것이라는 관측이 나온다. 증권가에서는 풍부한 현금성 자산을 보유하고도 주주 환원에 소극적인 저평가 기업들이 행동주의 펀드의 표적이 될 가능성이 큰 것으로 보고 있다.10일 LS증권이 블룸버그 자료를 분석한 결과 올해 1~10월 국내 기업에 대한 행동주의 펀드 캠페인 수는 21건으로 2023년(42건), 2024년(49건) 대비 절반 수준에 그쳤다. 일부 기업들이 기업가치 제고(밸류업) 계획을 내놓았고 비상계엄 사태로 인한 정치적 불확실성이 한동안 이어지면서 행동주의 활동은 전년보다 다소 위축됐다.다만 올해 9월 라이프자산운용이 KCC에 대한 공개 주주 제안을 제기하고 10월 얼라인파트너스가 스틱인베스트먼트 지분율을 높이면서 적극적 주주활동을 공식화하는 등 하반기부터 활동이 재개되는 모습이다. 특히 새 정부에서 1차 상법 개정으로 이사의 주주 충실 의무를 시행한 데 이어 2차 상법 개정으로 집중투표제 의무화, 분리선출 감사위원 확대 등을 차례로 도입한 만큼 내년 정기 주총에서 행동주의 활동이 본격화할 것이라는 관측이 나온다.행동주의 펀드의 표적이 될 만한 저평가 종목들도 여전히 많다는 평가다. 유가증권·코스닥 합산 주가순자산비율(PBR) 1배 미만 기업은 전체 상장사 대비 51%로 주요국 대비 여전히 높은 수준일 뿐만 아니라 해당 기업들의 절반이 순현금 기업이라는 것이다.증권가에서는 주주 환원이 필요한 저평가 종목을 찾는 움직임도 활발해지고 있다. IBK투자증권은 기업가치 제고 계획을 발표하거나 행동주의 활동이 발생했을 때 주가 상승 가능성이 큰 기업으로영원무역(111770)·농심(004370)·에스엘(005850)·HD현대건설기계(267270)·세방전지(004490)·경동나비엔(009450)·아세아(002030)·동아쏘시오홀딩스(000640)등을 꼽았다. 자기자본 대비 현금성 자산이 5~20%로 충분하지만 주주 환원 성향은 20% 미만인 기업들이다. LS증권도 행동주의 펀드들이 배당 확대 등 주주 제안 대상으로 삼을 가능성이 큰 기업으로삼성전자(005930)·삼성물산(028260)·LG(003550)·농심·대덕전자(353200)등을 꼽았다. 권순호 IBK투자증권 연구원은 “이익과 현금 창출력이 양호한데 그동안 주주 환원 성향이 낮았던 기업들은 구조적으로 디스카운트를 받고 있다”며 “주주 환원 정책이 달라지면 재평가를 통해 크게 상승할 여지가 있다”고 했다.iM증권은 행동주의 펀드가 개입할 가능성이 큰 기업으로DL이앤씨(375500)를 꼽았다. 올해 3분기 말 기준으로 현금성 자산 등 순현금 9340억 원, 여의도 글래드 등 투자부동산 5494억 원, 관계기업 투자주식 장부가 6007억 원 등으로 다수 자산을 보유하고도 시가총액이 1조 6000억 원에 불과하기 때문이다. 최대주주 지분율도 24.82%로 지배력이 낮은 수준인 데다 주주 환원 정책도 보수적인 만큼 타깃이 될 수 있다는 분석이다.DS투자증권은웹젠(069080)의 현금성 자산이 시가총액보다 많다며 게임 종목 가운데 독보적인 저평가주로 거론했다. 주주 환원이나 지분투자를 활용하면 재평가를 받을 수 있다는 설명이다. NH투자증권도기업은행(024110)에 대해 적극적인 배당 정책의 필요성을 강조하고 나섰다.김윤정 LS증권 연구원은 “국내 증시 자체는 사상 최고치를 기록했으나 주요국과 비교했을 때 자기자본이익률(ROE) 대비 PBR이 낮은 ‘코리아 디스카운트’는 계속되고 있다”며 “행동주의 펀드들에 한국 증시는 여전히 개선의 여지가 많은 시장인 만큼 캠페인에 나서기 매우 적절한 대상”이라고 했다.', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004565795', 'https://imgnews.pstatic.net/image/011/2025/12/10/0004565795_001_20251210235503652.jpg?type=w800', 'NEWS_ETC', NULL, '2025-12-10 17:52:18', 0, true, '2026-03-09 05:53:59.111060') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (792, '오늘의 메모[12월 10일]', '[서울경제]<코스피>▲주권변경상장=아세아(002030)·아세아시멘트(183190)(주식소각)<코스닥>▲공모주청약=알지노믹스(주관사 삼성) IBKS제25호스팩(IBK) 미래에셋비전스팩11호(미래에셋) ▲구주주유상청약=포바이포(389140)▲실권주청약=노을(376930)(주관사 한국)알에스오토메이션(140670)(삼성) ▲보통주추가상장=SG(255220)·인벤티지랩(389470)(국내CB) ▲주권변경상장=코이즈(121850)(감자)화신정공(126640)(주식소각) ▲신규상장=페스카로(0015S0)', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004565115', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2025-12-09 10:58:15', 0, true, '2026-03-09 05:53:59.111060') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (793, '[서울데이터랩]12월 2일 코스피 주요 종목 마감시황', '12월 2일 한국거래소에 따르면, 동양고속(084670)은 전 거래일 대비 29.96% 상승한 16,440원에 거래를 마감하며 금일 코스피 상승률 1위를 차지했다. 천일고속(000650)은 29.81% 상승한 307,000원에 거래를 마치며 뒤를 이었다. 현대오토에버(307950)는 18.65% 상승한 233,500원에, 코오롱모빌리티그룹(450140)은 17.76% 상승한 12,000원에, 세기상사(002420)는 13.72% 상승한 6,050원에 거래를 마감했다.코리아써키트는 전 거래일 대비 5.67% 하락한 34,100원에 거래를 마감하며 금일 코스피 하락률 1위를 기록했다. 경인양행은 5.11% 하락한 3,160원에, 아세아는 4.67% 하락한 378,000원에 거래를 마쳤다. 한미약품은 4.66% 하락한 430,000원에, 한미사이언스는 4.39% 하락한 37,000원에 거래를 마감했다.시가총액 상위 종목 중 삼성전자가 13,619,200주의 거래량을 바탕으로 2.58% 상승했다. SK하이닉스는 2,683,882주의 거래량을 기록하며 3.72% 상승했다. LG에너지솔루션은 200,831주의 거래량으로 0.48% 상승했고, 삼성바이오로직스는 33,670주의 거래량을 기록하며 0.30% 상승했다. 삼성전자우는 2,162,299주의 거래량으로 2.10% 상승했다. 현대차는 1,055,288주의 거래량을 기록하며 4.52% 상승했다. KB금융은 1,336,269주의 거래량을 보이며 4.51% 상승했다. 두산에너빌리티는 2,978,860주의 거래량으로 0.13% 상승했다. HD현대중공업은 151,483주의 거래량으로 0.97% 상승했다. 기아는 976,373주의 거래량을 기록하며 4.19% 상승했다.금일 코스피 주요 종목들은 대체로 상승세를 보이며 긍정적인 흐름을 나타냈다. 투자자들은 개별 종목의 실적과 시장 동향을 주의 깊게 살피며 투자 결정을 내리는 것이 중요하다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003597406', 'https://imgnews.pstatic.net/image/081/2025/12/02/0003597406_001_20251202161810362.png?type=w800', 'NEWS_ETC', NULL, '2025-12-02 16:18:10', 0, true, '2026-03-09 05:53:59.111060') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (794, '산일전기·한화엔진·LG씨엔에스, 코스피200에 신규 편입', 'HD현대미포·OCI 등 편출…코스닥150도 16개 종목 리밸런싱서울 여의도 한국거래소 전경(서울=뉴스1) 한유주 기자 = 산일전기(062040)와 한화엔진(082740), LG씨엔에스(064400) 등 7개 종목이 다음 달부터 코스피200지수에 새롭게 편입된다.한국거래소는 주가지수운영위원회 심의 결과 다음 달 12일부터 코스피200 8종목, 코스닥150 16종목, KRX300 22종목이 교체된다고 18일 밝혔다.코스피200 지수에는 산일전기와 한화엔진, LG씨엔에스, 이수페타시스(007660), 현대오토에버(307950), 파라다이스(034230), 아세아(002030) 등 7개 종목이 새롭게 편입된다.HD현대중공업에 합병되는 에이치디현대미포(010620)와 HDC(012630), 한화비전(489790), 덴티움(145720), 하나투어(039130), KG모빌리티(003620), TCC스틸(002710), OCI(456040) 등 8개 종목은 코스피200지수에서 편출된다.한편 삼성바이오로직스 인적분할로 신설되는 삼성에피스홀딩스는 재상장 다음 매매거래일인 오는 25일 코스피 200지수에 편입될 예정이다.코스닥150지수에는 펌텍코리아(251970), 비에이치아이(083650), LS마린솔루션, 유일로보틱스(388720), 유진로봇(056080), 감성코퍼레이션(036620), 올릭스(226950), 디앤디파마텍(347850), 인카금융서비스(211050), 로보티즈(108490), 코나아이(052400), 미코(059090), 솔트룩스(304100), 아이쓰리시스템(214430), 우리기술(032820), 클로봇(466100) 등 16개 종목이 새로 편입된다.반면 미래나노텍(095500), 아이패밀리에스씨(114840), 매일유업(267980), 아이센스(099190), 에이치엘비테라퓨틱스(115450), 바이오니아(064550), 한국기업평가(034950), 파트론(091700), 덕산테코피아(317330), 기가비스(420770), 칩스앤미디어(094360), 프로텍(053610), 아이티엠반도체(084850), 오픈엣지테크놀로지(394280), 인탑스(049070), 이엠텍(091120)은 지수에서 빠진다.정기변경 후 코스피200 구성종목은 코스피 전체 시총의 92.6%를 차지하게 된다. 코스닥150 구성종목의 코스닥 시총 비율은 56.5% 수준이다.', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008611842', 'https://imgnews.pstatic.net/image/421/2025/11/18/0008611842_001_20251118170818614.jpg?type=w800', 'NEWS_ETC', NULL, '2025-11-18 17:07:43', 0, true, '2026-03-09 05:53:59.111060') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (795, '아세아·파라다이스, 코스피200 식구 되나', '한투證, 내달 12일 정기변경 앞두고 편입 예상종목 선정한화엔진 포함 전망도… 편출종목 TCC스틸·OCI 꼽아전문가들 "한달전부터 수급 본격 유입… 선제점검 필요"코스피200 리밸런싱 편입 편출 예상 종목/그래픽=이지혜코스피200 정기변경이 한 달이 채 남지 않자 시장의 관심이 편입·편출 후보군에 쏠린다. 증권가에서는 한 달 전부터 관련 종목에 수급이 본격 유입되는 만큼 선제점검이 필요하다고 조언한다.17일 금융투자업계에 따르면 산업별 최우량 코스피 기업 200개사로 구성된 코스피200이 다음달 12일 정기변경을 앞뒀다. 종목변경은 다음달 11일 확정돼 12일부터 효력이 생긴다. 코스피200은 ETF(상장지수펀드), 인덱스펀드, 옵션 등의 기초지수로 활용돼 지수에 편출입되는 종목수급에 영향을 미친다.증권가에서는 통상 코스피200 정기변경 한 달 전부터 액티브펀드 매수수요가 본격 유입되고 변경 당일에는 인덱스펀드 자금까지 더해지며 수급 변동성이 커진다고 분석했다. 신채림 한국투자증권 연구원은 "최근 5년 반기마다 시행된 정기변경에서 편입종목들은 정기변경일 4주 전부터 평균 8.2%의 강한 상승을 보였다"며 "정기변경 당일까지 예상 편입종목에 대해 트레이딩 관점으로 접근해야 한다"고 밝혔다.한투증권은 이번 정기변경에서 파라다이스와 아세아가 편입될 것이라고 전망하는 한편 TCC스틸과 OCI는 편출될 것이라고 예상했다. 호텔과 카지노사업을 하는 파라다이스는 최근 1년간 주가가 57% 넘게 올랐다. 올해 3분기 연결기준 매출은 전년 동기대비 7% 증가한 2882억원, 영업이익은 9% 늘어난 395억원으로 증권사 추정치를 각각 1%, 23% 하회한 탓에 최근 주가가 조정받기도 했다.하지만 증권가에서는 모멘텀(상승동력)이 유효하다는 분석을 내놓았다. 김유혁 IBK투자증권 연구원은 "인스파이어 카지노사업 개시에 따라 클러스터 효과가 예상되고 그랜드하얏트 인천 웨스트타워 인수 추진으로 실적 레버리지도 기대한다"며 "별도 호텔을 짓지 않아도 501개 객실을 증축한 것과 같은 효과를 누려 카지노부문의 가파른 성장이 기대된다"고 했다.박수영 한화투자증권 연구원은 "강한 영업력을 기반으로 이미 가동률을 최대한 끌어올려 영업하고 있다"며 "꾸준히 유치 중인 신규 일본 고객에 더해 중국 고객까지 록인(lock-in)돼 내년 카지노 매출이 성장하면 이익률 개선은 필연적일 것"이라고 밝혔다.시멘트와 제지회사를 자회사로 둔 아세아는 상법개정을 통한 지주사 가치 재평가 기대감에 올들어 주가가 50% 상승했다. 이날 장중 38만4000원까지 올라 52주 신고가를 경신했다.자회사 아세아시멘트 업황회복과 비용절감에 따른 실적개선 기대가 커지면서 지주사 아세아에도 긍정적 영향이 미칠 것으로 전망된다. 이은상 NH투자증권 연구원은 "착공증가와 판가인상으로 실적개선이 기대된다"며 "연료 대체율 상승을 통한 원가절감으로 구조적 마진도 개선할 수 있고 연안과 내륙에 공장을 보유해 안정적 납품도 할 수 있다"고 밝혔다.한편 이번 코스피200 정기변경을 전후로 일부 구성종목은 합병으로 상장폐지를 앞둬 수시변경 가능성도 나온다. 삼성증권은 HD현대중공업과 합병해 상장폐지될 HD현대미포 자리를 동일한 산업재 섹터 내 예비종목인 한화엔진이 대체할 것이라고 전망했다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005279452', 'https://imgnews.pstatic.net/image/008/2025/11/18/0005279452_001_20251118042018962.jpg?type=w800', 'NEWS_ETC', NULL, '2025-11-18 04:20:00', 0, true, '2026-03-09 05:53:59.111060') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (796, '기업 공시 [11월 7일]', '[서울경제]<코스피 시장>▲더존비즈온(012510)=최대주주 변경을 수반하는 주식 매매 계약 체결 ▲아세아시멘트(183190)=자사주 41만 9112주 소각 결정 ▲아세아(002030)=자사주 1만 1494주 소각 결정 ▲대교(019680)=오로라월드와 사업협력관계 구축을 위한 45억 원 규모 자사주 상호 교환 결정<코스닥 시장>▲HPSP(403870)=이춘흥 대표 신규 선임 ▲HLB테라퓨틱스(115450)=65억 원 규모 수막구균 백신 공급 계약 체결 ▲크리스탈신소재(900250)=107억 원 규모 제3자배정 유상증자 결정 ▲율호(072770)= 제3자배정 유상증자 납입에 따라 어게인파트너스로 최대주주 변경 ▲인텍플러스(064290)=자사주 기반 교환사채 발행 결정 ▲한국큐빅(021650)=본점 소재지 변경', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004553288', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2025-11-07 16:51:11', 0, true, '2026-03-09 05:53:59.111060') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (798, '기업공시 [10월 16일]', '[서울경제]<코스피 공시>▲HMM(011200)=3조 500억 원 규모 친환경 컨테이너선 12척 국내 조선사에 발주 ▲아세아제지(002310)=보통주 1주당 50원 현금배당 ▲엑시큐어하이트론(019490)=서울교통공사와 24억 원 규모 계약 체결 ▲한화에어로스페이스(012450)=다음 달 3일 3분기 잠정 실적 발표 ▲진도(088790)=최대주주, 임병남 대표이사로 변경 ▲아세아(002030)=30억 원 규모 자사주 취득 신탁계약 체결 ▲롯데쇼핑(023530)=기업가치 제고계획 이행현황 공시 ▲삼성중공업(010140)= 드릴십 매각<코스닥 공시>▲탑런토탈솔루션(336680)=보통주 1주당 50원 중간배당 ▲나우로보틱스(459510)=5000억 원 규모 신규 시설 투자 ▲웨이비스(289930)=335억 원 규모 신주인수권부사채 발행 ▲이엠코리아(095190)=전환사채 전환가액 2377원으로 상향 조정 ▲메가스터디교육(215200)=200억 원 규모 자사주 소각 결정 ▲NHN KCP(060250)=싱가포르 법인, MPI 라이선스 취득 예비승인', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004544138', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2025-10-16 16:29:10', 0, true, '2026-03-09 05:53:59.111060') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (799, '또 쌍방울 계열사에 접근한 이 기업... 뒤에는 ‘보물선 사태’ 설계자 있다는데', '이니텍, 비비안 투자 이어 디모아 유상증자 참여모두 과거 쌍방울 계열사... 투자 과정에 이용호씨 관여본지 보도 이후 투자조합 조합원 변경 정정 공시이니텍 CI.이 기사는 2026년 1월 30일 10시 14분 조선비즈 머니무브(MM) 사이트에 표출됐습니다.코스닥 상장사 이니텍이 과거 쌍방울그룹에 속해 있던 디모아 유상증자에 참여한다. 이니텍은 지난해 9월 디모아 전환사채(CB)에 투자했다가 매각하고는 유증으로 재투자하는 상황이다. 이에 앞서서는 또 다른 쌍방울 계열사 비비안에도 투자했다.30일 투자은행(IB) 업계 및 금융감독원 전자공시시스템에 따르면, 디모아는 지난 28일 제3자 배정 유상증자 대상을 이글스유통에서 프라임라이트 투자조합1호로 변경했다. 프라임라이트조합은 이니텍이 99.98% 출자해 설립한 투자 조합이다.디모아는 과거 쌍방울그룹 계열사로, 김성태 회장의 사법 리스크가 불거진 이후 그룹이 해체되는 과정에서 팔린 바 있다. 당시 비비안 자회사였던 디모아는 현재 최대주주인 에스제이홀딩스 제1호 투자조합에 넘어갔다.디모아는 그러나 최대주주 변경에도 사정이 나아지지 않았다. 지난해 4월 유상증자 계획을 처음 발표한 이후 수차례 납입일이 연장되며 자금 모집에 난항을 겪었다. 그러나 최근 이니텍이 투자자로 나서면서 자금 유치 가능성이 높아지고 있다. 디모아는 이번 유상증자로 신주 260만주를 발행할 계획이다. 발행가액은 3700원으로 총 96억2000만원을 조달한다.이니텍과 디모아의 인연은 이번이 처음은 아니다. 이니텍은 지난해 9월 디모아가 발행한 7회차 CB에 127억원을 투자한 바 있다. 해당 CB의 발행 당시 전환가액은 6917원으로, 유상증자 발행가액의 두 배 수준이었다. 이를 전환 가능한 주식 수로 환산하면 약 183만주다.주식 전환 조건이 불가능에 가까웠던 이 CB를 이니텍은 투자 단행 약 3개월 만인 지난해 12월 전량 디모아에 매각했다. 자금 여력이 충분하지 않은 디모아가 어떤 과정을 통해 이니텍의 CB를 되사줬는지는 알려지지 않았다.아무튼 이니텍은 유상증자를 통해 CB 때와 비교하면 더 저렴한 가격에 많은 지분을 확보할 수 있게 됐다. 투자금은 127억원에서 96억2000만원으로 감소했으나, 얻을 수 있는 주식은 약 183만주에서 260만주로 오히려 증가했다. 이는 현재 최대주주인 에스제이홀딩스 조합의 특수관계인 주식을 더한 294만8772주에 육박하는 수준이다.이니텍이 디모아에 투자를 단행한 배경에는 과거 쌍방울그룹에 대한 관심이 있는 것으로 보인다. 이니텍은 지난해 12월 프라임라이트 조합을 통해 비비안 CB에 100억원을 투자한 바 있다. 지난 21일에도 자회사인 이니넥스트를 통해 비비안 CB 150억원을 추가 투자키로 했다. 해당 CB가 모두 주식으로 전환되면 이니텍은 비비안의 최대주주에 올라서게 된다.일각에서는 이니텍이 쌍방울에 관심을 보이는 배경에 이용호 전 G&G그룹 회장이 있다고 설명한다. 이 전 회장은 김대중 정부 시절 보물선 인양 사기로 시작해 권력형 비리로 번진 ‘이용호 게이트’의 당사자다. 지난해 에스제이홀딩스가 이니텍을 인수하는 과정에서 이 전 회장이 관여했다는 의혹이 이미 제기된 바 있다. 자본시장업계에서는 이에 더 나아가서 이니텍을 실질 지배하는 인물이 이 전 회장이며, 쌍방울 명함을 사용하고 서울 서빙고에 있는 쌍방울 사무실로 출근한다는 증언이 나온다.이와 관련해 이 전 회장 본인은 이니텍의 경영에 전혀 관여하고 있지 않으며, 쌍방울 명함을 사용하는 것도 사실이 아니라는 입장을 전해 왔다. 이 전 회장은 “이니텍 매각 과정에 일부 관여한 것은 맞지만, 현재 영향력이 있는 것은 아니다”며 “쌍방울과 관련 있다는 것은 음해 세력의 일방적 주장”이라고 맞섰다.한편 본지 보도 이후 이니텍은 “프라임라이트 투자조합1호에서 탈퇴했다”고 입장을 밝혀왔다. 디모아도 이날 오후 3시 42분 제3자 배정 유상증자 정정 공시를 내며 프라임라이트 투자조합 1호의 조합원이 이모씨, 박모씨로 바뀌었다고 밝혔다.', NULL, '조선비즈', 'https://n.news.naver.com/mnews/article/366/0001139770', 'https://imgnews.pstatic.net/image/366/2026/02/02/0001139770_001_20260202165212317.png?type=w800', 'NEWS_CONSUMER', NULL, '2026-02-02 06:01:11', 0, true, '2026-03-09 05:54:21.335649') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (800, '기업공시 [1월 21일]', '[서울경제]<코스피 공시>▲한화오션(042660)=7383억 원 규모 LNG선 2척 수주 ▲프레스티지바이오파마(950210)=사외이사 신규 선임 ▲한미약품(128940)=당뇨 치료제 임상 3상 승인 ▲신흥(004080)=15억 규모 자사주 소각 결정 ▲비비안(002070)=150억 규모 전환사채 발행 결정 ▲영보화학(014440)=1주당 350원 현금배당 결정 ▲HD현대에너지솔루션(322000)=2025년 연결기준 매출액 4927억 원, 영업이익 412억 원<코스닥 공시>▲윈스테크넷(136540)=30억 규모 자사주 취득 신탁계약 체결 ▲알톤(123750)=20억 규모 제3자배정 유상증자 결정 ▲디티앤씨=9억 규모 자사주 소각 결정 ▲한주에이알티(058450)=각자대표체제로 전환 ▲PS일렉트로닉스(332570)=29억 규모 자사주 소각 결정 ▲링네트(042500)=1주당 300원 현금배당 결정', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004581435', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_CONSUMER', NULL, '2026-01-21 16:40:16', 0, true, '2026-03-09 05:54:21.335649') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (801, '딥시크發 AI 혁신 1년…중국 기술주, 자립 청사진 속 상승세 지속', '딥시크 벤치마크[디지털데일리 이상일기자] 딥시크(DeepSeek)의 인공지능(AI) 기술이 글로벌 시장에 충격을 준 지 1년이 지난 지금, 중국 기술주가 새해 들어 상승세를 이어가고 있다. 주택 경기 침체와 소비 둔화 등 경기 부진 속에서도 기술 자립 전략이 투자심리를 자극하고 있다는 분석이다.18일(현지시간) 블룸버그통신에 따르면 이달 들어 중국 내 나스닥형 기술주 지수는 약 13% 상승했고, 홍콩 상장 중국 기술기업 지수도 약 6% 오르며 나스닥 100지수를 웃돌았다. 딥시크의 신형 AI 모델 공개와 정부의 기술 자립 중심 5개년 경제계획이 이 같은 상승세를 이끌고 있다.지난해 1월 27일 딥시크가 저비용 고성능 모델을 출시한 이후 알리바바와 텐센트를 비롯한 중국 대형 IT 기업들이 생성형 AI 개발에 속도를 내고 있다.로봇·비행차·정밀공작 등 다양한 산업에서도 대형 언어모델(LLM) 적용이 확산됐다. 제프리스 파이낸셜 그룹은 중국 AI 관련 33개 종목의 시가총액이 1년 새 약 7320억달러 증가했다고 밝혔다. 미국 시장의 6.5% 수준에 불과하다며 추가 상승 여력을 전망했다.한편 AI 칩 제조사 캔브라이콘 테크놀로지스는 예상 주당순이익 대비 약 120배 수준에서 거래되고 있으며, 중국 로봇 기업 지수 역시 40배 이상으로 평가된다. 과열 우려 속에서도 일부 투자자들은 낮은 비용 구조와 국가 주도형 산업 전략을 근거로 낙관적 시각을 유지하고 있다.가베칼 리서치 틸리 장 애널리스트는 “딥시크의 성공이 중국을 ‘저비용·고효율’ 모델 전략에 집중하게 만들었다”고 평가했다. 블룸버그 인텔리전스는 곧 출시될 딥시크 R2 모델이 “중국의 AI 경쟁력을 다시 부각시킬 촉매가 될 것”이라고 분석했다.3월 발표될 새 5개년 계획이 기술 자립을 강화할 경우, 관련 산업의 주가 상승세는 이어질 가능성이 높다. 윌리엄 블레어 인베스트먼트 비비안 린 서스턴은 “수익 성장과 수출 경쟁력이 맞물릴 경우 중국 주식이 미국을 앞설 수 있다”고 내다봤다.', NULL, '디지털데일리', 'https://n.news.naver.com/mnews/article/138/0002215505', 'https://imgnews.pstatic.net/image/138/2026/01/19/0002215505_001_20260119061509789.png?type=w800', 'NEWS_CONSUMER', NULL, '2026-01-19 06:15:09', 0, true, '2026-03-09 05:54:21.335649') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (802, '''비비안 구'' 이어 ''스테판 곽'' 등장…의문 가득한 LG家 윤관 관련자들', '123억 규모 종합소득세 부과 처분 취소 청구 소송지분 넘겨받고, 학비 대신 내고…의문의 인물 속속 등장12일 서울고법에서 윤관 블루런벤처스 대표가 강남세무서장을 상대로 제기한 종합소득세 부과 처분 취소 청구 소송의 항소심 2차 변론기일이 열렸다. /더팩트 DB[더팩트ㅣ이성락 기자] LG가(家) 맏사위 윤관 블루런벤처스(BRV) 대표의 100억원대 세금 불복 소송에서 기존에 알려지지 않았던 의문의 인물들이 속속 거론돼 관심이 쏠린다. 윤관 대표로부터 지분을 넘겨받은 ''Vivian Koo(비비안 구)''에 이어 윤관 대표를 대신해 자녀 학비를 낸 ''Stephen Kwok(스테판 곽)''이라는 인물이 등장했는데, 윤관 대표가 ''소득세법상 국내 거주자가 아니라 세금을 낼 수 없다''는 입장을 유지하려면 해당 관련자들에 대한 자세한 설명이 필요한 상황이다.서울고법 행정1-1부(윤승은 차문호 박형준 부장판사)는 12일 윤관 대표가 강남세무서장을 상대로 제기한 종합소득세 부과 처분 취소 청구 소송의 항소심 2차 변론기일을 열었다. 앞서 세무당국은 윤관 대표가 2016~2020년 국내에서 벌어들인 배당 소득 221억원에 대해 종합소득세 신고를 누락했다고 보고, 종합소득세 123억원을 청구했다. 이에 불복한 윤관 대표는 지난 2023년 3월부터 소송전을 벌이고 있다. 윤관 대표는 자신이 외국인(미국 시민권자)이며 국내 거주자도 아니라 세금을 낼 수 없다고 주장했고, 1심에서 완패했다.◆ 자녀 학비 대신 보낸 ''스테판 곽'' 누구?해당 재판에서는 1심 당시 언급되지 않았던 인물들이 속속 등장하고 있다. 1차 변론에서는 윤관 대표로부터 지분을 넘겨받은 ''비비안 구''가 수면 위로 떠올랐다. ''비비안 구''는 윤관 대표가 이끄는 BRV의 지배구조 최상단에 있는 BRV케이만 지분 60% 넘겨받은 중요 인물이지만 윤관 대표, BRV와의 관계가 명확히 드러나지 않고 있다. BRV케이만의 지분율은 윤관 대표 20%, 윤관 대표의 친누나 20%, ''비비안 구'' 60%다.이날 재판에서는 ''스테판 곽''이라는 이름이 나왔다. 재판부에 따르면 윤관 대표의 자금 유동성에 문제가 생기거나, 직접 은행 업무를 보기 어려울 때 대여 형식으로 국내에 돈을 송금한 인물이다. 구체적으로 ''스테판 곽''은 과거 윤관 대표의 자녀 학비를 지불했다. 특히 윤관 대표를 대신해 유명 연예인 아내 A 씨의 자녀 학비를 낸 인물과 동일인으로 파악된다. <더팩트>는 지난해 10월 자녀 학비·아파트 제공 등 ''사적 지인'' A 씨를 향한 윤관 대표의 경제적 지원 사실을 보도한 바 있다.재계에서는 ''스테판 곽'' 역시 윤관 대표의 또 다른 명의 아느냐는 추측이 제기된다. 윤관 대표는 과거 주주명부, 각종 신고서 등에 ''윤최관'', ''윤관최'' 등 여러 이름을 사용하며 신분을 숨겼다. 윤관 대표는 위조 서류로 과테말라 국적을 취득하고 병역 의무를 면탈했다는 의혹도 받고 있다.윤관 블루런벤처스 대표와 구연경 LG복지재단 대표가 지난 3월 27일 서울 송파구 잠실야구장에서 열린 2025 KBO리그 LG 트윈스와 한화 이글스의 경기를 관람하고 있다. /더팩트 DB◆ ''비비안 구·스테판 곽'' 구체화될까?세금 불복 소송에서 윤관 대표와 주변 관련자들의 관계를 구체화하는 것은 중요한 절차라는 게 재판부의 설명이다. ''스테판 곽''의 경우 ''윤관 대표와 아내 구연경 LG복지재단 대표는 생계를 같이하지 않았다''는 윤관 대표 측 주장과 관련해 신뢰성을 떨어뜨리는 존재다.앞서 윤관 대표 측은 "배우자(구연경)가 경제적으로 풍족해 윤관 대표에게 경제적으로 지원받지 않았고, 이는 생계를 같이하지 않았다고 볼 수 있다"고 주장했다. ''국내에서 생계를 같이하는 가족 및 국내 자산의 유무 등 생활 관계의 객관적 사실에 따라 윤관 대표는 국내 거주자가 맞고, 세금도 내야 한다''는 1심 판결을 뒤집기 위해 윤관·구연경 부부를 경제적으로 분리하려는 시도다. 다만 재판부는 "재산이 많은 배우자가 있어 경제적으로 분리됐다고 이야기하는데, 정작 본인(윤관)의 유동성이 좋지 않을 때 남(''스테판 곽'')에게 돈을 빌려서까지 왜 (자녀) 학비를 냈는지 의문이 생긴다"며 "입증할 수 있으면 입증해달라"고 밝혔다.''비비안 구''는 해당 재판의 쟁점과 더욱 직접적으로 관련이 있다. 윤관 대표 측은 국조법상 특정외국법인 유보소득 배당간주 규정에 따라 과세하기 위해선 윤관 대표가 BRV케이만 지분 50% 이상 보유해야 하지만, ''비비안 구''를 제외하고 자신과 누나 지분을 더하면 40%에 불과해 과세 요건이 성립되지 않는다고 주장한다. 반대로 세무당국은 ''비비안 구'' 지분 역시 실질적으로 윤관 대표가 지배하고 있다고 보고 있다. 재판부는 "과반 주주인 ''비비안 구''의 역할 등에 대해 밝힐 필요가 있다는 것이 재판부의 생각"이라고 말했다.이날 재판부는 윤관 대표 측 주장에 대해 여러 의문을 제기하며 뒷받침할 수 있는 추가 설명·자료를 요청했다. /더팩트 DB◆ 윤관 대표 측 주장에 재판부 연신 ''갸우뚱''윤관 대표 측 변호인단의 고심은 깊어질 전망이다. 먼저 윤관 대표 측은 명의신탁이 아닌, ''비비안 구''가 BRV케이만 지분의 실질적 귀속자임을 스스로 증명해야 할 것으로 보인다. 이를 증명하지 못한다면 코너에 몰릴 가능성이 크다.''비비안 구'', ''스테판 곽'' 외에도 의문점을 해소해야 할 부분은 상당히 많다. 실제로 이날 재판부는 "(윤관 대표 측 주장을) 인정하기 어려워 뒷받침할 만한 게 더 있으면 좋겠다"고 수차례 언급했다.대표적으로 ''과세 관할 구역''이 있다. 이날 윤관 대표 측은 "(강남세무서가) 관할 세무서가 아닌 것은 중대하고 명백한 하자(瑕疵)"라고 설명했으나, 재판부는 "(윤관 대표의) 주민등록상 주소가 없는 상황이기 때문에 사업장 소재지(강남구 신사동 BRV코리아 사무실)로 충분히 할 수 있다는 입장이긴 하다"고 답했다. 강남세무서 측도 "통상적으로 우리나라에 주소지가 있는 사람에 관해 다른 관할에서 (세금) 처분을 보냈다면 무효일 수 있겠으나, 주민등록이 말소된 윤관 대표의 경우에는 본질적으로 차이가 있다"고 강조했다.국내 거주자가 아니라면, 어느 나라에 거주하고 있는지도 소명해야 할 대목이다. 윤관 대표 측은 미국 거주자라고 반복 주장하고 있으나, 정작 과세 기간 동안 미국에서 부담한 세금액은 줄어드는 흐름이었다. 또 윤관 대표 측이 직접 작성한 출입국 자료가 재판부에 제출됐지만, 이 또한 현 단계에서 신뢰할 수 없고, 윤관 대표가 어디에서 거주하고 있는지 명확히 증명할 수 있는 내용이 아니다. 재판부는 "원고 측이 우리나라 거주자가 아니라고 주장하고 있는 건 알겠다. 그런데 본인의 주된 거주지가 어디이고, 세금을 어디에서 내고 있는지 잘 모르겠다"며 "여러 나라에 오갔다는 건 원고의 일방적인 내용이다. 신빙성을 인정하기 어렵다"고 밝혔다.다음 기일은 내년 2월 27일 오후 2시 5분이다. 재판부는 "이 사건은 간단치 않다. 조금 더 깊게 들어갈 수밖에 없다"며 "윤관 대표 측은 다음 기일까지 (의문점에 대해) 답변을 해 주시고, 자료가 있다면 제출해달라"고 말했다.발로 뛰는 더팩트는 24시간 여러분의 제보를 기다립니다.▶카카오톡: ''더팩트제보'' 검색▶이메일: jebo@tf.co.kr▶뉴스 홈페이지: http://talk.tf.co.kr/bbs/report/write', NULL, '더팩트', 'https://n.news.naver.com/mnews/article/629/0000452917', 'https://imgnews.pstatic.net/image/629/2025/12/12/202557501765519679_20251218172210204.jpg?type=w800', 'NEWS_CONSUMER', NULL, '2025-12-12 15:57:12', 0, true, '2026-03-09 05:54:21.335649') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (803, '쌍방울그룹 3개 계열사 결국 상장 폐지… 17~19일부터 정리 매매', '김성태 전 회장 횡령·배임으로 상장 폐지 결정김성태 전 회장의 횡령·배임 혐의로 거래 정지된 쌍방울·광림·퓨처코어 등 3개 쌍방울그룹 계열사가 결국 상장 폐지된다.한국거래소는 13일 쌍방울과 광림, 퓨처코어가 법원에 제기한 상장폐지 결정 효력정지 가처분 신청이 모두 기각돼 17~19일부터 정리 매매에 들어간다고 밝혔다. 쌍방울은 19일부터 27일까지, 퓨처코어와 광림은 각각 17일부터 25일까지 정리 매매가 이뤄진다.서울 용산구 쌍방울 그룹 본사./뉴스1이들 쌍방울그룹 계열사는 지난 2023년 7월 김 전 회장이 특정경제범죄가중처벌법 위반(배임·횡령) 혐의로 기소된 이후 상장 폐지 대상이 됐다. 김 전 회장은 쌍방울로 하여금 광림이 보유한 비비안 주식을 정당한 가격보다 비싸게 매수하게 하는 등 광림에 부당 이익을 안겨 준 혐의를 받았다.김 전 회장의 횡령·배임 혐의 발생 금액은 98억4000만원이다. 이는 쌍방울 자기자본의 7.1%에 해당하는 규모로, 유가증권시장 상장 규정상 이는 상장 적격성 실질 심사 사유에 해당한다.김 전 회장은 2019년 이화영 전 경기도 평화부지사 요청으로 북한에 800만달러를 대납했다는 이른바 ‘쌍방울 불법 대북 송금 사건’에도 연루됐다.이후 쌍방울은 거래소에 경영 개선 개획을 제출했지만, 거래소는 이를 종합적으로 검토한 뒤 올해 2월 최종적으로 상장 폐지를 결정했다.광림과 퓨처코어는 특수관계인 간 자금 거래와 경영 투명성 훼손 문제로 상장 폐지 결정을 받았다. 이들 회사는 법원에 상장폐지 결정 효력정지 가처분 신청을 제기했지만, 법원은 이를 받아들이지 않았다.쌍방울그룹은 올해 초 그룹 해체 작업을 시작했다. 지난 1월 쌍방울을 뷰티 기업 네이처리퍼블릭에 매각했고, 산하 회사들은 독자 경영에 나섰다.', NULL, '조선비즈', 'https://n.news.naver.com/mnews/article/366/0001122743', 'https://imgnews.pstatic.net/image/366/2025/11/13/0001122743_001_20251113163814113.jpg?type=w800', 'NEWS_CONSUMER', NULL, '2025-11-13 16:38:14', 0, true, '2026-03-09 05:54:21.335649') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (815, '[주목! 이 상품] 경농 ‘알투도’, 팜한농 ‘노블킬’', '흰가루병에 효과적인 신제품 살균제(사진)다.국내 최초로 도입되는 ‘피리다진계’ 신물질을 사용해 농가에서 주로 사용하던 흰가루병 살균제와 교차저항성이 없다. 흰가루병을 95% 이상 예방할 수 있고 28일 이상 약효가 지속된다. 업체 관계자는 “흰가루병이 20% 발병했을 때도 치료 효과가 있다”고 말했다.특수 코팅 구조로 만든 토양 살충제(사진)다.입자 겉면엔 토양 해충을 방제하는 ‘비펜트린’이 있고, 내부엔 식물의 즙을 빨아 먹는 해충에 효과적인 ‘딤프로피리다즈’가 있다. 외부 약제가 작은뿌리파리 등을 빠르게 방제하고 내부 약제는 진딧물 등을 방제한다.', NULL, '농민신문', 'https://n.news.naver.com/mnews/article/662/0000085167', 'https://imgnews.pstatic.net/image/662/2025/12/26/0000085167_001_20251226050202954.jpg?type=w800', 'NEWS_ETC', NULL, '2025-12-26 05:02:02', 0, true, '2026-03-09 05:54:46.133521') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (804, '비비안, 신규 브랜드 ''샌디즈'' 론칭…데일리웨어 신시장 공략', '샌디즈 홍보 사진./사진제공=비비안비비안은 오는 31일 신규 브랜드 ''샌디즈(SANDIES)''를 공식 론칭한다고 30일 밝혔다. 이번 론칭을 통해 밀레니얼과 Z세대를 중심으로 한 젊은 소비층의 데일리웨어 시장을 선점하고 브랜드에 새로운 활력을 불어넣겠다는 계획이다.''샌디즈''는 체형의 다름을 교정하기 보다는 인간 본질과 기초에 집중한 브랜드로 쌓이고 다져져 단단한 기반이 되는 모래의 특성에서 영감을 받아 탄생했다. 퓨징 심리스 언더웨어로 자사 온라인몰에서 구매 가능하다.''Where flow becomes form(흐름이 형태가 되는 곳), 보이지 않지만 견고하게, 가볍지만 무너지지 않게''라는 슬로건 아래 ''눈에 띄지 않는 곳에서부터의 편안함''을 키워드로 한 베이스웨어 컬렉션이다.샌디즈의 첫 컬렉션은 △코어웨이브세트 △레이어슬리브리스 △멜란지코튼세트 △샌드데일리세트 △슬릭코어세트 △네트뮤즈세트 등 총 6종으로 구성됐다. 모래의 물결을 형상화한 유려한 곡선 패턴과 와이어 없는 안정적 지지력, 스킨·화이트·브라운·핑크 등 자연스러운 컬러로 깔끔하면서도 세련된 무드를 완성했다.비비안의 60년 노하우에 퓨징 기술을 적용해 봉제선 없는 심리스 구조를 구현했으며 겉옷 위로 자국이 드러나지 않아 깔끔하고 자연스러운 실루엣을 완성했다.또 식물성 단백질 추출물로 보습 처리된 무자극 보습 섬유와 이중직 신축 원단을 사용해 피부 자극을 최소화하고 장시간 착용해도 쾌적함이 유지된다. 특히 자체 개발한 샌디즈의 곡선 패턴은 움직임에 따라 유연하게 반응해 안정적인 핏감을 선사한다.비비안 관계자는 "샌디즈는 단순한 속옷이 아닌 인간 본질의 편안함과 자연스러움에 집중한 베이스웨어"라며 "앞으로 다양한 라인업으로 카테고리를 확장해 나갈 계획"이라고 말했다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005270585', 'https://imgnews.pstatic.net/image/008/2025/10/30/0005270585_001_20251030093618207.jpg?type=w800', 'NEWS_CONSUMER', NULL, '2025-10-30 09:35:21', 0, true, '2026-03-09 05:54:21.335649') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (805, '디모아, 최대주주 변경', '[이데일리 원다연 기자] 디모아(016670)는 최대주주가 비비안에서 에스제이홀딩스 제1호 투자조합으로 변경됐다고 1일 공시했다.변경후 최대주주의 소유 비율은 34.93%다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006130758', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_CONSUMER', NULL, '2025-10-01 16:27:08', 0, true, '2026-03-09 05:54:21.335649') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (806, '[단독] 차바이오텍, 제이준코스메틱 인수... 4개월만에 또 주인 바뀌어', '1주당 3만원 안팎 가격에 인수…주가 급등차바이오텍이 계열사를 앞세워 유가증권시장에 상장된 화장품 제조 업체 제이준코스메틱을 인수한다.30일 투자업계에 따르면 차바이오텍의 계열사 차헬스케어는 제이준코스메틱이 진행하는 유상증자에 참여해 새로운 최대주주에 등극할 예정이다. 차헬스케어 외 다른 계열사도 이번 인수전에 참여할 예정이다. 이들은 경영권 프리미엄을 포함해 1주당 3만원 안팎의 매매 대금을 지급할 것으로 알려졌다.이에 따라 제이준코스메틱은 불과 4개월 만에 새로운 최대주주를 맞게 됐다. 앞서 메타엑스1호조합은 지난 6월 회사가 추진한 100억원 규모의 유상증자에 참여해 최대주주에 해당하는 지분을 확보했다.제이준코스메틱마스크팩 등 화장품을 제조하는 제이준코스메틱은 그동안 상당한 부침을 겪었다. 당초 회사는 쌍방울그룹 지배구조에서 핵심 역할을 했다. 쌍방울그룹의 핵심인 광림의 최대주주로, 쌍방울→비비안→디모아→엔에스이엔엠→제이준코스메틱→광림→쌍방울에 이르는 순환출자 고리를 형성했다.그런데 쌍방울그룹이 해체되면서 계열사를 매각했고 제이준코스메틱의 지배구조도 바뀌었다. 기존 최대주주이던 엔에스이엔엠이 보유한 지분을 그대로 두고 제3자 유상증자를 통해 새로운 투자자를 유치한 것이다.제이준코스메틱의 주가는 이날 큰 폭 오름세를 보이고 있다. 전날 11% 넘게 상승한 데 이어 이날은 가격 제한폭까지 올랐다.', NULL, '조선비즈', 'https://n.news.naver.com/mnews/article/366/0001112054', 'https://imgnews.pstatic.net/image/366/2025/09/30/0001112054_001_20250930160613042.jpg?type=w800', 'NEWS_CONSUMER', NULL, '2025-09-30 15:28:12', 0, true, '2026-03-09 05:54:21.335649') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (807, '[서울데이터랩]STX그린로지스 9.86% 상승…실시간 상승률 1위', '1일 오전 9시 10분 STX그린로지스(465770)가 등락률 9.86%로 상승률 1위를 차지했다. STX그린로지스는 개장 직후 10분간 52,541주가 거래되었으며 주가는 전 거래일 대비 720원 오른 8,020원이다.한편 STX그린로지스의 PER은 4.40으로 상대적으로 저평가를 받고 있을 가능성을 시사하며, ROE는 48.26%로 수익성이 매우 높은 수준이다.이어 상승률 2위 제이준코스메틱(025620)은 현재가 7,510원으로 주가가 8.37% 상승하고 있다. 상승률 3위 HJ중공업(097230)은 현재 20,200원으로 6.99% 상승하며 활발한 거래를 보이고 있다. 상승률 4위 깨끗한나라(004540)는 6.39% 상승하며 2,165원에 거래되고 있다. 상승률 5위 인바이오젠(101140)은 5.33%의 상승세를 타고 12,840원에 거래되고 있다.6위 SJM(123700)은 현재가 3,560원으로 5.01% 상승 중이다. 7위 지역난방공사(071320)는 현재가 80,600원으로 4.81% 상승 중이다. 8위 신영증권(001720)은 현재가 155,400원으로 4.30% 상승 중이다. 9위 비비안(002070)은 현재가 759원으로 3.83% 상승 중이다. 10위 이화산업(000760)은 현재가 12,270원으로 3.54% 상승 중이다.이밖에도 한화에어로스페이스(012450) ▲3.51%, 우진아이엔에스(010400) ▲3.37%, 세진중공업(075580) ▲2.83%, 농심홀딩스(072710) ▲2.76% 등을 기록하며 시장에서 활발히 거래되고 있다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003570497', 'https://imgnews.pstatic.net/image/081/2025/09/01/0003570497_001_20250901093116152.png?type=w800', 'NEWS_CONSUMER', NULL, '2025-09-01 09:31:16', 0, true, '2026-03-09 05:54:21.335649') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (808, '비비안, CB 전환가액 775원→755원 조정', '여성내의류 전문업체 비비안이 제3회차 무기명식 이권부 무보증 사모 전환사채(CB)의 전환가액을 775원에서 755원으로 조정한다고 20일 밝혔다. 이번 전환가액 조정은 최근 시가 하락에 따른 것이기에 별도의 이사회 결의는 하지 않았다.해당 CB는 1개월, 1주일, 최근일 주가를 산술평균한 기준가액(751.57원)과 최근일 가중산술 평균주가(754.55원) 가운데 높은 값이 기존 전환가액보다 낮으면 하향 조정할 수 있다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000071369', 'https://imgnews.pstatic.net/image/293/2025/08/20/0000071369_001_20250820153613137.png?type=w800', 'NEWS_CONSUMER', NULL, '2025-08-20 15:36:13', 0, true, '2026-03-09 05:54:21.335649') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (838, '도화엔지니어링, 지난해 영업익 324억…흑자전환', '[헤럴드경제=증권부] 도화엔지니어링은 지난해 연결기준 영업이익이 323억6241만원으로 전년대비 흑자전환했다고 5일 공시했다.같은 기간 매출액은 6994억8625만원으로 20% 늘어난 것으로 나타났다.당기순이익 역시 81억509만원으로 흑자전환했다.', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002596650', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ENERGY', NULL, '2026-02-05 16:32:10', 0, true, '2026-03-09 06:09:00.766160') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (839, '재원 마련 나선 GS家, 7만원 문턱서 지주사 지분 매각', '승산·허연수 전 대표 매도 반면 허태수 회장 장녀 매수…오너 3세 팔고 4세 매입 흐름GS그룹 차기 승계 구도에 대한 관심이 커지면서 오너일가의 지주사 지분 변동도 주목받고 있다.3일 전자공시시스템에 따르면 비상장 계열사 승산은 지난달 30일과 이달 2일 두차례에 걸쳐 GS 지분 5만5896주를 장내 매도했다. 매각일 종가 기준으로 환산하면 약 37억1966만원 규모다. 승산은 지난해 11월 24일에도 약 11억6500만원어치 GS 주식을 장내 매도한 바 있다.허연수 GS리테일 전 대표(부회장)도 지주사 지분을 줄였다. 그는 지난달 29일부터 이달 3일까지 네 차례에 걸쳐 7만5000주를 매각했으며, 매각일 종가 기준 약 50억원 규모로 집계된다.서울 역삼동에 위치한 GS그룹 사옥 전경승산은 고(故) 허만정 창업주의 5남 고(故) 허완구 승산 회장 일가가 지분을 보유한 회사로, 허용수 GS에너지 부회장이 최대주주(62.6%)다. 승산 지분은 허 부회장 외에도 ▲동생 허인영 승산 대표 22.59% ▲장남 허석홍 7.16% ▲차남 허정홍 5.26% ▲모친 김영자 2.39% 등이 나눠갖고 있어 사실상 오너일가가 소유한 사기업 형태다. 회사는 최근 3년간 배당으로 약 320억원을 수령했다.이번 매각은 승계 구도를 뒤흔들 만한 규모는 아니다. 다만 최근 1~2년간 흐름을 보면 오너 3세는 일부 지분을 매각·증여하고, 4세는 지분을 직접 매입하거나 수증받는 식으로 승계 재원을 마련하고 지분 구조를 정리해가는 모습이 이어지고 있다는 분석이 나온다.실제로 지난해 11월 허인영 승산 대표가 조카인 허석홍·허정홍 씨에게 승산 지분을 넘겼고, 9월에는 허광수 삼양인터내셔날 회장이 장남 허서홍 GS리테일 대표에게 GS 주식 50만주를 증여했다. 같은해 8월 허준홍 삼양통상 대표와 허정윤씨는 각각 118만910주, 63만5760주를 창업주 장남인 고 허남각 삼양통상 회장으로부터 상속받았다.이 밖에 허정현·허정홍·허선홍·허성준·허성윤·허원홍 등 오너 4세 상당수가 지난해 지주사 지분을 장내 매수했다. 올해 들어서도 허태수 회장의 장녀 허정현 씨는 지주사 지분을 꾸준히 매입하며 지분율을 높여나가고 있다.최근 오너일가 지주사 지분 매각의 배경으로는 주가가 상승한 점이 거론된다. 거의 10년 만에 GS 주가가 7만원대를 바라보기 때문이다. GS 주가는 지난해 4월 3만원대 중반에서 출발해 최근 6만원대 후반까지 올라 지난달 30일 장중 7만원을 터치하기도 했다. 3일 종가는 6만8000원이다. 업계에서는 주가가 고점권에 근접하자 개인 단위 재원 마련(증여세 재원 포함)을 위해 일부 지분을 현금화했을 가능성이 있다는 해석이 나온다.GS그룹 관계자는 "그룹 차원에서 지분 매각을 결정한 사안이 아니어서 별도로 설명할 부분은 없다"면서 "오너일가가 개인적으로 지주사 지분을 사고파는 경우는 종종 있으며, 이번도 그 연장선으로 보인다"고 말했다.', NULL, '지디넷코리아', 'https://n.news.naver.com/mnews/article/092/0002409028', 'https://imgnews.pstatic.net/image/092/2026/02/03/0002409028_001_20260203174714941.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-03 17:47:14', 0, true, '2026-03-09 06:09:08.963031') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (840, '[GS 포커스]⑤ 3·4세 허용수·허세홍 전면에, 미묘한 ''승계 균형''', '허용수 GS 에너지 대표이사 부회장(왼쪽), 허세홍 GS칼텍스 대표이사 부회장. /사진 제공=GSGS그룹은 재계에서도 독특한 가족 경영 전통을 가진 기업 집단이다. 특정 개인 한 명이 독식하기보다 창업주 후손들이 지분을 나눠 갖고 주요 계열사를 맡아 경영하며 가족 회의를 통해 그룹 회장을 추대하는 방식을 취해왔다. 현재는 3세 경영인인 허태수 회장이 그룹을 이끌고 있지만 최근 4세 경영인들이 전면에 등장하며 차기 승계 경쟁이 본격화되는 양상이다.4세 경영 전면, 여전한 허준구家 ''지배력''GS그룹은 지난 2005년 LG그룹에서 계열 분리한 뒤 가족 경영 체제를 유지해왔다. GS그룹의 효시인 허만정 창업주는 슬하에 8남을 두었는데 이 중 첫 부인 사이에서 얻은 허정구, 허학구, 허준구, 허신구, 허완구 일가가 주로 GS그룹과 계열사를 이끌어왔다.현재 GS그룹은 사실상 허정구 일가와 허준구 일가가 운영하는 형태다. 허정구 일가에서는 4세인 허세홍 부회장이 GS칼텍스 대표를, 허서홍 부사장이 GS리테일의 경영을 맡고 있다. 허준구 전 명예회장은 창업 1세대를 도와 현재 GS그룹의 토대를 만든 인물로 평가받는다. 이어 지금까지도 그의 아들인 허창수 GS그룹 명예회장과 허태수 회장 등 3세들이 그룹을 이끄는 주축으로 활동해왔다.일가별 지배력 측면에서는 허준구 일가가 주도하고 있다. 1월 16일 공시된 최대주주등소유주식변동신고서의 보통주 기준 허준구 일가의 지분율 합산은 16.34%다. 반면 허정구 일가의 지분율은 14.76%로 두 일가 간에는 1.58%p의 격차가 존재한다. 다만 허정구 일가의 4세들이 그룹 요직에 배치되면서 경영상의 균형을 맞추는 구조다.GS그룹의 또 다른 주요 계열사인 GS건설 역시 지분 구조상 허준구 일가가 지배하고 있다. 허창수, 허윤홍, 허진수, 허태수 등 허준구 일가 특수관계인 16인이 보유한 지분만 23.64%에 달한다. 경영 구조상으로도 사내이사부터 기타비상무이사까지 허준구 일가가 이사회와 경영진의 핵심을 구성하고 있다.허용수·허세홍 부회장, 승계구도 윤곽GS그룹은 지난해 연말 인사에서 허용수 GS에너지 사장과 허세홍 GS칼텍스 사장을 각각 부회장으로 승진시켰다. GS 측은 두 부회장의 승진 배경에 대해 "에너지 산업 전반의 구조 개편이 임박한 데다 글로벌 정유·석유화학 사업의 어려움을 동시에 극복해야 하는 절체절명의 시점에서 평범한 리더십을 넘어 보다 강력한 책임을 부여한다는 의미를 담고 있다"고 설명했다.그간 GS그룹의 승계 구도는 허세홍·허서홍·허윤홍 등 4세 간의 레이스로 보는 것이 일반적이었다. 이에 더해 장손인 허준홍 삼양통상 대표가 ㈜GS의 지분율을 끌어올리면서 승계 구도가 4파전 양상을 띠는 것 아니냐는 해석도 있었다.그러나 허세홍 부회장과 함께 3세 경영인인 허용수 부회장도 승진하면서 승계 구도가 새로운 국면에 접어들었다. 허용수 부회장은 허창수 명예회장의 사촌 동생이지만 1968년생으로 1969년생인 허세홍 부회장과 나이 차이가 크지 않다. 또한 그는 지주사인 ㈜GS의 지분 5.26%를 보유한 단일 최대주주이기도 하다. 허세홍 부회장은 4세 중 가장 연장자이자 직급상 우위에 있어 실질적인 권위까지 확보했다.허용수·허세홍 두 사람이 동시에 부회장으로 승진하면서 재계에서는 차기 회장 후보가 ''투톱 경쟁 체제''로 좁혀졌다는 분석이 나온다. 두 부회장은 GS그룹의 핵심 사업군인 에너지와 정유·석유화학 분야를 오랫동안 이끌어왔다는 점에서 역량 측면에서도 적임자라는 평가를 받는다.향후 경쟁의 향방은 두 인물의 성과와 리더십에 따라 갈릴 것으로 예상된다. 두 인물 모두 부회장 승진으로 권한이 강화됨과 동시해 강력한 책임이 책임을 부여된 상황이다. 허태수 회장이 올해 ''AI 비즈니스 임팩트''를 가시화하는 원년으로 삼겠다고 밝힌 만큼 향후 인수합병(M&A)이나 AI 확산에 따른 에너지·인프라 신사업 성과 등이 공과로 직결될 전망이다.GS그룹이 범LG가(家)로서 과거 인화의 가치를 중시했으나 허 회장 취임 이후 성과주의가 핵심 경영 원칙으로 자리 잡았다는 점도 눈여겨볼 대목이다. 허 회장은 올해 신년사에서 "변화는 언제나 우리의 준비보다 빠르게 다가오고 그 속도를 따라가지 못하면 뒤처질 수밖에 없다"며 "GS가 가장 잘할 수 있는 영역에 역량을 집중하고 실행과 성과로 변화를 증명해 나가자"고 강조했다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000078259', 'https://imgnews.pstatic.net/image/293/2026/01/23/0000078259_001_20260204141107585.png?type=w800', 'NEWS_ETC', NULL, '2026-01-23 07:00:08', 0, true, '2026-03-09 06:09:08.963031') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (809, '[특징주] 조비·남해화학·경농 등 비료주, 이란 사태에 급등', '이란 사태 장기화 전망이 나오면서 9일 장 초반 국내 비료 관련주들이 일제히 급등세를 보이고 있다.이날 오전 9시50분 기준 한국거래소에서 조비는 전일 대비 4370원(29.9%) 오른 1만8960원에 거래되고 있다. 같은 시각 남해화학은 2270원(29.9%) 상승한 9860원, 효성오앤비는 1840원(29.8%) 오른 8000원을 기록하며 비료 관련 종목들이 장중 강세를 보이고 있다.경농은 전일 대비 2300원(23.0%) 오른 1만1630원, 한일사료는 1170원(28.4%) 상승한 5280원, 누보는 301원(23.7%) 오른 1566원, 한탑은 163원(19.9%) 상승한 981원에 거래되는 등 비료·농업 관련주 전반에 매수세가 유입되고 있다.시장에서는 이란을 둘러싼 지정학적 긴장 고조로 글로벌 비료 원료 및 에너지 공급 불안 우려가 부각된 영향으로 보고 있다. 이란을 포함한 중동 지역은 천연가스 기반 질소 비료 생산과 밀접하게 연결돼 있어 지정학적 리스크 확대 시 비료 가격 상승 가능성이 거론된다.이란 사태로 호르무즈 해협이 장기간 봉쇄될 수 있다는 우려가 커지고 있는 상황이다. 호르무즈 해협은 비료 무역의 3분의 1을 차지하는 핵심 운송망으로 꼽힌다.', NULL, '아시아경제', 'https://n.news.naver.com/mnews/article/277/0005731248', 'https://imgnews.pstatic.net/image/277/2026/03/09/0005731248_001_20260309100122153.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 10:00:47', 0, true, '2026-03-09 05:54:46.133521') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (810, '기업공시 [2월 25일]', '<코스피>▲현대백화점(069960)=보통주 28만 5093주 자기주식 소각 결정 ▲넥센(005720)=자기주식 보통주 100만 주 소각 결정 ▲경농(002100)=중장기 주주환원계획 발표 ▲동아쏘시오홀딩스(000640)=주당 1000원 현금배당 결정<코스닥>▲선익시스템(171090)=OLED 디스플레이 양산용 증착장비 공급계약 ▲저스템(417840)=74억 원 규모 디스플레이 제조장비 공급계약 ▲케이엘넷(039420)=보통주 120만 7736주 자기주식 소각 결정 ▲프리엠스(053160)=보통주 29만 8062주 자기주식 취득 소각 결정', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004593382', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2026-02-25 16:29:11', 0, true, '2026-03-09 05:54:46.133521') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (811, '농진청 ‘K-인삼 청년농업인’ 금산 워크숍…신품종·고온 피해 대응 공유', '회원 평균 36세, 인삼 재배 농가 평균 66세와 대비차열제·토양소독·이중구조 하우스 등 현장 과제 발표농촌진흥청 전경. ⓒ데일리안DB[데일리안 = 김소희 기자] 농촌진흥청은 11일부터 12일까지 충남 금산군농업기술센터에서 ‘K-인삼 청년농업인’ 공동 연수(워크숍)를 연다. 국립원예특작과학원을 주축으로 2022년 출범한 K-인삼 청년농업인은 약 60명 규모다.이번 행사에는 인삼 청년농업인과 농촌진흥청, 도 농업기술원, 인삼농협 관계자 등 60여 명이 참석한다. 농촌진흥청은 청년농업인의 역량을 높이고 신품종·신기술의 현장 정착 속도를 높이기 위해 이번 연수를 마련했다고 밝혔다.K-인삼 청년농업인 회원 평균 연령은 약 36세로, 인삼 재배 농가 평균 연령(약 66세)과 차이가 크다. 농촌진흥청은 이들이 신품종·신기술 도입 확산을 이끌 핵심 주체로 주목받고 있다고 설명했다.첫날에는 청년농업인이 발굴한 현장 과제 발표와 신기술 특강이 진행된다. 안시영 K-인삼 청년농업인 회장은 ‘차열제를 활용한 고온 피해 경감 기술’을 과제로 제안한다. 경농은 ‘연작 장해 경감을 위한 최신 토양소독 기술’을 소개할 예정이다.또 김장욱 국립원예특작과학원 연구관은 인삼 신품종과 노동력 절감형 재배시설을, 유진 연구사는 이중구조 하우스를 활용한 인삼 안정 생산 기술 보급 사업을 각각 안내한다. 현장 견학 시간에는 금산군농업기술센터 내 ‘인삼 뿌리썩음병원균 밀도 진단실’을 방문해 연작 장해 경감 기반 기술을 살펴본다. 이후 ‘인삼 산업 발전을 위한 청년농업인-연구자 협력 확대 방안’을 주제로 토의한다.둘째 날에는 K-인삼 청년농업인 총회를 열고, 수삼 유통 선진화 사례를 보기 위해 금산 인삼약초 유통단지를 방문할 계획이다.김영창 농촌진흥청 국립원예특작과학원 특용작물육종과장은 “고령화와 이상기상 등으로 인삼 재배 여건이 악화하는 상황에서 청년 후계 인력 육성이 절실하다”며 “청년농업인의 수요를 반영한 연구 과제를 발굴하고 신품종·신기술 보급을 강화해 인삼 산업의 지속 성장을 뒷받침하겠다”고 말했다.', NULL, '데일리안', 'https://n.news.naver.com/mnews/article/119/0003058232', 'https://imgnews.pstatic.net/image/119/2026/02/10/0003058232_001_20260210140016124.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-10 14:00:16', 0, true, '2026-03-09 05:54:46.133521') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (812, '[서울데이터랩]조비 23.14% 폭등 금일 증시 상승률 1위로 마감', '6일 오후 3시 35분 조비(001550)가 등락률 +23.14%로 상승률 1위로 마감했다. 조비는 장 중 3,185,447주가 거래되었으며 주가는 전 거래일 대비 2,520원 오른 13,410원에 마감했다.한편 조비의 PER은 62.96으로, ROE는 1.22%로 나타났다.이어 상승률 2위 대양금속(009190)은 주가가 15.63% 급등하며 종가 1,369원에 마감했다. 상승률 3위 한화솔루션(009830)의 주가는 4만 2,000원으로 15.38% 급등하며 강세를 보였다. 상승률 4위 우진플라임(049800)은 12.98% 상승하며 2,480원에 마감했다. 상승률 5위 일신석재(007110)는 12.76%의 상승세를 타고 1,811원에 마감했다.6위 미원화학(134380)은 10만 7,000원으로 12.63% 상승 마감했다. 7위 한화솔루션우(009835)는 종가 3만 250원으로 11.83% 상승 마감했다. 8위 인디에프(014990)는 종가 834원으로 10.76% 상승 마감했다. 9위 SG세계물산(004060)은 491원으로 10.34% 상승 마감했다. 10위 OCI홀딩스(010060)는 15만 1,100원으로 9.10% 상승 마감했다.이밖에도 화천기계(010660) ▲8.70%, 넷마블(251270) ▲7.68%, 한화비전(489790) ▲7.57%, 부산산업(011390) ▲7.28%, KB금융(105560) ▲7.03%, 더블유게임즈(192080) ▲6.72%, 신원(009270) ▲6.35%, 현대엘리베이터(017800) ▲6.24%, 남선알미우(008355) ▲5.41%, 경농(002100) ▲5.25% 등을 기록하며 금일 증시를 마감했다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003615370', 'https://imgnews.pstatic.net/image/081/2026/02/06/0003615370_001_20260206160512384.png?type=w800', 'NEWS_ETC', NULL, '2026-02-06 16:05:12', 0, true, '2026-03-09 05:54:46.133521') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (813, '[공시pick] 경농·동방아그로, 농협경제지주와 대규모 농약 공급계약', '◆…조세일보 DB경농과 동방아그로가 농협경제지주와 농약 공급 계약을 각각 체결했다고 6일 공시했다.경농의 계약금액은 1327억원으로 최근 매출액 대비 40.8% 규모다. 계약 기간은 12월 31일까지다.동방아그로는 859억원 규모 계약을 맺었다. 최근 매출액 대비 50.5% 수준이며 공급 기간은 동일하다.두 계약 모두 국내 농약 공급을 위한 연간 납품 계약으로 수요에 따라 공급량과 금액이 변동될 수 있다.', NULL, '조세일보', 'https://n.news.naver.com/mnews/article/123/0002377364', 'https://imgnews.pstatic.net/image/123/2026/02/06/0002377364_001_20260206151208912.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-06 15:12:08', 0, true, '2026-03-09 05:54:46.133521') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (814, '필리핀 서비사야스 지역 ‘KOICA 스마트농업 가치사슬 강화사업’ 착공식 개최', '- 한-필 농업 협력 본격 실행 단계 진입. 1ha 규모 스마트온실 조성 착수<시삽식. (사)한국개발전략연구소 제공>(사)한국개발전략연구소(이하 KDS, 원장 신기덕)는 한국국제협력단(이하 KOICA, 이사장 장원삼)이 지원하는 ‘스마트농업을 적용한 서비사야스 지역 고소득작물 가치사슬 강화사업’의 일환으로 필리핀 아클란 주에서 통합 착공식을 개최했다고 27일 밝혔다.지난 금요일(23일)에 실시한 이번 착공식은 동 사업이 구상·설계 단계를 넘어 실제 현장 인프라 구축으로 진입했음을 알리는 중요한 이정표이며, 약 1ha 부지에 연동형 온실, 육묘장, 저온저장고, 태양광 설비, 사무·작업장 등 현대적 농업 인프라가 조성될 예정이다. 온실 시설은 1차 구축 대상지인 아클란주 칼리보와 일로일로주 티그바완을 시작으로, 2차 구축지인 안티케주 팟농온과 네그로스 옥시덴탈주 바고까지 총 4개 지역으로 확대해 스마트농업 기반을 순차적으로 확충한다.행사는 아클란 농수산 시범농장 및 교육센터(AAADFTC, Aklan Agri-Aqua Demo Farm and Training Center) 내 온실 구축 사업부지에서 진행되었으며, KOICA를 비롯해 필리핀 농업부(DA) 중앙 및 지역청, 주필리핀 대한민국대사관, 아클란 주정부와 각 지방자치단체, 현지 농민그룹 등 양국의 주요 이해관계자 110여 명이 참석했다.공식 행사는 내빈 소개 및 양국 국가 제창으로 시작해, 대표기도, 아클란 주지사 환영사, 사업총괄책임자(PM)의 사업 소개 순으로 진행되었다.<참석자 단체사진. (사)한국개발전략연구소 제공>윤해진 PM은 “기후변화로 농업 여건의 불확실성이 커지는 도전적 상황 속에서 과학·기술 기반 스마트농업은 중요한 대응 수단”이라며, “동 사업은 4개 지역에 스마트온실과 관련 시설을 구축하는 데 그치지 않고, 스마트농업 정책 제안, 운영체계 구축, 유통 기반 강화, 현장 역량강화를 함께 추진해 이러한 과제를 극복하고 지속가능한 가치사슬 모델을 구축하는 데 목적이 있다”고 말했다.이어 주필리핀 대한민국대사, 필리핀 농업부 장관, KOICA 필리핀사무소 소장의 축사를 전했으며, 타임캡슐 봉인식과 시삽식이 차례대로 진행되며 스마트농업 기반 구축의 의미를 공유했다.프란시스코 P. 티우-라우렐 주니어(Francisco P. Tiu-Laurel Jr.) 필리핀 농업부 장관은 “동 사업은 4개 지역에 스마트온실 기반을 구축해 생산성과 품질·안전성, 기후 회복력을 높이고 농가 소득과 지역사회 기회를 확대하는 농민의 미래에 대한 투자”라고 말했다. 이어 “KOICA와 대한민국 정부, 지방정부, 농민조직의 협력에 깊이 감사드리며, 동 사업이 현장 수요에 부합하도록 추진되어 서비사야스 지역의 농업 현대화와 식량 안보 강화에 실질적으로 기여할 수 있도록 적극 지원하겠다”고 밝혔다.이날 행사에서는 시삽식 등 공식 프로그램과 함께 유통 기반 강화를 위한 냉장탑차 기증식도 진행됐다. 사업대상지 4개 지역에 각 1대씩 지원되는 냉장탑차는 수확물의 신선도 유지와 물류 효율화를 통해 농가의 시장 접근성을 높이는 데 활용될 예정이다.사업 수행 주체인 KDS 컨소시엄(KDS, ㈜경농, ASK)은 착공 이후 온실 구축과 생산 기반 조성에 더해 현장 실습 중심의 재배기술 교육, 농민조직 운영 역량 강화, 로컬푸드 유통 활성화 등 다양한 프로그램을 단계적으로 추진할 계획이다. 아클란과 티그바완 지역의 스마트온실은 2026년 7월 준공을 목표로 하고 있으며, 완공 이후 시범재배와 생산·유통 모델 구축이 순차적으로 이어질 예정이다.이번 행사는 양국이 농업 분야에서 협력의 폭을 확대하고, 기후변화 대응과 지역 농업의 지속 가능한 성장 기반을 함께 모색하는 계기로 평가된다. KDS는 스마트농업 기술과 지역 공동체 기반 운영 모델이 결합될 경우 서비사야스 지역 농업의 경쟁력이 강화될 것으로 기대하며, 동 사업이 지역 농민들의 소득과 삶의 질 개선으로 이어지도록 현장 중심의 지원을 지속해 나갈 계획이다.', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002591456', 'https://imgnews.pstatic.net/image/016/2026/01/27/0002591456_001_20260127145513045.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-27 10:00:21', 0, true, '2026-03-09 05:54:46.133521') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (841, '비싸진 펄프·골판지…종이값 줄인상 우려', 'PRICE펄프 5개월 새 11% 상승세계 제지사 펄프 재고 줄고中 포장지 생산 회복 기대 커져폐골판지 가격 떨어지는데도원지값은 ㎏당 100원씩 인상인건비·연료 가격 상승 등 여파신문·인쇄용지 등에 쓰이는 펄프 국제 가격이 재고 감소 등으로 5개월째 상승세다. 골판지 가격도 올랐다. 인건비와 연료비 증가가 폐골판지값 하락 효과를 상쇄하면서다.◇국제 펄프 가격 5개월째 상승10일 산업통상자원부에 따르면 지난해 8월 톤(t)당 630달러였던 미국 남부산 혼합활엽수 펄프(SBHK) 가격이 지난달 700달러까지 올랐다. 다섯 달 만에 10% 이상 올랐다. 작년 4월 750달러까지 치솟다가 안정세를 보이더니 최근 5개월 연속 상승세를 탔다. 펄프는 인쇄용지, 화장지, 백판지 등의 핵심 원료로 제지 제조 원가의 60%를 차지한다. 국내에선 총사용량 228만t 중 88.2%를 수입에 의존한다.펄프값이 오르는 이유는 펄프 재고가 바닥난 제지업체들이 다시 구매를 재개한 영향이다. 제지업체들은 2024년 중반 브라질의 세계 최대 펄프 생산 기업 스자노의 친환경 펄프 생산 시설 세라도의 가동으로 펄프 구매를 미뤄왔다. 펄프 공급이 급증하면서 가격이 하락하는 모습을 보이니 굳이 미리 사둘 필요가 없었기 때문이다.제지회사들은 재고 떨어질 때까지 펄프 구입을 꺼리다가 작년 중순에 와서야 보충에 나섰다. 국내 제지업계 관계자는 “단순히 펄프 수요 증가라는 시각보다는 제지회사들이 원래 샀어야 했던 펄프를 뒤늦게 한꺼번에 사들이면서 나타나는 가격 상승으로 봐야 한다”고 말했다.세계 최대 펄프 소비국 중국에서 내수 회복 기대감에 포장지·티슈·위생 용지 생산이 증가할 수 있다는 전망도 일부 영향을 줬다. 지난해 11월 말 인도네시아 수마트라섬에서 발생한 대규모 홍수로 원목 조달과 펄프 생산에 차질이 생긴 것도 오름세의 원인 가운데 하나다.◇폐골판지 내려도 원지값 올라골판지 원지 가격도 올랐다. 국내 골판지 제조사들은 지난해 12월 원지 가격을 1kg당 평균 100원씩 인상했다. 태림페이퍼와 전주페이퍼를 필두로 아진피앤피, 한솔페이퍼텍, 한국수출포장공업 등도 잇달아 가격 인상을 통보했다.이들 골판지 원지 제조사들의 가격 조정은 새로운 골판지를 만드는 핵심 재료인 폐골판지 가격의 하락 속에서 이뤄졌다. 폐골판지 가격은 최근 4개월 동안 꾸준히 하락했다. 산업통상자원부에 따르면 지난달 폐골판지(OCC) 가격은 t당 8만1600원을 기록했다. 1년(10만5100원)보다 22.3% 떨어졌다. 지난해 3월엔 t당 8만원까지 내려앉으며 52주 최저치를 기록하기도 했다. 업계 관계자는 “폐골판지값은 내렸지만 인건비, 에너지 및 고정비 부담이 증가하면서 원지 제조사들의 영업이익이 많이 감소해 골판지 수익성이 크게 악화했다”고 말했다.폐골판지값이 내린 이유는 공급 증가다. 유통업체들이 비용 절감을 위해 종이박스 크기를 줄이거나 재사용할 수 있는 다회용 박스를 확대하면서 골판지 원지 수요가 줄었고 그 결과로 폐골판지가 쌓이게 됐다. 한국제지연합회에 따르면 코로나 등의 영향으로 2021년 598만t이었던 골판지원지 생산량이 지난해 564만t으로 줄었다.', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005250136', 'https://imgnews.pstatic.net/image/015/2026/02/11/0005250136_001_20260212004510126.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-11 17:22:15', 0, true, '2026-03-09 06:09:15.960665') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (816, '경농, 가족친화기업 인증 획득', '성평등가족부 주관 3년 유효 인증다양한 일·가정 양립 제도 운영경농 기업이미지(CI).경농은 성평등가족부 주관 ''2025 가족친화기업'' 인증을 획득했다고 17일 밝혔다.가족친화기업 인증은 ‘가족친화 사회환경의 조성 촉진에 관한 법률’에 따라 근로자의 일·가정 양립 관련 제도와 조직문화를 모범적으로 운영하는 기업에 부여하는 제도다. 2008년 도입됐고 자녀 출산·양육 지원과 가족친화적 직장문화 조성 여부 등을 종합적으로 평가한다. 인증 유효기간은 3년이다.경농 관계자는 "근무 환경 개선과 복지 제도 운영 전반에서 가족친화적 경영 체계를 구축해 온 점이 높은 평가를 받았다"며 "단순한 복지 제도 도입을 넘어, 일·가정 양립을 기업 운영의 핵심 가치로 정착시켜 왔다는 점이 이번 인증의 배경으로 꼽힌다"고 설명했다.경농은 임직원이 안정적인 환경에서 업무에 몰입할 수 있도록 근무 제도와 조직문화를 꾸준히 개선해 왔다. 특육아휴직·시차출퇴근제·가족돌봄휴가 등 제도가 대표적이다. 건강검진과 체력단련비 지원 등 임직원 삶의 질 향상을 위한 복지 제도도 병행하고 있다. 이와 함께 대체인력 채용, 자기계발 지원, 장기근속·주택자금 지원 등을 통해 안정적인 고용 환경을 구축하고 있다.경농 관계자는 "앞으로도 임직원의 삶의 질 향상과 건강한 조직문화 조성을 통해 사람을 중심에 둔 ESG 경영을 강화해 나가겠다"고 말했다.', NULL, '농민신문', 'https://n.news.naver.com/mnews/article/662/0000084874', 'https://imgnews.pstatic.net/image/662/2025/12/22/0000084874_001_20251222093109169.jpg?type=w800', 'NEWS_ETC', NULL, '2025-12-22 09:31:09', 0, true, '2026-03-09 05:54:46.133521') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (817, '김기옥 제놀루션 대표, ''고려대 경제인 대상'' 수상', '(사진=제놀루션) *재판매 및 DB 금지[서울=뉴시스] 김경택 기자 = 그린바이오 전문기업 제놀루션은 회사 김기옥 대표이사가 고려대 경제인회로부터 기업 경영과 국가 경제 발전에 기여한 공로를 인정받아 ''고려대 경제인 대상''을 수상했다고 16일 밝혔다.회사 측에 따르면 고려대 경제인 대상은 고려대 출신 경영인 및 경제인 중 한 해 동안 두드러진 업적과 공로를 보인 이들에게 수여되는 상이다.김기옥 대표는 40여년간 진단의학·의료기기 분야에 헌신해 온 전문가로 지난 2006년 제놀루션을 설립해 핵산추출 장비와 시약의 국산화를 이끌었다. 제놀루션은 독자적인 핵산추출 플랫폼과 RNA(리보핵산) 기술을 바탕으로 전 세계 50여개국에 제품을 수출하며 글로벌 경쟁력을 입증했다.이런 성과로 김 대표는 2021년 금탑산업훈장 수훈과 ''7000만불 수출의 탑''을 동시에 달성했으며 코로나19 팬데믹 당시 국내외에 진단 제품을 공급해 K-방역의 위상을 높이는 데 크게 기여했다.한편 제놀루션은 최근 정밀의료를 넘어 그린바이오 분야로 사업 영역을 확장하고 있다. 지난해 세계 첫 꿀벌 유전자 치료제 ''허니가드-R액''의 품목허가를 획득했으며 올해 5월에는 경농과 차세대 작물보호제 개발을 위한 MOU(업무협약)를 체결하는 등 RNA 기술 기반의 신사업 행보를 가속화하고 있다.', NULL, '뉴시스', 'https://n.news.naver.com/mnews/article/003/0013660603', 'https://imgnews.pstatic.net/image/003/2025/12/16/NISI20251216_0002019590_web_20251216132737_20251216133620269.jpg?type=w800', 'NEWS_ETC', NULL, '2025-12-16 13:35:13', 0, true, '2026-03-09 05:54:46.133521') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (822, '코스피 7% 급락 출발…개미 홀로 1.2조 ''사자'' [시황]', '장중 코스피 매도 사이드카코스닥도 5% 하락 출발코스피가 전 거래일(5584.87)보다 319.50포인트(5.72%) 하락한 5265.37에 개장한 9일 오전 서울 중구 하나은행 딜링룸에 지수가 표시돼 있다. ⓒ뉴시스[데일리안 = 강현태 기자] 미국의 이란 공습 여파로 중동 관련 불확실성이 커진 가운데 코스피가 9일 장 초반 급락 출발했다.한국거래소에 따르면, 이날 오전 9시 26분 코스피 지수는 전 거래일보다 409.54포인트(7.33%) 내린 5175.33을 가리키고 있다. 지수는 전장보다 319.50포인트(5.72%) 내린 5265.37로 출발했다.투자주체별로 보면 개인이 홀로 1조20779억원을 순매수하고 있고, 외국인과 기관이 각각 7157억원, 5136억원을 순매도하고 있다.코스피 시가총액 상위 10개 종목은 일제히 내리고 있다. 구체적으로 삼성전자(-8.40%)·SK하이닉스(-8.87%)·현대차(-9.58%)·삼성전자우(-7.34%)·LG에너지솔루션(-5.03%)·한화에어로스페이스(-2.63%)·삼성바이오로직스(-6.08%)·SK스퀘어(-9.95%)·두산에너빌리티(-2.45%)·기아(-8.62%) 등이 하락세를 보이고 있다.이날 오전 9시 6분 2초께 코스피200선물지수 변동 영향으로 5분간 프로그램매도호가 일시효력정지(사이드카)가 이뤄지기도 했다.발동 시점 당시 코스피200선물지수는 전일 종가보다 53.75포인트(6.49%) 하락한 773.90이었다.매도 사이드카는 코스피200선물 지수가 5% 이상 하락해 1분간 지속되는 경우 발동된다.같은 시각 코스닥 지수는 전장보다 62.60포인트(5.48%) 내린 1092.07을 나타내고 있다. 지수는 전장보다 58.19포인트(5.04%) 내린 1096.48로 출발했다.투자주체별로 보면 개인이 420억원을 팔아치우고 있고, 외국인과 기관이 각각 189억원, 508억원을 사들이고 있다.코스닥 시가총액 상위 10개 종목은 일제히 내리고 있고. 구체적으로 에코프로(-4.59%)·에코프로비엠(-2.52%)·알테오젠(-4.42%)·삼천당제약(-5.76%)·레인보우로보틱스(-9.62%)·에이비엘바이오(-2.26%)·리노공업(-5.35%)·코오롱티슈진(-4.87%)·리가켐바이오(-6.38%)·HLB(-4.04%) 등이 우하향하고 있다.지난 금요일(현지시각) 미국증시는 중동 불확실성과 고용 지표 충격이 더해지며 3대 지수가 일제히 하락 마감했다.iM증권 리서치본부는 "도널드 트럼프 대통령이 ''(이란의) 항복 없이 전쟁 종결 협상은 없다''고 언급해 중동전쟁 장기화 우려가 커져 유가 급등이 지속됐다"며 "이와 함께 미국 고용 보고서 충격에 스태그플레이션 공포가 확대돼 위험자산 선호심리가 약화했다"고 전했다.국내증시 역히 국제정세 영향에 따라 하락세가 이어질 전망이다.iM증권 리서치본부는 "글로벌 위험자산 선호심리가 위축되는 가운데 국내 증시에도 일부 부담으로 작용할 가능성이 존재한다"고 말했다.한편 이날 서울 외환시장에서 달러 대비 원화 환율은 1490원대에서 움직이고 있다. 환율은 전 거래일보다 16.6원 오른 1493.0원으로 출발했다.', NULL, '데일리안', 'https://n.news.naver.com/mnews/article/119/0003066662', 'https://imgnews.pstatic.net/image/119/2026/03/09/0003066662_001_20260309094616867.jpg?type=w800', 'NEWS_BIO', NULL, '2026-03-09 09:46:16', 0, true, '2026-03-09 05:58:33.306572') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (854, '‘어쩔 수가 없다?’…AI시대, 제지공장들의 생존법', '영화 ‘어쩔 수가 없다’ 영화속 주인공 이병헌 분은 영화 내에 ‘어쩔 수가 없다’는 말을 반복한다. 모든 것이 디지털화 전자화 된 AI 시대에 제지 산업은 살아남을 수 있을까 [CJE&M]신문은 사라지고 택배 상자는 늘었다지종 구조 재편이 업종 구도까지 바꿔깨끗한나라·한솔제지 등 실적 희비고용·설비는 그대로인데 수익성 흔들[한솔제지][헤럴드경제=홍석희 기자] 박찬욱 감독의 영화 ‘어쩔 수가 없다’는 제지공장에서 해고된 노동자(이병헌 분)의 이야기다. 결혼도 하고 집도 사고 아들과 딸, 그리고 반려견까지 두마리나 키우는 이병헌은 영화속에서 “나는 다 이뤘다”고 말한다. 그러나 맛있게 먹었던 ‘장어’는 사실 해고가 확정된 이들에게만 전달된 ‘마지막 선물’이었다. 이병헌은 영화에서 반복적으로 ‘어쩔 수가 없다’는 말을 한다. 이병헌이 일했던 ‘제지산업’은 디지털을 넘어 AI시대에 와있는 지금 영화속 주인공처럼 ‘어쩔 수가 없다’는 말을 반복 할 수밖에 없을까.한국제지연합회가 집계한 2009년~2024년 국내 제지류 생산량 현황. 신문용지 생산량은 급격하게 줄었고, 골판지원지 생산량은 늘었다. [한국제지연합회]한국제지연합회 통계에 따르면 한국에서 생산된 종이류 가운데 지난 10여년 동안 가장 많이 줄어든 종이류는 신문용지로 2009년 146만톤에서 2024년 37만톤으로 줄었다. 디지털 뉴스 전환의 가장 직접적인 타격을 입은 제지산업계가 바로 신문용지 부문이다. 인쇄용지 타격도 심각하다. 2009년 297만톤이나 되던 인쇄용지 생산량은 2024년에는 226만톤으로 약 71만톤 가량 줄었다. 사무에 필요한 문서들 다수가 디지털화 전자화 되면서 굳이 ‘인쇄용지’가 필요치 않은 상황이 수년동안 누적된 결과다.이에 비해 택배용 포장 박스에 사용되는 골판지원지 생산량은 2009년 369만톤에서 2024년 557만톤으로 188만톤이나 수직상승했다. 온라인 쇼핑과 택배 물류가 확장되면서 골판지원지 사업 분야를 빠르게 성장시켰다. 위생용지 부문 역시 성장세가 가팔랐다. 2009년 44만톤 규모던 위생용지 생산량은 2024년에는 52만톤으로 8만톤 가량이 늘었다. 국내 생산 제지류 총 생산량은 지난 2009년 1048만톤이었고, 2024년에는 1081만톤이다. 생산된 종이가 어떤 종류냐는 달라졌지만 전체 종이 생산량은 소폭이나마 늘어난 셈이다.이 같은 지종 구조 변화는 기업 실적에도 그대로 반영된다. 생활소비재(위생용품) 비중이 큰 깨끗한나라는 2025년 연결 기준 매출 5082억원(전년 대비 5.4% 감소), 영업손실 226억원으로 적자가 확대됐다. 당기순손실은 472억원으로 손실 폭이 커졌다. 과자 박스 등 소형 포장에 많이 사용되는 백판지의 시황 악화가 실적에 부담으로 작용했다는 평가다.반면 인쇄·산업용지 비중이 큰 한솔제지는 2025년 연결 기준 매출 2조2900억원, 영업이익 499억원을 기록했다. 영업이익은 전년 대비 127.1% 증가했고, 당기순이익은 38억원으로 흑자 전환했다. 회사는 환율 상승과 원부재료 가격 및 해상운임 하락 등을 손익 개선 요인으로 들었다.골판지업은 물류 수요를 타고 매출 방어는 했지만 원가·시황에 따라 희비가 갈린다. 대림제지는 2025년 연결 기준 매출 1688억원(전년 대비 1.5% 증가)에도 영업이익 52억8000만원(46.3% 감소), 당기순이익 66억원(49.9% 감소)으로 수익성이 둔화됐다. 한창제지도 2025년 기준 매출 2669억원(9.2% 감소), 영업손실 51억원으로 적자 전환했고, 당기순손실 131억원을 기록했다.아세아제지, 신대양제지 등 골판지 중심 기업들은 물류 수요와 맞물려 비교적 안정적인 흐름을 이어가고 있다. 다만 골판지 업황 역시 경기 변동과 증설 경쟁 영향에서 완전히 자유롭지는 않다. 내수 물동량 둔화나 해외 공급 확대가 동시에 나타날 경우 수익성 변동성이 커질 수 있다는 지적이 나온다. 결국 제지산업의 핵심 변수는 ‘종이 수요의 존재 여부’가 아니라 ‘어떤 종이를 얼마나 남길 것인가’로 이동했다.고용과 설비 측면에서도 변화는 제한적이다. 대형 제지공장은 여전히 막대한 투자와 인력을 필요로 하는 장치산업이다. 자동화가 확대됐지만 공장 자체가 사라지는 속도는 느리다. 대신 생산 품목 전환과 설비 구조 조정이 점진적으로 진행되고 있다. 인쇄용지 라인을 줄이고 포장·친환경 소재 중심으로 재편하는 흐름이 대표적이다. 산업의 소멸이 아니라 체질 변화에 가깝다는 평가가 나오는 이유다.한국제지연합회가 집계한 종이류별 생산량 표 [한국제지연합회]', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002600489', 'https://imgnews.pstatic.net/image/016/2026/02/12/0002600489_001_20260213102708168.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-12 20:30:17', 0, true, '2026-03-09 06:09:45.926822') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (887, '철강 중소기업 법인세 납부 3개월 연장…국세청장 “체감도 높은 세정지원할 것”', '임광현 국세청장, 포항 철강기업들과 만나관세인상 등 영향 수출 전년보다 줄어들어포항세무서 ‘세금애로 해소센터’ 3월 신설임광현 국세청장이 22일 포항 철강산업단지를 찾아 손기영 TCC 스틸대표를 만나 이동하고 있다. 국세청 제공국세청이 철강업을 주 업종으로 하는 중소기업에게는 법인세 납부기한을 3개월 연장하기로 했다.임광현 국세청장은 21일 김해 지역 수출 중소기업인들과의 간담회에 이어 22일엔 포항을 찾아 철강기업과 간담회를 가졌다.이번 방문의 목적은 포항 내 철강 기업인들과 소통의 시간을 갖고, 포항세무서를 찾아 지역 납세자들의 부가세 신고 관련 애로사항을 살피기 위해서다.임 청장은 먼저 포항 철강산업단지를 찾아 단지 내 표면처리강판 제조회사인 TCC스틸을 방문해 세무상 어려움 등을 들었다.포항 철강산업단지 내 기업들은 연 생산 약 12조 7000억원을 담당하는 등 포항 경제의 기둥 역할을 하고 있다. 그러나 최근 관세 인상과 글로벌 공급과잉으로 전년 대비 수출이 6.5% 감소하는 등 어려움을 겪고 있다.손기영 TCC스틸 대표는 “작년 부가세 조기환급으로 위기에 큰 도움이 됐으나, 매출의 약 67%가 수출인만큼 관세 인상 등 대외 악재로 경영상 부담이 크다”고 밝혔다.임 청장은 “철강 산업은 우리 산업의 근간”이라며 “기업이 당면한 어려움을 극복할 수 있도록 국세청이 보다 체감도 높은 세정지원을 통해 적극 뒷받침하겠다”고 말했다.이후 간담회에 참석한 철강기업 대표들은 “철강 산업 의존도가 높은 포항 지역이 산업 위기의 영향을 크게 받고 있는 만큼, 지역 및 산업 특성을 고려한 맞춤형 지원 방안이 필요하다”고 말했다.이에 국세청은 철강업을 주업종으로 하는 중소기업에게는 법인세 납부기한을 납세자의 신청 없이 직권으로 3개월(6월 30일까지) 연장하고 납세 담보도 면제한다. 법인세 환급세액이 발생하는 경우, 10일 이내(4월 10일까지) 환급금을 신속 지급할 계획이다.국세청은 또 세액공제 적용이 가능한 법인에게 ‘법인세 공제감면 컨설팅’ 등 지원 제도를 안내하고, 세무서에 상담 채널인 ‘세금애로 해소센터’를 신설해 보다 손쉽게 공제·감면 혜택을 받을 수 있도록 했다. 이 센터는 3월 중 개소할 계획이다.추가로 각종 공제제도의 공제율 상향 등 위기지역·산업을 위한 세법 개정을 재경부에 적극 건의하기로 했다.아울러 대구지방국세청은 포항 철강 산업단지 전용 세정지원 전담반을 만들어 단지 내 중소기업에 대한 상시 세무 상담을 실시하기로 했다. 또 공제·감면 관련 컨설팅 결과에 따라 접수된 경정청구가 있는 경우, 대구지방국세청에서 해당 건을 직접 처리해 신속히 환급하기로 했다.임 청장은 “본청의 정책적 지원과 더불어, 지방국세청 차원에서도 현장형 세정지원을 병행하는 것이 중요하다”며 “오늘 논의 내용을 토대로 지역 특화 지원을 강화해 나가겠다”고 말했다.그는 “세금애로 해소센터에서도 국세청 상담요원이 맞춤형 세무 상담을 제공해 기업이 세금 문제 없이 경영에만 전념할 수 있는 환경을 만들어 나가겠다”고 말했다.', NULL, '부산일보', 'https://n.news.naver.com/mnews/article/082/0001363894', 'https://imgnews.pstatic.net/image/082/2026/01/22/0001363894_001_20260122162911958.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-01-22 16:29:11', 0, true, '2026-03-09 06:11:30.516364') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (823, '현대차·기아 자율주행차, 광주 도심 달린다…‘자율주행 협력 모델’ 사업자 선정', '지난 1월 미국 네바다주 라스베이거스 모셔널 테크니컬센터에서 현대차 아이오닉 5를 기반으로 한 로보택시가 달리고 있는 모습. /연합뉴스현대차·기아의 자율주행 차량이 국내 최초 자율주행 실증도시인 광주 전역에서 실제 도로를 달리게 된다.현대차·기아는 국토교통부 주관 ‘자율주행 실증도시 조성사업’의 ‘K자율주행 협력 모델’에서 자동차 제작사와 운송 플랫폼사로 각각 선정됐다고 9일 밝혔다. 국내 첫 도시 단위 자율줗애 실증 프로젝트로, 실제 도로 주행을 통해 대규모 데이터를 확보하고 기술 표준 수립과 제도 정비를 진행하는 것이 목표다.앞으로 현대차·기아는 자율주행 개발 전용 차량을 제작하고, 운송 플랫폼 운영을 맡는다. 향후 선정될 자율주행 기술 사업자의 기술 개발에 적합한 차량을 공급하고, 자율주행 서비스 운영·관제 플랫폼 운영을 담당하는 역할이다.자율주행 개발용 차량은 센서 장착, 차량 제어 시스템 연동, 무선 업데이트(OTA) 등 기술 개발과 검증에 필요한 기능을 갖춰야 한다. 현대차·기아는 이미 자율주행 합작사 모셔널과 구글 계열 웨이모 로보택시에 아이오닉5 기반 자율주행 차량을 공급하며 이 같은 ‘자율주행 차량 파운드리’ 역량을 확보해 왔다.운송 플랫폼에는 현대차·기아의 모빌리티 플랫폼 ‘셔클(Shucle)’이 활용된다. 인공지능(AI)과 실시간 교통정보를 기반으로 최적 경로를 생성하고 차량 호출·배차, 승하차 관리, 차량 관제 등을 통합 운영하는 시스템이다. 셔클은 현재까지 33개 지자체, 82개 이상 서비스 지역에서 운영되며 서비스 안정성을 검증받았다.현대차·기아는 이번 실증사업을 통해 차량과 이용자, 플랫폼이 하나로 연결되는 통합형 자율주행 서비스 모델을 구축한다는 계획이다. 현대차·기아 모빌리티사업실 김수영 상무는 “차량과 자율주행 기술, 플랫폼이 유기적으로 연동되는 체계를 구축하고, 실증 성과가 확산 가능한 표준으로 이어지도록 기술 고도화에 역량을 집중하겠다”고 말했다.', NULL, '조선일보', 'https://n.news.naver.com/mnews/article/023/0003963374', 'https://imgnews.pstatic.net/image/023/2026/03/09/0003963374_001_20260309145617913.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-03-09 14:56:17', 0, true, '2026-03-09 05:58:46.207093') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (824, '현대차·기아, 웨어러블 로봇 ''엑스블 숄더'' KS 인증 획득', '현대자동차·기아는 산업용 착용 로봇 ''엑스블 숄더''가 한국로봇산업진흥원으로부터 KS 인증을 획득했다고 9일 밝혔다.엑스블 숄더는 작업자가 산업현장에서 직접 착용할 수 있는 웨어러블 로봇으로 근골격계 부담을 덜어주는 역할을 한다.''엑스블 숄더'' 생산 업체인 인탑스 구미 공장에서 열린 KS 인증 수여식에서 한국로봇산업진흥원 김태우 본부장, 인탑스 김근하 대표, 현대차·기아 로보틱스랩 최리군 상무(좌측부터)가 기념 사진을 촬영하고 있다. [사진=현대차·기아]KS 인증은 제품과 서비스가 한국산업표준(KS)에 부합함을 국가가 인증하는 제도로 운영 주체인 국가기술표준원이 지정한 기관을 통해 인증 절차가 진행된다.로봇 분야에서는 한국로봇산업진흥원이 인증 기관으로 지정돼 첨단 로봇 제품의 안전과 신뢰성 확보를 위해 인증 제도를 운영하고 있다.이번 인증은 국내 로봇 산업에서 착용 로봇 품질을 국가 공인 기준으로 확보한 첫 사례로, ''엑스블 숄더''가 안전성과 품질을 갖춘 제품으로 공식 인정받았다는 점에서 의미가 크다는 평가다.현대차·기아는 사람 중심의 로보틱스 기술인 ''엑스블'' 시리즈의 개발과 사업화를 지속적으로 추진하고 있다. 그중 ''엑스블 숄더''는 현대차그룹 주요 계열사와 대한항공, 한국철도 공사 등 국내 여러 산업 현장에 적용되고 있으며, 지난해에는 농촌진흥청과도 업무협약을 체결했다.또한 허리 보조용 ''엑스블 웨이스트''는 중량물 취급 작업자의 부담 완화를 목표로 개발 중이며, 하지마비 환자의 보행을 돕는 착용 로봇 ‘엑스블 멕스(X-ble MEX)’는 재활 및 의료 분야 활용을 위해 연구개발이 이어지고 있다.특히 엑스블 숄더는 무동력 토크 생성 구조로 설계돼 가벼울 뿐만 아니라 별도로 충전할 필요가 없어 유지 및 관리가 편리하다.또, 근력 보상 모듈을 적용해 보조력을 생성하고, 이를 통해 작업자의 어깨 관절 부하와 전∙측방 삼각근 활성도를 각각 최대 60%와 30% 경감할 수 있다.현대차·기아 로보틱스랩 최리군 상무는 "엑스블 숄더가 KS인증을 통해 국내 산업용 착용 로봇의 안전·품질 기준을 선도하게 됐다"며 "앞으로도 로봇 기술의 실용성을 높이고, 글로벌 산업 현장에도 기여할 수 있는 제품 개발에 주력할 것"이라고 말했다.', NULL, '아이뉴스24', 'https://n.news.naver.com/mnews/article/031/0001011537', 'https://imgnews.pstatic.net/image/031/2026/03/09/0001011537_001_20260309144511771.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-03-09 14:45:11', 0, true, '2026-03-09 05:58:46.207093') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (825, '[유가 100달러 쇼크] “유가 급등에 팔아도 걱정”...중동발 가격 인상 도미노 현실화', '■ 중동발 유가급등 충격파가파른 물류비, 원자재 가격 상승수입 비중 큰 건자재 업계 직격타기업 “사태 장기화 시 가격 인상”중기부, 운송비 지원 등 대책 마련사진은 6일 부산항 신선대부두, 감만부두에 컨테이너가 가득 쌓여 있는 모습. 연합뉴스국내 중소·중견기업계가 이란 사태 여파로 브렌트유·WTI 등 국제유가가 8일 배럴당 100달러를 넘어서면서 불안감을 감추지 못하고 있다. 관세와 고환율 등 불확실성이 커진 상황에서 중동의 지정학적 위기로 국제유가까지 폭등하면서 기업들의 경영계획에도 심각한 차질이 빚어지고 있다. 특히 에너지비용이 제품 원가에 차지하는 비중이 큰 기업일수록 시름이 깊다. 중동 사태가 장기화할 조짐을 보이고 있는만큼 국내 중소기업의 피해를 방지하기 위한 지원책 마련이 시급하다는 지적이다.■유가 충격에 수입 원자재·에너지 다소비 기업 ‘흔들’유가 급등에 따른 원자재와 물류비 상승에 민감한 건자재 업계의 불안감이 최고조로 치닫고 있다. 건설경기 침체로 인한 전방산업 악화로 수익성에 비상이 켜진 가운데 중동사태로 추가 비용 부담이 생기면서 고통이 가중되는 모양새다.한찬수 한국시멘트협회 이사는 “최종 소비자인 레미콘쪽이나 건설 쪽에 시멘트를 공급하려면 벌크 시멘트 트레일러(BCT) 등을 움직여야 하는데 유가 상승으로 물류비가 엄청나게 늘 것”이라며 “시멘트를 팔면 팔수록 물류비도 증가해 판매를 해도 남는 게 없어 걱정”이라고 말했다.실제 2022년 러시아·우크라이나 전쟁이 터진 직후 한국건설산업연구원의 연구 결과를 보면 당시 국제 유가 10% 상승 시 시멘트·레미콘 등 콘크리트 제품은 0.21%, 건설용 골재·석재는 0.19%, 철근은 0.12% 등 생산 비용이 오르는 것으로 분석됐다.국내 시멘트 제조사의 한 관계자는 “시멘트 출하량이 급감한 상황에서 친환경 설비 투자는 지속하는 상황에서 중동사태로 원재료인 유연탄 가격까지 상승해 시름이 깊다”며 “딱히 별다른 대비책이 있는 것은 아니고, 원가 인상분을 회사가 수용할 수밖에 없다”고 하소연했다.전쟁이 장기전 양상을 보이면서 가구 업계 역시 비축된 원자재가 소진될 경우 타격을 받을 것이란 우려가 크다. 국내 가구업계는 수입 원자재 비중이 높아 대외 변수에 취약한 구조다. 실제 산림청의 2024년 ‘목재이용실태조사’를 보면 수입 원목과 수입 목재 제품을 포함한 수입 목재 이용량은 2123만㎥에 달했다. 반면 국산 목재 이용량은 518만㎥에 그쳤다.국내 가구업계 관계자는 “규모가 큰 기업을 제외하고 영세 가구업체들은 비축된 원자재가 통상 1~2개월에 불과할 것”이라며 “비축분량이 많아도 가구는 크기가 커 보관료 부담도 적지 않을 것”이라고 전했다.제지업계도 국제 유가 상승으로 인해 비상이 걸렸다. 유가와 연동된 액화천연가스(LNG) 및 산업용 전기세 폭등 가능성이 높아지면서, 생산 원가가 대폭 오를 것으로 우려해서다.제지 산업의 경우 종이를 건조하는 과정에서 막대한 양의 스팀과 전력을 사용하는 ‘에너지 다소비형’ 구조를 띠고 있다. 이에 LNG 및 전기요금 등 에너지 가격 변동이 수익성에 즉각적인 영향을 준다. 일반적으로 제조 원가에서 에너지 비용이 차지하는 비중이 10~15%에 달하는 만큼, 유가 급등은 곧바로 영업이익 하락으로 이어질 수밖에 없다.이에 한솔제지, 무림제지 등 주요 제지 기업들은 향후 에너지 비용 변화에 예의주시하면서, 에너지 효율을 높이는 방안을 강구해 나가겠다는 계획이다.제지연합회 관계자는 “장치 산업인 제지업의 특성상 매번 유가 변동에 따라 수익성에 큰 영향을 끼쳐왔다”면서 “당장의 대책을 세우긴 어렵겠지만 앞으로 신재생에너지 등으로 전력 의존도를 다각화시키는 노력을 지속해야 할 것”이라고 설명했다.■비용 부담에 결국 가격 인상 카드 ‘만지작’9일 서울 시내 한 주유소의 모습. 연합뉴스국제유가와 물류비는 앞으로도 상승세를 이어갈 것이라는 전망이 우세하다.김문식 한국주유소운영협동조합 이사장은 “중동사태로 원유 수송선이 호르무즈 해협을 빠져나오지 못하는 상황에서 4~5개월 분이 묶여있다”며 “당장 출하가 이뤄지지 않으면서 정유사는 생산 가동률 줄이고 감산하기 때문에 유가 상승은 계속될 것 같다”고 진단했다.중소기업계 한 관계자는 “현지 물류사들이 긴급분쟁 할증료라며 컨테이너당 100원 하던 것을 150원으로 받고 있다”며 “물류사가 비용 부담을 화물을 맡긴 화주에게 직접적으로 전가하는 상황이기 때문에 현지에서 비용 부담이 커지고 있다”고 설명했다.이에 이미 일부 기업들은 가격 인상 방안 검토에 들어간 것으로 파악됐다.국내 시멘트 제조사의 한 관계자는 “당장 원가상승으로 인해 손해가 나고 있는 상황이지만 건설사를 포함한 업계 전반이 힘든 상황이라 바로 가격 인상 얘기를 꺼내기 참 어렵다”면서도 “우선은 자체적으로 견뎌보겠지만 전쟁이 장기화하면 가격인상은 불가피해 보인다”고 말했다.국내 가구업계 관계자도 “그간 고환율·물가상승 등 여파로 다수 가구 업체가 가격 인상을 검토 중이었던 상황”이라며 “중동사태로 원자재 가격이 상승하면 업계가 전반적으로 가격 인상에 나설 것”이라고 전망했다.고환율과 물류비 상승을 이유로 선제적으로 가격 인상을 단행했던 페인트 업계는 추가 인상 필요성도 보고 있다. 삼화페인트는 지난달 각 거래처에 주요 제품 공급가격을 3월 1일부터 최소 10% 이상 인상한다는 공문을 전한 것으로 확인됐다. 노루페인트 역시 지난해 11월 건축용 주요 제품군 가격을 평균 3~5% 올렸다. 노루페인트 관계자는 “외부 변수가 장기화돼 원가 부담이 확대될 경우 추가 조정 가능성도 완전히 배제할 수 없다”고 했다.비닐·플라스틱 제조업계는 이미 석유 기반 원재료 가격 인상 직격탄을 맞았지만 이러지도 저러지도 못하는 상황이다. 비닐 포장용품 제조업체를 운영하는 A씨는 “비닐 포장재를 만드는 데 폴리에틸렌을 사용하는데 폴리에틸렌 공급가를 올린다는 얘기를 거래처에서 들었다”며 “비닐 포장재는 사실 원료가 차지하는 비중이 대부분이라 원료 가격이 오르면 장사 자체를 할 수가 없어 막막하다”고 말했다.또다른 비닐 제조업체 대표 B씨는 “이번달에 원료인 나프타를 ㎏당 15만~20만 원 올린다고 통보가 왔고 다음달엔 40만원 얘기가 나온다”며 비닐을 생산하는 공장들은 다 어려운 상황이지만 거래처가 끊길까봐 원재료값 올라도 판매 가격을 쉽게 못 올린다”고 하소연했다.이어 그는 “안 그래도 불황이라서 거래처들이 가격 내려줄 수 없냐고 하는 상황인데 올린다고 하면 어떤 반응일지 두렵다”며 “(원료 공급사들은) 전쟁 전에 이미 입고된 원료들이 있을 텐데 바로 가격을 올려버리니 영세 업자들은 살아남을 수가 없다”고 밀헸다.한성숙 중기부 장관.연합뉴스현재 중소벤처기업부는 국내 중소기업들의 피해를 방지하기 위해 다양한 지원책 마련에 나섰다. 중동 국가 수출 피해·애로 유형 가운데 29%에 해당하는 9건이 물류비 증가인 만큼 정부는 관련 지원 강화에 착수했다. 중기부는 유가 상승 등과 관련해 수출바우처를 통한 국제운송비 지원을 통해 피해를 최소화해 나가겠다는 계획이다. 중기부 관계자는 “유가 급등은 물론 중동 피해 상황을 종합적으로 파악하고 대책 마련에 나설 것”이라고 말했다.', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004597226', 'https://imgnews.pstatic.net/image/011/2026/03/09/0004597226_001_20260309144810839.jpg?type=w800', 'NEWS_SEMI', NULL, '2026-03-09 14:47:08', 0, true, '2026-03-09 06:03:27.778894') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (826, '삼성그룹, 내일부터 신입 공채 접수…반도체 인력 대거 뽑을 듯', '9일 오전 서울 서초구 삼성전자 서초사옥 깃발 모습.  2026.03.09 [서울=뉴시스]삼성그룹이 올 상반기 신입사원 공개채용을 실시한다. 삼성은 9일 채용 홈페이지에 공고를 올리고 10일부터 17일까지 지원서를 접수한다고 밝혔다. 이번 공채에는 삼성전자, 삼성물산, 삼성바이오로직스, 삼성생명 등 18개 계열사가 참여한다.채용 절차는 3월 직무적합성 평가를 시작으로 4월 삼성직무적성검사(GSAT), 5월 면접, 건강검진 순으로 진행된다. 소프트웨어(SW) 직군 지원자는 GSAT 대신 실기 방식의 SW 역량 테스트를 치르며, 디자인 직군은 포트폴리오 심사를 통해 선발한다.올해 공채에서는 반도체 사업을 담당하는 디바이스솔루션(DS) 부문을 중심으로 채용 규모가 늘어날 것이라는 전망이 나온다. 삼성전자가 차세대 고대역폭메모리(HBM) 경쟁력을 강화하고 생산시설 확대를 추진하면서 관련 인력 확보에 적극 나설 것으로 보인다.이재용 삼성전자 회장은 지난달 이재명 대통령과의 면담에서 “삼성전자의 영업 실적이 개선돼 올해 더 많은 채용을 할 여력이 생겼다”고 언급하기도 했다. 삼성은 반도체와 인공지능(AI), 바이오, 배터리, 디스플레이 등 첨단 산업 경쟁력 강화를 위해 투자를 이어가고 있으며, 지난해부터 2029년까지 5년간 국내에서 총 6만 명을 채용한다는 계획이다.삼성은 1957년 국내 최초로 신입사원 공개채용 제도를 도입한 이후 올해까지 70년째 공채 제도를 이어오고 있다. 1970년대 오일쇼크와 2000년대 금융위기 등 숱한 경제 위기 속에서도 외환위기 시기를 제외하고는 공채를 유지했다. 현재 4대 그룹 가운데 정기 공채 제도를 유지하는 곳은 삼성이 유일하다.한편 SK하이닉스도 신입 채용에 나선다. SK하이닉스는 10일 채용 홈페이지를 새로 개편하고 기술·사무직 신입사원 모집을 시작할 예정이다. 메모리 반도체 분야를 중심으로 채용 규모는 세 자릿수 수준이 될 것으로 업계는 보고 있다. 회사는 최근 ‘탤런트 하이웨이(Talent hy-way)’라는 새 채용 전략을 공개하고 신입과 생산직을 포함한 수시 채용을 확대하는 등 인재 확보에 나서고 있다.', NULL, '동아일보', 'https://n.news.naver.com/mnews/article/020/0003702473', 'https://imgnews.pstatic.net/image/020/2026/03/09/0003702473_001_20260309150209508.jpg?type=w800', 'NEWS_SEMI', NULL, '2026-03-09 15:02:09', 0, true, '2026-03-09 06:04:23.510316') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (827, '주한미군 전역 장병, 美 진출 韓 기업 현지 채용 플랫폼 출범', '대한상의·한미동맹재단·美 진출 기업, 주한미군 채용 플랫폼 협력 맞손대미 투자 확대에 발맞춘 민간 협력 모델…한미 경제협력 강화 ''효과''박일준 대한상의 상근부회장과 참석자들이 기녀촬영을 하고 있다. 사진 앞줄 왼쪽부터 최은미 LG에너지솔루션 인재육성담당, 강인석 이마트 지원본부장, 유인정 효성중공업 상무, 니콜라스 남바 공관차석 대행, 제임스 헬러 주한미국대사대리, 임호영 한미동맹재단 회장, 박일준 대한상의 상근부회장, 김대자 산업통상부 국가기술표준원장, 이형희 서울상의 부회장, 제임스김 AMCHAM 회장, 지승영 GS건설 HR실장, 정무경 고려아연 사장, 장종인 HyAxiom 수석. (사진제공 = 대한상공회의소)(서울=뉴스1) 박기호 기자 = 주한미군 전역 장병을 미국에 진출한 우리나라 기업의 현지 채용과 매칭하는 플랫폼이 출범했다. 대미 투자 확대에 발맞춘 민간 협력 모델로 한국과 미국 간 경제협력 강화 효과가 기대된다.대한상공회의소는 9일 서울 중구 상의회관에서 한미동맹재단, 미국 진출 국내 기업과 함께 ''주한미군 전역장병 채용 플랫폼 운영 협력''을 위한 업무협약(MOU)을 체결하고, 플랫폼을 개설했다.이번 협약은 대한상의가 구축한 플랫폼을 통해 미국에 진출한 한국 기업과 주한미군 출신 전역 장병 간의 미국 내 일자리 매칭을 지원하고, 이를 바탕으로 한미 협력과 파트너십 확대에 기여하고자 마련됐다.삼성전자를 비롯해 SK하이닉스, 현대자동차, 한화오션, GS건설, LS그룹, 두산밥캣, 고려아연, 효성중공업, 상미당홀딩스 등 21개 기업이 플랫폼에 참여했다.반도체, 자동차, 이차전지 등 첨단 제조 분야를 비롯해 에너지·조선·로봇·바이오·식품 등 미국에서 활발히 활동 중인 다양한 산업군이 포함됐다. 이들 산업은 미국 내 제조·R&D·영업·서비스 등 다양한 직무 수요가 확대되고 있는 분야다. 진출 한국 기업은 우리나라에 대해 잘 아는 인재를 확보하고 주한미군 전역 장병은 귀국 후에 새로운 커리어를 쌓을 수 있는 길이 열려 양측 모두에 의미가 크다고 대한상의는 전했다.대한상의는 플랫폼 운영 및 기업 대상 홍보를 담당하고, 한미동맹재단은 장병 대상 안내 및 참여 독려를 맡는다. 기업들은 플랫폼에 채용공고를 등록·관리하는 것을 지원하고, 플랫폼을 통해 지원한 주한미군 장병을 대상으로 채용 절차를 진행하는 역할을 수행한다.이번 플랫폼은 미국 진출 기업들의 인재 확보 경로를 다변화하는 새로운 대안이 될 것으로 기대된다. 주한미군으로 한국에서 근무한 장병들은 한국 사회와 문화에 대한 이해도가 높고, 양국을 연결하는 경험을 갖춘 인재라는 점에서 미국에 진출한 우리 기업에 실질적인 도움이 될 수 있을 것으로 전망된다.대한상의는 지난해 9월 한미동맹재단과 사업 추진을 위한 첫 업무협약을 체결한 이후, 평택·동두천·오산 등 주요 미군기지 관계자를 만나 플랫폼을 소개하고 유관기관과의 협력을 이어 왔다. 또한 기업 대상 설명회와 홍보를 병행하며 플랫폼 활성화를 위한 기반을 단계적으로 구축해 왔다.이번 사업은 단순한 채용 지원을 넘어, 미국 내 우호적 기업 환경 조성과 동맹 기반 경제 협력 강화를 위한 전략적 의미도 갖는다. 주한미군 출신 인력은 미국 사회 각 분야에서 활동하며 한미 관계에 대한 높은 이해도를 바탕으로 양국 간 가교 역할을 수행할 잠재력이 크다.또한 미국 연방정부와 주정부는 전역 군인을 채용한 기업에 대해 세제 혜택과 고용 지원 프로그램 등 다양한 인센티브를 운영하고 있어 경영 효율성 제고 측면에서도 긍정적인 효과를 가져올 것으로 기대된다.박일준 대한상의 상근부회장은 "우리 기업들의 적극적인 투자가 미국 내 대규모 고용 창출로 이어지고 있는 만큼, 주한미군 장병들이 그 결실을 공유하며 양국 관계가 더욱 공고해질 것으로 기대한다"며 "이번 플랫폼이 한국 기업의 인력난 해소와 미군 장병의 취업 지원을 동시에 달성하는 한미 협력의 대표적인 윈윈 모델이 될 수 있도록 플랫폼 고도화와 참여기업 확대에 힘쓰겠다"고 말했다.', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008814952', 'https://imgnews.pstatic.net/image/421/2026/03/09/0008814952_001_20260309150111292.jpg?type=w800', 'NEWS_SEMI', NULL, '2026-03-09 15:00:05', 0, true, '2026-03-09 06:04:23.510316') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (828, '잘 나가던 韓반도체에 중동 사태 변수…소재·장비 수급 촉각', '헬륨·브롬 등 일부 소재 의존도 높아…정부, 공급망 대응 강화물류 차질·에너지 가격 상승도 우려…"사태 장기화시 기업 부담"호르무즈 해협 통과하는 유조선[로이터=연합뉴스 자료사진. 재판매 및 DB 금지](서울=연합뉴스) 한지은 기자 = 중동 사태가 장기화할 조짐을 보이면서 호황기를 맞은 국내 반도체 산업에도 공급망 리스크가 새로운 변수로 떠오르고 있다.일부 소재와 장비 수급 차질 가능성에 더해 에너지 가격 상승까지 겹칠 경우 산업 전반의 부담이 커질 수 있다는 우려가 제기된다.9일 한국무역협회에 따르면 지난해 기준 국내에 수입된 헬륨의 64.7%가 카타르산이다. 헬륨은 반도체 웨이퍼 냉각에 필수적인 원료다.반도체 식각 공정에 활용되는 원료인 브롬은 97.5%가 이스라엘에서 들어온다. 중동 지역의 긴장감이 반도체 산업에도 퍼질 수 있는 배경이다.이란의 미사일 공격으로 피해가 발생한 이스라엘 텔아비브 인근에 글로벌 반도체 장비 기업들이 있다는 점도 변수로 지목된다.이 지역은 반도체 공정에 사용되는 측정·검사 장비를 생산하는 주요 거점으로, 일부 장비는 삼성전자와 SK하이닉스 공장에도 공급되는 것으로 알려졌다.이종환 상명대 시스템반도체공학과 교수는 "반도체 산업은 소재와 장비 등 산업 생태계가 긴밀하게 연결돼 있어 중동 사태로 일부 소재나 장비 수급에 차질이 발생할 경우 글로벌 반도체 생태계 전반에 영향을 미칠 수 있다"며 "핵심 재료 몇 가지만 부족해도 생산에 큰 영향을 줄 수 있는 만큼 사전에 대응이 필요하다"고 말했다.이 때문에 정부는 중동 지역 의존도가 높은 반도체 관련 원자재와 장비 공급망 점검에 나섰다.산업통상자원부는 반도체 측정·검사기기와 브롬·헬륨 등 중동 의존도가 높은 14개 품목을 중심으로 수급 상황을 점검하고, 공급망 차질이 발생하지 않도록 대응을 강화하기로 했다.이재명 대통령, 중동상황 관련 비상경제점검회의 주재(서울=연합뉴스) 김도훈 기자 = 이재명 대통령이 9일 청와대에서 열린 중동상황 관련 비상경제점검회의를 주재하고 있다. 2026.3.9 superdoo82@yna.co.kr정부는 반도체 제조용 검사 부품과 장비의 경우 미국 등에서 대체 수입이 가능하고, 브롬 등 일부 정밀화학 제품도 국내 생산과 재고 활용, 수급 대체 등을 통해 영향을 최소화할 수 있을 것으로 본다.정부는 기업별 수급 상황을 점검하면서 필요할 경우 대체 공급선 확보와 물류 지원 등 맞춤형 대응을 통해 반도체 산업의 공급망 안정화를 지원한다는 방침이다.중동 정세 불안이 장기화할 경우 물류 차질과 에너지 가격 상승 등 간접적인 영향이 확대될 수 있다는 전망도 나온다.국제유가 상승은 해상 운임과 항공 운임 상승으로 이어질 가능성이 있어 반도체 장비와 소재 운송 비용에도 부담으로 작용할 수 있기 때문이다.특히 반도체 제조 공정은 대규모 전력과 산업용 가스를 사용하는 에너지 집약적 산업인 만큼 유가 상승이 장기화할 경우 생산 비용 증가로 이어질 수 있다는 분석이 제기된다.실제로 2022년 러시아·우크라이나 전쟁 당시 반도체 산업은 공급망 충격을 경험한 바 있다.우크라이나에서 생산되는 네온가스 공급이 차질을 빚으면서 반도체 핵심 소재 수급 불안이 커졌고 가격도 급등했다.여기에 국제유가 상승에 따른 에너지 비용 증가와 글로벌 경기 둔화가 겹치면서 반도체 산업 전반의 불확실성이 확대됐다.다만 업계에서는 이번 사태가 당장 생산 차질로 이어질 가능성은 제한적일 것으로 보고 있다.주요 반도체 기업들이 핵심 소재와 장비에 대해 일정 수준의 재고를 확보하고 있고, 공급망도 다변화돼 있기 때문이다.반도체 업계 관계자는 "현재로서는 생산 차질로 이어질 가능성은 크지 않다"며 "다만 중동 상황이 장기화하면 물류와 에너지 비용 상승 등으로 기업 부담이 커질 수 있어 상황을 예의주시하고 있다"고 말했다.writer@yna.co.kr', NULL, '연합뉴스', 'https://n.news.naver.com/mnews/article/001/0015947197', 'https://imgnews.pstatic.net/image/001/2026/03/09/PCM20260306000065990_P4_20260309145123731.jpg?type=w800', 'NEWS_SEMI', NULL, '2026-03-09 14:50:17', 0, true, '2026-03-09 06:04:23.510316') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (829, '고려아연 주총 앞두고 ESG평가원 “현 경영진 지지”', '뉴시스[스포츠동아 양형모 기자]  고려아연 정기주총을 앞두고 한국ESG평가원이 현 경영진 지지를 권고하며 경영 안정 필요성을 강조했다.한국ESG평가원은 최근 ‘2026년 고려아연 정기주주총회 의안 분석 보고서’를 통해 주주들에게 현 경영진을 지지하는 방향으로 의결권을 행사할 것을 권고했다. 보고서는 고려아연이 창사 이래 최대 실적을 기록했고 거버넌스 개선과 주주환원 확대에서도 긍정적인 성과를 보였다고 평가했다.평가원은 “현 경영진 체제에서 실적 개선과 거버넌스 개선, 주주환원율 제고가 이어지고 있다”고 설명했다. 이어 자사주 소각과 현금배당 등 주주환원 정책이 주주가치 제고에 기여했다고 분석했다.또한 보고서는 고려아연이 경영실적과 주주환원, ESG 평가 등에서 영풍보다 우월한 평가를 받고 있다고 언급했다. “MBK라는 사모펀드의 경영이 실적과 재무구조가 탄탄한 고려아연에 도움이 될지는 의문”이라는 의견도 함께 제시했다.정기주총 주요 안건 가운데 이사 선임과 감사위원 분리선출 확대에 대해서는 고려아연 측 제안에 긍정적인 평가가 나왔다. 보고서는 고려아연이 이사 5인을 먼저 선임하고 나머지 1석을 감사위원 분리선임 절차에 따라 채우겠다는 방안이 개정 상법 취지를 선반영한 접근이라고 설명했다.한국ESG평가원은 “감사위원 분리선임을 별도 의제로 진행하면 소액주주가 감사위원의 자격과 전문성을 보다 집중적으로 검토할 수 있을 것”이라고 밝혔다.영풍·MBK 연합이 제안한 정관 변경안에 대해서는 신중한 입장을 나타냈다. 집행임원제 도입 안건은 2025년 1월 임시주총에서 영풍·MBK 측이 반대표를 던져 부결됐던 사안이라는 점도 지적했다.신주 발행 시 이사의 충실의무를 정관에 명문화하자는 주주제안에 대해서도 이미 관련 법적 판단이 내려진 사안이라는 점을 들어 필요성이 크지 않다는 의견을 제시했다.주주총회 의장을 대표이사가 아닌 이사회 의장이 맡도록 하자는 안건에 대해서는 경영권 갈등 상황에서 경영 혼란을 키울 가능성이 있다고 평가했다.고려아연 관계자는 “창사 이래 최대 실적과 거버넌스 개선, 주주환원 강화 노력 등을 종합적으로 평가해 긍정적 의견이 제시된 것으로 보인다”며 “경영 안정성을 확보해 장기 성장과 주주가치 제고에 힘쓰겠다”고 말했다.', NULL, '스포츠동아', 'https://n.news.naver.com/mnews/article/382/0001260329', 'https://imgnews.pstatic.net/image/382/2026/03/09/0001260329_001_20260309144413626.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 14:44:13', 0, true, '2026-03-09 06:04:31.189434') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (830, '‘추억의 프로스펙스’ 리브랜딩 본격 추진…“나이키 비켜~”', 'LS네트웍스, 유통구조 개선브랜드 중심 전략체계 구축''러닝화'' 중심 상품군 강화프로-스펙스가 45년 브랜드 자산을 바탕으로 리브랜딩에 나선다. 사진은 전략 상품으로 이번에 출시하는 프로-스펙스 쿠셔닝 러닝화 SWNA SEAM 26. LS네트웍스 제공사진은 2019년 3월 출시한 오리지널 한정판 모습. 프로스펙스는 당시 88올림픽을 기념하는 1988, 프랭크, 빈티지플로럴 등 총 19종으로 구성된 오리지널 부산 한정판을 출시했다. 한정판 디자인, 네이밍에는 동의대 학생들이 참여했다. 국제신문 DB1980~1990년대 글로벌 브랜드 나이키에 맞섰던 국내 브랜드 프로-스펙스가 브랜드 혁신을 통해 재기에 나선다. 유통 구조를 혁신하고 러닝화 중심의 전략 상품을 개발해 리브랜딩에 나선 것이다. 리브랜(Rebranding)은 시장에 알려진 기업 또는 브랜드 정체성을 새롭게 하는 작업이다.프로스펙스를 생산·판매하는 LS네트웍스는 올해 SS 시즌(봄·여름)을 기점으로 대대적인 리브랜딩을 전개한다고 9일 밝혔다. 이번 리브랜딩은 브랜드 중심의 전략 체계를 구축하고 브랜드 가치를 체계적으로 강화하기 위한 중장기 전략이라는 게 LS네트웍스 설명이다. 현재 LS네트웍스 본사는 경남 김해시에, 주요 거점은 서울 용산구에 있다. 프로-스펙스는 45년간 축적한 브랜드 자산을 기반으로 정체성을 명확히 하고 상품 기획, 디자인, 유통 전략 전반에서 일관된 브랜드 경험을 구축해 나갈 계획이다.프로-스펙스는 이번 리브랜딩에서 브랜드 방향성을 ‘SPORTS FOR ALL(모든 이를 위한 스포츠)’로 내세웠다. 기록, 경쟁 중심의 스포츠를 넘어 누구나 자신의 방식으로 스포츠를 즐기고 도전할 수 있는 문화를 지향하는 브랜드 철학이다. ‘SPORTS FOR ALL’은 패럴림픽(장애인 올림픽) 선수단과 국가대표 후원, 스포츠 구단 협력, 마라톤 대회 참여 등 기존 브랜드 활동과도 이어진다.상품 포트폴리오는 ▷러닝 ▷스포츠스타일 ▷헤리티지 ▷스포츠 등 네 개 전략 상품군 중심으로 재편했다. 러닝 카테고리를 브랜드 핵심 축으로 설정했다. 2026 SS 시즌에는 이 전략의 첫 결과물로 쿠셔닝 러닝화 ‘SWNA SEAM 26’을 선보인다. 산업디자인 스튜디오 SWNA와 협업해 개발했으며 일상과 10km 내외 러닝을 아우르는 데일리 러닝화로 설계됐다.유통 전략 또한 브랜드 경험 중심으로 재구성했다. 서울 용산 LS타워 지하 1층의 직영점과 아웃렛은 통합 직영 매장으로 리뉴얼했다. 프로-스펙스는 매장을 단순 판매 공간을 넘어 브랜드 철학과 스토리를 경험할 수 있는 브랜드 라운지로 확대해 나갈 계획이다. 부산에는 롯데백화점 광복점에 대형 매장이 있다.LS네트웍스는 1949년 양태진 양정모 부자가 부산 부산진구 범천동에 설립한 국제화학이 모태다. ‘왕자표’ 고무신으로 전국적 명성을 얻었고 국내 신발 산업의 기틀을 닦았다. 국제화학은 1976년 국제상사로 이름을 바꿨고 1981년 자체 브랜드 프로-스펙스를 출시했다.하지만 국제상사가 속한 국제그룹은 1985년 전두환 정권으로부터 강제 해체를 당하고 한일합섬에 인수됐다. 1997년 IMF 외환위기 때 한일합섬이 부도가 나면서 1999년부터 법정관리를 받았다. 2007년 LS그룹 계열인 E1이 국제상사를 인수하고 2008년에는 사명을 LS네트웍스로 바꿨다.프로-스펙스가 주춤하던 2000년대 초반 국내 스포츠화 시장은 나이키, 뉴발란스, 아디다스 등 외산 브랜드가 주류를 이뤘다. 현재 국내 스포츠화(운동화) 시장은 약 4조 원 규모로 추산된다. 나이키 뉴발란스 아디다스가 3강 체제를 구축한 가운데 아식스 호카 데상트 스케처스 등이 약진하는 양상이다. 유통망에서는 무신사, 크림 등의 영향력도 크다.', NULL, '국제신문', 'https://n.news.naver.com/mnews/article/658/0000137351', 'https://imgnews.pstatic.net/image/658/2026/03/09/0000137351_001_20260309143910165.jpg?type=w800', 'NEWS_CONSUMER', NULL, '2026-03-09 14:39:10', 0, true, '2026-03-09 06:04:36.201426') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (862, '한독 ''항암제 명가'' 드라이브 건다 … 2년 내 자체 신약으로 경쟁력 입증', '김윤미 전문의약품 사업 총괄"올해 항암 사업 매출을 전년 대비 2배 이상 성장시키겠습니다."김윤미 한독 전문의약품(ETC) 사업 총괄 전무가 매일경제 인터뷰에서 "단순한 외형 성장을 넘어 신약의 허가부터 급여, 판매까지 아우르는 독보적인 ''비즈니스 플랫폼''으로서 가치를 증명하겠다"며 이같이 밝혔다.가장 즉각적인 움직임은 항암 조직의 강화다. 한독은 올해 1월 사노피의 표준 항암제 ''엘록사틴''과 ''잘트랩''을 도입하며 해당 제품을 전담하던 사노피 출신의 항암 전문가 10명을 전격 영입했다. 김 전무는 "항암제 시장은 전문의와의 고도화된 학술적 소통이 필수적인 만큼 검증된 인적 자산을 확보해 진입 장벽을 낮췄다. 업계에 유례없는 일"이라며 "기존 소화기계 암 치료제의 강점을 기반으로 올해 위암·대장암 시장 점유율을 공격적으로 확대할 계획"이라고 밝혔다.특히 올해는 위암 분야에서 엘록사틴이 면역 항암제 ''키트루다''와의 병용요법으로 급여가 확대된 첫해라는 점에 주목하고 있다. 김 전무는 "지난 4년간 기다려온 위암 병용요법 급여가 올해 1월 시작되면서 엘록사틴의 매출 성장에 강력한 모멘텀이 될 것"이라고 말했다. 또 올해 항문암 치료제 ''자이니즈''의 허가 절차를 본격화하고, 담관암 치료제 ''페마자이레''를 시장에 안착시켜 소화기계 암 전주기 포트폴리오를 완성한다는 복안이다.중장기 비전은 2027년 출시 예정인 자체 신약 ''토베시미그''에 맞춰져 있다. 김 전무는 "에이비엘바이오에서 국내판권을 확보하고 미국 컴퍼스 테라퓨틱스와 공동개발 중인 이 담도암 치료제는 글로벌 임상 2/3상이 순조롭게 진행 중"이라며 "최근 임상에서 예상보다 낮은 사망 건수가 관찰되는 등 유의미한 데이터가 확보됐다"고 말했다. 2027년 한독의 이름으로 시장에 나올 첫 자체 항암 신약은 한독이 ''라이선스 인 위주의 회사''에서 ''연구개발(R&D) 기반 신약 기업''으로 완전히 탈바꿈하는 상징이 될 것이라고 덧붙였다.희귀질환 분야에서는 글로벌 파트너십 고도화를 통한 수익성 개선에 집중한다. 2024년 출범한 글로벌 희귀질환 전문 기업 ''소비''와의 합작법인 ''한독소비''를 통해 혁신 신약의 국내 도입 속도를 대폭 끌어올린다. 연속혈당측정기(CGM)와 같은 메디컬 디바이스 사업도 강화해 ''당뇨 명가''의 전문성을 디지털 헬스케어 영역으로 확장한다. 김 전무는 "올해는 한독이 가진 ''문제 해결 역량''을 숫자로 증명하는 해가 될 것"이라며 "환자와 의료진에게 없어서는 안 될 파트너로서 내실 있는 성장을 이어가겠다"고 강조했다.[고재원 기자 / 사진 김재훈 기자]', NULL, '매일경제', 'https://n.news.naver.com/mnews/article/009/0005645896', 'https://imgnews.pstatic.net/image/009/2026/03/05/0005645896_001_20260306092516451.jpg?type=w800', 'NEWS_BIO', NULL, '2026-03-05 17:44:13', 0, true, '2026-03-09 06:10:18.699251') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (831, '현대건설, 상반기 신입 공채…6개 분야 인재 모집', '인적성·1차 면접·2차 면접 거쳐 7월 합격자 발표*재판매 및 DB 금지[서울=뉴시스] 홍찬선 기자 = 현대건설이 올 상반기 신입사원을 공개 채용한다.현대건설은 ▲토목(토목) ▲건축주택(건축·설비·전기·토목) ▲플랜트(기계·화공) ▲뉴에너지(원자력·기계·화공·전기·토목·건축) ▲지원(경영일반) ▲안전품질 등 6개 분야에 대해 올 상반기 신입공채를 실시한다고 9일 밝혔다.지원자격은 정규 4년제 대학(이상) 기졸업자 및 올 8월 졸업예정자로, 지원서는 오는 24일까지 접수하면 된다. 채용 절차는 인적성(4월), 1차 면접(5월), 2차 면접(6월)을 거쳐 7월에 최종 합격자 발표할 예정이다.또한 글로벌 인재 확보를 위해 외국인 유학생 채용도 동시 진행한다. 현대건설은 해외사업의 추진을 위해 북미와 유럽, 일본, 오세아니아 국적자와 한국어 능력우수자를 우대한다고 설명했다.현대건설은 오는 16일부터 20일까지 서울 신사동 디에이치 갤러리에서 팝업 리쿠르팅을 개최하고, 채용설명회를 비롯해 본부·직무 특강, 신입사원 합격수기 공유, 채용상담 등 다양한 프로그램을 진행한다고 밝혔다.', NULL, '뉴시스', 'https://n.news.naver.com/mnews/article/003/0013810344', 'https://imgnews.pstatic.net/image/003/2026/03/09/NISI20260305_0002076590_web_20260305143942_20260309143926193.jpg?type=w800', 'NEWS_CONSTRUCT', NULL, '2026-03-09 14:37:50', 0, true, '2026-03-09 06:04:46.725565') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (832, '삼성, 상반기 공채 시작…18개 계열사 참여', '2025년 10월 삼성전자 인재개발원(경기도 수원)에서 삼성전자 감독관이 삼성직무적성검사(GSAT) 응시자를 대상으로 예비 소집을 진행하는 모습. 사진 삼성전자반도체와 인공지능(AI) 산업을 중심으로 인재 확보 경쟁이 치열한 가운데 삼성이 올해 상반기 신입사원 공개채용에 나선다. 주요 대기업들이 수시 채용으로 채용 방식을 바꾸는 추세지만, 삼성은 70년째 공채 제도를 유지하고 있다.9일 삼성에 따르면 10일부터 17일까지 채용 홈페이지 ‘삼성커리어스’를 통해 2026년 상반기 대졸 신입사원 공개채용 지원서를 접수한다. 채용 절차는 직무적합성 평가를 거쳐 4월 삼성직무적성검사(GSAT), 5월 면접과 건강검진 순으로 진행된다.이번 공채에는 삼성전자·삼성물산·삼성바이오로직스·삼성바이오에피스·삼성생명·삼성디스플레이·삼성SDI·삼성전기·삼성SDS·삼성화재·삼성증권·삼성자산운용·삼성중공업·삼성E&A·제일기획·에스원·삼성글로벌리서치·삼성웰스토리 등 18개 관계사가 참여한다.소프트웨어(SW) 직군 지원자는 GSAT 대신 실기 방식의 SW 역량 테스트를 치르며, 디자인 직군은 디자인 포트폴리오 심사를 통해 선발한다.삼성은 1957년 국내 기업 가운데 처음으로 신입사원 공개채용 제도를 도입해 현재까지 이어오고 있다. 외환위기 등 일부 특수한 시기를 제외하면 글로벌 금융위기 등 경제 위기 상황에서도 공채를 중단하지 않았다. SK·현대차·LG 등 4대 그룹 가운데 유일하게 정기 공채를 유지하고 있다.재계에서는 삼성이 공채를 유지하면서 청년들에게 예측 가능한 취업 기회를 제공하고 있다는 평가가 나온다. 매년 상·하반기 정기적으로 진행되는 공채가 대규모 채용 창구 역할을 해왔다는 것이다.채용 제도의 내용적 혁신도 주목받는다. 1993년 대졸 여성 공채를 도입했고, 1995년에는 지원 자격에서 학력 제한을 없애 ‘열린 채용’을 도입했다. 삼성직무적성검사(GSAT)도 자체 선발 시스템으로 자리잡았다.삼성은 반도체·AI·바이오·배터리·디스플레이 등 첨단산업 투자를 늘리면서 인재 확보에도 속도를 내고 있다. 삼성은 향후 5년 동안 국내에서 6만명을 채용할 계획이다.이재용 삼성전자 회장은 지난해 8월 경제단체·기업인 간담회에서 “국내에서 양질의 일자리를 창출하고 고부가가치 산업을 육성할 수 있도록 관련 투자를 지속하겠다”고 밝혔다.삼성은 공채 외에도 인재 양성 프로그램을 운영하고 있다. 대표적으로 ‘삼성청년SW·AI아카데미(SSAFY)’를 통해 청년들에게 소프트웨어 교육을 제공하고 있는데 2019년 이후 수료생 약 8500명이 2300여개 기업에 취업했다. 최근에는 교육 대상을 마이스터고 졸업생까지 확대하고 AI 중심 교육으로 커리큘럼을 개편했다.이밖에 전국기능경기대회 입상 기술 인재 특별채용, 마이스터고 학생 대상 채용연계형 인턴 제도 등을 통해 고졸 기능 인력 채용도 확대하고 있다.', NULL, '중앙일보', 'https://n.news.naver.com/mnews/article/025/0003507767', 'https://imgnews.pstatic.net/image/025/2026/03/09/0003507767_001_20260309150111980.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 15:00:00', 0, true, '2026-03-09 06:04:55.433267') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (833, '현대차·삼성화재, ‘K-자율주행 협력모델’ 기업 선정', '정부, 자율주행 차량·보험·운행 서비스 통합 지원… 사고 보상 최대 100억정부세종청사 국토교통부청사 전경. 경기일보DB국토교통부는 자율주행 실증도시 사업을 지원하기 위해 자동차제작사, 보험사, 운송플랫폼사로 구성된 ‘K-자율주행 협력모델’에 참여할 기업을 공모한 결과, 자동차제작사와 운송플랫폼사에 ‘현대자동차’, 보험사에 ‘삼성화재’를 각각 최종 선정했다고 9일 밝혔다.자동차제작사로 선정된 현대자동차는 자율주행 기술 실증에 최적화된 자율주행 전용차량(SDV)을 개발·공급하고, 차량 정비 및 개발 인력을 현장에서 지원할 계획이다. 특히, 자율주행 기업의 자율주행시스템을 탑재할 수 있도록 표준화된 차량 제어 인터페이스(API)와 고속 통신 네트워크를 제공해 기술개발을 지원할 예정이다. 차량에서 발생하는 데이터를 실시간으로 수집해 차량 상태 모니터링 및 데이터 파이프라인 구축도 추진한다.운송플랫폼의 경우에는 자율주행 차량과 플랫폼간 연동을 통해 차량 관제 및 배차 관리, 운행 데이터 분석 등 서비스 운영체계를 구축한다. 실시간으로 수집되는 차량 센서 및 상태 데이터 기반으로 엣지 케이스 자동 수집, 운행 품질 분석, 차량 관제 지원 등을 통해 자율주행 기업의 기술개발을 지원할 예정이다.보험사로 선정된 삼성화재는 자율주행 사고당 100억원, 연간 총 300억원 수준의 보상한도를 제시해 자율주행 실증 과정에서 발생할 수 있는 다양한 사고에 대해 안정적인 보장체계를 마련했다. 또 자율주행 보험 전담 콜센터 및 고객창구를 운영해 보험가입부터 사고 대응·보상까지 원스톱 서비스를 제공하고 사고기록장치(EDR) 데이터 분석, 사고예방 컨설팅, IT 보안 컨설팅 등 자율주행 기업을 위한 특화 서비스도 지원할 예정이다.국토부는 이번 참여기업 선정을 통해 차량 공급, 전용 보험, 서비스 운영을 하나의 체계로 묶어 자율주행 기업이 기술 개발에 집중할 수 있도록 지원하고 자율주행 서비스 상용화를 앞당길 계획이다. 우선 참여기업과 자율주행 기업 지원방안 논의에 착수하고, 4월말 실증도시 참여기업 공모가 마무리되면 선정된 자율주행 기업도 협력모델에 참여해 본격적인 기술협력에 나선다는 방침이다.박준형 국토부 모빌리티자동차국장은 “차량·시스템·서비스·보험이 결합된 자율주행 산업 생태계를 구축해 국가대표 K-자율주행 협력모델로 거듭날 수 있도록 노력하겠다”고 밝혔다.', NULL, '경기일보', 'https://n.news.naver.com/mnews/article/666/0000098544', 'https://imgnews.pstatic.net/image/666/2026/03/09/0000098544_001_20260309143812899.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 14:38:12', 0, true, '2026-03-09 06:04:55.433267') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (834, '현대차증권, 우리사주 대출이자 지원 연장 "주주가치 제고"', '대출이자 지원 연장 통해 주식 장기 보유 여건 마련잠재적 매물(오버행) 우려 해소 통해 주주가치 보호현대차증권이 임직원들의 금융 부담을 완화하고 주가 안정성을 제고하기 위해 우리사주 대출이자 지원을 연장하기로 결정했다. 이번 결정은 임직원들의 경제적 부담을 덜어주는 동시에 시장의 잠재적 매도 물량 우려를 해소해 주주가치를 보호하기 위한 선제적 조치다.9일 금융투자업계에 따르면 현대차증권 임직원이 우리사주 청약으로 받은 주식의 의무보호예수 기간이 다음 달 1일 종료된다. 이에 따라 현대차증권 우리사주 조합원은 다음 달 2일부터 유상증자 때 받은 신주를 매매할 수 있다. 다만 현대차증권은 우리사주 청약대금에 대한 대출이자 지원 기간을 올해 8월까지로 연장하기로 했다.지난해 현대차증권은 우리사주조합과 구주주를 대상으로 진행한 1620억원 규모의 유상증자를 성공적으로 마무리한 바 있다. 특히 우리사주조합 대상 청약은 사전 청약률 161%를 기록하면서 흥행에 성공했고, 당시 우리사주조합에 배정된 물량 301만2048주 전부 청약하면서 100%의 청약률을 보였다.현재 주가는 1만700원 전후로 당시 발행가(5380원)와 비교하면 100% 주가가 올랐다. 주가 상승으로 인해 임직원들의 투자 수익률이 고공 행진을 하는 상황인 만큼 현대차증권의 이번 결정은 이례적이라는 평가다.이번 연장 조치를 통해 우리사주를 보유하고 있는 현대차증권 임직원들은 대출 이자 부담에 대한 압박 없이 주식을 장기 보유할 수 있게 됐다. 회사의 성장을 믿고 투자한 임직원을 대상으로 금융 부담을 실질적으로 낮춰 자산 증식을 돕겠다는 취지다.또한 시장에서는 이번 대출이자 지원 연장이 주가 안정에 긍정적인 역할을 할 것으로 기대하고 있다. 의무보호예수가 해제되면 임직원들이 주식을 매도할 수 있고, 매도 물량이 단기간에 급증해 주가에 부정적 영향을 미칠 가능성이 있다. 현대차증권은 대출이자 지원 기간을 8월까지로 늘려 매도 시점을 분산하는 효과를 노린 것으로 보인다.매월 이자 비용을 낼 필요가 없어진 만큼 주식을 장기 보유하는 임직원들도 늘어날 것으로 예상된다. 현대차증권 관계자는 "이번 대출이자 지원은 임직원과 회사가 함께 성장을 이뤄내겠다는 책임경영의 의지를 다지는 계기가 될 것"이라며 "앞으로도 주주 가치 제고를 위한 다양한 정책을 검토하는 한편, 임직원들이 애사심을 갖고 성장에 집중할 수 있는 환경을 만들어 나갈 것"이라고 강조했다.', NULL, '아시아경제', 'https://n.news.naver.com/mnews/article/277/0005731511', 'https://imgnews.pstatic.net/image/277/2026/03/09/0005731511_001_20260309145310600.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 14:52:07', 0, true, '2026-03-09 06:07:12.888728') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (835, '대상 청정원, 브랜드 론칭 30주년 기념 엠블럼 공개', '대상 청정원이 브랜드 론칭 30주년을 기념해 새롭게 제작한 엠블럼을 9일 공개했다. 대상 제공대상 청정원이 브랜드 론칭 30주년을 기념해 새로 제작한 엠블럼을 공개했다.9일 대상에 따르면 청정원은 1996년 출범 이후 장류, 소스, 간편식 등 다양한 제품군을 확장해 온 종합식품브랜드다. 이번 엠블럼은 지금까지 청정원이 쌓아온 브랜드 헤리티지를 시각적으로 구현해 소비자와 함께한 30년을 기념하기 위해 개발됐다.대상은 청정원 BI(Brand Identity)의 핵심 디자인 요소를 숫자 ‘30’에 녹여내 브랜드 정체성을 직관적으로 인식할 수 있도록 청정원 30주년 기념 엠블럼을 설계했다. 청정원 BI의 타원 형태와 곡선 두께감을 엠블럼에 동일하게 적용했으며 대표 메인 컬러인 프레시 블루(Fresh Blue)와 트루 옐로우(True Yellow)를 활용해 일관성을 높였다.대상은 청정원 BI도 개선했다. 폰트와 심볼 마크의 굵기, 비율 등을 조정해 다양한 환경에서 선명하게 인식할 수 있도록 가독성을 높였다. 새 BI는 청정원 순창, 호밍스, 맛선생, 햇살담은 등 제품 패키지에 순차적으로 적용해나갈 예정이다.대상 관계자는 “30년간 쌓아온 청정원의 브랜드 DNA를 시각적으로 재해석한 이번 엠블럼을 통해 소비자들이 청정원만의 차별화된 가치를 직관적으로 체감할 수 있도록 했다”며 “새로워진 엠블럼과 BI를 앞세워 다시 한번 청정원의 브랜드 존재감을 각인시키고, 소비자들의 일상 전반에서 브랜드 신뢰도와 친밀도를 강화해 나갈 것”이라고 말했다.앞서 대상 청정원은 지난 1일부터 브랜드 론칭 30주년을 맞아 소비자의 일상에 늘 함께하는 ‘라이프푸드 전문 브랜드’로서의 도약을 선포하고 배우 임윤아와 함께 새 브랜드 캠페인을 전개하고 있다.', NULL, '경향신문', 'https://n.news.naver.com/mnews/article/032/0003432066', 'https://imgnews.pstatic.net/image/032/2026/03/09/0003432066_001_20260309150108381.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 15:00:00', 0, true, '2026-03-09 06:07:53.407195') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (836, '"용산에 1만가구?…뉴욕·런던처럼 주택보다 기능 중심 설계해야"', '6일 국회서 용산국제업무지구 주택공급 토론회(서울=뉴스1) 유승관 기자 = 오세훈 서울시장과 권영세 국민의힘 의원을 비롯한 참석자들이 6일 서울 여의도 국회 의원회관에서 열린 용산국제업무지구 ''글로벌 허브'' 인가 ''거대 베드타운''인가? 주택 1만호 공급 논란과 해법 모색을 위한 정책토론회에서 기념 촬영을 하고 있다. 2026.3.6/뉴스1  Copyright (C) 뉴스1. All rights reserved. 무단 전재 및 재배포,  AI학습 이용 금지. /사진=(서울=뉴스1) 유승관 기자"용산은 서울의 마지막 대규모 가용부지로, 일반 주거지와는 달리 국가 상징성과 국제 기능을 고려해야 합니다."정재훈 단국대 교수는 6일 서울 영등포구 국회 국회의원회관 제1소회의실에서 열린 용산국제업무지구 주택공급 토론회에서 "용산이 서울역과 광역철도망, GTX 등이 연결되는 교통 허브로, 교통·녹지·업무 기능이 교차하는 서울의 핵심 공간"이라며 이같이 말했다.이날 토론회는 ''주택 1만호 공급 논란과 올바른 해법 모색을 위한 토론회-용산국제업무지구, 글로벌 허브인가 거대 베드타운인가''를 주제로 정부의 도심 주택 공급 확대 방안에 따른 용산국제업무지구 개발 방향을 논의하기 위해 마련됐다.정 교수는 서울이 인구 규모에 비해 국제업무 기능의 밀도가 높지 않다고 지적했다. 그는 "서울의 인구 집중도 대비 지역내총생산(GRDP) 집중도는 런던이나 뉴욕에 비해 아직 낮은 수준"이라며 "한국 내 글로벌 기업 본사(헤드쿼터)도 14개에 불과해 미국(138개), 중국(135개)보다 크게 부족하다"고 말했다.정 교수는 또 직주 근접 구조를 갖춘 국제업무지구 조성이 필요하다고 강조했다. 그는 "직주 분리는 교통 혼잡과 시간 비용을 증가시키고 밤에는 도심 공동화 현상을 초래해 도시 중심 기능을 약화시킨다"며 "국제 기업 종사자와 전문 인력 역시 직주 근접을 선호하기 때문에 (직주 근접 구조를 갖춘 업무지구 조성이) 글로벌 인재 유치 전략으로도 이어질 수 있다"고 설명했다.아울러 해외 주요 도시의 글로벌 업무지구 역시 금융·첨단산업·행정·연구 기능을 우선 배치한 뒤 주거 기능을 보완적으로 도입하는 방식으로 개발됐다고 분석했다. 주거는 업무 중심성을 약화시키지 않는 범위에서 계획됐다는 것이다.정 교수는 "미국 뉴욕의 허드슨야드는 맨해튼 서부의 업무 기능 확장을 핵심 목표로 개발됐고 주거는 업무 집적을 보완하는 구조로 확대됐다"며 "글로벌 업무지구들은 업무 집적이 안정화된 이후 주거가 단계적으로 확대되는 방식으로 발전해 왔다"고 말했다. 이어 "어느 사례도 단순히 주택 물량 확대를 중심으로 전략을 세우지는 않았다"고 덧붙였다.이날 토론회에서는 ''용산국제업무지구 도시개발사업 개발계획''(이재종 도화엔지니어링 이사) 등에 대한 발제와 토론도 이어졌다. 토론은 유석연 서울시립대 교수를 좌장으로 도시계획·주택 분야 전문가와 용산 지역 주민, 인근 지역 학부모 등 100여 명이 참석한 가운데 진행됐다.오세훈 서울시장은 이날 토론회에 참석, "양을 늘리는 대신 질을 포기한 주거 정책은 결국 시민의 삶의 질을 떨어뜨리고 서울이 키워온 경쟁력을 스스로 약화시키는 결과를 낳을 수 있다"며 "오늘 토론회가 용산과 서울의 미래를 책임 있게 설계하는 합리적인 공론의 장이 되길 바란다"고 강조했다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005326503', 'https://imgnews.pstatic.net/image/008/2026/03/06/0005326503_001_20260306171709041.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-03-06 17:16:36', 0, true, '2026-03-09 06:09:00.766160') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (837, '적도기니 대통령 관저도…병오년 해외건설 수주 첫달 성적은', '1월 해외 수주액 7.8억달러…전년比 47.3%↓삼성 형제와 현대엔지니어링, 쌍용건설 ''낭보''K-건설이 ''붉은 말''의 해인 병오년에 500억달러 수주 달성을 목표로 뛴 첫달 성적표가 나왔다. 북미·태평양 시장을 중심으로 새 일감을 따냈고 그 뒤를 이어 아시아와 아프리카에서 수주가 많았다. 그러나 수주 실적 자체는 전년 동기 대비 절반에 그쳤다.12일 해외건설협회에 따르면 지난달 국내 건설사의 해외 수주액은 7억7517만달러다. 이는 전년 동기(14억7136만달러) 대비 47.3% 감소한 수치다.쌍용건설이 2024년 준공한 적도기니 바타공항 전경./사진=쌍용건설가장 많은 수주액을 기록한 건설사는 삼성E&A다.삼성E&A는 2억8667만달러를 기록했다. 신규 수주는 1건이다. 멕시코에서 삼성전기 멕시코법인이 발주한 삼성전기 M4프로젝트를 4444만달러에 수주했다.나머지 수주고는 기존 현장의 공사비 증액을 통해 쌓았다. 특히 북미·태평양 지역에서 2억2972만달러의 증액이 있었다. 삼성전자의 미국 반도체 공장 프로젝트인 ''T-PJT'' 증액분(2억2855만달러)이 반영됐다. 아시아에서는 태국 올레핀 플랜트 개보수 프로젝트 증액분인 749만달러를 포함해 총 1251만달러의 증액이 있었다.그다음으로 많은 일감을 확보한 건설사는현대엔지니어링이다. 미국 HMGMA 현대차공장 신축공사에서 1억2000만달러의 증액 계약이 1건 있었다.삼성물산은 9777만달러의 일감을 따냈다. 일본 오키나와에 주둔 중인 미 육군 공병단의 자녀를 위한 교육시설인 쿠바사키 고등학교 건설공사를 4081만달러에 수주한 게 대표적이다.쌍용건설은 중앙아프리카 적도기니에서 대통령 관저 및 오피스 공사 2건을 포함해 7455만달러를 수주했다. 적도기니의 신수도가 될 시우다드데라파스(오얄라)에 대통령 레지던스(4744만달러)와 적도기니 동쪽 가봉과 맞닿은 몽고모에 대통령 오피스(1788만달러) 등을 짓는다.쌍용건설 관계자는 "2011년 적도기니 진출 후 다양한 건축·토목 공사를 수행했다"면서 "적도기니에서 2018년과 2024년에 각각 몽고메엔국제공항, 바타공항을 준공해 해당 국가에 3개 공항 건설프로젝트 중 2개 등 사업을 마친 경험이 있다"고도 말했다.중앙아프리카에서는 원전 관련 수주도 있었다. 도화엔지니어링이 우간다에서 631만달러의 신규 원전 부지평가 수행 용역 일감을 따냈다.이처럼 지난달 수주 대부분은 북미·태평양과 아시아, 아프리카 시장에서 나왔다. 북미·태평양에서만 전체 수주의 52.1%에 해당하는 4억390만달러의 일감이 나왔다. 아시아와 아프리카에서는 각각 1억5212만달러, 9427만달러를 수주했다. 반면 수주 텃밭이라 불리는 중동 수주는 3334만달러에 그쳤다.', NULL, '비즈워치', 'https://n.news.naver.com/mnews/article/648/0000044466', 'https://imgnews.pstatic.net/image/648/2026/02/12/0000044466_001_20260212063619664.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-02-12 06:36:19', 0, true, '2026-03-09 06:09:00.766160') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (842, '기업공시[2월 9일]', '<코스피 시장>▲아모레퍼시픽 홀딩스=496만 원 규모 자기 주식 처분 결정 ▲아주스틸(139990)=29억 원 규모 자기주식 처분 결정 ▲대한조선(439260)=오세아니아 지역 선주에 2597억 원 규모 원유운반선 2척 공급 계약 ▲한국수출포장(002200)공업=오산공장 화재 발생으로 골판지 원지 생산중단 ▲조비(001550)=농협경제지주에 1222억 원 규모 무기질 비료 구매납품 계약 ▲메리츠금융지주(138040)=7034억 원 규모 자기주식 소각 결정 ▲현대리바트(079430)=33억 원 규모 자기주식 소각 결정 ▲신세계인터내셔날(031430)=63억 원 규모 자기주식 소각 결정 ▲크래프톤(259960)=2000억 원 규모 자기주식 취득 및 소각 결정<코스닥 시장>▲케이지에이(455180)=탑머티리얼과 49억 원 규모 2차전지 전극공정 장비 공급 계약 ▲아이에스티이(212710)=SK하이닉스에 23억 원 규모의 풉 클린 장비 판매 계약 체결 ▲유니트론텍(142210)=18억 원 규모 자기주식 소각 결정 ▲부스타(008470)=7억 원 규모의 자기주식 처분 결정 ▲씨앤지하이테크(264660)=SK하이닉스에 19억 원 규모의 반도체 제조장비 판매 계약 ▲오비고(352910)=모트렉스 주식회사에 15억 원 규모 픽나우 서비스 글로벌 공급계약 체결 ▲고려신용정보(049720)=3억 원 규모의 자기주식 처분 및 상여 지급 결정', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004588428', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2026-02-09 16:42:24', 0, true, '2026-03-09 06:09:15.960665') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (843, '[공시pick] 한국수출포장공업, 화재 여파로 오산공장 생산중단', '◆…조세일보 DB한국수출포장공업이 오산공장 생산중단을 결정했다고 9일 공시했다.중단 분야는 골판지원지 생산이다. 지난 7일 발생한 화재로 건축물과 기계장치가 소실되며 생산 차질이 발생했다.생산재개 예정일은 미정이다. 회사는 사고 경위와 피해 규모를 조사 중이며 재산종합보험에 가입돼 있다고 밝혔다.', NULL, '조세일보', 'https://n.news.naver.com/mnews/article/123/0002377480', 'https://imgnews.pstatic.net/image/123/2026/02/09/0002377480_001_20260209150111945.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-09 15:01:11', 0, true, '2026-03-09 06:09:15.960665') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (844, '동성제약, ''회생 부결설'' 반박…"1600억 M&A로 정상화"', '[동성제약 CI (동성제약 블로그 캡처=연합뉴스)]경영 정상화 절차를 밟고 있는 동성제약이 최근 시장 일각에서 제기된 ''회생계획안 부결설''에 대해 근거 없는 허위 사실이라는 입장을 냈습니다.1천600억 원 규모의 인수 자금을 확보한 만큼, 오는 18일 관계인 집회에서 계획안 인가를 끌어내 조속히 거래 재개를 추진하겠다는 방침입니다.오늘(9일) 동성제약은 이날 홈페이지에 게시한 입장문에서 최대주주 브랜드리팩터링이 회생계획안 부결 의결 기반을 이미 확보했다고 주장한 데 대해 "실제 절차와 부합하지 않을 뿐 아니라 사실과도 다르다"고 일축했습니다.동성제약은 "악의적 선동 행위에 대해서는 모든 법적 수단을 포함해 강경하게 대응할 예정"이라고 전했습니다.동성제약 측은 현재 제출된 회생계획안에 ▲총 1천600억 원 규모의 인수계약 체결 ▲채권 100% 일시 변제 ▲기존 주주의 지분 감자 없는 M&A 구조 등 모든 이해관계자를 보호하는 내용이 담겨있다고 설명했습니다. 또, 관계인 집회에서 회생계획 가결을 위한 의결권 요건을 이미 확보한 상태라고 강조했습니다.이어 "회생 절차는 공동관리인이 법원의 감독 아래 안정적으로 진행하고 있다"며 "당일에도 이해관계인들의 합리적인 의결이 이뤄질 것으로 판단한다"고 덧붙였습니다.동성제약은 "주주 브랜드리팩터링은 회생절차 폐지 신청, 회생개시 취소 소송, 자체 회생계획 제출 등 지속적인 회생 절차 방해 행위를 이어가고 있으나, 이는 법원에서 모두 기각되거나 배제되어 정당성을 인정받지 못한 상황"이라고 설명했습니다.동성제약은 관계인 집회를 기점으로 지배구조 및 재무구조 개선을 마무리하고 상장 주식의 거래 재개를 본격화할 계획입니다.당신의 제보가 뉴스로 만들어집니다.SBS Biz는 여러분의 제보를 기다리고 있습니다.홈페이지 = https://url.kr/9pghjn', NULL, 'SBS Biz', 'https://n.news.naver.com/mnews/article/374/0000496683', 'https://imgnews.pstatic.net/image/374/2026/03/09/0000496683_001_20260309150820419.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 15:08:20', 0, true, '2026-03-09 06:09:23.994295') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (845, '동성제약, ''회생 부결설'' 반박…"1천600억 M&A로 정상화할 것"', '"법원 감독 아래 안정적 진행…회생안 가결 요건 충분"동성제약 CI[동성제약 블로그 캡처](서울=연합뉴스) 최현석 기자 = 경영 정상화 절차를 밟고 있는 동성제약이 최근 시장 일각에서 제기된 ''회생계획안 부결설''에 대해 근거 없는 허위 사실이라는 입장을 내놨다.1천600억 원 규모의 인수 자금을 확보한 만큼, 오는 18일 관계인 집회에서 계획안 인가를 끌어내 조속히 거래 재개를 추진하겠다는 방침이다.9일 제약·바이오업계에 따르면 동성제약은 이날 홈페이지에 게시한 입장문에서 최대주주 브랜드리팩터링이 회생계획안 부결 의결 기반을 이미 확보했다고 주장한 데 대해 "실제 절차와 부합하지 않을 뿐 아니라 사실과도 다르다"고 일축했다.동성제약은 "악의적 선동 행위에 대해서는 모든 법적 수단을 포함해 강경하게 대응할 예정"이라고 전했다.동성제약 측은 현재 제출된 회생계획안에 ▲ 총 1천600억 원 규모의 인수계약 체결 ▲ 채권 100% 일시 변제 ▲ 기존 주주의 지분 감자 없는 M&A 구조 등 모든 이해관계자를 보호하는 내용이 담겨있다고 설명했다. 또, 관계인 집회에서 회생계획 가결을 위한 의결권 요건을 이미 확보한 상태라고 강조했다.이어 "회생 절차는 공동관리인이 법원의 감독 아래 안정적으로 진행하고 있다"며 "당일에도 이해관계인들의 합리적인 의결이 이뤄질 것으로 판단한다"고 덧붙였다.동성제약은 "주주 브랜드리팩터링은 회생절차 폐지 신청, 회생개시 취소 소송, 자체 회생계획 제출 등 지속적인 회생 절차 방해 행위를 이어가고 있으나, 이는 법원에서 모두 기각되거나 배제되어 정당성을 인정받지 못한 상황"이라고 설명했다.동성제약은 관계인 집회를 기점으로 지배구조 및 재무구조 개선을 마무리하고 상장 주식의 거래 재개를 본격화할 계획이다.harrison@yna.co.kr', NULL, '연합뉴스', 'https://n.news.naver.com/mnews/article/001/0015947168', 'https://imgnews.pstatic.net/image/001/2026/03/09/PCM20181002000142990_P4_20260309144814527.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 14:47:29', 0, true, '2026-03-09 06:09:23.994295') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (846, '브랜드리팩터링 "M&A 부결 가능한 상거래채권 의결 기반 확보"', '동성제약의 최대주주 브랜드리팩터링은 상거래채권자 부문에서 인가전 M&A 부결을 이끌 수 있는 의결 기반을 이미 확보했으며, 현재 추가 상거래채권 확보도 이어가고 있다고 9일 밝혔다.브랜드리팩터링 측은 상거래채권자들이 대주주 측에 의결권을 위임하는 방식으로 부결 요건을 사실상 충족한 상태라고 설명했다. 이에 따라 오는 18일 관계인집회는 새로운 승부를 가르는 자리가 아니라, 이미 형성된 의결 구조를 확인하는 절차에 가깝다는 입장이다.브랜드리팩터링 관계자는 "최근 시장에서는 인가전 M&A가 기정사실처럼 받아들여지는 분위기도 감지되지만, 이는 실제 의결 구조와 다른 흐름"이라며 "회생절차의 핵심은 여론전이 아니라 실질 의결권 확보 여부고 현재 판세는 부결 쪽으로 기울어졌다"고 주장했다.최대주주 측이 부결 요건을 넘어 추가 상거래채권 확보에 나서는 배경도 분명하다. 관계인집회 직전까지 발생할 수 있는 혼선과 변수를 원천 차단하고, 의결 안정성을 더욱 높이기 위한 조치라는 설명이다. 단순히 법정 기준을 맞추는 수준이 아니라, 부결 구도를 보다 확실하게 굳히겠다는 전략이다.최대주주 측은 "주주들 사이에서도 인가전 M&A 구조가 현실화될 경우 감자, 신주 발행, 전환성 자금 유입 등에 따라 기존 지분가치 훼손 우려가 크다는 인식이 확산되고 있다"며 "기존 주주 손실 방지 필요성을 앞세워 반대 동의 확보에도 속도를 내고 있다"고 밝혔다.이어 "부결은 목표가 아니라 이미 확보한 결과"라며 "추가 상거래채권 확보는 승부를 뒤집기 위한 것이 아니라 흔들림을 원천 차단하기 위한 것"이라고 강조했다.', NULL, '아시아경제', 'https://n.news.naver.com/mnews/article/277/0005731312', 'https://imgnews.pstatic.net/image/277/2026/03/09/0005731312_001_20260309104220660.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 10:40:43', 0, true, '2026-03-09 06:09:23.994295') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (863, '[인사] 한독', '상무▲ 디지털 전략실 이동국이사▲ ETC 마케팅 유진희▲ ETC 병의원영업1실 임성재 (서울=연합뉴스)hanju@yna.co.kr', NULL, '연합뉴스', 'https://n.news.naver.com/mnews/article/001/0015936256', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_BIO', NULL, '2026-03-04 09:34:50', 0, true, '2026-03-09 06:10:18.699251') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (847, '[서울데이터랩]‘삼화페인트’ 29.96% 상한가 금일 증시 상승률 1위로 마감', '9일 오후 3시 35분 삼화페인트(000390)가 등락률 +29.96%로 상한가를 기록하며 상승률 1위로 마감했다. 삼화페인트는 장 중 10,065,342주가 거래되었으며 주가는 전 거래일 대비 2,190원 오른 9,500원에 마감했다.한편 삼화페인트의 PER은 31.77로 시장에서의 평가가 높을 수 있음을 나타내며, ROE는 4.87%로 수익성이 상대적으로 낮은 편이다.이어 상승률 2위 디아이(003160)는 주가가 25.46% 폭등하며 종가 37,200원에 상승 마감했다. 상승률 3위 아모레퍼시픽(090430)의 주가는 165,100원으로 20.25% 급등하며 강세를 보였다. 상승률 4위 비에이치(090460)는 17.00% 급등하며 19,890원에 마감했다. 상승률 5위 솔루스첨단소재(336370)는 15.87%의 상승세를 타고 8,980원에 마감했다.6위 에이블씨엔씨(078520)는 11,810원으로 15.56% 상승 마감했다. 7위 아모레퍼시픽홀딩스(002790)는 종가 34,950원으로 14.78% 상승 마감했다. 8위 한화솔루션(009830)은 종가 47,700원으로 13.57% 상승 마감했다. 9위 한일철강(002220)은 5,260원으로 13.12% 상승 마감했다. 10위 코오롱인더(120110)는 62,600원으로 13.00% 상승 마감했다.이밖에도 일진전기(103590) ▲12.72%, SK이터닉스(475150) ▲12.16%, 아모레퍼시픽우(090435) ▲12.02%, 산일전기(062040) ▲11.93%, 다우기술(023590) ▲11.89%, 코오롱ENP(138490) ▲11.89%, 아모레퍼시픽홀딩스3우C(00279K) ▲11.32%, 미래에셋증권(006800) ▲11.25%, KIWOOM 코스닥150선물레버리지(291630) ▲11.16%, HD현대일렉트릭(267260) ▲11.07% 등을 기록하며 금일 증시를 상승으로 마감했다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003616088', 'https://imgnews.pstatic.net/image/081/2026/02/09/0003616088_001_20260209155615825.png?type=w800', 'NEWS_ETC', NULL, '2026-02-09 15:56:15', 0, true, '2026-03-09 06:09:30.593862') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (848, '[서울데이터랩]금호건설우 29.97% 상한가 금일 증시 상승률 1위로 마감', '10일 오후 3시 35분 금호건설우(002995)가 등락률 +29.97%로 상승률 1위로 마감했다. 금호건설우는 장 중 50,290주가 거래되었으며 주가는 전 거래일 대비 3,540원 오른 15,350원에 마감했다.한편 금호건설우의 PER은 26.06으로 상대적으로 적정보다는 높은 평가를 받을 가능성을 시사한다.이어 상승률 2위 동양고속(084670)은 주가가 29.96% 폭등하며 종가 46,850원에 마감했다. 상승률 3위 태영건설우(009415)의 주가는 8,510원으로 29.92% 폭등하며 강세를 보였다. 상승률 4위 동부건설우(005965)는 21.81% 급등하며 19,600원에 마감했다. 상승률 5위 대성산업(128820)은 15.79%의 상승세를 타고 종가 5,940원에 마감했다.6위 세아베스틸지주(001430)는 종가 34,950원으로 14.03% 상승 마감했다. 7위 세기상사(002420)는 종가 6,240원으로 13.66% 상승 마감했다. 8위 에이프로젠(007460)은 종가 910원으로 13.04% 상승 마감했다. 9위 자화전자(033240)는 종가 22,100원으로 9.95% 상승 마감했다. 10위 일동제약(249420)은 종가 32,500원으로 9.43% 상승 마감했다.이밖에도 삼아알미늄(006110) ▲7.91%, 아이에스동서(010780) ▲7.46%, 한일철강(002220) ▲6.77%, 한화투자증권우(003535) ▲6.19%, 일동홀딩스(000230) ▲5.80%, 진흥기업우B(002785) ▲5.64%, CJ씨푸드1우(011155) ▲5.48%, 우진(105840) ▲5.25%, 대한유화(006650) ▲5.18%, 삼양바이오팜(0120G0) ▲4.89% 등을 기록하며 금일 증시를 상승으로 마감했다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003599736', 'https://imgnews.pstatic.net/image/081/2025/12/10/0003599736_001_20251210154914952.jpg?type=w800', 'NEWS_ETC', NULL, '2025-12-10 15:49:14', 0, true, '2026-03-09 06:09:30.593862') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (849, '“李정부 들어 100% 넘게 상승”…24개 주식 ‘대박’', '지난 6월~이달 24일 코스피서24개 종목 ‘100%’ 이상 수익률[이데일리 권혜미 기자] 코스피가 사상 처음으로 4000선을 돌파한 가운데, 지난 6월 이후 코스피 시장에서 24개 종목이 100% 이상 수익률을 기록한 것으로 나타났다.27일 뉴스1에 따르면 지난 6월부터 이달 24일까지 코스피 시장에서 100% 이상 수익률을 기록한 종목은 총 24개로 집계됐다. 같은 기간 코스피는 2697.67에서 3941.59로 46.11% 상승했는데, 지수 상승률보다 2배 이상 수익률을 기록한 것이다.사진=연합뉴스이 기간 SK하이닉스는 20만4500원에서 41만원으로 149.39% 상승했다. SK하이닉스를 자회사로 둔 SK스퀘어도 136.06% 올랐다. 이 외에도 ▲해성디에스(145.09%) ▲대덕전자(134.65%) ▲이수페타시스(143.75%) 등 반도체 관련주들이 높은 수익률을 기록했다.전력기기 업종 상승세도 가팔랐다. 효성중공업(207.43%)은 이 기간 61만9000원에서 190만3000원으로 3배 이상 급등했다. ▲HD현대일렉트릭(105.80%) ▲산일전기(115.97%) 등도 상승했다.한미 조선 협력 기대에 조선주도 곱절로 주가가 불어났다. HJ중공업(291.97%)은 6월 이후 7220원에서 2만8300원으로 3배가량 올랐다. ▲화인베스틸(160.16%) ▲HD현대마린엔진(129.51%) ▲세진중공업(103.24%) ▲한일철강(119.70%) 등도 크게 올랐다.이외에도 K뷰티 관련 종목인 ▲에이피알(110.32%) ▲제이준코스메틱(104.17%)도 가파르게 올랐다. 원전주인 두산에너빌리티(100.50%)와 이차전지(2차전지) 관련 종목인 ▲엘앤에프(133.57%) ▲LG화학(103.24%) 등도 높은 상승률을 기록했다.모회사 코오롱과 합병을 위해 자진 상장폐지를 추진 중인 ▲코오롱모빌리티그룹(1295.90%) ▲코오롱모빌리티그룹(329.37%)에도 투자자들이 몰리며 같은 기간 기록적인 수익률을 냈다.한편 이날 오전 10시 기준 코스피는 전 거래일 대비 89.87포인트(2.28%) 오른 4031.46를 찍었다. 이는 지난 6월 20일 3000선을 처음 돌파한 이후 넉 달 만의 기록이다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006148248', 'https://imgnews.pstatic.net/image/018/2025/10/27/0006148248_001_20251027110312468.jpg?type=w800', 'NEWS_ETC', NULL, '2025-10-27 11:03:12', 0, true, '2026-03-09 06:09:30.593862') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (850, '고려제강, 작년 영업익 412억…전년대비 57.8% 증가', '고려제강은 2025년 연결기준 매출 1조8093억원, 영업이익 412억원을 기록했다고 9일 공시했다. 전년 대비 각각 4.0%, 57.8% 증가한 수치다. 같은 기간 당기순이익은 85.9% 감소한 47억원으로 집계됐다.고려제강은 손익구조 변동에 대해 ''국내 및 해외법인의 판매단가 인상 등 매출증가로 인해 영업이익이 증가했으며 유형자산 손상차손 인식에 따라 순이익이 감소했다''고 설명했다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000079188', 'https://imgnews.pstatic.net/image/293/2026/02/09/0000079188_001_20260209172706873.png?type=w800', 'NEWS_ETC', NULL, '2026-02-09 17:27:06', 0, true, '2026-03-09 06:09:38.129476') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (851, '포스코 장인화 "철강업계, 고부가가치로 대체불가 선택지 돼야"', '13일 포스코센터서 ''2026년 철강업계 신년인사회'' 진행"K-스틸법 발판 삼아 올해 철강산업 도약하는 전환점으로"장인화 포스코그룹 회장 겸 한국철강협회 회장은 13일 "철강 산업의 지속 가능한 발전을 위해서는 우리 철강 제품이 고부가가치화를 통해 대체 불가한 선택지가 돼야 한다"고 강조했다.그는 이날 오후 서울 강남구 포스코센터에서 진행된 2026년 철강업계 신년인사회에서 "미국의 50% 관세 부과를 비롯해 주요국 보호주의 강화로 수출과 내수 모든 부문이 어려움을 겪었다"며 이같이 밝혔다.장인화 포스코그룹 회장 겸 한국철강협회 회장이 13일 서울 강남구 포스코센터에서 진행된 2026년 철강업계 신년인사회에 참석해 발언하고 있다. [사진=최란 기자]장 회장은 "지난해 12월 철강공업 육성법 이후 40년 만에 철강 산업 경쟁력 강화를 위한 특별법이 제정돼 철강 산업 지원 정책의 법적 기반이 마련됐다"며 "이 소중한 기회를 발판 삼아 올해를 철강 산업이 다시 한 번 도약하는 전환점으로 만들어야 한다"고 말했다.그는 "수요 침체와 글로벌 공급 과잉, 저가 수입재가 지속되는 상황에서 지속 가능한 발전을 위해서는 고부가가치 경쟁 우위를 강화해야 한다"며 "기술·개발·마케팅 전 분야의 협력을 통해 글로벌 경쟁력을 확보하고 이는 다시 국산 철강재 수요로 이어지는 선순환을 만들어야 한다"고 말했다.이어 "저탄소 전환을 위한 노력을 더 강화해야 한다"며 "탄소국경조정제도(CBAM)가 본격 시행되고 온실가스 배출권 거래제 강화가 예정된 현실 앞에서 저탄소 전환은 먼 미래를 위한 보호가 아닌 오늘의 생존 문제"라고 강조했다.그러면서 "올해 한국형 수소환원제철 실증 사업이 본격 추진되는 만큼 철강 산업의 탄소 중립 전환을 위한 장기 노력을 차질 없이 추진해야 한다"며 "단기적으로는 탄소 배출 감축을 위해 기존 생산 공정의 에너지 향상을 높이고 저탄소 원료 사용 확대를 위한 글로벌 공급망 강화에 적극 나서야 한다"고 밝혔다.마지막으로 "안전을 최우선 핵심 가치로 삼아 무사고 철강 산업을 정착시키도록 노력하자"며 "안전은 모든 경영활동의 기본이자 기업 생존을 담보하는 필수 조건이다. 형식적인 구호가 아니라 실질적인 무사고를 달성해야 할 것"이라고 강조했다.문신학 산업통상부 차관이 13일 서울 강남구 포스코센터에서 진행된 2026년 철강업계 신년인사회에 참석해 발언하고 있다. [사진=최란 기자]이날 문신학 산업통상부 차관은 격려사를 통해 "철강산업은 우리나라 6위 수출산업이자주력산업에 소재를 공급하는 경제안보의 핵심 축"이라며 "철강업계는 수출과 투자, 기술혁신을 통해 대한민국 산업과 지역경제의 든든한 버팀목이 되어주었다"고 말했다.그러면서 "정부는 앞으로도 현장의 목소리를 가장 먼저 듣고 여러분들과 함께 고민하겠다"고 덧붙였다.13일 서울 강남구 포스코센터 아트홀에서 열린 ''2026년 철강업계 신년인사회''에서 참석자들이 기념 촬영을 하고 있다. [사진=최란 기자]한편 이번 신년인사회에는 이희근 포스코 사장, 이보룡 현대제철 사장, 곽재선 KG스틸 회장,  이휘령 세아제강 부회장, 홍석표 고려제강 부회장, 조석희 TCC스틸 부회장, 이경호 한국철강협회 부회장을 비롯해 한국철강협회 회원사 대표와 철강산업 관련 주요 인사들이 참석했다.', NULL, '아이뉴스24', 'https://n.news.naver.com/mnews/article/031/0000996655', 'https://imgnews.pstatic.net/image/031/2026/01/14/0000996655_001_20260114082210241.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-14 08:22:10', 0, true, '2026-03-09 06:09:38.129476') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (852, '기업 공시 [3월 4일]', '<코스피 시장>▲스틱인베스트먼트(026890)=최대주주 The Miri Strategic Emerging Markets Fund LP로 변경, 지분율 24.97% ▲한국카본(017960)=자기주식 60만2114주 소각 결정 ▲노루페인트(090350)=1주당 400원 현금배당 결정, 시가배당률 4.6% ▲아세아제지(002310)=1주당 200원 현금배당 결정, 시가배당률 2.4% ▲SK증권(001510)=1주당 1000원 주식병합(기존 500원) ▲일진홀딩스(015860)=1주당 200원 현금배당 결정, 시가배당률 2.8% ▲일진전기(103590)=1주당 500원 현금배당 결정, 시가배당률 0.9%<코스닥 시장>▲나우로보틱스(459510)=한국후꼬꾸와 37억 원 규모 공급계약 체결, 최근 매출액 대비 30.68% ▲엔지켐생명과학(183490)=자기주식 42만 5327주 소각 ▲위즈코프(038620)=1주당 2500원 주식병합(기존 500원) ▲케이엠제약(225430)=1주당 500원 주식병합(기존 100원) ▲유니테크노(241690)=1주당 17원 현금배당 결정, 시가배당률 0.5%', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004595714', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2026-03-04 17:01:10', 0, true, '2026-03-09 06:09:45.926822') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (853, '“AI시대, 어쩔 수가 없다” 제지업계 ‘체질개선’ 사활', '디지털뉴스 전환…신문용지 생산급감택배 급증 포장용 골판지는 수직상승지종 구조 재편…업종 구도까지 바꿔제지업계가 디지털화 가속 등에 따른 종이 시장 변화에 발맞춰 체질 개선에 힘을 쏟고 있다. 사진은 한솔제지의 백판지 생산 공장 모습.   [한솔제지 제공]박찬욱 감독의 영화 ‘어쩔 수가 없다’는 제지공장에서 해고된 노동자(이병헌 분)의 이야기다.그가 맛있게 먹었던 ‘장어’는 사실 해고가 확정된 이들에게만 전달된 ‘마지막 선물’이었다. 이병헌은 영화에서 반복적으로 ‘어쩔 수가 없다’는 말을 한다. 이병헌이 일했던 ‘제지산업’은 디지털을 넘어 AI시대에 와있는 지금 영화속 주인공처럼 ‘어쩔 수가 없다’는 말을 반복할 수밖에 없을까.한국제지연합회 통계에 따르면 한국에서 생산된 종이류 가운데 지난 10여년 동안 가장 많이 줄어든 종이류는 신문용지로 2009년 146만톤에서 2024년 37만톤으로 줄었다. 디지털 뉴스 전환의 가장 직접적인 타격을 입은 제지산업계가 바로 신문용지 부문이다. 인쇄용지 타격도 심각하다. 2009년 297만톤이나 되던 인쇄용지 생산량은 2024년에는 226만톤으로, 71만톤가량 줄었다. 사무에 필요한 문서들 다수가 디지털화·전자화되면서 굳이 ‘인쇄용지’가 필요치 않은 상황이 수년 동안 누적된 결과다.이에 비해 택배용 포장박스에 사용되는 골판지 원지 생산량은 2009년 369만톤에서 2024년 557만톤으로, 188만톤이나 수직 상승했다. 온라인쇼핑과 택배물류가 확장되면서 골판지 원지사업 분야를 빠르게 성장시켰다. 위생용지 부문 역시 성장세가 가팔랐다. 2009년 44만톤 규모이던 위생용지 생산량은 2024년에는 52만톤으로, 8만톤가량이 늘었다. 국내 생산 제지류 총 생산량은 지난 2009년 1048만톤이었고, 2024년에는 1081만톤이다. 생산된 종이가 어떤 종류냐는 달라졌지만 전체 종이 생산량은 소폭이나마 늘어난 셈이다.이 같은 지종 구조 변화는 기업 실적에도 그대로 반영된다. 생활소비재(위생용품) 비중이 큰 깨끗한나라는 2025년 연결 기준 매출 5082억원(전년 대비 5.4% 감소), 영업손실 226억원으로 적자가 확대됐다. 당기순손실은 472억원으로, 손실폭이 커졌다. 과자 박스 등 소형 포장에 많이 사용되는 백판지의 시황 악화가 실적에 부담으로 작용했다는 평가다.반면 인쇄·산업용지 비중이 큰 한솔제지는 2025년 연결기준 매출 2조2900억원, 영업이익 499억원을 기록했다. 영업이익은 전년 대비 127.1% 증가했고, 당기순이익은 38억원으로 흑자 전환했다. 회사는 환율 상승과 원부재료 가격 및 해상운임 하락 등을 손익 개선 요인으로 들었다.골판지업은 물류 수요를 타고 매출 방어는 했지만 원가·시황에 따라 희비가 갈린다. 대림제지는 2025년 연결기준 매출 1688억원(전년 대비 1.5% 증가)에도 영업이익 52억8000만원(46.3% 감소), 당기순이익 66억원(49.9% 감소)으로 수익성이 둔화됐다. 한창제지도 2025년 기준 매출 2669억원(9.2% 감소), 영업손실 51억원으로 적자 전환했고, 당기순손실 131억원을 기록했다.아세아제지, 신대양제지 등 골판지 중심 기업들은 물류 수요와 맞물려 비교적 안정적인 흐름을 이어가고 있다. 다만 골판지업황 역시 경기 변동과 증설경쟁 영향에서 완전히 자유롭지는 않다. 내수 물동량 둔화나 해외 공급 확대가 동시에 나타날 경우 수익성 변동성이 커질 수 있다는 지적이 나온다.고용과 설비 측면에서도 변화는 제한적이다. 대형 제지공장은 여전히 막대한 투자와 인력을 필요로 하는 장치산업이다. 자동화가 확대됐지만 공장 자체가 사라지는 속도는 느리다. 대신 생산품목 전환과 설비구조 조정이 점진적으로 진행되고 있다. 인쇄용지 라인을 줄이고 포장·친환경 소재 중심으로 재편하는 흐름이 대표적이다. 산업의 소멸이 아니라 체질 변화에 가깝다는 평가가 나오는 이유다. 홍석희 기자', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002602151', 'https://imgnews.pstatic.net/image/016/2026/02/19/0002602151_001_20260219112309147.png?type=w800', 'NEWS_ETC', NULL, '2026-02-19 11:23:09', 0, true, '2026-03-09 06:09:45.926822') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (855, '한진, 택배기사 위해 ''찾아가는 맞춤형 건강검진 서비스'' 실시', '한진은 택배 종사자를 위해 직접 현장으로 찾아가는 ''맞춤형 건강검진 서비스''를 시행한다고 4일 밝혔다.한진은 택배 종사자를 위해 직접 현장으로 찾아가는 ''맞춤형 건강검진 서비스''를 시행한다고 4일 밝혔다.한진은 지난 2월 말부터 택배기사, 집배점장, 간선기사 등 약 1만여 명의 택배 종사자를 대상으로 건강검진에 돌입했다. 이번 서비스는 근로자 건강권을 보호하고 질병을 사전에 예방하여 안전한 배송 환경을 구축하기 위해 기획됐다.건강검진은 평일 낮 시간대 병원 방문이 어려운 택배기사들의 여건을 고려해, 전문 의료진이 탑승한 검진 버스가 전국 180여 개 터미널을 직접 찾아가는 방식으로 운영한다. 세부 일정은 지난달 말 서울 및 수도권을 시작으로 3월에는 천안·청주 등 충청권, 4~5월에는 대구·부산을 포함한 영남권과 광주·목포 등 호남권을 거쳐, 6월 제주도 지역을 마지막으로 전국의 모든 종사자를 찾아갈 예정이다.검진 항목은 택배 종사자들에게 발생하기 쉬운 질환을 중심으로 구성했다. 뇌심혈관계 질환, 심전도, 혈액 검사, 특수화학 검사, 스트레스 진단, 고혈압, 간암 검사 등 총 60여 개의 정밀 항목으로 종사자 건강 상태를 면밀히 체크한다.정다은 기자 dandan@etnews.com', NULL, '전자신문', 'https://n.news.naver.com/mnews/article/030/0003404695', 'https://imgnews.pstatic.net/image/030/2026/03/05/0003404695_001_20260305144216246.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-05 14:42:16', 0, true, '2026-03-09 06:09:53.849594') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (856, '넥센타이어, 기아 ''셀토스'' 신차용 타이어 공급…"SUV 라인업 강화"', '''엔프리즈 S'', ''엔페라 AU7'' 장착신차용 포트폴리오 라인업 확대넥센타이어가 장착된 기아 디 올뉴 셀토스. 넥센타이어 제공.[파이낸셜뉴스] 넥센타이어는 기아의 스포츠유틸리티차량(SUV) ''디 올 뉴 셀토스''에 신차용(OE) 타이어를 공급한다고 9일 밝혔다.디 올 뉴 셀토스는 이전 모델 대비 차체 크기가 확대됐다.기존 가솔린 모델에 더해 하이브리드 모델도 새롭게 추가되면서 차급 구성과 사양 선택 폭도 넓어졌다.휠 크기 구성도 이러한 변화를 반영해 기존 16인치와 18인치에 더해 19인치 사양이 추가됐다. 넥센타이어는 차체 크기와 하중이 큰 SUV 특성은 물론 하이브리드 모델의 특성까지 고려해 휠 크기별 주행 특성과 요구 성능에 최적화된 타이어 제품을 공급한다.16인치와 18인치 휠 사양에는 ''엔프리즈 S(N''PRIZ S)''가 장착된다. 이 제품은 전기차부터 하이브리드와 내연기관까지 모두 장착 가능한 고효율 사계절용 타이어다. 뛰어난 마모 성능과 함께 불규칙한 블록 간격 설계를 통해 정숙하고 편안한 승차감을 제공한다. 기존 제품 대비 눈길 성능을 강화해 한국의 뚜렷한 사계절에도 최적화된 주행 안전성을 제공하는 것이 특징이다.차체 확대와 함께 고인치 휠 수요가 반영된 19인치에는 ''엔페라 AU7(N''FERA AU7)''이 적용된다. 이 제품은 고인치 휠에 요구되는 고속 주행 안정성과 편안한 승차감을 제공하는 프리미엄 타이어다. 고강도 내구 소재를 적용한 구조 설계와 최적화된 패턴 디자인을 통해 안정적인 주행 성능을 확보했다. 여기에 저소음 흡음재 시스템(NRS)을 적용해 타이어 내부에 흡음 패드를 부착함으로써 주행 시 발생하는 공명음을 효과적으로 줄였다.이번 셀토스 공급을 통해 넥센타이어는 SUV 차종을 중심으로 고인치 사양 대응 역량을 한층 더 확대했다. 넥센타이어는 올해 KGM 무쏘를 비롯해 지난해 현대 팰리세이드, 전기 SUV 일렉시오, 기아 EV5, 픽업트럭 타스만, 폭스바겐 산하 스코다의 SUV 카록(KAROQ) 등 다양한 SUV 및 픽업트럭 차종에 신규 공급을 지속 확대하고 있다.넥센타이어 관계자는 "글로벌 시장에서 SUV 선호가 지속되는 가운데 고인치 휠 사양을 적용한 OE 타이어 공급도 함께 증가하고 있다"며 "앞으로도 글로벌 완성차 브랜드와의 지속적인 협력을 강화하며 검증된 기술력과 제품 경쟁력을 바탕으로 SUV 및 고인치 제품 공급을 지속 확대할 것"이라고 말했다.', NULL, '파이낸셜뉴스', 'https://n.news.naver.com/mnews/article/014/0005488115', 'https://imgnews.pstatic.net/image/014/2026/03/09/0005488115_001_20260309101415621.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-03-09 10:14:15', 0, true, '2026-03-09 06:09:59.155451') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (857, '넥센타이어, 신형 BMW iX3에 신차용 타이어 공급', '넥센타이어 고성능 퍼포먼스 타이어 ''엔페라 스포츠''./사진제공=넥센타이어넥센타이어가 신형 BMW iX3에 신차용 타이어로 ''엔페라 스포츠''를 공급한다고 3일 밝혔다.엔페라 스포츠는 고성능 차량에 맞춰 설계된 고성능 퍼포먼스 타이어로 고속 주행 시에도 우수한 핸들링과 제동 성능을 제공한다. 우선 고강도 내장재를 통해 접지 압력과 하중을 고르게 분산하고 최적화된 블록 디자인으로 안정적인 제동력을 발휘한다. 디지털 시뮬레이션으로 설계된 배수 홈이 물을 효과적으로 배출시켜 젖은 노면에서도 안정적인 성능을 확보해준다.넥센타이어는 프리미엄 브랜드에 신차용 타이어를 공급 제품의 품질과 기술력을 입증하고 있다. 2012년 최초로 해외 완성차 제조사에 신차용 타이어 공급을 시작한 이후 공급을 지속적으로 확대해 단기간에 BMW 그룹과 같은 프리미엄 브랜드를 비롯한 유수의 글로벌 완성차 제조사의 타이어 공급사로 자리매김했다.이러한 성과는 넥센타이어의 지속적인 연구개발 투자로 최첨단 기술력을 갖춘 우수한 제품을 개발해온 결과다. 넥센타이어는 신제품 개발부터 완제품 검사까지 다양한 영역에서 인공지능(AI)과 가상현실(VR) 기술을 적용하고 있다. 최근에는 국내 업계 최초로 ''하이 다이나믹 드라이빙 시뮬레이터''를 도입해 가상 타이어 개발을 가속화하고 있다. 아울러 AI 기반 제품 검사 자동화 시스템을 도입해 타이어 생산 과정에서 제품 검사의 정밀도를 향상해 품질 경쟁력을 높이고 있다.넥센타이어 관계자는 "지속적인 연구개발과 최신 기술을 적용한 프리미엄 제품 개발·생산을 통해 글로벌 완성차 제조사와 협력을 강화할 것"이라고 말했다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005324657', 'https://imgnews.pstatic.net/image/008/2026/03/03/0005324657_001_20260303161611570.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-03-03 16:15:50', 0, true, '2026-03-09 06:09:59.155451') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (858, '넥센타이어, 세대 공감 오피스 웹드라마 ''넥생'' 선봬', '넥센타이어는 회사 생활을 소재로 한 웹드라마 ''넥생''을 선보이며 디지털 커뮤니케이션을 확대한다고 27일 밝혔다.넥생은 ''넥센타이어 라이프''의 줄임말이다. 동시에 ''새로운 삶(NEXT LIFE)''이라는 중의적 의미를 담고 있다.웹드라마 넥생에는 배우 고창석과 김규남이 출연한다.갑작스러운 조직 개편으로 회사를 떠나게 된 중년과 갓 대학을 졸업한 취업 준비생이 넥센타이어 인턴으로 새로운 삶에 도전하는 이야기를 그렸다.촬영은 서울 마곡에 있는 넥센타이어 중앙연구소 ''더넥센유니버시티''에서 진행됐다.넥센타이어는 주력 상품인 ''엔페라 슈프림'', 렌탈 서비스 ''넥스트레벨'', 내고성능 제품에 부여되는 전용 마크 ''EV 루트'' 등을 드라마에 녹였다.총 5부작으로 3월 13일부터 5월 8일까지 격주 금요일마다 한 편씩 공개된다. 넥센타이어 공식 유튜브 채널에서 볼 수 있다.넥센타이어 관계자는 "앞으로도 브랜드 경험을 확장하며 고객과의 소통을 지속 강화해 나갈 것"이라고 말했다.', NULL, '한국경제TV', 'https://n.news.naver.com/mnews/article/215/0001243271', 'https://imgnews.pstatic.net/image/215/2026/02/27/A202602270272_1_20260227094807151.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-02-27 09:47:55', 0, true, '2026-03-09 06:09:59.155451') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (859, '100달러 넘은 유가에 코스피 투매나왔지만…정유·에너지주는 웃었다 [매경 자이앤트]', '중앙에너비스 주가 추이[사진 출처=매경 자이앤트 텔레그램]중동지역 리스크가 고조되면서 코스피가 휘청이고 있다.그 가운데 유가 급등으로 수혜를 볼 것으로 예상되는 국내 정유·에너지주(株)가 급등세를 보인다.9일 오후 12시38분 기준 중앙에너비스는 전 거래일 보다 5500원(18.87%) 오른 3만4650원에 거래되고 있다.중앙에너비스는 중동지역 리스크가 불거진 이후인 지난 5일 장중 3만8000원까지 상승하면서 52주 신고가를 기록했다.매경 자이앤트 텔레그램이 집계한 결과 중앙에너비스 외 남해화학(29.9%), 대성에너지(27%), 지에스이(20.7%), 극동유화(18.1%), SH에너지화학(16.9%), 흥구석유(14.9%) 등의 정유·에너지 관련 종목들이 상승세를 보였다.9일 오후 주도 섹터 현황[사진 출처=매경 자이앤트 텔레그램]국제유가는 심리적 저항선인 배럴당 100달러를 넘어섰다.이날 오전 7시26분 기준 미국 뉴욕상품거래소에서 거래되는 4월 인도분 서부 텍사스산 원유(WTI) 선물 가격은 전 거래일 보다 14.85% 오른 배럴당 107.54달러를 기록했다.한때 111.24달러까지 치솟았는데, WTI 가격이 배럴당 100달러를 넘어선 건 2022년 7월 이후 처음이다.윤재성 하나증권 연구원은 “러시아-우크라이나 전쟁 보다 에너지 시장에 더 큰 충격을 주고 있고 특히 정제마진, 에틸렌 상승 속도가 빠르다”며 “향후 전쟁이 2주 이상 이어질 경우 글로벌 공장의 점진적인 가동 중단이 이어질 것으로 보이고 에너지 가격 급등을 헷지할 필요가 있다”고 했다.그러면서 윤 연구원은 최선호주로 SK이노베이션, S-Oil, 한화솔루션, 유니드 등을 꼽았다.☞더 많은 투자 정보가 궁금하다면?매경 자이앤트 텔레그램으로 입장하세요! 매경 자이앤트 텔레그램 서비스는 전자공시를 포함한 다양한 시장 데이터를 AI 기반으로 분석하는 데이터 플랫폼AWAKE – 마켓 브리핑에서 정보를 받아 운영됩니다.매경 자이언트 텔레그램 채널에서는AI가 최근 7년간의 공시를 분석해 주가에 영향을 미칠 가능성이 높은 공시를 선별하고, 이용자가 한눈에 확인할 수 있도록 핵심 시장 정보만을실시간으로제공하고 있으니 꼭 확인해 보시기 바랍니다.', NULL, '매일경제', 'https://n.news.naver.com/mnews/article/009/0005647240', 'https://imgnews.pstatic.net/image/009/2026/03/09/0005647240_001_20260309133206001.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 13:32:06', 0, true, '2026-03-09 06:10:07.845355') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (860, '‘상법 개정’ 무기 쥔 행동주의 펀드, 이사회 개편 압박 [시그널]', '■주주충실의무 확대따라 적극 제안팰리서, LG화학에 선임독립이사얼라인, 코웨이 등 감사위원 추천이 기사는 2026년 3월 8일 17:45자본시장 나침반  ''시그널(Signal)''에 표출됐습니다.서울 시내 빌딩숲. 연합뉴스최근 수년간 이어진 행동주의 펀드의 공세는 올해 정기 주주총회에서도 활발할 것으로 전망된다. 단순히 배당 증액 등 주주 환원을 압박했던 과거와 달리 정관 변경부터 이사 후보자 추천을 통한 이사회 진입까지 기업 맞춤형 전략으로 진화하는 모습이다. 특히 주주명부 열람부터 경영진 대상 공개서한 발송, 주주 제안권 행사까지 다양한 소수주주권 행사가 예상됨에 따라 기업들은 주주와의 소통으로 신뢰를 확보해야 할 필요성이 높아졌다.8일 투자은행(IB) 업계에 따르면LG화학(051910)을 상대로 주주 제안을 한 영국계 행동주의 펀드 팰리서캐피털은 법무법인 넥서스와 비사이드코리아를 선임하고 주주 대상 의결권 대리 행사 권유에 본격적으로 착수했다. 상법 개정으로 사외이사의 명칭이 독립이사로 변경되며 실질적인 독립성 강화가 화두로 떠오른 가운데 팰리서는 선임독립이사제도 도입과 자회사인LG에너지솔루션(373220)지분 유동화 등을 안건으로 상정하며 압박 수위를 높였다.국내 행동주의 펀드 얼라인파트너스는코웨이(021240)·DB손해보험(005830)·가비아(079940)·솔루엠(248070)·에이플러스에셋(244920)·덴티움(145720)등 무려 6개 상장사에 주주 제안을 던졌다. 코웨이와 DB손보에는 각각 2인의 분리 선출 감사위원 후보를 추천하며 이사회의 근본적인 개편을 꾀하고 있다. 특히 코웨이에는 감사위원회 전원을 독립이사로 구성하고 이사회 의장까지 독립이사에 맡기라는 파격적인 요구도 내걸었다. 아울러 경영진 보상 체계 공개를 거부한 가비아를 상대로 법원에 가처분을 신청하는 등 법적 절차도 병행 중이다. 주주 충실 의무 확대에 따라 이사들의 책임 범위가 넓어진 점을 적극적으로 활용하고 있다는 분석이 나온다.다른 주요 행동주의 펀드들도 자사주 의무 소각이나 독립이사 도입 등 강화된 상법 기조에 맞춰 공세를 다변화하고 있다. 트러스톤자산운용은KCC(002380)에 유휴 자산인삼성물산(028260)지분 유동화와 함께 자사주 전량 소각을 촉구했다. 또 태광산업에는 자진 상장폐지와 선임독립이사제 도입까지 요구하며 거버넌스 개편을 압박했다. 라이프자산운용은BNK금융지주(138930)에 이사진에 대한 체계적인 보상 체계 도입을 제안했다. 회사가 보유 중인 자기주식을 이사에 대한 성과 보상으로 지급해 경영진과 주주의 이해관계를 일치시키도록 하자는 것이다.이처럼 올해 주총 시즌을 앞두고 달라진 점으로 행동주의 펀드들의 요구 사항이 다변화하고 있다는 것이 꼽힌다. 특히 이사회 독립성 확보와 감사위원 선임 방식 개선, 자산 유동화 같은 맞춤형 전략으로 옮겨가고 있다는 평가가 나온다. 한 행동주의 펀드 대표는 “주주 충실 의무와 독립이사제, 감사위원 분리 선출 등 법적 장치가 강화되면서 이전보다 훨씬 치밀한 주주 제안이 올 정기 주총 시즌을 앞두고 나타나고 있다”고 평가했다.', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004596952', 'https://imgnews.pstatic.net/image/011/2026/03/08/0004596952_001_20260308233309187.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-03-08 20:22:19', 0, true, '2026-03-09 06:10:12.872550') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (861, '막 오른 3월 주총…행동주의 공세·거버넌스 개편 시험대', '주주환원 논쟁 확산…기업가치 재평가 분수령코리아 디스카운트 해소 기대…리레이팅 분기점사진은 삼성전자 제55기 정기 주주총회에서 주주와의 대화 시간이 진행되고 있는 모습. [사진 연합뉴스][이코노미스트 송현주 기자] 본격적인 3월 정기 주주총회 시즌을 앞두고 자본시장의 긴장감이 빠르게 높아지고 있다. 행동주의 펀드들이 공개서한과 주주제안을 잇달아 내놓으며 전면전에 나선 가운데, 기업들도 선제적 대응에 나서는 분위기다. 배당 규모 같은 단기 이슈를 넘어 이사회 구성과 경영진 보상 체계, 자본 배분 전략 등 기업 운영 전반이 논의 대상에 오르면서 주총의 성격 자체가 달라지고 있다는 분석이다.주총 일정만 놓고 봐도 올해는 예년보다 열기가 뜨겁다. 한국상장회사협의회에 따르면 2월 27일 기준 정기 주총 일정을 확정한 상장사는 593곳이다. 이 가운데 436곳, 약 73%가 3월 중 주총을 개최한다. 특히 상당수 기업이 24일·26일·31일로 일정을 잡으면서 이달 말 특정 날짜에 주총이 한꺼번에 몰릴 전망이다. 기관투자가와 의결권 자문사, 소액주주들의 대응이 물리적으로 겹칠 수밖에 없는 구조다. 안건별 표 대결이 현실화될 경우 일정 집중 자체가 변수로 작용할 가능성도 제기된다.행동주의 자본의 움직임은 이미 본격화됐다. 영국계 헤지펀드 팰리서캐피탈은 LG화학에 기업가치 제고 계획의 구체화를 요구하는 주주제안을 제출했다. 단순히 배당을 늘리라는 수준이 아니다. 순자산가치(NAV) 할인율을 공개하고 이를 핵심성과지표(KPI)에 반영하라는 요구, 자기자본이익률(ROE) 중심의 성과 관리, 경영진에 대한 주식 연계 보상 도입 등이 포함됐다. LG에너지솔루션 지분 유동화 확대와 자사주 매입·소각, 독립이사 선임 요구까지 더해지면서 자본 효율성과 거버넌스를 동시에 압박하는 구조다.국내 행동주의 펀드 역시 적극적이다. 얼라인파트너스자산운용은 DB손해보험에 요구자본이익률(ROR)을 중심으로 한 경영 전략과 중기 자본관리·주주환원 정책 정교화를 주문했다. 에이플러스에셋, 코웨이에는 정관 변경과 독립이사 선임을 제안했고, 덴티움·가비아·솔루엠 등에도 거버넌스 개선 요구를 이어가고 있다. 트러스톤자산운용은 KCC에 삼성물산 지분 유동화와 자사주 소각을 요구하며 구체적인 답변 시한까지 제시했다. 태광산업에는 소수주주 지분 전량 매입과 상장폐지, 선임독립이사 제도 도입을 촉구했다. 라이프자산운용은 BNK금융지주에 이사회 구성원의 주식 보상 체계를 제안하며 경영진과 주주의 이해 일치를 강조했다.상법 개정 여파…주총마다 힘겨루기눈에 띄는 점은 행동주의 요구의 성격이 이전과 달라졌다는 것이다. 과거에는 배당 확대나 자사주 매입·소각 등 주주환원 규모를 늘리라는 단선적 요구가 중심이었다면 올해는 기업 경영 체계 전반을 겨냥한 구조적 개선 요구가 부각되고 있다.순자산가치(NAV) 할인율을 공개하고 이를 경영 성과지표에 반영하라는 주문이나, 자기자본이익률(ROE) 중심으로 핵심성과지표(KPI)를 재설계하라는 요구는 단순한 현금 배분 차원을 넘어선 것으로 보인다. 이는 기업이 왜 저평가를 받고 있는지 원인을 진단하고, 이를 해소하기 위한 내부 관리 체계를 재정비하라는 의미에 가깝다는 게 업계 안팎의 관측이다.아울러 이사회 구성의 독립성 강화, 감사위원 선임 방식 개선, 경영진 보상에 대한 주식 연계 체계 도입 등도 주요 요구 사항으로 떠올랐다. 배당 확대를 넘어 기업 운영의 틀과 의사결정 구조까지 점검 대상으로 삼고 있다는 점에서 행동주의 공세가 한층 정교해지고 있다는 평가가 나온다.이 같은 흐름은 증권업계에도 부담으로 작용할 가능성이 크다. 대규모 자기자본을 기반으로 자금 운용과 신사업 확장을 병행하는 증권사의 특성상 자본 효율성과 내부 통제 체계에 대한 검증 요구가 더 직접적으로 제기될 수 있기 때문이다. 상법 개정과 스튜어드십코드 내실화 이후 기관투자가의 의결권 행사 기준이 강화되면서, 경영권 방어 전략이 과거처럼 단순하게 작동하기 어려운 환경도 조성되고 있다.법무법인 율촌 기업지배구조센터는 올해 주총을 두고 “기업지배구조 개선과 기업가치 제고가 자본시장의 중심 의제로 자리 잡으면서 행동주의 공세가 한층 조직화되고 있다”며 “형식적 대응과 실질적 개선 사이의 차이가 시장 평가로 직결될 수 있다”고 진단했다.현장 긴장감도 커지고 있다. 이남우 한국기업거버넌스포럼 회장은 “지배주주 측이 개정 상법 발효 이전에 유리한 고지를 선점하기 위해 선제적으로 의안을 발의할 가능성이 크다”며 “이에 맞서 일반주주와 기관투자가가 결집할 경우 곳곳에서 표 대결이 벌어질 수 있다. 올해는 어느 때보다 뜨거운 주총이 될 것”이라고 내다봤다.시장에서는 잇따른 상법 개정이 ‘코리아 디스카운트(한국 증시 저평가)’ 해소로 이어질 수 있을지에 주목한다. 제도 변화가 이벤트로 끝날지, 기업의 체질 개선과 구조적 재평가로 연결될지가 관건으로 해석하고 있다.이경민 대신증권 연구원은 “세 차례의 상법 개정은 한국 자본시장이 구조적 리레이팅 국면으로 진입하는 계기가 됐다”며 “이제 관건은 기업이 3월 주총과 이후 실적 발표에서 얼마나 실질적 변화를 보여주느냐다”고 분석했다. 이어 “주주환원이 본업에서 창출된 현금으로 지속 가능하게 이뤄지는지, 성장 투자와 환원 간 균형을 유지하고 있는지가 향후 주가 상승의 핵심 동력이 될 것”이라고 강조했다.', NULL, '이코노미스트', 'https://n.news.naver.com/mnews/article/243/0000094075', 'https://imgnews.pstatic.net/image/243/2026/03/07/0000094075_001_20260307080214949.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-03-07 08:02:14', 0, true, '2026-03-09 06:10:12.872550') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (865, '[서울데이터랩]극동유화 30.00% 상한가 금일 증시 상승률 1위로 마감', '3일 오후 3시 35분 극동유화(014530)가 등락률 30.00%로 상승률 1위로 마감했다. 극동유화는 장 중 943만 5078주가 거래됐으며 주가는 전 거래일 대비 1065원 오른 4615원에 마감했다.한편 극동유화의 PER은 64.1로 비교적 높은 수치로 평가되며, ROE는 4.4%로 수익성은 평균 수준으로 볼 수 있다.이어 상승률 2위 세기상사(002420)는 주가가 29.98% 폭등하며 종가 6460원에 상승 마감했다. 상승률 3위 대성에너지(117580)의 주가는 1만 450원으로 29.98% 폭등하며 두드러졌다. 상승률 4위 대한해운(005880)은 29.95% 상승하며 2820원에 마감했다. 상승률 5위 STX그린로지스(465770)는 29.90%의 상승세를 타고 종가 7690원에 마감했다.6위 LIG넥스원(079550)은 종가 66만 1000원으로 29.86% 상승 마감했다. 7위 한국ANKOR유전(152550)은 종가 279원으로 29.77% 상승 마감했다. 8위 한국석유(004090)는 종가 2만 1150원으로 29.75% 상승 마감했다. 9위 흥아해운(003280)은 종가 2330원으로 29.73% 상승 마감했다. 10위 한화시스템(272210)은 종가 14만 6700원으로 29.14% 상승 마감했다.이 밖에도 대성산업(128820) 29.10%, SH에너지화학(002360) 29.03%, S-Oil(010950) 28.45%, 한화에어로스페이스(012450) 19.83% 등을 기록하며 이날 증시를 상승으로 마감했다.전문가는 극동유화의 폭등에 대해 “극동유화는 석유화학 분야에서 중요한 위치를 차지하고 있으며, 최근의 주가 상승은 업계 내 긍정적인 전망과 맞물려 투자자들의 관심을 끌었다”고 분석했다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003622426', 'https://imgnews.pstatic.net/image/081/2026/03/03/0003622426_001_20260303160213566.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-03 16:02:13', 0, true, '2026-03-09 06:10:30.402210') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (866, '[서울데이터랩]‘대성에너지’ 29.85% 폭등…실시간 상승률 1위', '3일 오전 9시 30분 대성에너지(117580)가 등락률 29.9%로 상승률 1위를 차지했다. 대성에너지는 개장 직후 5분 동안 134만 5063주가 거래됐으며 주가는 전 거래일 대비 2400원 오른 1만 440원이다.한편 대성에너지의 주가수익비율(PER)은 10.6으로 상대적으로 저평가됐을 가능성을 시사하며, 자기자본이익률(ROE)은 5.3%로 수익성이 낮다고 보기에는 무리가 있는 준수한 수준이나 고성장 기업과 비교했을 때는 보통 수준일 수 있다.이어 상승률 2위 한국ANKOR유전(152550)은 현재가 279원으로 주가가 29.8% 폭등하고 있다. 상승률 3위 한국석유(004090)는 현재 2만 1150원으로 29.8% 폭등하며 강세를 보이고 있다. 상승률 4위 흥아해운(003280)은 28.1% 상승하며 2300원에 거래되고 있다. 상승률 5위 극동유화(014530)는 25.2%의 상승세를 타고 4445원에 거래되고 있다.6위 SH에너지화학(002360)은 현재가 463원으로 24.5% 상승 중이다. 7위 LIG넥스원(079550)은 현재가 63만 3000원으로 24.4% 상승 중이다. 8위 세기상사(002420)는 현재가 6180원으로 24.4% 상승 중이다. 9위 STX그린로지스(465770)는 현재가 7300원으로 23.3% 상승 중이다. 10위 미창석유(003650)는 현재가 16만 6000원으로 23.1% 상승 중이다.이 밖에도 에쓰오일(010950) 22.6%, 한화시스템(272210) 19.8%, 일진하이솔루스(271940) 19.0%, 퍼스텍(010820) 16.2% 등을 기록하며 시장에서 활발히 거래되고 있다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003622252', 'https://imgnews.pstatic.net/image/081/2026/03/03/0003622252_001_20260303095311809.png?type=w800', 'NEWS_ETC', NULL, '2026-03-03 09:51:10', 0, true, '2026-03-09 06:10:30.402210') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (867, '[서울데이터랩]‘태영건설우’ 29.97% 상한가…실시간 상승률 1위', '16일 오전 9시 10분 태영건설우(009415)가 등락률 +29.97%로 상한가를 기록하며 상승률 1위를 차지했다. 태영건설우는 개장 직후 5분간 15만 4744주가 거래되었으며 주가는 공모가 대비 2580원 오른 1만 1190원이다.한편 태영건설우의 PER은 -49.96으로 상대적으로 저평가를 받고 있을 가능성을 시사한다.이어 상승률 2위 동양고속(084670)은 현재가 10만 2400원으로 주가가 29.46% 폭등하고 있다. 상승률 3위 형지엘리트(093240)는 현재 1375원으로 15.26% 급등하며 활발한 거래를 보인다. 상승률 4위 와이투솔루션(011690)은 11.17% 급등하며 4330원에 거래되고 있다. 상승률 5위 동부건설우(005965)는 10.25%의 상승세를 타고 2만 2050원에 거래되고 있다.6위 티엠씨(217590)는 현재가 1만 8430원으로 9.90% 상승 중이다. 7위 금호건설우(002995)는 현재가 2만 5100원으로 9.85% 상승 중이다. 8위 티웨이홀딩스(004870)는 현재가 555원으로 7.98% 상승 중이다. 9위 에이블씨엔씨(078520)는 현재가 1만 1850원으로 5.80% 상승 중이다. 10위 케이씨(029460)는 현재가 2만 5000원으로 4.82% 상승 중이다.이밖에도 LS(006260) ▲4.49%, 삼성에피스홀딩스(0126Z0) ▲4.09%, 세기상사(002420) ▲4.08%, 미래아이앤지(007120) ▲4.02% 등을 기록하며 시장에서 활발히 거래되고 있다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003601231', 'https://imgnews.pstatic.net/image/081/2025/12/16/0003601231_001_20251216092815882.jpg?type=w800', 'NEWS_ETC', NULL, '2025-12-16 09:28:15', 0, true, '2026-03-09 06:10:30.402210') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (868, '''롯데렌탈 인수전'' 아직 안 끝났다?…이의신청 변수 촉각[마켓인]', '공정위, SK렌터카 보유한 어피니티 롯데렌탈 인수 불허어피니티, 법무법인 세종 새로 선임해 향후 대응 모색설 연휴 지나면 이의신청 여부 윤곽 드러날 것으로 관측이 기사는 2026년02월15일 08시48분에마켓인 프리미엄 콘텐츠로 선공개 되었습니다.[이데일리 마켓in 송승현 기자] 롯데렌탈 매각이 공정거래위원회(공정위)의 ''불허'' 결정으로 좌초 위기에 놓인 가운데 매도측과 원매자의 후속 대응이 주목받고 있다. 롯데그룹과 사모펀드(PE) 어피니티에쿼티파트너스가 거래 포기 대신 협의를 이어가는 것으로 알려진 가운데 공정위 결정에 이의신청을 할지 이목이 집중된다.롯데렌터카 서울역 지점 전경.(사진=롯데렌탈)15일 투자은행(IB) 업계에 따르면 지난달 26일 공정위는 어피니티가 롯데렌탈 주식 63.5%를 취득하는 기업결합에 대해 경쟁 제한 우려가 크다며 불허 결정을 내렸다.어피니티는 앞서 지난 2024년 8월 SK렌터카를 8200억원에 인수한 상태다. 공정위는 업계 1·2위 사업자인 롯데렌탈과 SK렌터카가 모두 어피니티 지배하에 놓이면 시장 경쟁이 실질적으로 제한될 수 있다고 판단했다.공정위가 특히 문제 삼은 것은 양사의 압도적인 시장 지배력이다. 2024년 말 기준 롯데렌탈과 SK렌터카의 합산 시장점유율은 장기 렌터카 38.3%, 내륙 단기 렌터카 29.3%, 제주 단기 렌터카 21.3%에 달한다. 나머지 경쟁사들은 대부분 영세한 중소업체로 각각의 점유율이 미미한 수준이다.일단 롯데그룹은 공정위 결정을 존중한다는 입장을 내놨으나, 양측은 거래를 포기하지 않은 상태다. 더 나아가 어피니티는 기존 기업결합을 자문한 법무법인 태평양과 계약을 종료하고 법무법인 세종을 새로 선임하며 본격적인 법률 대응에 나섰다. 세종은 대한항공-아시아나항공 기업결합을 성공적으로 수행한 이력이 있다. 당시 세종은 매각자 측인 아시아나항공을 자문했으며, 국내 1·2위 업체의 결합에 더해 글로벌 경쟁당국의 승인까지 받아내야 하는 고난도 딜을 성사시켰다. 이러한 경험이 이번 선임의 배경으로 작용한 것으로 보인다.업계에서는 어피니티가 행정소송보다는 이의신청을 통한 재심의에 무게를 두고 있는 것으로 관측하고 있다. 행정소송의 경우 최종 판결까지 2년 이상 소요될 수 있어, 단기간 내 자산 가치를 높여 되파는 사모펀드의 특성상 오히려 독이 될 수 있기 때문이다. 실제 과거 삼익악기와 영창악기의 기업결합 불허 건에 대한 행정소송은 대법원 확정까지 약 2년 반이 걸렸으며, 결과도 공정위 승소였다.반면 이의신청은 상대적으로 빠른 시간 내 결론을 낼 수 있다. 공정거래법 제96조에 따르면 처분에 불복하는 자는 통지를 받은 날부터 30일 이내 이의신청을 할 수 있으며, 공정위는 이의신청을 받은 날부터 60일 이내, 부득이한 사유가 있으면 30일 범위에서 연장해 재결을 내릴 수 있다.관건은 공정위가 제기한 경쟁 제한성을 어떻게 완화하느냐다. 어피니티와 세종은 독과점 우려를 해소할 수 있는 강력한 시정방안을 제시해야 한다. 업계에서는 일정 기간 양사의 점유율을 자율 제한하거나, 제주 렌터카 시장에서 일부 차량을 매각하는 등의 대안이 검토될 가능성을 점치고 있다.공정위 불승인에도 불구하고 양측이 거래를 포기하지 못하는 이유는 명확하다. 롯데그룹은 유동성 확보 계획에 차질을 빚을 수밖에 없기 때문이다. 어피니티 역시 SK렌터카 인수 후 1위 업체인 롯데렌탈이 다른 사모펀드에 넘어가면 경쟁 지위가 크게 약화될 수 있어 부담이 크다. 또한 2018년 결성한 60억달러 규모 5호 블라인드펀드의 자금 소진 필요성도 있다.롯데그룹과 어피니티 측의 이의신청 여부가 설 연휴 이후 윤곽이 드러날 것으로 보인다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006219722', 'https://imgnews.pstatic.net/image/018/2026/02/15/0006219722_001_20260215094911491.jpeg?type=w800', 'NEWS_ETC', NULL, '2026-02-15 09:49:11', 0, true, '2026-03-09 06:10:38.753115') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (869, '''롯데렌탈 결합 불승인'' 어피니티, 로펌 새로 선임[Only 이데일리]', '기존 법무법인 태평양과 계약 종료…세종 새로 선임공정위 결정 이의신청·경쟁 완화 방안 마련 등 유력이 기사는 2026년02월04일 17시15분에마켓인 프리미엄 콘텐츠로 선공개 되었습니다.[이데일리 마켓in 송승현 기자] 롯데렌탈 인수가 불발된 사모펀드 어피니티 에쿼티 파트너스가 법무법인을 새로 교체하는 등 후속 대응에 본격적으로 나섰다.롯데렌터카 서울역 지점 전경.(사진=롯데렌탈)4일 이데일리 단독 취재에 따르면 어피니티는 기존 기업결합을 자문한 법무법인 태평양과 자문 계약을 종료하고 법무법인 세종을 새로 선임했다.앞서 지난달 26일 공정거래위원회(공정위)는 어피니티가 롯데렌탈 주식 63.5%를 취득하는 기업결합을 심사한 결과 독과점 우려가 제기된다며 불승인 결정을 내렸다.어피니티는 업계 2위인 SK렌터카를 소유하고 있는데, 업계 1위인 롯데렌탈까지 소유하면 국내 렌터카 시장 경쟁을 저해할 우려가 있다고 판단해서다.실제 롯데렌탈과 SK렌터카의 시장 점유율은 지난 2024년 말 기준 내륙 29.3%, 제주 21.3%로 집계됐다. 나머지 업체들은 영세한 중소업체들로 시장점유율이 미미하다.공정위의 불승인으로 셈법이 복잡해진 어피니티는 세종을 새로 선임해 대응에 나섰다. 롯데그룹이 새 인수 후보자를 검토한다는 얘기도 있지만, 롯데그룹과 어피니티는 재심의에 방점을 찍고 있다.IB 업계와 법조계에서는 행정소송으로 이어질 가능성은 낮게 보고 있다. 행정소송의 경우 판결이 최종 확정되기까지 오랜 시간이 필요해서다.비슷하게 독과점 우려로 공정위의 기업결합 불승인 결정을 받은 국내 피아노 시장의 ‘양대 산맥’인 삼익악기와 영창악기의 경우 대법원 확정까지 약 2년 반이 걸렸다. 결과도 공정위 승소였다.기업을 사서 가치를 높인 뒤 되팔아 수익을 얻는 사모펀드의 특성상 오랜 시간을 필요로 하는 행정소송은 오히려 독이 될 수 있다.대신 이의신청을 통해 재심의를 받는 방법을 택할 가능성이 높다. 이의신청은 행정소송에 비해 빠른 시간에 결론이 날 수 있다는 장점이 있다.공정거래법 제96에 따르면 처분에 불복하는 자는 통지를 받은 날부터 30일 이내 이의신청을 할 수 있다고 규정하고 있다. 공정위는 이의신청을 받은 날부터 60일 이내, 부득이한 사유가 있으면 30일 이내 범위를 연장할 수 있다.관건은 공정위가 제기한 경쟁 제한성을 어떻게 완화하느냐다.''경쟁 제한성 완화''란 특정 기업의 독과점이나 기업 결합(M&A)으로 시장 내 경쟁이 줄어들 우려가 있는 상황에서 실제로는 해외 경쟁 도입, 신규 사업자의 진입, 기술 발전 등 요인으로 시장 경쟁이 유지되거나 완화되는 상태를 의미한다.어피니티가 세종을 택한 건 대한항공-아시아나항공의 기업결합을 성공적으로 수행한 이력이 있다는 점이 작용한 것으로 알려졌다.당시 세종은 매각자 측인 아시아나항공을 자문했다. 해당 인수합병(M&A)은 국내 1·2위 업계의 결합과 더불어 글로벌에서도 기업결합을 승인받아야 하는 고난도 딜로 평가된다. 이 경험을 바탕으로 세종으로서는 경쟁 제한성을 완화할 수 있는 시정방안을 제시해야 하는 큰 과제를 떠안게 됐다.공정거래 업무를 수행하는 대형로펌의 한 변호사는 "어피니티가 롯데렌탈을 인수하는 방법은 경쟁 제한성을 완화할 수 있는 강력한 시정방안을 제시해 설득하는 것 뿐"이라며 "세종이 획기적인 묘수를 내지 않으면 쉽지 않은 싸움"이라고 말했다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006213340', 'https://imgnews.pstatic.net/image/018/2026/02/04/0006213340_001_20260204181710786.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-04 18:17:10', 0, true, '2026-03-09 06:10:38.753115') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (870, '"벤처 스튜디오 모델 본격 추진"…DSH코리아, 오강록 대표 영입', '[스타트업에 대한 보다 다양한 기업정보는 유니콘팩토리 빅데이터 플랫폼''데이터랩''에서 볼 수 있습니다.]오강록 드레이퍼 스타트업 하우스(DSH) 코리아스타트업 성장지원부문장(대표) /사진=DSH코리아 제공스타트업 AC(액셀러레이터)인 드레이퍼 스타트업 하우스(DSH) 코리아(한국 법인)가 오강록 프로미티어스 대표를 스타트업 성장지원부문장(대표)으로 영입했다고 9일 밝혔다.DSH는 미국 실리콘밸리의 유명 투자자 팀 드레이퍼(Timothy C. Draper)가 주도하는 스타트업 육성 공간이다. 전세계 20개국 30여개 도시에서 운영되며, 30개 이상의 유니콘을 배출했다.DSH는 지난해 5월 서울 강남구 가로수길에 한국 센터를 개소한 이후 최근 판교와 인천 송도에도 추가 센터를 열었다. LG생활건강과 뷰티테크 오픈 이노베이션 프로그램을 운영하고 있으며, 여러 대학·기관과 협력해 스타트업의 글로벌 진출을 돕고 있다.DSH 코리아는 이번 영입을 통해 스타트업 육성과 성장 지원 역량을 강화하고, 전략적 오픈 이노베이션 활성화와 함께 벤처 스튜디오 모델을 본격적으로 추진한다는 계획이다.오강록 대표는 삼성카드와 삼성생명 재직 후 삼익악기그룹 디지털추진본부장(전무)을 지냈다. 또 어반베이스 CRO(최고인사책임자), 그린랩스 디지털커머스센터장, 비즈니스캔버스 한국사업 총괄, 어센트코리아 CRO 등을 거쳤다.이세용 DSH 코리아 대표는 "오 대표 영입으로 스타트업의 아이디어 발굴부터 제품 개발, 시장 검증, 투자 유치까지 전 주기를 체계적으로 지원하는 벤처 스튜디오 모델을 본격화할 수 있게 됐다"고 했다.그러면서 "DSH의 글로벌 네트워크를 기반으로 북미·유럽·아시아 등 주요 시장에서의 현지화, 비즈니스 매칭, 투자자 연결 등 스타트업 지원을 강화하겠다"고 덧붙였다.[머니투데이 스타트업 미디어 플랫폼''유니콘팩토리'']', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005289339', 'https://imgnews.pstatic.net/image/008/2025/12/09/0005289339_001_20251210042006122.jpg?type=w800', 'NEWS_ETC', NULL, '2025-12-09 13:30:00', 0, true, '2026-03-09 06:10:38.753115') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (871, 'HS화성, 케냐 나이로비 BRT 도로공사 수주…아프리카 인프라 시장 첫 진출', '공사금액 784억원 규모에 공사기간 24개월총 연장 10.5Km 도로에 정류장 13곳 등 건설[대구=이데일리 홍석천 기자] HS화성(회장 이종원)이 해외시장 진출을 향한 의미있는 첫 발을 내디뎠다.HS화성은 케냐 나이로비 BRT(Bus Rapid Transit) 도로공사를 수주, 아프리카 인프라 시장에 첫 진출하는 성과를 거뒀다고 5일 밝혔다.이번 수주는 지난 2024년 7월 사명 변경 이후 해외사업 전담 조직 등을 통한 해외시장 진출을 추진한 이후 첫 결실이다.이번 공사는 지역의 영진종합건설과 함께 진행한다. 사업의 파트너인 영진종합건설은 지난 50년간 국내외 토목 인프라 프로젝트를 수행하면서 축적한 해외사업 및 행정관리 역량, 해외 발주처 영업 경험 등을 바탕으로 사업 전반의 안정적인 운영을 담당한다.사진=HS화성 제공HS화성은 68년간 국내 도시 인프라 현장에서 도로·교량·건축 등 다양한 사업을 수행하며 축적한 정밀 시공 기술력과 현장 중심의 공정관리 노하우를 기반으로 품질과 실행력을 책임진다.두 회사는 이같은 역할 분담을 통해 시너지를 극대화해 아프리카 시장 동반 진출이라는 의미 있는 성과를 이끌어냈다.이번 사업은 한국수출입은행의 EDCF(대외경제협력기금) 지원을 받아 추진되는 아프리카 도시 교통 인프라 개선 사업으로, 총 공사금액은 약 784억원, 공사기간은 착공일로부터 24개월이며, HS화성은 40%의 지분으로 참여한다.BRT는 간선급행버스체계로 불리는 대중교통시스템으로, 버스 전용 차로를 이용해 다수의 버스가 대량으로 도심에서 운용되며, 전철 운영이 어려운 도심에서 낮은 비용으로 효율적인 대중교통 시스템을 확보할 수 있다는 장점이 있다.사진=HS화성 제공해당 공사는 케냐 나이로비 외곽 간선도로 총 연장 10.5㎞도로에 고가교 2개소 및 강교 3개소 등을 포함한 토목공사와 함꼐 BRT 정류장 13개소, 운영기지(Depot) 등이다.특히 공사 시작 지점에는 주케냐 한국대사관이, 종점에는 발주처인 케냐 도시도로청(KURA) 본부가 위치해 있어 완공 시 HS화성의 기술력과 친환경 시공 역량을 현지에 알릴 수 있는 계기가 될 전망이다.HS화성은 성공적인 사업 추진을 위해 지난해 6월과 7월 두 차례에 걸쳐 사내 토목기술자를 파견, 현지 실사 및 협력업체 발굴, 관계기관 미팅 등 철저한 사전 준비를 진행했다. 또 같은 해 8월 사내 공모를 통해 토목분야 직원 2명을 케냐 현지로 인사 발령해 상주 인력을 배치하고 있다.HS화성 장익모 해외사업팀장은 “이번 BRT 사업은 케냐 나이로비 도심의 교통혼잡과 대기오염을 동시에 해소할 수 있는 프로젝트로, 당사가 추구하는 인류의 지속가능성과도 맞닿아 있다”며 “앞으로 EDCF 입찰참여 확대와 함께 HS화성이 강점을 가진 온실가스 국제감축사업을 비롯해 친환경 재생에너지 사업, 해외PPP(민관협력 파트너십) 사업까지 더해 해외사업 포트폴리오를 지속적으로 확장해 나가겠다”고 밝혔다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006230428', 'https://imgnews.pstatic.net/image/018/2026/03/08/0006230428_001_20260308182115628.jpg?type=w800', 'NEWS_CONSTRUCT', NULL, '2026-03-08 18:21:15', 0, true, '2026-03-09 06:10:47.558980') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (874, '거래소, 내년도 단일가매매 적용대상 저유동성종목 확정공표', '코스피 22종목, 코스닥 2종목 최종 확정[이데일리 권오석 기자] 한국거래소가 거래 빈도가 낮은 종목에 대한 가격발견기능 제고를 위해 2026년도 1년간 단일가매매 방식으로 거래될 저유동성종목을 최종 확정해 30일 발표했다.(사진=한국거래소)한국거래소는 상장주식 유동성 수준을 1년 단위(전년도 10월~9월)로 평가해 평균 체결주기가 10분을 초과하는 경우 저유동성종목으로 분류하고 단일가매매를 적용하고 있다.2026년 단일가매매 대상 저유동성종목 선정을 위한 유동성 평가결과, 최종 확정된 종목은 총 24종목이었다.우선 코스피(유가증권시장)에선 천일고속(000650)을 비롯해 △이화산업(000760) △미원화학(134380) △조흥(002600) △미원홀딩스(107590) 등 22사가 선정됐다. 코스닥에선 우선주인 △대호특수강우(021045) △소프트센우(032685) 2사가 이름을 올렸다.한국거래소는 “단일가매매 적용 대상으로 최종 확정된 종목은 2026년 1년간 30분단위 단일가매매로 체결될 예정”이라며 “1월 이후 LP계약 여부 및 유동성 수준을 월단위로 반영해 단일가매매 대상 저유동성종목에서 제외하거나 재적용할 것”이라고 설명했다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006192219', 'https://imgnews.pstatic.net/image/018/2025/12/30/0006192219_001_20251230164814857.jpg?type=w800', 'NEWS_ETC', NULL, '2025-12-30 16:48:14', 0, true, '2026-03-09 06:10:55.328329') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (875, '거래소, 내년 단일가매매 적용 저유동성종목 24개 예비 선정', '하이트진로홀딩스우·깨끗한나라우 등 포함[이데일리 신하연 기자] 한국거래소는 9일 내년 1년간 단일가매매가 적용될 저유동성종목 예비 명단을 공개했다. 거래 빈도가 낮은 종목의 가격발견 기능을 강화하기 위한 조치다.거래소에 따르면 전년도 10월부터 올해 9월까지 상장주식의 유동성을 평가한 결과 평균 체결주기가 10분을 초과한 종목은 ‘저유동성종목’으로 분류된다. 이 중 2026년 단일가매매 대상 후보로 24개 종목이 예비 선정됐다. 유가증권시장 22개, 코스닥시장 2개다.예비 선정 종목은 잠재적인 대상 종목으로 유가증권시장에서 하이트진로홀딩스우(000145), 유유제약2우B(000227), 노루홀딩스우(000325), 부국증권우(001275), 동양우(001525), 동양2우B(001527), 진흥기업우B(002785), 진흥기업2우B(002787), 유화증권우(003465), 서울식품우(004415), 깨끗한나라우(004545), 넥센우(005725), 크라운해태홀딩스우(005745), 코리아써키트2우B(00781K), 남선알미우(008355), 계양전기우(012205), 금강공업우(014285), 성문전자우(014915), 노루페인트우(090355), 미원홀딩스(107590)우, 미원화학(134380), 삼양사우(145995), JW중외제약우(001065), JW중외제약2우B(001067), 동부건설우(005965), CJ씨푸드1우(011155), 동원시스템즈우(014825) 등이다. 코스닥시장에서는 대호특수강우(021045), 소프트센우(032685)가 포함됐다.저유동성 기준에 해당하는 종목은 총 34개였으나, LP(유동성공급자) 지정 또는 유동성 개선으로 10개 종목이 제외됐다.이번 예비 명단은 12월 8일 기준이며, 거래소는 이달 30일에 LP 지정 여부와 유동성 수준을 다시 평가해 2026년에 단일가매매를 적용할 최종 종목을 확정할 예정이다. 최종 지정 종목은 내년 1년간 30분 주기로 단일가매매가 적용된다.아울러 LP 계약 체결 여부나 유동성 수준은 매월 반영된다. 유동성 개선 또는 LP 계약 체결로 대상에서 제외된 종목이라도 이후 상황이 악화되면 익월부터 다시 단일가매매가 적용될 수 있다. 천일고속(000650), 이화산업(000760), 조흥(002600), 코리아써우(007815), 대덕1우(00806K) 등은 LP계약, 직전 3개월간 유동성수준 개선으로 단일가매매 대상에서 제외됐지만 LP계약해지 혹은 종료시, 유동성수준 악화시 익월부터 단일가매매가 재적용된다.한편 단일가매매는 주문이 있을 때마다 거래를 체결시키는 일반적인 방식과 달리 일정 시간 동안 주문을 모아서 일정 시점에 하나의 가격으로 거래를 체결하는 주식 매매거래 방식이다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006180441', 'https://imgnews.pstatic.net/image/018/2025/12/09/0006180441_001_20251209163614189.jpg?type=w800', 'NEWS_ETC', NULL, '2025-12-09 16:36:14', 0, true, '2026-03-09 06:10:55.328329') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (876, '오뚜기, 농가 계약재배 2030년까지 4만t으로 늘린다', '''상생발전 프로젝트'' 확대 추진…올해 목표 1.5만t의 167%↑*재판매 및 DB 금지[서울=뉴시스] 변해정 기자 = 오뚜기는 오는 2030년 농가 계약재배 목표치를 4만톤(t)으로 잡았다.8일 식품 업계에 따르면 오뚜기는 2030년 4만t 규모의 계약 재배량을 달성하는 내용의 ''한국농업 상생발전 프로젝트'' 로드맵을 구축했다.한국농업 상생발전 프로젝트는 농가의 안정적인 소득 보장과 국내 농업 경쟁력 강화에 기여하고 소비자에게는 더욱 신선하고 안전한 국산 원재료로 만든 제품을 제공하기 위해 지난 2022년 시작됐다.오뚜기는 프로젝트 추진을 위해 오뚜기라면, 오뚜기냉동, 오뚜기제유, 오뚜기SF, 조흥, 상미식품 등 관계사 임직원이 참여하는 태스크포스팀(TFT)을 구성·운영 중에 있다.로드맵에 제시된 올해 계약 재배량 목표는 1만5000t이다. 전년의 1만3318t보다 12.6% 증가한 수치다.오뚜기는 2026년에는 2만t으로, 2030년에는 4만t으로 늘린다는 복안이다.4만t은 올해 목표 대비 166.7% 확대된 것으로, 농산물 구매량(원물환산 20만t) 기준 20%를 달성하게 되는 수치이기도 하다.오뚜기는 계약재배 품목 수도 점진적으로 늘려 나가기로 했다.오뚜기 관계자는 "농가, 국민, 기업이 파트너십을 통해 상생하는 환경을 구축하기 위한 것"이라면서 "앞으로도 상생경영 강화를 위해 다각도의 노력을 기울이겠다"고 말했다.', NULL, '뉴시스', 'https://n.news.naver.com/mnews/article/003/0013350737', 'https://imgnews.pstatic.net/image/003/2025/07/08/NISI20250103_0001742402_web_20250103095402_20250708170317995.jpg?type=w800', 'NEWS_ETC', NULL, '2025-07-08 17:01:17', 0, true, '2026-03-09 06:10:55.328329') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (877, '일동제약·제일파마 작년 매출 뒷걸음질, 올해 반등할까', '다국적사 제품 코프로모션 종료 타격… “자체 품목으로 부진 탈피”국내 주요 제약사 가운데 일동제약과 제일파마홀딩스는 지난해 매출이 뒷걸음질했다. 사진=일동제약·제일파마홀딩스일동제약이 지난해 소폭 쪼그라든 매출 성적표를 내놨다. 실적 발표를 앞둔 제일파마홀딩스도 지난해 매출이 감소한 것으로 관측된다. 둘 다 다국적 제약사에서 도입한 약물의 공동 판매(코프로모션) 계약이 종료된 영향이 크다. 이에 자체 대형 품목을 육성해 매출 체질을 바꾸겠다고 선언하지만, 그 결과는 알 수 없는 상황이다.12일 제약업계에 따르면 2024년 기준 매출 5000억원 이상을 기록했던 국내 중대형 제약바이오 헬스케어 기업 19곳 중 일동제약과 제일파마홀딩스가 지난해 매출 성장에 실패했거나 그럴 것으로 예상된다.전날 일동제약은 지난해 매출이 5669억원으로 전년(약 6149억원) 대비 7.8% 줄었다고 공시했다. 영업이익은 195억원으로 전년 대비 48.5% 증가했다. 이 회사는 고정비 절감 등으로 수익성이 개선됐지만 코프로모션 종료에 따라 일부 의약품이 제외되면서 전체 매출이 줄었다고 설명했다.일동제약은 지난 2024년 말 바이엘코리아와 맺었던 항진균제 ''카네스텐''을 비롯해 일반의약품 5개 품목에 대해 코프로모션 계약을 종료했다. 이들 약물의 매출 규모는 약 500억원 수준이다. 아울러 지난해 일동제약은 일부 컨슈머헬스케어(CHC) 사업 부문을 계열사인 일동생활건강으로 이관함에 따라 해당 매출이 제외됐다.일동제약 측은 "수익성 극대화에 초점을 맞춘 사업 재정비의 결과다"며 "재무 건전성을 바탕으로 자회사를 통한 신약개발 성과와 새로운 자체 대형 품목 육성을 통해 기업 가치를 높이겠다"고 설명했다. 이 회사는 2023년 설립한 자회사 ''유노비아''를 통해 경구용 비만 신약 후보 물질 ''ID110521156''의 임상 1상에 성공한 바 있다.제일파마홀딩스 역시 코프로모션 종료 의약품 때문에 매출 역성장이 점쳐지고 있다.제일파마홀딩스는 제일약품과 제일헬스사이언스 등을 거느린 지주사다. 이 중 제일약품의 자회사가 위식도역류질환 대상 제37호 국산 신약 ''자큐보(성분명 자스타프라잔)''를 허가받은 온코닉테라퓨틱스다.제일파마홀딩스가 종속회사의 자회사(온코닉테라퓨틱스)를 통해 지난 2024년 제37호 국산 신약 ''자큐보(성분명 자스타프라잔)''를 허가받았다. 사진=온코닉테라퓨틱스제일파마홀딩스의 연결 기준 매출은 2024년 7798억원이었다. 그런데 이 회사의 지난해 분기별 매출은 1분기 1912억원, 2분기 1667억원, 3분기 1636억원 등으로 나타났다. 지난해 3분기까지 누적 매출이 5215억원에 불과한 상황이다. 따라서 4분기 매출이 2583억원(1분기 매출의 135%)에 미치지 못했다면 연간 매출이 전년보다 뒷걸음질 하는 결과가 나온다.제일파마홀딩스의 종속회사인 제일약품은 미국 화이자와 파트너십을 맺고 고지혈증 치료제 ''리피토''와 진통소염제 ''리리카'', 골관절염치료제 ''쎄레브렉스'' 등의 국내 유통을 10년 이상 담당했다. 연간 1300억~1500억원 매출을 올리던 효자품목들이었는데, 지난해 코프로모션이 종료됐다.제일파마홀딩스 관계자는 "외자사 약물이 빠진 영향을 완전히 메우진 못했다"며 "직접 창출한 대형 품목 자큐보에 기대를 걸고 회사의 전 영업망을 매출 신장을 위해 집중하고 있다"고 말했다.자큐보를 보유한 온코닉테라퓨틱스의 지난해 매출은 전년 대비 260% 증가한 535억원을 기록했을 것으로 잠정 집계되고 있다. 이 회사는 올해 매출 목표치를 1000억원대로 높여 잡고 총력전을 펼치고 있다.', NULL, '코메디닷컴', 'https://n.news.naver.com/mnews/article/296/0000097537', 'https://imgnews.pstatic.net/image/296/2026/02/12/0000097537_001_20260212164014078.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-12 16:40:14', 0, true, '2026-03-09 06:11:02.632001') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (878, '제약·바이오 ''동전주'' 퇴출 우려…따져보니 ''찻잔 속 태풍''', '동전주 스무곳 중 7곳은 이미 관리종목주식병합·무상감자…기술적 대응 가능오는 7월부터 강화되는 이른바 ''동전주''의 상장폐지 요건이 제약·바이오 업계에 미칠 타격은 예상 보다 작아 ''찻잔 속 태풍''에 그칠 전망이다. 제약·바이오 종목 가운데 20여 곳이 퇴출 사정권에 들긴했으나 상당수가 이미 거래소 관리 대상인 데다, 주식병합 등 명목 주가를 올릴 기술적 탈출구도 열려 있어서다.27일 비즈워치가 지난 24일 종가 기준으로 분석한 결과 주가 1000원 이하의 제약·바이오 동전주는 19곳으로 나타났다. 이는 코스피·코스닥 전체 동전주 223곳 가운데 10%에 못 미친(8%) 수준이다.제약·바이오 동전주 많아 보이나...19개 기업은 코스피 3개사(에이프로젠·에이프로젠바이오로직스·오리엔트바이오) 코스닥 16개사(세종메디칼·유틸렉스·에스씨엠생명과학·이원다이애그노믹스·파라택시스코리아·동성제약·피플바이오·앱토크롬·케이엠제약·우진비앤지·모아라이프플러스·씨유메디칼·경남제약·네오이뮨텍·휴마시스·씨엔알리서치)이다.이들 기업은 동전주 요건 신설에 따라 퇴출 위기 기업으로 주목 받았다. 금융위원회와 한국거래소는 지난 12일 상장폐지 요건 강화안을 발표하며 1000원 미만 동전주 퇴출 요건을 신설했다. 구체적으로 상장기업의 주가가 30일 연속 1000원을 밑돌 경우 관리종목으로 지정되고, 이후 90일간 45일 연속 1000원 미만을 벗어나지 못하면 상장폐지된다.이에 동전주 폐지 요건 강화가 제약·바이오 기업의 무더기 퇴출로 이어질 것이란 관측이 제기됐다. 하지만 집계된 기업 중 상당수는 이미 거래소 관리 대상인 것으로 확인됐다.세종메디칼·유틸렉스·에스씨엠생명과학·이원다이애그노믹스·파라택시스코리아·피플바이오·앱토크롬·동성제약 등 8곳은 상장폐지 대상에 오르거나 관리종목 또는 투자주의환기종목으로 지정된 상태다.재무구조나 영업 지속성에 대한 우려가 이미 시장에 충분히 반영된 기업들인 만큼, 이번 요건 강화로 갑작스러운 상장폐지 위험이 불거졌다고 보기 어렵다는 분석이다. 세종메디칼과 유틸렉스, 이원다이애그노믹스, 동성제약은 이미 매매 정지된 상태다.주식 병합 → 동전주 탈출 가능거래소 제재를 받은 종목 9곳 외 기업들은 별도의 주가 부양책 없이도 기술적으로 동전주 탈출이 가능한 상황이다. 주로 주식병합이나 무상감자를 통해 명목 주가를 끌어올리는 방식으로 대응하는 형태다.실제로 휴마시스와 경남제약은 5대 1 주식병합을 결정했다. 시가총액이 유지된다는 가정하에 병합 후 주당 가격은 4000원대에 이르게 된다.금융당국은 주식병합을 통한 동전주 탈출을 제재하기 위해 병합 등으로 주가를 1000원 이상 높이더라도, 이후 주가가 액면가 이하로 떨어지면 상장폐지 대상에 올리기로 했다. 병합 전 주가가 액면가 이하에서 형성된 경우 퇴출 요건에 해당할 수 있다는 의미다.이에 해당하는 기업은 에이프로젠바이오로직스와 앱토크롬이다. 이들 기업은 무상감자를 통해 액면가는 유지하면서 주가를 올린다는 계획이다. 에이프로젠바이오로직스도 15대 1, 앱토크롬은 20대 1 비율로 무상감자를 결정했다.구조적 요인 때문에 동전주로 분류된 사례도 있다. 면역항암제 개발 기업 네오이뮨텍은 코스닥에서 주식예탁증서(KDR) 형태로 거래되며, 원주와 KDR 비율이 1대 5로 설정돼 있다. 이에 따라 코스닥 거래 가격은 미국 원주 가격의 5분의 1 수준에서 형성된다. 네오이뮨텍은 향후 KDR 병합을 통해 이러한 가격 괴리를 해소하겠다는 입장이다.동전주로 ''좀비 바이오'' 퇴출 어려워상장폐지 요건 강화 소식에 업계에서는 좀비 바이오 퇴출을 기대하는 시각과 연구개발 기업의 성과 압박이 커져 성장성 있는 기업들이 퇴출될 거란 우려가 교차했다.연구개발 중심 기업의 퇴출 우려는 다소 개연성이 떨어진다. 특히 신약 개발 바이오텍들은 기술력에 대한 기대감으로 주가가 높게 형성된 경우가 많아 동전주를 전전하는 경우가 적었다.동전주 기업 중 신약 중심 바이오텍으로 분류될 수 있는 유틸렉스·에스씨엠생명과학·파라택시스코리아 등은 최대주주 변경, 경영권 분쟁, 임상 실패 등의 사유로 동전주로 전락한 경우라 성장성 높은 기업이 퇴출되는 것으로 보기는 어렵다.동전주 퇴출·시가총액 기준 강화를 통한 좀비 바이오 솎아내기도 쉽지 않을 전망이다.업계 관계자는 "금융당국의 이번 조치가 당장은 유상증자와 전환사채(CB) 발행 등으로 실적 없이 연명하는 이른바 ''좀비 바이오'' 퇴출에는 큰 실효성을 거두지 못할 것"이라면서 "2027년부터 적용되는 상장 유지 매출 요건 강화 등과 결합해야 실효성을 담보할 수 있을 것"이라고 말했다.', NULL, '비즈워치', 'https://n.news.naver.com/mnews/article/648/0000044824', 'https://imgnews.pstatic.net/image/648/2026/02/27/0000044824_001_20260227103110963.gif?type=w800', 'NEWS_ETC', NULL, '2026-02-27 08:10:20', 0, true, '2026-03-09 06:11:09.029436') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (879, '삼목에스폼 자사주 처분 논란…액트·주주연대 금감원 진정', 'ACT·주주연대, “공개매수 실패 뒤 자사주로 우회 확보”삼목에스폼의 자기주식 처분에 대해 소수주주들이 공시 규정 위반과 배임 혐의를 제기했다.액트와 삼목에스폼 주주연대는 지난 8일 삼목에스폼 경영진을 공시 규정 위반과 배임 혐의로 금융감독원에 진정서를 제출했다고 9일 밝혔다.삼목에스폼 [사진=삼목에스폼 홈페이지]앞서 김준년 회장의 개인회사인 에스폼과 김 회장의 세 자녀(김수민·김수현·김승유)가 지분 80%를 보유한 특수관계사 에스브이씨(SVC)는 지난해 9월 삼목에스폼 지분 9.52%(140만주)를 주당 2만2800원에 공개매수하겠다고 밝혔다. 회사 측은 ‘경영권 안정’과 ‘책임경영 강화’를 내세웠지만, 공개매수 가격이 주당 장부가치(BPS)의 절반 수준에 불과하다는 점에서 소수주주의 반발이 컸다. 실제 공개매수 결과 응모 주식은 36만2301주로 예정 물량의 25.8%에 그쳤다.공개매수 이후 삼목에스폼은 보유 중이던 자사주 17만264주를 공개매수와 동일한 가격인 주당 2만2800원에 에스폼과 에스브이씨에 처분했다.이에 대해 액트 측은 “공개매수로 확보하지 못한 물량을 자사주 거래로 우회 확보한 것”이라며 “자사주 소각 압력을 피하면서 최대주주 측 지분율을 높이기 위한 수순”이라고 지적했다.주주연대는 자사주 처분 과정에서 절차적 문제도 지적했다. ‘증권의 발행 및 공시 등에 관한 규정’은 자사주 신탁계약 해지 결과보고서 제출 후 최소 1개월(30일) 이후에 자사주를 처분할 수 있도록 하고 있다. 그런데 삼목에스폼은 지난해 9월4일 해지 보고서 제출 후 19일 만에 이사회를 열어 처분을 의결했다.이사회 운영의 적법성도 도마에 올랐다. 이번 거래는 최대주주 특수관계인과의 거래로 이사회 7명 중 3분의 2 이상인 5명의 찬성이 필요했는데, 김준년 회장과 엄석호 대표가 이해관계자로 의결에서 배제된 상황에서 김 회장의 4촌인 김재년 이사가 표결에 참여해 가결 정족수를 채웠다는 게 주주연대 측의 주장이다. 이해관계자를 제외할 경우 안건이 부결될 수 있는 상황에서 무리하게 표결을 성사시켰다는 것이다.이 같은 자사주 활용 방식은 삼목에스폼에만 국한되지 않는다는 점에서 논란을 키운다. 에스폼의 또 다른 계열사인 동일제강 역시 지난해 보유 중이던 자사주 132만7000주를 주당 1980원에 최대주주 에스폼에 처분했다. 동일제강은 처분 목적을 유동성 확보라고 밝혔지만, 당시 유동비율은 600%를 웃돌아 실질적 필요성은 크지 않았다는 평가가 나왔다. 이 거래로 에스폼의 동일제강 지분율은 41.63%에서 48.17%로 상승했으며, 처분 가격은 장부가치의 0.3배 수준에 불과했다.삼목에스폼 주주연대는 이번 진정서 제출을 시작으로 위법한 이사회 결의에 찬성한 이사들에 대한 직무집행정지 가처분 신청과 주주명부 열람·등사 청구 등 추가 법적 대응에 나선다는 계획이다.', NULL, '아이뉴스24', 'https://n.news.naver.com/mnews/article/031/0000995572', 'https://imgnews.pstatic.net/image/031/2026/01/09/0000995572_001_20260109104310031.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-09 10:43:10', 0, true, '2026-03-09 06:11:15.260392') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (880, '“자사주 날리긴 아깝다”…교환사채 외 생존법 찾는 기업들', '후성그룹 계열사, 잇따라 자사주 상호 매입광동제약 이어 경방-일신방직 등 우군간 자사주 상호 교환도금감원 제동 및 시장 비판에 EB발행 우회로 찾아이 기사는 11월 04일 15:52마켓인사이트에 게재된 기사입니다.Copyright @ gettyimages Bank자사주 의무소각 법안의 국회 통과가 임박하면서 법안 시행 전에 자사주를 활용한 ‘방어책’을 마련하려는 기업들의 움직임이 분주하다. 자사주를 기초로 한 교환사채(EB)가 대표적인 해법으로 떠오르고 있지만, 금감원 견제와 시장의 비판에 부딪히고 있다. 이를 우회하기 위해 자사주를 계열사에 넘기거나 우호적인 세력과 상호 매입해 주는 사례가 이어지고 있다.4일 증권업계에 따르면 한국내화는 보유한 자사주 약 563만주 전량을 계열사인 후성이 보유한 한텍 보통주 보통주 26만5758주와 교환할 예정이다. 총 124억원 규모의 거래다.앞서 후성글로벌은 지난달 말 퍼스텍 자사주 8억500만원(0.36%)을 매입했다. 후성 자사주 82만원어치도 샀다. 이번 거래로 후성그룹 계열사가 보유한 자사주는 모두 없어지게 된다.후성홀딩스는 사실상 후성그룹의 지주회사로 후성·한국내화·퍼스텍 등 유가증권시장 상장사와 다수의 비상장 계열사를 거느리고 있다.코스닥 상장사 파워넷도 자회사 아이즈비전의 자사주 14억원어치(3.43%)를 다음달 초까지 매입할 계획이다. 지난달 엘엠에스는 계열사 창강화학과 특수관계자인 나노머티리얼즈에 보유 자사주 35%를 넘겼고, 동일제강도 특수관계사 에스폼에 자사주 6.54%를 매각했다.자사주 의무소각을 담은 상법 개정안이 이달 안에 국회를 통과될 가능성이 높아지면서 기업들의 자사주 처분 움직임이 빨라지는 모습이다.‘소각은 손해’라는 인식이 확산되며 EB 발행이 주로 활용되고 있지만, 자사주 규모가 작거나 외부 투자자 유치가 부담스러운 기업들은 계열사 자금으로 이를 처리하고 있다. 최근 금융감독원이 자사주 기반 EB 공시를 강화하면서 부담이 커진 점도 이런 행보에 영향을 미쳤다는 분석이다.우호세력과 자사주를 맞교환하거나 협력관계를 내세워 안정적 지분을 확보하려는 곳도 있다. 외부 투자자 확보나 EB 발행이 여의치 않은 기업들이 지분 방어를 위해 ‘맞손 전략’을 택하는 모습이다.경방과 일신방직은 지난달 말 자사주를 맞교환했다. 경방은 일신방직에 자사주 75억원어치(3.9%)를 팔고, 일신방직은 같은 금액의 경방 자사주(3.0%)를 사들였다. 양사는 “베트남 사업 협력의 일환”이라고 설명했지만, 시장에서는 자사주 활용도를 높이기 위한 전략으로 바라본다.자사주는 제3자에게 넘기면 의결권이 되살아나기 때문에 경영권이 불안한 기업들에겐 사실상 ‘우군 확보 카드’로 사용된다. 직접적인 위협이 없더라도 중장기적으로 활용 여지가 크다는 점에서 이해관계가 맞아떨어진 셈이다.이같은 움직임은 올해 곳곳에서 이어지고 있다. 지난 7월 세방과 하이비젼시스템도 자사주 상호 교환을 의결했다. 광동제약 역시 9월말 협력사인 삼양패키징·금비·삼화왕관 등에 자사주 373만4956주(지분율 9.5%)를 넘기는 동시에, 금비 자사주 7.94%와 삼화왕관 자사주 6.56%를 받았다.전체 주주를 고려해야 한다는 취지에 맞게 사업적 협력 관계를 앞세워 명분을 확보하기에도 외부 자금 조달보다는 수월하다는 분석이다.증권업계 관계자는 “자사주 의무소각이 시행되더라도 유예기간이 주어질 가능성이 높다”며 “이 기간 동안 소각이 어렵거나 실제 처분이 부담스러운 기업들이 우군 네트워크를 통한 자사주 거래를 확대할 것”이라고 내다봤다.', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005207148', 'https://imgnews.pstatic.net/image/015/2025/11/05/0005207148_001_20251105094214990.jpg?type=w800', 'NEWS_ETC', NULL, '2025-11-05 09:42:14', 0, true, '2026-03-09 06:11:15.260392') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (881, '대선조선 영도조선소 부지 우선협상자 한라IMS', '채권단, 공개입찰 방식도 병행- 한라보다 나은 조건땐 주인 변경- 美 마스가 호재에 매각작업 속도부산 중견 조선업체 대선조선 영도조선소 부지 매각 작업이 속도를 내고 있다.23일 지역 조선업계에 따르면 대선조선 채권단은 최근 지역 선박 기자재 제조 및 수리조선 업체인 한라IMS를 대선조선 영도조선소 부지 매각 관련 우선협상대상자로 선정했다. 대선조선 영도조선소 매각은 우선협상대상자를 미리 정해두고 공개 입찰을 진행하는 ‘스토킹 호스(Stalking Horse)’ 방식으로 진행된다. 채권단은 조만간 입찰공고를 낼 계획이다. 한라IMS보다 더 좋은 조건을 제시한 곳이 나오면 해당 기업이, 그렇지 않으면 한라IMS가 대선조선 영도조선소의 새 주인으로 최종 결정될 전망이다.매각을 진행 중인 대선조선 영도조선소의 부지 규모는 약 3만㎡에 이른다. 부동산업계는 해당 부지 시세가 3.3㎡ 당 1000만 원이 넘을 것으로 본다. 대선조선은 2023년 1600억 원 규모의 적자를 내며 그해 말 워크아웃에 들어간 후부터 차입금 상환을 위해 영도조선소 부지 매각을 추진했다. 그러나 영도조선소 부지와 HJ중공업 조선소가 인접, 용도 변경이 어려워 좀처럼 팔리지 않았다.올해 들어 이런 국면은 바뀌었다. 미국 도널드 트럼프 대통령의 ‘마스가’(MASGA·미국 조선업을 다시 위대하게)프로젝트에 대한 관심이 높아지면서 영도조선소가 선박 MRO(정비·보수·운영) 거점으로서의 가치를 인정받았기 때문이다. 업계에서는 한라IMS가 영도조선소를 인수하면 수리 조선업 등을 할 것으로 예견한다. 이 회사는 2020년 전남에 있는 오리엔트조선 광양사업장 62만8000㎡ 부지를 구입해 선박 수리 사업에 진출했다. 선박평형수처리장치 선박용수위계측장치 밸브원격제어장치 등을 국내외 조선소와 선사에 생산·공급하는 국내 대표 강소기업이다. 올해 상반기에만 매출액과 영업이익을 각각 622억 원, 112억 원 기록했다. 이에 대해 한라IMS 관계자는 “대선조선 영도조선소 부지 우선협상대상자가 된 것은 맞지만 현재 진행 중인 사항으로 추가로 확인해줄 수 있는 것은 없다”고 말했다.대선조선은 앞서 내년 1월께까지 이미 수주한 신조 선박을 모두 인도하고 남은 다대포 조선소에서는 대형 조선사의 선박 블록 및 선실 제작에 집중하겠다고 밝힌 바 있다. 대선조선은 조선업 불황으로 위기에 놓이면서 2010년 채권단 자율 협약에 들어간 뒤 2021년 장인화 전 부산상공회의소 회장이 이끄는 동일제강 컨소시엄에 인수됐다. 컨소시엄은 동일철강 동원주택 동원종합물산 세운철강 동일스위트 등 부산 지역 향토기업 5곳으로 구성됐다.', NULL, '국제신문', 'https://n.news.naver.com/mnews/article/658/0000123703', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2025-10-23 18:53:15', 0, true, '2026-03-09 06:11:15.260392') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (882, '[미리보는 이데일리 신문]고유가에 치솟는 물가…S의 발톱 드러냈다', '[이데일리 김소연 기자] 다음은 9일자 이데일리 신문 주요 뉴스다.△1면-고유가에 치솟는 물가…S의 발톱 드러냈다- 민간기관 4곳, 기술평가 87% 독점 코스닥 특례상장 불공정 우려 키워- 노란봉투법발 파업 쓰나미, 석화·철강산업 덮칠듯- 韓 수출 쏠림 심화 반도체가 절반 될 판-[사설]2차 대미 투자 나서는 日 아직 발도 떼지 못한 한국-[사설]치솟는 유가, 고통 가중시키는 시장 교란 엄단해야△고유가發 S공포 현실화-“쌀·고기·달걀 줄줄이 올랐는데 전쟁까지”…‘설상가상’ 밥상 물가-경윳값, 3년여 만에 휘발유 추월 생계형 화물차·택배 기사 ‘비명’△고유가發 S공포 현실화-고유가→고물가→내수침체…원유 의존 크고 수출로 먹고사는 韓 치명상-33조 ‘빚투’ 반대매매 폭탄 터질라…증시 하락 공포↑-기름값 급등 ‘네탓 공방’ 속…정부, 가격상한제 검토△기술특례상장 공신력 갖추려면-국책기관엔 인센티브, 민간엔 외부전문가 투입…기술평가 신뢰회복 급선무- 옥석 못 가린 기술특례…상폐·관리지정 잇달아△반도체 쏠림 심화-반도체 빠면 수출 마이너스 슈퍼사이클 꺾이면 닶 없다-삼전·닉스 흔들리면…증시·자산·환율 ‘휘청’-“첨단업종 중심 수출엔진 다변화 필요”△종합-버려진 금속서 ‘반도체·방산 핵심’ 인듐·안티모니 추출…美中 흉내 못 내-“노란봉투법 안착 지원”…중노위, 내달부터 조정기능 강화 포럼-대기업 여성 고용 늘었다…롯데쇼핑, 女 비중 66.8% 가장 높아-“중동 군사작전 중단” 촉구하고도 왕이, 美에 직접적 비판은 자제△경제-‘환헤지’ 늘리는 외국인 투자자에…원화 약세 ‘악순환’-취업 늦어지고 집값은 버겁고…청년층 이중고-정부 주도 해상풍력 ‘속도’…연내 첫 예비지구 지정-IMF “올해 韓 경제성장률 1.8→1.9%”△정치-정부, 전세기 띄워 ‘중동 탈출’ 지원…오산에 있던 美 수송기, 줄줄이 이륙- 후원금 쪼그라든 국힘…‘고액 후원’은 싹쓸이- 물건너간 대전충남·대구경북 통합 정청래 “국힘, 지선서 심판받을 것”- 오세훈, 서울시장 후보 미등록 ‘초강수’…“당 노선 변경부터”△경제-“韓 경제, 관세·유가·금리 등 대외 변수에 발목”- 무보·코트라, 中企 수출지원 ‘원팀’ 협력- 담합 사건 ‘속도전’이 능사 아니다- 교복값 잡힐까…공정위, 제조사·대리점 전방위 조사△금융-주담대 3건 중 1건 다주택자…정부 규제 촉각-압류 막아준다던 생계비계좌…월급 250만원 넘으면 그림의 떡-“증시로 자금이탈 막아라”…저축은행 예금 금리 ‘꿈틀’-“웹3 신사업 기술 준비 완료 스테이블코인 컨소시엄 추진”△산업-LG, 금융 AI에이전트로 B2B 수익화 정조준-“파업 불참하면 해고 1순위” 삼성전자 노조, 직원 압박 논란- 멕시코 현지맞춤형 라인업 LG전자, 글로벌 사우스 공략- HD현대일렉, 북미 제2공장 착공…초고압 변압기 시장 경쟁력 강화-“차별화한 AI기술로 건설장비 시장 선도”-삼성 글로벌 TV 시장 20년 연속 ‘톱’△산업-유럽판 IRA 추진…한국車 추가 투자압박 커져-모셔널 CEO “무인 로보택시 연말 상용화”-AI·셀투팩·ESS…‘3사3색’ 기술전쟁 막오른다△ICT-‘투자금 68억원’ 손실위기 KT스카이라이프 경영책임 논란 속 차기 CEO 선임에도 불똥-“데이터 유출 걱정 없는 ‘소버린 AI 인프라’ 개발 속도”- “내가 보는 것 그대로 인식하는 AI 스마트폰 연동으로 가볍게 쓴다”-‘AI 앱스토어’ 경쟁 본격화…앤스로픽, ‘클로드 마켓플레이스’ 공개△성장기업-코딩 넘어 기업 맞춤 AI 교육…매출 1000억 눈앞-생활가전 사업 확장 신일전자, 멤버십 오픈-“日 거장의 수업 통했다…글로벌 콘텐츠 확장 가속”-“끓는 소리 듣고 스스로 화력 조절”…인덕션도 ‘쿠쿠’하세요△생활경제-보릿고개 넘나 했더니…면세점 덮친 ‘중동 쇼크’-“평화시장 위기, 라방으로 돌파…연매출 50억 찍어”- 지역상생장터…쿠팡 ‘착한상점’ 매출 5조 돌파-“아무리 바빠도 아침은 챙겨야죠” CU 간편식 100만개 돌파△부동산-“재건축, 수익성 없으면 NO”…군포·광명 이어 서울 핵심지 확산 우려-지방 악성 미분양 15년래 최대…LH “준공 전 주택까지 매입 확대”-사전협상 공공기여 10조 확보 서울시 “강북 전성시대 구축”△증권-“3차 상법 개정 다음 스텝은 자본비용 공시”-AI·원유·방산 들고 이란전 참전한 서핵개미들-전쟁공포 한결 가신 증시 반도체·배터리 반등 기대-중동전쟁에 불붙은 원유·가스, 얼어붙은 석유화학△스포츠-123일 만에 기지개 켜는 KLPGA ‘총상금 347억’ 최강자들 정면승부-이미향, 9년 만에 LPGA 정상 올해 韓 첫 우승 트로피 들었다-올해도 럭셔리車가 빛낸다…벤츠까지 ‘골프대전’ 합류-韓, 대만에 4-5 패…WBC 8강행 ‘먹구름’△문화-자본중심의 공연산업 앞장 관객데이터로 시너지 낼 것-화려한 무대 장치·영화같은 장면 ‘대형 서사’로 韓 창작뮤지컬 확장△오피니언-[新 광수생각]누구의 눈물이 진짜인가-[임진모의 樂카페]오스카 트로피 들어올리는 법-[생생확대경]경찰·소방수장 공석 속 행안장관의 역할△오피니언-증시 변동성 완화를 위한 제언- 한·네덜란드 ‘반도체 토털협력’의 힘-MWC26이 보여준 미래, AI 인프라 진화한 통신△피플-월가 자산관리 비법 대중화…금융격차 줄일 것-금융권 “핵심 직무 내 여성 리더십 확대”-KAIST, 약물작동·단백질 기능 활성화 예측 AI 개발-KT ‘에이블스쿨 8기 성료 AI 인재 300명 역량 키웠다△사회-10명 중 7명 “내 집에서 생 마감하고 싶다”…절차 복잡해 결국 병원행-생애 말기 환자에겐 치료보다 돌봄 필요 대응계획 세운다면 가정 호스피스 가능-“SKY대학보다는 의대” 미충원 인원 6년새 3배↑-“BTS 공연 관광객, 숙박 피해 막아라” 서울시 총력', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006230464', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2026-03-08 21:29:07', 0, true, '2026-03-09 06:11:23.220814') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (883, '생활가전 넓힌 신일전자, 첫 멤가전 넓힌 신일전자, 첫 멤버십 오픈', '사업 다각화로 작년 영업익 30%↑카테고리 확장·마케팅 강화 추진[이데일리 김응태 기자] 선풍기로 유명한 신일전자(002700)가 사업다각화에 적극 나서고 있다. 편중된 매출 구조에서 벗어나 라이프스타일 가전 및 리빙으로 사업 영역을 확대하는 가운데, 여러 제품을 구매하면 혜택을 주는 멤버십을 론칭하며 사업 전반의 시너지를 추진한다. 사업다각화 효과로 지난해 실적이 개선되면서 올해 역시 사업 포트폴리오 확대에 주력할 것으로 전망된다.신일전자 서울 선유도 사옥. (사진=뉴스1)8일 중소기업 업계에 따르면 신일전자는 지난달 첫 공식 멤버십을 오픈했다. 네이버 브랜드 스토어 내 멤버십에 가입하면 총구매액에 따라 혜택을 제공하는 구조로 5개 등급으로 이뤄졌다. 가장 높은 등급인 VVIP의 경우 최근 3개월간 구매금액이 100만원 이상이면 10% 할인 혜택을 준다. 두 번째로 높은 VIP 등급은 50만원 이상 구매하면 7%의 할인 혜택을 준다.신일전자는 멤버십 가입 고객을 대상으로 설문조사도 진행하고 있다. 설문조사 내용 중에는 ‘새롭게 출시를 원하는 제품’에 대한 질문이 포함됐다.신일전자가 멤버십을 론칭한 것은 종합가전기업을 지향하며 고객들로부터 다양한 제품 구매를 유도하려는 의도가 반영된 것으로 분석된다. 선풍기 시장점유율 1위인 신일전자는 선풍기와 계절가전에 편중된 매출 구조를 타파하고 신규 수익원을 발굴하기 위해 라이프스타일 가전 및 리빙 영역으로 사업 범위를 넓혔다. 지난해에는 창립 66주년을 맞아 여행용 캐리어 시장에 첫 진출해 ‘세이 예스’ 브랜드를 론칭했다. 세이 예스 캐리어 상품은 항공기에 사용되는 내구성이 강한 폴리카보네이트(PC) 소재를 적용한 게 특징이다. 또 리빙 시장에도 진출하며 ‘스마트 모션센서 휴지통’을 신상품으로 선보였다. 이 제품은 뚜껑 내부에 자동 오존 살균 시스템이 적용되고 발광다이오드(LED) 무드램프가 들어가 어두운 환경에서도 편리하게 활용되도록 제작됐다. 이밖에 무선 물걸레 청소기, 음식물처리기, 칫솔살균기, 푸드워머 등으로 신제품 품목을 확대한 바 있다. 신일전자 관계자는 “종합가전기업으로 성장하기 위해 주방·생활 가전뿐 아니라 다양한 라이프스타일 가전의 카테고리를 지속적으로 확대하고 있다”며 “올해 출시한 푸드워머를 비롯해 주방 및 생활 가전 영역에서 선보인 제품들이 온라인 채널을 중심으로 긍정적인 반응을 얻고 있다”고 말했다.라이프스타일 가전 및 리빙 시장으로 보폭을 넓히면서 전체 매출에서 선풍기가 차지하는 비중도 줄고 있다. 금융감독원에 따르면 지난해 1~3분기 기준 선풍기가 전체 매출에서 차지하는 비중은 65.5%를 기록했는데, 이는 전년 동기(67%) 대비 1.5%포인트 하락한 수준이다.전체 실적은 우상향했다. 별도 기준 지난해 신일전자 영업이익은 52억원을 기록해 전년 대비 29.9% 증가한 것으로 나타났다. 같은 기간 매출액은 1783억원에서 1944억원으로 9% 늘었다. 신일전자 관계자는 “제품의 기능 확장과 디자인 완성도를 강화하는 동시에 카테고리를 확대하고 브랜드와 소비자 간 접점을 확대하기 위한 타깃별 맞춤 홍보 마케팅 전략을 전개해 나갈 계획”이라고 밝혔다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006230329', 'https://imgnews.pstatic.net/image/018/2026/03/08/0006230329_001_20260309100509751.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-08 13:24:09', 0, true, '2026-03-09 06:11:23.220814') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (884, '"더 가볍게" 1kg대 무선청소기 경쟁…가전업계 경량화 승부', '흡입력 중심 경쟁에서 사용 편의성으로 시장 변화쿠쿠·신일 잇달아 초경량 스테이션 무선청소기 출시파워클론 제트슬림ⓒ쿠쿠[데일리안 = 임채현 기자] 국내 무선청소기 시장의 경쟁 구도가 달라지고 있다. 과거에는 흡입력과 배터리 성능이 핵심 경쟁력이었다면, 최근에는 무게를 줄이고 청소 이후 관리 과정을 자동화하는 방향으로 제품 개발이 이어지는 모습이다.6일 업계에 따르면 최근 가전업체들은 경량 설계와 자동 먼지 비움 기능을 결합한 ''스테이션 무선청소기'' 제품을 잇달아 출시하고 있다. 장시간 사용 시 손목 부담을 줄이면서도 청소 후 먼지 처리까지 자동화하려는 수요를 반영한 전략이다.쿠쿠는 최근 초경량 무선청소기 ''파워클론 제트슬림''을 선보이며 시장 공략에 나섰다. 제품 무게는 약 1.47kg 수준으로, 실제 사용 시 체감 무게를 약 700g 수준까지 낮춘 것이 특징이다. 슬림 브러시를 적용해 소파나 침대 아래 등 낮은 공간도 쉽게 청소할 수 있도록 했다.청소 후 관리 편의성도 강화했다. 제품을 거치하면 먼지통을 자동으로 비워주는 ''오토 클린 스테이션''을 적용해 먼지 날림을 줄이고 관리 부담을 낮췄다.스테이션 무선청소기.ⓒ신일전자신일전자도 최근 스테이션 무선청소기를 출시하며 같은 흐름에 합류했다. 이 제품은 완제품 기준 1.7kg 수준의 무게를 구현했으며 거치 시 자동 먼지 비움과 충전이 동시에 이뤄지는 구조다. 최대 2만Pa 흡입력의 BLDC 모터를 적용해 미세먼지 제거 성능도 강화했다.업계에서는 무선청소기 시장이 성숙 단계에 접어들면서 제품 경쟁의 기준이 바뀌고 있다고 보고 있다. 강력한 흡입력을 기본으로 하되, 사용자 피로도를 줄이는 경량 설계와 청소 이후 관리까지 자동화하는 기능이 새로운 경쟁 요소로 떠오르고 있다는 분석이다.특히 스테이션형 무선청소기는 먼지통 비움, 충전, 보관을 한 번에 해결할 수 있어 프리미엄 제품군 중심으로 빠르게 확산되는 추세다.', NULL, '데일리안', 'https://n.news.naver.com/mnews/article/119/0003066263', 'https://imgnews.pstatic.net/image/119/2026/03/06/0003066263_001_20260306173818924.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-06 17:38:18', 0, true, '2026-03-09 06:11:23.220814') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (890, '병·의원에 현금·경품 등 리베이트…공정위, 동성제약·국제약품 제재', '시정명령 혹은 과징금 부과공정위 현판. 부산일보DB동성제약과 국제약품이 자사 약품을 써달라며 병·의원에 부당한 금품·경품 등 리베이트를 제공했다가 적발돼 공정거래위원회의 제재를 받았다.공정위는 동성제약이 자사 의약품을 처방하는 대가로 병·의원에 리베이트를 제공한 것을 적발해 시정명령(향후 금지 명령)을 내렸다고 18일 밝혔다.공정위에 따르면 동성제약은 자사 의약품 채택·처방을 유지 혹은 늘리고자 수도권 소재 4개 병·의원 의료인들에게 2010년 10월부터 2019년 4월까지 현금 등 약 2억 5000만원 상당의 경제적 이익을 제공했다.동성제약은 리베이트를 제공함으로써 생기는 법적 책임이나 위험을 회피하기 위해 영업대행업체에 전면 위탁하는 방식으로 전문 의약품 영업 방식을 변경하기도 했으며, 계열사에서 퇴직한 뒤 영업대행업체를 설립한 이들과 계약하기도 한 것으로 조사됐다.공정위는 일련의 행위가 부당하게 경쟁자의 고객을 자기와 거래하도록 유인하는 행위(부당한 고객유인행위)이며, 독점규제 및 공정거래에 관한 법률(공정거래법) 위반이라고 판단했다.다만, 동성제약이 회생절차가 진행 중인 점을 고려해 과징금을 면제하고 시정명령으로 제재를 갈음했다.공정위는 또 국제약품이 자사 제품 판매를 촉진하기 위해 2015년 11월부터 2019년 12월까지 광주시 소재 병원 송년회에 백화점상품권과 가전제품 등 경품을 지원하거나 병원 직원들이 단체 관람하도록 영화관을 빌리고 비용을 대신 내는 등 1300만 원 상당의 부당 이익을 제공한 것을 적발해 시정명령과 함께 과징금 300만 원을 부과하기로 결정했다.공정위는 "보건복지부, 식품의약품안전처 등 관계 기관과 유기적으로 협조해 의약품 시장의 불공정거래관행 감시를 강화해 나갈 것"이라며 "법 위반 사실이 확인될 경우 엄중하게 조치할 예정"이라고 밝혔다.', NULL, '부산일보', 'https://n.news.naver.com/mnews/article/082/0001367351', 'https://imgnews.pstatic.net/image/082/2026/02/18/0001367351_001_20260218175511677.JPG?type=w800', 'NEWS_CHEM', NULL, '2026-02-18 17:55:11', 0, true, '2026-03-09 06:11:39.620947') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (891, '한국식품산업협회, 2026년 정기총회 개최…"K-푸드 글로벌 도약 지원"', '농심·대상·동서식품 등 11개사 비상근 부회장 재선임"국내 식품산업의 글로벌 진출은 필수…협회가 지원"박진선 한국식품산업협회장이 27일 롯데호텔 서울에서 열린 ''2026년도 정기총회''에서 모두 발언을 하고 있다. /한국식품산업협회[더팩트 | 손원태 기자] 한국식품산업협회(이하 협회)는 롯데호텔 서울에서 ''2026년도 정기총회''를 개최했다고 27일 밝혔다.협회는 이번 정기총회에서 △2025년도 주요사업 실적 및 결산 △2026년도 주요사업 계획 및 예산(안) △임원 선임 등에 관한 사항 등에 대해 심의·의결했다.또한 협회 비상근 임원의 임기가 만료되면서 농심 조용철 대표이사, 대상 임정배 대표이사, 동서식품 김광수 대표이사 등 11개사가 비상근 부회장으로 재선임됐다. 사조대림 김상훈 대표이사, 삼양식품 김동찬 대표이사, 서울에프앤비 오덕근 대표이사 등 3개사도 비상근 이사사로 신규 선임됐다.협회는 상근부회장 임기 만료에 따라 지난 12월부터 공모제를 통해 임원추천위원회 및 제162차 이사회 등 인선 절차를 진행했다. 이날 총회에서는 정용익 전 식품의약품안전처 식품소비안전국장이 최종 선출됐다.협회는 식품 안전과 산업 발전에 공헌한 유공자들에 정부포상(식품의약품안전처장 표창 5명)도 수여했다.정기총회 부대행사로는 ''2025 식품산업 공급망 ESG 경영 대상'' 시상식도 함께 가졌다. 식품산업 최초 ESG 시상식으로, 협회 ''식품산업 공급망 ESG 공동사업''에 참여한 협력사 중 우수한 ESG 성과를 거둔 기업에 포상했다. 시상은 ESG 진단 점수 상위 기업을 대상으로 심의위원회를 거쳐 총 2개 기업(△대상 아그라나프루트코리아 △최우수상 대한제분)이 최종 선정됐다.박진선 한국식품산업협회장은 "국내 식품산업의 글로벌 진출은 선택이 아닌 생존 전략이며, 협회는 식품산업 경쟁력 강화 및 K-푸드 글로벌 도약 선도를 지원하는 다양한 사업을 추진하겠다"라고 밝혔다.[한국식품산업협회 임원 선임 사항]◇재선임-비상근부회장△농심 조용철 대표이사 △대상 임정배 대표이사 △동서식품 김광수 대표이사 △롯데웰푸드 서정호 대표이사 △매일유업 이인기 대표이사 △삼양사 정지석 부사장 △CJ제일제당 박린 대표이사 △SPC삼립 경재형 대표이사 △hy 변경구 대표이사 △오뚜기 황성만 대표이사 △정식품 정연호 대표이사-비상근이사△남양유업 김승언 대표이사 △보락 정기련 대표이사 △오리온 이승준 대표이사 △피엔에프에스 김홍규 대표이사 △해태제과식품 신정훈 대표이사-비상근감사△대평 김동주 대표이사 △일동후디스 이준수 대표이사◇신규선임-비상근이사△사조대림 김상훈 대표이사 △삼양식품 김동찬 대표이사 △서울에프앤비 오덕근 대표이사◇변경-비상근부회장△빙그레 김광수 대표이사발로 뛰는 더팩트는 24시간 여러분의 제보를 기다립니다.▶카카오톡: ''더팩트제보'' 검색▶이메일: jebo@tf.co.kr▶뉴스 홈페이지: http://talk.tf.co.kr/bbs/report/write', NULL, '더팩트', 'https://n.news.naver.com/mnews/article/629/0000476661', 'https://imgnews.pstatic.net/image/629/2026/02/27/202688971772170605_20260227145712179.png?type=w800', 'NEWS_ETC', NULL, '2026-02-27 14:57:12', 0, true, '2026-03-09 06:11:46.995178') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (892, '기업공시 [2월 23일]', '<코스피 공시>▲더존비즈온(012510)=1주당 12만 원에 발행 주식의 57.69%에 대한 도로니쿰의 공개매수 추진 ▲에코프로머티(450080)리얼즈=계열사 임원 박재하 2000주 장내 매도 ▲동부건설(005960)=신내동 493, 494번지 일대 모아타운 정비사업 시공사 선정 ▲영흥(012160)=자사주 소각을 통한 감자 결정 ▲SK네트웍스=업스테이지 470억 원 출자해 지분율 12.9%로 확대 결정 ▲보락(002760)=1주당 7원 결산배당(시가배당율 0.67%) 결정 ▲이구산업(025820)=1주당 90원 결산배당(시가배당율 1.67%) 결정<코스닥 공시>▲성호전자(043260)=부산 엘시티 랜드마크 타워동 저층부 1500억 원에 인수 ▲에스에스알(275630)=17억 원 규모 기취득 자사주 소각 결정 ▲디오=195억 원 규모 기취득 자사주 소각 결정 ▲대한광통신(010170)=유상증자 최종발행가액 2340원으로 결정 ▲케스피온(079190)=주식 병합 후 액면가액 500원에서 1000원으로 변경 ▲상보(027580)=주식 병합 후 액면가액 500원에서 2500원으로 변경 ▲도이치모터스(067990)=1주당 390원 결산배당(시가배당율 8.3%) 결정', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004592498', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2026-02-23 16:17:07', 0, true, '2026-03-09 06:11:46.995178') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (893, '[서울데이터랩]금일 코스피 거래량 1위 SG세계물산 거래대금 6천억원 돌파', '코스피 거래량 상위 종목들이 전반적으로 엇갈린 흐름을 보인다. 6일 한국거래소에 따르면, SG세계물산(004060)이 1억8백만주 이상 거래되며 코스피 종목 중 실시간 거래량 1위를 차지한다. 현재 주가는 531원으로, 시가총액의 약 55%에 해당하는 6천억원이 넘는 거래대금을 기록하며 19.33% 급등하고 있다. PER -26.55, ROE 2.10으로, 부정적인 재무지표에도 불구하고 급격한 투자 심리를 반영하고 있다. 한화솔루션(009830)은 2천5백만주 이상 거래되며 거래량 2위를 기록하며, 현재 주가는 40,350원으로 10.85% 상승세를 보이고 있다. 거래대금은 9천9백억원으로, 시가총액 대비 약 14%에 달하고 있으며, PER -16.14, ROE -15.99로 재무지표는 다소 부진한 상태이다.한편 삼성전자(005930)는 현재가 157,400원으로 1.19% 하락하며, 거래량 2천5백만주를 기록 중이다. 신성이엔지(011930)는 2,095원으로 0.48% 하락하였고, 거래량은 1천6백만주를 기록하고 있다. 서울식품(004410)은 147원으로 3.92% 하락하며 1천4백만주가 거래되었다. 일신석재(007110)는 1,849원으로 15.13% 급등하며 1천4백만주가 거래되었다. 한화갤러리아(452260)는 2,175원으로 0.46% 상승하며 1천만주 이상이 거래되고 있다. 한온시스템(018880)은 3,785원으로 6.08% 하락하며 8백9십만주가 거래되었다. 대한해운(005880)은 2,030원으로 5.36% 하락하며 7백만주 이상 거래되었다. 보락(002760)은 1,317원으로 0.45% 하락하며 6백만주가 넘는 거래량을 기록하고 있다.한편 거래량 상위 20위권 종목들은 미래에셋증권(006800) ▼4.64%, 에이프로젠(007460) ▼6.25%, 대우건설(047040) ▲2.21%, 두산에너빌리티(034020) ▼2.32%, KG모빌리티(003620) ▲1.79%, 신원(009270) ▲4.30%, SK하이닉스(000660) ▼0.36%, SK증권(001510) ▼3.56%, 대성산업(128820) ▼13.47%, 한화투자증권(003530) ▼4.52% 등의 성적을 기록했다.주목할 만한 종목으로는 SG세계물산과 일신석재가 있다. SG세계물산은 시가총액 대비 거래대금이 55%에 달하며, 급격한 매수세가 유입되어 주가가 19.33% 상승하고 있다. 일신석재 역시 시가총액의 1.8%에 해당하는 거래대금과 함께 15.13% 급등하며 투자자들의 관심을 받고 있다. 반면, 대성산업은 13.47% 하락하며 거래대금이 시가총액의 0.88%에 그치고 있으며, 한온시스템도 6.08% 하락하며 시가총액 대비 거래대금 비율이 0.09%에 불과하다.전반적으로 코스피 시장은 SG세계물산과 일신석재의 급등세가 눈에 띄는 가운데, 많은 종목들이 하락세를 보이며 혼조세를 띠고 있다. 이러한 시장 흐름은 투자자들 간의 매수·매도 공방이 치열하게 전개되고 있는 것으로 해석될 수 있다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003615292', 'https://imgnews.pstatic.net/image/081/2026/02/06/0003615292_001_20260206132123037.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-06 13:21:23', 0, true, '2026-03-09 06:11:46.995178') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (894, '“부동산 얼어붙었지만 여긴 예외”…학군지, 신고가 행진에 청약 열기 ‘후끈’', '‘래미안대치팰리스’ 역대 최고가 경신지방·청약시장서도 학군지 선호 ‘뚜렷’부산 학군지서는 116대 1 경쟁률도학교 교실 전경. 기사 내용과 관련 없음 [연합뉴스]부동산 시장이 조정을 겪는 국면에서도 학군 입지를 중심으로 한 수요는 좀처럼 꺾이지 않고 있다. 자산가들조차 주거지를 결정할 때 교육 환경을 최우선 가치로 두는 흐름이 뚜렷해지고 있다는 평가다.4일 국토교통부 실거래가 공개시스템에 따르면 서울의 대표적인 학군지인 강남구 대치동 ‘래미안대치팰리스’ 전용면적 84㎡는 지난해 11월 47억5000만원에 거래되며 역대 최고가를 경신했다.이러한 현상은 지방에서도 뚜렷하게 나타난다. ‘대구의 대치동’으로 불리는 수성구 범어동 ‘힐스테이트범어’ 전용 84㎡는 올해 1월 전년 동월 대비 2억 원 상승한 16억7250만원에 거래되며 일대 시세를 견인하고 있다.청약 시장에서도 비슷한 분위기가 감지되고 있다. 지난해 12월 서울 강남구 역삼동에서 공급한 ‘역삼센트럴자이’는 평균 487.1대 1의 높은 1순위 청약 경쟁률을 기록했다.앞서 서초구에서 공급한 반포래미안트리니원과 래미안원페를라도 각각 237.5대 1과 151.6대 1의 높은 경쟁률을 보이며 학군지의 위력을 입증한 바 있다.‘학군 불패’ 현상은 수도권에만 국한되지 않는다. 지방광역시에서도 전통적인 명문 학군을 중심으로 주택 수요가 몰리고 있다는 설명이다.실제 학군 프리미엄은 신규 분양 시장에서도 강력한 영향을 발휘하고 있다.부산에서 학군이 잘 형성된 해운대구 일원에서 지난해 7월 공급된 ‘르엘 리버파크 센텀’은 최고 116대 1의 청약 경쟁률을 기록했다. 같은 해 8월 부산 대연고 학군지인 남천동의 ‘써밋 리미티드 남천’ 역시 평균 23.6대 1로 청약 마감에 성공했다.미분양 적체로 고전하던 대구에서도 대표 학군지 수성구에서 지난해 7월에 분양한 ‘범어2차 아이파크’는 1순위 청약에서 75.2대 1의 경쟁률을 기록했다.‘해링턴 플레이스 오룡역’ 투시도. [진흥기업]이러한 가운데 진흥기업은 대전 중구 용두동 일원에 들어서는 ‘해링턴 플레이스 오룡역’을 이달 분양할 예정이다. 단지는 약 300m 이내에 목동초가 위치해 있으며, 대성중·고교를 비롯해 목양초, 충남여중·고 등 약 10여 개 학교가 밀집했다.학군으로 유명한 대구 수성구에서는 HS화성이 ‘범어역 파크드림 디아르’ 분양을 앞뒀다. 범어생활권은 명문 수성학군의 중심지로 학원가와 학교 등 교육 인프라가 밀집돼 있으며, 생활권 자체가 자녀 교육 중심으로 형성돼 교육 수요가 높은 세대의 선호도가 높다.자이에스에인디가 경북 상주시 함창읍 일원에 이달 분양 예정인 ‘상주자이르네’도 탄탄한 교육환경을 갖췄다. 단지 인근에는 함창초(그린스마트스쿨 2027년 완공예정), 함창중·고, 상지여중 등이 밀집해 있는 것은 물론 함창중·고는 농어촌특례입학이 가능하다.분양업계 관계자는 “명문 학군 아파트는 부동산 경기 불황 속에서도 꾸준히 몸값을 높이고 있다”며 “자녀 교육에 대한 투자를 아끼지 않는 30·40세대가 주택 시장의 핵심 수요층으로 자리 잡으면서 학군 프리미엄이 강력한 힘을 발휘하고 있다”고 짚었다.', NULL, '매일경제', 'https://n.news.naver.com/mnews/article/009/0005644797', 'https://imgnews.pstatic.net/image/009/2026/03/04/0005644797_001_20260304090510608.png?type=w800', 'NEWS_CONSTRUCT', NULL, '2026-03-04 09:05:10', 0, true, '2026-03-09 06:11:54.858527') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (895, '지방 부동산 침체에도…‘더블 역세권’은 다르다', '“주거 수요 높아 집값 상승 탄력 강해”진흥기업·HS화성 등 분양 앞둬해링턴 플레이스 오룡역 투시도. ⓒ진흥기업[데일리안 = 이수현 기자] 지방 부동산 시장 침체가 장기화하고 있지만 2개 이상의 노선을 걸어서 이용할 수 있는 역세권 단지는 가격이 상승하고 있다. 신축 아파트를 중심으로 입주와 동시에 지역 시세를 이끄는 대장주로 자리매김하고 있다.3일 국토교통부 실거래가 공개시스템에 따르면 대구 1·2호선 반월당역과 1·3호선 명덕역이 가까운 ‘청라힐스자이’ 전용 84㎡는 2020년 분양 당시 5억 중반대의 분양가였으나 지난 1월 8억1500만원에 거래됐다.이는 1월 기준 대구 수성구 평균 아파트 값인 6억376만원, 단지가 자리하는 중구의 평균 아파트값 5억1091만원보다 비싸다.단지는 지난 2020년 분양 당시 평균 141 대 1을 기록하며 대구 내 최고 경쟁률을 기록한 바 있는데 입주 후 가격으로도 반영되는 모양새다.부산에서는 1·2호선 서면역 더블 역세권인 부산진구 서면 롯데캐슬 엘루체가 인근 단지보다 1억원 이상 높은 시세를 형성하고 있다.단지는 분양가가 전용 84㎡ 기준 4억 후반~5억 초반이었으나 지난 1월 전용 84㎡가 최고 7억7000만 원에 거래되며 분양가 대비 약 30~40% 상승했다. 단지는 2019년 분양 당시 평균 42.82 대 1로 부산 청약 경쟁률 상위 3위에 이름을 올린 바 있다.더블 역세권 단지 가격 상승은 지방 주택 가격은 약세와 대비된다 . 한국부동산원 통계 기준 지난해 부산 아파트값은 0.88% 하락했고 부산진구는 1.33% 떨어졌다. 대구 또한 지난해 3.29% 하락했고 중구도 1.60% 가격이 내려갔다.한 부동산 전문가는 “부동산 시장이 불확실할수록 입지의 본질적 가치가 중요해진다”며 “지방의 더블 역세권 단지는 편리한 주거 환경 덕분에 수요가 꾸준해 가격 하방 경직성이 강하고 시장 회복기에는 상승 탄력이 높다”고 분석했다.이러한 가운데 지방 더블 역세권 단지가 공급을 앞두고 있다. 진흥기업은 대전 중구 용두동에 공급하는 ‘해링턴 플레이스 오룡역’를 분양한다.단지는 대전 지하철 1호선 오룡역과 인접한 초역세권 입지를 갖추고 있으며 향후 도보권 내에 충청권 광역철도가 정차할 용두역이 신설될 예정이다. 한 정거장 거리인 서대전네거리역에는 대전 도시철도 2호선 트램이 2028년 개통 예정이다.대구에서는 HS화성이 수성구 수성동4가 일원 광명아파트 재건축 사업으로 공급하는 ‘범어역 파크드림 디아르’가 더블 역세권 입지를 갖추고 있다. 이달 분양 예정인 이 단지는 전용 73~138㎡, 총 158가구 규모(일반분양 47가구)로 조성되며 대구 도시철도 2호선 범어역과 대구은행역이 도보권이다.부산에서는 올해 현대건설이 부산진구 범천동 일원에 공급할 예정인 ‘범천1-1구역(가칭)’도 더블 역세권 입지를 갖추고 있다. 단지는 부산도시철도 1호선 범내골역과 2호선 국제금융센터·부산은행역을 도보로 이용할 수 있다. 단지는 최근 착공식을 진행한 것으로 전해졌으며 최고 49층, 총 1509가구로 조성된다.', NULL, '데일리안', 'https://n.news.naver.com/mnews/article/119/0003064470', 'https://imgnews.pstatic.net/image/119/2026/03/03/0003064470_001_20260303070016490.jpg?type=w800', 'NEWS_CONSTRUCT', NULL, '2026-03-03 07:00:16', 0, true, '2026-03-09 06:11:54.858527') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (896, '아모레퍼시픽, K뷰티 인디 브랜드 발굴사업 공모', '아모레퍼시픽 제공아모레퍼시픽이 뷰티·웰니스 인디 브랜드 발굴을 위한 개방형 혁신(오픈 이노베이션 프로그램) ‘뉴뷰티 이노베이션 챌린지’를 진행한다고 9일 밝혔다.이 프로그램은 참신한 브랜드와 기술을 조기에 발굴하고 사업화를 지원하는 사업이다. 아모레퍼시픽은 브랜드 전략, 제품 개발, 제조 및 생산, 유통 채널 등 전사 역량을 기반으로 스타트업의 실질적인 성장을 돕는 인큐베이팅 체계를 운영하고 있다.올해는 오는 4월 5일까지 공모한다. 모집 분야는 △스킨케어·메이크업·헤어케어 등 뷰티 브랜드 △이너뷰티·헬스케어 등 웰니스 브랜드 △뷰티 디바이스 브랜드 등이다. 기술 기반 브랜드는 중소벤처기업부 기술창업 지원 프로그램 팁스(TIPS) 추천도 검토한다. 설립 2년 이내 초기 브랜드를 위한 ''루키 리그''를 신설해 잠재력 높은 브랜드도 발굴한다.관련한 세부 내용과 신청 방법은 아모레퍼시픽 벤처스 공식 홈페이지에서 확인할 수 있다.', NULL, '부산일보', 'https://n.news.naver.com/mnews/article/082/0001369978', 'https://imgnews.pstatic.net/image/082/2026/03/09/0001369978_001_20260309151113560.JPG?type=w800', 'NEWS_CHEM', NULL, '2026-03-09 15:11:13', 0, true, '2026-03-09 06:12:01.995432') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (897, '아모레퍼시픽홀딩스, 우선주 6만2598주 소각 결정', '아모레퍼시픽홀딩스는 주주가치 제고를 위해 기보유 자기주식인 1우선주 6만2598주를 소각하기로 결정했다고 9일 공시했다.소각 예정 금액은 7억8247만5000원이며 소각 예정일은 다음 달 2일이다.이번 소각은 상법 제343조에 따른 자기주식 소각으로 자본금 감소 없이 발행주식총수만 줄어든다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000080536', 'https://imgnews.pstatic.net/image/293/2026/03/09/0000080536_001_20260309145409482.png?type=w800', 'NEWS_CHEM', NULL, '2026-03-09 14:54:09', 0, true, '2026-03-09 06:12:01.995432') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (905, '김정돈 미원홀딩스 회장, 미원상사 주식 외손자에 양도', '미원상사는 김정돈 미원홀딩스 회장이 자사 보통주 2만3257주를 지난 2일 각각 2007년·2011년생인 외손자 두 명에게 양도했다고 5일 공시했다.김정돈 회장의 미원상사 주식은 87만600주에서 84만3743주로 줄었다. 보유 지분율은 18.33%에서 17.84%로 0.49%포인트 하락했다.주식을 양도받은 이들은 2007년생인 강민석 군과 2011년생인 강윤석 군이다. 이들은 김정돈 회장의 첫째 딸인 소영씨와 사위인 강신우 미원상사 대표의 자녀들이다.강민석 군의 미원상사 지분은 기존 6286주에서 1만4014주가 늘어 2만300주가 됐다. 강윤석 군은 5457주에서 9243주를 받아 1만4700주다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000078974', 'https://imgnews.pstatic.net/image/293/2026/02/05/0000078974_001_20260205105109807.png?type=w800', 'NEWS_CHEM', NULL, '2026-02-05 10:51:09', 0, true, '2026-03-09 06:12:25.459631') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (898, '아모레퍼시픽, K-뷰티 선도 스타트업 발굴 ''뉴뷰티 이노베이션 챌린지'' 공모', '아모레퍼시픽아모레퍼시픽은 뷰티·웰니스 인디 브랜드 발굴 오픈 이노베이션 프로그램 ''뉴뷰티 이노베이션 챌린지''를 개최한다고 9일 밝혔다.''뉴뷰티 이노베이션 챌린지''는 빠르게 변하는 시장 환경에서 참신한 브랜드와 기술을 조기에 발굴해 사업화까지 연결하는 것을 목표로 한다. 아모레퍼시픽은 브랜드 전략, 제품 개발, 제조 및 생산, 유통 채널 등 전사 역량을 기반으로 스타트업의 실질적인 성장을 돕는 인큐베이팅 체계를 운영하고 있다.올해는 설립 2년 이내 초기 스타트업을 위한 ''루키 리그''를 새롭게 도입해 인큐베이팅 스펙트럼을 높였다. 공모는 4월 5일까지이며 모집 분야는 △뷰티 브랜드(스킨케어, 메이크업, 헤어케어 등) △웰니스 브랜드(이너뷰티, 헬스케어) △뷰티 디바이스 브랜드 등이다. 기술 기반 브랜드의 경우 중소벤처기업부 팁스(TIPS) 추천 기회도 검토된다.정다은 기자 dandan@etnews.com', NULL, '전자신문', 'https://n.news.naver.com/mnews/article/030/0003405466', 'https://imgnews.pstatic.net/image/030/2026/03/09/0003405466_001_20260309103312107.jpg?type=w800', 'NEWS_CHEM', NULL, '2026-03-09 10:33:12', 0, true, '2026-03-09 06:12:01.995432') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (899, '기업 공시[2월 12일]', '<코스피 공시>▲일진전기(103590)=1100억 원 규모 태양광 발전사업 공사 도급계약 ▲LG씨엔에스(064400)=2409억 원 규모 고양 IT플랫폼센터 구축공사 수주 ▲삼영무역(002810)=자사주 18만 주 처분 결정 ▲대신증권(003540)=자사주 1535만 주 소각 결정 ▲더블유게임즈(192080)=주당 1200원 현금 결산 배당 결정 ▲씨케이솔루션(480370)=보통주 1주당 신주 2주 배정 무상증자 결정 ▲카카오(035720)=지난해 연결 기준 매출 8조 991억 원(전년 대비 3%), 영업익 7320억 원(48%)<코스닥 공시>▲휴젤(145020)=이달 26일까지 기업설명회(IR) 개최 ▲영우디에스피(143540)=삼성디스플레이와 46억 원 규모 장비 공급계약 체결 ▲컴투스(078340)=주당 1300원 현금 결산 배당 결정 ▲플리토(300080)=지난해 매출액 360억 원(77%), 영업이익 62억 원(흑자 전환)', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004589896', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2026-02-12 16:52:21', 0, true, '2026-03-09 06:12:10.659968') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (900, '[애프터마켓 브리핑] 마이크론 급등·필라델피아 지수↑…국내 반도체주 강세', '■ 머니쇼+ ''애프터마켓 브리핑'' - 김유민애프터마켓 브리핑입니다.오늘(12일) 코스피는 대형주 중심으로 수급이 쏠리면서 상승 마감했고, 코스닥도 마찬가지로 상승으로 마감했습니다.오늘부터 NXT에서 거래되는 종목들이 650개로 축소되며 거래량 상위 50개 종목들은 제외됐는데, 현재 애프터마켓 분위기는 어떤지 짚어보겠습니다.시가총액 순위권 종목들부터 보겠습니다.간밤 마이크론이 급등했는데, 경쟁사인 국내 반도체주들도 좋은 흐름 보여주고 있습니다.삼성전자는 장 마감 직전에 HBM4 출하를 세계 최초로 시작했다는 소식 전해지면서, 20만 원을 목표로 달려가고 있습니다.현재가는 179,000원에 거래되고 있습니다.SK하이닉스도 정규장보다 조금 오른 890,000원에 거래되고 있습니다.현대차는 어제(11일) 50만 원선 회복했는데 오늘 조정받고 있습니다.그래도 애프터마켓에서 50만 원선 지켜내고 있습니다.현재 거래가는 505,000원입니다.LG에너지솔루션은 오늘 개별적인 모멘텀이 있었습니다.일부 언론에 따르면, 아틀라스에 배터리를 공급해 온 것으로 전해지면서 주가는 현재 406,500원에 육박합니다.다음으로 상승률 1위에서 5위 종목들 보겠습니다.홈쇼핑 관련주 태광산업이 상승률 1위로, 현재 23.84% 올라가고 있습니다.2위는 아이센스로, 혈당측정기 부문 매출이 예상치를 상회하면서 어제 호실적 발표했는데요.현재 20% 가까이 올라가며 23,050원에 거래되고 있습니다.오늘 호실적을 발표한 파미셀도 20% 가까이 올라가며 17,460원에 거래되고 있고요.폰드그룹도 호실적 발표하자 애프터마켓에서 17.43%로 상승폭 더 키우고 있습니다.현재 순위권에 없는 현대지에프홀딩스도 연일 강세입니다.현대홈쇼핑을 완전 자회사 전환한다고 밝힌 이후부터 지금도 상승 흐름 이어가고 있습니다.넥슨게임즈도 장 마감 후 상승으로 전환했습니다.또, 삼영무역은 4시에 급등했습니다.자기 주식 18만 주 처분 소식에 NXT에서 크게 올랐고요.대신증권도 자사주 1535만 주를 단계적으로 소각한다는 소식이 나오자마자 애프터마켓에서 급등했습니다.이어서 하락률 순위권 종목들도 함께 보겠습니다.하락률 1위는 SAMG엔터로, 현재 10% 넘게 밀리면서 40,650원에 거래되고 있습니다.어제장에서는 티니핑 효과로 호실적 발표하며 급등 움직임 보였는데, 오늘은 크게 빠집니다.이마트도 새벽 배송 기대감으로 연일 올랐는데 현재 하락률 3위입니다.8.15% 하락한 117,200원에 거래되고 있습니다.현재 순위권에 없는 컴투스는 영업이익이 급감하자 NXT서 낙폭을 더 키웠습니다.숲도 조금 전에 실적 발표했죠.발표 후 애프터마켓에서 급락했습니다.마지막으로 거래량 동반해서 움직이는 종목들도 체크해 보겠습니다.삼성전자, 현재 179,300원에 거래되며, 18만 원선을 목전에 두었습니다.파미셀은 현재 17,350원에 거래되고 있습니다.정규장 마감 후 추가적으로 상승했고요.카카오는 역대 최대 실적 발표하면서 주가가 민감하게 반응합니다.구글과의 파트너십 기대감까지 받으며 거래 활발합니다.현재 59,000원에 거래되고 있습니다.이렇게 애프터마켓 흐름부터 특징주까지 살펴봤는데요.오늘 밤 열리는 뉴욕증시는 안자은 캐스터와 함께 대비해 보시죠.지금까지 애프터마켓 브리핑이었습니다.당신의 제보가 뉴스로 만들어집니다.SBS Biz는 여러분의 제보를 기다리고 있습니다.홈페이지 = https://url.kr/9pghjn', NULL, 'SBS Biz', 'https://n.news.naver.com/mnews/article/374/0000492430', 'https://imgnews.pstatic.net/image/374/2026/02/12/0000492430_001_20260212164616212.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-12 16:46:16', 0, true, '2026-03-09 06:12:10.659968') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (901, '[마켓인]선앤엘, 20억에 산 이루팩 적자는 29억…신사업 추진 ‘삐걱’', '선앤엘, 다각화 위해 지난해 이루팩 인수이루팩, 3Q까지 23억 적자…작년 포함 29억연결실적 부담 가중…자회사 12곳 중 10곳 손실별도 실적도 3년 연속 적자…유동성도 ''노란불''이 기사는 2025년12월31일 17시04분에마켓인 프리미엄 콘텐츠로 선공개 되었습니다.[이데일리 마켓in 이건엄 기자]SUN&L(002820)(이하 선앤엘)이 인수한 이루팩이 적자의 늪에서 벗어나지 못하면서 투자금보다 더 큰 손실을 떠안게 됐다. 생활뷰티 사업에 주력하기 위해 20억원을 투입해 이루팩을 인수했지만 누적 적자가 30억원에 달하면서 선앤엘에 오히려 부담으로 작용하고 있다는 분석이다. 특히 선앤엘의 자회사 대부분이 적자를 기록하고 있다는 점에서 이루팩의 부진이 더욱 뼈아프다는 평가가 나온다.(사진=선앤엘)31일 금융감독원 전자공시시스템에 따르면 이루팩은 올해 3분기까지 23억원의 적자를 기록했다. 지난해 선앤엘에 인수된 이후 기록한 적자까지 포함하면 총 29억원의 손실을 냈다. 선앤엘이 이루팩을 20억원에 인수한 점을 고려하면 투자금을 모두 까먹고도 10억원 가까이 손해를 본 셈이다.선앤엘은 지난해 6월 이루팩 지분 66.7%(20만주)를 20억원에 취득했다. 2009년 설립된 이루팩은 화장품 기초·색조 용기 전문 제조업체로, 콤팩트와 립글로스 등 화장품 용기 생산 노하우를 보유하고 있다는 평가를 받아왔다. 주요 거래처로는 애경산업 등이 있다.누적 적자가 이어지면서 이루팩의 재무 구조도 빠듯해진 상황이다. 올해 3분기 말 연결 기준 이루팩의 자산총계는 약 129억원, 부채총계는 약 121억원으로 자본 여력이 크지 않은 상태다. 이 같은 구조에서 적자가 지속될 경우 자본총계가 0 이하로 떨어지는 완전자본잠식으로 이어질 가능성도 제기된다.이는 이루팩을 필두로 생활뷰티 사업으로 포트폴리오 다각화를 추진 중인 선앤엘에 부담이 될 수밖에 없다. 선앤엘은 목재 사업을 줄이는 한편 오는 2026년까지 해외 매출 비중 50% 달성을 목표로 화장품 패키징 사업 강화를 추진하고 있다. K-뷰티의 글로벌 성장세에 대응해 친환경·고기능 패키징 기술 투자와 생산 설비 확대를 이어간다는 설명이다.문제는 이루팩의 부진이 신사업 추진 과정에서 부담으로 작용하는 데 그치지 않고 선앤엘의 연결 실적 부담을 키우고 있다는 점이다. 선앤엘은 자회사 12곳 중 10곳이 적자를 기록할 정도로 분위기가 좋지 않다.실제 선앤엘 자회사 12곳의 올해 3분기 누적 총포괄손실은 77억원으로 전년 동기 26억원 대비 3배 가까이 증가했다. 세부적으로 보면 포괄이익은 3억원에 그친 반면 포괄손실은 80억원에 달했다.자회사 가운데 인테리어 부문을 담당하는 선앤엘인테리어가 43억원의 손실을 기록하며 적자 규모가 가장 컸고, 이루팩이 23억원의 손실로 뒤를 이었다. 즉 이루팩의 손실이 전체 자회사 손실에서 차지하는 비중이 30%에 달하는 셈이다. 반면 선앤엘 쿤산 플라스틱 프로덕츠와 선앤엘 인테리어 캐나다법인 등 2곳만이 흑자를 냈다.이처럼 자회사들의 적자 행진이 이어지는 상황에서 선앤엘 자체 수익성도 회복될 기미를 보이지 않아 우려는 더욱 크다. 부동산 경기 침체와 원자재 부담 확대로 주력인 목재 사업에서 수익성 개선에 어려움을 겪고 있기 때문이다.선앤엘은 지난 2022년부터 별도 기준으로도 3년 연속 적자를 이어오고 있다. 올해 3분기에도 누계기준 50억원의 영업손실을 기록한 점을 고려하면 4년 연속 적자가 유력하다는 평가다. 이 여파로 이익잉여금도 모두 소진돼 올해 3분기 말 기준 869억원의 결손금을 쌓은 상태다. 유동성 사정 역시 녹록지 않아 같은 기간 유동비율은 91.3%에 그쳤다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006193089', 'https://imgnews.pstatic.net/image/018/2026/01/01/0006193089_001_20260101050614806.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-01 05:06:14', 0, true, '2026-03-09 06:12:17.909797') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (902, 'SUN&L, 최대주주 등 보유주식 1245주 증가', '선앤엘(SUN&L)은 31일 ''최대주주등소유주식변동신고서''를 통해 최대주주 등의 보유주식 변동 내역을 공시했다.공시에 따르면 직전보고서 제출일(2025년10월29일) 기준 최대주주 등의 보통주 보유 주식 수는 590만8737주(46.86%)였으나, 이번 보고서 제출일(2025년12월31일) 기준 590만9982주(46.87%)로 1245주 증가했다. 이에 따라 지분율은 46.86%에서 46.87%로 0.01%p 상승했다. 발행주식총수는 1260만7989주다.개인별 세부 변동사항을 보면 발행회사 임원인 김남수가 11월20일 장내매수를 통해 보통주 1245주를 취득했다. 김남수의 보유 주식 수는 기존 4만6554주에서 4만7799주로 늘었다.최대주주등 주식소유현황(총괄현황) 기준으로 정연준은 보통주 290만8431주(23.07%)를 보유하고 있으며, 김남수는 4만7799주(0.38%)를 보유하고 있다. 최대주주등의 합계 보유 주식 수는 590만9982주로 지분율 46.87%다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000077197', 'https://imgnews.pstatic.net/image/293/2025/12/31/0000077197_001_20251231104811246.png?type=w800', 'NEWS_ETC', NULL, '2025-12-31 10:48:11', 0, true, '2026-03-09 06:12:17.909797') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (903, '[서울데이터랩]‘이화산업’ 29.98% 상한가…실시간 상승률 1위', '28일 오전 9시 10분 이화산업(000760)가 등락률 +29.98%로 상승률 1위를 차지했다. 이화산업(000000)은 개장 직후 5분간 70,919주가 거래되었으며 주가는 공모가 대비 3,910원 오른 16,950원이다.한편 이화산업의 PER은 -50.00으로 나타나며, ROE는 0.46%로 수익성이 낮다고 평가될 수 있다.이어 상승률 2위 천일고속(000650)은 현재가 236,500원으로 주가가 29.80% 폭등하고 있다. 상승률 3위 신영와코루(005800)는 현재 19,970원으로 25.05% 폭등하며 강세를 보이고 있다. 상승률 4위 세기상사(002420)는 20.72% 급등하며 7,050원에 거래되고 있다. 상승률 5위 대림통상(006570)은 16.73%의 상승세를 타고 2,860원에 거래되고 있다.6위 코아스(071950)는 현재가 4,470원으로 11.75% 급등 중이다. 7위 금강공업우(014285)는 현재가 10,930원으로 8.54% 상승 중이다. 8위 HL만도(204320)는 현재가 46,600원으로 8.12% 상승 중이다. 9위 SK(034730)는 현재가 272,000원으로 7.09% 상승 중이다. 10위 동양고속(084670)은 현재가 15,660원으로 6.53% 상승 중이다.이밖에도 프레스티지바이오파마(950210) ▲5.88%, 삼성에피스홀딩스(0126Z0) ▲5.75%, 전방(000950) ▲5.58%, KIWOOM 코스닥150선물레버리지(291630) ▲5.58%, 한온시스템(018880) ▲5.54%, SK우(03473K) ▲5.34%, 삼양바이오팜(0120G0) ▲4.87%, 이연제약(102460) ▲4.70%, 대성산업(128820) ▲3.99%, SUN&L(002820) ▲3.89% 등을 기록하며 시장에서 활발히 거래되고 있다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003596293', 'https://imgnews.pstatic.net/image/081/2025/11/28/0003596293_001_20251128094118744.png?type=w800', 'NEWS_ETC', NULL, '2025-11-28 09:41:18', 0, true, '2026-03-09 06:12:17.909797') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (904, '미원상사, 주당 1400원 현금배당 결정', '[헤럴드경제=증권부] 미원상사는 보통주 1주당 1400원의 현금 결산배당을 결정했다고 4일 공시했다.시가배당율은 0.9%이며 배당금총액은 63억5600만원이다.', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002608390', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_CHEM', NULL, '2026-03-04 16:18:07', 0, true, '2026-03-09 06:12:25.459631') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (906, '기업 공시 [12월 9일]', '[서울경제]<코스피 공시>▲에이피알(278470)=모건 스탠리 지분 59만 1735주(1.59%) 장내 매도 ▲미원상사(002840)=10%이상 주주인 김정돈 2191주(0.05%) 장내 매도<코스닥 공시>▲흥국(010240)=기취득 자기주식 61만 6696주 소각 결정, 32억 원 규모 ▲다우데이터=오르비스인베스트먼트 48만 1926주(1.26%) 장내에서 추가 매수, 단순 투자 목적', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004565265', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_CHEM', NULL, '2025-12-09 16:26:17', 0, true, '2026-03-09 06:12:25.459631') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (907, '신풍, 2025년 영업손실 23억원…적자폭 48% 축소', '신풍은 30일 2025사업연도 연결 기준 매출액 또는 손익구조가 전년 대비 30% 이상 변경됐다고 공시했다.공시에 따르면 2025년 연결 매출액은 242억2806만원으로 전년 227억7845만원 대비 6.4% 증가했다.영업이익은 -22억9334만원으로 전년 -43억6569만원에서 적자 폭이 47.5% 축소됐다. 법인세비용차감전계속사업이익은 28억5646만원으로 전년 3억0896만원 대비 824.5% 증가했고, 당기순이익도 28억5646만원으로 같은 폭 늘었다. 회사는 영업손실 감소와 금융수익 증가가 순이익 확대에 영향을 미쳤다고 설명했다.재무상태를 보면 2025년 말 연결 자산총계는 773억4462만원으로 전년 753억1758만원 대비 증가했다. 부채총계는 28억3887만원으로 전년 36억0093만원 대비 감소했고, 자본총계는 745억0575만원으로 전년 717억1665만원 대비 늘었다. 자본금은 174억7935만원이다.매출 증가 요인으로는 2024년 도입한 신규 설비 효과로 지류유통 부문 판매량이 증가한 점을 제시했다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000078663', 'https://imgnews.pstatic.net/image/293/2026/01/30/0000078663_001_20260130133306422.png?type=w800', 'NEWS_ETC', NULL, '2026-01-30 13:33:06', 0, true, '2026-03-09 06:12:32.580833') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (908, '[서울데이터랩]동부건설우 30.00% 상한가 금일 증시 상승률 1위로 마감', '17일 오후 3시 35분 동부건설우(005965)가 등락률 +30.00%로 상승률 1위로 마감했다. 동부건설우는 장 중 48,914주가 거래되었으며 주가는 공모가 대비 7,800원 오른 33,800원에 마감했다.한편 동부건설우의 PER은 512.12로 높은 수준을 보이며, 이는 회사의 주가가 실적 대비 과대평가되었을 가능성을 시사한다.이어 상승률 2위 한화갤러리아(452260)는 주가가 30.00% 상한가를 기록하며 종가 1,443원에 상승 마감했다. 상승률 3위 금호건설우(002995)의 주가는 38,600원으로 29.97% 폭등하며 주목받았다. 상승률 4위 동양고속(084670)은 29.96% 상승하며 133,600원에 마감했다. 상승률 5위 대성산업(128820)은 29.89%의 상승세를 타고 종가 10,430원에 마감했다.6위 한화갤러리아우(45226K)는 종가 2,720원으로 29.83% 상승 마감했다. 7위 메타랩스(090370)는 종가 2,025원으로 29.72% 상승 마감했다. 8위 해성디에스(195870)는 종가 58,500원으로 19.27% 상승 마감했다. 9위 진흥기업우B(002785)는 종가 4,550원으로 16.37% 상승 마감했다. 10위 아이에스동서(010780)는 종가 24,700원으로 12.79% 상승 마감했다.이밖에도 한세실업(105630) ▲10.35%, 현대위아(011210) ▲9.52%, 신풍(002870) ▲8.52%, LF(093050) ▲7.83% 등을 기록하며 금일 증시를 상승으로 마감했다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003601751', 'https://imgnews.pstatic.net/image/081/2025/12/17/0003601751_001_20251217154311523.jpg?type=w800', 'NEWS_ETC', NULL, '2025-12-17 15:43:11', 0, true, '2026-03-09 06:12:32.580833') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (909, '[서울데이터랩]코오롱모빌리티그룹 29.95% 상한가 금일 증시 상승률 1위로 마감', '5일 오후 3시 35분 코오롱모빌리티그룹(450140)이 등락률 +29.95%로 상승률 1위로 마감했다. 코오롱모빌리티그룹은 장 중 2,959,251주가 거래되었으며 주가는 전 거래일 대비 2,420원 오른 10,500원에 마감했다.한편 코오롱모빌리티그룹의 PER은 -159.09로 나타났으며, ROE는 -5.62%로 부정적인 수익성을 보였다.이어 상승률 2위 일동홀딩스(000230)는 주가가 +29.94% 폭등하며 종가 11,760원에 상승 마감했다. 상승률 3위 코오롱모빌리티그룹우(45014K)의 주가는 36,100원으로 +29.86% 폭등하며 강세를 보였다. 상승률 4위 코리아써키트(007810)는 +12.94% 급등하며 22,700원에 마감했다. 상승률 5위 디아이씨(092200)는 +10.08%의 상승세를 타고 종가 6,990원에 마감했다.6위 대덕전자(353200)는 종가 43,200원으로 +9.64% 상승 마감했다. 7위 SJG세종(033530)은 종가 9,200원으로 +9.26% 상승 마감했다. 8위 코리아써우(007815)는 종가 8,240원으로 +8.56% 상승 마감했다. 9위 일정실업(008500)은 종가 18,320원으로 +8.53% 상승 마감했다. 10위 에이프로젠(007460)은 종가 662원으로 +7.82% 상승 마감했다.이밖에도 해성디에스(195870) ▲7.45%, 한올바이오파마(009420) ▲7.38%, 대덕전자1우(35320K) ▲7.36%, 일동제약(249420) ▲6.57%, 에이프로젠바이오로직스(003060) ▲6.00%, 신풍(002870) ▲5.65%, 삼성화재(000810) ▲5.51%, 명인제약(317450) ▲5.08%, 대한항공우(003495) ▲4.40%, 인디에프(014990) ▲4.39% 등을 기록하며 금일 증시를 상승으로 마감했다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003588754', 'https://imgnews.pstatic.net/image/081/2025/11/06/0003588754_001_20251106163114019.png?type=w800', 'NEWS_ETC', NULL, '2025-11-06 16:31:14', 0, true, '2026-03-09 06:12:32.580833') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (910, '대유에이텍, 박은진 대표 신규선임…각자대표 체제 전환', '대유에이텍은 31일 대표이사(대표집행임원) 변경 안내공시를 통해 기존 임근호 단독 대표이사 체제에서 임근호·박은진 각자대표 체제로 변경됐다고 공시했다.변경 사유는 대표이사 신규선임에 따른 각자대표 체제 전환이다. 변경일자는 2026년1월1일이다. 회사는 이사회 결의에 따른 선임일자가 2025년12월31일이고 변경일자는 취임일자라고 밝혔다. 회사는 대표이사를 각자 대표이사로 운영한다고 공시했다.임 대표이사의 주요 경력은 △현대정공(주) 근무 △(주)대유에이텍 품질관리·생산관리 팀장 △(주)대유홀딩스 우레탄사업부 사업부장 △(주)대유글로벌 대표이사 등이다. 박 대표의 주요 경력은 △매일경제 편집국 기자 △대유에이텍 부사장 등이다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000077218', 'https://imgnews.pstatic.net/image/293/2025/12/31/0000077218_001_20251231153111427.png?type=w800', 'NEWS_AUTO', NULL, '2025-12-31 15:31:08', 0, true, '2026-03-09 06:12:40.539570') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (911, '힘쎈충남, 18개 기업서 4355억 투자 유치', '2030년까지 6개 시군 산업단지에 생산시설 신·증설…신규 고용 899명 창출김태흠 충남지사충남도가 국내외 기업 투자 유치를 핵심 성장 전략으로 삼아 온 가운데, 18개 기업으로부터 총 4355억 원 규모의 투자를 끌어내며 지역 산업 경쟁력 강화에 속도를 내고 있다.도는 이번 투자로 첨단산업과 제조업 전반의 기반 확충 및 고용과 생산 유발 효과도 본격화될 전망이다.도는 23일 도청 대회의실에서 6개 시군 단체장 또는 부단체장과 18개 기업 대표가 참석한 가운데 투자협약을 체결했다.협약에 따라 18개 기업은 오는 2030년까지 천안·아산·서산·당진·서천·예산 등 6개 시군 산업단지와 개별 입지 28만 9360㎡ 부지에 총 4355억 원을 투자해 생산시설을 신·증설하거나 이전한다. 신규 고용 인원은 899명에 달한다.천안에는 자동차·반도체·이차전지 관련 기업들의 투자가 집중된다. 자동차 기계부품 업체 이화다이케스팅은 350억 원을 투입해 평택 공장을 천안 북부BIT일반산단으로 이전하며, 이차전지 전고체 업체 엔플로우는 160억 원을 투자해 신규 공장을 신설한다.또 유제품·반려동물 우유 업체 유담도 335억 원을 들여 생산시설을 확장 이전한다.반도체 제조 장비 분야에서는 디앤디테크솔루션(310억 원)과 서우테크놀로지(285억 원)가 각각 공장을 신설·확장하고, 자동차 브레이크 부품 업체 제이디테크(200억 원), 화학공정 설비 업체 케이엠제이(100억 원)도 이전·증설에 나선다.아산에는 자동차 시트 업체 대유에이텍(451억 원), 반도체 웨이퍼 재생 및 실리콘 부품 업체 에이텍솔루션(650억 원), 보일러 업체 귀뚜라미(200억 원) 등이 대규모로 투자한다.서산에서는 자동차 부품 업체 동해금속이 111억 원을 투자해 공장을 증설한다.당진 석문국가산단에는 전지대두 업체 휠라선이 620억 원을 들여 인천 공장을 이전하고, 재생구리·재생알루미늄 업체 티지와이는 291억 원을 투자해 신규 공장을 짓는다.서천에는 화장지·물티슈 업체 연우와 화학작용제 탐지장비 업체 센서테크가 각각 공장을 신·증설하며, 예산에는 보호필름 업체 엠비머티리얼즈가 신규 투자를 확정했다.도는 이번 투자로 생산 유발 효과 6000억 원, 부가가치 유발 2500억 원, 고용 유발 효과 3400명에 이를 것으로 내다봤다.김태흠 지사는 "이번 협약으로 충남은 국내외 317개 기업으로부터 총 43조 7200억 원이 넘는 투자를 유치하게 됐다"며 "이차전지·반도체·자동차 등 첨단산업 경쟁력을 높이는 동시에 제조업 구조 다변화의 전환점이 될 것"이라고 밝혔다.이어 "입지·설비 보조금, 인허가, 인력 공급까지 기업 투자가 성공으로 이어지도록 전방위 지원하겠다"고 강조했다.', NULL, '아시아경제', 'https://n.news.naver.com/mnews/article/277/0005697880', 'https://imgnews.pstatic.net/image/277/2025/12/23/0005697880_001_20251223165320417.jpg?type=w800', 'NEWS_AUTO', NULL, '2025-12-23 16:52:20', 0, true, '2026-03-09 06:12:40.539570') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (912, '대유에이텍, 울산  부지 매입…현대차 1차 벤더 지위 확보[only 이데일리]', '대유에이텍, 시트패드 업체 정운 공장 인수울산 반천반송산업단지 내 부지기아·현대트랜시스 이어 현대차까지 납품대유위니아그룹 공중분해 여파 상쇄하나이 기사는 2025년12월23일 14시58분에마켓인 프리미엄 콘텐츠로 선공개 되었습니다.[이데일리 마켓in 이건엄 기자] 기아(000270)에 자동차 시트를 납품하는 대유에이텍(002880)이 현대차(005380)에 부품 공급을 위해 울산 지역 공장 부지를 매입한 것으로 확인됐다. 기존 거점인 광주광역시와 경기 서남부를 넘어 울산에 새로운 생산 기반을 구축했다. 특히 기아에 이어 현대차 1차 협력사 지위까지 확보했다는 점에서 의미가 크다는 평가다.대유에이텍 직원들이 현대자동차 경형 스포츠 유틸리티 차량(SUV) ‘캐스퍼’ 차량 전용 시트 조립 라인에서 작업 중이다.(사진=대유에이텍)23일 이데일리 단독 취재에 따르면 대유에이텍은 울산광역시 울주군 언양읍 반천반송산업단지 내에 위치한 공장 부지를 인수했다. 현재 부지 매매 계약을 완료하고 시설 정비와 생산 설비 구축을 순차적으로 진행하고 있는 것으로 알려졌다.해당 공장은 그동안 현대차에 시트 패드를 납품해 온 정운이 사용하던 시설로 대유에이텍은 기존 공장을 그대로 인수해 현대차 전용 생산 라인으로 활용할 계획이다. 대유에이텍은 공장 정비와 준비 작업을 거쳐 준공 이후 현대차에 시트에 들어가는 패드 납품을 시작할 예정이다.앞서 지난 6월 대유에이텍은 현대차로부터 부품 공급업체로 선정됐다고 공시한 바 있다. 납품 차종은 SX3로, 현대차 소형 스포츠유틸리티차량(SUV) ‘코나’의 후속 모델로 알려졌다. 납품 품목은 차량용 의자 패드(SEAT PAD ASSY)로 이번에 인수한 공장 부지의 활용과 정확히 일치한다.시장에서는 대유에이텍이 이번 부지 인수와 함께 현대차 1차 협력사 지위를 확보했다는 점에서 의미가 남다르다고 보고 있다. 기아를 중심으로 이어온 납품 구조에서 벗어나 현대차 울산공장에 부품을 직접 공급하며 지속가능한 성장 기반을 마련했기 때문이다.대유에이텍은 현대차그룹 내에서는 주로 기아 납품에 집중해 왔다. 대유에이텍의 시트가 현대차 차량에 적용된 사례는 광주글로벌모터스에서 생산되는 캐스퍼와 현대트랜시스를 통한 간접 납품을 제외하면 미미한 수준이었다.특히 수익성 악화를 겪고 있는 대유에이텍 입장에선 현대차 납품을 통해 실적 개선과 재무건전성 회복에도 긍정적 요인이 될 것으로 보인다. 대유에이텍은 대유위니아그룹 계열사들이 잇달아 파산한 여파로 현금 유출이 지속돼 부진을 이어가고 있다.실제 대유에이텍의 올해 3분기 누계 기준 영업이익은 271억원으로 전년 동기 324억원 대비 16.4% 감소했다. 재무건전성도 좋지 않다. 대유에이텍의 올해 3분기 말 기준 차입금의존도와 순차입금비율은 각각 33%, 224.1%로 적정 수준을 상회하고 있다. 단기 현금 동원능력을 보여주는 유동비율도 44.7%에 불과해 안전하다고 판단되는 150%를 크게 밑돌고 있다.대유에이텍 관계자는 “현대차 울산공장에 시트 패드 납품을 위해 공장 부지를 인수하게 됐다”며 “이번 납품과 함께 현대차 1차 협력사 지위도 확보하게 됐다”고 설명했다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006188789', 'https://imgnews.pstatic.net/image/018/2025/12/23/0006188789_001_20251223160009047.jpg?type=w800', 'NEWS_AUTO', NULL, '2025-12-23 16:00:09', 0, true, '2026-03-09 06:12:40.539570') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (913, 'TYM, 경제사절단 동행 필리핀行…마르코스 만나 농기계 현대화 논의', '2025년 12월 10일, 필리핀 ‘한국농기계전용공단’ 착공식에서 마르코스 주니어 대통령(사진 중앙 왼쪽)이 참석했다. TYM 측에선 김도훈 대표이사가 마르코스 주니어 대통령을 만났다. TYM측은 최근 이재명 대통령의 필리핀 순방 당시에도 경제사절단에 포함돼, 마르코스 대통령을 만난 것으로 알려진다. [TYM]누적 1870대·350억 연속 수주 발판한-필 농업협력 MOU 개정도 맞물려“현지화 넘어 동반성장 모델 구축”[헤럴드경제=홍석희 기자] TYM은 지난 4일 이재명 대통령의 필리핀 방문을 계기로 열린 ‘한-필리핀 비즈니스포럼’에 참석했다고 7일 밝혔다. 포럼은 지난 7일 오전 10시부터 오후 2시까지 진행됐으며, TYM 김도훈 대표이사가 농업 부문 대표로 자리를 함께했다.이번 ‘농업협력에 관한 양해각서’도 개정됐다. 개정된 협약에 따라 한국과 필리핀은 식량 안보를 위한 농업 발전 협력을 강화하는 한편, 농업 기계화와 수확 후 관리 및 유통 시스템 고도화, 농업 투입 자재 및 기계 발전 관련 기술 분야에서 공동으로 협력하게 된다.TYM이 이번 경제사절단에 농업 대표로 이름을 올린 것은 필리핀 시장에서 쌓아온 실적이 뒷받침됐기 때문이다. TYM은 필리핀 정부의 ‘쌀 경쟁력 강화 기금(RCEF)’ 프로젝트를 통한 정부 입찰에서 2024년부터 2025년까지 누적 1870대, 350억원 이상의 트랙터를 연속 수주했다. 일본 등 글로벌 농기계 업체들이 장기간 독점해온 필리핀 시장에서 국산 농기계가 연속으로 대규모 수주에 성공한 사례다.필리핀은 농업 의존도가 높은 반면 기계화율이 약 20% 수준에 불과해 성장 잠재력이 큰 시장으로 꼽힌다. 필리핀 정부는 RCEF 프로젝트를 중심으로 농기계 보급과 교육 인프라 확충에 주력하고 있으며, TYM은 이 흐름의 중심에 서 있다.TYM은 지난해 10월에는 필리핀 최대 농업 박람회 ‘어그리링크(AGRILINK) 2025’에서 필리핀 농업기계화센터(PHilMech)와 현지 부품·서비스 대응력 강화를 위한 업무협약(MOU)을 체결했다. 이 협약에 따라 TYM은 2026년까지 필리핀 현지에 부품·서비스 통합 센터를 설립하고, PHilMech 엔지니어를 대상으로 한 정규 기술 교육 프로그램을 본격 가동할 계획이다.지난해 12월에는 마르코스 주니어 대통령이 직접 참석한 ‘한국농기계전용공단(KAMIC)’ 착공식에도 참여해 필리핀 농업 현대화의 핵심 협력 파트너로서 위상을 확인했다. 한국농기계전용공단은 필리핀 카바나투안시에 농기계 제조 및 수출 거점을 조성하는 민관 협력 사업으로, 필리핀 정부가 토지 임대와 함께 인프라 구축 및 세제 혜택을 지원한다.TYM은 지난해 9월 필리핀 오리엔탈 민도로주에서 ‘2025 TYM 로드쇼’를 개최해 현지 농업 관계자와 농민 1200여 명을 대상으로 트랙터 성능을 직접 시연했다. 행사에 참석한 우메를리토 돌로르 오리엔탈 민도로 주지사는 “한국은 신뢰할 수 있는 동반자이며, K-농기계의 활약이 필리핀 농업 발전에 큰 힘이 될 것”이라고 말했다.이번 이재명 대통령 방문을 계기로 양국 간 농업 협력 체계가 정부 간 협약 수준으로 격상되면서 TYM의 필리핀 사업 확대에도 탄력이 붙을 전망이다. TYM이 준비 중인 부품·서비스 센터 설립과 기술 인력 양성 프로그램이 양국 농업협력 MOU의 구체적 이행 수단으로 연결될 수 있다는 점에서다. TYM은 쌀 외에 옥수수 등 타작물 중심의 원조사업 확대 가능성도 함께 모색하고 있다.TYM 관계자는 “그간 TYM이 필리핀 시장에서 쌓아온 신뢰와 실적이 이번 정상 외교 자리에서 인정받은 것”이라며 “필리핀 현지 농업 현대화를 위한 긴밀한 협업은 앞으로도 지속될 것”이라고 밝혔다.', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002609950', 'https://imgnews.pstatic.net/image/016/2026/03/08/0002609950_001_20260308143007979.png?type=w800', 'NEWS_ETC', NULL, '2026-03-08 07:00:13', 0, true, '2026-03-09 06:12:47.845670') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (914, '불황 뚫은 TYM, ''증설 없는 고마진 전략'' 통할까 [실적why]', '고마진 전략·재고정리·美비중↑·환율효과 맞물려 실적 큰폭 개선실적 개선 지속은 미지수…"올해 성적표 지속성장 분수령"TYM 북미 최대 농기계 전시회(Sunbelt AG EXPO 2025·EQUIP EXPO 2025) 부스 (TYM 제공)(서울=뉴스1) 김민석 기자 = TYM이 지난해 북미 시장에서 부가가치가 높은 중·대형 마력대 트랙터 판매를 늘리면서 불황을 뚫고 매출과 수익성 모두 끌어올렸다. 원·달러 환율이 높은 수준을 유지하면서 TYM(북미 수출 비중 60%대)은 환율 효과도 누렸다.다만 생산능력(CAPA) 확대 및 설비 증설 없이 환율 상승 효과에 기댄 고마진 전략은 외부 변수에 취약할 수 있다는 우려가 제기된다.8일 금융감독원 전자공시 시스템에 따르면 TYM은 지난해 연결기준 매출 9403억 원과 영업이익 641억 원을 거둬 각각 19.2%와 298.5% 증가했다. 순이익도 411억 원으로 125.6% 늘었다.악조건 속 실적 개선 배경으론 원·달러 환율 강세 속에서 코로나19 이후 공격적으로 늘렸던 재고 정리도 순조롭게 이뤄지고 중·대형 마력대 모델 판매 비중을 키워 영업 레버리지 효과를 극대화했다는 분석이 나온다.업계는 TYM이 지난해 전체 판매 매출의 약 64%를 북미에서 거둔 것으로 보고 있다.여기엔 TYM 북미법인이 2020년대 들어 국제종합기계의 북미법인인 ''브랜슨''(Branson)을 통합한 후 2023년 1월 출범한 브랜드 ''TYM North America''가 현지 시장에 안착한 점이 주효한 것으로 분석된다.TYM은 2016년부터 당시 업계 4위였던 국제종합기계 인수를 위한 지분 확보에 나서 2022년 흡수합병 절차를 마무리하며 ''한국 농기계 빅 3''에 올랐다.미국에선 TYM North America의 조지아 롬·펜실베이니아 블룸즈버그 등 현지 조립·물류 거점을 기반으로 부품 공급과 A/S 속도를 끌어올리고 브랜드를 ''TYM''으로 일원화했다. 일각에선 브랜드 인지도 하락 우려가 있었지만, 유통·서비스 인프라 정비를 기반으로 북미 시장에도 안착했다는 평가다.TYM은 2024년~2025년 미국 펜실베이니아엔 ''노스이스트 캠퍼스'', 조지아엔 ''시더타운 캠퍼스''를 구축해 북미 통합 서비스 거점을 구축했다. 이를 기반으로 지난해 북미 전략형 모델(T3025·T4058P) 판매 비중을 크게 늘려 비용 효율화 전략이 통했다는 분석이다.다만 설비 증설 및 제품 라인업을 확대하기보다 중·대형 트랙터에 편중된 고마진 전략은 중장기적관점에선 한계를 맞을 것이란 우려도 나온다.실제로 도널드 트럼프 미국 대통령발 관세 변수와 금리·환율 변동, 현지 농산물 가격 변동, 보조금 정책 등에 따라 트랙터 구매·교체 수요는 크게 흔들릴 수 있다.대동 역시 유럽·동남아 수출을 넓히고 데이터·서비스 기반 ''미래농업 플랫폼'' 기업으로 체질개선에 나선 만큼, 고마력·고마진 포트폴리오 하나만으론 지속 성장하기 쉽지 않을 수 있다는 시각이다.업계 관계자는 "TYM이 농기계 수요 둔화라는 악조건을 고마진 포트폴리오 전략으로 뚫으며 실적 반등을 이뤄냈다"면서 "단기적으론 이같은 전략과 강달러 기조가 맞물리며 수익성을 높였지만, 설비 투자와 글로벌 분산 전략이 뒷받침되지 않는다면 중장기 성장엔 제동이 걸릴 수 있다"고 우려했다. 이어 "올해 성적표가 지속 성장 가능성을 가늠할 분수령이 될 것"이라고 말했다.<용어설명>■ 영업 레버리지 효과영업 레버리지 효과는 매출이 조금만 늘어도 영업이익이 그보다 훨씬 크게 늘어나는 현상을 말한다. 기업이 부담하는 비용으로는 고정비(공장·설비 감가상각비·임대료·인건비 등)와 매출에 비례해 늘어나는 변동비가 있다. 매출이 손익분기점을 넘어 계속 늘면 매출 총이익이 더해지며 영업이익이 급격히 커질 때 영업 레버리지 효과라고 부른다.', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008812333', 'https://imgnews.pstatic.net/image/421/2026/03/08/0008812333_001_20260308064515166.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-08 06:45:00', 0, true, '2026-03-09 06:12:47.845670') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (938, '대웅 前 회장 직접 챙긴 시지바이오 매각, 인수자 찾았다…“지분율·가격 논의 중”', '사모펀드(PEF) 운용사 IMM프라이빗에쿼티(PE), 우선협상대상자로 선정대웅그룹 오너 2세인 윤재승 전 대웅제약 회장이 주도해 온 재생의료 계열사 시지바이오 매각 우선협상대상자로 사모펀드(PEF) 운용사 IMM프라이빗에쿼티(PE)가 선정됐다. 윤 전 회장이 직접 추진해 온 매각 작업이 본격적인 협상 단계에 들어간 것이다.5일 투자은행(IB) 업계에 따르면 IMM PE는 최근 시지바이오 인수 우선협상대상자로 선정돼 실사에 착수했다. 매각 대상은 시지바이오의 지주사인 에이하나가 보유한 지분 51%다. 거래 금액은 약 6000억원 수준으로 거론된다.대웅 측은 “현재는 우선협상대상자만 선정된 상태로 실사 절차가 남아 있다”며 “지분율과 거래 가격 등은 앞으로 협의를 통해 결정될 것”이라고 말했다.그래픽=정서희이번 매각은 윤 전 회장이 직접 챙겨 온 것으로 전해진다. 윤 전 회장은 별도의 매각 주관사를 두지 않고 국내외 중대형 재무적 투자자(FI)들을 상대로 개별 협상을 진행해 왔다.시지바이오는 뼈·피부·유착방지제 등 생체재료 기반 인공조직 대체재를 주력으로 하는 재생의료 기업이다. 대표 제품인 ‘노보시스’는 2017년 국내 최초로 개발된 골형성 단백질(BMP) 탑재 골대체재로, 골절 치료나 척추 수술 시 손상 부위에 주입해 줄기세포의 골세포 분화를 유도하고 뼈 생성을 촉진하는 역할을 한다.시지바이오의 최대주주는 대웅 오너 일가의 가족회사인 블루넷으로 지분 55.84%를 보유하고 있다. 블루넷 지분은 2018년 기준 윤재승 CVO(53.08%)를 중심으로 배우자 홍지숙 씨(10.35%), 장남 윤석민 씨(6.56%) 등이 나눠 갖고 있다.업계에서는 최근 단행된 그룹 내부 지배구조 개편에도 주목하고 있다. 시지바이오는 지난달 물적분할을 통해 ‘에이하나’를 존속법인으로 두고 그 아래 시지바이오·에디테라·노바메드텍 등 3개 신규 법인을 두는 구조로 재편했다.회사 측은 “경영 효율성 제고를 위한 조치”라고 설명했지만, 시장에서는 매각을 염두에 둔 구조 정리라는 해석이 나온다. 주요 사업 계열사를 시지바이오 산하로 묶어 기업가치 산정과 매각 협상에 유리한 구조를 만들었다는 평가다.시지바이오가 2024년 2월 인수한 코스닥 상장사 시지메드텍도 이번 재편 과정에서 시지바이오 산하로 편입됐다. 이에 따라 지분 구조는 ‘에이하나–시지바이오–시지메드텍’으로 단순화됐다. 시지메드텍은 척추 수술용 임플란트 부품을 생산하는 기업이다.대웅 관계자는 “경영 효율성 차원에서 주력 사업부문과 신사업 파트를 물적분할해 지주사 체제를 구축했다”며 “시지메드텍을 포함한 주요 계열사들은 시너지를 고려해 시지바이오 산하에 배치했다”고 설명했다.시장에서는 이번 매각 자금의 활용처에도 관심이 쏠린다. 현재 지배구조상 매각이 성사될 경우 확보되는 현금은 그룹이 아니라 오너 개인 지배 영역으로 유입된다. 업계에서는 이 자금이 향후 대웅 지주사 지분 확대나 계열사 지분 구조 조정 등 지배구조 재편에 활용될 가능성이 있는 것으로 보고 있다. 장기적으로는 승계 구도와 맞물린 재원으로 쓰일 수 있다는 관측도 나온다.이와 함께 대웅제약이 검토 중인 디지털헬스케어 기업 인수 가능성도 거론된다. 업계에 따르면 이 과정에 윤 CVO의 장남 윤석민 씨가 참여하고 있는 것으로 알려졌다. 윤 씨는 윤 CVO가 최대주주로 있는 엠서클에서 혈당 관리 헬스케어 사업 ‘웰다’의 팀장을 맡고 있다.', NULL, '조선비즈', 'https://n.news.naver.com/mnews/article/366/0001146180', 'https://imgnews.pstatic.net/image/366/2026/03/05/0001146180_001_20260306094017261.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-05 18:49:07', 0, true, '2026-03-09 06:13:49.690142') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (939, '최대주주 지분 희석의 후폭풍…경영권 흔들리는 바이오기업은', '이 기사는 2026년02월24일 11시14분에팜이데일리 프리미엄 콘텐츠로 선공개 되었습니다.[이데일리 김새미 기자] 바이오·헬스케어 기업들이 반복적인 자금 조달로 지분이 희석되며 경영권 리스크에 노출되면서 산업과 자본시장 모두 성숙 단계로 나아가기 위한 시험대에 올랐다.최대주주 지분 20% 미만 23곳…바이오 경영권 리스크 ''경고등''신약 개발은 10년 이상 장기간 연구개발(R&D) 투자가 필요하고 실패 확률도 높아 상용화 전까지 안정적인 현금흐름을 기대하기 어렵다. 이에 유상증자와 전환사채(CB), 신주인수권부사채(BW) 발행이 반복되면서 최대주주 지분율이 낮아지는 구조가 고착화되고 있다. 특히 기술특례 상장사는 상장 이후에도 임상 자금 조달이 이어지며 지배력이 약화되는 경우가 적지 않다.이데일리가 특수관계인 포함 최대주주 지분율 20% 미만, 시가총액 2000억원 이상 1조원 미만 바이오·헬스케어 상장사를 선별한 결과 23개사가 해당됐다. 특수관계자 포함 최대주주 지분율이 20%를 밑돌면 실질적 지배력이 취약한 구조로 평가된다. 시가총액이 2000억원 미만일 경우 경영권 분쟁의 실익이 제한적이라 보고 분석 대상에서 배제했다. 시가총액이 1조원을 넘는 경우도 의결권 확보 비용이 커져 방어 효과가 일정 부분 작용한다고 판단해 제외했다.[그래픽=이데일리 김일환 기자]코스피 상장사 중에는 삼진제약(005500)과 부광약품(003000)이 포함됐지만 모두 지배력 보완을 위한 안전판을 갖춘 상태다. 삼진제약은 지난해 11월 일성아이에스(003120)(구 일성신약)와 자사주를 맞교환하며 우호 지분을 확충했다. 지난해 말 제약업계에선 상법 개정으로 자사주 소각 의무화 논의가 진행되자 제약사 간 자사주 스왑을 통해 경영권 안정성을 보완하려는 움직임이 확산됐다. 부광약품은 최대주주 OCI홀딩스(010060)(17.11%) 외에 김동연 전 회장과 정창수 전 부회장이 각각 7%대 지분을 보유해 우호 지분 기반을 갖추고 있다.일반적으로 우호 지분이 부족한 기업은 외부 세력의 영향력에 노출되기 쉽다. 행동주의 펀드는 통상 최대주주 지분율이 15~22% 구간인 기업을 타깃으로 삼는 것으로 추정된다. 임플란트 업체 덴티움(145720)은 최근 8%대 지분을 확보한 얼라인파트너스가 공개 주주 제안을 제기했다.다만 순수 신약개발사는 현금흐름이 부재하고 임상·지적재산권(IP) 리스크가 커 적대적 인수합병(M&A) 매력도는 낮다는 평가가 우세하다. 금융투자업계 관계자는 "순수 신약개발사는 현금흐름이 부재하고 핵심 자산의 리스크가 크기 때문에 인수 매력도가 낮다"고 했다. 바이오업계 관계자는 “핵심 기술을 보유한 창업자가 이탈하면 기업가치 자체가 훼손되기 때문에 단순히 최대주주 지분율만으로 인수 가능성을 판단하긴 어렵다”고 언급했다.인수 이후에도 창업자와 새로운 최대주주가 공존하는 구조는 강스템바이오텍(217730)에서 확인된다. 강스템바이오텍은 2023년 11월 최대주주가 ㈜세종으로 변경됐지만 창업자인 강경선 서울대 교수와 공존하고 있다. 강 교수는 지난해 3분기 말 지분율이 3.36%지만 기술고문 형태로 강스템바이오텍의 R&D에 관여하고 있다. 시장에서는 이를 기술 기반 창업자와 재무적 투자자(FI) 간 이해관계가 일정 부분 맞물린 구조로 해석하고 있다.지배력이 약한 신약개발사는 행동주의 펀드의 개입보다는 소액주주 연대 등 주주 행동이 촉발되며 경영권 분쟁으로 번지는 사례가 많다. 헬릭스미스(084990), 셀리버리(268600), 아미코젠(092040), 오스코텍(039200) 등은 경영권 분쟁 당시 최대주주 지분율이 7.8%~13.32%로, 10% 안팎에 그쳤다.경영권 방어 이슈가 불거지면 R&D에 집중하기 어려워진다는 게 바이오 업계 관계자들의 공통된 시각이다. 경영진이 주주 대응과 분쟁, 임시주주총회 준비 등에 상당한 시간과 자원을 투입하게 되면 본업인 R&D에 차질이 생길 수밖에 없다는 얘기다. 바이오업계 관계자는 "신약 개발은 일관적인 전략과 속도가 중요한데 경영권이 흔들리면 R&D를 속도감 있게 추진하기 어려워진다"고 토로했다.소통 부재가 키운 갈등…"시총으로 경영권 방어 가능"바이오업계에서는 지분 희석 자체보다 기업과 시장 간 소통 부재가 갈등을 키운 요인이라고 보고 있다. 바이오업계 관계자는 "오스코텍 같은 경우는 시장과 소통이 원활하지 않았던 부분이 있었다"며 "기업에서는 마일스톤과 전략을 시장에 명확히 소통해야 하고, 투자자는 기업에 대해 충분히 이해한 후 장기적 관점에서 투자해야 한다"고 지적했다.최대주주 지분율이 낮고 주가 변동성이 크더라도 시가총액이 큰 기업은 상대적으로 경영권 방어가 수월한 편이다. 시가총액이 클수록 필요한 의결권 확보 비용이 커지기 때문이다. 일례로 펩트론의 경우 최대주주인 최호일 대표 지분율이 특수관계자 포함 8.47%에 불과하지만 시총이 6조3423억원이기 때문에 외부 세력이 지배력을 확보하긴 쉽지 않다.결국 일정 수준 이상의 기업가치를 유지하는 것 자체가 방어 수단이 되는 셈이다. 이는 바이오기업들이 기업설명(IR) 활동에 힘을 쏟는 배경이기도 하다.이승규 한국바이오협회 부회장은 “지분율이 낮더라도 시가총액을 높이면 방어 효과가 있다”며 “R&D 투자와 시장과의 적극적인 소통이 병행돼야 한다”고 강조했다. 이어 “법차손 문제 등 제도적 개선을 포함해 바이오 생태계 전반을 함께 정비할 필요가 있다”고 덧붙였다.일각에서는 바이오 산업 특성을 고려해 차등의결권 도입 등 장기 R&D 산업에 적합한 제도 보완이 필요하다는 의견도 제기된다. 류영재 서스틴베스트 대표는 “창업자가 지분 희석을 두려워하지 않고 장기 혁신에 도전할 수 있도록 상장사에도 일정 범위 내 복수의결권을 허용하는 방안을 검토할 필요가 있다”고 말했다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006223625', 'https://imgnews.pstatic.net/image/018/2026/02/24/0006223625_001_20260224195816056.jpg?type=w800', 'NEWS_BIO', NULL, '2026-02-24 15:17:11', 0, true, '2026-03-09 06:13:57.565288') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (915, '“트랙터·콤바인·이앙기 등 한자리에”…TYM, ‘2026 고객 초청 행사'' 열어', '충북 청주오스크서2000여명 참석TYM은 2월26일 충북 청주 청주오스코에서 ‘2026 TYM DAY 고객 초청 행사’를 개최했다. TYMTYM은 2월26일 충북 청주 청주오스코에서 ‘2026 TYM DAY 고객 초청 행사’를 개최했다고 3일 밝혔다.2000여명이 참석한 행사에서 TYM은 트랙터·콤바인·이앙기 등 모든 라인업을 한자리에서 선보였다. 마력대별 트랙터와 보통형 콤바인 ‘TH1200’, 존디어·이세키 제품, 출시 예정인 무인 운반차 등이 그것이다. TYM은 구매·정비·부품·금융 상담을 통합 제공하는 ‘TYM 원스톱 스토어’ 전략도 공개했다.TYM 관계자는 “국내 브랜드 가운데 유일한 88마력 트랙터 ‘T5088’이 행사에서 가장 높은 관심을 받았다”고 말했다. 그러면서 "독일 도이츠 엔진을 탑재한 이 모델은 중저속 엔진회전수(RPM) 구간에서도 안정적인 고출력을 구현하고, 중형급 기동성과 대형급 작업 성능을 동시에 확보해 70마력대와 100마력대 사이 수요를 겨냥한 전략 제품"이라고 소개했다.‘T5088’은 4년간의 연구개발을 거쳐 올초 출시됐다. 기계 경력 10년 이상 전문가 36인으로 구성된 기술 자문위원단과 고객 의견을 제품 설계에 반영했다는 것이 업체 측 설명이다.전후방 6포트 유압 외부 밸브, 비례제어밸브, 동급 최대 수준의 캐빈(유리로 막은 운전석) 공간, 에어 서스펜션과 통풍·열선 시트 등을 적용했다.TYM은 존디어 제품에 대해 구매처와 관계없이 사후서비스(AS)를 제공하고 140개 항목 점검과 최대 12개월 무상 보증을 지원하는 ‘인증중고 존디어’ 프로그램도 소개했다.김도훈 TYM 대표는 “고객 2000여명이 보여준 관심은 고객 중심 경영에 대한 시장의 신뢰를 보여준다”며 "전국 6대 권역에 구축한 TYM 플라자를 중심으로 원스톱 네트워크를 고도화해 차별화한 고객 경험을 제공하겠다"고 밝혔다.', NULL, '농민신문', 'https://n.news.naver.com/mnews/article/662/0000089718', 'https://imgnews.pstatic.net/image/662/2026/03/04/0000089718_001_20260304090014312.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-04 09:00:14', 0, true, '2026-03-09 06:12:47.845670') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (916, '유성 사례로 본 노란봉투법 시행령…노-노 갈등의 서막?[노동:판]', '"창구 단일화, 노조파괴 수단 악용된 유성기업 사태 재현될라"정부 "개별교섭은 소송으로 수년 허비…''노동위 선 판정''이 지름길"현장 "노동위 인정해도 소송 걸면 그만…절차만 늘어난 ''희망고문''"편집자 주우리는 일합니다. 공장에서, 사무실에서, 거리에서, 가정에서 오늘도 일합니다. 지금 이 순간도 쉼 없이 조금씩 세상을 바꾸는 모든 노동자에게, 일터를 찾은 나와 당신에게 필요한 이야기를 판 깔아봅니다.지난 8월 24일 서울 여의도 국회에서 열린 제428회 국회(임시회) 제2차 본회의에서 노동조합 및 노동관계조정법(노란봉투법) 일부개정법률안(대안)이 재적 186명, 찬성 183명, 반대 3명으로 통과되고 있다. 국민의힘은 투표에 불참했다. 박종민 기자정부가 입법예고한 노란봉투법(개정 노동조합법) 시행령 개정안에 노동계가 ''유성기업 노조 파괴 사태''가 반복될 것이라며 우려하고 있다. 그간 노사(勞使)-노노(勞勞) 갈등을 부른다는 비판을 받던 ''교섭창구 단일화''를 이번 개정안에도 원칙으로 내세웠기 때문이다.노동계는 ''제2의 유성기업 사태'', 즉 극심한 ''노노 갈등''의 서막이 될 수 있다고 경고하고 있다. 하지만 정부는 "소송으로 인한 시간 낭비를 막고 실질적 교섭을 앞당기는 조치"라며 고수하고 있다.''유성기업 트라우마''…창구 단일화는 어떻게 흉기가 되었나주무부처인 고용노동부는 노조법 시행령 개정안은 현행 교섭창구 단일화 절차와 사용자 정의를 확대한 노란봉투법의 취지를 절충했다고 주장한다. 현행 교섭창구 단일화 절차의 틀을 유지하고, 대신 노동위원회의 결정을 통해 교섭단위를 분리할 수 있도록 해 ''진짜 사장''인 원청 사용자에 대한 하청 노조의 실질적 교섭권을 보장하겠다는 구상이다.하지만 노동계는 ''창구 단일화'' 자체가 위험하고, 작고 약한 노조에게 불리한 제도라고 우려한다.대표적인 사례가 ''유성기업 노조 파괴 사태''다. 2011년 자동차 부품사 유성기업은 전국민주노동조합총연맹 소속 노조를 무력화하기 위해 회사 주도로 어용노조인 제2노조를 설립했다. 복수노조가 있는 사업장에서 조합원 수가 많은 ''교섭대표노조''만 회사와 교섭할 수 있다는 제도를 악용한 것이다. 회사의 지원을 등에 업은 제2노조가 교섭권을 독점했고, 기존 노조는 교섭 테이블에서 배제된 채 10년 넘게 거리 투쟁을 벌여야 했다.지난 2011년 5월 유성기업 아산공장 노조 파업 및 직장 폐쇄 당시 모습. 연합뉴스대법원은 지난 2021년 사측 주도로 설립된 제2노조에 대해 "사용자가 노조 설립과 운영에 지배·개입해 자주성을 상실했으므로 설립 자체가 무효"라고 확정 판결했다. 유성기업 류시영 회장은 노조 파괴 공작에 관여한 배임 등의 혐의로 실형을 선고받기도 했다.이번 시행령은 이처럼 악용될 소지가 있는 ''창구 단일화'' 제도를 원·하청 관계에 그대로 적용한다. 개정안에 따르면 원청의 사용자성이 인정돼 하청 노조가 교섭할 권리를 갖더라도, 원청 내 다른 정규직 노조나 다른 하청 노조 등과 단일화 절차를 거치는 또 하나의 문턱을 넘어야 한다.노란봉투법 개정 운동을 펼쳐온 ''손잡고'' 윤지선 활동가는 "복수노조 도입 당시에도 소수 노조 권익 신장을 명분으로 내세웠지만, 뚜껑을 열어보니 회사가 만든 노조가 민주노조를 와해시키는 수단이 됐다"며 "이번 시행령은 하청 노동자들에게 그 악몽을 다시 겪으라는 것과 같다"고 지적했다."대놓고 불법 안 저질러도"…일감 몰아주기로 합법적 배제 가능?2011년 5월 27일 유성기업 아산공장 앞에서 공장진입을 시도하는 노조원과 이를 제지하는 경찰이 뒤엉켜 있다. 연합뉴스물론 사측이 유성기업 사태처럼 노골적으로 노조 설립에 개입하면 ''부당노동행위''로 처벌받는다. 하지만 전문가들은 처벌을 피하면서도 합법적으로 하청 노조를 무력화할 수 있는 ''회색지대''가 열려있다고 경고한다. 굳이 범죄를 저지르지 않고도, 원청이 쥐고 있는 ''일감 배분권''만 활용하면 되기 때문이다.시나리오는 이렇다. 원청이 쓴소리를 하는 강성 하청 노조가 속한 업체에는 일감을 줄이고, 말을 잘 듣는 ''친(親)원청 성향'' 노조가 있는 하청 업체에 일감을 더 많이 배정한다. 자연스럽게 ''친원청'' 업체의 노조원 수가 늘어나 ''과반수 노조''로서 교섭대표권을 쥘 수 있다. 영세한 하청 업체의 명줄을 원청이 쥐고 흔들 수 있는 수직계열화된 한국의 산업 구조에서, 하청 노조 간에 교섭창구를 얻기 위해서는 오히려 원청을 상대로 충성 경쟁을 벌여야 하는 셈이다.민주사회를 위한 변호사 모임 노동위원회 신하나 변호사는 "원청이 ''어용''까지는 아니더라도 원청 친화적 노조가 있는 업체에 물량을 몰아주면 그곳이 대표 노조가 되고, 회사의 입맛대로 교섭이 짜여질 가능성이 훨씬 커진다"며 "부당노동행위로 입증하기도 어렵고, 하청 노조의 손발을 묶는 고도화된 수법이 될 것"이라고 우려했다.원청 정규직 노조도 하청 노조에게 넘기 힘든 벽이다. 원청 정규직 노조와 하청 노조가 하나의 창구로 묶일 경우, 통상 조합원 수가 압도적으로 많은 정규직 노조가 교섭 주도권을 쥘 수밖에 없다.신 변호사는 "원청 직원과 하청 직원은 사실상 한정된 파이 하나를 놓고 경쟁하는 관계"라며 "정규직 입장에서는 하청이 이익을 많이 가져갈수록 자신의 근로조건이 떨어진다고 생각하기 때문에 이해관계가 전혀 다르다"고 짚었다.정부의 반박 "노동위 판정이 더 빠르다"김영훈 고용노동부 장관이 24일 서울 종로구 정부서울청사에서 노동조합 및 노동관계조정법 시행령 개정안 브리핑을 하고 있다. 연합뉴스하지만 정부는 이번 시행령이 하청 노조의 교섭권을 약화시킨다는 주장에 대해 "오해"라며 선을 그었다. 오히려 법의 취지를 현실적으로 구현하기 위한 ''패스트트랙''이라는 설명이다.노동부는 "이번 개정안의 취지는 하청노조의 교섭권을 제한하는 것이 아니라, 안정적인 교섭체계 틀 안에서 교섭권을 최대한 보장하여 실질적 교섭을 촉진하는 데 있다"고 강조했다.정부가 내세운 핵심 논리는 ''선(先) 사용자성 판단''이다. 노사가 교섭을 시작하기 전, 창구 단일화 및 교섭단위 분리 절차를 밟는 과정에서 노동위가 미리 원청의 사용자성을 판단한다는 것이다.정부는 노동위가 사용자성을 인정하면 즉시 교섭 의무가 부과되고, 원청이 정당한 이유 없이 불응할 경우 지방고용노동관서의 지도와 부당노동행위 사법처리가 가능하다고 설명한다. 반면 창구 단일화 없이 개별교섭할 경우, 원청이 교섭을 거부하고 소송을 제기하면 법원의 확정 판결이 날 때까지 수년간 교섭이 중단되어 현장 혼란만 가중된다는 논리다.하지만 현장에서는 정부의 낙관론에 회의적이다. 노동위의 판단이 어떻게 내려져도 마찬가지로 사측이 소송으로 버티면 그만이라는 지적이다. 대개 규모가 영세한 하청 노조가 대기업 원청을 상대로 대법원 판결까지 십수 년이 걸릴 수도 있는 법정 공방을 버티기는 매우 어렵다.대표적인 예가 현대제철이다. 현대제철은 법에 따라 교섭하자는 사내하청 노동자들의 요구를 무시로 일관했지만, 지난 26일 서울고등법원은 불법파견을 인정했다. 게다가 지난 7월에는 서울행정법원도 현대제철에 교섭의무가 있다고 판결했지만, 현대제철은 고법의 선고를 일주일 앞두고 ''법원의 확정판결 결과에 따라 후속 조치를 취할 예정''이라며 교섭에 응하지 않겠다는 입장을 담은 공문을 보냈다.윤 활동가는 "이미 판결을 받은 곳도 교섭을 거부하고 있는데, 정부가 행정력으로 이를 강제하지 못하고 있다"며 "이런 상황에서 절차만 더 복잡하게 만든 시행령은 그 자체로 무력할 수밖에 없다"고 비판했다.교섭단위 분리…"교섭권 보장" vs "족쇄"전국금속노동조합 조합원들. 황진환 기자창구단일화가 안되더라도 정부는 "교섭단위 분리 제도를 통해 하청 노조의 실질적 교섭권을 보장하겠다"고 거듭 강조했다. 노동위가 이해관계의 공통성 등을 따져 원청 노조와 하청 노조를 분리해 주면 문제가 없다는 것이다.하지만 현장에서는 이 절차 자체가 교섭을 가로막는 또 다른 족쇄가 될 것이라고 비판한다. 이상규 금속노조 현대제철비정규직지회장은 지난 24일 긴급기자회견에서 "노동위원회의 허가를 받기 전까지 노동 3권은 유예되는 셈"이라며 "사용자가 이 절차를 악용해 시간을 끌고, 그사이 현장을 회유하거나 협박해 노조를 와해시킬 시간은 충분하다"고 비판했다.노동위에 과도한 권한이 몰리지만 일처리에 한계가 있다는 지적도 있다. 시행령에 따르면 노동위는 하청 노조의 분리 신청이 들어오면 최대 20일 안에 원청의 ''사용자성(실질적 지배력)''을 판단해야 하는데, 현재 인원 규모의 업무능력으로는 힘들다는 평가다. 정부도 문제를 인정하고 노동위의 인력 증원을 추진하겠다고 했다.김영훈 노동부 장관은 시행령 브리핑을 한 뒤 질의응답 과정에서 "과거의 기준에는 판례도 있고 관행도 있다. 그리고 무엇보다 중요한 건 불신도 있다"며 "세상에 어디에도 완벽한 제도는 없고 특히 노사 관계에서 법 제도를 뛰어넘는 자산은 신뢰라고 저는 알고 있다"고 말했다.하지만 과연 그 신뢰가 쌓여있는지 노동계는 묻고 있다. 내년 3월 시행될 노란봉투법 시행령이 정부의 기대대로 ''새로운 노사 신뢰''의 시작이 될지, 노동계의 우려대로 하청 노동자들끼리 교섭권을 놓고 다투는 ''노노 갈등의 서막''이 될지는 아직 미지수다.※CBS노컷뉴스는 여러분의 제보로 함께 세상을 바꿉니다. 각종 비리와 부당대우, 사건사고와 미담 등 모든 얘깃거리를 알려주세요.이메일 :jebo@cbs.co.kr카카오톡 :@노컷뉴스사이트 :https://url.kr/b71afn', NULL, '노컷뉴스', 'https://n.news.naver.com/mnews/article/079/0004090923', 'https://imgnews.pstatic.net/image/079/2025/11/29/0004090923_001_20251129050117892.jpg?type=w800', 'NEWS_AUTO', NULL, '2025-11-29 05:01:17', 0, true, '2026-03-09 06:12:55.003379') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (917, '유류 최고가격 지정제 추진에…급등하던 정유주 ''멈칫''', 'S-Oil 3% 하락…GS도 약보합[서울=뉴시스] 김혜진 기자 = 서울 평균 휘발유 가격이 리터당 1900원을 넘는 등 상승 흐름이 이어지는 6일 서울 시내 한 주유소에 유가 정보가 표시돼 있다.중동 리스크와 수급 불안정성에 따라 국내 기름값이 엿새 연속 오름세를 보이고 있다. 6일 한국석유공사 유가정보시스템 오피넷에 따르면 이날 오전 9시 기준 서울 지역 평균 휘발유 가격은 리터당 1916.5원으로 집계됐다. 전날보다 27원 오른 수준이다. 2026.03.06. jini@newsis.com[서울=뉴시스] 박주연 기자 = 미국과 이란 간 무력 충돌로 인한 석유 가격 급등에 정부가 ''최고가 지정제''로 대응키로 한 가운데 최근 가파르게 상승했던 정유업종 주가가 6일 혼조세를 나타내고 있다.한국거래소에 따르면 S-Oil은 이날 오전 9시58분 현재 유가증권시장에서 전 거래일보다 2.67% 하락한 13만1100원을 나타내고 있다. GS 역시 0.90% 하락한 6만6000원에 거래되고 있다.극동유화(-2.95%), 미창석유(-1.99%), 흥구석유(-1.07%) 등도 하락세다.반면 SK이노베이션(1.03%), 한국쉘석유(0.39%) 등은 상승 중이다.전일 국제유가가 중동정세 긴장으로 폭등을 기록했음에도 정부가 유류 최고가격 지정제를 추진한다는 소식에 투심이 약화된 것으로 풀이된다.서부텍사스산원유(WTI) 가격은 지난 5일(현지시간) 배럴당 6.35달러(8.51%) 오른 81.01달러로, 국제유가 벤치마크 브렌트유 가격은 4.01달러(4.93%) 상승한 배럴당 85.41달러로 장을 마감했다.이재명 대통령은 지난 5일 국무회의에서 최근 국내 유류가격 상승을 언급하며, "휘발유 가격에 바가지를 씌우는 행위에는 엄중 대응하라"며 최고가격 지정제 도입을 검토할 것을 지시했다.구윤철 부총리 겸 재정경제부 장관은 이에 대해 "석유사업법 23조에 보면 가격이 급등할 경우 최고 가격을 지정하도록 돼 있다"며 "오늘 오후에 가격을 점검해 가격이 높을 경우 고시를 통해 최고가를 지정하는 방안까지도 검토할 것"이라고 답했다.한국석유공사 유가정보시스템 오피넷에 따르면 6일 오전 9시 기준 전국 평균 휘발유 가격은 리터당 1856.3원으로 전날보다 22원 상승했다. 서울 지역 평균 휘발유 가격의 경우 리터당 1916.5원으로 집계됐다. 전날보다 27원 오른 수준이다.정유업종은 미국과 이스라엘의 이란 공습 소식이 전해진 후 급등세를 이어왔다. 유가 상승에 따라 정제마진이 높아질 것이라는 예상에 투심이 고조됐다.S-Oil은 이달 들어 지난 5일까지 3거래일간 22.27% 상승했다. S-Oil우 역시 같은 기간 7.27% 주가가 올랐다. 한국석유(79.75%), 대성에너지(65.42%), 극동유화(41.13%) 등도 강세를 나타냈다．', NULL, '뉴시스', 'https://n.news.naver.com/mnews/article/003/0013805366', 'https://imgnews.pstatic.net/image/003/2026/03/06/NISI20260306_0021197521_web_20260306095358_20260306105922945.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-06 10:08:29', 0, true, '2026-03-09 06:12:57.992873') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (918, '[특징주] 한국쉘석유 7% 상승… 호실적에 고배당까지', '한국쉘석유가 27일 7% 넘게 급등하고 있다. 지난해 호실적을 발표했고, 전날 열린 이사회에서 1주당 3만4000원의 배당(시가 배당률 7.3%)을 발표하면서 투자 자금이 유입된 것이다.한국쉘석유 CI./ 한국쉘석유 제공이날 오전 9시 50분 기준 유가증권시장에서 한국쉘석유는 전 거래일 대비 3만3000원(7.11%) 오른 49만7000원에 거래되고 있다.석유 정제품 제조업체 한국쉘석유는 전날 잠정실적 공시를 통해 지난해 개별기준 매출액이 3449억5916만원으로 전년 대비 5.4% 증가했다고 밝혔다. 영업이익은 14.9% 증가한 527억8133만원을 기록했다. 당기순이익은 482억2796만원으로 31.6% 증가한 것으로 집계됐다.한편, 한국쉘석유는 주주 환원 정책의 일환으로 현금배당도 결정했다. 배당금 총액은 442억원으로, 시가배당률은 7.3%다.', NULL, '조선비즈', 'https://n.news.naver.com/mnews/article/366/0001144835', 'https://imgnews.pstatic.net/image/366/2026/02/27/0001144835_001_20260227095210414.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-27 09:52:10', 0, true, '2026-03-09 06:12:57.992873') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (919, '[서울데이터랩]참엔지니어링 10.06% 상승…실시간 상승률 1위', '27일 오전 9시 10분 참엔지니어링(009310)가 등락률 +10.06%로 상승률 1위를 차지했다. 참엔지니어링은 개장 직후 5분간 67만 9527주가 거래되었으며 주가는 전 거래일 대비 132원 오른 1444원이다.한편 참엔지니어링의 PER은 -1.17로 나타나며, 이는 시장에서의 기대 수익률이 낮음을 시사한다. 또한 ROE는 -36.15%로, 이는 자본 대비 순이익이 감소하고 있음을 보여준다.이어 상승률 2위 대원전선우(006345)는 현재가 4955원으로 주가가 8.90% 상승하고 있다. 상승률 3위 한국쉘석유(002960)는 현재 50만 4000원으로 8.62% 상승하며 좋은 흐름을 보이고 있다. 상승률 4위 한전기술(052690)은 8.58% 상승하며 18만 4700원에 거래되고 있다. 상승률 5위 이수스페셜티케미컬(457190)은 7.77%의 상승세를 타고 11만 5100원에 거래되고 있다.6위 대원전선(006340)은 현재가 6890원으로 7.49% 상승 중이다. 7위 인디에프(014990)는 현재가 893원으로 6.95% 상승 중이다. 8위 두산2우B(000157)는 현재가 54만 1000원으로 6.29% 상승 중이다. 9위 서원(021050)은 현재가 1334원으로 6.29% 상승 중이다. 10위 상상인증권(001290)은 현재가 1655원으로 6.23% 상승 중이다.이밖에도 한화시스템(272210) ▲6.06%, 현대제철(004020) ▲5.67%, 현대건설(000720) ▲5.37%, 한전산업(130660) ▲5.36% 등을 기록하며 시장에서 활발히 거래되고 있다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003621415', 'https://imgnews.pstatic.net/image/081/2026/02/27/0003621415_001_20260227093511853.png?type=w800', 'NEWS_ETC', NULL, '2026-02-27 09:35:11', 0, true, '2026-03-09 06:12:57.992873') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (920, '[인사이드 스토리]"공공택지 못 사면?" 건설사의 밥벌이 고민', '중견사 "도급 공사 외형 유지가 한계"가로주택·모아타운 등 주택시장 틈새 찾아민참 사업도 적극적으로국내 증시에 상장된 중견 건설사 다수가 실적 개선 벨을 나란히 울렸습니다. 원가율 정상화 등을 통해 수익성을 크게 개선했기 때문입니다. 다만 눈에 띄는 매출 성장은 없었습니다.▷관련기사: 원가 고비 넘긴 중견 건설사, 일제히 ''실적 개선'' 벨 울렸다(2월20일)수익성을 살려낸 건설사의 다음 고민은 외형 유지입니다. 건설업은 발주처로부터 일감을 받아 장기간 매출을 일으키는 수주 산업입니다. 건설사는 벌이가 당장은 안정적이더라도 먹거리를 미리 쟁이지 않으면 보릿고개를 맞기 마련입니다.그러나 건설업계, 특히 중견 건설사들이 바라는 양질의 먹거리는 제한적입니다. 특히 그간 수익성을 끌어올린 공공택지 개발은 이재명 대통령이 밝힌 것처럼 한국토지주택공사(LH)의 몫이 될 것으로 보입니다. 수익성의 한계가 보이는 만큼 건설사의 먹거리 고민은 깊어질 전망입니다.수도권 도시개발 공사현장./사진=정지수 기자 jisoo2393@벌이 시원찮은 도급 공사6일 건설업계에 따르면 LH는 매년 개최하는 공동주택용지 공급계획 설명회를 이달 말에 열기 위해 일정을 조율 중입니다. 이 설명회는 LH가 연간 단위 공동주택용지 공급물량과 시기, 공급유형을 건설업계에 알리는 목적으로 열립니다.다만 올해는 LH 내부에서도 이 설명회를 어떻게 진행할 것인지를 놓고 고심 중이라고 합니다. 정부가 LH의 공공택지 직접시행 등을 포함한 LH 개혁 방안을 논의하고 있기 때문입니다.당장 LH는 지난달 25일 올해 공사·용역 발주 계획을 밝히면서 직접 시행하는 주택 건설사업을 확대하겠다고 밝히기도 했습니다. 공공택지 매각을 전면 중단할 수 있는 상황에서 건설사에 공동주택용지 매각 설명에 나서는 게 맞는지도 혼란스럽다는 전언입니다.LH 관계자는 "곧 공동주택용지 공급계획 설명회의 윤곽을 잡을 예정"이라면서 "다만 공동주택용지 개발 관련한 정부의 기조 변화도 있어 건설사의 참여가 저조하지는 않을까 걱정하는 부분이 있다"고 말했습니다.건설사는 매입한 공동주택용지 개발을 포기하는 경우가 최근 다수입니다. 그러나 여전히 공사 계약금에 맞춰 수익이 발생하는 도급공사에 비해 큰 이익을 기대할 수 있는 사업입니다. 도급 수익 외에 분양 수익까지 취하는 구조이기 때문입니다.▷관련기사: [단독]건설사, 작년 LH 공동주택용지 1.4조 어치 토했다(3월4일)중견 건설사 관계자는 "도급 사업은 수익이 거의 남지 않지만 인력을 함부로 줄일 수 없어 외형 유지 차원에서 수주를 하는 경우가 많다"면서 "공공택지 개발이 불가능하다면 주택 브랜드 파워가 상대적으로 떨어진 건설사는 주택 사업에서 수익성 확보를 기대하기 어렵다"고 말했습니다.최근 대형 건설사는 주요 입지의 도시정비사업 시공권을 따내면서도 에너지 사업에 힘을 싣는 경영 전략을 잇달아 발표하고 있습니다. 그러나 주택 사업 중심의 중견 건설사는 사업 구성을 다양화하기 어렵습니다.앞선 관계자는 "산업 설비나 에너지 관련 시설을 짓는 건 주택 사업처럼 단기간에 현금을 창출할 수 있는 사업이 아니다"라면서 "대규모 사업을 끌고 갈 기초 체력이 부족한 중견 건설사가 ''에너지''를 주력으로 삼기에는 무리"라고 강조했습니다.동부건설이 수주한 지난달 수주한 신내동 모아타운 조감도./자료=동부건설민간 주택시장 틈새 찾는다공공택지 개발이 막힌다면 양호한 수익성을 안정적으로 기대할 수 있는 재건축·재개발 사업을 노려야 합니다. 그러나 민간에서 선호도가 강한 주택 브랜드를 보유한 대형 건설사가 아니고서는 양질의 일감을 확보하기 어렵습니다. 중견 건설사의 발길은 결국 주택 시장 틈새로 향합니다.모아타운이 대표적입니다. 모아타운은 노후한 단독·다가구주택이 밀집해 뒤엉킨 지역을 하나로 묶어 개발하는 방식입니다.모아타운은 일반적인 재건축·재개발에 비해 소규모 사업이다 보니 수익성을 끌어올릴 일반분양 물량이 비교적 적고 소유주도 나뉘어 있습니다. 사업 진행이 쉽지 않다고 판단한 대형사가 손을 대기 꺼리자 중견사에서 나서는 겁니다.특히 동부건설은 서울 모아타운 수주에 몇 년간 힘을 쏟고 있습니다. 지난달 23일 서울 중랑구 신내동 493·494 일원 모아타운 정비사업을 품는 성과도 냈습니다. 지하 3층~지상 29층, 10개동 규모 904가구의 주거단지와 근린생활시설, 커뮤니티 시설 등이 조성하는 사업입니다. 총 도급 공사비는 약 3341억원입니다.쌍용건설은 올해 소규모 정비사업에서 성과가 있었습니다. 지난달 3일 노량진 은하맨션 일대 가로주택 정비사업 시공권을 따내기도 했습니다. 서울 동작구 노량진동 84-24 일대 구역면적 9256㎡에 지하 5층~지상 29층 높이의 아파트 3개동, 206가구를 짓는 사업입니다. 일반분양분이 106가구입니다.서울이 아닌 지역에서도 사업성이 있다고 판단해 대형 재건축·재개발 사업을 과감히 수주하는 건설사도 나옵니다.BS한양은 지난해 말 인천 동구에서 도급공사비가 9100억원에 달하는 ''금송구역 재개발 사업''의 시공권을 확보했습니다. 송림동 일대에 최고 45층 높이의 아파트 26개동, 3690가구를 짓는 사업입니다.한신공영은 지난달 4일 지방에서 회원2구역 재개발정비사업조합과 총 6039억원의 도급공사 계약을 맺었습니다. 경상남도 창원시 마산회원구 회원2동 480-31 일원에 지하 3층~지상 27층, 총 21개 동, 아파트 2016가구 및 부대복리시설을 신축하는 사업입니다.한신공영 관계자는 "올해도 수익성이 높고 사업 안정성이 우수한 도시정비사업에 집중하며 수주 포트폴리오를 집중하고 있다"면서 "하반기에도 서울 및 수도권과 입지가 우수한 지방 대도시권 대규모 정비사업을 중심으로 정비사업 수주 확대에 주력할 방침"이라고 말했습니다.LH 2026년 유형별 공사용역 발주계획./자료=LH공공택지 개발 못 해도 민참 사업에 적극중견 건설사는 LH가 개발하는 택지 물량도 눈여겨봅니다. 개발 수익이 없더라도 외형 유지 혹은 성장 차원에서는 공공사업에 뛰어들 필요가 있다는 게 업계 시각입니다.LH는 올해 공공기관 최대 규모인 17조8839억원의 일감을 발주할 예정입니다. 이 중 공사는 15조8222억원, 용역은 2조617억원입니다.남양주왕숙·인천계양·고양창릉·하남교산 등 수도권 대규모 공공주택 공급을 위한 3기 신도시 관련 사업 발주 물량만 12조8000억원에 달합니다. 공종별로는 전기·통신·소방 등 부대공사를 포함한 주택사업 관련 발주가 12조500억원으로 전체 발주액의 68%를 차지합니다.LH는 아울러 올해 민간참여사업 1만8000가구에 대한 신규 공모를 진행합니다. 사업비는 6조1000억원에 달합니다. 인천영종과 인천검단, 남양주왕숙, 성대야구장, 위례업무, 안산장상, 수원당수, 오산오산 등 전국 27개 블록입니다.이 같은 민참사업에 금호건설이 적극적입니다. 금호건설은 2024년부터 2025년까지 나온 30개의 민참 패키지사업 중 6개의 민참 패키지사업에 참여했습니다. 광명시흥과 평택고덕, 남양주왕숙 등이 주요 참여 사업장입니다. 아울러 주택본부 산하 공모개발 담당조직도 운영 중입니다.금호건설 관계자는 "공공주택 공급 확대라는 정부 정책 기조에 맞춰 올해도 민간참여 공공주택 사업에 적극적으로 참여할 예정"이라며 "특히 정부가 3기 신도시 등을 중심으로 관련 사업을 확대하고 있는 만큼 사업성을 검토해 참여 기회를 모색할 계획"이라고 밝혔습니다.', NULL, '비즈워치', 'https://n.news.naver.com/mnews/article/648/0000045007', 'https://imgnews.pstatic.net/image/648/2026/03/06/0000045007_001_20260306073017358.jpg?type=w800', 'NEWS_CONSTRUCT', NULL, '2026-03-06 07:30:17', 0, true, '2026-03-09 06:13:03.721738') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (921, '''흑자전환'' 금호건설, 3년 만에 배당 재개…주당 200원', '(금호건설 제공)  뉴스1 ⓒ News1(서울=뉴스1) 김종윤 기자 = 금호건설(002990)이 3년 만에 배당을 재개했다. 지난해 흑자전환 성공 이후 주주가치 제고를 위한 결정이다.금호건설은 5일 결산 배당으로 보통주 기준 주당 200원을 배당한다고 공시했다.금호건설은 결산 기준 2022년(500원)을 마지막으로 2년 동안 배당을 중단했다. 건설 경기 침체에 따른 실적 악화 영향이었다.지난해 458억 원으로 흑자전환 이후 3년 만에 배당 재개를 결정했다. 배당 총액은 72억 8914만 원이다.', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008809283', 'https://imgnews.pstatic.net/image/421/2026/03/05/0008809283_001_20260305173617943.jpg?type=w800', 'NEWS_CONSTRUCT', NULL, '2026-03-05 17:35:15', 0, true, '2026-03-09 06:13:03.721738') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (922, '수익성 겨우 살렸는데… 전쟁 리스크에 건설사 ‘노심초사’', '■실적개선 나선 건설사들지난해 상장사 빅7 영업익 20%↑美·이란 전쟁 파장에 노심초사도시정비·원전 수주로 반등 목표이란 테헤란에 있는 이란 전 최고지도자 알리 하메네이 거주지가 1일(현지 시간) 미국과 이스라엘의 공습 직후 파괴돼있다. /AP연합국내 주요 건설사들이 지난해 철저한 원가 관리와 이익 위주의 사업 재편을 통해 수익성을 끌어올린 것으로 확인됐다. 올해는 해외에서 인공지능(AI)발 대규모 원전 프로젝트가 본격화하고, 국내는 80조 원에 육박하는 도시정비사업 물량이 쏟아질 것으로 관측돼 더 큰 폭의 이익 개선이 기대되고 있다. 다만 미국·이스라엘과 이란 간 전쟁 여파가 중동 전역으로 번지고 장기화할 경우 간신히 잡아놓은 원가율과 수익성이 다시 악화할 수 있다는 우려가 나온다.4일 금융감독원 전자공시시스템에 따르면 시공능력평가 순위 1~10위의 대형 상장 건설사 7곳(삼성물산·현대·대우·GS건설·DL이앤씨·삼성E&A·HDC현대산업개발)과 11~30위권의 중견 건설사 7곳(계룡·금호·태영건설·한신공영·HL D&I한라·동부·KCC건설)은 지난해 수익성 개선세가 뚜렷했다.특히 중견사들의 반등이 극적이었다. 중견사 7곳의 합산 영업이익(이하 연결기준, 잠정)은 5742억 원으로 전년도 970억 원대비 492% 뛰었다. 당기순이익 역시 1673억원 적자에서 지난해 4365억 원 흑자로 돌아섰다. 매출은 2024년 14조 3121억 원보다 오히려 5%가량 줄어든 13조 5302억 원으로 집계됐지만 순이익이 1년 만에 무려 6000억 원 이상 늘어난 셈이다.수익성 개선의 비결은 ‘원가율 정상화’가 거론된다. 이들 기업은 2024년 원자재 가격 폭등과 고금리로 인해 대규모 적자를 기록했지만 지난해 현장 원가 관리 등을 강화하고 외형 확장 대신 수익성이 높인 사업장 위주의 선별 수주를 진행하며 턴어라운드에 성공한 것이다. 실제 금호건설과 동부건설의 지난해 매출 원가율은 전년 대비 10~11%포인트 내린 87~93%까지 낮아졌다.대형사들 역시 공정·원가 관리 강화와 선별 수주 전략 등을 통해 체질 개선에 성공했다. 상장사 7곳의 합산 영업이익은 2조 2391억 원으로, 전년 대비 20.8%가 증가했고 평균 영업이익률도 1.9%에서 2.6%로 개선됐다. 다만 대형사는 희비가 엇갈렸는데 현대건설과 GS건설, DL이앤씨와 HDC현대산업개발 등 4곳은 이익이 회복된 반면 고수익 프로젝트들이 종료된 삼성물산과 삼성E&A, 지방 미분양 등 8000억 원대의 대규모 잠재 부실을 선제적으로 털어낸 대우건설은 실적이 악화했다.80조 정비물량·글로벌 원전 수주 등 ‘장밋빛 미래’ 기대됐는데 전쟁 리스크에 노심초사코스피가 미국과 이란 간 전쟁 발발 여파로 역대 최대 폭으로 폭락해 5100선마저 내준 4일 서울 중구 하나은행 본점 딜링룸에 코스피가 표시돼 있다. /연합뉴스전문가들은 대부분 건설사가 원가율 개선과 부실 선반영, 수익성 중심의 사업 재편 등의 준비를 마친 상황에서 올해 이익 성장의 가능성을 높게 봤다. 특히 올해는 서울 압구정·여의도·목동·성수 등 핵심 입지를 중심으로 80조 원 규모의 도시정비사업(재건축·재개발) 물량이 쏟아질 예정이며 해외에서도 체코와 루마니아 등지에서 글로벌 원전 수주전이 본격화하고 있어 기술력있는 대형 건설사의 가파른 성장 가능성이 점쳐졌다.그러나 지난 달 28일 미국과 이스라엘의 전격적인 이란 공습으로 중동 전쟁이 발발하면서 체질 개선을 통해 어렵사리 수익성을 확보해놓은 건설업계의 셈법이 다시 복잡해졌다. 이란이 세계 에너지 공급의 핵심 통로인 호르무즈 해협을 봉쇄하면서 국제유가와 해상운임이 크게 오르고 있어서다. 국제유가와 해상운임은 아스팔트와 시멘트, 철강 등 주요 건설자재의 생산·운송 원가에 크게 영향을 미치는 요소다. 한국건설산업연구원에 따르면 유가가 60% 상승할 경우 건축물 생산비용이 1.5%, 일반 토목시설 생산비용이 3%까지 증가한다.우려는 현실이 되고 있는데 3일(현지시간) 런던ICE선물거래소에서 5월 인도분 브렌트유 가격은 배럴당 81.4달러에 거래를 마쳤고 4일 83달러를 돌파해 상승 중이다. 이란 공습일 직전 거래일인 지난달 27일 이후 16% 이상 올랐다. JP모건 등 글로벌 투자은행(IB)들은 호르무즈 해협 봉쇄가 장기화할 경우 브렌트유의 가격이 배럴당 100~200달러에 육박할 가능성도 관측하고 있다. 해상 운임 역시 전쟁 전과 비교해 3배 이상 급등하며 해외 사업 비중이 큰 대형사들을 압박하고 있다.전문가들은 전쟁의 장기화 여부가 건설사 수익성의 주요 변수가 될 것으로 보고 있다. 박세라 신영증권 연구원은 “전쟁은 중동에서 수행 중인 프로젝트의 공기 지연 가능성을 높이고 향후 수주 일정에도 불확실성을 키운다”며 “에너지 공급 차질이 장기화하면 경기 둔화 우려가 확산돼 주택사업 등 내수 중심인 건설사에도 피해를 줄 수 있다”고 내다봤다.', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004595873', 'https://imgnews.pstatic.net/image/011/2026/03/05/0004595873_001_20260305070123301.jpg?type=w800', 'NEWS_CONSTRUCT', NULL, '2026-03-05 07:01:23', 0, true, '2026-03-09 06:13:03.721738') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (923, '빚 500억·완전 자본잠식 덮쳤지만…부광약품 “유니온제약 상폐돼도 300억 인수 강행”', '부광약품이 300억에 인수하는 한국유니온제약, 회생계획안 제출채권자들이 동의하면 인가→채무 변제 수행한 뒤 법정 관리 졸업자본 잠식에 상폐 사유 발생은 변수…잠식 해소 입증해야 하는데부광약품 “상폐와 무관하게 인수 절차 계속 진행”부광약품 전경. /부광약품 제공기업 회생(법정 관리) 절차를 밟고 있는 한국유니온제약이 법원에 회생 계획안을 제출했다. 한국유니온제약은 자본 전액 잠식 상태에 들어갔고 상장 폐지 위기에 놓였지만 부광약품은 이와 관계없이 300억원에 인수를 강행한다는 계획이다.7일 제약 및 법조계에 따르면 한국유니온제약 관리인은 지난 달 서울회생법원 회생14부에 회생 계획안을 제출했다. 한국유니온제약이 지난해 9월 회생 절차에 들어간 지 5개월여 만이다.회생 계획안에는 매각 대금으로 채무를 변제하는 방안이 담긴 것으로 알려졌다. 한국유니온제약의 채무는 500억원대다. 이 가운데 부광약품의 인수 대금 300억원으로 일부 채무를 갚을 계획이다. 법조계 관계자는 “나머지 채무는 신주를 발행해 (채권자에게) 주식을 교부하는 방식으로 정리하는 방안이 유력하다”고 했다.앞으로 채권자와 이해 관계자들은 회생 계획안에 대해 의견을 제출하게 된다. 법원은 회생 계획안을 의결하는 집회 기일을 지정할 계획이다. 채권자들이 회생 계획안에 동의하면 회생안이 인가(認可)된다. 법원은 이후 한국유니온제약이 회생 계획안대로 채무 변제를 수행하는지 확인한 뒤 회생 절차를 종결한다. 이렇게 되면 한국유니온제약은 법정 관리를 졸업하게 된다.부광약품은 지난 1월 스토킹 호스 방식으로 한국유니온제약 최종 인수자로 선정됐다. 스토킹 호스는 일단 인수자를 두고 더 좋은 조건의 투자자가 나오면 이를 따져 최종 인수자를 결정하는 방식이다. 인수는 공정거래위원회 기업 결합 심사가 마무리되는 4월 완료될 예정이다.한국유니온제약 강원 원주 공장 전경. /한국유니온제약1956년 설립된 한국유니온제약은 강원 원주에 공장을 두고 항생제와 주사제 등을 생산한다. 부광약품은 기존 경기 안산 공장에서 의약품을 생산하고 있다. 이번 인수로 생산 능력이 30% 확대될 전망이다. 부광약품은 지난해 연결 기준 매출 2007억원, 영업이익 142억원을 기록했다. 각각 전년 대비 25%, 775% 증가했다.다만 한국유니온제약은 경영 상황이 악화된 상태다. 한국유니온제약은 지난 2018년 7월 코스닥에 입성했으나 현재 상장폐지 위기에 놓였다. 한국유니온제약의 지난해 매출은 364억원으로 2023년 대비 42% 줄었다. 영업손실은 172억원으로 2023년 영업손실 52억원보다 적자 폭이 커졌다. 한국유니온제약 측은 “2024년 사업 보고서는 감사 의견이 거절됐다”고 했다.한국유니온제약은 지난해 자본 총계가 마이너스(-)231억원을 기록하며 자본 전액 잠식 상태에 빠졌다. 자산보다 부채가 많은 상황이다. 한국유니온제약은 사업 보고서 제출 기한까지 자본 잠식 해소 사유를 입증하는 재무제표 등을 제출해야 한다. 이를 충족하지 못하면 코스닥 상장 폐지 사유가 될 수 있다.한국거래소는 한국유니온제약에 지난해 4월 8일부터 지난 2월 9일까지 개선 기간 10개월을 부여했다. 한국유니온제약은 전날 개선 계획 이행 내역서를 제출했다. 한국거래소는 서류 제출일로부터 20영업일 이내 코스닥 시장 위원회를 열고 상장 폐지 여부를 결정할 예정이다.다만 부광약품은 한국유니온제약 상장 폐지 여부와 무관하게 인수 절차를 계속 진행할 예정이다. 부광약품 관계자는 “인수가 마무리되는 4월 이후 재무 구조를 개선할 계획”이라고 했다.', NULL, '조선비즈', 'https://n.news.naver.com/mnews/article/366/0001146528', 'https://imgnews.pstatic.net/image/366/2026/03/07/0001146528_001_20260307100010988.jpg?type=w800', 'NEWS_BIO', NULL, '2026-03-07 10:00:10', 0, true, '2026-03-09 06:13:10.689554') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (924, '"콘테라파마 RNA 플랫폼 통했다"…부광약품, 자회사 중심 신약 개발 ''2막''', '부광약품 지난해 영업익 770% 이상 급증자회사 콘테라파마 RNA 플랫폼 중심 성장룬드벡, 연례보고서에 콘테라파마와의 협력 언급부광약품 본사 전경 ⓒ부광약품[데일리안 = 이소영 기자] 부광약품이 자회사 중심의 ‘선택과 집중’ R&D 전략을 통해 글로벌 바이오 시장의 핵심 모달리티인 RNA 분야에서 존재감을 드러내고 있다. 기존 CNS(중추신경계) 제품을 통해 안정적인 매출원을 확보하는 동시에 혁신 RNA 플랫폼을 전면에 내세우며 체질 변화에 속도를 내는 모습이다.5일 업계에 따르면 부광약품은 지난해 연결 기준 매출 2007억원, 영업이익 141억원을 기록했다. 창사 이래 최대 실적으로 전년 대비 매출은 25.4%, 영업이익은 775.2% 급증했다.실적 성장은 주력 제품인 당뇨병성 신경병증 치료제 ‘덱시드’와 ‘치옥타시드’가 견인했다. 2017년 일본 스미토모 파마로부터 도입한 조현병 치료제 ‘라투다’ 역시 양극성 장애 등으로 적응증을 확대하며 CNS 부문의 핵심 매출원으로 자리 잡았다.빅파마 DNA 심은 콘테라파마… RNA 플랫폼 가치 입증부광약품은 여타 중견 제약사들처럼 합성 의약품 제조와 제네릭(복제약) 중심으로 사업을 전개해 왔으나, 최근 고부가가치 신약 및 플랫폼 기술 중심으로 포트폴리오를 재편하고 있다.R&D 중심에는 2014년 부광약품이 인수한 덴마크 소재 자회사 콘테라파마가 있다. 로슈 등 글로벌 빅파마 출신 전문가들로 구성된 콘테라파마는 독자적인 RNA 치료 플랫폼을 구축하며 차별화된 입지를 다지는 중이다.콘테라파마의 RNA 플랫폼은 질병을 유발하는 RNA를 선별해 최적의 올리고뉴클레오타이드 및 저분자 화합물을 도출하는 3단계 시스템으로 운영된다.구체적으로 ▲AI 및 바이오인포매틱스를 활용해 질병을 일으키는 RNA 타깃을 찾는어택포인트▲식별된 타깃에 최적화된 ASO 및 siRNA 후보물질을 정밀 설계하는올리고디스크▲RNA 가공 과정을 조절하는 경구용 저분자 화합물을 찾아내 투여 편의성을 극대화하는스플라이스매트릭스등이다.콘테라파마의 RNA 플랫폼 경쟁력은 글로벌 CNS 분야 빅파마인 룬드벡과의 파트너십으로 이어졌다. 지난해 콘테라파마는 룬드벡과 RNA 신약 공동 연구 및 라이선스 옵션 계약을 체결했다. 이번 계약은 신경퇴행성 질환을 포함한 중추신경계 질환 치료제 개발을 목표로 한다.룬드벡은 콘테라파마의 RNA 기반 플랫폼 기술을 결합해 신규 올리고뉴클레오타이드 후보물질을 발굴하며, 콘테라파마가 후보를 도출하면 룬드벡이 이를 임상 및 글로벌 상용화 단계로 발전시킨다.룬드벡은 최근 발표한 연례 보고서에서 ‘2025년 파이프라인의 뚜렷한 진전’ 항목 중 하나로 콘테라파마와의 연구 협력을 명시했다. 글로벌 빅파마가 공식 보고서에 공동 프로젝트를 별도로 소개한 것은 해당 프로그램을 전략적 과제로 관리하고 있음을 시사한다.부광약품 측은 룬드벡과의 구체적인 계약 규모를 밝히지 않았으나, 지난해 영업이익이 대폭 증가한 배경에는 룬드벡으로부터 수령한 계약금이 상당 부분 영향을 미쳤다고 설명했다.부광약품은 선택과 집중을 통해 R&D 전략도 재정비하고 있다. 과거 콘테라파마의 성장을 견인했던 파킨슨병 이상운동증 치료제 ‘JM-010’이 유럽 임상 2상에서 유효성 확보에 실패하자, 미국 임상을 즉각 중단하는 결단을 내렸다. 대신 그간 축적해온 RNA 플랫폼 기술을 전면에 내세우며 사업 축을 이동시키는 ‘리셋’을 단행했다.부광약품은 향후 RNA 사업부의 스핀오프(분할)를 통해 독립적인 가치를 가시화하고, 외부 투자 유치 및 해외 IPO를 추진할 계획이다. 또한 파킨슨병 아침무동증 치료제 ‘CP-012’의 글로벌 임상 2상 진입을 통해 자회사 중심의 신약 개발 성과를 극대화할 방침이다.부광약품 관계자는 “자회사 콘테라파마가 개별 파이프라인을 넘어 RNA 플랫폼 자체의 혁신성과 확장 가능성을 글로벌에서 인정받고 있다”면서 “RNA 플랫폼 사업부 분할 및 신설 법인 설립에 관한 구체적인 사항은 아직 정해지지 않았다”고 말했다.', NULL, '데일리안', 'https://n.news.naver.com/mnews/article/119/0003065713', 'https://imgnews.pstatic.net/image/119/2026/03/05/0003065713_001_20260305143012371.jpg?type=w800', 'NEWS_BIO', NULL, '2026-03-05 14:30:12', 0, true, '2026-03-09 06:13:10.689554') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (925, '혜인, AI·방산 MRO 엔진사업 투자 확대 선언', '시설·인력 투자로 AI 및 방산 분야 사업 확장 계획삼성·네이버 데이터센터 및 해군 함정 엔진 공급 성과㈜혜인은 AI 데이터센터 및 방산 분야 MRO(유지·보수·정비) 시장의 성장세에 발맞춰 엔진·발전기 사업 투자를 확대한다고 19일 밝혔다.  (혜인 제공. 재판매 및 DB금지) 2026.1.19/뉴스1(대전=뉴스1) 이동원 기자 = ㈜혜인은 인공지능(AI) 확산에 따른 초대형 데이터센터 증가와 방산 분야 유지·보수·정비(MRO) 수요 확대에 발맞춰 엔진·발전기 사업 분야 투자를 확대한다고 19일 밝혔다.2025년 정부의 약 2조 원 규모 국가 AI 컴퓨팅 센터 구축 추진과 미 해군의 해외 MRO 외주화 전략에 따라 대규모·무중단 전력 인프라 및 방산 MRO 시장의 중요성이 커지고 있다.혜인은 캐터필라(Caterpillar Inc.)의 공식 딜러로서 65년간 엔진·발전기 사업을 영위해 왔다. 캐터필라의 세계적인 기술력과 서비스 네트워크를 기반으로, 혜인은 비상발전기 분야에서 삼성전자, 네이버, 카카오 등 국내 주요 데이터센터에 공급하며 미국 빅테크 기업 프로젝트에도 참여했다. 방산 분야에서도 고속정, 대형 수송함, 영국 해군 군수지원함 등에 엔진을 공급하며 지속적인 성과를 기록 중이다.㈜혜인은 AI 데이터센터 및 방산 분야 MRO(유지·보수·정비) 시장의 성장세에 발맞춰 엔진·발전기 사업 투자를 확대한다고 19일 밝혔다.  (혜인 제공. 재판매 및 DB금지) 2026.1.19/뉴스1또한, 혜인은 대형 발전기 및 함정 엔진의 분해·정비·조립·성능시험까지 자체 수행할 수 있는 설비를 보유하고 있다. 이를 바탕으로 미 해군 함정의 국내 발전기 수리 사업 부품 공급, 국내 대형 조선소의 해외 방산 프로젝트 협업 등 글로벌 해군 MRO 시장 진출을 본격화하고 있다.㈜혜인 관계자는 “엔진·발전기 공급 및 정비 사업에 대한 시설·인력 투자를 통해 AI 데이터센터 및 방산 분야 사업을 지속 확장해 나갈 계획”이라고 밝혔다.', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008721115', 'https://imgnews.pstatic.net/image/421/2026/01/19/0008721115_001_20260119095823814.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-01-19 09:57:44', 0, true, '2026-03-09 06:13:17.011686') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (926, '(주)혜인, AI 데이터센터·방산 MRO 엔진 사업 확대', '(대전=뉴스1) 이동원 기자 = (주)혜인은 AI 데이터센터 및 방산 분야 MRO(유지·보수·정비) 시장의 성장세에 발맞춰 엔진·발전기 사업 투자를 확대한다고 19일 밝혔다. 이는 정부의 국가 AI 컴퓨팅 센터 구축 계획과 미 해군의 해외 MRO 외주화 전략에 대한 선제적 대응으로 풀이된다.캐터필라의 공식 딜러로서 축적된 기술력과 실적을 기반으로 혜인은 데이터센터 비상전력과 해군 함정 엔진 공급을 통해 핵심 사업 역량을 강화하고 있다. 시설 및 인력 투자를 통해 글로벌 AI 및 방산 시장에서의 입지를 더욱 굳건히 할 계획이다.  (혜인 제공. 재판매 및 DB금지) 2026.1.19/뉴스1', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008721009', 'https://imgnews.pstatic.net/image/421/2026/01/19/0008721009_001_20260119092919947.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-01-19 09:28:54', 0, true, '2026-03-09 06:13:17.011686') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (927, '뉴진스 복귀에 하이브 주가 5% ''껑충''', '그룹 뉴진스 [어도어 제공]소속사 어도어와 전속 계약 분쟁을 벌여왔던 그룹 뉴진스 멤버들이 전원 복귀를 선언하면서 오늘(13일) 하이브[352820] 주가가 5% 넘게 오르고 있습니다.오늘 오전 11시 13분 기준 유가 증권 시장에서 하이브는 전장 대비 5.67% 오른 30만7천500원에 거래되고 있습니다.어제(12일) 장 마감 후 뉴진스 멤버들은 지난해 11월 전속 계약 해지 선언 이후 1년 만에 소속사 어도어에 전원 복귀 의사를 밝혔습니다.어도어 측은 멤버 해린과 혜인이 상의를 거쳐 복귀하기로 했다고 밝혔으며, 어도어의 이 같은 발표 이후 약 2시간 30분 뒤 민지, 하니, 다니엘도 소속사로 복귀하겠다는 뜻을 알렸습니다.앞서 뉴진스 멤버들은 하이브와의 갈등으로 해임된 민희진 전 대표의 복귀 등을 요구했으나 받아들여지지 않자, 지난해 11월 어도어의 전속 계약 위반으로 계약이 해지됐다고 주장했습니다.어도어는 뉴진스와 계약이 여전히 유효하다며 같은 해 12월 전속 계약 유효 확인 소송을 내고, 본안 소송 결론이 나기 전까지 멤버들의 독자 활동을 막아 달라는 가처분 신청도 냈습니다. 법원은 가처분 사건과 1심에서 모두 어도어의 손을 들어줬습니다.#뉴진스 #어도어 #복귀 #하이브 #소송 #재판 #판결 #주가 #주식 #민지 #다니엘 #해린 #혜인 #하니', NULL, 'MBN', 'https://n.news.naver.com/mnews/article/057/0001918644', 'https://imgnews.pstatic.net/image/057/2025/11/13/0001918644_001_20251113112908313.jpg?type=w800', 'NEWS_ENERGY', NULL, '2025-11-13 11:29:08', 0, true, '2026-03-09 06:13:17.011686') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (928, '세아제강지주, 지난해 영업익 2058억원…전년比 2.7%↓', '매출액 3조7596억원…전년 대비 2.3% 증가세아제강지주가 지난해 매출 3조7596억원, 영업이익 2058억원의 잠정 실적을 기록했다. /더팩트 DB[더팩트ㅣ황지향 기자] 세아제강지주는 지난해 연결 기준 매출액 3조7596억원, 영업이익 2058억원의 잠정 실적을 기록했다고 6일 밝혔다. 매출은 전년 대비 2.3% 증가했지만 영업이익은 2.7% 감소했다.당기순이익은 978억원으로 16.5% 감소했다.세아제강지주는 건설 경기 침체와 글로벌 철강 시황 부진, 미국 관세 영향 등으로 국내 사업부문(세아제강)의 수익성이 악화됐다고 설명했다.반면 미국 법인(SSA)의 비축 재고를 활용한 관세 대응과 지난해 하반기 유정용강관 단가 회복, 해외 프로젝트 매출 반영 등 해외 사업부문이 국내 사업부문의 부진한 수익성을 상쇄하며 실적을 방어했다.세아제강지주는 대미 관세 등 시장 불확실성에도 불구하고 북미 지역의 유정용 및 송유관용 강관 수요가 견고하게 유지될 것으로 전망했다. 특히 데이터센터 건설 확대와 전력 수요 대응을 위한 인프라 확충이 중경(16~24인치) 이상 배관재 수요 확대 요인으로 작용할 것으로 보고 국내외 제조 거점을 활용해 해당 수요에 대응한다는 계획이다.또 중동 프로젝트(도라 가스전) 물량 공급과 캐나다 가스전 프로젝트 수행을 통해 실적을 확보할 계획이다. 세아윈드의 상업 생산 출하와 해상풍력 프로젝트 추가 수주를 추진하고 CRA 클레드 강관 등 고부가가치 제품 확대를 통해 시장 대응력을 강화한다는 방침이다.발로 뛰는 더팩트는 24시간 여러분의 제보를 기다립니다.▶카카오톡: ''더팩트제보'' 검색▶이메일: jebo@tf.co.kr▶뉴스 홈페이지: http://talk.tf.co.kr/bbs/report/write', NULL, '더팩트', 'https://n.news.naver.com/mnews/article/629/0000478884', 'https://imgnews.pstatic.net/image/629/2026/03/06/202616261772775976_20260306175708382.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-03-06 17:57:08', 0, true, '2026-03-09 06:13:23.639334') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (929, '지난달 밸류업 지수 2836.31 ''사상 최고''', '상승률 185.9% 코스피보다 높아기업가치 제고 공시 확산 추세연합뉴스지난달 밸류업 지수가 코스피보다 높은 상승률을 기록하며 사상 최고치를 경신했다.한국거래소는 5일 ''월간 기업가치 제고 현황''을 통해 지난달 26일 기준 밸류업 지수가 사상 최고치인 2836.31로 집계됐다고 밝혔다.이는 지수 산출 개시일인 지난 2024년 9월 30일 대비 185.9% 상승한 수치로, 같은 기간 코스피 지수 상승률 143.2%보다 높다. 반도체 등 주력 산업의 실적 개선과 정부의 지속적인 주주친화 정책 등이 뒷받침됐다.밸류업 상장지수펀드(ETF) 13종목의 순자산총액은 2조7000억원으로, 지난 2024년 11월 4일 최초 설정 대비 446.3% 증가했다.지난달 기준 기업가치 제고 계획을 신규 공시한 기업은 골드앤에스, 서울전자통신, JYP Ent, 아이센스, 세아제강지주 등 5개사로, 이 중 4개사가 코스닥 시장 기업이다. 거래소는 "기업가치 제고 계획 공시가 코스피 대형주 중심에서 코스닥 기업으로 확산되는 모습이 나타나고 있다"고 설명했다.이로써 기업가치 제고 계획 공시 기업은 누적 181개사로 확대됐다. 코스피 132개사, 코스닥 49개사다.주기적 공시 제출 기업은 총 11개사다. JB금융지주, 우리금융지주, 메리츠금융지주, 이녹스첨단소재는 지난 2024년 최초 공시 이후 연 1회 이상 주기적 공시를 제출한 것으로 나타났다. 거래소는 특히 메리츠금융지주가 2024년 7월 최초 공시 이후 매 분기 이행 현황을 공시하는 등 주주와의 소통을 지속했다고 언급했다.주주환원도 확대되는 추세다. 지난달 KB금융은 6000억원 규모의 자기주식 매입·소각을, DB손해보험과 메리츠금융지주는 각각 8000억원, 7000억원 규모의 자사주 소각을 결정했다.거래소 관계자는 "기업들의 부담 완화를 위해 시행 첫해는 기존보다 간소화된 공시가 가능하며, 설명회와 일대일 공시 컨설팅 등을 통해 밀착 지원할 예정"이라고 말했다. 한편 조세특례제한법 시행령 개정에 따라 고배당 기업은 특례 요건 충족 사실을 기업가치 제고 계획 공시로 제출해야 한다.', NULL, '파이낸셜뉴스', 'https://n.news.naver.com/mnews/article/014/0005486956', 'https://imgnews.pstatic.net/image/014/2026/03/05/0005486956_001_20260305181421109.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-03-05 18:14:21', 0, true, '2026-03-09 06:13:23.639334') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (930, '한국거래소 "2월 밸류업 지수, 사상 최고치 경신…코스피 수익률 상회"', '밸류업 ETF 순자산액 446.3% 급증한국거래소한국거래소는 지난달 말 밸류업 지수가 사상 최고치인 2836.31포인트를 기록했다고 5일 밝혔다.거래소가 이날 발표한 ''월간 기업가치 제고 현황(2026년 2월)''에 따르면 지난달 말 기준 밸류업 지수는 거래소가 지수를 산출하기 시작한 지난 2024년 9월 30일(992.13) 대비 185.9% 상승했다. 같은 기간 코스피 지수 상승률인 143.2%를 42.7%포인트 상회했다.밸류업 ETF 13종목의 순자산총액은 2조7000억원을 기록하며 2024년 11월 4일 최초 설정 당시 대비 약 446.3% 증가했다.지난달 기업가치 제고 계획을 신규 공시한 기업은 ▲골드앤에스(5일) ▲서울전자통신(12일) ▲JYP Ent.(20일) ▲아이센스(25일) ▲세아제강지주(25일·예고공시) 등 5사며 누적 181사(코스피 132사·코스닥 49사)가 공시했다.JB금융지주(5일)와 코웨이(6일) 등 11사는 주기적 공시를 제출했다.아울러 거래소는 지난달 27일부터 시행된 조세특례제한법 시행령 개정으로 고배당 기업은 과세특례 요건 충족 사실을 기업가치 제고 계획 공시로 제출해야 한다고 강조했다.거래소 관계자는 "고배당 기업이 기업가치 제고 계획 공시를 원활히 제출할 수 있도록 설명회 및 1:1 컨설팅 등을 통해 밀착 지원할 예정"이라고 말했다.', NULL, '매일신문', 'https://n.news.naver.com/mnews/article/088/0000999683', 'https://imgnews.pstatic.net/image/088/2026/03/05/0000999683_001_20260305162816433.png?type=w800', 'NEWS_ENERGY', NULL, '2026-03-05 16:28:16', 0, true, '2026-03-09 06:13:23.639334') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (931, '''신저가'' 늪 빠진 동전주, 상폐 패닉 속 ''병합''으로 활로 찾는 중', '활황장 뒤편 동전주 82개 신저가 수렁…병합으로 주가 올려도 시총 벽은 ''여전''사진=클립아트코리아코스피가 사상 첫 6000선을 돌파하며 활황이 이어지는 사이, 이른바 ''동전주''(액면가 1000원 미만 주식)들은 52주 신저가를 잇달아 경신하고 있다.26일 한국거래소에 따르면 올해 2월1일부터 25일까지 코스피·코스닥 시장에서 52주 신저가를 기록한 주가 1000원 이하 동전주는 82개에 달했다. 코스닥 상장사 78개, 코스피 4개다. 오는 7월 강화된 상장폐지 요건 시행을 앞두고 기업들은 주식병합으로 활로를 모색하고 있지만 시가총액이라는 더 높은 벽이 남아 있다는 우려가 나온다.━52주 신저가 동전주 82개…주식병합 잇따라━증시 활황에도 동전주의 추락은 멈추지 않고 있다. 주가 1000원 미만 동전주는 오는 7월 1일부터 새로 신설되는 상장폐지 요건에 직접 적용된다. 30거래일 연속 주가가 1000원 미만이면 관리종목으로 지정되고 이후 90거래일 동안 45거래일 연속 1000원 이상을 회복하지 못하면 최종 상장폐지된다.퇴출 압박이 현실화되자 기업들은 주식병합 카드를 꺼내들고 있다. 에이프로젠은 23일 주식을 15주에서 1주로 합치는 병합을 결정했다고 공시했다. 시장의 반응은 즉각적이었다. 다음 날인 24일 에이프로젠바이오로직스 주가는 상한가를 기록했다. 같은 날 휴마시스와 경남제약도 각각 5주를 1주로 합치는 주식병합 결정을 공시했다.두 회사 모두 적정 유통주식수 유지와 주가 안정화가 목적이라고 밝혔다. 이론상 주가 820원이던 휴마시스는 4100원으로, 640원이던 경남제약은 3200원으로 오르게 된다.━주식병합으로 주가올려도 코스닥 200억원 이상 시총 문턱에 ''공포''━업계에서는 주식병합이 근본적인 해법이 될 수 없다는 지적이 나온다. 주식 수를 줄여 주가를 높이는 방식이지만 기업 가치의 총합인 시가총액은 변하지 않기 때문이다. 증권업계 관계자는 "주식병합으로 주가는 높일 수 있어도 시가총액은 그대로"라며 "결국 시총 기준을 충족하지 못하면 두 번째 벽에서 막힌다"고 말했다.실제로 7월부터 코스닥 시가총액 상장폐지 기준은 200억원으로 오른다. 내년 1월에는 300억원으로 추가 상향된다. 코스피도 각각 300억원, 500억원으로 강화된다. 동전주 요건을 주식병합으로 피하더라도 시총 요건이라는 다음 관문이 기다리는 셈이다. 금융당국은 이 같은 우회 시도에 대비해 병합 후 액면가 미만인 경우에도 상장폐지 요건에 포함시키기로 했다.올해 1월 금융투자협회는 K-OTC 시장에 ''상장폐지기업부''를 신설했다. 상장폐지 기업이 6개월간 거래를 통해 환금성을 확보하고 요건 충족 시 재상장도 가능한 경로를 마련한 것이다. 하지만 이 역시 근본적인 기업 체질 개선 없이는 한계가 있다는 시각이 지배적이다./그래픽=강지호 기자━부실기업 퇴출 vs 기술기업 역차별…시장 정상화 논쟁━금융당국은 이번 개편이 시장 신뢰 회복을 위한 불가피한 조치라는 입장이다. 금융위원회와 한국거래소는 지난 12일 ''부실기업 신속·엄정 퇴출을 위한 상장폐지 개혁방안''을 발표하고 2027년 6월까지 ''상장폐지 집중관리기간''을 운영하기로 했다. 관리단은 거래소 코스닥본부 담당 부이사장을 단장으로 총 4개 팀 20명 체제로 꾸려져 있다.이번 제도 개편을 주도한 권대영 금융위 부위원장은 "투자자에게 신뢰받는 시장으로 도약하기 위해서는 더 빠르고 더 엄정한 부실기업 퇴출이 필요하다"며 "코스닥 시장은 지난 20년간 진입이 1353개사, 퇴출은 415개사에 그쳐 다산소사(多産少死) 구조가 지속됐고, 시총은 8.6배 올랐지만 지수는 1.6배 상승에 머물렀다"고 강조했다.전문가들도 시장 정상화의 방향 자체는 옳다고 본다. 이상헌 iM증권 연구원은 "이미 이전에 이뤄졌어야 할 시장 정상화"라면서도 "주가를 끌어올리는 외형 조정만으로는 부족하고 실적이라는 기초체력이 뒷받침돼야 한다"고 말했다.일각에서는 선의의 피해를 우려하는 목소리도 나온다. 연구개발(R&D)에 집중하는 초기 기술기업의 경우 단기 실적보다 기술력과 성장 가능성이 기업가치의 핵심인데, 주가와 시총 잣대만으로는 이를 제대로 평가할 수 없다는 지적이다.한 IB업계 관계자는"동전주 요건 자체는 필요하다"며 "다만 기술특례 기업처럼 R&D 단계에서 주가가 낮을 수밖에 없는 곳까지 같은 잣대로 보는 건 무리가 있다"고 지적했다. 최근 한국거래소의 시뮬레이션 결과에 따르면 올해 코스닥에서만 최대 220개사가 상장폐지 영향권에 드는 것으로 추산된다. 부실기업 퇴출이라는 제도적 취지를 살리면서도 성장 잠재력을 갖춘 유망 기업이 고사하지 않도록 정교한 보완책을 마련하는 것이 향후 과제로 남아 있는 상황이다.', NULL, '동행미디어 시대', 'https://n.news.naver.com/mnews/article/417/0001131693', 'https://imgnews.pstatic.net/image/417/2026/02/26/0001131693_001_20260226165406616.jpg?type=w800', 'NEWS_BIO', NULL, '2026-02-26 15:16:59', 0, true, '2026-03-09 06:13:30.994171') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (932, '코오롱글로벌, 평택 고덕 현장서 AI 기반 안전점검 강화', '김일호 CSO 주관, 김영범 사장 등 30여명 참석현장 위험 요인 집중 점검 및 종사자 의견 청취[서울=뉴시스] 김영범 코오롱글로벌 사장이 평택 고덕 공공폐수처리시설에서 안전보건 합동점검을 실시하고 있다. (출처=코오롱글로벌) 2026.03.03. photo@newsis.com *재판매 및 DB 금지[서울=뉴시스]이종성 기자 = 코오롱글로벌은 지난달 27일 평택 고덕 공공폐수처리시설 4단계 건설공사 현장 안전보건 합동점검을 실시했다고 3일 밝혔다.점검은 김일호 코오롱글로벌 최고안전책임자(CSO)가 주관했으며 김영범 사장, 김동헌 공사지원본부 상무, 협력사 대표 등 30여명이 참석했다.합동점검에서는 ''코오롱 세이프티 골든 룰'' 행동 강령을 중심으로 현장을 점검했다. 합동점검단은 근로자 이동통로 전도사고, 밀폐공간 질식사고 등을 점검하고 잠재적 위험 요인에 대한 해결을 당부했다.이날 김 사장은 근로자 휴게시설을 점검하고 종사자 의견청취 시간을 가졌다. 이후 현장안전의 중요성을 강조하며 건의사항에 대한 적극적인 지원을 약속했다.김 사장은 "관행적인 절차에 얽매이기보다 무엇이 현장의 안전을 지키는 실질적인 방법인지 끊임없이 고민하고 행동해야 한다"며 "원청과 협력사가 단순한 협력을 넘어 한 몸처럼 움직이는 일심동체의 마음으로 안전 관리에 임해 주길 바란다"고 강조했다.한편 코오롱글로벌은 인공지능(AI) 기술을 기반으로 한 안전시스템을 구축하고 보다 체계적인 안전관리를 위해 노력하고 있다.지난해 10월 그룹 IT 계열사인 코오롱베니트와 협력해 안전 관제 시스템 ''비전 AI''를 구축했다. 해당 시스템은 CCTV 영상을 기반으로 ▲안전모 미착용 ▲위험구역 진입 ▲중장비 접근 등 건설 현장의 다양한 위험 상황을 실시간으로 탐지하고, 이를 언어 알림으로 변환해 사고를 예방한다.', NULL, '뉴시스', 'https://n.news.naver.com/mnews/article/003/0013799035', 'https://imgnews.pstatic.net/image/003/2026/03/03/NISI20260303_0002074638_web_20260303163042_20260303173014811.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-03-03 17:29:04', 0, true, '2026-03-09 06:13:36.042705') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (933, 'IFC몰 샐러드 맛집 새 단장…윤잇IFC몰점 리뉴얼 오픈', '"여의도 점심, 더 빠르고 신선하게"… 여의도 혼밥·직장인 점심 수요 겨냥그랩앤고 강화, 페어링 티·앱 기반 서비스까지 확대2월 13일 리뉴얼 오픈한 윤잇 IFC몰점 전경. 스마트팜 ''윤잇팜''을 매장 전면에, 오더존을 입구 왼쪽에 배치해 고객 동선을 직관적으로 구성했다. 사진=SB성보 제공(서울=뉴스1) 이재상 기자 = 샐러드 브랜드 윤잇(yunit)은 리뉴얼 공사를 마치고 서울 여의도 IFC몰점을 13일 정식 재오픈했다고 이날 밝혔다.이번 리뉴얼은 여의도 직장인들의 점심시간 흐름에 맞춰 매장 동선을 단순화하고, 혼자서도 편하게 식사할 수 있는 좌석 환경과 서비스 접근성을 함께 개선한 것이 특징이다.윤잇은 SB성보가 운영하는 F&B 브랜드로, 매장 내 자체 스마트팜 ''윤잇팜(Yunit Farm)''에서 재배한 친환경 수경재배 채소를 식재료로 활용한다. 이를 바탕으로 샐러드와 고단백 플레이트를 선보이며, ''건강하고 지속 가능한 한 끼''라는 브랜드 철학을 제안하고 있다.가장 큰 변화는 고객의 시선과 이동을 고려한 공간 재설계다. 매장 입구에서 주문, 픽업, 좌석으로 이어지는 흐름을 한눈에 이해할 수 있도록 구성해, 점심 피크타임에도 빠르게 식사를 마칠 수 있도록 했다. 특히 대기 없이 제품을 선택해 구매할 수 있는 그랩앤고(Grab&Go) 존을 강화해 직장인 고객들의 이용 편의성을 높였다.윤잇의 정체성을 담은 스마트팜 윤잇팜은 매장 전면에 배치됐다. 매장에서 재배되는 친환경 수경재배 채소가 자연스럽게 시선을 끌며, 윤잇이 지향하는 ''팜 투 테이블(Farm to Table)'' 가치를 고객이 눈으로 직접 확인할 수 있도록 했다.메뉴 역시 간결하게 정비됐다. 윤잇의 대표 샐러드와 함께 치킨·살몬·비프를 활용한 플레이트 메뉴를 중심으로 구성해, 가볍지만 든든한 점심을 원하는 고객들의 선택 폭을 넓혔다.음료 및 서비스 경험도 확장됐다. 기존 커피 메뉴와 커피 구독 서비스에 더해, 윤잇의 시그니처 서비스인 무료 페어링 티 3종을 새롭게 도입했다. 메뉴와 어울리는 티를 함께 제안하는 페어링 티 서비스는 윤잇이 국내에서 최초로 선보인 식사 기반 티 페어링 서비스로, 윤잇팜에서 재배한 허브를 활용해 식사를 보다 산뜻하게 마무리할 수 있도록 돕는다.윤잇 IFC몰점은 이번 리뉴얼을 통해 윤잇 브랜드 전용 앱을 활용한 주문·픽업 서비스를 적극 활용한다. 윤잇 전용 앱은 간편 주문과 포장 이용, 포인트 적립 기능을 제공해 점심 피크타임에도 매장 대기 없이 보다 효율적으로 식사할 수 있도록 돕는다.그동안 잠실타워730점과 스타필드 에비뉴그랑서울점에서만 사용할 수 있었던 윤잇 전용 앱은, 이번 IFC몰점 리뉴얼을 계기로 윤잇 전 매장에서 사용할 수 있게 됐다. 앱을 통해 멤버십 및 구독형 서비스도 함께 운영 중이며, 멤버십 고객에게는 메인 메뉴 20% 할인 쿠폰이 제공돼 반복 방문 고객들이 보다 합리적으로 매장을 이용할 수 있다.윤잇 관계자는 "이번 IFC몰점 리뉴얼은 단순히 매장을 새롭게 단장하는 것을 넘어, 여의도 직장인들이 바쁜 일상에서도 윤잇이 지향하는 ‘건강하고 지속 가능한 한 끼’를 보다 편안하게 경험할 수 있도록 식사 환경과 서비스를 함께 재설계한 사례다"며 "앞으로도 매장 운영과 앱 기반 서비스를 유기적으로 연결해, 일상에서 신뢰할 수 있는 윤잇만의 식사 경험을 지속해서 확장해 나갈 것"이라고 밝혔다.', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008774479', 'https://imgnews.pstatic.net/image/421/2026/02/13/0008774479_001_20260213135910799.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-13 13:58:11', 0, true, '2026-03-09 06:13:41.042262') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (934, '[업계는 지금] TYM, 트랙터시장 디지털대응 두각', 'SB위드아그로, 채소 부산물 순환모델 구축누보, 美원예기업과 비료공급 계약TYM(대표 김희용·김도훈)은 북미 트랙터시장 디지털서비스 대응력에서 경쟁업체 대비 높은 평가를 받았다고 22일 밝혔다.미국 시장조사업체 ‘파이드 파이퍼’가 수행한 ‘2026 인터넷 리드 효율성 조사’ 결과에 따르면 TYM은 종합 점수 32점을 획득했다. 북미 진출 국내 농기계 브랜드 중 1위이자 전체 순위 2위다.SB성보의 자회사SB위드아그로(대표 한기돈)는 경기 여주 갈색거저리유충(밀웜) 사육농가(산마루곤충농원)와 협력해 채소 부산물(사진)을 곤충 사료 원료로 활용하는 순환경제 모델을 구축했다고 20일 밝혔다.스마트팜에서 로메인·버터헤드 등 고급 양채류를 재배하는 SB위드아그로는 생산과정에서 발생하는 부산물을 매주 80㎏, 연간 4t 규모로 농가에 제공한다.누보가 미국 가정원예기업인 ‘더 스캇츠 미라클-그로 컴퍼니’와 5년간 비료 공급 계약을 체결했다. 누보누보(대표 김창균·이경원)는 자사 미주 법인이 미국 최대 가정원예기업인 ‘더 스캇츠 미라클-그로 컴퍼니’와 5년간 비료 공급 계약을 체결했다고 14일 밝혔다.이를 통해 누보는 ‘발포확산형 비료 제조’ 기술이 적용된 제품을 연간 200만달러 규모로 미국에 수출할 것으로 예상된다고 설명했다.', NULL, '농민신문', 'https://n.news.naver.com/mnews/article/662/0000087541', 'https://imgnews.pstatic.net/image/662/2026/01/30/0000087541_001_20260130050310860.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-30 05:03:10', 0, true, '2026-03-09 06:13:41.042262') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (935, 'SB위드아그로, 지역 밀웜 농가와 순환경제 모델 구축', '폐기물 없는 스마트팜, 여주에서 시작된 순환경제연간 최대 12톤 농업 부산물 재자원화… 탄소 6.7톤 저감 효과 기대채소 재배 과정에서 발생한 부산물을 밀웜 사료로 활용하는 모습. SB위드아그로는 지역 곤충 농가와 협력해 순환경제 모델을 운영하고 있다. (사진=SB성보)(서울=뉴스1) 이재상 기자 = SB성보의 자회사 SB위드아그로가 경기 여주 지역 밀웜 사육 농가와 협력해 스마트팜 채소 재배 과정에서 발생하는 부산물을 곤충 사료로 활용하는 순환경제 모델을 구축했다.이번 협력은 스마트팜에서 발생한 자원을 폐기하지 않고 지역 곤충 농가의 사료 자원으로 활용한 사례로, 지역 기반의 환경·경제적 상생 모델이라는 점에서 의미가 있다.여주에 위치한 SB위드아그로는 스마트팜을 통해 유러피안 채소를 재배·판매하고 있다. 유러피안 채소는 로메인, 버터헤드 등 식감이 부드럽고 풍미가 뛰어난 고급 엽채류로, 샐러드의 주재료로 사용된다.채소 재배 과정에서 발생하는 부산물은 현재 곤충산업진흥협동조합 소속 산마루곤충농원에 사료 원료로 제공되고 있다. 매주 약 80㎏, 연간 약 4톤 규모의 부산물이 밀웜 사육에 활용된다.이번 협력은 지난해 11월, 산마루곤충농원이 여주 지역 스마트팜 관련 기사를 접한 뒤 SB위드아그로를 직접 방문하며 시작됐다.산마루곤충농원은 SB위드아그로의 스마트팜에서 발생한 부산물로 샘플 테스트를 진행한 결과, 기호성과 섭취율 등의 측면에서 밀웜 사육에 적합하다고 판단해 현재 사료 전량을 해당 부산물로 교체해 운영하고 있다. 같은 지역 내 기업과 농가가 유기적으로 연결돼 운영 효율을 높이는 동시에, 부산물을 다시 자원으로 활용하는 순환 구조를 만든 것이다.경기 여주에 위치한 SB위드아그로의 스마트팜 윤잇팜(yunit Farm) 전경. 지역 농가 협력과 스마트팜 운영 경험을 바탕으로 다양한 사업 모델을 검토하고 있다. (사진=SB성보)환경적 성과 역시 수치로 가시화된다. SB위드아그로는 연간 120톤 규모의 유러피안 채소 생산 시설을 보유하고 있으며, 수확 과정에서 약 12톤(손실률 10% 기준)의 채소 부산물이 발생한다.현재 시설 가동률 70% 수준에서 연간 약 4톤을 사료 자원으로 재자원화하고 있으며, 2026년 가동률이 100%에 도달할 경우 수확 과정에서 발생하는 부산물 전량을 다시 자원화할 수 있을 것으로 기대한다.글로벌 탄소 발자국 데이터 플랫폼 카본클라우드(CarbonCloud)에 따르면 상추 기준으로 산정한 엽채류의 평균 탄소 배출량은 1㎏당 약 0.56kg CO₂e로, 연간 12톤의 해당 부산물을 자원으로 활용할 경우 약 6.7톤의 CO₂e 배출 저감 효과가 있다.이는 승용차 1~2대의 연간 배출량 또는 나무 약 300그루가 1년간 흡수하는 탄소량에 해당한다. 여기에 음식물 쓰레기 처리 비용 절감 효과까지 더하면 실질적인 환경·경제적 가치는 더욱 커질 것으로 기대된다.이번 협력은 농업 부산물의 재자원화를 통해 폐기물을 줄이는 동시에, 밀웜 농가에는 안정적인 사료 공급처를 제공하는 지역 기반 상생 사례로 평가받고 있다.산마루곤충농원 관계자는 "신선한 사료를 지역에서 안정적으로 공급받을 수 있게 됐다"며 "기존에 사용하던 양배추 사료보다 품질이 좋아 밀웜 생육에도 긍정적인 영향을 주고 있다"고 말했다.SB위드아그로 신정훈 본부장은 "스마트팜 운영 과정에서 발생하는 부산물을 다시 지역 농가의 자원으로 연결하는 것이 이번 협력의 핵심"이라며 "폐기물 감축이라는 환경적 가치와 함께, 지역 농가에 실질적인 도움이 되는 구조를 만드는 데 의미를 두고 있다"고 말했다.이어 "앞으로도 스마트팜 운영 전반에서 자원 순환 가능성을 지속해서 모색하며 지역사회와 함께 성장하는 ESG 모델을 확대해 나가겠다"고 덧붙였다.SB위드아그로는 여주 지역 내 다른 곤충 농가와의 협력 가능성을 검토하고 있으며, 유러피안 채소 외에도 다양한 작물의 부산물을 활용하는 방안도 단계적으로 추진할 계획이다.', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008727697', 'https://imgnews.pstatic.net/image/421/2026/01/22/0008727697_001_20260122085831783.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-22 08:58:00', 0, true, '2026-03-09 06:13:41.042262') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (936, '대웅, 시지바이오 인수 우선협상자로 IMM PE 선정', '시지바이오[시지바이오 제공. 재판매 및 DB 금지](서울=연합뉴스) 최현석 기자 = 대웅그룹은 재생의료 분야 계열사 시지바이오 인수우선협상자로 IMM PE를 선정했다고 6일 밝혔다.매각 대상은 대웅그룹 오너일가 가족회사로 시지바이오 최대주주인 에이하나가 보유한 지분 51%다.매각 금액은 인수 작업은 실사와 본계약 체결 등을 거쳐 확정될 예정이지만 일부에서는 시장에서 시지바이오 기업가치가 1조 원대로 평가되고 있는 점을 근거로 6천억원 전후로 추정하고 있다.시지바이오는 뼈와 피부, 혈관 등 인체 조직 재생에 필요한 의료기기와 치료제 등을 생산하고 있으며, 2024년 매출 2천8억원을 기록했다.harrison@yna.co.kr', NULL, '연합뉴스', 'https://n.news.naver.com/mnews/article/001/0015941606', 'https://imgnews.pstatic.net/image/001/2026/03/06/PCM20240229000098505_P4_20260306074413131.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-06 07:43:44', 0, true, '2026-03-09 06:13:49.690142') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (937, '대웅 계열 시지바이오 매각 추진…IMM PE 우선협상대상자 선정', '[파이낸셜뉴스] 대웅그룹 계열 재생의료 기업 시지바이오가 사모펀드(PEF) 운용사 IMM프라이빗에쿼티(PE)에 매각되는 절차에 들어갔다. 5일 투자은행(IB) 업계에 따르면 IMM PE는 최근 시지바이오 인수 우선협상대상자로 선정돼 실사에 착수했다. 매각 대상은 시지바이오 최대주주 측이 보유한 경영권 지분 약 51% 수준으로 알려졌다.현재 거래 조건은 확정되지 않았으며, 지분율과 최종 거래 가격 등은 향후 실사와 협상을 거쳐 결정될 예정이다. 다만 업계에서는 이번 거래 규모가 약 6000억원 수준에서 거론되고 있는 것으로 전해졌다.시지바이오는 뼈·피부·유착방지제 등 생체재료 기반 인공조직 대체재를 주력으로 하는 재생의료 기업이다. 특히 골형성 단백질(BMP) 기반 골이식재 제품을 중심으로 국내 시장에서 높은 점유율을 확보하고 있다.대표 제품인 ‘노보시스 퍼티(NOVOSIS Putty)’는 골절 치료나 척추 수술 시 손상 부위에 주입해 뼈 생성을 유도하는 골대체재로, 국내 최초로 개발된 BMP 기반 제품이다. 현재 미국 식품의약국(FDA) 확증 임상 승인을 기반으로 미국과 일본 등 해외 시장 진출도 추진 중이다.실적도 꾸준한 성장세를 보이고 있다. 시지바이오 매출은 2022년 1297억원에서 2024년 2008억원으로 증가했으며, 지난해 상각전영업이익(EBITDA)은 400억원을 넘어선 것으로 알려졌다.최근에는 그룹 내부 사업 구조 재편도 진행됐다. 시지바이오는 물적분할을 통해 지주 성격의 법인을 중심으로 주요 사업 계열사를 재편했으며, 의료기기 및 재생의료 관련 사업을 시지바이오 산하로 묶는 구조를 구축했다.시장에서는 이를 기업가치 제고와 함께 매각을 염두에 둔 사전 정비 작업으로 해석하는 시각도 나온다.IMM PE는 과거 제약·바이오 분야 투자 경험도 보유하고 있다. IMM PE는 2020년 한국콜마 제약사업부를 인수해 제뉴원사이언스를 출범시킨 뒤 2024년 약 6200억원에 매각하며 투자 원금 대비 약 두 배 수준의 수익을 거둔 바 있다.업계에서는 IMM PE가 시지바이오 인수를 통해 재생의료 및 의료기기 분야 포트폴리오 확대에 나설 가능성이 있는 것으로 보고 있다. 다만 현재는 우선협상대상자 선정 단계인 만큼 향후 실사 결과와 협상 과정에 따라 거래 구조나 가격 등이 조정될 가능성도 남아 있다.', NULL, '파이낸셜뉴스', 'https://n.news.naver.com/mnews/article/014/0005487041', 'https://imgnews.pstatic.net/image/014/2026/03/05/0005487041_001_20260306093822857.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-05 21:02:11', 0, true, '2026-03-09 06:13:49.690142') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (940, '유니테스트, SK하이닉스 HBM4용 ''번인 테스터'' 양산 검증 완료', '디아이 이어 공급망 진입…실제 수주 성과 기대반도체 검사장비 전문기업 유니테스트가 SK하이닉스 HBM4(6세대 고대역폭메모리)용 번인 테스터(Burn-in Tester) 공급망에 합류한 것으로 파악됐다.5일 업계에 따르면 유니테스트는 지난달 SK하이닉스와의 HBM4용 번인 테스터 양산 퀄(품질) 테스트를 완료했다.SK하이닉스 청주 M15(사진=SK하이닉스)번인 테스터는 반도체에 극한의 고온·고전압 환경을 가하고, 이후 제품의 불량 여부를 판별하는 장비다. HBM4는 이전 세대 대비 데이터 처리 속도 상승, D램 적층 수 증가해 이에 대응하는 신규 테스트가 필요하다. 이에 SK하이닉스는 국내 복수의 후공정 장비기업들로부터 HBM4용 번인 테스터 검증을 진행해 왔다.유니테스트의 경우 지난해 데모 장비로 성능 평가를 통과해, 지난달 양산용 퀄테스트까지 성공적으로 마무리한 것으로 파악됐다. 회사가 HBM 공급망 진입하는 것은 이번이 처음이다.관건은 실제 수주량이다. SK하이닉스는 올해부터 HBM4 양산을 본격적으로 확대할 계획으로, 지난해 말부터 HBM4 번인 테스터에 대한 초도 발주에 나섰다. 청주 P&T(패키징&테스트), M15X 등 팹 투자도 적극 진행하고 있어, 연간으로 지속적인 투자가 진행될 것으로 예상된다.다만 SK하이닉스 HBM4용 번인 테스터 공급망은 또 다른 장비기업인 디아이가 자회사 디지털프론티어를 통해 지난해 말 선제적으로 진입한 바 있다. 유니테스트는 세컨 벤더의 지위다.반도체 업계 관계자는 "최근 유니테스트가 HBM4 공급망에 합류한 만큼, 조만간 가시적인 수주 성과가 나타날 가능성이 있다"며 "물론 이미 경쟁사가 진입해 있기 때문에 공급 비중을 최대한 빠르게 확보해야할 것"이라고 말했다.', NULL, '지디넷코리아', 'https://n.news.naver.com/mnews/article/092/0002412967', 'https://imgnews.pstatic.net/image/092/2026/03/05/0002412967_001_20260305103010907.jpg?type=w800', 'NEWS_SEMI', NULL, '2026-03-05 10:30:10', 0, true, '2026-03-09 06:14:02.960948') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (941, '디아이, 삼성전자에 96억 반도체 검사장비 공급 [공시pick]', '◆…조세일보 DB디아이가 삼성전자에 반도체 검사 장비를 공급하는 계약을 체결했다고 3일 공시했다.계약금액은 96억원으로 2024년 연결 기준 매출의 4.5% 규모다. 공급 제품은 DDR5용 차세대 번인 테스터(Burn In Tester)와 NAND용 고속 번인 테스터다.번인 테스트는 반도체를 고온·고전압 환경에서 일정 시간 구동해 초기 불량을 선별하는 검사 공정이다. DDR5 메모리 확산으로 고속 동작 환경에서 안정성을 검증하는 검사 장비 수요가 늘고 있다.계약 기간은 오는 12월 31일까지다. 대금은 납품 후 10일 이내 중도금 90%, 검수 후 10일 이내 잔금 10%를 지급하는 조건이다. 계약금액은 부가가치세(VAT)를 제외한 금액이다.', NULL, '조세일보', 'https://n.news.naver.com/mnews/article/123/0002378798', 'https://imgnews.pstatic.net/image/123/2026/03/04/0002378798_001_20260304132212754.jpg?type=w800', 'NEWS_SEMI', NULL, '2026-03-04 13:22:12', 0, true, '2026-03-09 06:14:02.960948') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (942, '''아아'' 마시면 밤새 뒤척이는데…직장인 환호한 ''이 음료'' [트렌드+]', '대체커피 팝업, 슈퍼말차·산스 현장 호평이달부터 식약처 디카페인 표시 기준 강화차·제약업계까지 ''카페인 제로'' 확산4일 신세계백화점 강남점(센트럴시티)에 위치한 산스 팝업 매장에 사람들이 줄을 서고 있다.  /사진=박상경 기자4일 저녁 신세계백화점 강남점(센트럴시티)에 마련된 대체 커피 브랜드 ''산스''의 팝업 매장. 퇴근 시간을 넘은 시각에도 제품을 구매하려는 발길이 이어졌다. 이곳에서는 캐모마일·국화·카카오닙스·카다멈·히비스커스 등 20가지 원료를 조합해 나만의 대체 커피를 커스터마이징할 수 있다. 매장 관계자는 "한 번 시음해보고 나중에 다시 와서 속이 편했다며 제품을 구매해가는 고객들이 많다"고 전했다. 산스는 서울 익선동에 국내 최초의 대체 커피 전문 오프라인 매장을 낸 곳이기도 하다.이날 현장에서 ''슬로우 에이징'' 바틀을 구매한 박모 씨(27)는 "카페인에 취약해서 아침에도 빈속에 커피를 못 마신다"며 "속이 편하다길래 궁금해서 시음해봤는데 생각보다 맛있어서 하나 구입했다"고 말했다. 실제로 슬로우 에이징을 음용해보니 라벤더 향이 감도는 헤이즐넛 라떼와 흡사한 풍미를 느낄 수 있었다.4일 서울 종로구 북촌에 마련된 슈퍼말차의 ''슈퍼보리'' 리뉴얼 팝업 매장.  /사진=박상경 기자같은 날 오후 서울 종로구 북촌에 마련된 슈퍼말차의 ''슈퍼보리'' 리뉴얼 팝업 매장에는 잘 자는 습관을 제안하는 문구들이 곳곳에 붙어 방문객을 맞이했다. 카페인이 전혀 들어있지 않은 보리 커피 시음 코너와 곡물 보리를 활용한 글루텐 프리 쿠키 등이 공간을 채웠다. 매장 직원은 "최근 건강과 숙면을 위해 카페인을 멀리하려는 이들이 늘면서 대체 커피 시장이 커지고 있다"며 "음료 시음 후 속이 편하다며 제품을 테이크아웃해 가는 손님도 많았다"고 말했다.전 세계 대체 커피 시장 2034년 6조 4000억 규모 전망식음료 시장에서 무알코올·무설탕에 이어 무카페인이 새로운 흐름으로 뜨고 있다. 3일 시장조사기관 엠브레인 트렌드모니터가 전국 만 13세부터 69세 남녀 1200명을 대상으로 조사한 결과, 응답자의 49.2%가 건강을 위해 커피 섭취를 줄이는 것이 바람직하다고 답했다. 카페인 과다 섭취에 대한 우려와 함께 속쓰림·수면장애 등을 경험한 소비자가 늘면서 무카페인 또는 저카페인 음료를 찾는 경향이 뚜렷해졌다는 분석이다.식음료(F&B) 현장에서 근무하는 부모 씨(28)는 "요즘 술을 줄이는 트렌드여서 저녁에 술집이 아닌 카페를 가는 경우가 많다"며 "아직까지는 디카페인이나 논커피 음료의 인지도가 더 높지만 이런 흐름이면 대체 커피도 유행할 수 있을 것 같다"고 내다봤다.글로벌 시장조사기관 포춘 비즈니스 인사이트에 따르면 전 세계 대체 커피 음료 시장 규모는 지난해 기준 24억 1000만 달러(한화 약 3조 4900억 원)에 달한다. 향후 연평균 6.98% 성장해 2034년에는 44억 1000만 달러(약 6조 4000억 원)에 이를 것으로 전망된다.식약처 디카페인 표시 기준 강화… 무카페인 제품군 확대사진은 기사와 무관함.  /사진=게티이미지뱅크식품의약처도 디카페인 커피 표시 기준을 강화하고 있다. 이전까지는 카페인을 90% 이상 제거하면 ''디카페인''으로 표시할 수 있었으나, 개정안에 따라 잔류 카페인 함량이 0.1% 이하인 커피만 디카페인 표시가 가능하다. 기준이 엄격해지면서 카페인 민감층은 물론 임산부·수유부·건강 관리 목적의 소비자들 사이에서는 아예 카페인이 없는 무카페인 제품에 대한 관심이 급증하고 있다.변화하는 흐름에 맞춰 업계에서는 보리·치커리 등 식물성 원료로 커피 풍미를 낸 대체 커피 출시가 줄을 잇고 있다. 차 브랜드 티젠은 지난 1월 말 보리를 이용한 대체 커피 ''카페 오르조''를 출시했고, 빙그레는 지난해 치커리 원료를 활용한 ''치커리 브루 블랙''을 선보였다.무카페인 차 음료 역시 물처럼 부담 없이 마실 수 있는 라이트 드링크로 각광받는 중이다. 동원F&B는 보리차와 옥수수차 제품을 중심으로 무카페인 라인업을 강화하고 있으며, 스타벅스 코리아도 카페인이 없는 허브티 옵션을 확대하고 있다.무카페인 트렌드는 제약업계로도 번져 대원제약 ''콜대원나이트시럽'' 등 나이트 감기약 시장에서도 수면 방해 요소를 없애기 위해 무카페인을 핵심 정체성으로 내세우고 있다.이은희 인하대 소비자학과 교수는 "최근의 무카페인 선호 현상은 소비자가 자신의 건강 상태와 취향에 맞춰 성분을 세밀하게 선택하는 커스터마이징 트렌드의 연장선"이라며 "헬시 플레저나 웰니스처럼 건강에 대한 관심이 어느 때보다 높은 상황에서 단백질이나 당분만큼 카페인 역시 음료 선택의 핵심 요소가 된 것"이라고 분석했다.', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005258849', 'https://imgnews.pstatic.net/image/015/2026/03/05/0005258849_001_20260305212511807.jpg?type=w800', 'NEWS_BIO', NULL, '2026-03-05 19:15:10', 0, true, '2026-03-09 06:14:12.726029') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (943, '대원제약, 수면건강 신제품 ''꿀잠샷''·''올영세일'' 참여', '올리브영 정기 행사·수면 케어 카테고리 기획전 진행식약처 개별인정형 원료 함유…"합리적 구성 선보여"대원제약이 수면건강 신제품 ''꿀잠샷''으로 ''올영세일''과 ''슬립웰 기획전''에 참여한다.(대원제약 제공)/뉴스1(서울=뉴스1) 황진중 기자 = 대원제약의 건강기능식품 브랜드 대원헬스는 신제품 ''꿀잠샷''이 올리브영 입점과 동시에 ''올영세일·슬립웰 기획전''의 주요 품목으로 선정됐다고 4일 밝혔다.꿀잠샷은 오는 3월 첫째 주부터 진행되는 올리브영 대표 정기 행사 올영세일과 수면 케어 슬립웰 기획전을 통해해 온·오프라인 매장에서 합리적인 가격으로 판매된다.이 제품은 수면 건강에 도움을 줄 수 있는 식품의약품안전처 개별인정형 원료인 라임과피추출물 300㎎을 주원료로 담았다. 액상 제형으로 섭취 편의성을 높인 점을 앞세워 2030세대의 수요를 공략해 올리브영 내 수면 케어 카테고리에서의 브랜드 인지도를 제고한다는 전략이다.대원제약 헬스케어사업본부 백인영 본부장은 "꿀잠샷의 주원료인 라임과피추출물은 라임의 껍질에서 추출한 안전한 식물성 원료"라면서 "인체적용시험을 통해 총수면 시간 증가, 입면 시간 감소, 수면 효율 증가 등 수면 질 개선과 관련된 유의미한 결과가 확인되어 식약처로부터 기능성을 인정받은 개별인정 건강기능식품"이라고 소개했다.또한 "이번 올영세일과 슬립웰 기획전을 통해통해 수면에 불편함을 겪는 많은 분이 꿀잠샷을 합리적으로 경험해 보시길 바란다"고 전했다.', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008804842', 'https://imgnews.pstatic.net/image/421/2026/03/04/0008804842_001_20260304092923311.jpg?type=w800', 'NEWS_BIO', NULL, '2026-03-04 09:28:55', 0, true, '2026-03-09 06:14:12.726029') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (944, '빵값 이어 라면·과자값 인하? 중동발 리스크에 ‘속앓이’ [푸드360]', '라면4사 소집한 정부 ‘물가 안정’ 강조밀가루·설탕 이어 전분당도 담합 의혹중동발 유가·환율 급등 우려 본격화에“원가 부담 커질 수밖에 없다” 하소연서울 시내 한 대형마트의 라면 판매대 모습. [연합][헤럴드경제=김진 기자] 정부의 물가 안정 기조가 식품업계 전반에 가격 조정 압박으로 작용하고 있다. 지난달 밀가루·설탕값 인하로 촉발된 빵·케이크 가격 인하에 이어, 이번엔 라면·과자 가격이 도마 위에 올랐다.9일 식품업계에 따르면 일부 라면·제과업체들은 정부 기조와 관련해 실무선에서 가격 인하 검토에 들어갔다. 지난달 밀가루·설탕 가격 인하 등에 따른 판매가 조정 요인에 대한 검토다. 다만 한 업계 관계자는 “밀가루 등 원재료가 원가에서 차지하는 비중이 적어 원론적인 논의의 성격이 강하다”고 설명했다.이들 업체의 내부 검토는 연일 물가 안정을 강조하고 있는 정부 기조를 의식한 것이다. 농림축산식품부는 지난 5일 농심·오뚜기·삼양식품·팔도 등 주요 라면 업체 4개사 임원진이 참석한 비공개 간담회에서 “장바구니 물가가 민생 안정의 시작”이라며 물가 안정 필요성을 거듭 강조했다. 한 업계 관계자는 “직접적으로 가격 인하를 언급하진 않았지만, 지난달 ‘민생물가 특별관리 관계장관 태스크포스(TF)’ 출범 계기에 대한 설명이 이뤄진 것으로 안다”고 전했다.제과업계는 최근 공정거래위원회의 전분당 담합 조사가 계기가 됐다. 전분당은 옥수수를 분쇄해 만든 분말 전분과 이를 통해 생산한 물엿, 포도당, 액상과당 등 당류를 의미한다. 식품용은 과자나 음료수의 재료로 쓰인다. 공정위는 대상, 사조CPK, 삼양사, CJ제일제당 4개사가 2018년 5월부터 지난해 10월까지 전분당 판매가를 담합했다고 보고 있다.서울의 한 대형마트에 진열된 과자. [연합]이번 공정위 보고서에는 2007년 이후 실제 적용 사례가 없었던 ‘가격 재결정’ 명령을 포함한 시정조치까지 담겼다. 업계는 빵값 인하를 부른 밀가루·설탕 가격 인하가 공정위의 담합 조사를 계기로 시작됐던 만큼, 향후 공정위 심의 결과를 주시하고 있다.가격 인하 흐름이 라면·제과업계로 이어질지는 미지수다. 지난달 28일 미국과 이스라엘의 이란 공습으로 시작된 전쟁이 일주일을 넘기며 중동 리스크에 대한 우려가 본격적으로 고개를 들었기 때문이다. 한 라면업계 관계자는 “밀가루의 원가 비중은 10~30% 미만”이라며 “유가와 환율이 오르면 오히려 원가 부담은 커질 수밖에 없다”고 말했다. 제과업계 관계자도 “밀가루 원가 비중은 10% 이내”라며 “생산 공장 가동비와 물류비, 인건비가 원가의 가장 많은 부분을 차지한다”고 토로했다.전쟁이 중동 주변국으로 확산될 조짐을 보이는 점도 불확실성을 키우고 있다. 주요 라면업체들은 앞서 중동 시장 진출을 위해 할랄 전용 생산라인을 구축하고, 할랄 인증을 받으며 투자를 확대해 왔다.주요 업체 중 한 곳이 가격을 내리면 ‘도미노’ 인하로 번질 수 있다는 관측도 나온다. 제빵업계의 경우 지난달 말 파리바게뜨가 가격을 내린 지 2시간 만에 뚜레쥬르가 가격 인하를 발표했다. 이 때문에 정부 기조가 사실상 가격 인하 압박이란 하소연도 나온다. 한 식품업계 관계자는 “일종의 손목 비틀기식 압박으로 느껴지는 게 사실”이라고 했다.', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002610361', 'https://imgnews.pstatic.net/image/016/2026/03/09/0002610361_001_20260309100709306.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 09:46:19', 0, true, '2026-03-09 06:14:20.540676') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (945, '"중동전쟁에 ''공급 불가항력'' 비상"…석유화학 주가 ''와르르''', '호르무즈해협 봉쇄에 투심 악화[호르무즈=AP/뉴시스]2023년 5월 19일(현지 시간) 호르무즈 해협에서 대형 컨테이너선 등이 항행하고 있다. 2026.03.05.[서울=뉴시스] 박주연 기자 = 석유화학 관련주들이 미·이란 전쟁으로 9일 직격탄을 맞고 있다.한국거래소에 따르면 코오롱인더는 이날 오전 9시40분 현재 전 거래일보다 10.49% 하락한 5만6300원을 나타내고 있다.태광산업(8.28%), 금호석유화학(-6.89%), LG화학(-7.20%), SKC(-6.85%), SK케미칼(-6.59%), 롯데케미칼(-6.50%) 등도 줄줄이 하락 중이다.석화업종은 미국과 이스라엘의 이란 공습 소식이 전해진 지난 한 주간(3~6일) 급격한 가격 조정을 겪었다. 이 기간 동안 대한유화(-34.81%), LG화학(-21.81%), 롯데케미칼(-21.38%) 등이 큰 폭의 하락을 나타냈다.미국·이스라엘과 이란간 전쟁으로 국내 석화업계에 연쇄 ''불가항력(포스마주르) 선언''이 나올 수 있다는 관측이 나오며 투자심리가 급격히 악화됐다. 포스마주르는 전쟁이나 자연재해처럼 기업이 통제할 수 없는 사유로 계약상 의무를 이행하기 어려울 때 면책을 위해 하는 선언이다.인도네시아·싱가포르 등의 석유화학 기업 일부가 공급 불가항력 선언을 한 가운데 여천NCC도 지난 4일 일부 고객사에 제품 공급 계약 이행이 지연되거나 조정될 수 있다며 불가항력 선언을 했다. 나프타분해시설(NCC)는 나프타를 고온·고압으로 분해해 에틸렌, 프로필렌 등을 생산하는 석유화학의 핵심이다.국내 업체들은 납사 상당량을 중동 지역에서 조달하고 있어 전쟁이 장기화하면 수급 불안이 더욱 확산될 수 있다는 분석이다.노우호 메리츠증권 연구원은 "공급망 차질이 장기화될 가능성, 석유제품들의 공급차질이 가져올 연쇄효과를 고민할 필요가 있다"며 "중동산 원유 의존도가 높은 국내 정유·화학 기업들의 공급 차질 장기화 변수, 생산설비 가동률 조정 가능성 등을 염두해야 할 시점"이라고 언급했다.전유진 iM증권 연구원은 "단기적으로 원가 부담에 따른 부정적 영향이 불가피하다"며 "다만 중장기적으로는 나프타 부족에 따른 역내 NCC 가동률 하향 조정, 중동산 물량 유입 감소, 유럽 업체들의 추가 구조조정 출현 등으로 수급밸런스 개선 효과를 기대할 수 있다"고 평가했다．', NULL, '뉴시스', 'https://n.news.naver.com/mnews/article/003/0013809377', 'https://imgnews.pstatic.net/image/003/2026/03/09/NISI20260131_0000966163_web_20260131154344_20260309103318776.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 10:16:46', 0, true, '2026-03-09 06:14:26.014433') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (946, '한일시멘트, 새해 임직원 헌혈 캠페인', '한일시멘트는 지난 9일 서울 서초구 본사에서 대한적십자사와 함께 ‘사랑의 헌혈’ 캠페인(사진)을 진행했다고 12일 밝혔다. 본사 앞에 마련된 헌혈버스에 한일홀딩스, 한일시멘트 임직원들이 줄을 이었다. 이날 단양공장에서도 헌혈 행사를 이어갔다. 한일시멘트는 임직원들이 원활하게 참여할 수 있도록 별도의 휴게 시간을 보장했다.', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005236078', 'https://imgnews.pstatic.net/image/015/2026/01/12/0005236078_001_20260113005420236.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-12 17:49:14', 0, true, '2026-03-09 06:14:35.738333') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (947, '“대주주 배불리기”… 한일시멘트, 어닝쇼크에도 이익 70% 배당', '영업이익 2714억→1605억 전망업황 악화에도 배당성향 높여“경영 악화 악순환에 빠질 것” 우려배당락일 外人 10만주 넘게 매도그래픽=정서희한일시멘트의 올해 영업이익이 40% 넘게 줄어들 것으로 전망된다. 순이익 기준으로 지난해 반 토막 수준이 될 것으로 예상됐다. 건설 경기 불황에 따른 매출 감소와 고정비 증가 등에 따른 영향이다. 금융투자 업계에선 “2026년까지 출하량 반등이 힘들 것”이라는 전망까지 나왔다. 일부 제품의 평균 가동률은 20~30%대까지 하락했다. 총 생산 가능한 제품량의 20~30%만 출하하고 있다는 의미다.이런 상황에서 한일시멘트가 연간 이익의 70%를 배당하겠다고 밝히면서 일각에서는 “대주주를 위한 무리한 배당”이라는 비판도 나온다. 불황 장기화에 대비해 유보금을 쌓거나 새로운 먹거리인 신사업 투자에 쓰일 돈을 주주의 주머니 속으로 넣는다는 것이다.유가증권시장에서 배당락일이었던 29일 한일시멘트 주가는 5% 넘게 내렸고, 외국인 투자자는 10만주 이상 매도했다. 배당락일은 배당 권리가 사라지는 날로 보통 배당 기준일 하루 전이다. 배당락일 전날까지 주식을 보유하면 배당금을 받을 수 있지만 배당락일부터는 주식을 보유해도 그해 배당금을 받을 수 없다.영업이익 전망치 1109억원, 전년比 40% 넘게 줄어30일 금융정보업체 에프앤가이드에 따르면 올해 한일시멘트의 영업이익 컨센서스(전망 평균치)는 1605억원으로 집계됐다. 지난해 2714억원의 영업이익을 낸 것을 고려하면 1년 만에 영업이익이 1109억원(40.8%) 급감할 것이라는 분석이다. 같은 기간 순이익도 1990억원에서 1025억원으로 965억원(48.4%) 줄 전망이다.수익성 악화의 주요 원인으로 꼽히는 것은 고정비 상승과 업황 불황에 따른 수요 부진이다. BNK투자증권에 따르면 3분기(9월 말)까지 주요 제품의 출하량은 크게 줄었다. 제품별로는 시멘트가 691만9000루베(㎥)로 지난해 같은 기간보다 10.4% 줄었고, 콘크리트 특화 제품인 레미콘(157만9000루베(㎥)·-20.6%), 시멘트와 모래를 섞은 제품인 레미탈(240만5000루베(㎥)·-27.0%)도 각각 20% 넘게 출하량이 감소했다.출하량 감소로 평균 가동률도 크게 떨어졌다. 평균 가동률은 기업의 총 생산 능력 대비 실제 출하량의 비율이다. 3분기까지 시멘트의 평균 가동률은 58.3%로 전년 동기(65.0%)보다 6.7%포인트 하락했고, 레미콘도 같은 기간 평균 가동률이 28.7%에서 22.8%로 내렸다. 레미탈도 42.8%에서 31.4%로 평균 가동률이 급락했다. 신동현 현대차증권 연구원은 “2025년 하반기 (공동주택 등) 분양 물량이 소폭 증가하면서 착공 면적도 반등이 가능하겠지만 착공 후 레미콘과 시멘트 출하가 이뤄지는 시차를 고려할 때 2026년까지는 유의미한 출하량 반등을 기대하기 어렵다”고 했다.그래픽=정서희배당으로 순이익 70% 지급, 배당락일 주가는 급락시장에선 ‘어닝쇼크’ 수준의 업황 악화 속에서 배당 성향을 크게 높인 것에 대한 우려도 있다.지난 16일 한일시멘트는 2025년 결산 배당으로 보통주 1주당 1000원을 배당한다고 공시했다. 총배당액은 731억원이다. 배당 금액은 지난해와 같다. 그러나 이익이 크게 줄 전망이어서 배당 성향은 급등할 것으로 예상된다. 영업이익 전망치의 45.5%, 순이익 전망치의 71.3%에 해당하는 금액을 배당으로 지급해야 한다. 배당금 중 75.75%(5246만4952주)는 최대주주인 한일홀딩스와 특수관계인에게 돌아간다.서지용 상명대 경영학과 교수는 “대주주와 특수관계인이 배당을 많이 받기 위해 실적이 악화하는데도 배당 성향을 올리면 사내 유보금이 줄고 투자도 못 하게 되면서 다시 이익이 감소하는 악순환이 발생할 수 있다”고 말했다.이익 급감이 예상되는 데 배당 성향을 높이면서 배당액을 전년과 같은 수준으로 유지하면서 주가 변동성도 커졌다. 배당락일이던 지난 29일 한일시멘트의 주가는 전날보다 5.08%(980원) 급락한 1만8300원까지 내렸다. 시가총액도 하루 만에 720억원이 사라졌다. 외국인은 이날 10만400주(18억원)를 매도했다. 증시에서 배당만 받은 후 주식을 매도하는 투자자들의 표적이 된 셈이다.최대 주주가 기업 실적과 관계없이 배당을 받으려는 태도를 개선하기 위해 최대주주에 대한 배당을 줄이는 차등 배당제 도입을 검토해야 한다는 의견도 있다. 이준서 동국대 경영학과 교수는 “최대 주주가 50% 넘게 지분을 보유하고 있으면 소액 주주들보다 배당을 적게 받는 차등 배당제도 등을 적용해 기업의 건전한 경영활동을 보장하면서도 소액 주주에게 기업의 이익이 많이 돌아갈 수 있도록 하는 방법도 검토해야 한다”고 했다.', NULL, '조선비즈', 'https://n.news.naver.com/mnews/article/366/0001133133', 'https://imgnews.pstatic.net/image/366/2025/12/30/0001133133_001_20251230142219600.jpg?type=w800', 'NEWS_ETC', NULL, '2025-12-30 11:31:16', 0, true, '2026-03-09 06:14:35.738333') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (948, '불붙는 혁신, ''붉은 말''의 해… 질주 준비하는 말띠 CEO 누구?', '쿠팡 김범석, 카카오 김범수 등 화제의 인물 포진유통 석화 등 오너 2·3세 다수…농협금융 66년생 3인방 포진김범수 카카오 창업자 2023.11.13/뉴스1 ⓒ News1 안은나 기자(서울=뉴스1) 박주평 배지윤 김동규 신민경 기자 = 2026년 ''붉은 말''의 해 병오년(丙午年)을 맞아 말띠 최고경영자(CEO)들이 주목받고 있다. 병오년은 태양 같은 강력한 불길 속을 거침없이 질주하는 말의 해여서 말띠 CEO들의 활약이 기대된다.30일 업계에 따르면 최근 개인정보 유출 사태로 논란의 중심에 선 쿠팡 김범석Inc. 의장, 김범수 카카오(035720) 창업자 등이 대표적인 말띠 기업인으로 꼽힌다.재계 관심 집중된 78년 말띠 CEO최근 개인정보 유출 사고로 곤욕을 치르고 있는 김범석 쿠팡Inc. 이사회 의장은 1978년생 말띠다. 쿠팡을 국내 최대 이커머스 플랫폼으로 키운 창업주인 그는 이번 사태를 계기로 위기관리와 책임경영 능력이 다시 시험대에 올랐다는 평가를 받는다.박준경 금호석유화학(011780) 총괄사장은 박찬구 금호석유화학그룹 회장의 장남이다. 석유화학 업황이 어렵지만, 금호석화는 합성고무, 합성수지, 에너지 등 다각화된 사업구조와 에틸렌을 직접 생산하지 않는 덕에 선방했다는 평가를 받는다.허희수 비알코리아 사장은 허영인 SPC그룹 회장의 차남이다. 허 사장은 멕시코 음식 프랜차이즈 치폴레의 국내 도입을 비롯해 새로운 성장 동력 확보와 글로벌 경쟁력 제고를 위한 미래 사업 발굴에 나서고 있다.코스맥스(192820) 오너 2세인 이병만 대표는 이날 그룹 인사에서 부회장으로 승진하며 화장품 사업을 계속 이끈다. 패션업계에서는 2019년부터 그룹을 이끄는 박이라 세정그룹 대표가 대표적인 여성 말띠 CEO로 꼽힌다.1966년생 말띠, 김범수 카카오 창업자·''흑백요리사'' 백종원김범수 카카오 창업자는 1966년생 말띠를 대표하는 기업인이다. 한국CXO연구소 ''말띠 주식부자 및 주요 CEO 현황''에 따르면 주식평가액 6조 1017억 원으로 1위에 올랐다. 지난 10월 SM엔터테인먼트 시세조종 공모 의혹에 대한 1심 판결에서 무죄를 선고받았으나 검찰이 항소해 2심이 진행 중이다. 대법 확정판결 이후 경영 일선에 복귀할지가 관심사다.허기호 한일홀딩스(003300) 대표이사 회장은 오너 3세로, 올해 7월 한일시멘트가 한일현대시멘트와 합병 후 내수 점유율 20%를 넘기며 업계 1위로 올라섰다. 건설 경기가 침체한 가운데 성장동력 발굴이라는 과제를 안고 있다.외식업계에서는 백종원 더본코리아(475560) 대표가 1966년생 말띠 CEO다. 올해 품질·위생 등을 둘러싼 각종 논란을 겪었지만, 최근 넷플릭스 흑백요리사 시즌2 심사위원으로 나서며 다시 주목받고 있다.건설업계에서는 김보현 대우건설(047040) 대표이사 사장이 손꼽힌다. 공군 준장 출신인 김 대표는 정창선 중흥그룹 회장의 사위로, 2021년 대우건설 인수단장을 맡아 중흥그룹의 대우건설 인수 과정을 총괄했다.54년생 박순재 알테오젠 회장, 90년생 이선호 CJ그룹 미래기획실장1954년생인 박순재 알테오젠(196170) 회장은 최근 대표이사에서 물러나 전문경영인 체제를 가동하고, 사내이사 및 이사회 의장직을 유지하며 전략 수립에 집중하기로 했다. 주식평가액 4조 4804억 원으로 말띠 기업인 중 2위에 올랐다. 마찬가지로 1954년생인 이용한 원익그룹 회장(6657억원)은 공정거래위원회가 지정한 말띠 기업총수 중에서는 주식평가액 1위다.1990년생은 CEO보다는 경영 승계를 준비하는 오너가 3·4세가 포진해 있다. 이선호 CJ그룹 미래기획실장이 주목할 만한 인물이다. 그는 그룹의 중장기 전략을 담당하며 차세대 오너 경영인으로 거론된다.금융계 농협금융 66년생 3인방·김이태 삼성카드 대표금융계에서는 농협금융의 66년생 3인방이 회사를 이끌고 있다. 오랜 기간 경제관료로 재직하며 ''경제정책통''으로 불리는 이찬우 농협금융지주 회장은 농협금융 계열사의 생산적 금융 정책을 이끌 것으로 보인다.앞서 농협금융은 2030년까지 추진되는 ''NH 상생성장 프로젝트''를 발표한 바 있다. 프로젝트 컨트롤 타워를 맡은 이 회장은 직속 생산적금융특별위원회(특별위)를 꾸려 프로젝트를 추진 중이다.강태영 NH농협은행장은 농협은행 디지털 혁신을 이끌 것으로 기대된다. 지주회장과 함께 뱅킹 앱을 그룹 슈퍼플랫폼으로 전환하는 데 앞장선 디지털 전문가라는 평가를 받고 있다.현장과 중앙회 조직을 경험한 ''농협맨'' 박병희 NH농협생명 대표는 부사장 시절부터 이어온 체질 개선 작업을 본격화하며 건전성 강화에 속도를 내고 있다.카드 업계에서도 66년생 김이태 삼성카드(029780) 대표의 활약이 기대된다. 삼성금융 통합 앱 ''모니모'' 운영을 맡고 있는 삼성카드는 지속해서 혁신을 추진 중이다.김 대표는 지난 2002년 기재부 국제금융국 서기관을 시작으로 대통령비서실 서기관과 기재부 국제금융과장을 지낸 관료 출신이다. 지난 2016년 삼성전자 합류 후 글로벌커뮤니케이션그룹장 및 대외협력팀장 등을 역임했으며, 지난해 말까지 삼성벤처투자 대표이사를 맡아 벤처 생태계에 성공 DNA를 이식했다는 평가를 받고 있다.', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008685487', 'https://imgnews.pstatic.net/image/421/2025/12/30/0008685487_001_20251230092421793.jpg?type=w800', 'NEWS_ETC', NULL, '2025-12-30 06:00:00', 0, true, '2026-03-09 06:14:35.738333') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (949, '"한한령 해제될까"…엔터·뷰티·게임주 변동성 확대', '5일 오후 베이징서 한중정상회담[서울=뉴시스] 최동준 기자 = 대통령실은 이재명 대통령과 시진핑 중국 국가주석이 1일 경북 경주박물관에서 공식 환영식을 마친 뒤 정상회담을 하기 위해 도보로 이동하는 모습을 2일 SNS에 공개했다. (사진=이재명 대통령 SNS) 2025.11.02. photo@newsis.com *재판매 및 DB 금지[서울=뉴시스] 박주연 기자 = 이재명 대통령이 5일 오후 중국 베이징에서 시진핑 국가주석과 정상회담을 갖는 가운데 국내 증시에서는 ''한한령 해제''에 대한 기대감과 경계심이 교차하고 있다.5일 한국거래소에 따르면 네이버·카카오·하이브·크래프톤·엔씨소프트·SM Ent. 등 20개 종목으로 이뤄진 KRX K콘텐츠지수는 지난해 12월 29일 1980.68에서 지난 2일 2098.31로 최근 한 주간 117.63포인트(5.94%) 상승했다. 다만 5일 오전장에서는 차익 실현 매물이 출회되며 0.8%대 하락세를 나타내고 있다.특히 이날 오전 10시 22분 현재 에스엠(-9.52%), 스튜디오드래곤(-8.70%), 와이지엔터테인먼트(-7.10%), JYP Ent.(-6.19%) 등이 줄줄이 하락세를 보이고 있다.한국화장품(-7.54%), 코스맥스(-3.20%), 에이블씨엔씨(-2.83%) 등 화장품 관련주와 형지글로벌(0.41%), 형지 I&C(-4.89%) 등 패션 관련주도 내리고 있다.게임 관련주인 펄어비스(-2.51%), 크래프톤(-1.61%) 역시 하락세다. 반면 NHN(3.24%), 엔씨소프트(0.69%) 등은 상승세다.지난 한 주간 국내 증시에서는 한중정상회담으로 한중관계가 정상화될 것이라는 기대감이 번지며 화장품, 패션, 게임, 엔터테인먼트 관련주들이 줄줄이 상승했다.한 주간 한국화장품(27.75%), 토니모리(14.95%), 코스맥스(9.67%), 달바글로벌(9.04%), 아모레퍼시픽홀딩스(7.41%), 한국콜마(7.04%), 아모레퍼시픽(6.73%), 한국화장품제조(5.28%) 등 화장품 관련주가 크게 올랐다. 형지글로벌(45.78%), 형지I&C(36.16%), 코데즈컴바인(17.93%) 등 패션주도 상승세를 나타냈다.스튜디오드래곤(11.36%), 하이브(10.2%), 키다리스튜디오(9.38%), 와이지엔터테인먼트(9.15%), JYP Ent.(9.00%), 에스엠(6.43%) 등 엔터테인먼트 관련주들과 NHN(8.44%), 엔씨소프트(5.89%) 등 게임 관련주들도 오름세를 보였다.김두언 하나증권 연구원은 "한중 정상회담으로 양국 간의 전면적 복원 기대가 높다"며 "주식시장에서는 한한령 해제에 따른 엔터, 게임, 콘텐츠, 관광, 화장품 업종 등에 기대가 크다"고 설명했다.지인해 신한투자증권 연구원은 "내수경기회복이 필요한 중국의 의지를 감안했을 때 K-콘텐츠를 활용할 가능성이 높다"며 "한중교류관계 물꼬가 실질적으로 트일 가능성이 높아진 상황이고, 중국이 전면 개방된다면 주목해야 할 종목은 에스엠, 디어유, 와이지엔터테인먼트, 스튜디오드래곤 등"이라고 분석했다.또 "정부 정책, K-컬쳐 확산, 원화 약세, 중일 갈등 등의 반사이익이 복합적으로 맞물리며 인바운드 관광 목표인 올해 2000만명, 2030년 3000만명을 조기 달성할 수 있을 전망"이라고 내다봤다.한편 이재명 대통령은 이날 오후 공식 환영식을 시작으로 정상회담, 양해각서(MOU) 서명식, 국빈 만찬 일정을 차례로 소화한다.이번 회담의 핵심 의제는 ''한중 관계의 실질적 복원''과 ''경제 협력''이다. 양 정상은 공급망 안정과 문화 콘텐츠 교류 등 민생 직결 분야에서 상생 모델을 모색할 것으로 예상된다. 이 대통령은 한반도 평화 프로세스에 대한 중국 측의 지지도 당부할 것으로 보인다. ''한한령''(한류 제한 조치) 해제 등 양국 간 민감한 현안도 테이블에 오를 전망이다.이번 방중에는 대규모 경제사절단도 동행했다. 삼성·SK·현대차·LG·롯데 5대 그룹 총수 외에도 CJ, 크래프톤, SM엔터테인먼트, 패션그룹 형지 등이 이름을 올렸다.', NULL, '뉴시스', 'https://n.news.naver.com/mnews/article/003/0013692269', 'https://imgnews.pstatic.net/image/003/2026/01/05/NISI20251102_0021041532_web_20251102174755_20260105103722539.jpg?type=w800', 'NEWS_CHEM', NULL, '2026-01-05 10:36:47', 0, true, '2026-03-09 06:14:44.831608') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (950, '서경배에서 김병훈으로…뷰티 산업 ‘제조’의 시대가 가고 ‘콘셉트’의 시대가 왔다[2026 뉴리더④]', '[커버스토리-2026 뉴 리더]에이피알의 김병훈 대표, 구다이글로벌의 천주혁 대표서경배. 한국 뷰티 산업에서 이 이름만큼 견고한 성벽은 없었다. 서 회장이 이끄는 아모레퍼시픽을 필두로 LG생활건강, 애경산업 등은 브랜드 파워와 견고한 오프라인 유통망, 그리고 내수 시장의 압도적 점유율을 무기로 수십 년간 시장을 장악해 왔다. 우리가 아는 ‘K뷰티’라는 고유명사 역시 대기업 중심 산업에서 일궈낸 빛나는 성과였다.하지만 2025년 8월 대한민국 산업사에 기록될 상징적인 장면이 연출됐다. 에이피알(APR)이 국내 뷰티 업계 시가총액 1위에 오르며 수십 년간 K뷰티의 상징으로 군림해 온 아모레퍼시픽을 왕좌에서 밀어낸 것이다. 김병훈 에이피알 대표의 개인 주식 가치는 2024년 말과 올해 12월 19일 1년 새 386% 폭증하며 2조9000억원을 돌파, 서 회장(2조58억원)의 자산 규모를 넘어섰다.이는 단순히 주식시장의 숫자가 바뀐 사건이 아니다. 화장품 산업의 중심축이 ‘제조와 자본’에서 ‘콘셉트와 플랫폼’으로 완전히 이동했음을 알리는 거대한 패러다임의 전환이다. 변화의 최전선에는 에이피알의 김병훈, 구다이글로벌의 천주혁, 더파운더즈의 이선형·이창주가 서 있다. 이들은 기존 화장품 가문의 후계자도, 정통 뷰티 대기업 출신의 엘리트도 아니다. 취업 대신 창업을, 연구소 대신 숫자(경영)를, 내수 대신 글로벌 온라인 영토를 택한 1980년대생 리더들이다.1980년대생‘닫힌 문’ 대신‘판’을 짠 세대현재 K뷰티를 재편하는 뉴 리더들의 가장 선명한 공통점은 1980년대생이라는 점이다. 김병훈 에이피알 대표(1988년생), 천주혁 구다이글로벌 대표(1987년생), 이선형·이창주 더파운더즈 공동대표(1988년생)는 모두 30대 후반의 경영자들이다.이들이 사회에 발을 내디딜 무렵 대한민국은 이미 ‘고성장의 종말’을 목격하고 있었다. 대기업 공채 문은 좁아졌고 평생직장의 신화는 무너진 지 오래였다. 대기업에 들어가 시간을 쌓아도 상위 1%가 되기 어렵다는 사실을 몸소 체감한 세대. 안정적인 커리어보다 단숨에 판을 뒤집는 ‘텐배거(10배 수익)’가 조직 안이 아니라 밖에서 나온다는 사실을 본능적으로 깨달은 세대였다.김병훈 대표의 삶은 이러한 세대적 갈증을 고스란히 투영한다. 그는 어린 시절 아버지가 대기업의 사내 정치에 휘말려 실직하는 모습을 지켜보며 “내 능력이 우선되는 조직을 만들겠다”는 결심과 함께 사업가의 길을 꿈꿨다. 창업을 목표로 연세대 경영학과에 진학했고 2011년 미국 교환학생 시절 글로벌 시장의 가능성을 목격하며 사업 구상을 구체화했다.“저는 진짜 어린 시절부터 창업을 꿈꿨습니다. 정주영 회장님 같은 1세대 창업가들을 동경했고 한강의 기적을 일궈낸 부모님 세대의 근면함을 존경했습니다. 스무 살, 창업을 하고 싶어 경영대에 입학했고 졸업하지 않은 상태에서 첫 창업팀을 꾸렸습니다.” 김 대표의 말처럼 이들은 기성세대가 닦아놓은 길을 걷는 대신 스스로 새로운 영토를 설계하는 데 주저함이 없었다.특히 이들은 기존 산업의 주류였던 화학과·화공과 출신이 아니다. 김병훈 대표(연세대 경영), 이선형·이창주 더파운더즈 공동대표(서울대 경제) 등 주역들의 면면을 보면 상경계열이 압도적이다. 이들은 화장품을 만들어야 하는 ‘화학적 물질’이 아니라 시장의 니즈를 ‘설계하고 유통하는 구조’로 바라봤다. 화장품 제조는 이미 한국화장품제조, 한국콜마와 코스맥스라는 세계적 수준의 OEM, ODM 인프라가 완성되어 있었다.ODM이란 한국 특유의 화장품 제조 환경은 진입장벽을 낮췄고 제조 경쟁력을 빠르게 평준화시켰다. 공장이 더 이상 차별화의 출발점이 되지 않으면서 경쟁의 무게중심은 자연스럽게 기획과 아이디어, 그리고 이를 시장에 전달하는 방식으로 이동했다. 중소 인디 브랜드들이 가진 날카로운 콘셉트와 빠른 실행력은 기존 질서의 틈을 파고들기 시작했다. 진짜 승부처는 누구에게 무엇을 어떻게 보여줄 것인가라는 ‘콘셉트’에 있었다.더파운더즈의 출발도 이를 보여준다. 대학 동기인 두 리더는 경영자적 기획력을 앞세워 창업에 나섰다. 모바일 환경이 보편화되면서 큰 자본이 없어도 소비자들에게 쉽게 제품을 알리고 판매할 수 있는 환경이 갖춰졌다는 판단이었다. 이선형 대표는 당시 인터뷰에서 “나는 경제학을, 공동창업자는 인류학을 전공했다”며 “개발 역량보다는 기획을 날카롭게 다듬을 때 고객 가치를 더 크게 창출할 수 있을 것이라 확신했다”고 말했다.제조의 피크에서 피어난 ‘콘셉트 산업’의 혁명하지만 이들의 창업기가 처음부터 탄탄대로였던 것은 아니다. 2010년대 중반 중국이 ‘세계의 소비시장’으로 변신하면서 아모레퍼시픽은 ‘황제주’에 등극했고 대기업들은 중국 특수라는 거대 자본의 파티를 독식했다.에이피알이 설립된 2014년, 구다이글로벌이 탄생한 2016년, 더파운더즈가 등장한 2017년은 화장품 브랜드가 기하급수적으로 증가하며 중소 브랜드 간의 생존 경쟁이 극에 달했던 시기였다. 구다이글로벌의 천주혁 대표는 한 언론 인터뷰에서 “2016년을 기점으로 중국 시장 경쟁이 과열되고 거대 자본이 유입되면서 나 같은 창업자가 기회를 잡기 어려운 환경이 됐다”고 당시를 회상했다.대기업의 자본력과 중국이라는 거대 시장의 틈바구니에서 살아남기 위해 이들은 기존의 문법을 완전히 버려야 했다. 더욱이 화장품 산업은 고도화된 ODM 인프라로 ‘제조업’에서 ‘콘셉트 산업’으로 넘어가는 변곡점이었다. 이들은 대기업과 대등하게 싸울 수 있는 ‘디지털 게릴라전’에 뛰어들었다.김병훈 대표는 이 지점을 가장 영리하게 파고들었다. 그는 정반대의 프로세스를 도입했다. 전통적 기업들이 연구개발 후 유통망을 확보했다면 김 대표는 SNS와 자사 몰(D2C)을 먼저 구축해 고객 데이터를 확보한 뒤 그들이 반응하는 콘셉트에 맞춰 제품을 소싱했다. 고객 리뷰에 민감하게 대응하느라 24시간이 모자랐다는 그의 집요함은 화장품을 파는 것에서 그치지 않고 ‘트래픽을 구매로 치환하는 행위’로 변모시켰다.그의 예상은 적중했다. 온라인 마케팅에는 국경이 없었다. 전 세계 뷰티 트렌드가 SNS를 통해 실시간으로 동기화된다는 점을 포착한 에이피알은 현재 매출의 80%가 해외에서 나온다. 미국 단일 국가에서만 분기 매출 1500억원을 돌파하며 ‘K뷰티의 영토’를 물리적 거리 밖으로 확장했다. 박종대 하나증권 애널리스트는 에이피알의 놀라운 실적 개선과 사업 확장에 대해 “우수한 제품력과 압도적인 마케팅 역량, 유연한 유통전략의 3박자가 맞아떨어진 결과”라며 “전사 인력의 절반을 마케팅 인력으로 채우면서 지역별, 품목별, 채널별로 최적화된 마케팅 콘텐츠를 쏟아낸 것이 핵심”이라고 분석했다. 이를 통해 확보한 높은 페이지뷰(PV)와 트래픽이 실제 구매로 전환되는 강력한 수익모델을 구축했다고 평가했다.코로나19와 한류라는 거대한 가속페달이들의 성공을 완성한 것은 시대가 던져준 결정적 환경이었다. 2020년 코로나19는 전 세계 소비 환경을 강제로 온라인에 밀어 넣었다. 사람들이 집에 머물며 넷플릭스를 통해 한국의 콘텐츠를 소비할 때 이미 디지털 유통망을 갖춘 이들은 ‘한류의 수혜’를 온몸으로 받아냈다. 한국 콘텐츠를 소비하는 글로벌 세대에게 한국인의 깨끗한 피부는 선망의 대상이 됐고 이들은 그 수요를 곧바로 글로벌 온라인 플랫폼(아마존, 울타뷰티 등)으로 연결했다.(파리=뉴스1) 이준성 기자 = 26일(한국시간) ''프랑스 K-박람회''가 열리고 있는 프랑스 파리 브롱냐르 궁 뷰티 브랜드존에서 방문객들이 티르티르, 조선미녀, 아이소이 등 K-뷰티 상품들을 살펴보고 있다.천주혁 대표가 이끈 ‘조선미녀’의 폭발적인 성장은 이러한 흐름을 가장 정확히 올라탄 사례다. 천 대표는 2018년 LA 케이콘(KCON) 행사 현장에서 수많은 인디 브랜드 중 조선미녀가 독보적으로 높은 매출을 기록하는 장면을 목격했다. 서구권 소비자들이 한국 특유의 ‘조선’이라는 콘셉트에 반응한다는 사실을 현장에서 데이터로 확인한 것이다. 이듬해 조선미녀를 인수한 천 대표는 탁월한 유통 감각과 마케팅 능력을 쏟아부었다. 한국콜마의 검증된 제조력 위에 서구권 맞춤형으로 벼려낸 ‘조선’의 서사를 입힌 전략은 적중했다.이들은 기존의 유통 문법도 파괴했다. 에이피알은 화장품에 머물지 않고 ‘뷰티 디바이스’로 영역을 확장했다. 100만원대에 달하던 고가 장비의 거품을 걷어내고 10만원대로 대중화하며 ‘뷰티테크’라는 신시장을 개척했다.천 대표 또한 글로벌 뷰티 공룡 로레알을 롤모델로 삼아 공격적인 M&A(인수합병)를 전개한다. 조선미녀에 이어 티르티르, 스킨1004 등 잘나가는 인디 브랜드들을 흡수하며 ‘K뷰티 연합군’을 구축했다. 지난해 3000억원대였던 매출이 올해 1조원 돌파를 눈앞에 둔 비결이다. “한국 화장품 업계에서도 시총 100조원 기업이 나올 것”이라는 그의 포부는 허황된 외침이 아닌, 변화된 산업 구조에 대한 확신에서 나온다.제조업의 황금기를 지나 콘셉트와 플랫폼의 시대를 연 80년대생 리더들. 이들이 쏘아 올린 것은 브랜드의 성공만이 아니라 저성장 시대 대한민국이 세계 시장에 던지는 새로운 생존의 공식이다. 서경배의 시대가 쌓아 올린 견고한 토양 위에서 이제 K뷰티의 뉴 리더들이 설계한 디지털 고속도로가 전 세계 뷰티 시장의 판도를 바꾸고 있다.', NULL, '한경비즈니스', 'https://n.news.naver.com/mnews/article/050/0000100533', 'https://imgnews.pstatic.net/image/050/2026/01/05/0000100533_001_20260105062414862.jpg?type=w800', 'NEWS_CHEM', NULL, '2026-01-05 06:24:14', 0, true, '2026-03-09 06:14:44.831608') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (951, '한중 정상회담에…엔터·게임·뷰티株 전방위 매수세', '[서울=뉴시스] 최동준 기자 = 대통령실은 이재명 대통령이 지난 11월 1일 경북 경주 소노캄 그랜드 볼룸에서 시진핑 중국 국가주석 국빈 만찬을 마친 뒤 시 주석을 환송하는 모습을 2일 SNS에 공개했다. (사진=이재명 대통령 SNS) 2025.11.02. photo@newsis.com *재판매 및 DB 금지[서울=뉴시스] 박주연 기자 = 한중 관계 복원에 대한 기대감이 커지며 국내 증시에서 엔터테인먼트·게임·뷰티 업종 전반으로 매수세가 확산되고 있다.이재명 대통령은 오는 4일부터 3박4일 일정으로 중국을 국빈 방문한다.오는 5일 오후에는 중국 베이징에서 시진핑 중국 국가주석과 한중 정상회담을 갖고 한중 관계 전면 복원과 민생 및 한반도 평화 협력 강화 방안을 논의한다. ''한한령(한류 제한 조치)'' 등 민감한 현안에 대해서도 문제 해결을 모색할 예정이다.양국 정상은 한중 관계를 전면 복원키로 한 경주에서의 대화를 바탕으로 한중 양국이 직면한 민생과 평화의 문제를 해결하기 위한 실질적인 방안에 대한 심도 있는 논의를 가질 것으로 전해졌다. 대통령의 중국 국빈 방문은 문재인 정부 때인 2017년 이후 9년 만이다.정상회담에 대한 기대감이 번지며 지난 2일 국내 증시에서는 엔터·게임·화장품 등 수혜를 입을 것으로 기대되는 업종들이 일제히 상승했다.엔터 업종에서는 삼화네트웍스(11.85%), 스튜디오드래곤(8.89%), 초록뱀미디어(8.31%), 키이스트(8.09%), JYP Ent.(6.75%), 하이브(4.85%), 큐브엔터(3.71%), SM C&C(3.38%), CJ ENM(3.25%), 판타지오(2.70%) 등이 상승세를 보였다.게임 업종에서는 넥써쓰(13.76%), 엔씨소프트(7.44%), 위메이드(7.41%), 펄어비스(6.42%)NHN(6.20%), 이스트소프트(6.10%) 등이, 화장품 업종에서는 한국화장품(21.51%), 제닉(11.99%), 코스맥스(9.20%), HLB펩(8.80%), 아모레퍼시픽홀딩스(8.01%), 코리아나(7.79%), 클래시스(7.52%), 아모레퍼시픽(6.19%), 한국화장품제조(5.56%) 등이 상승세를 나타냈다. 미용기기 업체인 레이저옵텍(18.18%), 아스테라시스(13.66%) 등도 강한 오름세를 보였다.증권가는 최근 중국의 내수 경기 부양 필요성과 외교적 기조 변화를 감안할 때, 한중 정상회담을 계기로 엔터 산업 등에서 의미있는 변화가 나타날 가능성이 높다고 보고 있다.특히 최근 ''한일령''과 중국 내 콘텐츠 소비 회복과 맞물려 한국 음악·드라마·게임·뷰티 등에 대한 수요가 다시 확대될 수 있다는 분석이다.신한투자증권 주식전략팀은 "다카이치 사나에 일본 총리의 ''대만 유사시 개입'' 발언 후 중·일 관계가 급속히 악화하고 있다"며 "일본 여행·유학 자제령, 일본 콘텐츠 제재, 공연 중단, 항공편 대규모 취소 등은 과거 사드 사태를 상기시키는 장기 제재 가능성을 시사한다"고 분석했다.이어 "반대급부로 한·중 관계는 문화·인적 교류 중심으로 완화 국면에 진입했다"며 "무비자 정책 확대, K-팝 콘서트 방영 허용, 외교 재개 등이 동시 진행되고 있고, 서비스 소비 확대 국면에서 한국이 ''중일 갈등의 반사 수혜''를 입을 것으로 기대된다"고 분석했다.이경민 대신증권 연구원은 "2일 국내 증시에서 한한령 해제 수혜 업종이 강세를 나타냈다"며 "한중 관계 개선의 수혜를 받을 수 있는 화장품, 엔터 등의 상승세가 가팔랐다"고 설명했다.지인해 신한투자증권 연구위원은 "중국의 한일령 입장 강화와 이재명 대통령의 방중, 내수경기부양이 필요한 중국의 의지를 감안할 때 긍정적이고 의미있는 한중 문화 교류의 물꼬가 트일 개연성이 높아졌다"고 분석했다.지 연구위원은 "엔터 업종 중 특별한 관심이 요구되는 종목은 전통적으로 중국 포지셔닝이 강한 에스엠, QQ뮤직 내 버블 사업을 개시한 디어유, 한한령 이전 중국에서 인지도가 가장 높았던 빅뱅을 보유한 와이지엔터, 이익 레버리지 효과가 가장 강하게 적용될 스튜디오드래곤 등"이라고 분석했다．', NULL, '뉴시스', 'https://n.news.naver.com/mnews/article/003/0013690103', 'https://imgnews.pstatic.net/image/003/2026/01/03/NISI20251102_0021041531_web_20251102174755_20260103081511484.jpg?type=w800', 'NEWS_CHEM', NULL, '2026-01-03 08:00:00', 0, true, '2026-03-09 06:14:44.831608') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (954, '유안타證 “신세계, 관광객 명품 매출 확대로 매출 성장 기대 …목표가↑”', '유안타증권은 외국인 관광객의 명품 매출이 증가해 신세계의 향후 성장세가 이어질 것으로 9일 전망했다. 투자 의견 ‘매수(Buy)’를 유지하고, 목표 주가를 기존 32만원에서 42만5000원으로 상향 제시했다. 전 거래일 신세계의 종가는 33만4000원이다.. /신세계 제공지난해 4분기 신세계의 매출액은 1조9337억원, 영업이익은 1725억원으로, 영업이익은 시장 기대치에 부합했다.매출 성장은 명품과 외국인 매출이 이끌었다. 이승은 유안타증권 연구원은 “백화점의 고객 수가 12% 증가하면서 전체 성장을 주도했는데 명품 비중이 높은 대형 점포 위주로 강세를 보였다”며 “루이비통 신규 오픈 효과가 있었던 대전점이 27%, 본점 26%, 강남점 17% 순으로 증가했다”고 분석했다.외국인 매출은 전년 동기 대비 약 70% 증가했다. 이 연구원은 “외국인 매출은 전년 동기 대비 70% 성장하며 지난해 4분기 매출 비중이 5.7%로 확대됐다”며 “월별로 전년 동기 대비 10월 44%, 11월 60%, 12월 79% 증가하면서 한일령 효과가 본격화돼 신장률이 가속화됐다”고 했다.신세계는 명품과 관련해 인바운드(외국인 관광객) 최대 수혜주로 꼽힌다. 백화점 3사 중 명품 매출 비중이 40%로 가장 높은 데다, 외국인 관광객 매출 중 명품이 차지하는 비중도 가장 크기 때문이다.이 연구원은 “최근 백화점 업계에서 외국인 매출이 꾸준히 늘어나는 가운데, 한일령 발효 이후 중국인 고객 매출까지 추가되고 있다”며 “신세계의 수혜가 가장 클 것으로 예상된다”고 했다.', NULL, '조선비즈', 'https://n.news.naver.com/mnews/article/366/0001146805', 'https://imgnews.pstatic.net/image/366/2026/03/09/0001146805_001_20260309092908674.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 09:29:08', 0, true, '2026-03-09 06:15:02.946574') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (955, '실적불안에 유가까지…전기·가스株 ''울상''', '美·이란 충돌에 국제유가 급등전기·가스업종 나흘새 20% ↓한국전력 주가 16%넘게 하락LNG 공급망 마비 우려 커지자가스공사 미수금 회수 ''빨간불''미국·이스라엘과 이란 간 전쟁이 발발한 충격으로 국내 증시가 한 주간 급등락을 보인 가운데 전기·가스업종이 가장 큰 타격을 받은 것으로 나타났다. 국제유가와 천연가스 가격 급등으로 에너지 수입 의존도가 높은 전기·가스업종 수익성이 악화될 것이라는 우려가 커진 영향이다.6일 한국거래소에 따르면 코스피 전기·가스지수는 지난 3일부터 나흘간 20.71% 하락했다. 코스피 전체 지수 중 최대 낙폭이다. 이날 업종 대장주인 한국전력은 나흘 새 16.58% 내린 4만8800원에 장을 마감했다. 같은 기간 한국가스공사(-10.44%) 지역난방공사(-6.44%) 삼천리(-9.57%) 한진중공업홀딩스(-7.58%) 등도 하락세가 두드러졌다.이 같은 급락은 전쟁 여파로 국제 에너지 가격이 가파르게 상승할 것이라는 염려 때문이다. 실제 이란의 유조선 공격 소식이 이어지면서 5일(현지시간) 서부텍사스산원유(WTI)는 전일 대비 8.51% 급등한 배럴당 81.01달러로 장을 마감했다. 이는 2024년 7월 이후 1년8개월 만에 최고 수준이다. 유럽과 아시아 시장을 중심으로 천연가스 가격도 폭등했다. 이란의 드론 공격으로 카타르 국영기업 카타르에너지(QE)의 라스라판 액화천연가스(LNG) 시설이 가동을 중단하면서다.한국전력은 작년 4분기 ''어닝 쇼크''를 기록한 가운데 전쟁이라는 악재까지 만나 주가 하락세가 두드러졌다. 한국전력은 작년 4분기 영업이익이 1조9834억원으로 전년 동기 대비 18% 감소하며 시장 전망치를 크게 하회했다. 경기 부진과 요금 인상 영향으로 산업용 전력 판매량이 부진하게 나타난 데다 온실가스 배출권·원전 사후 처리 충당부채 비용 등이 증가한 탓이다. 산업용 요금 단가가 이미 높게 형성된 탓에 추가 요금 인상을 기대하기 힘든 점도 주가에 부담으로 작용하고 있다. 류제현 미래에셋증권 연구원은 "한국전력은 올해 경기 반등과 조업일수 증가 영향으로 전력 판매량 감소세가 완화될 것으로 기대된다"며 "다만 요금제 개편과 유가의 방향성이 장기적으로 한국전력 실적을 좌우할 것으로 보이는 만큼 당분간 관망할 필요가 있다"고 분석했다.한국가스공사도 실적 부진이 지속되고 있다. 한국가스공사의 작년 4분기 영업이익은 4736억원으로 전년 동기 대비 59.7% 급감하며 역시 시장 전망치를 크게 밑돌았다. 판매 물량이 예상보다 적었던 데다 지난해 저유가가 이어지며 모잠비크·호주 광구에서 장부상 자산가치 하락에 따른 손상차손이 대거 발생한 탓이다.이런 가운데 이란발 위기로 유가와 LNG 가격이 가파르게 오르며 이번에는 국내 가스 도입 단가 상승에 따른 미수금 비용 압박이 다시금 커졌다는 분석이다. 김일혁 KB증권 연구원은 "OPEC+의 생산 확대나 미국의 전략비축유 방출, 사우디의 파이프라인을 통한 수출 등 우회 경로가 있는 원유와 달리 LNG는 대체할 방법이 없고 카타르 LNG 수출 물량은 전량이 호르무즈 해협을 통과한다"며 "분쟁 장기화 시 아시아와 유럽이 가장 큰 충격을 입을 것"이라고 경고했다. 지역난방공사는 지난해 미수금 회수를 위한 열요금 정산 효과와 특정 발전소의 필수 가동 지정 등으로 영업이익이 정점을 찍었으나 올해 하반기부터는 이러한 효과가 사라지며 영업이익이 감소할 것으로 관측된다.[문가영 기자]', NULL, '매일경제', 'https://n.news.naver.com/mnews/article/009/0005646392', 'https://imgnews.pstatic.net/image/009/2026/03/06/0005646392_001_20260306173811123.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-06 17:38:11', 0, true, '2026-03-09 06:15:07.358051') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (956, '한진중공업홀딩스, 지난해 영업익 733억…전년비 59.7% ↑', '[헤럴드경제=증권부] 한진중공업홀딩스는 지난해 연결기준 영업이익이 732억5392만원으로 전년대비 59.7% 증가했다고 26일 공시했다.같은 기간 매출액은 1조2017억3042만원으로 3.2% 늘어난 것으로 나타났다.당기순이익은 625억6213만원으로 2.8% 증가한 것으로 집계됐다.', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002605806', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2026-02-26 16:45:10', 0, true, '2026-03-09 06:15:07.358051') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (957, '한진중공업홀딩스, 자회사 한일레저 주당 875원 결산 배당 결정', '한진중공업홀딩스는 자회사인 한일레저가 주주가치 제고를 위해 보통주 1주당 875원의 현금 배당을 결정했다고 24일 공시했다. 한일레저는 한진중공업홀딩스 자산 총액의 13.2%를 차지하는 주요 자회사다.배당금 총액은 38억원이다. 이번 배당금 총액은 발행주식 총수 439만9840주를 기준으로 산정했다. 배당기준일은 2025년 12월 31일이다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000079822', 'https://imgnews.pstatic.net/image/293/2026/02/24/0000079822_001_20260224150906150.png?type=w800', 'NEWS_ETC', NULL, '2026-02-24 15:09:06', 0, true, '2026-03-09 06:15:07.358051') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (958, '''유가 급등'' 항공권 美 45만원·日 7만원↑…항공사 실적 ''빨간불''', '항공유 1주일 만에 최고 170% 급등…내달 유류할증료 인상 확실시이달 발권해야 유리…적자 빠진 항공업계, 올해도 난항 예상중동 상황 악화와 환율 급등으로 항공, 여행업계에 초비상이 걸린 가운데 지난 5일 인천국제공항 활주로에 대한항공 여객기가 계류돼 있는 모습. 2026.3.5 ⓒ 뉴스1 오대일 기자(서울=뉴스1) 김성식 기자 = 미국·이란 전쟁 영향으로 국제 유가가 급등하면서 내달 국제 항공권 가격이 큰 폭으로 오를 전망이다. 왕복 기준으로 장거리 노선인 인천~뉴욕의 경우 이달 대비 45만 원, 단거리 노선인 김포~도쿄는 7만 원 이상 상승할 것으로 예상된다. 고환율과 좌석 공급과잉에 시달리던 항공사들이 이달 들어 고유가까지 ''3중고''에 직면하면서 올해 실적에도 빨간불이 들어왔다.싱가포르 항공유 사상 최고가 기록…재고량 적어 타유종보다 오름폭 커9일 로이터·블룸버그 통신에 따르면 지난달 중순 배럴당 80달러 선에서 거래되던 싱가포르 항공유 현물 가격은 지난달 28일 시작된 미국의 대(對)이란 군사작전 이후 지난 4일 170%가량 급등한 배럴당 221달러로 사상 최고치 기록했다. 지난 6일에는 159달러로 거래를 마치며 하향 조정됐으나 여전히 전쟁 이전 대비 90% 이상 높은 수준이다.싱가포르 항공유는 다른 국제 유가 대비 상승 폭이 더욱 가파른 편이다. 지난 6일 두바이유 선물 가격은 99달러로 전쟁 이전 대비 45% 오르는 데 그쳤다. 같은 기간 서부텍사스산원유, 브렌트유 선물 가격도 각각 34%, 27% 상승한 수준이었다. 항공유는 특수 탱크에 저장해야 해 다른 유종 대비 재고량이 적어 공급 상황에 따른 가격 등락이 큰 편이다.현재 이란은 사우디아라비아, 아랍에미리트(UAE) 등 미군 기지가 소재한 인근 걸프국에 보복 공격을 감행하며 중동산 원유 해상 운송로인 호르무즈 해협까지 봉쇄, 원유 생산과 운송 전반에 악영향을 주고 있다. 이러한 중동산 원유 공급 차질은 항공유 가격 상승을 더욱 부채질한다. 호르무즈 해협에 가로막힌 중동산 원유의 상당 부분이 항공유와 디젤을 생산하는 데 쓰이는 ''중질·산성 원유''(medium-sour crude)이기 때문이다.미국과 이스라엘이 이란에 대한 공습에 들어간 가운데 지난 5일(현지시간) 사우디아라비아 리야드에서 연기 기둥이 솟구치고 있다. 2026.03.05. ⓒ 로이터=뉴스1내달 유류 할증료 러우전 직후 수준 인상…"항공권 이달 발권해야 저렴"항공유가 급등함에 따라 국내 항공사들의 내달 항공권 가격도 큰 폭의 인상이 확실시된다. 운임, 공항 이용료와 함께 항공권 가격에 포함되는 유류 할증료가 항공유 시세에 연동되는 구조여서다. 유류 할증료는 매달 16일부터 다음 달 15일까지의 싱가포르 항공유 평균 가격을 기준으로 그다음 달분이 책정된다. 이달 항공료는 배럴당 평균 85달러였던 지난 1월 16일~2월 15일 싱가포르 항공유를 기준으로 계산됐다.대한항공(003490)의 경우 이달 유류 할증료는 △김포~하네다(도쿄)·베이징 등 동북아 노선이 2만 1000원 △인천~방콕·싱가포르·호찌민 등 동남아 노선이 3만 9000원 △인천~런던·파리·로스앤젤레스(LA) 등 유럽·미국 서부 노선이 7만 9500원 △인천~뉴욕·워싱턴 등 미국 동부 노선이 9만 9000원에 형성됐다.이달 들어 싱가포르 항공유는 평균 150달러 안팎에 거래되고 있는데, 이는 러시아·우크라이나 전쟁 발발로 유가가 상승한 2022년 6월과 비슷한 수준이다. 그해 7월 대한항공의 유류 할증료는 △동북아 5만 9800원 △동남아 14만 1700원 △유럽·미국 서부 29만 1200원 △미국 동부 32만 5000원에 달했다. 내달 유류 할증료가 이때 수준으로 오른다면, 이달 대비 왕복 기준 일본은 7만 원, 미국 뉴욕은 45만 원 이상 유류 할증료를 추가로 부담해야 한다.최근 유가 안정으로 유류 할증료가 저렴했던 만큼 소비자들의 체감 충격은 더욱 클 것으로 보인다. 국토교통부는 국제 항공 여객편의 경우 유류 할증료를 총 33단계로 구분하고 있다. 이달 유류 할증료는 6단계로 낮은 편이며, 2022년 7월은 22단계였다. 항공업계 관계자는 "장거리일수록 유류 할증료 인상 폭이 크다"며 "유류 할증료는 발권일을 기준으로 부과되는 만큼 장거리 여행을 계획한 고객이라면 이달 발권을 서두르는 게 저렴하다"고 말했다.지난 8일 인천국제공항 2터미널에서 여행객들이 이동하고 있다. 미국·이스라엘과 이란의 무력 충돌로 중동 하늘길이 막힌 가운데 대한항공은 오는 15일까지 인천~두바이 항공편 운항 중단을 연장한다. 2026.3.8 ⓒ 뉴스1 안은나 기자고환율·공급과잉에 고유가까지 ''3중고''…항공사 실적 회복, 올해도 요원항공사들은 예상치 못한 고유가 사태에 당혹감을 감추지 못하는 분위기다. 고환율 고착에 좌석 공급 과잉으로 지난해 상장 항공사 6곳 중 대한항공을 제외한 5곳이 모두 영업손실을 기록했다. 복수의 상장 항공사가 적자를 기록한 건 신종 코로나바이러스감염증(코로나19)에 따라 여객 운항에 차질을 빚었던 2022년 이후 3년 만이다.가뜩이나 대외 여건이 어려운 상황에서 중동발(發) 고유가까지 악재가 3중고로 늘어난 것이다. 여기에 유류 할증료 상승에 따른 항공권 가격 인상은 여객 수요 둔화로 이어질 수 있어 추가 악재까지 예상된다. 항공업계 관계자는 "중동 사태 장기화로 고유가가 이어진다면 올해 실적 회복은 기대하기 어려울 것"이라고 말했다.유류비가 항공사 전체 영업비용에서 차지하는 비중은 30% 정도로 가장 많다. 대한항공의 경우 연간 유류 소모량은 약 3050만 배럴로 유가 1달러 변동 시 약 3050만 달러(약 450억 원)의 손익 변동이 발생한다. 달러·원 환율이 1400원대 후반으로 자리 잡은 상황에서, 고유가는 항공사들의 비용 부담을 더욱 키울 수밖에 없는 요인이다. 대한항공 관계자는 "연간 예상 유류 소모량을 고려해 헤지를 시행하고 있다"며 "국제 유가 추이를 지속해서 모니터링하며 대응하겠다"고 말했다.', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008814739', 'https://imgnews.pstatic.net/image/421/2026/03/09/0008814739_001_20260309151130560.jpg?type=w800', 'NEWS_TRANSPORT', NULL, '2026-03-09 14:01:04', 0, true, '2026-03-09 06:15:15.201637') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (959, '[제약 리그테이블]중견사 영업익 고만고만…''약가인하 어쩌나''', '10개사 실적 살펴보니 영업이익 대체로 부진이익률 5% 미만 대부분, 약가인하 생존위협JW중외제약과 동아에스티 등 국내 제약 산업의 허리격인 중견 제약사들이 지난해 매출 외형은 눈에 띄게 확대됐으나 영업이익은 대체로 부진한 것으로 나타났다. 핵심 사업인 의약품 부문에서 원가 상승과 판매관리비, 연구개발비 증가 등 비용 부담이 늘어난 것이 수익성을 떨어뜨리게 만들었다.자체 개발 신약을 기반으로 안정적인 실적을 이어가는 대형 제약사들과 달리, 중견 제약사는 제네릭(복제약)과 외부 도입 품목 의존도가 높아 수익성 개선이 쉽지 않다. 정부가 추진하는 약가 인하제가 적용되면 가뜩이나 취약한 중견 제약사들의 수익 기반이 더욱 쪼그라들 수 있다는 우려가 나온다.10개 중견 제약사 매출  외형은 늘었으나...23일 비즈워치가 집계한 JW중외제약, 동아에스티, 휴온스, 대원제약, 일동제약, 한독, 삼진제약, 일양약품, 영진약품, 삼천당제약 등 주요 중견 제약사 10곳의 2025년 연간 매출 총합은 4조4296억원으로 전년 4조2477억원보다 4.3% 증가했다.이들 기업의 지난해 매출 외형은 확대됐으나 영업이익은 감소했다. 10개사의 영업이익 총합은 전년 2502억원에서 2242억원으로 10.4% 줄었다. 의약품 사업 확대로 외형은 키웠지만 일부 기업에서 원가 상승 등 비용 증가로 수익성이 둔화된 것으로 풀이된다. 자체 품목 경쟁력을 기반으로 수익성을 방어한 기업이 있는 반면, 비용 부담 확대 영향으로 이익이 크게 줄어든 기업이 적지 않았다.중견 제약사 가운데 가장 높은 매출과 영업이익을 기록한 JW중외제약은 개량신약 중심 전략으로 외형과 수익을 동시에 끌어올렸다. 이상지질혈증 치료제 ''리바로''와 복합제 ''리바로젯'' 처방 확대에 힘입어 매출 7748억원을 기록했으며, 수익성이 높은 전문의약품 비중 확대가 영업이익 증가(전년비 14.5%↑)로 이어졌다.주요 중견 제약사 실적 변화 /그래픽=비즈워치휴온스 역시 의약품과 건강기능식품 수출 확대에 비용 관리 효과가 더해지며 매출은 5.2% 늘어난 6208억원, 영업이익은 14.3% 증가한 456억원을 달성했다. 북미 주사제 수출 성장과 종속회사 실적 호조도 연결 실적에 긍정적으로 작용했다.한독과 삼천당제약은 전문의약품 판매 호조로 전반적으로 실적이 개선됐지만, 수익성이 낮은 도입 품목과 제네릭 비중이 높은 탓에 영업이익은 100억원을 한참 밑도는 수준에 그쳤다.외형과 수익성 흐름이 엇갈린 기업들도 있었다. 동아에스티는 자체 품목인 성장호르몬제 ''그로트로핀''과 온코닉테라퓨틱스의 위식도역류질환 치료제 ''자큐보'', 입센의 전립선암 치료제 ''디페렐린'' 등 외부 도입 품목의 판매 확대로 매출은 전년 보다 16.5% 늘었지만 원가율 상승과 연구개발비 증가 영향으로 영업이익이 50억원가량 감소했다.또 제네릭 의존도가 높은 대원제약(-84.8%), 영진약품(-60%), 일양약품(-53%), 삼진제약(-15%)도 원료의약품 가격 상승 등 비용 부담 증가로 영업이익이 큰 폭으로 줄었다.반대로 일동제약은 일부 사업 부진으로 매출이 전년 대비 5.6% 줄어든 5669억원에 그친 반면, 인력 효율화 등 비용 구조 조정 효과로 영업이익은 전년 보다 약 48.5% 증가한 195억원을 기록했다.이익률 5% 미만 7곳…약가제도 개편시 생존 위협중견 제약사 상당수가 영업이익률 5%에도 못 미치는 등 수익 구조가 취약한 것으로 나타났다. 10개 제약사 가운데 대원제약과 한독은 영입이익률이 각각 0.6%에 불과했고, 일양약품(1.7%), 영진약품(1.3%), 일동제약(3.4%), 동아에스티(3.7%), 삼천당제약(3.7%) 등 총 7곳이 5%대를 밑돌았다.중견 제약사들의 낮은 수익성은 원료의약품 가격 상승, 인건비·마케팅 비용 증가, 연구개발 투자 확대 등 비용 부담이 겹친 결과다. 실제로 동아에스티에 따르면 원가율이 2024년 49.2%에서 지난해 54.2%로 증가했다.제네릭과 도입 품목 중심의 매출 구조에서 원가 상승에 따른 비용 증가가 곧바로 영업이익 감소로 이어지는 구조적 한계가 드러난 셈이다. 여기에 반복되는 약가 인하로 제네릭 마진은 점차 낮아지는 상황이다.정부가 제네릭 약가 인하 중심의 약가제도 개편을 추진하고 있다는 점에서 중견 제약사들의 수익성 타격은 불가피해 보인다. 영업이익률이 1~3% 수준인 기업은 대대적인 일괄 약가인하가 현실화되면 수익성 악화는 물론 영업이익 적자를 낼 가능성이 크다. 제약업계에서 약가제도 개편에 크게 반발하는 이유이기도 하다.이들 가운데 JW중외제약, 동아에스티, 삼진제약, 삼천당제약 등은 제네릭에서 개량신약과 혁신신약 개발로 넘어가는 과도기에 있어, 중견 제약사들이 안정적으로 성장할 수 있는 합리적 약가제도 검토가 필요하다는 지적이 나온다. 아울러 제약사들 역시 장기적인 수익 확보를 위해 체질 개선과 제품 포트폴리오 재편이 요구된다.업계 관계자는 "마진이 낮고 수익성이 떨어지는 제네릭 사업의 한계를 극복하기 위해 중견 제약사들도 신약 R&D에 발을 내딛는 상황"이라며 "R&D 혁신이 이제 막 확산되는 분위기 속에서 추가적인 약가 인하가 현실화될 경우 소형 제약사뿐만 아니라 중견 기업들 역시 생존을 위협받을 수 있다"고 말했다.', NULL, '비즈워치', 'https://n.news.naver.com/mnews/article/648/0000044663', 'https://imgnews.pstatic.net/image/648/2026/02/23/0000044663_001_20260223100009472.jpg?type=w800', 'NEWS_BIO', NULL, '2026-02-23 10:00:09', 0, true, '2026-03-09 06:15:20.858194') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (960, '부광약품 "한국유니온제약, 2분기부터 실적 편입…내년부터 시너지"', '[이데일리 나은경 기자] 한국유니온제약(080720) 인수를 앞둔 부광약품(003000)이 내년부터 인수로 인한 ''플러스 효과''가 나타날 것이라고 장담했다. 부광약품 편입 첫 해인 올해에도 한국유니온제약의 적자는 없을 것으로 봤다.부광약품 본사 전경 (사진=부광약품)유니온제약 인수로 ''공급중단'' 급한불 껐다9일 오후 부광약품은 2025년 실적 기업설명회(IR)를 열고 이 같이 답했다. 부광약품은 지난해 한국유니온제약의 경영권 인수를 결정하고 관련 절차를 진행 중이다.이제영 부광약품 대표이사는 "공정거래위원회의 기업결합심사가 마무리되는 오는 4월 초에 한국유니온제약 인수가 마무리될 것으로 예상한다"며 "오는 2분기부터 부광약품의 연결실적에 한국유니온제약의 실적이 편입될 것"이라고 설명했다.문제는 한국유니온제약이 최근 3년간 적자 상태였다는 데 있다. 2023년 적자전환한 한국유니온제약은 △2023년 매출 632억원, 영업적자 52억원 △2024년 매출 513억원, 영업적자 135억원 △2025년 3분기 누적 매출 299억원, 영업적자 146억원으로 매년 매출은 줄고 영업적자는 커져가고 있었다.지난 2024년 가까스로 흑자전환에 성공해 찬찬히 실적을 개선시켜가고 있는 부광약품 입장에서는 한국유니온제약의 적자가 우려될 수 있다.이에 대해 이제영 대표는 "한국유니온제약의 적자는 ''높은 영업대행업체(CSO) 수수료율''과 ''수수료 지급 차질''이 ''공장 가동률 하락''으로 이어지는 악순환이 있었기 때문이었던 것으로 파악하고 있다"며 "매출의 가장 큰 비중을 차지하는 세파계 항생제에서는 꾸준히 매출이 잘 나오고 있어 인수 절차가 마무리 지어지면 (부광약품과) 시너지를 낼 수 있을 것"이라고 설명했다.부광약품은 자사 영업조직을 활용해 한국유니온제약과 코프로모션을 진행하거나 한국유니온제약에 적극적으로 위탁제조를 맡김으로써 상승효과를 기대하는 것으로 알려졌다.한국유니온제약 인수로 부광약품의 골칫거리였던 의약품 공급차질 이슈가 해소될 수 있을지 주목된다. 부광약품은 최근 몇년 사이 여러 의약품의 공급차질로 골머리를 앓아왔다. 올해는 △프리마란정 △부광코멜리안정50밀리그램 △부광이소맥지속성캡슐 △부광켈론정 등 벌써 한 달여만에 3건의 의약품이 공급 중단됐다.부광약품은 한국유니온제약 외에도 자사 생산공장에 투자해 생산역량(CAPA)을 확보할 방침이다. 지난해 부광약품은 주주배정 유상증자로 893억원을 조달했는데 이중 한국유니온제약 인수에 300억원을 쓰고, 나머지 300억원은 자사 생산공장에, 나머지 270억원은 연구·개발(R&D)에 쓰겠다고 밝혔다.이 대표는 "앞선 증자의 가장 큰 목표가 CAPA 확충이었다"며 "향후 3년간 경기 안산공장의 낙후된 물류창고를 자동화하고, 다른 생산파트는 신식 제조공장으로 탈바꿈하는 데 300억원을 집행할 예정"이라고 강조했다.부광약품이 일본 스미토모파마에서 국내 독점 판권을 사들인 항정신병 신약 ''라투다'' (사진=부광약품)"연내 ''제2 라투다''·''제2 룬드벡 딜'' 기대해달라"부광약품은 지난해 매출 2007억원, 영업이익 141억원으로 창사 이래 첫 2000억원 돌파에 성공했다. 전년 대비 매출은 25%, 영업이익은 775% 개선된 수치다.이같은 실적개선은 2024년 8월 국내 출시된 항정신병 신약 ''라투다''와 덴마크 제약사 룬드벡과의 기술수출 계약에서 받은 선급금(업프론트)의 영향이 컸던 것으로 풀이된다. 부광약품은 연내 ''제2 룬드벡 딜''과 같은 기술수출, ''제2 라투다''가 될 기술도입에 나서겠다는 계획이다.특히 제2 라투다를 겨냥한 기술도입은 CAPA 확보에 쓰고 남은 270억원을 예산으로 책정했다. 이 대표는 "현재 라투다 장기지속형 주사제 개발 연구가 진행 중이며, 해외에서 좋은 신약후보물질들을 도입하기 위해 좋은 회사를 찾아다니고 있다"며 "남은 유증 예산은 자체적인 신약개발 및 연구, 신약후보물질 도입에 쓰겠다"고 설명했다.일본 스미토모파마가 개발한 라투다는 부광약품이 2017년 한국 내 독점 라이선스를 확보한 의약품이다. 하지만 적은 부작용으로 장기 복용 부담이 적다는 장점이 부각되면서 환인제약(016580), 명인제약(317450), 종근당(185750), 영진약품(003520) 등 다양한 제약사들이 특허 회피를 통해 시장진입을 노리고 있다. 이 때문에 부광약품 입장에서는 라투다를 개량신약으로 만들거나 적응증을 확장하는 등의 노력이 필요한 상황이다. 이 대표의 발언은 라투다의 입지를 강화하는 전략과 동시에 ''포스트 라투다''를 위한 투자를 아끼지 않겠다는 뜻으로 해석된다.최근 룬드벡이 실적발표 어닝 콜에서 콘테라파마와의 협업을 주요 파이프라인으로 다뤘다는 점도 언급됐다.이 대표는 "이는 콘테라파마와 룬드벡의 공동연구가 공식 IR행사에서 언급될 만큼 의미있는 파트너십으로 인식되고 있다는 점에서 (룬드벡의 발표를) 긍정적으로 보고 있다"며 "룬드벡과의 공동연구는 계획된 일정에 맞춰 정상적으로 진행 중이며, 내부적으로 기대한 것보다 더 긍정적인 흐름을 보이고 있다"고 자평했다.이어 그는 "파킨슨병 관련 파이프라인과 RNA 플랫폼 기술을 분리해 좀 더 효율적으로 발전시키기 위한 분사 작업도 진행 중"이라고 덧붙였다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006216392', 'https://imgnews.pstatic.net/image/018/2026/02/10/0006216392_001_20260210090214613.jpg?type=w800', 'NEWS_BIO', NULL, '2026-02-10 09:02:14', 0, true, '2026-03-09 06:15:20.858194') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (961, '다이소몰, ''다이소데이 두근두근 뷰티 위크'' 실시', '다이소몰아성다이소는 오는 8일까지 다이소몰에서 ''다이소데이 두근두근 뷰티 위크'' 행사를 진행한다고 4일 밝혔다.행사는 매일 아침 9시마다 뷰티 신상을 만나볼 수 있는 ''뷰티 위크 오픈런''과 상품기획자(MD)가 추천하는 상품을 엄선한 ''MD''s 픽'' 등으로 구성해 약 370여 종 상품을 선보인다.4일부터 6일까지 진행하는 ''뷰티 위크 오픈런''에서는 ''VT 리들샷 에센스 립 플럼퍼'' 3종, ''더봄 스키니 브로우'' 4종을 선보인다. 인기 상품 ''줌 바이 정샘물''도 5차 재입고해 선보인다. 각종 화장품과 ''영진약품'' 알부민, 키즈 유산균 상품까지 다양하게 구성했다.''MD''s 픽''은 최근 두바이 쫀득 쿠키 유행으로 품절이 지속됐던 ''머쉬멜로우''를 비롯해 인기 초콜릿상품, 선물 포장용품을 엄선했다.정다은 기자 dandan@etnews.com', NULL, '전자신문', 'https://n.news.naver.com/mnews/article/030/0003396398', 'https://imgnews.pstatic.net/image/030/2026/02/04/0003396398_001_20260204143510796.jpg?type=w800', 'NEWS_BIO', NULL, '2026-02-04 14:35:10', 0, true, '2026-03-09 06:15:20.858194') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (962, '[클릭 e종목]"롯데관광개발, 3월 성수기 강한 실적 반등 전망"', '한화투자증권은 9일 롯데관광개발에 대해 3월 성수기 시즌에 들어서면서 실적 회복이 본격화할 것이라고 분석했다. 특히 주가가 연초 이후 조정을 거치며 밸류에이션 매력이 높아진 만큼 적극적인 매수 전략이 유효하다는 설명이다.박수영 한화투자증권 연구원은 이날 보고서를 통해 "부진했던 2월을 뒤로하고 3월부터 성수기 채비에 들어갈 것"이라고 전망했다. 보고서에 따르면 롯데관광개발의 2월 카지노 순매출액은 326억원, 드롭액은 1729억원으로 전월 대비 각각 28%, 34% 감소했다.다만 이는 제주 관광 비수기의 계절적 영향이라는 분석이다. 제주도 관광 수요는 통상 11월부터 2월까지 비수기에 접어들며 실제 2월 제주 왕복 항공편도 전월 대비 약 20% 감소한 것으로 나타났다.다만 3월부터는 상황이 달라질 것으로 전망된다. 박 연구원은 "3월부터 항공편 회복과 대규모 바카라 대회 개최로 카지노 실적의 단기 리바운드 가능성이 높다"며 "비수기 종료 이후 2분기부터 강한 전년 대비 실적 성장세가 다시 나타날 것"이라고 말했다.외국인 카지노 업종 전반의 실적 전망도 긍정적이다. 시장 컨센서스 기준 내년 영업이익 성장률은 롯데관광개발이 14%, 파라다이스가 21%, 그랜드코리아레저가 17%로 예상된다. 지배주주 순이익 성장률은 각각 54%, 27%, 14%로 추정된다.그러나 주가는 연초 이후 섹터 소외로 크게 하락해 밸류에이션 매력이 높아졌다는 평가다. 현재 12개월 선행 기준 주가수익비율(P/E)은 롯데관광개발 16.7배, 파라다이스 14.4배, GKL 13.2배 수준이다. 이는 중국 인바운드 호황기였던 2013~2014년 당시 파라다이스 평균 P/E 약 21배와 비교하면 낮은 수준이다.박 연구원은 "강한 실적 성장이 예상되나 현저히 낮아진 멀티플은 주요 카지노주에 대한 적극적인 매수 대응 전략이 유효하다"며 "P/E 15배 부근에서는 매수가 맞다"고 강조했다.', NULL, '아시아경제', 'https://n.news.naver.com/mnews/article/277/0005731454', 'https://imgnews.pstatic.net/image/277/2026/03/09/0005731454_001_20260309135909984.jpg?type=w800', 'NEWS_IT', NULL, '2026-03-09 13:58:09', 0, true, '2026-03-09 06:15:29.523368') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (963, '코스피 5000선은 ''강력한 지지선''...중동발 변동성, 주도주 비중 확대 기회[어쨌든 경제]', '대신증권 정해창 선임연구원 인터뷰이란 사태는 과열 해소의 트리거실적 기반 주도주 주목[이데일리TV 유은길 경제전문 기자] 지난 주 국내 증시는 그야말로 ‘롤러코스터’ 장세였다. 이틀 연속 급락하던 지수가 다음 날 급등하며 이례적인 변동성을 기록했다.투자자들의 불안 심리가 커진 가운데 대신증권 리서치센터 정해창 선임연구원은 현 상황을 “누적된 피로가 분출된 과열 해소 과정”으로 진단하며, 오히려 핵심 업종에 대한 비중 확대 기회가 될 수 있다고 분석했다.이데일리TV ‘어쨌든 경제’ 초대석에서는 정 연구원과의 인터뷰를 통해 이번 변동성 장세의 배경과 향후 투자 전략을 짚어봤다.중동 리스크가 촉발한 변동성...과열 해소 과정시장 변동성을 키운 핵심 변수는 중동발 지정학적 리스크였다.초기에는 이란 최고지도자 하메네이 사망 소식으로 사태 조기 종식 기대감이 형성됐지만, 이후 이란 혁명수비대의 반격과 호르무즈 해협 봉쇄 가능성이 부각되면서 투자 심리가 빠르게 위축됐다.정 연구원은 “코스피는 2026년 이후 약 50% 상승하며 피로감이 누적된 상황이었다”며 “이란 사태가 트리거가 되면서 과열된 시장의 하방 압력이 한꺼번에 표출된 것”이라고 분석했다.예측보다 대응...협상 과정 변동성 불가피미국과 이란의 갈등은 당분간 시장의 주요 변수로 작용할 전망이다.정 연구원은 “양국 모두 전쟁 장기화는 부담이 큰 만큼 협상을 통한 긴장 완화가 가장 현실적인 시나리오”라고 내다봤다.다만 협상 과정에서 협상력을 높이기 위한 강경 발언이나 국지적 충돌이 이어질 수 있어 단기 변동성은 불가피하다는 설명이다.환율은 일시적으로 1500원을 돌파하기도 했지만 정부의 시장 안정 조치로 관리 가능한 범위에 있다는 분석이다.유가는 현재 시나리오상 배럴당 85달러 수준이 상단으로 예상되지만, 사태가 한 달 이상 장기화될 경우 100달러 돌파 가능성도 열어둘 필요가 있다고 그는 덧붙였다.코스피 5000선은 밸류에이션 바닥...역사적 매수 구간정 연구원은 이번 주 지지선으로 작용한 코스피 5000선에 주목했다.해당 구간은 주가수익비율(PER) 약 8배 수준으로, 과거 미중 무역분쟁, 코로나19 팬데믹 등 극단적인 시장 충격 상황에서만 나타났던 저평가 구간이라는 설명이다.그는 “지나고 보면 이 구간은 항상 매수 기회였다”며 “5000선 부근에서는 공포에 따른 매도보다 장기 관점에서 저평가 매력을 볼 필요가 있다”고 강조했다.“삼성전자·SK하이닉스·현대차 펀더멘털 이상 없다”폭락과 폭등을 주도한 대장주들에 대해서는 낙관적인 전망을 유지했다.정 연구원은 “삼성전자, SK하이닉스, 현대차 등 주도주 3인방의 실적 추세와 펀더멘털은 이번 사태로 훼손되지 않았다”며, 오히려 이런 변동성을 비중 확대의 기회로 활용할 것을 권고했다.추격 매매 금지...현금 비중 관리 필요마지막으로 최근 시장에 진입한 개인 투자자들에게는 리스크 관리를 강조했다.정 연구원은 “오를 때 따라 사고 내릴 때 던지는 추격 매매는 자산 손실의 지름길”이라며 “상승 구간에서는 분할 매도로 현금을 확보하고, 급락 시에는 펀더멘털이 확실한 종목을 분할 매수하는 전략이 필요하다”고 조언했다.이데일리TV 경제 프로그램 ‘어쨌든 경제’는 매주 금요일 오후 4시 TV와 유튜브를 통해 생방송된다.[사진=어쨌든경제 방송 캡쳐] 정해창 대신증권 리서치센터 선임연구원(사진 좌측하단)이 ''어쨌든 경제'' 방송에서 앵커를 맡고 있는 유은길 경제전문기자(사진 중앙)의 질문을 듣고 있다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006231053', 'https://imgnews.pstatic.net/image/018/2026/03/09/0006231053_001_20260309151408511.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 15:14:08', 0, true, '2026-03-09 06:15:36.356298') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (964, '증시 출렁이자 레버리지·인버스 적극 활용…''전투개미'' 통했다', '증시 역대급 급락에도 ''상승 베팅''반등 후 레버리지 팔며 차익실현사진=연합뉴스[파이낸셜뉴스] ''이란 사태''로 국내 증시가 출렁이자, 개인투자자들이 레버리지와 인버스 상장지수펀드(ETF)를 적극 활용하고 있다. 역대급 롤러코스터 장세에서 공격적인 투자로 단기적 성과를 거둔 것으로 분석된다.9일 코스콤 ETF체크에 따르면 개인투자자는 코스피가 급락한 지난 3~4일 이틀간 ''KODEX 레버리지''를 8866억원을 순매수했다. 이후 지수가 반등한 5일에는 2015억원을 순매도하며 차익실현에 나섰다. 반면 3~4일 ''KODEX 200선물인버스2X''는 4155억원 팔아치운 뒤 5일 900억원을 사들였다.코스닥 시장에서도 레버리지·인버스 상품을 적극 활용했다. 지난 3~4일 ''KODEX 코스닥150레버리지''는 9037억원 사들인 반면 ''KODEX 코스닥150선물인버스''는 301억원 순매도했다. 5일 레버리지 상품은 3797억원 팔아치웠고, 인버스 상품은 595억원 순매수했다.이번 개미들의 베팅은 단기적으로 성공한 것으로 평가된다. 코스피·코스닥이 이틀간 크게 흔들린 뒤, 하루 만에 극적 반등하며 하락폭을 회복해 나갔기 때문이다. 코스피와 코스닥 지수는 지난 3~4일에 각각 18.43%, 17.97% 급락한 뒤 5일 각각 9.63%, 14.10% 반등했다.실제 개인투자자들이 레버리지 상품을 적극 매도한 5일 ''KODEX 레버리지''는 19.84%, ''KODEX 코스닥150레버리지''는 25.75% 급등했다. 인버스 상품 매도에 나선 3~4일 ''KODEX 200선물인버스2X''는 45.38%, ''KODEX 코스닥150선물인버스''는 22.20% 상승했다.다만 중동발 리스크로 당분간 변동성 장세가 지속될 것으로 예상되는 만큼, 투자에 유의가 필요하다는 게 증권가 시각이다. 단기 조정 이후 장기적으로는 우상향 흐름을 이어갈 것으로 전망된다.이경민 대신증권 연구원은 "향후 국내 증시는 수주간 지정학적 이슈를 소화할 것으로 보인다"며 "미국과 이란 모두 협상력을 높이기 위한 강경 발언과 무력 행사가 단기 심리적 불안을 자극할 수 있다"고 진단했다.이어 "대내외 여건상 협상을 통한 긴장 완화가 더 합리적인 시나리오"라며 "3월을 넘는 장기화가 현실화되지 않는다면 정책·실적 동력을 재확인하며 상승을 재개할 것으로 예상된다"고 말했다.나정환 NH투자증권 연구원은 "미국·이란 이슈가 완전히 종결된 것은 아니지만, 시장이 극단적 우려에서 벗어나며 우선 낙폭 과대 업종·종목 중심의 반등이 전개될 가능성이 높다"며 "반도체, 이차전지, 자동차, 전력기기 등 낙폭 과대 업종이 먼저 반등한 이후 한국 정책 모멘텀이 있는 금융, 지주 및 코스닥 시장으로 상승 흐름이 확산될 수 있다"고 내다봤다.', NULL, '파이낸셜뉴스', 'https://n.news.naver.com/mnews/article/014/0005488328', 'https://imgnews.pstatic.net/image/014/2026/03/09/0005488328_001_20260309144223759.jpeg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 14:20:10', 0, true, '2026-03-09 06:15:36.356298') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (965, '대신자산신탁, 신림5구역 추진위와 MOU…"재개발 사업 지원"', '신림동 412번지 일대 개발…약 3900세대 대단지 주거 조성 지원[서울=뉴시스](왼쪽 5번째)김송규 대신자산신탁 대표이사와 (왼쪽 6번째)권기백 신림5구역 신속통합준비위원장이 ‘신림5구역 주택재개발 정비사업’ 추진을 위한 MOU를 체결하고 관계자들과 기념촬영을 하고 있다. (사진=대신증권 제공) 2026.03.09. photo@newsis.com[서울=뉴시스] 김진아 기자 = 대신증권 계열사 대신자산신탁은 신림5구역 주택재개발 정비사업 추진을 위해 신속통합준비위원회와 업무협약(MOU)을 체결했다고 9일 밝혔다.이번 MOU를 통해 대신자산신탁은 신림5구역 재개발 사업 초기 단계부터 체계적인 지원에 나설 계획이다.사업지는 서울시 관악구 신림동 412번지 일대로 전체 구역 면적은 약 16만9069㎡로, 재개발을 통해 약 3900세대 규모의 대규모 주거 단지가 들어설 예정이다. 관악구는 서울 서남권 대표 주거 밀집지역으로 여의도·구로·가산디지털단지 등 주요 업무지구와 인접해 직주 근접성이 뛰어나다는 평가를 받는다.김송규 대신자산신탁 대표이사는 "신림동 일대는 노후 주거지 정비 수요가 꾸준하고 재개발·재건축 추진 구역이 인접해 주거환경 개선 기대감이 높은 지역"이라며 "재개발 사업 완료시 서남권을 대표하는 주거단지로 거듭나 지역 가치 상승에도 긍정적인 영향을 줄 것으로 기대한다”고 말했다.', NULL, '뉴시스', 'https://n.news.naver.com/mnews/article/003/0013810198', 'https://imgnews.pstatic.net/image/003/2026/03/09/NISI20260309_0002079082_web_20260309140443_20260309141011924.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 14:09:38', 0, true, '2026-03-09 06:15:36.356298') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (966, '삼성SDI, ‘인터배터리 2026’서 피지컬AI 전용 전고체 배터리 최초 공개', '삼성SDI 부스 조감도.삼성SDI가 11~13일 서울 강남구 코엑스에서 열리는 국내 최대 배터리 전시회 ‘인터배터리 2026’에 참가해 피지컬인공지능(AI)용 전고체 배터리 샘플을 공개한다.9일 삼성SDI는 “피지컬AI 전용으로 개발 중인 파우치형 전고체 배터리를 최초로 공개할 계획”이라고 밝혔다.로봇은 전기차에 비해 훨씬 작은 공간에 사용 시간이 긴 배터리를 탑재해야 한다. 또 움직일 때마다 짧은 순간 전력이 상승하기 때문에 배터리의 출력도 좋아야 한다. 삼성SDI는 로봇용으로 고체 전해질을 사용해 안정성이 높고 에너지밀도도 높은 전고채 배터리를 개발 중이다. 삼성SDI는 “2027년 하반기 양산이 목표”라고 설명했다.LS그룹에선 LS 엠앤엠(MnM)과 LG머트리얼즈, LG알스코 등 7개 계열사가 인터배터리 2026에 총출동한다. LS그룹은 ‘배터리 산업의 시작과 끝, LS가 함께합니다’를 주제로 배터리 소재부터 에너지저장장치(ESS) 플랫폼 등 배터리 산업 전반에 걸친 그룹의 기술력을 선보일 계획이다.한국배터리산업협회에 따르면 올해 인터배터리에는 14개국 667개 업체가 참여해 총 2382개 부스를 열 예정이다. 이 중 182개 업체는 미국과 호주, 캐나다, 독일, 중국, 일본 등 해외 기업이다. 국내 기업의 해외 교류 확대와 시장 진출을 지원하기 위한 국내외 유관기관의 세미나 등도 마련된다.', NULL, '동아일보', 'https://n.news.naver.com/mnews/article/020/0003702474', 'https://imgnews.pstatic.net/image/020/2026/03/09/0003702474_001_20260309150212062.jpg?type=w800', 'NEWS_IT', NULL, '2026-03-09 15:02:12', 0, true, '2026-03-09 06:15:43.903919') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (967, '삼성, 상반기 대규모 공채…"반도체·AI·바이오 청년인재 육성, 5년간 6만명 채용"', '삼성전자, 삼성물산 등 18개사 실시70년째 대규모 공채…4대 그룹 유일5년간 국내서 6만명 대거 채용키로삼성전자 서초사옥. 뉴시스 자료사진.[서울=뉴시스] 홍세희 기자 = 삼성그룹은 오는 10일부터 2026년 상반기 공개 채용을 실시한다고 9일 밝혔다.삼성은 이번 대규모 공채를 통해 청년들에게 양질의 취업 기회를 제공하고, 우수 인재를 확보할 예정이다.이번 공채에 나선 관계사는 ▲삼성전자 ▲삼성물산 ▲삼성바이오로직스 ▲삼성바이오에피스 ▲삼성생명 ▲삼성디스플레이 ▲삼성SDI ▲삼성전기 ▲삼성SDS ▲삼성화재 ▲삼성증권 ▲삼성자산운용 ▲삼성중공업 ▲삼성E&A ▲제일기획 ▲에스원 ▲삼성글로벌리서치 ▲삼성웰스토리 등 18개사다.삼성은 오는 10일부터 17일까지 삼성 채용 홈페이지 삼성커리어스를 통해 지원서를 접수한다. 이후 ▲3월 직무 적합성 평가 ▲4월 삼성직무적성검사 (GSAT) ▲5월 면접 ▲건강검진 순으로 진행한다.삼성은 1957년 국내 최초로 신입사원 공채를 도입한 이래 올해로 70년째 제도를 지속하고 있다. 삼성, SK, 현대차, LG 등 4대 그룹 중 공채 제도를 유지하고 있는 곳은 삼성이 유일하다.삼성은 반도체와 인공지능(AI), 바이오, 배터리, 디스플레이 등 첨단 산업 육성을 위해 국내 투자와 청년 채용 확대에 노력 중이다.이재용 삼성전자 회장은 지난해 8월 열린 경제단체 및 기업인 간담회에서 "국내에서 지속적으로 양질의 일자리를 창출하고 고부가가치 산업을 육성할 수 있게 관련 투자를 지속할 것"이라고 약속했다.이에 따라 삼성은 5년간 6만명을 채용해 미래 성장 사업 육성과 청년 일자리 창출에 나설 계획이다. 올해 신규 채용 규모는 약 1만2000명 수준으로 전망된다.한편, 삼성은 대규모 공채 외에도 인재 육성을 위한 다양한 노력을 지속 중이다.청년들의 소프트웨어 경쟁력 강화를 지원하기 위해 무상으로 양질의 교육을 제공하는 ''삼성청년SW·AI아카데미(SSAFY)를 운영 중이다.또 마이스터고 학생 중 장학생을 선발해 방학 동안 인턴 실습을 한 뒤 졸업 후에는 삼성에 입사할 수 있는 ''채용연계형 인턴 제도''도 운영하고 있다.', NULL, '뉴시스', 'https://n.news.naver.com/mnews/article/003/0013810437', 'https://imgnews.pstatic.net/image/003/2026/03/09/NISI20260309_0021201424_web_20260309125516_20260309150018744.jpg?type=w800', 'NEWS_IT', NULL, '2026-03-09 15:00:00', 0, true, '2026-03-09 06:15:43.903919') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (968, '"갤럭시 고장 아니었다"…이재용 사진 후일담 전한 카를로스', '“청와대 보안 규정으로 사진·녹음 앱 사용 제한”"삼성 장학금으로 성균관대 유학…무선사업부 근무 경험도"카를로스 고리토 인스타그램 통해 당시 상황 설명한·브라질 국빈 만찬 행사에서 있었던 이재용 삼성전자 회장과의 사진 일화를 소개했던 브라질 출신 방송인 카를로스 고리토가 당시 갤럭시 스마트폰이 고장났던 게 아니라는 후일담을 다시 공개했다.고리토는 지난 8일 인스타그램에 글을 올려 “이재용 회장과 관련한 일화에 많은 관심을 가져 놀랐다”며 당시 상황을 추가로 더 설명했다.이재용 삼성전자 회장(왼쪽)과 카를로스 고리토 브라질 출신 방송인. [사진=카를로스 고리토 인스타그램 계정 캡처]고리토는 지난달 23일 청와대 영빈관에서 열린 한·브라질 국빈 만찬에서 행사 사회를 맡았다. 이 자리에서 자신의 갤럭시 스마트폰이 사진 촬영이 되지 않자 참석자들에게 사진 촬용 도움을 요청했고, 이 회장이 나서서 자신의 휴대폰으로 사진을 찍어 이메일로 보내주겠다고 제안한 일화를 전해 화제가 됐었다.고리토는 이번 인스타그램 글에서는 당시 휴대폰이 작동하지 않았던 이유에 대해 “(고장난 게 아니라) 청와대 보안 규정 때문이었다”고 추가로 설명했다.그는 “행사 사회자로 참여해 입장 단계부터 사진 촬영과 녹음 앱 사용이 제한됐다”며 “초청 손님으로 참석한 이 회장 등 귀빈들은 휴대폰 사용이 가능했다”고 밝혔다.이어 “이 회장이 먼저 자신의 휴대폰으로 사진을 찍고 이메일로 보내주겠다고 친절하게 제안했다”며 당시 상황을 전했다.삼성과의 인연도 소개했다. 그는 “성균관대에서 공부할 수 있었던 것도 삼성 장학금 덕분이었고 이후 삼성전자 무선사업부에서 일한 경험도 있다”며 “그래서 지금도 휴대폰은 삼성 제품을 사용하고 있다”고 말했다.또 “한국에서 18년 동안 생활하며 한국인 아내와 결혼하고 방송 활동도 했다”며 “영빈관 만찬 사회 등 다양한 경험을 할 수 있었던 것은 한국과 삼성 덕분”이라고 덧붙였다.고리토는 “예전부터 이 회장에게 직접 감사 인사를 전하고 싶었는데 이런 기회가 생겨 매우 소중한 기억”이라며 “앞으로도 한국을 알리고 한국에 도움이 되는 일을 계속하겠다”고 밝혔다.이날 국빈 만찬에는 이재용 회장을 비롯해 국내 주요 기업 총수들이 참석했다. 재계에서는 정의선 현대자동차그룹 회장, 구광모 LG 대표, 최태원 SK그룹 회장 등이 함께 자리한 것으로 알려졌다.브라질은 삼성전자의 중남미 핵심 시장이다. 삼성전자는 브라질 상파울루주 캄피나스와 마나우스 등에 생산거점을 운영하며 스마트폰과 TV, 가전제품을 현지에서 생산하고 있다. 마나우스 공장은 삼성전자의 중남미 최대 생산기지 가운데 하나로 스마트폰과 TV 등을 생산한다.한편 삼성전자는 오는 11일 신제품 ''갤럭시S26'' 시리즈 출시를 앞두고 있다. 이달 초 진행한 사전예약에는 국내에서만 135만대가 판매됐다.', NULL, '아이뉴스24', 'https://n.news.naver.com/mnews/article/031/0001011496', 'https://imgnews.pstatic.net/image/031/2026/03/09/0001011496_001_20260309135806448.jpg?type=w800', 'NEWS_IT', NULL, '2026-03-09 13:58:06', 0, true, '2026-03-09 06:15:43.903919') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (969, '새파랗게 질린 한국증시, 코스피 역대 최대 12% 급락', '한달 1000포인트 올랐던 코스피, 사흘만에 도로 5000피코스피·코스닥 동반 급락, 동시 서킷브레이커 발동미국-이스라엘과 이란간 전쟁 여파로 국내 증시가 사상 최악의 하루를 보냈다. 코스피는 12%, 코스닥은 14% 하락했다.한국거래소에 따르면 4일 코스피는 전날보다 12.06% 급락한 5093.54포인트로 장을 마감했다. 12.03% 하락했던 2000년 미국 911테러 당시를 넘어서는 사상 최대 하락폭이다.지난 한 달여간 1000포인트 오르며 6000포인트를 돌파, 6300포인트까지 단숨에 올랐던 코스피는 불과 사흘만에 무려 1200포인트를 토해내며 도로 5000포인트대로 밀렸다.패닉 매도와 저가 매수세가 겹치며 수급은 혼조세를 보였다. 외국인이 2377억원 순매수세로 돌아섰지만 기관은 5888억원 순매도했다. 개인은 이날도 796억원어치를 순매수했다.대표 종목들도 지수만큼 큰 폭으로 주가가 빠졌다. 삼성전자는 11.74%, SK하이닉스는 7.03% 하락했고, 현대차는 14.45%, 기아는 12.51%나 떨어졌다. HD현대중공업은 12.2%, 두산에너빌리티는 15.07% 하락했다.전쟁 영향에 전날 급등했던 방산주도 상승분을 고스란히 토해냈다. 한화시스템은 22.02% 폭락했고, 한화오션은 18.54%, 풍산은 11.94%, SNT다이내믹스는 15.19%, LIG넥스원은 6.35% 하락했다.코스닥은 더 큰 폭으로 떨어졌다. 코스닥은 전날보다 14% 하락한 978.44포인트로 장을 마치며 한 달만에 1000포인트 아래로 밀렸다.외국인은 1조1752억원, 기관은 252억원 순매수했고, 개인은 1조2028억원어치를 던졌다. 에코프로는 18.41%, 에코프로비엠은 16.99% 떨어졌고, 알테오젠 13.32%, 삼천당제약 14.46%, 레인보우로보틱스는 16.19% 하락하며 새파란 색으로 장을 마쳤다.이날 코스피와 코스닥이 동시에 큰 폭으로 하락하며 오전 11시 16분, 두 시장에서 동시에 서킷브레이커가 발동되기도 했다. 서킷브레이커는 직전 거래일보다 8% 이상 하락해 1분간 지속될 때 발동하며, 모든 시장에서 20분간 매매가 정지된다. 매매정지 해제 후에도 10분간 단일가매매하고 이후에 접속매매가 가능하다.조아인 삼성증권 연구원은 전쟁격화와 미중 정상회담 취소, 사모신용펀드의 환매요청 급증, 국내 증시의 반대매매 우려 등이 복합적으로 작용해 증시 급락을 이끌었다고 분석했다.조 연구원은 "전쟁 양상의 불확실성이 높은 만큼 당분간 변동성 장세가 지속될 수 있지만, 펀더맨털과 이익을 고려할 때 현재와 같은 주가 하락은 과도한 수준"이라며 "당기 급락에 따른 반발 매수세 유입 가능성도 열려 있다"고 분석했다.임정은 KB증권 연구원은 "국제 정세의 불안정성 및 그로 인한 매크로 환경의 불확실성이 지속되고 있다"며 "불확실성 속에서 기업의 펀더멘탈 변화 여부에 집중할 필요가 있다"고 밝혔다.', NULL, '비즈워치', 'https://n.news.naver.com/mnews/article/648/0000044953', 'https://imgnews.pstatic.net/image/648/2026/03/04/0000044953_001_20260304171608705.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-03-04 16:37:10', 0, true, '2026-03-09 06:15:52.821883') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (970, '쿠팡 실적', '27일 장 체크리스트▷오전 6시(한국시간)쿠팡실적▷오전 8시30분일본2월 도쿄소비자물가지수▷오전 9시재정경제부, MSCI 선진국지수 편입 추진TF▷오전 10시재경부3월 개인투자용 국채 발행계획▷오전 11시재경부1월 국세수입 현황▷오전 11시30분세제개편후속 시행규칙 개정안▷낮 12시한국은행1월 금융기관 가중평균금리 및 거주자외화예금▷오후 3시30분한국기업거버넌스포럼공시제도 개편 세미나▷오후 10시30분(한국시간)미국1월 생산자물가지수▷SNT홀딩스 SNT에너지 SNT모티브 SNT다이내믹스 DKME 인바이오젠 글로벌텍스프리 DH오토웨어 오성첨단소재 비덴트 한울앤제주 버킷스튜디오주주총회▷코오롱인더실적', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005255921', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_AUTO', NULL, '2026-02-26 17:29:09', 0, true, '2026-03-09 06:15:52.821883') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (971, 'HLB생활건강 ''미인실록'' 헤어&바디, 루마니아서 초도물량 완판', 'HLB생활건강의 프리미엄 미백 브랜드 ''미인실록''의 펩타이드 헤어&바디 케어 라인 제품./사진=HLB생활건강 제공HLB글로벌 자회사 HLB생활건강의 프리미엄 뷰티 브랜드 ''미인실록'' 헤어&바디 라인이 루마니아에서 초도 물량이 완판됐다고 5일 밝혔다.HLB생활건강은 루마니아의 대표 로컬 약국 체인 알마 파머시(Alma Pharmacy) 오프라인 매장에 ''미인실록 펩타이드 헤어&바디 케어'' 라인을 선보였다.이번 제품은 그룹사인 HLB펩의 고기능 펩타이드 적용과 전달 효율을 높이는 시스템 설계 기술과 술지게미 업사이클링 기반 발효 바이오 원료까지 더해지며 제품 완성도를 끌어올렸다. 여기에 한국적인 미를 살린 패키지 디자인이 더해지며 긍정적인 반응을 이끌어냈다는 설명이다.알마 파머시 입점은 루마니아 현지 유통사와 바이어의 요청으로 추진됐다. 미인실록이 현지에서 프리미엄 K뷰티 브랜드로 자리 잡으면서 ''고기능 바이오''와 ''클린 뷰티''를 결합한 신제품에 대한 관심도 높아졌다.HLB생활건강은 지난해 7월 루마니아 오프라인 뷰티 시장에 미인실록 앰플, 크림, 팩클렌저 등을 유통하기 시작했다.김혜란 HLB생활건강 대표는 "''고기능 바이오''와 ''클린 뷰티''의 결합이 단순한 세정을 넘어 피부와 모발의 근본적인 개선을 중시하는 유럽 2030세대의 니즈에 부합한 것으로 보인다"며 "루마니아를 교두보로 동유럽은 물론 북유럽과 서유럽 시장까지 진출 범위를 점진적으로 확대해 나가겠다"고 말했다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005325577', 'https://imgnews.pstatic.net/image/008/2026/03/05/0005325577_001_20260305091616528.jpg?type=w800', 'NEWS_CHEM', NULL, '2026-03-05 09:16:01', 0, true, '2026-03-09 06:15:59.604352') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (972, '증시 폭락에 거래 멈췄다… 강원 상장사 직격타', '코스피·코스닥 서킷브레이커 발동코스피 12%↓ 5000피 턱걸이''중동 긴장'' 투자심리 얼어붙어도내  LS에코에너지 등 급락▲ 코스피가 미국과 이란 간 전쟁 발발 여파로 역대 최대 폭으로 폭락해 5100선마저 내준 4일 코스피는 전장보다 698.37포인트(12.06%) 내린 5093.54에, 코스닥은 159.26포인트(14.00%) 급락한 978.44에 장을 마쳤다. 원/달러 환율은 10.1원 오른 1476.2원이다.  연합뉴스속보= 중동 정세 불안 속에 투자 심리가 위축되면서(본지 3월 4일자 1면) 서킷브레이커가 잇따라 발동되는 등 국내 증시가 큰 변동성을 보이는가운데, 강원지역 상장사도 일제히 하락했다.4일 한국거래소 공시를 보면 이날 코스피와 코스닥은 각각 5093.54(-12.06%), 978.44(-14.00%)에 장을 마감, 하루만에 10%p 이상 급락했다. 오전 한때에는 장중 급격한 하락세가 나타나며 거래가 일시 중단되는 서킷브레이커가 20분 간 발동됐다. 서킷브레이커는 주가가 전일 종가 대비 8% 이상 급락할 경우 투자자 보호와 시장 충격 완화를 위해 일정 시간 거래를 중단하는 제도다.최근 국내 증시는 가파른 상승 이후 단기간에 큰 조정을 겪고 있다. 코스피 지수는 2024년 1월 2일 2669.81에서 지난해 1월 2일 2398.94로 한 차례 조정을 거친 뒤, 이재명 정부 출범 이후인 2026년 1월 2일에는 4309.63까지 급등하며 상승세가 본격화됐다. 이후 상승 흐름이 이어지면서 지난 2월 26일에는 장중 6307.27까지 올라 최고치를 기록하기도 했다.그러나 상승세는 오래가지 않았다. 중동 지역의 군사적 긴장과 글로벌 금융시장 불안이 겹치면서 투자 심리가 급격히 냉각됐다. 전쟁 발발 이후 첫 거래일인 지난 3일 코스피는 5791.91로 크게 하락했고, 4일에는 5093.54까지 밀리며 낙폭이 확대됐다. 최근 최고치와 비교하면 불과 며칠 사이 1200p 이상 빠진 셈이다.코스닥 시장 역시 비슷한 흐름을 보였다. 코스닥 지수는 2024년 1월 2일 878.93에서 지난해 1월 2일 686.63으로 하락한 뒤 올해 1월 2일 945.57까지 회복됐다. 이후 상승세를 이어가 코스닥 지수 최고치를 기록했던 지난달 26일에는 1064.41, 이튿날인 27일에는 코스닥 또한 최고치인 1192.78까지 상승했다. 이후 지난 3일에는 1188.15, 4일에는 978.44로 급락하며 1000선 방어에 실패했다.특히 단기간 급등했던 반도체와 인공지능(AI) 관련 대형 기술주가 이번 하락장에서 낙폭을 키우며 지수 하락을 주도했다는 분석이 나온다. 글로벌 증시 전반의 위험 회피 심리가 확대되면서 외국인과 기관 투자자 매도가 동시에 나타난 것도 지수 변동성을 키운 요인으로 지목된다. 증권가에서는 당분간 시장 변동성이 이어질 가능성이 크다는 전망이 나온다. 지정학적 리스크가 해소되지 않을 경우 투자심리가 빠르게 회복되기 어렵기 때문이다.시장에서는 특히 코스피가 심리적 지지선으로 여겨지는 5000선을 지킬 수 있을지에 관심이 쏠리고 있다. 최근 낙폭을 고려하면 추가 하락 가능성도 배제할 수 없다는 분석이 나오면서 투자자들의 긴장감도 커지고 있다.한편, 강원지역 상장사 또한 일제히 하락세를 면치 못했다. 이날 LS에코에너지는 15.67% 하락한 3만 7950원, HLB글로벌은 10.30% 하락한 1767원, 모나용평은 9.48% 하락한 2865원에 장을 마감했다. 코스닥 시장에서는 삼표시멘트(-22.59%), 에이프릴바이오(-19.03%), 대화제약(-17.43%), 메디아나(-12.95%), 파마리서치(-12.33%)순으로 큰 낙폭을 보였다.김혜정 기자 hyejkim@kado.net#하락 #증시 #코스닥 #상장 #지수', NULL, '강원도민일보', 'https://n.news.naver.com/mnews/article/654/0000169217', 'https://imgnews.pstatic.net/image/654/2026/03/05/0000169217_001_20260305091907006.jpg?type=w800', 'NEWS_CHEM', NULL, '2026-03-05 00:09:50', 0, true, '2026-03-09 06:15:59.604352') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (973, 'HLB생활건강, 대구한의대와 산학협력 결실…‘우수기업상’ 수상', 'HLB글로벌 자회사인 HLB생활건강은 최근 대구시 호텔수성에서 열린 ‘대구한의대학교 산학연협력 성과 확산 포럼’에서 ''산학협력 우수기업상''을 수상했다고 밝혔다.이번 포럼은 지역 기업과 대학이 함께 만드는 상생 모델을 공유하고, 산학연 협력을 통해 성장한 우수기업의 성과를 널리 확산하기 위해 마련됐다.HLB생활건강은 대구한의대학교 가족기업으로서 산학연계교육, 공동 연구개발, 기술이전 등 다양한 산학협력 활동을 통해 기술혁신과 지역 산업 발전에 기여한 공로를 인정받아 수상의 영예를 안았다.앞서 HLB생활건강과 대구한의대학교는 ‘K-MEDI 성장 및 화장품 산업 공동협력 MOU’를 체결한 이후 지속적인 공동 연구를 추진해 왔다. 그 성과로 두피·모발·바디케어 플랫폼 처방 기술을 기반으로 개발한 ‘미인실록 펩타이드 헤어&바디 라인’을 출시했다.‘미인실록 펩타이드 헤어&바디’ 제품은 펩타이드 전문기업 HLB펩의 고기능 펩타이드를 제형에 안정적으로 적용하고, 생체 친화적 전달 효율을 극대화하는 시스템 설계 기술을 확립한 것이 특징이다. 또한 HLB생활건강은 기존에 폐기되던 술지게미를 유효 성분이 풍부한 발효 바이오 원료로 전환하는 업사이클링 기술을 접목해 제품 완성도를 높였다.김혜란 HLB생활건강 대표이사는 “앞으로도 대구한의대와의 긴밀한 협력을 통해 차별화된 제품을 지속적으로 선보이며 K-뷰티 산업의 경쟁력 강화에 기여하겠다”고 말했다.<사진=김혜란 HLB생활건강 대표이사(사진 오른쪽)>', NULL, '한국경제TV', 'https://n.news.naver.com/mnews/article/215/0001243339', 'https://imgnews.pstatic.net/image/215/2026/02/27/A202602270448_1_20260227141009722.jpg?type=w800', 'NEWS_CHEM', NULL, '2026-02-27 14:09:56', 0, true, '2026-03-09 06:15:59.604352') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (974, '방림, 자사주 18만주 처분…임직원 상여금 지급', '방림은 임직원 상여금 지급을 위해 자기주식 18만333주를 처분했다고 2일 공시했다.처분 단가는 1주당 5490원으로, 처분 금액은 총 9억9002만8170원이다. 해당 주식은 지난달 30일 임직원 상여금 지급을 목적으로 회사의 자기주식 계좌에서 임직원 증권 계좌로 이체됐다.처분 이후 방림의 자기주식 보유량은 859만1380주로, 전체 발행주식 대비 21.37%다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000078791', 'https://imgnews.pstatic.net/image/293/2026/02/02/0000078791_001_20260202154513436.png?type=w800', 'NEWS_ETC', NULL, '2026-02-02 15:45:13', 0, true, '2026-03-09 06:16:07.056931') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (975, '방림, 자사주 12만주 처분…임직원 상여금 지급', '방림은 5일 임직원 상여금 지급 명목으로 자사주 12만주 처분을 완료했다고 6일 공시했다.처분 이후 방림이 보유한 자사주는 877만1713주로 이는 전체 발행주식의 21.82%에 해당한다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000077386', 'https://imgnews.pstatic.net/image/293/2026/01/06/0000077386_001_20260106131807392.png?type=w800', 'NEWS_ETC', NULL, '2026-01-06 13:18:07', 0, true, '2026-03-09 06:16:07.056931') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (976, '기업공시[12월 12일]', '[서울경제]<코스피 공시>▲방림(003610)=주당 70원 현금배당 결정 ▲동부건설(005960)=1124억 원 규모 수원당수 공공주택건설사업 우협 선정 ▲계룡건설(013580)=1122억 원 규모 수원당수 공공주택건설사업 우협 선정 ▲대우건설(047040)=2980억 원 규모 수원당수 공공주택건설사업 우협 선정 ▲진흥기업(002780)=1622억 원 규모 충남 아파트 건설공사 수주 ▲배당기준일 관련 정관 변경=토니모리(214420),현대오토에버(307950),미래에셋증권(006800),LG이노텍(011070),애경산업(018250),제주은행(006220),교촌에프앤비(339770)<코스닥 공시>▲로스웰(900260)=자진 상장폐지를 위한 공개매수 결정 ▲빛샘전자(072950)=주당 70원 현금배당 결정 ▲카티스(140430)=19일 기업설명회 개최 ▲DH오토웨어(025440)=사업목적 추가 정관 변경 ▲빅텍(065450)=111억 원 규모 소형전자전장비 공급계약 체결 ▲상상인(038540)=102억 원 규모 보통주 소각 ▲동국S&C(100130)=원자재 입고에 따른 생산 재개 ▲하이드로리튬(101670)=40억 원 규모 제3자 배정 유상증자 결정', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004566688', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2025-12-12 16:51:14', 0, true, '2026-03-09 06:16:07.056931') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (977, 'KGM ''무쏘'' 순항…누적 계약 5000대 넘겼다', '국내 시장 점유율 약 85% 차지무쏘 ⓒKG모빌리티[데일리안 = 편은지 기자] KG 모빌리티(KGM)의 신형 픽업 무쏘가 원조 ''K-픽업''의 입지를 공고히 하고 있다.KGM은 지난 1월 출시한 ‘무쏘’가 현재까지 누적 계약 대수 5,000대를 넘어섰다고 9일 밝혔다. KGM의 국내 픽업 시장 점유율은 약 85%에 달한다.‘무쏘’는 지난 1월 19일 1호차를 시작으로 2월까지 총 2516대를 고객에게 인도하며 픽업 1위 자리를 확고히 했다. 전기 픽업 ‘무쏘 EV’ 역시 전기차 보조금이 확정된 지자체를 중심으로 안정적인 판매 흐름을 이어가며 올해 1369대를 판매했다.KGM이 ‘무쏘’의 계약 데이터를 분석한 결과, 고객들은 ‘디젤 엔진’ 및 ‘4WD 사양’, ‘스탠다드 데크’를 가장 많이 선택하는 것으로 나타났다.트림별로는 주요 안전·편의 사양을 갖추면서도 가격 부담을 낮춘 중간 트림 M7(52.4%)이 과반이 넘는 선택을 받았다. 최고급 사양을 기본으로 두루 갖춘 최상위 트림 M9(39.7%)도 많은 호응을 얻고 있다.파워트레인 선택에서는 디젤 모델과 가솔린 모델이 각각 54.4%와 45.6%로 균형을 이뤘다. 사륜구동(4WD) 선택률은 92.6%에 달해 픽업 본연의 강력한 퍼포먼스와 활용성을 중시하는 고객들의 수요가 그대로 반영됐다. 데크 타입은 일상 활용도가 높은 스탠다드 데크(69.9%)의 선택률이 높았다.고객층을 살펴보면 개인이 52.8%, 사업자가 47.2%이며, 50~60대는 비즈니스용으로 활용하는 경향을 보인 반면 30~40대에서는 레저와 여가 활동 등 다양한 라이프스타일에 맞춰 픽업을 선택하는 것으로 분석됐다.KGM 관계자는 “정통 픽업 본연의 기능에 충실한 구성과 높은 가격 경쟁력을 바탕으로 비즈니스부터 레저까지 다양한 고객층의 니즈를 충족시키고 있다”라며 “지난 2월부터 가솔린 모델 출고를 본격적으로 시작함에 따라 시장 경쟁력을 더욱 높여갈 것”이라고 밝혔다.', NULL, '데일리안', 'https://n.news.naver.com/mnews/article/119/0003066910', 'https://imgnews.pstatic.net/image/119/2026/03/09/0003066910_001_20260309151307524.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-03-09 15:13:07', 0, true, '2026-03-09 06:16:15.115795') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (978, 'KGM, ''무쏘'' 누적 계약 5000대 돌파', 'KGM 무쏘. 사진=KG모빌리티.KG모빌리티는 지난 1월 출시한 신형 픽업 ‘무쏘’가 지난달까지 누적 계약 대수 5000대를 넘었다고 9일 밝혔다.무쏘는 지난 1월 19일부터 2월까지 총 2516대가 판매됐다. 무쏘EV는 올해 1~2월 누적 1369대가 판매됐다. KGM은 올해 1~2월 국내 픽업 모델 기준 시장에서 약 85%의 점유율을 차지했다고 설명했다.KGM은 데이터를 분석한 결과 트림별로 중간 트림 M7(52.4%)이 절반이 넘는 선택을 받았다. 최상위 트림 M9은 39.7%의 점유율을 차지했다. 디젤 선택 비중은 54.5%로, 가솔린 선택 비중(45.6%) 대비 높았다.사륜구동(4WD) 선택률은 92.6%에 달했다. 데크 타입은 일상 활용도가 높은 스탠다드 데크 선택률이 69.9%를 기록했다.개인 소비자가 52.8%, 사업자가 47.2%를 차지했다. 외장 색상은 스모크 토프(28.3%)와 그랜드 화이트(28.2%)가 나란히 상위권에 올랐고, 내장은 브라운 인테리어(45.6%)가 많이 선택됐다.주요 선택 사양으로는 3D 어라운드 뷰 모니터링 시스템(59.3%)과 그랜드 스타일 패키지(45.8%)의 선호도가 높게 나타났다.KGM 관계자는 “정통 픽업 본연의 기능에 충실한 구성과 높은 가격 경쟁력을 바탕으로 비즈니스부터 레저까지 다양한 고객층의 니즈를 충족시키고 있다”며 “지난 2월부터 가솔린 모델 출고를 본격적으로 시작함에 따라 시장 경쟁력을 더욱 높여갈 것”이라고 밝혔다.', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005259823', 'https://imgnews.pstatic.net/image/015/2026/03/09/0005259823_001_20260309132716850.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-03-09 13:27:16', 0, true, '2026-03-09 06:16:15.115795') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (979, '유가 급등에 정유주 강세…에쓰오일 24% 급등[특징주]', '[이데일리 김경은 기자] 미국과 이스라엘의 이란 공습 여파로 국제 유가가 급등하면서 정유주가 강세다.3일 엠피닥터에 따르면 이날 오전 9시 3분 기준 S-Oil(010950)(에쓰오일)은 전 거래일 대비 3만6500원(24.09%) 급등해 13만6500원에 거래되고 있다.같은 시각 극동유화(014530)도 830원(23.38%) 상승한 4380원에, 미창석유(003650)는 2만5000원(18.53%) 오른 15만9900원에 거래 중이다.정유주가 급등한 건 중동의 지정학적 위기가 고조되면서 정유 수급 불균형이 나타날 것이라는 전망에서다.삼성증권은 이날 에쓰오일의 목표주가를 14만원으로 상향 제시하며 “중동 전쟁이 지속될 경우 현재보다 타이트한 등경유 제품 중심의 정제 설비를 전쟁 위험이 없는 아시아에서 생산하고 있다는 점이 지정학적 관점에서 기회로 작용할 것”이라고 강조했다.2일(현지시간) ICE선물거래소에서 5월 인도분 브렌트유 선물 종가는 배럴당 77.74달러로 전 거래일 대비 6.7% 올랐다. 브렌트유 선물 가격은 장중 한때 배럴당 82.37달러로 13% 급등하며 지난해 1월 이후 1년여 만에 최고가를 기록했다.뉴욕상품거래소에서 4월 인도분 서부텍사스산원유(WTI) 선물 종가는 배럴당 71.23달러로 전장 대비 6.3% 상승했다. WTI 선물 역시 장중 한때 배럴당 75.33달러로 12% 급등하며 지난해 6월 이후 최고가를 기록했다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006227236', 'https://imgnews.pstatic.net/image/018/2026/03/03/0006227236_001_20260303091624403.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-03 09:16:24', 0, true, '2026-03-09 06:16:21.269149') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (980, '[인터배터리 26 관전포인트] ① AI 인프라 시장 겨냥…전력망 ESS·로봇 솔루션 등장', '[배터리레이다] 인터배터리 2026 11일 개막인터배터리 2025 관람객. / 사진 = 배태용 기자[디지털데일리 고성현기자] 전세계적인 인공지능(AI) 인프라 투자 광풍으로 침체됐던 배터리 업계가 반등을 다짐하고 있다. AI가 필요로 하는 전력을 배터리로 충당하는 전력망 에너지저장장치(ESS) 시장이 확대된 덕분이다. 이에 따라 다가온 국내 최대 배터리 산업 전시회 ''인터배터리 2026''에서도 ESS를 비롯한 휴머노이드 로봇 등 AI 대응 솔루션이 화두가 될 전망이다.산업통상부가 주최하고 한국배터리산업협회, 코엑스, 대한무역투자진흥공사(KOTRA)가 주관하는 ''인터배터리 2026''이 오는 11일부터 13일까지 사흘 동안 서울 코엑스에서 개최된다. 전세계 14개국에서 약 667개 기업이 참여할 예정이다.올해 인터배터리의 전시 부스를 채울 핵심 키워드는 AI가 될 전망이다. 전기차 시장 장기 둔화로 국내산 배터리 수요가 떨어진 가운데, 미국 중심의 AI 인프라 투자 급증이 ESS 배터리 중심 판도를 확대하고 있는 영향이다. 또 피지컬 AI 고도화에 따라 산업 내 적용 가능성이 높아진 로봇용 배터리도 관심을 받고 있다.국내 주요 배터리 셀 제조사들도 일제히 AI 솔루션을 간판에 내걸었다. LG에너지솔루션은 국내 전력 인프라에 최적화된 전력망용 ESS 솔루션 ''JF2 DC LINK 5.0''을 선보인다. 이 제품은 국내 최초로 LFP 배터리를 탑재해 화재 안전성을 대폭 끌어올렸다.또 AI 데이터센터 전력 급증에 대비해 LFP 기반 차세대 JP6 UPS용 랙 시스템과 고출력 원통형 배터리를 탑재한 배터리백업유닛(BBU) 솔루션을 국내 최초로 공개한다. 이와 함께 LG전자 홈로봇 ''LG 클로이드''와 베어로보틱스 자율주행 로봇 및 드론에 사용하는 고성능 원통형 배터리와 차세대 리튬망간리치(LMR) 배터리도 처음 전시할 예정이다.삼성SDI 인터배터리 2026 전시 부스 조감도 [사진=삼성SDI]삼성SDI는 전력망 ESS와 함께 데이터센터 서버에 직접 대응하는 솔루션인 무정전전원장치(UPS), 배터리백업유닛(BBU)을 내세웠다. UPS용 리튬망간산화물(LMO) 배터리 ''U8A1''과 전력 피크 시 서버 랙 전력에 대응하는 BBU 솔루션을 전시할 예정이다. 이와 함께 일체형 ESS 브랜드인 ''삼성배터리박스(SBB)'' 풀 라인업, AI 기반 화재 예방 소프트웨어 ''SBI''를 공개한다.매년 공개해 왔던 전고체 배터리 분야에서는 로봇 등 피지컬AI로 활용할 파우치 기반 샘플을 전시한다. 내년 하반기로 전고체 양산이 다가온 만큼, 적용처에 맞춰 폼팩터를 넓혀 대응하겠다는 목표다.SK온은 파우치 배터리 기반 역량을 내세운 솔루션과 SK그룹 계열 회사 간 시너지 등을 중심으로 부스를 전개한다. 파우치 셀투팩(CTP), 파우치 통합 각형 팩, 대면적 냉각기술(LSC) CTP 등 3종과 셀-모듈-팩으로 구성된 CMP(Cell-Module-Pack) 패키지 1종을 선보인다.SK엔무브와 공동 개발하는 액침냉각 플루이드 기술을 융합한 팩 모형도 전시한다. SK온은 차량 하부 모형에 ‘액침냉각 팩’을 적용하고 액침냉각 소형 모듈이 냉각 플루이드에 침지된 모습 등을 시각적으로 연출할 예정이다.포스코퓨처엠 인터배터리 2026 전시 조감도. [사진=포스코퓨처엠]소재에서도 데이터센터에 대응하는 제품을 소개한다. 포스코퓨처엠은 데이터센터용 장수명 양·음극재와 고내식·차폐 강판 등 에너지 저장 및 전력 인프라용 핵심 소재를 전시하며, 엘앤에프는 차세대 Fe₂O₃ 공법 기반 3세대 및 초고밀도 LFP 양극재 개발 현황을 공개할 예정이다.배터리 업계는 이번 전시회가 침체된 배터리 시장의 반등을 위한 전환점이 될 수 있다는 기대감을 드러내고 있다. 국내 주요 배터리 셀·소재 기업이 미국발 ESS 투자에 힘입어 실적 반등 국면에 접어든 가운데, 자율주행·휴머노이드 로봇에 대응하는 솔루션 실물을 내놓고 성장 동력을 회복할 수 있다는 이유에서다.전기차 수요 둔화로 생존 경쟁이 심화된 것 역시 인터배터리의 주목도를 높이는 요소 중 하나다. ESS 시장이 셀·소재·부품 등 각 요소에서 전기차 시장보다 과점 기업이 발생할 가능성이 높아, 성과 및 경쟁력을 알리기 위한 홍보 경쟁도 치열해질 전망이다.', NULL, '디지털데일리', 'https://n.news.naver.com/mnews/article/138/0002219952', 'https://imgnews.pstatic.net/image/138/2026/03/09/0002219952_001_20260309121807608.JPG?type=w800', 'NEWS_ENERGY', NULL, '2026-03-09 12:18:07', 0, true, '2026-03-09 06:16:26.727802') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (981, '“포스코퓨처엠, 베트남 인조흑연 투자로 음극재 사업 반등 기대”', '포스코퓨처엠 포항 인조흑연 음극재 공장 생산라인. [포스코퓨처엠]DS투자증권은 9일 포스코퓨처엠에 대해 베트남 인조흑연 생산법인 설립을 통해 음극재 사업의 구조적 개선 국면에 진입할 것으로 예상하면서 2027년부터 음극재 사업부의 구조적 흑자 전환이 가시화될 전망이라고 분석했다. DS투자증권은 포스코퓨처엠에 대해 투자의견 ‘매수’와 목표주가 29만원을 유지했다.업계에 따르면 포스코퓨처엠은 최근 이사회를 열고 베트남 북부 타이응웬성에 인조흑연 음극재 공장을 신설하기 위해 약 3570억원을 투자하기로 결정했다. 올해 하반기 착공해 2028년부터 양산을 시작할 예정인 이 공장은 향후 수주 상황에 따라 연산 5만5000톤 규모까지 단계적으로 확장이 가능하다.DS투자증권 기업 분석 보고서에 따르면, 해당 투자는 약 2만~2만5000톤 규모의 생산능력 확보를 목표로 한 것으로, 향후 글로벌 전기차 배터리 소재 수요 확대에 대응하기 위한 전략적 투자로 평가된다. 아직 관련 수주는 확인된 바 없으나 지난해 10월 천연흑연 수주를 감안하면 글로벌 완성차 업체(OEM)향 인조흑연 수주도 기대해볼 수 있다고 분석했다.이번 투자 배경으로는 글로벌 공급망 변화가 꼽힌다. DS투자증권은 중국의 흑연 수출 통제와 미국의 공급망 규제 강화로 글로벌 완성차 업체들이 탈중국 배터리 소재 공급망을 확보하려는 움직임이 확대되고 있다고 분석했다.특히, DS투자증권은 오는 12일 최종 발표될 미국 국제무역위원회(ITC)의 중국산 흑연 반덤핑 상계관세는 점유율 확대 및 수익성 제고의 기회라고 강조했다.미국이 중국산 흑연에 대해 최소 160% 수준의 반덤핑·상계관세를 부과할 경우 중국산 수입 단가는 kg당 약 9.1달러 이상으로 상승하는 반면 베트남산은 25% 관세를 적용해도 약 6.3달러 수준이다. 미국산 생산단가인 kg당 7달러 수준에 판가가 수렴할 가능성이 높아 스프레드 확대 여지도 크다는 분석이다.DS투자증권은 2027년 음극재 흑자 전환 가시화 및 밸류에이션(평가가치) 리레이팅(재평가)을 기대한다고 설명했다.최태용 DS투자증권 연구원은 “2만5000톤 신규 라인이 풀가동될 경우 북미향 인조흑연 예상 판가(kg당 7달러)를 적용하면 연평균 약 2500억원의 신규 매출 기여가 예상된다”며 “2026년까지는 물량 증가에 따른 가동률 회복 국면을 거친 뒤 2027년에는 음극재 사업부의 구조적 흑자 전환이 가시화될 것”이라고 말했다.그는 이어 “미국의 금지외국기관(FPE) 요건 강화로 고객사들의 탈중국 공급망 구축 수요가 늘어날 것”이라며 “향후 추가 수주가 확인될 경우 밸류에이션 상향의 트리거가 될 것”이라고 했다.', NULL, '매일경제', 'https://n.news.naver.com/mnews/article/009/0005647040', 'https://imgnews.pstatic.net/image/009/2026/03/09/0005647040_001_20260309085708157.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-03-09 08:57:08', 0, true, '2026-03-09 06:16:26.727802') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (982, '전고체·하이니켈 ''퍼스트 무버'' 격돌', '인터배터리 11일부터 사흘간포스코·에코프로·엘앤에프 3사전기차·AI·로봇 기술 경쟁 주목포스코퓨처엠과 에코프로, 엘앤에프 등 국내 배터리 소재 3사가 오는 11일부터 13일까지 서울 강남구 코엑스에서 열리는 ''인터배터리 2026''에서 차세대 소재 기술을 일제히 선보인다. 전기차(EV)와 에너지저장장치(ESS)는 물론 휴머노이드 로봇과 인공지능(AI) 데이터센터에 이르기까지 확장된 응용처를 겨냥한 기술 포트폴리오를 소개한다는 계획이다. 특히 세 기업 모두 전고체 배터리 소재와 리튬·인산·철(LFP)·울트라 하이니켈 양극재를 핵심 먹거리로 내세우며 기술 경쟁에 불을 지폈다.8일 업계에 따르면 포스코퓨처엠은 ''투게더, 드로잉 BoT(Battery of Things) 퓨처''를 주제로 5개 부스를 운영한다. 자율주행 EV를 겨냥한 니켈 함량 95% 이상 울트라 하이니켈 양극재, ESS와 엔트리급 전기차용 LFP 양극재, 그리고 로봇 등 차세대 산업의 게임체인저로 주목받는 전고체 배터리용 양극재와 실리콘 음극재 등을 한 자리에서 선보인다는 계획이다. 포스코퓨처엠이 차세대 시장 선점을 위해 미국 전고체 배터리 기업인 팩토리얼과 공동으로 연구한 오픈 이노베이션 성과도 공개된다. 양 사는 전시 기간인 12일 배터리 소재 연구개발 전략을 소개하는 기조 강연도 합동으로 진행하기로 했다.에코프로는 ''Perfect Chain, Connected Value''를 주제로 4개 공간에서 하이니켈 삼원계부터 전고체 소재 풀 밸류체인까지 아우르는 기술 라인업을 전시한다. 지난 4년간 약 8000억원을 투자해 구축한 인도네시아 니켈 제련 사업과 유럽 현지 규제에 대응하는 헝가리 양극재 공장 등 글로벌 공급망 성과를 공개하고, 2027년 양산을 목표로 개발 중인 고체 전해질과 전고체용 양극재, 리튬 메탈 음극재 등 전고체 소재 전 라인업도 선보인다.이와 함께 휴머노이드 시대를 겨냥한 미드니켈 양극재, 나트륨이온배터리(SIB) 양극재, 리튬망간리치(LMR) 양극재, ESS용 LFP 양극재까지 폭넓은 제품군도 전시된다. 나아가 사용 후 배터리 재사용·재활용을 포괄하는 배터리 생애주기 관리(Battery Asset Management, BAM) 시장 진출 계획과 오창 R&D 미래캠퍼스 건설 로드맵도 이번 전시를 통해 처음 윤곽을 드러낸다.엘앤에프는 ''리딩 더 퓨처(Leading the Future)''를 주제로 전시 참가 이래 최대 규모(약 87평) 부스를 운영한다. 핵심은 2026년 하반기 국내 최초 LFP 양극재 양산 돌입 선언이다. 지난해 인터배터리에서 LFP 양산 계획을 예고한 데 이어, 이번엔 구체적인 기술 실체를 처음 공개한다. 특히 산화철(Fe₂O₃)을 원료로 쓰는 ''무전구체 LFP'' 차세대 공법과 자체 인산철(FP) 기술 개발 성과를 세계 최초로 선보인다. 이 공법은 핵심 소재의 중국 의존도를 낮추면서도 원가 경쟁력을 동시에 확보할 수 있어 업계의 주목을 받고 있다. 이미 세계 최초 양산에 성공한 니켈 함량 95% 울트라 하이니켈(NCMA95) 양극재와 3세대 LFP(압축밀도 2.50g/cc 이상), 초고밀도 LFP(2.70g/cc급) 개발 현황, 전고체전지(ASSB)·나트륨이온전지(SIB)용 차세대 양극재 포트폴리오도 함께 공개한다.', NULL, '파이낸셜뉴스', 'https://n.news.naver.com/mnews/article/014/0005487872', 'https://imgnews.pstatic.net/image/014/2026/03/08/0005487872_001_20260308183417053.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-03-08 18:34:17', 0, true, '2026-03-09 06:16:26.727802') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (983, '남대서양 해역서 벌어지는 ‘금징어 전쟁’···대형선 허용 vs. 지역업체·환경단체 반발', '지난해 11월30일 서울 시내 대형마트에 진열된 오징어. 연합뉴스정부가 최근 ‘금징어’라 부를 만큼 급등한 오징어 가격을 잡겠다며 국내 오징어 공급의 핵심 어장인 남서대서양 공해에 7700t급 대형 원양 트롤선(저인망 어선) 조업을 추가로 허가했다.이 해역에는 중국 어선 500여척이 조업하고 있는데, 한국도 국제적인 규제 도입시 어획량 할당을 확보하기 위해 조업 실적을 미리 쌓겠다는 계산도 깔려 있다.그러나 수십 년간 이곳에서 오징어를 잡아 온 부산 지역 중소업체들은 수익 감소를 우려하며 반발하고 있고, 환경단체는 해양 생태계 파괴를 경고했다. 물가 안정과 대·중소기업 상생 문제, 생태 보전이라는 세 가지 가치가 충돌하는 양상이다.2일 정부와 업계의 말을 종합하면, 해양수산부는 지난달 9일 브라질·아르헨티나 동쪽 바다인 남서대서양에서 원양 트롤선 4척의 오징어 조업을 추가로 허가했다. 남극바다에서 크릴을 잡던 동원산업의 7700t급 원양 트롤선 세종호가 남서대서양으로 이동해 오징어를 잡고 있다. 내년부터는 북태평양에서 명태를 잡던 트롤선인 남북수산의 남북호, 사조오양의 제99오양호, 한성기업의 준성호도 투입된다.남서대서양 해역에서 조업 중인 오징어 어선들의 불빛이 인공위성에 찍혔다. NASA 지구 관측소 제공.정부가 조업을 허가한 곳은 유엔식량농업기구(FAO)가 지정한 남서대서양 41해구(FAO 41해구)다. 아르헨티나와 영국령 포클랜드섬 사이에 있는 공해로, 양국의 영유권 분쟁으로 사실상 ‘주인 없는 바다’다. 이곳엔 어획량을 규제할 국제기구인 ‘지역수산관리기구(RFMO)’도 없어 중국, 스페인, 대만, 한국, 어선 등이 경쟁적으로 조업해 왔다. 밤이면 오징어 집어등 불빛이 우주에서도 선명히 보일 정도다.이 해역은 국내 오징어 수급의 핵심 어장이다. 한국해양수산개발원은 국내에서 소비되는 오징어의 약 90%가 이 해역에서 생산된다고 추산했다. 그동안 부산 지역 500t급 채낚기 어선 29척과 3000t급 트롤선 11척이 정부 허가를 받아 이 해역에서 조업 중이었다.정부가 대형 트롤선 조업 추가 허가에 나선 이유는 급감한 어획량과 치솟은 가격 때문이다. 기후 위기로 동해 수온이 2~4℃ 높아지며 동해안에서 오징어가 자취를 감췄다. 국가데이터처 국가통계포털을 보면, 연근해에서 잡힌 오징어는 2021년 6만880t에서 지난해 3만1006t으로 4년 만에 반 토막 났다. 원양 어획량도 같은 기간 7만3867t에서 5만2122t으로 줄었다. 그 결과 가격이 급등했다. 수협중앙회 수산경제연구원이 발표한 ‘2026 수산경제전망’을 보면, 냉동 오징어의 소비자 가격은 2021년 1㎏당 1만5260원에서 지난해 2만108원으로 31.8% 올랐다.정부는 대형 트롤선 투입으로 올해 오징어 생산량이 최대 2000t 늘고, 소비자 가격은 10% 하락할 수 있다고 기대한다. 해수부 관계자는 “물가 안정 대책으로 국내에서만 팔아야 한다는 조건을 달아 트롤선 조업을 추가로 허용했다”고 설명했다.그러나 기존 조업 업체들은 반발했다. 윤동호 남서대서양 오징어 채낚기위원회 위원장은 “조업 중인 29척은 모두 500t급 채낚기 어선인데, 8000t급 대기업 어선이 새로 들어오면 경쟁이 안 된다”며 “중소업체들은 생존하기 어렵다”고 말했다.동원산업의 7700t급 원양 트롤선 세종호. 동원산업 제공어획 방식에 따른 환경 영향 논란도 제기된다. 채낚기는 밤에 불빛을 밝혀 오징어를 낚싯줄에 한 마리씩 낚는 반면, 트롤은 자루 모양의 그물을 끌어 어류를 한꺼번에 잡는 방식이다. 남서대서양에서 조업 중인 전선중 정일산업 부사장은 “저인망식 트롤은 오징어뿐 아니라 다른 어종까지 함께 잡아 생태계에 더 좋지 않은 영향을 미친다”며 “우리 정부가 국제사회에서 중국 어선의 무분별한 조업을 비판하면서 초대형 선박을 투입하는 것이 과연 설득력이 있나”라고 반문했다.정부도 반박 논리가 있다. 앞으로 생길 국제 규제에 대비해 FAO 41해구에 어획량 쿼터를 확보하려면 지금부터 조업 실적을 쌓아야 한다는 것이다. 해수부 관계자는 “FAO 41해구에 지역수산관리기구(RFMO)가 생긴다면 어획량 쿼터를 확보할 때 우리 어선의 조업 실적이 절대적으로 필요하다”고 말했다. 이 관계자는 “중국 배들이 남서대서양에서 잡은 오징어가 매년 6만t씩 우리나라로 수입되고 있다”며 “중국 어선들은 이 해역에서 편안하게 잡고 있는데, 우리만 손을 놓을 순 없다”고 말했다.오징어 채낚기 배가 남서대서양에서 오징어를 낚고 있다. 남서대서양 오징어 채낚기위원회 제공환경단체들도 반발에 가세했다. 기후해양정책연구소(CORI)는 지난달 23일 논평에서 “기후위기 시대에 원양 오징어 조업 허가를 확대하는 것은 근시안적인 조치이며, 해양 생태계를 고갈시켜 미래 세대에게 부담을 넘기는 일”이라며 원양 오징어 조업 허가 확대 방침 재고를 촉구했다.오징어는 멸종위기종은 아니지만 해양 생태계에서 먹이사슬 중간고리 역할을 한다. 그린피스는 2022년 발표한 보고서에서 “오징어 남획은 이를 먹이로 삼는 바다사자, 고래, 상어, 바닷새를 비롯한 전체 생태계에 심각한 위협을 가한다”고 했다. 국제환경단체인 환경정의재단(EJF)은 지난해 발간한 보고서에서 “오징어는 수명이 짧아 환경 조건에 매우 민감하다”며 “단 한 해의 남획만으로도 개체군 붕괴로 이어질 수 있다”고 경고했다.동원산업은 그러나 과도한 우려라는 입장이다. 동원산업 관계자는 “어획량은 선박 규모가 아닌 그물 크기가 좌우하는데, 세종호의 그물의 크기는 기존에 조업 중인 다른 트롤선들과 똑같아서 잡을 수 있는 물량은 비슷하다”며 “많이 잡아야 올해 1500t 수준이고 전량 국내로 들어가는 물량을 대체한다”고 말했다.대형 트롤선 투입이 실제 오징어 소비자 가격 인하로 이어질지, 아니면 어장 경쟁과 환경 논란만 키울지는 향후 조업 결과로 판가름 날 전망이다.', NULL, '경향신문', 'https://n.news.naver.com/mnews/article/032/0003430728', 'https://imgnews.pstatic.net/image/032/2026/03/03/0003430728_001_20260304110514887.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-03 06:00:08', 0, true, '2026-03-09 06:16:33.300104') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (984, '한성기업 ‘크래미’ 출시 25주년 맞았다', '사진 제공=한성기업한성기업은 대표 프리미엄 맛살 브랜드 ‘크래미’가 출시 25주년을 맞았다고 13일 밝혔다.2001년 국내 최초의 고급 맛살로 탄생한 크래미는 출시 당시 전분 함량을 대폭 낮추고 알래스카 1등급 연육을 사용해 실제 게살에 가까운 식감을 구현하며 큰 인기를 끌었다. 한성기업에 따르면 25년간 크래미의 누적 판매 횟수는 약 3억 8553만 회를 기록했다. 사용된 연육의 총량은 7만 5867톤에 이른다.한성기업은 25주년을 기점으로 크래미의 브랜드 정체성 강화에 집중할 방침이다. 크래미는 한성기업이 독자적으로 개발해 등록한 고유 상표명임에도 불구하고, 높은 인지도로 인해 일반 명사처럼 혼용되는 경우가 많기 때문이라는 설명이다. 한성기업은 이번 캠페인을 통해 원조 프리미엄으로서의 독점적 지위를 공고히 할 계획이다.한성기업은 25주년을 기념해 브랜드의 성장을 함께 이끈 소비자 팬클럽인 ‘CHEFde한성(쉐프드한성)’의 활약도 조명했다. 쉐프드한성은 크래미를 활용한 창의적인 레시피를 자발적으로 공유해온 소비자들로 구성된 한성기업의 파트너 그룹이다. 이들이 제안한 크래미 레시피는 크래미가 단순 간식을 넘어 다양한 미식 요리로 소비자들의 삶에 얼마나 깊숙이 녹아 있었는지를 보여주는 살아있는 증거라고 회사 측은 강조했다.한성기업 마케팅실은 “크래미의 25년은 소비자의 삶 속에 녹아들어 함께 성장한 시간”이라며 “앞으로도 원조 프리미엄 브랜드로서 고객과 소통하며 지속 가능한 식문화를 선도하겠다”고 말했다. 한성기업은 현재 25주년 특별 페이지를 통해 브랜드 히스토리와 고객 참여 레시피를 포함한 80가지의 크래미 레시피를 공개 중이다.', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004590231', 'https://imgnews.pstatic.net/image/011/2026/02/13/0004590231_001_20260213135412557.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-13 13:54:12', 0, true, '2026-03-09 06:16:33.300104') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1130, '기업공시 [2월 19일]', '<코스피 시장>▲삼성물산(028260)=차기 3개년 최소 주당 배당금은 2500원으로 상향 ▲고려산업(002140)=주당 40원 현금배당 결정 ▲파미셀(005690)=두산 전자BG와 약 92억 원 규모 전자재료용 소재 공급 계약 체결 ▲삼성SDI(006400)=투자 재원 확보 및 재무구조 개선을 위해 보유 중인 삼성디스플레이 지분 매각 추진 검토 ▲한신공영(004960)=타이거자산운용, 장내 매수 통해 지분 5.65% 확보 ▲더핑크퐁컴퍼니(403850)=KT(030200)보유 지분 7.89%에서 3.94%로 축소 ▲POSCO홀딩스(005490)=약 6351억 원 규모 자사주 169만 1425주 소각 결정<코스닥 시장>▲클래시스(214150)=171억 원 규모 자사주 27만 주 소각 결정 ▲RFHIC(218410)=레이시온 캐나다와 506억 원 규모 고출력 전력증폭기 공급 계약 체결', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004591397', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_BIO', NULL, '2026-02-19 16:39:07', 0, true, '2026-03-09 06:24:03.759555') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (985, '“크래미는 상표입니다” 한성기업, 25주년 맞아 브랜드 정체성 재정립', 'ⓒ한성기업[데일리안 = 임유정 기자] 한성기업의 대표 프리미엄 맛살 브랜드 ‘크래미’가 출시 25주년을 맞았다.지난 2001년 국내 최초의 고급 맛살로 탄생한 크래미는 출시 당시 전분 함량을 대폭 낮추고 알래스카 1등급 연육을 사용해 실제 게살에 가까운 식감을 구현하며 큰 인기를 끌었다.한성기업에 따르면 25년간 크래미의 누적 판매 횟수는 약 3억8553만회를 기록했으며, 사용된 연육의 총량은 7만5867톤에 이른다.특히 한성기업은 이번 25주년을 기점으로 ‘크래미’의 브랜드 정체성 강화에 집중할 방침이다.‘크래미’는 한성기업이 독자적으로 개발해 등록한 고유 상표명임에도 불구하고, 높은 인지도로 인해 일반 명사처럼 혼용되는 경우가 많기 때문이다.한성기업은 이번 캠페인을 통해 ‘원조 프리미엄’으로서의 독점적 지위를 공고히 할 계획이다.한편, 한성기업은 이번 25주년을 기념해 브랜드의 성장을 함께 이끈 소비자 팬클럽인 ‘CHEFde한성(쉐프드한성)’의 활약을 조명했다.‘CHEFde한성’은 크래미를 활용한 창의적인 레시피를 자발적으로 공유해온 소비자들로 구성된 한성기업의 파트너 그룹이다.이들이 제안한 크래미 레시피는 크래미가 단순 간식을 넘어 다양한 미식 요리로 소비자들의 삶에 얼마나 깊숙이 녹아 있었는지를 보여주는 살아있는 증거다.한성기업 마케팅실은 “크래미의 25년은 소비자의 삶 속에 녹아들어 함께 성장한 시간”이라며, “앞으로도 원조 프리미엄 브랜드로서 고객과 소통하며 지속 가능한 식문화를 선도하겠다”고 말했다.한성기업은 현재 25주년 특별 페이지를 통해 브랜드 히스토리와 고객 참여 레시피를 포함한 80가지의 크래미 레시피를 공개 중이다.', NULL, '데일리안', 'https://n.news.naver.com/mnews/article/119/0003059472', 'https://imgnews.pstatic.net/image/119/2026/02/12/0003059472_001_20260212161615656.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-12 16:16:15', 0, true, '2026-03-09 06:16:33.300104') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (986, '전쟁으로 인한 유가 폭등에… 美 "러 원유 제재 추가완화 가능"', '인도 러 석유 수입 한시 허용에 이어"대러 제재 해제로 원유 공급 만들 수 있어"원유 가격 주간 상승률, 1983년 이후 최대미국 캘리포니아주 엘세군도 해안에 성조기 뒤로 원유 수송선 한 척이 정박한 모습이 보이고 있다. 엘세군도(미국 캘리포니아주)=AP 연합뉴스미국·이란 전쟁으로 주요 원유 운송로인 호르무즈해협이 봉쇄되며 유가가 크게 오르자 미국이 러시아산(産) 원유에 부과된 제재를 추가 해제할 가능성을 내비쳤다. 국제 원유 가격은 배럴당 90달러(약 13만3,000원)를 넘어서며 1983년 이후 가장 큰 주간 상승률을 기록한 상태다."해상에 떠 있는 러 원유 수입 허가"스콧 베선트 미국 재무장관은 6일(현지시간) 미국 폭스비즈니스방송과의 인터뷰에서 "재무부는 이미 동맹국 인도가 해상을 통해 운송 중인 러시아산 원유를 구매할 수 있도록 허용했다"며 "전 세계적인 일시적 원유 공급 부족을 완화하기 위해 수입을 허용한 것"이라고 밝혔다. 이어 "다른 러시아산 원유에 대한 제재도 해제할 수 있다"며 "(현재 해상에는) 수억 배럴의 제재 대상 원유가 있고, 재무부가 제재를 해제한다면 (원유) 공급을 만들어낼 수 있을 것"이라고 덧붙였다.미국은 그간 러시아의 원유 수출을 막아 러시아·우크라이나 전쟁 수행을 위한 자금을 마련하지 못하게 하겠다는 근거를 들며 인도의 러시아산 원유 수입을 막아왔다. 그러나 미국·이란 전쟁으로 이란이 호르무즈해협의 유조선 통행을 막으며 유가가 폭등하면서 5일 인도의 러시아산 원유 수입을 다음달 4일까지 30일간 허용한 상태다.유가 인하 조치 이어지지만이날 미국 정부 관계자들은 잇따라 유가 인하를 위한 추가 조치를 약속했다. 케롤라인 레빗 백악관 대변인은 유가를 위한 "구체적인 조치가 있을 것"이라며 호르무즈해협을 통과하는 유조선에 대한 미 해군 호위를 제공하겠다는 트럼프 대통령 발언을 다시 언급했다. 트럼프 대통령 본인 역시 이날 미국 CNN방송과의 인터뷰에서 "(유가 상승은) 단기적인 현상일 뿐이다. 급격히 떨어질 것"이라며 애써 안심하라는 메시지를 보냈다.호르무즈해협을 지나는 유조선을 대상으로한 ''추가 보험''에 대한 구체적인 계획도 나왔다. 이날 미국 국제개발금융공사(USIDFC)는 성명을 통해 미국·이란 전쟁 기간 석유 및 가스 운송과 관련해 최대 200억 달러(약 29조6,000억 원)의 손실에 대한 재보험(보험사의 부담을 분담하는 보험)을 제공할 것이라고 발표했다.여러 조치에도 유가는 고공행진을 계속 이어가고 있다. 이날 뉴욕상품거래소(NYMEX)에서 4월 인도분 서부텍사스산중질유(WTI) 선물 가격은 전장 대비 12.21% 오른 90.90달러(약 13만4,600원)에 거래를 마쳤다. 미국 월스트리트저널(WSJ)의 집계에 따르면 전쟁 발발 후 한 주간 WTI 가격은 36% 폭등했는데, 이는 1983년 이후 가장 큰 폭의 주간 상승률이다. WSJ는 이날 전문가 분석을 인용해 원유 가격이 배럴당 100달러(약 14만8,000원)를 넘길 가능성이 높다고 전망하기도 했다.', NULL, '한국일보', 'https://n.news.naver.com/mnews/article/469/0000918064', 'https://imgnews.pstatic.net/image/469/2026/03/07/0000918064_001_20260307105811666.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-07 10:24:14', 0, true, '2026-03-09 06:16:40.365913') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (987, '[거버넌스워치] 대기업 은퇴 후 60세에 중기 재취업해 360억 대박…산일전기 누구', '[중견기업 진단] 산일전기④현대重 출신 한익희 사장 스톡옵션 21만3300주이환수·오창희 상무 290억 등 줄줄이 대박행진직원들도 우리사주 통해 1인당 수억 목돈 챙겨한마디로 파죽지세다. 매년 매출 천억원대 앞자리 숫자를 갈아치우는 폭풍 성장을 앞세워 주식시장 입성 1년 반 만에 주가는 상장 공모가의 5배로 치솟았다. 몸값은 5조원을 훌쩍 넘어섰다. 산업용 변압기를 주력으로 하는 신흥 중견기업 산일전기 얘기다.창업주 박동석(65) 회장은 주식자산 2조원에 육박하는 거부(巨富) 반열에 올랐다. 오너를 보좌해온 임원들도 수백억원 대박을 터트렸다. 대기업 은퇴 후 60세에 재취업해 360억원을 거머쥔 이도 있다. 직원들도 예외가 아니다. 우리사주로 수억원의 목돈을 만졌다. 대기업 못지않은 성장의 과실(果實)을 맛보고 있다.증시 입성 1년 반 만에 주가 5배 폭등산일전기는 올해 1월22일 신주 10만주가 상장됐다. 앞서 5일 스톡옵션(주식매수선택권)이 행사된 데 따른 것이다. 주당 3344원짜리다. 산일전기가 2024년 7월 증시에 상장한 이래 첫 신주 상장이다.백성규(68) 전 전무(해외영업2부문장)가 행사했다. 박동석(65) 회장이 1987년 8월 창업한 이래 초기부터 함께해온 임원이다. 남웅해운․보양상운 통신장, 삼영정공을 거쳐 1993년 산일전기에 입사해 30년 넘게 잔뼈가 굵었다. 작년 4월 말 퇴임했다.‘[거버넌스워치] 산일전기 ①편’에서 얘기한대로, 2022년부터 시작된 미국발 초호황으로  산일전기 주가는 상장 이후 펄펄 날고 있다. 3만5000원(상장 공모가)으로 출발해 딱 1년만인 작년 7월 10만원을 돌파했다. 지금은 17만700원(2월24일 기준)으로 뛰어올랐다.백 전 전무의 10만주 차익실현 여부는 알 수 없지만 예상 수익이 어마하다. 신주 상장 뒤 산일전기 주가는 낮아봐야 13만6200원이었다. 평균값(15만3450원)에 처분했더라도 약 4490%(주당 15만원), 총 150억원의 수익을 챙겼을 것이란 계산이다.이게 다가 아니다. 남아 있는 스톡옵션도 7만650주나 된다. 초창기 멤버였던 까닭에 보유 주식도 많았다. 2024년 11월~작년 3월 4만4778주를 29억원에 현금화한 뒤 퇴임 때 12만3164주(지분 0.4%)를 갖고 있었다. 당시 시세(종가 5만4500원) 67억원, 현 시세로 210억원어치다.산일전기 주가 추이산일전기 최대주주 주식가치스톡옵션 행사가 3344원…주가 50분의 1돈방석에 앉은 경영진, 백 전 전무 말고도 수두룩하다. 김상준(64) 상무(재경팀장) 6만6450주(113억원)를 비롯해 8명이 현재 16만1646주, 276억원어치를 보유 중이다. 특히 대박 임원들에 관한 한, 빼놓고 갈 수 없는 인사 더 있다.이번 스톡옵션은 산일전기가 2023년 6월 임원 4명에게 신주발행 방식으로 부여했던 것이다. 앞서 같은 해 3월 대표주관계약(미래에셋증권)을 체결하고 본격적으로 기업공개(IPO)에 나선 직후다.당시 가장 많은 스톡옵션을 받았던 이가 한익희(69) 현 사장이다. 21만3300주다. 백 전 전무와 이환수(54) 상무(해외영업2부문장), 오창희(50) 상무(전략기획팀장)가 17만650주씩을 받았다. 도합 72만5250주다. 총발행주식(10만주 행사 전 3044만5200주)의 2.38%다.한 사장은 HD현대중공업맨이다. 2007년 상무보로 임원을 단 뒤 서울사무소, 해외지사를 거쳐 2013년 전기전자시스템사업본부 전무로 승진했다. 2014년 12월 임원 퇴임 뒤 자문역으로 활동하다 2017년 초 산일전기 사장으로 영입됐다. 작년 3월에는 공동대표에 올라 한 회장을 보좌하며 전기사업본부를 총괄하고 있다.한 사장의 스톡옵션 예상 차익이 357억원(주당 16만7000원)에 달한다. 한 사장이 합류한 2017년만 해도 산일전기는 매출이 작년(5020억원)의 거의 10분의 1(543억원)에 불과한 중소기업에 지나지 않았다. 영업이익은 150분의 1(11억원/1820억원)도 안됐다. 결국 1957년생인 한 사장이 대기업 은퇴 후 60세에 과거 납품 중소기업에 재취업해 초대박을 터트렸다는 얘기가 된다.두 현직 상무도 예상수익이 각각 286억원이나 된다. 이 상무 또한 HD현대중공업 출신의 해외영업통이다. 해외영업·미주지사장을 지낸 뒤 2016년 4월 제룡전기 이사를 거쳐  이듬해 한 회장과 비슷한 시기에 산일전기에 입사했다. 오 상무는 인공지능 영상인식 솔루션 상장사 알체라 재무최고책임자(CFO)로 활동한 뒤 2023년 초 자리를 옮겼다.한 사장을 비롯해 전현직 임원 3명은 상장후 스톡옵션 의무보유(보호예수) 기한(1년)이 작년 7월 말에 풀려 언제든 주식 전환이 가능해졌다. 비교적 근래에 합류한 오 상무는 올해 7월 말(2년) 해제된다. 행사기간은 2030년 6월까지다.산일전기 스톡옵션상장 전 우리사주 주당 3344원 증자 ‘잭팟’임원들뿐만 아니다. 직원들도 주식으로 꽤 두둑한 수익을 거뒀다. 산일전기가 스톡옵션 부여 한 달 뒤인 2023년 7월 우리사주조합에도 같은 가격(주당 3344원)으로 29억원 유상증자를 실시한 데서 비롯됐다. 주식수로는 임원(미등기) 16명 16만1500주, 직원 96명 69만1500주 도합 85만3000주다.직원 1인당 배정주식은 평균 7200주가량이다. 직원들은 상장 직후인 2024년 8월 1년 의무예탁기간이 종료되자 그 해에 거의 대부분 주식을 처분했다. 한때 2만9650원으로 공모가를 밑돌기도 했지만 7만4000원까지 주가가 상승했던 시기다. 평균치(5만1800원)에 매각했더라도 1인당 3억4900만원의 수익을 챙겼을 것이란 의미다.이뿐만 아니다. 우리사주는 2660억원(신주모집 650만주·2660억원, 구주매출 110만주·385억원) 상장공모 때 우선배정분 20%(152만주·532억원) 중 8.55%를 소화했다. 액수로 227억원, 주식수는 64만9655주다. 당시 임직원수(303명)로 환산하면 1인당 2044주다.작년 7월 말 상장 1년 의무보유 제한이 풀렸다. 이 또한 해제 직후 대부분 내다 팔아 9월 말에 가서는 16만9552주가 남았다. 이때는 주가가 10만3300원~13만100원을 오르내렸다. 평균값(11만6700원)에 처분했더라도 1인당 1억7500만원의 차익(평가수익 포함)을 손에 쥐었다.산일전기 재무실적', NULL, '비즈워치', 'https://n.news.naver.com/mnews/article/648/0000044882', 'https://imgnews.pstatic.net/image/648/2026/03/03/0000044882_001_20260303071017018.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-03-03 07:10:17', 0, true, '2026-03-09 06:16:46.988064') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (988, '삼영, 지난해 영업익 149억…전년비 63.9% ↑', '[헤럴드경제=증권부] 삼영은 지난해 연결기준 영업이익이 149억2118만원으로 전년대비 63.94% 증가했다고 27일 공시했다.같은 기간 매출액은 1532억830만원으로 21.56% 늘어난 것으로 나타났다.당기순이익은 150억4802만원으로 80.23% 증가한 것으로 집계됐다.', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002606363', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_AUTO', NULL, '2026-02-27 14:27:17', 0, true, '2026-03-09 06:16:46.988064') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (989, '공포지수·빚투 치솟아…"변동성 커지면 ''도미노 하락'' 올수도"', '코스피200 변동성지수 50 넘어"증시 열기 과도…숨고르기 필요"코스피지수가 연일 최고치 랠리를 이어가는 가운데 시장의 불안 심리를 반영하는 ‘공포지수’가 치솟고 있다. 개인투자자의 ‘빚투’(빚내서 투자) 규모도 사상 최대치로 불어나며 변동성을 키울 수 있다는 우려가 나온다.26일 한국거래소에 따르면 이날 코스피200 변동성지수(VKOSPI)는 전 거래일 대비 10.29% 오른 54.67을 기록했다. 8거래일 연속 상승이다. 이 지수는 코스피200 옵션 가격을 토대로 한 달 뒤 지수 변동성을 예측하는 지표다. 통상 50을 넘으면 ‘극단적 공포’ 구간으로 해석한다.증권가에서는 코스피지수 단기 급등에 따른 고점 부담과 도널드 트럼프 미국 행정부의 관세 정책 불확실성을 주요 변수로 지목한다. 특히 미 연방대법원의 상호관세 위법 판결 이후 트럼프 대통령이 관세체계를 재정비하는 과정에서 아직 세율이 확정되지 않은 반도체 업종을 겨냥할 가능성도 거론된다. 김지현 다올투자증권 연구원은 “반도체 품목 관세 여부에 따라 관련 종목의 주가 변동성이 확대될 수 있다”고 분석했다.개인투자자의 신용거래도 부담 요인이다. 금융투자협회에 따르면 지난 25일 기준 신용거래 융자 잔액은 32조1340억원으로 사상 최대를 기록했다. 연초 대비 약 18% 늘었다. 신용거래 융자는 개인이 증권사에서 자금을 빌려 주식을 매수한 뒤 아직 상환하지 않은 금액이다.일부 중·소형주는 신용잔액 비율이 상장 주식 수의 7~9%에 달한다. 유가증권시장에서는 삼영(8.74%)이 가장 높았고 한농화성(8.02%), YG PLUS(7.48%), 한신기계(7.43%)가 뒤를 이었다. 코스닥시장에서는 바이오스마트(9.34%), 지투파워(9.21%), 에스와이스틸텍(8.74%) 순으로 집계됐다.증권업계 관계자는 “조정장이 시작되면 신용융자 잔액이 매물 폭탄으로 바뀔 수 있다”며 “증시 전반의 낙폭을 키울 가능성이 있다”고 말했다.', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005255882', 'https://imgnews.pstatic.net/image/015/2026/02/26/0005255882_001_20260227010913167.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-02-26 17:07:11', 0, true, '2026-03-09 06:16:46.988064') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (990, '[KPX그룹 옥상옥]③ 개인 아닌 법인 통한 지배력 강화 왜', '/사진=KPX홀딩스 홈페이지 갈무리, 이미지 제작=이채연 기자KPX그룹 계열사인 씨케이엔터프라이즈의 존재감은 양준영 현 회장으로의 승계 작업과 긴밀히 맞닿아 있다는 분석이다. 선대 회장인 부친으로부터 증여로 지분을 넘겨받는 일반적인 방식 대신 양 회장 개인 소유의 법인을 통해 지주사 지분율을 늘려왔다는 점에서다.직접 증여에 따른 막대한 세금 부담을 줄이면서도 실질적인 지배력은 그대로 유지할 수 있는 꼼수를 택한 셈이란 지적이 나온다.25일 금융감독원 전자공시시스템에 따르면 씨케이엔터프라이즈의 KPX홀딩스 지분율은 지난해 3분기 말 기준 28.89%로, 2017년 말 10.39%에서 18.5%p 확대됐다. 2017년은 씨케이엔터프라이즈가 KPX홀딩스 감사보고서에 주주로 처음 등장한 시점이다.그런데 씨케이엔터프라이즈는 양 회장의 개인 회사다. 양 회장은 씨케이엔터프라이즈의 주식 40만3221주 모두를 들고 있는 지분율 100%의 최대주주다.씨케이엔터프라이즈의 몫을 더해 KPX홀딩스에 대한 양 회장의 실질 지배력은 5분의2를 웃도는 수준까지 올라섰다. 양 회장 개인으로도 KPX홀딩스 지분을 들고 있어서다. 양 회장의 KPX홀딩스 지분율은 12.19%로 씨케이엔터프라이즈 지분율과 합산하면 41.08%다.그 사이 양 회장의 아버지인 양규모 전 회장은 지분을 모두 정리했다. 양 전 회장이 마지막으로 갖고 있던 1%대의 KPX홀딩스 지분마저 팔아 치우면서다. 양 전 회장은 지난해 4월 보유하고 있던 KPX홀딩스 지분 1.04%를 블록딜(시간 외 대량매매) 방식으로 매각했다. 이로써 2017년 말 19.64%에 달했던 양 전 회장의 KPX홀딩스 지분율은 이제 완전히 0%가 됐다.KPX홀딩스 지분율 변화 /자료=금감원, 그래픽=이채연 기자결과적으로 기존 지주사인 KPX홀딩스 위에 씨케이엔터프라이즈라는 양 회장의 개인 회사가 올라선, 이른바 옥상옥 형태가 완성됐다. 부동산 임대업·도매업을 주요 사업으로 하는 씨케이엔터프라이즈가 KPX홀딩스의 단일 최대주주로 등극하면서 KPX케미칼·KPX개발·KPX글로벌은 물론 진양화학·진양산업·진양폴리우레탄 등을 계열사로 가진 진양홀딩스까지 거느리는 지배구조의 정점에 서게 됐다.이를 두고 일각에서는 증여세 회피를 위한 방편이란 비판도 나온다. 양 전 회장의 주식을 아들인 양 회장에게 직접 증여하는 대신 아들의 개인 회사를 최대주주로 만들었기 때문이다.만약 양 회장이 아버지부터 개인 자격으로 약 20%p의 지분을 직접 넘겨받았다면 세금 부담은 상당했을 수밖에 없다. 코스피 시장 상장사인 KPX홀딩스의 지분 20%의 가치는 전 거래일 종가인 8만7400원 기준 738억원이다.학계에서는 우회적 지배력 확대 방식이라는 지적이 나온다. 이창민 한양대학교 경영학과 교수는 "지주사 지분을 총수 일가가 직접 취득하는 게 아니라 개인 회사를 통해 간접적으로 취득하는 구조"라며 "세금 부담을 고려한 일종의 우회 수단으로 볼 수 있다"고 말했다.배당소득세 부담 구조의 차이도 짚었다. 그는 "총수가 지주사 지분을 직접 보유하면 배당소득세를 내야 하지만, 배당이 개인회사로 들어가면 여러 가지 방식으로 세금을 줄일 수도 있다"고 덧붙였다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000079879', 'https://imgnews.pstatic.net/image/293/2026/02/25/0000079879_001_20260225094109191.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-25 09:41:09', 0, true, '2026-03-09 06:16:54.780803') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (991, '진양산업, 작년 순익 68억…전년 대비 32.5% 감소', '진양산업은 연결 기준 지난해 영업이익이 67억7679만원으로 전년 대비 32.5% 감소한 것으로 잠정 집계됐다고 26일 공시했다.같은 기간 매출은 918억원으로 4.0% 늘었다. 영업이익은 84억원으로 3.0% 증가했다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000078368', 'https://imgnews.pstatic.net/image/293/2026/01/26/0000078368_001_20260126112706388.png?type=w800', 'NEWS_ETC', NULL, '2026-01-26 11:27:06', 0, true, '2026-03-09 06:16:54.780803') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (992, '진양산업, 지난해 영업익 84억…전년비 3% ↑', '[헤럴드경제=증권부] 진양산업은 지난해 연결기준 영업이익이 84억4429만원으로 전년대비 3% 증가했다고 26일 공시했다.같은 기간 매출액은 917억5881만원으로 4% 늘어난 것으로 나타났다.당기순이익은 67억7679만원으로 32.5% 감소한 것으로 집계됐다.', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002590879', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2026-01-26 10:52:14', 0, true, '2026-03-09 06:16:54.780803') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (993, '태광, 롯데홈쇼핑 공정위 신고…수수료 ''통행세'' 공방 격화', '태광그룹, 롯데홈쇼핑 지분 45% 가진 2대 주주내부거래 통해 롯데그룹 계열사 부당 지원 의혹롯데홈쇼핑, "일반적 거래 구조로 투명하게 관리" 반박[이데일리 김은비 기자] 태광그룹이 롯데홈쇼핑의 계열사 거래 행위에 대해 ‘통행세’ 의혹을 제기하며 공정거래위원회에 신고했다. 롯데홈쇼핑은 이를 전면 부인하며 반발하고 나섰다. 공정위가 어떤 결론을 낼지 주목된다.6일 업계에 따르면 태광그룹은 최근 롯데홈쇼핑이 내부거래를 통해 롯데그룹 계열사를 부당 지원했다며 공정위에 신고서를 제출했다. 공정위는 신고 접수 후 15일 이내에 조사 착수 여부를 결정하게 된다.태광그룹은 태광산업, 대한화섬, 티시스 등의 계열사들을 통해 롯데홈쇼핑의 지분 45%를 보유하고 있는 2대 주주다. 태광산업은 롯데홈쇼핑과 납품업체의 직거래가 가능한 상황에서도 롯데쇼핑(롯데백화점)이 중간에 끼어 유통 마진을 수취하고 있다는 입장이다.태광 측은 롯데홈쇼핑이 사실상 최대주주인 롯데쇼핑을 수수료 형태로 지원하는 구조가 19년간 지속돼 왔다고 주장한다. 롯데쇼핑이 롯데백화점 등에서 보유한 상품을 롯데홈쇼핑 온라인몰에서 판매하면, 롯데홈쇼핑은 제휴 수수료를 롯데쇼핑에 지급하는 동시에 판매 수수료도 롯데쇼핑으로부터 받는 구조라는 설명이다.태광 측은 또 납품업체 상품이 롯데쇼핑을 거쳐 롯데홈쇼핑에서 판매되면서 납품업체가 부담하는 실질 수수료율도 업계 평균을 크게 웃돈다고 지적했다.공정위 실태조사에 따르면 TV홈쇼핑 업계 평균 실질 수수료율(2024년 기준)은 27% 수준이다. 반면 롯데홈쇼핑이 롯데쇼핑을 통해 납품받은 상품의 경우 수수료를 양사가 절반씩 나눠 갖는 구조여서, 업계 평균보다 높은 수수료율이 적용되고 있다는 것이 태광 측 주장이다.이에 대해 롯데홈쇼핑은 롯데쇼핑과의 거래는 투명하고 공정하게 운영하고 있다는 입장이다.롯데홈쇼핑은 우수한 상품과 파트너사를 유치하는 과정에서 고객 선호도가 높은 백화점 상품 판매를 시작했다고 설명했다. 또 백화점 판매 수수료는 롯데홈쇼핑과 백화점이 절반씩 나눈 뒤, 백화점이 해당 수수료를 다시 파트너사와 분배하는 구조라고 밝혔다.이는 다른 온라인몰의 백화점 상품관도 동일한 구조로 운영되고 있어 납품업체가 과도한 수수료를 부담한다는 지적은 사실이 아니라는 주장이다. 상품 판매 역시 사전에 마련된 내부 기준에 따라 운영되고 있어 주주 등 특정 기업의 요구나 압력에 의해 좌우될 수 있는 구조도 아니라고 덧붙였다.롯데홈쇼핑 관계자는 “롯데백화점 상품 거래는 지난 19년간 동일한 구조로 운영돼 왔다”며 “그동안 태광 측 이사들도 매년 관련 안건에 동의해왔는데 이제와 문제를 삼는 것은 납득하기 어렵다”고 맞섰다.그러면서 “주주사의 정상적인 문제제기에 대해서는 겸허히 수용하고 개선하고 있지만, 회사의 이익과 반하는 터무니 없는 주장이나 문제제기에 대해서는 강경하게 대응할 계획”이라고 말했다.(사진=이데일리 DB)', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006229731', 'https://imgnews.pstatic.net/image/018/2026/03/06/0006229731_001_20260306132111585.jpg?type=w800', 'NEWS_CHEM', NULL, '2026-03-06 13:21:11', 0, true, '2026-03-09 06:17:04.605704') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (994, '태광산업, 롯데홈쇼핑 ''계열사 부당지원 의혹'' 공정위 신고', '중간 유통 구조 ‘통행세’ 문제 제기실질 수수료율 업계 평균 상회 지적태광산업 본사 전경. ⓒ태광산업[데일리안 = 백서원 기자] 태광그룹이 롯데홈쇼핑의 내부거래를 문제 삼으며 공정거래위원회에 신고했다. 롯데쇼핑이 중간 유통 구조를 통해 ‘통행세’를 가져가며 계열사를 부당 지원했고, 이는 공정거래법상 불공정행위에 해당한다는 주장이다.5일 업계에 따르면 태광산업(법인명 우리홈쇼핑)은 최근 롯데홈쇼핑이 내부거래를 통해 롯데그룹 계열사를 부당 지원했다며 공정위에 신고서를 제출했다태광그룹은 태광산업·대한화섬·티시스 등을 통해 롯데홈쇼핑 지분 45%를 보유한 2대 주주다. 태광 측은 롯데홈쇼핑이 납품업체와 직거래가 가능한 상황에서도 롯데쇼핑(롯데백화점)이 중간에 개입해 유통 마진을 가져가는 구조라고 주장한다.롯데쇼핑이 롯데백화점 등에서 보유한 상품을 롯데홈쇼핑 온라인몰에서 판매하면 롯데홈쇼핑은 롯데쇼핑으로부터 판매수수료를 받는 동시에 제휴수수료를 지급한다. 또 롯데홈쇼핑은 롯데백화점 등에 입점한 매장 임차인에게도 임차수수료를 지급하고 있다.이에 대해 태광 측은 사실상 롯데홈쇼핑이 최대주주인 롯데쇼핑을 수수료 형태로 지원하는 방식이며, 2006년 롯데쇼핑의 우리홈쇼핑 인수 이후 약 19년간 이어져 왔다고 주장했다.또 납품업체 상품이 롯데쇼핑을 거쳐 롯데홈쇼핑에서 판매되는 과정에서 실질 수수료율이 업계 평균보다 높다고 지적했다. 공정위 실태조사에 따르면 2024년 TV홈쇼핑 업계 평균 실질 수수료율은 약 27% 수준이다. 태광 측은 롯데홈쇼핑과 롯데쇼핑이 수수료를 절반씩 나눠 갖는 구조여서 실제 부담률이 더 높다고 주장했다.이와 관련 롯데홈쇼핑은 지난해 12월 롯데쇼핑 등 계열사와의 내부거래 한도를 확대하는 안건을 이사회에 올렸지만 태광 측 이사들의 반대로 부결된 것으로 알려졌다. 해당 안건은 내부거래 규모를 기존 291억원에서 670억원으로 늘리는 내용이었다. 현재 롯데홈쇼핑 이사회는 롯데 측 5명, 태광 측 4명으로 구성돼 있으며 해당 안건은 특별결의 사항으로 3분의 2 이상의 동의가 필요하다.반면 이 같은 주장에 대해 롯데홈쇼핑은 태광 측의 주장을 전면 부인했다.롯데홈쇼핑 관계자는 “롯데홈쇼핑이 온라인에서 상품을 취급하는 것은 타사에서 운영 중인 온라인 백화점몰과 동일한 구조”라며 “관계사와의 거래이기에 더욱 공정하고 투명하게 운영 중”이라고 강조했다.수수료 부담 논란에 대해서도 “백화점 판매 수수료는 롯데홈쇼핑과 백화점이 약 5대 5 비율로 나누고, 백화점은 해당 수수료를 다시 파트너사와 분배하는 방식”이라며 “납품업체가 과도한 수수료를 부담한다는 태광 측 주장은 사실과 다르며, 직매입 상품은 일반 판매 수수료 방식보다 수수료율이 높은 구조”라고 반박했다.또 “롯데백화점 상품 거래는 지난 19년간 동일한 구조로 운영돼 왔고 그동안 태광 측 이사들도 관련 안건에 동의해 왔다”며 “갑자기 문제를 삼는 것은 납득하기 어렵다”고 밝혔다.아울러 롯데홈쇼핑 측은 “주주사의 정상적인 문제 제기는 수용하고 개선하고 있으나 회사의 이익에 반하는 근거 없는 주장에 대해서는 강경 대응할 계획”이라고 말했다.', NULL, '데일리안', 'https://n.news.naver.com/mnews/article/119/0003065806', 'https://imgnews.pstatic.net/image/119/2026/03/05/0003065806_001_20260305170112021.jpg?type=w800', 'NEWS_CHEM', NULL, '2026-03-05 15:56:16', 0, true, '2026-03-09 06:17:04.605704') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1131, '자사주 소각 의무화 전 EB 막차 발행…고민 깊어지는 지주사', 'KCC, 9.9% EB 발행 활용 계획에 주가 11.75% 급락9월 코스피 상장사 10곳 자사주 활용 EB 발행 공시''자사주 소각 의무화'' 李 공약, 연내 처리 전망대기업집단 지주사 30곳 중 처리계획 확정 8곳뿐“소각·처분·종류주 발행·임직원 보상 조합할듯”[이데일리 원다연 기자] 자사주 소각 의무화를 담은 ‘3차 상법 개정안’의 국회 통과를 앞두고 자사주를 활용한 교환사채(EB) 발행에 나서는 기업 사례가 잇따르고 있다. 자사주를 소각해 주주가치를 높여야 한다는 시장 요구에 역행한다는 지적에도 자사주 소각 제도화 전 막차를 타려는 기업들의 움직임이 바빠지고 있다.[이데일리 이미나 기자]24일 한국거래소에 따르면 이날 KCC 주가는 전 거래일 대비 11.75% 급락했다. 이는 이날 KCC가 자사주를 EB 발행에 활용한다는 계획을 공시한데 따라 시장에서 실망 매물이 쏟아진 영향이다. KCC는 이날 개장 전 ‘자기주식 활용 계획 안내’ 공시를 통해 총 발행주식의 9.9%에 해당하는 88만 2300주를 4분기 내 교환사채 발행에 활용한다고 밝혔다.EB는 기업이 보유하고 있는 자사주 또는 타사 주식을 기초자산으로 발행되며, 투자자가 채권 만기 전에 교환권을 행사하면 채권의 원리금 대신 해당 주식으로 교환받을 수 있는 권리가 붙어 있는 채권을 말한다. 투자자는 교환 대상 주식의 가격이 오르면 만기 전 교환권을 행사 추가 수익을 기대할 수 있지만, 기존 주주 입장에서는 교환권 행사로 자사주가 시장에 다시 유통되면 주주가치가 희석되게 된다. 유통주식 수를 줄여 주당가치와 주당이익(EPS) 증가로 이어져 기존 주주에게 직접 이익이 되는 자사주 소각과 정반대의 영향이 미치는 것이다.정부와 여당이 회사가 보유한 자사주를 의무적으로 소각하게 하는 내용의 상법 개정을 추진하면서 자사주 소각이 제도화되기 전 이를 활용하려는 막차 수요가 잇따르고 있는 셈이다. 이달 들어서만도 코스피 상장사 중에서만도 INVENI(015360), 쿠쿠홀딩스(192400), 넥센(005720) 등 10곳이 자사주를 교환대상으로 하는 EB 발행을 공시한 것으로 집계됐다.자사주가 본래 주주환원 취지에 맞게 쓰일 수 있도록 자사주 소각을 의무화하겠다는 건 이재명 대통령의 대선 공약이다. 현재 국회에는 자사주 소각을 의무화하는 내용의 법안이 다섯개 발의돼 있다. 각 법안별로 소각 시한과 예외 인정 범위, 승인 절차 등에는 차이가 있지만 신규 취득분뿐 아니라 기존 보유분까지 소각하도록 한다는 데에는 모두 동일한 원칙을 갖고 있다. 이경연 대신증권 연구원은 “1·2차 상법 개정을 통해 일반주주 권익 강화 관련 공약이 이행된 만큼 앞으로는 자본·손익거래 등을 악용한 지배주주 사익편취 행위 근절을 위한 공약 이행 차례”라며 “이 가운데 자사주에 대한 원칙적 소각 제도화 검토가 먼저 진행될 예정”이라고 밝혔다.특히 자사주 소각 제도화될 경우 보다 직접적인 영향을 받는 지주사들의 대응에도 이목이 쏠린다. KB증권에 따르면 이재명 정부 출범 이후 대규모기업집단 내 30개 지주회사 가운데 자사주 처리 계획을 확정한 곳은 롯데지주(004990), 티와이홀딩스(363280), LS(006260), 하림지주(003380), 아모레퍼시픽(090430)그룹, HL홀딩스(060980), LG(003550), 삼양홀딩스(000070) 등 8곳에 불과해서다. 이 가운데 티와이홀딩스, LS, 삼양홀딩스, LG, HL홀딩스가 자사주를 소각하겠다고 밝혔고, 나머지 3곳은 자사주를 제3의 투자자에게 매각하거나 교환사채 발행에 나섰다.아직까지 자사주 처리 계획을 밝히지 않은 지주사의 경우 3차 상법 개정안 처리 여부에 따라 자사주를 소각하거나 제3자에게 처분 또는 임직원 보상에 활용, 교환사채 등의 종류주식 발행 등의 방안을 병행하는 방식을 선택하게 될 것이란 전망이다. 박건영 KB증권 연구원은 “지주사는 지분 구조와 재무 상황에 따라 네가지 옵션을 조합해 활용할 것”이라고 전망했다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006124359', 'https://imgnews.pstatic.net/image/018/2025/09/24/0006124359_001_20250924185618364.jpg?type=w800', 'NEWS_AUTO', NULL, '2025-09-24 18:52:15', 0, true, '2026-03-09 06:24:11.522197') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1132, '"지주 밸류업 먼저"…후순위로 밀린 iM증권 완전자회사 편입', 'iM증권, 금융지주 계열 중 완전자회사 아닌 유일한 비상장iM금융지주, 2025년 내 "완전자회사 관련 결정" 밝혔지만주식교환 대신 ''자사주'' 소각…"지주사 밸류업 우선 먼저"iM금융지주가 자회사인iM증권완전자회사 편입을 후순위로 미루면서 내년 이후로 기약 없이 연기될 전망이다. iM금융지주는 자사주를 iM증권 완전자회사 전환에 활용할 수 있다고 언급해왔지만, 올초 ''주주가치 제고''를 이유로 소각했다.iM금융지주 관계자는 지난 9일 "iM증권의 완전자회사 편입과 관련해 현재 논의되고 있는 사항은 없다"고 밝혔다. iM증권은 iM금융지주가 지분 87.88%를 보유한 비상장사다.10대 금융지주 계열 증권사 가운데 완전자회사가 아닌 비상장 증권사는 iM증권이 유일하다. NH투자증권도 농협금융지주의 완전자회사는 아니지만 코스피 상장사이며, 농협금융지주의 지분율도 상대적으로 낮다. 그 외 신한·KB금융·하나금융·BNK금융·메리츠금융·한국투자금융, 우리금융지주(우리투자증권 지분 99.43%) 등 7곳은 증권사를 완전자회사로 두고 있으며, JB금융은 계열 증권사가 없다.iM증권의 전신은 제일투자신탁으로, 1989년 부산상공회의소 주도로 설립됐다. 당시 부산·경남 지역 상공인 7만여명을 대상으로 공모를 진행해 소액주주가 대거 유입됐다. 금융감독원 전자공시시스템에 따르면 1999년 사업보고서 기준 소액주주 비율은 59.48%에 달했다. 이후 수차례 유상증자 등을 거쳐 현재 지분율 구도(iM금융지주 87.88%, 소액주주 12.08%, 우리사주조합 0.10%)가 형성됐다. 이 기간 대주주는 흥아타이어(현 넥센)→제일제당(현 CJ)→현대중공업(현 HD현대)을 거쳐 DGB금융지주(현 iM금융지주)로 손바뀜이 있었다.iM증권 주주토론방에서는 그동안 완전자회사화를 기다려온 분위기다. 모회사 iM금융지주와의 주식교환이 유일한 엑시트(투자회수) 수단이라는 판단 때문이다. 금융투자협회 비상장주식 장외거래 플랫폼(K-OTC)에 따르면 iM증권 주가는 2014년 8월 평균 598원에서 2022년 8월 1161원까지 올랐다가 올해 8월 기준으로 865원까지 하락했다. 유상증자 발행가액도 낮아졌다. 2008년 12월 발행가는 주당 2450원이었으나 2010년 2250원, 2015년 2000원, 2020년 1600원으로 내려갔다.이 같은 분위기가 이어진 가운데 지주 차원에서도 iM증권 완전자회사화 방안을 검토한다는 최근 발표가 이어졌다. 천병규 iM금융지주 CFO(최고재무책임자)는 지난해 2월 실적 컨퍼런스콜에서 "자사주 매입은 기본적으로 소각하겠다고 생각하고 접근하는 것이지만, 계열사 완전자회사를 위해 주식교환을 할 가능성도 있다"고 밝혔다.이어 지난해 10월에는 "2023년 200억원 규모의 자사주 매입할 때는 이를 다양하게 쓸 수 있는 상황이었다"며 "내년 혹은 내년 하반기까지 완전 자회사와 관련해 처리할 부분을 결정해야 한다"고 언급했다.통상 지주사가 자회사를 완전자회사로 편입할 때 주식교환을 활용한다. 지주사는 자회사 소수주주들로부터 주식을 모두 넘겨받는 대신 이들에게 지주사 신주나 자사주를 지급한다. 다시 말해 iM금융지주는 2023년 200억원 규모의 자사주를 매입했는데, 이를 활용해 iM증권 완전자회사화 여부를 2025년 하반기 내 결정하겠다는 의지를 드러낸 셈이다.그러나 iM금융지주가 해당 자사주를 지난 2월 소각해버리면서 연내 iM증권 완전자회사화는 멀어진 것으로 보인다. 지난해 10월 iM금융지주가 ''2027년까지 총 1500억 원 규모의 자사주 매입·소각''을 골자로 한 기업가치 제고 계획을 발표하면서, iM증권 완전자회사 편입이 밸류업 정책에 우선순위가 밀린 셈이다.iM금융지주가 비상장 계열사인 iM증권 지분을 90% 가까이 보유한 상황에서 소수주주 환금성 제고 노력을 하지 않는 것은 무책임하다는 지적이 나온다.이와관련 iM금융지주 관계자는 "2023년 매입한 200억원 규모의 자사주에 대해 자사주 소각, iM증권 잔여 주식 인수 등 다양한 옵션을 검토하면서 추후 주주가치 극대화에 도움이 되는 방향으로 의사결정을 하겠다고 소통했다"면서도 "이미 취득한 자사주는 소각을 통한 기업가치 제고가 더 적절하다고 판단해 소각했다"고 밝혔다.', NULL, '비즈워치', 'https://n.news.naver.com/mnews/article/648/0000039725', 'https://imgnews.pstatic.net/image/648/2025/09/11/0000039725_001_20250911093010078.jpg?type=w800', 'NEWS_AUTO', NULL, '2025-09-11 09:30:10', 0, true, '2026-03-09 06:24:11.522197') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (995, '보령, 中 혈액암 신약 ‘엑스포비오’ 라이선스 인 계약 체결', '국내 판권·유통권·허가권 등 권리 확보혈액암 신약 ‘엑스포비오’. [사진=보령]보령이 중국 제약사인 안텐진과 혈액암 신약 ‘엑스포비오’ 라이선스 인 계약을 체결했다고 4일 밝혔다.이번 계약에 따라 보령은 엑스포비오에 대한 국내 판권·유통권·허가권 등 독점적 권리를 확보하게 됐다. 지난 2월부터 국내 공급을 시작했다.엑스포비오는 안텐진에서 개발한 다발골수종·미만성 거대 B세포 림프종 치료제다. 새로운 작용 기전을 가진 세계 최초의 ‘선택적 XPO1(핵 외 반출 단백질)’ 억제제다. 핵 외 반출 단백질의 작용을 억제하면 종양 억제 단백질과 성장 조절 단백질이 세포핵 밖으로 빠져 나가지 못하고 핵 내에 축적 및 활성화되어 암세포의 사멸을 유도한다.다발골수종은 치료가 거듭될수록 기존 약제에 불응하는 재발 환자가 많아 다른 작용 기전의 약제가 필요한 암종이다. 보령 측은 “엑스포비오는 기존 치료제와 다른 새로운 작용 기전 때문에 치료 선택지가 제한된 재발·불응성 다발골수종 환자의 추가 치료 옵션으로 주목 받는다. 주사제가 아닌 경구제형으로 개발돼 장기 치료 환자의 치료 편의성을 높였다”고 밝혔다.엑스포비오는 2019년 미국 식품의약국(FDA)와 2021년 유럽의약품청(EMA)으로부터 품목 허가를 승인 받았으며, 국내에서 2021년 승인을 받았다.엑스포비오는 ‘5차 이상 치료에서 덱사메타손 성분과의 병용요법’으로 급여 적용되어 있다. 지난 1일부터는 ‘2차 이상 치료에서 보르테조밉 및 덱사메타손과의 병용요법’도 급여 적용됐다. 초기 다발골수종 재발 환자에게 새로운 치료 옵션이 될 전망이다.보령은 엑스포비오 도입으로 혈액암 신약을 추가하며, 총 8종의 혈액암 치료제 포트폴리오를 구축하게 됐다. 보령은 혈액암 진단 초기부터 재발·불응 단계까지 치료 전 주기를 아우르는 솔루션 제공을 목표로 하고 있다.성백민 보령 BD&마케팅본부장은 “엑스포비오는 기존 치료 패러다임을 보완할 수 있는 새로운 기전의 경구 혈액암 신약”이라며, “혈액암 치료 전반을 아우르는 전문성을 바탕으로 환자와 의료진 모두에게 의미 있는 치료 옵션을 지속적으로 제공해 나갈 것”이라고 말했다.', NULL, '매일경제', 'https://n.news.naver.com/mnews/article/009/0005644994', 'https://imgnews.pstatic.net/image/009/2026/03/04/0005644994_001_20260304124817536.png?type=w800', 'NEWS_BIO', NULL, '2026-03-04 12:48:17', 0, true, '2026-03-09 06:17:12.663535') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (996, '보령, 혈액암 신약 ‘엑스포비오’ 라이선스 인 계약 체결', '국내 판권·유통권·허가권 등 독점적 권리 확보선택적 XPO1 억제 기반 신약, 이달부터 2차 이상 치료로 급여 확대보령은 중국 항암제 전문기업 안텐진과 혈액암 치료제 엑스포비오(성분명 셀리넥서)의 국내 라이선스 인 계약을 체결했다고 4일 밝혔다. 이번 계약으로 보령은 국내 판권과 유통권, 허가권 등 독점적 권리를 확보했다. 엑스포비오는 올해 2월부터 국내 공급을 시작했다.혈액암 신약 엑스포비오 제품 이미지. 보령엑스포비오는 선택적 XPO1 억제제다. 암세포에서 종양 억제 단백질을 세포핵 밖으로 내보내는 핵 외 반출 단백질(XPO1)을 차단해 종양 억제 단백질이 핵 내에 축적되도록 유도하는 기전이다. 이를 통해 암세포 사멸을 촉진한다.2019년 미국 식품의약국, 2021년 유럽의약품청에서 각각 허가를 받았다. 국내에서는 2021년 품목허가를 획득했다.적응증은 재발·불응성 다발골수종과 미만성 거대 B세포 림프종이다. 특히 다발골수종은 치료를 반복할수록 기존 약제에 내성이 생기는 사례가 많아 새로운 작용 기전의 치료제가 요구되는 영역이다. 엑스포비오는 경구 제형으로 개발돼 장기 치료 환자의 편의성을 높였다는 점도 특징이다.엑스포비오는 그동안 ''5차 이상 치료에서 덱사메타손 병용요법''에 한해 급여가 적용됐다. 이달 1일부터는 ''2차 이상 치료에서 보르테조밉 및 덱사메타손 병용요법''으로 급여 범위가 확대됐다. 재발 초기 단계 환자까지 적용 대상이 넓어진 셈이다.보령은 이번 도입으로 총 8종의 혈액암 치료제 포트폴리오를 갖추게 됐다. 회사 측은 혈액암 전담 조직을 중심으로 진단 초기부터 재발·불응 단계까지 치료 전 주기를 아우르는 전략을 강화하겠다는 계획이다.성백민 보령 BD·마케팅본부장은 "기존 치료 패러다임을 보완할 수 있는 새로운 기전의 경구 혈액암 치료제"라며 "의료진과 환자에게 의미 있는 선택지를 확대하겠다"고 밝혔다.', NULL, '아시아경제', 'https://n.news.naver.com/mnews/article/277/0005728985', 'https://imgnews.pstatic.net/image/277/2026/03/04/0005728985_001_20260304095617052.png?type=w800', 'NEWS_BIO', NULL, '2026-03-04 09:55:02', 0, true, '2026-03-09 06:17:12.663535') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (997, '샌드·초코 이어 ''말차''… 빙그레, 프리미엄 브랜드 ''왕실'' 라인업 강화', '이르면 내달 ''왕실말차'' 출시…왕실쿠키샌드·왕실초코 이어 세번째작년 남양유업·스타벅스 등 말차 음료 출시…시장 성장에 경쟁 고조빙그레가 지난해 출시한 ''왕실초코'' 제품 광고 이미지.(빙그레 제공)(서울=뉴스1) 황두현 기자 = 빙그레(005180)가 프리미엄 브랜드 ''왕실'' 시리즈의 세 번째 신제품 ''왕실말차''를 선보인다. 전 세계적인 말차 열풍에 식품업계 경쟁이 거세지는 양상이다.9일 업계에 따르면 빙그레는 내달 왕실말차를 출시를 앞두고 상표권 출원을 마쳤다. 전 세계적인 말차 트렌드를 반영해 유제품 라인업을 강화하는 것이다.왕실은 빙그레가 2024년 7월 아이스크림 ''왕실쿠키샌드''를 출시하며 선보인 브랜드다. 왕실쿠키샌드는 왕실 콘셉트를 내세우고 소비자가격 4000원을 책정해 프리미엄 제품으로 화제를 모았다.지난해 2월에는 초콜릿 드링크 ''왕실초코''를 출시하고 오프라인에서 왕이 행차하는 형태의 행사도 열었다. 두 제품 모두 포장지에 왕실 문양을 넣고 유제품 명가의 50년 기술력이 뒷받침됐다는 점을 강조했다.왕실말차의 구체적인 제품 형태와 유통·판매채널은 확정되지 않았다. 동일한 원재료를 두고 제품 판매 경쟁을 벌이는 식품업계 특성상 신제품 출시 직전까지 관련 정보는 대외비에 부쳐진다.유가공식품 시장 강자인 빙그레가 말차를 전면에 내세운 유제품을 내놓는 건 처음이다. 판매 중인 상품 중 말차가 함유된 건 아이스크림 ''쿠앤크 말차''가 유일하다.반면 타 식품업체들은 지난해 잇따라 말차 제품을 내놓고 시장 선점에 나섰다. 남양유업이 지난해 출시한 ''말차에몽''은 초기 라이브커머스 물량이 완판되는 등 인기를 얻었다. 스타벅스와 폴바셋, 공차 등 카페 브랜드도 말차 음료를 내놨다.시장 조사기관 포춘 비즈니스 인사이트에 따르면 전 세계 말차 시장 규모는 지난해 23억2000만 달러(3조 4092억 원)에서 2034년까지 45억7000만 달러(6조 7156억 원)로 성장할 것으로 예상된다.', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008813433', 'https://imgnews.pstatic.net/image/421/2026/03/09/0008813433_001_20260309064015258.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 06:40:00', 0, true, '2026-03-09 06:17:18.901718') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (998, '“이사 보수한도 부결될라” 잇단 셀프 삭감 [시그널]', '■남양유업 판결 여파에 선제 조정표결서 최대주주 의결권은 제외실지급률 맞춰 가결 안정성 높여티웨이 등 한도 절반 가량 낮춰이 기사는 2026년 3월 8일 17:43자본시장 나침반  ''시그널(Signal)''에 표출됐습니다.서울 여의도 증권가. 연합뉴스개정 상법 시행과 함께 ‘이사 보수 한도’도 올해 정기 주주총회 시즌의 뜨거운 감자로 부상했다. 이사들의 충실 의무 대상이 주주로 확대된 가운데 대법원에서 회사의 최대주주인 이사가 보수 한도를 스스로 승인하는 것이 위반이라는 판결을 내놓은 여파다. 이에 자발적으로 이사 보수 한도를 낮춰 부결 가능성을 줄이는 상장사들이 속속 등장했다.8일 한국거래소 기업공시채널 카인드(KIND)에 따르면티웨이항공(091810)·풀무원(017810)·한화갤러리아(452260)등은 올해 열리는 정기 주총에 이사 보수 최대 한도를 낮추는 안건을 상정했다. 구체적으로 티웨이항공은 지난해 최고 한도액 40억 원에서 올해 20억 원으로, 풀무원은 45억 원에서 30억 원으로, 한화갤러리아는 40억 원에서 30억 원으로 각각 내렸다.이는 지난해 ‘남양유업 판결’이 영향을 미친 것으로 해석된다. 지난해 대법원은 홍원식 전 남양유업 회장이 2023년 주총에서 의결권을 행사해 이사 보수 한도 안건을 통과시킨 것이 위법이라는 판결을 내렸다. 따라서 이사인 주주는 보수 한도 승인 안건의 특별이해관계인으로 의결권을 행사할 수 없다는 점이 명확해졌고 회사의 최대주주나 특수관계인 중 이사가 포함된 경우 그 지분을 표결에서 제외해야 한다.이 경우 국민연금 등 기관투자가가 이사 보수 안건에서 캐스팅보트를 쥘 수밖에 없기 때문에 지급률 차이에 의한 부결을 방지하기 위해 자발적으로 보수 한도를 내리는 것으로 풀이된다. 실제 지난해 티웨이항공의 실제 이사 보수 지급 총액은 25억 3000만 원으로 지급률 63.25%를 기록했다. 풀무원과 한화갤러리아는 각각 29억 6400만 원(65.87%), 9억 9900만 원(24.98%)으로 나타났다. 문성 법무법인 율촌 변호사는 “기업들은 보수 한도 안건의 가결 안정성을 높이기 위해 실제 예상 지급 수준에 맞춰 비교적 보수적으로 한도를 설정하는 경향이 나타나고 있다”고 설명했다.아울러 이사 보수 안건 승인 여부에서 소액주주들의 역할이 중요해지고 있다는 분석도 지배적이다. 해당 안건의 승인을 위해서는 총 발행주식 수의 4분의 1 출석 그리고 출석 주주의 의결권 과반수 찬성이라는 요건을 충족시켜야 한다. 이 가운데 최대주주의 지분을 제외하게 된다면 안건 표결을 위한 출석 기준부터 맞추기 어려워질 수 있다. 이로 인해 소액주주들의 주총 참여도를 높이는 것이 새로운 과제로 부상하고 있다는 진단이다.이런 문제를 해소하기 위해 이사별로 보수 한도 안건을 나눠서 상정하는 방법이 해결책으로 제시되고 있다. 최대주주가 스스로 보수 한도를 승인할 수 없지만 다른 이사들에 대해서는 표결을 할 수 있다는 해석 때문이다. 김춘 한국상장회사협의회 정책1본부장은 “이사 보수 한도를 하나의 안건으로 올린다면 이사인 최대주주가 의결권이 없지만 이사별로 나눈다면 표결할 수 있다”며 “부결 가능성에 따라 나머지 이사들이 보수를 받을 수 있는 조치로 제안하고 있다”고 말했다.', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004596953', 'https://imgnews.pstatic.net/image/011/2026/03/08/0004596953_001_20260308233305882.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-08 20:24:13', 0, true, '2026-03-09 06:17:18.901718') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (999, '“경영권 방파제 쌓을 마지막 기회”…이사 수 줄이고 퇴임시점 분산 [시그널]', '[상법 개정發 주총전쟁]<상> 이사회 수성 총력전오뚜기 등 이사회 정원 축소분리선출 확대 전 임기 다변화우호적 감사위원도 선제 확보거버넌스 개편…불확실성 줄여이 기사는 2026년 3월 8일 17:16자본시장 나침반  ''시그널(Signal)''에 표출됐습니다.상장사가 밀집한 서울 강남구 테헤란로 전경. 연합뉴스3월 정기 주주총회가 향후 기업 거버넌스(지배구조)에 중요한 분기점으로 지목되는 것은 올해 7월 이후로는 개정 상법이 본격적으로 시행되기 때문이다. 즉 내년 정기 주총부터는 최대주주의 의결권을 제한하는 ‘합산 3%룰’과 분리 선출 감사위원 확대, 집중투표제 등이 적용돼 최대주주의 영향력이 약화되는 게 불가피하다. 이 때문에 기업들은 이사회와 감사위원회를 선제적으로 재편하는 등 진입장벽을 최대한 높여 경영권 견제를 최소화하고 소수주주와의 분쟁 가능성을 차단하겠다는 구상이다.8일 투자은행(IB) 업계와 산업계에 따르면 한화갤러리아는 이달 26일 정기 주총에서 이사회 정원을 기존 13명에서 7명으로 줄이는 정관 변경 안건을 처리할 예정이다. 기존 이사회 정원이 9명인 오뚜기는 이를 7명으로 줄이는 안건을 상정했다. 법조계에서는 이사회 정원 감축을 집중투표제 영향을 최소화하기 위한 조치로 보고 있다. 올해 9월 10일부터 시행되는 집중투표제는 주식 1주당 선임할 이사의 수만큼 의결권을 부여하는 제도로, 한 번에 선임하는 이사의 수가 많을수록 소수주주에게 유리해진다. 이 때문에 이사 수 상한을 설정해 대응하려는 기업들도 많다.원혜수 법무법인 광장 변호사는 “정관상 이사의 총수에 제한을 두지 않는 경우 소수주주가 상법상 주주 제안권을 활용해 다수의 이사 선임 안건을 상정하고 여러 명의 이사를 동시에 선출하도록 하는 상황에 효과적으로 대응하기 어려울 수 있다”고 말했다. 한화갤러리아 측은 “한화솔루션 합병 당시 회사 규모에 따라 이사가 늘었다가, 분할되면서 줄어드는 상황을 반영하는 것”이라고 설명했다.이사의 임기를 축소하거나 다변화하는 식으로 이사 임기 구조를 재설계하는 안건도 비슷한 맥락에 있다. 삼성SDS는 이번 주총을 앞두고 이사 임기를 기존 3년에서 ‘3년 이내’로 축소하는 안건을 올렸다. 한화에어로스페이스는 현재 ‘2년 내’로 명시된 이사 임기를 ‘3년 혹은 3년 내’로 다변화할 예정이다. 이사의 임기가 집중돼 있으면 임기 만료 시점에 이사회 공석이 한 번에 여럿 발생하면서 소수주주 등이 주총에서 제안·선임할 수 있는 이사 수가 늘어난다. 조완희 법무법인 디엘지 대표변호사는 “이사의 퇴임 시점을 분산시키는 것이 선임 이사 수를 줄이고 변수를 최소화하는 데 유리할 수 있다”며 “이사회 주도권을 지키는 것이 이번 주총 시즌을 앞둔 기업들의 가장 큰 고민거리”라고 말했다.지난해 상법 개정의 핵심은 이사의 충실 의무를 주주로 확대하는 내용과 이사회·감사위원회의 독립성 강화였다. 이 중 이사의 주주 충실 의무는 지난해 7월 개정 법안 공포와 동시에 시행됐다. 그 외에 상장사 이사회 내 독립이사 비율을 기존 4분의 1에서 3분의 1로 높이는 조항과 분리 선출 감사위원 확대 등은 각각 올해 7월과 9월에 시행돼 정기 주총에서 관련 정관 변경이나 안건을 의결하지 않으면 연중 임시 주총을 열어야 하는 상황이 발생할 수 있다. 이는 공포일과 시행일, 최초 적용 주총 사이에 시간차가 존재한 영향이다.보다 큰 변수는 내년 정기 주총부터 집중투표제를 비롯해 전자 주총을 도입해야 하고 감사위원 선임 시 최대주주 의결권이 추가로 제한되는 합산 3%룰의 제약을 받는다는 점이다. 최대주주와 그 특수관계인 등이 소유한 주식을 합산하지 않고 각각 3% 의결권을 행사할 수 있는 ‘개별 3%룰’과 달리 합산 3%룰에서는 모두 합해 3%까지밖에 행사하지 못한다. 이들 제도가 결합되면 최대주주 측 감사위원을 선임시킬 가능성은 줄어들고 소수주주나 행동주의 펀드 측의 이사회 진입 가능성은 대폭 커진다.즉 올 7월 전에 분리 선출 감사위원을 선임해야 최대주주 측의 의결권이 상대적으로 더 많게 되는 것이다. 이로 인해 이마트·롯데쇼핑 등도 이번 주총에서 신규 감사위원을 분리 선출할 계획이다. 배기완 법무법인 지평 파트너변호사(경영권분쟁대응센터장)는 “올해 정기 주총이 대주주가 최대한의 권한을 행사할 수 있는 마지막 기회”라며 “합산 3%룰 적용 시 우호 지분이 어떻게 산정되는지 확인해볼 필요가 있다”고 강조했다.일부 기업들에서는 미리 기업 사정에 밝은 전문가나 우호 인력을 감사위원으로 선임하려는 모습이 포착됐다. 현대백화점은 전임 유통학회장이자 차기 마케팅학회장인 정연승 단국대 경영학과 교수를 감사위원으로 선임할 계획이다. 한화갤러리아와 BGF리테일은 기존 사외이사로 회사 상황을 잘 파악하고 있는 송지혜 마녀공장 대표와 신현상 한양대 교수를 각각 감사위원에 선임할 예정이다.일부 전문가들은 주총을 앞둔 기업들의 이러한 움직임에 비판적인 의견을 내고 있다. 상법 개정의 취지는 이사회와 감사위원회의 독립성을 높이는 것인데 이를 역행한다는 이유에서다. 남양유업 상근감사 출신의 심혜섭 변호사는 “사회적 합의를 통해 법이 개정된 것인데 감사위원회 정원 확대나 이사 임기 분산 등은 개정 취지와는 맞지 않는 편법으로 보인다”고 지적했다. 이남우 한국기업거버넌스포럼 회장은 “기업들이 지배주주나 경영진에 반대하지 않는 이사를 찾는 데만 몰두하는 측면이 있다”며 “기업 수준을 높일 수 있는 이사회를 구축하는 것이 중요하다”고 했다.', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004596948', 'https://imgnews.pstatic.net/image/011/2026/03/08/0004596948_001_20260308234909458.jpeg?type=w800', 'NEWS_ETC', NULL, '2026-03-08 19:17:14', 0, true, '2026-03-09 06:17:18.901718') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1000, '중동 리스크까지 덮친 식품업계 ''속앓이''', '정부, 주요 식품업체에 가격 인하 압박 수위 높여업계 "밀가루 비중 10% 수준⋯인상해야 할 수도"가공식품 가격 정책을 두고 식품업계의 속앓이가 깊어지고 있다.밀가루·설탕 등 주요 원재료 가격 하락 이후 물가 안정에 동참하라는 정부의 압박이 점점 거세지는 상황이지만, 중동 사태 여파로 통상 환경의 불확실성이 커지며 되레 원가 부담이 심화하고 있기 때문이다. 가격을 올릴 수도, 내릴 수도 없는 진퇴양난에 빠진 셈이다.서울 시내의 한 대형마트 라면 판매대. [사진=연합뉴스]농림축산식품부는 5일 농심·오뚜기·삼양·팔도 등 라면 4사를 소집해 비공개 실무진 회의를 진행했다. 전날 CJ제일제당·사조대림·오뚜기·대상·동원F&B·롯데웰푸드 등 식용유 업체들과 만난 데 이어 라면 업체들까지 소환한 것이다. 향후 제과·제빵 등 다른 가공식품도 간담회를 열어 품목별 상황을 수시로 점검할 계획인 것으로 알려졌다.농식품부는 업종별로 시장 동향을 파악하기 위한 자리라고 설명했다. 다만 밀가루·설탕 가격 인하 후 정부와 식품 업체가 처음 만나는 자리인 만큼, 업체 입장에선 ''물가 안정'' 기조에 동참해 달라는 압박 신호로 받아들여질 수밖에 없다는 해석이 나온다.실제로 가격 담합 의혹 조사가 시작된 후 제분·제당업계가 선제적으로 공급가를 낮추기 시작하자, 정부는 이를 원재료로 사용하는 가공식품 가격도 낮아져야 한다는 메시지를 쏟아내기 시작했다. 주병기 공정거래위원장은 "밀가루와 설탕 가격이 하락한 만큼 가공식품 가격을 인하해야 한다"는 취지의 발언을 했고, 이재명 대통령은 밀가루·설탕 가격 인하를 언급하며 "설탕을 쓰는 상품이 가격을 그대로 유지해서 소비자는 혜택도 못 받고 공정위가 열심히 한 결과물을 업체들이 독식하게 하면 안 된다"고 지적했다.식품업계는 이러한 정부 기조에 보조를 맞추기 어려운 현실이라고 입을 모은다. 밀가루와 설탕 등이 주요 원재료인 건 사실이지만, 제조 원가에서 차지하는 비중은 생각보다 크지 않기 때문이다. 라면의 경우 많아야 10~20% 수준, 일부 과자 제품은 1% 미만에 불과하다. 반대로 물류·인건비 등 나머지 비용들은 여전히 상승하는 추세고, 고환율 부담이 지속되며 수입에 의존하는 원재료 부담 역시 증가세다.업계 관계자는 "정부가 어떠한 취지로 물가 안정을 요구하는지 공감은 하지만 상황이 너무 어렵다. 보폭을 맞추고 싶지만 현실적으로 힘든 상태"라며 "가격을 동결하기도 어려워 고민할 지경"이라고 토로했다.미국·이스라엘과 이란 간 군사 충돌이 중동 전반으로 확산되고 장기화할 조짐을 보이면서, 가격 인하가 아닌 인상을 고민해야 할 수도 있다는 전망도 나온다. 국제 유가·해상 운임·환율 등이 급등하며 수입에 의존하는 원재료 가격이 폭등할 수 있기 때문이다. 이 경우 정부 압박에 가격 인하를 고려하던 일부 업체들까지 전면 재검토에 들어갈 수밖에 없다.서용구 숙명여대 경영학과 교수는 "중동 사태 이후 정부의 가격 인하 압박이 유명무실해질 것 같다"며 "중동 사태로 국제 유가·환율이 상승하는 흐름이 되면서 오히려 가격 인상을 생각할 시점으로 전환됐다"고 설명했다.', NULL, '아이뉴스24', 'https://n.news.naver.com/mnews/article/031/0001010835', 'https://imgnews.pstatic.net/image/031/2026/03/06/0001010835_001_20260306063111176.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-06 06:31:11', 0, true, '2026-03-09 06:17:25.595182') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1001, '[조직 리와이어링]현대제철, ''美'' 중요성 부각 전담 조직 띄웠다', '현대제철 미국 전기로 제철소 모형 사진/사진=현대제철현대제철은 북미사업 확대에 대응하기 위해 ''북미철강사업부''를 운영 중인 것으로 확인됐다. 이 조직은 지난해 미국 전기로 제철소 투자 추진 이후 북미사업을 전담하기 위해 구축된 것으로 보인다.현대제철이 최근 공개한 조직도를 보면 8개 본부와 함께 동일 선상에 북미철강사업부가 배치돼 있다. 이는 2024년 말 기준 조직도와 비교했을 때 가장 눈에 띄는 변화다.기존에는 특정 해외 지역만 명문화해 조직화하지 않았다. 현대제철이 북미시장을 별도 사업부로 둔 것은 그만큼 해당 시장의 전략적 중요성이 커졌다는 점을보여준다.현대제철의 해외 거점 확대는 그동안 현대·기아차의 수출 전략과 맞물려 추진돼 왔다. 이는 현대차그룹 완성차 밸류체인에서 현대제철이 맡고 있는 역할과도 관련이 깊다. 현대제철은 현대·기아차에 자동차강판을 공급하는 핵심 공급망이다. 북미시장은 현대제철 내에서 내수 다음으로 매출 비중이 큰 핵심 소비 시장인데다 현대·기아차 입장에서도 판매량이 높은 곳으로 손꼽히는 지역이다.다만 미국의 보호무역 조치로 인해 시장 진입 장벽은 상당히 높아진 상태다. 이에 따라 현대차그룹 차원의 현지 생산 확대 검토가 이뤄졌고 북미 시장의 중요성이 커진 것도 이 같은 흐름과 무관하지 않다.아울러 현대제철은 현재 미국 현지 전기로 제철소 건설을 추진하고 있다. 북미철강사업부 역시 북미 투자 추진 과정에서 신설된 것으로 파악된다.올초 현대차그룹과 포스코가 공동 출자한 ''현대-포스코 루이지애나'' 법인이 설립되고 현대제철의 출자 규모도 정해지면서 현대차그룹과 주요 SI(전략적 투자자) 간 투자 비율 협상도 어느 정도 마무리된 것으로 보인다. 제련·제강·압연 등이 모두 한 곳에서 처리 가능한 일관제철소 형태로 지어지는 루이지애나 제철소가 완공되면 현지 완성차 업체에 연간 약 180만톤의 강판을 공급할 수 있다. 전기차와 하이브리드, 내연기관 등 다양한 차종 수요에 대응할 수 있다는 점도 강점으로 꼽힌다.올해 3분기 본격적인 착공에 들어갈 예정이어서 북미철강사업부의 역할도 한층 커질 전망이다. 사업부는 과거 공정연구센터장을 지낸 김형진 전무가 담당하고 있다. 루이지애나 제철소는 친환경 공정에서 자동차용 고부가 강제를 생산하는 핵심 인프라다. 김 전무는 공정 설계에 대한 이해도가 높은 기술 인력이라는 점에서 적임자라는 평가다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000080539', 'https://imgnews.pstatic.net/image/293/2026/03/09/0000080539_001_20260309150507656.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-03-09 15:05:07', 0, true, '2026-03-09 06:17:34.556429') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1002, '[M&A알쓸신잡]순환출자 끊는 日도요타…현대차 지배구조 개편 촉매될까', '도요타그룹, 자동직기 공개매수 엘리엇과 합의55조원 규모…일본 역대 최대 M&A상호·순환출자 해소와 창업일가 승계 포석국내 순환출자 기업 현대차그룹에 시사점5조9000억엔(약 55조원). 일본 도요타그룹이 계열사 도요타 자동직기를 비상장화하는 데 투입하기로 한 금액입니다. 일본 기업 대상 인수합병(M&A) 거래로는 역대 최대 규모입니다. 지난 2일 도요타그룹은 행동주의 펀드 엘리엇 매니지먼트와 공개매수 인수가액을 주당 2만600엔으로 최종 합의했습니다. 처음 제시한 주당 1만6300엔에서 9개월에 걸쳐 26%를 더 올린 건데요.9일 M&A알쓸신잡에선 도요타가 막대한 금액을 들여 자기 계열사를 사들인 이유와 이 거래가 국내 10대 그룹 중 유일하게 순환출자를 유지하고 있는 현대차그룹에 주는 시사점을 함께 짚어봤습니다.도요타의 55조원짜리 ''출자 고리'' 풀기도요타그룹은 일본 특유의 ''케이레츠(계열)'' 문화가 고스란히 남아 있는 곳입니다. 도요타 자동차, 자동직기, 덴소, 아이신정기 등 핵심 계열사들이 서로의 지분을 보유하며 상호출자와 순환출자 고리가 복잡하게 얽혀 있었습니다. 핵심은 그룹의 ''원조'' 기업인 자동직기입니다. 1926년 창업주 도요다 사키치가 설립한 방직기 제조회사가 출발점이고, 여기서 자동차 부문이 분리돼 지금의 도요타 자동차가 만들어졌습니다. 현재 사업은 방직기와는 거의 관련 없고, 세계 최대 지게차 제조업체로 거듭났습니다.문제는 이 구조가 그룹 결속력을 높이는 대신 외부의 경영권 위협에도 취약하다는 점입니다. 자동직기가 상장사로 남아 있으면 외부 투자자가 자동직기 지분을 사들여 간접적으로 도요타 자동차 경영권에 영향을 미칠 수 있기 때문입니다. 실제로 엘리엇이 자동직기 지분을 3.3%에서 7.1%까지 확대하며 인수가액 인상을 압박한 사례가 이를 잘 보여줍니다.도요타의 선택은 자동직기를 완전 자회사로 만든 뒤 상장폐지하는 것이었습니다. 비상장 계열사인 도요타 부동산 아래 신규 지주사와 특수목적회사(SPC)를 설립해 자동직기 지분 전량을 매입하고, 스퀴즈아웃(소수 주주 강제 매수)을 통해 상장을 폐지하는 3단계 구조입니다. 자동직기가 보유한 계열사 지분도 매각해 상호출자와 순환출자 고리를 끊겠다는 계획입니다."日 자본시장 내 행동주의 역할 확대 영향도"최태용 DS투자증권 연구원은 "이번 공개매수는 단순한 비상장화가 아니라 장기적으로 창업일가의 승계를 감안한 지배구조 개편의 시작점"이라고 분석했습니다. 도요타 자동차에 대한 창업일가 지분율이 최대 12% 내외에 불과해 지분 매입만으로는 충분한 지배력 확보가 어렵기 때문입니다. 실제로 도요타는 최근 아키오 회장의 장남 도요다 다이스케(38)가 우븐(Woven)의 수석부사장으로 재직 중이며, 신임 최고경영자(CEO) 켄타 콘과 함께 근무하고 있어 세대교체가 진행 중인 것으로 알려져 있죠.이번 거래에서 눈여겨볼 점은 행동주의 펀드 엘리엇의 역할입니다. 도요타그룹이 지난해 6월 공개매수를 처음 발표했을 때 인수가액은 4조7000억엔(주당 1만6300엔)으로 시가 대비 23% 프리미엄이었습니다. 그러나 지난해 11월 엘리엇이 일본 증시 평균 공개매수 프리미엄(40% 내외)에 못 미친다며 주당 2만6000엔을 요구하면서 교착 상태에 빠졌습니다.도요타는 올해 1월 5조4000억엔(프리미엄 41.9%)으로 올렸지만 엘리엇은 거절했고, 결국 이달 2일 5조9000억엔(프리미엄 55.4%)에 합의가 이뤄졌습니다. 일본 내 행동주의 펀드 캠페인 건수가 2018년 60건 내외에서 2024년 150건 가까이 급증한 흐름 속에서, 소수주주 권리가 실제 M&A 가격에 반영되는 사례로 기록될 전망입니다.현대차그룹의 ''두 번째 승계 설계도''는 언제도요타 사례가 국내에서 주목받는 이유는 현대차그룹과의 구조적 유사성 때문입니다. 현대차그룹은 국내 10대 그룹 중 유일하게 ''현대모비스→현대차→기아→현대모비스''로 이어지는 순환출자를 유지하고 있습니다. 2018년 현대모비스 인적분할과 현대글로비스 합병을 통한 지배구조 개편을 시도했지만, 합병 비율 논란과 투자자 반발로 두 달 만에 철회된 바 있습니다.DS투자증권은 현대차그룹 개편의 핵심 목표를 세 가지로 정리했습니다. 순환출자 해소, 정 회장 중심 지배력 강화, 현대모비스 중심 지배구조 구축입니다. 도요타 개편이 지배력 약화가 아니라 창업일가 지배력 강화를 목표로 설계됐다는 점에서 현대차그룹의 방향성과 일치합니다.정 회장이 순환출자 해소와 승계를 마무리하는 데 필요한 자금은 지난해 말 기준 약 5조8000억원으로 추산했습니다. 기아와 현대제철이 보유한 현대모비스 지분 매입에 약 3조원, 정몽구 명예회장 보유 계열사 지분의 승계 관련 자금까지 합산한 규모입니다.관건은 정 회장의 자금 조달 능력입니다. 2018년과 달라진 점은 그룹 핵심 계열사 기업가치가 크게 올랐다는 것입니다. 현대차 시가총액은 100조원을 돌파했고, 현대모비스·현대오토에버 등 핵심 계열사 가치도 동반 상승했습니다. 기업가치 상승은 곧 대주주의 보유 자산 가치 상승이자 지분 거래에 필요한 레버리지 확대를 의미합니다.여기에 비상장사인 미국 로봇 개발 기업 보스턴다이나믹스(BD)의 기업공개(IPO)가 새로운 변수로 부상하고 있습니다. 정 회장은 BD의 주요 주주로, IPO가 성사될 경우 구주매각을 통해 3조~4조원 규모의 추가 자금을 확보할 수 있다는 관측이 나옵니다. 현대글로비스 지분(약 23%) 역시 정 회장의 핵심 재원으로 꼽히죠.자본 배치의 차이가 만드는 지배구조 전환 차이다만 도요타와 현대차그룹 사이에는 결정적인 차이가 있습니다. 도요타는 내부 지분 정리에만 5조9000억엔 이상을 소진해야 합니다. 반면 현대차그룹은 지분 교환이나 모비스 인적분할 같은 방식으로 상대적으로 적은 자본으로 순환출자를 정리할 수 있다는 것이 증권가의 분석입니다.최 연구원은 "도요타는 막대한 자본을 내부 구조 정리에 써야 하지만, 현대차그룹은 그 자본을 미래 밸류체인에 집중할 수 있다"며 "기존 완성차 업체에서 ''피지컬 인공지능(AI)'' 플랫폼으로의 전환 속도 우위를 증명하는 핵심 논리"라고 설명했습니다.한편일본에서 순환출자를 유지하는 상장사 비중은 1990년대 30%를 넘었지만, 현재 10% 아래로 떨어졌습니다. 한국에서도 SK, LG, 삼성 등 대부분의 대기업이 순환출자를 해소한 가운데, 공정거래위원회의 해소 권고와 상법 개정에 따른 이사 충실의무 강화까지 맞물린 상황이죠. 도요타가 55조원짜리 ''큰 그림''을 꺼내든 지금, 현대차그룹의 ''두 번째 설계도''에도 시장의 관심이 쏠리는 배경입니다.', NULL, '아시아경제', 'https://n.news.naver.com/mnews/article/277/0005731024', 'https://imgnews.pstatic.net/image/277/2026/03/09/0005731024_001_20260309111220428.png?type=w800', 'NEWS_ENERGY', NULL, '2026-03-09 06:55:00', 0, true, '2026-03-09 06:17:34.556429') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1003, '중국 철강 재고 급증에 비상 걸린 韓철강… ‘저가 공세’ 반복될까 우려', '중국 철강 재고 열흘새 22% 급증부동산 침체·관세·감산 불가 여파국내 철강업체 “불공정 수입 확대되면 정부와 협력”올해 우리나라 철강산업이 바닥을 다지고 반등할 것이라는 기대가 흔들리고 있다. 중국의 철강 재고가 급격하게 늘어나면서 ‘밀어내기 수출’이 재현될 가능성이 커졌기 때문이다. 미국·유럽연합(EU), 남미 등의 관세 부과와 더불어 내수 침체가 심화된 여파로 풀이된다.9일 중국철강협회(CISA)와 철강전문 외신 등에 따르면 지난달 20일 기준 중국의 5대 철강재(열연, 냉연, 후판, 선재, 철근) 재고는 953만톤(t)으로 집계됐다. 이는 지난 10일(781만톤) 대비 22% 급증한 규모다.중국 랴오닝성 다롄의 한 창고에서 직원이 철강 선재 제품을 점검하고 있다./로이터연합뉴스중국철강협회 회원사인 대형 철강업체들이 보유 중인 완제품 재고도 1511만톤 수준이다. 현지에서는 재고 규모가 과도하다는 평가가 나오고 있다.중국 내 철강 재고가 쌓이고 있는 가장 큰 이유는 부동산 경기 침체로 인한 내수 부진이다. 재고 중 철근이 약 414만톤으로 전체의 43%를 차지한다. 열흘간 재고 증가율은 27.5%로, 5대 철강재 중 가장 컸다.중국 정부는 지난 30년간 부동산 개발, 인프라 투자를 고성장을 위한 발판으로 삼았다. 그 결과 중국 국내총생산(GDP)의 25%를 건설 부동산이 차지하고 있다.그러나 3~4년 전부터 비구이위안, 완다 등 부동산 기업들이 디폴트(채무불이행)에 빠졌고, 최대 건설기업인 완커도 유동성 위기를 맞았다. 중국 내 미분양과 공실 주택은 약 8000만 가구로 추산된다.국제 신용평가사 스탠더드앤드푸어스(S&P)는 “올해 중국 내 신규 주택 판매량이 지난해보다 최대 14% 줄어들 것”이라면서 “중국 정부의 각종 부양책에도 공급 과잉과 수요 침체가 맞물리며 시장 회복이 늦어지고 있다”고 했다.중국을 겨냥한 글로벌 관세의 여파도 재고 급증의 원인이다. 미국은 중국산 철강에 대해 평균 24~37%의 실질 관세를 유지하고 있다. 유럽은 올해부터 ‘탄소국경조정제도(CBAM)’를 본격적으로 시행해 중국산 철강 대부분에는 ‘탄소 비용’이 부과된다. 국제에너지기구(IEA)에 따르면 중국의 이산화탄소 배출량은 2023년 기준 1만1310메가톤(Mt)으로, 세계 1위다.브라질과 칠레 등 남미 국가들도 중국산 저가 철강 유입을 막기 위해 올해 초부터 25% 수준의 긴급 관세를 부과하기 시작했다.중국 정부는 철강업계에 감산 조치를 내렸지만, 통하지 않고 있다. 아직 전기로로 대체하지 못한 철강업체들이 전체의 80%로, 생산 중단에 상당한 비용이 따르기 때문이다. 또 지방 정부는 세수 유지를 위해 철강 업체에 우회적으로 생산 유지를 압박하거나 보조금을 지급하고 있다.이에 중국철강협회의 한 임원은 공개석상에서 “지방정부가 GDP와 세수 목표를 달성하기 위해 부실 철강사의 가동 중단을 방해하고 있다”고 비판한 바 있다.국내 철강업계에서는 3~4월 중 중국의 ‘밀어내기 수출’이 늘어날 가능성을 우려하고 있다. 이로 인해 올해 실적 반등을 기대했던 철강업계에 부정적인 여파를 미칠 수도 있다는 것이다. 세계철강협회는 올해 글로벌 철강 수요가 1.3~1.8% 성장할 것으로 전망했다.한편 국내 양대 철강사인 포스코와 현대제철은 사업 다변화와 첨단화로 활로를 찾고 있다. 포스코는 철강 수출을 확대와하고 동시에 리튬 소재 공급망을 늘릴 방침이다. 현대제철은 탄소배출을 20% 이상 줄인 저탄소 강판을 양산해 현대차·기아 전기차에 우선 공급하기로 했다.한 대형 철강업체 관계자는 “후판, 열연의 경우 무역구제조치로 중국산 유입이 제한적일 것”이라면서도 “다만 그 외 제품의 불공정 수입이 확대될 경우 국내 수급 안정화에 방해가 될 것으로 보인다”고 했다.', NULL, '조선비즈', 'https://n.news.naver.com/mnews/article/366/0001146769', 'https://imgnews.pstatic.net/image/366/2026/03/09/0001146769_001_20260309060306984.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-03-09 06:03:06', 0, true, '2026-03-09 06:17:34.556429') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1004, '[서울데이터랩]금일 코스피 거래량 1위 흥아해운 거래대금 4585억 돌파', '코스피 거래량 상위 종목들이 전반적으로 엇갈린 흐름을 보인다.5일 한국거래소에 따르면, 흥아해운(003280)이 1억5846만2048주가 거래되며 코스피 종목 중 실시간 거래량 1위를 차지하고 있다. 현재 주가는 3095원이며, 거래대금은 4585억9900만원에 달한다. 시가총액 대비 거래대금 비율은 약 61.63%로, 시장에서의 집중적인 매수세를 보이고 있다. PER은 27.15, ROE는 20.08로, 재무 지표상 양호한 평가를 받고 있다. 한국ANKOR유전(152550)은 1억5162만814주가 거래되며 거래량 2위를 기록하고 있으며, 주가는 450원, 거래대금은 643억5600만원으로 시가총액 대비 거래대금 비율이 204.31%에 달해 투자 심리가 급격히 움직였다. 케이뱅크(279570)는 1억3646만8178주가 거래되며 거래량 3위를 기록하고 있으며, 현재 주가는 8740원이다.한편 거래량 4위부터 10위에 오른 종목들은 SK증권(001510)(현재가 1705원, +14.81%, 거래량 7777만4768주), 대한해운(005880)(2305원, +3.36%, 4201만3323주), 삼성전자(005930)(191,500원, +11.21%, 3532만2916주), 서울식품(004410)(196원, +5.95%, 3365만6509주), SH에너지화학(002360)(474원, -13.82%, 3021만6357주), 유니켐(011330)(817원, -24.21%, 2849만6993주), 극동유화(014530)(5490원, -8.35%, 2363만8287주) 등의 흐름을 보인다.한편 거래량 상위 20위권 종목들은 남선알미늄(008350) ▲5.97%, 대성에너지(117580) ▲0.22%, 한국석유(004090) ▲6.74%, 한화생명(088350) ▲10.42%, 한온시스템(018880) ▲9.38%, 대우건설(047040) ▲14.04%, KEC(092220) ▲16.87%, 신성이엔지(011930) ▲18.12%, SG세계물산(004060) ▲5.79%, 팬오션(028670) ▲3.69% 등의 성적을 기록했다.주목할 만한 종목으로는 한국ANKOR유전과 KEC가 있다. 한국ANKOR유전은 거래대금이 시가총액 대비 204.31%에 달하며, 급격한 투자 심리 변동을 나타내고 있다. KEC는 16.87%의 상승률을 기록하며 거래량 1039만4300주를 기록했다. 반면, 유니켐과 SH에너지화학은 각각 ▼24.21%, ▼13.82% 하락하며 부진한 모습을 보이고 있다. 유니켐의 거래대금은 224억6200만원으로 시가총액의 29.39%에 해당하며, 매도세가 강하게 작용하고 있는 것으로 보인다.전체적으로 코스피 시장은 엇갈린 흐름을 보이며, 일부 종목에서 집중적인 매수세와 매도세가 관측되고 있다. 특히, 거래대금이 시가총액의 2%를 넘는 종목들이 다수 확인되며, 적극적인 자금 유입이 이뤄지고 있다. 투자자들은 이러한 흐름을 주의 깊게 살피며, 시장의 변동성에 주목해야 할 것으로 보인다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003623173', 'https://imgnews.pstatic.net/image/081/2026/03/05/0003623173_001_20260305133917080.png?type=w800', 'NEWS_CONSUMER', NULL, '2026-03-05 13:39:17', 0, true, '2026-03-09 06:17:42.432919') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1005, '[서울데이터랩]금일 코스피 거래량 1위 흥아해운 거래대금 3916억 돌파', '코스피 거래량 상위 종목들이 전반적으로 엇갈린 흐름을 보이고 있다.한국거래소에 따르면 흥아해운(003280)이 1억 4350만주 이상 거래되며 코스피 종목 중 실시간 거래량 1위를 차지하고 있다. 현재 주가는 2790원으로, 시가총액의 약 5.8%에 해당하는 거래대금 3916억원을 기록하며 19.7% 급등하고 있다. PER 24.47, ROE 20.08로 기업의 재무 상태도 양호한 편이다. 대한해운(005880)은 현재 2355원으로 거래되며, 1억 1137만주를 기록해 거래량 2위를 차지하고 있다. 이 종목은 시가총액 대비 거래대금이 3.9% 수준이며, 16.4% 폭락한 상태다. PER 5.23, ROE 8.93으로 수급과 재무 지표에서 안정성을 보인다.삼성전자(005930)는 현재 17만 4200원으로 10.7% 하락하며 거래량 5863만주를 기록 중이다. SH에너지화학(002360)은 570원으로 18.7% 상승하며 5390만주가 거래됐다. SK증권(001510)은 1494원으로 17.9% 하락하며 거래량 4720만주를 기록하고 있다. 서울식품(004410)은 174원으로 17.9% 하락, 남선알미늄(008350)은 1190원으로 1.7% 상승, 한국ANKOR유전(152550)은 362원으로 29.7% 폭등 중이다. 대성산업(128820)은 1만 2020원으로 10.5% 상승, 한온시스템(018880)은 3630원으로 13.0% 하락하고 있다.한편 거래량 상위 20위권 종목들은 팬오션(028670) ▼18.39%, 극동유화(014530) ▲29.58%, 대우건설(047040) ▼15.73%, 퍼스텍(010820) ▼11.39%, 한화생명(088350) ▼13.22%, SG세계물산(004060) ▼9.24%, 한화갤러리아(452260) ▼4.96%, 한화시스템(272210) ▼15.81%, 신성이엔지(011930) ▼12.27%, 대성에너지(117580) ▲29.95% 등의 성적을 기록하고 있다.극동유화는 1595만주 이상 거래되며 29.5% 상승, 거래대금은 894억원으로 시가총액의 약 42.8%에 달한다. 대성에너지는 986만주 이상 거래되며 29.9% 급등, 거래대금은 1269억원으로 시가총액의 약 34%를 차지한다. 반면 한화시스템은 1125만주 이상 거래되며 15.8% 하락, 거래대금은 1조 663억원으로 시가총액의 4.5%를 차지하고 있다. 팬오션은 1768만주 이상 거래되며 18.3% 하락, 거래대금은 949억원으로 시가총액의 3.5% 수준이다.이날 코스피 시장은 상승과 하락이 혼재된 가운데 특정 종목들이 급격한 등락을 보이며 투자자들의 이목이 집중되고 있다. 특히 흥아해운과 대한해운의 주가 움직임이 시장의 큰 주목을 받고 있다. 거래대금이 시가총액의 높은 비율을 차지하는 종목들이 다수 등장하며 시장 참여자들의 적극적인 거래가 이어지고 있다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003622788', 'https://imgnews.pstatic.net/image/081/2026/03/04/0003622788_001_20260304141220082.png?type=w800', 'NEWS_CONSUMER', NULL, '2026-03-04 14:12:20', 0, true, '2026-03-09 06:17:42.432919') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1006, '[서울데이터랩]금일 코스피 거래량 1위 대한해운 거래대금 무려 2,306억 돌파', '코스피 거래량 상위 종목들이 전반적으로 상승세를 보이고 있다.3일 한국거래소에 따르면 대한해운(005880)이 8600만주 이상 거래되며 코스피 종목 중 실시간 거래량 1위를 차지하고 있다. 현재 주가는 2820원이며 거래대금은 2306억원에 달한다. 대한해운은 시가총액 대비 거래대금 비율이 약 25.3%로 시장에서 집중적인 매수세를 보이고 있다. 또한 PER 6.27, ROE 8.93으로 저평가 인식이 매수세로 이어지고 있음을 시사한다. 남선알미늄(008350)은 5900만주가 거래되며 2위를 기록 중이다. 현재 주가는 1333원으로 거래대금은 806억원에 이른다. PER -5.42, ROE -8.90으로 재무 지표는 부진하나 14.4%의 상승률로 투자자들의 주목을 받고 있다.팬오션(028670)은 4600만주 이상 거래되며 거래량 3위를 기록하고 있다. 현재 주가는 6420원으로 21.6%의 높은 상승률을 보이고 있다. SK증권(001510)은 1908원으로 10.2% 하락하며 4위를 기록 중이다. 삼성전자(005930)는 2887만 5148주의 거래량을 기록하며 7.6% 하락하고 있다. SH에너지화학(002360)은 22.9% 상승, 흥아해운(003280)은 29.7% 상승하고 있다. 한온시스템(018880), 신성이엔지(011930), 대우건설(047040)은 각각 하락세를 보이며 거래량 상위 10위 안에 들고 있다.한편 거래량 상위 20위권 종목들은 조일알미늄(018470) 3.0% 상승, 대원전선(006340) 11.1% 하락, HMM(011200) 13.8% 상승, SG세계물산(004060) 7.5% 하락, 에이프로젠(007460) 8.4% 하락, 퍼스텍(010820) 14.7% 상승, 한화생명(088350) 1.5% 하락, 극동유화(014530) 30.0% 상승, LG디스플레이(034220) 7.7% 하락, 서울식품(004410) 13.3% 하락 등의 성적을 기록하고 있다.주목할 만한 종목으로는 대한해운과 팬오션이 있다. 대한해운은 거래량과 거래대금이 시가총액 대비 높은 비율을 보이며 대규모 매수세가 관찰된다. 팬오션은 21.6% 상승하며 강한 매수세가 이어지고 있다. 하락 종목으로는 SK증권과 대우건설이 눈에 띈다. SK증권은 거래대금이 시가총액 대비 0.9%로 매도세가 강하다. 대우건설은 11% 이상 하락하고 있다.전체적으로 코스피 시장은 상승세를 보이는 종목들이 많지만 일부 종목은 하락세를 면치 못하고 있다. 이러한 흐름은 시장의 다양한 투자 심리를 반영하고 있으며 종목별 수급 상황에 따라 변동성이 클 것으로 예상된다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003622365', 'https://imgnews.pstatic.net/image/081/2026/03/03/0003622365_001_20260303140514962.png?type=w800', 'NEWS_CONSUMER', NULL, '2026-03-03 14:05:14', 0, true, '2026-03-09 06:17:42.432919') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1007, 'G마켓, 명품 직구 플랫폼 ''MXN'' 입점', '/사진제공=G마켓G마켓이 해외 명품 브랜드 전문 이커머스 ''MXN 커머스 이태리(이하 MXN)''와 손잡고 명품 직구 분야를 강화한다.MXN은 명품 데이터베이스 20만개 이상을 기반으로 인기 브랜드를 선보이는 해외 직구 플랫폼이다. 정품만 취급하며 해외 배송과 통관 절차를 일괄 지원해 직구 경험이 없는 고객도 안심하고 쓸 수 있다.G마켓은 이번 MXN 입점으로 명품 선택지를 확대했다. 신흥과 전통 브랜드, 인기 신발 브랜드 등을 한곳에 모아 비교하고 구매할 수 있다.3월1일까지 입점 프로모션도 마련했다. ''봄맞이 해외 명품직구''를 열고 G마켓 모든 고객을 대상으로 8% 할인쿠폰과 10% 브랜드 중복쿠폰을 준다.특히 매일 다른 브랜드를 선보이는 ''요일별 브랜드 특집'' 상품은 할인 혜택을 강화했다. 8% 할인쿠폰에 12% 브랜드 중복쿠폰을 더해 최대 20% 할인한다. 요일별 주요 할인 브랜드는 가니, 스톤아일랜드, 버버리, 막스마라, 구찌, 롱샴, 드래곤디퓨전 등이다.G마켓 관계자는 "해외 명품 수요가 확대되는 가운데 신뢰도 높은 플랫폼과 협업으로 경쟁력을 강화했다"며 "할인쿠폰과 요일별 브랜드 특가를 통해 합리적인 가격으로 인기 명품을 경험할 수 있을 것"이라고 말했다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005320744', 'https://imgnews.pstatic.net/image/008/2026/02/23/0005320744_001_20260223104021697.jpg?type=w800', 'NEWS_BIO', NULL, '2026-02-23 10:39:25', 0, true, '2026-03-09 06:17:50.203914') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1008, '신흥 K뷰티기업의 연이은 호실적…인기 속 늘어난 ''짝퉁''은 고민', '지난달 7일 이재명 대통령과 중국을 방문한 김혜경 여사가 상하이 푸싱아트센터에서 열린 K-뷰티행사에서 참석자 얼굴에 화장품을 발라주고 있다. 청와대공동취재단해외 수요 확대에 힘입어 신흥 K뷰티 기업들이 지난해 최대 실적을 기록했다. 수출 확대와 함께 위조품·지식재산(IP) 침해도 늘면서 성장세를 이어가기 위한 정부의 제도적 지원 필요성이 제기된다.20일 K뷰티 기업 달바글로벌은 지난해 매출 5198억원, 영업이익 1011억원을 기록했다고 밝혔다. 전년 대비 매출은 68%, 영업이익은 69% 증가했으며 연매출은 처음으로 5000억원을 넘어섰다. 해외 매출은 전년(1410억원)보다 131% 증가한 3261억원으로 전체 매출의 62.7%를 차지했다.달바글로벌 관계자는 “지난해 12월 말부터 북미 코스트코 150개 매장과 미국 화장품 체인 ‘울타뷰티’ 1500개 매장에서 주력 제품 판매를 시작했다”며 “올해 북미 지역 오프라인 점포 수를 약 3000개까지 확대하고 권역 내 오프라인 매출 비중을 25%까지 끌어올릴 계획”이라고 말했다.김영옥 기자달바글로벌과 함께 ‘신흥 K뷰티 3대장’으로 꼽히는 에이피알과 구다이글로벌도 지난해 실적 성장을 이어갔다. 세 기업 모두 설립 10년 안팎의 비교적 짧은 업력에도 글로벌 시장을 중심으로 외형을 확대해왔다. 지난해 에이피알은 매출 1조5273억원, 영업이익 3654억원으로 전년 대비 각각 111%, 198% 증가했다. 구다이글로벌은 아직 공식 실적을 공개하지 않았지만 2024년 연결 기준 매출 1조원을 돌파한 데 이어 지난해에는 약 1조7000억원 규모의 매출을 기록한 것으로 업계는 보고 있다.11일 서울의 한 화장품 매장에서 시민이 화장품을 구경하고 있다. 연합뉴스K뷰티 성장세는 수출 성과에서도 확인된다. 산업통상자원부와 한국무역협회에 따르면 지난해 화장품 수출은 전년 대비 11.8% 증가한 114억 달러(약 16조5300억원, 1달러=1450원 기준)로 사상 최대를 기록했다. 2024년 처음 100억 달러를 넘어선 이후 2년 연속 100억 달러대를 유지했다.성장과 함께 위조품도 증가했다. 관세청에 따르면 지난해 적발된 K브랜드 위조 물품 11만7000점 중 화장품류는 4만1903점(35.9%)으로 전체 품목 가운데 가장 높은 비중을 차지했다. 지식재산(IP) 침해 물품에는 구다이글로벌의 뷰티 브랜드 ‘조선미녀’ 선크림 등을 모방한 제품도 포함됐다.김영옥 기자정부는 K뷰티 기업의 성장과 브랜드 보호를 위해 대응 체계 정비에 나섰다. 지난달 23일 위조 화장품 유통 실태 파악과 단속 강화를 위해 식품의약품안전처·특허청·관세청으로 구성된 ‘위조 화장품 대응 관계기관 협의회’를 출범했다.국회도 관련 논의에 착수했다. 김원이 더불어민주당 의원은 지난 10일 ‘전자상거래 기반 K뷰티 기업의 글로벌 성장과 상표권 보호 과제’ 정책 세미나를 열고 K뷰티·플랫폼 기업과 대책을 논의했다. 김 의원은 “K뷰티 기업의 지식재산(IP) 피해 규모가 1조원을 넘은 상황”이라며 “글로벌 시장에서 경쟁력을 유지하려면 제도적·정책적 뒷받침이 필요하다”고 말했다.현장에서도 제도 개선 요구가 이어졌다. 세미나에서 발제에 나선 신화숙 아마존 글로벌셀링코리아 대표는 “K뷰티는 미국 시장에서 프랑스를 제치고 화장품 수입 비중 1위를 차지할 만큼 빠르게 성장하고 있다”며 “일시적 지원이 아닌 구조적 경쟁력을 강화하는 정책이 필요하다”고 말했다. 패널로 참석한 신재하 에이피알 부사장도 “K뷰티의 지속 가능한 성장을 위해 가품 처벌 강화 등 제도적 장치가 마련돼야 한다”고 밝혔다.', NULL, '중앙일보', 'https://n.news.naver.com/mnews/article/025/0003504102', 'https://imgnews.pstatic.net/image/025/2026/02/20/0003504102_001_20260220145611297.jpg?type=w800', 'NEWS_BIO', NULL, '2026-02-20 14:55:48', 0, true, '2026-03-09 06:17:50.203914') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1009, '오늘의 메모[2월 20일]', '<코스피>▲공모주청약=케이뱅크(주관사 NH투자) ▲보통주추가상장=삼아알미늄(006110)(국내CB)에이피알(278470)(주식매수선택권행사) ▲주권변경상장=신흥(004080)(주식소각)<코스닥>▲보통주추가상장=제이케이시냅스·씨아이에스·아시아경제·에코프로비엠·포커스에이아이(국내CB) 인텔리안테크·뉴로메카·메지온(주식매수선택권행사)SG(255220)(국내CB·BW) ▲주권변경상장=이니텍(053350)(주식소각)', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004591315', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_BIO', NULL, '2026-02-19 14:00:06', 0, true, '2026-03-09 06:17:50.203914') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1133, '[인사이드 스토리]해태 ''에이스'', 공장 별 맛 차이 논란의 진실', '맛차이 의혹에 선 긋는 해태제과''굽기 조건'' 공정 차이의 가능성도과거 참이슬 소주 사례와 닮은꼴에이스/사진=해태제과같은 제품, 다른 맛누구나 마음속에 하나쯤은 ''최애'' 과자가 있습니다. 자주 먹는 과자일수록 작은 변화도 금세 눈치채게 되죠. 저 역시 즐겨 먹는 과자가 있는데요. 과자의 양이 줄어들거나 제품이 조금만 달라져도 그 차이를 바로 느끼게 되더군요.최근 온라인 커뮤니티에서는 해태제과의 스테디셀러 비스킷 ''에이스''가 공장별로 맛이 다르다는 글이 올라와 화제가 됐습니다. 작성자는 자신을 ''에이스를 정말 좋아하는 1인''이라고 소개했는데요. 에이스가 예전부터 먹던 그 맛이 아니라 묘하게 바뀌었다고 주장했습니다.훼미리식품 전주공장 생산 제품(왼쪽)과 해태제과식품 아산공장 생산 제품(오른쪽)/사진=온라인 커뮤니티 갈무리이와 함께 꽤 구체적인 근거도 제시했습니다. 전북 전주시의 훼미리식품 공장에서 만든 제품과 충남 아산의 해태제과식품 공장에서 제조한 제품이 서로 다르다는 것이었습니다. 작성자가 공개한 사진 속 두 제품은 색상부터 달랐습니다. 훼미리식품 제품은 육안으로 봐도 구분될 정도로 색이 연했는데요. 짙은 갈색빛을 띠는 아산공장 제품과는 확연한 차이를 보였습니다.맛에 대한 평가도 갈렸습니다. 전주공장 제품은 일본 계란과자처럼 느끼하고 소금맛이 거의 느껴지지 않는 반면, 아산공장 제품은 평소 먹던 고소하고 짭짤한 에이스의 맛에 가깝다는 설명이었습니다. 이 글이 퍼지면서 일부 유튜버들은 직접 비교 실험 영상까지 공개하며 논란에 불을 지폈습니다.훼미리식품 전주공장 생산 제품(왼쪽)과 해태제과식품 아산공장 생산 제품(오른쪽)/사진=김다이 기자 @neverdie궁금증을 확인하기 위해 기자가 실제로 두 공장에서 제조한 에이스를 구입해 비교해 봤습니다. 결과는 예상했던 것과 조금 달랐습니다. 기자가 구매한 제품에서는 오히려 훼미리식품에서 만든 에이스의 색이 더 진했는데요. 맛에서도 뚜렷한 차이를 느끼기 어려웠습니다. 온라인에서 확산된 주장과는 또 다른 결과가 나온 셈입니다.그렇다면 공장별 맛 차이, 정말 가능한 이야기일까요. 현재 에이스는 해태제과식품의 아산 공장과 OEM(주문자상표부착생산) 공장인 전주 훼미리식품 두 곳에서 생산되고 있습니다. 일각에서는 외주 공장에서 레시피를 제대로 지키지 않은 것 아니냐는 의문을 제기합니다.하지만 구조를 뜯어보면 이야기가 달라집니다. 훼미리식품은 단순한 외주업체가 아닙니다. 크라운해태홀딩스 계열사로 해태제과식품이 지분 96.79%를 보유하고 있습니다. 사실상 한 지붕 아래 있는 같은 회사로 봐도 무방한 구조죠. 해태제과 측 역시 "동일한 레시피, 동일한 원료로 제조하고 있기 때문에 맛이 달라질 수 없다"는 단호한 입장을 고수하고 있습니다.뭐가 달랐을까그럼에도 소비자들이 체감할 정도의 차이를 이야기하는 이유는 무엇일까요. 업계에서는 ''레시피''보다는 ''제조 공정 조건''에 주목합니다. 식품공학적으로 같은 배합이라도 설비와 공정 환경이 다르면 미세한 차이가 발생할 수 있다는 설명입니다. 특히 크래커류는 오븐 온도와 열 전달 방식 등 ''굽기 공정''이 맛의 핵심입니다. 공장별로 설비의 노후도나 가열 방식이 미세하게 다를 경우 마이야르 반응(갈색으로 변하며 풍미가 살아나는 현상)의 정도가 변할 수 있다는 논리입니다.한 식품업계 관계자는 "같은 레시피라도 오븐의 구간별 온도 조건이 조금만 달라져도 색이 달라지고, 그에 따라 고소함이나 짠맛에 대한 인식이 달라질 수 있다"고 말했습니다. 대량 생산을 전제로 한 공정에서는 레시피라는 설계도가 같아도 조리 도구인 설비 환경까지 완벽히 동일하다고 보기는 어렵다는 의미입니다.색 차이가 맛 인식을 키웠을 가능성도 큽니다. 심리학적으로 색이 더 진하면 ''더 고소하다''고 느끼고, 옅으면 ''담백하거나 느끼하다''고 느끼는 경향이 있습니다. 결국 온라인의 논란은 제조 로트(Lot)별로 발생할 수 있는 미세한 품질 편차가 예민한 소비자의 미각과 만난 결과로 풀이됩니다.에이스/사진=해태제과해태제과 입장에서는 억울할 수 있습니다. 그러나 역으로 생각하면 소비자들이 에이스 특유의 ''고소하고 짭짤한 밸런스''를 얼마나 좋아하고 있는지를 보여주는 대목이기도 합니다.공장별 품질 논란은 비단 에이스만의 이야기는 아닙니다. 과거 주류업계에서도 비슷한 사례가 있었는데요. 소주는 성분의 대부분이 물이기에 공장마다 사용하는 용수가 달라 맛이 다르다는 주장이 꾸준히 제기되었습니다. 하이트진로 ''참이슬''의 경우 특정 공장 제품이 더 달다는 루머가 돌아 애주가들 사이에서 ''공장 찾기'' 열풍이 불기도 했습니다.이번 에이스 논란은 단순한 불평을 넘어 브랜드에 대한 소비자들의 애정을 확인시켜주는 계기가 됐습니다. 제조 공정의 미세한 변수와 이를 민감하게 포착해내는 소비자 인식이 맞물리며 하나의 흥미로운 논쟁이 완성된 셈이죠.매일같이 먹는 익숙한 과자 한 봉지. 그 안에 담긴 미세한 차이를 둘러싼 논란은 우리에게 대량 생산 식품에서 ''절대적인 맛''이란 존재하는지 다시 한번 생각하게 합니다. 결국 중요한 것은 수십 년간 변치 않는 맛을 기대하는 소비자들의 두터운 신뢰를 지켜나가는 것 아닐까요.', NULL, '비즈워치', 'https://n.news.naver.com/mnews/article/648/0000044182', 'https://imgnews.pstatic.net/image/648/2026/02/03/0000044182_001_20260203161818505.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-03 16:18:18', 0, true, '2026-03-09 06:24:19.124183') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1225, '北 "공식적 유감 표시 다행"…대북주 장 초반 강세', '[특징주]김여정 북한 노동장 부부장이 정동영 통일부 장관이 대북 무인기 침투 사건과 관련해 유감을 표명한데 대해 "다행으로 생각한다"고 밝히자 장 초반 남북경협주가 강세를 보인다.13일 오전 9시14분 현재 거래소에서 코데즈컴바인은 전 거래일 대비 475원(11.89%) 오른 4470원에 거래 중이다. 조비(8.34%), 좋은사람들(7.25%), 인디에프(6.04%), 제이에스티나(3.41%), 일신석재(2.88%) 등도 동반 강세다.이날 김 부부장의 발언으로 남북 간 긴장 완화와 함께 관계 개선에 대한 기대가 나오자 관련주에 수급이 몰린 것으로 풀이된다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005318279', 'https://imgnews.pstatic.net/image/008/2026/02/13/0005318279_001_20260213091909861.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-13 09:18:13', 0, true, '2026-03-09 06:28:46.432405') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1010, '[특징주] 유가 급등에 커진 변동성…대형 정유주 상승 후 반락', '유가 100달러 돌파 속 중소형 정유주는 두자릿수 상승세치솟는 유가(서울=연합뉴스) 이진욱 기자 = 9일 서울 중구 하나은행 본점 딜링룸 현황판에 두바이유 선물 가격, 코스피가 표시돼 있다. 이날 코스피는 하락 출발해 장 초반 5,200대까지 내려앉았다. 2026.3.9 cityboy@yna.co.kr(서울=연합뉴스) 고은지 기자 = 국제유가가 100달러를 넘기자 국내 대형주 정유주가 일제히 상승 출발했으나 다시 하락세로 돌아서는 등 큰 변동성을 보이고 있다.이날 오전 9시 53분 현재 SK이노베이션은 전장보다 2.64% 떨어진 12만1천600원에 거래되고 있다. 주가는 상승 출발해 장 초반 12만8천600원까지 올랐으나 빠르게 상승분을 반납하고 하락 전환했다.GS(-2.74%)와 S-Oil(-1.46%)도 동반 약세를 나타내고 있다.이들 종목 역시 급등하는 듯 보였으나 상승세가 오래가지 못했다.미국 뉴욕상품거래소에서 서부텍사스산원유(WTI) 선물 가격은 한국 시간으로 이날 오전 7시 26분 기준 배럴당 107.54달러를 기록했다. WTI 가격이 배럴당 100달러를 넘어선 것은 2022년 7월 이후 처음이다.브렌트유도 배럴당 100달러를 넘어섰다.국제유가가 치솟으면서 정유주가 개장 직후 ''반짝'' 반사 수혜를 봤지만, 변동성이 큰 장세에서 단기 차익실현 매물이 출회하면서 반락한 것으로 풀이된다.반면, 흥구석유(10.69%), 한국석유(12.04%), 한국ANKOR유전(11.43%) 등 중소형 정유주는 계속 급등세를 보이는 중이다.eun@yna.co.kr', NULL, '연합뉴스', 'https://n.news.naver.com/mnews/article/001/0015946263', 'https://imgnews.pstatic.net/image/001/2026/03/09/PYH2026030903590001300_P4_20260309100817696.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 10:07:35', 0, true, '2026-03-09 06:17:57.909976') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1011, '[특징주]국제유가 100달러 돌파…정유주 테마 강세', '국제 유가가 배럴당 100달러를 넘어가는 등 치솟으면서 정유주가 강세다.9일 오전 9시32분 기준 흥구석유는 전 거래일 대비 17.57% 오른 3만2450원을 기록했다. 극동유화(14.0%), 한국석유(12.0%), 한국ANKOR유전(14.2%) 등도 강세를 보였다.국제유가 급등이 투심에 영향을 미친 것으로 보인다. 이날 오전 7시께 국제유가의 기준점 역할을 하는 브렌트유와 서부텍사스산원유(WTI)가 모두 배럴당 100달러를 넘겼다. WTI는 한때 111.24달러까지 올랐다.최근 미국 원유 가격은 지난주에만 35.63% 급등했다. 1983년 이후 선물거래 사상 최대 상승 폭이다. 이란의 호르무즈 해협 봉쇄 여파가 걸프만 일대 국가의 원유 생산량 감축을 촉발했기 때문이다.', NULL, '아시아경제', 'https://n.news.naver.com/mnews/article/277/0005731219', 'https://imgnews.pstatic.net/image/277/2026/03/09/0005731219_001_20260309094129781.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 09:40:34', 0, true, '2026-03-09 06:17:57.909976') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1012, '태양금속공업, 보통주 1주당 10원 현금배당 결정', '태양금속공업은 보통주 1주당 10원, 우선주 1주당 15원의 현금배당을 결정했다고 9일 공시했다. 배당금 총액은 4억1373만8600원이며 시가배당률은 보통주와 우선주 모두 0.4%다.배당 기준일은 2025년 12월31일이며 배당금 지급 예정일은 다음 달 23일이다. 해당 안건은 오는 25일 정기 주주총회에서 확정할 예정이다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000080535', 'https://imgnews.pstatic.net/image/293/2026/03/09/0000080535_001_20260309145012483.png?type=w800', 'NEWS_AUTO', NULL, '2026-03-09 14:50:12', 0, true, '2026-03-09 06:18:03.259410') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1013, '태양금속공업, 영업익 전년比 39.7% 증가…원부자재 해외현지화 효과', '태양금속공업은 연결 기준 지난해 영업이익이 224억원으로 전년 161억원 대비 39.7% 증가했다고 9일 공시했다.같은 기간 매출은 전년과 비슷한 수준인 6202억원을 유지했고, 당기순이익은 33.6% 증가한 32억원을 기록했다.회사 측은 원부자재 해외 현지화에 따른 수익성 개선이 실적 증가의 주요인이라고 설명했다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000080533', 'https://imgnews.pstatic.net/image/293/2026/03/09/0000080533_001_20260309144807388.png?type=w800', 'NEWS_AUTO', NULL, '2026-03-09 14:48:07', 0, true, '2026-03-09 06:18:03.259410') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1014, '태양금속, 지난해 영업익 224억…전년비 39.7% ↑', '[헤럴드경제=증권부] 태양금속은 지난해 연결기준 영업이익이 224억1880만원으로 전년대비 39.7% 증가했다고 9일 공시했다.같은 기간 매출액은 6201억6933만원으로 비슷한 수준으로 나타났다.당기순이익은 31억8351만원으로 33.6% 늘어난 것으로 집계됐다.', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002610645', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_AUTO', NULL, '2026-03-09 14:16:13', 0, true, '2026-03-09 06:18:03.259410') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1015, '동방, 27일 정기주총 개최…재무제표 승인 등 안건 상정', '동방이 정기 주주총회를 열고 재무제표 승인과 이사 선임 등의 안건을 논의한다.5일 금융감독원 전자공시시스템에 따르면 동방은 27일 오전 9시 서울 중구 동방빌딩에서 제66기 정기 주주총회를 개최할 예정이다.이번 주총에서는 이사 4인의 선임이 안건으로 오른다. 구체적으로는 지희진 법무법인 세종 고문, 정운건 동방 특수사업본부장, 박성준 동방 기획실장·미래전략실장, 강영진 동방 재경부문장 등이다. 지 고문은 사외이사 후보, 나머지 3인은 사내이사 후보다.제66기 재무제표 및 연결재무제표 승인 안건도 상정된다. 이와 함께 이사 보수한도 승인 안건도 논의될 예정이다. 주총 보고사항으로는 영업보고와 감사보고, 내부회계관리제도 운영실태 보고 등이 포함된다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000080368', 'https://imgnews.pstatic.net/image/293/2026/03/05/0000080368_001_20260305163712827.png?type=w800', 'NEWS_ETC', NULL, '2026-03-05 16:37:12', 0, true, '2026-03-09 06:18:10.442185') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1032, '농심 ‘포테토칩 교촌간장치킨맛’ 출시', '교촌치킨과 협업, K-푸드메뉴 확장농심이 오는 23일 치킨 브랜드 교촌치킨과 협업한 스낵 신제품 ‘포테토칩 교촌간장치킨맛(사진)’을 출시한다.포테토칩 교촌간장치킨맛은 인기 외식 메뉴를 감자칩으로 재해석하는 ‘포슐랭 가이드’ 시리즈 제품으로, 교촌의 인기 메뉴인 ‘간장치킨’을 모티브로 개발됐다. 생감자를 물결 모양으로 잘라 식감을 살리고 간장치킨의 특징을 입체적으로 구현했다.농심은 2023년부터 포슐랭 가이드 프로젝트를 통해 다양한 맛의 감자칩을 선보이고 있다. 엽기떡볶이와 잭슨피자, 올디스타코 등 유명 외식 브랜드와 협업을 이어왔다. 지난해에는 포테토칩 K-양념치킨맛 등 K-푸드 메뉴를 적용한 제품을 출시했다.농심은 올해 주요 스포츠 경기 연계 및 포슐랭 시리즈 협업을 통해 포테토칩 마케팅 활동을 적극적으로 전개할 계획이다.농심 관계자는 “국내외 소비자에게 꾸준히 사랑받는 외식 메뉴인 교촌 간장치킨을 포테토칩으로 선보였다”라며 “앞으로도 인기 K-푸드를 농심의 스낵 카테고리로 확장하는 시도를 이어갈 계획”이라고 말했다. 박연수 기자', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002610496', 'https://imgnews.pstatic.net/image/016/2026/03/09/0002610496_001_20260309111617310.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 11:16:17', 0, true, '2026-03-09 06:18:58.745050') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1016, '진원생명과학, 유상증자 납입으로 경영권 안정…"구조조정 박차"', '진원생명과학이 최대주주인 동반성장투자조합 제1호(이하 동방조합)을 대상으로 한 유상증자 납입을 완료했다. 동반조합은 경영권을 강화하고 유동성도 확보한 만큼 경영정상화를 속도감 있게 진행한다는 구상이다.진원생명과학은 지난 4일 동방조합이 81억원 규모 제3자 배정 유상증자 납입을 완료했다고 5일 밝혔다. 동방조합은 지난해 8월 유상증자를 통해 진원생명과학 지분을 처음 인수했으며 이번 유상증자로 지분율이 기존 5.71%에서 11.38%로 확대했다.이에 따라 2대주주인 박영근 전 대표(지분율 4.78%)와의 지분율 차이는 2배 이상으로 확대했다. 앞서 이전 최대주주인 박 전 대표는 지난해 11월 모든 계열사에서 사임하면서 보유목적을 ''단순투자''로 변경하고 보유 지분 일부를 장내매도했다.동방조합은 경영권 확보 후 미국 자회사 VGXI 등의 경영 안정을 위해 인력을 절반으로 줄이는 등 고강도 구조조정을 진행해왔다. 매년 발생하던 수백억원 규모 적자를 해소하겠다는 취지다.진원생명과학은 미국 CDMO(위탁개발생산) 공장 등 자산이 1200억원에 달하지만 보유 현금이 수십억원 수준으로 적어 유동성에 어려움을 겪었다. 회사는 이번에 납입된 자금을 활용해 본업인 DNA(유전자) 및 mRNA(메신저 리보핵산)) 기반의 ''개인 맞춤형 항암 핵산 백신'' 개발에 박차를 가한다는 구상이다.앞서 회사는 개인맞춤형 항암 핵산 백신을 차세대 주력 파이프라인으로 육성하기 위해 △핵산 기반 백신 플랫폼의 고도화 △암 항원 선별 기술 보유 기업과의 협업 확대를 위한 전략적 파트너쉽 구축 △GMP 제조 역량 강화 △글로벌 네트워크 구축 등을 4대 고도화 전략으로 발표한 바 있다.특히 지난달에는 보건복지부로부터 받은 73억원 규모 과태료와 2년간 국가과제 참여제한 처분에 대해 가처분 소송에서 승소해 단기 리스크를 해소하기도 했다.회사 관계자는 "최대주주의 경영권이 한층 안정화되고 유동 자금도 확보한 만큼 경영 정상화를 위해 최선을 다할 것"이라며 "올해부터 구조조정의 성과가 반영될 것으로 보고 있다"고 말했다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005325586', 'https://imgnews.pstatic.net/image/008/2026/03/05/0005325586_001_20260305092109723.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-05 09:20:05', 0, true, '2026-03-09 06:18:10.442185') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1017, '소액주주 선택은…한솔홈데코, 김경록 대표 3연임 앞두고 주가 띄우기', '한솔홈데코가 정기 주주총회를 앞두고 주가부양을 위한 액면합병에 나선다. 사진은 한솔홈데코 CI. /사진=한솔홈데코 제공한솔그룹 건자재 업체이자 코스피 상장사인 한솔홈데코가 정기 주주총회를 앞두고 주가부양에 나선다. 최근 금융당국이 발표한 동전주 상장폐지 요건 신설에 대한 선제 조치로 풀이된다.5일 업계에 따르면 한솔홈데코는 오는 19일 서울시 동작구 전문건설회관에서 정기주주총회를 열고 액면병합에 따른 1주의 금액 변경 건, 김경록 한솔홈데코 대표 사내이사 재선임건 등 안결을 의결할 예정이다.앞서 지난 3일 한솔홈데코는 액면가 1000원 5주를 액면가 5000원 1주로 병합하는 액면병합을 진행한다고 공시했다. 지난 4일 종가 기준 한솔홈데코 주가는 564원, 시가총액은 489억원 수준이다.금융당국은 지난달 증시 내 부실 종목을 솎아내기 위한 개혁안을 발표했다. 특히 주가 1000원 미만 종목(동전주) 상장폐지 요건을 신설해 오는 7월부터 도입할 것을 예고했다. 신설규제가 도입될 경우 30거래일 연속 주가 1000원 미만이면 관리종목으로 지정되며 이후 90거래일 중 45거래일 연속 1000원 이상 주가를 끌어올리지 못하면 상장폐지된다.다만 한솔홈데코는 이번 액면합병에 대해 "중장기적인 주주환원과 주식가치 재평가를 위한 조치"라며 "단순 주가부양을 위한 것이 아니다"라고 설명했다. 또 이번 주총에서 주주가치 제고를 위한 로드맵을 상세하게 설명할 것을 약속했다. 구체적인 주주환원 계획으로는 ▲배당을 통한 투자 수익제공 ▲자사주 매입 및 소각 검토 ▲IR 강화 및 투명한 소통 실행 등을 내걸었다.김 대표의 연임도 이번 주주총회 핵심 안건이다. 사업부문장 출신인 김 대표는 2020년부터 현재까지 6년 동안 대표이사를 맡았으며 사내에서 좋은 평판을 얻고 있다. 김 대표 부임 후 한솔홈데코 실적은 ▲2020년 매출 2532억원, 영업이익 27억원 ▲2021년 매출 2632억원, 영업이익 86억원 ▲매출 2834억원, 영업이익 27억원 ▲2022년 매출 2966억원, 영업이익 36억원 ▲2024년 매출 3273억원, 영업이익 114억원 기록했다. 다만 지난해 건설경기 악화로 전년 대비 각각 14.5%, 75.1% 줄어든 매출 2798억원, 영업이익 28억원을 기록했다.김 대표의 연임 여부는 소액주주들의 손에 달려있다. 한솔홈데코 지분율 중 한솔홀딩스 등이 가진 지분은 23.66%에 불과하다. 반면 소액주주 지분율은 76.35%다.', NULL, '동행미디어 시대', 'https://n.news.naver.com/mnews/article/417/0001132699', 'https://imgnews.pstatic.net/image/417/2026/03/05/0001132699_001_20260305101307325.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-05 10:12:39', 0, true, '2026-03-09 06:18:17.477133') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1018, '한솔홀딩스, 2025년 영업이익 226억원 전년比 202% 증가…매출도 39% 늘어', '[한솔][헤럴드경제=홍석희 기자] 한솔홀딩스는 2025년 연결 기준 매출액과 영업이익이 모두 큰 폭으로 증가했다고 3일 공시했다.한솔홀딩스눈 2025년 연간 연결 매출액은 1조984억원으로 전년 대비 38.7% 증가했다. 같은 기간 영업이익은 227억원으로 202.3% 늘었다.수익성 지표도 개선됐다. 법인세비용차감전계속사업이익은 148억원으로 전년 대비 565.3% 증가했으며, 당기순이익은 91억원으로 471.5% 증가했다.회사 측은 실적 개선의 주요 요인으로 “전기 중 신규 편입된 종속회사의 실적 반영 효과와 주요 자회사의 실적 회복에 따른 지분법 손익 증가” 때문이라고 설명했다.', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002595418', 'https://imgnews.pstatic.net/image/016/2026/02/03/0002595418_001_20260203224710314.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-03 22:47:10', 0, true, '2026-03-09 06:18:17.477133') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1019, '[단독]한솔제지 대표, 제지업계 첫 ''중처법 위반'' 檢 송치', '지난해 12월 9일, 기소 의견 송치李 정부 강경 기조에 고강도 수사한 대표 경영 안정성 변수 불가피한경록 한솔제지 대표가 지난해 대전 신탄진공장에서 발생한 근로자 사망 사고와 관련해 중대재해처벌법 위반 혐의로 검찰에 송치됐다. 한 대표는 지난해 초 실적 악화와 제지 업계의 구조적 불황을 극복할 적임자로 낙점됐으나, 취임 1년 만에 중대한 사법 리스크에 직면하게 됐다.28일 관련 업계에 따르면 고용노동부 대전지청은 지난해 12월 한 대표를 검찰에 기소 의견으로 송치했다. 한 대표는 지난해 7월, 30대 근로자 A씨가 교반기 투입구에 떨어져 숨진 사고와 관련해 공장 내부에 안전보건관리 체계를 제대로 구축하지 않았다는 혐의를 받고 있다. 사건을 넘겨받은 대전지검은 수사 기록을 검토해 최종 기소 여부를 판단할 계획이다.그간 제지 업계에서는 대형 설비로 인한 끼임·추락 등의 산업재해가 반복해 발생했으나, 대부분 내사 종결돼 실제 중처법 위반 혐의로 검찰에 송치되거나 기소돼 처벌받은 사례는 없었다. 이번 송치는 수사 당국이 제지업계의 근로자 안전사고에 대한 총괄 경영자의 책임을 인정한 첫 사례로, 업계 전반의 안전 관리 체계와 문화에 적지 않은 영향을 미칠 수 있단 평가다.이재명 정부 출범 이후 ''산업재해 무관용 원칙'' 기조가 이어지면서 제지 업계의 안전 관리 부담도 한층 커졌다는 분석이다. 지난해 7월, 이 대통령이 국무회의를 통해 산업재해 재발 방지를 거듭 강조한 이후, 경찰과 노동부는 서울 한솔제지 본사와 대전 신탄진공장을 대상으로 압수수색에 나서는 등 수사 강도를 높여왔다.한 대표가 기소되면 실적 반등과 체질 개선을 위한 한솔제지의 경영 전략에도 차질이 빚어질 수 있다는 분석이다.한 대표는 조동길 한솔그룹 회장의 맏사위로, 2014년 한솔그룹에 입사해 한솔제지 인쇄·감열지 사업본부장 등 핵심 보직을 두루 거쳤다.한솔제지는 사고 발생 이후 안전 부문 대표를 신설하고 최고안전책임자(CSO)를 대표이사급으로 격상하는 등 내부 안전 체계를 전면적으로 개편한다는 방침이다. 현재 안전 부문 대표에는 고민혁 한솔홀딩스 인사지원실장이 내정된 상태다. 한솔제지 관계자는 "그간 제지사업과 환경사업으로 나뉘어있던 안전 관리 체계를 일원화하고 관련 의사 결정의 일관성을 확보했다"며 "안전을 기업 경영의 핵심 가치로 삼겠다는 의지를 반영했다"고 설명했다.', NULL, '아시아경제', 'https://n.news.naver.com/mnews/article/277/0005712914', 'https://imgnews.pstatic.net/image/277/2026/01/28/0005712914_001_20260128155010233.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-28 09:10:41', 0, true, '2026-03-09 06:18:17.477133') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1020, '태영건설 ''메트로시티 자산 데시앙'' 5월 분양', '전용 59~84㎡ 738가구 일반분양[서울=뉴시스] 메트로시티 자산 데시앙 투시도. (사진=태영건설 제공) 2026.03.09. photo@newsis.com *재판매 및 DB 금지[서울=뉴시스]정진형 기자 = 태영건설은 자산구역 주택재개발 정비사업을 통해 조성하는 ''메트로시티 자산 데시앙''을 오는 5월 분양할 계획이라고 9일 밝혔다.메트로시티 자산 데시앙은 경남 창원시 마산합포구 자산동 일원에 지하 2층~지상 33층, 총 12개 동, 1250가구 규모로 조성되며, 이 중 738가구를 일반 분양한다.일반분양 타입별 가구수는 ▲59㎡A 221가구 ▲59㎡B 27가구 ▲72㎡A 253가구 ▲72㎡B 114가구 ▲84㎡A 27가구 ▲84㎡B 96가구다.이번 단지는 마산합포구에서 5년 만에 선보이는 신규 공급이자 대규모 브랜드 단지이기도 하다. 바로 앞에 무학초등학교가 위치한 ''초품아'' 입지이며, 마산중, 마산고 등도 도보 통학이 가능하다.무학산과 추산근린공원이 단지를 감싸고 있으며, 일부 세대에서는 마산항 파노라마 조망도 누릴 수 있다.마산 고속버스터미널, KTX 마산역, 서마산IC 등 주요 교통 거점까지 차량 이용 시 15분 이내로 이동할 수 있다. 부산 부전역에서 김해 장유역을 거쳐 창원 마산역까지 약 51㎞를 연결하는 부전-마산 복선전철이 공정률 99%로 개통을 앞두고 있다. 가덕도 신공항 고속화 철도와 창원형 트램도 추진 중이다.단지는 롯데마트, 이마트, 신세계백화점, 스타벅스, 창원NC파크 등 주요 생활·문화 시설을 차량 10분 내외에서 이용할 수 있다. 마산의료원과 창원제일종합병원도 가까이에 있다.인근 마산해양신도시 개발 사업이 추진되고 있다. 마산해양신도시 내에는 디지털 마산자유무역지역이 조성될 예정이다.단지는 남향 위주의 단지 배치에 넉넉한 동간 거리를 확보한 공원형 단지로 조성된다. 지상에는 그린 프라자, 아띠랑스 가든 등 프리미엄 조경 설계를 더했다.  피트니스센터, 실내 골프 연습장, 사우나, 프라이빗 영화관, 코인 세탁소, 카페형 도서관, 뮤직 스튜디오 등의 커뮤니티 시설을 갖출 계획이다.세대 설계는 전용면적 59㎡~84㎡(일반분양)의 중소형 위주 평면으로 구성했다. 전 세대 유리난간 창호가 시공된다. 2~3세대 라인별 엘리베이터를 2대씩 설치된다.', NULL, '뉴시스', 'https://n.news.naver.com/mnews/article/003/0013810378', 'https://imgnews.pstatic.net/image/003/2026/03/09/NISI20260309_0002079161_web_20260309144045_20260309144530089.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 14:44:38', 0, true, '2026-03-09 06:18:25.378602') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1021, 'SSG닷컴, 봄·여름 패션 할인 행사 ''패션명품 쓱세일''…최대 60% 혜택', 'SSG닷컴 ''패션명품 쓱세일'' 홍보 이미지. SSG닷컴 제공[파이낸셜뉴스] SSG닷컴은 봄·여름 시즌 패션 상품을 최대 60% 할인하는 ''패션명품 쓱세일'' 행사를 오는 15일까지 진행한다고 9일 밝혔다.이번 행사에서는 몽블랑과 페라가모의 신상품을 먼저 선보이며, 휴고보스 제품을 할인된 가격에 판매한다. 코치는 화이트데이를 겨냥한 기프트 셀렉션을 공개한다.패션 카테고리에서는 대표 캐주얼 브랜드 중심으로 혜택을 강화했다. 폴로 랄프로렌의 ''호주 오픈 캡슐 컬렉션''을 쓱닷컴 단독 상품으로 판매하고, 빈폴과 라코스테, 프론트로우, H&M 등의 제품도 할인된 가격에 선보인다.아울러 봄철 야외활동 수요를 겨냥해 스포츠 의류와 용품을 최대 50% 할인 판매한다.행사 기간에는 신세계몰과 신세계백화점몰에서 사용할 수 있는 할인 쿠폰을 매일 제공하며, 오전 10시부터 오후 2시까지 타임 특가 행사도 진행한다.SSG닷컴 관계자는 "올봄 트렌드를 반영한 다양한 브랜드를 한자리에 모았다"며 "행사를 통해 관심 있던 상품을 합리적인 가격에 구매할 수 있을 것"이라고 말했다.', NULL, '파이낸셜뉴스', 'https://n.news.naver.com/mnews/article/014/0005488309', 'https://imgnews.pstatic.net/image/014/2026/03/09/0005488309_001_20260309140611769.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 14:06:11', 0, true, '2026-03-09 06:18:25.378602') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1033, '농심, ‘카프리썬 제로 오렌지’ 출시', '[스포츠동아 정정욱 기자] 농심이 9일 ‘카프리썬 제로 오렌지’(사진)를 선보인다.건강을 중시하는 ‘헬시 플레저’ 트렌드에 초점을 맞춰, 기존 ‘카프리썬 오렌지’의 특징을 살리면서 당 함량을 대폭 줄였다. 회사 측은 “칼로리 부담을 줄여 남녀노소 누구나 부담 없이 즐길 수 있다”며 “향후 다양한 맛의 제로 칼로리 라인업을 지속 확대해 브랜드 가치를 높일 것”이라고 했다.', NULL, '스포츠동아', 'https://n.news.naver.com/mnews/article/382/0001260113', 'https://imgnews.pstatic.net/image/382/2026/03/08/0001260113_001_20260308184712379.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-08 18:47:12', 0, true, '2026-03-09 06:18:58.745050') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1022, '유통가 “큰손 러닝족 잡아라”… 현대백화점 등 특화매장 마련', '달리기(러닝) 열풍이 이어지면서 러너를 모시기 위한 유통가의 마케팅 경쟁도 치열해지고 있다.9일 유통업계에 따르면 백화점들은 앞다퉈 러닝족 전용 공간·체험 서비스 등을 강화하고 있다. 현대백화점은 오는 17일 서울 영등포구 여의동 더현대 서울에 약 535㎡ 규모 러닝 특화 공간 ‘더현대 러닝 클럽’을 연다. 라이다·칼렉 등 러닝 브랜드가 입점하고, 러닝 습관과 발 유형을 분석해주는 상담 서비스도 제공한다. 현대백화점 관계자는 “지난해 러닝 관련 매출이 전년 대비 35.8% 증가했고, 올해 1~2월에도 46.7% 늘었다”고 설명했다.롯데백화점은 서울 송파구 잠실 일대 러닝 코스 입지에 주목해 지난달 인근 롯데월드몰에 약 694㎡ 규모 ‘아디다스 롯데월드몰 브랜드센터’를 열었다. 기능성과 패션 중심 공간을 구성하고 발 형태 분석 등 체험 콘텐츠를 마련했다.신세계백화점은 지난달 경남 마산점에 기존보다 4배 이상 확대된 약 550㎡ 규모 ‘나이키 라이즈’ 메가숍을 열고 러닝족 마케팅에 적극 나서고 있다.편의점 업계에선 CU가 한강 인근 점포 3곳에서 ‘CU 러닝스테이션’ 시범 운영에 나섰다. 탈의실과 물품보관함을 설치하고, 에너지 음료·스포츠 드링크·단백질바 등 러닝족 특화 상품을 확대했다.', NULL, '문화일보', 'https://n.news.naver.com/mnews/article/021/0002775717', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2026-03-09 11:49:15', 0, true, '2026-03-09 06:18:25.378602') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1023, '자산 1조원 미만 중견기업, 지배구조 핵심지표 준수율 38.6%로 저조', '코스피 549개사 중 독립 내부감사부서 설치기업 48% 그쳐이사회 과반 이상 사외이사 선입 기업도 55.7%로 개선 필요거래소 2025 기업지배구조 보고서 점검·분석결과 발표기업 규모에 따른 기업지배구조 핵심지표 준수율 격차가 과도하게 큰 것으로 나타났다. 자산규모가 큰 기업은 핵심지표 공시 가이드라인을 비교적 잘 지켰으나 규모가 적은 기업은 그렇지 못했다. 5000억원 이상~1조원 미만 기업그룹과 2조원 이상 기업그룹의 가이드라인 준수율 격차가 2배에 가까웠다.한국거래소는 유가증권시장 상장기업의 2024사업연도 기업지배구조 보고서를 점검·분석한 결과 자산 2조원 이상 기업의 핵심지표 가이드라인 준수율은 67.1%인 반면, 자산 1조원 이상~2조원 미만 기업은 49.3%, 자산 5000억원 이상~1조원 미만 기업은 38.6%에 그쳤다고 7일 밝혔다. 5000억원 이상 그룹과 2조원 이상 그룹의 핵심지표 준수율 격차는 28.5%포인트다.핵심지표별로는 내부감사기구와 외부감사인간의 소통, 배당정책 통지 등의 지표에서 기업규모간의 격차가 특히 컸다.내부감사기구와 외부감사인간 소통 준수율은 2조원 이상 기업이 84.1%로 높은 반면, 1조원 이상은 61.3%, 5000억원 이상은 30.3%에 그쳤다. 상위그룹과 하위그룹의 준수율 격차는 53.8%포인트에 달했다.이사회 내 성별 다양성 부문도 자산 2조원 이상(80.9%)과 자산 5000억원 이상(27.5%)그룹 간 격차가 53.4%포인트로 컸다.배당정책 및 배당실시 계획을 연 1회 이상 통지했는지를 보는 배당부분에서도 자산 2조원 이상은 66.8% 준수율을 보였지만 5000억원 이상은 19.7%에 그쳤다. 준수율 격차는 47.1%포인트다.지배구조 보고서를 세부 부문별로 보면, 전자투표 실시(80.2%), 주총 분산개최(70.9%) 등 다수 상장기업이 주주의결권 보장을 위해 노력하고 있는 것으로 평가받았다. 주총 이전에 주주에게 충분한 검토 시간을 제공했는지를 보는 주총일과 소집공고일 간의 기간도 2023년 21일에서 2025년 21.9일도 늘어났다.하지만 이사회 부문에서는 이사회의 과반수 이상 사외이사 선임 기업이 55.7%에 그쳤고, 이사회 내 성별 다영성을 확보한 기업도 53%에 머무는 등 다양성과 독립성면에서 추가 개선이 필요한 것으로 나타났다.감사기구 부문에서도 독립된 내부감사부서 설치기업이 48%에 불과했고, 외부감사인과 분기별 회의를 개최하는 경우도 62.6%에 그치는 등 감사기구 운영에서의 추가 개선이 필요한 것으로 집계됐다.다만 내부감사기구에 회계·재무전문가가 존재(87.9%)하고 경영관련 주요정보 접근절차 마련(98.6%) 등 감사기구의 구성과 제도관련 지표에서는 상대적으로 높은 준수율이 기록됐다.기업지배구조 보고서를 의무적으로 제출해야하는 기업은 2025년 기준 자산총액 5000억원 이상 상장기업 541개사이고, 자율공시 기업은 8곳이다.한국거래소는 지난 6월 2일 보고서 접수 이후 보고서 가이드라인 준수 여부와 기재누락, 오기재 등에 대해 점검하고 기재 오류가 있는 기업 31곳에 대해 9월 중 정정신고를 요구했다. 2024년과 2025년 연속으로 정정신고를 한 기업은 엔피씨와 한국가스공사 두곳이다.거래소 관계자는 "내년부터 코스피 상장기업 전체로 의무공시 대상이 확대됨에 따라 원활한 공시를 위해 안내자료를 배포하고, 1대1 컨설팅과 교육 등을 체계적으로 지원할 계획"이라고 말했다.', NULL, '비즈워치', 'https://n.news.naver.com/mnews/article/648/0000041555', 'https://imgnews.pstatic.net/image/648/2025/11/07/0000041555_001_20251107113607243.jpg?type=w800', 'NEWS_ENERGY', NULL, '2025-11-07 11:05:06', 0, true, '2026-03-09 06:18:33.886308') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1024, '[체크!공시] 엔피씨 "100% 자회사 엔에스씨 합병"', '[편집자주] [체크!공시]는 공시 관련 각종 이슈를 빠르게 확인, 전달하는 코너입니다.엔피씨가 100% 자회사 엔에스씨를 합병한다./그래픽=강지호 기자엔피씨가 100% 자회사 엔에스씨를 합병한다.29일 엔피씨는 "본 합병을 완료하면 엔피씨는 존속회사로 계속 남고 피합병법인 엔에스씨는 합병 후 해산한다"고 공시했다. 합병기일은 내년 1월2일이다.엔피씨는 "본 합병에 있어 신주를 발행하지 않고 완료 후 최대주주 변경이 없다"며 "본 합병은 엔피씨 재무와 영업에 유의적 영향을 미치지는 않을 것으로 예상되며 본 합병을 통해 경영 효율성과 경쟁력 제고로 기업가치를 제고할 수 있을 것으로 기대한다"고 덧붙였다.엔피씨는 일반 산업용 플라스틱 사출제품 판매·렌탈 사업을 운영하는 기업이다.이날 주가는 전 거래일 대비 0.48% 내린 4185원에 마쳤다.', NULL, '동행미디어 시대', 'https://n.news.naver.com/mnews/article/417/0001109877', 'https://imgnews.pstatic.net/image/417/2025/10/29/0001109877_001_20251029172311502.jpg?type=w800', 'NEWS_ENERGY', NULL, '2025-10-29 17:22:50', 0, true, '2026-03-09 06:18:33.886308') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1025, '생기원·엔피씨, 스티로폼 대체 다회용 수산물 패키징 개발', '재활용 소재 다회용 용기 공동 개발…이마트에브리데이에서 활용한국생산기술연구원(원장 이상목)과 엔피씨가 발포 폴리스티렌(EPS)을 대체할 ‘수산물 전용 다회용 B2B 패키징’을 공동 개발했다.개발된 용기는 반복 사용이 가능하고 보냉 성능이 뛰어나 기존 일회용 스티로폼 단점을 보완할 수 있다. 또 대부분을 폴리프로필렌(PP) 소재로 제작해 사용 종료 후에도 다른 제품으로 재활용할 수 있다.생기원 패키징기술센터 연구팀은 폐플라스틱 재활용 기술을 개발하고 설계 개선과 환경 평가를 수행했다.용기 외부에는 폴리프로필렌 소재를 사용해 내구성을 높였고, 단열재로 가볍고 보냉 효과가 좋은 발포 폴리프로필렌(EPP)을 사용했다.이마트에브리데이에서 수산물 유통에 사용하는 다회용 수산물 패키징.연구팀은 폐플라스틱으로 재생 폴리프로필렌 소재를 만들어 용기 외부에 적용 가능한 시제품을 제작하고, 압축강도·내충격성 등의 성능시험으로 내구성을 입증했다.전과정평가(LCA)를 통해 탄소 배출량을 산정한 결과 개발 용기는 초기 생산 시 EPS 상자보다 탄소 배출량이 약 3배 높지만, 4~5회 재사용 이후부터는 환경적 이득이 더 커지는 것을 확인했다.엔피씨는 공동 연구 개발 성과를 토대로 구조와 특성을 개량한 양산형 제품 제조에 성공했다. 이 과정에서 생기원의 리빙랩 실증을 통해 제기된 수요기업 의견을 반영해 포갤 수 있는 네스팅 구조로 보관·운송 효율을 높였다.용기 뚜껑과 손잡이를 개선, 사용 편의성을 강화하는 한편, 무게도 소형 1㎏, 대형 1.5㎏로 유통 현장 사용 시 부담 없는 수준으로 경량화했다.용기를 회수해 세척·건조·살균 과정을 거쳐 재투입하는 렌탈 시스템을 마련한 결과, 용기 당 35회 이상 반복 사용 가능한 결과를 얻었다.이번 성과는 이마트에브리데이가 ESG 경영의 일환으로 개발 용기를 수산물 유통 과정에 실용화했다.현재 약 3만3천개 용기를 수산물 유통 과정에 투입해 스티로폼 상자를 대체하고 있으며, 향후 활용 규모를 확대할 계획이다.이마트에브리데이가 수산물 유통 과정에서 사용하고 있는 EPS를 개발 용기로 전량 대체하면 3천톤 이상의 EPS 폐기물을 감축할 수 있는 것으로 나타났다.이번 성과는 해양수산부와 해양수산과학기술진흥원 지원으로 2021년부터 2024년까지 수행한 ‘수산물 신선유통 스마트 기술개발’ 과제를 통해 도출됐다.생기원이 총괄 주관기관으로 연구 개발을 주도하고 엔피씨가 공동 연구 개발기관으로 참여했다.심진기 생기원 패키징기술센터장은 “국내 수산물 유통 현장에 스티로폼을 대체해 친환경 다회용 용기를 도입한 첫 사례”라며 “향후 수산 부산물의 부위별 품질관리와 패키징을 추가로 개발할 예정”이라고 말했다.홍성원 엔피씨 연구소장은 “수산물 분야에도 스티로폼을 대체할 수 있는 친환경 용기가 도입된 만큼 보급·확산 속도를 낼 수 있도록 지원이 필요하다”며 “앞으로는 규격을 다변화하고 적용 분야를 넓혀 확산을 이어갈 계획”이라고 설명했다.', NULL, '지디넷코리아', 'https://n.news.naver.com/mnews/article/092/0002393219', 'https://imgnews.pstatic.net/image/092/2025/10/09/0002393219_001_20251009095112024.jpg?type=w800', 'NEWS_ENERGY', NULL, '2025-10-09 06:04:14', 0, true, '2026-03-09 06:18:33.886308') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1026, '[人사이트] 윤성호 남성 대표 “北美 2만6000개 유통망이 AI 플랫폼 된다”', '윤성호 남성 대표“올해는 인공지능(AI)을 파는 해가 아니라 AI 플랫폼을 까는 해입니다.”윤성호 남성 대표는 올해를 ''자동차 AI 플랫폼 원년''으로 규정했다. 창업 60년을 넘긴 남성은 북미 자동차 애프터마켓에서 파이오니아와 1위를 다투는 강자다. 월마트, 펩보이, 오라일리 등 2만6000개 이상 판매 거점을 확보한 남성이 올해 승부수로 내건 것은 스마트 미러링 기반 AI 플랫폼이다.윤 대표는 “스마트폰 화면을 차량 디스플레이에 그대로 끌어다 놓는 스마트 미러링 제품을 2분기부터 월마트에서 출시합니다. 소비자들은 편리한 미러링 제품으로 볼 수 있지만, 저희는 이걸 AI가 운전자의 인포테인먼트 정보를 인지하고 맞춤 추천을 하는 플랫폼 첫 단계로 봅니다”라고 소개했다.남성은 이를 위해 KAIST 연구팀과 공동으로 ''스마트 미러링과 스크린 인식'' 기술을 약 1년째 개발 중이다. 고성능 CPU 없이 온디바이스 방식으로 미러링 콘텐츠를 분석해 맥락에 맞는 정보를 제안하는 경량 AI 시스템이 목표다. 윤 대표는 “미국에 이미 연간 100만대 이상 남성 제품이 판매되고 있다”며 “여기에 AI가 올라타면 그게 곧 플랫폼”이라고 강조했다.애프터마켓에서 남성은 듀얼(DUAL)과 젠슨 등 2개 브랜드로 시장을 공략한다. 듀얼은 남성이 2002년 인수한 100년 역사의 독일 브랜드로, 99~199달러 대중 가격대를 겨냥한 주력 브랜드다. 젠슨은 미국에서 스피커와 앰프 명가로 이름을 알린 브랜드로, 남성이 북미 판권을 인수해 하이엔드 라인으로 운영 중이다. 700~800달러대 파이오니아와는 포지션이 다르지만, 젠슨을 통해 프리미엄 세그먼트에도 발을 걸쳐 두는 전략이다.윤 대표는 “경쟁사들은 저가 제품을 내놓으면 기존 고가 라인과 충돌이 생긴다”며 “남성은 처음부터 대중 시장을 겨냥했기 때문에 공격적으로 갈 수 있고, 젠슨으로 하이엔드 시장도 함께 챙긴다”고 말했다.남성의 탄탄한 유통망은 빅테크 시선도 끌었다. 아마존이 먼저 남성에 협업을 제안한 것이 대표적 사례다. 카플레이·안드로이드 오토에 이어 AI 솔루션 업체들도 하드웨어 유통망을 가진 남성을 찾아오기 시작했다. 윤 대표는 “새로운 기술이 나오거나 플랫폼을 가진 업체들이 북미에서 유통을 확장하려 할 때 가장 먼저 연락이 온다”고 말했다. 2만6000개 판매망이 협상 테이블에서 가장 강력한 무기가 된다는 얘기다.OEM 전장에서도 존재감을 키운다. 북미 RV 시장 점유율 60% 이상을 가진 특장차 업체 TMC에 인포테인먼트를 90% 이상 공급 중이다. 올해는 배터리 충전·발전기 제어·슬라이드아웃 구동 등 바디 컨트롤 시스템으로 납품 범위를 확대해 현재 30%대 공급 점유율을 50% 이상으로 끌어올린다는 목표다. 이 같은 전략으로 올해 매출은 전년 대비 20~30% 성장을 기대하고 있다.윤 대표는 “남성의 역사는 1970년대 현대차 포니에 카오디오를 최초 납품한 것이 그 출발”이라며 “일찌감치 수출에 주력한 자동차 애프터마켓 시장은 우리가 제일 잘 안다”라고 자신했다. 이어 “AI가 본격 확산될 때 좋은 열매를 딸 수 있도록 지금 플랫폼을 심을 것”이라고 말했다.김시소 기자 siso@etnews.com', NULL, '전자신문', 'https://n.news.naver.com/mnews/article/030/0003404743', 'https://imgnews.pstatic.net/image/030/2026/03/05/0003404743_001_20260306102620635.jpg?type=w800', 'NEWS_TRANSPORT', NULL, '2026-03-05 16:01:15', 0, true, '2026-03-09 06:18:40.303239') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1027, '남성, 미국 수출 호조로 영업익 흑자전환…순이익은 적자', '남성이 미국 수출 증가와 비용 절감에 힘입어 영업이익 흑자전환에 성공했다. 남성은 2025년 연결 기준 영업이익이 1억7360만9000원을 기록해 전년 18억950만6000원 적자에서 흑자로 돌아섰다고 3일 공시했다.같은 기간 매출은 775억4122만3000원으로 전년 745억7781만7000원 대비 4.0% 증가했다. 다만 순이익은 기타수익과 금융수익이 줄어들면서 37억8519만원 적자를 기록해 전년 44억1706만1000원 흑자에서 적자로 돌아섰다.실적 개선은 미국 지역 수출이 늘어난 가운데 매출원가와 판매관리비를 절감한 결과다. 2025년 말 기준 자산총계는 2782억8840만원이며 부채총계와 자본총계는 각각 1728억2441만5000원, 1054억6398만5000원이다.이번 실적은 외부감사인의 감사가 완료되기 전 내부 결산 자료이며 향후 주주총회 승인 결과에 따라 수치가 변경될 수 있다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000080190', 'https://imgnews.pstatic.net/image/293/2026/03/03/0000080190_001_20260303155208453.png?type=w800', 'NEWS_TRANSPORT', NULL, '2026-03-03 15:52:08', 0, true, '2026-03-09 06:18:40.303239') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1028, '남성인프라넷, 오너 회사에 213억 빌려주고 이자도 못받아 [넘버스]', '이 기사는 2026년 01월 02일 16시 16분넘버스유료 사이트에 발행된 기사입니다./ 사진=남성 홈페이지 캡처, 그래픽=정유진 기자남성 계열사의 수백억원대 자금이 오너 일가가 지배하는 ''드리머'' 계열로 이동한 것으로 나타났다. 여기에 수년째 드리머 계열사를 상대로 발생한 미수금, 매출채권 등을 상당 부분 회수하지 못한 것으로 나타난다.남성은 드리머멤버스와 그 자회사인 NSI의 차입금에 대해 400억원이 넘는 지급보증을 제공해왔다. 드리머가 채무상환을 하지 못할 경우 남성이 이를 대신 이행하겠다는 약정이다.드리머멤버스에 대한 지급보증은 29억원이며 이 가운데 상환가능성을 반영해 이미 부채로 인식한 금융보증계약부채는 26억원이다. 또 NSI에 대한 지급보증은 253만달러로 한화 약 366억원에 달한다. 이 가운데 금융보증계약부채는 한화 약 89억원이다.남성은 지급보증에 이어 드리머멤버스의 차입을 위해 단기금융상품 26억원도 담보로 제공한 상태다.NSI와의 거래에서 발생한 대금 역시 제때 회수하지 못한 채 쌓이고 있다. 영업 외 거래에서 정산되지 않은 미수금은 13억원이며, 물건이나 서비스를 받기 전에 먼저 지급한 선급금은 94억원에 달한다. 이 가운데 장기선급금 36억원은 회수 가능성이 낮다고 판단해 전액 대손충당금으로 설정했다. 대손충당금은 해당 금액을 회수 가능성이 낮다고 판단해 선제적으로 손실 반영했다는 의미다.남성은 회수 불확실성이 드러난 거래처와 대규모 거래를 지속하고 있다. 올해 3분기에도 남성은 NSI로부터 10억원을 정산 받은 뒤 다시 21억원을 선급금으로 지급했다. 같은 기간 NSI로부터 184억원 규모의 재고를 매입했으며 지난해에는 237억원, 2023년에는 223억원 등 수년간 수백억원대 매입 거래가 이어지고 있다. 남성은 드리머로부터 차량용 CD, GPS 등을 매입해온 것으로 파악된다.남성 관계자는 "드리머는 IT 관련 회사"라며 "드리머는 별도 법인이기 때문에 직원 수 등 회사 사안에 대해서는 남성 측에서 답변하기 어렵다"고 말했다.그래픽 = 박진화 기자남성인프라넷은 드리머에 직접 자금을 대여하고 있다. 올 3분기 기준 남성인프라넷이 드리머에 빌려준 금액은 213억원이며 적용 이자율은 연 4.6%다. 그러나 현재까지 드리머가 지급하지 않은 이자만 10억원에 달한다. 그럼에도 남성인프라넷은 올해 9억원을 회수한 뒤 다시 15억원을 추가 대여했다.남성에이엠디 역시 드리머와 드리머멤버스를 상대로 자금 거래를 이어왔다. 올 3분기 드리머에 9억원을 빌려줬고 같은 기간 곧바로 회수했다. 다만 남성에이엠디는 이와 별도로 드리머멤버스의 차입을 위해 단기금융상품 33억원을 담보로 제공했다. 남성 계열사들이 드리머와 자회사들의 자금 조달을 뒷받침하고 있는 모습이다.문제는 드리머와 그 계열사가 남성 오너 일가가 지배하는 특수관계회사라는 점이다. 본체인 남성은 실적 부진으로 자금 여력이 빠듯한 상황이지만 상당한 규모의 자금이 오너 일가의 회사로 흘러 들어가고 있다.남성의 올해 3분기 매출은 564억원을 기록했지만 영업이익은 7억원에 그쳤고, 순이익은 -31억원으로 지난해에 이어 적자를 이어가고 있다. 같은 기간 남성의 현금성자산은 6억원에 불과하다.드리머는 故윤봉수 남성 창업회장의 장남 윤남철 남성인프라넷 대표이사와 차남 윤성호 남성 대표이사가 각각 대표와 이사로 재직 중이다. 회사 소재지는 서울특별시 금천구 가산동 남성프라자 15층으로 남성과 동일하다.남성 관계자는 "남성은 드리머 지분을 5% 보유하고 있을 뿐 직접적인 거래는 없고 특별한 관계도 아니다"고 말했다. 이어 "지급보증이나 담보 등에 대해서는 회수 방안을 검토하고 있다"며 "해당 금액들은 과거 거래 과정에서 발생한 것"이라고 덧붙였다.남성이 보유한 드리머와 NSI 주식은 누적 손실이 지속되며 투자금 회수 가능성이 없다고 판단해 장부상 주식 가치를 전액 감액 처리했다. 남성은 드리머 지분 5%, NSI 지분 9.45%를 보유하고 있다. 각각의 취득원가는 6000만원과 4억9000만원이다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000077976', 'https://imgnews.pstatic.net/image/293/2026/01/19/0000077976_001_20260119110307367.png?type=w800', 'NEWS_TRANSPORT', NULL, '2026-01-19 08:57:06', 0, true, '2026-03-09 06:18:40.303239') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1029, '소액주주 입틀막 ‘SLAPP’ 확산… 기관·외인도 기피 우려', '주주 활동 막아 시장 견제 기능 약화주총 내실화 위한 상법개정 후순위소액주주 목소리를 고소전으로 차단하는 전략적 봉쇄소송(SLAPP 슬랩)이 중·소형주를 중심으로 유행처럼 번지고 있다. 지배주주나 회사에 대한 비판적 발언을 한 개인 소액주주를 고소해 행동을 위축시키기 위한 것으로 분석된다. 개인 투자자 비중이 높은 중·소형주에서 이런 흐름이 지속하면 시장의 감시 기능을 크게 위축시켜 기관과 외국인 투자자의 기피 현상이 강화될 것이라는 우려가 나온다.1일 금융투자업계에 따르면 물류기업 세방은 지난 1월 28일 소액주주 연대에 내용증명을 발송해 민형사상 법적 조치를 취할 수 있다고 경고했다. 전날 소액주주가 금융감독원에 세방의 자사주 처분 관련 조사를 요청하는 진정서를 제출했다는 게 이유다. 소액주주는 세방이 지난해 7월 하이비젼시스템과 자사주를 상호 교환하기로 한 점을 문제 삼았다. 상법을 회피하고 지배주주의 경영권 방어를 위한 편법이라는 판단에서다. 하지만 세방은 ‘소송 불사’ 의지를 담은 내용증명으로 맞섰다.주주 대표를 명예훼손으로 경찰에 고소한 사례도 있었다. 2024년 6월 삼목에스폼은 소액주주가 회사 자산가치 등을 문제 삼자 주주대표를 명예훼손으로 고소했으나 같은 해 9월 증거불충분으로 무혐의 처분이 나왔다. 바이오니아, 오스코텍 등과 같은 코스닥 상장사들도 소액주주와 갈등을 빚어 주주 개인을 고소한 전력이 있다.기업이 소액주주를 상대로 벌이는 소송전은 주주의 활동을 막아 시장 견제 기능을 약화시킨다. 소액주주 플랫폼 액트(Act) 이상목 대표는 “승소가 목적이 아닌 일종의 입막음용인 경우가 있다”며 “상대적으로 약자를 괴롭히는 지능적인 수법이라고 판단된다. 비판의 여지가 많다”고 지적했다.의결권을 조작해 소액주주의 견제를 무력화하는 시도도 있었다. 하나마이크론은 지난해 7월 임시 주주총회를 통해 회사를 인적분할하는 안건을 통과시켰다. 하지만 회사 측이 제출한 위임장 1400여장이 조작됐다는 의심을 받고 있다. 회사의 인적분할 시도는 ‘주주총회 효력정치 가처분’ 신청을 법원이 인용하면서 중단된 상태다. 가처분을 신청한 소액주주 측은 회사와 의결권 위임 대행사 양쪽에 모두 법적 대응에 나선다는 계획이다.‘기울어진 운동장’으로 평가받는 주주총회를 개선하려는 상법개정은 국회에 계류돼 있다. 이강일 더불어민주당 의원은 주총 의장을 주주가 원하는 인물로 요청할 수 있도록 하는 내용의 상법개정을 지난해 7월 발의했다. 발행주식 총수의 10% 이상을 보유한 주주가 주총 10일 전까지 법원에 의장 선임 청구를 할 수 있도록 한 내용이다.이 의원은 “의장이 회사 측 이해에 따라 자의적으로 발언을 제한하는 경우가 빈번히 발생하고 있다”며 “소액주주의 정당한 의결권 행사를 훼손하고 있다”고 지적했다. 다만 현재 K자본시장 특별위원회 차원에서 논의되는 법안은 아니다. 실제 법안 통과까지는 시간이 필요할 것으로 보인다.', NULL, '국민일보', 'https://n.news.naver.com/mnews/article/005/0001834582', 'https://imgnews.pstatic.net/image/005/2026/03/02/2026030122330538284_1772371986_1772343503_20260302001410694.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-02 00:14:10', 0, true, '2026-03-09 06:18:51.660853') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1030, '''주주권 강화'' 상법 원년… 주주제안으로 목소리 키우는 소액주주들', '소액주주 플랫폼 ''액트'' 등 중심으로 주주제안별도 감사위원 선출·임원 보수 산정기준 공개행동주의 펀드도 주주제안·공개서한 등 여론전내년부턴 3% 룰 강화에 집중투표제도 도입게티이미지뱅크상장사 정기주주총회를 앞두고  소액주주와 행동주의 펀드의 움직임이 본격화하고 있다. 별도의 감사위원 선출이나 임원 보수 공개 등을 요구하는 주주제안에 나서고 있는 것이다. 특히 올해는 ''주주권 강화''를 골자로 한 개정 상법이 적용되는 첫 주총이라는 점에서 압박 강도가 커질 전망이다.19일 금융투자업계와 주주행동 플랫폼 액트에 따르면 최소 42개 상장사의 소액주주들이 3월 정기주주총회를 계기로 주주연대 구성에 나서고 있다. 이 중 최소 10개사 소액주주들이 실제 상장사에 주주제안을 제출했다.상법에 따르면 회사 발행주식의 3%를 보유하거나, 1% 이상을 6개월 이상 보유한 주주들은 주총 6주 전까지 주주제안을 할 수 있다. 통상 상장사 주총이 3월 하순에 열린다는 점을 고려하면, 소액주주들도 설 연휴 이전까지는 주주제안에 나서야 하는 상황이었다.코스피 상장사 세방이 대표적이다. 세방 소액주주연대는 주당 800원의 현금 배당과 감사위원 분리 선출을 요구하고, 소액주주 측 감사위원도 별도로 추천했다. 코스닥 상장사인 다원시스 주주연대도 주주제안을 통해 사외이사와 감사 후보를 내세웠다.행동주의를 표방하는 자산운용사들의 요구도 거세다. 얼라인파트너스는 코웨이에 세 차례 주주서한을 보낸 뒤 이사회 의장은 ''독립이사''로 하고, 감사위원 전원을 독립이사로 구성하라는 내용의 주주제안을 보냈다. 코웨이 외에도 덴티움, 가비아, 솔루엠 등에도 주주제안을 통해 독립 사외이사를 선임하고, 임원 보수 산정 투명성을 높일 것을 요구했다.또 다른 행동주의 운용사인 트러스톤자산운용도 KCC와 태광산업에 공개 주주서한을 보내 회사를 압박했다. KCC에는 삼성물산 지분 유동화 계획을 수립하고 자사주 소각 계획을 밝힐 것을, 태광에는 소수주주가 보유한 21.1% 지분을 매입한 뒤 아예 상장폐지에 나설 것을 각각 요구했다.통상 대주주와 우호지분 비중이 큰 국내 상장사 특성상 주주제안이 주총에서 통과되기는 쉽지 않다. 상장회사협의회와 코스닥협회에 따르면 지난해 주주제안 안건이 상정된 상장사는 총 41개사인데 이 중 주주제안 안건이 1건이라도 가결된 상장사는 10개사에 그쳤다.다만 올해는 상법상 ''이사의 충실의무'' 대상이 주주로 확대된 후 첫 주총이 열리는 만큼 주주제안에 나서는 소액주주와 행동주의 펀드의 압박이 거세질 것으로 보인다. 특히 자산총액 2조 원 이상의 대규모 상장사는 9월 10일 이전까지 ''분리 선출''한 감사위원 2명을 선임해야 해, 이번 주주총회에서 관련 안건이 다뤄질 가능성이 크다. 상장사들은 올해 주총부터 표결 결과에 대한 ''찬반 비율''도 공시해야 한다.한국ESG기준원은 ''2026 주주총회 프리뷰'' 보고서에서 "올해 주주총회에서는 감사위원 분리 선출 안건 등을 통한 소액주주의 이사회 진입 시도가 크게 증가할 것"이라고 예상했다.올해 주총은 사실상 내년 주총의 전초전 격이다. 사외이사인 감사위원을 선임할 때 ‘최대주주와 특수관계인 지분 합산’ 3%까지만 의결권 행사가 가능하다는 상법 조항이 올해 7월부터, 집중투표제 의무화는 9월부터 시행되면 내년 주총에서는 소액주주의 영향력이 더 커질 수 있다.', NULL, '한국일보', 'https://n.news.naver.com/mnews/article/469/0000915210', 'https://imgnews.pstatic.net/image/469/2026/02/19/0000915210_001_20260220061042802.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-19 18:01:14', 0, true, '2026-03-09 06:18:51.660853') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1031, '주총 앞두고 곳곳서 지뢰밭…참다 못한 KG, 소액주주연대 경찰 고소[시그널]', '“컨설팅 명목으로 5000만원 요구”KG, 액트 등 공갈미수 혐의 고소LS에식스 이어 세방·이마트까지주주제안 넘어 신고 남발로 압박“자본시장 거버넌스 개선에 찬물부당한 활동으로 경영위협” 지적이 기사는 2026년 2월 10일 15:44자본시장 나침반  ''시그널(Signal)''에 표출됐습니다.KG그룹 기업 CI. KG그룹다음 달 정기 주주총회 시즌을 앞두고 기업과 소액주주 간 갈등이 곳곳에서 분출되고 있다. 상법이 개정되고 한국 증시 전반에 주주가치 제고 바람이 거세게 불면서 소액주주 연대의 활동도 더욱 힘을 받기 때문으로 풀이된다. 다만 이 과정에서 소액주주연대가 금융 당국과 공정거래위원회 등 정부 기관에 신고를 남발하고 일부 주주 대표는 기업을 상대로 경제적 이득을 취하려 하는 등의 부작용이 속출하고 있다.10일 재계와 투자은행(IB) 업계에 따르면 KG그룹은 지난해 말 소액주주 플랫폼 액트(ACT)와 소액주주연대 대표를 공갈 미수 혐의로 서울 강남경찰서에 고소했다. KG그룹 관계자는 “액트 측이 회사에 거버넌스 개선 컨설팅을 해주겠다고 별도로 5000만 원을 요구했다”며 “회사는 이 같은 행위가 부당하다고 판단해 응하지 않았고 공갈 미수 혐의를 적용해 고소장을 제출한 것”이라고 밝혔다.KG케미칼(001390)·KG에코솔루션(151860)·KG모빌리티(003620)등 KG그룹 내 6개 상장사 주주들로 구성된 소액주주연대는 지난해부터 다양한 경로를 통해 사측을 압박해 왔다. 이들은 오너 일가의 사익 편취, 낮은 주주 환원, 기업설명(IR) 활동 미흡 등을 주장하며 지난해 대통령실에 탄원서를 제출하고 공정위에 곽재선 KG그룹 회장을 고발하기도 했다. 지난달에는 청와대 인근에서 트럭 시위를 벌이면서 공론화 장으로 끌어올리려는 시도를 하고 있다.문제는 주주가치 제고 명분을 발판 삼아 연대 측 대표가 회사에 경제적 이득을 요구하는 등 본질을 흐리고 있다는 점이다. 이에 재계에서는 일부 사업자들이 소액주주 활동을 통해 기업을 압박하고 사적 이익을 취하려는 행태가 반복돼 문제가 있다는 비판이 커지고 있다.최근 소액주주들의 거센 비판으로 상장 계획을 철회한LS(006260)에식스솔루션즈 사례도 유사하다. 상장 무산에 자금 조달 계획이 틀어지자 액트 측은 LS그룹에 직접 5000억 원 규모의 자금을 조달해주겠다고 제안하는 등 물밑 접촉을 시도했던 것으로 알려졌다. 법조계 관계자는 “자발적으로 모인 소액주주 세력을 이용해 회사를 압박하고 별도의 경제적 이득을 취하려 하는 행위는 형법상 공갈 혐의나 상법에 명시된 ‘이익공여 금지’ 위반 사례에 해당할 수 있다”고 지적했다.LS와 KG 외에도 정기 주총을 앞두고 상장사와 소액주주 간 갈등은 전방위로 확산 중이다. 일부 부도덕한 사례 탓에 시장 전반에 일고 있는 거버넌스 개선 흐름에 찬물을 끼얹는 것 아니냐는 불안감도 커지는 분위기다.이마트(139480)가신세계푸드(031440)를 100% 자회사로 만들어 경영 효율화를 꾀하려던 계획도 소액주주들의 반발이 거세지며 위기에 직면해 있다. 신세계푸드 소액주주들은 이마트가 제시한 공개매수 가격이 낮다며 대부분 응하지 않았다. 또 포괄적 주식 교환을 통한 상장폐지도 반대하는 입장이다. 이들은 회사를 압박하기 위해 한국거래소와 금융감독원에 선행 매매 가능성에 대한 조사를 요청한 상태다.유한양행(000100)의 항암 신약 연구개발(R&D) 자회사인이뮨온시아(424870)주주들은 최근 발표된 1200억 원 규모의 유상증자 결정에 반발하며 비상대책위원회 결성을 추진하고 있다. 이들은 최대주주인 유한양행이 배정 물량에 100% 청약해 경영 책임을 다해야 한다고 주장했다. 요구가 받아들여지지 않을 경우 집단 민사소송도 불사하겠다는 입장이다.세방(004360)은 자사주 처분 문제를 두고 진통을 겪고 있다. 세방 소액주주연대는 세방이 지난해 7월 하이비젼시스템과 자사주를 맞교환한 것을 두고 경영권 방어를 위한 편법이라 비판했다. 그러면서 지난달 금융감독원에 세방의 자사주 처분 관련 조사를 요청하는 진정서를 냈다. 세방 측은 과거 관계기관 조사 등을 통해 명확히 소명된 사안을 주주연대가 반복적으로 문제 삼고 있다는 입장이다. 또 객관적 근거 없이 회사 명예를 훼손하는 행위가 지속될 경우 민형사상 법적 조치를 취하겠다고 경고하는 등 갈등이 비화될 조짐도 보인다.소액주주와 갈등을 빚고 있는 한 기업 관계자는 “주주들이 적극적으로 목소리를 내는 분위기는 코리아 디스카운트 해소와 거버넌스 선진화의 촉매제로 작용할 수 있다”면서도 “관계 당국을 통해 기업을 압박하고 뒤로는 사적 이득을 취하려는 일부 부도덕한 행태가 반복돼 정상적 경영 활동에 위협을 받고 있다”고 호소했다.', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004588932', 'https://imgnews.pstatic.net/image/011/2026/02/10/0004588932_001_20260210234808256.png?type=w800', 'NEWS_ETC', NULL, '2026-02-10 17:31:07', 0, true, '2026-03-09 06:18:51.660853') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1034, '''휴머노이드 특화단지''가 뭐길래', '''국가 전략산업 핵심 거점'' 공식 선언적 성격이재명 대통령이 대구 엑스코에서 열린 ''미래혁신기술박람회(FIX 2025)''를 방문해 글러브를 낀 휴머노이드 로봇을 살펴보고 있다. 대통령실 제공대구가 휴머노이드 로봇을 앞세워 ''국가첨단전략산업 특화단지'' 지정에 도전하면서 특화단지의 의미와 파급효과에 관심이 쏠린다. 단순한 산업단지 지정이 아니라, 국가 차원의 전략산업 거점을 공식 인증받는 절차이기 때문이다.산업통상부는 지난해 12월 ''국가첨단전략산업 특화단지 공모''를 시작하고 지난달 27일 오후 6시까지 신청을 받았다. 이번 공모 대상은 로봇(휴머노이드), 방산, 2차전지 분야다. 특화단지는 ''국가첨단전략산업 경쟁력 강화 및 보호에 관한 특별조치법''에 따라 지정되는 지역이다. 전략산업 관련 교육시설·연구시설·산업시설이 집적돼 혁신 생태계를 이루고, 투자와 기술개발이 촉진되도록 국가가 공식 지정·운영하는 산업 거점이다.지정 요건은 까다롭다. 법령상 전략산업을 영위하는 선도기업 집적과 전략기술을 기반으로 한 생산·연구 수행, 기반시설 확보 가능성 등이 지정 요건으로 제시된다. 여기에 전문인력 확보, 지역 주력 산업과의 연계 효과, 집적화 수준 등은 평가 항목에 반영된다. 이후 특화단지소위원회와 산업조정위원회 사전 검토를 거쳐 국무총리 주재 국가첨단전략산업위원회에서 최종 의결된다.특화단지로 지정되면 인·허가 신속 처리와 산업기반시설·공동연구 인프라 구축 지원, 국·공유재산 사용료 감면, 부담금 감면, 예비타당성조사 특례 등이 적용된다. 전략기술 사업화 시설 투자와 연구개발에 대한 세액공제, 정책금융 우대, 정부 R＆D 사업 우선 고려 등 재정·정책 지원도 병행된다.특화단지는 정부가 해당 지역을 국가 전략산업의 핵심 거점으로 인정하는 공식 선언에 가깝다. 지정 이후에는 대규모 민간 투자와 정부 R＆D, 인력 양성 정책이 집중되면서 산업 생태계가 빠르게 고도화되는 구조를 만든다. 특히 휴머노이드 로봇은 올해 전략산업에 새롭게 포함된 분야다. 첫 지정 단지에 따라 국내 로봇 산업의 중심축이 결정될 가능성도 있다.대구시는 기존 제조로봇 중심 산업을 휴머노이드 로봇으로 확장해 ''제조·실증·인증이 결합된 통합 거점''으로 도약하겠다는 전략을 내세우고 있다. 지역에는 HD현대로보틱스, 삼익THK, LS메카피온 등 제조로봇 및 핵심 부품 기업이 집적돼 있고, 일본 야스카와전기와 독일 쿠카로보틱스 등 글로벌 기업의 거점도 운영 중이다. 여기에 한국로봇산업진흥원, 한국기계연구원 대구융합기술연구센터, 대구기계부품연구원 등 연구 인프라가 갖춰져 있어 ''선도기업–공급기업–연구기관'' 삼각 구조를 형성하고 있다는 점이 강점이다.대구기계부품연구원 관계자는 "특화단지가 지정되면 휴머노이드 로봇 분야에 국비 예산이 집중되고 기업의 과제 수주 경쟁력이 높아진다"며 "신규 투자와 기업 이전을 유도하는 산업 생태계 확장 효과가 기대된다"고 말했다.', NULL, '매일신문', 'https://n.news.naver.com/mnews/article/088/0000998920', 'https://imgnews.pstatic.net/image/088/2026/03/01/0000998920_001_20260301194813021.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-01 13:46:09', 0, true, '2026-03-09 06:19:05.000037') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1035, '"제조업에 로봇AI 성장엔진"…대구 산업지도 다시 그린다', 'AX기술개발에 5510억 투입글로벌 혁신특구로 규제 특례비수도권 최대 ''AI 엔진''기대국가로봇테스트필드도 조성대구시가 로봇과 AI(인공지능) 산업 인프라스트럭처를 기반으로 ''글로벌 AX(인공지능 전환) 선도 도시''로 힘찬 비상을 준비 중이다. 사진은 대구시 전경.  대구시대구는 ''로봇 도시''다. 로봇 기업과 종사자 수는 수도권(서울·경기·인천)을 제외하고 비수도권 중에서 가장 많고 로봇 기업 매출액 역시 수도권과 경남에 이어 전국 4위다.대구시에 따르면 대구 지역 로봇 기업은 2023년 기준 251개사로 전국(4521개사) 대비 5.6%를 차지하고 있다. 종사자 수도 2859명으로 전국(5만1758명)의 5.5% 수준이다. 특히 대구 지역 로봇 기업의 매출액 비중은 1조2313억원으로 전국(10조2567억원) 대비 12%의 비중을 차지한다. 이는 대구에 HD현대로보틱스, 삼익THK 등을 비롯해 일본의 야스카와전기, 독일의 쿠카로보틱스, 스위스의 ABB 등 글로벌 로봇 기업들이 밀집해 있는 덕분이다.대구의 로봇 기업은 제조로봇 등 하드웨어 중심으로 발달한 것이 특징이다. 대구는 주력 제조업이 자동차부품, 기계금속 등으로 로봇 산업의 안정적인 수요처와 실증 기반을 갖추고 있다. 대구에는 한국로봇산업진흥원 등을 비롯해 한국전자통신연구원, 한국기계연구원 등 풍부한 로봇 관련 연구기관들도 있다. 이 같은 로봇 산업 기반 위에 대구는 인공지능(AI) 산업 기반도 우수하다. 대표적인 곳이 수성알파시티다. 수성알파시티는 2019년 기업 입주가 시작된 이후 현재 270여 개 정보통신기술(ICT) 기업과 종사자 6000여 명이 근무하는 비수도권 최대 ICT 기업 집적단지다. 2022년부터 최근 3년간 수성알파시티에 투자한 기업은 14곳, 투자액은 1조2133억원에 달한다.대구시가 이 같은 우수한 인프라스트럭처를 기반으로 ''글로벌 AX(인공지능 전환) 선도도시''로 힘찬 비상을 준비 중이다. 로봇 산업과 AI 산업 기반을 활용해 ''제조 AI 전환(M.AX)''에 적극 나서고 있기 때문이다.대표적인 사업이 ''AI 로봇 글로벌 혁신특구'' 조성이다. 지난해 대구시는 중소벤처기업부로부터 국내에서 유일하게 ''AI로봇 글로벌 혁신특구''에 지정됐다. 이 사업은 2028년까지 총 248억원을 투입해 기업들의 신제품 개발과 해외 진출을 위한 규제특례, 해외 실증 및 인증 등 각종 혜택을 지원하는 사업이다. 특구는 테크노폴리스를 중심으로 하는 첨단 제조존과 수성알파시티 중심의 AI 혁신존으로 운영된다.대구시는 국가 AX 혁신거점 도약의 발판도 마련했다. 지난해 전국에서 유일하게 ''지역거점 AX 혁신 기술개발'' 사업에 대한 예비타당성조사 면제가 확정돼 AX 사업에 탄력을 받았기 때문이다. 이 사업은 대구 지역 특화 산업인 로봇, 바이오, 헬스케어 분야의 AI 전환 가속화를 위해 AX 연구개발(R&D) 허브 조성 및 핵심 기술 개발을 지원하는 사업이다. 올해부터 2030년까지 사업비만 5510억원이 투입된다.AX 지원을 위한 인프라스트럭처도 확대 중이다. 대구시는 AX혁신기술 개발 등 AI 활용 맞춤형 분석을 위해 그래픽처리장치(GPU) 1200장을 구축할 예정이다. 또 2028년에는 SK AI 데이터센터 구축도 예정돼 있어 대규모 데이터 저장·처리 및 AI 학습 등을 지원한다. 수성알파시티도 1조1000억원을 투입해 기존 99만㎡에서 158만㎡로 확장한다. 2028년 착공해 2030년 제2수성알파시티를 분양할 계획이다.AI 전문인력과 지역 정착을 위해서도 대구경북과학기술원(DGIST)이 수성알파시티에 글로벌 캠퍼스를 조성 중이며 2028년 준공을 목표로 하고 있다. 경북대 SW융합캠퍼스도 수성알파시티에 조성해 맞춤형 계약학과(ICT융합학과)를 신설한다.대구시는 지난해 중소벤처기업부 공모에 선정된 ''지역특화 제조데이터 활성화사업''도 올해부터 본격 추진한다. 이 사업은 중소기업의 AI 및 제조 데이터 도입·활용을 체계적으로 지원해 현장의 디지털 전환을 촉진하는 것이 핵심이다. 특히 지난해 정부가 발표한 ''AI 기반 스마트제조혁신 3.0 전략''과 발맞춰 지역 제조 산업의 체질을 근본적으로 개선하는 계기가 될 것으로 기대된다. .대구시는 AI 로봇과 자율주행, 제조 AX를 위한 필수 부품인 센서 산업 육성을 위해 ''지능형 센서 생산 거점''도 조성 중이다. 이를 위해 R&D부터 양산까지 센서 전 주기 기업 지원 시스템을 구축하기 위해 2024년 개소한 DGIST 센소리움연구소에서는 R&D 검증을 하고 시제품 제작 및 양산은 D-FAB이 담당할 예정이다.대구시는 달성군에 1997억원을 들여 전국 유일의 국가로봇테스트필드 조성 사업도 추진 중이다. 이곳에서는 휴머노이드 로봇 상용화에 대비한 안전성 평가와 인증 지원이 이뤄진다. 이를 위해 테스트필드 안에는 2028년까지 휴머노이드 로봇 안전인증센터가 조성되고 로봇산업기술혁신센터(가칭)도 2029년 착공된다.대구시장 권한대행 김정기 행정부시장도 "수도권 일극 체제 극복과 지역 중심 경제 성장을 향한 정부의 강력한 의지에 감사하다"며 "대구가 제안한 성장 엔진 산업들이 지역경제를 부흥하는 핵심 열쇠로 작동할 수 있도록 지역의 혁신 역량을 결집하는 노력을 하겠다"고 말했다.[대구 우성덕 기자]', NULL, '매일경제', 'https://n.news.naver.com/mnews/article/009/0005642584', 'https://imgnews.pstatic.net/image/009/2026/02/26/0005642584_001_20260226160714260.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-26 16:07:14', 0, true, '2026-03-09 06:19:05.000037') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1036, '로봇은 여기서 움직인다…삼익THK, 모션부품에서 로봇까지 확장', 'LM가이드 등 정밀 모션부품 생산라인 자동화 구축하드웨어 기술력 바탕 로봇 솔루션 영역 확대지난 11일 오전 삼익THK 테크노폴리스 공장. 작업자들이 LM가이드 가공 작업을 수행하고 있다. 정우태 기자지난 11일 찾은 삼익THK 대구 달성 테크노폴리스 공장. 내부는 예상 외로 소음이나 먼지가 없는 쾌적한 환경이었다. 간격이 넓은 생산라인 사이로 로봇 팔이 눈에 띄었다. 공정 상당수가 자동화가 이뤄져 작업 인력은 많지 않았지만 설비는 쉬지 않고 돌아갔다.이곳에서 생산하는 핵심 제품은 자동화 설비의 필수적인 LM가이드다. 금속 레일 위를 정밀하게 직선 이동하도록 돕는 장치로 반도체, 2차전지 등 신산업에 필수적인 제품이다. 미세한 회로를 그리는 것은 물론 정밀가공을 수행할 때 기계가 정해진 속도로 정확한 위치에 도달하도록 하는 직선운동을 가능케 한다.지난 11일 오전 삼익THK 테크노폴리스 공장 내 로봇 자동화 라인 모습. 정우태 기자생산은 원재로 열처리부터 연삭, 가공, 조립, 검사까지 한 공장에서 ''원 스톱''으로 이뤄진다. 6축 다관절 로봇이 LM가이드를 잡고 작업대 위에 올리자 함께 조립되는 볼을 고정하는 스크루가 생성됐다. 특히 자동 측정 시스템을 도입해 공정 단계마다 정밀도를 분석하는 것은 물론 불량을 즉식 선별해 신뢰도를 높이고 있다. 일부 공정은 아직 사람 손이 필요하지만 이 역시 자동화 전환이 함께 이뤄지고 있다.삼익THK는 반도체 등 첨단 공정 맞춤형 로봇 솔루션을 제공하며 자동화 설루션의 강자로 자리매김하고 있다.최근에는 로봇 분야로 사업 다각화를 추진하며 시장의 주목을 받고 있다. 반도체용 기판을 이송하는 산업용 로봇인 ''U-WTR''은 정확한 위치를 찾는 것은 물론 빠르고 정밀한 작업이 가능하다. 올해 초에는 사람 대신 반도체 공장 내에서 화학물질이 흐르는 배관을 청소해주는 로봇 개발에 착수했다.삼익THK가 개발한 휴머노이드 결합 자율이동로봇 ''NX-mobile AMR''. 삼익THK 제공회사는 휴머노이드 형상의 다관절 로봇이 결합한 AMR(자율이동로봇) 제품인 ''NX-mobile AMR''을 이달 초 열린 반도체 전시회 세미콘코리아 2026에서 공개했다. 해당 다관절 로봇을 기반으로 다양한 작업을 수행한다. 카메라로 주변 환경을 3차원으로 인식하고, 각 관절 끝단의 핸드 카메라를 통해 작업 대상물의 형상을 파악해 물품을 적재하거나, 반대로 물건의 위치를 확인하고 꺼내는 등 자율적인 동작이 가능하다.삼익THK 관계자는 "축적된 하드웨어 기술력을 바탕으로 로봇 산업 전반으로 영역을 확장하고 있다. 로봇이 차세대 핵심 성장의 동력이 될 것"이라고 강조했다.', NULL, '매일신문', 'https://n.news.naver.com/mnews/article/088/0000997799', 'https://imgnews.pstatic.net/image/088/2026/02/22/0000997799_001_20260222193511385.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-22 14:32:10', 0, true, '2026-03-09 06:19:05.000037') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1037, '[서울데이터랩]금일 코스피 거래량 1위 한국ANKOR유전 거래대금 689억 돌파', '코스피 거래량 상위 종목들이 전반적으로 엇갈린 흐름을 보인다.6일 한국거래소에 따르면, 한국ANKOR유전(152550)이 1억2160만주 이상 거래되며 코스피 종목 중 실시간 거래량 1위를 차지한다. 현재 주가는 588원으로, 시가총액 412억원 대비 68,922백만원의 거래대금을 기록하며 25.11% 폭등하고 있다. SK증권(001510)은 1,833원으로 5.16% 상승하며 거래량 1억1530만3949주를 기록하고 있으며, 시가총액 8,663억원 대비 거래대금은 218,264백만원이다.서울식품(004410)은 213원으로 9.79% 상승하며 1억936만1465주의 거래량을 보인다. 흥아해운(003280)은 2,675원으로 4.97% 하락하며 거래량 4,212만4799주를 기록하고 있다. 케이뱅크(279570)는 7,880원으로 5.40% 하락하며 3,496만4110주의 거래량을 나타낸다. 퍼스텍(010820)은 8,960원으로 16.06% 상승하며 2,906만4561주의 거래량을 기록하고 있다. 유니켐(011330)은 679원으로 10.07% 하락하며 2,646만9079주의 거래량을 보인다. 삼성전자(005930)는 184,700원으로 3.60% 하락하며 거래량 2,069만7292주를 기록하고 있다. 에이엔피(015260)는 680원으로 21.00% 폭등하며 1,562만3672주의 거래량을 보인다. 남선알미늄(008350)은 1,325원으로 6.03% 하락하며 1,541만4045주의 거래량을 기록하고 있다.한편 거래량 상위 20위권 종목들은 상상인증권(001290) ▲7.49%, 대한해운(005880) ▼5.58%, 신성이엔지(011930) ▲6.93%, 대원전선(006340) ▼2.39%, SH에너지화학(002360) ▼2.65%, KEC(092220) ▼6.39%, 한화솔루션(009830) ▲17.57%, 한온시스템(018880) ▲3.41%, 한화생명(088350) ▲3.74%, 극동유화(014530) ▼3.77% 등의 성적을 기록했다.주목할 만한 종목으로는 한화솔루션이 있다. 17.57% 상승하며 8,970,814주의 거래량을 기록 중이다. 거래대금은 443,349백만원으로 시가총액 89,728억원 대비 약 0.49%에 해당한다. 반면, 유니켐은 10.07% 하락하며 2,646만9079주의 거래량을 보이고 있다. 거래대금은 16,593백만원으로 시가총액 635억원 대비 약 2.61%에 해당한다.전체적으로 코스피 시장은 상승과 하락이 혼재된 모습을 보이며, 특히 일부 종목에서는 급등락이 관찰된다. 투자자들은 장 마감까지 변동성을 주시할 것으로 보인다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003623563', 'https://imgnews.pstatic.net/image/081/2026/03/06/0003623563_001_20260306135117562.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-06 13:51:17', 0, true, '2026-03-09 06:19:13.998985') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1038, '송원산업, 주당 300원 현금배당 결정', '[헤럴드경제=증권부] 송원산업은 보통주 1주당 300원의 현금 결산배당을 결정했다고 23일 공시했다.시가배당율은 3.19%이며 배당금총액은 72억원이다.', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002603738', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_SEMI', NULL, '2026-02-23 15:20:10', 0, true, '2026-03-09 06:19:19.733244') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1039, '대기업 CEO, 서연고 줄고 서성한 늘고…부산대 24명, 동아대 16명', '올해 기준 한국CXO 연구소 분석서연고 29.6%에서 29.1%부산대 영남대 비수도권 톱 경쟁2025년 기준 국내 매출 1000대 상장사 CEO 출신대별 현황. 한국CXO연구소올해 국내 1000대 기업 중 SKY(서울대·고려대·연세대) 대학 출신 최고경영자(CEO) 비율은 29.1%로 1년 새 0.5% 포인트 하락하며 7년 연속으로 20%대를 기록한 것으로 나타났다. 비수도권 대학 가운데에서는 부산대 24명, 동아대 16명을 배출한 것으로 조사됐다.기업분석전문 한국CXO연구소는 ‘2025년 국내 1000대 기업 CEO 출신대 및 전공 현황 분석’에서 이 결과가 나왔다고 22일 밝혔다. 상장사 매출액(개별 기준)을 기준으로 했다. 최고경영자(CEO)는 올해 반기보고서 기준으로 조사가 이뤄졌다.조사 대상자는 1407명이다. 이중 서울대 출신은 189명(13.4%)으로 가장 많았다. 하지만 서울대 출신 비중은 감소세였다. 2019년 15.2%에서 2020년 14.9%, 2023년 13.8%, 올해 13.4%로 하락했다. 서울대 빈자리를 외국대학 출신이 채웠다. 서울대에 이어 연세대(112명, 8%)와 고려대(108명, 7.7%) 순이었다. 다음으로 한양대(56명), 서강대(46명), 성균관대(38명), 인하대·중앙대(각 30명), 한국외국어대(27명, 부산대(24명), 경희대·동국대·영남대(각 23명) 순이었다.비수도권 대학 가운데에서 부산대가 가장 많은 CEO를 배출한 가운데 경북대(19명), 동아대(16명)도 15명 이상의 CEO를 배출한 지역 명문대로 위상을 굳혔다. 부산대 출신 가운데는 GS 홍순기 부회장(경제학), 두산에너빌리티 정연인 부회장(기계설계학), 한진 노삼석 사장(무역학), 금호석유화학 백종훈 사장(화학공학), 고려아연 박기덕 사장(경영학)이 이름을 올렸다.동아대 출신 가운데 경동나비엔 손연호 회장(공업경영학), 넥센 강병중 회장(법학), 대웅제약 이창재 대표이사(중문학), 송원산업 김충식 대표이사(경영학), 아주스틸 이현식(금속공학)이 포함됐다.올해 조사에서 1000대 기업 CEO 대학별 전공 현황까지 파악한 969명 중 이공계 출신 비율은 46.6%(452명)인 것으로 나타났다. 작년보다 1.1% 포인트 정도 증가했다. 이번 조사 대상자 중 학부 대학 전공까지 파악이 가능한 CEO(969명 대상) 중 경영학도 출신은 22.8%(221명)로 가장 많았다. 다음으로 화학공학(화학 포함) 8.5%(82명), 경제학 8.3%(80명) 순이었다. 화학계열 전공자가 경제학 출신보다 역전한 것은 처음이다. 이어 전기·전자공학 7.1%(69명), 기계공학 6.3%(61명) 순으로 5%를 상회했다.한국CXO연구소 오일선 연구소장은 “1000대 기업 대표이사급 최고경영자 중에는 외국 대학을 나온 CEO도 올해 조사에서 110명을 넘어섰다”며 “향후 4~5년 내 외국인을 포함해 외국 대학을 나온 1000대 기업 CEO는 10명 중 1명꼴로 활약할 가능성이 높아질 것으로 예상된다”고 말했다.', NULL, '국제신문', 'https://n.news.naver.com/mnews/article/658/0000129932', 'https://imgnews.pstatic.net/image/658/2025/12/22/0000129932_001_20251222105010220.jpg?type=w800', 'NEWS_SEMI', NULL, '2025-12-22 10:49:09', 0, true, '2026-03-09 06:19:19.733244') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1040, '송원산업, 3분기 영업익 54억…전년비 75.7% ↓', '[헤럴드경제=증권부] 송원산업은 3분기 연결기준 영업이익이 53억9100만원으로 전년동기대비 75.7% 감소했다고 31일 공시했다.같은 기간 매출액은 2586억1600만원으로 9.5% 줄어든 것으로 나타났다.당기순이익은 16억9700만원으로 85.2% 감소한 것으로 잠정 집계됐다.', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002550830', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_SEMI', NULL, '2025-10-31 15:25:07', 0, true, '2026-03-09 06:19:19.733244') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1041, '[서울데이터랩]‘성문전자’ 29.97% 상한가 금일 증시 상승률 1위로 마감', '31일 오후 3시 35분 성문전자(014910)가 등락률 +29.97%로 상승률 1위로 마감했다. 성문전자는 장 중 5,890,163주가 거래되었으며 주가는 전 거래일 대비 350원 오른 1,518원에 마감했다.한편 성문전자의 PER은 11.59로 상대적으로 저평가를 받고 있을 가능성을 시사하며, ROE는 7.00%로 수익성이 낮다고 보기에는 무리가 있는 준수한 수준이나 고성장 기업과 비교했을 때는 보통 수준일 수 있다.이어 상승률 2위 성문전자우(014915)는 주가가 29.86% 폭등하며 종가 6,350원에 상승 마감했다. 상승률 3위 태영건설우(009415)의 주가는 13,500원으로 13.83% 급등했다. 상승률 4위 형지엘리트(093240)는 13.43% 급등하며 1,698원에 마감했다. 상승률 5위 무학(033920)은 13.31%의 상승세를 타고 9,450원에 마감했다.6위 일성건설(013360)은 2,220원으로 11.78% 급등 마감했다. 7위 동부건설우(005965)는 종가 24,550원으로 11.59% 급등 마감했다. 8위 코리아써키트(007810)는 종가 48,300원으로 10.65% 상승 마감했다. 9위 삼일씨엔에스(004440)는 5,990원으로 8.71% 상승 마감했다. 10위 코리아써우(007815)는 14,000원으로 8.53% 상승 마감했다.이밖에도 한진칼우(18064K) ▲7.81%, 삼화페인트(000390) ▲7.33%, 현대리바트(079430) ▲7.15%, HLB글로벌(003580) ▲6.67%, HDC(012630) ▲6.55%, 녹십자(006280) ▲6.50%, 현대오토에버(307950) ▲6.41%, 금호건설우(002995) ▲6.38%, SK스퀘어(402340) ▲6.36%, HDC현대산업개발(294870) ▲5.80% 등을 기록하며 금일 증시를 상승으로 마감했다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003605374', 'https://imgnews.pstatic.net/image/081/2025/12/31/0003605374_001_20251231160110967.png?type=w800', 'NEWS_ENERGY', NULL, '2025-12-31 16:01:10', 0, true, '2026-03-09 06:19:28.565730') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1042, '[서울데이터랩]성문전자 29.97% 상한가…금일 증시 상승률 1위로 마감', '30일 오후 15시 35분 성문전자(014910)(001510)가 등락률 +29.97%로 상승률 1위로 마감했다. 성문전자는 장 중 5,890,143주가 거래되었으며 주가는 공모가 대비 350원 오른 1,518원에 마감했다.한편 성문전자의 PER은 11.59로 상대적으로 저평가를 받고 있을 가능성을 시사하며, ROE는 7.0%로 수익성이 낮다고 보기에는 무리가 있는 준수한 수준이나 고성장 기업과 비교했을 때는 보통 수준일 수 있다.이어 상승률 2위 성문전자우(014915)는 주가가 29.86% 폭등하며 종가 6,350원에 상승 마감했다. 상승률 3위 태영건설우(009415)의 주가는 13,500원으로 13.83% 급등하며 강세를 보였다. 상승률 4위 형지엘리트(093240)는 13.43% 상승하며 1,698원에 마감했다. 상승률 5위 무학(033920)은 13.31%의 상승세를 타고 종가 9,450원에 마감했다.6위 일성건설(013360)은 종가 2,220원으로 11.78% 상승 마감했다. 7위 동부건설우(005965)는 종가 24,550원으로 11.59% 상승 마감했다. 8위 코리아써키트(007810)는 종가 48,300원으로 10.65% 상승 마감했다. 9위 삼일씨엔에스(004440)는 종가 5,990원으로 8.71% 상승 마감했다. 10위 코리아써우(007815)는 종가 14,000원으로 8.53% 상승 마감했다.이밖에도 한진칼우(18064K) ▲7.81%, 삼화페인트(000390) ▲7.33%, 현대리바트(079430) ▲7.15%, HLB글로벌(003580) ▲6.67%, HDC(012630) ▲6.55%, 녹십자(006280) ▲6.50%, 현대오토에버(307950) ▲6.41%, 금호건설우(002995) ▲6.38%, SK스퀘어(402340) ▲6.36%, HDC현대산업개발(294870) ▲5.80% 등을 기록하며 금일 증시를 상승으로 마감했다.전문가는 “성문전자의 급등은 최근 전자 부품 산업의 회복세에 따른 투자자들의 기대감이 반영된 결과로 보인다”고 밝혔다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003605069', 'https://imgnews.pstatic.net/image/081/2025/12/30/0003605069_001_20251230161221311.png?type=w800', 'NEWS_ENERGY', NULL, '2025-12-30 16:12:21', 0, true, '2026-03-09 06:19:28.565730') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1061, '[서울데이터랩]일동홀딩스 29.97% 상한가…금일 증시 상승률 1위로 마감', '7일 오후 15시 35분 일동홀딩스(000230)가 등락률 +29.97%로 상한가를 기록하며 상승률 1위로 마감했다. 일동홀딩스는 장 중 2,177,935주가 거래되었으며 주가는 전 거래일 대비 2,200원 오른 9,540원에 마감했다.한편 일동홀딩스의 PER은 1.71로 상당히 저평가된 수준을 시사하며, ROE는 72.94%로 매우 높은 수익성을 나타내어 투자 매력이 높음을 보여준다.이어 상승률 2위 일동제약(249420)은 주가가 29.95% 폭등하며 종가 18,050원에 상승 마감했다. 상승률 3위 동양생명(082640)의 주가는 7,880원으로 19.21% 급등하며 강세를 보였다. 상승률 4위 GS피앤엘(499790)은 12.82% 상승하며 39,600원에 마감했다. 상승률 5위 제이에스코퍼레이션(194370)은 11.11%의 상승세를 타고 종가 13,600원에 마감했다.6위 달바글로벌(483650)은 종가 195,100원으로 10.29% 상승 마감했다. 7위 평화홀딩스(010770)는 종가 5,850원으로 9.96% 상승 마감했다. 8위 에이피알(278470)은 종가 149,500원으로 8.49% 상승 마감했다. 9위 제주은행(006220)은 종가 14,990원으로 8.47% 상승 마감했다. 10위 세아베스틸지주(001430)는 종가 33,450원으로 8.25% 상승 마감했다.이밖에도 씨아이테크(004920) ▲7.63%, 써니전자(004770) ▲7.18%, 동국제강(460860) ▲7.18%, 동방(004140) ▲7.17%, 팜스코(036580) ▲6.92%, 자화전자(033240) ▲6.89%, SNT모티브(064960) ▲6.75%, 더존비즈온(012510) ▲6.71%, 해태제과식품(101530) ▲6.38%, 선진(136490) ▲6.01% 등을 기록하며 금일 증시를 상승으로 마감했다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003555627', 'https://imgnews.pstatic.net/image/081/2025/07/07/0003555627_001_20250707161113206.png?type=w800', 'NEWS_ETC', NULL, '2025-07-07 16:11:13', 0, true, '2026-03-09 06:20:26.475040') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1043, '[서울데이터랩]금일 코스피 거래량 1위 형지엘리트 급등세 거래대금 1,045억 돌파', '코스피 거래량 상위 종목들이 전반적으로 엇갈린 흐름을 보인다.30일 한국거래소에 따르면, 형지엘리트(093240)가 6,228만 주 이상 거래되며 코스피 종목 중 실시간 거래량 1위를 차지한다. 현재 주가는 1,732원으로, 시가총액의 15.73%에 해당하는 거래대금을 기록하며 15.70%의 급등세를 보이고 있다. PER은 19.68, ROE는 -1.56으로 재무 지표에서 다소 불안정한 모습을 보인다. 남선알미늄(008350)는 2,779만 주 이상 거래되며 거래량 2위를 기록하고 있으며, 현재 주가는 1,324원, 등락률은 -3.29%다. 거래대금은 시가총액 대비 2.23%에 해당한다.일성건설(013360)는 1,501만 주가 거래되며 19.84%의 급등세를 보이고 있다. 현재가는 2,380원이다. 삼성전자(005930)는 1,184만 주가 거래되며 현재가는 120,450원으로, 0.79%의 보합세를 기록하고 있다. 성문전자(014910)의 현재가는 1,518원으로 29.97%의 상한가를 기록하며 574만 주가 거래되었다. 삼화페인트(000390)(7,670원, +6.09%, 510만 주), 삼일씨엔에스(004440)(6,370원, +15.61%, 460만 주), 한화갤러리아(452260)(1,402원, -0.78%, 412만 주), 동양(001520)(847원, +0.47%, 299만 주), 태영건설(009410)(1,750원, +1.92%, 254만 주) 등의 순이다.한편, 거래량 상위 20위권 종목들은 SK하이닉스(000660) ▲1.56%, 이구산업(025820) ▼8.54%, 경인양행(012610) ▼6.26%, 티엠씨(217590) ▼16.53%, 현대약품(004310) ▼0.23%, 조일알미늄(018470) ▼4.74%, 한국전력(015760) ▲0.11%, 인스코비(006490) ▼9.77%, HL만도(204320) ▲3.56%, 두산에너빌리티(034020) ▼0.65% 등의 성적을 기록했다.주목할 만한 종목으로는 급등세를 보인 성문전자와 일성건설가 있다. 성문전자는 29.97%의 상한가를 기록하며, 거래대금은 8,200백만원으로 시가총액의 2.41%를 차지하고 있다. 일성건설는 19.84%의 급등세와 함께 거래대금은 35,453백만원으로 시가총액의 2.76%를 차지한다. 반면, 큰 하락을 보인 티엠씨와 이구산업는 각각 16.53%와 8.54% 하락하며, 거래대금은 시가총액 대비 0.89%와 6.67%를 기록하고 있다.전체적으로 코스피 시장은 상한가와 급등 종목이 다수 존재하는 가운데, 일부 종목의 급락도 함께 나타나는 혼조세를 보이고 있다. 시장의 변동성이 커진 만큼 투자자들의 신중한 판단이 요구된다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003605010', 'https://imgnews.pstatic.net/image/081/2025/12/30/0003605010_001_20251230135628882.png?type=w800', 'NEWS_ENERGY', NULL, '2025-12-30 13:56:28', 0, true, '2026-03-09 06:19:28.565730') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1044, '삼화왕관, 13억 규모 결산배당 실시…주당 700원 현금배당', '삼화왕관이 결산배당으로 현금배당을 실시한다.삼화왕관은 보통주 1주당 700원의 현금배당을 결정했다고 3일 공시했다. 시가배당률은 2.3%이며 배당금 총액은 13억4125만8100원 규모다.이번 배당은 2025년 12월31일을 배당기준일로 하며 배당금 총액은 자사주 23만8296주를 제외하고 산정됐다. 이사회에는 사외이사 1명이 참석했으며 감사의 참석도 이루어졌다.주주총회 예정일은 추후 소집 이사회에서 확정할 예정이며 배당금은 주주총회 결의 후 1개월 이내에 지급될 예정이다. 삼화왕관은 "배당금은 재무제표 승인 과정에서 일부 변동될 수 있다"고 설명했다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000080189', 'https://imgnews.pstatic.net/image/293/2026/03/03/0000080189_001_20260303155108454.png?type=w800', 'NEWS_ETC', NULL, '2026-03-03 15:51:08', 0, true, '2026-03-09 06:19:36.017587') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1045, '자사주 교환 나선 제약바이오사…의결권 지키고 시너지 높이고', '최근 지분 교환 등으로 자사주 처분한 제약바이오사/그래픽=윤선정자사주 소각을 의무화하는 법안이 추진되면서 제약사들이 서둘러 자사주 활용하기에 나섰다. 자사주를 서로 교환하면서 경영권을 방어하고 타사와 협업을 강화해 사업 동반 상승 효과(시너지)를 강화한다는 취지다.26일 제약업계, 금융감독원 전자공시시스템에 따르면 광동제약은 지난 24일 자사주 664만5406주를 약 397억원에 처분했다고 공시했다. 대웅, 휴온스그룹 자회사인 휴메딕스에 각각 230만9151주, 232만9567주를 넘기며 자사주를 맞교환한다. 이를 통해 광동제약은 대웅 58만1420주, 휴메딕스 33만6900주를 취득했다. 나머지 광동제약 주식 200만6688주는 120억원 규모에 동원시스템즈에 매각했다.광동제약은 "휴메딕스, 대웅 간 전략적 제휴 관계를 강화해 중장기적인 안정적 생산기반 마련 및 미래 수익 사업 강화 등 사업 시너지 창출을 목적으로 당사가 보유한 자기주식을 교환하는 건"이라며 "동원시스템즈의 경우 동일 목적으로 당사가 보유한 자기주식을 처분하는 건"이라고 설명했다.광동제약은 대웅과 주식 교환으로 공동마케팅 협력과 연구개발의 공동참여로 전문의약품 사업에서 성장을 제고하겠다는 계획이다. 휴메딕스와 자사주 교환으로는 안과 사업과 주사제 사업에서의 사업 협력으로 다양한 제품군을 확보해 수익성 증대화를 꾀한다는 방침이다. 앞서 광동제약은 지난 9월에도 금비, 삼화왕관과 자사주를 교환했다.아울러 광동제약은 약 156억7400만원 규모의 자사주 262만1043주를 내년 1월9일 소각할 예정이라고 밝혔다. 주주가치 제고를 위해서다.이 같은 광동제약의 움직임은 자사주 소각을 의무화하는 상법 개정을 앞두고 선제적으로 조치를 취한 것으로 해석된다. 현재 국회에서는 자사주 소각을 의무화하는 상법 개정안을 추진하고 있다. 이 개정안이 시행되면 기업들은 더 이상 자사주를 지배주주를 위한 경영권 방어 등에 쓰지 못한다. 그런데 이에 앞서 자사주를 다른 회사 주식으로 교환하면 의결권이 살아나면서 지배력을 강화할 수 있게 된다. 다른 회사의 자사주를 취득하면서 협력 관계도 강화할 수 있다. 이에 기업들이 서둘러 자사주를 처분하는 것으로 풀이된다.다른 제약바이오사들도 자사주 교환 행렬에 동참했다. 한국유나이티드제약은 지난 19일 환인제약과 자사주를 교환했다. 43만5000주의 자사주는 기타 특수관계사 한국바이오켐제약에 매각했다. 환인제약은 지난 12일 약 154억원 규모의 자사주 131만6880주를 동국제약, 경동제약, 진양제약 등의 자사주와 교환했다.이밖에 삼진제약은 일성아이에스와 자사주를 교환했고, 국제약품은 일동홀딩스와, 엘앤씨바이오는 휴메딕스와 자사주를 각각 맞바꿨다.제약업계 관계자는 "자사주를 소각할 경우 보유 지분이 줄고 지배력이 약해지는데 자사주를 다른 회사와 서로 교환하면 경영 안정성을 확보하면서 사업적 협력의 가능성도 생기는 효과가 생기기 때문에 회사들이 자사주 교환을 선택한 것으로 보인다"고 말했다. 다만 일각에선 이 같은 행보가 소액주주의 불만을 살 수 있다고 본다. 자사주 소각을 통한 주주가치 제고보다는 규제를 피하기 위한 ''꼼수''를 썼다는 시각에서다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005296867', 'https://imgnews.pstatic.net/image/008/2025/12/26/0005296867_001_20251226073015380.jpg?type=w800', 'NEWS_ETC', NULL, '2025-12-26 07:30:00', 0, true, '2026-03-09 06:19:36.017587') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1046, '세방전지, 조직문화 혁신 이끌 ‘로케트보드’ 공식 출범', '세방전지㈜(대표이사 박정희)는 2월 26일(목), 세방그룹 본사에서 조직문화 혁신을 이끌 제3기 ‘로케트보드(ROCKET BOARD)’ 발대식을 개최하고 공식 출범을 알렸다.‘로케트보드’는 기존 ‘주니어보드’의 운영 취지와 성과를 계승·발전시킨 조직문화 활성화 프로그램으로, 사원부터 책임급 구성원으로 이루어진 차세대 리더 그룹이다. 2년 전 1기를 시작으로 2기 활동까지 성공적으로 운영된 주니어보드는 전사 구성원과의 수평적 소통을 기반으로 세방전지만의 바람직한 기업문화 구축을 이끌어 왔다.올해부터는 세방전지의 대표 브랜드인 ‘로케트(Rocket)’의 상징성을 반영해 명칭을 ‘로케트보드’로 변경했다. 이는 구성원의 아이디어와 실행력이 조직의 추진력이 되어, 기업문화 혁신을 가속화하겠다는 의미를 담고 있다.세방전지는 최근 급변하는 경영환경 속에서 ‘생존과 성장’을 핵심 화두로 삼고 있다. 이에 따라 새로운 업무 방식 정립과 조직문화 활성화의 필요성이 더욱 커지고 있으며, 로케트보드는 이러한 변화의 중심에서 성과 창출을 견인하는 ‘체인지 에이전트(Change Agent)’로 활동하게 된다.로케트보드는 ▲구성원들의 다양한 의견을 경영진에 전달하는 수평적 소통 채널 활성화 ▲조직문화 개선을 위한 진단 및 아이디어 발굴 ▲부문·부서·구성원 간 협업 강화를 통한 업무 생산성 향상 등을 주요 목표로 한다.그동안 주니어보드는 실질적인 변화를 이끌어내는 다양한 활동을 전개해 왔다. 대표적으로 ▲불필요한 회의를 줄이기 위한 ‘회의 ZERO-DAY’ 운영 ▲업무 스케줄러 활용 확대 ▲AI 회의록 도입 ▲회의·보고 간소화 가이드 전파 ▲리버스 멘토링 ▲사업장별 원팀(One-Team) 데이 운영 ▲SMART-WORK 영상 제작 ▲‘세방전지 착한 동료상’ 운영 등 구체적인 실행 과제를 통해 업무 효율성과 소통 문화를 동시에 개선해 왔다.이번 3기 로케트보드는 기존 활동 성과를 기반으로 디지털 기반의 스마트워크 확산과 실질적인 협업 문화 정착에 더욱 박차를 가할 계획이다. 특히 현장의 목소리를 신속하게 수렴하고 실행 과제로 연결하는 구조를 강화해, 조직 전반의 변화 체감도를 높인다는 방침이다.세방전지 관계자는 “로케트보드는 단순한 참여 프로그램이 아니라, 세방전지의 미래 기업문화를 설계하는 실행 조직”이라며 “젊은 구성원들의 도전적이고 창의적인 아이디어가 조직의 성장 동력으로 이어질 수 있도록 적극 지원하겠다”고 밝혔다.', NULL, '한국경제TV', 'https://n.news.naver.com/mnews/article/215/0001243831', 'https://imgnews.pstatic.net/image/215/2026/03/04/A202603040379_1_20260304133711364.png?type=w800', 'NEWS_ENERGY', NULL, '2026-03-04 13:37:02', 0, true, '2026-03-09 06:19:43.300836') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1047, '[서울데이터랩]‘미래에셋생명’ 30% 상한가…실시간 상승률 1위', '23일 오전 9시 10분 미래에셋생명(085620)가 등락률 +30.00%로 상한가를 기록하며 상승률 1위를 차지했다. 미래에셋생명은 개장 직후 5분간 33만 7571주가 거래되었으며 주가는 공모가 대비 3720원 오른 1만 6120원이다.한편 미래에셋생명의 PER은 15.49로 보통 수준이며, ROE는 4.88%로 수익성이 다소 낮은 편이다.이어 상승률 2위 SG세계물산(004060)은 현재가 749원으로 주가가 26.73% 폭등하고 있다. 상승률 3위 더존비즈온(012510)은 현재 11만 8500원으로 23.44% 폭등하며 강세를 보이고 있다. 상승률 4위 에이엔피(015260)는 16.77% 급등하며 550원에 거래되고 있다. 상승률 5위 롯데손해보험(000400)은 16.24%의 상승세를 타고 2935원에 거래되고 있다.6위 텔코웨어(078000)는 현재가 1만 8620원으로 14.66% 상승 중이다. 7위 영흥(012160)은 현재가 707원으로 13.67% 상승 중이다. 8위 한국ANKOR유전(152550)은 현재가 269원으로 13.50% 상승 중이다. 9위 삼화콘덴서(001820)는 현재가 4만 9650원으로 13.23% 상승 중이다. 10위 삼성전기우(009155)는 현재가 17만 1900원으로 13.09% 상승 중이다.이밖에도 대한조선(439260) ▲12.15%, 대원전선(006340) ▲11.59%, 흥국화재(000540) ▲10.76%, 넥센우(005725) ▲10.08%, 삼성전기(009150) ▲9.95%, 조광피혁(004700) ▲9.93%, 세방전지(004490) ▲9.39%, 일진전기(103590) ▲9.02%, DB(012030) ▲8.25%, 광동제약(009290) ▲7.98% 등을 기록하며 시장에서 활발히 거래되고 있다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003619804', 'https://imgnews.pstatic.net/image/081/2026/02/23/0003619804_001_20260223094313670.png?type=w800', 'NEWS_ENERGY', NULL, '2026-02-23 09:43:13', 0, true, '2026-03-09 06:19:43.300836') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1048, '세방전지, 지난해 영업익 1538억…전년비 14.4% ↓', '[헤럴드경제=증권부] 세방전지는 지난해 연결기준 영업이익이 1537억6358만원으로 전년대비 14.42% 감소했다고 9일 공시했다.같은 기간 매출액은 2조1420억6833만원으로 4.01% 증가한 것으로 나타났다.당기순이익은 1414억7327만원으로 17.9% 줄어든 것으로 집계됐다.', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002598285', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ENERGY', NULL, '2026-02-09 16:11:15', 0, true, '2026-03-09 06:19:43.300836') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1049, '“대통령 한 마디에”…편의점도 생리대 가격 인하', '세븐일레븐, 14일 ''순수한스페셜중형'' 생리대 출시...가격은 16개에 2900원. 개당 181원 수준.세븐일레븐이 출시한 ''순수한면스페셜중형 2종'' / 코리아세븐(세븐일레븐)세븐일레븐이 개당 181원 순면커버 생리대 2종을 출시할 예정이다. 앞서 정부가 “값싼 생리대를 왜 생산하지 않는가”라고 지적한 영향으로 분석된다.9일 코리아세븐에 따르면, 세븐일레븐은 깨끗한나라와 손잡고 업계 최저가 수준의 생리대를 출시한다. 개당 181원짜리 순면커버 생리대 2종이다.세븐일레븐이 오는 14일 출시하는 ‘순수한스페셜중형’은 16개에 2900원이다. 계산하면 개당 181원으로 일반 편의점 상품 대비 낮은 가격이다. 20일에는 ‘순수한면스페셜중형(4p)’을 900원에 내놓는다. 소분한 형태로 개당 225원 가격이다.편의점의 저가 생리대 출시는 올해 초 이재명 대통령이 생리대 가격을 지적한 영향으로 풀이된다. 이 대통령은 지난 1월 국무회의에서 “기본 품질을 갖춘 값싼 생리대는 왜 생산하지 않는가”라고 말했다.영국 런던 민간 연구기관(IBMNC)에 따르면 국내 생리대 가격은 조사 대상 30개국 중 7번째로 비싼 것으로 나타났다. 이에 국내 생리대 제조업체 유한킴벌리, LG유니참, 깨끗한나라 등이 생리대 가격을 낮추기로 결정했다.이후 유통업계에도 초저가 생리대 판매가 이어지고 있다. 전자상거래(이커머스) 플랫폼에서 쿠팡이 생리대를 개당 99원에 먼저 출시했다. 이어 홈플러스도 99원 수준의 제품을 내놓았다.이마트도 지난 3일 일부 생리대 제품을 최대 70% 할인된 가격으로 판매 시작했다. 이에 CU, GS25 등 편의점 업계도 ‘1+1’ 행사를 포함해 생리대 가격을 전반적으로 인하하고 있다.앞서 아성다이소(국내 다이소)는 깨끗한나라와 협업해 오는 5월 생리대를 개당 100원에 출시한다고 밝혔다. 기존 판매가 대비 최대 60% 낮은 가격이다.', NULL, '한경비즈니스', 'https://n.news.naver.com/mnews/article/050/0000103335', 'https://imgnews.pstatic.net/image/050/2026/03/09/0000103335_001_20260309141614757.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 14:16:14', 0, true, '2026-03-09 06:19:49.501571') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1050, '깨끗한나라, 세계 여성의 날 맞아 생리대 20만 개 기부', '깨끗한나라가 지난 8일 세계 여성의 날을 맞아 국제개발협력 NGO 지파운데이션과 함께 생리대 20만 개를 기부했다고 9일 밝혔다.이번 나눔은 세계 여성의 날과 오는 5월 28일 ‘세계 월경의 날’을 계기로 진행하는 사회공헌 활동의 일환으로, 여성의 건강한 일상을 응원하고 생애주기별 맞춤 지원을 실천하기 위해 마련됐다고 깨끗한나라는 설명했다.지원 물품은 취약계층 여성 청소년을 위한 ‘순수한면’, ‘디어스킨’ 생리대와 중장년층 여성을 위한 성인용 기저귀 ‘메디프렌즈’로 구성된다. 생리대는 지파운데이션을 통해 전달하며 메디프렌즈는 기빙플러스와 협력해 별도로 지원한다.이와 함께 깨끗한나라는 오는 5월 28일 세계 월경의 날을 맞아 지파운데이션이 주관하는 참여형 기부 캠페인 ‘런포더문’에 참여할 예정이다. 런포더문은 참가자들이 5.28km 또는 10km를 달리며 취약계층 여성의 건강한 월경을 응원하는 캠페인이다. 깨끗한나라는 해당 캠페인을 통해 위생용품을 기부하며 나눔 활동에 동참할 계획이다.깨끗한나라 관계자는 “위생용품은 여성의 일상을 지탱하는 기본적인 생활필수품”이라며 “여성 청소년부터 중장년층 여성까지 생애주기 전반에 걸쳐 실질적인 도움이 되는 지원을 지속해 나가겠다”고 말했다.깨끗한나라는 2019년부터 매년 여성 취약계층을 대상으로 생리대를 꾸준히 기부해 왔다. 누적 기부 수량은 200만 개에 달한다.', NULL, '동아일보', 'https://n.news.naver.com/mnews/article/020/0003702456', 'https://imgnews.pstatic.net/image/020/2026/03/09/0003702456_001_20260309141517374.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 14:15:17', 0, true, '2026-03-09 06:19:49.501571') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1051, '깨끗한나라 창립 60년…이젠 플랫폼 기업으로 거듭난다', 'AX기반 운영·의사결정 체계 강화데이터 중심 경영 등 미래비전 발표깨끗한나라는 창립 60주년을 맞아 제조 기반 경쟁력을 인공지능 전환(AX) 인프라로 고도화하고 기술과 데이터 역량을 강화해 생활 혁신 설루션 플랫폼 기업으로 도약하겠다는 미래 비전을 6일 발표했다.창립 60주년을 앞둔 최현수 깨끗한나라 회장은 “지난 60년 동안 수많은 경쟁과 위기, 산업 재편 속에서도 책임 있는 판단과 실행으로 현재의 기반을 만들었다”며 “플랫폼으로 연결되고 데이터로 고도화되며 실행으로 증명되는 체계를 통해 다음 60년을 준비하겠다”고 밝혔다.깨끗한나라는 기존 제조 경쟁력 중심 성장 기반 위에 AX를 핵심 인프라로 접목해 운영과 의사결정 체계를 고도화한다는 계획이다. AX는 단순한 기술 도입을 넘어 기업 운영 방식을 정교하게 개선하는 기반으로, 향후 사업 전반의 체질 개선을 뒷받침하는 역할을 하게 된다.사업부별 전략 방향도 제시됐다. HL(Home&Life) 사업부는 데이터 기반으로 브랜드와 고객 경험을 정교하게 연결하고 PS(Packaging Solution) 사업부는 친환경 설계와 공급망 역량을 강화해 패키징 설루션 경쟁력을 높여나갈 계획이다.공장 운영은 자동화와 데이터 기반 관리 체계를 강화하고 글로벌 공급망 관리(SCM) 최적화를 통해 시장 대응력을 높인다. 동시에 자원순환 체계와 에너지 전환을 병행해 지속가능한 성장 기반도 강화할 방침이다.깨끗한나라는 창립 60주년을 기념해 지난 60년의 변화와 주요 성과를 정리한 인포그래픽도 공개했다.자료에 따르면 1996년 이후 백판지 누적 생산량은 약 1042만톤을 기록했다. 깨끗한나라, 보솜이, 순수한면 등 26개 생활용품 브랜드를 중심으로 제품군을 확대하며 국내외 유통 채널을 확장해 현재 약 50개국 수출 네트워크를 구축했다.또 약 1900억원 규모의 친환경 설비 투자를 진행하며 제조 경쟁력과 환경 대응 역량을 강화하고 있다.인포그래픽에는 1966년 제지 산업 기반 구축을 시작으로 사업 다각화와 해외시장 진출, 생활용품 포트폴리오 확대, 생활문화 기업 전환, 생활 혁신 설루션 플랫폼 기업으로 이어지는 6단계 성장 과정도 제시됐다.깨끗한나라 관계자는 “창립 60주년을 계기로 회사의 변화 흐름을 다시 정리하고 향후 방향을 보다 명확히 설정했다”며 “제조 기반 경쟁력을 유지하면서 AX와 에너지, 데이터 중심 체계를 강화해 미래 경쟁력을 확보해 나가겠다”고 말했다. 홍석희 기자', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002610487', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2026-03-09 11:13:10', 0, true, '2026-03-09 06:19:49.501571') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1052, '[채용게시판] 한국전력거래소·현대비앤지스틸 등', '커리어 플랫폼 사람인 제공[파이낸셜뉴스] 한국전력거래소와 현대비앤지스틸, 한화에너지 등이 인재 확보에 나섰다.8일 커리어 플랫폼 사람인에 따르면 △한국전력거래소 △현대비앤지스틸 △한화에너지 △신한은행 △롯데케미칼 등이 신입 및 경력사원을 채용 중이다.우선 한국전력거래소는 2026년 상반기 공개채용을 실시한다. 모집부문은 △신입직(전기, IT) △전문경력직(전력경제, 전력계통, 발전·송전 설비운영, 기상빅데이터, 정보보안, 산업안전) △공무직(사무보조) △전문계약직(변호사, 공인회계사, 공인노무사) △체험형 청년인턴(사무, 전기, IT) 등이다. 전형절차는 △서류전형 △필기전형 △1차 면접전형 △2차 면접전형 △최종합격 예정자 선발 △최종합격자 선발 순이다. 전문계약직은 1차 면접전형 후 최종합격 순이다. 오는 13일 오전 10시까지 채용홈페이지로 지원하면 된다.현대비앤지스틸은 대졸신입사원과 채용전제형 인턴을 모집한다. 모집부문은 △회계(대졸신입사원) △경영지원(채용형인턴)이다. 전공과 무관하게 4년제 대학 이상 졸업자 또는 졸업예정자는 지원이 가능하다. 관련 전공자 및 외국어능력 우수자, 회계는 CPA 및 CTA 1차시험 합격자를 우대한다. 채용형인턴은 오는 8일까지, 대졸신입사원은 오는 15일까지 채용 홈페이지에서 지원이 가능하다.한화에너지는 2026년 상반기 신입사원을 공개 채용한다. 모집부문은 △기계·전기 △안전 △재무 등이다. 올해 6월 말부터 근무가 가능한 4년제 이상 대학 이상 졸업자 또는 졸업예정자는 지원 가능하며, 안전 분야는 산업안전기사 자격을 보유해야 한다. 관련 전공자, 기계·전기 분야는 일반기계기사, 에너지관리기사, 전기기사, 산업안전기사 등 전공 관련 자격 보유자를 우대한다. 전형절차는 △서류전형 △면접전형OT △1차면접 △2차면접 △최종합격 순이다. 오는 16일까지 채용 홈페이지에서 지원할 수 있다.신한은행은 경력직 채용을 진행한다. 모집부문은 글로벌 프로젝트 매니저다. 동종 업종 3년 이상 경력 보유자는 지원 가능하며, 관련 자격증 보유 및 국내·외 금융기관·회계법인 FAS 경력 보유자, 어학 역량 우수자는 우대한다. 전형절차는 △서류전형 △온라인 역량검사 △면접 △HR미팅(필요시) △채용검진을 거쳐 최종 합격자 발표이다. 오는 12일 오후 1시까지 지원이 가능하며, 채용 홈페이지로 지원하면 된다.롯데케미칼에서 신입사원 채용을 실시한다. 모집부문은 △글로벌영업 △기술영업 △연구개발(의왕, 여수) △생산관리 △안전환경(의왕, 여수) △공무(기계) △품질관리 △HR(의왕, 여수) △경영기획 등이다. 오는 7월 입사 가능한 4년제 대학 이상 졸업자 및 졸업예정자로, OPIc 및 TOEIC 스피킹 IH 수준 외국인 공인 회화 성적을 보유한 자는 지원 가능하다. 연구개발은 석사학위 소지자에 한한다. 영어 우수자 및 인사·노무 관련 자격 보유자는 우대한다. 전형절차는 △지원서 접수 △서류전형 △인적성전형 △면접전형 △건강검진을 거쳐 최종합격 순이다. 오는 17일까지 채용 홈페이지에서 접수하면 된다.', NULL, '파이낸셜뉴스', 'https://n.news.naver.com/mnews/article/014/0005487726', 'https://imgnews.pstatic.net/image/014/2026/03/08/0005487726_001_20260308123709105.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-08 12:37:09', 0, true, '2026-03-09 06:19:56.869418') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1053, '“이재명·정의선 새만금서 맞손”…현대차 10%·현대제철 20% ‘주가 날았다’ [종목Pick]', '현대차그룹 새만금에 9조원 투자로봇·AI 등 ‘미래 산업 거점’ 구축현대위아·현대비앤지스틸도 주가 급등이재명 대통령이 27일 전북 군산새만금컨벤션센터에서 열린 새만금 로봇·수소·AI 시티 투자협약식에서 기념촬영을 마친 뒤 정의선 현대차그룹 회장과 악수하고 있다. 배경훈(왼쪽부터) 부총리 겸 과기부 장관, 이재명 대통령, 정의선 현대차그룹 회장, 김윤덕 국토부 장관. [연합][헤럴드경제=김지윤 기자] 현대자동차그룹이 전북 새만금에 9조원을 투자해 로봇, 인공지능(AI), 수소 미래 산업 거점을 구축한다는 소식이 전해지면서 현대차 주가가 급등하고 있다.27일 오후 2시36분 현재 유가증권 시장에서 현대차는 전 거래일 대비 10.18% 오른 67만1000원에 거래되고 있다. 이날 오전 장중 60만원 선이 깨지며 3% 가까이 하락했지만, 새만금에 대한 대규모 투자 소식이 알려지면서 빠르게 반등, 신고가를 경신했다.이날 현대차그룹은 전북 군산 새만금컨벤션센터에서 정부·전북특별자치도와 ‘새만금 로봇·수소첨단산업 육성 및 AI 수소 시티 조성을 위한 투자협약(MOU)’을 맺었다.이번 협약으로 현대차그룹은 전북 새만금 지역에 총 9조원을 투입해 ▷로봇 제조 공장 ▷AI 데이터센터 ▷수전해 기반 그린 수소 생산 기지 ▷재생에너지 발전소 ▷수소 AI 시범도시 등 5개 생산 기지를 구축한다.이번 새만금 투자는 지난해 현대차그룹이 발표한 125조2000억원 규모의 국내 중장기 투자 계획 중 핵심 프로젝트로 꼽힌다. 이번 투자가 유발하는 경제효과는 약 16조원으로 추산되며, 7만1000명 규모의 직·간접 고용 창출 효과가 있을 것으로 분석된다.이번 투자 발표의 영향으로 그룹주 모두 강세를 보였다. 현대제철은 20.88% 급등한 4만6900원에 거래되고 있다. 현대위아(12.15%), 현대비앤지스틸(8.71%), 현대로템(6.14%), 현대오토에버(1.98%), 기아(1.70%) 등도 동반 강세를 보이고 있다.', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002606384', 'https://imgnews.pstatic.net/image/016/2026/02/27/0002606384_001_20260227150113792.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-27 15:01:13', 0, true, '2026-03-09 06:19:56.869418') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1054, '''새만금 9조'' 투자 시동 건 현대차…장중 66만6000원 신고가 질주', '특징주머니투데이 특징주 그래픽 이미지현대차그룹이 전북 새만금에 9조원을 투자해 로봇·AI(인공지능)·수소 미래 산업 거점을 구축한다는 소식이 전해지면서 주가가 급등하고 있다.27일 오후 1시17분 현재 코스피 시장에서 현대차는 전 거래일 대비 4만5000원(7.39%) 오른 65만4000원에 거래되고 있다. 현대차는 장 중 한 때 66만6000원까지 오르며 역대 최고가를 갈아치웠다.현대차 주가는 이날 오전까지 약보합권에 머무르다 대규모 투자 소식이 전해지면서 강세로 전환했다. 이날 현대차그룹은 전북 군산 새만금컨벤션센터에서 정부·전북특별자치도와 ''새만금 로봇·수소첨단산업 육성 및 AI 수소 시티 조성을 위한 투자협약(MOU)''을 맺었다. 이번 협약으로 현대차그룹은 전북 새만금 지역에 총 9조원을 투입해 △로봇 제조 공장 △AI 데이터센터 △수전해 기반 그린 수소 생산 기지 △재생에너지 발전소 △수소 AI 시범도시 등 5개 생산 기지를 구축한다.이번 새만금 투자는 지난해 현대차그룹이 발표한 125조2000억원 규모의 국내 중장기 투자 계획 중 핵심 프로젝트로 꼽힌다. 이번 투자가 유발하는 경제효과는 약 16조원으로 추산되며, 7만1000명 규모의 직·간접 고용 창출 효과가 있을 것으로 분석된다.이번 투자 발표 영향으로 현대제철(27.45%)·현대비앤지스틸(15.67%)·현대로템(8.05%)·현대위아(6.72%)·현대오토에버(5.35%) 등 현대차그룹주도 동반 강세를 보인다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005323387', 'https://imgnews.pstatic.net/image/008/2026/02/27/0005323387_001_20260227135215139.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-27 13:29:03', 0, true, '2026-03-09 06:19:56.869418') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1055, '삼천리, 주당 3000원 현금배당 결정', '[헤럴드경제=증권부] 삼천리는 보통주 1주당 3000원의 현금 결산배당을 결정했다고 5일 공시했다.시가배당율은 2%이며 배당금총액은 102억7208만원이다.', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002609056', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ENERGY', NULL, '2026-03-05 16:02:10', 0, true, '2026-03-09 06:20:03.584091') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1062, '[서울데이터랩]금일 코스피 거래량 1위 동방 거래대금 788억 돌파', '코스피 거래량 상위 종목들이 전반적으로 엇갈린 흐름을 보인다. 7일 한국거래소에 따르면, 동방(004140)가 2,387만주 이상 거래되며 코스피 종목 중 실시간 거래량 1위를 차지한다. 현재 주가는 3,265원으로, 시가총액의 5%에 해당하는 막대한 거래대금에 비해 8.83%의 상승률을 기록하고 있다. PER 9.72, ROE 13.73으로, 수급과 재무 지표 모두에서 안정적인 모습을 보인다. 매수세와 매도세가 접전을 펼치는 가운데 장 마감까지 많은 투자자들의 이목이 집중될 것으로 보인다. 동양철관(008970) 역시 1,474원으로 1.80% 하락하며, 거래량 1,328만9,099주를 기록한다.삼성전자(005930)는 6만2,400원으로 1.42% 하락하며, 거래량 858만6,104주를 기록한다. LG헬로비전(037560)는 현재가 3,050원, 7.99% 하락하며 648만3,751주 거래된다. KCTC(009070)는 6,250원으로 2.63% 상승하며 612만5,394주 거래되고 있다. 흥아해운(003280)는 1,795원으로 0.55% 하락, 거래량은 501만1,277주이다. 두산에너빌리티(034020)는 60,150원으로 0.25% 상승하며 423만1,933주 거래량을 기록한다. 서울식품(004410)는 169원으로 0.60% 상승하며 349만705주의 거래량을 보인다. 삼성중공업(010140)는 16,130원으로 2.61% 상승하며, 거래량이 337만542주로 나타난다. 미래에셋증권(006800)는 19,370원으로 0.05% 하락하며 280만7,321주가 거래된다.한편 거래량 상위 20위권 종목들은 한국전력(015760) ▲0.27%, 제주은행(006220) ▲6.80%, 신일전자(002700) ▼0.13%, 카카오(035720) ▲3.60%, 써니전자(004770) ▲6.95%, 카카오페이(377300) ▲4.68%, 형지엘리트(093240) ▼0.16%, SK증권(001510) ▲0.45%, 대한해운(005880) ▼0.82%, 한컴라이프케어(372910) ▼0.95% 등의 성적을 기록한다.특히, 상승률이 높은 종목으로는 제주은행와 써니전자가 있다. 제주은행는 시가총액 5,579백만원에 거래대금 40,794백만원, 거래량 2,733,159주로 6.80% 상승하고 있다. 써니전자는 시가총액 267,269백만원, 거래대금 138,684백만원, 거래량 2,321,980주로 3.60% 상승 중이다. 하락률이 높은 종목으로는 LG헬로비전와 KCTC가 있다. LG헬로비전는 시가총액 3,693,854백만원, 거래대금 537,009백만원, 거래량 8,586,104주로 1.42% 하락 중이며, KCTC는 시가총액 2,362백만원, 거래대금 19,815백만원, 거래량 6,483,751주로 7.99% 하락하고 있다.전체적으로 코스피 시장은 혼조세를 보이고 있다. 거래량 상위 종목들 간에 매수세와 매도세가 엇갈리며 투자자들의 주목을 받고 있다. 특히, 주목할 만한 종목들의 거래대금이 시가총액의 2%를 넘어서면서 투자 심리가 급격히 움직이고 있는 것으로 분석된다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003555536', 'https://imgnews.pstatic.net/image/081/2025/07/07/0003555536_001_20250707125625294.jpg?type=w800', 'NEWS_ETC', NULL, '2025-07-07 12:56:25', 0, true, '2026-03-09 06:20:26.475040') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1151, '미-이란 충돌에 군비 경쟁 가속화…방산주로 쏠린 투심', '오늘의 포인트[코나라크=AP/뉴시스] 미 위성업체 밴터(Vantor)가 제공한 위성 사진에 1일(현지 시간) 이란 코나라크에 있는 코나라크 공군 기지 격납고와 주변 건축물들이 미·이스라엘의 공습으로 파손돼 있다. 2026.03.02. /사진=민경찬미국과 이스라엘이 이란을 겨냥한 대규모 공습에 나서면서 중동 리스크가 급격히 부각되자, 국내 증시에서는 방산주가 일제히 급등했다. 전쟁 장기화 가능성은 높지 않다는 관측이 지배적이지만, 글로벌 군비 증강 흐름이 가속화될 것이란 기대가 커지며 투자자 자금이 방산주로 몰리는 모습이다.3일 코스피 시장에서 LIG넥스원은 전 거래일 대비 15만2000원(29.86%) 올라 상한가인 66만1000원에 거래를 마쳤다. LIG넥스원 신고가다. LIG넥스원은 이날 장 중 내내 상한가 부근에서 강세를 유지했다.LIG넥스원뿐만 아니라 방산업종 전반이 강세였다. 네이버 증권에 따르면 이날 우주항공과 방산업종은 전 거래일 대비 16.97% 올랐다. 라이다 등 항공기 부품을 공급하며 방산 및 민수 사업을 운영하는 빅텍도 이날 1320원(30.00%) 올라 상한가인 5720원으로 마무리했다.이밖에도 한화시스템(29.14%), RF머트리얼즈(20.33%), 삼양컴텍(20.22%), 한화에어로스페이스(19.83%), 퍼스텍(18.90%), 휴니드(13.36%), 코츠테크놀로지(9.27%), 그린광학(9.23%), RF시스템즈(8.78%), 현대로템(8.03%), 한국항공우주(3.19%) 등이 상승 마감했다.특히 한화에어로스페이스는 시총 8위 규모에도 장중 한 때 24.85% 오른 149만2000원까지 오르며 신고가를 경신했고, 한화시스템도 29.40% 오른 14만7000원으로 역대 최고가에 도달했다. 현대로템, RF머트리얼즈, 한국항공우주 등도 최고가를 갈아치웠다.방산주 강세는 지난달 28일(현지 시각) 미국과 이스라엘이 이란 공습을 시작하면서 지정학적 리스크가 커진 영향이다.이경민 대신증권 연구원은 "미국과 이스라엘은 이란 내 군사 시설과 정권 주요 거점을 겨냥한 대규모 합동 공습 ''사자의 표''효(Lion''s Roar) 작전을 시작했다"며 "이란의 최고지도자 아야톨라 알리 하메네이를 사살하는 사상 유례없는 공격을 단행했고 이란도 보복에 나서며 지정학적 리스크 확대됐지만, 현재로서는 1개월 이내 단기간에 상황이 진정되거나 마무리될 것으로 예상된다"업계는 이란 최고 지도자 하메네이가 사망한 만큼 전쟁이 장기화되지는 않을 것으로 내다보고 있지만, 이란이 헤즈볼라와 손잡고 반격하면서 불확실성에 대한 대비를 위해 글로벌 방산 투자가 더욱 확대될 것으로 내다봤다.채운샘 하나증권 연구원은 "글로벌 방산 투자 관점에서 이번 미국·이스라엘의 이란 공격은 △트럼프 대통령이 주장하는 2027년 미국 국방예산 1조5000억 달러 증액(2026년 대비 66% 확대) 당위성 강화 △전쟁 조기 종료에도 이란 후속 공격 가능성과 역내 불확실성에 대비한 중동 지역의 무기 수입의 중장기적 증가 두 가지 효과로 이어질 가능성이 있다"고 강조했다.채 연구원은 "한국 방산업체들은 중동 무기 수요 증가 국면에서 수혜가 기대된다"며 "한화에어로스페이스는 사우디아라비아 지상무기, 현대로템은 이라크의 전차 수주 확보에 집중하고 있다"며 "한국항공우주와 LIG넥스원은 350억달러(약 51조원) 규모로 체결된 한국 정부-UAE(아랍에미리트) 간 방산 협력 프레임 MOU(업무협약) 흐름에서 수혜주로 주목받고 있다"고 설명했다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005324766', 'https://imgnews.pstatic.net/image/008/2026/03/03/0005324766_001_20260303174817142.jpg?type=w800', 'NEWS_TRANSPORT', NULL, '2026-03-03 17:47:10', 0, true, '2026-03-09 06:25:07.296655') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1056, '호르무즈 봉쇄에 LNG 공급 차질 우려...SK가스·한국가스공사 강세[특징주]', '[이데일리 김경은 기자] 미국·이스라엘의 이란 공습과 호르무즈 해협 봉쇄 현실화로 액화천연가스(LNG) 공급 차질 우려가 커지면서 3일 국내 가스 유틸리티 관련주가 일제히 강세를 보였다.엠피닥터에 따르면 이날 오전 9시 4분 현재 SK가스(018670)는 전일 대비 2만500원(8.80%) 오른 25만3500원에 거래됐고, 한국가스공사(036460)는 2850원(6.92%) 상승한 4만4050원을 기록했다. E1(017940)도 6800원(6.57%) 오른 11만300원으로 급등세다. 이 밖에 대성홀딩스(016710)(+4.09%), 경동도시가스(267290)(+3.96%), 인천도시가스(034590)(+2.58%), 삼천리(004690)(+2.03%) 등도 강세다.가스주 강세의 직접적 배경은 호르무즈 해협 봉쇄로 풀이된다. 호르무즈 해협은 전 세계 해상 원유와 LNG 물동량의 약 20%가 통과하는 핵심 해상 수송로다. 한국의 중동 의존도는 높다. 국내 원유 수입의 70.7%, LNG의 20.4%가 중동산이다.이란 혁명수비대 사령관 보좌관 에브라힘 자바리 소장은 “호르무즈 해협을 통과하려는 모든 선박에 불을 지르겠다”며 “석유 한 방울도 여기서 빠져나갈 수 없다”고 경고했다.가스 공급 불안 속에 LNG 가격 급등 기대가 커진 것이 가스주 강세 요인으로 풀이된다. 글로벌 투자은행(IB)은 호르무즈 해협의 전면 봉쇄 시 국제유가가 배럴당 120~130달러까지 치솟을 것으로 전망하고 있어 에너지 가격 상승 수혜 기대감이 관련주 전반으로 퍼진 모습이다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006227231', 'https://imgnews.pstatic.net/image/018/2026/03/03/0006227231_001_20260303091412854.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-03-03 09:14:12', 0, true, '2026-03-09 06:20:03.584091') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1057, '오늘의 메모[3월 6일]', '<코스피>▲보통주추가상장=이수스페셜티케미컬(457190)(국내BW) 하이브(국내CB) ▲주권변경상장=한솔테크닉스(004710)(주식소각)<코스닥>▲공모주청약=카나프테라퓨틱스(주관사 한국) ▲보통주추가상장=디와이디(국내BW) 에스에이엠지엔터테인먼트·대진첨단소재(주식매수선택권행사) 엔알비·컨텍·에스비비테크·엠케이전자·아이텍·아이엘·아이센스·알티캐스트·선익시스템·다날·이수앱지스·제테마(국내CB)와이지-원(019210)(우선주의 보통주전환)이렘(009730)·엔케이맥스(182400)(유상 제3자배정) ▲주권변경상장=세보엠이씨(011560)·티에스아이(주식소각) ▲신규상장=에스팀(458350)', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004595994', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ENERGY', NULL, '2026-03-05 10:49:10', 0, true, '2026-03-09 06:20:13.984027') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1058, '한솔테크닉스, 자사주 70만주 전량 소각..."주주환원 강화"', '글로벌생산 거점 및 사업구조 재편..."수익성 높일 것"한솔그룹 계열 전기·전자부품 전문기업인 한솔테크닉스가 보유 중인 자사주 전량을 소각해 주주환원 강화에 나섰다. 또 글로벌 생산거점과 사업구조를 재편해 수익성을 높일 방침이다.23일 업계에 따르면 한솔테크닉스는 최근 이사회 의결을 통해 기존에 취득해 보유하던 자사주 69만2361주 전량을 소각키로 결정했다.자사주 소각은 발행 주식 수를 줄여 주당순이익(EPS)과 주당 가치 상승 효과를 기대할 수 있는 대표적인 주주 환원 수단이다. 단순히 자사주를 보유하는 것과 달리 소각은 발행주식 수 자체를 줄인다는 점에서 보다 직접적인 주주가치 제고 방식으로 평가된다.한솔테크닉스는 앞으로 재무 여건과 시장 상황을 종합적으로 검토해 추가로 자사주 매입과 소각을 검토하고 있다. 단기 주가 대응보다 중장기적인 자본 효율성 개선과 기업가치 제고를 염두에 둔 행보란 해석이 나온다.한솔테크닉스는 또 글로벌 생산거점과 사업구조 재편을 통한 수익성을 높일 계획이다. 올해 내 해외에 분포된 주요 생산거점을 재편하는 게 골자다. 우선 태국과 베트남으로 분산됐던 TV용 파워보드 생산을 베트남 호치민 법인으로 일원화해 생산·운영 효율을 높인다. 태국 공장은 가전용 파워보드 전문 생산법인으로 전환해 제품 특성에 맞는 운영 체계를 구축할 예정이다.아울러 사업 포트폴리오 전반에 대한 재편을 통해 사업 경쟁력을 높일 방침이다. 태양광 모듈 사업부를 자회사로 전환해 사업 운영의 독립성과 효율성을 강화하고 국내 사업장들에 대한 재편도 추진한다.한솔테크닉스 관계자는 "사업 포트폴리오에 대한 전반적인 재검토와 재편을 통해장기적인 수익성을 높이고 성장을 위한 체력을 확보할 계획"이라며 "향후 자회사인 한솔아이원스, 한솔오리온텍 등과 함께 전자소재·반도체·전장에 걸친 안정적인 사업 구조와 수익창출 기반을 확보할 수 있을 것으로 기대한다"고 말했다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005320706', 'https://imgnews.pstatic.net/image/008/2026/02/23/0005320706_001_20260223100117810.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-02-23 10:00:59', 0, true, '2026-03-09 06:20:13.984027') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1059, '팜젠사이언스, 활력 에너지 ''솔루티 마시는 알부민 메가 부스터'' 출시', '/사진=팜젠사이언스팜젠사이언스는 벨기에산 프리미엄 알부민을 주요성분으로 한 액상형 활력 에너지 제품인 ''솔루티 마시는 알부민 메가 부스터''를 자사몰 ''솔루티''를 통해 공식 출시했다고 6일 밝혔다.솔루티 마시는 알부민 메가 부스터는 한 포당 1만9400mg의 고함량 알부민 복합물을 액상 형태로 담아 체내 흡수율을 높였다. 알부민 특유의 비린 맛을 최소화한 상큼한 파인애플 맛으로 섭취 편의성과 기호성을 모두 고려한 것이 특징이다.특히 이번 제품은 단순 영양 보충을 넘어 즉각적인 에너지 부스팅을 위해 아르기닌 50mg과 타우린 40mg을 복합 배합했다. 여기에 에너지 대사에 필수적인 비타민 B1, B2, B6와 9종 아미노믹스, 그리고 기력 보충에 탁월한 발효녹용추출액을 더해 현대인에게 필요한 최적의 활력 시너지를 완성했다.팜젠사이언스 관계자는 "이번에 출시된 솔루티 마시는 알부민 메가 부스터''는 60년 제약 노하우를 가진 팜젠사이언스가 성분을 직접 설계하고, HACCP 인증 시설인 대원헬스케어에서 엄격한 품질 관리를 거쳐 제조한 신뢰할 수 있는 제품"이라며 "바쁜 일상 속에서 만성 피로를 느끼는 직장인이나 수험생, 기력이 떨어진 어르신들이 언제 어디서나 간편하게 활력을 충전할 수 있다"고 말했다.팜젠사이언스는 지속성 비타민 ''비타잉''에 이어 이번 솔루티 알부민 제품 출시를 통해 헬스케어 라인업을 강화하고 있다. 앞으로도 고객의 다양한 니즈에 부응하는 혁신적인 제품들을 지속적으로 선보이며 건강식품 시장에서의 입지를 더욱 확장해 나갈 계획이다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005326247', 'https://imgnews.pstatic.net/image/008/2026/03/06/0005326247_001_20260306094909189.jpg?type=w800', 'NEWS_BIO', NULL, '2026-03-06 09:48:16', 0, true, '2026-03-09 06:20:20.992052') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1060, '오늘의 메모[9월 5일]', '[서울경제]<코스피>▲실권주청약=NH올원리츠(400760)(주관사 NH) ▲보통주추가상장=에이프로젠(007460)(국내CB) ▲주권변경상장=써니전자(004770)·삼양홀딩스(000070)(주식소각)<코스닥>▲신주배정기준일=와이제이링크(209640)(무상) ▲구주주유상청약=빌리언스(044480)▲실권주청약=큐라클(365270)(주관사 한양) ▲보통주추가상장=제이스코홀딩스(023440)·율호·제이에스링크·네오펙트·아난티·SAMG엔터·지아이이노베이션(국내CB) 성일하이텍·해성에어로보틱스·캡스톤파트너스(452300)(주식매수선택권행사)', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004529021', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2025-09-04 10:37:08', 0, true, '2026-03-09 06:20:26.475040') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1075, '조광페인트, 지난해 영업손실 195억…건설경기 침체, 수출 감소 영향', '조광페인트가 건설경기 침체와 수출 감소의 영향으로 지난해 영업손실을 기록했다.조광페인트는 지난해 매출 2026억원을 기록했다고 밝혔다. 이는 전년 대비 18.29% 감소한 수치다.같은 기간 영업손실 195억원을 기록하며 적자전환했다.조광페인트 측은 “건설경기 침체와 수출 감소로 매출 규모가 축소됐고, 이에 따라 영업이익률도 하락했다”고 설명했다.', NULL, '조선비즈', 'https://n.news.naver.com/mnews/article/366/0001144198', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ENERGY', NULL, '2026-02-25 08:51:06', 0, true, '2026-03-09 06:21:09.990986') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1063, '[서울데이터랩]금일 코스피 거래량 1위 디아이씨 거래대금 1,961억원 돌파', '코스피 거래량 상위 종목들이 전반적으로 강세를 보인다.8일 한국거래소에 따르면, 디아이씨(092200)가 1,519만주 이상 거래되며 코스피 종목 중 실시간 거래량 1위를 차지한다. 현재 주가는 13,370원으로, 시가총액의 3.77%에 해당하는 거래대금에 비해 19.70%의 급등세를 보인다. PER 110.50, ROE 10.04로, 재무 지표에서도 주목할 만한 모습을 보인다. 삼성제약(001360)은 1,773원으로 상한가를 기록하며, 거래량 1,504만주를 기록한다. 거래대금은 2.59%로 시가총액 대비 높은 매수세를 보인다.코오롱모빌리티그룹(450140)은 현재 16,910원으로 16.06% 상승하며, 거래량은 1,210만주에 달한다. 일성건설(013360)은 2,250원으로 2.27% 상승, 에이프로젠(007460)은 759원으로 6.90% 상승 중이다. 삼성전자(005930)는 109,600원으로 1.11% 상승하며, 819만주가 거래된다. 동양(001520)은 835원으로 5.22% 하락, 두산에너빌리티(034020)는 76,800원으로 4.48% 하락 중이다. 현대약품(004310)과 한국무브넥스(010100)는 각각 6,570원, 4,770원으로 29.84%, 1.49% 상승세를 보인다.한편 거래량 상위 20위권 종목들은 현대건설(000720) ▼0.93%, 태영건설(009410) ▲1.03%, 대한해운(005880) ▼3.48%, 금강공업(014280) ▲6.34%, 덕성(004830) ▲4.42%, SG세계물산(004060) ▼2.88%, 에넥스(011090) ▼6.42%, 한온시스템(018880) ▼2.77%, 삼성중공업(010140) ▲0.59%, 한국전력(015760) ▼2.11% 등의 성적을 기록한다.주목할 만한 종목으로는 급등세를 보인 현대약품과 삼성제약이 있다. 현대약품은 3,514,432주의 거래량과 21,767백만원의 거래대금을 기록하며, 시가총액의 1.04%를 차지하는 거래대금으로 높은 투자 심리를 반영한다. 반면 하락세를 보인 동양과 두산에너빌리티는 각각 거래량 대비 낮은 거래대금을 기록하며, 매도세가 우세한 모습을 보인다.시장 전반적으로 상승 종목들이 두드러지며 활발한 매수세가 이어지는 가운데, 일부 종목들은 하락세를 기록하며 엇갈린 투자 심리를 보여준다. 장 마감까지 이러한 추세가 이어질지 주목된다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003598929', 'https://imgnews.pstatic.net/image/081/2025/12/08/0003598929_001_20251208132230163.png?type=w800', 'NEWS_ETC', NULL, '2025-12-08 13:22:30', 0, true, '2026-03-09 06:20:37.519614') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1064, '[서울데이터랩]현대약품 29.84% 폭등…실시간 상승률 1위', '8일 오전 9시 10분 현대약품(004310)이 등락률 +29.84%로 상승률 1위를 차지했다. 현대약품은 개장 직후 3,113,812주가 거래되었으며 주가는 공모가 대비 1,510원 오른 6,570원이다.한편 현대약품의 PER은 273.75로 높은 수치를 보이고 있으며, ROE는 0.70%로 수익성이 다소 낮은 수준이다.이어 상승률 2위 태영건설우(009415)는 현재가 8,410원으로 주가가 29.78% 폭등하고 있다. 상승률 3위 코오롱모빌리티그룹우(45014K)는 현재 27,350원으로 25.17% 폭등하며 강세를 보이고 있다. 상승률 4위 삼성제약(001360)은 21.33% 급등하며 1,655원에 거래되고 있다. 상승률 5위 동부건설우(005965)는 10.28%의 상승세를 타고 22,000원에 거래되고 있다.6위 에이플러스에셋(244920)은 현재가 9,090원으로 6.07% 상승 중이다. 7위 에이피알(278470)은 현재가 269,000원으로 5.70% 상승 중이다. 8위 코오롱모빌리티그룹(450140)은 현재가 15,340원으로 5.28% 상승 중이다. 9위 덕성(004830)은 현재가 5,220원으로 4.82% 상승 중이다. 10위 율촌화학(008730)은 현재가 31,550원으로 4.82% 상승 중이다.이밖에도 덕성우(004835) ▲4.66%, 고려아연(010130) ▲4.64%, 동아지질(028100) ▲4.45%, GS피앤엘(499790) ▲4.17%, 에코프로머티(450080) ▲4.00%, 엘앤에프(066970) ▲3.81%, SNT모티브(064960) ▲3.79%, 이수화학(005950) ▲3.67%, 티와이홀딩스우(36328K) ▲3.63%, 보락(002760) ▲3.51% 등을 기록하며 시장에서 활발히 거래되고 있다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003598850', 'https://imgnews.pstatic.net/image/081/2025/12/08/0003598850_001_20251208091812538.png?type=w800', 'NEWS_ETC', NULL, '2025-12-08 09:18:12', 0, true, '2026-03-09 06:20:37.519614') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1065, '기업 공시 [11월 6일]', '[서울경제]<코스피 공시>▲삼성바이오로직스(207940)=아시아 소재 제약사와 765억 원 규모 위탁생산(CMO) 증액 계약 체결 ▲LG화학=2조 원 규모의 자회사 LG에너지솔루션 보통주 575만 주 장외 처분 ▲한화엔진(082740)=한화오션과 2700억 원 규모 선박엔진 공급계약 체결 ▲덕성(004830)=인도네시아에 합성피혁 제조·판매 법인 설립 ▲미래에셋증권(006800)=3분기 매출 6조 6724억 원(전년 동기 대비 22.5%), 영업이익 2조 228억 원(-39.9%) ▲LIG넥스원(079550)=3분기 매출 1조 492억 원(41.7%), 영업이익 896억 원(72.5%) ▲에이피알(278470)=3분기 매출 3859억 원(121.7%), 영업이익 961억 원(252.9%) ▲일동제약(249420)=3분기 매출 1455억 원(-6.7%), 영업이익 68억 원(87.6%) ▲GS리테일(007070)=3분기 매출 3조 2054억 원(5.3%), 영업이익 1111억 원(31.6%) ▲롯데칠성(005300)=3분기 매출 1조 792억 원(1.3%), 영업이익 918억 원(16.6%) ▲케이카(381970)=3분기 매출 6655억 원(14.8%), 영업이익 240억 원(40.3%)<코스닥 공시>▲LK삼양(225190)=유상증자 최종 발행가액 주당 1216원으로 확정 ▲알테오젠(196170)=코스피 이전상장 관련 임시 주주총회 개최 결의 ▲브이엠(089970)=SK하이닉스와 76억 5000만 원 규모 반도체 제조장비 공급계약 체결 ▲소프트센(032680)=100억 원 규모 자사주 매입 결정 ▲헥토이노베이션(214180)=3분기 매출 956억 원(19.2%), 영업이익 147억 원(5.4%) ▲스튜디오드래곤(253450)=3분기 매출 1365억 원(51.1%), 영업이익 105억 원(흑자전환) ▲코스메카코리아(241710)=3분기 매출 1824억 원(44%), 영업이익 272억 원(78.8%)', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004552850', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2025-11-06 16:27:06', 0, true, '2026-03-09 06:20:37.519614') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1066, '[서울데이터랩]대덕전자 20.57% 급등 금일 증시 상승률 1위로 마감', '30일 오후 3시 35분 대덕전자(353200)가 등락률 +20.57%로 상승률 1위로 마감했다. 대덕전자는 장 중 5,713,909주가 거래되었으며 주가는 전 거래일 대비 10,800원 오른 63,300원에 마감했다.한편 대덕전자의 PER은 123.63으로 매우 높은 수준을 기록하며, ROE는 2.73%로 수익성이 낮은 수준이다.이어 상승률 2위 DRB동일(004840)은 주가가 +16.95% 급등하며 종가 6,140원에 상승 마감했다. 상승률 3위 SK네트웍스(001740)의 주가는 5,600원으로 +15.82% 급등했다. 상승률 4위 미래에셋증권우(006805)는 +15.67% 상승하며 19,490원에 마감했다. 상승률 5위 한화비전(489790)은 +11.55%의 급등세를 타고 61,800원에 마감했다.6위 DB(012030)는 1,832원으로 +10.83% 상승 마감했다. 7위 삼아알미늄(006110)은 종가 34,200원으로 +9.97% 상승 마감했다. 8위 대성산업(128820)은 종가 7,350원으로 +9.87% 상승 마감했다. 9위 대덕전자1우(35320K)는 17,300원으로 +9.29% 상승 마감했다. 10위 S-Oil우(010955)는 59,900원으로 +8.12% 상승 마감했다.이밖에도 케이씨텍(281820) ▲8.12%, 동국제강(460860) ▲8.10%, 더존비즈온(012510) ▲7.98%, 영원무역(111770) ▲7.70%, 에쓰씨엔지니어링(023960) ▲7.63%, 롯데관광개발(032350) ▲7.48%, 미래에셋증권2우B(00680K) ▲7.38%, SK스퀘어(402340) ▲7.34%, 코리아써키트(007810) ▲7.12%, KSS해운(044450) ▲6.83% 등을 기록하며 금일 증시를 상승으로 마감했다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003613172', 'https://imgnews.pstatic.net/image/081/2026/01/30/0003613172_001_20260130160209200.png?type=w800', 'NEWS_ETC', NULL, '2026-01-30 16:02:09', 0, true, '2026-03-09 06:20:46.375141') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1105, '[하나벤처스 is] 창업 멤버 ''토사구팽'', 지주 직속 체제 ''가속화'' [넘버스]', '이 기사는 2026년 02월 13일 16시 14분넘버스유료 사이트에 발행된 기사입니다.서울 중구 하나은행 본점 전경 /사진 제공=하나금융그룹설립 9년 차를 맞은 하나벤처스가 ''지주 중심'' 체제로 재편되고 있다. 지난해 3월 하나금융지주 출신 양재혁 대표 취임 이후 경영진과 이사회 구조를 전면 손질하면서다. 설립 멤버를 비롯한 초기 핵심 인력의 이탈이 이어진 반면, 지주 및 외부 영입 인재들이 공백을 채우면서 금융그룹 자회사로서의 색채가 한층 짙어졌다는 평가다.13일 벤처캐피탈(VC) 업계에 따르면 회사 내부 변화가 본격화한 시점은 지난해 3월 양재혁 대표 취임 이후다. 양 대표는 하나금융지주에서 그룹전략 조직에 몸담으며 최고전략책임자(CSO)까지 지낸 전략통이다. 전임자인 안선종 전 대표 역시 지주 CSO 출신이었다는 점에서, 설립 당시 내세웠던 ''은행과의 독립 경영'' 기조에서 벗어나 그룹의 직접 관리 체계가 자리잡았다는 분석이다.양 대표 취임 전후로 창립 멤버와 핵심 운용 인력의 이탈도 이어졌다. 지난해 5월 정지웅 전 경영기획본부장이 사임했고, 6월에는 주요 펀드 운용을 총괄했던 강문수 상무가 퇴사한 뒤 스틱벤처스로 자리를 옮겼다. 12월에는 창립 멤버인 강훈모 상무도 회사를 떠났다. 2020년부터 투자본부에 몸담았던 조경훈 상무는 올해 1월 경영기획본부로 이동하며 투자 일선에서 물러났다. 현재 상무급 이상 심사역은 대부분 최근 1년 내 합류한 인물들로 재편된 상태다.공백은 외부 및 지주 출신 인사 영입으로 채웠다. 지난해 8월 길준일 전 녹십자홀딩스 상무가 경영기획본부장(CFO)으로 선임되며 회사 살림을 맡았고, 9월에는 유안타인베스트먼트 출신 박상우 상무가 투자본부장(CIO)으로 합류했다. 이 밖에 이에스인베스터 출신 유성욱 상무, 문미란 상무, 성경아 이사, 김성은 이사 등 외부 출신 심사역과 바이오·딥테크 분야 전문 인력도 보강됐다. 현재 하나벤처스의 C레벨 조직은 양재혁 대표를 필두로 하나은행을 거친 임지영 위험관리책임자(CRO), 박상우 CIO, 길준일 CFO 체제다. 지주·은행 출신과 외부 영입 인사가 혼재된 구조다.이사회도 올해 1월 개편을 마쳤다. 초기 ''사내이사 3인, 감사 1인'' 체제에서 ''사내이사 1인, 기타비상무이사 2인, 감사 1인'' 체제로 전환했다. 사내이사는 양 대표 1인으로 축소됐고, 기타비상무이사에는 이동욱 하나금융지주 리스크관리팀장과 올해 1월 신규 선임된 이승헌 하나금융지주 신사업전략팀 부팀장이 이름을 올렸다.지난해까지만 해도 설립 멤버인 강훈모 상무가 투자본부장으로서 사내이사에 참여했으나, 현재는 감사를 제외한 이사회 구성원이 모두 지주 직속 인사로 채워진 셈이다. 투자 심의와 중장기 전략 수립 과정에 지주의 의중이 직접 반영되는 구조가 강화됐다는 평가가 나오는 이유다.이 같은 인적 쇄신과 지배구조 개편은 펀드레이징 재개를 위한 사전 정비로 해석된다. 하나벤처스는 지난해 신규 펀드 결성에 나서지 않았다. 특히 정책기관 출자 사업을 통한 펀드 조성은 2023년 1월 이후 공백이 장기화한 상태다. 펀드 공백이 길어진 만큼, 올해는 그룹과의 연계를 강화하는 한편 정책자금을 기반으로 한 신규 펀드레이징에 적극 나설 것으로 전망된다.현재 하나벤처스의 운용자산(AUM)은 1조468억원이다. 누적 투자액은 7535억원, 포트폴리오 기업은 254곳을 보유하고 있다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000080467', 'https://imgnews.pstatic.net/image/293/2026/03/06/0000080467_001_20260306185307078.jpg?type=w800', 'NEWS_BIO', NULL, '2026-03-06 18:53:07', 0, true, '2026-03-09 06:22:33.600754') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1067, '[서울데이터랩]‘삼아알미늄’ 17.68% 급등…실시간 상승률 1위', '30일 오전 9시 10분 ##삼아알미늄(006110)_0##가 등락률 +17.68%로 상승률 1위를 차지했다. 삼아알미늄은 개장 직후 5분간 12만 2127주가 거래되었으며 주가는 전 거래일 대비 5500원 오른 3만 6600원이다.한편 삼아알미늄의 PER은 -33.21로 시장에서 가치 절하를 받고 있을 가능성을 시사하며, ROE는 -3.75%로 수익성이 낮다고 볼 수 있다.이어 상승률 2위 대덕전자(353200)는 현재가 5만 9500원으로 주가가 13.33% 급등하고 있다. 상승률 3위 삼화전기(009470)는 현재 5만 7300원으로 11.26% 급등하며 강세를 보이고 있다. 상승률 4위 남선알미우(008355)는 7.46% 상승하며 1만 6990원에 거래되고 있다. 상승률 5위 풍산(103140)은 7.26%의 상승세를 타고 13만 8900원에 거래되고 있다.6위 SK텔레콤(017670)은 현재가 7만 4000원으로 6.47% 상승 중이다. 7위 씨티알모빌리티(308170)는 현재가 7760원으로 6.30% 상승 중이다. 8위 대덕전자1우(35320K)는 현재가 1만 6810원으로 6.19% 상승 중이다. 9위 한농화성(011500)은 현재가 2만 7250원으로 5.83% 상승 중이다. 10위 미래에셋증권우(006805)는 현재가 1만 7830원으로 5.82% 상승 중이다.이밖에도 한화비전(489790) ▲5.78%, DRB동일(004840) ▲5.71%, 대한전선(001440) ▲5.65%, GS피앤엘(499790) ▲5.52%, 진흥기업2우B(002787) ▲4.84%, 남선알미늄(008350) ▲4.84%, F＆F(383220) ▲4.76%, 한화시스템(272210) ▲4.74%, S-Oil(010950) ▲4.49%, 더존비즈온(012510) ▲4.32% 등을 기록하며 시장에서 활발히 거래되고 있다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003613009', 'https://imgnews.pstatic.net/image/081/2026/01/30/0003613009_001_20260130092708943.png?type=w800', 'NEWS_ETC', NULL, '2026-01-30 09:27:08', 0, true, '2026-03-09 06:20:46.375141') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1068, '[서울데이터랩]윌비스 29.96% 상승…금일 증시 상승률 1위로 마감', '26일 오후 3시 35분 윌비스(008600)가 등락률 +29.96%로 상승률 1위로 마감했다. 윌비스는 장 중 2,812,685주가 거래되었으며 주가는 전 거래일 대비 77원 오른 334원에 마감했다.한편 윌비스의 PER은 0.83으로 상대적으로 저평가를 받고 있을 가능성을 시사하며, ROE는 -27.78%로 수익성이 낮다고 평가된다.이어 상승률 2위 계양전기우(012205)는 주가가 29.91% 폭등하며 종가 9,120원에 상승 마감했다. 상승률 3위 와이투솔루션(011690)의 주가는 5,180원으로 23.33% 폭등했다. 상승률 4위 KIWOOM 코스닥150선물레버리지(291630)는 22.90% 폭등하며 8,050원에 마감했다. 상승률 5위 팜스코(036580)는 16.70%의 급등세를 타고 2,935원에 마감했다.6위 고려아연(010130)은 1,807,000원으로 14.37% 급등 마감했다. 7위 삼아알미늄(006110)은 종가 29,000원으로 12.84% 급등 마감했다. 8위 디아이(003160)는 종가 31,650원으로 11.84% 급등 마감했다. 9위 KIWOOM 코스닥150(316670)은 9,195원으로 11.05% 급등 마감했다. 10위 현대비앤지스틸(004560)은 13,980원으로 10.95% 상승 마감했다.이밖에도 SK증권우(001515) ▲9.50%, 코리아써우(007815) ▲9.43%, KG케미칼(001390) ▲9.07%, KEC(092220) ▲8.41%, 콘텐트리중앙(036420) ▲8.38%, 선진(136490) ▲8.05%, 코스모신소재(005070) ▲7.23%, DRB동일(004840) ▲7.20%, 크래프톤(259960) ▲7.13%, 삼일제약(000520) ▲6.95% 등을 기록하며 금일 증시를 상승으로 마감했다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003611742', 'https://imgnews.pstatic.net/image/081/2026/01/26/0003611742_001_20260126155019764.png?type=w800', 'NEWS_ETC', NULL, '2026-01-26 15:50:19', 0, true, '2026-03-09 06:20:46.375141') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1069, '국제유가 배럴당 100달러 넘었다…항공주 동반 하락', '[특징주]머니투데이 특징주 그래픽 이미지항공주가 유가 급등 소식에 장 초반 동반 하락 중이다.9일 오전 9시17분 현재 티웨이항공은 전 거래일 대비 112원(9.42%) 내린 1077원에 거래 중이다.한진칼은 전 거래일 대비 9600원(7.76%) 내린 11만4100원을 나타내고 있다.대한항공(-7.76%), 제주항공(-4.73%), 진에어(-4.55%), 아시아나항공(-4.68%), 에어부산(-4.11%), AK홀딩스(-3.6%), 티웨이홀딩스(-2.75%) 등도 동반 하락 중이다.지난달 28일 미국과 이스라엘이 이란을 공습한 이후 이란이 영국과 미국의 유조선이 지나가는 호르무즈 해협을 사실상 봉쇄하면서 국제 유가가 급등하고 있다. 통상 국제유가가 오를 경우 항공유의 부담이 커지는 만큼 항공 업체 투자심리는 악화한다.국제 유가는 배럴당 100달러선을 넘었다. 블룸버그에 따르면 한국 시간 기준 이날 오전 7시께 국제 유가의 기준점 역할을 하는 브렌트유와 서부텍사스산원유(WTI)가 모두 배럴당 100달러를 넘겼다. WTI가 배럴당 100달러를 넘긴 것은 2022년 7월 이후 처음이다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005327020', 'https://imgnews.pstatic.net/image/008/2026/03/09/0005327020_001_20260309092216690.jpg?type=w800', 'NEWS_TRANSPORT', NULL, '2026-03-09 09:21:44', 0, true, '2026-03-09 06:20:54.365239') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1070, '美 이란 공습에 국제유가 급등…항공주 연일 하락', '[특징주]머니투데이 특징주 그래픽 이미지미국과 이스라엘의 이란 공습 여파로 국제유가가 급등하자 항공주가 연일 하락하고 있다.4일 오전 9시17분 현재 한진칼은 전날 대비 7800원(5.71%) 내린 12만8700원에 거래 중이다.제주항공(등락률 -4.09%), 대한항공(-3.97%), 진에어(-3.87%), AK홀딩스(-3.77%), {에어부산-}(3.76%), 아시아나항공(-3.68%), 티웨이홀딩스(-3.62%), 티웨이항공(-3.51%) 등도 동반 하락세다.이란이 영국과 미국의 유조선이 지나가는 호르무즈 해협을 사실상 봉쇄하면서 국제 유가가 급등하고 있다. 통상 국제유가가 오를 경우 항공유의 부담이 커지는 만큼 항공 업체 투자심리는 악화한다.3일(현지시간) ICE선물거래소에서 브렌트유 선물 종가는 배럴당 81.4달러로 전장보다 3.66달러(4.71%) 올랐다. 뉴욕상품거래소에서 서부 텍사스산 원유(WTI)는 3.33달러(4.67%) 상승한 배럴당 74.56달러에 거래를 마쳤다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005324945', 'https://imgnews.pstatic.net/image/008/2026/03/04/0005324945_001_20260304092413433.jpg?type=w800', 'NEWS_TRANSPORT', NULL, '2026-03-04 09:23:35', 0, true, '2026-03-09 06:20:54.365239') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1071, '"이란 공습 파장 확산"…방산·에너지주↑ 항공·여행주↓(종합)', 'LIG넥스원·극동유화 등 상한가 직행한진칼 13% 하락…여행주도 ''와르르''[테헤란=AP/뉴시스] 2일(현지 시간) 이란 테헤란의 한 건물에서 연기가 치솟고 있다. 미국과 이스라엘은 지난달 28일부터 이란에 대한 공습을 이어오고 있다. 2026.03.03.[서울=뉴시스] 박주연 기자 = 미국과 이스라엘의 대규모 대이란 군사작전 개시로 지정학적 위험이 고조되고 국제유가가 급등하며 국내 증시가 요동쳤다. 방산·에너지 관련주는 강세를 나타낸 반면 항공·여행주는 직격탄을 맞았다.한국거래소에 따르면 방위산업 관련주인 LIG넥스원은 3일 상한가까지 치솟은 15만2000원에 거래를 마무리했다. 한화시스템(29.14%)도 상한가 턱밑에서 장을 마쳤다.한화에어로스페이스(19.83%), 휴니드(13.36%), 풍산(12.78%), 현대로템(8.03%), 한국항공우주(3.19%) 등도 강세를 나타냈다.정유업종인 S-Oil 역시 전 거래일보다 28.45% 오른 14만1400원에 거래를 마감했다. GS(2.62%), SK이노베이션(2.51%)도 상승했다.LPG 관련주인 극동유화, 중앙에너비스, 흥구석유도 나란히 상한가를 기록했다. 대성산업(29.10%), SK가스(12.66%)도 상승 마감했다.반면 항공·여행 관련 업종은 가파른 내림세를 나타냈다.이란 공습 여파로 항공 노선 운항 차질이 발생하고, 유가 급등에 따른 연료비 부담이 커질 수 있다는 우려가 반영됐다. 여행주의 경우 중동 지역을 중심으로 한 지정학적 리스크 확대로 여행 심리가 위축될 수 있다는 전망이 부담으로 작용했다.한진칼이 전 거래일보다 12.67% 하락한 13만6500원에 장을 마무리한 가운데 대한항공(-10.32%), 제주항공(-7.72%), 아시아나항공(-5.41%), 진에어(-5.09%), 티웨이홀딩스(-4.44%), 에어부산(-4.30%) 등이 줄줄이 하락했다.참좋은여행(-7.68%), 하나투어(-6.65%), 롯데관광개발(-5.18%), 노랑풍선(-4.69%), 그래디언트(-4.57%), 모두투어(-4.05%) 등도 하락했다.이란혁명수비대의 호르무즈 해협 봉쇄로 국제 에너지 가격은 급등했다.지난 2일(현지시간) ICE선물거래소에서 5월 인도분 브렌트유 선물은 배럴당 77.74달러로 전 거래일 대비 6.7% 상승 마감했다. 브렌트유는 장중 한때 82.37달러까지 치솟으며 13% 급등, 지난해 1월 이후 1년여 만에 최고가를 기록했다.뉴욕상품거래소에서 4월 인도분 서부텍사스산원유(WTI) 선물은 배럴당 71.23달러로 6.3% 올랐다. WTI도 장중 한때 75.33달러로 12% 급등해 지난해 6월 이후 최고가를 찍었다.네덜란드 TTF거래소에서 천연가스 선물은 1㎿h(메가와트시)당 44.51유로로, 전 거래일 대비 40% 급등했다. 동북아 천연가스 가격지표인 LNG 일본·한국 마커(JKM) 역시 전장 대비 약 40% 오른 100만BTU당 15.068달러를 나타냈다.최보원 한투증권 연구원은 "이번 사태로 단기적으로 가장 유의해야 하는 사항은 에너지 공급망"이라며 "수혜업종은 전통 에너지, 산업재·방산, 친환경 에너지, 미드스트림 기업들, 피해업종은 여행, 운송주"라고 설명했다.최 연구원은 "항공·운송 기업들은 원유 가격 상승 부담이 지속되는 경우 실적 약화 부담이 커질 수 있다"며 "여행·호텔 기업들에 대한 투자심리도 위축될 수 밖에 없다"고 덧붙였다.', NULL, '뉴시스', 'https://n.news.naver.com/mnews/article/003/0013798698', 'https://imgnews.pstatic.net/image/003/2026/03/03/NISI20260302_0001070317_web_20260302220013_20260303155519880.jpg?type=w800', 'NEWS_TRANSPORT', NULL, '2026-03-03 15:54:38', 0, true, '2026-03-09 06:20:54.365239') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1072, '"주식에 80억 투자했는데"…120억 번 40대女 대표의 고민', '영앤리치 포트폴리오120억 번 창업가, 美국채·금 등 안전자산에 60% 담아볼 만수익률보다 변동성 관리 초점안전자산 비중 두 배로 늘려야금 ETF에 10억, 인플레 대비MMF·현금에 12억, 유동성 확보장기 성장 고려해 나스닥 투자코스피 ETF로 비과세도 고려사업으로 큰 성공을 거둔 창업가에게 자산관리는 또 다른 과제가 된다. 사업에서 이미 높은 리스크를 감수하는 만큼 금융자산 운용에서는 수익률보다 변동성 관리와 안정적인 현금흐름이 중요하기 때문이다.라이프스타일 브랜드를 창업해 빠르게 성장시킨 40대 초반 여성 대표 A씨도 비슷한 고민을 안고 있었다. 지분 일부 매각과 배당수익을 통해 약 120억원의 금융자산을 확보했지만 기존 포트폴리오는 소비·플랫폼 기업 중심의 개별 종목에 집중돼 있었다. 사업과 금융자산이 동일 산업에 노출돼 변동성이 커질 수 있는 구조였다.A씨는 최근 글로벌 증시가 사상 최고 수준까지 상승한 상황에서 자산 구조를 점검한 뒤 안정적인 자산관리 체계를 구축하고 싶었다. 위험자산 비중을 줄이고 안정적인 자산 기반을 확대할 필요가 있었다. 기존 포트폴리오는 안전자산 30%, 위험자산 70% 구조였는데 이를 안전자산 60%, 위험자산 40%로 재편했다.안전자산에는 달러 자산과 미국 중기 국채 상장지수펀드(ETF)를 편입했다. 달러 자산은 환율 상승 시 자연스러운 헤지 효과를 기대할 수 있고, 국채 ETF는 금리 하락 국면에서 채권 가격 상승에 따른 자본차익을 노릴 수 있어서다. 여기에 확정금리형 연금보험을 활용해 장기 현금흐름을 확보하고 과세 이연 효과도 함께 노렸다.금 ETF는 인플레이션과 지정학적 리스크에 대비한 자산으로 편입했다. 머니마켓펀드(MMF)와 현금은 시장 조정 시 투자 기회를 확보하기 위한 유동성 자금으로 유지했다.위험자산은 산업 편중을 줄이고 글로벌 성장성을 반영하는 방향으로 재구성했다. 미국 나스닥 ETF와 S&P500 ETF를 편입해 혁신 기술 기업 및 글로벌 우량 기업의 장기 성장성을 확보했다. 국내 코스피 ETF도 일부 편입해 지역 분산 효과와 비과세 혜택을 동시에 고려했다.A씨의 이해도가 높은 소비재산업은 글로벌 소비재 펀드를 통해 간접적으로 편입했다. 개별 종목 투자 대신 펀드를 활용해 산업 집중 리스크를 낮추기 위한 전략이었다. 일부 자금은 비상장 스타트업 투자에 배분해 초과 수익 기회를 노렸다. 다만 전체 포트폴리오 안정성을 해치지 않도록 비중은 제한적으로 설정했다.최근 글로벌 경제 환경도 이런 전략을 뒷받침하고 있다. 원자재 가격과 물가가 다시 상승하는 가운데 기업 수익성은 개선되고 있다. 글로벌 소비와 경기 역시 점진적인 회복세가 예상된다. 하지만 글로벌 증시는 이미 경기 회복 기대를 상당 부분 선반영했다.특히 미국 기준금리는 여전히 높은 수준이고 고용 시장도 둔화 조짐을 보인다. 이런 상황에서 물가 상승이 이어지면 시장 변동성이 커질 가능성이 있다는 분석이다. 이런 점을 고려해 위험자산 비중을 점진적으로 줄이고 방어적 포트폴리오로 전환하는 전략을 세웠다.강수진 하나은행 용산PB센터 골드 PB부장은 “기업가 고객은 이미 본업에서 높은 리스크를 감수하고 있기 때문에 금융자산은 수익 극대화보다 변동성 관리와 안정적인 자산 성장에 초점을 맞춰야 한다”며 “수십 년 동안 투자를 이어가야 하는 만큼 단기 수익률보다 장기적인 자산 성장 전략이 중요하다”고 말했다. 그러면서 “증시 밸류에이션이 높은 구간에서는 위험자산 비중을 줄이고, 시장이 조정받을 때 다시 확대하는 방식으로 포트폴리오를 관리할 필요가 있다”고 덧붙였다.', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005259543', 'https://imgnews.pstatic.net/image/015/2026/03/08/0005259543_001_20260309003112035.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-08 18:08:17', 0, true, '2026-03-09 06:21:02.425856') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1073, '''사업 대박'' 40대 女 자산가, 120억 굴리는 방법이…''깜짝'' [영앤리치 포트폴리오]', '"본업에서 높은 리스크를 감수하는 기업가 고객변동성 관리·안정적인 자산 성장에 초점 맞춰야"사진=게티이미지뱅크사업으로 큰 성공을 거둔 창업가에게 자산관리는 또 다른 과제가 된다. 사업에서 이미 높은 리스크를 감수하는 만큼 금융자산 운용에서는 수익률보다 변동성 관리와 안정적인 현금흐름이 중요하기 때문이다.라이프스타일 브랜드를 창업해 빠르게 성장시킨 40대 초반 여성 대표 A씨도 비슷한 고민을 안고 있었다. 지분 일부 매각과 배당수익을 통해 약 120억원의 금융자산을 확보했지만 기존 포트폴리오는 소비·플랫폼 기업 중심의 개별 종목에 집중돼 있었다. 사업과 금융자산이 동일 산업에 노출돼 변동성이 커질 수 있는 구조였다.A씨는 최근 글로벌 증시가 사상 최고 수준까지 상승한 상황에서 자산 구조를 점검한 뒤 안정적인 자산관리 체계를 구축하고 싶었다. 위험자산 비중을 줄이고 안정적인 자산 기반을 확대할 필요가 있었다. 기존 포트폴리오는 안전자산 30%, 위험자산 70% 구조였는데 이를 안전자산 60%, 위험자산 40%로 재편했다.안전자산에는 달러 자산과 미국 중기 국채 상장지수펀드(ETF)를 편입했다. 달러 자산은 환율 상승 시 자연스러운 헤지 효과를 기대할 수 있고, 국채 ETF는 금리 하락 국면에서 채권 가격 상승에 따른 자본차익을 노릴 수 있어서다. 여기에 확정금리형 연금보험을 활용해 장기 현금흐름을 확보하고 과세 이연 효과도 함께 노렸다.금 ETF는 인플레이션과 지정학적 리스크에 대비한 자산으로 편입했다. 머니마켓펀드(MMF)와 현금은 시장 조정 시 투자 기회를 확보하기 위한 유동성 자금으로 유지했다.위험자산은 산업 편중을 줄이고 글로벌 성장성을 반영하는 방향으로 재구성했다. 미국 나스닥 ETF와 S&P500 ETF를 편입해 혁신 기술 기업 및 글로벌 우량 기업의 장기 성장성을 확보했다. 국내 코스피 ETF도 일부 편입해 지역 분산 효과와 비과세 혜택을 동시에 고려했다.A씨의 이해도가 높은 소비재산업은 글로벌 소비재 펀드를 통해 간접적으로 편입했다. 개별 종목 투자 대신 펀드를 활용해 산업 집중 리스크를 낮추기 위한 전략이었다. 일부 자금은 비상장 스타트업 투자에 배분해 초과 수익 기회를 노렸다. 다만 전체 포트폴리오 안정성을 해치지 않도록 비중은 제한적으로 설정했다.최근 글로벌 경제 환경도 이런 전략을 뒷받침하고 있다. 원자재 가격과 물가가 다시 상승하는 가운데 기업 수익성은 개선되고 있다. 글로벌 소비와 경기 역시 점진적인 회복세가 예상된다. 하지만 글로벌 증시는 이미 경기 회복 기대를 상당 부분 선반영했다. 특히 미국 기준금리는 여전히 높은 수준이고 고용 시장도 둔화 조짐을 보인다. 이런 상황에서 물가 상승이 이어지면 시장 변동성이 커질 가능성이 있다는 분석이다. 이런 점을 고려해 위험자산 비중을 점진적으로 줄이고 방어적 포트폴리오로 전환하는 전략을 세웠다.강수진 하나은행 용산PB센터 골드 PB부장은 “기업가 고객은 이미 본업에서 높은 리스크를 감수하고 있기 때문에 금융자산은 수익 극대화보다 변동성 관리와 안정적인 자산 성장에 초점을 맞춰야 한다”며 “수십 년 동안 투자를 이어가야 하는 만큼 단기 수익률보다 장기적인 자산 성장 전략이 중요하다”고 말했다. 그러면서 “증시 밸류에이션이 높은 구간에서는 위험자산 비중을 줄이고, 시장이 조정받을 때 다시 확대하는 방식으로 포트폴리오를 관리할 필요가 있다”고 덧붙였다.조미현 기자', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005259372', 'https://imgnews.pstatic.net/image/015/2026/03/07/0005259372_001_20260307184509533.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-07 17:43:13', 0, true, '2026-03-09 06:21:02.425856') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1074, '"ETF는 예금이 아닙니다"…금감원, 과장 광고에 경고장', '만기매칭형 ''안전 예금'' 포장·커버드콜 ''확정 수익'' 오인 유도 등 5가지 불량 사례 적발금감원 사옥/사진=뉴스1국내 ETF 시장이 4년 새 4배로 급팽창하면서 운용사 간 마케팅 경쟁도 과열되고 있다. 금융감독원이 투자자들이 흔히 오해할 수 있는 ETF 광고 사례 5가지를 공개하며 주의를 촉구하고 나섰다.5일 금감원에 따르면 국내 ETF 순자산은 지난해 말 기준 297조2000억원으로 2021년(74조원) 대비 4배 가까이 늘었다. 상장 종목 수도 같은 기간 533개에서 1058개로 두 배로 불어났다. 이 과정에서 핀플루언서 등을 통한 SNS 마케팅이 확산되면서 투자자 보호 측면에서 문제가 있는 광고 사례도 늘고 있다는 게 금감원의 판단이다.금감원이 꼽은 첫 번째 문제는 ETF를 예금처럼 포장하는 광고다. 만기매칭형 ETF를 "예금만큼 안전하다"고 홍보하거나, 목표 분배율 연 10% 상품을 "1억원 넣으면 월 150만원씩 따박따박"이라고 표현한 사례가 대표적이다. ETF는 예금자보호법 대상이 아니며 원금 손실이 언제든 발생할 수 있다.두 번째는 위험 요인을 숨긴 채 장점만 부각하는 광고다. 환노출(Unhedged) 구조의 해외주식형 ETF를 홍보하며 "달러 노출이 장점"이라고 단정적으로 표현한 경우가 해당된다. 환율이 하락하면 기초자산 가격이 올라도 환차손으로 전체 수익률이 낮아지거나 원금 손실이 생길 수 있다.세 번째는 수익률의 기준 기간을 속이는 광고다. 커버드콜 ETF를 홍보하면서 시장 변동성이 일시적으로 컸던 특정 기간 데이터만 골라 성과를 부풀리거나, 연간 목표 분배율 7%를 마치 매달 확정 수익처럼 오인하게 표현한 사례다.네 번째는 ''최초·최저'' 문구를 앞세운 과장 광고다. "국내 유일 ○○산업 대표 ETF"라고 홍보했지만 실제로는 동일 산업 ETF가 이미 상장돼 있거나 주요 편입 종목이 상당 부분 겹치는 경우다. 업계 최저 보수나 최초 출시가 수익성·안정성을 보장하지는 않는다.다섯 번째는 실질 비용을 숨기는 광고다. "총보수 0.00%"라고 홍보하지만 운용보수 등 일부 항목만 강조한 것으로, 지수사용료 등을 포함한 합성총보수(TER)는 타사보다 오히려 높은 경우도 있다. ETF는 총보수 외에도 기타 비용과 증권거래비용이 추가로 발생한다.업계에서는 ETF 시장의 급성장과 함께 운용사 간 경쟁이 치열해지면서 광고 과장 사례가 늘어나는 추세라고 보고 있다. 금감원은 앞으로도 부적절한 광고 사례를 지속 모니터링하고 금융회사의 자율 시정을 유도할 방침이다.', NULL, '동행미디어 시대', 'https://n.news.naver.com/mnews/article/417/0001132735', 'https://imgnews.pstatic.net/image/417/2026/03/05/0001132735_001_20260305134308987.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-05 13:42:51', 0, true, '2026-03-09 06:21:02.425856') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1106, '공학한림원 대상에 권오경 한양대 교수…장진아 포스텍 교수, 젊은공학인상', '대상 상금 4억원으로 두배 늘어제30회 한국공학한림원 대상 수상자로 선정된 권오경 한양대 융합전자공학부 교수. 한국공학한림원 제공제30회 한국공학한림원 대상 수상자로 권오경 한양대 융합전자공학부 석좌교수가 선정됐다. 국내 디스플레이와 전력반도체 산업 기반을 구축하고 연구부터 산업생태계까지 이어지는 전 주기 성과를 이룬 점이 높게 평가됐다. 올해 대상 수상자 상금은 4억원으로 지난해 2억원에서 규모가 2배로 늘었다.9일 한국공학한림원은 올해 한국 공학 발전에 기여한 한국공학한림원 대상·젊은공학인상·뉴프런티어상·일진상·해동상·동진상·원익 차세대 공학도상 수상자를 발표했다.1996년도에 제정된 공학한림원 대상과 젊은공학인상은 매년 대한민국 산업 발전과 공학 기술 혁신에 기여한 공학기술인에게 수여된다.권 교수는 고전압 환경의 상보형금속산화반도체(CMOS), 전력반도체 공정, 센서와 의료 영상용 집적회로 칩 상용화, 마이크로디스플레이 패키징 기술개발 등 국내 디스플레이와 반도체 산업 기반을 구축한 연구자다. 인력 양성과 학술기관 운영 혁신까지 연구와 제조, 산업 생태계 전반을 일궜다는 평가를 받는다.상금 1억원의 제30회 젊은공학인상을 받은 장진아 포스텍 무은재석좌교수는 3차원(3D) 바이오프린팅 기반 바이오 인공장기 설계·제작 핵심 기술을 고도화한 업적을 인정받았다.김장우 망고부스트 대표는 신설된 제1회 뉴프런티어상을 수상해 상금 1억원을 받는다. 인공지능(AI) 기술 구동에 필요한 AI 가속기를 고속으로 연결하는 네트워크 하드웨어와 소프트웨어, 최적화 기술을 개발해 대규모 AI 데이터센터 시스템 효율을 극대화했다.대상과 젊은공학인상, 뉴프런티어상은 귀뚜라미문화재단의 전액 출연으로 운영된다. 올해부터 기술 인재의 사기 진작과 연구 의욕 고취를 위해 포상 규모를 대폭 증액했다는 설명이다.류석현 한국기계연구원장은 제22회 일진상 산학협력증진부문을 수상했다. 인재 양성·활용의 선순환 구조를 구축하는 ''U-LINK'' 플랫폼을 개발하고 ''후불제 연구개발(R&D)'' 도입으로 공공 R&D 기술사업화 촉진에 기여했다는 평가를 받았다.김민선 한국생산기술연구원 인간중심생산기술연구소장은 일진상 기술정책개발부문을 수상했다. 규제샌드박스 정책 기획을 통해 산업융합촉진법 및 시행령 개정에 기여하고 규제특례와 임시허가의 법적 근거를 마련해 연구개발 성과가 현장 검증을 거쳐 시장으로 확산되는 선순환 구조를 정립했다.일진상은 일진과학기술문화재단 후원으로 산학협력 증진 및 기술정책 개발에 기여한 인물을 선정해 포상한다. 수상자에게는 상패와 상금 2500만원이 주어진다.제21회 해동상 공학기술문화확산 부분 수상자인 임창환 한양대 교수는 뇌공학·바이오메디컬공학·인공지능 등을 주제로 다수의 베스트셀러 공학 교양서적을 출간하고 뇌공학 강연을 통해 중고등학생의 미래 공학기술에 대한 관심을 높이고 공학 진로 유도에 기여했다.이경우 서울대 교수는 공학교육 인증제도 개선과 교육과정 혁신을 주도하고 공학 기반 교양 확산 및 공학교육 위상 제고에 기여해 해동상 공학교육혁신 부문을 수상했다.해동상은 해동과학문화재단 후원으로 공학교육 혁신과 공학기술문화 확산에 기여한 인물에게 수여된다. 상금은 부문별 2500만원에서 이번 회차부터 3000만원으로 증액됐다.제1회 동진상을 수상한 안진호 한양대 연구부총장은 34년간 차세대 노광 기술을 연구해 국내 최초로 극자외선(EUV) 노광 기술의 정부 투자를 이끌고 2019년 국내 양산 토대를 마련했다. 동진쎄미켐 출연으로 올해 제정된 동진상은 소재·부품·장비 분야를 포함한 산업 현장의 기술혁신과 성과를 중심으로 10년 이상 활동한 국내 기관 소속 내국인 연구자를 선정해 시상한다.제4회 원익 차세대 공학도상 최우수상에는 메타표면을 이용한 180도 시야각 초소형 3차원 이미징 시스템을 처음으로 구현한 김래언 포스텍 박사과정생이 선정돼 상금 1000만원을 받는다.상금 500만원 규모의 우수상에는 권용현 연세대 박사과정생, 정은진 고려대 석박통합과정생, 조석주 KAIST 박사과정생, 조예현 KAIST 박사과정생, 서동은 울산과학기술원(UNIST) 학부생, 이정우 대구경북과학기술원(DGIST) 학부생 등 6명이 선정됐다.원익 차세대 공학도상은 국내 기업 원익의 후원으로 소재·부품·장비 분야와 스마트팩토리 최적화 시스템, AI 활용 소재 개발 등 관련 소프트웨어분야에서 우수한 공과대학(원)생을 지원하기 위해 제정된 상이다.윤의준 한국공학한림원장은 "올해부터 주요 포상을 ''2026 한국공학한림원 시상식''으로 통합 개최한 것은 공학계 성과를 더 크게 조명하기 위한 상징적 도약"이라며 "공학인들이 이뤄낸 탁월한 성취가 산업 경쟁력과 국가 성장으로 이어질 수 있도록 앞으로도 최선을 다하겠다"고 밝혔다.시상식은 3월 10일 오후 5시 그랜드 워커힐 서울 비스타홀에서 개최된다.', NULL, '동아사이언스', 'https://n.news.naver.com/mnews/article/584/0000036680', 'https://imgnews.pstatic.net/image/584/2026/03/09/0000036680_001_20260309143812549.jpg?type=w800', 'NEWS_SEMI', NULL, '2026-03-09 14:38:12', 0, true, '2026-03-09 06:22:40.581941') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1076, '“또 상한가 가나” 삼화페인트 분쟁 불씨에 이틀째 급등 [이런국장 저런주식]', '지난해 말 김장연 회장 별세창업가문 충돌 가능성 부각지난해 10월 일산 킨텍스에서 열린 ‘2025 국제도로교통박람회’에 참석한 삼화페인트의 홍보 부스 모습. 삼화페인트경영권 분쟁 가능성이 부각된삼화페인트(000390)주가가 장중 상한가를 기록했다.10일 한국거래소에 따르면 삼화페인트는 오후 2시 17분 기준 전 거래일 대비 30.00% 오른 1만 2350원에 거래 중이다. 전날인 9일에도 삼화페인트는 상한가로 장을 마감했다.시장에서는 급등의 주요 배경으로 창업주 가문 간의 경영권 분쟁 가능성을 꼽고 있다. 삼화페인트는 공동 창업한 김씨 가문이 경영권을, 윤씨 가문이 지분을 보유하며 협력 체제를 유지해왔다. 그러나 지난해 12월 최대주주인 김장연 회장이 별세하면서 지배구조에 변수가 발생했다.삼화페인트는 이달 5일 오너가 3세인 김현정 삼화페인트 부사장을 신임 대표로 선임했다. 김 대표는 고(故) 김장연 회장의 장녀로 김 회장의 지분 전량을 상속받은 최대 주주다. 특수관계인을 합한 김 대표 측 지분은 28.1%로 윤씨 일가와 큰 차이는 나지 않고 있다. 2대 주주인 윤씨 일가 측 지분율은 20% 안팎이다.과거 김씨 가문과 윤씨 가문 간 경영권 충돌이 있었던 이력이 시장의 투심을 자극하는 것으로 풀이된다. 삼화페인트 주가가 돌연 이틀 연속 상한가로 폭등한 점 역시 내달 정기 주주총회를 앞두고 양측의 지분 확보 경쟁이 벌어질 수 있다는 기대감이 작용했다는 관측이다.경영권 분쟁 불씨와는 관계가 없는 피어그룹 종목도 같은 날 덩달아 상승세를 이어가는 중이다. 삼화페인트로 인해 페인트 업종에 대한 투자자들의 관심이 쏠린 영향으로 해석된다.조광페인트(004910)는 1.9% 상승했고,노루페인트(090350)는 1.1% 올랐다.', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004588823', 'https://imgnews.pstatic.net/image/011/2026/02/10/0004588823_001_20260210143813781.png?type=w800', 'NEWS_ENERGY', NULL, '2026-02-10 14:37:10', 0, true, '2026-03-09 06:21:09.990986') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1077, '씨아이테크, 작년 당기순익 146억원…흑자 전환', '씨아이테크는 지난해 연결 기준 당기순이익이 146억원으로 전년 대비 흑자 전환했다고 6일 공시했다. 같은 기간 영업이익은 20억원으로 흑자전환했고, 매출액은 414억으로 13% 감소한 것으로 집계됐다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000080431', 'https://imgnews.pstatic.net/image/293/2026/03/06/0000080431_001_20260306144709549.png?type=w800', 'NEWS_ETC', NULL, '2026-03-06 14:47:09', 0, true, '2026-03-09 06:21:16.476288') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1078, '씨아이테크, 지난해 영업익 20억…흑자전환', '[헤럴드경제=증권부] 씨아이테크는 지난해 연결기준 영업이익이 20억174만원으로 전년대비 흑자전환했다고 6일 공시했다.같은 기간 매출액은 414억4980만원으로 12.62% 감소한 것으로 집계됐다.당기순이익은 146억2106만원으로 흑자전환했다.', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002609634', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2026-03-06 14:05:07', 0, true, '2026-03-09 06:21:16.476288') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1079, '기업공시[2월 27일]', '<코스피>▲바이오노트(377740)=37억 원 규모 자기주식 소각 결정 ▲HD현대중공업(329180)=3724억 원 규모 컨테이너선 6척 수주 ▲주연테크(044380)=보통주 5대 1 주식 병합 결정 ▲씨아이테크(004920)=자회사 케빅 흡수 합병 결정 ▲강원랜드(035250)=주당 950원 현금 배당 결정 ▲한전기술(052690)=완도금일 해상풍력 EPC 사전착수역무 323억 원에 계약 ▲DB손해보험(005830)=7981억 원 규모 자기주식 소각 결정 ▲현대리바트(079430)=1141억 이라크 해수처리시설 공사 수주 ▲현금배당결정=토니모리(214420)보통주 1주당 50원,에이피알(278470)1500원,모나미(005360)30원<코스닥>▲삼화네트웍스(046390)=보통주 액면가 200원에서 500원으로 주식병합 결정 ▲하이즈항공(221840)=대한항공과 100억 원 규모 보잉 787 구조물 관련 신규 계약 체결 ▲세아메카닉스(396300)=136억 원 규모 구미 국가산업단지 토지 구미데이터인프라솔루션에 양도 결정 ▲DH오토웨어(025440)=임시주총서 사내이사 문경호 선임 ▲아크솔루션스(203690)=유상증자결정(제3자배정) 철회▲마이크로투나노(424980)=SK하이닉스와 102억 원 규모 반도체용 프로브카드 공급 계약 체결 ▲에코글로우(159910)=리브위드와 30억원 규모 ESG 캠페인 계약 체결 ▲LS티라유텍(322180)=우선주 1만 주를 8867주로 병합하는 감자 결정 ▲사토시홀딩스(223310)=보통주 액면가 100원에서 500원으로 주식병합 결정 ▲대성파인텍(104040)=보통주 액면가 100원에서 500원으로 주식병합 결정 ▲심텍홀딩스(036710)=종속회사 심텍 인터내셔널, 말레이시아 인쇄회로기판 제조업체 지분 68.6% 258억 원에 인수 결정 ▲글로벌텍스프리(204620)=신임 대표이사에 오태석 한성크린텍 대표 선임 ▲현금배당결정=제이아이테크(417500)보통주 1주당 100원,고스트스튜디오(950190)554원,대한과학(131220)125원', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004594332', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2026-02-27 16:51:07', 0, true, '2026-03-09 06:21:16.476288') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1080, '가덕도신공항 접근도로 공사 ‘수의계약’ 전환', '[KBS 부산]가덕도신공항 건설의 핵심 기반시설인 접근도로 건설사업이 7차례 유찰 끝에 수의계약 방식으로 전환됩니다.국회 국토교통위원회 소속 김도읍 의원은 "부산지방국토관리청은 해당 사업을 수의계약으로 전환하고, 단독 응찰한 한신공영 컨소시엄을 대상으로 절차 진행에 들어갔다"고 밝혔습니다.가덕도신공항 접근도로는 강서구 대항동에서 송정동까지 이어지는 9.3km 구간 사업으로, 내년에 착공할 예정입니다.', NULL, 'KBS', 'https://n.news.naver.com/mnews/article/056/0012135607', 'https://imgnews.pstatic.net/image/056/2026/03/05/0012135607_001_20260305083754921.jpg?type=w800', 'NEWS_CONSTRUCT', NULL, '2026-03-05 08:07:37', 0, true, '2026-03-09 06:21:24.825338') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1081, '신라교역, 지난해 영업손 15억…적자전환', '[헤럴드경제=증권부] 신라교역은 지난해 연결기준 영업손실이 14억7587만원으로 전년대비 적자전환했다고 3일 공시했다.같은 기간 매출액은 4547억4113만원으로 8.3% 감소한 것으로 나타났다.당기순이익은 145억4958만원으로 63.8% 줄어든 것으로 집계됐다.', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002595261', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2026-02-03 15:05:08', 0, true, '2026-03-09 06:21:29.869536') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1082, '기업 공시[12월 10일]', '[서울경제]<코스피 공시>▲동남합성(023450)=12억 원 규모 자사주 취득 결정 ▲신라교역(004970)=정관 개정으로 배당기준일을 결산기말에서 ‘이사회가 정하는 날’로 변경 ▲LG(003550)=정관 개정으로 배당기준일을 결산기말에서 ‘이사회에서 정하는 날’로 변경<코스닥 공시>▲서부T&D(006730)=보통주 1주당 100원 결산 현금배당 ▲케이피에프(024880)=36억 원 규모 자사주 처분 결정 ▲중앙백신(072020)=20억 원 규모 자기주식 소각 결정 ▲SKAI(357880)=144억 원 규모 제3자배정 유상증자 결정 ▲프레스티지바이오로직스(334970)=19억 원 규모 의약품 위탁생산계약 체결 ▲티에스아이(277880)=LG엔솔 미시간과 266억 원 규모 2차전지 믹싱시스템 공급 계약', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004565729', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2025-12-10 16:30:17', 0, true, '2026-03-09 06:21:29.869536') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1107, '[단독] IBM, 국내 총판 3곳 재선정…기존 총판 중 대교CNS는 탈락', '씨플랫폼·쿠도커뮤니케이션·코오롱베니트 선정…SW·AI 역량 중심 재편뉴욕증권거래소에 표시된 IBM 로고 [사진=연합뉴스][디지털데일리 이안나기자] IBM이 국내 총판사(디스트리뷰터)를 재선정하며 소프트웨어와 AI 중심 사업 구조로의 전환을 가속화한다.6일 업계에 따르면 IBM은 최근 국내 총판 선정 절차를 마무리하고 씨플랫폼(아이티센그룹), 코오롱베니트, 쿠도커뮤니케이션 등 3개사를 새 총판으로 확정했다. 새 체계는 오는 4월 1일부터 출범한다.이번 선정에는 기존 총판 3곳(씨플랫폼, 코오롱베니트, 대교CNS)과 신규 지원 2곳 등 5개 기업이 제안서를 제출했다. 결과적으로 씨플랫폼과 코오롱베니트가 재선정됐고 쿠도커뮤니케이션이 새롭게 총판으로 합류했다. 대교CNS는 이번 선정에서 제외됐다.업계에 따르면 기존엔 총판사 3곳 외에도 특정 솔루션 총판 비슷한 역할을 하던 곳들이 여러 곳 있었으나 이번에 3곳으로 압축됐다. 다만 총판사 수를 3곳으로 유지한 것은 한국 시장 상황을 고려한 결과로 풀이된다.선정된 총판들 공통점은 소프트웨어와 AI 사업을 강조했다는 점이다. 쿠도커뮤니케이션은 독일 소프트웨어AG의 웹메소드(webMethods) 제품을 국내에서 공급해 오다가 2023년 12월 IBM이 해당 제품군을 인수하면서 2024년 7월부터 IBM 파트너사로 활동해 왔다. 이번 총판 선정 과정에서 소프트웨어 역량 확대 방안을 제시하며 파트너사에서 총판사로 사업 범위를 확대하게 됐다.아이티센그룹 계열사인 씨플랫폼은 IBM 파트너사로 출발해 오랜 기간 서버를 비롯한 다양한 IBM 제품군을 취급해왔다. 다만 메인프레임보다는 왓슨x 등 IBM AI 플랫폼과 소프트웨어 사업에 집중해왔으며 이번 재선정에서도 소프트웨어 역량을 강조했다.코오롱베니트 역시 기존 총판 지위를 유지했다. 이전부터 동진쎄미캠 왓슨x 구축 등 IBM AI·소프트웨어 사업 확대에 나서온 데 이어 이번 선정에선 파트너사 네트워크와 지방 지사 운영 등 전국 단위 유통 범위를 경쟁력으로 내세웠다.IBM은 선정 과정에서 소프트웨어 비즈니스 확장 방안과 서비스형소프트웨어(SaaS) 비즈니스 확장 방안 등을 주요 평가 기준으로 제시했다. 하이브리드 클라우드 중심 전략과 산업별 선도 역량 활용, 소프트웨어 중심 성장 등을 사업 방향으로 강조한 것으로 전해진다.이는 그동안 하드웨어 중심으로 사업을 전개해 온 IBM 체질 개선 의지를 반영한 것으로 풀이된다. IBM은 레드햇 인수 이후 하이브리드 클라우드와 AI 소프트웨어 역량 강화에 주력해 왔으며 국내 유통 채널 역시 이러한 방향에 맞춰 재정비하고 있다.업계 관계자는 “IBM이 기존 하드웨어 중심 유통 구조에서 소프트웨어 비즈니스를 확대하는 방향으로 재편을 진행한 것”이라며 “AI 중심 시장 변화에 대응하기 위한 움직임”이라고 평가했다.', NULL, '디지털데일리', 'https://n.news.naver.com/mnews/article/138/0002219723', 'https://imgnews.pstatic.net/image/138/2026/03/06/0002219723_001_20260306131414486.jpg?type=w800', 'NEWS_SEMI', NULL, '2026-03-06 09:17:10', 0, true, '2026-03-09 06:22:40.581941') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1161, '한국자산신탁·한국토지신탁, 작년 영업이익 60% 급감한 이유는', '한국자산신탁, 영업이익 100억 밑으로한국토지신탁도 전년比 57.2%↓지방 중심 차입형 부동산 신탁 영향수주 늘었지만 지방 중심 미분양 쌓여서울 강남구 역삼동 한국토지신탁, 한국자산신탁 본사. /각 사 제공국내 부동산신탁사 1, 2위 업체인 한국토지신탁과 한국자산신탁이 동반 ‘어닝쇼크(실적 충격)’에 빠졌다. 지난해 영업이익이 전년보다 60%가량 급감했다. 지방 사업장을 중심으로 한 차입형 신탁사업 등에서 비용이 늘고 이익은 발생하지 않은 것이 영업이익 급감의 원인으로 분석된다.9일 각 사 잠정 실적 공시에 따르면 지난해 한국자산신탁의 영업이익은 90억원(별도 기준)으로 집계됐다. 전년 231억원보다 61.1%(141억원) 감소했다. 이 회사의 영업이익은 2024년부터 2년 연속 줄었다. 2023년 1046억원을 기록했던 영업이익은 2024년에는 200억원대로 급감했고 지난해에는 100억원 선 아래로 내려앉았다.영업이익이 줄어든 것은 수수료 등으로 벌어들이는 수익이 줄고 비용은 늘어났기 때문이다. 한국자산신탁의 지난해 수수료 수익은 617억원으로 전년(850억원)보다 233억원(27.4%) 감소했다. 비용도 계속 늘고 있다. 한국자산신탁의 이자 비용은 2024년 139억원에서 지난해 261억원으로 100억원 넘게 증가했다. 다만 영업 외 수익이 증가하며 당기순이익은 전년 165억원에서 254억원으로 늘었다. 한국자산신탁 관계자는 “매출이 줄고 비용이 늘어나면서 영업이익은 감소했지만, 영업 외 수익 증가에 따라 당기순이익은 늘었다”고 설명했다.한국토지신탁도 지난해 영업이익이 크게 줄었다. 한국토지신탁의 지난해 영업이익은 283억원으로 집계됐다. 전년 663억원보다 57.2%(379억원) 줄었다. 수수료 등으로 벌어들이는 돈이 줄고 판매관리비 등 영업에 필요한 비용이 늘어나는 구조가 이익 감소로 이어졌다.한국토지신탁과 한국자산신탁은 총 자산 기준 국내 14개 부동산신탁사 중 1, 2위 기업이며 유가증권시장 상장사다. 한국토지신탁의 자산 규모가 1조6499억원(2025년 3분기 기준)으로 1위, 한국자산신탁이 1조2997억원으로 2위다.한국토지신탁의 최대주주는 차정훈 회장이 이끄는 엠케이인베스트먼트(지분율 24.25%)와 엠케이전자(지분율 11.21%)다. 또 한국토지신탁은 키스톤PE와 조성한 펀드인 ‘키스톤에코프라임’을 통해 동부건설(지분율 56.22%)을 보유하고 있다.한국자산신탁은 국내 최대 부동산 시행사인 엠디엠(MDM)그룹 계열 신탁사다. 엠디엠이 지분 28.76%, 엠디엠플러스가 10.13% 등 엠디엠과 특수관계인 지분율이 54.34%다.그래픽=손민균업계에서는 1, 2위 부동산 신탁사의 수익성 악화가 차입형 토지신탁 부실의 여파라는 분석도 나온다. 차입형 토지신탁은 자금이나 개발 노하우가 부족한 토지 소유자를 대신해 신탁사가 토지를 수탁받아 직접 자금을 조달(차입)하고, 인허가부터 분양, 준공까지 전 과정을 책임지고 개발한 뒤 수익을 돌려주는 것이다. 신탁사가 사업 위험을 부담하며, 보통 매출의 3~4%를 보수(수수료)로 받는다. 지난해 한국자산신탁의 수주액(신탁수수료 약정액)은 총 981억원, 이 중 차입형 토지신탁이 590억원(정비사업 430억원+일반사업 160억원)으로 60.1%를 차지했다.한국토지신탁도 차입형 토지신탁이 늘었다. 지난해 누적 기준 차입형 토지신탁 수주액 규모는 1154억원으로 전년보다 615억원 증가했다. 현재 진행되고 있는 차입형 토지신탁 사업 수는 24개소, 1만1451가구 규모다. 이 사업장의 공사 공정률은 평균 30.3%(2025년 12월 말 기준)이지만 분양률은 49.3%에 그친다.윤재성 나이스신용평가 수석연구원은 “한국토지신탁과 한국자산신탁은 차입형 부동산 신탁 사업이 전반적으로 좋지 않았고 이 부문에서 대손 비용이 늘었다”고 설명했다.업계 관계자는 “차입형 부동산 신탁은 서울이나 수도권에서는 거의 이뤄지지 않고 보통 지방에 있는 사업장에서 많이 이뤄진다”며 “최근 지방 분양 시장이 굉장히 안 좋아 분양 수익이 줄었고 이익 감소가 진행되는 것”이라고 했다.', NULL, '조선비즈', 'https://n.news.naver.com/mnews/article/366/0001146921', 'https://imgnews.pstatic.net/image/366/2026/03/09/0001146921_001_20260309141512898.jpg?type=w800', 'NEWS_CONSTRUCT', NULL, '2026-03-09 14:15:12', 0, true, '2026-03-09 06:25:39.618828') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1083, '파파이스 M&A 매물로…매각가 500억 원 내외 [시그널]', '2021년 국내 시장 재진출매장 수 22곳으로 늘렸지만적자 쌓여 사업권 넘기기로[서울경제]이 기사는 2025년 12월 8일 18:40자본시장 나침반  ''시그널(Signal)''에 표출됐습니다.치킨·햄버거 프랜차이즈 파파이스 BI. 사진 제공=RBI치킨·햄버거 프랜차이즈 파파이스가 인수합병(M&A) 시장 매물로 나왔다. 파파이스는 신라교역이 파파이스 본사인 레스토랑브랜드인터내셔널(RBI)과 프랜차이즈 계약을 맺어 운영하고 있다. 이번 매각은 RBI가 주도한 것으로 알려졌다.8일 투자은행(IB) 업계에 따르면 RBI는 삼일PwC를 매각 주관사로 선정해 국내에서 파파이스를 운영할 기업을 물색하고 있다. 매각 추진 가격은 500억 원 내외다. 매각 측은 다수의 국내외 사모펀드(PEF) 운용사를 접촉한 것으로 전해졌다. 그동안 BHC, 할리스, 맘스터치, 공차, 투썸플레이스 등 여러 식음료(F&B) 기업은 PEF 운용사에 인수돼 규모를 키웠다. 신사업을 찾는 중소·중견기업이나 국내 시장 진출에 관심을 가진 해외 F&B 기업도 인수 후보군으로 거론된다.파파이스는 1972년 미국에서 만들어진 브랜드로 1994년 한국 시장에 첫발을 들였다. 대한제당 계열사 TS푸드앤시스템이 운영을 맡으며 한때 약 200개에 달하는 점포를 운영하는 등 인기를 끌었다. 하지만 시장 트렌드 변화로 입지가 좁아지면서 TS푸드앤시스템은 2020년 파파이스 사업을 포기했다.현재 운영 기업인 신라교역은 2021년 RBI와 마스터 프랜차이즈 계약을 맺어 파파이스를 국내 시장에 다시 들여왔다. 자회사 넌럭셔리어스컴퍼니를 설립해 서울 강남역 인근에 1호점을 열었고 신규 출점을 이어가며 매장 수를 22곳으로 늘렸다. 하지만 시장 내 출혈 경쟁으로 적자가 쌓여 한국 사업권을 넘기게 된 것으로 알려졌다. 넌럭셔리어스컴퍼니는 올해 3분기 누적 매출 97억 원, 순손실 52억 원을 냈다. 신라교역은 약 4년 동안 파파이스 운영을 위해 넌력셔리어스컴퍼니에 유상증자 방식으로 513억 원을 투입했다.파파이스 M&A 매물로…매각가 500억 원 내외 [시그널]', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004564970', 'https://imgnews.pstatic.net/image/011/2025/12/09/0004564970_001_20251209064709824.jpg?type=w800', 'NEWS_ETC', NULL, '2025-12-09 06:02:10', 0, true, '2026-03-09 06:21:29.869536') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1084, '[미국·이란 전쟁]사우디 공략 나선 네이버, 중동 사태에 ''발동동''', '미국의 이란 타격으로 네옴시티·뉴 무라바·슈퍼앱 등 사업 전망 불투명네이버가 중동 진출을 위해 수주했던 사우디아라비아 디지털 트윈 사업이 지정학적 리스크에 직면했다. 사진은 네옴시티 ''더라인''의 모습. /사진=네옴시티네이버가 ''제2의 중동 붐''을 기치로 내걸고 사우디아라비아에서 추진 중인 디지털 트윈 및 스마트시티 사업이 ''이란 사태''라는 대외적 악재를 맞았다. 지난해 한 차례 사업 축소를 겪은 데 이어 지정학적 리스크까지 겹치면서 네이버가 공들여온 중동 사업이 위기에 놓일 수 있다는 관측이 나온다.네이버는 2023년 10월 사우디 자치행정주택부(MOMRAH)로부터 1억달러(1466억원) 규모의 디지털 트윈 구축 사업을 수주하며 본격적으로 중동 시장 공략에 나섰다. 네옴시티는 사우디 북서부 홍해 인근에 조성되는 친환경 에너지 자급자족 도시로 면적이 서울의 44배에 달하는 2만6500km²다. 공식 사업비는 약 5000억달러(733조원)에 이른다.이 프로젝트는 무함마드 빈 살만 사우디 왕세자가 추진하는 ''비전 2030'' 프로젝트의 핵심 사업으로 2030년까지 수도 리야드를 포함해 메디나·제다·담맘·메카 등 주요 도시에 클라우드 기반 디지털 트윈 플랫폼을 구축하는 것을 논의 중이다.네이버는 대규모 도시 단위 디지털 트윈 구축 솔루션 ''어라이크(ALIKE)'' 기술을 통해 도시의 3D 모델, 로드레이아웃, HD맵 등 핵심 데이터들을 통합 제작해왔다. 메카·메디나·제다 3개 도시의 디지털 트윈 플랫폼은 지난해 6월 구축을 완료했고 리야드와 담맘의 추가 작업을 앞두고 있다.이란과 이스라엘 간의 갈등 격화로 사우디 주요 인프라에 대한 위협이 가시화되며 현지 작업 인력의 안전과 물류 수송에 비상이 걸렸다. 사우디 수도 리야드 소재 미국 대사관이 드론 두 대의 공격을 받았고 사우디 최대 정유시설인 라스 타누라 정유 공장은 가동을 중단했다. 외교부는 지난 2일 전쟁 확산 우려에 따라 사우디에 여행 경보인 ''특별여행주의보''를 발령했다.네이버가 공들였던 중동 시장 진출 사업이 지정학적 리스크를 맞이했다. 그래픽은 사우디아라비아 디지털 트윈 플랫폼 사용화면 중 홍수 시뮬레이션. /그래픽=네이버랩스중동 정세 악화로 사우디 사업 추진이 제약을 받게 되면서 ''오일 머니'' 확보에 주력해온 네이버의 사업 전망도 불투명해졌다. 네이버는 지난해 6월 사우디 국부펀드(PIF)가 주도하는 미래형 신도시 개발 프로젝트 ''뉴 무라바(New Murabba)''와 로봇·공간지능·스마트 시티 분야 기술 협력을 위한 업무협약(MOU)도 체결했다. 뉴 무라바는 리야드 중심에 15km² 규모로 조성 중인 도시로 사우디 ''비전 2030''의 또 다른 핵심 사업이다.연내 구축을 목표로 추진 중이던 ''슈퍼앱 프로젝트''역시 난항이 예상된다. 네이버는 이를 위해 지난해 전략합작법인 ''네이버 이노베이션(NAVER Innovation)''을 현지에 설립했다. 이 곳에서 사우디 생활 전반을 돕는 지도 기반 슈퍼앱의 구축·운영, 디지털 트윈 플랫폼 사업을 추진하고 있다. 지난달에는 사우디 국립 과학기술연구기관인 킹 압둘라지즈 과학기술도시(KACST)와 아랍어 특화 거대언어모델(LLM) 개발을 위한 업무협약도 체결했다.사우디 정부의 사업 축소 우려가 커지고 있다. 네옴시티 프로젝트에 참여했던 성신양회는 2023년 현지 법인을 설립하고 공장을 가동했으나 1년 6개월 만에 가동을 중단하고 현지 인력을 일부 철수시켰다. 네옴시티 완공이 지연됨에 따라 네이버의 기술력도 투입이 밀린 상태다.사우디 정부가 2030년 리야드 엑스포와 2034년 월드컵 준비에 집중하면서 네옴시티가 후순위로 밀리고 있다는 지적도 나온다. 네옴시티의 핵심인 선형 도시 ''더 라인(The Line)''은 당초 170km 구간에 150만명 거주를 목표로 했으나 최근 재정 압박으로 인해 2030년까지 완공 가능한 구간을 2.4km 수준으로 대폭 축소하고 입주 예상 인구도 30만명 미만으로 낮추는 등 사업 계획이 전면 수정된 상태다.네이버 관계자는 "현재까지 사우디 현지 사업은 계약된 일정에 따라 진행 중"이라며 "지정학적 상황을 예의주시하고 있으나 사업 철회나 변경을 논의할 단계는 아니다"라고 밝혔다.', NULL, '동행미디어 시대', 'https://n.news.naver.com/mnews/article/417/0001132346', 'https://imgnews.pstatic.net/image/417/2026/03/03/0001132346_001_20260303174416573.gif?type=w800', 'NEWS_ETC', NULL, '2026-03-03 16:56:13', 0, true, '2026-03-09 06:21:39.371208') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1085, '"환경파괴 주범?" 성신양회, 친환경 시멘트 만든다… 저탄소 연구 추진', '친환경 규제 대응 강화성신양회 단양공장./사진=성신양회국내 시멘트 시장 점유율(내수 출하량 기준) 5위 기업인 성신양회가 친환경 시멘트로 불리는 저탄소 시멘트 생산을 위한 작업에 본격 착수했다. 성신양회는 저탄소 시멘트를 통해 시멘트 산업이 환경파괴 주범이라는 오명을 씻고, 친환경 시멘트 시장 공략으로 실적개선 속도도 높이겠다는 방침이다.2일 관련 업계에 따르면 성신양회는 이달 중순 단양공장에서 저탄소 시멘트 생산기술 안정성·경제성 등을 검증하는 작업인 ''저탄소 연료화 실증 연구''를 추진할 예정이다. 성신양회는 저탄소 연료화 실증 연구를 마치는대로 산업통상자원부 승인을 거쳐 양산에 들어갈 계획이다.그 첫 단계로 지난해 10월 성신양회는 저탄소 연료화 기술개발 실증설비를 설치한 후 10여명으로 구성한 연구팀을 실증 작업에 투입했다. 저탄소 시멘트 양산 시점은 이르면 올해 3분기, 늦어도 4분기다.저탄소 시멘트는 일반 시멘트보다 석회석 함량이 50% 이상 적은 시멘트다. 저탄소 연료화 실증 연구는 시멘트 주원료인 석회석을 분해하는 과정에서 발생하는  이산화탄소·미세먼지를  CCU(탄소·포집) 기술로 포집한 후 합성가스로 전환해 메탄올 등 청정연료를 생산하는 통합공정 기술을 실증하는 것이다. 석회석은 1450℃ 열분해 공정을 거치는데 이 과정에서 대량의 온실가스가 발생한다.즉 이산화탄소·미세먼지를 포집해 온실가스 발생량을 최대한 줄이는 게 저탄소 시멘트 생산기술의 핵심인 셈이다.성신양회는 저탄소 시멘트를 통해 온실가스 배출량을 감축하고 환경 규제에 대응한다는 방침이다. 실제 시멘트 산업은 국내 산업부문 온실가스 배출의 약 10%를 차지하는 대표적인 ''온실가스 다배출 업종''으로 꼽힌다.통상 업계에선 시멘트 산업 온실가스 배출량 중 60~65%가 석회석 분해 과정에서 발생하는 것으로 추정한다.특히 지난해 11월 정부가 ''2035 국가온실가스 감축목표(NDC)''를 발표한 이후 시멘트업계의 친환경화는 더 시급해졌다.  정부는 시멘트업계에 2035년까지 온실가스 배출량을 2018년(7억4230만tCO2eq) 대비 61%(4억5280만tCO2eq) 줄어든 2억8950tCO2eq까지 감축하라고 권고했다.업계 한 관계자는 "정부 규제가 갈수록 강화하면서 친환경 기술과 설비에 대한 투자가 절실한 상황"이라고 말했다. 성신양회는 환경 규제 강화와 탄소 가격 상승 등으로 저탄소 등에 따른 친환경 시멘트 시장 성장 잠재력에도 주목했다.한국시멘트협회에 따르면 2026년부터 2031년까지 매년 친환경 시멘트 시장은 매년 7.1% 성장할 것으로 보인다. 성신양회는 친환경 시멘트 시장 공략을 서둘러 실적을 개선한다는 방침이다.금융감독원 전자공시시스템에 따르면 성신양회의 지난해 3분기 누적 기준 순이익은 140억6594만원으로 전년 동기 대비 65.3% 감소했다.성신양회 관계자는 "저탄소 시멘트 생산을 통해 친환경 규제에 대응할 것"이라고 말했다.업계 한 관계자는 "규제 의무화, 탄소 가격 상승, 저탄소 소재를 선호하는 조달 규정 등으로 인해 친환경 시멘트 시장은 틈새시장에서 공공 및 민간 프로젝트의 주류로 자리매김하는 중"이라고 전했다.', NULL, '동행미디어 시대', 'https://n.news.naver.com/mnews/article/417/0001127738', 'https://imgnews.pstatic.net/image/417/2026/02/02/0001127738_001_20260202140307690.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-02 14:02:18', 0, true, '2026-03-09 06:21:39.371208') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1086, '성신·한일 이어 아세아시멘트도 "수도권 쓰레기 반입 금지"', '단양 성신양회·한일시멘트 동참아세아시멘트 제천공장.(아세아시멘트 제공, 재판매 및 DB금지)/뉴스1(제천ㆍ단양=뉴스1) 손도언 기자 = 충북 제천지역 시멘트 업체가 단양지역 업체들처럼 ''수도권 생활폐기물을 반입·처리하지 않겠다''고 선언했다.아세아시멘트 제천공장은 "수도권 종량제 생활폐기물이 당사 사업장으로 반입·처리되는 일은 없다"고 1일 밝혔다.공장은 "이를 원천적으로 차단하기 위해 반입 처리업체 관리·감독을 더 강화하고 있다"고 전했다.제천공장은 "현재 폐기물 반입 과정에서 발생지, 처리경로 등을 철저히 확인하고 있다"며 "반입업체 정기 점검 및 서류 검증을 통해 위반 가능성을 사전 차단하고 있다"고 설명했다.단양군과 지역 시멘트업체 ''수도권 반입폐기물 금지'' 상생협약식.(단양군 제공. 재판매 및 DB금지) /뉴스1단양지역에 시멘트공장을 둔 성신양회·한일시멘트는 지난달 22일 단양군과 수도권 생활폐기물 반입 금지 협약을 체결하고 수도권 종량제 폐기물을 반입하지 않겠다고 밝혔다. 수도권 생활폐기물 직매립 금지 정책으로 일부 수도권 종량제 생활폐기물이 시멘트공장으로 유입될 수 있을 것으로 보고, 시멘트 업체와 단양군이 선제 조치에 나선 것이다.제천시도 외부 폐기물의 불법 반입을 차단하기 위해 감시 체계를 강화하고 있다. 특히 제천시는 위반 사례가 적발될 경우 강력한 행정처분과 사법 대응에 나설 방침이라고 설명했다.', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008746523', 'https://imgnews.pstatic.net/image/421/2026/02/01/0008746523_001_20260201131515355.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-01 12:44:24', 0, true, '2026-03-09 06:21:39.371208') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1087, '[개정상법 후폭풍] 직격탄 맞은 SK, 6조 자사주 선택지 소멸', 'SK 서린빌딩 전경 /사진제공=SK상법 개정으로 자기주식 의무 소각이 도입되면서 SK의 재무·지배구조 전략에 변화가 불가피해졌다. 자사주를 장기간 보유하며 지배력 보완과 구조 개편에 활용해온 기존 방식이 제도적으로 차단됐기 때문이다.올 2월 말 국회 본회의를 통과한 3차 개정 상법은 상장사가 자기주식을 새로 취득할 경우 1년 이내 소각하도록 의무화했다. 기존 보유분 역시 일정 유예기간 이후에는 소각을 원칙으로 한다. 임직원 보상 등 제한적인 경우에만 보유가 허용되며 이 경우에도 매년 주주총회 승인을 받아야 한다. 이달 열리는 SK㈜ 정기 주주총회는 자사주 처리 방향이 처음으로 논의되는 자리가 될 전망이다.합병 자사주 15%…지배구조 변수 부상6일 재계에 따르면 3차 상법 개정안의 직접적인 영향권에 있는 곳은 SK그룹 지주사인 SK㈜다. SK㈜는 현재 SK스퀘어를 통한 SK하이닉스 간접 출자를 비롯해 SK이노베이션, SK텔레콤 등 핵심 계열사를 지배하고 있다.지난해 3분기 말 기준 SK㈜가 보유한 자사주는 1798만2486주로 총 발행주식수(7306만 8838주)의 24.61%에 달한다. 주요 그룹 지주사 가운데 롯데지주(33%)에 이어 두 번째로 높은 수준이다. 현 주가 기준으로는 약 6조원 규모로 추산된다.자사주는 기업이 경영권 방어와 지배구조 재편 과정에서 활용해온 대표 수단이다. 특히 지주사 체제에서는 총수 일가의 직접 지분율을 보완하는 간접적인 통제 장치로 기능해왔다. 인적분할이나 합병, 계열사 편입 과정에서 지분 구조를 조정하거나 거래 대가로 활용되는 사례도 적지 않다.SK㈜가 보유한 자사주 24.61%는 성격이 다른 두 갈래로 나뉜다. 9.52%(695만7461주)는 기업가치 제고와 주가 안정을 목적으로 시장에서 직접 매입한 물량이다. 나머지 15.09%(1102만5025주)는 2015년 SK C&C와의 합병 과정에서 발생했다. 당시 SK C&C가 보유하고 있던 SK 지분이 합병 이후 자사주로 전환되면서 현재 보유 구조의 근간이 형성됐다.지배구조 측면에서도 자사주는 중요한 역할을 해왔다. 최태원 회장의 SK㈜ 지분율은 17.90%, 특수관계인 포함 합산 지분율은 약 25.42%다. 자사주는 의결권이 없지만 발행주식 수에는 포함되기 때문에 경영권 공격이 발생할 경우 우호 세력에 매각해 의결권을 확보하는 방식으로 방어 수단으로 활용될 수 있다.자사주가 모두 소각될 경우 수치상 대주주 지분율은 일부 상승하지만 외부 세력에 대응할 수 있는 전략적 수단은 줄어들게 된다. 그만큼 경영권 방어 여력도 약화될 수 있다는 분석이 나온다.세무 부담도 만만치 않다. 현행 세법은 자사주 소각 시 소각 시점 주가가 취득가액보다 높으면 그 차액을 배당으로 간주해 의제배당 과세를 적용한다. SK C&C 합병 당시 발생한 합병차익에 대해서는 그간 과세가 이연돼 왔는데 합병 취득분까지 소각 대상에 포함될 경우 이연됐던 이익이 확정되면서 과세 대상이 된다.업계에서는 SK㈜가 자사주를 전량 소각할 경우 부담해야 할 법인세가 약 5000억원에 이를 수 있다고 본다. 회계상 조정이 아니라 실제 현금 유출을 수반하는 비용이다.경영권 방어 약화 우려자사주 소각 자체는 유통주식 수 감소로 주당순이익(EPS)을 높이는 효과가 있다. 그러나 지주사인 SK㈜의 경우 자사주가 단순한 주주환원 수단을 넘어 지배구조 설계의 일부로 활용돼 왔다는 점에서 영향이 더 크다.자사주를 활용한 비현금성 거래 수단이 제한되면 향후 지배구조 개편이나 계열사 정리 과정에서 현금 또는 외부 자본 조달 의존도가 높아질 가능성도 있다.자사주 의무소각으로 SK㈜의 경영권 방어 수단이 제거되는 동안 대안 제도는 마련되지 않고 있다. 국내에는 미국의 포이즌필이나 차등의결권처럼 기업이 활용할 수 있는 법적 경영권 방어 장치가 사실상 없다. 과거 2003년 외국계 헤지펀드 소버린이 지분 14.99%를 확보하며 최태원 회장 퇴진을 요구했던 사태보다 더 취약한 환경에 처할 수 있다는 우려가 재계 안팎에서 나온다.최태원 회장과 노소영 아트센터나비 관장 간 재산분할 파기환송심이라는 오너 리스크도 변수다. 대규모 재산분할이 확정될 경우 최 회장 측 SK㈜ 지분의 유동화 가능성이 거론되는 상황에서 자사주 처리 방향은 소송 진행 상황과도 맞물릴 수 있다.SK㈜ 관계자는 "유예기간 내 자사주 소각 일정과 방식, 세금 부담 최소화 방안, 향후 지배구조 안정성 확보 방안을 종합적으로 검토할 것"이라고 말했다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000080418', 'https://imgnews.pstatic.net/image/293/2026/03/06/0000080418_001_20260306131008371.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-06 13:10:08', 0, true, '2026-03-09 06:21:47.429239') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1088, '거래소, GS건설·LG화학·하나금융 등 공시우수법인 선정', '[서울=뉴시스] 박주연 기자 = 한국거래소가 GS건설과 LG화학, 하나금융지주 등을 ''공시우수법인''으로 선정해 시상했다.거래소는 5일 서울 사옥에서 ''2025년도 증권시장 공시우수법인'' 시상식을 개최했다.코스피 상장사 중에서는  공시우수법인 8개사와 영문공시우수법인 3개사, 공시제도개선실무협의회 우수위원 1명이 선정됐다.공시우수법인으로는 GS건설, LG유플러스, LG화학, 대한항공, 유한양행, 하나금융지주, 한국항공우주산업, 한화가 선정됐다.영문공시우수법인으로는 LIG넥스원, 롯데케미칼, 한화시스템이, 공시우수위원으로는 롯데지주 공시담당자 배덕호 수석이 선정됐다.코스닥시장에서는 장기 성실공시 우수법인 2개사, IR활동 우수법인 1개사, 종합평가 우수법인 12개사 등 15개사가 선정됐다.장기 성실공시 우수법인으로는 한국알콜산업, 서울반도체가, IR활동 우수법인으로는 고영테크놀러지가 선정됐다.종합평가 우수법인으로는 코미코, 에스에프에이, 현대이지웰, 휴젤, 에이피시스템, 슈프리마, 이녹스첨단소재, NHN KCP, 헥토파이낸셜, 위메이드, 티씨케이, 카카오게임즈가 선정됐다.코넥스시장에서는 프로젠이 공시우수법인, 노브메타파마가 IR우수법인으로 각각 선정됐다.공시우수법인으로 선정되면 불성실공시법인 지정 유예, 공시 담당자 연례교육 이수 면제 등의 혜택이 제공된다.코스피 상장사는 연부과금과 상장수수료가 1년간 면제되며 코넥스 기업은 불성실공시 벌점 감경 혜택을 받는다.거래소는 "어려운 경영환경 속에서도 성실히 공시 의무를 수행한 상장법인의 노고에 감사한다"며 "앞으로도 기업정보를 신속하고 정확하게 공시해 투자자와 적극적으로 소통하고 시장 신뢰도와 투명성을 높이기 위해 노력해 달라"고 당부했다.', NULL, '뉴시스', 'https://n.news.naver.com/mnews/article/003/0013804638', 'https://imgnews.pstatic.net/image/003/2026/03/05/NISI20260305_0002076988_web_20260305192823_20260305193316371.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-05 19:32:39', 0, true, '2026-03-09 06:21:47.429239') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1108, '코스피 연이틀 매도 사이드카...19만전자·90만닉스 무너져', '[특징주]머니투데이 특징주 그래픽 이미지코스피가 또다시 사이드카가 걸린 상황에서 장 초반 반도체주들이 일제히 급락하고 있다.4일 오전 9시2분 현재 거래소에서 삼성전자는 전 거래일 대비 1만1800원(6.05%) 하락한 18만3300원에 거래 중이다. SK하이닉스도 90만원을 내주며 갭하락해 89만1000원에 거래 중이다.이외에도 덕산하이메탈이 11%대 약세를 보이고 두산은 8%대 약세를 나타낸다. 하나마이크론은 7% 하락 중이고 동진쎄미켐은 6% 하락하고 있다. 리노공업, 원익IPS 등은 4% 하락 중이다.이란 사태로 증시 내 불확실성이 커지는 가운데 간밤 미국 증시에서도 기술주들이 동반 하락하며 반도체주들이 연일 급락을 이어가고 있다. 필라델피아반도체지수는 4% 하락 마감했다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005324935', 'https://imgnews.pstatic.net/image/008/2026/03/04/0005324935_001_20260304091811233.jpg?type=w800', 'NEWS_SEMI', NULL, '2026-03-04 09:07:54', 0, true, '2026-03-09 06:22:40.581941') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1162, '“찬탈 vs 정상화”…알로이스 창업 멤버 갈등 ''점입가경''', '포티스 동료들이 창업…OTT 셋톱박스로 성장10년 동업 균열…작년 주총서 본격 수면 위브럼테크 지분 매집 이후 ‘용병 의혹’ 제기권충식 우호지분 확보, 정기주총 표대결 예고창업 초기부터 10여년간 유지돼 온 코스닥 상장사알로이스의 경영권 공조 체제가 무너졌다. 권충식 전 대표이사와 신정관 현 대표, 이시영 연구소장이 일궈온 상장 신화는 이제 법적 공방과 경영권 분쟁이라는 진흙탕 싸움으로 번지는 모습이다. 갈등의 본질을 두고는 ''기습적 경영권 찬탈''(권충식 전 대표)과 ''소유·경영 분리의 정상화''(신정관 현 대표)라는 상반된 주장이 맞서고 있다.승부의 분수령은 이달 열릴 정기주주총회가 될 전망이다. 권 전 대표가 최근 주주와의 협력을 통해 지분을 늘리면서 현 경영진 측과의 지분 격차가 박빙 구도로 좁혀졌다. 이에 따라 이번 주총은 양측의 표 대결 양상으로 전개될 것으로 보인다.창업 멤버 3인 체제…알로이스 성장 기반알로이스는 2015년 9월 권충식 전 대표가 직전 근무처인㈜포티스에서 함께 일하던 신정관 현 대표와 이시영 연구소장 등과 함께 설립한 회사다. 당시 포티스의 셋톱박스 사업부는 만성 적자로 사업 중단 위기에 놓여 있었지만, 권 대표 등은 기술적 잠재력에 주목해 관련 지적재산권을 인수하고 독자 노선을 택했다.설립 초기부터 안드로이드 기반 OTT 셋톱박스 시장을 공략한 알로이스는 첫해 매출액의 25.3%를 연구개발(R&D)에 투입하는 등 기술력 확보에 집중했다. 유럽·중동 등 해외 시장으로 판로를 확대했고, 그 결과 연평균 97%에 달하는 매출 성장률을 기록했다. 기세에 힘입어 2019년에는 코스닥 상장에도 성공했다.상장 이후에도 매년 40억원 이상의 순이익을 올리며 안정적인 실적 흐름을 이어왔다. 이 과정에서 권 전 대표가 경영 전반을 총괄하고, 신 대표와 이 소장이 각각 영업과 기술을 맡는 구도가 정착됐다. 2024년 말 기준 이들 창립 멤버 3인의 합산 지분율은 35.55%로, 특수관계인 체제도 유지되고 있었다.2024년 말 기준 알로이스 지분 구조/사진=금융감독원작년 정기주총서 권충식 재선임 부결균열은 지난해 3월 정기주총에서 발생했다. 권 전 대표는 신 대표, 이 소장과 함께 사내이사로 재선임될 예정이었지만, 주총에서 두 사람이 권 전 대표의 재선임 안건에 반대표를 던지면서 상황이 급변했다. 결국 권 전 대표 안건만 부결됐고, 그는 경영 일선에서 물러나게 됐다.권 전 대표 측은 해당 사태를 치밀하게 기획된 경영권 찬탈 시나리오로 규정하고 있다. 알로이스의 주요 거래처인 ㈜브럼테크가 주가 하락기에 회사 주식을 매집해 반대표를 행사한 점을 근거로 제시한다. 권 전 대표에 따르면, 브럼테크는 지난 2024년 11월 추징보전조치 공시로 인해 알로이스 주가가 급락한 시점을 틈타 약 138만주에 달하는 지분을 매집했다.특히 권 전 대표 측은 주주명부 열람을 통해 나타난 브럼테크의 사후 행보를 문제 삼고 있다. 권 전 대표는 이사회 재편의 결정적 표를 던졌던 브럼테크가 지난해 보유 지분을 시장에 전량 매도해 현재 지분이 남아있지 않다고 밝혔다. 결과적으로 브럼테크가 저가에 주식을 사들여 의결권을 행사함으로써 자신을 축출하는 도구 역할을 수행했고, 이후 주식을 팔아 치워 차익까지 챙기고 떠났다는 주장이다.경영 조치 둘러싼 공방 확산정기주총 이후 이뤄진 조치들을 두고도 공방이 이어지고 있다. 경영진 교체 이후 알로이스가 브럼테크와 독점 계약을 체결하면서 판매 가격 협상력이 약화됐으며, 그 결과 이익이 특정 업체에 집중됐다는 것이 권 전 대표 측 주장이다.하지만 신정관 대표 측은 경영권 탈취 주장에 선을 그었다. 신 대표는 “지난해 정기주총 결정은 갑작스러운 조치가 아니라 회사의 지속 가능한 성장을 위한 소유와 경영의 분리 원칙을 이행한 것”이라며 “주주들의 합리적 판단에 따른 결과”라고 밝혔다.다만 그는 브럼테크의 지분 매집 경위, 독점 계약 체결 배경 등에 대한 구체적 질의에 “현 시점에서 사실 여부를 따지는 것은 적절치 않다”며 별도 입장을 밝히 않았다.종속회사 한국파일 투자를 둘러싼 판단 차이도 갈등의 배경으로 거론된다. 한국파일은 지난 2023년 PHC 파일 생산을 위해 설립한 알로이스의 종속회사로 권 전 대표 재임 시절 추진한 사업이다.신 대표는 한국파일 사업이 알로이스 규모를 고려할 때 약 300억원 이상이 투입된 대형 투자였다는 점을 지적한다. 권 전 대표 주도로 사업을 개시한 이후 매출 정체와 적자가 이어지면서 내부적으로 경영 관리에 대한 우려가 커졌다는 것이다.신 대표는 “사업이 기대만큼 성과를 내지 못했고 인사와 자금 운용 과정에서도 혼란이 있었다”며 “이를 바로잡지 못할 경우 모회사인 알로이스까지 흔들릴 수 있다는 위기감이 컸다”고 말했다. 한국파일에 대한 경영 책임과 리더십에 대한 재검토가 불가피하다고 판단했다는 것이 신 대표 측의 설명이다.반면 권 전 대표 측은 한국파일의 적자가 사업 초기 단계에서 불가피한 투자 과정이었다고 반박한다. PHC 파일 산업은 대규모 설비 투자가 필요한 장치 산업으로, 한국파일도 공장 부지 확보와 정지 작업 등을 거쳐 2024년 상반기 공장을 완공했고 같은 해 하반기부터 본격적인 영업을 시작했다.이후 지난해 상반기 현대산업개발과 대우건설, 동부건설, 호반건설 등의 협력업체로 등록되며 매출이 발생하기 시작했다. 이에 따라 올해부터는 연간 50억~80억원 수준의 순이익 창출도 가능하고, 현재의 적자는 사업 초기 투자 단계에서 나타난 일시 현상에 불과하다는 것이 권 전 대표 측 설명이다.시장에서는 결국 승부가 이달 예정된 정기주총에서 갈릴 것이라는 전망이 나온다. 권 전 대표는 최근 김민우 이노비엠케이알 대표 측과 주주간 협약을 체결하며 우군을 확보했다. 김 대표는 기존 알로이스 주주였으며, 특수관계인을 포함한 보유 지분은 약 4.97% 수준으로 파악된다.이로써 권 전 대표 측 연합 지분은 기존 16.63%에서 21.60%로 늘어나 신정관 대표·이시영 이사 측 합산 지분 20.21%를 약 1.39%포인트 앞서는 상황이다. 지분 격차가 크지 않은 만큼, 소액주주 표심과 위임장 확보 여부가 이번 주총 결과를 가를 핵심 변수로 꼽힌다.', NULL, '비즈워치', 'https://n.news.naver.com/mnews/article/648/0000045060', 'https://imgnews.pstatic.net/image/648/2026/03/09/0000045060_001_20260309141413347.jpg?type=w800', 'NEWS_CONSTRUCT', NULL, '2026-03-09 10:00:08', 0, true, '2026-03-09 06:25:39.618828') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1089, '롯데웰푸드, 신동빈 사내이사 재선임…자사주 10만주 소각도 추진', '주식매수청구권 행사로 취득한 보통주 소각…발행주식 1.07% 감소신동빈 롯데그룹 회장이 지난해 서울 송파구 롯데월드타워에서 열린 고 신격호 회장 5주기 추모식에서 추모를 마치고 임원들과 인사를 나누고 있는 모습. 2025.1.17 ⓒ 뉴스1 박세연 기자(서울=뉴스1) 배지윤 기자 = 롯데웰푸드가 신동빈 롯데그룹 회장의 사내이사 재선임 안건을 정기 주주총회에 상정한다.4일 금융감독원 전자공시에 따르면 롯데웰푸드(280360)는 이달 20일 서울 영등포구 본사에서 정기 주주총회를 열고 신 회장의 사내이사 재선임 안건을 의결할 예정이다.안건이 통과되면 신 회장은 임기 3년의 사내이사로 재선임된다. 신 회장은 현재 롯데그룹 회장과 롯데지주·롯데케미칼·롯데쇼핑 대표이사 등을 맡고 있으며 과거 롯데칠성음료 대표이사를 지낸 바 있다.이번 주총에서는 서정호 롯데웰푸드 부사장과 민준웅 재무전략부문장의 사내이사 신규 선임 안건도 함께 상정된다.롯데웰푸드는 자기주식 소각을 위한 자본금 감소 안건도 주총에 올린다. 주식매수청구권 행사로 취득한 보통주 10만주를 소각할 계획으로 발행주식 총수는 930만4574주에서 920만4574주로 줄어든다. 감자 비율은 약 1.07%다.', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008806634', 'https://imgnews.pstatic.net/image/421/2026/03/04/0008806634_001_20260304170422724.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-04 17:03:55', 0, true, '2026-03-09 06:21:47.429239') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1090, '트럼프 알래스카 LNG 발언에…이 기업 18%↑', '넥스틸 주가 추이/그래픽=윤선정도널드 트럼프 미국 대통령의 알래스카 LNG(액화천연가스) 발언에 넥스틸을 포함한 국내 강관업체들 주가가 일제히 급등했다.21일 거래소에서 넥스틸은 전 거래일 대비 1890원(18.17%) 오른 1만2290원에 거래를 마쳤다. 하이스틸(10.87%), 이렘(6.41%), 유에스티(5.53%), 휴스틸(2.37%) 등도 동반 상승 마감했다.20일(현지시각) 트럼프 대통령은 취임 1주년을 맞아 브리핑을 진행하며 자신의 역점 사업인 알래스카 파이프라인 사업에 대한 성과를 강조했다. 한국과 일본이 개발 사업을 위한 자금을 지원할 것이란 취지의 발언도 했다. 이에 송유관 사업을 하는 넥스틸 등 관련주 투심이 개선된 것으로 풀이된다.트럼프 대통령은 "아시아로 천연가스를 수출하기 위한 대규모 알래스카 파이프라인 프로젝트를 시작했다"며 "한국, 일본과 합의를 통해 전례 없는 자금을 확보했다"고 밝혔다.지난해 메리츠증권은 넥스틸이 미국 유정관 CAPA(생산능력)를 보유한만큼 알래스카 LNG 메인 파이프라인에 대응가능할 것으로 예상한다고 분석하기도 했다.하지만 트럼프 대통령 희망처럼 알래스카 가스관 프로젝트에 한국이 참여할지는 미지수다. 지난해 11월 발표된 한미 정상회담 공동 발표자료에는 한국의 대미 투자 대상에 에너지 분야가 포함된다고 명시됐지만 알래스카 사업이 구체적으로 언급되어 있지는 않았기 때문이다.한편 넥스틸의 실적은 내리막길을 걷고 있다. 2022년 영업이익 1813억원에서 2023년 1573억원, 2024년 632억원으로 하락했다. 지난해 3분기 영업이익은 전년동기대비 61% 감소한 54억원으로 집계됐다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005307576', 'https://imgnews.pstatic.net/image/008/2026/01/21/0005307576_001_20260122041658253.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-21 15:56:59', 0, true, '2026-03-09 06:21:55.219829') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1091, '트럼프 "알래스카 LNG 프로젝트 착수" 언급에 강관株 강세…넥스틸 20%대 급등', '하이스틸·이렘·유에스티 등 동반 강세연합뉴스국내 강관업체들의 주가가 일제히 강세다. 도널드 트럼프 미국 대통령의 LNG(액화천연가스) 관련 발언으로 가스관·강관 수요 확대 기대감이 주가에 반영된 모습이다.21일 한국거래소에 따르면 오전 10시 45분 기준 넥스틸은 전장(1만400원)보다 20.29% 급등한 1만2510원에 거래되고 있다. 거래량과 거래대금은 각각 389만주, 507억원을 기록 중이다.같은 시간 또 다른 강관 관련주인 하이스틸(18.74%)과 이렘(11.80%)도 두 자릿수 오름세를 나타내고 있으며 ▲유에스티(7.58%) ▲휴스틸(6.23%) ▲KBI동양철관(6.22%) ▲세아제강(1.97%) 등도 동반 강세다.앞서 트럼프 대통령은 지난 20일(현지 시각) 취임 1주년 기자회견에서 "아시아로 천연가스를 수출하기 위한 대대적인 알래스카 파이프라인 프로젝트를 시작했다"며 "한국, 일본과 협상을 체결하면서 유례없는 수준의 자금을 확보했다"고 말했다.이 프로젝트는 알래스카 노스슬로프에서 추출한 천연가스를 1300km의 가스관을 통해 니키스키까지 운반한 뒤 액화·공급하는 대형 사업으로 초기 사업비만 450억달러에 달한다.', NULL, '매일신문', 'https://n.news.naver.com/mnews/article/088/0000993009', 'https://imgnews.pstatic.net/image/088/2026/01/21/0000993009_001_20260121110717442.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-21 11:07:17', 0, true, '2026-03-09 06:21:55.219829') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1092, '중동 쇼크도 힘겨운데...공매도 비중 높은 종목 TOP10', '시가총액 대비 공매도 순보유잔고금액 비중 상위 종목/그래픽=윤선정이란 사태가 장기화할 수 있다는 우려가 커지며 국내 증시도 높은 변동성을 보인다. 이런 가운데 공매도 비중이 높은 종목은 변동성 장세에서 일반 종목보다 낙폭이 더 커질 수 있어 주의가 필요하다는 조언이 나온다.4일 한국거래소 정보데이터시스템에 따르면 집계가 가능한 가장 최근일인 지난달 26일 기준 코스피에서 시가총액 대비 공매도 순보유잔고 금액 비중이 높은 종목은 한미반도체(4.57%), 코오롱인더(4.04%), LG생활건강(4.03%), 코스맥스(3.92%), 대우건설(3.84%), 코스모신소재(3.56%), 하이트진로(3.53%) 등으로 집계됐다.증권가에서는 최근까지도 가파르게 상승했던 코스피 내 공매도 비중이 높은 종목에 특히 유의해야한다는 분석을 내놓았다. 한 증권업계 관계자는 "이란 사태가 예상보다 장기화할 가능성이 커지고 있다"며 "반도체나 2차전지가 전쟁에 직접적 영향을 받는 산업은 아니지만 한국은 에너지 순수입국인만큼 에너지 가격 상승이 거시경제 불확실성을 키워 국내 증시를 흔들 수 있다"고 말했다.이어 "공매도는 통상 시장에서 기업 가치 대비 주가가 높다고 판단되는 종목에 집중되는데 일부 반도체 소부장(소재·부품·장비), 2차전지 등 최근 모멘텀으로 주가가 가파르게 올랐던 종목이 변동성 장세에서 낙폭이 클 수 있다"고 했다.HBM(고대역폭메모리) 제작에 필요한 TC본더 장비를 생산하는 한미반도체는 장비 공급 이슈와 경쟁사와 법적 분쟁 등으로 노이즈가 발생하며 다른 반도체 소부장 종목 대비 주가 상승 시점이 다소 늦었다. 하지만 올해 들어서도 반도체 슈퍼사이클 기대감이 계속되며 지난달 27일 주가는 장중 한때 33만2500원까지 오르며 신고가를 경신했다.반면 시장 내 평가는 엇갈리고 있다. 유진투자증권은 연초 한미반도체가 HBM 본딩 시장에서 안정적인 점유율을 이어갈 것으로 전망해 목표주가 23만원을 제시했다. 반면 JP모간은 지난달 밸류에이션 부담과 TC본더 시장내 경쟁이 심화하고 있어 한미반도체에 대한 비중축소 의견을 유지했다.패션사업을 영위하는 코오롱인더는 최근 AI(인공지능) 반도체 모멘텀이 발생하며 주가가 급격히 상승했다. 코오롱인더가 생산하는 mPPO(폴리페닐렌 옥사이드)가 AI와 반도체 등에 활용되는 CCL(동박적층판) 소재로 사용된다는 점이 부각됐기 때문이다. 주가는 전날 장중 7만1500원까지 오르며 52주 신고가를 경신했다.대우건설은 원전 모멘텀으로 지난달 27일 장중 1만850원을 돌파하며 신고가를 경신했다. 증권가에서는 원전 모멘텀은 유효하지만 이란 사태가 본업에 부정적인 영향을 줄 수 있다는 분석을 내놓는다. 문경원 메리츠증권 연구원은 "주택 공사비 상승 우려와 중동 현장 플랜트 공기 지연 우려 등 건설 본업에서 부정적인 영향이 원전 모멘텀보다 더 클 수 있다"고 했다.2차전지 소재 사업을 영위하는 코스모신소재는 지난해 하반기 ESS(에너지저장장치)와 피지컬 AI 관련 수혜 기대가 2차전지 업종 전반에 확산되며 시장의 주목을 받았다. 하지만 기대감이 실적에 미치는 영향은 제한적이라는 점은 그간 증권가에서 꾸준히 지적돼 왔다. 포스코퓨처엠 역시 공매도 순보유잔고 금액은 7008억원으로 시가총액 대비 3.19%에 달해 높은 수준을 기록했다.한편 코스닥에서는 시가총액 대비 공매도 순보유잔고 금액 비중이 높은 종목은 HLB(6.85%), 엔켐(6.71%), 제룡전기(6.46%), 다날(5.09%), 펩트론(4.88%), 한국비엔씨(4.79%) 순으로 나타났다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005325272', 'https://imgnews.pstatic.net/image/008/2026/03/04/0005325272_001_20260304163014578.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-03-04 16:06:18', 0, true, '2026-03-09 06:22:00.548494') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1093, '"AI 수혜 반도체 다음은 MLCC"…삼화콘덴서 등 연일 강세', '[특징주]머니투데이 특징주 그래픽 이미지AI(인공지능) 산업 성장으로 반도체에 이어 MLCC(적층세라믹콘덴서)가 수혜를 입을 것이란 전망에 관련 주들이 연일 상승하고 있다.24일 오전 9시11분 현재 한국거래소 증시에서 삼화콘덴서는 전날 대비 8800원(15.44%) 오른 6만5800원에 거래 중이다. 장 중 6만8400원까지 오르며 52주 신고가를 경신했다. 삼화콘덴서는 전날 상한가 마감한 데 이어 연일 상승 중이다.지아이에스(11.24%), 한울반도체(4.13%), 코스모신소재(4.71%), 대주전자재료(4.26%), 원준(2.34%), 아바텍(1.8%) 등도 전날에 이어 오르고 있다. 지아이에스는 장 중 신고가를 새로썼다.MLCC관련 주는 AI 산업 발달로 MLCC 가격이 상승할 것이란 기대감에 오르고 있다.  MLCC는 전자제품의 회로에 전류가 일정하게 흐르도록 제어하는 부품으로, 반도체와 함께 ''전자산업의 쌀''로 불린다. 세계 최대 MLCC 공급업체인 무라타 제작소(Murata Manufacturing)는 지난 17일(현지 시각) 인터뷰를 통해 AI 서버용 MLCC 수요가 공급을 상회하고 있다며 가격 인상 가능성을 시사했다.또, AI 서버용 MLCC 수요 성장에 따라 범용 MLCC 가격 상승 가능성도 커지고 있다. 이상헌 iM증권 연구원은 "최근 삼성전기, 무라타 등이 저수익 범용 MLCC 생산을 줄이고, AI 서버와 전장용 고수익 MLCC에 대한 생산을 늘리고 있다"며 "이에 대한 반작용으로 범용 MLCC 재고가 크게 줄었다. 풍선효과로 향후 범용 MLCC 가격 인상이 기대된다"고 말했다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005321263', 'https://imgnews.pstatic.net/image/008/2026/02/24/0005321263_001_20260224091510460.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-02-24 09:14:44', 0, true, '2026-03-09 06:22:00.548494') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1163, '40초 완판…`BTS 진` 입은 동원참치캔, 어떻게 나왔나', '다꾸·백꾸 이어 캔꾸 인기BTS 진과 협업 `김희언 주임` 주도2021년 눈독, 2024년 제대 후 접촉해외 판매량 늘자, 글로벌 가속화21일 컴백 콘서트 해외 마케팅 고삐[이데일리 김미경 기자] 10·20대의 유행이던 다꾸(다이어리 꾸미기), 백꾸(가방 꾸미기) 열풍이 캔꾸(캔 꾸미기)로 옮겨붙었다. 동원산업의 식품 계열사인 동원F&B가 방탄소년단(BTS) 멤버 진(본명 김석진)과 협업해 선보인 동원참치캔의 변신 덕분이다. 동원F&B는 동원참치 브랜드 모델인 BTS 진이 그려진 참치캔 묶음 제품에 스티커를 동봉해 나만의 캔을 꾸밀 수 있도록 ‘슈퍼튜나포유’(Super Tuna For You) 캠페인을 진행 중이다. 직접 꾸민 캔 사진을 소셜미디어(SNS)에 올려 응모하면 된다.BTS 진과의 협업을 기획하고 주도한 인물은 동원F&B CMG1(카테고리매니저그룹1) 참치HMR(간편식)의 CM팀 김희언 주임이다. 김 주임은 “BTS 진과의 협업으로 판매량 호조를 보이고 있어 올해도 다양한 협업 제품 출시를 검토하고 있다”며 “해외 판매량도 크게 늘고 있다”고 웃었다.김희언 동원F&B CMG1 참치HMR CM팀 주임이 최근 서울 서초구 양재동 동원산업 본사 사무실에서 가진 이데일리와의 인터뷰에서 동원참치 브랜드 모델인 BTS 멤버 진과의 협업에 대해 설명하고 있다. (사진=동원산업)김 주임에 따르면 BTS 진과 동원참치의 만남은 꽤 운명적이라 할만하다. 2021년 진이 유튜버에 공개한 자작곡 ‘슈퍼 참치’를 주의 깊게 보고 있다가, 그가 제대한 2024년 6월부터 동원참치 브랜드 모델로 발탁하기 위해 공을 들여왔다. 해당 노래 영상은 유튜브 누적 조회수 1억회를 돌파하는 등 해외에서 특히 많은 사랑을 받았다.진이 제대한 후 접촉을 시작으로, 내부 설득 과정과 협업 구상을 동시에 진행했다고 했다. 김 주임은 “낚시를 즐기는 진이 참치를 잡은 경험을 살려 만든 이 노래가 동원참치의 건강한 이미지와 잘 부합한다고 보고 작업에 착수했다. 브랜드 방향성은 물론 해외 공략 가속화에 나선 동원참치로서도 투자 가치가 있다는 경영진의 판단도 이어졌다”고 말했다. 지난해 7월 드디어 진을 브랜드 모델로 발탁한 뒤 바로 티저 영상을 제작, 공개했고, 다양한 협업 마케팅 활동을 벌이는 중이다.동원참치 캔꾸 캠페인 제품 이미지진의 모습이 담긴 명절용 ‘슈퍼참치 선물세트’는 지난해 사전판매 당시 40초만에 1000개 모두 완판됐다. 또 지난해 12월엔 해당 선물세트 1만개를 미국으로 수출하기도 했다. 실제 동원참치는 진과의 협업에 힘입어 지난해 수출액이 전년대비 10% 이상 늘어났다. 작년 하반기 이후 해외 현지 매출도 15% 이상 증가했다.김 주임은 “캔꾸 제품의 경우 캔 패키지를 진과 어울리는 핑크색으로 꾸몄다”면서도 “내용물은 기존 그대로 담았다. 오메가3, DHA를 더 넣어보기도 하고 20여개의 샘플을 만들었지만 결국 기본으로 돌아가자는 결론에 닿았다. 기존 동원참치가 이미 슈퍼참치더라. (하하) 좋은 동원참치를 전 세계인들에게 많이 알리는 게 마케팅 기획자로서 포부”라고 강조했다.오는 21일 서울 광화문광장 일대에서 열릴 예정인 BTS 컴백 공연을 앞두고선 글로벌 마케팅에 고삐를 죌 계획이다. 모델 진과의 다양한 협업 상품을 선보이되 미국 아마존 전용 상품을 론칭해 글로벌 시장 점유율 확대에 나선다. 또한 컴백 콘서트가 열리는 광화문을 비롯해 명동, 서울역 등 인근 상권에 상품군을 강화해 글로벌 팬들의 수요를 흡수하겠다는 전략이다.김희언 동원F&B CMG1 참치HMR CM팀 주임이 최근 서울 서초구 양재동 동원산업 본사 사무실에서 이데일리와의 인터뷰에 앞서 동원참치 브랜드 모델인 BTS 멤버 진과 협업한 제품을 들어보이고 있다. (사진=동원산업).', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006228930', 'https://imgnews.pstatic.net/image/018/2026/03/05/0006228930_001_20260305192214886.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-05 10:47:08', 0, true, '2026-03-09 06:25:48.167156') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1094, 'SGC에너지, 사외이사에 피지컬 AI 전문가 김종국 고려대 교수 내정', '김종국 고려대학교 공과대학 전기전자공학부 교수(SGC에너지 제공)(서울=뉴스1) 최동현 기자 = SGC에너지(005090)는 오는 20일 열리는 정기주주총회에서 피지컬 인공지능(AI) 전문가로 손꼽히는 김종국 고려대 전기전자공학부 교수를 신규 사외이사로 선임하는 안건을 상정한다고 9일 밝혔다.김 신임 사외이사 내정자는 미국 퍼듀대학교(Purdue Univ.)에서 전기전자공학 박사 학위를 취득했다. 이후 삼성 SDS IT 연구개발(R&D) 책임연구원, 고려대 차세대 컴퓨팅 시스템 위원, 전기·전자·컴퓨터공학과 학과장, 정보통신기술연구소 소장, 고려대 민간 협업형 전문 랩(KU-3DS) 사업단장 등을 지냈다.김 내정자는 AI 데이터센터의 핵심인 그래픽처리장치(GPU) 기반 병렬처리 최적화를 연구하는 HCW의 의장으로 재임하며 에너지 효율 최적화 및 클라우드, 엣지 컴퓨팅의 이기종 자원 관리 등의 연구를 주도했다는 평가를 받는다.SGC에너지 관계자는 "김 내정자는 지능형 AI 인프라와 병렬·분산컴퓨팅 분야에서 실무와 학술적 역량을 두루 섭렵한 전문가"라며 "AI 인프라 기술의 고도화는 물론 AI 데이터센터를 중심으로 한 신규 비즈니스 생태계를 조성하는 데 실질적인 제언과 핵심적인 역할을 할 것으로 기대한다"고 말했다.', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008814223', 'https://imgnews.pstatic.net/image/421/2026/03/09/0008814223_001_20260309110826300.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 11:07:47', 0, true, '2026-03-09 06:22:06.400895') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1095, 'SGC문화재단, 경희대 병원에서 ‘찾아가는 나눔 음악회’ 열어', '[파이낸셜뉴스]지난 2월 26일 SGC문화재단이 서울 동대문구 경희대학교병원에 개최한 ''찾아가는 나눔 음악회''에서 현악 4중주 ‘뤼미에르 콰르텟’이 연주하고 있다. SGC문화재단제공SGC문화재단은 지난 2월 26일 경희대학교병원 로비에서 환우와 보호자, 의료진을 위한 ''찾아가는 나눔 음악회''를 개최했다고 4일 밝혔다.''봄의 서막, 힐링 콘서트''라는 주제로 진행된 이번 음악회는 SGC문화재단이 추진하는 지역사회 나눔 사업의 일환으로, 병마와 싸우는 환자와 그 곁을 지키는 보호자, 그리고 지친 의료진에게 클래식 선율을 통해 따뜻한 위로와 희망의 메시지를 전하기 위해 마련됐다.이날 연주회에는 연세대학교 재학생으로 구성된 현악 4중주 ‘뤼미에르 콰르텟’이 참여해 약 1시간 동안 다채로운 연주를 펼쳤다. 따뜻한 봄의 기운을 느낄 수 있는 모차르트의 ‘작은 밤의 음악을 시작으로, ‘여인의 향기’, ‘라이온킹’ 등 대중에게 친숙한 영화 OST 등 희망의 메시지를 담은 다양한 곡들로 관객들의 큰 호응을 얻었다.SGC문화재단 관계자는 "음악이 가진 치유의 힘을 통해 병원에 계신 모든 분들께 따뜻한 위로를 전하고 싶었다"며 “앞으로도 문화 사각지대를 찾아가는 나눔 활동을 통해 우리 사회에 따뜻한 온기를 전파하는 데 앞장서겠다”고 밝혔다.한편, SGC문화재단은 비영리 재단법인으로, SGC그룹 지주회사인 SGC에너지가 문화예술을 통한 사회공헌 활동을 전개할 목적으로 지난해 설립했다. 문화예술 공연 및 예술인 창작 활동 후원, 문화 아카데미 운영, 문화소외계층 대상 문화나눔 사업, 기획 공연 등의 주요 사업을 전개하며 국내 문화예술 발전에 기여하고 있다.', NULL, '파이낸셜뉴스', 'https://n.news.naver.com/mnews/article/014/0005486081', 'https://imgnews.pstatic.net/image/014/2026/03/04/0005486081_001_20260304144110770.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-04 14:41:10', 0, true, '2026-03-09 06:22:06.400895') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1096, '"목표가 비해 너무 싸다"…파마리서치·코웨이 관심', '올해 목표가 상향 리포트 2187건…작년 대비 2배 급증증권가 실적 눈높이 못맞춘파마리서치 괴리율 72% 달해한컴·동원산업 등도 높아SGC에너지·대우건설 목표가 추월"과열 가능성…추격 매수 자제를"증권사 목표주가가 현재 주가보다 50% 이상 높은 종목이 속출하고 있다. 올해 들어 코스피지수가 치솟으면서 주가 눈높이도 덩달아 상승했지만, 실제 실적이 기대에 못 미치거나 시장의 관심을 충분히 얻지 못한 탓이다. 반대로 일부 인공지능(AI)산업 관련주는 투자자의 공격적인 매수로 목표주가를 뛰어넘는 사례가 많아졌다.◇괴리율 확대 종목 속출3일 금융정보업체 에프앤가이드에 따르면 올해 들어 국내 증권사가 발간한 목표주가 상향 종목 리포트 건수는 2187건이다. 작년 같은 시기(942건)와 비교하면 약 두 배 급증했다. 지난달 코스피지수가 6000을 돌파하는 등 연일 랠리를 펼치면서 낙관적인 전망이 쏟아진 결과다.증권사 기대와 달리 주가가 오르지 않으면서 괴리율이 크게 벌어진 종목도 늘어났다. 스킨부스터를 판매하는 파마리서치는 주요 분석 대상 종목 가운데 괴리율이 가장 컸다. 지난달 27일 34만9500원에 거래를 마쳐 최근 3개월간 12개 증권사가 제시한 평균 목표주가 60만2500원 대비 괴리율이 72.39%에 달했다. 시장 예상보다 저조한 지난해 4분기 실적이 실망 매물 증가로 이어졌다는 분석이 나온다. 이날도 주가가 6% 넘게 내리면서 목표주가 괴리율은 더욱 커졌다.목표주가 괴리율은 증권사가 제시한 목표가와 현재 주가의 차이를 나눠 백분율로 표시한다. 증권사가 제시하는 목표주가는 최소 3~6개월 또는 1년 뒤에 도달할 수 있는 최고 주가 수준을 뜻한다. 괴리율이 높을수록 해당 종목의 주가 상승 여력이 크다는 의미로 해석할 수 있다.두 번째로 괴리율이 큰 종목은 콘텐트리중앙이다. 지난달 말 기준 목표주가 괴리율이 72.17% 수준이다. 이 회사는 지난해 영업이익이 56억원을 기록하면서 6년 만에 흑자 전환했지만, 올해 들어 주가가 6000원대로 작년 말 9700원 대비 크게 떨어졌다. 목표주가로 1만4000원을 제시한 장지혜 DS투자증권 연구원은 “올해도 실적 개선세가 이어질 것으로 전망되는 만큼 재무 부담 우려가 해소되면 주가는 반등할 것”이라고 말했다.씨어스테크놀로지와 코웨이도 목표주가 괴리율 상위권에 이름을 올렸다. 목표주가 괴리율은 각각 67.38%, 57.20%에 달한다. 증권가에서는 코웨이와 관련해 향후 신제품 확장과 적극적인 주주환원 정책이 기대된다고 평가했다. 지난달 코웨이 목표주가로 15만원을 제시한 박종대 메리츠증권 연구원은 “국내외 렌털시장에서 압도적인 시장 점유율로 견조한 실적 개선세를 보이고 있다”며 “올해 주주환원율도 40%를 유지할 것”이라고 분석했다.◇일부 AI 관련주는 목표가 초과일부 종목은 목표가를 넘어 상승하면서 과열 우려가 나온다. 주가 상승 속도가 워낙 빠르다 보니 증권가 목표주가 상향이 주가를 따라가지 못하면서다. SGC에너지의 목표주가 괴리율은 지난달 말 기준 마이너스(-) 28.57%다. 마이너스 수치가 커질수록 현 주가가 증권가의 목표주가보다 높다는 의미다. 발전사인 SGC에너지는 최근 인공지능(AI) 인프라 관련주로 주목받으며 주가가 급등했다.원자력발전소 인프라 수혜주로 재평가받는 대우건설과 현대건설의 목표주가 괴리율도 각각 -25.99%, -16.64% 수준이다. 다수의 증권사는 건설업종 목표주가와 실제 주가의 역전을 해소하기 위해 목표가를 수시로 높이고 있다. 증권업계 관계자는 “목표주가 상향이 주가 상승률을 따라가지 못할 정도면 단기 과열 가능성이 있어 추격 매수를 자제하는 게 좋다”고 말했다.', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005257641', 'https://imgnews.pstatic.net/image/015/2026/03/03/0005257641_001_20260304005621524.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-03 17:59:12', 0, true, '2026-03-09 06:22:06.400895') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1097, '"10년을 기다렸다"…''첫 흑자'' 컬리, 다음은 상장?', '[주간유통]컬리 창사 이래 첫 영업이익 흑자사업 확장하며 흑자까지…성장 모델 입증IPO 신중론…일회성 아닌 지속성 보여줘야그래픽=비즈워치[주간유통]은 한주간 유통·식음료 업계에서 있었던 주요 이슈들을 쉽고 재미있게 정리해 드리는 콘텐츠입니다. 뉴스 뒤에 숨겨져 있는 또 다른 사건들과 미처 기사로 풀어내지 못했던 다양한 이야기들을 여러분께 들려드릴 예정입니다.[편집자]국내 이커머스업계에서 흑자를 낸다는 건 상당히 어려운 일입니다. 현재 흑자를 내고 있는 이커머스 기업은 쿠팡과 오아시스 정도뿐입니다. 한때 쿠팡과 어깨를 나란히 했던 티몬은 회생절차를 밟다 오아시스에 매각됐고 위메프는 파산했습니다.15년 연속 흑자를 내던 오픈마켓 1위 G마켓마저 이젠 적자를 면치 못하고 있죠. 그러다 보니 대부분의 이커머스 기업들이 적자를 줄이겠다고 허리띠를 졸라매다 몸집까지 함께 쪼그라드는 악순환을 반복하고 있습니다.그런데 이번주 컬리가 조금 다른 소식을 들고 왔습니다. 창업 10년 만인 지난해 처음으로 연간 영업이익 흑자를 달성한 겁니다. 비용을 쥐어짜서 만들어낸 흑자도 아니었습니다. 지난해 매출액과 거래액도 역대 최대치를 기록하며 화려한 기록을 세웠죠.강남맘서 전국구로컬리의 시작은 2015년 만들어진 ''마켓컬리''로 거슬러 올라갑니다. 김슬아 컬리 대표가 맞벌이를 하면서 느낀 ''좋은 식재료를 편하게 살 수가 없다''는 답답함이 컬리의 출발점이었는데요. 마켓컬리는 낮에 장을 보기 어려운 맞벌이 부부를 위해 엄선한 식재료를 새벽에 배달하는 방식을 택했습니다. 밤 11시 전에 주문하면 다음날 아침 7시 전에 신선식품이 문 앞에 도착하는 ''샛별배송''이 그렇게 탄생했습니다.당시는 새벽에 신선식품을 배달한다는 개념이 생소하던 시기였습니다. 신선도를 지키려면 ''콜드체인''이 필요해 포장부터 배송까지 직접 책임져야 했고요. 그러려면 상품을 직접 매입해 판매하는 방식이어야 했습니다.차별화 된 상품도 컬리의 강점이었습니다. 전국 산지에서 직접 깐깐하게 발굴한 상품이라는 점을 전면에 내세웠죠. 치즈, 허브 같이 당시만 해도 생소했던 식재료를 대중화한 것도 컬리였습니다.그래픽=비즈워치컬리는 사업 초기 강남 주부들 사이에서 입소문을 타면서 빠르게 자리를 잡을 수 있었습니다. 성장세도 무척 가팔랐는데요. 매출 1000억원을 달성하는 데 창업 후 3년이 걸렸지만 5000억원까지는 2년, 1조원 돌파까지는 불과 1년밖에 걸리지 않았죠.문제는 팔수록 적자가 쌓인다는 점이었습니다. 다른 사람들의 물건을 대신 팔아주며 수수료만 받는 중개 방식이 아니라 상품을 직접 매입해 재고를 책임져야 하다보니 자본이 많이 필요했습니다. 콜드체인에 새벽배송 인건비까지 구조적으로 돈이 많이 드는 사업이기 때문입니다.자본이 많은 유통 대기업이 이 시장에 뛰어들면 컬리가 규모의 경제에서 밀릴 수밖에 없다는 말도 따라붙었습니다. 컬리를 둘러싼 매각설이 끊이지 않았던 이유가 여기에 있었죠.적자에도 ''고''실제로 컬리의 영업손실은 계속 불어나기만 했습니다. 코로나19 팬데믹으로 새벽배송 수요가 한창이던 2022년에는 연간 영업손실만 2334억원으로 정점을 찍기까지 했습니다. 컬리에게는 IPO을 통한 자금 조달이 필요했지만 이마저도 여의치 않았습니다. 컬리가 IPO를 추진하던 2022년 증시가 침체되면서 결국 상장 계획을 무기한 연기할 수밖에 없었습니다.그래도 컬리는 직매입으로 상품을 직접 관리하고 새벽배송으로 책임지는 사업 모델을 포기하지 않았습니다. 이 사업은 비용이 많이 들지만 그만큼 품질 통제와 배송 경쟁력의 원천이 됐기 때문입니다. 코로나19 팬데믹 이후 많은 이커머스들이 쿠팡에 밀리면서 성장 한계에 부딪치자 허리띠를 졸라맬 수밖에 없었는데요. 컬리는 ''신선식품''이라는 점에서 쿠팡과 차별화에 성공하며 성장세를 이어갈 수 있었습니다.컬리N마트. / 사진=컬리게다가 컬리는 이 시기 오히려 취급 품목을 늘리며 사업 영역을 확장했습니다. ''뷰티컬리''가 대표적인데요. 신선식품에만 쏠린 컬리의 포트폴리오를 다각화 하기 위한 결정이었죠.뷰티컬리가 처음 나왔을 때만 해도 ''신선식품 플랫폼이 왜 화장품을 파냐''는 시선이 있었는데요. 컬리는 컬리의 주고객층이 뷰티 고객층과 겹친다는 데 착안해 뷰티컬리를 집중적으로 키웠습니다. 실제로 뷰티컬리는 지난해 전년 대비 23% 성장하며 어엿한 수익원으로 완전히 자리를 잡았습니다.이뿐만이 아닙니다. 컬리는 판매자가 컬리 물류망을 이용하도록 하는 3P 서비스도 도입하며 빠르게 몸집을 키웠습니다. 지난해에는 샛별배송 권역도 전라북도까지 넓혔고요. 미국법인도 구축하며 신사업에도 도전했습니다. 지난해 9월에는 네이버(NAVER)와 손잡고 컬리N마트를 선보여 컬리 앱 밖의 고객을 끌어들이기도 했습니다.남은 과제는주목할 만한 것은 이렇게 컬리가 여러 신규 투자를 이어가면서도 지난해 흑자 전환에 성공했다는 점입니다. 컬리는 지난해 매출 2조3671억원, 거래액 3조5340억원까지 모두 역대 최대치를 기록했는데요. 매출액은 전년보다 7.8%나 성장한 수치입니다. 성장과 수익성을 동시에 잡는 사업구조를 만드는 데 성공한 셈입니다.그렇다고 컬리의 모든 숙제가 끝난 건 아닙니다. 컬리가 거둔 지난해 영업이익은 131억원으로 아직 작은 수준입니다. 영업이익률은 아직 0.5%에 그치죠. 지금까지 컬리가 만든 비즈니스 모델의 가능성을 증명했다면 이제는 그 규모를 키우는 게 다음 과제입니다.사진=컬리업계의 시선은 자연스럽게 컬리의 IPO로 향합니다. 2023년 초 실패로 끝났던 상장 도전이 이번 흑자를 발판으로 재점화될 수 있다는 관측이 나옵니다.다만 컬리는 신중론을 유지하고 있습니다. 흑자 전환이라는 성적표를 받았다고 해서 서두르지 않겠다는 입장인데요. 이 흑자 달성이 일회성이 아니라는 점을 시장에 증명하는 게 우선 과제가 될 전망입니다.이번 흑자는 컬리에게 달성하려던 목표가 아니라 새로운 출발점일 겁니다. 10년 동안 쌓아온 모델이 작동한다는 걸 증명했으니 이제는 그걸로 얼마나 더 멀리 갈 수 있는지가 남았죠. 컬리의 ''샛별''이 진짜 빛을 발할 수 있을지 지켜봐야겠습니다.', NULL, '비즈워치', 'https://n.news.naver.com/mnews/article/648/0000045039', 'https://imgnews.pstatic.net/image/648/2026/03/07/0000045039_001_20260309083111564.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-07 13:00:16', 0, true, '2026-03-09 06:22:12.879582') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1098, '''자사주 소각'' 3차 상법 개정 임박…''수혜주 찾기'' 분주', '오늘 오후 3차 상법 개정안 통과 전망지주사·증권·보험 등 주가 변동성 확대[서울=뉴시스] 김명년 기자 = 더불어민주당 의원들이 24일 오후 서울 여의도 국회에서 열린 본회의에서 윤한홍 국민의힘 의원의 상법 일부개정법률안(대안)에 대한 무제한토론(필리버스터)를 시작하자 회의장을 빠져나가고 있다. 2026.02.24. kmn@newsis.com[서울=뉴시스]이지민 기자 = 세 번째 상법 개정안 통과가 임박했다. 상장사가 취득한 자사주를 1년 내 의무 소각하도록 하는 것이 골자다. 시장에서는 일찌감치 수혜주 찾기에 나서면서 관련 종목들의 주가 변동성이 커진 모습이다.25일 정치권 및 금융투자업계에 따르면 이날 국회 본회의에서 3차 상법 개정안이 여당 주도로 통과될 전망이다. 전날 국민의힘이 개정안에 반대하며 필리버스터에 나섰으나, 더불어민주당이 종결 동의를 제출하면서 법안 처리 강행을 예고했다.이날 이재명 대통령은 X(옛 트위터)에 "자사주 소각 입법이 한시라도 빨리 되면 좋겠다"며 "해는 짧은데, 갈 길이 멀다. ''주가 누르기 방지법'' 등 해야 할 일이 산더미"라고 말했다.개정안의 핵심은 자사주를 원칙적으로 소각 대상으로 규정하는 것이다. 회사는 새로 취득한 자사주를 1년 이내에 소각해야 한다. 기존 보유 중인 자사주는 법 시행일로부터 1년 6개월 안에 소각하도록 했다. 자사주가 지배주주의 경영권 방어 수단으로 악용되는 것을 막기 위해서다.단, 임직원 보상, 우리사주 제도 운영, 신기술 도입이나 재무구조 개선 등 경영상 필요한 경우에는 예외적으로 보유가 가능하다.증권가에서는 향후 자사주 소각 법안에 따른 기업들의 주식 소각 확대로 코스피 주식 수 증가율은 연평균 1% 감소할 것으로 예상하고 있다.이정연 대신증권 연구원은 "이번 3차 상법 개정안의 핵심은 자사주 소각을 무조건적으로 강제하는 것이 아니라, 자사주의 처리 방향을 이사회가 아닌 주주총회에서 결정하도록 하여 일반주주의 권익을 보호하는 데 있다"고 평가했다.시장에서는 수혜주 찾기가 한창이다. 다만, 기대감이 선반영된 종목들의 경우 차익실현 등에 따른 변동성이 커진 만큼 주의가 필요하다는 목소리가 나온다.시가총액 1조원 이상 종목 중 전체 주식 수 대비 자기주식 비율이 20%가 넘는 종목으로는 신영증권(자사주 비율 53.1%), SNT다이내믹스(32.7%), 대웅(29.7%), 한샘(29.5%), 롯데지주(27.5%), 미래에셋생명(26.3%), SK(24.8%), 대신증권(24.3%), 미래에셋증권(23.1%) 등이 있다.KCC(17.2%), 두산(16.2%), DB손해보험(14.6%), 오뚜기(14.2%), 영원무역홀딩스(14.0%), LS(13.7%), 한화생명(13.5%), 금호석유화학(13.4%) 등도 자사주 비율이 높은 종목이다.일찌감치 3차 상법 개정 수혜주로 꼽혔던 증권 업종과 금융지주, 보험 종목들의 경우 최근 주가 변동성이 확대됐다.전날 삼성생명(-3.45%)·한화생명(-10.89%)·미래에셋생명(-6.27%) 등 보험주와 신영증권(-6.86%)·NH투자증권(-5.08%)·유진투자증권(-3.92%)·한화투자증권(-3.12%)·키움증권(-2.97%) 등 증권주 등이 일제히 하락 마감했다. KB금융(-1.19%)·신한지주(-0.88%)·하나금융지주(-2.32%)·우리금융지주(-2.98%) 등 금융지주사도 주가가 내렸다.이들 종목은 최근 주가가 오름세를 보였으나, 전날 차익 실현 매물이 쏟아지며 변동성이 커졌다.정준섭 NH투자증권 연구원은 "자사주 신규 매입 없는 보유 자사주 소각은 주주환원이 아닌 일회성 이벤트에 불과한 만큼 실적이나 자본정책의 진전이 없는 상태에서 최근 이슈가 주가 상승을 얼마나 정당화할 수 있는지 고려해야 한다"고 짚었다．', NULL, '뉴시스', 'https://n.news.naver.com/mnews/article/003/0013786409', 'https://imgnews.pstatic.net/image/003/2026/02/25/NISI20260224_0021185930_web_20260224160911_20260225095511787.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-25 09:32:26', 0, true, '2026-03-09 06:22:12.879582') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1099, '수천억·조 단위 벌어들인 기업들…''사이클 위한 준비'' 빛났다', '(거제=뉴스1) 윤일지 기자 = 경남 거제시 한화오션 거제사업장. 2025.10.30/뉴스1 Copyright (C) 뉴스1. All rights reserved. 무단 전재 및 재배포, AI학습 이용 금지. /사진=(거제=뉴스1) 윤일지 기자업계의 호황 사이클에 올라타기 위한 기업들의 준비가 한창이다.한화오션이 대표적이다. 실제로 지난해 영업이익은 1조1091억원에 달했다. 2023년만해도 적자의 늪에 빠져있던 기업이 지난해 흑자전환에 이어 2년만에 영업이익 1조원 클럽에 가입한 것이다. 실적개선의 일등공신은 물론 LNG(액화천연가스) 운반선 사이클이다. 2022년 우크라이나 전쟁 발발 이후 LNG 운반선 발주가 증가했고, 이 과실을 작년부터 본격 수확하게 됐다. 실제 한화오션 상선 부문의 지난해 영업이익은 1조1200억원으로 전년비 792% 증가했다. 지난해 2~3분기에는 영업이익률이 12~13%에 달했다.LNG 운반선 사이클에 한화오션이 성공적으로 안착한 것은 체질개선의 영향이다. 한화그룹은 2023년 당시 대우조선해양을 인수한 후 한화오션 간판을 달게 하고 새로운 출발을 알렸다. 한화오션은 기술 개발과 생산성 혁신을 통해 연간 최대 25척의 LNG 운반선을 건조할 수 있는 능력을 갖췄다. 한화는 그룹 차원에서 구상하고 있는 LNG 밸류체인 구축에서 생산 및 운송을 담당하는 핵심 플레이어로 한화오션을 지목하고 전폭적인 지원을 진행했다.향후 전망도 밝다. 한화그룹은 미국 필리조선소를 인수하고 한화오션이 마스가(MASGA·미국 조선업을 다시 위대하게) 프로젝트의 주축으로 거듭나게 할 수 있는 기반을 만들었다. 미국이 발주하는 LNG 운반선은 물론 미 해군 함정, 중장기적으로는 핵추진 잠수함까지 제작할 수 있는 여건이 갖춰지고 있다.고려아연 온산제련소 전경/사진제공=고려아연고려아연은 지난해 1조2324억원의 영업이익으로 사상 최대 실적을 기록했다. 2025년 연간 영업이익률은 7.4%로 전년대비 1.4%포인트 상승했다. 양적, 질적인 성장이 모두 이뤄진 것이다. AI(인공지능) 및 방위 산업이 사이클을 타면서 안티모니와 인듐, 비스무트 등 핵심광물 수요가 증가한 영향이다.고려아연의 이익률 상승 비법으로는 희소금속 부문 회수율 증대가 꼽힌다. 순환경제를 통한 희소금속 생산에 그동안 힘을 줘온 게 결실을 맺었다는 평가다. 자원순환은 신재생에너지, 이차전지 소재와 함께 최윤범 회장이 강조하는 ''트로이카 드라이브''의 한 축이다. 고려아연의 은과 동은 100% 순환자원을 원료로 만든 제품으로, 세계적 전문 인증기관 SGS로부터 인증을 받았다. 자원순환 사업을 담당하는 미국 자회사 페달포인트가 지난해 처음으로 흑자를 기록하기도 했다.고려아연은 게르마늄과 갈륨 등 핵심광물을 추가 생산하기 위해 온산제련소에 신규 설비투자를 진행하고 있다. 미국 정부와 함께 약 74억 달러(약 10조9000억원)를 투자해 핵심광물 11종을 포함한 비철금속 13종을 생산하는 통합 제련소 역시 짓고 있다. 이같은 투자들이 결실로 이어지면 고려아연은 지속 성장할 수 있는 발판을 마련할 것으로 기대된다.효성중공업 창원공장 10조원 돌파 기념식/사진제공=효성중공업효성중공업도 지난해 괄목할만한 성장세를 보였다. 효성중공업은 지난해 영업이익은 7470억원으로 전년비 106% 늘었다. AI 데이터센터 폭증에 따라 변압기 사이클이 시작된 덕을 봤다. 글로벌 변압기 시장은 공급자 우위인 구조가 심화되고 있다. 미국 등 국가의 제조역량이 전력 수요를 따라가지 못하기 때문이다. 트럼프 2기 행정부 출범 이후 부과되고 있는 20% 안팎의 관세도 변압기 수요를 꺾지 못한다. 지난해 말 기준  효성중공업 중공업부문 수주잔액은 11조9000억원에 달했다.뚝심있는 사업 추진이 결실로 맺어졌다. 효성중공업은 1969년 국내 최초로 154kV(킬로볼트) 초고압변압기를 개발해 생산에 나섰고, 창원공장은 올들어 누적 10조원 어치의 초고압변압기 생산을 달성할 정도로 노하우를 쌓았다. 2010년대 초부터 미국 시장에서 765kV 변압기 점유율 1위를 유지하고 있는 효성중공업이다. 2020년부터는 미국 테네시주 멤피스에 변압기 공장을 설립해 운영 중이기도 하다.상승세는 여전하다. 지난 10일에는 미국 유력 송전망 운영사와 약 7870억원 규모의 765kV 초고압변압기·리액터 등 전력기기 계약을 체결하는 낭보를 전했다. 효성중공업은 내년 7월 완공을 목표로 국내 창원공장에 HVDC(초고압직류송전) 변압기 전용 공장을 구축하기로 했다. 자체 기술로 시스템 설계, 컨버터·제어기·변압기 등 기자재까지 생산하는 등의 방식으로 시장 공략에 속도를 낼 계획이다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005319002', 'https://imgnews.pstatic.net/image/008/2026/02/17/0005319002_001_20260217073017686.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-17 07:30:00', 0, true, '2026-03-09 06:22:12.879582') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1100, '요미우리 시절 200억 베팅한 이승엽, 성수동서 수백억 수익', '[사진 일간스포츠][이코노미스트 김영서 기자] 두산 베어스 전 감독이자 현 요미우리 자이언츠 코치인 이승엽이 16년 전 매입한 서울 성수동 빌딩의 시세가 3배 이상 급등하며 수백억 원대 시세차익을 거둔 것으로 추정된다. 200억원을 투자한 이승엽 전 감독은 약 900억원에 달하는 시세차익을 거두며 이른바 ‘부동산 투자 홈런’을 기록한 것으로 평가된다.최근 부동산 업계와 밸류맵 등에 따르면 이승엽 전 감독 소유의 서울 성동구 성수동1가 빌딩 추정 시세는 지난달 기준 약 1167억 원 수준으로 집계됐다. 2009년 매입가가 293억 원인 점을 감안하면 단순 시세차익만 약 874억 원에 달한다는 계산이 나온다. 건물은 지하 3층~지상 10층 규모로, 대지면적은 1489㎡(약 450평), 연면적은 9881㎡(약 2989평) 규모다.이승엽 전 감독은 2009년 7월 일본 프로야구 요미우리 자이언츠 소속 선수로 활약하던 당시 뚝섬역 인근에 위치한 해당 빌딩을 매입했다. 당시 건물은 구두회사 에스콰이어 사옥으로 사용 중이었고, 매입 당시 성수동 일대는 상권이 본격적으로 형성되기 전의 준공업 지역으로, 분당선 연장 개통과 재개발 기대감이 거론되던 곳이었다.이후 성수동은 낡은 공장지대 이미지를 벗고 ‘한국의 브루클린’으로 불리며 카페·패션·문화 상권이 빠르게 확산한 대표 지역으로 변모했다. 해당 빌딩은 지하철 2호선 뚝섬역 도보 2분, 수인분당선 서울숲역 도보 4분 거리의 더블 역세권으로, 대로변 코너 입지까지 갖춘 핵심 자산으로 평가된다.이승엽 전 감독은 당초 단독 명의로 건물을 매입했으나, 이후 아내 이송정 씨와 두 아들에게 지분을 증여해 현재는 가족 공동 소유 형태로 현재는 가족 공동 소유 형태로 관리되고 있다. 부동산 가치 상승과 함께 절세 효과까지 고려한 자산 관리라는 평가도 나온다. 현재 건물에는 공유오피스 기업 ‘헤이그라운드’가 상당수 층을 통임대해 안정적인 임대수익을 내는 것으로 전해진다.한편, 한편 이승엽야구장학재단은 13일 서울아산병원과 칠곡경북대학교 어린이병원에 저소득층 환아 수술비로 총 6000만원을 전달했다고 밝혔다. 재단은 지난 7일 동국산업과 함께 서울아산병원을 찾아 후원금 5000만원을 기탁했다. 이어 9일에는 칠곡경북대학교 어린이병원에 수술비 1000만원을 전달했다.', NULL, '이코노미스트', 'https://n.news.naver.com/mnews/article/243/0000091145', 'https://imgnews.pstatic.net/image/243/2026/01/13/0000091145_001_20260113133911375.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-13 13:39:11', 0, true, '2026-03-09 06:22:20.771696') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1101, '임팩티브AI, 현대차 추가 투자 유치…누적 투자금 110억원', '재무 성과 정밀 예측 솔루션 성장성 입증…모빌리티·수요예측 분야 사업 시너지 기대임팩티브AI가 인공지능(AI) 수요예측 솔루션의 성장성을 입증하며 지속적인 투자 유치에 속도를 낸다.임팩티브AI는 현대자동차 제로원벤처스로부터 전략적 투자를 유치했다고 9일 밝혔다. 이번 투자를 통해 임팩티브AI의 누적 투자금은 총 110억원 규모로 늘어났다.임팩티브AI는 한동대학교 AI융합학부 정두희 교수가 2021년 창업한 기업으로, 지난 8월 시리즈A 라운드에서 에이벤처스·현대투자파트너스·롯데벤처스·CJ인베스트먼트·IBK벤처투자·신용보증기금 등으로부터 82억원을 확보한 데 이어, 이번 현대차의 추가 투자까지 이끌어내며 성장성을 입증했다.(사진=임팩티브AI)이번 투자를 통해 임팩티브AI는 단순 재무적 성격을 넘어 제조와 모빌리티 영역에서의 사업적 시너지 창출 가능성에 의미를 두고 있다.임팩티브AI는 기업의 실질적인 재무 성과를 개선하는 정밀한 예측 기술을 기반으로 성장 중이다. 제품 수요예측, 재고 최적화, 원자재 가격예측 등 기업 운영의 핵심 의사결정 영역에 집중하고 있다. 국내에서는 삼성전자·SKT·CJ제일제당·한미사이언스·동국산업 등 주요 기업과 협력하는 등 제조·유통 분야에서 예측 기술을 통한 경영 혁신을 지원 중이다.기술력은 해외에서도 주목받고 있다. 임팩티브AI는 독일 베를린에서 열린 ''드라이버리 베를린'' 마켓플레이스 대회에서 우승한 데 이어, 유럽 최대 응용기술 연구기관인 ''프라운호퍼''와 제조 예측 기술 공동 연구를 수행 중이다.최근에는 미국 전자상거래 풀필먼트 선도기업 ''래디얼''과 기술 공급 협약을 체결하며 글로벌 고객 기반도 본격적으로 확대 중이다. 또 ''CIKM 2025'' 등 저명한 국제학술대회에서 논문이 다수 채택되는 등 기술 경쟁력도 인정받고 있다.임팩티브AI의 솔루션 ''딥플로우''는 복잡한 수요 예측을 자동화하고 재고 관리 및 데이터 기반 의사결정을 지원하는 플랫폼이다. 200개 이상의 고급 딥러닝·머신러닝 모델을 활용해 출고량과 판매량을 높은 정확도로 예측한다. 실제 도입 기업에서는 재고 비용 30% 이상 절감, 업무 시간 5분의 1 수준 단축 등 정량적 성과가 확인되고 있다.임팩티브AI는 이번 투자를 바탕으로 딥플로우를 한층 고도화하고 연구개발(R&D) 강화, 해외 시장 확대 등 성장 전략을 가속화할 계획이다.정두희 임팩티브AI 대표는 "현대차의 투자는 우리의 기술력이 글로벌 제조·모빌리티 시장에서도 통할 수 있다는 강한 신뢰의 표현"이라며 "딥플로우를 통해 자동차 및 모빌리티 산업의 경쟁력을 높여 명확한 AI 전환 혁신 사례를 만들어가겠다"고 말했다.', NULL, '지디넷코리아', 'https://n.news.naver.com/mnews/article/092/0002401677', 'https://imgnews.pstatic.net/image/092/2025/12/09/0002401677_001_20251209162515413.jpg?type=w800', 'NEWS_ETC', NULL, '2025-12-09 16:25:15', 0, true, '2026-03-09 06:22:20.771696') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1102, '"빙그레, 내수 침체와 원자재 부담으로 실적 부진…목표가↓"-DS', '빙그레 수출용 메로나/사진제공=빙그레DS투자증권은 9일 빙그레가 내수 소비 부진과 원가 부담 심화로 지난해 4분기 실적이 부진했다고 분석했다. 다만 올해 기업가치 제고 기반을 다지고 다음해 턴어라운드(흑자전환)에 성공할 것이라고 내다봤다. DS투자증권은 목표주가를 기존 13만원에서 10만원으로 하향하고 투자의견 ''매수''를 유지했다.빙그레의 지난해 영업이익은 전년 대비 32.7% 감소한 883억원, 매출액은 1.8% 늘어난 1조2896억원을 기록했다.장지혜·강태호 연구원은 "빙그레의 지난해 실적 부진에는 연중 내수 소비 침체와 원·부자재 부담, 인건비성 비용 증가가 영향을 미쳤기 때문"이라고 말했다.다만, 올해 실적은 지난해에 비해 성장할 것이라는 전망이다. 장·강 연구원은 "빙그레의 올해 영업이익은 전년 대비 10% 증가한 968억원, 매출액은 3.5% 성장한 1조5400억원을 예상한다"고 했다.장·강 연구원은 "내수 소비에 대한 부담은 여전히 존재하지만 최근 냉장 부문 매출 감소 폭이 줄어들고 있고 수출은 미국 냉동 부문이 메로나·붕어싸만코 등 주력 제품 확대로 견조한 성장을 이어갈 것"이라고 내다봤다. 이어 "기타 비용 효율화, 수출 성장으로 실적 개선이 기대된다"고 말했다. 다만 지난해와 동일한 수준으로 이어지는 원·부자재 부담과 해태 합병과 관련된 일시적 비용 반영은 실적 우려 요소로 꼽았다.올해 또다른 기대 요소는 기업가치 제고 기반 마련과 주주 환원 확대다. 지난 4일 빙그레는 지난해 3분기 기업가치제고 계획을 발표했다. 장·강 연구원은 "자회사 해태아이스크림 흡수합병을 통한 운영 효율화, 미국 등 주요 시장 중심 매출 확대와 향후 호주 OEM(주문자상표제작) 생산 기반 활용 오세아니아·유럽 등 시장 확대, 별도 당기순이익 기준 최소 25% 이상 배당 정책, 이달 중 기보유 자사주 3% 추가 소각 등을 발표했다"며 "지난해 실적 감소에도 DPS(주당배당금)를 전년과 동일한 수준으로 유지해 배당 성향 50%를 초과했다"고 평가했다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005326983', 'https://imgnews.pstatic.net/image/008/2026/03/09/0005326983_001_20260309084418567.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 08:43:33', 0, true, '2026-03-09 06:22:27.195834') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1103, 'K아이스크림 세계로…제2의 불닭 꿈꾼다 [실적 녹는 아이스크림]②', '롯데웰푸드·빙그레, 해외 공략 박차K푸드 인기, 빙과류까지 긍정적 영향파리 국제식품박람회에서 바이어들이 빙그레 메로나를 살펴보고 있다. [사진 빙그레][이코노미스트 이지완 기자] 국내 대표 빙과류 취급 기업인 롯데웰푸드와 빙그레가 K-아이스크림의 세계화를 꿈꾼다. 디저트류 다변화로 인한 치열한 시장 경쟁 속에 빙과류 주요 소비층인 아동 인구까지 감소하면서 내수 시장의 한계가 명확해졌기 때문이다. 기업에 신시장 개척은 더 이상 선택 사항이 아니다. 생존을 위한 필수 요소가 됐다.인도 공략 롯데웰푸드...현지 공장까지업계에서는 빙과류를 취급하는 국내 기업 중 해외 시장 공략에 가장 적극적인 곳으로 롯데웰푸드를 꼽는다. 회사의 지난해(2025년) 빙과 수출액은 전년 동기 대비 10.6% 증가했다. 관련 실적은 최근 4년(2022~2025년)간 꾸준히 두 자릿수의 연평균 성장률을 보인다. 롯데웰푸드의 연도별 빙과 수출액은 ▲2022년 203억원 ▲2023년 248억원 ▲2024년 264억원 ▲2025년 292억원 등이다.롯데웰푸드의 주요 빙과 수출국은 ▲미국 ▲중국 ▲필리핀 ▲대만 등이다. 회사는 국내 소비자들에게도 익숙한 메가 브랜드인 ▲죠스바 ▲스크류바 ▲수박바(죠크박) ▲티코 ▲설레임 ▲빵빠레 ▲찰떡아이스 등으로 해외 소비자들의 입맛을 사로잡고 있다.특히 롯데웰푸드가 눈여겨보는 시장은 인도다. 회사는 지난 2017년 빙과 업체 ‘하브모어’를 인수하며 14억 인구를 자랑하는 인도 시장에도 본격적으로 진출했다. 지난해 7월에는 현지 건과 법인 ‘롯데 인디아’와 합병 절차를 진행하며 경영 효율성 제고에 나서기도 했다.현지 성과는 긍정적이다. 최근 5년(2021~2025년) 연도별 연간 매출은 ▲2021년 994억원 ▲2022년 1544억원 ▲2023년 1656억원 ▲2024년 1729억원 ▲2025년 1965억원 등으로 꾸준한 오름세를 기록했다.롯데웰푸드의 인도 시장 공략은 앞으로도 계속된다. 롯데 인디아는 지난해 2월 인도 서부 푸네 지역에 빙과 신공장을 준공했다. 푸네 신공장은 롯데웰푸드가 하브모어를 인수한 뒤 처음으로 증설한 생산 시설이다. 공장 부지 면적은 6만㎡로 축구장 8개 크기다. 해당 공장에서 처음 선보인 크런치바(한국 제품명 돼지바)는 출시 3개월 만에 누적 판매 100만개를 넘어설 정도로 현지 반응이 좋다. 롯데웰푸드는 현재 9개 라인이 가동되고 있는 푸네 신공장의 라인을 2028년까지 16개로 늘릴 계획이다.롯데웰푸드 관계자는 “올해는 푸네 신공장을 통한 공급 안정화와 확대 전략을 통해 본격적인 외형 확장에 박차를 가할 계획”이라며 “이와 더불어 롯데 인디아 합병을 통한 남부 지역 커버리지 확장도 성장에 긍정적인 영향을 미칠 것으로 기대된다”고 말했다.미국 판매용 메로나 코코넛. [사진 빙그레]롯데웰푸드가 해외로 수출하는 월드콘. [사진 롯데웰푸드]다소 늦은 빙그레...해외 공략 박차해외 매출 비중이 10%대인 빙그레도 최근에는 해외 영토 확장에 속도를 내고 있다. 회사는 현재 ▲미국 ▲중국 ▲베트남에 해외 법인을 두고 있다. 주요 수출 제품은 국내 소비자들에게도 익숙한 빙그레의 대표 장수 브랜드 메로나와 붕어싸만코 등이다.빙그레에 따르면 현재 빙과류 수출 국가는 ▲미국 ▲캐나다 ▲중국 ▲대만 ▲홍콩 ▲베트남 ▲필리핀 등 30개국 이상이다. 회사는 다양한 국가의 소비자 입맛을 모두 사로잡기 위해 현지 맞춤형 제품을 적극 선보이고 있다. 해외에서는 오리지널 멜론맛 외에도 ▲딸기맛 ▲망고맛 ▲바나나맛 ▲코코넛맛 ▲타로맛 ▲피스타치오맛 등 다양한 맛의 메로나가 판매되고 있다.유제품 수출이 까다로운 국가에는 식물성 제품을 판매한다. 빙그레는 ▲네덜란드 ▲독일 ▲영국 ▲프랑스 등 유럽 지역과 호주 등에 식물성 메로나를 수출하며 지속적으로 해외 시장 확대를 모색하고 있다. 식물성 메로나는 유성분 없이 식물성 소재만으로 메로나 고유의 질감과 풍미를 살린 제품이다. 빙그레는 지난해 독일 쾰른식품박람회에서 식물성 붕어싸만코를 처음 선보이며 관련 제품 확대와 유럽 공략에 대한 의지를 동시에 보여주기도 했다.당분간 빙그레는 브랜드 알리기에 집중한다는 방침이다. 최근 모스크바 국제식품박람회 등 글로벌 식품박람회에 적극적으로 참가하는 것도 이런 이유다. 빙그레 관계자는 “향후 회사는 국가별 아이스크림 제품 포트폴리오를 다변화하고 진출 국가를 확대해 나갈 계획”이라고 설명했다.물론 빙그레가 단순 수출만 고집하는 것은 아니다. 한국 생산 제품의 수출은 품목 다변화와 시장 확대 등에 한계가 있기 때문이다. 이에 빙그레는 이달(3월) 기업가치제고계획 공시를 통해 호주 위탁생산(OEM) 기반을 활용한 오세아니아 및 유럽 시장 확대 가능성을 검토하고 있다고 밝혔다.롯데웰푸드와 빙그레가 해외 시장 공략에 박차를 가하는 이유는 K-푸드·컬처에 대한 세계인의 관심이 최고조에 달한 상황이기 때문이다. 농림축산식품부에 따르면 아이스크림은 지난해 농식품 역대 최고 수출 품목(총 12개) 중 하나로 이름을 올렸다. 아이스크림의 지난해 수출액은 전년 대비 21.6% 늘어난 1억1130만달러(약 1646억원)로 집계됐다.업계 관계자는 “빙과류의 경우 아동 인구 감소가 치명적일 수밖에 없다”며 “최근 출산율이 반등하고 있다고 하지만 실제 소비에 영향을 끼치려면 오는 2030년 중후반이 돼야 한다. 내수 시장이 한계점에 도달한 상황에서 불닭 시리즈 같은 글로벌 메가 브랜드의 탄생을 기대할 수밖에 없다”고 말했다.', NULL, '이코노미스트', 'https://n.news.naver.com/mnews/article/243/0000094111', 'https://imgnews.pstatic.net/image/243/2026/03/08/0000094111_001_20260308080012856.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-08 08:00:12', 0, true, '2026-03-09 06:22:27.195834') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1104, '상법개정안 시행...자사주 많은 제약바이오사, 소각 언제하나', '셀트리온, 2조원 규모 자사주 소각 계획 발표자사주 보유 지분 27.7%인 대웅 등은 미정기업들, 주주가치 제고 혹은 기업가치 극대화 방안 검토주요 제약바이오사 자사주 보유 비율/그래픽=김지영자사주 소각을 의무화한 상법 개정안이 시행되면서 일부 제약바이오사들이 자사주 소각에 나섰다. 셀트리온은 2조원 규모의 자사주 소각 계획을 발표했다. 아직 자사주 관련 방침을 정하지 않은 기업들은 주주가치 제고나 기업가치 극대화 등에 자사주를 활용하겠다는 계획이다.주주가치 제고를 위해 자사주 의무 소각안을 포함하는 3차 상법 개정안이 지난 5일부터 시행됐다. 이에 따라 신규 자사주 취득분은 1년 이내, 기보유 자사주는 1년 6개월 이내 소각이 의무화됐다. 자사주를 교환 또는 상환 대상으로 해 사채를 발행하는 것도 금지됐다. 다만 임직원 보상 등의 사유 발생 시 주주총회 승인을 통해 예외적으로 자사주를 보유하거나 처분하는 것은 가능하다.이에 따라 일부 기업들은 선제적으로 대응에 나섰다. 자사주 보유 비율이 5.3%인 셀트리온은 지난 6일 2조원 규모의 자사주 소각안을 발표했다. 꾸준히 자사주를 소각하며 주주친화 행보를 보여온 셀트리온은 자사주 소각 규모를 약 911만주까지 확대하기로 했다. 이는 전체 자사주의 74%로, 지난 5일 종가 기준 약 1조9268억원에 달하는 규모다.셀트리온 관계자는 "주주총회 이후 바로 소각 절차에 돌입할 것"이라며 "자사주 소각 결정은 불안정한 시장 환경 속에서 주주 권익 보호를 최우선 가치로 삼는 회사의 기업 경영 방침에 따른 결단"이라고 말했다.상법 개정안 시행에 앞서 자사주를 지분 교환 등에 활용하며 처분한 기업들도 많다. 지난해 7월 자사주 지분율이 약 25%에 이르렀던 광동제약의 자사주 보유비율은 현재 0.3% 정도다. 광동제약은 지난해 12월 자사주 일부를 대웅, 휴메딕스와 지분 교환에 사용했고, 일부는 동원시스템즈에 매각했다. 올해 1월에는 약 157억원 규모의 자사주를 소각했다.한국유나이티드제약도 지난해 7월 자사주 지분율이 9.9%였으나 현재는 0.3%가량(5만주)으로 낮아졌다. 지난해 12월 환인제약과 자사주 교환, 기타 특수관계사 한국바이오켐제약에 매각 방식으로 자사주를 처분했고, 지난 1월 73억원 규모의 자사주를 소각했다. 유나이티드제약 관계자는 "정부 정책에 발맞춰 주주들이 실질적으로 체감할 수 있는 환원책을 마련하기 위해 자사주 소각과 배당 확대를 통해 주당 가치를 극대화했다"고 설명했다.대웅은 아직 자사주 보유비율이 27.7%로 높다. 대웅 관계자는 "자사주의 소각이나 활용 중 어느 한 방향만을 고집하기보다는 급변하는 경영 환경 속에서 기업의 가치를 극대화할 수 있는 최선의 방안을 전략적으로 선택해 나갈 방침"이라고 전했다.자사주 지분율이 12.2%인 휴젤  관계자는 "2016년부터 현재까지 약 4700억원 규모의 자기주식을 취득하고 87만주 이상을 소각했다"며 "앞으로도 주주와 상생을 위해 꾸준히 책임 경영을 이어갈 예정"이라고 말했다.GC녹십자홀딩스와 GC녹십자의 자사주 보유비율은 각각 4.4%, 2.3%다. GC녹십자 측은 "현재 공식적으로 언제 몇 주를 소각하겠다는 계획이 확정된 바는 없으나, 기업가치 제고를 위해 자사주 소각을 포함한 다양한 주주 친화 정책을 내부적으로 검토 중"이라고 말했다.유한양행은 2024년 10월 자사주 1% 소각 등을 골자로 한 ''밸류업 계획''을 밝혔고 지난 1월 약 362억원 규모의 자사주를 소각했다. 남은 자사주 비중은 7.6%인데 아직 이에 대한 계획은 공시되지 않았다.이밖에 자사주 비율이 10.1%인 메디톡스, 12.9%인 안국약품(지난해 9월 기준), 5.0%인 삼진제약 등은 아직까지 자사주 관련 특별한 방침을 밝히지 않았다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005326863', 'https://imgnews.pstatic.net/image/008/2026/03/08/0005326863_001_20260309041744498.jpg?type=w800', 'NEWS_BIO', NULL, '2026-03-08 17:09:00', 0, true, '2026-03-09 06:22:33.600754') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1109, '롯데중앙연구소, 중소 식품업체 안전관리 역량강화 교육 시행', '2010년부터 진행해온 교육 프로그램⋯9일부터 신청 접수롯데중앙연구소가 중소 식품업체의 식품 안전관리 역량 강화를 위한 교육 프로그램 2026 LOTTE Food Safety Academy(LFSA) 신청 접수를 9일부터 받는다고 밝혔다.교육을 진행 중인 롯데중앙연구소 연구원. [사진=롯데중앙연구소]LFSA는 롯데중앙연구소 안전센터가 2010년부터 17년째 진행 중인 식품안전교육 프로그램이다. 지난 2022년부터는 식품사 최초로 롯데 거래 여부와 무관하게 국내 모든 식품 제조·가공 업체를 대상으로 무상 실시하고 있다. 총 4200명의 수강생을 배출했으며 식품업계 ESG 실천의 모범사례로 꼽힌다.2026년 LFSA는 △원산지 표시 실무 △깨끗하고 위생적인 식품공장 만들기 △식품공전의 이해 및 적용 △식품법령 파헤치기(수입식품안전관리 특별법 편) △올바른 식품표시의 이해 △중대재해처벌법의 실무 대응(중대시민재해 편)의 주제로 실시간 온라인 교육 형태로 운영된다. 롯데중앙연구소에 따르면 올해 과정에는 수강생 니즈를 토대로 4건의 신규 주제가 추가됐다.신청은 상생누리 또는 롯데중앙연구소 홈페이지에서 가능하며 협력사는 롯데중앙연구소 식품안전관리통합시스템(FSM)에서 접수할 수 있다.롯데중앙연구소 안전센터 관계자는 "양질의 교육을 제공해 협력사를 비롯한 국내 많은 중소 식품업체의 품질인력관리 부담을 해소하고 업계 식품안전문화 발전에 도움이 되고 싶다"며 "앞으로도 수강생의 목소리를 반영하여 실무에 도움이 되는 과정을 제공하기 위해 노력할 것"이라고 말했다.한편, 롯데중앙연구소는 1983년 설립된 롯데그룹의 종합 식품 연구소다. 롯데웰푸드, 롯데칠성음료, 롯데GRS 등 롯데 식품사 신제품 개발 및 품질 개선, 기초·바이오 연구, 패키징 개발, 식품 및 상품 안전 관리 등을 담당하고 있다.', NULL, '아이뉴스24', 'https://n.news.naver.com/mnews/article/031/0001011366', 'https://imgnews.pstatic.net/image/031/2026/03/09/0001011366_001_20260309092219038.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 09:22:19', 0, true, '2026-03-09 06:22:49.393143') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1110, '[딜 워치]골프웨어 크리스에프앤씨, 프리미엄 받고도 눈물의 손절', '온타이드 지분 40%, 386억원 받고 약진통상에 매각보통주 167% 프리미엄 받았지만 취득가 대비 손절매OEM 업황 급랭에 실적 급락, 매출 줄고 적자 전환장내매수·FI 지분 정리하며 500억 투자...100억대 손실골프웨어 전문 코스닥 상장사크리스에프앤씨가 코스피 상장 의류 주문자상표부착방식(OEM) 전문업체온타이드지분을 3년여 만에 손절했다. 글로벌 생산기지를 확보해 공급망 경쟁력을 높이겠다는 전략이었지만, 업황 악화로 기업가치가 급격히 떨어지면서 기대했던 성과를 거두지 못했다. 인수 이후 장내 매수와 재무적투자자(FI) 지분 취득까지 이어지며 약 500억원 가까운 자금을 투입했지만, 결과적으로는 100억원대 손실을 떠안게 됐다.크리스에프앤씨, 온타이드 387억에 매각크리스에프앤씨는 지난 4일 보유 중인 온타이드 경영권 지분 전량(40.16%)을약진통상에 넘기는 주식양수도계약(SPA)을 체결했다. 매각 대상은 보통주 2245만9094주(29.27%)와 상환전환우선주(RCPS) 835만730주(10.88%)다. 총 매각 대금은 387억원이다.전체 매각대금 가운데 약 80%에 해당하는 310억원이 계약 당일 납입됐고, 주식 이전 절차도 마무리했다. 이에 따라 온타이드의 최대주주는 약 4년 만에 크리스에프앤씨에서 약진통상으로 변경됐다. 잔금 77억원은 오는 27일 납입 예정이다.표면적인 매각 조건만 놓고 보면 경영권 프리미엄은 상당한 수준이다. 보통주의 양수도 단가는 주당 1340원으로 코스피 상장사인 온타이드의 최근 1개월 평균 종가(501원) 대비 약 167.5%의 프리미엄이 붙었다. RCPS 역시 주당 1025원으로 시장 가격 대비 두 배 수준에서 거래됐다.시너지 노리고 인수했는데…실적 저조했던 온타이드그러나 높은 경영권 프리미엄에도 투자 성과는 기대에 미치지 못한 모습이다. 크리스에프앤씨가 인수한 이후로 온타이드의 주가가 많이 떨어진 탓에 결과적으로는 원금 회수에 실패했다는 분석이 나온다.두 회사의 인연은 2022년 8월로 거슬러 올라간다. 핑(PING), 팬텀(PHANTOM), 파리게이츠(PEARLY GATES) 등 골프웨어 브랜드를 앞세워 국내 시장 1위를 유지하던 크리스에프앤씨는 제조 역량 내재화를 위해 니트류 주문자상표부착생산(OEM) 업체 온타이드(당시 국동)을 인수했다.크리스에프앤씨가 기대한 핵심 시너지는 온타이드가 보유한 글로벌 생산 거점이었다. 온타이드는 인도네시아와 멕시코에 생산기지를 운영하며 나이키(Nike), H&M 등 글로벌 패션 기업들과 계약을 맺고 있었다.온타이드 인수를 통해 글로벌 공급망 불안에도 안정적인 생산 기반을 확보하면서 원가 경쟁력을 강화는 것이 크리스에프앤씨의 복안이었다. 같은 시기 이탈리아 스포츠 브랜드 ‘하이드로겐’을 인수하며 해외 사업 확장을 추진하던 상황에서 온타이드는 밸류체인의 마지막 퍼즐로 여겨졌다.당시 크리스에프앤씨는 온타이드의 전 최대주주 다와이홀딩스로부터 지분 21.82%를 340억원에 취득하며 경영권을 확보했다. 주당 인수 가격은 2822원이었다. 경영권 확보 이후에는 56억원 규모의 우선주를 추가 인수하며 운영자금을 지원하기도 했다.그러나 시장 환경은 녹록지 않았다. 글로벌 경기 둔화와 소비 위축 여파로 의류 OEM 업황이 급격히 악화되면서 온타이드 실적도 빠르게 꺾였다.실제 온타이드의 경영 지표는 크리스에프앤씨가 경영권을 잡은 2022년을 정점으로 매년 가파른 하향 곡선을 그렸다. 2022년 매출 3299억원, 영업이익 170억원을 기록했지만 이후 매출은 2000억원대 초반으로 줄었고 영업손익도 적자로 돌아섰다. 지난해 잠정 실적 기준으로도 매출 2315억원, 영업손실 19억원을 기록하며 수익성 회복이 지연됐다.실적 부진에 주가도 내리막길, 손실 감수실적 부진은 주가으로 옮겨갔다. 온타이드 주가는 2023년 이후 하락세를 이어가며 400~500원대까지 밀리는 등 역사적 저점을 형성했다.주가 하락 국면에서 크리스에프앤씨는 이례적인 장내매수에 나섰다. 2024년 9월부터 지난해 2월까지 총 15차례에 걸쳐 약 312만9577주를 추가 매집했다. 평균 매입 단가는 약 515원 수준으로 초기 취득 단가의 5분의 1에도 미치지 않는 가격이었다. 경영권 매각을 염두에 두고 전체 보유 지분의 평균 취득 단가를 낮추려는 재무적 판단이 반영된 것으로 해석된다.이번 매각 협상을 앞두고 재무적투자자(FI) 지분을 정리하는 작업도 진행했다. 크리스에프앤씨는 지난해 12월 ‘아트만-JB 신기술투자조합 제1호’가 보유하고 있던 RCPS를 전량 인수했다. 이를 통해 경영권 지분을 단일 창구로 정리하면서 원매자와의 협상에서 통매각 구조를 만들 수 있게 됐다.최종 성적표는 손실이다. 크리스에프앤씨가 초기 지분 인수와 장내매수, FI 지분 인수 등에 투입한 총 투자금은 약 497억원에 달한다. 반면 이번 매각을 통해 회수한 금액은 약 387억원에 그쳤다. 약 4년간의 투자 끝에 111억원의 손실을 본 셈이다.크리스에프앤씨 관계자는 "핵심 사업에 집중하기 위해 온타이드 매각을 결정하게 됐다"며 "운영을 하는 동안 주가가 많이 빠졌는데, 현재 500원 수준으로 주가가 형성돼 있는 것과 비교하면 괜찮은 가격에 매각했다고 생각하고 있다"고 말했다.', NULL, '비즈워치', 'https://n.news.naver.com/mnews/article/648/0000045058', 'https://imgnews.pstatic.net/image/648/2026/03/09/0000045058_001_20260309090016191.jpg?type=w800', 'NEWS_CONSUMER', NULL, '2026-03-09 09:00:16', 0, true, '2026-03-09 06:22:55.367721') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1111, '기획재정부, 산업경쟁력강화 관계장관회의 겸 성장전략 TF', '오늘 장 체크리스트▶오전 8시30분기획재정부, 산업경쟁력강화 관계장관회의 겸 성장전략 TF▶오전 10시포스코DX3분기 실적▶오전 11시더불어민주당-대한상공회의소정책간담회▶낮 12시한국은행10월 통화 및 유동성▶낮 12시국가데이터처2024년 기업활동조사 결과▶오후 4시한국은행금통위 의사록▶오후 9시30분(한국시간)미국 10월 소매판매▶오후 10시30분(한국시간)11월 미국 고용보고서▶아크릴상장(공모가 1만9500원)▶리브스메드청약(공모가 5만5000원)▶한화 온타이드 동아화성 에이에스텍 디앤디플랫폼리츠주주총회', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005224693', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_CONSUMER', NULL, '2025-12-15 17:27:13', 0, true, '2026-03-09 06:22:55.367721') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1112, '[특집기획]③ 고물가 속 ''똑똑한 시작''…유통가 ''올인원'' 승부수', '[2026 아카데미] 새학기 맞이 학용품부터 체험형 프로그램·디지털 기기 할인 등 ''풍성''지난 18일 고객이 롯데마트 제타플렉스 서울역점 가방 진열 코너에서 신학기 용품을 둘러보고 있다. [사진=롯데마트][디지털데일리 유채리기자] 필기구와 책가방만 준비하면 되던 새 학기는 끝났다. 신학기를 앞둔 유통업계는 학용품이라는 카테고리를 넘어 먹거리, 문화 체험, 일상 공간까지 아우르는 ''라이프스타일 올인원'' 채널로 거듭나고 있다. 고물가 기조 속에서 단순 할인을 넘어 고객의 취향과 경험을 공략하는 대규모 프로모션이 줄을 잇는 추세다.◆ "김치 담그고 ''볼꾸'' 하고"…이색 경험 눈길먼저 풀무원 뮤지엄김치간은 신학기를 맞아 학생들에게 색다른 문화 경험을 선사한다. 직접 담근 김치를 활용해 요리를 만들고 시식하는 프리미엄 프로그램 ''김치 올인원''을 새롭게 선보인다. 특히 3월에는 ''처음''을 주제로 새 학기를 시작하는 이들에게 입장료를 할인해주고, 유료 관람객에게는 ''김치 포춘 카드''를 제공한다.롯데마트는 체험형 강좌를 강화한다. 송파점 등 전국 42개 롯데마트 문화센터에서는 최근 유행인 ''볼펜 꾸미기(볼꾸)'' 특강을 진행한다. 가방 꾸미기 특강도 열린다. 각 수업에서는 이니셜을 활용해 자신만의 키링을 만들 수 있다.[사진=이마트]◆ 학용품, 가방은 필수품…잡화부터 디지털 기기까지 ''파격 특가''신학기 필수품인 문구와 생필품 할인 대전도 뜨겁다. 문구기업 모나미는 오는 28일 네이버 브랜드스토어에서 최대 63% 할인하는 ''브랜드데이''를 연다. 주요 프리미엄 라인을 구매하는 고객에게는 무료 각인 서비스를 제공해 ''나만의 잇템''을 선호하는 학생들의 수요를 공략한다.스타벅스 코리아는 학생들의 새로운 시작을 응원하는 ''백 투 스쿨(Back to school)'' 굿즈를 선보인다. 굿즈는 텀블러, 크로스백, 보냉백 세트로 키즈부터 대학생까지 라이프스타일에 맞춰 폭넓게 사용할 수 있도록 구성했다. 스타벅스 앱 내 온라인 스토어에서는 백 투 스쿨 기획전을 통해 3일까지 5만원 이상 구매 시 적용 가능한 10% 할인 쿠폰을 제공한다.GS25에서도 3월 한 달 간 1500여 종의 인기 상품을 대상으로 대규모 할인 프로모션을 펼친다. 이번 프로모션은 전국 초중고 및 대학 인근 주요 100개 점포를 대상으로 데이터를 분석해 간편식, 스낵 등 9개 카테고리를 핵심 상품군으로 선정해 집중 할인한다.백화점과 마트 역시 실속 있는 신학기 준비를 돕는다. 현대백화점은 전국 백화점과 아울렛 점포에서 국내외 아동스포츠 브랜드의 의류 가방 등 브랜드 상품을 최초 판매가 대비 최대 30% 할인한다. 이마트는 프리미엄 상품에 대한 수요가 높은 생리대 균일가 행사와 더불어 태블릿, 노트북, 복합기 등 고가의 디지털 기기를 최대 20% 할인한다.무신사도 신학기 시즌을 앞두고 올 한 해 가장 큰 규모의 잡화 축제인 ''잡화 페스티벌''을 연다. 오는 3월5일까지 진행하는 이번 행사는 새로운 시작을 준비하는 고객들을 위해 무신사의 폭넓은 잡화 큐레이션을 제안하고자 기획됐다. 가방, 신발은 물론 디지털 기기까지 카테고리를 확장한 게 특징이다.[사진=오늘의집]◆ "새 학기는 내 방부터" 홈퍼니싱 시장도 신학기 ''정조준''''홈퍼니싱'' 시장도 신학기 특수를 정조준한다. 오늘의집은 올해 첫 빅세일 ''집요한 세일''을 내달 8일까지 연다. 이번 세일은 고객이 상품 탐색에 헤맬 필요 없이 오늘의집에서 원하는 상품을 합리적인 가격에 구매할 수 있도록 만족도가 검증된 상품을 선보인다. 또 삼성전자, LG전자, 한샘, 시디즈 등 인기 브랜드를 한 자리에 모은 ''브랜드세일''도 함께 진행한다.가격대가 높아 구매를 망설이던 대형 가구들도 파격적인 가격으로 만나볼 수 있다. 한샘은 상반기 최대 쇼핑 행사인 ''쌤페스타''를 다음달 3일부터 30일까지 전국의 한샘 매장과 온라인 한샘몰에서 동시에 진행한다. 현대 리바트도 소파와 침대 등 가구는 최대 10% 할인하고 구매 금액대별로 5~10% 추가 할인을 적용한다. 일부 특가 상품은 최대 60%까지 할인 판매한다.유통업계 관계자는 "저출산 여파로 학령인구는 줄고 있지만 아이 한 명에게 투자가 집중되는 ''텐 포켓'' 현상이 뚜렷해진 덕에 신학기 소비 규모는 오히려 커지는 추세"라며 "연초 소비 심리를 선점할 수 있는 중요한 대목인 만큼 당분간 세분화된 고객 취향을 겨냥한 마케팅 경쟁이 더욱 치열해질 것"이라고 분석했다.', NULL, '디지털데일리', 'https://n.news.naver.com/mnews/article/138/0002219039', 'https://imgnews.pstatic.net/image/138/2026/02/27/0002219039_001_20260227094909846.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-27 09:49:09', 0, true, '2026-03-09 06:23:03.425162') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1113, '모나미, 네이버 브랜드데이 진행…"단 하루 최대 63% 할인"', '무료 각인 서비스 등 추가 혜택 제공모나미는 오는 28일 단 하루 네이버 브랜드스토어에서 ''브랜드데이''를 열고 인기 제품들을 최대 63% 할인가로 판매한다고 26일 밝혔다.이번 행사에는 색연필·사인펜·물감 등 신학기 필수 문구류를 비롯해 프리미엄 볼펜과 만년필 제품을 최대 63% 할인된 가격으로 선보인다. 또한 컬래버레이션 제품과 롭다(LOBDA)의 데스크테리어 용품까지 다양한 제품을 만나볼 수 있다.모나미 네이버 브랜드데이 대표 이미지. 모나미제품 할인과 함께 추가 혜택도 마련했다. 153 골드, 153 아이디 로즈 등 주요 프리미엄 라인을 구매하는 고객에게는 무료 각인 서비스를 제공한다. 특히 153 독도 프리미엄 볼펜 세트를 구매할 경우 판매 수익금 일부가 사단법인 독도사랑운동본부에 기부된다.이와 함께 ''알림 받기'' 설정 시 3% 추가 할인 쿠폰을 증정한다. 포토리뷰 이벤트 참여자는 추첨을 통해 총 30명에게 네이버페이 포인트 3000원을 지급한다.모나미 관계자는 "앞으로도 소비자들이 만족할 수 있는 차별화된 제품과 혜택을 제공하기 위해 꾸준히 노력하겠다"라고 했다.', NULL, '아시아경제', 'https://n.news.naver.com/mnews/article/277/0005726862', 'https://imgnews.pstatic.net/image/277/2026/02/26/0005726862_001_20260226195911367.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-26 19:58:30', 0, true, '2026-03-09 06:23:03.425162') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1114, 'AI 인재 뺏기 현대차도 뛰어들었다…삼성·SK와 3파전', '[앵커]반도체 호황을 맞은 삼성과 SK가 대규모 채용에 나서는 가운데 현대차까지 가세했습니다.AI 인재를 선점하기 위해 국내 글로벌 기업들이 그야말로 사활을 건 쟁탈전에 돌입했습니다.박규준 기자, 현대차가 또 대규모 채용에 나서는군요?[기자]현대차가 이번 달 중으로 경영지원 등 일반직과 연구직 신규 채용을 합니다.오는 20일부터 다음 달 3일까지 채용공고를 하고, 4~5월 서류전형, 인적성 검사 5~6월 직무면접, 7월 이후 입사 예정 일정인 것으로 알려졌습니다.이들 중 연구인력들은 현대차 의왕 연구소, 남양 연구소 등에 배치됩니다.앞서 현대차는 지난해 10월에도 연구개발, 생산·제조 등 부문을 대상으로 신입, 경력 사원들을 뽑았는데 5개월 만에 대규모 인재 확보에 나섭니다.이 가운데 나스닥 상장이 유력한 현대차 보스턴다이내믹스는 최근 아틀라스 관련 로봇 운영 기술자, 선임 전기 엔지니어, VR 소프트웨어 엔지니어 채용 공고를 띄우며 전문성 보강에 나섰습니다.[앵커]삼성, SK 하이닉스는 채용 일정이 더 빠르죠?[기자]삼성전자를 비롯한 삼성그룹 18개 계열사는 내일(10일)부터 신입사원 지원서를 접수합니다.삼성그룹은 "삼성은 반도체, 인공지능 첨단산업 육성을 위해 청년 채용 확대에 나서며 5년 간 6만 명을 채용할 것"이라고 밝혔습니다.SK하이닉스도 내일부터 신입사원 채용을 시작합니다.경기 이천과 청주 캠퍼스 등에서 일할 메모리 반도체 분야 인력으로 박사급 인력까지 모집 대상에 포함했습니다.올 초 청주와 용인에 40조 원을 쏟아붓기로 한 SK하이닉스는 HBM 생산 라인을 돌릴 핵심 인력 확보가 시급한 상황입니다.업종의 경계가 사라진 재계의 AI 인재 3파전은 올 상반기 채용시장의 최대 화두가 될 전망입니다.SBS Biz 박규준입니다.당신의 제보가 뉴스로 만들어집니다.SBS Biz는 여러분의 제보를 기다리고 있습니다.홈페이지 = https://url.kr/9pghjn', NULL, 'SBS Biz', 'https://n.news.naver.com/mnews/article/374/0000496691', 'https://imgnews.pstatic.net/image/374/2026/03/09/0000496691_001_20260309152108863.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-03-09 15:21:08', 0, true, '2026-03-09 06:23:09.805722') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1115, '다가온 정기 주총 시즌, 기업들 ''정관 재정비'' 러시', '상법 개정안 맞춰 집중투표제 의무화·감사위원 분리선출 확대 등 조치우원식 국회의장이 지난해 3월13일 오후 서울 여의도 국회에서 열린 제423회 국회(임시회) 제1차 본회의에서 상법일부개정법률안 가결을 선포하며 의사봉을 두드리고 있다. / 사진=뉴시스정기 주주총회 시즌이 다가오면서 주요 대기업들이 정관 재정비에 속도를 내고 있다. 개정된 상법 시행을 앞두고 이사충실 의무 확대, 전자주총 도입 등의 안건을 정기 주총 핵심 안건으로 상정하며 관련 규정을 손질하고 있다.9일 재계에 따르면 올해 정기 주총에서 정관 변경 안건을 상정한 기업이 크게 늘어났다. 자산 규모가 큰 대기업을 중심으로 정관 재정비 움직임이 활발하다.삼성전자는 이번 정기 주총에서 이사회 운영과 관련된 일부 정관 조항을 손질하기로 했다. 집중투표제 배제 조항을 삭제하고 이사의 충실의무 대상 확대 관련 조문 정비하는 식이다. 사외이사의 독립이사 명칭 변경 관련 조문과 감사위원 분리 선출 인원 상향 관련 조문도 손보기로 했다. 전자 주주총회 도입 관련 조문도 정비할 예정이다.현대자동차그룹 역시 주요 계열사를 중심으로 정관 변경 논의를 진행하고 있다. 기아와 현대모비스는 감사위원 선임 및 이사회 관련 규정을 중심으로 정관 변경 안건을 주총에 상정했다.SK하이닉스도 집중투표제 배제 조항 삭제와 전자 주총 도입을 골자로 한 정관 변경을 추진한다. 이 밖에 상법 개정 반영을 위한 정관 변경, 사외이사·기타비상무이사·감사위원 선임, 이사 보수한도, 임원 퇴직금 지급 규정 개정 등이 처리될 예정이다.LG그룹에서도 정관 정비 움직임이 이어지고 있다. LG전자는 이사회 운영과 관련한 일부 조항을 손질하는 정관 변경 안건을 주총에 상정했으며 LG화학과 LG디스플레이 등 주요 계열사들도 지배구조 관련 규정 정비에 나섰다.포스코홀딩스는 이사회 및 감사위원회 운영과 관련된 일부 규정을 정비하는 방안을 검토하고 있으며 고려아연 역시 감사위원 선임 방식 등을 포함한 정관 변경 안건을 논의 중이다.주요 대기업들이 정관 재정비에 나서는 가장 큰 이유는 개정 상법 시행에 따른 제도 변화 때문이다. 지난해 국회 문턱을 넘은 1차 상법 개정안은 기업 이사의 주주에 대한 충실의무를 명문화하고 감사위원을 선임할 때 최대주주, 특수관계인 의결권을 ''합산 3%''로 제한하는 내용을 골자로한다. 상장회사 전자 주주총회를 의무화하고 사외이사를 독립이사로 전환하는 내용도 포함됐다.2차 상법 개정안은 자산 규모 2조 원 이상의 기업에 집중투표제 시행을 의무화했고 분리선출 감사위원 확대 등을 규정하고 있다. 7월 23일 자로 독립이사 명칭 변경이 시행되고 9월 10일부터는 집중투표제 시행이 의무화된다. 이에 따라 기업들은 제도 시행 이전에 정관을 선제적으로 정비해 불확실성을 줄이려는 움직임을 보이고 있다는 분석이다.행동주의 펀드와 기관투자가의 영향력 확대 역시 기업들이 정관 정비에 나서는 배경으로 꼽힌다. 최근 국내 주식시장에서 주주권 행사가 활발해지면서 기업들은 경영권 안정성과 지배구조 투명성을 동시에 고려한 제도 정비 필요성이 커졌기 때문이다.재계에서는 올해 정기 주총 시즌이 국내 기업 지배구조 변화의 분수령이 될 것으로 본다. 재계 관계자는 "개정 상법 시행을 앞두고 주요 기업들이 정관을 선제적으로 정비해 제도 변화에 대응하려는 분위기"라며 "앞으로도 기업 지배구조와 관련한 제도 변화에 따라 정관 개정 논의가 지속될 것"이라고 말했다.', NULL, '동행미디어 시대', 'https://n.news.naver.com/mnews/article/417/0001133293', 'https://imgnews.pstatic.net/image/417/2026/03/09/0001133293_001_20260309152107746.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-03-09 15:20:15', 0, true, '2026-03-09 06:23:09.805722') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1116, '주한미군 전역 장병, 美진출 韓기업 현지 채용 지원 플랫폼 출범', '대미 투자 발맞춘 민간 협력 모델韓기업-주한미군 연결로 한미 경제협력 강화대한상공회의소가 9일 상의회관에서 한미동맹재단, 미국 진출 국내 기업과 함께 ''주한미군 전역장병 채용 플랫폼(이하''플랫폼'') 운영 협력''을 위한 업무협약(MOU)을 체결하고, 플랫폼을 공식 오픈했다.이번 협약은 대한상의가 구축한 플랫폼을 통해 미국에 진출한 한국 기업과 주한미군 출신 전역 장병 간의 미국 내 일자리 매칭을 지원하고, 이를 바탕으로 한미 협력과 파트너십 확대에 기여하고자 마련됐다.박일준 대한상의 상근부회장과 참석자들이 9일 기념촬영을 하고 있다.(앞줄 왼쪽부터 최은미 LG에너지솔루션 인재육성담당, 강인석 이마트 지원본부장, 유인정 효성중공업 상무, 니콜라스 남바 공관차석 대행, 제임스 헬러 주한미국대사대리, 임호영 한미동맹재단 회장, 박일준 대한상의 상근부회장, 김대자 산업통상부 국가기술표준원장, 이형희 서울상의 부회장, 제임스김 AMCHAM 회장, 지승영 GS건설 HR실장, 정무경 고려아연 사장, 장종인 HyAxiom 수석). 대한상공회의소체결식에는 박일준 대한상의 상근부회장, 임호영 한미동맹재단 회장, 제임스 헬러 주한미국대사대리, 김대자 산업통상부 국가기술표준원 원장, 제임스 김 주한미국상공회의소 회장, 이형희 서울상의 부회장 등이 참석 했으며, 삼성전자, SK하이닉스, 현대자동차 등 미국 진출 국내 대표기업들이 함께했다.플랫폼에는 반도체, 자동차, 이차전지 등 첨단 제조 분야를 비롯해 에너지·조선·로봇·바이오·식품 등 미국 내 다양한 산업군에서 활발히 활동 중인 21개사(삼성전자, SK하이닉스, SK온, SK바이오팜, 현대자동차, 기아자동차, LG에너지솔루션, 롯데인프라셀, 포스코홀딩스, 한화오션, 한화큐셀, HD현대일렉트릭, GS건설, 이마트, LS그룹, 두산밥캣, HyAxiom, 두산로보틱스, 고려아연, 효성중공업, 상미당홀딩스)가 참여했다. 이들 산업은 미국 내 제조·연구개발(R&D)·영업·서비스 등 다양한 직무 수요가 확대되고 있는 분야들이다.협약에 따라 대한상의는 플랫폼 운영 및 기업 대상 홍보를 담당하고, 한미동맹재단은 장병 대상 안내 및 참여 독려를 맡는다. 기업들은 플랫폼에 채용공고를 등록·관리하는 것을 지원하고, 플랫폼을 통해 지원한 주한미군 장병을 대상으로 채용 절차를 진행하는 역할을 수행한다.주한미군으로 한국에서 근무한 장병들은 한국 사회와 문화에 대한 이해도가 높고, 양국을 연결하는 경험을 갖춘 인재라는 점에서 미국에 진출한 우리 기업에 실질적인 도움이 될 수 있을 것으로 전망된다.상의는 지난해 9월 한미동맹재단과 사업 추진을 위한 첫 업무협약을 체결한 이후, 평택·동두천·오산 등 주요 미군기지 관계자를 만나 플랫폼을 소개하고 유관기관과의 협력을 이어 왔다. 아울러 기업 대상 설명회와 홍보를 병행하며 플랫폼 활성화를 위한 기반을 단계적으로 구축해 왔다.박일준 대한상의 상근부회장은 "우리 기업들의 적극적인 투자가 미국 내 대규모 고용 창출로 이어지고 있는 만큼, 주한미군 장병들이 그 결실을 공유하며 양국 관계가 더욱 공고해질 것으로 기대한다"며 "이번 플랫폼이 한국 기업의 인력난 해소와 미군 장병의 취업 지원을 동시에 달성하는 한미 협력의 대표적인 ''윈윈'' 모델이 될 수 있도록 플랫폼 고도화와 참여기업 확대에 힘쓰겠다"고 말했다.제임스 김 주한미국상공회의소(AMCHAM) 회장은 "최태원 대한상공회의소 회장과 대한상의가 이처럼 선도적이고 의미 있는 이니셔티브를 추진한 데 대해 높이 평가한다"며 "한미동맹의 굳건한 관계를 고려할 때, 미국 내 한국 기업에서 미군 장병들에게 일자리 기회를 제공하는 이번 이니셔티브는 매우 의미가 크다"고 화답했다.', NULL, '아시아경제', 'https://n.news.naver.com/mnews/article/277/0005731526', 'https://imgnews.pstatic.net/image/277/2026/03/09/0005731526_001_20260309152008198.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-03-09 15:19:18', 0, true, '2026-03-09 06:23:09.805722') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1194, '장원영, 137억 ‘이곳’에 쐈다…김태희도 산 한남 고급빌라 어딜까', '한남동 부촌 유엔빌리지 소재 고급빌라2007년 준공…대림디앤아이 첫 사업장철저한 보안·희소성·조용한 주거 환경이 기사는 헤럴드경제 회원 전용 콘텐츠 ‘초고가주택 그들이 사는 세상’에 게재된 기사입니다. 회원으로 가입하시면 더 생생하고 유익한 콘텐츠를 ‘먼저’ 보실 수 있습니다.서울 용산구 한남동 ‘루시드하우스’ 단지 전경. [대림디앤아이 공식 홈페이지][헤럴드경제=신혜원 기자]“중개업을 하면서 정말 다양한 고급주택을 가봤지만 ‘루시드하우스’ 보안시스템은 그중에서도 가장 높은 편이었어요. 워낙 가구수가 적은 데다 주거 만족도가 높아서 임대도 매물이 잘 안 나옵니다.”(송예준 에테르부동산중개법인 대표)앞으로는 탁 트인 한강 조망을 누릴 수 있고 뒤로는 남산이 위치한 배산임수 입지를 갖춘 국내 대표 부촌 유엔빌리지 안에서도 ‘루시드하우스’는 최고급 빌라로 손 꼽힌다. 2000년대 후반에 지어진 구축 주택임에도 거래될 때마다 수십억씩 뛰며 초고가주택으로서의 위상을 입증하고 있다. 가구수가 적어 매매 자체가 드물지만 지난해 그룹 아이브 멤버 장원영이 137억원 전액 현금 매입한 사실이 알려지며 다시 한 번 시장의 관심을 받았다.서울 용산구 한남동 유엔빌리지길을 따라 언덕을 오르다 보면 나오는 루시드하우스는 2개 동, 15가구 규모로 2007년 7월 준공됐다. 범 DL그룹(옛 대림그룹) 3세인 이해성 대표가 설립한 부동산 개발업체 대림디앤아이(대림D&I)가 처음으로 시행한 사업장으로, 15가구 모두 244.53~273.65㎡(이하 전용면적) 대형 타입으로 구성됐다.2007년 분양 당시 40억원 초반대로 공급돼 유엔빌리지 내 최고가를 기록했다. 서울부동산정보광장에 따르면 2007년 12월 기준 서울 아파트 평균 매매금액은 3억1744만원으로, 루시드하우스 분양가격이 일반 아파트 평균금액의 10배를 넘는 수준이었다.배우 김태희·범DL가(家) 인사들 보유…임상민 대상 부사장도 현금 매입가격만큼이나 루시드하우스에 거주했거나 보유하고 있는 이들의 면면도 화려하다. 이해성 대표가 이끄는 대림디앤아이의 사업장인 만큼 범DL가 인사 다수가 루시드하우스를 분양받았다. 고(故) 이재준 DL그룹 창업주의 차남이자 이해성 대표의 아버지인 고(故) 이부용 대림바스(옛 대림비앤코) 고문이 1가구를 분양받아 현재는 이해성 대표의 차남에게 증여된 상태다.이해성 대표의 동생인 이해영 대림바스 회장도 1가구를 분양받아 거주하고 있다. 이재준 DL그룹 창업주의 막내동생인 이재연 아시안스타 회장과 결혼한 고(故) 구인회 LG그룹 창업회장의 차녀 구자혜씨는 1가구를 분양받은 뒤 2009년 아들인 이지용 전 대림통상 대표에게 증여했다. 이지용 전 대표는 해당 가구를 약 16년간 보유하고 있다가 지난해 3월 그룹 아이브 멤버 장원영에게 137억원에 매도했다.이 전 대표는 어머니로부터 증여받은 가구 외에도 지난 2017년 루시드하우스의 또다른 가구를 70억원에 매수한 뒤 2021년 4월 허진수 GS칼텍수 상임고문에게 83억5000만원에 매도했다.이해성 대표 또한 1가구를 보유하고 있었는데 지난 2022년 3월 임세령 대상 부회장의 동생인 임상민 대상 부사장에게 98억5000만원에 팔았다. 임 부사장은 98억5000만원 대금 전액을 현금으로 치렀다.뿐만 아니라 배우 김태희는 2012년 2월 루시드하우스 1가구를 43억4868만4191원 전액 현금으로 매수해 거주하다가 가수 비와 결혼한 이후인 2018년 8월 64억원에 매도했다.식품 기업 ㈜팔도도 법인 명의로 1가구를 보유하고 있고, 중국인 A씨와 미국인 B씨도 1가구씩 갖고 있다.보안과 프라이버시·입지·희소성 모두 갖춰…18년간 매매 17건 뿐이처럼 루시드하우스를 거쳐갔거나 보유한 인사들의 면면은 단순히 고가주택이라는 이유 만으로는 설명되지 않는다. 루시드하우스가 서울 내 여러 초고가주택 중 연예계·재계인사들의 선택을 받아 온 배경에는 ▷보안과 프라이버시 ▷입지 ▷희소성 등이 있다. 주거 기준이 가격보다 ‘프라이빗하고 조용하게 살기 좋은 집’에 맞춰져 있는 자산가 수요가 반영됐다.서울 용산구 한남동 ‘루시드하우스’ 단지 전경. [대림디앤아이 공식 홈페이지]①보안에 최적화된 구조…유엔빌리지에서도 언덕 위쪽 위치고급주택으로서의 루시드하우스의 가장 큰 경쟁력은 보안이다. 사생활 노출을 꺼리는 유명인사들에게 동선 노출이 최소화된 루시드하우스 구조는 매력적인 지점이다. 한 층에 두 가구만 거주하는 데다 라인별 엘리베이터가 따로 있어 같은 동 거주자라 하더라도 마주칠 가능성이 높지 않다. 24시간 보안 시스템 또한 고급주택 중 최고 수준이라는 게 중개업 관계자 설명이다.또한 유엔빌리지로 진입하는 도로 자체가 제한적이고 루시드하우스는 유엔빌리지 안에서도 고지대에 위치해 있어 외부인의 접근이 어렵다. 언덕길이기 때문에 보행자 통행이 많지 않고 차량 위주로 이동하게 돼 자연스럽게 외부 유입이 걸러지게 된다. 입지와 설계가 맞물려 조용하면서 사생활이 노출되지 않는 주거 환경이 완성됐다.송 대표는 “청담, 압구정, 성수 등 서울에 다양한 부촌이 있지만 유엔빌리지를 택하는 자산가들의 가장 큰 이유는 프라이빗함 때문이다”며 “외부인이 유엔빌리지 내에서 왔다갔다할 수 있는 구조 자체가 안 되기 때문에 프라이버시를 중요시하는 분들이 쭉 살고 있고 그런 분위기가 유지되고 있는 것”이라고 말했다.②한강과 남산뷰 동시에…전형적인 배산임수 입지서울 용산구 한남동 ‘루시드하우스’ 내부 이미지. [대림디앤아이 공식 홈페이지]루시드하우스의 또다른 강점은 한강과 남산뷰를 동시에 누릴 수 있는 입지다. 산이 바람을 막아줘 집으로 들어오는 기를 보호하는 역할을 하고, 물이 땅의 기운을 모아 재물이 들어온다고 알려져 있는 전형적인 배산임수 입지로 자산가들의 선호도가 높다. 전면을 가로막는 요소 없이 통창으로 탁 트인 한강뷰를 영구적으로 누릴 수 있고, 입주민들만 이용할 수 있는 옥상정원에서 한강과 남산을 동시에 조망할 수 있다.교통 측면에서도 한남대교가 가까워 강남 접근성이 좋고 남산1호터널을 이용하면 을지로, 광화문 등 강북권 이동도 수월하다. 강변북로, 올림픽대로 진입도 편리하고 경의중앙선·3호선 옥수역, 경의중앙선 한남역 등을 이용할 수 있다. 서울 내 핵심 상권인 한남동·이태원 상권도 걸어서 이용할 수 있어 도심의 주요 입지 요소를 두루 누릴 수 있다. 그러면서도 유동인구나 소음 부담은 크지 않아 편의성과 조용한 주거 환경을 모두 갖췄다는 평가다.③15가구 불과한 희소성…매매·전세 매물 ‘0’전 가구가 대형 면적이면서도 15가구 뿐이라는 점도 루시드하우스의 가치를 높여주는 요소다. 각 동에 1~4층까지 8가구, 7가구가 배치돼 있어 층별·동별 밀도도 낮다.가구수가 적고 입주민들의 주거 만족도가 높아 거래 자체도 1년에 1~2건에 불과하다. 2007년 준공 이후 지난해까지의 매매 거래는 17건 뿐이다. 현재 시장에 나와있는 매매와 전세 매물은 없고, 244㎡ 타입이 보증금 70억원, 임대료 1000만원 월세 매물로 1건 등록돼 있다.공급 자체가 극히 제한적인 데다 실거주 중심으로 수요가 형성돼 있어 거래 빈도가 낮음에도 건마다 가격은 수십억씩 오르는 양상이다. 장원영이 지난해 137억원에 매수한 244.65㎡는 직전 거래가 2021년 4월에 체결됐는데 당시 매매금액은 83억5000만원이었다. 4년 만에 53억5000만원이 오른 것이다. 2022년 98억5000만원에 거래됐던 244.53㎡ 타입도 2023년 108억5000만원에 팔려 1년 새 10억원 뛰었다.송 대표는 “루시드하우스가 두 동짜리 빌라로 규모도 있고 면적이 넓어서 수요가 높은데 매물 자체는 안 나온다”며 “일반 주택과 다르게 시세를 가늠할 수 없다”고 했다.', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002601378', 'https://imgnews.pstatic.net/image/016/2026/02/16/0002601378_001_20260216070011775.png?type=w800', 'NEWS_ETC', NULL, '2026-02-16 07:00:11', 0, true, '2026-03-09 06:27:21.216925') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1117, '코스모화학, 삼성 출신 재무·배터리 전문가 영입', '코스모화학이 오는 3월 26일 제58기 정기주주총회를 개최한다고 24일 공시했다.이번 주주총회에서는 제58기 재무제표 승인, 정관 일부 변경, 이사 및 감사위원 선임, 이사 보수한도 승인 등 총 6개의 안건을 상정할 예정이다.코스모화학은 기존 경영진의 재선임을 통해 경영 연속성을 확보하는 동시에 외부 전문가 영입으로 전문성을 강화할 방침이다. 사내이사로는 삼성전기 부사장 출신의 김두영 대표이사를 비롯해 최재용 최고재무책임자(CFO), 신동구 영업구매부문장, 강선구 코스모앤컴퍼니 대표이사 등 4명에 대한 재선임 안건을 상정했다.사외이사 및 감사위원으로는 재무와 배터리 분야의 전문가들이 후보로 이름을 올렸다. 삼성SDI 경영지원실장(부사장)과 삼성전자 미래전략실 부사장 등을 역임한 재무 전문가 권영노 후보와 한국전기연구원 책임연구원 출신의 배터리 기술 전문가 김현수 후보가 사외이사 겸 감사위원으로 신규 선임할 예정이다. 대전광역시 정무부시장을 지낸 김재혁 사외이사도 재선임 및 감사위원 후보로 확정했다.이번 주주총회에서는 제58기 연결 재무제표 및 결손금처분계산서 승인과 개정 상법 등을 반영하기 위한 정관 일부 변경 건 등을 의결할 예정이다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000079821', 'https://imgnews.pstatic.net/image/293/2026/02/24/0000079821_001_20260224150610704.png?type=w800', 'NEWS_ENERGY', NULL, '2026-02-24 15:06:10', 0, true, '2026-03-09 06:23:17.904733') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1118, '코스모화학, 인도네시아 전구체사에 광물 공급 MOU', '배터리용 황산니켈·황산코발트 조달 협력코스모화학(대표 김두영)은 23일 인도네시아 소재 글로벌 최대 전구체 생산법인과 배터리용 황산니켈 및 황산코발트 공급 협력을 위한 업무협약(MOU)을 체결했다고 밝혔다.이번 협약은 올해부터 2030년까지 배터리급 니켈 황산염과 코발트 황산염의 안정적 공급 및 조달 협력을 주요 내용으로 한다. 양사는 연간 약 2000톤 규모의 니켈, 코발트 황산염 공급을 논의 중이며, 현재 시세로 최대 2000억원 규모다.코스모화학은 이번 협력을 통해 인도네시아 현지 전구체 생산과 연계한 원료 공급 체계를 구축할 것으로 기대된다.코스모화학 전경양사는 저탄소 공급망 구축이 전기차 산업의 탈탄소화를 가속화하는 핵심 요소란 점에 공감했다. 구체적인 상업 조건은 별도 계약을 통해 확정해 나갈 계획이다.코스모화학 관계자는 “이번 MOU는 글로벌 선도 전구체 기업과의 전략적 협력 기반을 마련했다는 점에서 의미가 크다”며 “지속 가능한 공급망 구축과 장기 파트너십 강화를 통해 글로벌 시장에서의 경쟁력을 더욱 높여가겠다”고 밝혔다.이번 MOU는 구속력 있는 본 계약 체결을 전제로 한 협력 의향서로, 구체적인 거래 조건은 향후 별도 계약 체결을 통해 확정될 예정이다.', NULL, '지디넷코리아', 'https://n.news.naver.com/mnews/article/092/0002411496', 'https://imgnews.pstatic.net/image/092/2026/02/23/0002411496_001_20260223192418173.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-02-23 19:24:18', 0, true, '2026-03-09 06:23:17.904733') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1119, '[지배구조 톺아보기] 범GS家 코스모그룹, 허경수 회장 지배력 강화…자녀들은 ‘유통 시험대’ 세웠다', 'CB로 실탄 확보…코스모신소재, 양극재 투자지주사 코스모앤컴퍼니, 적자 유통 떼어내 ‘순수 지주사’ 전환핵심 ‘이차전지’는 회장이 직할… 자녀에겐 비주력 맡겨 경영 수업리스크 차단과 승계 명분 동시에 챙기는 ‘이원화 전략’ 가동범GS그룹에 속하는 코스모그룹이 전환사채(CB) 발행 등 자본 거래를 계기로 허경수 회장 중심의 지배구조 재편에 속도를 내고 있다.그룹의 미래인 이차전지 소재 사업은 허 회장이 지주사를 통해 지배력을 강화한 반면, 수익성이 낮은 유통 사업은 자녀들에게 넘기는 이원화 전략을 택했다. 이는 지주사의 재무 건전성을 확보하는 동시에, 그룹 핵심과 떨어진 곳에서 자녀들의 경영 능력을 검증하겠다는 포석으로 풀이된다.그래픽=손민균‘돈 먹는 하마’ 유통 떼어내고, ‘순수 지주사’로 체질 개선9일 금융감독원과 투자은행(IB) 업계에 따르면 코스모그룹 내 상장사인 코스모신소재는 지난달 1200억원 규모의 CB를 발행해 국내외 양극재 관련 투자를 진행할 계획을 세웠다. 양극재는 배터리의 용량·출력·수명·안전성을 좌우하는 핵심 소재로, 코스모신소재 사업인 이차전지 소재 부문과 직결된다.지주사인 코스모앤컴퍼니도 국내 사모펀드(PEF) 운용사를 통해 자금을 조달할 계획인 것으로 전해졌다. 자금 조달이 끝나면 코스모앤컴퍼니는 순수 지주사로 전환한 뒤 일부 자금을 코스모신소재에 투입해 지배구조를 공고히 다지고, 코스모신소재는 확보한 자금으로 일시적으로 성장세가 둔화한 이차전지 소재 시장을 현금으로 버티겠다는 구상이다.허신구 GS리테일 명예회장의 장남인 허 회장은 2015년 GS그룹에서 독립해 코스모그룹을 이끌고 있다. 코스모그룹의 지주사인 코스모앤컴퍼니 지분은 허 회장이 100% 보유하고 있다. 허 회장은 코스모앤컴퍼니⟶코스모화학⟶코스모신소재로 이어지는 지배구조 정점에 올라 있다.코스모그룹의 이번 지배구조 개편은 ‘선택과 집중’이라는 전략을 보여준다. 그동안 허 회장이 지분 100%를 보유한 지주사 코스모앤컴퍼니는 기형적인 구조였다. 자회사를 거느린 지주사임에도 불구하고, 과거 정산티비엘 등과 합병하며 떠안은 가전·스포츠용품 유통 사업을 직접 영위해왔기 때문이다. 특히 2023년 4월부터 야심 차게 전개한 글로벌 가전 브랜드 ‘샤크닌자’ 유통은 아픈 손가락이 됐다. 샤크닌자 탓에 코스모앤컴퍼니는 2024년 영업손실 143억원으로 2023년(약 111억원)보다 적자 폭이 더 커졌다.사업으로 재미를 보지 못하자 이번 자본 거래를 계기로 순수 지주사 전환을 꾀하고 있다. 가전 유통과 스포츠용품 도소매 사업은 마진이 낮고 재고 부담이 크다. 이미 코스모화학과 코스모신소재라는 핵심 계열사를 보유한 상황에서 지주사가 실익 없는 사업을 껴안고 있던 셈이다.순수 지주자 전환은 허 회장 지배력을 강화하는 결과도 낳는다. 지주사가 직접 사업을 하지 않으면 영업상 위험은 자회사로 분산되고, 지주사는 투자·지분 관리에만 집중할 수 있다. 지주사 실적 변동이 그룹 전체 가치나 위험으로 직결되지 않아 지배구조 안정성이 높아진다.그래픽=손민균자녀들에겐 ‘안전한 울타리’ 대신 비주력 맡겨이번 개편에서 눈여겨볼 대목은 허 회장의 자녀들(선홍·수연·지연씨)의 위치다. 그룹이 사활을 건 배터리 사업 대신, 지주사가 포기한 ‘유통 사업’을 넘겨받았기 때문이다.이들이 보유한 ‘디투에스원파트너스’가 그 중심에 있다. 장남 허선홍씨(60%)와 두 딸이 지분 100%를 가진 이 회사는 경영컨설팅 업체지만, 실질적으로는 그룹 물류를 담당하는 조양국제종합물류의 모회사 역할을 한다. 코스모앤컴퍼니가 손을 떼는 샤크닌자 등 유통 사업은 향후 조양국제종합물류가 넘겨받을 공산이 크다.실적 상당 부분은 관계사 성과에 의존하고 있다. 디투에스원파트너스는 2023년과 2024년 매출 없이 각각 691만원, 2837만원의 영업 손실을 기록했다. 다만 매년 매출 약 600억원, 영업이익 약 20억원 규모의 조양국제종합물류 실적이 지분법 이익으로 반영되면서 회계상 당기순이익은 흑자를 냈다. 지분법 이익은 자회사 이익을 지분율에 따라 모회사 실적에 반영하는 방식이다.시장에서는 자녀들에게 비핵심 사업을 통해 경영 수업을 진행하려는 ‘승계 준비용 구조 재편’ 성격이라고 평가한다. 기업 인수·합병(M&A) 전문 변호사는 “가장 비싼 자산과 가장 민감한 의사 결정에서 자녀들을 분리한 구조”라며 “향후 승계 과정에서 발생할 수 있는 이해관계 충돌을 최소화하려는 의도로 보인다”고 말했다.전기차 캐즘(일시적 수요 둔화)으로 이차전지 시장이 숨 고르기에 들어간 지금, 코스모그룹은 지배구조 재편이라는 내부 정비를 통해 ‘다음 스텝’을 준비하고 있다. 허경수 회장의 ‘이원화 승부수’가 그룹의 도약과 승계라는 두 마리 토끼를 모두 잡을 수 있을지 주목된다.', NULL, '조선비즈', 'https://n.news.naver.com/mnews/article/366/0001141298', 'https://imgnews.pstatic.net/image/366/2026/02/09/0001141298_001_20260209060233147.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-02-09 06:02:33', 0, true, '2026-03-09 06:23:17.904733') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1120, '제주를 움직이는 ‘연결’의 의미… 한진 한국공항 기탁, 인프라 기업의 역할을 다시 묻다', '항공망·지상 운영·물류 맞물린 구조 속, 커진 책임5,000만 원 기탁, 지역과 이어온 협력의 흐름관광을 넘어 생활과 안전까지 확장된 역할기업의 선택이 곧 섬의 조건이 되는 현실대한항공 787-10. (대한항공 제공)제주에서는 기업의 활동이 곧 생활 환경과 맞닿습니다.하늘길로 내륙과 연결되는 항공편의 안정성은 이동의 문제를 넘어 의료 접근과 물류 흐름, 지역 경제의 리듬까지 좌우합니다.이러한 구조 속에서 24일 한진그룹 계열사 한국공항이 제주사회복지공동모금회에 5,000만 원을 기탁했습니다.이번 기탁은 단순히 한 기업의 지원 소식 이상의 의미를 가집니다.항공 네트워크와 지상 운영을 통해 제주 사회의 기반과 긴밀하게 연결돼 온 기업이 어떤 방식으로 지역과 관계를 이어가고 있는지를 보여주기 때문입니다.이날 제주자치도의회에서 열린 전달식에서 한국공항은 지역사회와의 협력 의지를 재확인했습니다.이 자리에서 이수근 사장은 지역과 함께 실질적인 협력 방안을 이어가겠다고 밝혔습니다.한진그룹 계열사 한국공항이 제주자치도의회에서 제주사회복지공동모금회에 성금을 전달한 뒤 관계자들과 기념촬영을 하고 있다. (대한항공 제공)■ 항공 네트워크가 곧 지역의 기반으로 작동하는 구조대한항공은 제주를 오가는 국내외 노선을 통해 사람과 자원을 연결하는 축을 형성해 왔습니다.한국공항은 항공기 지상 조업과 화물 처리 운영을 담당하며 이 연결이 안정적으로 작동하도록 뒷받침하고 있습니다.섬 지역에서는 운항의 연속성이 곧 지역의 안정성과 직결됩니다. 관광 수요뿐 아니라 주민 이동과 긴급 수송까지 항공망의 영향을 직접적으로 받습니다.■ 물류 흐름이 만드는 생활의 연속성제주에서 생산된 농산물과 생활 물자는 항공 화물과 물류 운영을 통해 전국으로 이동합니다.특히 계절 변화가 뚜렷한 지역 특성상 운송망의 역할은 산업의 지속성과 직결됩니다.겨울철 농산물 수송 지원과 농가 협력은 항공과 물류 인프라가 지역 산업을 어떻게 지탱해 왔는지를 보여주는 사례로 평가됩니다.■ 공공 기능을 수행해 온 항공 서비스대한항공이 운영하는 중환자 항공 이송(스트레처) 서비스는 항공사가 지역 사회의 안전망으로 기능해 온 대표적인 성공 모델로 꼽힙니다.연간 100여 건의 환자 이송을 지원하고, 경제적 부담 완화를 위해 필요 좌석의 절반 이상을 무상 제공하고 있습니다.응급 상황에서 환자 이동을 지원해 온 경험은 기업 활동이 공공 영역과 맞닿아 있음을 보여줍니다.■ 산업 환경 변화 속에서 더 선명해진 역할최근 항공 산업 환경 변화 속에서 한진그룹의 제주 내 역할은 더욱 또렷해지고 있습니다.항공과 물류 운영이 지역 경제 구조와 긴밀히 맞물려 있는 만큼 기업의 선택은 지역 전반에 영향을 미칩니다대한항공·아시아나항공 통합을 상징하는 로고 합성 이미지.이번 기탁은 이러한 흐름 속에서 기업이 지역과 어떤 방식으로 관계를 이어갈 것인지 다시 생각하게 하는 계기로 받아들여집니다.제주에서는 기업의 역할을 일회성 활동이 아니라, 축적되는 책임의 문제로 바라봅니다.항공망 운영과 물류 지원, 지역 협력으로 이어져 온 경험은 한진그룹이 사업 주체를 넘어 지역 인프라의 한 축으로 기능해 왔음을 보여줍니다.한진이 제주에서 이어 온 선택은 결국 하나의 방향으로 모입니다.지역과 함께 작동하는 구조를 얼마나 안정적으로 유지할 것인가라는 질문입니다.남는 것은 연결을 지켜내는 일입니다.', NULL, 'JIBS', 'https://n.news.naver.com/mnews/article/661/0000071818', 'https://imgnews.pstatic.net/image/661/2026/02/24/0000071818_001_20260224150015758.png?type=w800', 'NEWS_ETC', NULL, '2026-02-24 15:00:15', 0, true, '2026-03-09 06:23:25.863283') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1121, '[제주소식] 한진그룹 한국공항, 제주 취약계층 지원 성금 5천만원 기부', '지난 23일 제주도의회 의장실에서 열린 한국공항 성금 전달식[한국공항 제공. 재판매 및 DB 금지](제주=연합뉴스) 한진그룹 계열사 한국공항은 지난 23일 제주도의회 의장실에서 성금 전달식을 갖고 제주사회복지공동모금회에 5천만원을 기부했다고 24일 밝혔다.이날 전달된 기부금은 제주지역 취약계층 지원 사업에 쓰일 예정이다.이수근 한국공항 사장은 "제주도와 상생할 수 있는 실질적인 방안을 모색하고 있다"며 "그룹사와 협력해 지역사회 기여를 확대해 나가겠다"고 말했다.', NULL, '연합뉴스', 'https://n.news.naver.com/mnews/article/001/0015921481', 'https://imgnews.pstatic.net/image/001/2026/02/24/AKR20260224114300056_01_i_P4_20260224145821171.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-24 14:57:27', 0, true, '2026-03-09 06:23:25.863283') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1122, '한국공항㈜, 9개 외국 항공사로부터 감사패 받아', '[이데일리 정병묵 기자] 한진그룹 계열사 한국공항은 인천국제공항에 취항 중인 9개 외국 항공사로부터 감사패를 수상했다고 1일 밝혔다.이번 수여식은 인천공항에서 외국적 항공사의 화물조업을 담당하고 있는 한국공항의 전문적이고 안정적인 조업 서비스와 헌신적인 파트너십에 대한 감사의 뜻을 전하기 위해 마련됐다.한국공항 관계자는 “고객 항공사로부터 차별화된 조업 역량을 인정받게 되어 매우 뜻깊다”며, “앞으로도 완벽한 안전 운항 지원과 고객 만족도 제고를 위해 최상의 서비스를 제공하겠다”고 소감을 밝혔다.한편, 한국공항은 항공기 지상조업 서비스를 주력으로 하는 국내 최대 지상조업사로 현재 인천공항에 취항하는 29개 항공사의 화물조업을 수행하고 있으며, 인천공항의 연간 전체 화물 물동량 약 295만톤 중 절반이 넘는 150만톤을 도맡아 처리하고 있다.아울러, 한진제주퓨어워터, 제동한우, 물류장비 렌탈, 세탁사업 등 다양한 분야로 사업 영역을 확대하고 있다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006193234', 'https://imgnews.pstatic.net/image/018/2026/01/01/0006193234_001_20260101110810070.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-01 11:08:10', 0, true, '2026-03-09 06:23:25.863283') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1123, '삼립 리더십 대수술…도세호 ''생산·안전''·정인호 ''글로벌''(종합)', '잇단 악재 이후 대대적 조직 쇄신…도세호·정인호 각자대표 체제로생산·안전 강화하고 글로벌 확대…"미래 성장 기반 공고히 다질 것"27일 경기 시흥시 SPC삼립 시화공장의 모습. ⓒ 뉴스1 황기선 기자(서울=뉴스1) 배지윤 기자 = 삼립이 안전사고와 실적 부진·공장 화재 등 잇단 악재를 계기로 대대적인 리더십 개편에 나섰다. 생산·안전 관리와 글로벌 사업 전략을 동시에 강화하기 위해 각자대표 체제를 도입하며 경영 체계를 정비하겠다는 전략이다.9일 삼립(005610)에 따르면 회사는 이날 이사회를 열고 도세호 상미당홀딩스 대표와 정인호 농심켈로그 대표를 각자 대표이사로 내정했으며, 이달 26일 열리는 정기 주주총회를 거쳐 공식 선임될 예정이다.각자대표 체제는 사업 부문을 나눠 책임 경영을 강화하고 의사결정 효율성을 높일 수 있는 구조로 평가된다. 삼립 역시 생산·안전 관리와 글로벌 사업 전략을 분리해 운영하는 방식으로 경영 체계를 정비하고 역할 분담을 명확히 할 계획이다.업계에서는 이번 인사가 지난해 발생한 안전사고를 비롯해 실적 부진·공장 화재 등 대내외 이슈와 경영 환경 변화에 대응하기 위한 대대적인 조직 쇄신 차원으로 보고 있다. 이에 따라 새로운 리더십을 중심으로 경영 체계를 정비하는 방향으로 인사 기조가 정해진 것으로 알려졌다.도세호 삼립 대표, 정인호 삼립 대표.(삼립 제공)도 대표 내정자는 제조 현장과 노사 협력 분야에서 경험을 쌓아온 전문가로 평가된다. 삼립은 도 대표가 생산 체계 재정비와 함께 현장 중심의 안전 문화를 정착시키는 역할을 맡게 될 것으로 기대하고 있다. 특히 생산 운영 체계를 안정화하고 안전 경영을 강화하는 데 집중할 전망이다.정 대표 내정자는 농심켈로그와 홍콩·대만 지역을 총괄하며 전략과 영업을 담당해 온 글로벌 경영 전문가다. 삼립은 정 내정자의 합류를 통해 글로벌 스탠다드에 부합하는 선진 경영 체계를 구축하고 해외 사업 확대에 속도를 낼 계획이다.삼립 관계자는 "이번 인사는 최근 경영 환경의 변화를 엄중히 인식하고 생산 현장과 경영 전반에 걸친 변화와 혁신을 추진하기 위한 것이다. 안전과 글로벌 사업 강화라는 두 축을 중심으로 경쟁력을 강화하고 미래 성장 기반을 더욱 공고히 해 나갈 것"이라고 말했다.한편 삼립은 경재형 수석부사장을 신임 대표로 내정해 김범수 현 대표와 함께 각자대표 체제를 구축할 계획이었다. 그러나 기존 단독 대표였던 김범수 대표가 임기 만료로 자리에서 물러나게 됐다. 각자대표로 선임될 예정이었던 경재형 수석부사장도 정기 주주총회를 앞두고 개인적인 사유로 사임했다.', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008815034', 'https://imgnews.pstatic.net/image/421/2026/03/09/0008815034_001_20260309151615982.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 15:15:47', 0, true, '2026-03-09 06:23:47.106621') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1124, '삼립, 도세호·정인호 각자대표 내정…"경영 쇄신 추진"', '삼립이 9일 이사회를 열고 도세호(68) 상미당홀딩스 대표와 정인호(58) 농심켈로그 대표를 각자 대표이사로 내정했다고 밝혔다. 내정자들은 오는 26일 정기 주주총회를 거쳐 공식 선임될 예정이다.삼립 측은 “이번 인사는 새로운 리더십을 바탕으로 경영쇄신을 추진하고, 안전과 글로벌 사업 강화란 두 축을 중심으로 경쟁력을 강화하기 위한 것”이라고 설명했다.삼립 대표로 내정된 도세호 상미당홀딩스 대표. 사진 삼립도세호 대표는 1987년 (주)샤니에 입사한 뒤 샤니 공장장과 ㈜SPC팩 대표이사 등을 거쳤다. 현재 지주사인 상미당홀딩스와 파리크라상 대표를 겸직하고 있다. 그는 삼립의 생산체계를 재정비하고, 안전경영을 강화하는 역할을 맡게 된다.잇따른 공장 사망사고로 흔들린 기업 신뢰도를 회복하기 위해 제조 현장 경험이 풍부한 내부 인사를 발탁했다는 해석이 나온다. 삼립은 “도 대표가 현장 중심의 안전 문화를 정착시키고 생산운영 체계를 안정적으로 강화할 것으로 기대한다”고 밝혔다.삼립 대표로 내정된 정인호 농심켈로그 대표. 사진 삼립정인호 대표는 글로벌 식품기업 ‘켈라노바(구 켈로그)’의 한국법인인 농심켈로그와 홍콩·대만 지역을 총괄해왔다. 그는 삼립의 해외사업 확대와 선진 경영체계 구축을 담당할 예정이다.앞서 삼립은 이달 주총에서 김범수 대표를 재선임하고, 황종현 대표의 후임으로 경재형 파리크라상 대표를 삼립 수석부사장으로 선임해 김 대표와 각자 대표체제를 구축할 계획이었다. 그러나 경 수석부사장이 주총을 약 3주 앞둔 이달 초 개인 사유로 사의를 표명하며 대표 인선이 변경됐다.', NULL, '중앙일보', 'https://n.news.naver.com/mnews/article/025/0003507765', 'https://imgnews.pstatic.net/image/025/2026/03/09/0003507765_001_20260309150007279.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 14:59:04', 0, true, '2026-03-09 06:23:47.106621') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1125, '경재형 SPC삼립 수석부사장, 사내이사 선임 주총 앞두고 사임', '삼성 출신 재무통⋯SPC삼립 "개인 사유"SPC삼립의 신임 대표로 내정됐던 경재형 수석부사장이 정기주주총회를 앞두고 전격 사임했다.경재형 SPC삼립 수석부사장. [사진=SPC삼립]6일 관련 업계에 따르면 경 부사장은 전날 개인적인 사유로 사의를 표명했다.그는 오는 26일 열리는 SPC삼립 정기주주총회에서 김범수 현 대표와 함께 사내이사로 선임될 예정이었다. SPC삼립은 두 사람을 각자대표로 선임해 경영하는 체제로 전환하는 방향을 추진해 왔다.경 부사장은 1989년 삼성전자에 입사해 27년 넘게 근무하며 재무 분야에서 경력을 쌓았다. 2017년 SPC삼립 경영관리본부장으로 영입된 이후 영업본부장과 FoodBU장 등을 거쳤고 파리크라상 대표를 역임했다.SPC삼립 측은 경 부사장이 개인적 사유로 자진 사임했으며, 주총 등 향후 일정은 예정대로 진행할 것이란 입장을 밝혔다.', NULL, '아이뉴스24', 'https://n.news.naver.com/mnews/article/031/0001011172', 'https://imgnews.pstatic.net/image/031/2026/03/06/0001011172_001_20260306211508700.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-06 21:15:08', 0, true, '2026-03-09 06:23:47.106621') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1126, '아버지 공장서 찾은 창업아이템...매출 10배 찍고, 미국까지 넘본다', '[스타트UP스토리]안재민 비링커 대표[이 기사에 나온 스타트업에 대한 보다 다양한 기업정보는 유니콘팩토리 빅데이터 플랫폼 ''데이터랩''에서 볼 수 있습니다.]안재민 비링커 대표 /사진=김진현 기자반도체 산업에는 공장 없이 설계만 전문으로 하는 ''팹리스(Fabless)''가 존재한다. 쇳물을 녹이고 철을 깎는 전통 제조업에서도 팹리스 모델이 가능할까.제조업 위탁생산과 AI(인공지능) 기반 도면관리 솔루션을 운영하는 비링커 안재민 대표는 이 질문에 "그렇다"고 답한다. 안 대표는 대학 시절 아버지의 금형 공장 일을 돕다가 창업의 실마리를 찾았다. 제조 현장은 여전히 종이 도면을 사용하거나 이메일로 작업 내용을 주고받아 업무 파편화와 보안 취약성 문제가 심각했기 때문이다.안 대표는 "IT 기술로 도면을 체계적으로 관리하고, 발주사와 제조사를 한 곳에 모아 연결하면 비효율을 해결할 수 있다고 판단했다"고 말했다. 그는 연세대학교 재학 시절 이 아이디어로 예비창업패키지의 지원을 받아 창업에 나섰다.━제조사 매칭·AI 도면 관리 ''투트랙''━비링커의 사업 모델은 크게 두 축이다. 위탁생산 솔루션인 ''비링커 매뉴팩처링''과 AI 기반 도면관리 솔루션 ''비링커 클라우드''다.비링커는 직접적인 생산 설비를 보유하지 않는다. 대신 고객사가 도면을 의뢰하면 자체 보유한 제조사 네트워크 데이터를 기반으로 가장 적합한 공장을 매칭해 제품을 생산한다. 대기업의 제조 수요와 중소 공장의 생산 역량을 연결하는 플랫폼 역할을 하는 셈이다.안 대표는 비링커의 핵심 경쟁력을 품질 관리로 꼽았다. 비링커는 충남 천안에 1300평 규모의 품질관리센터(Hub)를 구축했다. 이곳에서 모든 위탁 생산품의 품질을 검수(QC)한 뒤 출고해 ''팹리스 제조''의 약점인 품질 신뢰도를 보완했다. 안 대표는 초기에 직접 전국의 공장을 돌며 네트워크를 확보했고, 제조업 전문인력을 영입해 검수 시스템을 고도화했다.또 다른 축인 ''비링커 클라우드''는 제조 현장의 디지털전환(DX)을 돕는다. AI 기반 OCR(광학문자인식) 기술을 탑재해 도면 내 치수, 소재, 공정 정보 등을 자동으로 추출해 데이터베이스화한다. 숙련된 작업자가 퇴사하면 노하우가 사라지거나 종이 도면이 유실되는 등의 고질적인 문제를 해결했다. 모바일 CAD 뷰어, IP(지식재산권) 접근 제한 기능 등을 통해 보안성도 높였다.제조업계의 DX를 이끌어낸 비링커의 기술력은 투자사의 투자로 이어졌다. 한국투자액셀러레이터, GVA자산운용, 스트롱벤처스, 신용보증기금 등이 비링커의 기술력을 보고 투자를 결정했다.비링커 개요/그래픽=이지혜━매출 10배 성장…3월 美 법인설립 ''글로벌 도전장''━비링커 클라우드 도면관리 솔루션/사진제공=비링커비링커는 설립 첫해인 2023년 매출 2억4000만원을 기록한 데 이어 2024년에는 13억원을 달성했다. 지난해에는 약 20억원의 매출을 올리며 2년 만에 10배 가까운 성장세를 보였다.이같은 성장의 비결은 대·중견기업 고객사를 빠르게 확보한 덕이다. 특히 세아그룹 계열사 브이엔티지(VNTG)의 투자를 유치한 이후 빠른 성장의 기반을 마련할 수 있었다. 세아그룹은 비링커 솔루션을 통해 기존 벤더 대비 원가절감 효과를 확인하고 세아제강, 세아창원특수강, 세아베스틸 등 핵심 계열사로 도입을 확대했다.복잡한 공장 관리와 협상 과정을 대행해주는 편의성이 입소문을 타면서 한국앤컴퍼니(한국타이어) 계열사를 비롯해 삼영전자공업, 유니크 등 중견기업까지 파트너로 확보했다.비링커는 올해 3월 미국 법인 설립하고 북미 시장 공략에 본격 나설 계획이다. 시카고에 법인을 설립하고 안 대표가 직접 상주하며 해외 사업을 진두지휘할 계획이다. 미국은 제조업 수요는 높지만 인건비와 가공비가 한국 대비 최대 6배까지 비싸다는 점에 착안해 미국 진출을 계획했다. 미국 기업과 국내 제조업체를 연결해 저렴한 단가로 제품을 제조해 공급할 계획이다.안 대표는 "한국은 중국을 대체할 수 있는 제조 품질과 지리적 강점을 가진 나라"라며 "한국에서 고품질 부품을 제조해 미국으로 수출하는 방식으로 가격 경쟁력과 품질을 모두 잡을 것"이라고 말했다.비링커의 목표는 한국의 제조 뿌리기업들이 글로벌 시장에서 활약할 수 있도록 돕는 것이다. 그는 "국내 제조 경쟁력은 높지만 해외 진출 여력이 없는 중소 공장들이 많다"며 "비링커가 이들의 해외 영업부서이자 물류팀이 되어 한국 제조업의 부흥을 이끌겠다"고 말했다.[머니투데이 스타트업 미디어 플랫폼유니콘팩토리]', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005310354', 'https://imgnews.pstatic.net/image/008/2026/01/28/0005310354_001_20260128060123463.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-28 06:00:00', 0, true, '2026-03-09 06:23:54.608175') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1127, '기업 공시 [1월 15일]', '[서울경제]<코스피 시장>▲금호타이어(073240)=곡성공장 중대재해 발생 공시 ▲대한조선(439260)=아프리카 지역 선주와 2539억 원 원유운반선 수주 계약 체결 ▲LS(006260)=자회사 LS전선의 멕시코의 전선 제조업 계열사에 2277억 원 출자 공시 ▲교촌에프앤비(339770)=삼성증권과 임직원 보상용 자사주 10억 원어치 취득 계약 체결 ▲삼영전자=직원의 근속과 성과 장려하기 위한 자사주 지급 목적으로 6600주 처분<코스닥 시장>▲크레버스(096240)=자사주 20만 주 소각 결정 ▲코미코(183300)=임직원 보상 목적으로 자사주 3270주 처분 ▲티에스아이(277880)=자사주 20만 4708주 취득 결정 ▲협진(138360)=회사 상호 앤로보틱스로 변경 ▲상상인(038540)=주주가치 제고 목적으로 NH투자증권과 자사주 20억 원어치 취득 신탁 계약 체결', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004579188', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2026-01-15 16:04:19', 0, true, '2026-03-09 06:23:54.608175') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1128, '‘전자·IT의 날’… LG전자 조주완 금탑산업훈장', '조주완 LG전자 최고경영자가 21일 서울 강남구 코엑스에서 열린 제20회 전자·IT의 날 기념식에서 금탑산업훈장을 받은 후 문신학 산업통상부 1차관과 기념 촬영하고 있다./산업통상부LG전자 조주완 대표가 21일 서울 삼성동 코엑스에서 열린 ‘제20회 전자·IT의 날’ 행사에서 금탑산업훈장을 받았다. 조 대표는 1987년 금성사(현 LG전자)에 입사해, 2021년부터 대표를 맡고 있다. 지난 37년간 LG전자 및 국내 전자 산업 경쟁력 강화 등에 기여한 공로를 인정받았다.은탑산업훈장은 전자제품 핵심 소재인 AL 전해 콘덴서 등을 국산화하는 데 기여한 삼영전자공업 김성수 대표이사가, 산업포장은 소비자·주방 혁신 가전 개발 등에 기여한 박재순 쿠첸 대표이사가 받았다.이날 행사에는 이들을 포함해 전자·IT 산업 발전 유공자 총 41명이 포상을 받았다. ‘전자·IT의 날’은 우리나라 전자·IT 연간 수출액이 처음 1000억달러를 돌파한 2005년에 제정돼, 매년 10월 한국판 소비자전자전시회(CES)인 ‘한국전자전’ 개막을 기념해 개최되고 있다.', NULL, '조선일보', 'https://n.news.naver.com/mnews/article/023/0003935991', 'https://imgnews.pstatic.net/image/023/2025/10/22/0003935991_001_20251022004341849.jpg?type=w800', 'NEWS_ETC', NULL, '2025-10-22 00:43:41', 0, true, '2026-03-09 06:23:54.608175') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1129, '파미셀, 현금 배당 및 자가주식 소각 결정…배당금은 주당 얼마?', '주당 50원, 자가주식 1만 2950주 소각파미셀이 현금 배당과 자가주식 소각으로 주주친화 정책에 나섰다.파미셀은 주당 50원의 현금배당 실시와 자기주식 1만2950주 소각을 결정했다고 24일 밝혔다.파미셀은 지난해 매출 1140억원, 영업이익 343억원, 당기순이익 403억원을 기록하며 창사 이래 최대 실적을 달성했다. 직전 해와 비교해 매출은 75%, 영업이익은 637%, 당기순이익은 536% 증가하며 연 매출 1000억원을 처음으로 돌파했다. 회사는 역대 최고 실적으로 확보한 이익을 주주 환원에 적극 활용하기로 했다.이번 배당의 배당금 총액은 30억원이다. 배당기준일은 지난해 12월 31일이며, 배당금 지급은 주주총회일로부터 1개월 이내에 지급될 예정이다. 이는 전년도 창사 이래 첫 배당이었던 주당 20원보다 150% 높은 수준으로, 2년 연속 배당을 실시하며 주주 환원 정책을 강화하고 있다.회사는 배당과 함께 보유 중인 자기주식 1만2950주를 소각하기로 결정했다. 자기주식 소각은 발행주식총수를 감소시켜 주당순이익 등 주당 가치 지표를 개선하는 효과가 있다.파미셀은 줄기세포치료제, 혁신적인 원료의약물질, 첨단 AI 소재 등 미래 성장 동력을 확보하는 동시에 울산 3공장 건설 등 대규모 투자를 이어가고 있다. 이러한 투자 국면에서도 배당 확대와 자기주식 소각을 결정한 것은 장기 투자자와의 신뢰를 최우선으로 하겠다는 경영 방침에 따른 것이다.파미셀 관계자는 “창사 이래 최대 실적을 달성할 수 있도록 지지해 준 주주들과 성과를 나누는 것은 당연한 결정”이라며, “앞으로도 사업의 경쟁력을 강화해 기업가치를 높이는 것은 물론, 지속 가능한 주주환원 정책을 통해 시장과 적극적으로 소통하겠다”고 말했다.', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005254350', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_BIO', NULL, '2026-02-24 11:30:12', 0, true, '2026-03-09 06:24:03.759555') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1134, '크라운해태, 2026년 한음회 전국 순회 첫 무대 광주 공연 성료', '전국 16개 도시 순회 공연의 첫 무대제7회 크라운해태 한음회 광주공연에서 임직원 국악동아리 ''팔풍의 몸짓팀''이 ''종묘제례일무 전폐희문''을 공연하고 있다.(크라운해태 제공)(서울=뉴스1) 이형진 기자 = 크라운해태홀딩스제과(005740)는 임직원들이 국악 명인명창들과 함께 꾸민 ''제7회 크라운해태 한음회'' 공연이 지난 28일 광주예술의전당 대극장에서 성황리에 열렸다고 29일 밝혔다.크라운해태는 임직원들이 스스로 즐기며 익힌 전통음악으로 고객들의 사랑에 보답하기 위해 전국을 무대로 순회 공연을 이어가고 있다. 지난해 광역시를 중심으로 연 4회 열렸던 공연을 올해는 전국 중소도시까지 포함해 총 16회로 대폭 늘려 더 많은 고객들과 흥겨운 국악 무대를 펼친다.올해 순회 무대의 포문을 연 광주 공연은 전석(1500석) 고객 초청으로 가득 채우며 지역 시민들과 하나된 무대를 선보였다. 국악 명인명창과 차세대 국악 인재인 한음 영재들도 한자리에 올라 전통 음악의 깊이와 젊은 에너지가 함께 어우러진 무대를 펼쳤다.크라운해태제과 관계자는 "올해 한음회 공연의 첫 시작을 광주 고객들과 함께해 기쁘다"며 "광주를 시작으로 광역시부터 중소도시까지 전국을 순회하며 고객들에게 울림 있는 우리 소리를 들려드리도록 노력할 것"이라고 밝혔다.', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008741214', 'https://imgnews.pstatic.net/image/421/2026/01/29/0008741214_001_20260129092541933.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-29 09:25:07', 0, true, '2026-03-09 06:24:19.124183') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1135, '[2025 증시 결산]② 두 차례 상법 개선으로 증시 체질 개선', '''사천피'' 돌파 정책적 뒷받침…''자사주 소각'' 3차도 잰걸음주주 중심 패러다임 전환…''행동주의 펀드'' 보폭 확대 전망국회 본회의서 ''더 센'' 상법 개정안 처리(서울=연합뉴스) 황광모 기자 = 지난 8월 25일 서울 국회 본회의에서 상법 개정안이 여당 주도로 처리되고 있다.상법 개정안은 자산 규모 2조원 이상 기업에 집중투표제 시행을 의무화하고, 분리선출 감사위원 확대 등의 내용을 담고 있다. 2025.8.25 hkmpooh@yna.co.kr(서울=연합뉴스) 임은진 고은지 기자 = 올해 새 정부 출범 이후 두 차례 이뤄진 상법 개정은 국내 증시를 본격적인 ''불장''으로 이끄는 불쏘시개 역할을 했다.이재명 대통령과 여당은 ''코스피 5,000시대''를 달성하기 위한 핵심 과제로서 상법 개정에 강하게 드라이브를 걸었다.상법 개정은 그동안 ''코리아 디스카운트''의 주된 원인으로 지적돼 온 재벌 중심의 불투명한 지배구조, 소극적인 주주 친화 정책, 정책의 불확실성 등을 해소할 중요한 열쇠로 여겨졌기 때문이다.이에 지난 7월 1차 상법 개정에 이어 9월 두 번째 상법 개정이 이뤄졌다. 자사주 소각 의무화를 담은 3차 상법 개정안도 내년 1월 국회 처리가 논의되고 있다.전문가들은 "국내 증시의 낮은 배당 성향과 주주환원 등이 상법 개정 등을 통해 해소되는 중"이라며 "체계적인 증시 부양책과 제도 개선이 뒷받침된다면 추가 상승도 가능하다"고 전망했다.코스피 상승 (CG)[연합뉴스TV 제공]새 정부 들어 1, 2차 상법 개정…"더 센 법 온다"1차 상법 개정안은 기업 이사의 충실 의무 대상을 회사 및 주주로 확대하고, 감사위원 선임 시 최대 주주와 특수 관계인의 의결권을 합산 3%로 제한하는 내용을 담고 있다.''더 센 상법''으로 불린 2차 개정안은 자산 2조원 이상 상장사에 대해 집중투표제 도입을 의무화하고, 감사위원 분리 선출을 기존 1명에서 2명 이상으로 확대하는 내용을 골자로 한다.두 차례 상법 개정은 국내 증시에 상승 압력으로 작용했다.1차 개정안이 국회를 통과한 7월 3일 코스피 지수 종가는 전 거래일 대비 41.21포인트(1.34%) 오른 3,116.27로, 기존 연고점인 3,108.25(6월 25일)를 경신했다.코스피 종가가 3,110선을 넘은 것은 2021년 9월 27일(3,133.64) 이후 3년 9개월여만이었다. 특히 외국인이 현·선물시장을 합쳐 1조원 이상을 순매수하며 지수 상승을 견인했다.2차 개정안이 국무회의에서 의결된 9월 2일 코스피는 0.94% 오른 3,172.35에 장을 마치며 3거래일 만에 반등했다.정책적 뒷받침을 받은 주가는 그 이후로 가파르게 상승 곡선을 그렸다.코스피는 지난 10월 27일 사상 처음으로 종가 기준 ''사천피''(코스피 4,000포인트)를 넘어섰고 현재 최고점은 4,221.87(11월 3일)이다.정부와 국회는 3차 상법 개정안도 추진 중이다.증권가에서는 배당소득 분리과세 세율과 자사주 소각 의무화를 골자로 한 3차 상법 개정 등 시장 친화적인 정책이 입안된다면 코스피에 ''강력한'' 상승 동력을 달아줄 것으로 보고 있다.한국투자증권 정다솜 연구원은 "자사주를 취득하고 소각하지 않는 것은 글로벌 스탠더드에서 벗어난 것으로 한국 시장이 선진시장으로 거듭나기 위해서 꼭 필요한 부분"이라며 "3차 개정안에서 논의 중인 자사주 소각 의무화 등은 국내 증시에 미치는 영향력이 큰 만큼 시장의 관심이 제고될 전망"이라고 말했다.상법 개정안 필리버스터 종결을 위한 투표 마친 정청래 대표(서울=연합뉴스) 황광모 기자 = 더불어민주당 정청래 대표(왼쪽)와 김병기 원내대표를 비롯한 당 최고위원단이 25일 국회에서 열린 본회의에서 상법 개정안에 대한 필리버스터 종결을 위한 투표를 마친 뒤 투표소에서 나오고 있다. 2025.8.25 hkmpooh@yna.co.kr주주 환원 강화에 금융·지주株 ''재부각''두 차례 상법 개정으로 특히 주목받은 종목은 금융(증권·보험) 및 지주 업종이었다.새 정부 출범일인 6월 4일 이후 지난 29일까지 KRX 증권 지수 등락률(시작일 기준가 대비 종료일 종가)은 43.90%, KRX 보험 지수는 33.68%, KRX 금융 지수는 32.77%를 기록했다.증권의 경우 KRX 단일 업종 중에서는 정보기술, 반도체, 기계장비, 자동차 다음으로 높다.지주 업종은 지난 7월 1일 국민의힘이 정부·여당이 추진하는 상법 개정안을 전향적으로 검토하겠다고 밝히자 일제히 강세를 보였다.당시 유가증권시장에서 HS효성은 전장보다 29.93% 오른 9만1천600원을 기록하며 상한가에 장을 마쳤다. 이외에도 크라운해태홀딩스(21.19%), 한화(15.38%), 풍산홀딩스(12.1%), SK(9.54%), LS(7.11%), LG(4.27%), CJ(2.8%) 등이 동반 상승했다.다만 같은 달 4일 국회 본회의 통과 당일에는 차익실현 매물이 출회되면서 그간 상법 개정 기대로 올랐던 일부 지주사 종목 주가가 하락했다.2차 상법 개정안이 국회 본회의를 통과했던 지난 8월 25일에도 지주 업종은 강세였다.SK그룹의 중간 지주사인 SK스퀘어는 전 거래일 대비 7.10% 오른 14만4천800원에 거래를 마쳤다. 롯데지주(4.27%), HD현대(2.02%), 한화(1.85%), CJ(2.35%) 등도 올랐다.현대차증권 김한이 연구원은 "상법 개정으로 코리아 디스카운트 해소 기대가 커지면서 지주 업종이 동반 상승했다"면서 "증시 부양, 주주가치 제고 등 정책 기대감이 해당 업종 주가와 동행하는 모습"이라고 말했다.대신증권 리서치센터는 최근 내놓은 ''2026년 산업전망'' 보고서에서 "3차 상법 개정, 배당소득 분리과세 최고 세율 인하, 고배당 기업 펀드 편입, 세제 혜택 등 우호적인 정책이 여전히 대기하고 있다"며 "내년에도 금융 관련 업종 전망은 긍정적"이라고 밝혔다.국내 주식 시황 (PG)[김토일 제작] 일러스트주주 중심 패러다임 전환…행동주의 펀드 광폭 행보 가능성금융투자업계에서는 일련의 상법 개정으로 기업의 지배구조 패러다임이 오너를 비롯한 소수 경영진에서 주주 중심으로 전환될 것이라는 평가가 나온다.특히 주목받는 내용은 상장사의 사외이사를 독립이사로 전환하고 독립이사의 이사회 내 의무 선임 비율을 늘리는 동시에 감사위원 선임·해임 시 최대 주주와 특수 관계인의 의결권을 합산 3%로 제한하도록 한 ''3% 룰''이다.해당 규정은 내년 하반기 시행 예정인 것으로 알려졌다.이에 따라 업계는 내년 3월 정기 주주총회 시즌을 시작으로 향후 소액 주주 및 기관 투자자 중심의 주주 행동주의가 확대될 것으로 내다봤다.김남은 아주기업경영연구소 부본부장은 "이사의 충실 의무 대상 확대가 이사 충실 의무의 ''대상''으로서 주주가 추가된 것인지 혹은 ''내용''으로서 주주가 추가된 것인지 학설이 대립하나 어느 학설에 의하든지 이사에 대한 배임죄 성립 가능성은 증가할 수 있다"고 말했다.그러면서 "위법 행위 유지 청구 또는 가처분 신청 시 이사 충실 의무 이유로 인용 가능성이 높아질 수 있으며 행동주의 펀드 또는 소수 주주에 의한 주주 활동이 활발해질 것"이라고 예상했다.이성훈 키움증권 연구원도 "상법 개정으로 주주 행동주의 캠페인은 가속할 것"이라며 "2024년 기준 한국은 전 세계에서 세 번째로 주주 행동주의 캠페인이 많은 국가로 자리매김했다"고 전했다.실제로 글로벌 리서치업체 ''딜리전트 마켓 인텔리전스''에 따르면 주주행동주의의 대상이 된 한국 기업은 2020년 10개 사에서 지난해 66개 사로 급증했다. 아울러 금융감독원 공시에 따르면 올해 정기주총에서 총 42개 상장회사에 164건의 주주제안이 상정됐는데, 이는 전년도 137건보다 20% 늘어난 결과다.이 연구원은 그러면서 "향후 국내 토종 기관 투자자, 소액 주주 연대, 연기금, 외국계 행동주의 펀드 등 주주 행동주의는 국내 기업의 밸류업으로 연결될 것"이라고 전망했다.업계에서는 임원의 ''셀프 보수 결의'' 사안도 내년 정기 주총 시기 주요 이슈로 제기될 것으로 예상했다.앞서 대법원은 지난 4월 홍원식 전 남양유업 회장이 자신의 이사 보수 한도 결의에 찬성표를 던진 2023년 주총 결의가 무효라고 판단한 원심을 확정했다.한 행동주의 펀드 관계자는 "대법원 판례로 이사인 임원이 자신의 보수를 직접 결정하는 관행에 제동이 걸린 것"이라며 "주주 권익 강화를 위한 행동주의 펀드들의 목소리가 한층 더 커질 것"이라고 말했다.eun@yna.co.kr', NULL, '연합뉴스', 'https://n.news.naver.com/mnews/article/001/0015819459', 'https://imgnews.pstatic.net/image/001/2025/12/30/PYH2025082504470001301_P4_20251230064212383.jpg?type=w800', 'NEWS_ETC', NULL, '2025-12-30 06:05:01', 0, true, '2026-03-09 06:24:19.124183') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1136, '롯데홈쇼핑, 리빙상품 최대 75% 할인', '이사, 신학기 시즌 반영 합리적 쇼핑 기회 제공롯데홈쇼핑(대표 김재겸)은 이달 9일까지 상반기 최대 리빙 행사 ‘룸 앤 키친쇼’를 모바일과 온라인 채널에서 동시 운영하며, 40여 개 인기 브랜드를 최대 75% 할인가에 선보인다고 3일 밝혔다.이번 행사는 봄 웨딩, 이사, 신학기 시즌을 맞아 증가하는 리빙 수요를 반영해 기획됐다. 코로나19 이후 감소했던 혼인 건수가 회복되고 있는 가운데, 2차 베이비붐 세대(1964~1974년생)의 자녀인 2차 에코붐 세대(1991-1996년생)가 본격적인 결혼 연령대에 진입하면서 가구, 침구 등 신규 구매 수요도 확대되고 있다. 이에 맞춰 고객에게 폭넓은 선택지와 실질적인 가격 혜택을 제공하기 위해 역대 최대 규모로 준비했다. 7년간 운영해 온 가구 특집전을 ‘룸 앤 키친쇼’로 전면 개편하고, 가구 중심 행사에서 침구·주방용품까지 카테고리를 확대한 통합 리빙 행사로 재편해 규모와 혜택을 강화했다.롯데홈쇼핑, 90년대생 결혼 본격화에 리빙상품 최대 75퍼 할인행사는 이달 9일까지 라이브커머스 ‘엘라이브(L.live)’와 온라인몰에서 진행된다. ‘자코모’, ‘다우닝’, ‘에싸’ 등 인기 가구 브랜드를 비롯해 프리미엄 침구, 글로벌 주방용품까지 최대 75% 할인 혜택을 제공한다. 사은품 증정과 1+1(원플러스원) 프로모션 등 추가 혜택도 마련했다. ‘엘라이브(L.live)’는 구매가 집중되는 오후 7시부터 9시까지 매일 특집 방송을 편성한다. 3일에는 소파 전문 브랜드 ‘자코모’와 롯데홈쇼핑이 공동개발한 ‘보흐’ 소파를 100만원 대 가성비 상품으로 소개한다.5일에는 지난해 완판을 기록한 금성침대의 ‘루미에르 LED 호텔형 수납침대’를 판매하고, 같은 날 ‘까사미아’의 인기상품 ‘벨로씨 레보르 천연가죽 소파’를 최대 50% 할인된 가격에 선보일 예정이다. 그 밖에 온라인몰에서는 ‘다우닝 플랫소파’, ‘에싸 시모네 스윙소파’, ‘대림바스 소형욕실 리모델링’ 등을 최대 59% 할인하고, ‘헬렌스타인’, ‘박홍근홈패션’ 등 프리미엄 침구와 ‘휘슬러’, ‘스타우브’, ‘포트메리온’ 등 글로벌 주방 브랜드를 단독 특가로 선보인다.김동원 롯데홈쇼핑 리빙부문장은 “90년대생이 본격적인 결혼 연령대에 진입하면서 리빙 수요가 확대되고 있고, 봄철 이사 시즌까지 맞물려 기존 가구 특집전을 최대 리빙 행사로 재편했다”며, “특히 혼수로 선호도가 높은 인기 브랜드를 경쟁력 있는 가격에 선보여 고객 선택의 폭을 넓히고 합리적인 쇼핑 기회를 제공하겠다”라고 말했다.', NULL, '지디넷코리아', 'https://n.news.naver.com/mnews/article/092/0002412670', 'https://imgnews.pstatic.net/image/092/2026/03/03/0002412670_001_20260303175811626.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-03 17:58:11', 0, true, '2026-03-09 06:24:26.267874') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1137, '욕실 인테리어 한번에…대림바스, ‘아르노 시리즈’ 출시', '수전·세면기·양변기 디자인 통일한 첫 시리즈대림바스는 주요 욕실 구성요소 디자인을 통일한 ‘아르노 시리즈’를 출시했다고 24일 밝혔다. <대림바스>대림바스가 수전·세면기·양변기를 하나의 디자인으로 통합한 ‘아르노 시리즈’를 출시했다고 24일 밝혔다.대림바스는 욕실 주요 제품을 하나의 디자인으로 통합 기획해 소비자가 조화로운 욕실을 연출할 수 있도록 기획했다. 향후에도 주요 제품 디자인을 통일한 시리즈형 제품군을 다양하게 출시할 계획이다.대림바스의 첫 시리즈형 제품인 아르노는 이탈리아 피렌체를 지나는 아르노 강에서 영감을 받은 제품이다. 곡선형 콘셉트의 ‘아르노-R’과 직선형 콘셉트의 ‘아르노-S’ 두 가지 제품군을 갖췄다. 아르노-R은 곡선형 수전과 슬림한 핸들라인으로 개방감을 강조했고, 양변기 물탱크 가장자리를 곡선처리했다.아르노-S는 사각형 구조 수전과 세면기로 현대적인 분위기의 욕실에 적합한 디자인이며, 단순한 형태의 위생도기와 조형미가 특징이다.대림바스는 아르노 시리즈의 기능 측면도 강화했다. 양변기는 림리스 구조로 청소 사각지대를 줄였고, 슬림한 물탱크 디자인과 대·소 구분형 레버를 탑재해 물 사용량 관리가 가능하다. 수전은 크롬과 니켈, 건메탈 등 세 가지 색상으로 출시됐다.대림바스는 이후 타일과 상·하부장 등 욕실 가구를 포함한 ‘아르노 욕실 리모델링 패키지’도 순차적으로 선보일 예정이다.', NULL, '매일경제', 'https://n.news.naver.com/mnews/article/009/0005641526', 'https://imgnews.pstatic.net/image/009/2026/02/25/0005641526_001_20260225083010898.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-25 08:30:10', 0, true, '2026-03-09 06:24:26.267874') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1138, '대림바스, 수전·세면기·양변기 ''아르노 시리즈'' 출시', '하나의 디자인으로 통합한 시리즈 제품위생 관리 용이하도록 기능성도 강화대림바스가 수전과 세면기, 양변기를 하나의 디자인으로 통합한 ''아르노 시리즈(ARNO Series)''를 출시했다고 24일 밝혔다.대림바스의 시리즈형 제품 ''아르노-R''. 대림바스대림바스의 첫 시리즈형 제품 ''아르노(Arno)''는 이탈리아 피렌체를 가로지르는 아르노강에서 영감을 받았다. 모든 지형에 순응하며 유연하게 흐르는 강물처럼, 다양한 환경과 니즈를 충족하는 제품 철학을 담았다.대림바스는 욕실 구성 요소를 각각 선택하고 조합했을 때 디자인과 형태의 조화가 부족해 욕실의 완성도가 떨어질 수 있다는 점에 주목했다. 욕실 주요 제품을 하나의 디자인으로 통합 기획해 조화로운 욕실을 연출할 수 있도록 했다. 향후에도 주요 제품의 디자인을 통일한 시리즈형 제품군을 다양하게 제안하며 소비자 선택의 폭을 넓힌다는 계획이다.이번 시리즈는 곡선형 콘셉트의 ''아르노-R(Round)''과 직선형 콘셉트의 ''아르노-S(Square)'' 두 제품군으로 구성된다. 아르노-R은 곡선을 중심으로 한 디자인을 적용해 부드러운 인상을 강조했다.  라운드 형태의 수전과 슬림한 핸들 라인으로 시각적 개방감을 높였고, 샤워 욕조 수전에는 회전형 토수구를 적용해 출수 전환이 쉽고 미사용 때 부딪힘을 줄였다. 양변기 물탱크 가장자리를 곡선 처리해 공간과 자연스럽게 어우러지도록 했다.대림바스의 시리즈형 제품 ''아르노-S''. 대림바스아르노-S는 직선과 엣지 디테일을 강조한 시리즈로 단정하고 현대적인 분위기의 욕실에 적합하다. 사각형 구조의 수전과 넓은 세면기는 안정적인 사용감을 제공하며, 샤워 욕조 수전에는 원터치 전환 레버를 적용해 조작 편의성을 높였다. 단순한 형태의 위생도기와 선이 돋보이는 조형미를 더해 도시적이고 정돈된 욕실을 만들어준다.아르노 시리즈의 위생도기는 기능성 측면에서도 완성도를 높였다. 양변기는 림리스 구조로 설계해 청소 사각지대를 최소화했으며, 강력한 수세력을 구현해 세척 성능을 강화했다. 슬림한 물탱크 디자인과 대·소 구분형 레버를 통해 물 사용을 효율적으로 관리할 수 있다. 수전은 크롬, 니켈, 건메탈 등 세 가지 색상으로 욕실 콘셉트와 취향에 맞춰 선택 가능하다.신동주 대림바스 디자인팀 팀장은 "아르노 시리즈는 개별 제품을 따로 고르지 않아도 통일감 있는 욕실을 구현할 수 있는 것이 가장 큰 강점"이라며 "이번 출시를 계기로 타일과 상·하부장 등 욕실 가구를 포함한 ''아르노 욕실 리모델링 패키지''도 순차적으로 선보일 예정"이라고 말했다.', NULL, '아시아경제', 'https://n.news.naver.com/mnews/article/277/0005724991', 'https://imgnews.pstatic.net/image/277/2026/02/24/0005724991_001_20260224103322461.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-24 10:32:46', 0, true, '2026-03-09 06:24:26.267874') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1139, '비너스, 모델에 트와이스 ‘지효’ 발탁…14년 만에 교체', '지효와 함께한 2026 봄 캠페인 공개"젊고 새로운 감각의 브랜드로 변신"[이데일리 김지우 기자] 국내 언더웨어 브랜드 비너스가 14년 만에 브랜드 모델을 교체하며 대대적인 리브랜딩에 나선다.비너스 모델 지효 (사진=신영와코루)신영와코루(005800)가 운영하는 비너스가 그룹 트와이스의 멤버 지효를 새로운 모델로 발탁하고, 2026년 봄 캠페인 ‘Yes, l am the VENUS’를 전개한다고 30일 밝혔다. 이번 모델 선정은 14년 만이다.비너스는 “지효가 가진 밝고 건강한 에너지와 당당한 이미지, 프로페셔널한 자세가 비너스가 추구하는 아름다움과 브랜드 방향성에 부합해 모델로 선정하게 됐다”고 밝혔다.공개된 캠페인 영상은 지효의 무대 위 화려한 모습부터 일상 속 편안한 모습까지 담아냈다. 지효가 착용한 민트색 드레스는 이번 캠페인을 위해 특별 제작된 의상으로 알려졌다. 최근 속옷과 겉옷의 경계를 허무는 스타일링 트렌드를 드러냈다는 게 회사의 설명이다.비너스 관계자는 “비너스가 쌓아온 고유한 헤리티지에 지효 특유의 밝고 건강한 에너지를 더해 브랜드의 새로운 지향점을 더 많은 분들과 소통하고자 한다”고 말했다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006210146', 'https://imgnews.pstatic.net/image/018/2026/01/30/0006210146_001_20260130104515917.jpg?type=w800', 'NEWS_CONSUMER', NULL, '2026-01-30 10:45:15', 0, true, '2026-03-09 06:24:34.266222') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1140, '3D 바디스캐너 ‘스캔바이미’ 새해 첫 팝업, 인천 스퀘어원에서 만난다', '- 1월 7일부터 20일까지 인천 스퀘어원 1층 팝업존에서 3D 바디 스캔 체험 팝업 운영- 체험 시 현금처럼 사용 가능한 2만5천 포인트 지급- 스톱워치 게임 및 인형뽑기 이벤트 등 다양한 현장 프로모션 및 경품 증정‘스캔바이미’ 인천 스퀘어원 팝업신영와코루의 3D 바디스캐너 ‘스캔바이미(SCAN BY ME)’가 1월 7일부터 20일까지 인천 스퀘어원에서 새해 첫 팝업을 운영한다고 밝혔다.360도 3D 입체 전신 뷰는 물론, 신체 18개 부위의 상세한 바디 데이터, 그리고 바디 타입부터 가슴 유형 등 평소에는 잘 몰랐던 체형 특징까지 제공하는 스캔바이미는 지난해 4월 처음 선보이며 언더웨어 업계에서는 처음 접하는 유니크한 서비스로 화제를 모았다.이번 스캔바이미 스퀘어원 팝업에서는 3D 바디 스캔 체험은 물론 팝업에서만 가능한 혜택과 이벤트도 준비됐다. 스캔바이미 체험 시 현금처럼 사용할 수 있는 최대 2만 5000포인트, 스캔바이미 론칭일을 기념해 4.25초를 맞추는 흥미진진한 스톱워치 게임, 체험 후 제품 구매 시 인형 뽑기 이벤트 참여권 증정 등 체험의 놀라움과 이벤트의 즐거움을 동시에 경험할 수 있다.스캔바이미 스퀘어원 팝업의 체험 예약은 스캔바이미 공식 인스타그램의 프로필 링크를 통해 쉽게 진행할 수 있다. 사전 예약을 우선으로 운영하지만, 예약이 없는 시간대일 경우 현장 신청을 통해 체험할 수 있다.20일까지 2주간 운영하는 스캔바이미 팝업이 종료된 후에도 체험을 하고 싶다면, 스타필드 고양 비너스플러스 매장과 비너스 명동 직매장으로 찾아가면 된다. 팝업과 달리 두 곳 모두 상시 운영 중이며, 스캔바이미 공식 인스타그램 프로필 링크에 체험 매장별 예약이 안내되어 있다.스캔바이미는 론칭 이후 지금까지 전체 체험 고객의 85%가 2030 세대일 정도로 젊은 층의 호응과 관심 속에 연일 체험 예약 매진이 발생하면서 예약 문의 역시 늘고 있다. 특히 360도로 확인할 수 있는 전신 뷰에 대한 신기함과 평상시 모르고 지나쳤던 신체 각 부위별 사이즈 등을 확인한 후 건강한 체형 관리에 대한 관심이 생겼다는 고객들의 재방문이 이어지고 있다.여성 전용 무료 체험 서비스 스캔바이미는 스캔부터 결과 리포트 확인까지 약 15~20분 만에 혼자서도 부담 없이 빠르고 간편하게 이용할 수 있다. 무엇보다 프라이빗 스캔룸에서 혼자만의 특별한 체험을 할 수 있어 인스타그램 등 SNS를 통한 공유가 확산되고 있다.‘스캔바이미’ 서비스를 담당하고 있는 신영와코루 관계자는 “퍼스널 체형 데이터를 바탕으로 쇼핑이나 속옷 사이즈 등 정확한 본인의 체형을 알고 싶다면 스캔바이미를 체험하는 것을 추천한다”면서 “상시 운영하고 있는 스타필드 고양과 명동은 물론, 더 많은 분들이 자신의 체형에 대해 잘 아실 수 있도록 스캔바이미 팝업을 통해 더 많은 곳으로 찾아갈 것”이라고 전했다.한편, 이번 스캔바이미 스퀘어원 팝업은 지하철 인천 1호선 동춘역에 위치한 인천 스퀘어원 1층 H＆M 매장 옆 팝업존에서 만날 수 있다.', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003607174', 'https://imgnews.pstatic.net/image/081/2026/01/08/0003607174_001_20260108090114614.jpg?type=w800', 'NEWS_CONSUMER', NULL, '2026-01-08 09:01:14', 0, true, '2026-03-09 06:24:34.266222') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1195, '중견련, 연말연시 소외된 이웃에 5000만원 규모 기부', '이호준(왼쪽) 한국중견기업연합회 상근부회장과 신혜영 서울사회복지공동모금회 사무처장이 지난 22일 서울시 중구 사랑의열매 회관에서 기부금 전달식을 가진 뒤 기념 촬영하고 있다. 한국중견기업연합회 제공한국중견기업연합회(중견련)는 지난 22일 회원사와 함께 사회복지공동모금회(사랑의열매)에 5000만원 규모의 ‘2025년 나눔 세상, 좋은 이웃’ 중견기업 기부금과 물품을 전달했다고 23일 밝혔다. 중견련은 삼구아이앤씨, 샘표식품, 솔루엠, 태양금속공업, 보미건설, 희림종합건축사사무소, 대림통상, 모나용평, 에프에스티, 선익시스템, SIMPAC 등 11개 회원사와 함께 기부금을 조성했다.', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003603405', 'https://imgnews.pstatic.net/image/081/2025/12/23/0003603405_001_20251223181309248.jpg?type=w800', 'NEWS_ETC', NULL, '2025-12-23 18:13:09', 0, true, '2026-03-09 06:27:21.216925') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1141, '‘110억 증식’ 이혜훈, 뭘로 돈벌었나 보니…‘이 주식’ 보유', '5일 인사청문회 준비 사무실로 출근하는 이혜훈 기획예산처 장관 후보자. 연합뉴스기획예산처 장관 인사청문요청안 자료갑질·폭언 논란에 휩싸인 이혜훈 기획예산처 장관 후보자가 175억6950만원에 달하는 재산을 신고하면서 논란이 되고 있다. 직전 2016년 신고액 대비 110억 원가량 급증한 규모다.5일 국회에 제출된 이혜훈 후보자의 인사청문요청안에 따르면 이 후보자는 본인과 배우자, 자녀 명의로 175억6952만 원의 재산을 신고했다. 2016년 8월 국회공직자윤리위원회가 공개한 20대 국회 신규 재산등록 내역에 따르면, 이 후보자는 총 65억2140만 원의 재산을 신고한 바 있다. 약 10년 만에 재산이 110억4810만 원 불어난 것이다. 배우자와 공동 명의로 보유한 서울 서초구 아파트(37억954만 원), 본인 명의 세종시 아파트 전세권(1억7330만 원)과 서울 중구 빌딩 전세권(1000만 원) 등을 신고했다.이 후보자 본인과 가족 명의 재산은 대부분 주식이었다. 이 후보자는 반도체 장비를 제조하는 비상장 회사인 ‘케이에스엠’(12억750만 원) 등 14억4593만 원을 신고했다. 이 후보자의 배우자도 케이에스엠(33억1478만 원) 등 주식으로만 주식 71억7384만원어치를 신고했다. 배우자 주식 보유 내역에는 한국씰마스타, 신영와코루 1200주, 삼성전자 100주, 엔케이맥스 593주 등이 포함됐다.특히 이 후보자와 배우자, 아들들 등 일가가 보유한 케이에스엠 주식만 총 76억3841만 원으로 나타났다.또한 이 후보자 본인 명의로는 예금 4758만 원, 배우자 명의로 예금 4억6165만 원이 신고됐다. 이 후보자의 배우자는 2020년식 포르쉐 파나메라4, 2019년식 기아 K9, 2018년식 도요타 캠리 등 차량 3대를 보유 중인 것으로 나타났다.이혜훈, 10년 새 재산 ‘110억 증식’…뭘로 돈 벌었나 봤더니 [문화일보]', NULL, '문화일보', 'https://n.news.naver.com/mnews/article/021/0002761563', 'https://imgnews.pstatic.net/image/021/2026/01/05/0002761563_001_20260105173116145.jpg?type=w800', 'NEWS_CONSUMER', NULL, '2026-01-05 17:31:13', 0, true, '2026-03-09 06:24:34.266222') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1142, '풍산, 탄약매각 현실화시 매수자 많을 것…''1.5조''는 불명확-KB', 'KB증권이 풍산에 대해 탄약 사업부문 매각이 현실화할 경우 다수의 매수희망자가 발생할 것으로 내다봤다. 다만 시중에 거론된 예상 매각가 1조5000억원에 대해선 신중론을 제기했다.최용현 KB증권 연구원은 지난 6일 발간한 보고서에서 "실제로 탄약부문 매각을 진행한다면 매수자는 많을 것"이라며 "글로벌 시장에서 탄약 수요가 높고, 규제로 인해 국내 경쟁사가 없다"고 밝혔다.최 연구원은 "독일 라인메탈은 장약·탄약을 함께 생산하며 시너지를 내고 있는 점, 국내 주요 전차·자주포에 풍산의 탄약이 활용되는 점을 감안하면 자금여유가 있는 국내 방산기업은 긍정적으로 검토할 가능성이 있을 것"이라고 했다.앞서 풍산 탄약부문 매각설을 제기한 일부 언론에선 예상 매각가격을 1조5000억원으로 거론한 바 있다. 전날 풍산은 ''미확정'', 풍산홀딩스는 ''사실무근''으로 각각 공시했다.최 연구원은 "기준이 탄약부문 전체 지분인지, 풍산홀딩스가 보유한 풍산의 지분 38%에 대한 탄약부문 지분인지 불명확하다"며 "후자일 경우 탄약부문의 가치가 3조9000억원"이라고 밝혔다.또 "탄약 부문 EV/EBITDA는 전자라면 5배, 후자라면 13배로 평가된다"며 "국내 주요 방산업체 밸류에이션은 올해 예상실적 기준 EV/EBITDA가 20배로, 풍산은 같은 기준으로 8.9배에 거래 중"이라고 했다.매각배경에 대해선 "상속과 관련 있다고 판단된다"고 밝혔다.  국내 방위사업법상 방산업체 경영권은 한국 국적자만 확보할 수 있지만, 풍산 최대주주의 장남은 미국 국적을 보유해 상속이 어렵다는 설명이다.최 연구원은 "최대주주 입장에선 방산 호황기에 탄약부문을 높은 가치로 매각하는 게 유리하다"고 밝혔다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005326197', 'https://imgnews.pstatic.net/image/008/2026/03/06/0005326197_001_20260306085818672.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-06 08:58:01', 0, true, '2026-03-09 06:24:41.566472') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1143, '풍산, 방산·구리가공 부문 인적분할 나설듯', '사측 "사업구조 개편 검토"소액주주가치 보호 위해물적분할 가능성은 희박기업가치 재평가도 기대방산부문 매각길 열릴수도풍산이 사업 양대축인 신동(구리 가공)과 방산 사업을 분리하는 기업 구조 재편 방안을 검토하는 것으로 알려졌다. 풍산 지주사인 풍산홀딩스는 풍산 지분을 파는 대신 풍산의 사업 구조를 개편해 향후 승계 작업에 나설 것으로 보인다.5일 풍산은 "기업가치 및 주주가치 제고를 위해 사업 구조 개편 등 다양한 방안을 검토 중"이라고 공시했다. 같은 날 최대주주인 풍산홀딩스는 "풍산 지분 매각 계획이 없다"고 공시했다. 3월 5일자 A21면 보도투자은행(IB) 업계에서는 이 같은 공시에 대해 풍산이 신동과 방산 사업을 분리하는 기업분할 가능성이 높아졌다고 해석했다.풍산은 탄약 등 군수품을 생산하는 방산 사업과 구리 가공 중심의 신동 사업을 동시에 영위하고 있다. 만약 매각을 검토한다면 방산 사업 가치가 상승한 현시점이 가장 유리한 시기라는 해석이다. 풍산의 매출 구조는 신동 사업이 약 70%, 방산 사업이 약 30%다. 매출은 신동 사업이 크지만, 수익성과 성장성은 방산 사업이 앞선다. 특히 방산 부문은 최근 글로벌 군비 확장 흐름 속에서 155㎜ 포탄 등 대구경 탄약 수요가 늘며 성장성이 부각되고 있다.분할 방식은 기존 풍산 주주에게 신동 사업회사와 방산 사업회사 지분을 각각 나눠주는 인적분할 방식이 유력하다.방산 사업회사를 풍산 100% 자회사로 만드는 물적분할 방식은 주주 반발이 거셀 수밖에 없기 때문이다. 현 정부 들어 소액주주 보호 정책이 강화되고 있어 ''알짜'' 사업 부문인 방산을 물적분할하는 방안은 사실상 실행이 불가능하다는 평가를 받는다. 풍산은 2022년에도 방산 사업 부문 물적분할을 추진하다가 주주들의 반발로 철회한 전례가 있다.현재 삼일회계법인이 관련 자문을 맡아 사업 구조 재편 방안을 검토 중인 것으로 전해진다.IB 업계에서는 방산 인적분할이 완료된 뒤 매각 작업이 본격화될 가능성을 열어두고 있다. 현재 잠재 인수 후보로는 LIG그룹, HD현대, 현대로템 등 방산 산업을 영위하는 국내 대기업들이 거론된다. 실제 매각이 성사되는 데 관건 중 하나는 입법 막바지 단계에 들어간 의무공개매수 조항이다. 풍산의 방산 사업 부문을 인수하려는 곳은 풍산그룹의 보유 지분 38%뿐만 아니라 다른 소액주주 지분을 합쳐 최소 50% 이상까지 공개매수해야 한다. 비용 부담이 커질 수밖에 없는 구조란 뜻이다. 풍산은 최근 시가총액 3조원 안팎을 넘나들고 있다.방산 사업 인적분할은 매각 가능성을 논외로 하더라도 기업가치 제고에 긍정적이라는 장점을 지닌다.최근 시장에서 방산 사업의 경우 15~20배의 멀티플을 적용받고 있다. 반면 신동 사업은 경기 민감도가 높고 성장성이 낮아 멀티플이 5~8배 수준에 불과하다. 이 둘을 분리할 경우 시장에서 밸류에이션이 재평가될 것이라는 전망이 나온다.풍산의 사업 구조 재편 가능성은 지배 구조 및 경영 승계 문제와도 맞물려 거론된다. 류진 풍산그룹 회장의 장남 류성곤 씨는 미국 국적을 보유하고 있는 것으로 알려져 있다. 방위산업체의 경우 방산법 35조 3항에 따라 외국인이 지분을 취득하거나 주요 임원 선임을 받기 위해서는 국방부 장관과 사전 협의를 거치고 산업통상부 장관의 승인까지 받아야 한다.외국인의 경영권 보유에 제약이 있는 만큼 방산 사업을 분리하는 방식의 지배 구조 재편 가능성이 그간 시장에서 꾸준히 언급돼 왔다.[남준우 기자 / 박승주 기자]', NULL, '매일경제', 'https://n.news.naver.com/mnews/article/009/0005645856', 'https://imgnews.pstatic.net/image/009/2026/03/05/0005645856_001_20260306101106155.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-05 17:33:48', 0, true, '2026-03-09 06:24:41.566472') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1144, '방산업 매각설 나온 풍산... ‘알짜’ 팔아 아들 이끄는 美 구리 회사 지원할까', '회사 영업익 75% 차지하는 방산업반면 美 법인은 누적 적자 3500억... 추가 투자 필요풍산이 생산하는 탄약 종류 /풍산 홈페이지 캡처이 기사는 2026년 3월 5일 17시 01분 조선비즈 머니무브(MM) 사이트에 표출됐습니다.풍산이 방산 부문을 매각한다는 설이 제기됐다. 최근 방산업이 주목받으면서 기업가치가 급등한 상태지만, 방산 부문이 회사 전체 영업이익의 대부분을 차지하는 만큼 매각설이 왜 나왔는지에 대한 배경에 관심이 쏠린다.방산 관련 업계에서는 이미 수개월 전부터 풍산의 매각설이 돌았다고 한다. 미국 국적인 류진 회장의 아들이 현행 법령상 방산 사업을 영위하는 데 제약이 있고 승계 의지도 크지 않아 류 회장이 오래전부터 방산 부문 매각을 진지하게 검토했다는 것이다.업계 일각에서는 이번 풍산의 방산 부문 매각설을 미국 구리 생산 법인의 실적 부진과 연결해 해석하기도 한다. 국내 방산 사업은 승계가 쉽지 않은 만큼, 차라리 지금 몸값이 최고조에 달했을 때 팔고 그 매각대금으로 미 법인을 지원하는 선택을 내린 것 아니냐는 분석이다.美 거주 류 회장 아들, 한국 정착 의지 약해5일 투자은행(IB) 업계에 따르면, 풍산그룹은 방산 부문을 매각하기 위해 복수의 기업과 물밑 접촉한 것으로 알려졌다. 매각가는 약 1조5000억원 수준으로 추정되며, 잠재 인수 후보로 한화에어로스페이스, LIG넥스원 등이 거론된다.현재 유가증권시장에서 풍산의 시가총액은 3조3000억원 수준이다. 지분 38%를 보유한 풍산홀딩스가 최대주주다. 풍산홀딩스의 최대주주는 류진 회장(37.61%)이며 배우자와 자녀 등 특수관계인 지분까지 더하면 총 48.76%가 된다. 즉 ‘류 회장→풍산홀딩스→풍산’으로 이어지는 지배 구조를 갖추고 있다.방산 부문은 풍산 전체 실적을 견인하는 핵심 사업이다. 매출액은 구리 부문이 70%, 방산이 30%를 차지하고 있으나, 영업이익은 반대다. 방산이 75%, 구리가 약 25%를 담당하고 있다. 겉으로는 구리 회사처럼 보이지만 돈은 방산이 버는 셈이다.풍산의 방산 부문 매각설이 나온 배경으로는 먼저 후계 구도 문제가 거론된다. 류 회장의 장남 로이스 류(한국명 류성곤)씨는 만 18세였던 2010년 미국 시민권을 취득했다. 현행법상 외국인은 방산 사업을 경영하거나 물려받기 쉽지 않다.외국인투자촉진법 제6조에 따르면 외국인이 기존 방산업체의 주식을 취득해 임원이 돼서 실질적 지배력을 행사하려면 반드시 사전에 산업통상부 장관의 허가를 받아야 한다. 산업부 장관이 방위사업청장과 협의해야 한다. 또 방위사업법 제35조는 방산업체 경영권의 실질적인 변화가 예상되는 경우 산업부 장관의 승인을 받아야 한다고 규정하고 있다.그 외에도 방산업체의 대표이사나 주요 경영진이 되려면 국군방첩사령부(옛 기무사) 등으로부터 신원조사를 받고 비밀취급인가를 받아야 하는데, 외국인에게는 원칙적으로 비밀취급인가가 나오지 않는다.류씨 또한 방산업에 대한 관심이 크지 않은 것으로 알려지고 있다. 류씨는 현재 미국 구리 부문 계열사 PMX인더스트리에서 부사장으로 일하고 있다.업계 일각에서는 PMX인더스트리의 부실이 방산 사업 매각의 동기로 작용했을 것이라는 해석도 나온다. PMX인더스트리는 풍산이 미국 관세 부담을 줄이기 위해 1989년 미 아이오와주에 설립한 법인이다.PMX인더스트리는 연간 12만톤 규모의 구리·구리합금 생산 능력을 바탕으로 한때 미국 내 3대 신동압연 업체로 주목받기도 했으나, 만성 적자에 시달리고 있다. 2008년 글로벌 금융위기 때는 1000억원 넘는 순손실을 기록하며 자본잠식에 빠졌고, 2022년부터 지난해까지 4년 연속 순손실 상태에서 못 벗어나고 있다. 누적 적자는 3468억원에 달한다.이에 풍산 본사는 PMX인더스트리가 외부에서 차입할 때 담보를 서주는 지급보증액을 2293억원까지 늘린 상태다. 사실상 본사의 지원 없이 법인 유지가 어려운 셈이다. 방산 매각 대금이 PMX인더스트리의 경쟁력 키우기에 활용될 수 있다는 예상이 나오는 배경이다.한화 인수시 독점 리스크, LIG는 인수할 이유 별로 없어다만 매각이 본격 궤도에 올라 성사될 가능성에 대해서는 물음표가 붙는다.가장 근본적인 문제는 인수 주체가 극히 제한된다는 점이다. 풍산은 5.56mm 소구경탄부터 155mm 곡사포탄까지 한국군이 사용하는 주요 탄약을 일관생산체제(제품의 개발 및 설계부터 제조·검품·출하까지 유기적으로 연결된 체제)로 공급하는 사실상 유일한 회사다. 외국 자본뿐 아니라 사모펀드의 인수는 사실상 불가능하다. 두산모트롤이 사모펀드에 팔린 전례가 있지만, 이는 당시 두산그룹이 재무 위기에 처해 있었다는 특수성이 반영된 결과였다.국내 기업으로 범위를 좁히면 이 정도 규모의 딜을 감당할 수 있는 곳은 한화그룹, 현대차그룹(현대로템), LIG그룹 등 몇 개 없다는 평가가 나온다. 방산업체의 경영권을 인수하려면 산업부 장관의 승인을 받아야 하는 만큼, 기존에 방산업을 영위하지 않던 기업이 새롭게 업에 진출하는 건 어렵다.그런데 한화는 탄약 시장에서 이미 풍산과 직접 경쟁하고 있어 풍산의 방산사업 인수를 추진할 시 독점 논란 때문에 정부가 허용하지 않을 가능성이 크다. LIG넥스원의 경우 이미 2010년 풍산과 합작사 ‘LIG풍산프로테크’를 만들어서 운영 중이기 때문에 굳이 풍산의 방산사업을 인수할 유인이 적다.업계 관계자는 “방산 기업 매각은 국방부와 방위사업청의 승인이 필수적이어서 사실상 정부가 인수자의 자격을 결정하는 구조”라며 “류 회장이 원하는 조건에 회사를 사겠다는 원매자가 나와도, 정부의 승인 여부가 딜의 성패를 가를 것”이라고 말했다.', NULL, '조선비즈', 'https://n.news.naver.com/mnews/article/366/0001146157', 'https://imgnews.pstatic.net/image/366/2026/03/05/0001146157_001_20260305172326000.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-05 17:23:26', 0, true, '2026-03-09 06:24:41.566472') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1145, '원림, 지난해 영업이익 44억…전년比 155.3%↑', '[서울=뉴시스] 김경택 기자 = 원림은 지난해 연결 영업이익이 44억원을 기록해 전년 대비 155.3% 증가했다고 23일 공시했다.같은 기간 매출액과 순이익은 897억원, 52억원으로 각각 8.9%, 6.8% 늘었다.', NULL, '뉴시스', 'https://n.news.naver.com/mnews/article/003/0013782663', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2026-02-23 14:33:52', 0, true, '2026-03-09 06:24:47.909592') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1146, '원림, 지난해 영업익 44억…전년비 155.3% ↑', '[헤럴드경제=증권부] 원림은 지난해 연결기준 영업이익이 44억2555만원으로 전년대비 155.3% 증가했다고 23일 공시했다.같은 기간 매출액은 896억8189만원으로 8.9% 늘어난 것으로 나타났다.당기순이익은 51억6562만원으로 6.8% 증가한 것으로 집계됐다.', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002603703', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2026-02-23 14:19:06', 0, true, '2026-03-09 06:24:47.909592') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1147, '김남호 DB그룹 명예회장 "부친에 맞설 생각 없어"…불화설 진화', '김남호 DB그룹 명예회장. 사진=한경DBDB그룹 오너 2세인 김남호 명예회장이 “창업자인 부친에 맞설 생각을 한 적은 없다”며 최근 불거진 경영권 분쟁 논란에 대해 일축했다.김 명예회장은 9일 입장문을 통해 “최근 저와 부친의 관계에 대해 잘못 알려지거나 과장된 이야기들로 많은 분께 심려를 끼쳤다”며 이같이 밝혔다. 이어 “회사 경영과 관련해 부친과 일부 이견이 있었던 적은 있지만 그렇다고 해서 창업자이신 부친께 맞설 생각을 한 적은 없으며, 앞으로도 그럴 일은 없을 것”이라고 강조했다.김준기 DB그룹 창업회장의 장남인 김 명예회장은 지난해 경영 일선에서 물러나 회장에서 명예회장으로 추대됐다. 동시에 전문경영인이자 김 창업회장의 측근인 이수광 전 DB손해보험 사장이 그룹 회장이 되면서 부자간 경영권 분쟁이 있었던 것 아니냐는 의혹이 불거졌다.김 명예회장은 “DB는 창업자를 중심으로 한 안정적인 경영권을 바탕으로 성장해 온 기업이며, 대주주와 전문경영인이 번갈아 가며 그룹 회장직을 맡는 새로운 전통을 만들어가고 있다”며 “불필요한 오해가 발생한 것은 모두 제 탓이라고 생각하며 이 점 깊이 반성하고 있다”고 했다.또한 “대주주 가문의 일원으로 앞으로도 그룹 발전을 위해 제 역할을 다하겠다는 점을 다시 한번 강조한다”며 “저와 DB그룹을 향한 불필요한 오해가 종식되기를 바란다”고 덧붙였다.', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005259868', 'https://imgnews.pstatic.net/image/015/2026/03/09/0005259868_001_20260309151217020.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 15:06:15', 0, true, '2026-03-09 06:24:54.000168') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1148, '현대차·기아, 모바일 로봇 ‘모베드’ 상용화...로봇 얼라이언스 출범', 'AW2026 전시장 내 현대차·기아 로보틱스랩 부스에서 관람객들이 모베드 콘셉트 모델을 둘러보는 모습. 사진ㅣ현대차·기아[스포츠서울 | 위수정 기자] 현대자동차·기아가 모바일 로봇 플랫폼 ‘모베드(MobED)’ 상용화에 나서며 로봇 솔루션 생태계 구축에 속도를 낸다.현대차·기아는 4일 서울 코엑스에서 열린 ‘2026 스마트공장·자동화산업전(AW2026)’에서 ‘모베드 얼라이언스(MobED Alliance)’ 출범식을 열고 모베드의 국내 상용화를 본격 시작했다고 밝혔다.이날 행사에는 현대차·기아 로보틱스랩을 비롯해 현대트랜시스, SL 등 주요 부품사 관계자와 LS티라유텍, 가온로보틱스 등 로봇 솔루션 기업, 한국AI·로봇산업협회 등 유관 기관 관계자들이 참석했다.모베드 얼라이언스는 로봇 하드웨어 판매에 그치지 않고 산업 현장에서 바로 활용 가능한 맞춤형 로봇 솔루션을 제공하기 위해 마련된 협력 체계다. 현대차·기아 로보틱스랩과 국내 부품사, 로봇 솔루션 기업, 관련 기관이 참여하는 다자간 협력 구조로 운영된다.현대차·기아가 AW2026에서 국내 최초 공개한 ‘모베드(MobED)’ 양산형 모델과 탑 모듈 결합 콘셉트 모델. (뒷열 왼쪽부터) 모베드 골프, 모베드 프로, 모베드 딜리버리, 모베드 언로딩, 모베드 로딩 (앞열 가운데) 모베드 베이직. 사진ㅣ현대차·기아모베드는 현대차·기아가 개발한 신개념 소형 모바일 로봇 플랫폼으로, 4개의 독립 구동 DnL(Drive-and-Lift) 메커니즘 기반 편심 구조를 적용해 다양한 지형에서도 안정적인 주행 성능을 확보한 것이 특징이다.특히 상단에 다양한 ‘탑 모듈(Top Module)’을 장착할 수 있는 확장성을 갖춰 물류 배송, 순찰용 드론 스테이션, 광고 사이니지 등 여러 산업 분야에서 활용될 수 있다.현대차·기아는 이러한 플랫폼 확장성을 기반으로 단순한 로봇 판매가 아닌 파트너 기업들과 함께 완성형 로봇 솔루션을 공급하는 생태계 중심 전략을 추진한다는 계획이다.얼라이언스 참여 기업 가운데 현대트랜시스와 SL 등 10개 부품사는 센서, 전장, 배터리 등 핵심 부품 공급을 맡고, LS티라유텍과 가온로보틱스 등 5개 로봇 솔루션 기업은 산업 맞춤형 서비스 개발과 현장 구축을 담당한다. 또한 한국AI·로봇산업협회 등 관련 기관은 실증 및 도입 환경 조성을 지원한다.로봇 솔루션 기업들은 물류 배송, 순찰용 드론 스테이션, 광고 사이니지 등 산업 맞춤형 ‘탑 모듈’ 10종을 개발해 고객에게 제공할 예정이다.AW2026에서 열린 모베드 얼라이언스 출범식에서 기념사진을 촬영하는 모습. (왼쪽부터) 아르비젼 손영숙 대표, 현대트랜시스 김진우 상무, 위고로보틱스 박세일 대표, 성우하이텍 이동주 상무, 고성엔지니어링 최창신 대표, 모베이스 송기갑 상무, LS티라유텍 김정하 대표, 서연이화 강상욱 상무, 현대차·기아 로보틱스랩 현동진 상무, SL 정문호 대표, 한국AI·로봇산업협회 김재환 상임이사, PHA 홍성율 전무, 가온로보틱스 이진성 대표, 성주음향 최선용 대표, 주식회사 로아스 주용 대표, 현대성우 윤형석 대표, BH-EVS 김진용 대표. 사진ㅣ현대차·기아현대차·기아는 이번 전시를 통해 모베드 양산형 모델을 국내 최초로 공개하고, 약 180㎡ 규모의 체험 부스를 운영해 기술력을 선보였다. 부스에는 배수로, 경사로, 굴곡 지형 등을 구현해 모베드의 험지 주행 능력과 자율주행 성능을 직접 확인할 수 있도록 했다.현대차·기아 로보틱스랩장 현동진 상무는 “글로벌 무대에서 혁신성을 인정받은 모베드가 이번 얼라이언스를 통해 한 단계 진화한 로봇 솔루션으로 발전하게 됐다”며 “핵심 파트너사들과 함께 국내 로봇 산업 경쟁력을 높이고 피지컬 AI 생태계 확장에 기여하겠다”고 말했다.한편 모베드는 지난 1월 세계 최대 가전·IT 전시회 ‘CES 2026’에서 로보틱스 부문 최고혁신상을 수상하며 기술력을 인정받은 바 있다. wsj0114@sportsseoul.com', NULL, '스포츠서울', 'https://n.news.naver.com/mnews/article/468/0001221641', 'https://imgnews.pstatic.net/image/468/2026/03/04/0001221641_001_20260304154408784.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-03-04 15:44:08', 0, true, '2026-03-09 06:24:58.497579') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1149, '현대차그룹, 車 넘어 로봇·AI 정조준…‘피지컬 AI 기업’ 전환 시동', '새만금에 9조 투자 미래산업 집적34만평 부지에 9조 투입…2027년 착공GPU 5만장급 데이터센터 5.8조 투자‘HTWO’ 앞세워 수소 전 밸류체인 구축車공장 시대 마감…미래기술 중심 투자 본격화배경훈(오른쪽부터) 부총리 겸 과기부 장관, 이재명 대통령, 정의선 현대차그룹 회장, 김윤덕 국토부 장관이 27일 전북 군산새만금컨벤션센터에서 열린 새만금 로봇·수소·AI 시티 투자협약식에서 국민의례를 하고 있다. [연합][헤럴드경제=정경수·권제인 기자] ‘피지컬 AI(인공지능)’ 기업으로 도약을 선언한 현대자동차그룹이 전북 새만금에 미래 산업 혁신거점을 조성한다. 오는 2026년부터 총 9조원을 단계적으로 투입해 ‘로봇·AI·수소 중심 미래기술 기업’으로의 전환을 본격화한다는 구상이다.27일 현대차그룹이 발표한 약 34만평에 달하는 새만금 혁신거점은 내년 AI 데이터센터와 태양광 발전시설 착공을 시작으로 본격 추진된다. 수전해 플랜트도 같은 해 첫 삽을 떠 2029년 1차 준공 후 단계적으로 확대될 예정이며, 로봇 제조 클러스터는 2028년 착공해 2029년 완공을 목표로 한다.이번 투자는 피지컬 AI 비전을 실행 국면으로 전환하는 계기다. 미국에 이어 한국에서도 관련 인프라 구축과 사업화를 본격화하며 글로벌 양축 체제를 갖추게 됐다. 중장기적으로 현대차가 피지컬 AI 기업으로 체질을 전환하는 분기점이 될 전망이다.▶AI 기업으로…데이터센터가 승부처=이번 프로젝트의 핵심은 피지컬 AI 구현을 위한 초대형 인프라 구축이다. 현대차그룹은 5조8000억원을 투입해 GPU 5만장급 연산 능력을 갖춘 AI 데이터센터를 새만금에 건립한다. 자율주행·로보틱스·스마트팩토리 개발에 필요한 방대한 실주행·제조 데이터를 학습·검증하는 ‘두뇌’ 역할을 맡는다.현대차가 지난달 CES에서 완성차 업체가 아닌 피지컬 AI 기업을 선언한 만큼, 대규모 연산 인프라는 필수에 가깝다. 자율주행과 로봇은 영상 기반 학습으로 데이터 처리량이 폭증해 초대형 서버 인프라 없이는 사업 확장이 어렵다. 그룹은 이를 위해 엔비디아와 계약을 맺고 최신 블랙웰 GPU 5만장을 도입하기로 했다.연내 미국 RMAC(로봇 메타플랜트 응용센터)구축과 SDV(소프트웨어 중심 차량) 양산이 시작되면 실주행·공정 데이터가 급증할 전망이다. SK·삼성 등도 AI 데이터센터 경쟁에 뛰어든 가운데, 연산 능력이 곧 산업 경쟁력이 되는 구조가 굳어지고 있다. 데이터센터는 초기 투자뿐 아니라 3~5년 주기의 칩 교체가 필요한 장기전이라는 점에서 지속 투자가 불가피하다.▶AI센터 전력, 태양광으로 푼다=문제는 전력이다. 엔비디아로부터 도입할 700W급 GPU 5만장은 단순 계산만으로도 약 35MW의 전력을 소모한다. 여기에 서버 주변장치와 냉각 설비 등을 포함하면 데이터센터 전체 전력 수요는 100MW 수준에 이를 것으로 추산된다. 이는 중소 도시 하나의 기저전력 부하에 맞먹는 규모다.새만금이 후보지로 부상한 배경도 여기에 있다. 이 지역에는 2.8GW 규모의 태양광 단지가 조성 중으로, 대규모 전력을 비교적 빠르게 확보할 수 있는 여건을 갖추고 있다.현대차그룹은 안정적 전력 확보를 위해 1조3000억원을 투입해 GW급 태양광 발전 사업을 추진한다. 2021년부터 새만금 육상태양광 1구역 운영에 참여해온 경험을 바탕으로, 2035년까지 발전 규모를 단계적으로 확대할 계획이다. 생산된 전력은 AI 데이터센터와 수전해 플랜트에 공급돼 대규모 연산·에너지 집약형 설비의 운영 기반을 뒷받침한다.서남권 수소 AI 신도시 육성▶수소차 1위 현대차, 인프라까지 선점=수소 분야에서도 대규모 투자가 이뤄진다. 현대차그룹은 1조원을 투입해 200MW 규모의 수전해 플랜트를 새만금에 건설한다. 풍부한 재생에너지를 활용해 청정 수소를 생산하고, 이를 트램·버스·수요응답형 교통서비스(DRT) 등 다양한 모빌리티에 공급한다는 계획이다. 장기적으로는 국내에 총 1GW 규모의 수전해 설비를 구축해 수소 생산 역량을 단계적으로 확대한다.4000억원을 들여 조성하는 ‘AI 수소 시티’에서는 인근 플랜트에서 생산한 수소를 지역 내에서 소비하는 지산지소형 에너지 순환 체계도 도입한다. 울산 수소연료전지공장 역시 내년 준공을 목표로 추진 중이다.이 같은 투자는 현대차그룹이 수소를 미래 에너지 전략의 핵심 축으로 보고 있기 때문이다. 현대차는 현재 글로벌 수소차 시장 점유율 1위 사업자다. 단순한 완성차 판매를 넘어 수소 생산부터 저장·운송·충전·활용까지 전 밸류체인을 아우르는 현대차 수소 브랜드 ‘HTWO’를 앞세워 생태계 확장에 속도를 내고 있다.업계에서는 전기차 중심의 전동화 전략이 승용 부문에서 빠르게 확산되고 있지만, 상용차·물류·발전 등 대규모 에너지 수요 분야에서는 수소의 역할이 커질 것으로 보고 있다.▶로봇 파운드리 구축…협력사까지 확장=로봇 산업 육성도 본격화한다. 현대차그룹은 4000억원을 투입해 연간 3만대 규모의 로봇 제조 및 부품 클러스터를 새만금에 조성한다. 이곳에는 로봇 완성품 생산라인과 함께 파운드리(위탁생산) 기능을 갖춘 공장이 들어선다. 제조 역량이 부족한 중소기업의 로봇 제품을 대신 생산하는 플랫폼 역할까지 수행하겠다는 구상이다.특히 현대차 로보틱스랩의 차세대 모빌리티 로봇 플랫폼 ‘모베드’를 비롯해 엑스블 숄더, 달이 딜리버리 등 주요 로봇 제품들이 이곳에서 생산될 전망이다. 현재 모베드는 에스엘(SL)을 통해 위탁생산되고 있다. 현대위아의 자율주행 물류로봇, 주차로봇, 협동로봇 역시 생산 대상에 포함될 가능성이 크다. 반면 보스턴다이나믹스의 휴머노이드 ‘아틀라스’는 미국에서 생산될 예정이다.새만금 클러스터는 국내 로보틱스 기술을 본격 양산 체제로 전환하는 첫 거점이 된다. 자동차 제조에서 축적한 대량 생산 노하우를 로봇 산업에 이식해, 핵심 부품의 국산화율을 높이는 계기가 될 전망이다.장재훈 현대차그룹 부회장이 27일 전북 군산새만금컨벤션센터에서 이재명 대통령이 참석한 가운데 열린 새만금 로봇·수소·AI 시티 투자협약식에서 새만금 미래 전략사업 투자계획을 발표하고 있다. [연합]▶AI 인프라로…투자 축 이동=현대차그룹의 투자 방향도 변화하고 있다. 지난해를 기점으로 국내 자동차 생산 공장에 대한 대규모 투자는 사실상 마무리 단계에 접어들었고, 올해부터는 AI 인프라와 차세대 기술 분야에 무게를 두는 구조로 전환하고 있다.이는 현대차그룹이 지난해 11월 발표한 국내 투자 계획을 구체화한 조치이기도 하다. 그룹은 올해부터 2030년까지 5년간 국내에 총 125조2000억원을 투자하겠다고 밝힌 바 있다. 이는 직전 5개년 대비 40% 늘어난 사상 최대 규모다.장재훈 현대차그룹 부회장은 “새만금에서 시작되는 차세대 산업 패러다임이 대한민국 미래를 설계하는 전환점이 될 것”이라며 “세계 최고 수준의 제조 역량과 로봇·AI·수소 기술을 두루 갖춘 현대차그룹은 첨단 산업 생태계 구축에 나설 준비가 됐다”고 강조했다.', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002606250', 'https://imgnews.pstatic.net/image/016/2026/02/27/0002606250_001_20260227115015985.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-02-27 11:33:08', 0, true, '2026-03-09 06:24:58.497579') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1150, '코스피 6,000 시대…AI·로봇·금융 질주에 대구 상장사 시총 급등', '이스페타시스 시총 8조5천400억원…1년새 5배 급등이수페타시스 대구 달성군 생산 공장 전경. 이수페타시스 제공코스피가 6,000선을 돌파한 가운데 대구 기업들도 인공지능(AI)·로봇·금융 등 각 분야를 주도하며 시가총액 상승을 견인하고 있다.25일 한국거래소에 따르면 대구 시가총액 1위 기업으로 자리매김한 이수페타시스의 시가총액은 8조5천400억원으로, 2024년 초(1조7천200억 원) 대비 5배 가까이 급등했다.이수페타시스는 초고다층 인쇄회로기판(MLB) 분야에서 독보적인 기술력을 보유하고 있다. 이를 기반으로 엔비디아, 구글, 인텔 등 글로벌 빅테크 기업을 고객사로 확보하며 글로벌 AI 인프라 밸류체인(가치사슬)의 핵심으로 자리매김했다.AI 데이터센터 확장과 이에 필수적인 GPU(그래픽 처리 장치) 수요가 여전히 상승세를 보이고 있다는 점을 고려하면 이수페타시스는 올해도 성장을 이어갈 가능성이 높다. 현재 대구에 신규 공장 증성을 통해 생산량을 확대하고 있어 향후 전망도 긍정적이라는 평가가 지배적이다.자동차 부품 기업에서 로보틱스 분야로 영역을 넓히고 있는 에스엘의 주가도 가파른 상승세를 보이고 있다. 이날 에스엘의 시가총액은 3조3천500억 원으로 지난 2024년 초(1조4천억 원)에 비해 2배 이상 뛰었다. 최근 1년간 주가는 105.11% 증가한 것으로 집계됐다.자동차 헤드램프를 주력으로 하는 에스엘은 최근 현대차그룹의 로보틱스 분야 핵심 협력사로 재평가 받고 있다. 남주신 DB증권 연구원은 에스엘에 대해 "보스턴 다이내믹스(현대차 계열사)의 4족 보행 로봇은 물론 로보틱스랩 모베드 플랫폼에 부품을 공급 중"이라며 "일부 프로젝트에서는 로봇 위탁생산(EMS) 역할까지 수행하며 기계 모듈 제조 역량을 활용한 로봇 밸류체인 진입이 예상된다"고 분석했다.iM금융지주 시총도 2024년 1조3천836억 원에서 25일 종가 기준 3조2천700억 원을 기록했다. 지주사 출범, 시중은행 전환 이후 견조한 상승세를 지속하며 투자자들의 관심을 끌고 있다.iM금융지주의 주가 상승은 은행주의 주주환원 확대 기조 강화, 기업 실적 상승에 대한 기대감이 작용했다. 또 내부적으로도 실적 개선과 적극적인 자사주 매입 및 소각, 배당 확대 정책 등 다각적인 노력이 긍정 요소로 작용했다는 분석이다.김보근 대구상공회의소 경제조사부장은 "신산업 체질 개선과 개별 기업의 노력으로 상장사 시가총액도 증가하고 있다. 지금의 긍정적인 흐름이 지속될 수 있도록 성장 지원 정책도 병행될 필요가 있다"고 짚었다.', NULL, '매일신문', 'https://n.news.naver.com/mnews/article/088/0000998436', 'https://imgnews.pstatic.net/image/088/2026/02/25/0000998436_001_20260225195708678.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-02-25 16:18:15', 0, true, '2026-03-09 06:24:58.497579') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1152, '이번엔 김승연 "어서 타!" 밈…이란 사태에 방산주 ''급등''', '김승연 한화그룹 회장이 한화 방산주들 급등장에 밈(meme)으로 합성됐다. [사진 온라인 커뮤니티 AI 이미지][이코노미스트 이용우 기자] "삼성전자·SK하이닉스 통수 맞고 한화만 믿는 사람들의 모임입니다" "불이 붙은 시대엔 불을 다루는 자만이 살아 남는다"이란 사태 여파로 대부분의 주식이 급락중인 가운데, 방위산업 관련주(방산주)들은 오히려 급등하고 있다.3일 오후 3시 현재 LIG넥스원(079550)은 상한가(29.86%)까지 치솟았고, 한화시스템(272210)은 28.87%, 한화에어로스페이스(012450)는 19.00%, 현대로템(064350)은 7.38% 급등하고 있다.빅텍은 29.77%, 스페코는 20.42%, 한일단조는 16.38%, 휴니드는 14.09%, 풍산은 13.13% 오르는 등 그밖의 방산주들도 강세다.최근 급등주에 붙었던 ''설명할 시간이 없어, 어서 타!'' 밈(meme, 인터넷 유행)까지 붙어, 방산 비중이 높은 한화그룹의 김승연 회장의 인공지능(AI) 합성 이미지도 만들어졌다.중동발 지정학적 리스크에 무기 수요가 높아질 것이라는 기대가 나오면서 방산주에 대한 관심이 높아지고 있는 모습이다.백종민 유안타증권 애널리스트는"미국과 이란 간 분쟁 흐름에 따라 방산 주가의 단기 등락은 불가피할 전망"이라며 "이번 사태는 중동 내 방공시스템 수요가 확대되는 계기가 될 것"이라고 판단했다.변옹진 iM증권 애널리스트도 "앞으로의 전개 양상에 따라 커다란 불확실성이 남아 있지만, 러시아-우크라이나 전쟁 이후로 4년 만에 다시 한번 전 세계에 자국의 방위력 증대를 통한 자주국방의 중요성을 강력하게 일깨울 것"이라며 "지상무기까지도 수요가 증가할 것"이라고 전망했다."이라며 "지상무기까지도 수요가 증가할 것"이라고 전망했다.', NULL, '이코노미스트', 'https://n.news.naver.com/mnews/article/243/0000093881', 'https://imgnews.pstatic.net/image/243/2026/03/03/0000093881_001_20260303150909159.jpg?type=w800', 'NEWS_TRANSPORT', NULL, '2026-03-03 15:09:09', 0, true, '2026-03-09 06:25:07.296655') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1153, '''석유 대안'' 재생에너지株 부상…HD현대엔솔 상한가[핫종목](종합)', '''에너지 안보 대안'' 재생에너지 부상…태양광·풍력 등 상승중동불안 수혜주 정유·해운 업종, 정부 가격담합 경고에 하락올해 6월 3일(현지시간) 미 캘리포니아주 산 라파엘의 한 주택 지붕에 태양광 패널이 설치되어 있는 모습. ⓒ AFP=뉴스1(서울=뉴스1) 박승희 기자 = 이란 사태로 석유 가격이 급등한 가운데 에너지주 희비가 갈렸다.6일 한국거래소에 따르면 HD현대에너지솔루션(322000)은 전일 대비 2만 7000원(29.97%) 오른 11만 7100원에 거래를 마쳤다.유가가 연일 급등하자 ''에너지 안보'' 대안으로 재생 에너지가 부상하면서다. 재생 에너지 투자 확대가 필요하단 목소리가 힘을 얻으며 수혜 기대가 커졌다.석유주에 대한 관심이 재생 에너지 관련 종목으로 옮겨붙으며 한화솔루션(009830)(16.67%), OCI홀딩스(010060)(15.38%), 씨에스윈드(112610)(11.83%) 등이 동반 상승했다.반면 중동 불안으로 상승했던 정유, 해운 업종은 정부의 가격담합 경고에 하락 마감했다.S-OIL(010950)(-3.71%), SK이노베이션(096770)(-1.26%) 등 정유 업종과 팬오션(028670)(-7.24%), 대한해운(005880)(-5.99%) 등이 내렸다.', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008811245', 'https://imgnews.pstatic.net/image/421/2026/03/06/0008811245_001_20260306163617119.jpg?type=w800', 'NEWS_TRANSPORT', NULL, '2026-03-06 16:35:48', 0, true, '2026-03-09 06:25:14.217109') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1154, '[성공예감] 폭락, 폭등, 또 폭락… 전쟁과 증시의 관계, 역사는 이렇게 답합니다 - 김학균 전무 (신영증권 리서치센터장)', '=======================================================인터뷰 자료의 저작권은 KBS라디오에 있습니다.전문 게재나 인터뷰 인용 보도 시,아래와 같이 채널명과 정확한 프로그램명을 밝혀주시기를 바랍니다.=======================================================- 과거 전쟁 후 금융시장 괜찮았다? 단기전 덕분… 이번엔 ''장기화 여부''에 모든 게 달려- 지금은 ‘조급함’이 가장 큰 적… 감내하고 견뎌야 할 때- "200조 원 증발"류의 기사는 최악… 주식은 팔아야 손실, ''만기 없는 것''이 최대 장점- 주식 변동성, 대처하려 하면 안 돼… 피할 수 없는 것이 변동성- 주식 투자의 지불 비용은 굴욕감 견디는 것... 레버리지는 투자 승률 낮추는 투자■ 프로그램명 : 성공예감 이대호입니다■ 방송 시간 : 3월 9일(월) 09:05-10:53 KBS 1R FM 97.3MHz■ 진행 : 이대호■ 출연 : 김학균 전무 (신영증권 리서치 센터장)◇이대호> 성공예감 이대호입니다. 오늘 증시 상황은 지금 낙폭은 계속 커지고 있네요. 코스피가 427포인트 7. 66% 떨어진 5157, 코스닥은 6% 떨어진 1084, 원달러 환율은 1494원으로 거의 10원 가까이 올라가고 있습니다. 삼성전자 하이닉스를 비롯해서 하이닉스 낙폭이 10% 이상으로 커졌고요. 우량주들까지도 10% 가까운 낙폭을 가리키고 있는데요. 중동 전쟁 사실 그게 언제 끝날지 예측이 어렵습니다만 우리가 과연 대응할 수 있는 방법이 있을까요? 개미스쿨 시간에 들어보시죠. 신영증권 리서치 센터장인 김학균 전무와 함께하고 있습니다. 안녕하세요.◆김학균> 안녕하십니까? 이런 날은 안녕하다고 인사드리는 게 조금 송구스럽네요.◇이대호> 안녕하셔야지요.◆김학균> 예.◇이대호> 혹시 들리십니까? 센터장님. 아우성 소리가.◆김학균> 들리진 않지만 짐작.◇이대호> 마음으로 들리는 것 같지요? 그런데 사실 어느 때건 증시의 급등락 변동성은 늘 있습니다만 이 정도까지 흔들리는 거, 물론 증시가 많이 올라와서 400포인트 이렇게 흔들리는 장세. 그런데 또 이게 퍼센티지로 따지면 7% 이상 반등할 때 12% 반등하는 날도 있습니다만 경험하시기에 기억 속에서는 어떻습니까?◆김학균> 지난주에 기록했던 하루 하락률이 사상 최고치라고 하니까 저도 처음 보는 현상인데 그런데 9.11 테러 직후나 아니면 2008년 금융위기 직후나 코로나 팬데믹 국면에서 크게 보면 비슷한 일이 지금이 제일 크긴 합니다마는 비슷비슷하게 나타나는 것 같고 오늘의 경우도 일본이 니케이 지수가 지금 한 6.5%, 10시에 개장한 우리 시간으로 대만 가권 지수가 한 5.5% 정도 조정받고 있으니까 역시 중동 이슈로 동북아 증시가 굉장히 큰 영향을 받는 것 같고요. 동북아 시장이 올 들어서 다른 나라보다 한국을 중심으로 해서 많이 올랐다는 것도 조정받을 때 세게 받는 이유인 것 같고 중동산 원유에 대한 의존도가 더 높은 나라들이 동북아 나라들입니다. 그러다 보니까 상대적으로 중동 지역 전쟁에 대한 어떤 후폭풍이 더욱더 크게 나타나는 것 같습니다.◇이대호> 한번 정리를 해보면 저도 참 항상 헷갈려서요. 연휴 끝나고 3월 3일에 7.24% 떨어졌고요, 코스피가. 그다음 날에도 12.06% 떨어졌고 그다음 날에 9.63% 급반등을 했고 지난주 금요일에는 보합 정도로 마감이 됐고 오늘 한 7.8% 가까이 떨어지고 있고. 어마어마합니다. 사실은 개별 종목이 이 정도 변동성 보여도.◆김학균> 큰 건데 주가지수가 그러니까 참 개별 종목은 한 15% 정도 움직여도 이상하지 않을 정도로 그렇게 진폭이 큰데요. 우리가 금융시장이 전쟁에 대해서 어떤 통찰이 있을까. 일반적으로 많은 사람들이 금융시장은 미래에 대한 현명한 예언자다. 자기 돈을 걸고 모든 정보를 반영해서 가격을 형성하기 때문에 금융시장이 굉장히 지혜로운 예언자 취급을 받기도 하는데 저는 생각이 다릅니다. 지정학에 대해서 금융시장은 모르죠. 이걸 어떻게 알겠어요? 최근에 중동 전쟁이 벌어졌을 때 대략 짧게는 한 달 지나면 괜찮았다 그런 식의 평가들은 그냥 과거의 경험입니다. 제 기억에 나는 큰 중동 전쟁이 91년도에 아버지 부시 대통령이 이라크 공격했던 때가 있었고 2001년 가을에 9.11 테러 직후에 미국이 아프가니스탄을 공격했던 적이 있었고 2003년도에 미국이 이라크를 2차 공격했죠. 또 작년 6월에는 미국이 이란을 공격했고 전부 미국 중심으로 큰 전쟁이 나타났던 게 90년대 이후로 4번이 있었는데 공교롭게도 그 4번의 전쟁이 나고 나서 금융시장이 큰 타격을 안 받았습니다. 그것은 중동 전쟁이 금융시장에 영향을 안 준다 못 줬다고 하는 거는 잘못된 해석이고요. 전쟁이 단기간에 끝나서 그렇습니다. 그런데 지금은 전쟁이 장기화된다고 그러면 후행적으로 영향을 받는데 제가 전쟁에 대한 금융시장의 예전의 통찰을 한 가지 사례를 말씀드리면 1914년 7월에 유럽에서 1차 세계대전의 소식이 미국으로 전해졌을 때 미국 다우지수가 단기간에 한 15% 넘게 급락했습니다. 이건 그 당시 세계사의 중심이었던 유럽에서 큰일 벌어졌구나 생각하고 악재로 해석하고 뉴욕 증권거래소가 또 한 넉 달 쉬었어요. 폐쇄했었습니다. 큰일 났다고 생각한 거죠. 그러다 1914년 12월에 거래가 재개되니까 그때부터 미국 시장이 한 2년 넘게 강세였습니다. 생각해 봤더니 자기 땅에서 전쟁 벌어지는 것도 아니고 유럽이 전쟁통이 되다 보니 미국이 수출의 기회가 많이 늘어나면서 우리에겐 기회네 이렇게 생각하면서 주식이 좋았고요. 반대로 1939년 9월 초에 독일이 폴란드를 침공하면서 2차 세계대전 침공 소식이 뉴욕에 전해졌을 때 뉴욕 증시는 단기간에 급등했습니다. 전쟁은 우리에게 기회다 생각했는데 주가가 단기간에 오르고 한 3년 가까이 약세였습니다. 그때가 왜 다르냐 하면 1차 세계대전은 정말 분리된 유럽 땅에서의 전쟁이었는데 2차 세계대전에서는 이미 아시아 태평양 지역의 일본이 독일과 동맹을 맺으면서 뭔가 팽창주의적인 노선으로 가면서 전쟁에 대한 위협이 있었던 거거든요. 그러니까 1차 세계대전과 2차 세계대전이 다르다 보니까 그 당시 투자자들은 1차 세계대전의 학습 효과만을 가지고 전쟁은 호재였구나 했는데 다르게 반응했던 거죠. 그래서 지금의 상황도 얼마나 장기화되느냐가 굉장히 중요할 것 같고요. 그런 점에서 보면 금융시장이 얼마나 전쟁이 길어질 거냐에 대해서는 저도 통찰이 없고 금융시장도 알지 못한다고 생각하는데 저는 비슷한 사례가 2022년도에 러시아 우크라이나 전쟁을 들 수 있다고 생각하고요. 또 비슷한 사례가 2011년 3월에 동일본 대지진 영향도 비슷한 사례가 될 것 같아요. 그땐 전쟁은 아니지만 어떻게 전쟁이 금융시장에 영향을 주는가 일반화시켜서 보면 전쟁 당사자국 무조건 악재입니다. 2차 세계대전 일본 러우 전쟁했을 때 러시아 조건 무조건 악재고요. 그럼 전쟁을 안 치르는 나라는 그러면 어떻게 영향을 받느냐 우리는 어떻게 영향을 받았어요? 우리가 지금 유가를 보면서 반응하잖아요. 전쟁은 결국은 글로벌 공급망을 교란시킵니다. 교란시키고 그 과정에서 유가를 비롯한 원자재 가격이 올라가고요. 인플레이션이 생깁니다. 그 과정에서 중앙은행이 긴축하고 금리가 올라가면서 주가가 조정을 받는 게 과거의 패턴인데요. 2011년도에 동일본 대지진도 장기간 밸류체인에 문제가 있었고 2022년 러우 전쟁 직후에도 그때 기름값이 단기간에 서부 텍사스 중질유 기준으로 90불 하다 120불 가면서 인플레가 생겼거든요. 그래서 그 당시에 주식 시장이 동일본 대지진 직후에는 한국의 코스피가 한 26% 그리고 러우 전쟁 국면에서는 전쟁 나고 나서 한 20% 정도 조정을 받았거든요. 그런데 제가 이 두 국면과 지금을 한번 비교해 보면 일단 전쟁이 장기화된다 그러면 제 생각에는 금융시장의 부진이 더 깊어질 수 있는데 거기에 대해서는 우리가 모른다고 생각해야 되고요. 그런데 2011년 동일본 대지진과 2022년 러시아 우크라이나 전쟁 다음에 나타났던 우리가 주목할 만한 점은 뭐냐 하면 중앙은행이 실수를 했습니다. 전쟁을 치르면서 막 물가가 높아지고 동일본 대지진으로 인해서 일본이 소재 부품의 강자인데 여기서 뭔가 생산이 안 되면서 그때도 공급난 때문에 물가가 높아졌거든요. 그러면 물가가 올라가게 되면 중앙은행이 금리를 올리는 긴축을 해야 된다고 생각하지만 물가 급등의 원인을 잘 봐야 되거든요. 중앙은행이 금리를 올려서 긴축하는 거는 경제의 과잉 수요가 있어서 사람들이 과하게 쓸 때 금리를 올림으로써 과잉 수요를 억제하면서 물가 안정을 도모하는데.◇이대호> 수요를 잡는 거지요.◆김학균> 그렇지요. 그럼 전쟁으로 인해서 지금 물가가 올라가고 지진으로 인해서 물가가 올라가는 거는 사람들이 과잉 소비를 해서 올라가는 것과는 거리가 멉니다. 공급의 문제예요. 금리 올린다고 공급난이 해결될 거냐 그건 아니죠. 물가가 올라가서 기본적으로 수입해서 살아가야 될 국민들은 굉장히 힘든데 거기까지 금리를 올리게 되면 굉장히 경제에 더 큰 압력을 가하는 거거든요. 그래서 2011년도에 누가 실수를 했냐면 유럽 중앙은행 ECB가 실수했습니다. 그 당시에도 미국 전 세계 경제가 2008년, 2009년 거의 2010년까지 진행이 됐던 글로벌 금융위기의 충격이 해소되면서 뭔가 물가가 올라가고 있었거든요. 그런데 여기서 동일본 대지진까지 터지면서 물가 상승률이 더 깊어지니까 이시비가 2011년 여름에 금리를 두 번 올렸습니다. 그런데 지나고 났더니 그건 잘못 올린 거예요. 재정 위기가 있어서 이시비가 금리를 올리면서 그리스에만 있었던 재정 위기의 불길이 피그스라고 하는 아일랜드라든가 이탈리아 스페인으로 번졌고 2011년 여름 즈음에는 프랑스도 재정 위기에 대한 우려가 굉장히 커졌었습니다. 정책 실수예요. 금리를 잘못 올리면서 문제가 생겼던 거고 2022년도 러우 전쟁 났을 때의 사례를 보면 그때는 미국이 전 잘못했다고 보는데요. 미국의 물가가 이미 2022년 2월에 전쟁 나기 전부터 2021년 하반기부터 올라가기 시작했습니다.◇이대호> 꿈틀대고 있었죠. 워낙 푼돈이 많아서.◆김학균> 그래서 그 당시에 미국의 소비자 물가지수가 전쟁 나기 전에도 한 6%, 7% 정도 가 있었는데 당시에 연준 의장이었던 파월 의장이 금리를 안 올렸어요. 제가 말씀드렸던 그런 논거였죠. 지금 물가가 올라가는 거는 코로나가 전체적으로 세계 경제가 코로나 팬데믹으로부터 벗어나고 있긴 하지만 일부 지역 동남아 같은 데서 차량용 반도체 생산 못 하고 하면서 공급 차질로 물가가 올라가는데 중앙은행이 금리를 올려서 수요를 누르는 게 맞느냐는 생각인데 그런데 그 당시 파월이 조금 잘못 생각했던 거는 이전에도 금리가 물가가 올라가는데 공급난도 있었지만 코로나가 끝나면서 미국 사람들의 보복 소비라는 얘기 그때 많이 했었죠. 그때 수요 과잉도 있었어요. 그런데 사실 그거를 갈라보기가 되게 힘듭니다. 그 국면에선. 그런데 러시아 우크라이나 전쟁이 나면서 물가가 훅 훅 올라가니까 그때 연준이 금리를 올렸는데 그냥 얌전하게 올린 게 아니지요. 지금 자이언트 스텝 기억 나시는지 모르겠는데 0. 75포인트씩 막 올리면서 세계 장기 금리도 올라가고 세계 경제가 아주 내려앉았거든요. 그래서 저는 지금 상황도 결국 전쟁이 중요하다. 전쟁이 장기화되거나 단기화되느냐가 굉장히 중요한데 이 금융시장이 전쟁을 치르지 않는 나라는 결국은 인플레이션과 금리가 중요한데 그 과정에서 중앙은행이 판단을 잘 내려는 게 중요한데 지금은 2011년과 2022년과 비교해 보면 동일본 대지진과 러시아 우크라이나 전쟁이 났을 때와 비교해 보면 지금은 전쟁을 제외하면 인플레이션 압박은 그때보다 상당히 낮은 상황이라서 결국은 저는 전쟁이 중요하다고 생각하는데 우리가 전쟁에 대해서는 통찰을 갖기가 힘든 거고 그걸 우리가 모르는 요인이라고 보면 그 과정에서 주가 조정이 깊어졌던 거는 인플레가 생기고 중앙은행의 정책 실수가 과거 두 차례 있었는데 지금은 조금은 중앙은행이 허겁지겁 움직일 가능성이 낮은 거 아닌가.◇이대호> 아직은 조금 더 지켜봐야 한다.◆김학균> 전쟁에 대해서 다시 한 번 말씀드리면 전쟁의 상황을 금융시장 후행적으로 반응을 할 텐데 거기에 대해서 금융시장의 통찰이 있다고 말하기는 어렵지만 전쟁을 제외한 다른 환경들을 놓고 본다 그러면 2011년과 2022년보다는 상대적으로 그 정도로 주가가 아주 털썩 내려앉을 환경은 아니지 않은가. 그래서 저는 매를 한두 방 더 맞더라도 지금은 조금 감내하고 견뎌야 될 때가 아닌가 제 의견은 그렇습니다.◇이대호> 일단 이 시각 현재 서부 텍사스산 원유가 배럴당 109달러 오름폭이 하루 사이에 20%에 달하고 있고 브렌트유도 비슷하고요. 천연가스도 한 8% 이렇게 올라가고 있고 일단 원자재 시장은 이걸 급격히 반영하고 있는데 이게 실물 경기까지 영향을 미칠 것이냐 그래서 긴축 금리를 올릴 것이냐는 이게 또 단기간에 끝날 것이냐 장기간 이어질 것이냐를 봐야 하는데 그런데 이게 또 중앙은행의 금리를 섣불리 올리기도 힘든 게 예전에 왜 러우 전쟁 발발했을 때 미국에서 그런 반문이 있었잖아요. 중앙은행이 금리를 올리면 러시아의 탱크를 멈출 수 있느냐. 그러니까 사실 수요측 요인 공급측 요인을 다 봐야 되는데 중앙은행이 할 수 있는 건 수요의 진작 혹은 수요를 둔화시키는 것뿐이지 중앙은행이 금리를 어떻게 한다고 해서 지금 호르무즈 해협을 뚫을 수 있는 것도 아니고 이게 너무 어려운 거죠.◆김학균> 그리고 그렇기 때문에 저는 지금 환경이 어느 한쪽이더라도 글로벌 환경이 수요가 너무 좋은 거는 글로벌 전체적으로는 전 굉장히 부정적인 영향을 줄 수 있다고 보는데 그런 점에서 보면 지난 주말에 미국의 고용지표가 부진하게 나온 게 그 자체가 좋다 나쁘다 다양한 해석이 나올 수 있겠지만 지금 어느 쪽이라도 수요를 과하게 밀어올리는 쪽이 있게 되면 글로벌 경제 전체 균형을 위해서는 안 좋은 거라고 생각하고 러시아 우크라이나 전쟁이 지금까지 이어지고 있지 않습니까? 그런데 러우 전쟁으로 인한 인플레는 2022년에 끝났고 2023년보다 물가가 안정됐어요. 그래서 전쟁이 4년 연속 이뤄지고 있지만 제가 그래서 다시 한번 말씀드리지만 전쟁을 치르지 않는 나라는 전쟁 그 자체보다 거기서 야기되는 공급량과 인플레이션이 중요하다는 말씀을 드리고 싶고요. 2023년부터 공급난이 완화되면서 전쟁은 치러지고 있지만 주가가 조정을 덜 받았는데 저는 그 이후에 물가가 안정된 중요한 이유 중에 하나가 중국 경제가 둔화됐기 때문이라고 봅니다. 부동산 경기 부양을 위해서 막 자원을 쓰다가 성장률을 끌어올리기 위해서 중국이 성장률을 높이는 정책을 썼다 그러면 저는 러우 전쟁의 여파로 더 오래 갔을 거라고 생각하거든요. 그래서 이후에 나타날 물가 상승 압력은 상당히 다양한 스펙트럼을 통해서 나타나는데 그 국면에서의 물가 상승이 수요 요인인지 아니면 공급 요인인지 정확히 발라내기는 상당히 힘든 일입니다. 그래서 2011년에는 유럽중앙은행이 전 실수했다고 생각하고요. 2022년에는 연준이 뒤늦게 금리를 공격적으로 올리는데 전쟁이라고 하는 게 어떻게 보면 그 계기가 됐다는 점에서 또 연준의 오판을 만든 측면도 있다고 보거든요. 그래서 아직까지는 물가 상승 압력이 높지는 않은데 결국은 지금은 장기화 여부가 가장 중요한 거 아닌가. 그전까지는 시장이 어떤 추세라기보다는 굉장히 높은 변동성을 띨 가능성이 높다고 봅니다.◇이대호> 그러니까 물가 때문에 유가 때문에 금리를 올려서라도 수요를 더 줄여야 한다는 일각의 요구가 나올 수도 있겠으나 사실은 또 물가가 올라가게 되면 수요는 자연스럽게 또 둔화되잖아요.◆김학균> 그럼요. 그게 자연스러운 일이죠.◇이대호> 그러면 미국의 고용 지표도 둔화되고 있고 유가 겁나서 많은 사람들이 대중교통 타겠다는 분들도 많은데 수요가 줄어들면 오히려 차라리 낫다 오히려 고맙다 또 이렇게도 역설적으로.◆김학균> 그게 어떻게 보면 어떤 자연적인 자정 작용이고요. 거기서 또 실패의 케이스가 5월에 연준 의장이 바뀌게 되는데요. 1971년도에 연준 의장에 올랐던 아서 번스라는 사람이 72년도 73년도에 중동 전쟁이 있었잖아요. 1차 이스라엘 중동 전쟁이 있었는데 전체적으로 70년대 초반은 인플레이션 압력이 컸던 시기거든요. 전쟁이 있었고 또 중동에서의 전쟁 베트남 전쟁 이런 게 있었는데 그 전쟁이 아무리 공급난이라고 하더라도 그걸 또 금리를 낮추는 거는 사실은 좋지 않은 정책인데 70년대 초반에 인플레이션에 대한 우려가 굉장히 높을 때 아서 번스라는 연준 의장이 당시 대통령이었던 닉슨 대통령이 거의 정치적으로 복속을 하면서 오히려 돈을 푸는 정책을 하면서 70년대의 인플레 기대 심리가 확 높아지면서 지금 진행자께서 말씀하신 것처럼 이유가 뭐든지 간에 가격이 높아지게 되면 수요가 줄어들면서 물가가 잡히는 효과가 있는데 거기서 연준이 인플레이션 기대심리 관리를 실패하면서 70년대 내내 인플레가 지속이 된 적이 있거든요. 그래서 중앙은행의 행동이 되게 중요한데 이건 제가 하나의 상상인데 트럼프의 의중을 잘 따르는 새로운 연중 의장이 들어와요. 이 사람이 그것이 공급의 요인이건 아니면 다른 요인이건 간에 물가가 불안하게 움직이는데 금리를 만약에 낮추거나 완화적으로 간다 그러면 제 생각엔 그건 다른 측면에서의 이 중앙은행의 정책 리스로 인한 인플레이션 장기화 시나리오가 만들어질 수도 있는 건데 그런데 어쨌든 지금은 아무튼 전쟁을 제외하면 물가 상승 압력이 과거 어수선했던 했던 때보다 낫다는 거는 제 생각에는 2011년도 2022년보다 글로벌 시장이 충격을 덜 받지 않을까 그런 정도의 전망과 기대를 갖고 있습니다.◇이대호> 그래서 아직은 최악으로 치달을 그런 상황은 아니라는 말씀으로도 해석되고요. 다만 중요한 건 이 전쟁이 얼마나 더 길어지느냐 트럼프 대통령의 말처럼 단기간에 끝날 수 있을 것이냐를 봐야 하는 거고요. 당장 시장이 많이 혼란스럽다 보니까 정부에서도 적극적으로 대응합니다. 예를 들어서 100조 원 규모의 시장 안정 프로그램. 그런데 이게 증시에 직접적으로 뭔가 주식을 사주면서 떠받치는 그런 개념은 일으키고.◆김학균> 그런 돈은 아니죠.◇이대호> 약간 산업적으로 이해해야 할까요?◆김학균> 예전에 채권 안정 기금이나 이런 거 금리가 올라갈 때 나름의 레고랜드 사태 그랬을 때 코로나 때도 물론 그런 식의 자금이 있었고요. 지금은 뭔가 시장의 변동성이 크고 투자자들이 아주 당혹스러울 때 나름의 어떤 안전판을 마련하고 이런 것들은 할 수 있다고 생각은 하는데 현상 자체가 글로벌한 현상입니다. 글로벌한 현상이기 때문에 어느 정도는 감내해야 될 속성이 있는 거 아닌가 싶습니다.◇이대호> 증시 안정 프로그램은 말 그대로 시장에 돈이 돌지 않을 때 누구도 돈을 빌려주지 않거나 내 돈 다 가져오라고 만기 때 회수만 한다면 큰일 나니까 그럴 때 좀 더 돈이 돌도록 혈액 순환을 시켜주겠다 이런 개념으로.◆김학균> 돈이 안 돌게 되면 멀쩡한 기업이나 경제 주체도 어려움을 겪을 수가 있는 거거든요.◇이대호> 그런데 왜 증안펀드 증시 안정 펀드 이야기도 예전에 코로나 팬데믹 때도 이야기 나왔었잖아요. 물론 집행된 적은 없습니다만. 그런데 6300 갔다가 5천 초반까지 밀렸다고 해서 증시 안정 펀드까지 가동해야 하느냐 이것도 참 딜레마일 것 같습니다.◆김학균> 어느 시점에 시장에 개입하느냐는 늘 좋은 고민이 되는 걸 텐데 이것도 주가 떨어지는 게 정당화된다, 사실 시장이 그런 건 없는 거고요. 나타날 수 있는 일로 봐야 될 것 같아요. 이런 시장의 변동성에 대해서 정책이 일일이 대응하기는 어렵고 역대 주식시장 부양책 중에서 가장 강력한 부양책은 1989년도에 12.12 증시 부양책이라는 게 있었거든요. 노태우 정권 때인데요. 그때 얌전하게 출자금을 금융기관으로 받아서 증안 펀드를 만드는 게 아니고 한국은행이 발권력을 동원해서 그 당시에 투자 신탁이라고 하는 서울에 재경 소위 삼투신이 있었거든요. 한투 국투 대투 이런 삼투신이 있었는데 그냥 중앙은행이 거의 무차별적으로 무제한적인 차입을 해서 주식 사라고 그랬는데 결국 못 막았고 결국 그 회사들이 망했죠. 지금은 주인이 바뀌어서 운영되고 있습니다마는 그 당시에 한은으로부터 차입해서 주식을 샀다가 그때 주가지수가 900, 1000이었어요. 그런데 장기적으로 외환위기 때 280까지 떨어지다 보니까 빚내서 산 주식이 전부 다 평가손이 발생하면서 회사들이 망했기 때문에 여러 가지 변동성을 줄이기 위해서 여러 고민하는 건 저는 그건 공무원들의 몫인데 어느 정도는 시장에서 벌어지는 자생적으로 돌아가는 메커니즘이 있는 것 같고 그걸 정책을 통해서 막기는 힘든 것 같습니다.◇이대호> 그 부작용을 생각하지 않을 수 없고.◆김학균> 글로벌 현상이라고 생각해야죠. 한국만 그런 건 아니니까요.◇이대호> 발권력을 동원해서 그리고 금융기관들이 차입을 통해서 주식을 사더라도 그렇게 힘든데 개인 투자자들도 요즘에 차입 많이 하지 않습니까? 신용융자 사상 최대치 가고 있고 최근에 보면 2월 말에서 3월 초 사이에 그러니까 증시가 흔들릴 때 마이너스 통장, 1조 3천억 원 정도의 마이너스 통장이 열렸다고 합니다. 대충 유추가 되지 않습니까?◆김학균> 그러니까 지금 주가라는 게 이게 아무리 강세장이더라도 저는 이번 강세장에서 지금 우리가 3월 초에 경험하고 있는 이 소란이 굉장히 저는 휘발성이 있다고 봐요. 아래쪽이든 다 기회가 열려 있는데 만약에 전쟁이 단기간에 끝나고 이게 수습된다고 그러면 우리가 3월 초에 기록했던 사상 최고의 하락률 이런 것도 지나고 나면 기억도 못 할 누군가가 잔잔한 호수에 돌을 던져서 나타났던 일시적인 파장일 수도 있다고 생각하는데 그런데 주식 투자가 좋은 거는 저는 만기가 없기 때문이라고 생각해요. 주식 사서 손해 봤더라도, 그래서 저는 기자분들이 주가 떨어졌을 때 200조 원 증발 이런 거 정말 안 좋은 기사라고 생각해요. 주가 떨어진 거죠. 그 직전에 1000조 원 넘게 늘어났다가 내 돈이 손실 보는 거는 내가 팔아야지 손실이 되는 거예요. 나쁠 때는 주식 팔지 않고 견디는 것도 저는 투자자가 견뎌야 될 중요한 태도라고 생각하거든요. 그런데 외상으로 주식을 사게 되면 만기가 있는 거죠. 금융회사들에게 주식을 빌려서 미수나 신용으로 주식을 사게 되면 알아서 반대 매매를 통해서 포지션이 청산이 될 수도 있기 때문에 이 투자라고 하는 거는 저는 절대적으로 치명상을 안 입는 게 절대적으로 중요한 게임인 것 같습니다. 우리 시장이 지난 1년 동안, 1년도 아닙니다. 작년 4월부터 좋았으니까 강세장이 채 1년도 지금 지생이 된 건 아니지만 그 이전까지 시장이 얼마나 어려웠어요. 미국 장으로도 가고 그랬지만 결국 견딘 이에게 보상을 해주는데 외상을 통해서 주식을 산다는 거는 기본적으로 견디기가 힘든 그런 환경을 조성하니까 이게 단기 조정이더라도 내 포지션이 일거에 청산될 수 있기 때문에 아무리 제 생각엔 수익률에 대한 조급증이 있으시더라도 투자는 절대적으로 치명상을 입지 않는 게 절대적으로 중요하다는 말씀을 꼭 드리고 싶습니다.◇이대호> 조금 전에 서킷 브레이크가 발동됐다고 우리 청취자분들이 알려주셔서 제가 지금 막 검색하고 있습니다. 아직 기사는 안 나왔는데 한 번 더 체크를 해보겠습니다. 안진수님 그리고 3000 쓰시는 분이 서킷 브레이크 발동됐다고 말씀해 주셨는데 체크해 볼게요. 그만큼 시장의 변동성은 커지고 있고 많은 분들이 놀라셔서 주식을 던지고 있고 코스피가 현재 한 8. 1% 빠지고 있으니깐요. 서킷 브레이크 발동될 수 있는 요인은 돼가고 있네요. 언제까지 갈지 모르니까 사람들이 사실은 던지는 행위들이 나타나는 건데 아침에 만난 어떤 분이 그 얘기 하더라고요. 워런 버핏이 산 주식을 사서 기다리고 있었는데 너무 안 올라서 힘들어서 팔았다고 그런데 그게 에너지 정유 관련주였거든요. 그런데 최근에 많이 올라 더 힘들다고 마음이. 그런데 사실 왜 사람들이 그런 거 있지 않습니까? 당장 언제까지 내가 어디 갖다 줘야 하는 돈이거나 갚아야 하는 돈이면 만기가 있겠습니다만 말씀하신 것처럼 만기가 없으면 힘든 건 마음뿐일 수 있잖아요.◆김학균> 그럼요. 그래서 돈의 성격이 투자 성패를 결정적으로 좌우하고요. 우리가 지난 2월 말까지 시장이 굉장히 좋았는데 저는 그거 굉장히 예외라고 생각합니다. 주식시장은 장기간 투자하게 되면 보람을 줬지만 작년 4월부터 금년 2월까지 거의 고속도로를 달리듯이 했던 것은 예외고 또 어떤 면에서는 저는 대부분의 경우는 주식 투자의 한 60~70%는 주식 투자를 함으로써 우리가 직면해야 될 일종의 지불해야 될 비용은 굴욕감을 견디는 거예요. 나쁠 때 내 주식 안 오르고 남의 주식 올라가는 것도 참고 견디고 결국 기다리면 보답하는 건데 그렇게 본다고 그러면 아무튼 내 돈의 만기를 자꾸 만드는 거는 그거는 좋은 투자 습관은 아닌 것 같고 그렇게 투자하다 보면 한 6, 7번 잘하더라도 한 번 실패하면 그게 치명상을 받을 수도 있는 거기 때문에 지금 주가가 급등락하기 때문에 손해를 보신 분들은 이걸 빨리 회복하려고 또다시 레버리지 투자를 고려하실 수 있을 텐데 저는 그런 거는 늘 장기적으로 보면 자신의 투자 승률을 낮추는 그런 투자라고 생각합니다.◇이대호> 코스피가 8% 넘게 낙폭이 커지면서 서킷 브레이크가 발동됐고요. 이거는 사이드카랑 다르게 실질적으로 매매 거래가 20분 동안 중단이 되죠. 사이드카는 프로그램 호가만 잠시 멈출 뿐인데 서킷 브레이크는 아예 주식 거래 자체가 20분간 중단이 되죠. 한 10시 50분 넘어야 거래가 다시 재개될 걸로 보이네요. 저희가 앞서 1부 오늘의 경제 뉴스 시간에 최근에 ETF 사신 분들이 이게 원금이 보장되는 줄 알았다. 혹은 ETF를 잘못 광고하시는 분들도 있거나 회사나 이런 잘못도 있겠으나 투자를 처음 하시는 분들의 자금이 급거 많이 들어오고 있잖아요. 최근에 고객 예탁금 그러니까 주식 대기성 매수 자금이라고도 볼 수 있는 게 130조를 넘어섰고요. 어떻게 보세요?◆김학균> 지금 새 돈이 1월 중후반부터 정말 많이 들어오고 있습니다. 지금 주식시장으로 돈이 들어오는 경로가 증권회사에 내가 주식 사려고 돈을 맡기는 직접 투자 자금이 이건 고객 예탁금으로 잡히고요. 주식형 펀드로 들어오는 자금이 있습니다. 그런데 지금 주식형 펀드로 들어오는 자금이 소위 액티브 펀드라고 하는 펀드 매니저들에게 내 돈 알아서 잘 운용해 주세요 이런 쪽으로 돈이 거의 안 들어오고요. ETF 쪽으로 돈이 많이 들어옵니다.◇이대호> 기계적으로 투자하겠다.◆김학균> 그런데 작년에 1년 동안 이 두 가지 유형을 합쳐서 주식시장으로 돈이 들어온 게 한 14조 원 정도 됩니다. 그런데 언론 같은 데서 고객 예탁금이 작년에 30조 넘게 늘었다 이런 보도 보셨을 거예요. 그런데 고객 예탁금은 실제로 들어온 돈의 양이 아니고요. 주식을 사기 위해 계좌 안에 있는 돈의 규모입니다. 그러면 작년도에 예탁금이 30조 늘었는데 거의 돈이 안 들어온 거는 개인 투자가들이 그만큼 주식을 팔아서 그렇습니다. 주식을 팔게 되면 새 돈이 안 들어오더라도 그 돈을 안 빼가면 예탁금으로 늘어나잖아요. 그래서 고객 예탁금은 특정 시점에 있는 돈의 양이고 실제로 돈이 들어오고 나간 거는 따로 개인 매매랑 분리해서 봐야 되는데요. 그런 점에서 보면 작년에 개인 투자가들의 직접 투자 자금이 들어온 게 한 5천억 주식형 펀드로 들어온 게 한 13조 원 후반대 이렇게 들어왔는데 금년 들어서 3월 4일까지 이 개인 투자가들 직접 투자 자금이 37조 원 정도 들어왔고요. 작년이 14조인데.◇이대호> 한 3배 가까이.◆김학균> 그게 2월 중순 이후로 확 들어온 거고, 주식형 펀드로 들어온 돈도 14, 15조 들어왔어요. 그러니까 지금 돈이 2월 중순부터 들어오고 있고 이 돈이 어떻게 보면 코스피 5천 이상에서 지금 돈이 많이 들어온 건데과거에도 주가가 올라가야 후행적으로 돈이 들어오거든요. 그건 늘 그런데 이번에는 작년에 주가 상승 속도가 너무 빨랐던 것 같아요. 2300에서부터 4500, 5천까지 그냥 조정 없이 올라가다 보니까 돈이 들어올 틈이 없었다가 지금에야 들어오고 있고 그래서 지금도 상당히 고점 부근에 투자해서 당황해하시는 분들이 많으실 텐데 주가의 미래를 아는 사람은 없죠. 아는 사람은 없는데 주식 투자라고 하는 게 세상에 별의별 일이 다 있습니다. 전쟁도 있고 다 있고 그걸 통해서 장기적으로 보면 시장은 무너지진 않았고 하기 때문에 앞서서 제가 여러 가지 이번 중동 사태에 대한 의견도 말씀드렸는데 아무튼 지금은 조급함이 어쨌든 투자자들에게 가장 큰 적이라고 생각하셔야 되고 시장이 이렇게 급등할 때 어떻게 대처하냐. 대처를 못하지요. 이 변동성을 대처하려고 그러면 안 돼요. 변동성은 어떻게 대처합니까?◇이대호> 단타 트레이딩 데이 트레이딩 하시는 분들이야.◆김학균> 그런 방법이 있겠지요.◇이대호> 그걸 피하면서 하시려고 하겠으나.◆김학균> 보통의 경우는 변동성은 내가 모른다고 생각해야 되고요. 그렇기 때문에 지금은 너무 짧게 움직이는 것보다 일단 모른다고 생각하고 무리한 포지션을 절대적으로 안 잡는 게 중요할 것 같고요. 예컨대 미수라든가 외상으로 주식을 사거나 내가 갚아야 될 차입을 통해서 주식을 사거나 이런 건 절대적으로 피해야 될 것 같고 기본적으로 지금 같은 경우는 주식시장에 꼭 사고 파는 게 대처가 아닙니다. 모르는 상황에서는 인내하고 견디는 것도 저는 투자라고 생각하거든요. 그래서 지금은 특히나 투자 처음 시작하시는 분들은 일단 조급함을 버려야 된다는 말씀을 꼭 드리고 싶습니다.◇이대호> 그러게요. 5천 넘어서면서 처음으로 들어왔던 그런 투자 자금들 그러니까 주식 투자에 사실은 ABCD 기초가 없이 그냥 요즘 많이 오른다는 종목만 적어서 증권사 가서 사달라는 분들 정말 많으셨다고 하고. 이참에 공부하기는 참 좋은 시기가 되는 것 같긴 한데 길게 봤을 때요. 또 전쟁이라는 외생 변수에서는 금융시장이 어떻게 반응하는가를 보는 것도 사실 인문학 수업이 될 겁니다. 이런 말을 하기가.◆김학균> 지금은 너무도 힘든 때이긴 한데 시장이라고 하는 거는 정말 별의별 일을 다 겪으면서 성장해 왔다는 걸 생각하셔야 됩니다.◇이대호> 그런데 요즘에 신규 자금이 유입되는 것뿐만이 아니라 회전율 있지 않습니까? 어마어마합니다. 개별 기업들은 그 회사의 시가총액 거의 5배 가까이가 하루 만에 거래가 된다거나 이런 현상들은 사실은 늘 변동성이 커질 때 나타나는 일이기도 합니다.◆김학균> 그럼요. 요즘은 조금 더 심하긴 한데 이런 일들이 사실 정도의 문제지 금융시장에서 전혀 못 봤던 일이라고 생각하시면 안 됩니다. 앞서 말씀드렸던 경우도 제가 러시아 우크라이나 전쟁과 동일본 대지진의 사례도 예기치 못한 외적 변수가 나타나서 꽤 나쁜 상황이 장기화됐던 사례들을 말씀드린 거예요. 중동에서는 이게 장기화되지 않고 짧게 끝났기 때문에 별일 없이 지나갔지만 그런 것들을 견딤으로써도 그런 것들을 경험하면서도 결국 시장은 무너지지 않았기 때문에 제 생각에 지금 정도라고 그러면 참 어렵겠습니다마는 잘 견뎌야 될 국면까지 저는 시장이 밀린 거 아닌가 싶습니다.◇이대호> 그런데 전쟁 같은 게 터지면 안전자산이 떠오르고 많은 사람들도 안전자산을 관심에 두는데 최근에 금값은 오히려 조정을 받고 있습니다.◆김학균> 지금은 제가 미국의 결국 장기금리, 금리를 계속 말씀드리는데 최근에는 가상자산 금 주식 이런 것들이 차별화가 됐는데 길게 보면 모든 자산시장이 좋았죠. 부동산도 좋고. 그건 결국은 비교적 자산시장의 우호적인 통화 정책 우호적인 저금리 환경이 결국 자산 가격을 다 같이 밀어 올린 것 같거든요. 그래서 지금은 자산들이 가졌던 전통적인 상관성이 깨진 것 같아요. 예전에 주식이 조정 받을 때 금은 올라가고 이런 현상들이 발생했는데 예컨대 주식이 조정받을 때 채권 가격은 올라가고 금리는 떨어지고 그랬는데 지금은 금리가 올라갈 때 오히려 채권이 깨질 때 주식도 같이 깨졌고요. 또 제가 말씀드렸던 지정학적 위험으로 인한 굉장히 장기화됐던 어떤 리스크 인플레이션이 생기고 중앙은행이 금리를 올렸던 2022년이 글로벌 주식 투자자들에게 굉장히 어려웠던 한 해였다고 말씀드렸는데 그럼 그때 금은 버텼냐, 금도 같이 떨어졌어요. 그래서 지금은 자산시장이 전통적으로 가졌던 상관성이 매우 약해지는 그러니까 어떤 자산이 무너지면 별로 숨을 데가 없는 다 같이 무너지는 모습이 나타날 수 있고 그런 것들을 만드는 힘이 저는 결국 금리라고 생각합니다. 금리가 올라가게 되면 저는 금이라고 괜찮을까라고 생각해 보면 같이 영향을 받지 않을까 생각합니다.◇이대호> 그래서 항상 김학균 센터장님이 미국 국채 금리 장기채 금리를 잘 봐야 한다는 말씀을 해 주셨고 전통적인 투자자 사이에 상관관계는 많이 깨지고는 있습니다만 돈의 흐름에 따라서 안전자산에 대한 인식도 어떻게 보면 단기간에는 달라질 수 있는 흐름을 현재 금값이 보여주고 있고 워낙 많이 올라서 그런 것도 있지 않을까요?◆김학균> 그럼요. 자산 가격이.◇이대호> 그동안 많이 몰려 있었기 때문에.◆김학균> 많이 올랐다고 하는 건 그 자체가 조정받을 때도 굉장히 깊게 조정을 받는 패턴들이 일반적인 거죠.◇이대호> 환율도 한번 체크를 해보면 거의 12원 가까이 오르고 있는데요. 1496원, 97원. 1500원 얼마 안 남기고 있습니다. 한 일주일쯤 지났나요? 그때 한 1500원 우리 밤 시간에 거의 1500원 1510원 가까이 올라갔었는데 환율도 변동성이 많이 커지고 있습니다.◆김학균> 제 생각엔 지금은 유가 변동성 주가 변동성 환율 변동성 오늘은 미국의 장기 금리도 10년짜리 국채 수익률도 4.2%까지 비교적 강하게 많이 올라가는데요. 이게 다 통상적인 변동성의 수준을 넘어서서 움직이는 것 같고 이런 것들이 제 생각에는 하나의 추세라기보다는 일종의 변동성인 것 같아요. 그래서 결국 이걸 결정하는 힘도 중동 지역의 전황에 따라서 굉장히 좌우가 되지 않을까. 그래서 이것도 역시 정답이 될 수는 없습니다. 많은 가정들을 가지고 한번 분석해 본 건데 국제유가가 서부 텍사스 중질유가 지금 100불 넘어갔는데 올해 연평균 기준으로 한 80불 정도, 1년 이내 연평균입니다. 그 기준으로 80불 정도가 장기화된다 그러면 제 생각에는 글로벌 경제가 그냥 무난한 정도일 것 같고 이게 그거보다 높아지게 되면 물가도 자극이 되고 그 과정에서 제가 말씀드렸던 중앙은행이 오판하거나 실수할 수 있는 그런 환경들이 만들어지는데 그래서 저희들이 보는 거는 어쨌든 연평균 80불 정도가 중요할 것 같은데 러시아 우크라이나 전쟁 때도 단기적으로 기름값이 90불에서 120불까지 갔습니다. 그러고 나서 조정을 받으면서 인플레 압박이 완화됐기 때문에 지금은 어쨌든 이 전쟁이 장기화되는 거는 미국에게도 큰 부담이기 때문에 어쨌든 전황이 중요한데 저는 제가 중동의 지정학 전문가는 아닙니다마는 지금 가능성이 반반 다 열려 있는 것 같습니다.◇이대호> 우리나라 입장에서 보면 국제유가도 올라가고 있는데 환율도 올라가고 있으면 물가 상승 압력은 더 커질 수밖에 없는 거잖아요.◆김학균> 더 크죠. 더 크고 물가 명목 물가를 말하기에 앞서서 당장 지금 주유소 기름값 때문에 여러 가지 얘기들이 많이 나오는데 아무튼 살기 되게 힘들어지는 그런 환경이죠.◇이대호> 중동의 이야기를 조금 더 덧붙여 보자면 결국 핵심은 호르무즈 해협 봉쇄인데 오펙 산유국들이 증산하더라도 사실은 아무리 많이 만들어내도 물류가 안 되니 가격을 떨어뜨릴 수가 없고.◆김학균> 놔둘 수 있는 탱크가 없으니까 증산하기도 힘들죠.◇이대호> 그래서 보관할 수 있는 탱크가 모자라니까 감산하겠다고 하고. 그런데 지금 감산해 버리면 나중에 그걸 즉시 증산을 다시 할 수 있을 것인가에 대한 걱정도 있고요.◆김학균> 그러니까 장기화가 문제일 것 같고요. 이건 저의 하나의 그냥 기대일 수도 있는데요. 저는 이렇게 유가 급등이 지속되면 미국도 굉장히 힘들 거라고 생각합니다. 인플레이션이라고 하는 건 결국 부담이 될 텐데 올 11월에 미국에 중간선거가 있는데 이 인플레이션은 정치적으로 굉장히 정치인에게 부담이 되는.◇이대호> 트럼프 대통령이 사실은 조 바이든 대통령의 물가.◆김학균> 물가 때문에 사실 정권이 넘어간 거지요. 실제로 2차 세계대전 이후로 미국이 대통령 한 번 되면 대부분 연임합니다. 그런데 연임 못한 대통령 76년도 카터에게 진 포드 대통령 인플레고요. 카터는 또 레이건한테 졌습니다. 인플레입니다. 92년 대선에서 클링턴한테 졌던 아버지 부시 인플레입니다. 그때도 이 중동 전쟁 이후에 물가가 불안했고요. 그다음에 재선 못 한 사람이 트럼프 대통령인데 2020년 선거에서는 사실 딱히 인플레이는 없었지만 코로나라든가 괴팍한 여러 가지 것들이 반영된 것 같고 이번에 정권이 넘어간 것도 저는 인플레이기 때문에 정치적으로는 되게 부담이 될 거고 경제학자들이 고통 지수라는 걸 만들었거든요. 실업률과 물가 상승률을 더한 겁니다. 실업률은 돈을 벌지 못하는 데서 오는 고통 그리고 물가 상승률은 내 돈의 상대적 가치가 구매력이 떨어지는 데서 오는 고통이니까요. 이게 장기화될지도 제 생각엔 관심 있게 봐야 될 포인트 중에 하나라고 봅니다.◇이대호> 일단 트럼프 대통령은 일시적인 고통이다. 이란의 핵 제거가 끝나면 유가는 다시 하락할 거라고 SNS에 글을 올렸습니다만.◆김학균> 2022년 시나리오지요. 단기간에 120불 갔다가 유가가 금방 떨어졌거든요.◇이대호> 신영증권의 리서치 센터장인 김학균 전무와 함께한 시간이었습니다. 도움 말씀 고맙습니다.◆김학균> 감사합니다.■ 제보하기▷ 전화 : 02-781-1234, 4444▷ 이메일 : kbs1234@kbs.co.kr▷ 카카오톡 : ''KBS제보'' 검색, 채널 추가▷ 네이버, 유튜브에서 KBS뉴스를 구독해주세요!', NULL, 'KBS', 'https://n.news.naver.com/mnews/article/056/0012137993', 'https://imgnews.pstatic.net/image/056/2026/03/09/0012137993_001_20260309152227240.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 15:21:03', 0, true, '2026-03-09 06:25:20.323299') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1155, '패닉장에 환율 1600원 공포…"펀더멘털 보면 가능성 낮아"', '[와우퀵] 투자정보 플랫폼나정환 NH투자증권 연구위원은 9일 한국경제TV에 출연해 "극도의 공포가 휘몰아치면 원·달러 환율이 1,500원대를 넘는 구간은 열릴 수 있지만, 1,600원까지 올라가는 시나리오는 가능성이 낮다"며 "현 시점에서 상단은 1,500원 초반, 1,400원 후반대 수준으로 본다"고 말했다.나 연구위원은 "미국의 강경 대응 가능성이 부각되면서 코스피가 지난주에만 12% 급락하는 등 극심한 패닉셀이 나타났다"며 "이 과정에서 환율도 1,600원까지 갈 수 있다는 공포가 커졌지만, 시장 심리가 실제 펀더멘털보다 앞서 나간 측면이 있다"고 진단했다.그러면서 "지난 1월과 2월 모두 수출 증가율이 상당히 견조하고, 한국 수출 흐름 자체가 강한 모습을 보이고 있다"며 "이런 펀더멘털을 감안하면 원·달러 환율이 1,600원대에 진입하더라도 그때는 일시적인 스파이크에 가까울 것"이라고 설명했다.나 연구위원은 "달러 인덱스가 현재 99포인트대까지 올라오긴 했지만, 100포인트를 넘어서 추세적으로 상승하는 흐름이 아니라면 환율 상단도 제한적일 수밖에 없다"며 "대외 변수로 단기 변동성은 확대되겠지만, 과도한 1,600원 공포보다는 상단이 정해진 구간이라는 인식 속에서 시장을 볼 필요가 있다"고 덧붙였다.● 핵심 포인트- 극단적 불안이 겹쳐 원·달러 환율이 1,500원을 일시적으로 넘길 수는 있어도 1,600원까지 치솟을 가능성은 낮다는 진단함.- 최근 코스피 급락과 대외 불확실성으로 환율 1,600원 공포가 커졌지만, 시장 심리가 펀더멘털보다 앞서간 측면 있음.- 1~2월 수출 증가 흐름이 견조한 만큼 한국의 펀더멘털 감안하면 1,600원대 진입은 있더라도 일시적 스파이크에 그칠 것임.- 달러 인덱스가 100선을 넘겨 추세적으로 오르지 않는다면 상단도 1,500원 초반~1,400원 후반대에서 제한될 수 있다는 평가임.● 방송 원문<앵커>더 강경한 대응을 미국이 한다면 시장의 불확실성이 더 커지고 단기적으로나마 변동성이 더욱더 확대될 수 있다.외환시장도 비슷할 것 같아요. 외환시장도 오늘(9일) 변동성이 어마어마하지 않습니까.지금 달러화에 대한 원화 환율이 1,500원대에 육박하고 있는 상황인데 1,500원을 넘어서 1,600원대도 얘기하는 시각이 있더라고요.<나정환 NH투자증권 연구위원>일단 극도의 공포가 휘몰아치면 그럴 수 있죠.1,600원 가능성은 저는 아니라고 생각을 하고 있습니다.1,500원대까지는 갈 수는 있겠지만 시장 자체가 코스피 시장에서도 보셨겠지만 지난주에 12% 하락하고 이런 극도의 패닉셀 구간이 나오다 보니까 그러면 원·달러 환율도 1,600원 갈 수 있는 거 아닌가요라고 할 수 있는데 한국의 펀더멘털 그러니까 최근 한국 수출을 보더라도 수출 자체는 상당히 견조합니다.1월도 그렇고 2월도 그렇고 수출 증가율 자체는 굉장히 강한 모습을 보이고 있어서 그런 관점에서 봤을 때는 원·달러 환율이 1,600원대로 가는 거는, 만약에 간다고 하면은 일시적인 스파이크 정도가 될 수 있겠죠.그런데 달러 지수만 보더라도 지금 99포인트대까지 올라오긴 했습니다.그런데 이게 추세적으로 100포인트 넘어서 계속 가는 수준이 아니라면 1,500원 초반대, 1,400원 후반대 이 정도 선이 상단 부분이지 않나라고 생각을 하고 있어요.', NULL, '한국경제TV', 'https://n.news.naver.com/mnews/article/215/0001244416', 'https://imgnews.pstatic.net/image/215/2026/03/09/A202603090136_20260309130611997.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 13:00:00', 0, true, '2026-03-09 06:25:25.564788') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1156, 'GC녹십자, 회사채 완판...재무 안정 ''청신호''', '/이미지 제작 = 김나영 기자GC녹십자가 회사채 시장에서 흥행을 터뜨리며 1560억원 규모의 자금을 확보했다. 수요예측에서 당초 모집 규모인 1000억원보다 6배에 달하는 5820억원의 주문이 몰리면서 최종 발행액을 1560억원으로 증액했다. 최근 실적 개선 기대감이 투자심리를 자극한 덕이 컸다는 평가가 나온다.당장 만기 도래 차입금을 상환할 단기 유동성은 확보했지만 재무구조 부담은 여전히 남아 있다는 지적도 나온다. 올해도 글로벌 혈액제제 사업 확대와 혈장센터 투자 등이 이어질 것으로 예상되면서 현금창출력 개선과 차입 규모 관리가 향후 재무 안정성의 핵심 과제로 떠오르고 있다.민평 대비 낮은 금리 확정, 실적 기대감 반영GC녹십자 회사채(45-1회, 45-2회) 발행 개요 / 자료 = 공시9일 금융감독원 전자공시시스템에 따르면 GC녹십자는 제45-1회 무보증사채(2년물) 600억원, 제45-2회 무보증사채(3년물) 960억원 등 총 1560억원 규모 공모 회사채의 발행 조건을 확정했다. 대표 주관사는 NH투자증권과 한국투자증권, 대신증권이 맡았으며 상장신청예정일은 오는 11일, 상장 예정일은 12일이다.지난 4일 진행된 수요예측에서는 총 5820억원의 주문이 몰렸다. 구체적으로 2년물에 2350억원, 3년물에 3470억원이 접수되며 경쟁률은 각각 5.88대1, 5.78대1을 기록했다. 금리는 두 만기 모두 민평 대비 -0.13%포인트(p)에서 결정됐다.시장에서는 회사채 시장이 다소 위축된 상황에서도 수요가 견조하게 형성됐다는 점에 주목하고 있다. GC녹십자는 당초 2년물 400억원, 3년물 600억원 등 총 1000억원을 모집할 계획이었으나 흥행몰이에 성공하면서 최종 발행액을 560억원 늘렸다. 자산운용사와 증권사, 보험사 등 기관 자금이 유입되면서 투자심리를 끌어올렸다는 평가다.GC녹십자 최근 5개년 실적 추이 / 자료 = 공시최근 실적 회복세도 투심을 자극한 요인으로 꼽힌다. GC녹십자는 지난해 연결 기준 매출 1조9913억원, 영업이익 691억원을 기록했다. 매출은 전년 대비 약 18.5% 증가했고 영업이익은 115%가량 늘었다. 특히 4분기에는 매출 4978억원, 영업이익 46억원을 기록하며 8년 만에 분기 기준 흑자 전환에 성공했다. 미국 시장에 진출한 면역글로불린 제제 ''알리글로(Alyglo)''가 4분기에만 5000만달러(약 720억원) 매출을 올리며 실적 개선을 견인했다.신용평가사들 역시 이 같은 회사의 수익성 개선 흐름에 주목하고 있다. 한국기업평가와 나이스신용평가는 고마진 제품 매출 확대와 매출 비중 상승으로 상각전영업이익(EBITDA) 창출력이 개선된 것으로 평가했다. 두 기관은 GC녹십자의 무보증사채 신용등급을 ''A+(안정적)''으로 유지하고 있다.GC녹십자는 이번 공모 회사채로 확보한 자금을 전액 기존 차입금 상환에 사용할 계획이다. 상환 대상은 우리은행 일반한도대출 260억원과 신한은행 무역금융 500억원 등이다. 각각 이달 25일, 17일 만기가 도래한다. 여기에 5월11일 상환 예정인 제43-2회 무보증사채 800억원도 포함됐다.올해도 시설 투자, ''적자 현금흐름'' 관리 과제다만 시장에서는 녹십자의 재무구조를 둘러싼 유동성 부담이 여전히 남아 있다고 보고 있다. 최근 몇 년간 투자 확대 영향으로 차입금과 현금흐름 지표가 악화되고 있어서다.회사의 차입금 규모는 2022년 5766억원에서 2023년 7240억원, 2024년 8281억원으로 증가했고 지난해 3분기 기준 1조229억원까지 확대됐다. 같은 기간 차입금 의존도도 22.8%에서 32.1%로 상승하며 통상 적정 수준으로 평가되는 30%를 넘어섰다.현금흐름 지표 역시 적자 부담이 늘고 있다. 녹십자의 잉여현금흐름(FCF)은 2023년 -1563억원, 2024년 -1154억원, 2025년 3분기 -443억원으로 최근 3년 연속 마이너스를 기록했다. 이는 영업활동으로 창출된 현금이 투자지출을 충분히 감당하지 못하고 있다는 의미다.이 같은 현금흐름 부담에는 알리글로의 글로벌 사업 확대를 위한 투자가 영향을 미쳤다. GC녹십자는 혈장 생산을 내재화하기 위해 2023년 12월 약 1380억원을 들여 미국 혈장센터 운영사 ABO홀딩스 지분을 전량 인수한 바 있다. 회사는 현재 ABO홀딩스를 통해 뉴저지·유타·캘리포니아 등 3개 지역에서 6곳의 혈장센터를 운영하고 있으며 올해 텍사스주에 2곳을 추가로 건설해 총 8곳으로 확대할 계획이다.업계에서는 올해도 회사가 추가적인 시설 투자를 이어가는 만큼 회사채 발행이 단기적인 상환 부담을 완화하는 효과는 있겠지만 차입 규모 관리와 현금창출력 회복 속도가 중장기 재무 부담을 좌우할 것이라는 분석이다.GC녹십자 관계자는 "2023년 이후 잉여현금흐름이 마이너스를 기록한 것은 알리글로 출시 초기 비용과 ABO홀딩스 인수 등 전략적 투자 영향이 반영돼 있다"면서 "알리글로 매출 확대와 비용 구조 개선이 이어지면서 점차 개선되는 흐름이 나타나고 있다"고 말했다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000080514', 'https://imgnews.pstatic.net/image/293/2026/03/09/0000080514_001_20260309120810250.png?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 12:02:16', 0, true, '2026-03-09 06:25:25.564788') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1157, '이수건설, 750억원 규모 신종자본증권 발행…신한인사이트제일차 매입', '이수화학 자회사 이수건설이 750억원 규모의 제131회 신종자본증권을 발행했다고 6일 공시했다. 신한인사이트제일차 주식회사가 해당 증권을 매입하며, 회사는 기발행 신종자본증권 상환 및 차입금 상환에 자금을 활용해 재무건전성을 확보한다. 만기일은 2056년 3월6일이다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000080447', 'https://imgnews.pstatic.net/image/293/2026/03/06/0000080447_001_20260306162020176.png?type=w800', 'NEWS_CHEM', NULL, '2026-03-06 16:20:20', 0, true, '2026-03-09 06:25:32.051147') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1158, '국민성장펀드 픽 이수스페셜티…"황화리튬 증설에 1천억"', '<앵커>울산에 전고체 배터리 소재 공장을 둔 이수스페셜티케미컬이 국민성장펀드를 통해 1천억 원 자금을 지원받을 예정입니다.회사 측은 초저리로 받은 자금을 황화리튬 생산 확대를 위한 공장 증설에 투입할 것으로한국경제TV 취재 결과 확인됐습니다.산업부 최민정 기자와 이야기 나눠보겠습니다.최 기자, 2차전지 기업 중 이수스페셜티케미컬이 선정된 특별한 이유가 있나요?<기자>정부가 이수스페셜티케미컬이 가진 ''황화리튬'' 기술을 키우겠다는 의지로 보입니다.황화리튬은 전고체 배터리 소재인데요.전고체 배터리 가격 경쟁력이 황화리튬에 달려 있는 만큼, 생산에 집중하는 겁니다.전고체 배터리는 전기차뿐 아니라 휴머노이드에도 쓰이는 차세대 배터리로 규모가 더 커질 전망인데요.배터리 산업을 장악하고 있는 중국도 황화리튬 기술을 갖고 있지만, 아직 국내 기업에 비해 불순물이 많다는 게 업계 관계자의 설명입니다.이수스페셜티케미컬은 지난 2020년부터 국책과제에 참여해 황화리튬 연구해 왔습니다. 관련 특허만 9건을 갖고 있습니다.오늘 (26일) 오후 국민성장펀드 운용위원회를 통해 1천억 원의 저금리 대출 지원이 확정될 예정입니다.<앵커>이수스페셜티케미칼이 자금을 어디에 사용할지도 관심인데, 생산 확대에 쓰인다구요?<기자>취재결과, 지원금 1천억 원을 공장 증설에 투입할 것으로 확인됐습니다.현재 연 40톤의 황화리튬 데모 플랜트를 운영하고 있는데요.이 공장을 내년 6월까지 150톤으로 확대할 계획입니다.약 4배 가까이 키우는 건데 국민성장펀드 지원으로 자금 부담을 덜었습니다.전고체 배터리 상용화 시점에 맞춰, 대량 생산 체계를 구축하는 건데요.이수스페셜티케미컬은 2023년 이수화학으로부터 전고체 소재 사업을 포함한 정밀화학 사업을 인적분할한 곳입니다.계열사인 이수화학의 노말파라핀(NP) 공정에서 발생하는 부산물인 황화수소 가스를 안정적으로 조달받을 수 있다는 강점이 있습니다.경쟁사의 경우 황화수소를 중국과 일본 등 해외에서 조달하는 만큼, 가격 우위를 확보할 수 있는데요.이수스페셜티케미컬이 대량 생산과 원가 절감으로 황화리튬 가격을 낮춰나갈 것으로 전망됩니다.<앵커>국내 배터리사에 황화리튬을 공급해야 이수스페셜티케미컬의 매출도 오를 텐데요. 본격적인 매출은 언제 나오나요?<기자>현재 전고체 전지를 양산 중인 국내외 고객사와 샘플 테스트를 진행하고 있습니다.황화리튬 관련 매출도 샘플 수준에 불과한데요.증권사에선 "배터리사들의 전고체 배터리 양산이 본격화되는 2027년 매출이 본격적으로 나타날 것"으로 추정합니다.주목할 점은 삼성SDI의 공급망 편입 여부인데요.LG에너지솔루션과 SK온보다 2년 먼저 삼성SDI가 전고체 상용화를 목표로 한 만큼, 삼성SDI와 협력 시 시장을 선점할 가능성이 크기 때문입니다.특히 이수스페셜티케미컬은 황화수소를 이용한 제품 생산 경험도 많습니다. 취급 숙련도도 높다는 평가를 받는데요.이를 통해 에코프로비엠과 롯데에너지머티리얼즈, 동화일렉트로라이트와 황화리튬 업무협약도 체결한 바 있습니다.<앵커>네, 잘 들었습니다.', NULL, '한국경제TV', 'https://n.news.naver.com/mnews/article/215/0001243166', 'https://imgnews.pstatic.net/image/215/2026/02/26/A202602260427_20260226143818621.jpg?type=w800', 'NEWS_CHEM', NULL, '2026-02-26 14:37:15', 0, true, '2026-03-09 06:25:32.051147') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1159, '불황에도 성장한 이수화학…스페셜티 수요가 실적 견인', '별도 영업이익 전년比 934%↑…LAB·NP, ‘수급 긴축’ 타고 반등석유화학 불황이 길어지는 가운데 이수화학이 스페셜티 제품을 앞세워 실적 반등에 성공했다.이수화학은 지난해 별도 기준 영업이익을 전년 대비 934% 증가시키며 견조한 성장세를 보였다고 19일 밝혔다. 회사에 따르면 선형알킬벤젠(LAB)과 노말파라핀(NP)의 수급 타이트 현상과 전략적 글로벌 판매망 재편이 실적 개선을 견인했다.이수화학은 지난 12일 매출액 또는 손익구조 30% 이상 변경 공시를 통해 연결 기준 매출액 1조 6566억원, 영업이익 76억원을 기록했다고 공시했다. 전년 대비 매출은 13.5% 줄었지만, 영업이익은 흑자전환했다. 별도 기준 매출은 1조 3777억원으로 전년 대비 6.6% 감소했지만, 영업이익은 전년 대비 934.2%나 증가한 297억원으로 흑자 기조를 강화했다.이번 호실적의 배경에는 급변하는 글로벌 시장 환경에 대한 선제적 대응이 있었다고 회사 측은 설명했다.이수화학 관계자는 "최근 LAB 시장은 중동·아시아 지역설비 증설과 유럽 지역 설비 폐쇄가 맞물리며 글로벌 공급망 재편이 빠르게 진행되고 있다"며 "이수화학의 글로벌 영업망이 차별화된 경쟁력으로 작용했다"고 말했다.이어 "지난해 시장 변화에 맞춘 최적화 전략으로 지역별 판매 포트폴리오를 조정하며 시장 기회를 선점했다"며 "판매망 재편 효과가 본격화됨에 따라 올해도 수익성 개선 흐름이 지속될 것으로 전망된다"고 덧붙였다.제품별로는 프리미엄 세제 수요 증가로 LAB 견조한 수요가 이어졌고, 유럽 내 에너지 부담과 정기보수로 인한 NP의 공급 부족이 가격 강세를 이끌며 수익성을 뒷받침했다. 여기에 디지털 전환(DT)을 통한 에너지 절감과 생산 효율화, NP·LAB 수직 계열화 구조가 원가 경쟁력 강화에 기여했다는 것이 회사 측 설명이다.이수화학 관계자는 “석유화학 업황이 전반적으로 침체된 상황에서도 이수화학의 LAB와 NP는 꾸준히 성장하는 스페셜티 제품으로 자리 잡았다”며 “우호적 시장 환경을 활용해 성과를 극대화하고, 고부가가치 특수 제품 비중을 확대하며 새로운 미래 성장 동력을 발굴할 것”이라고 강조했다.', NULL, '지디넷코리아', 'https://n.news.naver.com/mnews/article/092/0002410989', 'https://imgnews.pstatic.net/image/092/2026/02/19/0002410989_001_20260219101011201.jpg?type=w800', 'NEWS_CHEM', NULL, '2026-02-19 10:10:11', 0, true, '2026-03-09 06:25:32.051147') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1160, '가덕도신공항 부지조성 기본설계 착수…공단 "공기문제 없을 것"(종합)', '설명회에 업체 20여곳 참석…우선 시공분 10월 착공 목표9일 가덕도신공항건설공단에서 열린 가덕도신공항 현장설명회[손형주 기자](부산=연합뉴스) 민영규 손형주 기자 = 가덕도신공항이 부지조성공사를 위한 기본설계에 들어갔다.국토교통부와 가덕도신공항건설공단은 이날 오후 2시 부산 강서구 가덕도신공항건설공단에서 입찰 참가 자격 사전심사를 통과한 대우건설 컨소시엄(공동수급체)을 대상으로 현장설명회를 개최했다.현장설명회는 기본설계 착수를 의미한다. 이날 설명회에서는 20여곳의 업체가 참가했고 비공개로 진행됐다.사업 추진계획과 설계·시공·입찰 시 유의 사항을 중심으로 입찰안내서의 주요 내용이 공유됐다.박용남 가덕도신공항건설공단 사업총괄처장은 "사업을 본격적으로 시작하는 시점이기 때문에 공사 계획에 대해 전반적으로 소개하고 전체적인 사업의 원칙과 기준을 제시하는 자리"라고 설명했다.공단은 업체가 보유한 기술과 전문성을 최대한 활용해 가덕도신공항이 안전한 공항으로 건설될 수 있도록 최선을 다해줄 것을 강조하고, 공사 기간 등 입찰 조건 준수와 함께 조속한 사업추진에도 힘써 달라고 당부한 것으로 전해졌다.대우건설 컨소시엄은 이날부터 기본설계에 착수해 6개월 안에 마무리 짓게 된다. 이후 중앙건설기술심의위원회에서 설계 적정성 판정을 받으면 실시 설계가 6개월간 진행될 예정이다.공단은 사업에 속도를 내기 위해 울타리 조성, 현장 사무소 설치 등 우선 시공분에 대해서는 기본설계가 끝나는 시점인 10월 착공에 들어가는 것을 목표로 하고 있다.공단은 일각에서 제기되는 공사 기간에 대한 우려에 대해서도 자신감을 내비쳤다.설명회 듣는 대우건설컨소시엄[손형주 기자]박 처장은 "공사 기간은 전문가 자문과 업체 의견을 충분히 수렴했기 때문에 공기로 인해 발생할 수 있는 문제는 별로 없는 것으로 보고 있다"며 천재지변이 없는 한은 당초 계획된 일정대로 사업을 진행하는 데 큰 무리가 없을 것으로 보고 있다"고 말했다.가덕도신공항 부지조성공사는 국가 균형발전과 동남권 관문 공항 건설을 위한 대형 인프라 사업으로, 총예산액은 약 10조7천174억원 규모다.대우건설 컨소시엄 참여 기업은 19개 사로, 주관사인 대우건설(지분율 55%)을 비롯해 HJ중공업과 중흥토건(각 9%), 동부건설과 BS한양(각 5%), 두산건설(4%) 등이다.부산·경남 지역 건설사 13곳(13%)도 컨소시엄 참여사에 이름을 올렸다.youngkyu@yna.co.krhandbrother@yna.co.kr', NULL, '연합뉴스', 'https://n.news.naver.com/mnews/article/001/0015947255', 'https://imgnews.pstatic.net/image/001/2026/03/09/AKR20260309047101051_04_i_P4_20260309145913038.jpg?type=w800', 'NEWS_CONSTRUCT', NULL, '2026-03-09 14:58:41', 0, true, '2026-03-09 06:25:39.618828') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1164, '동원산업, ‘3월 7일’ 참치데이 프로모션 진행', '사진 | 동원[스포츠서울 | 조선경 기자] 동원산업이 3월 7일 참치데이를 맞아 다양한 행사를 진행한다고 밝혔다.동원산업은 오는 5일부터 11일까지 이마트 주요 점포에서 참다랑어 해체쇼를 진행하며, ‘프리미엄 참다랑어회’를 최대 30% 할인 판매한다. 현대백화점 6개 점포에선 오는 6일부터 8일까지 대뱃살, 중뱃살, 턱살 등 특수부위를 선보인다. 또한 롯데마트 제타플렉스점에선 오는 7일 참다랑어 모둠회 구매시 후토마끼 3조각을 증정한다.동원산업 네이버 브랜드스토어에선 ‘국내산 참다랑어회’를 선보인다. 구매 인증 이벤트도 진행한다. 동원산업의 참치 제품을 2만 7천원 이상 구매한 영수증을 인증해 참여할 수 있다.추첨을 통해 70만 원 상당의 고급호텔 숙박권을 비롯해 패밀리 레스토랑 상품권, 동원산업 브랜드스토어 할인 쿠폰 등을 제공한다.동원산업 관계자는 “다양한 온오프라인 마케팅을 통해 동원산업의 신선하고 건강한 수산물을 알리기 위해 노력할 것”이라고 말했다.eternal@sportsseoul.com', NULL, '스포츠서울', 'https://n.news.naver.com/mnews/article/468/0001221889', 'https://imgnews.pstatic.net/image/468/2026/03/05/0001221889_001_20260305093409477.png?type=w800', 'NEWS_ETC', NULL, '2026-03-05 09:34:09', 0, true, '2026-03-09 06:25:48.167156') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1165, '[경제 단신] GS건설, 자이 보증 끝나도 안전 지원 외', 'GS건설, 자이 보증 끝나도 안전 지원GS건설은 하자담보책임 기간이 종료된 자이(Xi) 아파트를 대상으로 안전 지원활동인 ‘자이답게, 관심깊게’를 시행한다고 4일 밝혔다. 이는 전기실, 기계실 펌프 장비 등 노후화된 공용부 및 차수막 등 주요 공용부 시설물 위주로 점검을 시행해 화재, 침수 등 대규모 피해를 선제로 예방하기 위한 점검활동이다. 입주자대표회의와 사전 협의를 통해 일정을 정한 뒤 GS건설과 사후서비스(AS) 전문업체 자이S&D의 전문가들이 파견돼 단지 공용부를 점검하고 결과를 보고서 형태로 입주자대표회의에 전달한다. 입주민 요청이 있으면 아파트 운영·관리업체에 점검 결과와 관련한 설명과 교육 등 자문도 진행할 계획이다.롯데百 봄맞이 뷰티 축제 26곳 참여롯데백화점은 본격적인 봄의 시작과 함께 뷰티 수요를 선점하기 위해 6일부터 15일까지 뷰티 페어 ‘겟 레디 포 뷰티’를 전점에서 진행한다. 롯데백화점은 이번 행사를 위해 럭셔리 뷰티 브랜드와의 파트너십을 더욱 강화했다. ‘샤넬 뷰티’와 최근 뷰티 시장에서 큰 주목을 받고 있는 ‘프라다 뷰티’가 신규로 합류하며 탄탄한 브랜드 라인업을 완성했다. 이 외에도 ‘디올’, ‘에스티로더’, ‘조말론 런던’ 등 26개 브랜드가 참여해 고객에게 스킨케어부터 메이크업, 프리미엄 향수까지 폭넓은 선택지를 제공한다.동원산업 참치데이 맞아 프로모션 진행동원산업이 7일 참치데이를 맞아 주요 유통 경로와 브랜드스토어에서 다양한 행사를 진행한다. 5~11일까지 이마트 주요 점포에서 참다랑어 해체쇼를 진행하며, ‘프리미엄 참다랑어회’를 최대 30% 할인판매한다. 현대백화점 6개 점포에선 6~8일까지 오도로(대뱃살), 중도로(중뱃살), 가마(턱살) 등 특수부위를 선보인다. 롯데마트 제타플렉스점에선 7일 참다랑어 모둠회 구매 시 후토마키 3조각을 증정한다. 동원산업 네이버 브랜드스토어에선 국내 연안에서 잡힌 참다랑어를 급속 냉동해 먹기 좋은 형태로 손질한 ‘국내산 참다랑어회’를 선보인다.', NULL, '세계일보', 'https://n.news.naver.com/mnews/article/022/0004110266', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2026-03-05 05:02:12', 0, true, '2026-03-09 06:25:48.167156') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1166, '화승인더스트리, 1주당 206원 현금배당', '화승인더스트리는 결산배당으로 1주당 206원의 현금배당을 결정했다고 23일 공시했다. 배당금 총액은 98억원이며 시가배당률은 5.3%다. 배당기준일은 2025년12월31일이다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000079760', 'https://imgnews.pstatic.net/image/293/2026/02/23/0000079760_001_20260223142106329.png?type=w800', 'NEWS_CONSUMER', NULL, '2026-02-23 14:21:06', 0, true, '2026-03-09 06:25:56.677940') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1167, '화승인더스트리, 영업익 766억…전년比 35.2% 감소', '화승인더스트리는 2025년 매출 1조7810억원, 영업이익 766억원을 각각 기록했다고 19일 공시했다. 매출은 전년 대비 4.6% 소폭 감소함 반면 영업이익은 35.2% 줄었다.회사 측은 대외 불확실성으로 인해 수익성이 악화됐다고 설명했다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000079598', 'https://imgnews.pstatic.net/image/293/2026/02/19/0000079598_001_20260219153422773.png?type=w800', 'NEWS_CONSUMER', NULL, '2026-02-19 15:34:22', 0, true, '2026-03-09 06:25:56.677940') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1168, '기업공시[12월 16일]', '[서울경제]<코스피 공시>▲화승인더(006060)=계열사 화승비나에 대해 369억 원 규모 채무보증 결정 ▲STX=대출원금 116억 원 규모 대출원리금 연체사실 발생, 연체사유 상환자금 부족 ▲한화=김우석 대표이사 신규 선임<코스닥 공시>▲제이스텍=해외 360억 원 규모 2차전지 제조용 설비 공급계약 체결 ▲딥노이드=주주배정 유상증자로 신주 683만 5444주 발행, 197억 원 규모, 신주 상장 예정일 12월 30일 ▲엠게임=기취득 자사주 34만 1303주 소각 결정 ▲JW신약=266만 977주 무상증자 결정, 신주 배정 기준일 2026년 1월 2일', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004568037', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_CONSUMER', NULL, '2025-12-16 16:52:14', 0, true, '2026-03-09 06:25:56.677940') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1169, '오징어값 비상에…명태 잡던 대기업 배까지 남미 급파', '한경PRICE온난화에 한반도 어획량 급감중소원양업계 보호 목적으로대기업 진출 막아왔지만 한계3년 전 1마리 5000원대에서8000원 육박하자 ''빗장'' 풀어정부, 원양어업 조업 규제 완화사진=게티이미지뱅크해수온 상승으로 한반도 인근 바다의 오징어 어획량이 급감하자 정부가 가격 안정을 위해 원양 조업을 확대하기로 했다. 국내에서만 팔아야 한다는 조건으로 해외 먼바다 오징어잡이를 추가 허용하는 방식이다. 정부는 이번 조치로 연간 8000톤(t)의 오징어를 더 잡을 수 있을 것으로 기대하고 있다.◇ “중소업체 눈치 볼 상황 아냐”5일 정부와 업계에 따르면 해양수산부는 조만간 브라질과 아르헨티나의 동쪽 바다 남서대서양에서 오징어 조업 허가를 늘려주기로 했다. 해양수산부 관계자는 “오징어값이 크게 오르면서 정부가 물량 확보를 최우선 목표로 두고 규제를 완화할 계획”이라며 “기업 규모를 따지지 않고 원양 어획을 허용해주기로 했다”고 말했다.정부가 오징어 확보전에 나선 이유는 바닷물 온도 상승으로 연근해 어획량이 빠르게 줄면서 가격 상승 압력이 커지고 있기 때문이다. 국가데이터처 어업생산동향에 따르면 연근해에 잡힌 오징어는 2021년 6만851t에서 2025년에는 3만976t으로 급감했다. 원양어업으로 확보한 오징어도 같은 기간 6만8301t에서 5만3595t으로 줄었다.오징어 공급 감소에 가격은 수년째 상승세다. 한국농수산식품유통공사에 따르면 연근해 오징어 소매가격은 2022년 1마리당 평균 5659원에서 올해는 7849원까지 올랐다. 원양 오징어도 4046원에서 5000원대로 올라섰다. 업계 관계자는 “그동안 중소원양어업 회사들의 이권을 보호해준다는 명목으로 경쟁을 제한했는데 정부가 오징어 수급 상황을 심각하게 받아들이는 것 같다”며 “정부가 이런저런 눈치 볼 것 없이 당장에 선박을 보내려 한다”고 전했다.◇ 동원 세종호 등 4척 투입새로 투입되는 배는 모두 4척이다. 동원산업의 세종호를 비롯해 남북수산 남북호, 사조오양 제99오양호, 한성기업 준성호 등이다. 이들 선박은 명태나 크릴을 잡고 있는데 남극 지역에 머물러고 있어 오징어 어장과 가까운 크릴조업선 세종호가 가장 먼저 나설 예정이다.원양 트롤선(저인망 어선)의 오징어 평균 생산량을 감안할 때 1척에 2000t씩 연간 최대 8000t의 오징어를 추가 확보할 수 있을 것으로 기대된다. 이들이 잡아오는 오징어는 다른 나라로 수출하지 않고 전량 국내로 들여오기로 했다.오징어잡이 배를 보낼 지역은 남미의 동해로 유엔 식량농업기구(FAO) 41 해구다. 러시아 땅보다 넓은 해역으로 영양분이 풍부한 포클랜드 해류와 브라질 해류가 만나 수산자원이 풍부하다. 오징어는 물론 메로, 대구, 새우 등 연간 200만t 규모의 수산물이 잡힌다.이곳의 특징은 북태평양이나 남태평양과 달리 지역을 총괄 관리하는 지역수산기구(RFMO)가 없다는 것이다. 국제적 조업 쿼터가 없다 보니 먼저 잡는 사람이 임자다. 중국 등 전세계에서 수백 척의 오징어잡이 배들이 불야성을 이루며 어획전쟁이 벌어지는 이유다. 업계 관계자는 “중국 어선들이 아무런 제한 없이 오징어를 잡아 한국에 수출하는 사례가 허다하다”며 “국내 업체들이 조금 더 공격적으로 어업 활동을 벌여도 괜찮은 상황”이라고 말했다.정부는 FAO 41 해구에 오징어조업선을 추가 투입하면서 어획 히스토리가 생기는 점도 긍정적으로 평가하고 있다. 해양수산부 관계자는 “만일 미래에 FAO 41 해구 지역수산관리기구(RFMO)가 설립되고 어획량 쿼터가 생긴다면 지금부터 어업 활동을 근거로 더 많은 어획권을 요구할 수 있을 것”이라고 말했다.', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005248389', 'https://imgnews.pstatic.net/image/015/2026/02/08/0005248389_001_20260213165612839.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-08 16:37:09', 0, true, '2026-03-09 06:26:04.072179') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1170, '[단독] "왜 이리 비싸?" 오징어값 급등에…정부, 특단의 조치', '정부, 원양 어선 규제 풀고 8000t 긴급 수혈기후변화發 오징어 가격 급등2년새 마리당 5000원→7000원대해수부 "가격 안정 위해 규제 완화"동원 세종호 등 원양선박 긴급 출동''남미 동해''에 4척 새 투입전량 국내 반입 예정사진=게티이미지뱅크해수온 상승으로 한반도 인근 바다의 오징어 어획량이 급감하자 정부가 가격 안정을 위해 원양 조업을 확대하기로 했다. 국내에서만 팔아야 한다는 조건으로 해외 먼바다 오징어잡이를 추가 허용하는 방식이다. 정부는 이번 조치로 연간 8000톤(t)의 오징어를 더 잡을 수 있을 것으로 기대하고 있다.◆“중소업체 눈치 볼 상황 아냐”사진=연합뉴스6일 정부와 업계에 따르면 해양수산부는 조만간 브라질과 아르헨티나의 동쪽 바다 남서대서양에서 오징어 조업 허가를 늘려주기로 했다. 해양수산부 관계자는 “오징어값이 크게 오르면서 정부가 물량 확보를 최우선 목표로 두고 규제를 완화할 계획”이라며 “기업 규모를 따지지 않고 원양 어획을 허용해주기로 했다”고 말했다.정부가 오징어 확보전에 나선 이유는 바닷물 온도 상승으로 연근해 어획량이 빠르게 줄면서 가격 상승 압력이 커지고 있기 때문이다. 통계청 어업생산동향에 따르면 연근해에 잡힌 오징어는 2021년 6만851t에서 2025년에는 3만976t으로 급감했다. 원양어업으로 확보한 오징어도 같은 기간 6만8301t에서 5만3595t으로 줄었다. 현재 국내 원양조업용 오징어잡이 배 40척이 잡아들이는 양이다.오징어 수요가 탄탄한 상황에서 어획량이 감소하다 보니 가격은 수년째 상승 일변도다. 한국농수산식품유통공사에 따르면 연근해 오징어 소매가격은 2022년 1마리당 평균 5659원에서 올해는 7849원까지 올랐다. 원양 오징어도 4046원에서 5000원대로 올라섰다.업계 관계자는 “그동안 중소원양어업 회사들의 이권을 보호해준다는 명목으로 경쟁을 제한했는데 정부가 오징어 수급 상황을 심각하게 받아들이는 것 같다”며 “정부가 이런저런 눈치 볼 것 없이 당장에 선박을 보내려 한다”고 전했다.◆동원 세종호 등 4척 투입동원산업 원양어선 (사진=한경DB)새로 투입되는 배는 모두 4척이다. 동원산업의 세종호를 비롯해 남북수산 남북호, 사조오양 제99오양호, 한성기업 준성호 등이다. 이들 선박은 명태나 크릴을 잡고 있는데 남극 지역에 머물러고 있어 오징어 어장과 가까운 크릴조업선 세종호가 가장 먼저 나설 예정이다.원양 트롤선(저인망 어선)의 오징어 평균 생산량을 감안할 때 1척에 2000t씩 연간 최대 8000t의 오징어를 추가 확보할 수 있을 것으로 기대된다. 이들이 잡아오는 오징어는 다른 나라로 수출하지 않고 전량 국내로 들여오기로 했다. 정부는 원양산업발전법에 따른 공해상 조업 허가를 즉시 내주겠다는 계획이다.오징어잡이 배를 보낼 지역은 남미의 동해로 유엔 식량농업기구(FAO) 41 해구다. 러시아 땅보다 넓은 해역으로 영양분이 풍부한 포클랜드 해류와 브라질 해류가 만나 수산자원이 풍부하다. 오징어는 물론 메로, 대구, 새우 등 연간 200만t 규모의 수산물이 잡힌다.이곳의 특징은 북태평양이나 남태평양과 달리 지역을 총괄 관리하는 지역수산기구(RFMO)가 없다는 것이다. 국제적 조업 쿼터가 없다 보니 먼저 잡는 사람이 임자다. 중국 등 전세계에서 수백 척의 오징어잡이 배들이 불야성을 이루며 어획전쟁이 벌어지는 이유다. 업계 관계자는 “중국 어선들이 아무런 제한 없이 오징어를 잡아 한국에 수출하는 사례가 허다하다”며 “국내 업체들이 조금 더 공격적으로 어업 활동을 벌여도 괜찮은 상황”이라고 말했다.정부는 FAO 41 해구에 오징어조업선을 추가 투입하면서 어획 히스토리가 생기는 점도 긍정적으로 평가하고 있다. 해양수산부 관계자는 “만일 미래에 FAO 41 해구 지역수산관리기구(RFMO)가 설립되고 어획량 쿼터가 생긴다면 지금부터 어업 활동을 근거로 더 많은 어획권을 요구할 수 있을 것”이라고 말했다.', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005247803', 'https://imgnews.pstatic.net/image/015/2026/02/06/0005247803_001_20260206103912114.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-06 10:03:15', 0, true, '2026-03-09 06:26:04.072179') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1171, '[서울데이터랩]‘미래에셋생명’ 29.98% 상한가…실시간 상승률 1위', '5일 오전 9시 10분 미래에셋생명(085620)이 등락률 +29.98%로 상승률 1위를 차지했다. 미래에셋생명은 개장 직후 5분간 20만 8941주가 거래되었으며 주가는 공모가 대비 3130원 오른 1만 3570원이다.한편 미래에셋생명의 PER은 13.04로 상대적으로 저평가를 받고 있을 가능성을 시사하며, ROE는 4.88%로 수익성이 낮다고 보기에는 무리가 있는 준수한 수준이나 고성장 기업과 비교했을 때는 보통 수준일 수 있다.이어 상승률 2위 아이엠에셋 200(0007N0)은 현재가 9만 7225원으로 주가가 25.61% 폭등하고 있다. 상승률 3위 삼아알미늄(006110)은 현재 2만 9800원으로 20.65% 급등하며 강세를 보이고 있다. 상승률 4위 SK증권(001510)은 19.06% 급등하며 1768원에 거래되고 있다. 상승률 5위 한전기술(052690)은 18.13%의 상승세를 타고 15만 7000원에 거래되고 있다.6위 에이엔피(015260)는 현재가 511원으로 18.01% 상승 중이다. 7위 일동제약(249420)은 현재가 3만 4950원으로 17.68% 상승 중이다. 8위 SK증권우(001515)는 현재가 3200원으로 16.79% 상승 중이다. 9위 한미반도체(042700)는 현재가 30만 2000원으로 16.60% 상승 중이다. 10위 자화전자(033240)는 현재가 3만 6000원으로 16.13% 상승 중이다.이밖에도 상상인증권(001290) ▲15.63%, 삼성전기(009150) ▲15.59%, 미래에셋증권(006800) ▲15.40%, 신대양제지(016590) ▲15.03%, 대덕전자(353200) ▲14.83%, 한화갤러리아우(45226K) ▲14.58%, 현대건설(000720) ▲14.42%, 삼성SDI우(006405) ▲14.36%, 삼성전기우(009155) ▲14.03%, 신성이엔지(011930) ▲13.81% 등을 기록하며 시장에서 활발히 거래되고 있다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003623053', 'https://imgnews.pstatic.net/image/081/2026/03/05/0003623053_001_20260305092612787.png?type=w800', 'NEWS_ETC', NULL, '2026-03-05 09:26:12', 0, true, '2026-03-09 06:26:09.951057') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1196, '[단독] ''이란 쇼크''에 화학업계 본격 감산 시작…"수급 대란 대비"', '3D 프린팅된 석유통과 이란 지도 /사진=뉴스1국내 주요 석유화학 기업들이 감산 움직임을 본격화하고 있다. 미국·이스라엘과 이란 간 전쟁이 2주째에 접어든 상황 속에서 ''원료 대란'' 리스크에 대한 선제 대응에 나선 것이다.9일 관련 업계에 따르면 울산 산단의 화학사들(SK지오센트릭·대한유화·S-OIL) 중 일부가 가동률 조정에 들어간 상황으로 확인됐다. 가동률 80~ 90% 수준을 유지하던 한 화학사의 경우 최근 원유와 나프타 수급 상황을 고려해 가동률을 낮추기로 결정했다. 이란 사태가 장기간 지속되면 설비 가동률이 60% 이하 수준까지 떨어질 가능성이 제기되고 있다.여수 산단 기업들도 이번주 내로 이란 사태가 진정되지 않을 경우 본격적인 가동률 조정에 나선다는 방침이다. 특히 이곳의 롯데케미칼 설비는 정기 보수를 앞두고 있어 추가적인 감산이 이뤄질 예정이다. 여천NCC는 지난 4일 고객사에 "호르무즈해협 봉쇄로 3월 인도 예정이었던 원료 납사의 도착이 크게 지연돼 제품을 공급하지 못할 수 있다"며 ''공급 불가항력''을 선언했다.울산 산단 화학사의 한 관계자는 "회사 차원에서 감산 기조에 들어간 상태"라며 "이번달까지는 대부분 버틸 수 있겠지만 다음달부터 원료 수급 대란이 벌어질 가능성도 있어 미리 대비하고 있다"고 설명했다. 여수에 위치한 화학사 관계자 역시 "산단 내 기업들 대부분 가동률 하향조정을 검토하는 상황"이라고 전했다.지난달 28일 발발한 이란 사태의 직격탄을 화학 업계가 맞은 모양새다. 이란이 호르무즈 해협을 봉쇄한 이후 화학 산업의 필수재인 나프타와 원유 수급이 불안해졌기 때문이다. 그동안 국내로 들어오는 수입 나프타의 54% 가량이 호르무즈 해협을 통과해왔다. 전체 원유 수입에서 중동이 차지하는 비중은 70%에 달했다. 이란 사태 이후 나프타 가격은 23% 급등한(지난 5일 기준) 것으로 파악되고 있고, 국제 유가는 배럴당 100달러를 넘기 시작했다.문제는 호르무즈 해협이 언제 열릴지 모른다는 점이다. 국내 석유화학 기업들은 석화 제품의 원료인 납사를 1개월 분량 정도 비축한 상황이다. 산업의 근간을 이루는 화학제품들의 감산폭이 커진다면 전자, 건설, 자동차, 유통, 생필품 등 각종 업종까지 영향을 받을 수밖에 없다. 화학 업계 관계자는 "지난달 확보한 물량으로 이번 달까지는 버틸 수 있겠지만 장기전으로 갈 경우 어려움이 커질 것"이라고 말했다.', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005327129', 'https://imgnews.pstatic.net/image/008/2026/03/09/0005327129_001_20260309133509294.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-03-09 11:07:09', 0, true, '2026-03-09 06:27:29.952135') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1172, '한앤코, SK이터닉스 태그얼롱 행사…분할매각 전략 통했다', '2018년부터 SK디앤디 2800억 투자…이터닉스 지분 매각만으로 2500억 회수한앤코, "신재생사업 가치평가 불리" 인적분할 적극 제안…이터닉스 분할로 이어져이 기사는 03월 06일 11:13마켓인사이트에 게재된 기사입니다.사진=연합뉴스한앤컴퍼니가 SK이터닉스 보유 지분 전량에 대한 태그얼롱(동반매도참여권)을 행사하며 SK디앤디 투자금 상당액을 회수했다. 한앤코는 2018년부터 SK디앤디에 총 2800억원을 투자했다. SK디앤디에서 인적분할된 SK이터닉스 투자금은 완전히 회수하고, SK디앤디는 단일 최대주주로 올라섰다.6일 투자은행(IB)업계에 따르면 한앤코는 SK이터닉스 최대주주 SK디스커버리가 지분 30.1%(1045만5825주)를 글로벌 사모펀드(PEF) KKR에 주당 2만3700원에 매각하는 거래에서 태그얼롱을 행사했다. 태그얼롱은 최대주주가 보유 지분을 매각할 때 2대 주주가 동일한 가격으로 팔아달라고 요구할 수 있는 권리를 뜻한다. 태그얼롱 행사 대상 주식은 422만5455주(12.5%)로, 한앤코는 이번 권리 행사를 통해 1000억원을 회수했다.SK이터닉스는 2024년 3월 SK디앤디 신재생 사업 부문이 인적분할돼 설립된 회사다. 한앤코는 2018년부터 SK디앤디에 총 2800억원을 투자했다. 최초 투자 당시 최창원 부회장과 SK가스가 보유한 구주 27.5%어치를 인수하고 같은 해 진행된 주주배정 유상증자에도 참여해 2275억원을 투입했다. 이후 2020년 5월 이뤄진 유상증자에도 참여해 511억원을 추가 투자하고 지분율을 31%까지 늘렸다.SK디앤디의 SK이터닉스 인적 분할은 한앤코의 적극적인 권유가 촉매제가 됐다. 한앤코는 SK디앤디 내 성장 산업인 신재생에너지 부문과 성숙 산업인 부동산 부문이 병존하는 구조에서는 각 사업의 가치가 시장에서 충분히 평가받기 어렵다고 판단했다. 이에 복합기업 디스카운트를 해소하고 사업별 전문성을 강화하기 위해 인적 분할을 적극 제안했다. 2024년 실제 분할이 이뤄지며 SK이터닉스의 기업가치 재평가가 이뤄졌다.이후 한앤코는 SK이터닉스 블록딜(시간외 대량매매)을 두 차례 단행하며 투자금을 회수하기 시작했다. 2024년 5월 지분 9%를 블록딜로 매도하며 692억원을 회수한 데 이어 이듬해 6월엔 9.5%를 매도해 822억원을 회수했다. SK이터닉스 지분 매도만으로 SK디앤디 투자 상당액을 거둬들였다.한앤코는 인적분할 존속법인 SK디앤디엔 추가 투자에 나선 상태다. 작년 10월 SK디스커버리가 보유한 SK디앤디 지분 31%를 742억원에 인수하고 상장폐지를 위한 두 차례 공개매수를 진행했다. 현재 한앤코의 SK디앤디 지분율은 47.4%다.', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005259711', 'https://imgnews.pstatic.net/image/015/2026/03/09/0005259711_001_20260309094511640.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 09:45:11', 0, true, '2026-03-09 06:26:15.471271') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1173, '[주간사모펀드] 어피니티, SK렌터카 매각 추진…롯데렌탈 인수 승부수', 'IMM PE, 대웅 계열 시지바이오 인수 추진KKR, SK이터닉스 인수 본격화어피니티에쿼티파트너스가 롯데렌탈 인수를 위해 보유 중인 SK렌터카 매각을 검토하고 있다. /롯데렌탈[더팩트ㅣ박지웅 기자] 글로벌 사모펀드(PEF) 운용사 어피니티에쿼티파트너스가 보유 중인 SK렌터카를 매각하는 방안을 검토하고 있다. 공정거래위원회의 기업결합 제동으로 롯데렌탈 인수가 막히자, 보유 자산을 정리해 인수 승인을 받기 위한 전략 수정에 나선 것이다.◆공정위 독과점 제동에 전략 수정…1위 사업자 인수 위해 2위 매각 검토7일 투자은행(IB) 업계에 따르면 어피니티는 SK렌터카 매각을 전제로 롯데렌탈 인수를 추진하는 방안을 내부적으로 검토 중이다. 공정위가 렌터카 업계 1·2위 사업자인 롯데렌탈과 SK렌터카를 동시에 보유할 경우 경쟁 제한 우려가 크다고 판단해 기업결합을 불허하자 전략을 바꾼 것으로 전해진다. 어피니티 관계자는 "아직 결정된 바 없다"고 입장을 밝혔다.어피니티는 2024년 8월 SK렌터카 지분 100%를 약 8200억원에 인수한 데 이어, 지난해 3월 호텔롯데 등이 보유한 롯데렌탈 지분 56.17%를 1조5730억원에 사들이는 계약을 체결했다. 렌터카 시장 1·2위 사업자를 동시에 확보해 ''규모의 경제''를 구축하려는 전략이었다. 그러나 공정위의 제동으로 거래가 멈추자, 2위 사업자인 SK렌터카를 정리하고 1위 사업자 인수에 집중하는 방향으로 선회했다는 분석이다.시장에서는 공정위가 일정 기간 내 SK렌터카 매각을 조건으로 롯데렌탈 인수를 승인하는 조건부 승인 가능성을 점치고 있다. 실제 2020년 독일 딜리버리히어로(DH)가 ''배달의민족'' 인수를 추진할 당시에도 기존에 운영하던 ''요기요'' 매각을 조건으로 기업결합을 허용한 사례가 있다.SK렌터카가 다시 매물로 나오면 국내외 PEF와 전략적 투자자(SI)들의 관심이 이어질 것으로 예상된다. 2024년 SK그룹이 매각을 추진했을 당시에도 IMM프라이빗에쿼티와 글랜우드PE 등이 인수전에 참여한 바 있다. 업계에서는 렌터카 사업 확대를 검토 중인 현대자동차그룹 역시 잠재적 인수 후보로 거론된다.IMM프라이빗에쿼티가 대웅그룹 계열 바이오 기업 시지바이오 인수를 추진하고 있다. /시지바이오◆IMM PE, 대웅 계열 시지바이오 인수 추진…6000억원 수준PEF 운용사 IMM프라이빗에쿼티(PE)가 대웅그룹 계열 바이오 재생의료 기업 시지바이오 인수를 추진한다. 바이오·헬스케어 투자 확대 전략의 일환으로 풀이된다.IB업계에 따르면 IMM PE는 최근 시지바이오 인수 우선협상대상자로 선정돼 실사 절차에 들어갔다. 인수 대상은 시지바이오 최대주주인 에이하나가 보유한 경영권 지분 51%로, 시장에서는 거래 규모를 약 6000억원 수준으로 보고 있다. 양측은 현재 실사 일정을 조율 중이며 상반기 내 거래 마무리를 목표로 협상을 진행 중인 것으로 전해졌다.시지바이오는 대웅그룹 내 재생의료 사업을 담당하는 기업으로 골대체재 등 바이오 재생의료 제품을 개발·생산하고 있다. 최근에는 미용·성형 분야로 사업 영역을 확대하며 글로벌 시장 진출을 추진하고 있다.IMM PE는 바이오 투자 경험도 보유하고 있다. 2020년 합성의약품 전문기업 제뉴원사이언스를 약 3200억원에 인수한 뒤 2024년 맥쿼리자산운용에 약 6200억원에 매각하며 성공적인 투자 회수 사례를 만든 바 있다. IB업계에서는 IMM PE가 시지바이오의 재생의료 기술과 미용 시장 성장성을 고려해 투자에 나선 것으로 보고 있다.KKR이 SK그룹 신재생에너지 계열사 SK이터닉스 인수 절차에 착수했다. /SK이터닉스◆KKR, SK이터닉스 인수 본격화…최대주주 지분 2478억 인수글로벌 사모펀드 운용사 콜버그크래비스로버츠(KKR)이 SK그룹의 신재생에너지 계열사 SK이터닉스 인수 절차에 본격 착수했다.IB업계에 따르면 SK이터닉스는 최대주주인 SK디스커버리가 보유한 보통주 약 1045만5825주(지분율 30.98%)를 약 2478억원에 매각하는 안건을 이사회에서 승인했다. 양수인은 KKR이 지분 인수를 위해 설립한 특수목적법인(SPC)인 ''Eclipse Holdco L.P.''로, 거래 종결 예정일은 오는 6월 30일이다.거래가 완료되면 KKR은 SK이터닉스의 최대주주로 올라서게 된다. 앞서 SK그룹은 지분 매각을 위한 우선협상대상자로 KKR을 선정하며 경영권 매각 절차를 진행해왔다.SK이터닉스는 2008년 SK디앤디 사업부에서 출발해 2024년 인적분할로 독립한 신재생에너지 기업이다. 태양광 발전과 에너지저장장치(ESS) 사업을 중심으로 전국에 발전소와 설비를 운영하고 있으며 최근 인공지능(AI) 기반 운영 솔루션 도입 등 사업 확장에 나서고 있다.이번 거래는 SK그룹이 진행 중인 에너지 사업 포트폴리오 재편의 일환으로 풀이된다. 시장에서는 SK이노베이션 E&S와 SK에코플랜트의 신재생에너지 사업 매각 가능성도 거론되면서 관련 자산 재편 작업이 이어질 것으로 보고 있다.발로 뛰는 더팩트는 24시간 여러분의 제보를 기다립니다.▶카카오톡: ''더팩트제보'' 검색▶이메일: jebo@tf.co.kr▶뉴스 홈페이지: http://talk.tf.co.kr/bbs/report/write', NULL, '더팩트', 'https://n.news.naver.com/mnews/article/629/0000478919', 'https://imgnews.pstatic.net/image/629/2026/03/07/20265044177278019000_20260307000147778.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-07 00:01:47', 0, true, '2026-03-09 06:26:15.471271') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1174, 'SK디스커버리·한앤코, SK이터닉스 지분 매각…2478억 규모', 'SK이터닉스가 운영 중인 풍력 발전소. 사진=SK이터닉스SK디스커버리가 6일 이사회를 열고 회사가 보유한 SK이터닉스 주식 1045만5825주를 글로벌 투자회사 KKR이 운용하는 펀드가 설립한 법인 ''Eclipse Holdco L.P.''에 매각하기로 했다고 밝혔다.이번 매각은 SK디스커버리가 보유한 SK이터닉스 지분 전량(30.98%)에 해당하며 처분 금액은 2478억원이다.SK이터닉스 지분 12.52%를 보유한 한앤컴퍼니 역시 보유 지분 전량인 422만5455주를 1001억원에 매각하기로 했다.SK디스커버리는 신재생에너지 사업 특성을 고려해 이번 매각을 결정했다고 설명했다. 신재생에너지 사업은 인프라 구축에 장기간이 소요되고 이후 전력 판매 등을 통해 점진적으로 투자금을 회수하는 구조가 일반적이어서 대규모 장기 투자가 필요하다는 판단에서다.이날 이사회에서는 자사주 매입·소각과 배당 정책을 포함한 중기 주주가치 제고 계획도 함께 의결됐다.SK디스커버리는 향후 3년간 총 600억원 규모의 자사주를 추가로 매입해 소각할 계획이다.신탁계약 방식을 통해 올해 200억원, 이후 2년간 약 400억원을 순차적으로 매입·소각한다는 방침이다.중기 배당정책도 제시했다. 연간 주당 최소 배당금을 1700원으로 설정하고, 경영목표 달성 여부에 따라 특별배당을 검토하기로 했다.또 유가증권시장 평균 배당수익률을 고려해 전년 대비 배당 규모를 점진적으로 확대하는 방향을 지향한다.이번 계획은 2023년 발표한 중기 주주가치 제고 계획의 연장선이다. SK디스커버리는 지주회사 전환 이후 약 900억원 규모(보통주 기준 약 191만주)의 자사주를 매입했으며 이 가운데 30만주를 제외한 대부분을 소각했다.SK디스커버리 관계자는 “성장성과 지속가능성을 종합적으로 고려해 사업 포트폴리오를 최적화하고 신규 성장 동력 발굴을 위한 다양한 방안에 대한 검토를 지속해 기업 가치를 제고해 나갈 것”이라며 “자사주 매입·소각과 배당 정책을 투명하게 공개하고 이를 성실히 이행하는 등 주주가치 제고를 위한 다양한 노력을 기울일 계획”이라고 밝혔다.한편 SK디스커버리는 최근 보통주 1주당 1500원, 우선주 1550원의 현금배당을 결정했다.해당 안건은 오는 26일 열리는 정기 주주총회에서 확정될 예정이다.', NULL, '한경비즈니스', 'https://n.news.naver.com/mnews/article/050/0000103242', 'https://imgnews.pstatic.net/image/050/2026/03/06/0000103242_001_20260306175612470.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-06 17:56:12', 0, true, '2026-03-09 06:26:15.471271') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1175, '[서울데이터랩]금일 코스피 거래량 1위 서울식품 거래대금 578억 돌파', '코스피 주요 종목들이 다양한 주가 흐름을 보이고 있다.24일 한국거래소에 따르면 서울식품(004410)이 2억 3000만주 이상 거래되며 코스피 종목 중 실시간 거래량 1위를 기록하고 있다. 현재 주가는 254원이며 시가총액의 5.84%에 달하는 거래대금을 기록하면서 13.90% 급등하고 있다. PER은 -36.29, ROE는 -12.02로 매수세가 강하게 유입되고 있다. SG세계물산(004060)은 7.06% 하락한 706원으로 거래되고 있으며 1억 1000만주 이상 거래량을 기록하고 있다.대원전선(006340)은 6680원으로 22.79% 폭등하며 거래량 1억 891만주를 기록하고 있다. 에이프로젠(007460)은 534원으로 27.14% 폭등하며 8760만주가 거래되고 있다. KEC(092220)는 29.96% 상한가를 기록하며 주가는 1028원으로 5448만주가 거래되고 있다. 한국ANKOR유전(152550)은 280원으로 1.45% 상승하며 4988만주가 거래되고 있다. 에이프로젠바이오로직스(003060)는 417원으로 12.40% 상승하며 3353만주가 거래되고 있다. 한화생명(088350)은 5270원으로 11.73% 급락하며 2604만주가 거래되고 있다. 한온시스템(018880)은 4555원으로 1.41% 하락하고 있으며 1858만주가 거래되고 있다. 삼성전자(005930)는 19만 9500원으로 3.37% 상승하며 거래량 1643만주를 기록하고 있다.한편 거래량 상위 20위권 종목들은 에이엔피(015260) ▲12.42%, SK증권(001510) ▼0.36%, 메타케어(118000) ▲18.61%, 부광약품(003000) ▲9.50%, 흥아해운(003280) ▼1.93%, 한국전자홀딩스(006200) ▲26.10%, 대창(012800) ▲4.38%, 신성이엔지(011930) ▲4.55%, SK네트웍스(001740) ▲11.43%, 한화투자증권(003530) ▼3.35% 등의 성적을 기록했다.주목할 만한 종목으로는 대원전선과 에이프로젠이 있다. 대원전선은 22.79% 폭등하며 거래량과 거래대금이 모두 시가총액 대비 높은 비율을 차지하고 있다. 에이프로젠은 27.14%의 폭등률을 기록하며 상당한 거래량을 보이고 있다. 반면 SG세계물산과 한화생명은 각각 7.06%와 11.73% 하락하며 주가가 하락세를 보이고 있다.전체적으로 코스피 시장은 다양한 등락을 보이며 개별 종목에 따라 투자자들의 집중이 달라지고 있다. 특히 급등 종목들이 거래량과 거래대금을 동반하여 시장의 관심을 받고 있다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003620343', 'https://imgnews.pstatic.net/image/081/2026/02/24/0003620343_001_20260224133218850.png?type=w800', 'NEWS_ETC', NULL, '2026-02-24 13:32:18', 0, true, '2026-03-09 06:26:24.046743') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1176, '[제주경제소식] ''대만 시장 정조준'' 팸투어 마무리', '지난 6일 대만 관광업계 관계자를 대상으로 열린 ''트래블 마트''.(제주관광공사 제공. 재판매 및 DB 금지)(제주=뉴스1) 홍수영 기자 = 제주도와 제주관광공사, 한국관광공사 타이베이지사, 진에어는 대만 아웃바운드 여행 시장을 겨냥해 고부가가치 상품개발 팸투어를 진행했다.9일 제주도 등에 따르면 5~9일 열린 팸투어에는 대만 주요 여행사 및 언론 관계자 등 12명이 참석했다.팸투어에서는 웰니스 관광지, 마이스 유니크베뉴(MICE Unique Venue), 그린키(Green Key) 등 제주가 보유한 친환경 고부가가치 관광 자원을 집중 홍보했다.특히 6일 도내 관광 사업체 14곳이 참가하는 ''트래블 마트''를 열고 현지 업계와 일대일 상담을 통해 상품망 확보 방안 등을 논의했다.◇제주은행, 희망의 봄 응원제주은행은 봄을 맞아 제주도민들을 향한 따뜻한 위로와 응원의 메시지를 담은 대형 공감 글판을 게시했다.제주은행 연삼로금융센터에 게시된 공감 글판.(제주은행 제공. 재판매 및 DB 금지)제주시 노형오거리 본점과 연삼로 사거리에 위치한 연삼로금융센터 외벽에 게시된 메시지는 ''번지듯 돋아난 희망의 봄, 어느새 피어난 행복이더라''다.제주은행은 화사한 봄의 기운이 지역사회 곳곳으로 퍼져나가고 도민들의 일상이 밝은 희망과 행복으로 가득 차길 바라는 마음을 담았다고 설명했다.제주은행은 분기마다 새로운 공감 글판을 게시한다.', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008814814', 'https://imgnews.pstatic.net/image/421/2026/03/09/0008814814_001_20260309142708087.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 14:26:32', 0, true, '2026-03-09 06:26:29.889477') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1177, '제주銀 지방은행 최초 ''생성형 AI플랫폼'' 구축', '업무 생산성·효율성 제고 목표제주은행은 지방은행 최초로 생성형 인공지능(AI) 플랫폼 구축에 나서 본격적인 ''인공지능 전환(AX)''에 착수했다고 3일 밝혔다.제주은행은 KT와 생성형 AI 플랫폼 구축을 위한 계약을 체결하고, 은행 업무 전반의 생산성과 효율성을 높이기 위한 AI 혁신 프로젝트를 추진키로 했다.지방은행 최초로 추진되는 이번 프로젝트는 단순한 기술 도입을 넘어 직원들이 업무용 AI 에이전트를 직접 개발·활용할 수 있는 환경을 구축하는데 중점을 두고 있다. 제주은행은 올해 상반기 내 구축을 완료하고, 업무 현장에서의 활용 범위를 단계적으로 확대할 계획이다.새로 구축되는 플랫폼은 은행 내 규정 기반 실시간 질의응답을 비롯해 보고서·공문 자동 작성 등 다양한 업무에 활용된다. 또 내부통제 점검, 여신심사 지원, 시스템 개발 업무 보조 등 은행의 주요 업무를 지원하는 AI 에이전트를 순차적으로 구축해 활용 범위를 넓혀갈 예정이다.제주은행은 이를 통해 반복적인 업무를 줄이고 업무 프로세스를 효율화함으로써 직원들이 전문적인 금융 서비스를 제공하고, 고객 가치 창출에 집중할 수 있는 환경을 마련해 나갈 방침이다.특히 금융권의 엄격한 보안 기준을 반영한 시스템 설계를 통해 안전한 AI 활용 체계를 구축하고, 이를 기반으로 디지털 금융 시장에서 AX 경쟁력을 강화할 계획이다. 이희수 제주은행장은 "생성형 AI 플랫폼 구축은 제주은행의 새 비전인 ''디지털제주 2030''을 실현하기 위한 핵심 과제"라며 "지방은행 최초로 생성형 AI를 실무에 도입해 직원 주도의 업무 혁신을 이루고, 고객에게 차별화된 금융 서비스를 제공하겠다"고 말했다.', NULL, '파이낸셜뉴스', 'https://n.news.naver.com/mnews/article/014/0005486972', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_FINANCE', NULL, '2026-03-05 18:20:16', 0, true, '2026-03-09 06:26:29.889477') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1178, '플래티어, KT와 제주은행 ‘생성형 AI 플랫폼’ 수주', '제주은행 ‘1부서 1에이전트’ 추진전사 AI 표준 플랫폼으로 XGEN 낙점[이데일리 김현아 기자] 버티컬 AI·DX 솔루션 기업 플래티어(Plateer)가 KT와 컨소시엄을 구성해 제주은행의 ‘GenAI 플랫폼 구축 사업’을 수주했다.최근 롯데홈쇼핑 프로젝트에 이어 금융권 레퍼런스를 확보하면서, 플래티어의 ‘에이전틱 AI(Agentic AI)’ 전략이 유통을 넘어 고규제 산업으로 본격 확장하는 흐름이다.제주은행은 이번 플랫폼 구축을 계기로 디지털 뱅크 전환 속도를 높인다는 방침이다. 특히 플랫폼 구축 이후 ‘1부서 1에이전트’ 체계를 전사적으로 도입하겠다는 계획을 내걸었다. 은행 내부에서는 직원이 쉽게 활용하는 AI 업무환경, 데이터 기반 의사결정, 고객 중심 지능형 금융서비스 구현을 핵심 방향으로 제시했다.플래티어는 자사 에이전틱 AI 플랫폼 ‘XGEN(엑스젠)’을 제주은행에 공급한다. 회사 측은 XGEN이 금융권이 요구하는 높은 보안 기준에 맞춰 설계된 엔터프라이즈급 생성형 AI 인프라라는 점을 강조했다. 핵심은 내부 데이터가 외부로 나가지 않는 폐쇄형 온프레미스(설치형) 환경, 망분리 구조, 정교한 접근 통제 정책과 내부통제 체계를 함께 지원한다는 점이다.현장 적용 시나리오도 구체화했다. 플래티어는 XGEN이 단순 챗봇을 넘어 업무 단위에서 작동하는 AI 에이전트 플랫폼으로 활용될 것으로 보고, 심사보고서 생성 지원, 내부통제·상시감시 자동화, KYC(고객확인제도, Know Your Customer)·AML(자금세탁방지, Anti-Money Laundering) 분석 등 은행 핵심 업무 전반에 단계적으로 적용할 기반을 마련하겠다고 밝혔다.또한 노코드 기반 비주얼 캔버스 에디터를 제공해 비개발자도 드래그 앤 드롭 방식으로 금융업무용 에이전트를 구성·운영할 수 있도록 지원한다는 설명이다.진병권 플래티어 ECS AX사업부문장은 “이번 협력은 XGEN이 온프레미스·망분리·내부통제 등 업계 최고 수준의 보안 요건을 충족하면서도 금융기관의 복잡한 업무를 실제로 자동화·효율화할 수 있음을 입증한 사례”라고 말했다. 이어 “기업은 단순 LLM(거대언어모델)도입을 넘어 업무 단위에서 작동하는 에이전틱 AI 인프라를 요구하고 있다”며 제조·에너지·제약·방산 등 고규제 산업군에서 PoC(개념검증)를 확대하겠다고 덧붙였다.플래티어는 KT와의 협력을 바탕으로 산업별 템플릿을 표준화해 적용 속도를 높이는 전략도 병행한다. 유통·이커머스에서 축적한 템플릿을 금융, 제조, 공공 등 규제가 강한 산업에 맞게 신속 확장하는 방식으로, 이번 제주은행 수주가 그 ‘버티컬 확장’ 전략의 대표 사례가 될 수 있다는 게 회사 측 판단이다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006228593', 'https://imgnews.pstatic.net/image/018/2026/03/04/0006228593_001_20260304184409460.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-04 18:44:09', 0, true, '2026-03-09 06:26:29.889477') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1179, '인베니, 맥쿼리인프라·우리금융지주 지분 처분…총 774억원 규모', 'LS그룹 계열사 인베니(구 예스코홀딩스)는 포트폴리오 재구성을 위해 맥쿼리한국인프라투융자회사와 우리금융지주 지분을 처분한다고 9일 공시했다.인베니는 맥쿼리인프라 주식 310만8000주를 353억6904만원에 처분할 예정이다. 처분 이후 보유 주식은 500만주(지분율 1.04%)다.회사는 우리금융지주 주식 127만3000주를 420억7265만원에 매각한다고 밝혔다. 이에 회사가 보유하는 주식은 150만주(지분율 0.2%)로 줄어들 전망이다.두 지분 매각 규모는 총 774억원이다. 처분 기한은 9월 9일까다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000080517', 'https://imgnews.pstatic.net/image/293/2026/03/09/0000080517_001_20260309124310511.png?type=w800', 'NEWS_ENERGY', NULL, '2026-03-09 12:43:10', 0, true, '2026-03-09 06:26:37.580620') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1180, 'LS 7개사, 차세대 ESS 등 신기술 총출동', '‘배터리 산업, LS가 함께’ 슬로건ESS·직류솔루션·EV 등 6개 테마LS그룹 주요 계열사들이 국내 최대 배터리 산업 전시회 ‘인터배터리 2026’에 총출동해 미래 전략 사업 역량을 선보인다.9일 LS일렉트릭은 LS MnM(엠앤엠)·LS머트리얼즈·LS알스코·LS사우타·LS이모빌리티솔루션·LS티라유텍 등 그룹 계열사와 함께 오는 11일부터 13일까지 3일간 서울 강남구 코엑스에서 열리는 인터배터리 2026에 참가한다고 9일 밝혔다.LS일렉트릭은 ‘배터리 산업의 시작과 끝, LS가 함께합니다’라는 주제로 6개 계열사들과 공동으로 45부스(406㎡·사진) 규모의 전시장을 마련하고 에너지저장장치(ESS), 직류(DC) 솔루션, 데이터센터, 미래 소재, 전기차(EV), 스마트팩토리 등 6개 테마를 중심으로 차별화된 설루션과 기술 역량을 강조한다.LS일렉트릭은 차세대 ESS와 직류 패키지 설루션 등 전략 신제품을 전면 배치한다. LS일렉트릭의 ‘올인원 ESS 플랫폼(All-in-One ESS Platform)’은 배터리와 PCS 등에 설치된 센서를 통해 실시간으로 수집되는 상태 데이터를 AI로 분석해 전력 사용량을 예측하고 사전 고장을 예방함으로써 효율성과 안정성을 획기적으로 높인 차세대 설루션이다.LS일렉트릭은 또, 산업용 모듈형 ESS설루션 ‘LS일렉트릭 MSSP (Modular Scalable String Platform)’도 소개한다. MSSP는 전력변환 분야 핵심 기술과 모터제어속도를 통해 에너지사용량을 절감시키는 전력전자 기반 산업용 드라이브(인버터) 분야에서 쌓아 온 세계 최고 수준 제조 역량을 바탕으로 독자 개발한 제품이다.이밖이 직류 배전 운영 플랫폼 ‘DC Factory Solution’을 공개하고 반도체 변압기(SST), DC-DC 컨버터, 반도체 차단기(SSCB) 등 차세대 직류 배전 핵심 제품 경쟁력도 강조한다.LS MnM은 글로벌 공급망과 비즈니스 프로세스를 시각화한 콘텐츠를 통해 배터리소재 사업의 추진 현황과 미래 비전을 제시한다. LS MnM은 원료 확보부터 제품 생산까지 수직계열화를 통해, 글로벌 시장의 규제 요구를 충족하는 투명한 출처의 ‘비금지외국기관(Non PFE)’ 공급망 구축을 앞두고 있다. 안정적인 원료 확보를 위해, 인도네시아에 소재한 니켈제련소 투자도 진행 중이다.LS머트리얼즈는 AI 데이터센터의 피크 전력 이슈 해결을 위한 고속 충·방전 에너지저장 솔루션 ‘울트라캐퍼시터(UC)’를 소개한다. 특히 AI 데이터센터에 최적화된 ‘셀듈(Celldule, 셀-모듈 일체형 울트라캐퍼시터)’은 이번 전시에서 최초 공개된다. 박혜원 기자', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002610482', 'https://imgnews.pstatic.net/image/016/2026/03/09/0002610482_001_20260309111110242.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-03-09 11:11:10', 0, true, '2026-03-09 06:26:37.580620') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1181, 'LS그룹 계열사들, 인터배터리 총출동…"전력산업 토털 설루션 공개"', 'LS일렉트릭 등 그룹 주요 계열사 7개 기업, 인터배터리 2026 참가인터배터리2026 LS부스 조감도. LS그룹 제공LS일렉트릭과 LS MnM 등 LS그룹 주요 계열사 7개 기업이 국내 최대 배터리 산업 전시회에 총출동해 기술 경쟁력을 강조한다.LS일렉트릭은 LS MnM·LS머트리얼즈·LS알스코·LS사우타·LS이모빌리티솔루션·LS티라유텍 등 그룹 계열사와 함께 오는 11일부터 13일까지 서울 강남 코엑스에서 열리는 ''인터배터리 2026''에 참가한다고 9일 밝혔다.LS일렉트릭은 이들 계열사들과 공동으로 406㎡ 규모의 전시장을 마련하고 △에너지저장장치(ESS) △직류(DC) 설루션 △데이터센터 △미래 소재 △전기차(EV) △스마트팩토리 등 6개 테마를 중심으로 차별화된 설루션과 기술 역량을 강조할 것이라고 이날 설명했다.전시 주제는 ''배터리 산업의 시작과 끝, LS가 함께합니다''로, 배터리 소재부터 데이터센터용 핵심 제품까지 차세대 전력산업 전반에 걸친 토털 설루션이 공개될 예정이다.LS일렉트릭은 차세대 ESS와 직류 패키지 설루션 등 전략 신제품을 전시장에 전면 배치한다. 핵심 제품인 ''올인원 ESS 플랫폼''은 배터리 등에 설치된 센서를 통해 실시간으로 수집되는 상태 데이터를 AI로 분석, 전력 사용량을 예측하고 사전 고장을 예방함으로써 효율성과 안정성을 높인 차세대 설루션이라고 이 기업은 설명했다.직류 배전 운영 플랫폼 DC 팩토리 설루션과 해당 기업이 독자 개발한 산업용 모듈형 ESS설루션인 ''LS일렉트릭 MSSP''도 현장에서 소개된다.LS MnM은 전시장에서 배터리소재 사업의 추진 현황과 미래 비전을 제시할 계획이다. 현재 LS MnM은 원료 확보부터 제품 생산까지 수직계열화를 통해 글로벌 시장의 규제 요구를 충족하는 투명한 출처의 ''비금지외국기관(Non PFE)'' 공급망 구축을 앞두고 있다.안정적인 원료 확보를 위해 인도네시아 니켈제련소 투자도 진행 중이다. 온산국가산업단지에 건설 중인 배터리소재 공장은 연내 테스트 가동을 거쳐 4분기부터 양산에 돌입할 예정이다.LS일렉트릭 관계자는 "(이번 전시를 통해) 배터리 소재부터 배터리가 적용되는 모빌리티와 데이터센터 사업까지 배터리 산업 전반의 생태계를 아우르는 계열사 간의 시너지를 강조할 것"이라고 말했다.※CBS노컷뉴스는 여러분의 제보로 함께 세상을 바꿉니다. 각종 비리와 부당대우, 사건사고와 미담 등 모든 얘깃거리를 알려주세요.이메일 :jebo@cbs.co.kr카카오톡 :@노컷뉴스사이트 :https://url.kr/b71afn', NULL, '노컷뉴스', 'https://n.news.naver.com/mnews/article/079/0004122427', 'https://imgnews.pstatic.net/image/079/2026/03/09/0004122427_001_20260309102819952.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-03-09 10:28:19', 0, true, '2026-03-09 06:26:37.580620') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1182, 'GS건설, 핵심 협력사 30곳 선정…동반성장 프로그램 강화', '선정된 협력사에 금융지원 등 인센티브 제공GS건설이 ''2026년 동반성장 프로그램''을 강화한다고 9일 밝혔다. 사진은 지난해 10월 진행된 GS건설 대표 상생협력행사인 ''그랑 파트너스 피에스타''에서 인사말을 전하는 허윤홍 GS건설 대표다. /GS건설[더팩트 | 공미나 기자] GS건설은 핵심 협력사 30곳을 선정해 네트워크를 강화하고 금융지원 등을 제공하는 ''2026년 동반성장 프로그램''을 강화한다고 9일 밝혔다.먼저 상반기에는 3월과 5월 두 차례 코어 파트너십(Core Partnership) 프로그램을 진행한다. 이는 우수협력사 30여 곳을 선정해 동반성장을 위한 방안을 논의하고, 핵심 협력사와 네트워크를 강화하는 프로그램이다. 코어 파트너로 선정된 협력사는 계약이행보증 감면, 금융지원 등의 인센티브를 받을 수 있다. 올해부터는 각 협력사들의 안전과 품질관리 우수 사례를 공유하는 섹션도 마련된다.하반기에는 GS건설의 대표 상생협력 행사인 그랑 파트너스 피에스타(GRAN PARTNERS FIESTA)가 열린다. 이 행사에는 올해 새롭게 선정된 코어 파트너사를 포함한 약 80여 협력사 대표가 참석, GS건설 대표 및 임원들과 함께 GS건설의 경영현황과 조달 정책 등을 공유하며 소통을 이어갈 계획이다.또한 GS건설은 ''안전''을 최우선 가치로 삼아 협력사의 안전한 현장관리를 위한 지원에 적극 나서고 있다. 산업안전보건관리비 선지급과 안전담당자 배치 비용 지원을 통해 안전에 대한 협력사의 재정 부담을 덜어주고, 협력사 현장소장 및 안전담당자를 대상으로 ''찾아가는 안전혁신학교'' 프로그램을 진행하고 있다.GS건설 관계자는 "핵심 협력사에 지원을 강화하는 이번 코어 파트너십 시행으로, 협력사에도 동기부여가 되는 등 긍정적인 효과가 기대된다"며 "앞으로도 협력사가 최고의 성과를 낼 수 앞으로도 체계적이고 실효성 있는 지원을 통해 공정거래 질서 확립과 동반성장에 앞장서겠다"고 밝혔다.발로 뛰는 더팩트는 24시간 여러분의 제보를 기다립니다.▶카카오톡: ''더팩트제보'' 검색▶이메일: jebo@tf.co.kr▶뉴스 홈페이지: http://talk.tf.co.kr/bbs/report/write', NULL, '더팩트', 'https://n.news.naver.com/mnews/article/629/0000479382', 'https://imgnews.pstatic.net/image/629/2026/03/09/202655221773035896_20260309151219193.png?type=w800', 'NEWS_CONSTRUCT', NULL, '2026-03-09 15:12:19', 0, true, '2026-03-09 06:26:52.098795') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1183, '6년 만에 신규 공급 ''상주자이르네'' 견본주택 문전성시…부동산 시장 관심 집중', '견본주택 개관 3일간 내방객 8천명 북적특별공급 16일, 1순위 17일, 2순위 18일 청약 접수최고 29층·773가구…상주 최대 규모상주 최초 스카이커뮤니티·사우나 등 적용상주 자이르네 조감도. 자이에스앤디 제공경북 상주에서 약 6년 만에 선보이는 신규 아파트 ''상주자이르네''가 견본주택 개관과 동시에 대규모 방문객을 끌어모으며 지역 부동산 시장의 높은 관심을 입증했다.시공사인 자이에스앤디는 9일 경북 상주시 함창읍에 공급하는 ''상주자이르네'' 견본주택에 개관 이후 주말 3일 동안 약 8천 명의 방문객이 다녀갔다고 밝혔다.지난달 기준 상주시 인구가 약 8만9천600여 명 수준임을 감안하면 지역 내 적체된 아파트 대기 수요가 상당했던 것으로 풀이된다. 특히 상주에서 신규 아파트 공급이 약 6년 만에 이뤄지는 만큼 실수요자들의 관심이 집중됐다는 분석이다.◆쌀쌀한 날씨에도 방문객 ''문전성시''견본주택 개관 첫날부터 방문객들이 몰리면서 현장은 하루 종일 북적였다. 쌀쌀한 날씨에도 견본주택 앞에는 이른 오전부터 입장을 기다리는 대기 줄이 길게 이어졌으며 내부에는 단지 설계와 청약 조건을 확인하려는 방문객들로 발 디딜 틈이 없었다.방문객은 상주뿐 아니라 인근 지역에서도 이어졌다. 특히 문경시와 김천시 등 주변 도시 주민들의 발길도 이어지며 관심을 보였다. 문경에 거주하는 하태진(56) 씨는 "스카이라운지와 사우나 같은 고급 커뮤니티 시설과 단지 규모, 브랜드 등 전체적인 수준이 주변에서 보기 어려운 수준이라 마음에 든다"며 "차로 5분이면 문경까지 이동 가능하고 초등학교도 도보권에 있어 입지 조건도 좋다"고 말했다.상주자이르네는 GS건설 자회사인 자이에스앤디가 시공하는 자이르네 브랜드 단지다. 지하 2층~지상 최고 29층, 총 773가구 규모로 조성되며 상주 지역 내 최대 규모이자 최고층 아파트 단지다. 전용면적은 84㎡~135㎡ 중대형 위주로 구성된다.커뮤니티 시설로는 피트니스센터, 실내골프연습장, 사우나, 작은도서관, 독서실 등이 조성되며 교보문고 북 큐레이션 서비스와 무인카페도 도입된다. 주차장을 100% 지하화해 지상은 공원형 단지로 꾸미고, 국공립 어린이집과 돌봄센터도 마련될 예정이다.◆교통·교육·생활 인프라 갖춘 입지교통 여건도 뛰어나다. 3번 국도 사아매 교차로와 중부내륙고속도로 점촌함창 IC를 이용하면 상주·문경·구미 등 인근 도시로 접근이 가능하다. 생활 인프라로는 하나로마트(함창점), 홈플러스(문경점), 문경제일병원, 문경중앙시장 등이 이용 가능하다.교육 환경도 갖췄다. 단지 인근에는 함창초등학교(2027년 완공 예정)를 비롯해 함창중·고, 상지여중 등이 있다. 이 지역은 농어촌 특별전형 대상 지역으로 일정 요건 충족 시 대학 정원 외 전형 지원도 가능하다.분양 일정은 16일 특별공급을 시작으로 17일 1순위, 18일 2순위 청약 접수가 진행된다. 1순위 청약 자격은 상주시 및 경북, 대구시에 거주하는 만 19세 이상 세대주 및 세대원으로, 청약통장 가입 기간 6개월 이상이고 지역·면적별 예치금 기준을 충족하면 신청할 수 있다. 재당첨 제한이 없고 전매 제한이 없어 계약금 완납 후 분양권 전매도 가능하다.분양 관계자는 "상주와 인근 문경 지역에 그동안 신규 아파트 공급이 거의 없었던 만큼 수요자들의 기대가 높다"며 "계약금 정액제와 중도금 무이자 혜택을 통해 자금 부담도 줄일 계획"이라고 밝혔다.상주 자이르네 조감도. 자이에스앤디 제공', NULL, '매일신문', 'https://n.news.naver.com/mnews/article/088/0001000113', 'https://imgnews.pstatic.net/image/088/2026/03/09/0001000113_001_20260309150818361.jpg?type=w800', 'NEWS_CONSTRUCT', NULL, '2026-03-09 15:08:18', 0, true, '2026-03-09 06:26:52.098795') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1184, '대구시청 앞 ''49층 시니어레지던스'' 무산…도심 공동화 우려', '상장폐지 결정 속 경영난 겹쳐 자산 정리 나서대구시청 앞 동인동 시니어 레지던스 사업이 매각 수순에 들어가고 신라스테이 중단·대백 본점 공백 등이 겹치며 대구 원도심 공동화 우려가 커지고 있다. 대구시청 동인청사 전경. 매일신문DB대구시청 앞 도심 핵심 부지로 주목받았던 중구 동인동 시니어 레지던스 사업이 매각 수순을 밟는다. 최근 잇따른 도심 핵심 개발사업 지연과 주요 시설 이전 논의까지 겹치며 대구 원도심의 침체를 우려하는 목소리도 커지고 있다.◆ 상폐 위기 몰린 리츠회사에이자기관리부동산투자회사주식회사(이하 에이리츠)는 대구 중구 동인동 대구시청 앞 시니어 레지던스(노인복지주택) 예정 부지에 대한 매각을 추진한다고 4일 밝혔다. 에이리츠는 지난 2020년 9월 동인동2가 4천376㎡ 부지를 매입해 지하 5층~지상 44층, 154가구 규모의 주상복합아파트 건립을 계획했다. 그러나 부동산 경기 침체로 착공에 나서지 못했고 부지는 2023년 4월부터 임시 유료주차장으로 위탁 운영됐다.돌파구를 모색하던 에이리츠는 2024년 하반기 사업 방향을 주상복합에서 시니어 레지던스 개발로 변경했다. 고령 인구 증가에 따라 관련 시장이 확대될 것이라는 판단에서다. 지난해 4월 대구시는 지하 5층~지상 49층, 434가구 규모의 시니어 레지던스에 관한 건축심의를 조건부 의결하기도 했다. 하지만 이후에도 사업은 본격 추진되지 못했고, 결국 매각 수순을 밟게 됐다.회사 사정은 점차 어려워졌다. 에이리츠는 지난해 8월 20일 기업의 계속성 및 공익성 등을 이유로 상장폐지가 결정됐으나, 다음 날 서울남부지방법원에 상장폐지결정 효력정지 가처분을 신청하면서 정리매매 절차는 보류된 상태다. 법원 판단 결과에 따라 후속 상장폐지 절차가 진행될 가능성이 있다.에이리츠의 지난해 매출액은 26억4천451만원으로 전년 45억2천515만원 대비 41.56% 감소했다. 영업손실은 4억4천395만원으로 적자를 지속했으며, 당기순손실은 47억3천769만원으로 전년보다 적자 폭이 2배가량 확대됐다. 회사 측은 "기존 부동산 개발사업이 완료되면서 분양 수입은 줄어든 반면, 신규 사업 발굴을 위한 운영 비용이 발생하며 수익성이 악화됐다"고 설명했다.동인동 개발 사업이 무산된 가운데 도심 핵심 프로젝트 전반에서도 사업 지연 사례가 이어지고 있다. 5성급 브랜드 호텔로 관심을 모은 ''신라스테이 대구''도 지난해 말부터 이어진 고환율, 고금리, 고물가 등 경제 여건에 따라 사업이 일시 중지된 상태다. 당초 목표는 2028년 9월까지 중구 동인동 공평네거리 2천16㎡ 부지에 호텔을 짓고 2029년 3월 영업을 개시하는 것이었으나, 이번 일시 중단에 따라 일정 연기가 불가피해졌다.대구시청 앞 동인동 시니어 레지던스 개발이 사업성 악화와 리츠 경영난 속에 무산되며 해당 부지 매각이 추진되고 있다. 대구 중구 동인동 대구시청 앞 시니어 레지던스 예정 부지에 토지 매매 안내 현수막이 붙어 있다. 구민수 기자◆잇따라 무산된 개발 사업도심 핵심 프로젝트가 멈추면서 대구 도심 공동화를 우려하는 목소리도 나온다. 지역 대표 상권이었던 대구백화점 본점은 2021년 7월 폐업 이후 5년째 새로운 활용 방안을 찾지 못하고 있다. 중심 상업시설이 장기간 비어 있는 상태가 이어지면서 도심 상권 침체를 상징하는 사례로 꼽힌다.행정 기능의 이동 가능성도 도심 활력을 약화시킬 요인으로 거론된다. 대구시청 동인청사는 대구신청사 이전 계획에 따라 2030년까지 매각이 추진될 예정이다. 여기에 지역 대표 의료기관인 경북대병원 역시 홍준표 전 대구시장 재임 시절 이전 가능성이 언급되면서 도심 공동화 우려를 부추겼다.문제는 동인청사와 경북대병원 부지 모두 향후 활용 계획이 뚜렷하지 않다는 점이다. 동인청사는 2023년 10월 매각 결정 이후 개발 논의가 사실상 중단된 상태다. 경북대병원은 본관 2층 건물이 사적 제443호로 지정돼 있어 부지 개발에 제약이 따른다. 여기에 도심 기능을 충분히 고려하지 못한 도시 정책 역시 침체를 심화시켰다는 분석도 나온다.임인환 대구시의원은 "대구 도심은 이미 대백 본점 폐업, 개발사업 지연 등으로 활력이 떨어지고 있는데도 시 차원의 명확한 대책이 보이지 않는다"며 "도심 기능을 제대로 고려하지 않은 채 추진된 정책들이 오히려 혼선을 키운 측면이 있다"고 진단했다.이어 "경북대병원 이전이나 동인청사 매각 같은 문제도 현실적인 사업성 검토 없이 논의부터 앞선 측면이 있다"며 "도심은 도시 경쟁력을 좌우하는 핵심 공간인 만큼 세계 주요 도시처럼 도심 재생을 중심으로 한 장기 전략이 필요하다"고 강조했다.이에 대해 대구시는 도심 활성화를 위한 여러 정책을 병행 추진하고 있다고 설명했다. 허주영 대구시 도시주택국장은 "중구 동성로 일대 상권 침체에 대응하기 위해 ''동성로 르네상스 사업''을 추진하고 있으며 옛 중앙파출소 전면 광장 정비와 통신골목 환경 개선 등 주요 사업이 올해부터 본격 착공에 들어간다"며 "하드웨어 정비뿐 아니라 상권 활성화를 위한 다양한 소프트웨어 사업도 함께 추진할 계획"이라고 말했다.또 "도심 주거 기능 강화를 위해 재개발·재건축 사업을 지속적으로 추진하고 있으며 근대 역사 자산을 활용한 신규 국비사업도 발굴하고 있다"며 "동인청사 이전 부지 등 주요 후적지에 대해서도 지역 특성에 맞는 개발이 이뤄지도록 인허가 과정에서 방향을 유도할 계획"이라고 밝혔다.', NULL, '매일신문', 'https://n.news.naver.com/mnews/article/088/0000999460', 'https://imgnews.pstatic.net/image/088/2026/03/04/0000999460_001_20260304193813938.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-04 14:41:07', 0, true, '2026-03-09 06:26:58.985681') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1185, '대백프라자, 파크골프 스크린 경기장 15→20개 확대', '대구백화점이 프라자점에 스크린 파크골프장 경기장을 20개로 확대했다.(대구백화점 제공, 재판매 및 DB 금지)(대구=뉴스1) 김종엽 기자 = 대구백화점은 27일 스크린 파크골프장을 확장했다고 밝혔다.프라자점 10층에 자리한 마실파크골프장은 지난해 2월 오픈 당시 15개이던 스크린 경기장을 20개로 늘렸다.또 교육장과 현장 체험 실습, 용품 매장, 전문강사 자격증 취득 등 토털 서비스 제공이 가능한 ''파크골프 토탈 문화공간''을 갖췄다.대백프라자는 확장을 기념해 가요교실, 액티브 시니어 교양 아카데미 등 문화센터 프로그램에 파크골프를 연계한 복합 문화서비스를 제공할 계획이다.', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008798018', 'https://imgnews.pstatic.net/image/421/2026/02/27/0008798018_001_20260227143731076.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-27 14:36:47', 0, true, '2026-03-09 06:26:58.985681') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1197, '[단독] "공장 멈추기 일보 직전"…셧다운 공포에 ''버티기 모드''', '중동 전쟁 여파로 나프타 수급 차질NCC 가동률 80%→65% ‘최저 운전’재고 2주→4주 버텨도 4월초 분수령한경DB중동 전쟁 여파로 석유화학 산업의 핵심 원료인 나프타 수급에 차질이 빚어지자 국내 나프타분해설비(NCC) 업체들이 원료 재고를 최대 4주 수준까지 확보하며 ''버티기 모드''에 들어갔다. 기업들이 공장 가동률을 낮춰 원료 소비를 줄이면서 통상 2주 수준이던 재고를 두 배 가까이 늘린 것이다. 업계에서는 4월 초까지 수입 물량이 정상적으로 들어오지 않을 경우 일부 공장 셧다운 가능성도 배제할 수 없다는 관측이 나온다.2주 불과했던 재고, 4주까지 확보9일 석유화학업계와 산업통상부 등 정부 관계자에 따르면 국내 NCC 업체들은 최근 가동률을 낮추면서 평균 나프타 재고를 약 4주 수준까지 늘린 것으로 파악됐다. 통상 약 2주 수준의 재고를 유지하던 것과 비교하면 두 배 가까이 늘어난 셈이다.한 관계자는 “NCC는 공장을 완전히 멈추면 재가동까지 상당한 시간이 걸리기 때문에 셧다운보다는 가동률을 낮춰 시간을 버는 방식으로 대응하고 있다”고 설명했다.재고 확보를 위해 기업들은 공장 가동률도 크게 낮췄다. 최근 고객사에 ‘포스 마주르(Force Majeure·불가항력 사유로 계약 이행 불가)’를 선언한 여천NCC를 비롯해 롯데케미칼, LG화학, 대한유화, GS칼텍스 등 주요 NCC 업체 5곳이 가동률을 줄였다. 이들 업체의 평균 가동률은 기존 약 80% 수준에서 최근 65%까지 떨어진 것으로 파악된다. 업계에서는 추가로 낮추기 어려운 사실상의 ‘최저 가동률’에 근접한 수준이라는 설명이다.업체별로 보면 가동률 조정은 지난달 말부터 시작됐다. 지난 6일 석유화학 정보업체 ICIS 집계에 따르면 GS칼텍스 여수 NCC는 2월 말 가동률을 83%에서 60%까지 낮췄다. 여천NCC는 90%에서 68%로, 롯데케미칼 대산 공장은 80%에서 70%로 각각 조정했다. 대한유화 울산 공장도 80%에서 75% 수준으로 낮춘 상태다.LG화학도 이번 주부터 가동률을 추가로 낮출 계획이다. 대산 공장은 69%에서 54%, 여수 공장은 64% 수준까지 하향 조정하는 방안을 검토하고 있는 것으로 전해졌다.포스 마즈르 ''연쇄 선언'' 가능성여천NCC에 이어 다른 업체들로 포스 마주르 선언이 확산할 가능성도 거론된다. 현재 주요 업체들은 기존 계약 물량은 유지하면서 현물(스팟) 거래 공급을 줄이는 방식으로 대응하고 있지만, 수입 차질이 장기화해 가동률을 더 낮추거나 재고를 빠르게 줄어들 경우 계약 이행 부담이 커질 수 있기 때문이다. 이미 인도네시아와 싱가포르 등 일부 석화 기업들도 나프타 공급 차질을 이유로 포스 마주르를 선언한 사례가 나오고 있다.다만 여천NCC의 포스 마주르는 실제 공급 중단보다는 장기 공급 계약과 관련한 법적 책임을 최소화하기 위한 선제적 조치라는 해석이 많다. 대형 석유화학 기업들이 NCC 생산물의 상당 부분을 자체 다운스트림 공정에서 소화하는 것과 달리 여천NCC는 외부 판매 비중이 높아 계약 리스크에 더 민감하다는 것이다.나프타는 플라스틱과 합성섬유의 출발 원료인 에틸렌·프로필렌 등을 생산하는 석유화학 산업의 핵심 원료다. 국내 공급은 정유사가 원유를 정제해 생산하는 물량이 약 50~60%, 수입이 40~50% 수준이며 상당량이 중동에서 들어온다.업계에서는 가동률 하향으로 재고를 약 4주 수준까지 확보했지만 중동 상황이 장기화해 4월 초까지 수입 물량이 정상적으로 들어오지 않을 경우 일부 NCC 공장 셧다운 가능성도 배제할 수 없다는 관측이 나온다. 한 석화업계 관계자는 “지금은 가동률을 낮춰 시간을 벌고 있는 상황”이라며 “수입 물량이 막히는 기간이 길어지면 결국 공장 가동을 중단해야 할 수도 있다”고 말했다.기업들은 정부와 함께 중동 이외 지역인 미국·인도 등에서 나프타를 확보하는 방안과 국내 정유사의 나프타 생산 확대 요청 등을 검토하고 있다. 다만 해외 기업들도 대체 수급처 확보에 나서면서 대응이 쉽지 않은 상황이다.', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005259767', 'https://imgnews.pstatic.net/image/015/2026/03/09/0005259767_001_20260309112417793.jpg?type=w800', 'NEWS_ENERGY', NULL, '2026-03-09 10:59:12', 0, true, '2026-03-09 06:27:29.952135') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1186, '''사업 확장+승계'' 대구 기업들 M&A 베팅…정부도 특별법 통한 제도화 추진', '창업 1세대 고령화로 지각변동…건설·유통·금융 등 전방위 확산대구백화점 본점.대구 지역 기업들의 인수·합병(M＆A) 시장이 업종과 규모를 가리지 않고 빠르게 재편되고 있다. 건설·유통·금융 분야에서 매각과 지분 투자가 동시에 이어지며 지역 자본의 이동 경로도 과거와는 다른 양상을 보이고 있다. 특히 창업 1세대 경영자들의 고령화가 본격화되면서 기업 승계와 구조조정, 사업 확장이 맞물린 거래가 늘고 있다는 점이 최근 M＆A 시장의 가장 큰 특징으로 꼽힌다.코스피 상장사 대구백화점은 최근 오너 일가가 보유한 대백저축은행 경영권 지분 70%를 M＆A 시장에 내놓았다. 희망 매각가는 약 300억원 수준으로 전해진다. 지역 건설사 서한은 대구 동구 신천동 대구 메리어트호텔 운영사의 지분 인수와 관련해 우선협상권을 확보하고, 이달 중 본계약을 체결할 예정이다. 인수가 완료되면 서한은 지분 30% 이상을 확보해 최대주주로 올라설 전망이다.M＆A 특성상 거래와 매물 정보는 외부로 드러나지 않는 경우가 많지만 체감 거래는 분명히 늘고 있다는 것이 업계의 공통된 설명이다. 과거 지역 자본의 주요 투자처가 부동산이었다면 최근에는 중소기업 M＆A로 자금 흐름이 이동하고 있다는 분석도 나온다.이 같은 흐름의 배경에는 창업 1세대 경영자들의 고령화가 자리하고 있다. 중소벤처기업부에 따르면 60세 이상 CEO가 운영하는 중소기업 236만2천953개 가운데 67만5천805개(28.6%)가 후계자를 찾지 못한 것으로 추정된다. 이 가운데 대구경북 중소기업은 5만6천561개로 전국의 8.4%를 차지했다.이에 따라 정부는 M＆A를 통한 가업 승계를 공식 정책 수단으로 제도화하고 나섰다. 중소벤처기업부는 지난해 ''M＆A를 통한 중소기업 승계 활성화 방안''을 발표하고, M＆A형 승계를 법적으로 정의하는 특별법 제정을 추진하고 있다.', NULL, '매일신문', 'https://n.news.naver.com/mnews/article/088/0000995746', 'https://imgnews.pstatic.net/image/088/2026/02/05/0000995746_001_20260205204616655.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-05 20:46:16', 0, true, '2026-03-09 06:26:58.985681') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1187, '삼성, 올해 신입 인재 1만여명 채용한다…70년째 공채 지속', '상반기 공채 시작전자·물산 등 18곳 모집내달 GSAT, 5월 면접삼성전자 감독관이 지난해 10월 경기 수원시 삼성전자 인재개발원에서 삼성직무적성검사(GSAT) 응시자를 대상으로 예비 소집을 진행하고 있다. 사진 제공=삼성전자삼성그룹이 올해 1만여명 규모로 신입 인재를 수혈한다. 삼성그룹은 4대 그룹 중 유일하게 70년 동안 변함없는 대규모 공개채용을 이어가며 양질의 일자리 창출에 기여하는 동시에 반도체와 인공지능(AI) 등 주력 사업 역량을 키워 점점 치열해지는 글로벌 경쟁에 대응해나갈 방침이다.삼성그룹은 10일부터 올해 상반기 공채 절차를 진행한다고 9일 밝혔다.삼성전자(005930)와 삼성물산, 삼성바이오로직스, 삼성생명, 삼성디스플레이, 삼성SDI, 삼성전기, 삼성SDS 등 계열사 18곳이 신입사원을 모집한다. 채용 인원은 이번 상반기와 하반기를 합쳐 연간 약 1만여 명 수준이다.삼성은 이달 17일까지 삼성 채용 홈페이지 ‘삼성커리어스’에서 지원서를 접수받고 지원자를 대상으로 직무적합성 평가를 진행한다. 다음달 삼성직무적성검사(GSAT)과 5월 면접, 건강검진을 거쳐 입사자를 최종 선발한다. 소프트웨어(SW) 직군 지원자는 GSAT 대신 실기 방식의 SW 역량 테스트를 치른다. 디자인 직군 지원자도 GSAT을 치르지 않고 디자인 포트폴리오 심사를 통해 선발될 예정이다.삼성은 1957년 국내 최초로 신입사원 공채를 도입한 이래 70년째 변함없이 이 제도를 유지해왔다. 1990년대 외환위기 등 극히 이례적인 상황을 제외하면 1970년대 오일쇼크, 2000년대 금융위기 등 큰 경제 위기 속에서도 중단된 적 없었다. 이처럼 공채 제도를 유지하는 기업은 SK, 현대자동차, LG를 포함한 4대 그룹 중 삼성이 유일하다.삼성은 1993년 대졸 여성 신입사원 공채를 신설했으며 1995년에는 지원 자격 요건에서 학력을 제외하는 등 ‘열린 채용’ 문화를 선도해왔다. 우수한 인재를 공정하게 선발하기 위 ‘삼성직무적성검사’를 자체 개발해 도입했다.삼성은 올해를 포함해 5년 간 총 6만여 명을 채용할 계획이다. 이재용 삼성전자 회장은 지난해 8월 19일 통령실에서 진행된 경제단체 및 기업인 간담회에 참석해 “국내에서 지속적으로 양질의 일자리를 창출하고 고부가가치 산업을 육성할 수 있게 관련 투자를 지속할 것”이라고 약속한 바 있다.삼성은 그외 청년들의 소프트웨어 경쟁력 강화를 지원하기 위해 무상으로 양질의 교육을 제공하는 ‘삼성청년SW·AI아카데미(SSAFY)’ 등 인재 양성 프로그램을 제공하고 있다.', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004597241', 'https://imgnews.pstatic.net/image/011/2026/03/09/0004597241_001_20260309151610555.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-03-09 15:16:10', 0, true, '2026-03-09 06:27:05.756817') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1188, '삼성SDI, 피지컬 AI용 전고체 배터리 최초 공개', '인터배터리 2026서 일반인에 샘플 공개경량화 파우치형 내년 하반기 양산 목표삼성SDI 인터배터리 2026 부스 조감도. [사진 삼성SDI][이코노미스트 김두용 기자]삼성SDI가 피지컬 인공지능(AI)용 전고체 배터리를 최초 공개한다.삼성SDI는 11일 서울 코엑스에서 열리는 ‘인터배터리 2026’에서 AI 시대를 이끌 고품질 배터리 혁신 기술을 선보인다. 특히 피지컬 AI용 전고체 배터리 샘플을 일반인에게 최초로 공개하는 등 글로벌 최고 수준의 전고체 기술력을 강조할 것으로 보인다.삼성SDI는 휴머노이드 로봇 등에 들어갈 피지컬 AI용 전고체 배터리를 파우치형으로 개발하고 있다. 내년 하반기 양산을 목표로 하고 있는 전고체 배터리다.특히 로봇의 경우 에너지 밀도가 높고, 사용 시간이 긴 배터리 사양이 필요하다. 출력 성능도 뛰어나야 한다. 이 같은 높은 안전성과 출력을 충적시키기 위해 전고체 배터리의 파우치형을 개발 중에 있다.그동안 삼성SDI는 전기차용으로 각형 전고체 배터리를 개발해왔다. 여기에 파우치형 배터리까지 폼팩터 다변화를 통해 각종 로봇과 차세대 웨어러블 등 다양한 애플리케이션에 적용할 계획이다.에너지저장장치(ESS)용 배터리 솔루션도 선보인다. AI 데이터센터에 필수적인 무정전 전원장치 및 배터리 백업 유닛 등에 탑재되는 고출력 배터리도 전시된다. 삼성SDI는 이를 통해 AI 시대의 핵심 인프라 분야의 경쟁력을 과시할 계획이다.삼성SDI의 이번 전시 슬로건은 ‘AI 상상, 배터리가 현실로’(AI thinks, Batter enables)다.삼성SDI 관계자는 “AI 시대의 모든 가능성을 삼성SDI의 배터리 기술로 완성하는 모습을 보여주겠다. 오랜 시간 축적해온 기술력을 기반으로 AI 시대에 걸맞는 고품질 배터리 솔루션을 제시할 것”이라고 설명했다.', NULL, '이코노미스트', 'https://n.news.naver.com/mnews/article/243/0000094179', 'https://imgnews.pstatic.net/image/243/2026/03/09/0000094179_001_20260309150815710.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-03-09 15:08:15', 0, true, '2026-03-09 06:27:05.756817') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1189, '‘삼성고시’ 10일부터…역대 최대 응시 예상', '삼성, 10일부터 상반기 공채 공고삼성전자 삼성물산 삼성전기 등 18곳10~17일 접수, 5~6월까지 면접올해 1만2000명 이상 채용 예고지난해 10월 삼성전자 인재개발원에서 삼성전자 감독관이 삼성직무적성검사(GSAT) 응시자를 대상으로 예비 소집을 진행하는 모습. 삼성 제공삼성그룹은 올해 상반기 공개채용 절차에 돌입한다. 삼성은 4대 그룹 가운데 유일하게 대규모 공채를 운영 중이다. 매회 10만 명가량 취업준비생이 몰리기 때문에 ‘삼성고시’라 불린다. 삼성은 올해 1만2000명 이상 채용할 것으로 예상된다.최근 들어 많은 대기업들이 생산과 사무 현장에 AI 에이전트를 본격적으로 활용하기 시작해 경력이 없는 신입 지원자들의 취업 기회가 많이 줄어 이번 삼성 공채에는 예년보다 더 많은 지원자가 몰릴 것으로 예상된다.삼성은 우수 인재를 확보하고 청년들에게 양질의 취업기회를 제공하기 위해 10일부터 올해 상반기 공채 절차를 진행한다고 9일 밝혔다. 공채에 나선 관계사는 삼성전자, 삼성물산, 삼성바이오로직스, 삼성바이오에피스, 삼성생명, 삼성디스플레이, 삼성SDI, 삼성전기, 삼성SDS, 삼성화재, 삼성증권, 삼성자산운용, 삼성중공업, 삼성E&A, 제일기획, 에스원, 삼성글로벌리서치, 삼성웰스토리 등 18곳이다.이 가운데 부산과 울산 경남에 대형 사업장을 둔 계열사는 삼성전기(부산·첨단 반도체 기판, 적층세라믹콘덴서 생산), 삼성중공업(경남 거제시·조선 및 해양플랜트), 삼성SDI(울산 울주군·에너지저장장치 및 대형 배터리) 세 곳이다.공채 지원자는 10일부터 17일까지 삼성 채용 홈페이지 삼성커리어스(samsungcareers.com)에서 입사를 희망하는 회사에 지원서를 접수하면 된다. 채용절차는 이달 직무적합성 평가를 시작으로 다음 달 삼성직무적성검사(GSAT, Global Samsung Aptitude Test), 5월 면접, 건강검진 순으로 진행된다. 소프트웨어(SW) 직군 지원자는 GSAT 대신 실기 방식의 SW 역량 테스트를 치른다. 디자인 직군 지원자들도 GSAT를 치르지 않고 디자인 포트폴리오 심사를 통해 선발된다.삼성은 해마다 상·하반기에 정기적으로 공채를 진행하는 데 최근 들어 해마다 약 1만2000명가량을 채용했다. 이재용 삼성전자 회장은 지난해 8월 19일 대통령실에서 진행된 경제단체 및 기업인 간담회에서 “국내에서 지속적으로 양질의 일자리를 창출하고 고부가가치 산업을 육성할 수 있게 관련 투자를 지속할 것”이라고 약속한 바 있다. 미래 성장 산업이란 반도체, 바이오, 인공지능 등이다. 최근 반도체 업황 회복과 HBM(고대역폭 메모리) 등 AI 반도체 수요 폭발로 인해 삼성전자 DS(디바이스 솔루션·반도체) 부문의 채용 폭이 넓을 것으로 예상된다.', NULL, '국제신문', 'https://n.news.naver.com/mnews/article/658/0000137353', 'https://imgnews.pstatic.net/image/658/2026/03/09/0000137353_001_20260309150707793.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-03-09 15:07:07', 0, true, '2026-03-09 06:27:05.756817') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1190, '인스코비, 31일 정기주총…전날까지 의결권 대리행사 권유', '인스코비가 정기 주주총회를 앞두고 의결권 대리행사 권유에 나선다.5일 금융감독원 전자공시시스템에 따르면 인스코비는 제56기 정기주주총회를 오는 31일 서울 강남구 청담평생학습관에서 개최할 예정이다. 회사는 주총 의사정족수 확보를 위해 10일부터 30일까지 의결권 대리행사 권유를 진행한다.이번 주총에서는 △재무제표 승인 △이사 선임 △감사 선임 △이사 보수한도 승인 △감사 보수한도 승인 등이 안건으로 상정된다.이사 후보로는 유인수 대표이사, 이혁재 사내이사, 임규오 후보, 이성호 사외이사 후보 등 4명이 추천됐다. 감사 후보로는 김기호 후보가 올라왔다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000080384', 'https://imgnews.pstatic.net/image/293/2026/03/05/0000080384_001_20260305175608849.png?type=w800', 'NEWS_CHEM', NULL, '2026-03-05 17:56:08', 0, true, '2026-03-09 06:27:13.041799') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1191, '[미리보는 이데일리 신문] 40만전자·200만닉스 정조준…8000까지 달린다', '[이데일리 안치영 기자] 다음은 26일자 이데일리 신문 주요 기사다.△1면-40만전자·200만닉스 정조준… 8000까지 달린다-대산 1호 재판 승인 여수·울산은 안갯속-“美 301조 조사 예의주시… 국익 최우선 대응”-에이전틱 AI 포문… AI폰 새 기준 세웠다-거침없이 질주하는 증시, 그래도 ‘빚투’는 경계해야-‘희토류 통제’ 中·日 갈등 격화, 남의 일로만 봐선 안 돼△종합-“고군분투하는 소방관 마음 아팠다” 정의선, 소방로봇 100대 쾌척한다-디지털지갑으로 카페서 주문 척척 원화코인 결제시대 연 KG이니시스△코스피 6000 시대-실적·정책·수급 ‘삼박자’… “코스피 지금도 싸다”-자사주 소각 의무화, ESG 공시 로드맵 6000피 오른 날 쏟아진 주주 친화 정책-“코리아 디스카운트 해소 마지막 퍼즐은 상속세 개편”△종합-최대 산단 여수, 감축규모 두고 진통… “전기로 인하 등 파격 유인책을”-트럼프 “더 센 관세 구상”… 韓 “전략적 소통으로 파장 최소화”-“신용점수 올랐네요”… AI가 알아서 대출 금리 인하 요구-BTS 공연때 숙박비 7만→77만원 바가지 씌우면 즉시 ‘영업정지’△삼성전자 갤럭시S26 언팩-자체 AP ‘엑시노스’ 2년 만에 귀환… AI 연산 고도화에도 기술력 자신-“1년 전 여행사진 줄래” 친구 요청에 AI가 알아서 사진 추린 후 공유 제안△정치-국민투표법 처리 초읽기…범여권 “개헌 논의 서둘러야” 총공세-“우리 민주당, 본연의 역할 잘해” 李대통령, ‘당정 갈등설’ 차단-장동혁표 지선 1호 인재는 회계사·원전 전문가-내달 9~19일 한미연합연습… “전작권 전환 준비”△경제-“가맹점 지원 의무 위반”… 커피빈 가맹본부 칼 겨눈 공정위-늦어진 ‘서학개미 복귀 계좌’… 4월까지 양도세 감면 연장될까-2년 연속 커진 아이 울음소리… 합계출산율 ‘0.8명’ 복귀△금융-‘디지털 금’ 흔들리자… ‘반짝반짝’ 금으로 돈 몰린다-“50만 軍장병 충성심 잡아라”… 은행권, 고금리 유치전-박상진 산은 회장 “HMM 매각보다 부산 이전이 먼저”-롯데카드 신임 대표에 정상호 전 부사장 추천△Global-“미국 지금이 황금기” 트럼프 자화자찬 108분-AI발 한파, 美 IPO 시장까지 얼렸다-AI 랠리 韓증시, 프랑스까지 제쳤다-“휴머노이드 로봇 5년 내 쏟아진다”△산업-中 추격에…삼성·LG전자 ‘미니 LED TV’ 맞불- SK하이닉스, 용인에 21.6조 신규 투자-SK온, 포스코와 3년간 리튬 2.5만t 구매 계약-삼성전기, 품귀 MLCC 가격인상 검토-에코프로, 신재생에너지로 사업영역 넓힌다-반도체 패키징 신기술 한화세미텍 개발 성공△ICT-게임도 칩플레이션 압박 “저사양PC 최적화 집중”-“플랫폼, 규제보다 국가전략산업으로 키워야”-국가정보 관리시스템 전면 재설계 ‘AI정부 인프라 컨트롤타워’ 신설-성장 멈춘 IPTV, 3사 통합 “VOD 상품권‘으로 판 흔든다△성장기업-묻지마 창업에 줄폐업하는 고령층…60대 실업급여 가장 많다-헬스케어전문 세라젬, 가구 이어 인테리어 진출-와이앤아처, 국내 AC 최초 벤처 전주기 투자 체계 구축△생활경제-”3년 1.3만명 채용“… 이재현 회장의 통큰 결단-성수 ’패션지구‘ 만든 무신사 ’플랫폼 연동형 앵커‘ 효과 입증-가방 대신 반지… ’웨딩수요‘에 명품관 판 바뀐다-”일상복부터 프리미엄까지“… 롯데홈쇼핑, 봄·여름 패션전략 확장△Auto&Life-’1400km 질주‘ 현대차 신형 넥쏘, 수소차 종주국 日 뒤흔든다-2200만원 中 전기차…성능은 굿, 디자인은 글쎄△제약·바이오-”CGM 유럽 진출… 성과 본 뒤 확장할 것“-A형 혈우병 치료제 ’헴리브라‘ 日 환자 91%서 약물이상반응 없어-메디포스트 ’카티스템‘ 美 임상3상시험계획 승인 받아-엘엔케이바이오, 신공장 증축 본격화△증권-더 센 상법 온다… 자사주 처분 막차 탄 기업들-’코스피 슬슬 꺾일 때 됐지…‘ 공매도 대기자금 역대 최대-셀루메드 털어낸 인스코비… 상폐 위기 넘을까-순익 60% 뛴 패션사 폰드 비결은 본업 아닌 ’M&A‘-메리츠증권, 수소기업 미코파워에 400억 투자△부동산- 옮기려니 매물 없고, 사려니 대출 찔끔… 세입자 절반 ’갱신권‘ 꺼냈다- 갭투자 옥죄는 정부, 공공·기업 임대 풀어 부작용 막는다-’용적률 2배‘ 보정계수 도입 1년 서울 정비사업 57곳 물꼬 텄다△엔터테인먼트-우리 언니 보러 국중박으로…덕질하며 한국사 여행-JTBC, 올림픽은 독점·패럴림픽은 패싱…보편적 시청권 외면 비난 폭주△피플-”통상 전문성 갖춘 리더“… KAMA, 정대진 신임 회장 선임-최수연 네이버 대표 ”불확실성 시대, 무기는 ’엉덩이의 힘‘“-오준호 ”한국 피지컬AI, 미·중 따라잡을 것“-부동산원 17대 원장에 이현욱 취임-구자열 LS그룹 의장, 한일경제협회장 선출-고려아연 온산제련소 노사 취약계층에 2.5억원 전달△오피니언-경제원리에 충실하자-관세는 죽지 않았고 전장은 넓어졌다△전국-”대입 개혁 첫 단추는 상대평가 폐지…늦어도 내년 중 결정할 것“-생활인구수 톱 찍은 포천시…축제·관광으로 규제 뚫었다-주거환경·교통 ’굿‘…서울시민 행복지수 ’쑥‘△사회-응급실 뺑뺑이 막는다…’광역상황실‘서 중증환자 이송 병원 지정-수능 출제위원 ’소득‘ 들여다본다…”사교육 유착 의심땐 교체“-오염원 불법 배출 사업장 단속 정부, 봄철 초미세먼지 잡는다-예비부부 울리는 ’깜깜이 스드메 계약‘…정부가 퇴치 나선다', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006224759', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_CHEM', NULL, '2026-02-25 22:02:10', 0, true, '2026-03-09 06:27:13.041799') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1192, '관리종목 해제 가능할까…인스코비, ‘상폐 분수령’ 결산 감사 촉각', '반기 의견거절 전력 속 결산 임박…주가는 1년새 70%↓지난해 연간 당기순손실 234억…영업이익은 흑자전환주주명부 열람 가처분 일부 인용…경영권 분쟁 변수 부각[이데일리 신하연 기자] 반기보고서 의견거절로 상장폐지 우려가 불거졌던 코스피 상장사 인스코비(006490)의 정기 감사의견 결과에 관심이 쏠리고 있다. 감사 결과에 따라 상장 유지 여부가 갈릴 수 있어서다. 여기에 최근 주주명부 열람 가처분 소송까지 법원이 일부 인용하면서 지배구조 변수도 새롭게 부각되고 있다.(그래픽=이데일리 김일환 기자)25일 금융감독원 전자공시시스템에 따르면 서울남부지방법원은 이달 초 주주가 인스코비를 상대로 제기한 주주명부 열람·등사 가처분 신청을 일부 인용해 인스코비가 주주명부를 열람·복사할 수 있도록 허용하도록 결정했다.통상 주주명부 열람 가처분은 경영권 분쟁이나 주주권 행사 과정에서 제기되는 경우가 많다는 점에서, 시장에서는 향후 주주 행동주의나 지배구조 갈등으로 확산될 가능성도 배제할 수 없다는 관측이 나온다. 감사의견 확보가 최대 현안으로 떠오른 상황에서 경영권 변수까지 더해진 셈이다.인스코비는 감사 리스크 해소를 위해 관계사 구조 정리에 속도를 내고 있다. 종속회사였던 셀루메드는 지난달 170억원 규모의 제3자배정 유상증자를 실시하면서 최대주주가 인스코비에서 ‘티디랜드마크조합1호’으로 변경됐다. 이에 따라 인스코비의 셀루메드 지분율은 18.2%에서 12.1%로 낮아졌다. 셀루메드는 내달 임시주주총회를 통해 이사회 및 경영진 교체 절차도 진행할 예정이다.셀루메드는 그간 인스코비 감사 리스크의 핵심 요인으로 지목돼 왔다. 미국 뷰첼 파파스와의 장기 로열티 소송에서 최종 패소하며 160억원대 배상금 지급 의무가 확정됐고, 이 과정에서 대규모 우발채무와 추가 손상차손 가능성이 동시에 부각됐다. 실제 인스코비는 셀루메드 관련 손상차손을 인식하며 연결 재무제표상 부담이 가시화된 바 있다.특히 셀루메드의 재무 여력만으로는 배상금 전액을 기한 내 상환하기 어렵다는 점이 문제로 지적됐다. 최대주주였던 인스코비가 추가 자금 지원에 나설 경우 재무 부담이 더욱 확대될 수 있다는 우려가 감사 과정에서도 주요 변수로 작용해 왔다. 이번 경영권 이양은 이러한 잠재 리스크를 구조적으로 차단하기 위한 조치로 해석된다.시장에서는 셀루메드 지배력 정리를 통해 인스코비 연결 재무제표에서 발생하던 핵심 불확실성이 상당 부분 제거됐다는 평가가 나온다. 지속적인 영업적자와 소송 대응 비용 부담이 연결 실적에 반영되던 구조에서 벗어나면서 재무 건전성 측면의 가시성이 개선됐다는 분석이다.다만 최근 발표된 연간 실적에서는 재무 체력의 명암이 동시에 확인됐다. 인스코비의 2025년 연결 기준 매출액은 1055억원으로 전년 대비 약 5% 증가했고, 영업이익은 38억원을 기록하며 전년도 영업손실에서 흑자전환했다. 알뜰폰(MVNO) 사업을 중심으로 한 캐시카우 구조가 수익성 회복을 견인한 것으로 풀이된다.반면 당기순이익은 232억원 순손실을 기록하며 적자전환했다. 관계기업 투자주식 가치 하락에 따른 평가손실과 유동부채 증가에 따른 금융비용 확대가 반영된 영향이다.재무상태도 부담 요인이다. 지난해 말 기준 인스코비의 자기자본은 349억원으로 자본금인 629억원에 미치지 못해 부분 자본잠식 상태다. 자본잠식률은 46.0%로 전년 20.6%에서 확대됐다. 한국거래소 규정에 따르면, 사업연도 말 기준 자본 전액이 잠식되거나 자본금의 50% 이상 잠식이 지속될 경우 상장폐지 사유에 해당한다.인스코비 주가는 최근 1년 사이 70% 넘게 하락했다. 이날 종가는 537원이다.회사 관계자는 “관리종목 해제는 감사보고서가 최종적으로 확정돼야 알 수 있는 부분이라 현재로서는 말씀드릴 수 있는 내용이 없다”면서도 “최대한 적정의견이 나올 수 있도록 감사인과 협의를 지속하고 있으며, 부정적인 결과가 나오지 않도록 관리하고 있다”고 말했다.자본잠식 이슈에 대해서도 “자본잠식률이 50%를 넘지 않아 당장 상장폐지 등의 문제가 발생하는 상황은 아니지만, 여전히 높은 수준인 것은 사실”이라며 “단기간에 해소할 수 있는 사안은 아닌 만큼 현재로서는 당면 과제 대응에 집중할 계획”이라고 설명했다.다만 일각에서 제기되는 자본확충 가능성과 관련해서는 선을 그었다. 회사 관계자는 “유상증자나 감자 등과 관련해서는 현재까지 논의된 바 없다”고 밝혔다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006224602', 'https://imgnews.pstatic.net/image/018/2026/02/25/0006224602_001_20260225193908220.jpg?type=w800', 'NEWS_CHEM', NULL, '2026-02-25 16:56:24', 0, true, '2026-03-09 06:27:13.041799') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1193, '대림통상, 독일 ‘iF 디자인 어워드 2026’ 본상 수상', '< 사진 제공 : 대림통상 >욕실 전문 기업 대림통상이 독일 ‘iF 디자인 어워드 2026(International Forum Design Award 2026)’ 제품 디자인 부문에서 본상인 ‘위너’에 선정됐다고 밝혔다.‘iF 디자인 어워드’는 1953년 독일 인터내셔널 포럼이 주관해 온 디자인상으로 ‘레드닷 디자인 어워드’, 미국 ‘IDEA’와 함께 세계 3대 디자인상으로 꼽힌다. 매년 국제 전문가 심사위원단이 디자인 혁신성, 기능성, 지속 가능성, 사용자 경험 등을 종합적으로 평가해 수상작을 선정한다.대림통상은 앞서 독일 ‘레드닷 디자인 어워드 2025’ 및 ‘2024’에서 싱글레버 수전 시리즈 ‘팔레트(Palette)’와 ‘님프(Nymph)’로 본상을 수상했다. 또한 한국디자인진흥원이 주관하는 ‘굿디자인어워드’에서도 2025년 일체형 비데 ‘크리스탈 3.0’이 동상을, 2024년에는 일체형 비데 ‘옴브레(Ombre)’와 수전 시리즈 ‘팔레트’가 은상을 수상하며 디자인 분야에서의 성과를 이어왔다.이번 ‘iF 디자인 어워드 2026’ 위너를 수상한 제품은 듀얼 스파우트 정수 수전 ‘DUA’다. DUA는 세면 수전, 싱크 수전 두 가지 타입으로 구성되며, 하나의 수전에서 일반수와 정수된 물을 각각 분리해 사용할 수 있는 듀얼 스파우트 구조를 적용한 것이 특징이다. 특히 조리 시 정수된 조리 수를 사용할 수 있도록 설계됐으며, 위생성과 공간 조화를 고려한 설계를 통해 효율적인 물 사용 환경을 구현했다.정수 필터는 싱크 하부 혹은 수납장 내부에 매립되는 방식으로 외부에 노출되지 않아 공간을 정돈된 상태로 유지할 수 있다. 또한 불필요한 시각적 요소를 최소화한 간결한 디자인을 통해 주방 및 욕실 환경을 구현했다.DUA는 세디먼트, 포스트 카본 블록, UF 멤브레인, 포스트 카본 필터로 구성된 4단계 필터링 시스템이 적용됐다. 이를 통해 물속의 불순물과 냄새, 미세입자, 세균 등을 제거해 식음 가능한 수준의 물을 제공한다. 별도의 전원이나 복잡한 장치 없이 안정적인 정수 성능을 구현한 점도 특징이다.대림통상 PR&Design팀 관계자는 “DUA가 iF 디자인 어워드에서 본상을 수상하게 되어 의미가 있다”라며 “대림통상은 위생, 건강, 안전을 주요 가치로 삼고 있으며, 설치와 유지가 용이한 설계를 통해 보편적 사용성을 실현하고자 한다”라고 설명했다.', NULL, '매일경제', 'https://n.news.naver.com/mnews/article/009/0005644823', 'https://imgnews.pstatic.net/image/009/2026/03/04/0005644823_001_20260304094108560.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-04 09:41:08', 0, true, '2026-03-09 06:27:21.216925') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1198, '기업 공시 [3월 6일]', '<코스피 시장>▲진원생명과학(011000)=10억 원 규모 만기 전 전환사채 취득 ▲SK디스커버리(006120)=KKR에 SK이터닉스 지분 2478억 원에 매각 ▲HD현대=2632억 원 규모 DWT 원유운반선 2척 수주 ▲두산에너빌리티(034020)=16조 2330억 원 규모 대형 가스터빈 패키지 공급 계약 ▲마니커(027740)=보통주 2대 1 주식 병합 결정 ▲현금배당결정=이건산업(008250)1주당 보통주 100원,아시아나IDT(267850)500원,삼성공조(006660)80원,기업은행(024110)1048원<코스닥 시장>▲오브젠(417860)=경남은행과 19억 6800만 원 규모 마케팅 시스템 구축 계약 ▲피씨디렉트(051380)=지난해 영업이익 42억 5137만 원으로 전년 대비 129.7% 증가 ▲위더스제약(330350)=자기주식 2191만 원 규모 자사주 2459주 소각 ▲티비씨(033830)=자기주식 38억 1957만 원 규모 자사주 546만 4350주 소각 ▲현금배당결정=진성티이씨(036890)1주당 보통주 330원, 피씨디렉트 70원,이건홀딩스(039020)500원,모코엠시스(333050)24원,현대공업(170030)300원', NULL, '서울경제', 'https://n.news.naver.com/mnews/article/011/0004596530', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_AUTO', NULL, '2026-03-06 16:42:16', 0, true, '2026-03-09 06:27:34.259457') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1199, '삼성공조, 지난해 영업익 32억…전년비 49.9% ↓', '[헤럴드경제=증권부] 삼성공조는 지난해 연결기준 영업이익이 32억4510만원으로 전년대비 49.9% 감소했다고 24일 공시했다.같은 기간 매출액은 1177억3635만원으로 1.7% 증가한 것으로 나타났다.당기순이익은 72억3955만원으로 51.4% 줄어든 것으로 집계됐다.', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002604432', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_AUTO', NULL, '2026-02-24 16:51:10', 0, true, '2026-03-09 06:27:34.259457') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1200, '[Why&Next]''땅 팔아 배당'' 쏘는 소주회사…지속 가능성은?', '하이트진로 독주 국내 소주시장고사 위기 무학 저평가 구조 탈출 시도비영업 자산 매각·분기배당·자사주 소각 추진하이트진로의 독주 체제가 굳어진 국내 소주 시장에서 지방 소주 업체들의 입지가 갈수록 좁아진 가운데 경남 지역을 대표하는 주류 기업 무학이 전면적인 체질 전환에 나서 주목을 받고 있다. 유가증권시장 상장사인 무학은 기업가치 제고와 자사주 처분 계획을 잇따라 내놓고 외형 성장 대신 ''자산·배당·수출''이라는 삼각축을 중심으로 ''지속가능한 경영 구조''를 만들겠다는 전략을 공개했는데, 기업가치의 근간인 실적은 단기 반등이 어려울 것이라는 전망이 우세하다.8일 금융감독원 전자공시시스템에 따르면 유가증권시장 상장사인 무학은 최근 공시를 통해 ''기업가치 제고 계획 보고서''를 발표하고 2027년까지 주가순자산비율(PBR) 0.7배, 자기자본이익률(ROE) 10% 달성을 중기 목표로 제시했다. 현재 PBR 0.41배, ROE 6.8%에서 단계적으로 끌어올리겠다는 것이다.무학의 대표 소주 브랜드 ''좋은데이''자산 팔고, 배당 늘리고, 주식 줄인다…무학의 4대 실행 전략이를 위한 실행 수단은 크게 네 갈래다. 우선 서울과 경남 일대에 보유한 비영업 부동산을 매각 대상 자산으로 분류했다. 지방 주류업체 특성상 과거 사옥·연수원·유휴 부지 형태로 쌓아온 자산이 많지만 이들 자산은 장부상 가치만 키웠을 뿐 실질적인 수익 창출에는 기여하지 못했다. 회사는 이들 자산을 단계적으로 매각해 차입금 상환, 설비 투자 재원, 주주환원 재원으로 재배치할 계획이다.아울러 분기 배당을 정관에 명시하고, 연간 최소 배당금 가이던스를 제시해 투자자들이 매년 배당 수준을 예측할 수 있는 구조를 만들겠다고 밝혔다. 이는 실적이 좋을 때만 배당하는 기존 지방 기업식 관행을 버리고, 배당을 경영의 기본 구조로 내재화하겠다는 의미다. 배당을 통해 주주 기반을 안정화하고, 주가 변동성을 줄이겠다는 전략이다.무학의 경남 창원1공장 외관.또한 향후 3년간 매년 별도 순이익의 5%를 자사주 매입 및 소각에 투입한다. 이는 단순 주가 관리 차원이 아니라 주식 수를 구조적으로 줄여 주당 가치(EPS)를 끌어올리는 전략이다. 국내 소주 시장처럼 성장성이 제한된 산업에서는 외형 확대보다 같은 이익을 더 적은 주식 수로 나누는 구조가 훨씬 중요하다는 판단이 깔려 있다.마지막으로 자사주를 단순 소각 대상이 아닌 설비 투자·조직 인프라 재원으로 적극적으로 활용하겠다고 밝혔다. 실제 무학은 약 100만주를 기초자산으로 교환사채(EB)를 발행해 창원2공장 설비 교체와 연수원 신축 자금으로 투입하기로 했다. 이어 지난달 15일에는 주당 8387원, 총 40억6235만원 규모의 자기 주식 48만4363주를 삼성공조에 처분했다. 무학은 이를 ''상생협력 강화를 위한 사업협력관계 구축''이라고 설명했다.하이트진로 독주 체제…지방 소주는 ''존재감 실종''무학의 소주 브랜드 ''화이트''무학의 이번 결정은 국내 소주 시장 구조와 직결된다. 업계 1위인 하이트진로는 수도권·대형마트·편의점 채널을 사실상 장악하며 전국 단위의 유통망을 완성했다. 반면 지방 소주 업체들은 거점 지역 밖으로 유통망을 확장하기 쉽지 않고, 지역 상권에서조차 하이트진로 브랜드에 밀리고 있다. 여기에 회식 문화 축소와 함께 저도주·하이볼·RTD(Ready To Drink) 트렌드가 급속히 확산하며 희석식 소주의 상대적 매력도는 지속적으로 하락하고 있다.이 때문은 무학은 수출로 돌파구를 찾는다는 전략이다. 다만 수출의 절대적인 규모는 아직 작다. 무학의 2024년 수출액은 172억원으로 전년(163억원) 대비 늘었지만 유의미한 성장세로 보기는 어렵다. 지난해 3분기 기준 107억원 수준으로 전체 매출(974억원)의 10% 안팎에 그치고 있다.실적도 이러한 구조적 변화를 고스란히 반영하고 있다. 코로나19 팬데믹(세계적 대유행) 시기 적자를 기록하다 2022년 흑자 전환 이후 2024년 매출 1520억원, 영업이익 168억원으로 흑자를 꾸준히 유지했지만, 지난해 3분기까지 누적 매출은  1089억원으로 전년 동기 대비 5% 감소했다. 이 기간 영업이익은 36% 감소한 80억원에 그쳤다. 지난해 연간 매출은 1400억원을 밑돌고, 영업이익도 100억원대로 후퇴할 것이라는 전망이 나온다.내수 의존 탈피…수출·자산·배당 3축 전환이번 체질 전환 전략을 통해 단기간에 실적 반등을 이뤄낼 가능성은 높지 않다는 관측이다. 국내 시장의 소주 소비 감소세가 분명하고, 하이트진로와의 격차도 영업력·마케팅 투자 규모 등을 고려하면 단기간에 좁히기 어렵다. 본업 성장만으로 ROE 10%를 달성하기는 현실적으로 쉽지 않은 상황인 셈이다.다만 무학의 전략은 ''성장 기업''이 아닌 ''현금 창출형 안정 기업''으로의 전환이라는 점에서 성과를 낼 여지는 있다. 비영업 자산 매각을 통해 차입 부담을 낮추고, 분기배당과 최소 배당 가이던스를 정착시킬 경우 주가는 실적보다 배당 안정성에 의해 재평가되는 구조로 옮겨갈 가능성이 크다. 특히 별도 순이익의 5%를 매년 자사주 매입·소각에 투입한다는 방침이 실제로 집행될 경우 이익 정체 국면에서도 주당가치(EPS)는 점진적으로 개선된다.수출 확대 역시 극적으로 실적 반등을 주도할 만한 요인이라기보다는 하방을 떠받치는 보완재에 가깝다. 과일소주를 중심으로 한 동남아·중국·미주 한인 상권 매출이 안정적으로 늘어 수출 비중이 15% 수준까지 올라간다면 내수 감소에 따른 매출 공백을 상당 부분 메울 수 있다. 다만 아직 해외 매출의 절대 규모가 작아 수출이 단기간에 실적 구조를 바꿀 수준은 아니라는 점도 분명하다.이 때문에 이번 전략이 성공한다면 무학은 안정적인 현금 창출형 주류 기업으로 시장에서 재평가받을 수 있다. 반대로 배당 가이던스 이행이 흔들리거나 자산 매각이 지연될 경우 이번 기업가치 제고 계획은 단발성 선언에 그칠 가능성도 있다.  심은주 하나증권 연구원은 "주류 수요 부진이 이어지고 있어 단기적 펀더멘털의 유의미한 개선은 어려워 보인다"면서도 "사측 공시대로 올해 연간 최소 주당 배당금이 유의미한 수준에서 결정된다면 주가 하방은 과거 대비 단단해질 것"이라고 내다봤다.무학의 수출용 과일소주 ''좋은데이''', NULL, '아시아경제', 'https://n.news.naver.com/mnews/article/277/0005703664', 'https://imgnews.pstatic.net/image/277/2026/01/08/0005703664_001_20260108112114219.jpg?type=w800', 'NEWS_AUTO', NULL, '2026-01-08 07:13:00', 0, true, '2026-03-09 06:27:34.259457') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1201, '''나인트리 호텔 동대문'' 인수전 8곳 몰렸다…800억~900억 초반 형성', '이번주 재입찰…8곳 참여 속 숏리스트 선정 착수2040년까지 호텔 책임임대차…안정·수익성 ''부각''도심·동대문 상권 인접…관광·비즈니스 수요 흡수수도권 호텔수요 ''증가''…기관 투자자들 관심 지속이 기사는 2026년02월25일 16시42분에마켓인 프리미엄 콘텐츠로 선공개 되었습니다.[이데일리 마켓in 김성수 기자] 신한서부티엔디리츠가 서울 중구에 위치한 ''나인트리 바이 파르나스 서울 동대문''(이하 나인트리 호텔 동대문) 매각을 위한 재입찰에 돌입한다. 금액은 800억~900억원 초반에 형성됐다.이번 매각은 신한서부티엔디리츠의 첫 자산 매각이다. 호텔 시장 회복세와 맞물려 매각에 따른 시세차익 기대감이 커지고 있다. 호텔 매각이 완료되면 투자자들에게 특별배당이 지급될 예정이다.이번주 재입찰…8곳 참여 속 숏리스트 선정 착수25일 투자은행(IB) 업계에 따르면 신한서부티엔디리츠는 최근 나인트리 호텔 동대문 매각을 위한 1차 입찰을 진행했으며, 총 8곳이 참여했다.회사 측은 재입찰을 통해 숏리스트(최종 후보 명단)를 선정하고, 인터뷰 등을 거쳐 우선협상대상자를 최종 결정할 계획이다.재입찰 대상자들이 제출한 가격은 800억원 초반~900억원 초반 수준에 형성됐다. 시장에서는 나인트리 호텔 동대문이 책임임대차 구조를 기반으로 한 안정적인 현금흐름을 갖고 있어 투자 매력이 높았다는 평가가 나온다.나인트리 바이 파르나스 서울 동대문 (사진=신한서부티엔디리츠)나인트리 호텔 동대문은 서울지하철 2·4·5호선 동대문역사문화공원역과 지하철 2·5호선 을지로4가역에서 걸어서 약 6분 거리에 있는 3성급 호텔이다. 동대문 상권과 도심권역(CBD), 동대문디자인플라자(DDP) 접근성이 우수해 관광·비즈니스 수요를 동시에 흡수할 수 있는 입지로 평가된다.특히 이 호텔은 파르나스호텔과 2040년까지 책임임대차 계약을 체결하고 있다. ''최소보장임대료''(MRG)와 ''매출 연동 임대료''가 결합된 구조로, 하방 안정성과 상방 수익성을 동시에 확보한 자산이라는 점이 강점으로 꼽힌다.''최소보장임대료''는 아웃렛, 복합쇼핑몰 등에서 매출이 낮아도 사전에 정해둔 정액의 최소 금액을 의무적으로 지불하는 임대료 계약 방식이다. 반면 ''매출 연동 임대료''는 고정된 월세 대신, 임차인의 월 매출액 중 일정 비율을 임대료로 지불하는 방식이다.국내에서 호텔 수요는 지속적으로 증가하는 추세다. 외국인 관광객 급증과 내국인 여가 수요 확대, K-콘텐츠를 중심으로 문화관광 활성화가 맞물리면서 숙박 수요가 빠르게 증가해서다.마이스(MICE) 산업도 회복세를 보이는 영향이다. 마이스란 기업회의, 포상여행, 국제회의, 전시회 등을 포함하는 서비스 산업을 의미한다.수도권 호텔수요 ''증가''…기관 투자자들 관심 지속수도권 주요 호텔들은 최근 객실당 4억원대 중반 수준에서 거래되는 등 시장 가격이 상승해왔다. 반면 신규 호텔 공급은 제한적인 상황이다. 호텔 멸실 및 개발비 상승 때문이다.특히 서울 내 공급 예정 호텔 중 80% 이상은 5성급 럭셔리 호텔로, 3~4성급 호텔의 추가 공급이 제한적이다. 수도권 주요 호텔에 대한 기관투자자의 관심도 꾸준히 증가하고 있다.이런 흐름을 감안하면 나인트리 호텔 동대문은 작년 매입가 대비 상당 수준의 시세차익이 가능할 것으로 보인다.앞서 신한서부티엔디리츠는 지난 2024년 9월 나인트리 호텔 동대문을 540억원(객실당 약 2억4700만원)에 매입했다. 최근 호텔 매매가격이 객실 당 4억원대 중반 이상이라는 점을 감안하면 상당한 시세차익 실현이 예상된다.신한서부티엔디리츠는 이번 매각이 마무리되면 투자자들에게 특별배당 지급도 추진할 예정이다.신한서부티엔디리츠 구조 (자료=신한서부티엔디리츠)신한서부티엔디리츠는 스폰서인 서부티엔디(서부T&D)와 리츠 자산관리회사(AMC)인 신한리츠운용의 협업으로 만들어진 리츠다.투자 자산으로는 △복합 쇼핑몰 ‘인천 스퀘어원’ △호텔 ‘용산 그랜드머큐어’(자(子)리츠 신한서부티엔디제1호리츠) △‘나인트리 호텔 동대문’(자리츠 신한서부티엔디제2호리츠) △호텔·오피스 ‘광화문G타워’(자리츠 신한광화문지타워리츠) 등이 있다.IB업계 관계자는 “나인트리 호텔 동대문은 최근 서울 도심 호텔 자산에 대한 투자 수요가 꾸준한 상황에서 장기 책임임대차가 체결된 물건이라는 점이 입찰 경쟁을 유도한 것으로 보인다”며 “가격과 운용 전략을 종합적으로 고려해 최종 매수자가 가려질 것”이라고 말했다.', NULL, '이데일리', 'https://n.news.naver.com/mnews/article/018/0006224660', 'https://imgnews.pstatic.net/image/018/2026/02/25/0006224660_001_20260225174407088.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-25 17:44:07', 0, true, '2026-03-09 06:27:41.362120') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1202, '[클릭 e종목]"서부T&D, 호텔이익·개발이익 기대감에 목표가↑"', '하나증권은 서부T&D에 대해 투자의견 매수를 유지하고 목표주가를 2만1000원으로 기존 대비 20% 상향한다고 23일 밝혔다.이기훈 하나증권 연구원은 "올해 2분기로 예상한 방한 중국인과 방일 중국인의 골든크로스가 훨씬 빠르고 강력하게 나타나고 있다"며 "용산에서 1700개 객실의 호텔을 운영하는 서부T&D의 객실점유율(OCC)과 일평균 객실 요금(ADR)이 동반 상승하며 사상 최대 실적이 이어질 것"이라고 전망했다.이어 "용산과 신정동 개발이 가시화하면서 올해 4분기에서 내년 1분기 사이 착공 및 분양이 이뤄질 것이며 완판 시 내년부터 2031년까지 상당한 개발 이익이 반영될 수 있는 만큼 레저 산업 내 지속 최선호주로 제시한다"고 덧붙였다.특히 이 연구원은 "용산 나진 상가 일대 특별계획으로 분류된 대부분 부지가 지난해 건축심의를 통과해 올해 4분기 착공 및 분양이 예상되는 가운데 2만2000평 중 오피스텔과 오피스가 각각 1만평이고 하이엔드 오피스텔 분양 이슈가 없다고 가정하면 분양 매출만 5000억원 내외로 예상된다"고 했다.그는 "신정동은 899가구로 2027년 1분기 착공 및 분양이 예상되는데 특별한 이슈가 없다면 분양 매출만 1조원을 넘을 것"이라며 "이 밖에도 2만평 이상의 물류센터와 복합쇼핑몰이 1년의 시차를 두고 완공되면 상당한 임대수익도 거둘 수 있다"고 설명했다.이 연구원은 "서부T&D의 지난해 4분기 매출액과 영업이익은 각각 774억원, 229억원으로 모두 사상 최대 실적"이라며 "호텔은 OCC 75% 내외, ADR 20만원 내외로 추정되고, BTS의 컴백 및 공연과 한일령의 혜택을 받을 것으로 전망한다"고 전했다.', NULL, '아시아경제', 'https://n.news.naver.com/mnews/article/277/0005724179', 'https://imgnews.pstatic.net/image/277/2026/02/23/0005724179_001_20260223074711185.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-23 07:46:37', 0, true, '2026-03-09 06:27:41.362120') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1203, '"돈 많이 벌었어요" 백화점에서 펑펑…그 돈, 반도체에서 나왔다', '수출·증시 호황에 내수주 실적개선 기대감자산가격 상승→소비 자극 ''부의 효과'' 전망반도체를 중심으로 한국의 수출이 큰 폭으로 개선되고 주식 시장도 살아나면서 백화점과 대형마트, 호텔 등 내수시장으로 부의 효과(Wealth effect)가 나타날 것이라는 기대감이 커지고 있다.서울 시내 백화점 전경.수출 개선·증시 호황에 내수주 실적개선 기대감 커져12일 한국거래소와 KB증권 등에 따르면 2월 들어 우리 증시에서 가장 높은 수익률을 기록한 업종은 유통주로 평균 상승률이 18%에 달했다. 2월 들어서는 백화점과 대형마트 등 주요 유통주 주가 상승률이 코스피 평균을 압도했다.롯데쇼핑의 2월 주가 상승률은 37%에 달했으며 이마트는 35%, 신세계 17%, 현대백화점도 16%를 기록했다. 유통주 주가 상승률은 이달 1~2%가량 상승하는 데 그친 코스피 수익률을 크게 뛰어넘었다.대표적인 내수 업종인 호텔 관련주들도 수익률이 좋았다. 파르나스호텔을 자회사로 둔 GS피앤엘은 이달에만 20%가량 주가가 상승했고 서울드래곤시티호텔을 보유한 서부T&D도 올해 들어 주가가 39% 상승하는 등 코스피 수익률을 크게 뛰어넘었다.의류 관련주들도 주가가 크게 상승했다. 작년 4분기 깜짝실적을 발표한 한섬은 이달에만 주가가 20%가량 상승했으며 LF 역시 이달 주가가 14% 이상 올랐다.자산가격 상승→소비 자극 ''부의 효과'' 나타날 전망시장에서는 반도체를 비롯한 조선, 방위산업, 전력기기 등 주요 산업의 수출 호황과 증시 활황 등에 힘입어 올해 국내 소비가 본격적으로 회복할 것으로 관측했다. 특히 증시의 가파른 상승이 소비자들의 지갑을 두툼하게 하고 내수 경기 개선으로 이어지는 긍정적인 효과가 발생할 수 있다고 봤다.유정현 대신증권 연구원은 "작년 4분기부터 본격적으로 소비가 회복세로 돌아서는 것이 대부분의 유통 채널에서 확인되고 있다"며 "주식시장의 가파른 상승으로 부의 효과가 발생할 것"이라고 기대했다.최근 소비자심리지수가 반등한 것도 내수 경기 개선에 대한 기대감을 높인다. 한국은행의 지난달 소비자심리지수(CCSI)는 110.8로 지난해 12월(109.8)보다 1포인트 올랐다. 100보다 높으면 장기평균(2003~2024년)과 비교해 소비 심리가 낙관적이라는 의미다.지난달 한은의 뉴스심리지수는 117.48로 2021년 7월(117.71) 이후 4년6개월 만에 최고치를 기록하기도 했다. 뉴스심리지수는 경제 분야 언론 기사에 나타난 경제 심리를 지수화한 것이다. 올해 코스피가 5000포인트를 넘기는 등 증시 호황이 이어지면서 전반적인 소비심리가 개선됐다는 평가다.이은택 KB증권 연구원은 "증시가 급등하면서 올해 우리나라의 국내총생산(GDP)과 소비심리를 자극할 가능성이 크다"며 "증시 급등은 보통 1년의 시차를 두고 영향을 미치는데 작년에 우리 증시가 76% 급등한 만큼 올해 영향을 끼칠 것"이라고 설명했다.', NULL, '아시아경제', 'https://n.news.naver.com/mnews/article/277/0005720871', 'https://imgnews.pstatic.net/image/277/2026/02/12/0005720871_001_20260212111118458.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-12 06:20:00', 0, true, '2026-03-09 06:27:41.362120') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1204, '대양금속, 전환사채 만기 3개월 연장…전환가액 하향 조정', '대양금속은 제22회차 국내 무기명식 이권부 무보증 사모 전환사채의 만기일을 기존 2월10일에서 5월10일로 3개월 연장했다고 11일 밝혔다. 해당 사채는 전액 회사가 보유 중이며 일부 또는 전액을 재매도할 계획이다.시가 하락에 따라 전환가액도 기존 1438원에서 1414원으로 조정됐다. 이에 따라 전환·행사·교환 가능 주식 수는 556만3282주에서 565만7708주로 증가했다.앞서 대양금속은 2022년 11월 영풍제지 지분 인수를 위한 자금 조달을 목적으로 비피에이치조합을 대상으로 150억원 규모의 해당 전환사채를 발행한 바 있다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000079281', 'https://imgnews.pstatic.net/image/293/2026/02/11/0000079281_001_20260211093412738.png?type=w800', 'NEWS_ETC', NULL, '2026-02-11 09:31:07', 0, true, '2026-03-09 06:27:49.571749') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1205, '블루산업개발, 설 맞아 평택 진위면 취약계층에 선물… "따뜻한 나눔"', '임직원 봉사 모임 ''해밀회'' 중심으로 20년 나눔 이어가블루산업개발이 설 명절을 맞아 평택시 진위면 관내 취약계층을 위한 선물세트 기부 전달식을 진행했다. /사진=블루산업개발블루산업개발은 설 명절을 맞아 평택시 진위면 관내 취약계층을 위한 선물세트 기부 전달식을 진행했다고 9일 밝혔다.이날 진위면행정복지센터에서 진행된 전달실에는 최남일 진위면장을 비롯한 면사무소 직원과 마을 이장단, 블루산업개발 임직원들이 참석했다. 블루산업개발은 진위면 관내 취약계층 35세대를 선정해 쌀과 홍삼, 생필품 세트 등 명절에 필요한 물품을 전달할 예정이다. 특히 이번 후원에는 블루산업개발의 계열사인 CSA코스믹이 함께 참여해 따뜻한 나눔의 의미를 더했다.블루산업개발은 임직원들이 자발적으로 참여하는 사내 봉사 모임 ''해밀회'' 모금과 회사의 자체 지원을 통해 매 명절마다 지역사회 나눔 활동을 펼치고 있다. 취약계층 지원뿐만 아니라 지역 고등학생 장학금 지원 등 다양한 사회공헌 활동을 20년째 이어오며 지역사회와 상생하는 기업으로 자리매김하고 있다.권혁범 블루산업개발 대표는 "설 명절을 맞아 이웃들이 조금이나마 따뜻한 시간을 보내길 바라는 마음으로 준비했다"며 "앞으로도 지역사회와 함께 성장하는 기업으로서 나눔 활동을 꾸준히 이어가겠다"고 말했다.최남일 진위면장은 "매년 명절마다 지역 주민들을 위해 따뜻한 나눔을 실천해 주시는 블루산업개발에 깊이 감사드리며, 이러한 관심과 지원이 어려운 이웃들에게 큰 힘이 되고 있다"며 "면에서도 복지 사각지대 해소를 위해 더욱 노력하겠다"고 전했다.', NULL, '동행미디어 시대', 'https://n.news.naver.com/mnews/article/417/0001129092', 'https://imgnews.pstatic.net/image/417/2026/02/09/0001129092_001_20260209180612500.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-09 18:05:23', 0, true, '2026-03-09 06:27:49.571749') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1206, '"당신의 경영권, 안전한가요?…가업승계는 건강검진처럼"', '[인터뷰] 김상훈·김승아 법무법인 트리니티 변호사 인터뷰김승아 법무법인 트리니티 변호사(왼쪽), 김상훈 트리니티 변호사 /사진=이기범 기자 leekb@"경영권 가업 승계는 지분율 50% 이상 확보하는 게 중요합니다만 여의치 않을 때를 대비해 여러 단계를 건강검진처럼 미리 들여다봐야 합니다. 유비무환(有備無患·준비하면 근심이 없다)이죠."김상훈 법무법인 트리니티 변호사(50)는 29일 머니투데이와 만나 "가족기업 대부분은 폐쇄적인 구조의 비상장사가 많은데 이런 회사의 정관은 10~20년 전에 만들어 대주주(창업주)에게 불리하거나 개정상법을 반영하지 않은 경우가 있다"며 이같이 밝혔다.김상훈 변호사는 가업상속·신탁 전문가로 최근 ''가족기업 전략센터''를 출범했다. 가족기업의 설립부터 경영 승계까지 정관, 법률, 소송 등 전 분야에서 원스톱 법률 서비스를 제공하기 위해서다. 1세대 창업주들이 물러나기 시작한 시대상을 반영했다.김상훈 변호사는 "경영권을 갖지 못한 소주주주는 상속인들의 입장에서 회사의 경영 참여를 통한 소수주주권 행사가 가능하다"며 "창업주의 사후 지분율뿐만 아니라 사전에 정관을 정비해 후계 구도에서 분쟁이 발생할 여지를 최소화할 필요가 있다"고 말했다.가족기업 전략센터 공동센터장인 경영권 분쟁 전문가 김승아 변호사(44) 역시 대비의 중요성을 강조하고 있다. 예를 들어 소수 지분권자가 이사진을 뽑을 수 있는 집중투표제를 정관에서 제외시키지 않는다면, 소수주주 측에서 선임한 이사가 이사회에 진입하는 것을 막기 어려울 수 있다. 일부 창업주들은 이런 사실을 알지 못했거나 인지하지 않았다.김상훈 변호사와 김승아 변호사가 함께 담당했던 송사에서 전기통신업체 Y사는 상속자(장남 23%, 차남 18%, 장녀 15%, 차남의 아들 13% 등)간 지분 다툼이 생겼다. 장남은 회사를 10년 넘도록 경영했지만 지분율은 50%가 넘지 않았다. 창업주가 사망하고 장남은 차남 측(차남과 장녀 등)에게 쫓겨났다. 차남 측은 최대주주로 경영권을 행사하면서 이사회를 열고 보수를 받았다. 그러면서 장남에게 월급과 배당금을 지급하지 않았다.이 사건은 상속받은 부동산을 활용해 가족 간 합의를 이뤘다. 회사 인력과 자산·부채를 통신사업과 부동산사업으로 인적·물적분할하고, 사업을 분담하는 구조의 주식 스왑 계약을 체결했다. 장남이 부동산사업 지분 60%를, 차남은 통신사업 지분 60%를 각각 갖게 됐다.김승아 변호사는 "Y사의 차남처럼 이사 보수를 챙겨간다면 위법한 주총의 결정이라 무효고, 애초에 특별한 이해관계가 있는 주주가 의결권을 가질 수도 없다"며 "소수 지분을 적정한 가격으로 평가해 매입해주거나, 배당가능한 회사 자금을 활용해 자기주식 취득이나 유상감자로 엑싯을 돕는 등 여러 방안을 염두에 둬야 한다"고 했다.김상훈 변호사(사법연수원 33기)로 여성도 제사 주재자가 될 수 있다는 대법원 전원합의체 판결과 상조금은 유족의 고유재산이라는 대법원 판결, 유언대용신탁과 유류분에 관한 효시 판결 등에서 승소 이력을 갖고 있다. 김승아 변호사(사법연수원 37기)는 피씨디렉트, 대양금속, 영풍제지, 한미사이언스, 아이로보틱스, 디케이엠 등 기업 경영권 분쟁 사건을 담당했다.김승아 법무법인 트리니티 변호사(오른쪽), 김상훈 트리니티 변호사 /사진=이기범 기자 leekb@', NULL, '머니투데이', 'https://n.news.naver.com/mnews/article/008/0005311451', 'https://imgnews.pstatic.net/image/008/2026/01/29/0005311451_001_20260129180214288.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-29 16:30:15', 0, true, '2026-03-09 06:27:49.571749') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1221, '재료부터 공정까지… GS25, 김밥 ''풀체인지'' 나서', '고객이 GS25에서 새롭게 선보이는 튀김유부참치김밥과 근본김밥을 들고 포즈를 취하고 있다. [사진=GS리테일][디지털데일리 장주영 기자] GS25가 김밥을 한층 업그레이드하는 ‘풀체인지 리뉴얼’을 진행한다고 9일 밝혔다.회사에 따르면 이번 리뉴얼은 고급화되는 소비자 입맛과 김밥으로 한 끼 식사를 해결하는 고객이 늘어남을 반영해 김밥 전문점 수준 이상의 맛 경쟁력을 확보하기 위해 추진됐다. GS25는 100여 명의 고객 및 임직원을 대상으로 한 설문조사를 통해 개선점을 도출하고 상품 개발에 반영했다.가장 먼저 적용된 변화는 밥과 토핑의 균형이다. 김밥 속 재료의 맛을 더욱 풍부하게 느낄 수 있도록 밥 비중을 약 10% 축소하고 토핑 구성을 강화했다. 밥의 감칠맛을 강화하기 위해 콩 추출물을 활용한 조미액을 더했으며, 고소한 풍미를 살리기 위해 참깨와 참기름도 1.5배 확대 사용했다.또 집밥처럼 토핑 개별의 맛을 살리기 위해 맛살을 튀기거나 계란 굽는 시간을 늘리는 등 재료별 조리 공정을 추가했다.패키지도 새롭게 변경했다. 100% 국내산 쌀과 햇김 사용 등 원재료의 품질을 강조하며 토핑이 가득 담긴 모습을 연출했다.GS25는 3월부터 오는 4월 1주차까지 리뉴얼 상품과 신상품을 주차별로 선보일 예정이다. 3월 한 달간 총 10여 개의 상품을 선보일 계획이다.오는 11일에는 ‘튀김유부참치김밥’과 ‘THE근본김밥’ 등 신상품 2종을 출시한다. 튀김유부참치김밥은 잘게 썬 햄과 유부 튀김을 섞은 밥에 참치마요를 메인 토핑으로 더해 감칠맛과 씹는 식감을 살린 제품으로 가격은 3500원이다.THE근본김밥은 구운 계란과 맛살 튀김을 핵심 재료로 활용해 집에서 만든 김밥의 정석을 구현했다. 가격은 2900원이다. 이어 내주에는 국내 1위 김치 브랜드 ‘종가’와 협업한 김치 김밥 시리즈 3종이 출시될 예정이다.김밥 풀체인지 리뉴얼을 기념해 다양한 프로모션도 진행한다. 3월 새로 출시하는 김밥 대상으로 네이버페이 결제 시 40% 페이백 혜택을 제공한다. 튀김유부참치김밥, THE근본김밥, 종가김치참치김밥, 스팸김치볶음김밥 등 4종에 대해서는 1000원 QR 할인 행사도 함께 운영할 예정이다.안진웅 GS리테일 FF팀 MD는 “최근 편의점 김밥이 간단한 간식을 넘어 한 끼 식사로 자리 잡으며 맛과 품질에 대한 고객 기대치도 높아지고 있다”며 “밥과 재료의 밸런스부터 조리 공정까지 개선해 김밥 전문점 수준 이상의 맛을 구현하고, 상품 라인업을 늘려 김밥 카테고리 경쟁력을 지속 강화해 나갈 계획”이라고 전했다.', NULL, '디지털데일리', 'https://n.news.naver.com/mnews/article/138/0002219974', 'https://imgnews.pstatic.net/image/138/2026/03/09/0002219974_001_20260309151507553.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 15:15:07', 0, true, '2026-03-09 06:28:38.700231') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1208, '한국거래소 시스템 오류로 일부 ETF 종목 거래 ''먹통''', '사진=게티이미지뱅크한국거래소의 거래 시스템 과부하로 유가증권시장의 일부 상장지수펀드(ETF) 거래 체결이 정상적으로 이뤄지지 않은 것으로 나타났다.18일 한국거래소에 따르면 이날 낮 12시 30∼33분, 오후 1시 39∼41분께 거래소 전산 문제로 일부 ETF 주문이 거부되거나 주문 처리가 지연됐다. 현재는 거래 시스템이 복구되면서 정상화됐다는 게 거래소 측 설명이다.금융투자업계에선 증시 변동성이 커지며 거래량이 급증한 상황에서 발생한 전산 오류로 추정하고 있다. 이란 사태 이후 시장 변동성이 확대돼 주식 거래 시스템에도 부담이 커졌다는 분석이다.한국거래소의 전산 오류는 이번이 처음이 아니다. 지난해 3월 시스템 오류로 유가증권시장 주식 계약 체결이 약 7분간 멈추는 사고도 있었다. 전체 거래가 멈춘 건 2005년 한국거래소 통합 출범 후 처음이었다.최근 증권업계에선 과부하 등에 따른 전산장애가 잇따르고 있다. 지난 5일 한국투자증권 모바일트레이딩시스템(MTS)에서 계좌 잔액과 수익률이 잘못 표시되는 전산 오류가 발생한 데 이어 미래에셋증권 MTS에서도 ETF 가격 급락 알림이 장 마감 이후 대량으로 지연 발송되기도 했다. 카카오페이증권에선 같은 날 약 40분 동안 ‘미국 주식 모으기’ 주문이 일부 체결되지 않는 문제가 발생했다.거래소 관계자는 "내부적으로 어떤 시스템 오류가 발생했는지 파악 중"이라며 "현재는 거래가 정상적으로 이뤄지고 있다"고 말했다.', NULL, '한국경제', 'https://n.news.naver.com/mnews/article/015/0005259884', 'https://imgnews.pstatic.net/image/015/2026/03/09/0005259884_001_20260309152007963.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 15:20:07', 0, true, '2026-03-09 06:27:57.543047') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1209, '韓·美·中 AI 집중투자...신한G3AI테크EMP목표전환형 펀드 나왔다', '[사진 신한자산운용][이코노미스트 송현주 기자] 신한자산운용이 글로벌 인공지능(AI) 산업 성장의 수혜를 입을 것으로 기대되는 한국·미국·중국 3개국의 핵심 테크 ETF에 투자하는 ''신한G3AI테크EMP목표전환형 펀드''를 출시한다고 9일 밝혔다.이 펀드는 글로벌 AI 산업의 핵심축인 ''G3(한·미·중)''의 AI 밸류체인에 집중 투자해 7%의 목표수익률 달성을 추구하는 목표전환형 상품이다. 주식 및 ETF와 국내 단기채권형 ETF에 분산 투자해 성장성과 안정성을 동시에 꾀하는 구조로 설계됐다. 최근 글로벌 AI 산업은 미국의 빅테크 중심 초거대 AI 투자 확대, 한국의 반도체 제조 경쟁력, 중국의 대규모 제조 및 데이터 인프라를 기반으로 가속화되고 있다. 신한자산운용은 AI 상용화가 산업 전반으로 확산함에 따라 관련 기업들의 밸류체인 확장세가 지속될 것으로 내다봤다.''신한G3AI테크EMP목표전환형 펀드''는 주식 관련 자산을 50% 미만으로 운용하며, 각 시장을 주도하는 핵심 AI 업종 ETF와 개별 주식을 중심으로 포트폴리오를 구성한다. 국가별 투자 비중은 지역별 모멘텀과 EPS(주당순이익) 추정치 변화율 등을 종합적으로 고려해 결정할 방침이다. 채권 부문은 국내 단기채권 ETF에 투자해 변동성을 낮추고 안정적인 이자 수익을 추구한다.신한자산운용은 올해 목표전환형 펀드 시장에서 두드러진 성과를 내고 있다. 지난 1월 출시한 ''신한대한민국의패러다임 목표전환형 펀드 1호''와 ''신한글로벌AI인프라목표전환형 펀드'', 2월 출시한 ''신한코어패러다임 목표전환형 펀드 2호'' 등 총 3종의 펀드를 통해 2400억 원 이상의 자금을 모집했다. 특히 ''신한코어패러다임 목표전환형 펀드 2호''는 목표 수익률을 조기에 달성해 성공적으로 상환된 바 있다.김성훈 신한자산운용 글로벌투자운용본부장은 "AI 산업을 이끌고 있는 한국·미국·중국의 주요 ETF와 핵심 기업에 투자하는 상품"이라며 "올해 중국의 대표적인 메모리 반도체 기업과 로봇 기업(Unitree Robotics) 등 과창판·창업판 상장이 예상되는 기업들은 개인의 직접투자가 제한적인 만큼 펀드를 활용하는 것이 좋은 투자 대안이 될 수 있다"고 설명했다.해당 펀드는 카카오뱅크, 미래에셋증권, LS증권 등을 통해 가입할 수 있으며, 모집 기간을 거쳐 오는 17일 설정될 예정이다. 이 펀드는 실적배당형 상품으로 과거 수익률이 미래 수익률을 보장하지 않으며, 운용 결과에 따라 원금 손실이 발생할 수 있다.', NULL, '이코노미스트', 'https://n.news.naver.com/mnews/article/243/0000094170', 'https://imgnews.pstatic.net/image/243/2026/03/09/0000094170_001_20260309140414016.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 14:04:14', 0, true, '2026-03-09 06:27:57.543047') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1210, '[주총 포커스]애경케미칼, 1년만에 ''지주사 등기임원 겸직'' 부활', '/사진 제공=애경케미칼애경케미칼이 정석 AK홀딩스 전략기획부문장(상무)을 신임 기타비상무이사로 추천했다. 정 상무는 지주회사인 AK홀딩스 이사회에도 조만간 합류할 예정이다. 그가 지주사 전략 부문 임원인 데다 양측 이사회에도 모두 참여하게 되는 만큼 이는 AK홀딩스와 애경케미칼의 의사결정 연계를 강화하기 위한 조치로 해석된다.애경케미칼은 이달 24일 정기 주주총회를 열고 정 상무를 기타비상무이사로 선임한다.눈에 띄는 점은 기존 기타비상무이사의 임기만료에 따른 조치가 아닌 중도교체를 택했다는 것이다. 민풍기 AK홀딩스 상무보는 지난해 정기 주총 때 애경케미칼 이사회에 합류해 임기가 2년 남은 상태다.이 같은 결정은 지주사이자 대주주인 AK홀딩스의 이사회 재편 움직임과 맞물린 것으로 해석된다. AK홀딩스는 기존 사내이사 4인이 임기를 채 마치기 전에 2인을 신규 사내이사 후보로 추천했다. 이에 기타비상무이사였던 채동석 애경그룹 부회장이 사내이사로 선임되며 역할이 확대됐고 다른 한 자리는 애경케미칼 등기임원 후보로도 추천된 정 상무가 맡게 됐다.정 상무가 선임될 경우 애경케미칼은 1년 만에 지주사 등기임원을 자사 이사회 구성원으로 다시 받아들이게 된다.그간 AK홀딩스와 애경케미칼 이사회에는 최소 1인의 겸직 인사가 포함됐으며 이 역할은 통상 상근 의무가 없는 기타비상무이사가 맡아왔다. 양측 이사회를 오가며 그룹 차원의 전략과 의사결정을 긴밀히 연계하기 위한 장치였다.대표적으로 이장환 재무담당(전무)은 2022~2025년 3월 AK홀딩스 사내이사이자 애경케미칼 기타비상무이사로 재직했다. 이 전무 이전에는 장영신 애경그룹 회장이 애경케미칼 경영에 참여하며 그룹 전반을 총괄했다. 다만 당시는 기타비상무이사 직책이 없고 공식적인 겸직 체제도 아니었던 만큼 현재와 비교하면 성격과 상징성에서 다소 차이를 보인다.따라서 현 체제는 이 전무가 선임되면서 본격화됐다. 겸직 구조를 택한 배경에는 2022년 애경유화·에이케이켐텍·애경화학 등 3사 간 합병으로 화학사업의 위상이 한층 커진 점이 자리한다는 분석이 나온다. 그룹 차원의 전략조율에 대한 필요성이 높아지면서 지주사와 사업회사 간 연결고리를 제도화했다는 해석이다.애경케미칼은 지난해 AK홀딩스 이사회에 진입하지 않은 민 상무보를 기타비상무이사로 선임하며 의사결정의 독립성을 강화했다. 그러나 1년 만에 겸직 인사가 재등장하면서 지주사와의 연계성을 강화하는 쪽으로 선회했다는 해석이 나온다.이사회의 변화에는 결정적으로 ''두 가지'' 요소가 작용한 것으로 분석된다. 우선 애경산업 매각이다. 애경그룹은 지난해 모태산업이자 핵심 자회사인 애경산업 처분을 결정했다. 향후 애경산업이 그룹에서 이탈하면 사업 포트폴리오는 화학과 항공 중심으로 재편된다. 자연스럽게 애경케미칼과 제주항공이 실적과 전략에서 그룹의 중심축으로 부상할 가능성이 크다.또 다른 배경으로는 석유화학 산업 구조조정이 꼽힌다. 최근 롯데케미칼과 HD현대오일뱅크가 공동 출자한 HD현대케미칼을 중심으로 1호 구조조정 사례가 등장하며 업계 재편이 본격화되는 가운데 대형 석유화학사들의 동참이 본격화할 경우 기초유분을 비롯한 석유화학 제품 생산이 크게 감소할 개연성이 크다.애경케미칼은 가소제, 프탈산무수물(PA), 복합소재, 코팅용 수지, 폴리우레탄(PU) 등 범용·중간소재를 생산한다. 이들 제품 중 상당수는 나프타분해시설(NCC)에서 생산되는 에틸렌·프로필렌·벤젠 등 기초유분을 원료로 한다. 이에 따라 NCC 업체들의 감산이나 통합이 이뤄질 경우 기초유분 수급 구조에 변화가 생기고 원재료 가격 변동성이 확대될 가능성도 제기된다.이사회 합류를 앞둔 정 상무가 AK플라자와 AK홀딩스 등에서 최고재무책임자(CFO)로 일했다는 점을 감안할 때 업황 변동성이 커지는 상황에서 이사회 내 재무 기능을 한층 강화하려는 포석으로 풀이된다.애경케미칼 측은 "(정 상무는) 현재 지주회사인 AK홀딩스 전략기획부문장을 맡고 있으며 AK플라자와 애경산업에서 전략본부장, 성장전략팀장을 역임했다"며 "경쟁력 강화와 지속적인 성장에 중요한 역할을 할 것으로 판단해 추천했다"고 설명했다.', NULL, '블로터', 'https://n.news.naver.com/mnews/article/293/0000080173', 'https://imgnews.pstatic.net/image/293/2026/03/03/0000080173_001_20260303160008544.jpg?type=w800', 'NEWS_TRANSPORT', NULL, '2026-03-03 14:16:13', 0, true, '2026-03-09 06:28:04.597982') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1211, '청정원·샘표·해찬들 順...3분기 장류 브랜드 관심도', '대상 청정원이 올해 3분기 장류 브랜드 가운데 가장 많은 소비자 관심도(정보량=포스팅 수)를 차지한 것으로 조사됐다. 샘표와 CJ제일제당의 해찬들이 뒤를 이었다.여론조사기관 데이터앤리서치가 뉴스·커뮤니티·블로그 등 다양한 채널, 사이트들을 대상으로 올 3분기 국내 주요 장류 브랜드 6곳 정보량을 빅데이터 분석한 결과다,키워드의 경우 ''브랜드명'' 또는 ''기업명''으로 설정해 분석했다. 조사 대상은 주요 장류 브랜드 중 국내에서 제품 판매하는 곳을 임의 선정했으며, 정보량 순으로 △대상 청정원 △샘표 △CJ제일제당 해찬들 △사조대림 순창궁 △삼화식품 △신송홀딩스 신송식품 순이다.분석 결과, 대상 청정원이 3분기 1만5966건 포스팅 수로 장류 브랜드 중 관심도 1위를 기록했다. 샘표가 8538건으로 정보량 2위를 차지했다. CJ제일제당 해찬들이 1110건으로 소비자 관심도 3위에 자리매김했다.이밖에 △사조대림 순창궁(680건) △삼화식품(268건) △신송홀딩스 신송식품(225건) 순으로 나타났다.', NULL, '조세일보', 'https://n.news.naver.com/mnews/article/123/0002372951', 'https://ssl.pstatic.net/static.news/image/news/ogtag/navernews_800x420_20221201.jpg', 'NEWS_ETC', NULL, '2025-12-01 10:46:12', 0, true, '2026-03-09 06:28:09.880551') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1207, '코스피 7% 급락에 시스템 마비?…한때 일부 주문 지연·거부', '여의도 KRX 한국거래소 / 사진=연합뉴스국내 증시가 폭락하는 가운데 한국거래소 주식 주문이 지연되거나 거부되는 현상이 발생했습니다.오늘(9일) 금융투자업계에 따르면 이날 낮 12시 30~33분, 오후 1시 39~41분쯤 한국거래소 전산 문제로 일부 주문이 거부되거나 주문 처리가 지연됐습니다. 현재 정상화 조치는 마친 것으로 전해졌습니다.미래에셋증권은 오늘 공지를 통해 "거래소 시스템 불안정으로 주문 지연이 발생할 수 있어 주문 결과를 반드시 확인해달라"고 안내했습니다.거래소 관계자는 "거래 지연 현상 등의 원인은 현재 파악 중"이라며 "현재 거래는 정상적으로 가능한 상황"이라고 말했습니다.#한국거래소 #주식 #증시 #코스피 #코스닥 #거래 #주문', NULL, 'MBN', 'https://n.news.naver.com/mnews/article/057/0001938922', 'https://imgnews.pstatic.net/image/057/2026/03/09/0001938922_001_20260309152406946.jpg?type=w800', 'NEWS_FINANCE', NULL, '2026-03-09 15:24:06', 1, true, '2026-03-09 06:27:57.543047') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1222, '“봄동·꽃게도 팝니다…마트 말고 편의점서 장보세요”', '김경한 GS리테일 축수산팀 MD팀장근거리 장보기族 늘며 신선식품 수요↑신선강화매장 연내 1100곳 확대계획“바나나 한 송이는 많다며 두 개짜리를 찾는 고객들도 있습니다.”지난 5일 서울 강남구 GS타워에서 만난 김경한 GS리테일 축수산팀 MD팀장은 최근 신선식품 소비 변화를 이같이 설명했다. 1~2인 가구 증가에 필요한 만큼만 사는 ‘소용량 장보기’가 확산하면서 편의점에서도 신선식품 수요가 꾸준히 늘고 있다는 것이다. 그는 “예전에는 편의점에서 신선식품을 파는지 모르는 고객이 많았지만, 최근에는 소량으로 간편하게 장을 보려는 수요가 분명히 늘었다”고 말했다.김 팀장은 2024년부터 GS25의 신선식품 강화 전략을 이끌어왔다. 2024~2025년에는 GS25 신선식품강화팀 MD팀장을 맡았고, 올해부터는 GS리테일 축수산팀 MD팀장을 맡고 있다. 그가 이끄는 축수산팀은 지난 1월 ‘4900원 한 끼 양념육’ 3종을 선보였다. 지난달 26일부터는 소용량·소포장 야채 14종 ‘한끼딱’ 시리즈도 판매하고 있다.GS25가 신선식품에 힘을 주는 배경에는 코로나19 이후 뚜렷해진 ‘근거리 장보기’ 수요 확산이 있다. 김 팀장은 “편의점은 주거지 인근에 점포가 촘촘하게 분포해 접근성이 높다”며 “마트와 달리 소용량 포장 상품을 중심으로 필요한 만큼만 구매하려는 수요를 공략하고 있다”고 말했다.실제 GS25 신선식품 카테고리 매출은 2023년 23.7%, 2024년 25.6%, 2025년 24.5% 등 3년 연속 두 자릿수 성장을 기록했다. 취급 품목도 약 2000여종으로 확대됐다. 소포장 농·축·수산물부터 연어, 꽃게 등 제철 상품까지 상품군을 넓혔다.신선식품은 동반 구매율이 높아 편의점 전체 매출 확대에도 도움을 준다. 김 팀장은 “신선식품 자체 매출도 중요하지만, 고객 장바구니를 키운다는 점에서 의미가 크다”며 “신선을 강화하면 다른 상품 매출까지 함께 늘어나는 효과가 있다”고 말했다.이 같은 성과를 뒷받침하는 것은 철저한 품질 관리 시스템이다. GS25는 신선식품 물류 통합 허브센터를 운영하고 있다. 협력사에서 출고된 신선식품은 이곳에서 꼼꼼한 검품을 거친 뒤 전국 물류센터와 점포로 배송된다.GS25는 올해도 신선식품 전략을 강화한다. 장보기 기능에 특화한 신선강화매장(FCS) 확대에 속도를 낸다. 2021년 3개점에서 시작해 올해 1월 기준 791개점까지 늘었다. GS25는 연말까지 이를 1100여개점으로 확대할 계획이다.상품 전략도 세분화한다. 김 팀장은 “중량이 큰 상품은 가격 경쟁력을 높이고, 소용량 상품은 편의성을 강화할 것”이라며 “봄동 같은 제철 신선식품과 연어처럼 빠르게 성장하는 카테고리를 중심으로 상품 경쟁력을 강화할 계획”이라고 강조했다. 박연수 기자', NULL, '헤럴드경제', 'https://n.news.naver.com/mnews/article/016/0002610494', 'https://imgnews.pstatic.net/image/016/2026/03/09/0002610494_001_20260309111510291.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 11:15:10', 0, true, '2026-03-09 06:28:38.700231') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1223, '[유통人터뷰] "진짜 사람 아니었어?"...바이브 코딩이 바꾼 홈쇼핑 현장', 'GS리테일 홈쇼핑 BU소속 정재현 영상제작1팀장 등현장 전문가 ''감각''으로 디테일↑…"1억짜리 작업 10만원에"GS리테일 홈쇼핑BU 소속의 정재현 영상제작1팀장(가운데), 김상범 영상제작1팀 매니저(왼쪽), 임은택 영상아트팀 매니저(오른쪽)이 포즈를 취하고 있다.(GS리테일 제공)(서울=뉴스1) 이형진 기자"1억 원 가까이 들던 작업을 구독료 10만 원으로, 제작 기간도 세 달에서 일주일로 줄였습니다"지난 6일 GS강서타워에서 GS리테일(007070) 홈쇼핑BU 소속의 정재현 영상제작1팀장, 김상범 영상제작1팀 매니저, 임은택 영상아트팀 매니저를 만났다.앞서 GS샵은 지난달 23일 생성형 AI 모델 ''재이''를 활용한 패션 특집 ''블루밍 스프링'' 기획 방송을 진행했다. GS샵은 시청자들이 가상 모델임을 인지하지 못할 정도로 정교한 움직임과 시선 처리를 구현했다.(GS리테일 제공)"코딩 몰라도 OK"…현장 전문가의 ''감각''으로 디테일한 프롬프트GS샵은 개인별 맞춤형 형태로 담당자들이 직접 AI 기반 업무 앱을 기획·제작해 실무에 적용하는 환경을 구축하고 있다. 비개발자도 생성형 AI 도구를 활용한 바이브 코딩으로 직접 AI 앱을 개발하고, 담당 업무에 활용하는 것이다.이날 현장에서 AI 모델 재이의 탄생 과정을 볼 수 있었다. 재이 역시 GS샵이 바이브 코딩으로 개발한 자체 AI 앱을 활용했다.카메라 담당의 김 매니저는 현업에서 익숙한 방송 현장 환경을 AI 모델 제작에서도 드러날 수 있도록 프롬프트를 입력했다. 조명의 강도, 카메라 구도와 화각, 모델과의 거리, 포즈와 시선 등을 입력해 이미지를 뽑아냈다.정 팀장은 "AI R&D 조직을 꾸리면서 카메라 담당을 꼭 집어넣었다. 일반인보다 카메라를 전문으로 한 담당자이기 때문에 더 디테일한 프롬프트를 입력 할 수 있었다"며 "AI를 한다는 건 IT 전문가의 영역이라 생각하지만, 자기 분야의 전문성이 있을수록 현업에 적용 시 강력한 무기가 된다"고 했다.GS샵의 AI모델이 동작을 시범보이고 있다.자체 앱 개발 ''한 시간''밖에…"소비자들이 더 정확하게 제품 이해하도록"GS샵은 지난해 7월 실제 스튜디오 화면에 AI 생성 이미지를 더하는 AI 스튜디오를 본격 도입했고, 여기서 더 고도화 해 지난해 10월 본격적인 AI R&D 팀을 구성했다.일종의 샌드박스 형태의 플랫폼을 구성하고, 그 아래 현업에서 필요한 앱을 개발해 쓸 수 있도록 만들었다. ''재이'' 역시 이 앱을 바탕으로 탄생했다. 이외에도 다양한 앱을 구성하고 있는데, 충분한 DB가 쌓이면서 특정 앱은 초기 버전 개발까지 한 시간밖에 걸리지 않을 정도로 개발과 제작 속도가 빨라졌다.정 팀장은 "제작 기간은 짧아졌지만, 할 수 없던 일들이 가능해지면서 의뢰가 폭증했다"고 웃음 섞인 고충을 토로하기도 했다. 방송 제작 자체에 시간이 줄어들면서 오히려 제작 건수가 늘어난 탓이다. 그만큼 효율성이 높아졌다는 의미다. 또 아직 한글 표기 오류, 단추 갯수, 작은 알약 크기 등 AI가 완벽히 구현하지 못해 "그런 것은 포토샵으로 수정하면서 완성도를 높이고 있다"고 전했다.소비자들은 AI로 만든 방송 화면과 AI 모델 등에 놀라워하면서도 실제 제품보다 좋아 보이게 만드는 것 아니냐는 불평도 나오는 상황이다.임 매니저는 "AI는 결국 과정이고, 이 제품을 소비자들이 어떻게 더 정확한 정보를 갖고 이해할 수 있게, 몰입형 콘텐츠를 제공하는 것이 저희의 목표"라고 설명했다. 김 매니저도 "패션 제품을 예로 들면 핏의 디테일에 차이가 있을 수 있다. 고객들에게 최대한 같은 경험을 할 수 있도록 만들고 있다"고 전했다.GS리테일 홈쇼핑BU 소속의 정재현 영상제작1팀장, 김상범 영상제작1팀 매니저, 임은택 영상아트팀 매니저가 회의를 하고 있다.(GS리테일 제공)', NULL, '뉴스1', 'https://n.news.naver.com/mnews/article/421/0008813445', 'https://imgnews.pstatic.net/image/421/2026/03/09/0008813445_001_20260309070020949.jpg?type=w800', 'NEWS_ETC', NULL, '2026-03-09 07:00:00', 0, true, '2026-03-09 06:28:38.700231') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1224, '[특징주] "美, 북한과 대화에 열려 있다"…남북경협주 일제히 강세(종합)', '2018년 북미정상회담에서 공동합의문에 서명하는 트럼프 미 대통령과 김정은 국무위원장[조선중앙통신=연합뉴스 자료사진. 국내에서만 사용가능. 재배포 금지. For Use Only in the Republic of Korea. No Redistribution](서울=연합뉴스) 황철환 기자 = 미국이 북한과 전제 조건 없는 대화에 열린 입장을 유지 중이란 소식에 남북경협주로 분류되는 종목 상당수가 27일 강세로 거래를 마쳤다.이날 코스닥 시장에서 코데즈컴바인은 전장보다 8.02% 급등한 5천390원에 장을 종료했다.좋은사람들도 3.73% 올랐고, 아난티(4.88%), 제이에스티나(0.47%), 일신석재(2.36%), 신원(1.15%) 등 여타 경협주도 주가가 상승했다.정부 북핵 수석대표인 정연두 외교부 외교전략정보본부장이 한국시간으로 이날 새벽 "미국이 북한과 전제 조건 없는 대화에 열린 입장에 변함이 없음을 확인했다"고 밝힌 것이 투자심리를 자극한 것으로 보인다.정 본부장은 워싱턴DC의 주미대사관에서 열린 한국 특파원단과의 간담회에서 이번 미국 방문 기간 "앨리슨 후커 국무부 정무차관과 토마스 디나노 군비통제·국제안보 담당 차관, 마이클 디솜브레 동아태 차관보 등 미 국무부 주요 인사들과 폭넓은 협의를 가졌다"며 이같이 말했다.다만, ''북한과의 조건 없는 대화에 열려 있다''는 미국 측 입장과 관련, 정부 고위 당국자는 북미 간의 접촉이 진행 중인지에 대해 "(북미 간의) 실무접촉 같은 새로운 뉴스는 없다"고 밝혔다.전날 공개된 북한의 제9차 노동당 대회 총화 보고에서 김정은 북한 국무위원장은 북한의 핵보유국 지위를 인정하고 대북 적대시 정책을 철회하면 미국과 좋게 지낼 수 있다는 취지의 언급을 했다.이와 관련한 연합뉴스의 질의에 미 백악관 당국자는 도널드 트럼프 대통령이 집권 1기 때 3차례 만났던 김정은 위원장과 "어떤 전제조건 없는 대화를 하는 데 여전히 열려 있다"고 이날 밝혔다.hwangch@yna.co.kr', NULL, '연합뉴스', 'https://n.news.naver.com/mnews/article/001/0015929545', 'https://imgnews.pstatic.net/image/001/2026/02/27/PYH2018092605420001300_P4_20260227155724210.jpg?type=w800', 'NEWS_ETC', NULL, '2026-02-27 15:56:54', 0, true, '2026-03-09 06:28:46.432405') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1212, '미중 신경전 한창인데…''전인미답'' 3700선 간다', '[앵커]미중 무역갈등 우려에도 아랑곳하지 않고 코스피가 파죽지세로 치솟으며 사상 처음으로 3천 650선마저 돌파했습니다.미·중 갈등 영향이 제한적일 것이라는 전망과 함께 오늘(15일) 나온 정부의 부동산 대책으로 시중 자금이 자본시장 쪽으로 유입될 것이라는 기대감이 복합적으로 작용했습니다.이제 코스피는 또 한 번 전인미답인 3천 700선을 향해 달리고 있습니다.첫 소식 이한나 기자입니다.[기자]샘표, 사조대림, 신송홀딩스 등 이른바 ''식용유 관련주''들이 줄줄이 상승했습니다.도널드 트럼프 미국 대통령이 중국의 미국에 대한 대두 수입 중단을 ''경제적 적대 행위''로 규정하면서 식용유 교역 중단 가능성을 시사한 데 따른 겁니다.[김대종 / 세종대 경영학부 교수 : (대두 원료인) 식용유는 가격이 올라도 수요가 줄어들지 않는 필수재입니다. 트럼프 대통령의 언급 때문에 이렇게 식용유 관련 주가가 올랐습니다. 반사 이익을 우리 식품 기업들이 봤습니다.]코스피는 2.68% 오른 3657.28 상승 마감하면서 역대 최고치를 찍었습니다.외국인과 기관이 약 1조 원어치를 사들이며 상승을 주도했습니다.이에 따라 코스피 시가총액은 3012조 원 가까이로 불어나 사상 처음으로 3000조 원을 넘어섰습니다.코스닥 역시 1.98% 올라 864.72에 상승 마감했습니다.무역 긴장도가 높아지면서 증시 변동성이 확대됐지만, 시장의 기대감은 식지 않고 있습니다.글로벌 투자은행 모건스탠리는 내년에 코스피가 4200선을 넘을 수도 있을 것으로 내다봤습니다.[신승진 / 삼성증권 연구원 : 우리나라는 IT 비중이 높거든요. 삼성전자, SK하이닉스 두 회사의 시가총액이 차지하는 비중이 높기 때문에 반도체 중심의 이익 성장이 나온다고 하면 지수 자체는 상방을 열어놓고 보는 게 맞다라고 생각합니다.]다만 미중 갈등이 장기화될 경우 증시 조정의 폭도 다시 커질 수 있는 만큼 투자에 신중할 필요가 있다는 지적도 나옵니다.SBS Biz 이한나입니다.당신의 제보가 뉴스로 만들어집니다.SBS Biz는 여러분의 제보를 기다리고 있습니다.홈페이지 = https://url.kr/9pghjn', NULL, 'SBS Biz', 'https://n.news.naver.com/mnews/article/374/0000468625', 'https://imgnews.pstatic.net/image/374/2025/10/15/0000468625_001_20251015180806676.jpg?type=w800', 'NEWS_ETC', NULL, '2025-10-15 18:08:06', 0, true, '2026-03-09 06:28:09.880551') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1213, '[서울데이터랩]금일 코스피 거래량 1위 동양 거래대금 2,517억 돌파', '코스피 거래량 상위 종목들이 엇갈린 흐름을 보이고 있다.15일 한국거래소에 따르면, 동양(001520)가 2억 1,830만 9491주 거래되며 코스피 종목 중 실시간 거래량 1위를 차지했다. 현재 주가는 1,061원이며, 거래대금은 251,744백만원으로 시가총액의 약 9.94%에 해당하는 높은 수준이다. 등락률은 5.78%로 상승세를 보이며, PER -3.04, ROE -9.94로 재무 지표는 다소 부진하다. 동양에 대한 투자자들의 관심이 급증한 가운데, 시장에서의 매수세와 매도세의 공방이 치열히 이루어지고 있다.흥아해운(003280)은 21,197,953주 거래되며 거래량 2위를 기록하고 있다. 주가는 1,768원이며, 거래대금은 37,705백만원으로 시가총액 대비 약 0.89%를 기록하고 있다. 등락률은 -5.10%로 하락세를 보이고 있다.삼성전자(005930)는 18,680,357주 거래되며 거래량 3위를 차지하고 있다. 현재 주가는 95,300원으로 등락률은 4.04% 상승세를 보이며, 거래대금은 1,753,977백만원으로 시가총액의 약 3.11% 수준이다.두산에너빌리티(034020)는 82,900원으로 9.37% 상승했으며, 거래량은 11,581,260주이다. 유니온머티리얼(047400)은 2,237원으로 등락률이 0.31%로 나타났고, 거래량은 11,503,252주이다. 성안머티리얼스(011300)는 471원으로 2.28% 하락하며, 거래량은 8,498,328주이다. 서울식품(004410)은 1.91% 상승한 160원에 거래되고 있으며, 거래량은 5,695,070주이다. 영흥(012160)은 11.54% 상승한 609원으로, 거래량은 5,673,745주를 기록하고 있다. 신송홀딩스(006880)는 5.01% 상승한 7,330원에 거래되며, 거래량은 4,868,805주이다. 우진(105840)은 5.13% 상승한 16,400원으로 거래되며, 거래량은 4,867,986주이다.한편 거래량 상위 20위권 종목들은 한국전력(015760) ▲4.11%, 삼성중공업(010140) ▲1.42%, 이건산업(008250) ▲9.13%, 대원전선(006340) ▲4.09%, 대한해운(005880) ▼0.59%, 한미반도체(042700) ▲10.33%, 삼성전자우(005935) ▲2.21%, HJ중공업(097230) ▲0.84%, 사조동아원(008040) ▲1.28%, LG디스플레이(034220) ▲2.85% 등의 성적을 기록했다.특히, 영흥과 한미반도체가 각각 11.54%, 10.33%의 상승률을 기록하며 주목을 받고 있다. 영흥은 거래대금이 시가총액의 약 0.57%로 나타났고, 한미반도체는 거래대금이 시가총액의 약 32.43%에 달하는 높은 집중도를 보이고 있다. 반면, 흥아해운과 성안머티리얼스는 각각 -5.10%, -2.28% 하락하며 부진한 모습을 보이고 있다.전반적으로 코스피 시장은 상승세와 하락세가 혼재된 가운데, 주요 종목들이 각각의 이슈에 따라 다양한 흐름을 보이고 있다. 이러한 상황 속에서 투자자들은 각 종목의 재무 지표와 시장 동향을 주의 깊게 살펴보며 신중한 투자 결정을 할 필요가 있다.[서울신문과 MetaVX의 생성형 AI가 함께 작성한 기사입니다]', NULL, '서울신문', 'https://n.news.naver.com/mnews/article/081/0003582402', 'https://imgnews.pstatic.net/image/081/2025/10/15/0003582402_001_20251015170421112.png?type=w800', 'NEWS_ETC', NULL, '2025-10-15 17:04:21', 0, true, '2026-03-09 06:28:09.880551') ON CONFLICT (id) DO NOTHING;
INSERT INTO news_article (id, title, content, content_summary, source, source_url, thumbnail_url, category_code, keywords, published_at, view_count, is_active, created_at) VALUES (1214, '춘천폴리텍-동춘천일반산업단지 입주자연합회, 지역산업 맞춤형 인재 양성 MOU 체결', '▲ 한국폴리텍Ⅲ대학(학장 지경배) 춘천캠퍼스는 16일 동춘천일반산업단지 입주자 연합회(회장 장덕범)와 산업 맞춤형 인재 양성과 직업교육 협력 강화를 위한 업무협약을 체결했다.한국폴리텍Ⅲ대학(학장 지경배) 춘천캠퍼스와 동춘천일반산업단지 입주자 연합회(회장 장덕범)가 산업 맞춤형 인재 양성과 직업교육 협력 강화를 위해 손잡았다.양 기관·단체는 16일 춘천캠퍼스에서 이를 위한 업무협약을 체결, 재직자 직업교육 확대는 물론, 재학생 맞춤형 교육과 현장 실습, 취업 연계까지 단계적으로 협력을 이어가며 지역 산업 경쟁력 강화에 기여하겠다고 밝혔다.동춘천일반산업단지 입주자 연합회는 춘천시 동산면 봉명리 일원에 조성된 동춘천 일반산업단지 내 입주 기업들로 구성된 단체로, 제조업을 중심으로 한 다양한 기업들이 참여해 산업단지 운영 협력과 기업 공동 현안 대응, 지역 산업 활성화에 기여하고 있다. 이번 협약에는 장덕범 회장을 비롯, 박재희 수석부회장(월드케마칼 대표)과 임환희 이사(태경화학 대표)가 참석했다.이번 협약은 대학의 직업교육 역량과 산업단지 현장의 인력 수요를 연계해 실효성 있는 인재 양성 체계를 구축하기 위해 추진됐다. 춘천캠퍼스는 입주기업 수요를 반영한 직무 중심 교육과 재직자 역량 강화 프로그램을 지원하고, 연합회는 산업 현장의 의견과 인력 수요를 공유하며 협력한다.#동춘 #일반산업단지 #맞춤형 #인재 #양성', NULL, '강원도민일보', 'https://n.news.naver.com/mnews/article/654/0000162231', 'https://imgnews.pstatic.net/image/654/2026/01/19/0000162231_001_20260119173707830.jpg?type=w800', 'NEWS_ETC', NULL, '2026-01-19 17:37:07', 0, true, '2026-03-09 06:28:16.483436') ON CONFLICT (id) DO NOTHING;
